    /// <summary>
    /// This class is the primary entry point to the Eagle scripting engine and
    /// the central runtime object for embedding Eagle in a .NET application.
    /// An interpreter holds all per-instance runtime state -- the commands,
    /// procedures, functions, operators, variables, namespaces, plugins,
    /// policies, resolvers, traces, the call stack, the host, and
    /// configuration -- and exposes the methods to create it, evaluate scripts,
    /// files, and expressions, register and remove entities, manage
    /// cancellation, and clean up.  The typical lifecycle is: create an
    /// interpreter with one of the static <c>Create</c> overloads, evaluate
    /// one or more scripts with the evaluation methods, then dispose it when
    /// finished (this class implements <see cref="IDisposable" />).  It
    /// composes a large set of manager interfaces (for example,
    /// <see cref="IInterpreter" />, <see cref="IEngineManager" />,
    /// <see cref="IEntityManager" />, <see cref="IVariableManager" />,
    /// <see cref="IPluginManager" />, and <see cref="ISecurityManager" />),
    /// and it delegates the actual script execution to the static
    /// <see cref="Engine" /> class.  Most embedding applications interact with
    /// Eagle primarily through this class.  See <c>embedding_eagle.md</c> for
    /// embedding patterns and <c>engine_vs_interpreter.md</c> for how this
    /// class relates to <see cref="Engine" />.
    /// </summary>
    [ObjectId("b98042f9-d66a-46db-81e9-a2f44c1f03fd")]
    public sealed class Interpreter :
#if ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
        ScriptMarshalByRefObject,
#endif
        IArgumentManager,
        ICacheManager,
#if CALLBACK_QUEUE
        ICallbackQueueManager,
#endif
        IDisposable, IDebugManager, IEngineManager,
        IEntityManager, IErrorManager,
        IHaveCultureInfo, IHaveOwner,
#if HISTORY
        IHistoryManager,
#endif
        IIdentifier,
#if DEBUGGER
        IInteractiveLoopManager,
#endif
        IInteractiveManager, IInterpreter, IInterpreterManager,
#if WINFORMS
        IKeyEventManager,
#endif
#if NOTIFY || NOTIFY_OBJECT
        INotifyManager,
#endif
        IPackageManager,
        IPluginManager, IPropertyManager, IResolveManager,
        IResourceManager, IRuntimeOptionManager, IScriptManager,
        ISecurityManager,
#if SHELL
        IShellManager,
#endif
        ISnippetManager,
#if WINFORMS
        IStatusManager,
#endif
        ISynchronizeAll,
#if NATIVE && TCL
        ITclEntityManager, ITclManager,
#endif
        ITraceManager,
        ITrustManager,
        IVariableManager
    {
