        /// <summary>
        /// The object used to synchronize access to the static data shared by
        /// all interpreters.
        /// </summary>
        private static readonly object staticSyncRoot = new object();

        /// <summary>
        /// The managed thread identifier currently holding the static data
        /// lock, or zero when that lock is not held.
        /// </summary>
        private static long staticLockThreadId = 0;
        #endregion

