        #region IArgumentManager Members
        /// <summary>
        /// This method checks the specified command arguments against the
        /// supplied collection of options, validating each one without modifying
        /// the options.  It is a convenience wrapper around the universal option
        /// parser.
        /// </summary>
        /// <param name="options">
        /// The collection of options to recognize while scanning the
        /// arguments.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments to be scanned for options.
        /// </param>
        /// <param name="listCount">
        /// The count of the list tied to the option(s), used when an option
        /// must be an index.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to consider.
        /// </param>
        /// <param name="stopIndex">
        /// The index of the last argument to consider.
        /// </param>
        /// <param name="nextIndex">
        /// Upon success, this is set to the index of the first non-option
        /// argument.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the options were processed
        /// successfully; otherwise, an error code.
        /// </returns>
        public ReturnCode CheckOptions(
            OptionDictionary options,
            ArgumentList arguments,
            int listCount /* for MustBeIndex, the count of the list tied to the option(s) */,
            int startIndex,
            int stopIndex,
            ref int nextIndex /* upon success, location of the first non-option argument. */,
            ref Result error
            )
        {
            CheckDisposed();

            int endIndex = Index.Invalid;

            return GetOptions(
                options, arguments, listCount, startIndex, stopIndex,
                OptionBehaviorFlags.CheckOptions, true, false, false,
                ref nextIndex, ref endIndex, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method parses the specified command arguments using the supplied
        /// collection of options, recording each recognized option.
        /// </summary>
        /// <param name="options">
        /// The collection of options to recognize while scanning the
        /// arguments.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments to be scanned for options.
        /// </param>
        /// <param name="listCount">
        /// The count of the list tied to the option(s), used when an option
        /// must be an index.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to consider.
        /// </param>
        /// <param name="stopIndex">
        /// The index of the last argument to consider.
        /// </param>
        /// <param name="strict">
        /// Non-zero to raise an error when an unknown option is encountered;
        /// otherwise, scanning stops at the first unknown option.
        /// </param>
        /// <param name="nextIndex">
        /// Upon success, this is set to the index of the first non-option
        /// argument.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the options were processed
        /// successfully; otherwise, an error code.
        /// </returns>
        public ReturnCode GetOptions(
            OptionDictionary options,
            ArgumentList arguments,
            int listCount /* for MustBeIndex, the count of the list tied to the option(s) */,
            int startIndex,
            int stopIndex,
            bool strict, /* raise an error if any unknown option is encountered (instead of stopping). */
            ref int nextIndex /* upon success, location of the first non-option argument. */,
            ref Result error
            )
        {
            CheckDisposed();

            int endIndex = Index.Invalid;

            return GetOptions(
                options, arguments, listCount, startIndex, stopIndex,
                strict ? OptionBehaviorFlags.Strict : OptionBehaviorFlags.Default,
                true, false, false, ref nextIndex, ref endIndex, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method parses the specified command arguments using the supplied
        /// collection of options, automatically determining the starting argument
        /// index from the kind of the specified identifier (e.g., command or
        /// ensemble sub-command).
        /// </summary>
        /// <param name="identifier">
        /// The command, ensemble, or other identifier whose arguments are
        /// being parsed; it is used to determine how many leading arguments
        /// to skip.
        /// </param>
        /// <param name="options">
        /// The collection of options to recognize while scanning the
        /// arguments.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments to be scanned for options.
        /// </param>
        /// <param name="argumentIndex">
        /// Upon success, this is set to the index of the first non-option
        /// argument.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the options were processed
        /// successfully; otherwise, an error code.
        /// </returns>
        public ReturnCode GetOptions(
            IIdentifier identifier,
            OptionDictionary options,
            ArgumentList arguments,
            ref int argumentIndex,
            ref Result error
            )
        {
            CheckDisposed();

            int startIndex = 0;
            IEnsemble ensemble = identifier as IEnsemble;

            if (ensemble != null)
            {
                EnsembleDictionary subCommands = ensemble.SubCommands;

                if ((subCommands != null) && (subCommands.Count > 0))
                    startIndex = 2; /* NOTE: Yes, has sub-commands. */
                else
                    startIndex = 1; /* NOTE: No, treat as command. */
            }
            else if (identifier is ICommand)
            {
                startIndex = 1; /* NOTE: Treat as command, one name. */
            }

            return GetOptions(
                options, arguments, 0, startIndex, Index.Invalid,
                false, ref argumentIndex, ref error);
        }

