        /// </param>
        /// <param name="strict">
        /// Non-zero to raise an error when an unknown option is
        /// encountered.
        /// </param>
        /// <param name="nextIndex">
        /// Upon success, this is set to the index of the first non-option
        /// argument.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the options were scanned
        /// successfully; otherwise, an error code.
        /// </returns>
        internal ReturnCode ScanOptions(
            OptionDictionary options,
            ArgumentList arguments,
            int listCount,
            int startIndex,
            int stopIndex,
            bool strict,
            ref int nextIndex,
            ref Result error
            )
        {
            int endIndex = Index.Invalid;

            return ScanOptions(
                options, arguments, listCount, startIndex,
                stopIndex, strict ?
                    OptionBehaviorFlags.Strict :
                    OptionBehaviorFlags.Default,
                ref nextIndex, ref endIndex, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method scans the specified command arguments for options, using
        /// the supplied option-handling behavior flags, without modifying the
        /// collection of options.
        /// </summary>
        /// <param name="options">
        /// The collection of options to recognize while scanning the
        /// arguments.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments to be scanned for options.
        /// </param>
        /// <param name="listCount">
        /// The count of the list tied to the option(s), used when an option
        /// must be an index.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to consider.
        /// </param>
        /// <param name="stopIndex">
        /// The index of the last argument to consider.
        /// </param>
        /// <param name="behaviorFlags">
        /// The flags that control how options and unknown arguments are
        /// handled.
        /// </param>
        /// <param name="nextIndex">
        /// Upon success, this is set to the index of the first non-option
        /// argument.
        /// </param>
        /// <param name="endIndex">
        /// Upon success, this is set to the index of the end-of-options
        /// marker, if one was found; otherwise, it is left unchanged.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the options were scanned
        /// successfully; otherwise, an error code.
        /// </returns>
        private ReturnCode ScanOptions(
            OptionDictionary options,
            ArgumentList arguments,
            int listCount,
            int startIndex,
            int stopIndex,
            OptionBehaviorFlags behaviorFlags,
            ref int nextIndex,
            ref int endIndex,
            ref Result error
            )
        {
            return GetOptions(
                options, arguments, listCount, startIndex,
                stopIndex, behaviorFlags, true, true, true,
                ref nextIndex, ref endIndex, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This is the "Universal Option Parser".
        //
        /// <summary>
        /// This method is the universal option parser for the interpreter.  It
        /// scans the specified command arguments against the supplied collection
        /// of options, optionally interpreting and recording option values, and
        /// is the core implementation used by the other option-handling methods.
        /// </summary>
        /// <param name="options">
        /// The collection of options to recognize while scanning the
        /// arguments.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments to be scanned for options.
        /// </param>
        /// <param name="listCount">
        /// The count of the list tied to the option(s), used when an option
        /// must be an index.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to consider.
        /// </param>
        /// <param name="stopIndex">
        /// The index of the last argument to consider.
        /// </param>
        /// <param name="behaviorFlags">
        /// The flags that control whether unknown options cause scanning to
        /// stop, raise an error, or be ignored.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to match option names without regard to case.
        /// </param>
        /// <param name="noValue">
        /// Non-zero to avoid interpreting argument strings as typed values
        /// of any kind.
        /// </param>
        /// <param name="noSet">
        /// Non-zero to operate in scan mode, leaving the collection of
        /// options unchanged.
        /// </param>
        /// <param name="nextIndex">
        /// Upon success, this is set to the index of the first non-option
        /// argument.
        /// </param>
        /// <param name="endIndex">
        /// Upon success, this is set to the index of the end-of-options
        /// marker, if one was found; otherwise, it is left unchanged.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the arguments were parsed
        /// successfully, <see cref="ReturnCode.Return" /> when a list-of-options
        /// marker was processed, or <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode GetOptions(
            OptionDictionary options,
            ArgumentList arguments,
            int listCount /* for MustBeIndex, the count of the list tied to the option(s) */,
            int startIndex,
            int stopIndex,
            OptionBehaviorFlags behaviorFlags, /* do we want to stop, error, or ignore unknown options? */
            bool noCase, /* case-insensitive option names? */
            bool noValue, /* do not try to interpret strings as values of any kind. */
            bool noSet, /* scan mode, do not set any values (no changes to options dictionary). */
            ref int nextIndex, /* upon success, location of the first non-option argument. */
            ref int endIndex, /* upon success, location of EndOfOptions if found, otherwise unchanged. */
            ref Result error
            )
        {
            if (options == null)
            {
                error = "invalid options";
                return ReturnCode.Error;
            }

            if (arguments == null)
            {
                error = "invalid argument list";
                return ReturnCode.Error;
            }

            int argumentCount = arguments.Count;

            if (!ListOps.CheckStartAndStopIndex(
                    0, argumentCount - 1, ref startIndex,
                    ref stopIndex, ref error))
            {
                return ReturnCode.Error;
            }

            AppDomain appDomain = AppDomainOps.GetCurrent();
            CultureInfo cultureInfo = Value.GetDefaultCulture();
            string dateTimeFormat = ObjectOps.GetDefaultDateTimeFormat();
            DateTimeKind dateTimeKind = ObjectOps.GetDefaultDateTimeKind();
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    behaviorFlags |= OptionBehaviorFlags;

                    appDomain = this.appDomain;
                    cultureInfo = InternalCultureInfo;
                    dateTimeFormat = this.dateTimeFormat;
                    dateTimeKind = this.dateTimeKind;
                }
                else if (FlagOps.HasFlags(behaviorFlags,
                        OptionBehaviorFlags.FailOnLocked, true))
                {
                    error = "could not lock interpreter";
                    return ReturnCode.Error;
                }
                else
                {
                    TraceOps.LockTrace(
                        "GetOptions",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockWarning,
                        MaybeWhoHasLock());
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }

            LookupFlags lookupFlags = LookupFlags.OptionDefault;

            if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.ValidateLookups, true))
                lookupFlags |= LookupFlags.Validate;
            else
                lookupFlags &= ~LookupFlags.Validate;

            if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.StrictLookups, true))
                lookupFlags |= LookupFlags.Strict;
            else
                lookupFlags &= ~LookupFlags.Strict;

            for (int argumentIndex = startIndex; argumentIndex <= stopIndex; argumentIndex++)
            {
                bool safe = InternalIsSafe(); /* REFRESH */

                Argument currentArgument = arguments[argumentIndex];

                Argument nextArgument = ((argumentIndex + 1) <= stopIndex) ?
                    arguments[argumentIndex + 1] : null;

                string currentString = currentArgument;
                string nextString = nextArgument;
                object nextValue = null;

                if (!FlagOps.HasFlags(behaviorFlags,
                        OptionBehaviorFlags.NoObject, true))
                {
                    IObject nextObject = null;

                    if ((GetObject(
                            nextString, LookupFlags.NoVerbose,
                            ref nextObject) == ReturnCode.Ok) &&
                        (nextObject != null))
                    {
                        nextValue = nextObject.Value;
                    }
                }

                //
                // NOTE: If this is the last argument, make sure it can be
                //       treated as a "possible option".  If not, stop now.
                //
                if ((argumentIndex == stopIndex) &&
                    FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.LastIsNonOption, true))
                {
                    nextIndex = argumentIndex;
                    break;
                }

                IOption option = null;

                if (Option.IsEndOfOptions(currentString))
                {
                    if (options.Has(Option.EndOfOptions, ref option))
                    {
                        if (option == null)
                        {
                            error = String.Format(
                                "{0} option is invalid",
                                FormatOps.WrapOrNull(currentString));

                            return ReturnCode.Error;
                        }
                        else if (option.IsIgnored(options))
                        {
                            if (option.MustHaveValue(options))
                            {
                                if (nextString != null)
                                {
                                    argumentIndex++; // skip option value...
                                }
                                else
                                {
                                    error = String.Format(
                                        "{0} option must be followed by {1}",
                                        FormatOps.WrapOrNull(currentString),
                                        option.FlagsToString());

                                    return ReturnCode.Error;
                                }
                            }
                        }
                        else if (option.CanBePresent(options, ref error))
                        {
                            //
                            // BUGFIX: Unless forbidden, actually mark as present.
                            //         Why not?
                            //
                            if (!noSet)
                                option.SetPresent(options, true, argumentIndex, null);

                            if ((argumentIndex + 1) < argumentCount)
                                nextIndex = argumentIndex + 1;
                            else
                                nextIndex = Index.Invalid;

                            endIndex = argumentIndex;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.ErrorOnEndOfOptions, true))
                    {
                        //
                        // NOTE: This is rarely used because if they do not
                        //       explicitly allow the end-of-options marker
                        //       they normally also want it to be considered
                        //       the first "non-option" argument.
                        //
                        error = "unexpected end-of-options marker";
                        return ReturnCode.Error;
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.StopOnEndOfOptions, true))
                    {
                        //
                        // NOTE: This end-of-options marker is not a valid
                        //       option and we want to stop now because we
                        //       want to assume it is the first non-option
                        //       argument.  This is the default behavior.
                        //
                        nextIndex = argumentIndex;
                        return ReturnCode.Ok;
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.IgnoreOnEndOfOptions, true))
                    {
                        //
                        // NOTE: This end-of-options marker is not a valid
                        //       option and we want to simply ignore it.
                        //       We may also want to skip the next argument.
                        //       This behavior should almost never be used
                        //       unless the caller is 100% sure what it does.
                        //
                        if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.SkipOnEndOfOptions, true))
                            argumentIndex++;
                    }
                }
                else if (Option.IsListOfOptions(currentString))
                {
                    if (options.Has(Option.ListOfOptions, ref option))
                    {
                        if (option == null)
                        {
                            error = String.Format(
                                "{0} option is invalid",
                                FormatOps.WrapOrNull(currentString));

                            return ReturnCode.Error;
                        }
                        else if (option.IsIgnored(options))
                        {
                            if (option.MustHaveValue(options))
                            {
                                if (nextString != null)
                                {
                                    argumentIndex++; // skip option value...
                                }
                                else
                                {
                                    error = String.Format(
                                        "{0} option must be followed by {1}",
                                        FormatOps.WrapOrNull(currentString),
                                        option.FlagsToString());

                                    return ReturnCode.Error;
                                }
                            }
                        }
                        else if (option.CanBePresent(options, ref error))
                        {
                            //
                            // BUGFIX: Unless forbidden, actually mark as present.
                            //         Why not?
                            //
                            if (!noSet)
                                option.SetPresent(options, true, argumentIndex, null);

                            //
                            // NOTE: The error message is the list of all
                            //       available options.
                            //
                            error = OptionDictionary.ListOptions(options, !safe);
                            return ReturnCode.Return; /* SPECIAL */
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.ErrorOnListOfOptions, true))
                    {
                        //
                        // NOTE: This is rarely used because if they do not
                        //       explicitly allow the list-of-options marker
                        //       they normally also want it to be considered
                        //       the first "non-option" argument.
                        //
                        error = "unexpected list-of-options marker";
                        return ReturnCode.Error;
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.StopOnListOfOptions, true))
                    {
                        //
                        // NOTE: This list-of-options marker is not a valid
                        //       option and we want to stop now because we
                        //       want to assume it is the first non-option
                        //       argument.  This is the default behavior.
                        //
                        nextIndex = argumentIndex;
                        return ReturnCode.Ok;
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.IgnoreOnListOfOptions, true))
                    {
                        //
                        // NOTE: This list-of-options marker is not a valid
                        //       option and we want to simply ignore it.
                        //       We may also want to skip the next argument.
                        //       This behavior should almost never be used
                        //       unless the caller is 100% sure what it does.
                        //
                        if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.SkipOnListOfOptions, true))
                            argumentIndex++;
                    }
                }
                else if (Option.LooksLikeOption(currentString))
                {
                    bool ambiguous = false;
                    Result localError = null;

                    if (options.TryResolve(
                            currentString, true, noCase, !safe, ref ambiguous,
                            ref option, ref localError) == ReturnCode.Ok)
                    {
                        if (option != null)
                        {
                            string name = option.Name;
                            OptionFlags flags = option.Flags;

                            if (option.IsIgnored(options))
                            {
                                if (option.MustHaveValue(options))
                                {
                                    if (nextString != null)
                                    {
                                        argumentIndex++; // skip option value...
                                    }
                                    else
                                    {
                                        error = String.Format(
                                            "{0} option must be followed by {1}",
                                            FormatOps.WrapOrNull(currentString),
                                            option.FlagsToString());

                                        return ReturnCode.Error;
                                    }
                                }
                            }
                            else if (!option.CanBePresent(options, ref error))
                            {
                                return ReturnCode.Error;
                            }
                            else if (FlagOps.HasFlags(flags, OptionFlags.EndOfOptions, true))
                            {
                                //
                                // BUGFIX: Unless forbidden, actually mark as present.
                                //         Why not?
                                //
                                if (!noSet)
                                    option.SetPresent(options, true, argumentIndex, null);

                                if ((argumentIndex + 1) < argumentCount)
                                    nextIndex = argumentIndex + 1;
                                else
                                    nextIndex = Index.Invalid;

                                endIndex = argumentIndex;
                                return ReturnCode.Ok;
                            }
                            else if (FlagOps.HasFlags(flags, OptionFlags.ListOfOptions, true))
                            {
                                //
                                // BUGFIX: Unless forbidden, actually mark as present.
                                //         Why not?
                                //
                                if (!noSet)
                                    option.SetPresent(options, true, argumentIndex, null);

                                error = OptionDictionary.ListOptions(options, !safe);
                                return ReturnCode.Return; /* SPECIAL */
                            }
                            else if (safe && !HasAllowUnsafeOptions() && option.IsUnsafe(options))
                            {
                                error = String.Format(
                                    "permission denied: safe interpreter cannot use option {0}",
                                    FormatOps.WrapOrNull(name));

                                return ReturnCode.Error;
                            }
                            else if (!HasAllowRestricted() && option.IsRestricted(options))
                            {
                                error = String.Format(
                                    "permission denied: {0}interpreter cannot use option {1}",
                                    safe ? "safe " : String.Empty, FormatOps.WrapOrNull(name));

                                return ReturnCode.Error;
                            }
                            else if (option.MustHaveValue(options))
                            {
#if !MONO && NATIVE && WINDOWS
                                bool canZero = HasZeroString();
#endif

                                bool zero = false;

                                try
                                {
                                    if (nextString != null)
                                    {
                                        //
                                        // NOTE: Initially, this value of this option is null.  The block
                                        //       below has the implicit guarantee that either the option
                                        //       value will be set to something non-null OR the return
                                        //       code will be set to something non-Ok.
                                        //
                                        IVariant variant = null;

                                        //
                                        // NOTE: Prevent any pre-existing (opaque object handle) value
                                        //       from being used if necessary, based on the flags for
                                        //       this option.
                                        //
                                        if (FlagOps.HasFlags(flags, OptionFlags.NoObject, true))
                                            nextValue = null;

                                        //
                                        // NOTE: Are we allowed to interpret the string as the type of
                                        //       value required for this option?  Otherwise, we will not
                                        //       attempt any conversion and if we are in non-scan mode
                                        //       the final option value will be set as a string.  We
                                        //       assume that the caller knows this.
                                        //
                                        if (!noValue)
                                        {
                                            //
                                            // NOTE: Does this option require strict value recognition
                                            //       semantics?
                                            //
                                            bool strictOption = option.IsStrict(options);

                                            //
                                            // NOTE: Does this option not care about case?
                                            //
                                            bool noCaseOption = option.IsNoCase(options);

                                            //
                                            // NOTE: Does this option allow integer values?  This
                                            //       only applies if the type is Enum.
                                            //
                                            bool allowIntegerOption = option.IsAllowInteger(options);

                                            //
                                            // NOTE: Ok, now figure out what kind of value this option
                                            //       requires and try to parse it from the option value
                                            //       string.
                                            //
                                            if (FlagOps.HasFlags(flags, OptionFlags.MustBeTypeList, true))
                                            {
                                                if (nextValue is TypeList)
                                                {
                                                    variant = new Variant((TypeList)nextValue);
                                                }
                                                else
                                                {
                                                    TypeList typeList = null;
                                                    ResultList errors = null;

                                                    if (Value.GetTypeList(
                                                            this, nextString, appDomain,
                                                            Value.GetTypeValueFlags(strictOption,
                                                            false, noCase || noCaseOption), cultureInfo,
                                                            ref typeList, ref errors) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(typeList);
                                                    }
                                                    else
                                                    {
                                                        error = errors;
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeEnumList, true))
                                            {
                                                if (nextValue is EnumList)
                                                {
                                                    variant = new Variant((EnumList)nextValue);
                                                }
                                                else
                                                {
                                                    Type valueType = option.Type;

                                                    if (valueType != null)
                                                    {
                                                        if (valueType.IsEnum)
                                                        {
                                                            object oldValue = null;

                                                            if (EnumOps.IsFlags(valueType))
                                                                oldValue = option.InnerValue;

                                                            EnumList enumList = null;
                                                            ResultList errors = null;

                                                            if (Value.GetEnumList(
                                                                    this, nextString, valueType,
                                                                    (oldValue != null) ?
                                                                        oldValue.ToString() : null,
                                                                    Value.GetTypeValueFlags(
                                                                        allowIntegerOption, strictOption,
                                                                        false, noCase || noCaseOption),
                                                                    cultureInfo, ref enumList,
                                                                    ref errors) == ReturnCode.Ok)
                                                            {
                                                                variant = new Variant(enumList);
                                                            }
                                                            else
                                                            {
                                                                error = errors;
                                                                return ReturnCode.Error;
                                                            }
                                                        }
                                                        else
                                                        {
                                                            error = String.Format(
                                                                "option {0} value type is not an enum",
                                                                FormatOps.WrapOrNull(name));

                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        error = String.Format(
                                                            "option {0} has an invalid value type",
                                                            FormatOps.WrapOrNull(name));

                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeReturnCodeList, true))
                                            {
                                                if (nextValue is ReturnCodeList)
                                                {
                                                    variant = new Variant((ReturnCodeList)nextValue);
                                                }
                                                else
                                                {
                                                    ReturnCodeList returnCodeList = null;

                                                    if (Value.GetReturnCodeList(
                                                            nextString, cultureInfo, ref returnCodeList,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(returnCodeList);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeAbsoluteUri, true))
                                            {
                                                Uri uri = null;

                                                if (nextValue is Uri)
                                                {
                                                    uri = (Uri)nextValue;

                                                    if (uri.IsAbsoluteUri)
                                                    {
                                                        variant = new Variant((Uri)nextValue);
                                                    }
                                                    else
                                                    {
                                                        error = String.Format(
                                                            "object {0} is not absolute uri {1}",
                                                            FormatOps.WrapOrNull(nextString),
                                                            FormatOps.WrapOrNull(nextValue));

                                                        return ReturnCode.Error;
                                                    }
                                                }
                                                else
                                                {
                                                    if (Value.GetUri(
                                                            nextString, UriKind.Absolute, cultureInfo,
                                                            ref uri, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(uri);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeVersion, true))
                                            {
                                                if (nextValue is Version)
                                                {
                                                    variant = new Variant((Version)nextValue);
                                                }
                                                else
                                                {
                                                    Version version = null;

                                                    if (Value.GetVersion(
                                                            nextString, cultureInfo, ref version,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(version);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeIdentifier, true))
                                            {
                                                if (nextValue is IIdentifier)
                                                {
                                                    variant = new Variant((IIdentifier)nextValue);
                                                }
                                                else
                                                {
                                                    StringList list = null;

                                                    //
                                                    // TODO: *PERF* We cannot have this call to SplitList perform any
                                                    //       caching because we do not know exactly what the resulting
                                                    //       list will be used for.
                                                    //
                                                    if (ListOps.GetOrCopyOrSplitList(
                                                            this, nextArgument, false, ref list, ref error) == ReturnCode.Ok)
                                                    {
                                                        if (list.Count == 2)
                                                        {
                                                            object enumValue = EnumOps.TryParse(
                                                                typeof(IdentifierKind), list[0], allowIntegerOption,
                                                                noCase || noCaseOption, ref error);

                                                            if (enumValue is IdentifierKind)
                                                            {
                                                                IIdentifier identifier = null;

                                                                if (GetIdentifier(
                                                                        (IdentifierKind)enumValue, list[1],
                                                                        arguments, lookupFlags, ref identifier,
                                                                        ref error) == ReturnCode.Ok)
                                                                {
                                                                    variant = new Variant(identifier);
                                                                }
                                                            }
                                                            else
                                                            {
                                                                return ReturnCode.Error;
                                                            }
                                                        }
                                                        else
                                                        {
                                                            error = "identifier must be list with two elements: <kind> <name>";
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeAlias, true))
                                            {
                                                if (nextValue is IAlias)
                                                {
                                                    variant = new Variant((IAlias)nextValue);
                                                }
                                                else
                                                {
                                                    IAlias alias = null;

                                                    if (GetAlias(
                                                            nextString, lookupFlags, ref alias,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(alias);
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeOption, true))
                                            {
                                                if (nextValue is IOption)
                                                {
                                                    variant = new Variant((IOption)nextValue);
                                                }
                                                else
                                                {
                                                    IOption optionValue = Option.FromString(
                                                        this, nextString, appDomain, allowIntegerOption,
                                                        strictOption, false, noCase || noCaseOption,
                                                        cultureInfo, ref error);

                                                    if (optionValue != null)
                                                        variant = new Variant(optionValue);
                                                    else
                                                        return ReturnCode.Error;
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeAbsoluteNamespace, true))
                                            {
                                                if (nextValue is INamespace)
                                                {
                                                    variant = new Variant((INamespace)nextValue);
                                                }
                                                else
                                                {
                                                    if (InternalAreNamespacesEnabled())
                                                    {
                                                        INamespace @namespace = NamespaceOps.Lookup(
                                                            this, nextString, true, false, ref error);

                                                        if (@namespace != null)
                                                            variant = new Variant(@namespace);
                                                        else
                                                            return ReturnCode.Error;
                                                    }
                                                    else
                                                    {
                                                        error = "namespaces not available";
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeRelativeNamespace, true))
                                            {
                                                if (nextValue is INamespace)
                                                {
                                                    variant = new Variant((INamespace)nextValue);
                                                }
                                                else
                                                {
                                                    if (InternalAreNamespacesEnabled())
                                                    {
                                                        INamespace @namespace = NamespaceOps.Lookup(
                                                            this, nextString, false, false, ref error);

                                                        if (@namespace != null)
                                                            variant = new Variant(@namespace);
                                                        else
                                                            return ReturnCode.Error;
                                                    }
                                                    else
                                                    {
                                                        error = "namespaces not available";
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
#if NATIVE && TCL
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeTclInterpreter, true))
                                            {
                                                if (nextValue is string)
                                                {
                                                    variant = new Variant((string)nextValue); /* interpName (?) */
                                                }
                                                else
                                                {
                                                    IntPtr interp = IntPtr.Zero;

#if TCL_THREADS
                                                    if (GetTclInterpreterOrThread(
                                                            nextString, lookupFlags, ref interp,
                                                            ref error) == ReturnCode.Ok)
#else
                                                    if (GetTclInterpreter(
                                                            nextString, lookupFlags, ref interp,
                                                            ref error) == ReturnCode.Ok)
#endif
                                                    {
                                                        variant = new Variant(nextString); /* interpName */
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
#endif
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeType, true))
                                            {
                                                if (nextValue is Type)
                                                {
                                                    variant = new Variant((Type)nextValue);
                                                }
                                                else
                                                {
                                                    Type type = null;
                                                    ResultList errors = null;

                                                    if (Value.GetAnyType(
                                                            this, nextString, null, appDomain,
                                                            Value.GetTypeValueFlags(
                                                                strictOption, false, noCase ||
                                                                noCaseOption), cultureInfo,
                                                            ref type, ref errors) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(type);
                                                    }
                                                    else
                                                    {
                                                        error = errors;
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeInterpreter, true))
                                            {
                                                if (nextValue is Interpreter)
                                                {
                                                    variant = new Variant((Interpreter)nextValue);
                                                }
                                                else
                                                {
                                                    Interpreter interpreter = null;

                                                    if (Value.GetInterpreter(
                                                            this, nextString, InterpreterType.Default,
                                                            ref interpreter, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(interpreter);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeObject, true))
                                            {
                                                if (nextValue is IObject)
                                                {
                                                    variant = new Variant((IObject)nextValue);
                                                }
                                                else
                                                {
                                                    IObject @object = null;

                                                    if (GetObject(
                                                            nextString, lookupFlags, ref @object,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(@object);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeValue, true))
                                            {
                                                if (nextValue != null)
                                                {
                                                    try
                                                    {
                                                        variant = new Variant(nextValue); /* throw */
                                                    }
                                                    catch (Exception e)
                                                    {
                                                        error = e;
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                                else
                                                {
                                                    object value = null;

                                                    if (Value.GetValue(
                                                            nextString, dateTimeFormat, ValueFlags.AnyStrict,
                                                            dateTimeKind, dateTimeStyles, cultureInfo, ref value,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(value);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeList, true))
                                            {
                                                if (nextValue is StringList)
                                                {
                                                    variant = new Variant((StringList)nextValue);
                                                }
                                                else
                                                {
                                                    //
                                                    // TODO: *PERF* We cannot have this call to SplitList perform any
                                                    //       caching because we do not know exactly what the resulting
                                                    //       list will be used for.
                                                    //
                                                    StringList list = null;

                                                    if (ListOps.GetOrCopyOrSplitList(
                                                            this, nextArgument, false, ref list,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(list);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeDictionary, true))
                                            {
                                                if (nextValue is StringDictionary)
                                                {
                                                    variant = new Variant((StringDictionary)nextValue);
                                                }
                                                else
                                                {
                                                    //
                                                    // TODO: *PERF* We cannot have this call to SplitList perform any
                                                    //       caching because we do not know exactly what the resulting
                                                    //       list will be used for.
                                                    //
                                                    StringList list = null;

                                                    if (ListOps.GetOrCopyOrSplitList(
                                                            this, nextArgument, false, ref list,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        if ((list.Count % 2) == 0)
                                                        {
                                                            try
                                                            {
                                                                variant = new Variant(
                                                                    new StringDictionary(list, true, true));
                                                            }
                                                            catch (Exception e)
                                                            {
                                                                error = e;
                                                                return ReturnCode.Error;
                                                            }
                                                        }
                                                        else
                                                        {
                                                            error = "dictionary list must have an even number of elements";
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeDateTime, true))
                                            {
                                                if (nextValue is DateTime)
                                                {
                                                    variant = new Variant((DateTime)nextValue);
                                                }
                                                else
                                                {
                                                    if (FlagOps.HasFlags(flags, OptionFlags.Nullable, true))
                                                    {
                                                        DateTime? dateTime = null;

                                                        if (Value.GetNullableDateTime2(
                                                                nextString, dateTimeFormat, strictOption ?
                                                                    ValueFlags.AnyStrictDateTime :
                                                                    ValueFlags.AnyDateTime, dateTimeKind,
                                                                dateTimeStyles, cultureInfo, ref dateTime,
                                                                ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(dateTime);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        DateTime dateTime = DateTime.MinValue;

                                                        if (Value.GetDateTime2(
                                                                nextString, dateTimeFormat, strictOption ?
                                                                    ValueFlags.AnyStrictDateTime :
                                                                    ValueFlags.AnyDateTime, dateTimeKind,
                                                                dateTimeStyles, cultureInfo, ref dateTime,
                                                                ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(dateTime);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeTimeSpan, true))
                                            {
                                                if (nextValue is TimeSpan)
                                                {
                                                    variant = new Variant((TimeSpan)nextValue);
                                                }
                                                else
                                                {
                                                    if (FlagOps.HasFlags(flags, OptionFlags.Nullable, true))
                                                    {
                                                        TimeSpan? timeSpan = null;

                                                        if (Value.GetNullableTimeSpan2(
                                                                nextString, strictOption ?
                                                                    ValueFlags.AnyStrictTimeSpan :
                                                                    ValueFlags.AnyTimeSpan, cultureInfo,
                                                                ref timeSpan, ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(timeSpan);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        TimeSpan timeSpan = TimeSpan.Zero;

                                                        if (Value.GetTimeSpan2(
                                                                nextString, strictOption ?
                                                                    ValueFlags.AnyStrictTimeSpan :
                                                                    ValueFlags.AnyTimeSpan, cultureInfo,
                                                                ref timeSpan, ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(timeSpan);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeGuid, true))
                                            {
                                                if (nextValue is Guid)
                                                {
                                                    variant = new Variant((Guid)nextValue);
                                                }
                                                else
                                                {
                                                    if (FlagOps.HasFlags(flags, OptionFlags.Nullable, true))
                                                    {
                                                        Guid? guid = null;

                                                        if (Value.GetNullableGuid(
                                                                nextString, cultureInfo, ref guid,
                                                                ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(guid);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        Guid guid = Guid.Empty;

                                                        if (Value.GetGuid(
                                                                nextString, cultureInfo, ref guid,
                                                                ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(guid);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeEnum, true))
                                            {
                                                Type valueType = option.Type;

                                                if (valueType != null)
                                                {
                                                    if (valueType.IsEnum)
                                                    {
                                                        if ((nextValue is Enum) && Object.ReferenceEquals(
                                                                nextValue.GetType(), valueType))
                                                        {
                                                            variant = new Variant((Enum)nextValue);
                                                        }
                                                        else
                                                        {
                                                            object enumValue;

                                                            //
                                                            // NOTE: Reset the local error result here because
                                                            //       we check it below (i.e. it will not be
                                                            //       set by TryParseEnum).
                                                            //
                                                            localError = null;

                                                            if (EnumOps.IsFlags(valueType))
                                                            {
                                                                object oldValue = option.InnerValue;

                                                                enumValue = EnumOps.TryParseFlags(
                                                                    this, valueType, (oldValue != null) ?
                                                                    oldValue.ToString() : null, nextString,
                                                                    cultureInfo, allowIntegerOption,
                                                                    strictOption, noCase || noCaseOption,
                                                                    ref localError);
                                                            }
                                                            else
                                                            {
                                                                enumValue = EnumOps.TryParse(
                                                                    valueType, nextString, allowIntegerOption,
                                                                    noCase || noCaseOption);
                                                            }

                                                            //
                                                            // NOTE: Did we end up with a valid enum value for this type?
                                                            //
                                                            if (enumValue != null)
                                                            {
                                                                //
                                                                // NOTE: It is now guaranteed to be the correct Enum type because
                                                                //       TryParseEnum uses our System.Type object directly and
                                                                //       cannot return non-null unless Enum.Parse succeeds.
                                                                //
                                                                variant = new Variant((Enum)enumValue);
                                                            }
                                                            else
                                                            {
                                                                //
                                                                // NOTE: Retain any locally generated error information (from
                                                                //       TryParseFlagsEnum) because it provides more specific
                                                                //       feedback than we can at this point.
                                                                //
                                                                if (!String.IsNullOrEmpty(localError))
                                                                {
                                                                    error = localError;
                                                                }
                                                                else
                                                                {
                                                                    error = ScriptOps.BadValue(
                                                                        null, String.Format("{0} value",
                                                                        MarshalOps.GetErrorTypeName(valueType)),
                                                                        nextString, Enum.GetNames(valueType), null, null);
                                                                }

                                                                return ReturnCode.Error;
                                                            }
                                                        }
                                                    }
                                                    else
                                                    {
                                                        error = String.Format(
                                                            "option {0} value type is not an enum",
                                                            FormatOps.WrapOrNull(name));

                                                        return ReturnCode.Error;
                                                    }
                                                }
                                                else
                                                {
                                                    error = String.Format(
                                                        "option {0} has an invalid value type",
                                                        FormatOps.WrapOrNull(name));

                                                    return ReturnCode.Error;
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeReturnCode, true))
                                            {
                                                if (nextValue is ReturnCode)
                                                {
                                                    variant = new Variant((ReturnCode)nextValue);
                                                }
                                                else
                                                {
                                                    ReturnCode returnCode = ReturnCode.Ok;

                                                    if (Value.GetReturnCode2(
                                                            nextString, ValueFlags.AnyReturnCode, cultureInfo,
                                                            ref returnCode, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(returnCode);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeMatchMode, true))
                                            {
                                                if (nextValue is MatchMode)
                                                {
                                                    variant = new Variant((MatchMode)nextValue);
                                                }
                                                else
                                                {
                                                    MatchMode matchMode = MatchMode.None;
                                                    object oldValue = option.InnerValue;

                                                    if (Value.GetMatchMode2(
                                                            this, (oldValue != null) ? oldValue.ToString() : null,
                                                            nextString, strictOption ? ValueFlags.AnyStrictMatchMode :
                                                            ValueFlags.AnyMatchMode, cultureInfo, ref matchMode,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(matchMode);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeLevel, true))
                                            {
                                                if (nextValue is ICallFrame)
                                                {
                                                    variant = new Variant((ICallFrame)nextValue);
                                                }
                                                else
                                                {
                                                    ICallFrame otherFrame = null;

                                                    if (GetCallFrame(
                                                            nextString, ref otherFrame,
                                                            ref error) != FrameResult.Invalid)
                                                    {
                                                        variant = new Variant(otherFrame);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeIndex, true))
                                            {
                                                int index;

                                                if (nextValue is int)
                                                {
                                                    index = (int)nextValue;

                                                    if ((index >= 0) && (index < listCount))
                                                    {
                                                        variant = new Variant(index);
                                                    }
                                                    else
                                                    {
                                                        error = String.Format(
                                                            "object {0} index {1} is out-of-bounds {2}",
                                                            FormatOps.WrapOrNull(nextString), index,
                                                            listCount);

                                                        return ReturnCode.Error;
                                                    }
                                                }
                                                else
                                                {
                                                    index = Index.Invalid;

                                                    if (Value.GetIndex(
                                                            nextString, listCount, ValueFlags.AnyIndex,
                                                            cultureInfo, ref index, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(index);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeDouble, true))
                                            {
                                                if (nextValue is double)
                                                {
                                                    variant = new Variant((double)nextValue);
                                                }
                                                else
                                                {
                                                    double doubleValue = 0.0;

                                                    if (Value.GetDouble(
                                                            nextString, ValueFlags.AnyDouble, cultureInfo,
                                                            ref doubleValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(doubleValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeDecimal, true))
                                            {
                                                if (nextValue is decimal)
                                                {
                                                    variant = new Variant((decimal)nextValue);
                                                }
                                                else
                                                {
                                                    decimal decimalValue = decimal.Zero;

                                                    if (Value.GetDecimal(
                                                            nextString, ValueFlags.AnyDecimal, cultureInfo,
                                                            ref decimalValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(decimalValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
#if NET_40
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeBigInteger, true))
                                            {
                                                if (nextValue is BigInteger)
                                                {
                                                    variant = new Variant((BigInteger)nextValue);
                                                }
                                                else
                                                {
                                                    BigInteger bigIntegerValue = BigInteger.Zero;

                                                    if (Value.GetBigInteger2(
                                                            nextString, ValueFlags.AnyInteger, cultureInfo,
                                                            ref bigIntegerValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(bigIntegerValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
#endif
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeUnsignedWideInteger, true))
                                            {
                                                if (nextValue is ulong)
                                                {
                                                    variant = new Variant((ulong)nextValue);
                                                }
                                                else
                                                {
                                                    ulong ulongValue = 0;

                                                    if (Value.GetUnsignedWideInteger2(
                                                            nextString, ValueFlags.AnyWideInteger | ValueFlags.Unsigned,
                                                            cultureInfo, ref ulongValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(ulongValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeWideInteger, true))
                                            {
                                                if (nextValue is long)
                                                {
                                                    variant = new Variant((long)nextValue);
                                                }
                                                else
                                                {
                                                    long longValue = 0;

                                                    if (Value.GetWideInteger2(
                                                            nextString, ValueFlags.AnyWideInteger,
                                                            cultureInfo, ref longValue,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(longValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeUnsignedInteger, true))
                                            {
                                                if (nextValue is uint)
                                                {
                                                    variant = new Variant((uint)nextValue);
                                                }
                                                else
                                                {
                                                    uint uintValue = 0;

                                                    if (Value.GetUnsignedInteger2(
                                                            nextString, ValueFlags.AnyInteger | ValueFlags.Unsigned,
                                                            cultureInfo, ref uintValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(uintValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeInteger, true))
                                            {
                                                if (nextValue is int)
                                                {
                                                    variant = new Variant((int)nextValue);
                                                }
                                                else
                                                {
                                                    int intValue = 0;

                                                    if (Value.GetInteger2(
                                                            nextString, ValueFlags.AnyInteger, cultureInfo,
                                                            ref intValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(intValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeUnsignedNarrowInteger, true))
                                            {
                                                if (nextValue is ushort)
                                                {
                                                    variant = new Variant((ushort)nextValue);
                                                }
                                                else
                                                {
                                                    ushort ushortValue = 0;

                                                    if (Value.GetUnsignedNarrowInteger2(
                                                            nextString, ValueFlags.AnyNarrowInteger |
                                                            ValueFlags.Unsigned, cultureInfo, ref ushortValue,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(ushortValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeNarrowInteger, true))
                                            {
                                                if (nextValue is short)
                                                {
                                                    variant = new Variant((short)nextValue);
                                                }
                                                else
                                                {
                                                    short shortValue = 0;

                                                    if (Value.GetNarrowInteger2(
                                                            nextString, ValueFlags.AnyNarrowInteger,
                                                            cultureInfo, ref shortValue,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(shortValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeByte, true))
                                            {
                                                if (nextValue is byte)
                                                {
                                                    variant = new Variant((byte)nextValue);
                                                }
                                                else
                                                {
                                                    byte byteValue = 0;

                                                    if (Value.GetByte2(
                                                            nextString, ValueFlags.AnyByte, cultureInfo,
                                                            ref byteValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(byteValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeSignedByte, true))
                                            {
                                                if (nextValue is sbyte)
                                                {
                                                    variant = new Variant((sbyte)nextValue);
                                                }
                                                else
                                                {
                                                    sbyte sbyteValue = 0;

                                                    if (Value.GetSignedByte2(
                                                            nextString, ValueFlags.AnyByte | ValueFlags.Signed,
                                                            cultureInfo, ref sbyteValue, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(sbyteValue);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeBoolean, true))
                                            {
                                                if (nextValue is bool)
                                                {
                                                    variant = new Variant((bool)nextValue);
                                                }
                                                else
                                                {
                                                    if (FlagOps.HasFlags(flags, OptionFlags.Nullable, true))
                                                    {
                                                        bool? boolValue = null;

                                                        if (Value.GetNullableBoolean2(
                                                                nextString, strictOption ?
                                                                    ValueFlags.AnyStrictBoolean :
                                                                    ValueFlags.AnyBoolean, cultureInfo,
                                                                ref boolValue, ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(boolValue);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        bool boolValue = false;

                                                        if (Value.GetBoolean2(
                                                                nextString, strictOption ?
                                                                    ValueFlags.AnyStrictBoolean :
                                                                    ValueFlags.AnyBoolean,
                                                                cultureInfo, ref boolValue,
                                                                ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(boolValue);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeSecureString, true))
                                            {
                                                if (nextValue is SecureString)
                                                {
                                                    variant = new Variant((SecureString)nextValue);
                                                }
                                                else
                                                {
                                                    zero = true;

                                                    SecureString secureString = null;
                                                    IObject @object = null;

                                                    if (GetObject(
                                                            nextString, lookupFlags, ref @object,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        if (@object.Value is SecureString)
                                                        {
                                                            secureString = (SecureString)@object.Value;
                                                        }
                                                        else
                                                        {
                                                            error = "invalid secure string";
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    else
                                                    {
                                                        secureString = new SecureString();

                                                        foreach (char character in nextString)
                                                            secureString.AppendChar(character);

                                                        secureString.MakeReadOnly();
                                                    }

                                                    variant = new Variant(secureString);
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeEncoding, true))
                                            {
                                                if (nextValue is Encoding)
                                                {
                                                    variant = new Variant((Encoding)nextValue);
                                                }
                                                else
                                                {
                                                    Encoding encoding = null;

                                                    if (GetEncoding(
                                                            nextString, lookupFlags | LookupFlags.EncodingOptionMask,
                                                            ref encoding, ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(encoding);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeCultureInfo, true))
                                            {
                                                if (nextValue is CultureInfo)
                                                {
                                                    variant = new Variant((CultureInfo)nextValue);
                                                }
                                                else
                                                {
                                                    CultureInfo localCultureInfo = null;

                                                    try
                                                    {
                                                        localCultureInfo = CultureInfo.GetCultureInfo(
                                                            nextString); /* throw */

                                                        if (localCultureInfo != null)
                                                        {
                                                            variant = new Variant(localCultureInfo);
                                                        }
                                                        else
                                                        {
                                                            error = "invalid culture";
                                                            return ReturnCode.Error;
                                                        }
                                                    }
                                                    catch (Exception e)
                                                    {
                                                        error = e;
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeByteArray, true))
                                            {
                                                if (nextValue is byte[])
                                                {
                                                    variant = new Variant((byte[])nextValue);
                                                }
                                                else
                                                {
                                                    byte[] bytes = null;

                                                    if (StringOps.GetBytesFromString(
                                                            nextString, cultureInfo, ref bytes,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(bytes);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBePlugin, true))
                                            {
                                                if (nextValue is IPlugin)
                                                {
                                                    variant = new Variant((IPlugin)nextValue);
                                                }
                                                else
                                                {
                                                    IPlugin plugin = null;

                                                    if (GetPlugin(
                                                            nextString, lookupFlags, ref plugin,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(plugin);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeExecute, true))
                                            {
                                                if (nextValue is IExecute)
                                                {
                                                    variant = new Variant((IExecute)nextValue);
                                                }
                                                else
                                                {
                                                    IExecute execute = null;

                                                    if (MatchAnyIExecute(
                                                            null, safe ?
                                                                EngineFlags.None :
                                                                EngineFlags.MatchHidden,
                                                            nextString, lookupFlags, ref execute,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(execute);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeCallback, true))
                                            {
                                                if (nextValue is ICallback)
                                                {
                                                    variant = new Variant((ICallback)nextValue);
                                                }
                                                else
                                                {
                                                    ICallback callback = null;

                                                    if (Value.GetCallback(
                                                            this, null, nextString, appDomain, options,
                                                            Value.GetTypeValueFlags(
                                                                strictOption, false, noCase || noCaseOption),
                                                            cultureInfo, null, ref callback,
                                                            ref error) == ReturnCode.Ok)
                                                    {
                                                        variant = new Variant(callback);
                                                    }
                                                    else
                                                    {
                                                        return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else if (FlagOps.HasFlags(flags, OptionFlags.MustBeRuleSet, true))
                                            {
                                                if (nextValue is IRuleSet)
                                                {
                                                    variant = new Variant((IRuleSet)nextValue);
                                                }
                                                else
                                                {
                                                    IRuleSet ruleSet;

                                                    if (FlagOps.HasFlags(flags, OptionFlags.CouldBePath, true) &&
                                                        PathOps.IsRemoteUriOrFile(nextString))
                                                    {
#if TEST
                                                        ruleSet = null;

                                                        if (_Tests.Default.TestLoadRuleSet(
                                                                nextString, ref ruleSet, ref error) == ReturnCode.Ok)
                                                        {
                                                            variant = new Variant(ruleSet);
                                                        }
                                                        else
                                                        {
                                                            return ReturnCode.Error;
                                                        }
#else
                                                        error = "not implemented";
                                                        return ReturnCode.Error;
#endif
                                                    }
                                                    else
                                                    {
                                                        ruleSet = RuleSet.Create(
                                                            nextString, cultureInfo, ref error);

                                                        if (ruleSet != null)
                                                            variant = new Variant(ruleSet);
                                                        else
                                                            return ReturnCode.Error;
                                                    }
                                                }
                                            }
                                            else
                                            {
                                                //
                                                // NOTE: No strongly-typed value flags were set for this
                                                //       option, just use the string verbatim.
                                                //
                                                if (nextValue is string)
                                                    variant = new Variant((string)nextValue); // String
                                                else
                                                    variant = new Variant(nextString); // String
                                            }
                                        }
                                        else
                                        {
                                            //
                                            // NOTE: We are forbidden from interpreting the string as a
                                            //       strongly-typed value, just use the string verbatim.
                                            //
                                            if (nextValue is string)
                                                variant = new Variant((string)nextValue); // String
                                            else
                                                variant = new Variant(nextString); // String
                                        }

                                        if (!noSet)
                                            option.SetPresent(options, true, argumentIndex, variant);

                                        argumentIndex++; // skip option value...
                                    }
                                    else
                                    {
                                        error = String.Format(
                                            "{0} option must be followed by {1}",
                                            FormatOps.WrapOrNull(currentString),
                                            option.FlagsToString());

                                        return ReturnCode.Error;
                                    }
                                }
                                finally
                                {
                                    if (zero)
                                    {
                                        //
                                        // HACK: Attempt to forcibly "scrub"
                                        //       the plain-text option value
                                        //       from memory via whatever
                                        //       means are available.
                                        //
                                        if (nextArgument != null)
                                            nextArgument.ResetValue(this, true);

                                        if (localError != null)
                                            localError.ResetValue(this, true);

                                        if (error != null)
                                            error.ResetValue(this, true);

#if !MONO && NATIVE && WINDOWS
                                        if (canZero)
                                        {
                                            /* IGNORED */
                                            StringOps.ZeroStringOrTrace(nextString);
                                        }
#endif

                                        ObjectOps.CollectGarbage(); /* throw */
                                    }
                                }
                            }
                            else if (!noSet)
                            {
                                option.SetPresent(options, true, argumentIndex, null);
                            }
                        }
                        else
                        {
                            error = String.Format(
                                "{0} option is invalid",
                                FormatOps.WrapOrNull(currentString));

                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        if (ambiguous)
                        {
                            if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.ErrorOnAmbiguousOption, true))
                            {
                                //
                                // NOTE: This is not a valid option and we want to
                                //       treat this as an error.
                                //
                                error = localError;
                                return ReturnCode.Error;
                            }
                            else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.StopOnAmbiguousOption, true))
                            {
                                //
                                // NOTE: This is not a valid option and we want to
                                //       stop now because we want to assume it is
                                //       the first non-option argument.  This is
                                //       the default behavior.
                                //
                                nextIndex = argumentIndex;
                                return ReturnCode.Ok;
                            }
                            else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.IgnoreOnAmbiguousOption, true))
                            {
                                //
                                // NOTE: This is not a valid option and we want to
                                //       simply ignore it.  We may also want to skip
                                //       the next argument.
                                //
                                if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.SkipOnAmbiguousOption, true))
                                    argumentIndex++;
                            }
                        }
                        else
                        {
                            if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.ErrorOnUnknownOption, true))
                            {
                                //
                                // NOTE: This is not a valid option and we want to
                                //       treat this as an error.
                                //
                                error = localError;
                                return ReturnCode.Error;
                            }
                            else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.StopOnUnknownOption, true))
                            {
                                //
                                // NOTE: This is not a valid option and we want to
                                //       stop now because we want to assume it is
                                //       the first non-option argument.  This is
                                //       the default behavior.
                                //
                                nextIndex = argumentIndex;
                                return ReturnCode.Ok;
                            }
                            else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.IgnoreOnUnknownOption, true))
                            {
                                //
                                // NOTE: This is not a valid option and we want to
                                //       simply ignore it.  We may also want to skip
                                //       the next argument.
                                //
                                if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.SkipOnUnknownOption, true))
                                    argumentIndex++;
                            }
                        }
                    }
                }
                else
                {
                    if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.ErrorOnNonOption, true))
                    {
                        //
                        // NOTE: This is a non-option and we want to treat
                        //       this as an error.
                        //
                        error = String.Format(
                            "unexpected non-option argument {0}",
                            FormatOps.WrapOrNull(currentString));

                        return ReturnCode.Error;
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.StopOnNonOption, true))
                    {
                        //
                        // NOTE: This is a non-option and we want to stop
                        //       now because we want to treat it as the
                        //       first non-option argument.  This is the
                        //       default behavior.
                        //
                        nextIndex = argumentIndex;
                        return ReturnCode.Ok;
                    }
                    else if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.IgnoreOnNonOption, true))
                    {
                        //
                        // NOTE: This is a non-option and we want to simply
                        //       ignore it.  We may also want to skip the
                        //       next argument.
                        //
                        if (FlagOps.HasFlags(behaviorFlags, OptionBehaviorFlags.SkipOnNonOption, true))
                            argumentIndex++;
                    }
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual merging of two argument lists,
        /// including any options, into a single well-formed argument list.  It is
        /// the private implementation behind the merge-arguments operation.
        /// </summary>
        /// <param name="options">
        /// The collection of options used while merging the argument
        /// lists.
        /// </param>
        /// <param name="arguments1">
        /// The first argument list to merge.
        /// </param>
        /// <param name="arguments2">
        /// The second argument list to merge.
        /// </param>
        /// <param name="optionBehaviorFlags">
        /// The flags that control how options are handled while merging.
        /// </param>
        /// <param name="startIndex1">
        /// The index of the first argument to use from the first argument
        /// list.
        /// </param>
        /// <param name="startIndex2">
        /// The index of the first argument to use from the second argument
        /// list.
        /// </param>
        /// <param name="skipFirst1">
        /// Non-zero to skip the first argument of the first argument list.
        /// </param>
        /// <param name="skipFirst2">
        /// Non-zero to skip the first argument of the second argument list.
        /// </param>
        /// <param name="useRemaining1">
        /// Non-zero to append any remaining arguments from the first
        /// argument list after merging.
        /// </param>
        /// <param name="arguments">
        /// Upon success, this is set to the merged argument list.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the argument lists were merged
        /// successfully; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateMergeArguments(
            OptionDictionary options,
            ArgumentList arguments1,
            ArgumentList arguments2,
            OptionBehaviorFlags optionBehaviorFlags,
            int startIndex1,
            int startIndex2,
            bool skipFirst1,
            bool skipFirst2,
            bool useRemaining1,
            ref ArgumentList arguments,
            ref Result error
            )
        {
            ReturnCode code = ReturnCode.Ok;

            //
            // NOTE: The purpose of this method is to properly merge two
            //       arguments lists, including any options, so that the new
            //       combined argument list is constructed in a well-defined
            //       way and can be processed properly by the target command.
            //
            if ((arguments1 != null) || /* OPT: First set of raw arguments. */
                (arguments2 != null))   /* OPT: Second set of raw arguments. */
            {
                arguments = new ArgumentList();
            }
            else
            {
                arguments = null;
            }

            //
            // NOTE: *PHASE 1* Figure out where the options are in the first
            //       argument list (if there are any at all).
            //
            int argumentCount1 = Count.Invalid;
            int nextIndex1 = Index.Invalid;
            int endIndex1 = Index.Invalid;
            int remainingIndex1 = Index.Invalid;

            if (code == ReturnCode.Ok)
            {
                if (startIndex1 < 0)
                    startIndex1 = 0;

                if (arguments1 != null)
                {
                    argumentCount1 = arguments1.Count;

                    if (options != null)
                    {
                        if (argumentCount1 > startIndex1)
                        {
                            //
                            // NOTE: Execute the universal option parser in
                            //       "scan only" mode.  We do not want to
                            //       waste any time processing the option
                            //       values here just to throw them away, we
                            //       just need to know where they end so that
                            //       we can build the final argument list for
                            //       the target command.
                            //
                            code = ScanOptions(
                                options, arguments1, 0, startIndex1,
                                Index.Invalid, optionBehaviorFlags,
                                ref nextIndex1, ref endIndex1,
                                ref error);

                            if (code == ReturnCode.Ok)
                            {
                                if (endIndex1 != Index.Invalid)
                                {
                                    remainingIndex1 = endIndex1 + 1;
                                }
                                else if ((nextIndex1 != Index.Invalid) &&
                                    (nextIndex1 > 0))
                                {
                                    remainingIndex1 = nextIndex1;
                                }
                            }
                        }
                    }
                    else
                    {
                        //
                        // BUGFIX: We must set the next index even if there
                        //         are no options because the default value
                        //         means that there are "no non-option
                        //         arguments left".
                        //
                        nextIndex1 = startIndex1;

                        //
                        // TODO: Is this the right thing?  If "use remaining"
                        //       is set, should we treat this the same as
                        //       hitting a non-option at the start index?
                        //
                        if (nextIndex1 > 0)
                            remainingIndex1 = nextIndex1;
                    }
                }
            }

            //
            // NOTE: *PHASE 2* Figure out where the options are in the second
            //       argument list (if there are any at all).
            //
            int argumentCount2 = Count.Invalid;
            int nextIndex2 = Index.Invalid;
            int endIndex2 = Index.Invalid;

            if (code == ReturnCode.Ok)
            {
                if (startIndex2 < 0)
                    startIndex2 = 0;

                if (arguments2 != null)
                {
                    argumentCount2 = arguments2.Count;

                    if (options != null)
                    {
                        if (argumentCount2 > startIndex2)
                        {
                            //
                            // NOTE: Execute the universal option parser in
                            //       "scan only" mode.  We do not want to
                            //       waste any time processing the option
                            //       values here just to throw them away, we
                            //       just need to know where they end so that
                            //       we can build the final argument list for
                            //       the target command.
                            //
                            code = ScanOptions(
                                options, arguments2, 0, startIndex2,
                                Index.Invalid, optionBehaviorFlags,
                                ref nextIndex2, ref endIndex2,
                                ref error);
                        }
                    }
                    else
                    {
                        //
                        // BUGFIX: We must set the next index even if there
                        //         are no options because the default value
                        //         means that there are "no non-option
                        //         arguments left".
                        //
                        nextIndex2 = startIndex2;
                    }
                }
            }

            //
            // NOTE: *PHASE 3* With the information gathered above, perform
            //       the merge of the two argument lists into one, retaining
            //       the options chosen and any trailing end-of-options
            //       marker we find (one maximum).
            //
            if (code == ReturnCode.Ok)
            {
                //
                // NOTE: Process the arguments from the first list, if any.
                //
                int stopIndex1 = Index.Invalid;

                if (arguments1 != null)
                {
                    //
                    // NOTE: Figure out where we need to stop adding option
                    //       arguments from the first list.
                    //
                    if (endIndex1 != Index.Invalid) /* Exclude EndOfOptions? */
                        stopIndex1 = endIndex1 - ((arguments2 != null) ? 1 : 0);
                    else if ((nextIndex1 != Index.Invalid) && (nextIndex1 > 0))
                        stopIndex1 = nextIndex1 - 1; /* Before First Non-Option */
                    else
                        stopIndex1 = argumentCount1 - 1; /* All */

                    //
                    // NOTE: First, we want all the arguments from the first
                    //       list except the trailing end-of-options marker,
                    //       if any.
                    //
                    for (int argumentIndex1 = (skipFirst1 ? 1 : 0);
                            argumentIndex1 <= stopIndex1;
                            argumentIndex1++)
                    {
                        arguments.Add(arguments1[argumentIndex1]);
                    }
                }

                //
                // NOTE: Process the arguments from the second list, if any.
                //
                int stopIndex2 = Index.Invalid;

                if (arguments2 != null)
                {
                    //
                    // NOTE: Figure out where we need to stop adding option
                    //       arguments from the second list.
                    //
                    if (endIndex2 != Index.Invalid)
                        stopIndex2 = endIndex2; /* Include EndOfOptions */
                    else if ((nextIndex2 != Index.Invalid) && (nextIndex2 > 0))
                        stopIndex2 = nextIndex2 - 1; /* Before First Non-Option */
                    else
                        stopIndex2 = Index.Invalid; /* None */

                    //
                    // NOTE: Next, we want all the option arguments from the
                    //       second list, including the trailing end-of-options
                    //       marker, if any.  If there is no trailing
                    //       end-of-options marker in the second list and there
                    //       was in the first list, we "move" the one from the
                    //       first list to the end of the options arguments for
                    //       the second list.
                    //
                    if (stopIndex2 != Index.Invalid)
                    {
                        for (int argumentIndex2 = startIndex2;
                                argumentIndex2 <= stopIndex2; argumentIndex2++)
                        {
                            arguments.Add(arguments2[argumentIndex2]);
                        }
                    }

                    //
                    // NOTE: Next, if the first list had a trailing
                    //       end-of-options marker (which we skipped) and the
                    //       second list does not, add it to the resulting
                    //       argument list now.
                    //
                    if ((endIndex1 != Index.Invalid) && (endIndex2 == Index.Invalid))
                        arguments.Add(Option.EndOfOptions);

                    //
                    // NOTE: Optionally use the last argument from the first list
                    //       here.
                    //
                    if (arguments1 != null)
                    {
                        if (useRemaining1 && (remainingIndex1 != Index.Invalid))
                        {
                            for (int argumentIndex1 = remainingIndex1;
                                    argumentIndex1 < argumentCount1; argumentIndex1++)
                            {
                                arguments.Add(arguments1[argumentIndex1]);
                            }
                        }
                    }

                    //
                    // NOTE: Next, we want all the [non-option] arguments from
                    //       the second list starting at the beginning of the
                    //       list and ending before the first option argument.
                    //
                    for (int argumentIndex2 = (skipFirst2 ? 1 : 0);
                            (argumentIndex2 < argumentCount2) &&
                            (argumentIndex2 < startIndex2); argumentIndex2++)
                    {
                        arguments.Add(arguments2[argumentIndex2]);
                    }

                    //
                    // NOTE: Next, we want all the [non-option] arguments from
                    //       the second list starting after the last option
                    //       argument until the end of the list.
                    //
                    if (stopIndex2 != Index.Invalid)
                    {
                        for (int argumentIndex2 = stopIndex2 + 1;
                                argumentIndex2 < argumentCount2; argumentIndex2++)
                        {
                            arguments.Add(arguments2[argumentIndex2]);
                        }
                    }
                }
                else if (arguments1 != null)
                {
                    if (useRemaining1 && (remainingIndex1 != Index.Invalid))
                    {
                        for (int argumentIndex1 = remainingIndex1;
                                argumentIndex1 < argumentCount1; argumentIndex1++)
                        {
                            arguments.Add(arguments1[argumentIndex1]);
                        }
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method retrieves the list of shell arguments for this interpreter
        /// from the appropriate interpreter variable.  It is the private
        /// implementation behind the get-arguments operation.
        /// </summary>
        /// <param name="arguments">
        /// Upon success, this is set to the list of shell arguments, or
        /// null if none are present.
        /// </param>
        /// <param name="whatIf">
        /// Non-zero to read from the what-if shell arguments variable
        /// instead of the live shell arguments variable.
        /// </param>
        /// <param name="failOnError">
        /// Non-zero to return an error if the shell arguments cannot be
        /// retrieved; otherwise, a missing value is treated as success
        /// with a null list.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the shell arguments were
        /// retrieved successfully; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateGetArguments(
            ref IList<string> arguments,
            bool whatIf,
            bool failOnError,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                ReturnCode code;
                Result localError; /* REUSED */
                Result value = null;

                localError = null;

                code = GetVariableValue2(
                    VariableFlags.None, whatIf ?
                        Vars.Core.WhatIfShellArguments :
                        TclVars.Core.ShellArguments,
                    null, ref value, ref localError);

                if (code == ReturnCode.Ok)
                {
                    string stringValue = value; /* CONVERSION */

                    if (stringValue != null)
                    {
                        StringList list = null;

                        localError = null;

                        code = ParserOps<string>.SplitList(
                            this, stringValue, 0, Length.Invalid,
                            false, ref list, ref localError);

                        if (code == ReturnCode.Ok)
                            arguments = list;
                        else
                            error = localError;
                    }
                    else
                    {
                        arguments = null;
                        code = ReturnCode.Ok;
                    }
                }
                else if (!failOnError)
                {
                    arguments = null;
                    code = ReturnCode.Ok;
                }
                else
                {
                    error = localError;
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the list of shell arguments for this interpreter by
        /// updating the appropriate interpreter variables.  It is the private
        /// implementation behind the set-arguments operation.
        /// </summary>
        /// <param name="arguments">
        /// The list of shell arguments to set.
        /// </param>
        /// <param name="whatIf">
        /// Non-zero to update the what-if shell arguments variables
        /// instead of the live shell arguments variables.
        /// </param>
        /// <param name="failOnNull">
        /// Non-zero to return an error when the argument list is null;
        /// otherwise, a null list clears the shell arguments.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the shell arguments were set
        /// successfully; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateSetArguments(
            IList<string> arguments,
            bool whatIf,
            bool failOnNull,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                ReturnCode code;
                Result localError; /* REUSED */

                if (arguments != null)
                {
                    StringList localArguments;

                    if (arguments is StringList)
                        localArguments = (StringList)arguments;
                    else
                        localArguments = new StringList(arguments);

                    localError = null;

                    code = SetLibraryVariableValue(
                        VariableFlags.None, whatIf ?
                            Vars.Core.WhatIfShellArgumentCount :
                            TclVars.Core.ShellArgumentCount,
                        localArguments.Count.ToString(),
                        ref localError);

                    if (code == ReturnCode.Ok)
                    {
                        localError = null;

                        code = SetLibraryVariableValue(
                            VariableFlags.None, whatIf ?
                                Vars.Core.WhatIfShellArguments :
                                TclVars.Core.ShellArguments,
                            localArguments.ToString(),
                            ref localError);

                        if (code != ReturnCode.Ok)
                            error = localError;
                    }
                    else
                    {
                        error = localError;
                    }
                }
                else if (!failOnNull)
                {
                    localError = null;

                    code = SetLibraryVariableValue(
                        VariableFlags.None, whatIf ?
                            Vars.Core.WhatIfShellArgumentCount :
                            TclVars.Core.ShellArgumentCount,
                        Value.ZeroString, ref localError);

                    if (code == ReturnCode.Ok)
                    {
                        localError = null;

                        code = SetLibraryVariableValue(
                            VariableFlags.None, whatIf ?
                                Vars.Core.WhatIfShellArguments :
                                TclVars.Core.ShellArguments,
                            null, ref localError);

                        if (code != ReturnCode.Ok)
                            error = localError;
                    }
                    else
                    {
                        error = localError;
                    }
                }
                else
                {
                    error = "invalid argument list";
                    code = ReturnCode.Error;
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally prepends the specified arguments to the
        /// shell arguments for this interpreter, first removing a number of
        /// leading arguments if requested.  The added arguments are also
        /// prepended to the supplied argument vector.
        /// </summary>
        /// <param name="whatIf">
        /// Non-zero to operate on the what-if shell arguments instead of
        /// the live shell arguments.
        /// </param>
        /// <param name="removeCount">
        /// On input, the number of leading arguments to remove before
        /// adding; upon success, this is reset to zero.
        /// </param>
        /// <param name="oldArgv">
        /// On input, the existing argument vector; upon success, this is
        /// updated to include the added arguments.
        /// </param>
        /// <param name="addArguments">
        /// The arguments to prepend.  When this list is null or empty, no
        /// action is taken.  Upon success, this list is cleared.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the arguments were added
        /// successfully; otherwise, an error code.
        /// </returns>
        private ReturnCode MaybeAddArguments(
            bool whatIf,                /* in */
            ref int removeCount,        /* in, out */
            ref IList<string> oldArgv,  /* in, out */
            IList<string> addArguments, /* in */
            ref Result error            /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if ((addArguments == null) ||
                    (addArguments.Count == 0))
                {
                    return ReturnCode.Ok;
                }

                if (MaybeRemoveArguments(whatIf,
                        ref removeCount, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                IList<string> newArguments = null;

                if (PrivateGetArguments(
                        ref newArguments, whatIf, false,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                IList<string> newArgv = (oldArgv != null) ?
                    new StringList(oldArgv) : null;

                foreach (string argument in ListOps.Reverse(
                        addArguments))
                {
                    if (argument == null)
                        continue;

                    if (newArguments == null)
                        newArguments = new StringList();

                    newArguments.Insert(0, argument);

                    if (newArgv == null)
                        newArgv = new StringList();

                    newArgv.Insert(0, argument);
                }

                if (PrivateSetArguments(
                        newArguments, whatIf, false,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                oldArgv = newArgv;
                addArguments.Clear();

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally removes a number of leading arguments from
        /// the shell arguments for this interpreter.
        /// </summary>
        /// <param name="whatIf">
        /// Non-zero to operate on the what-if shell arguments instead of
        /// the live shell arguments.
        /// </param>
        /// <param name="count">
        /// On input, the number of leading arguments to remove; upon
        /// success, this is reset to zero.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the arguments were removed
        /// successfully; otherwise, an error code.
        /// </returns>
        private ReturnCode MaybeRemoveArguments(
            bool whatIf,     /* in */
            ref int count,   /* in, out */
            ref Result error /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (count > 0)
                {
                    IList<string> arguments = null;

                    if (PrivateGetArguments(
                            ref arguments, whatIf, false,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    if (arguments != null)
                    {
                        int localCount = count;

                        while ((arguments != null) &&
                            (arguments.Count > 0) &&
                            (localCount-- > 0))
                        {
                            GenericOps<string>.PopFirstArgument(
                                ref arguments);
                        }

                        if (PrivateSetArguments(
                                arguments, whatIf, false,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        count = 0;
                    }
                }

                return ReturnCode.Ok;
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ICacheManager Members
        /// <summary>
        /// This method determines whether the caches identified by the
        /// specified flags are currently enabled for this interpreter.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to query.
        /// </param>
        /// <returns>
        /// Non-zero if the specified caches are enabled; otherwise, zero.
        /// </returns>
        public bool AreCachesEnabled(
            CacheFlags flags
            )
        {
            CheckDisposed();

#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
            return InternalAreCachesEnabled(flags);
#else
            return false;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the caches identified by the specified flags,
        /// optionally updating the properties of the affected caches.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to clear.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable the affected caches when setting their
        /// properties; otherwise, zero to disable them.
        /// </param>
        /// <returns>
        /// The total number of items removed from the affected caches.
        /// </returns>
        public int ClearCaches(
            CacheFlags flags,
            bool enable
            )
        {
            CheckDisposed();

#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
            return PrivateClearCaches(flags, enable);
#else
            return 0;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables or disables the caches identified by the
        /// specified flags for this interpreter.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to enable or disable.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable the specified caches; otherwise, zero to
        /// disable them.
        /// </param>
        /// <returns>
        /// The flags identifying the caches that were actually affected.
        /// </returns>
        public CacheFlags EnableCaches(
            CacheFlags flags,
            bool enable
            )
        {
            CheckDisposed();

#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
            return InternalEnableCaches(flags, enable);
#else
            return CacheFlags.None;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the cache control operations (for example,
        /// locking, unlocking, resetting, clearing, and pre-setup) identified
        /// by the specified flags for this interpreter.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to operate on and which control
        /// operations to perform.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable the affected caches when setting their
        /// properties; otherwise, zero to disable them.
        /// </param>
        /// <returns>
        /// The flags identifying the control operations that were actually
        /// performed.
        /// </returns>
        public CacheFlags ControlCaches(
            CacheFlags flags,
            bool enable
            )
        {
            CheckDisposed();

#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return PrivateControlCaches(flags, enable);
            }
#else
            return CacheFlags.None;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
        /// <summary>
        /// This method initializes the caches for this interpreter using the
        /// default cache level appropriate for its priority.
        /// </summary>
        /// <param name="refresh">
        /// Non-zero to forcibly reinitialize the caches even when they have
        /// already been initialized.
        /// </param>
        private void InitializeCaches(
            bool refresh
            )
        {
            int level;

            if (HasHighPriority())
                level = CacheConfiguration.GetHighDefaultLevel(0);
            else
                level = CacheConfiguration.GetDefaultLevel();

            InitializeCaches(null, level, true, false);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the caches for this interpreter using the
        /// specified configuration text and cache level, optionally forcing a
        /// reinitialization, and emits a diagnostic trace describing the
        /// outcome.
        /// </summary>
        /// <param name="text">
        /// The optional cache configuration text to use.  This parameter may
        /// be null.
        /// </param>
        /// <param name="level">
        /// The cache level to use when initializing the caches.
        /// </param>
        /// <param name="defaultLevel">
        /// Non-zero if the supplied cache level is the default level, which is
        /// used only to refine the emitted diagnostic trace.
        /// </param>
        /// <param name="refresh">
        /// Non-zero to forcibly reinitialize the caches even when they have
        /// already been initialized.
        /// </param>
        private void InitializeCaches(
            string text,
            int level,
            bool defaultLevel,
            bool refresh
            )
        {
            bool didInitialize;
            bool wasInitialized;

            didInitialize = CacheConfiguration.Initialize(
                this, text, level, refresh, out wasInitialized);

            int count = 0;

            if (didInitialize && wasInitialized)
                count = PrivateClearCaches(CacheFlags.Default, false);

            StringList state = CacheConfiguration.GetStateAndOrSettings(
                CacheInformationFlags.Initialize);

            TracePriority priority;

            if (didInitialize)
            {
                priority = wasInitialized ?
                    TracePriority.StartupDebug3 :
                    TracePriority.StartupDebug;
            }
            else
            {
                priority = TracePriority.StartupError2;
            }

            TraceOps.DebugTrace(String.Format(
                "InitializeCaches: {0}{1} at {2}level {3} and cleared {4} items: {5}",
                String.Format("{0}{1}{2}", didInitialize ? String.Empty : "failed to ",
                refresh ? (didInitialize ? "forcible " : "forcibly ") : String.Empty,
                wasInitialized ? "reinitialized" : "initialized"), (text != null) ?
                String.Format(" using text {0}", FormatOps.WrapOrNull(text)) :
                String.Empty, defaultLevel ? "default " : String.Empty, level, count,
                FormatOps.WrapOrNull(state)), typeof(Interpreter).Name, priority);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the caches for this interpreter and then
        /// performs their pre-setup, all while holding the interpreter lock.
        /// </summary>
        /// <param name="text">
        /// The optional cache configuration text to use.  This parameter may
        /// be null.
        /// </param>
        /// <param name="level">
        /// The cache level to use when initializing the caches.
        /// </param>
        /// <param name="refresh">
        /// Non-zero to forcibly reinitialize the caches even when they have
        /// already been initialized.
        /// </param>
        /// <returns>
        /// The flags identifying the caches that were pre-set up.
        /// </returns>
        internal CacheFlags InitializeAndPreSetupCaches(
            string text,
            int level,
            bool refresh
            )
        {
            lock (syncRoot)
            {
                /* NO RESULT */
                InitializeCaches(text, level, false, refresh);

                return PreSetupCaches();
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
        /// <summary>
        /// This method compares the supplied cache generation value against
        /// the current cache generation of this interpreter, updating the
        /// cache hit and miss statistics accordingly.
        /// </summary>
        /// <param name="readOnly">
        /// Non-zero to require an exact match against the current cache
        /// generation; otherwise, the supplied value is updated to the
        /// current cache generation.
        /// </param>
        /// <param name="value">
        /// The cache generation value to compare.  When
        /// <paramref name="readOnly" /> is zero and a match is established,
        /// this is updated to the current cache generation.
        /// </param>
        /// <returns>
        /// Non-zero if the cache generation matched (or matching was skipped);
        /// otherwise, zero.
        /// </returns>
        internal bool MatchCacheGeneration(
            bool readOnly, /* in */
            ref long value /* in, out */
            )
        {
            //
            // WARNING: Having this flag set is dangerous because it could, at
            //          least in theory, lead to incorrect command resolution.
            //          This flag is primarily for diagnostic / test use only.
            //
            if (FlagOps.HasFlags(
                    cacheFlags, CacheFlags.NoGeneration, true)) /* NO-LOCK */
            {
                /* IGNORED */
                Interlocked.Increment(ref cacheHits);

                return true;
            }

            long localCacheGeneration = Interlocked.CompareExchange(
                ref cacheGeneration, 0, 0);

            if (localCacheGeneration <= 0) /* NOTE: Forbidden. */
            {
                /* IGNORED */
                Interlocked.Increment(ref cacheMisses);

                return false;
            }

            if (readOnly)
            {
                //
                // NOTE: Very strict, exact match only.
                //
                if (localCacheGeneration == value)
                {
                    /* IGNORED */
                    Interlocked.Increment(ref cacheHits);

                    return true;
                }
                else
                {
                    /* IGNORED */
                    Interlocked.Increment(ref cacheMisses);

                    return false;
                }
            }
            else
            {
                //
                // TODO: Should this actually be allowed?
                //
                // if (value <= 0) /* NOTE: Forbidden. */
                // {
                //     /* IGNORED */
                //     Interlocked.Increment(ref cacheMisses);
                //
                //     return false;
                // }
                //

                /* IGNORED */
                Interlocked.Increment(ref cacheHits);

                value = localCacheGeneration;
                return true;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the caches identified by the
        /// specified flags are currently enabled, while holding the
        /// interpreter lock.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to query.
        /// </param>
        /// <returns>
        /// Non-zero if the specified caches are enabled; otherwise, zero.
        /// </returns>
        internal bool InternalAreCachesEnabled(
            CacheFlags flags
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return PrivateAreCachesEnabled(flags);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the caches identified by the
        /// specified flags are currently enabled, assuming the interpreter
        /// lock is already held.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to query.
        /// </param>
        /// <returns>
        /// Non-zero if the specified caches are enabled; otherwise, zero.
        /// </returns>
        private bool PrivateAreCachesEnabled(
            CacheFlags flags
            )
        {
            return FlagOps.HasFlags(CacheFlagsNoLock, flags, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables or disables the caches identified by the
        /// specified flags, while holding the interpreter lock.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to enable or disable.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable the specified caches; otherwise, zero to
        /// disable them.
        /// </param>
        /// <returns>
        /// The flags identifying the caches that were actually affected.
        /// </returns>
        internal CacheFlags InternalEnableCaches(
            CacheFlags flags,
            bool enable
            )
        {
            CacheFlags result = CacheFlags.None;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                result |= PrivateControlCaches(flags, enable);

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Argument Cache
#if ARGUMENT_CACHE
                if (FlagOps.HasFlags(flags, CacheFlags.Argument, true))
                {
                    if (enable)
                        cacheFlags |= CacheFlags.Argument; /* EXEMPT */
                    else
                        cacheFlags &= ~CacheFlags.Argument; /* EXEMPT */

                    result |= CacheFlags.Argument;
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region StringList Cache
#if LIST_CACHE
                if (FlagOps.HasFlags(flags, CacheFlags.StringList, true))
                {
                    if (enable)
                        cacheFlags |= CacheFlags.StringList; /* EXEMPT */
                    else
                        cacheFlags &= ~CacheFlags.StringList; /* EXEMPT */

                    result |= CacheFlags.StringList;
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region ParseState Cache
#if PARSE_CACHE
                if (FlagOps.HasFlags(flags, CacheFlags.IParseState, true))
                {
                    if (enable)
                        cacheFlags |= CacheFlags.IParseState; /* EXEMPT */
                    else
                        cacheFlags &= ~CacheFlags.IParseState; /* EXEMPT */

                    result |= CacheFlags.IParseState;
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region IExecute Cache
#if EXECUTE_CACHE
                if (FlagOps.HasFlags(flags, CacheFlags.IExecute, true))
                {
                    if (enable)
                        cacheFlags |= CacheFlags.IExecute; /* EXEMPT */
                    else
                        cacheFlags &= ~CacheFlags.IExecute; /* EXEMPT */

                    result |= CacheFlags.IExecute;
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Type Cache
#if TYPE_CACHE
                if (FlagOps.HasFlags(flags, CacheFlags.Type, true))
                {
                    if (enable)
                        cacheFlags |= CacheFlags.Type; /* EXEMPT */
                    else
                        cacheFlags &= ~CacheFlags.Type; /* EXEMPT */

                    result |= CacheFlags.Type;
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region ComTypeList Cache
#if COM_TYPE_CACHE
                if (FlagOps.HasFlags(flags, CacheFlags.ComTypeList, true))
                {
                    if (enable)
                        cacheFlags |= CacheFlags.ComTypeList; /* EXEMPT */
                    else
                        cacheFlags &= ~CacheFlags.ComTypeList; /* EXEMPT */

                    result |= CacheFlags.ComTypeList;
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Static (AppDomain) Caches
                if (FlagOps.HasFlags(flags, CacheFlags.StringBuilder, true))
                {
                    if (SBC.MaybeEnable(enable))
                    {
                        if (enable)
                            cacheFlags |= CacheFlags.StringBuilder; /* EXEMPT */
                        else
                            cacheFlags &= ~CacheFlags.StringBuilder; /* EXEMPT */

                        result |= CacheFlags.StringBuilder;
                    }
                }
                #endregion
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method locks or unlocks the caches identified by the
        /// specified flags, assuming the interpreter lock is already held.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to lock or unlock.
        /// </param>
        /// <param name="lock">
        /// Non-zero to lock the specified caches; otherwise, zero to unlock
        /// them.
        /// </param>
        /// <returns>
        /// <see cref="CacheFlags.Lock" /> or <see cref="CacheFlags.Unlock" />
        /// when at least one of the typical caches was affected; otherwise,
        /// <see cref="CacheFlags.None" />.
        /// </returns>
        private CacheFlags LockCaches(
            CacheFlags flags,
            bool @lock
            )
        {
            CacheFlags newFlags = CacheFlags.None;

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Argument Cache
#if ARGUMENT_CACHE
            if ((argumentCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.Argument, true))
            {
                if (@lock)
                    cacheFlags |= CacheFlags.LockArgument; /* EXEMPT */
                else
                    cacheFlags &= ~CacheFlags.LockArgument; /* EXEMPT */

                newFlags |= CacheFlags.Argument;
            }
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region StringList Cache
#if LIST_CACHE
            if ((stringListCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.StringList, true))
            {
                if (@lock)
                    cacheFlags |= CacheFlags.LockStringList; /* EXEMPT */
                else
                    cacheFlags &= ~CacheFlags.LockStringList; /* EXEMPT */

                newFlags |= CacheFlags.StringList;
            }
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region ParseState Cache
#if PARSE_CACHE
            if ((parseStateCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.IParseState, true))
            {
                if (@lock)
                    cacheFlags |= CacheFlags.LockIParseState; /* EXEMPT */
                else
                    cacheFlags &= ~CacheFlags.LockIParseState; /* EXEMPT */

                newFlags |= CacheFlags.IParseState;
            }
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region IExecute Cache
#if EXECUTE_CACHE
            if (FlagOps.HasFlags(flags, CacheFlags.IExecute, true))
            {
                if (@lock)
                    cacheFlags |= CacheFlags.LockIExecute; /* EXEMPT */
                else
                    cacheFlags &= ~CacheFlags.LockIExecute; /* EXEMPT */

                newFlags |= CacheFlags.IExecute;
            }
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Type Cache
#if TYPE_CACHE
            if ((typeCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.Type, true))
            {
                if (@lock)
                    cacheFlags |= CacheFlags.LockType; /* EXEMPT */
                else
                    cacheFlags &= ~CacheFlags.LockType; /* EXEMPT */

                newFlags |= CacheFlags.Type;
            }
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region ComTypeList Cache
#if COM_TYPE_CACHE
            if ((comTypeListCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.ComTypeList, true))
            {
                if (@lock)
                    cacheFlags |= CacheFlags.LockComTypeList; /* EXEMPT */
                else
                    cacheFlags &= ~CacheFlags.LockComTypeList; /* EXEMPT */

                newFlags |= CacheFlags.ComTypeList;
            }
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Static (AppDomain) Caches
            if (FlagOps.HasFlags(flags, CacheFlags.StringBuilder, true))
            {
                //
                // HACK: This is faked because this cache does
                //       not support locking (or trimming).
                //
                if (@lock)
                    cacheFlags |= CacheFlags.LockStringBuilder; /* EXEMPT */
                else
                    cacheFlags &= ~CacheFlags.LockStringBuilder; /* EXEMPT */

                newFlags |= CacheFlags.StringBuilder;
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (FlagOps.HasFlags(newFlags, flags & CacheFlags.TypicalMask, true))
                return @lock ? CacheFlags.Lock : CacheFlags.Unlock;
            else
                return CacheFlags.None;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method performs the cache locking, unlocking, resetting,
        /// clearing, pre-setup, and property-setting operations identified by
        /// the specified flags, assuming the interpreter lock is already held.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to operate on and which control
        /// operations to perform.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable the affected caches when setting their
        /// properties; otherwise, zero to disable them.
        /// </param>
        /// <returns>
        /// The flags identifying the control operations that were actually
        /// performed.
        /// </returns>
        private CacheFlags PrivateControlCaches(
            CacheFlags flags,
            bool enable
            )
        {
            CacheFlags newFlags = CacheFlags.None;

            if (FlagOps.HasFlags(flags, CacheFlags.Unlock, true))
                newFlags |= LockCaches(flags, false);

            if (FlagOps.HasFlags(flags, CacheFlags.Lock, true))
                newFlags |= LockCaches(flags, true);

            if (FlagOps.HasFlags(flags, CacheFlags.Reset, true))
            {
                Dictionary<CacheFlags, long[]> savedCacheCounts = null;

                if (FlagOps.HasFlags(flags, CacheFlags.Clear, true))
                    newFlags |= ResetCaches(flags, ref savedCacheCounts);

                if (FlagOps.HasFlags(flags, CacheFlags.PreSetup, true))
                    newFlags |= PreSetupCaches(flags, savedCacheCounts);

#if CACHE_DICTIONARY
                if (FlagOps.HasFlags(flags, CacheFlags.SetProperties, true))
                    newFlags |= SetPropertiesOnCaches(flags, enable);
#endif
            }

            return newFlags;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE
        /// <summary>
        /// This method determines whether the argument cache can be used and,
        /// if so, retrieves the cached argument associated with the current
        /// context.
        /// </summary>
        /// <param name="hasCacheFlags">
        /// The additional cache flags that must also be enabled for the
        /// argument cache to be usable.
        /// </param>
        /// <param name="argument">
        /// Upon success, receives the cached argument.  Upon failure, this is
        /// left unchanged.
        /// </param>
        /// <returns>
        /// Non-zero if the argument cache can be used and a cached argument
        /// was retrieved; otherwise, zero.
        /// </returns>
        internal bool CanUseArgumentCache(
            CacheFlags hasCacheFlags, /* in */
            ref Argument argument     /* out */
            )
        {
            bool locked = false;

            try
            {
                //
                // HACK: Since the cache is used primarily to speed
                //       things up, do not use a waiting lock here.
                //
                InternalSoftTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    bool result = PrivateAreCachesEnabled(
                        CacheFlags.Argument | hasCacheFlags);

#if CACHE_DICTIONARY
                    if (!result &&
                        !PrivateAreCachesEnabled(CacheFlags.LockArgument) &&
                        CacheConfiguration.MaybeEnableOrDisable<Argument, Argument>(
                            this, argumentCache, CacheFlags.Argument, CacheFlagsNoLock))
                    {
                        if (argumentCache != null)
                            argumentCache.RestartChanges();

                        //
                        // TODO: Why aren't the "hasCacheFlags" considered here?
                        //       Of course, since the "cacheFlags" have not been
                        //       changed between the check above and here, that
                        //       would not make sense either.  Is this actually
                        //       correct?
                        //
                        result = PrivateAreCachesEnabled(CacheFlags.Argument);
                    }
#endif

                    if (result)
                    {
                        if (argumentCache != null)
                        {
                            Argument localArgument = CacheArgument; /* NOTE: Context only. */

                            if (localArgument != null)
                                argument = localArgument;
                            else
                                result = false;
                        }
                        else
                        {
                            result = false;
                        }
                    }

                    return result;
                }
                else
                {
                    //
                    // NOTE: If the interpreter lock cannot be obtained,
                    //       we cannot use its argument cache.
                    //
                    return false;
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For the core [source] command implementation and
        //       the core script library ("init.eagle") use only.
        //
        /// <summary>
        /// This method temporarily disables the argument cache for the current
        /// context, saving the previous context cache flags so they can be
        /// restored later.
        /// </summary>
        /// <param name="savedCacheFlags">
        /// Receives the context cache flags in effect prior to disabling the
        /// argument cache.
        /// </param>
        internal void BeginNoArgumentCache(
            out CacheFlags savedCacheFlags
            )
        {
            savedCacheFlags = ContextCacheFlags;
            ContextCacheFlags &= ~CacheFlags.Argument;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For the core [source] command implementation and
        //       the core script library ("init.eagle") use only.
        //
        /// <summary>
        /// This method restores the context cache flags previously saved by
        /// <c>BeginNoArgumentCache</c>, re-enabling the argument cache for the
        /// current context.
        /// </summary>
        /// <param name="savedCacheFlags">
        /// The context cache flags to restore.  This is reset to
        /// <see cref="CacheFlags.None" /> upon return.
        /// </param>
        internal void EndNoArgumentCache(
            ref CacheFlags savedCacheFlags
            )
        {
            ContextCacheFlags = savedCacheFlags;
            savedCacheFlags = CacheFlags.None;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if EXECUTE_CACHE
        /// <summary>
        /// This method clears the execute caches (including the hidden execute
        /// cache) for this interpreter and advances the cache generation.
        /// </summary>
        /// <returns>
        /// The total number of items removed from the execute caches.
        /// </returns>
        internal int ClearExecuteCache()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int result = 0;

                if (hiddenExecuteCache != null)
                {
                    Interlocked.Increment(ref cacheGeneration);

                    result += hiddenExecuteCache.Count;
                    hiddenExecuteCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    hiddenExecuteCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }

                if (executeCache != null)
                {
                    Interlocked.Increment(ref cacheGeneration);

                    result += executeCache.Count;
                    executeCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    executeCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }

                return result;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE
        /// <summary>
        /// This method clears the argument cache for this interpreter and
        /// resets the per-context cache argument.
        /// </summary>
        /// <param name="argumentOnly">
        /// Non-zero to reset only the per-context cache argument, leaving the
        /// shared argument cache contents intact; otherwise, zero to also
        /// clear the shared argument cache.
        /// </param>
        /// <returns>
        /// The total number of items removed from the argument cache.
        /// </returns>
        private int ClearArgumentCache(
            bool argumentOnly /* in */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int result = 0;

                if (!argumentOnly && (argumentCache != null))
                {
                    result += argumentCache.Count;
                    argumentCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    argumentCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }

                Argument argument = CacheArgument;

                if (argument != null)
                {
                    CacheArgument = null;
                    result++;
                }

                CacheArgument = Argument.InternalCreate();
                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the per-context cache argument, creating a new
        /// argument when one does not already exist.
        /// </summary>
        /// <returns>
        /// The existing or newly created cache argument.
        /// </returns>
        private Argument GetOrCreateCacheArgument()
        {
            Argument argument = CacheArgument;

            if (argument != null)
                return argument;

            return Argument.InternalCreate();
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally clears the argument cache for this
        /// interpreter, removing only the cached entry matching the specified
        /// value when one is supplied.
        /// </summary>
        /// <param name="value">
        /// The optional value whose matching cached argument should be
        /// removed.  When null, the entire argument cache is cleared.  This
        /// parameter may be null.
        /// </param>
        /// <returns>
        /// The total number of items removed from the argument cache.
        /// </returns>
        internal int MaybeClearArgumentCache(
            string value /* in: OPTIONAL */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int result = 0;

                if (value != null)
                {
                    Argument argument = GetOrCreateCacheArgument();

                    if (argument != null)
                    {
                        argument.Reset(
                            ArgumentFlags.ResetWithDefault, value);

                        if (MaybeRemoveCachedArgument(argument))
                        {
                            result += ClearArgumentCache(true) + 1;
                            goto done;
                        }
                    }
                }

                result += ClearArgumentCache(false);

            done:

                return result;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the caches identified by the specified flags for
        /// this interpreter.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to clear.
        /// </param>
        /// <returns>
        /// The total number of items removed from the affected caches.
        /// </returns>
        private int PrivateClearCaches(
            CacheFlags flags
            )
        {
            return PrivateClearCaches(flags, false);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the caches identified by the specified flags for
        /// this interpreter, optionally updating the properties of the
        /// affected caches.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches to clear.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable the affected caches when setting their
        /// properties; otherwise, zero to disable them.
        /// </param>
        /// <returns>
        /// The total number of items removed from the affected caches.
        /// </returns>
        private int PrivateClearCaches(
            CacheFlags flags,
            bool enable
            )
        {
            int result = 0;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                #region Argument Cache
#if ARGUMENT_CACHE
                if ((argumentCache != null) &&
                    FlagOps.HasFlags(flags, CacheFlags.Argument, true))
                {
                    result += argumentCache.Count;
                    argumentCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    argumentCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region StringList Cache
#if LIST_CACHE
                if ((stringListCache != null) &&
                    FlagOps.HasFlags(flags, CacheFlags.StringList, true))
                {
                    result += stringListCache.Count;
                    stringListCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    stringListCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region ParseState Cache
#if PARSE_CACHE
                if ((parseStateCache != null) &&
                    FlagOps.HasFlags(flags, CacheFlags.IParseState, true))
                {
                    result += parseStateCache.Count;
                    parseStateCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    parseStateCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region IExecute Cache
#if EXECUTE_CACHE
                if ((executeCache != null) &&
                    FlagOps.HasFlags(flags, CacheFlags.IExecute, true))
                {
                    result += executeCache.Count;
                    executeCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    executeCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if ((hiddenExecuteCache != null) &&
                    FlagOps.HasFlags(flags, CacheFlags.IExecute, true))
                {
                    result += hiddenExecuteCache.Count;
                    hiddenExecuteCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    hiddenExecuteCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Type Cache
#if TYPE_CACHE
                if ((typeCache != null) &&
                    FlagOps.HasFlags(flags, CacheFlags.Type, true))
                {
                    result += typeCache.Count;
                    typeCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    typeCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region ComTypeList Cache
#if COM_TYPE_CACHE
                if ((comTypeListCache != null) &&
                    FlagOps.HasFlags(flags, CacheFlags.ComTypeList, true))
                {
                    result += comTypeListCache.Count;
                    comTypeListCache.Clear();

#if CACHE_STATISTICS
                    /* IGNORED */
                    comTypeListCache.IncrementCacheCount(CacheCountType.Clear);
#endif
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

#if CACHE_DICTIONARY
                if (FlagOps.HasFlags(flags, CacheFlags.SetProperties, true))
                {
                    /* IGNORED */
                    SetPropertiesOnCaches(flags, enable);
                }
#endif
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Static (AppDomain) Caches
            if (FlagOps.HasFlags(flags, CacheFlags.StringBuilder, true))
            {
                result += SBC.Clear();
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Miscellaneous Caches
            if (FlagOps.HasFlags(flags, CacheFlags.Miscellaneous, true))
            {
                result += ProcessOps.Cleanup();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += EnumOps.ClearCache();

                ///////////////////////////////////////////////////////////////////////////////////////

#if SHELL && INTERACTIVE_COMMANDS
                result += HelpOps.ClearCache();
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

                result += StringOps.ClearPreambleEncodings();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += _Comparers.StringFileName.ClearCache();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += HashOps.Cleanup();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += FactoryOps.Cleanup();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += ScriptOps.ClearInterpreterCache();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += SyntaxOps.ClearCache();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += ConfigurationOps.Cleanup(
                    FlagOps.HasFlags(flags, CacheFlags.FullClear, true));

                ///////////////////////////////////////////////////////////////////////////////////////

                result += TraceLimits.Cleanup();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += MarshalOps.ToStringCache.Clear();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += CertificateOps.ClearCache();

                ///////////////////////////////////////////////////////////////////////////////////////

                result += RuntimeOps.ClearCache();
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            return result;
        }
        #endregion
        #endregion

