        /// <param name="engineContext">
        /// The engine context to reset, as an opaque object; when null, the
        /// engine context for the current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellation state is reset (e.g. local
        /// versus global).
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing why the
        /// cancellation state could not be reset.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode ResetCancel(
            object engineContext,
            CancelFlags cancelFlags,
            ref Result error
            )
        {
            CheckDisposed();

            Result canceledResults = null;
            bool canceled = false;
            bool unwound = false;
            bool reset = false;

            return InternalResetCancel(
                engineContext as IEngineContext, cancelFlags,
                ref canceledResults, ref canceled, ref unwound,
                ref reset, ref error);
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        //
        // NOTE: This method assumes the lock is held.
        //
        /// <summary>
        /// This method returns the thread that should be targeted when
        /// canceling script evaluation for this interpreter, selecting either
        /// the interactive thread or the primary thread.  It assumes the
        /// interpreter lock is held.
        /// </summary>
        /// <param name="useInteractiveThread">
        /// Non-zero to return the interactive thread; otherwise, the primary
        /// thread is returned.
        /// </param>
        /// <param name="threadTypeName">
        /// Receives a human-readable name describing which kind of thread was
        /// selected.
        /// </param>
        /// <returns>
        /// The selected thread, or null if there is no such thread.
        /// </returns>
        private Thread GetCancelThread(
            bool useInteractiveThread,
            ref string threadTypeName
            )
        {
#if SHELL
            if (useInteractiveThread)
            {
                threadTypeName = "interactive thread";

                /* NO-LOCK */
                return Interlocked.CompareExchange(
                    ref interactiveThread, null, null);
            }
            else
#endif
            {
                threadTypeName = "primary thread";

                /* NO-LOCK */
                return Interlocked.CompareExchange(
                    ref thread, null, null);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to interrupt (and optionally abort and/or wait
        /// for) the interpreter thread associated with this interpreter, as
        /// part of canceling script evaluation.
        /// </summary>
        /// <param name="timeout">
        /// The maximum time, in milliseconds, to wait for the thread; when
        /// null, a default timeout is used.
        /// </param>
        /// <param name="useThreadAbort">
        /// Non-zero to permit aborting the thread in addition to interrupting
        /// it.
        /// </param>
        /// <param name="useInteractiveThread">
        /// Non-zero to target the interactive thread instead of the primary
        /// thread.
        /// </param>
        /// <param name="waitForThread">
        /// Non-zero to wait for the thread after interrupting it.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat a failure to acquire the interpreter lock as an
        /// error.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode CancelThread(
            int? timeout,
            bool useThreadAbort,
            bool useInteractiveThread,
            bool waitForThread,
            bool strict,
            ref Result error
            )
        {
            Thread thread = null;
            string threadTypeName = null;
            bool gotThread = false;
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    thread = GetCancelThread(
                        useInteractiveThread, ref threadTypeName);

                    gotThread = true;
                }
                else
                {
                    TracePriority priority = strict ?
                        TracePriority.LockError :
                        TracePriority.LockWarning;

                    TraceOps.LockTrace(
                        "CancelThread",
                        typeof(Interpreter).Name, false,
                        priority,
                        MaybeWhoHasLock());

                    if (strict)
                    {
                        error = "could not lock interpreter";
                        return ReturnCode.Error;
                    }
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }

            if (thread != null)
            {
                if (!ThreadOps.IsCurrent(thread))
                {
                    try
                    {
                        ShutdownFlags flags = ShutdownFlags.Cancel;

                        if (useThreadAbort)
                            flags &= ~ShutdownFlags.NoAbort;

                        if (waitForThread)
                            flags |= ShutdownFlags.WaitAfter;

                        /* NO RESULT */
                        ThreadOps.MaybeShutdown(
                            this, timeout, flags, ref thread); /* throw */
                    }
                    catch (Exception e)
                    {
                        TraceOps.DebugTrace(
                            e, typeof(Interpreter).Name,
                            TracePriority.ThreadError);
                    }
                }
            }
            else if (gotThread)
            {
                TraceOps.DebugTrace(String.Format(
                    "CancelThread: no {0} to interrupt",
                    threadTypeName), typeof(Interpreter).Name,
                    TracePriority.ThreadError);
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method cancels the script currently being evaluated in this
        /// interpreter, discarding any error message produced while doing so.
        /// </summary>
        /// <param name="engineContext">
