        /// current thread is used.
        /// </param>
        /// <param name="result">
        /// The result to associate with the cancellation; when null, a default
        /// canceled (or unwound) error message is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellation is performed (e.g. local
        /// versus global, whether to unwind, and whether a result is needed).
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalCancelEvaluate(
#if THREADING
            IEngineContext engineContext,
#endif
            Result result,
            CancelFlags cancelFlags
            )
        {
            Result error = null;

            return PrivateCancelEvaluate(
#if THREADING
                engineContext,
#endif
                result, cancelFlags, ref error);
        }

