        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method computes the effective cancellation and unwind state for
        /// this interpreter from the specified flags, omitting the local and
        /// global scope indicators.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to consult; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that select which scopes (local and/or global) to consider.
        /// </param>
        /// <param name="localCancel">
        /// Receives a value indicating whether a local cancellation is pending.
        /// </param>
        /// <param name="localUnwind">
        /// Receives a value indicating whether a local unwind is pending.
        /// </param>
        /// <param name="globalCancel">
        /// Receives a value indicating whether a global cancellation is
        /// pending.
        /// </param>
        /// <param name="globalUnwind">
        /// Receives a value indicating whether a global unwind is pending.
        /// </param>
        /// <param name="anyCancel">
        /// Receives a value indicating whether any cancellation is pending.
        /// </param>
        /// <param name="anyUnwind">
        /// Receives a value indicating whether any unwind is pending.
        /// </param>
        private void GetCancelFlags(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
#if THREADING
            out bool localCancel,
            out bool localUnwind,
#endif
            out bool globalCancel,
            out bool globalUnwind,
            out bool anyCancel,
            out bool anyUnwind
            )
        {
            bool local;
            bool global;

            GetCancelFlags(
#if THREADING
                engineContext,
#endif
                cancelFlags,
                out local,
                out global,
#if THREADING
                out localCancel,
                out localUnwind,
#endif
                out globalCancel,
                out globalUnwind,
                out anyCancel,
                out anyUnwind
            );
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method computes the effective cancellation and unwind state for
        /// this interpreter from the specified flags, including the local and
        /// global scope indicators.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to consult; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that select which scopes (local and/or global) to consider.
        /// </param>
        /// <param name="local">
        /// Receives a value indicating whether the local scope was considered.
        /// </param>
        /// <param name="global">
        /// Receives a value indicating whether the global scope was considered.
        /// </param>
        /// <param name="localCancel">
        /// Receives a value indicating whether a local cancellation is pending.
        /// </param>
        /// <param name="localUnwind">
        /// Receives a value indicating whether a local unwind is pending.
        /// </param>
        /// <param name="globalCancel">
        /// Receives a value indicating whether a global cancellation is
        /// pending.
        /// </param>
        /// <param name="globalUnwind">
        /// Receives a value indicating whether a global unwind is pending.
        /// </param>
        /// <param name="anyCancel">
        /// Receives a value indicating whether any cancellation is pending.
        /// </param>
        /// <param name="anyUnwind">
        /// Receives a value indicating whether any unwind is pending.
        /// </param>
        private void GetCancelFlags(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
            out bool local,
            out bool global,
#if THREADING
            out bool localCancel,
            out bool localUnwind,
#endif
            out bool globalCancel,
            out bool globalUnwind,
            out bool anyCancel,
            out bool anyUnwind
            )
        {
            local = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Local, true);

            global = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Global, true);

#if THREADING
            localCancel = false;
            localUnwind = false;

            if (local &&
                HaveAnyEngineContext(engineContext, cancelFlags))
            {
                if (engineContext != null)
                {
                    localCancel = engineContext.Cancel; /* PROPERTY */
                    localUnwind = engineContext.Unwind; /* PROPERTY */
                }
                else
                {
                    localCancel = this.Cancel; /* PROPERTY */
                    localUnwind = this.Unwind; /* PROPERTY */
                }
            }
#endif

            globalCancel = false;
            globalUnwind = false;

            if (global)
            {
                globalCancel = this.cancel; /* FIELD */
                globalUnwind = this.unwind; /* FIELD */
            }

#if THREADING
            anyCancel = localCancel || globalCancel;
            anyUnwind = localUnwind || globalUnwind;
#else
            anyCancel = globalCancel;
            anyUnwind = globalUnwind;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method computes the effective halt state for this interpreter
        /// from the specified flags, omitting the local and global scope
        /// indicators.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to consult; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that select which scopes (local and/or global) to consider.
        /// </param>
        /// <param name="localHalt">
        /// Receives a value indicating whether a local halt is pending.
        /// </param>
        /// <param name="globalHalt">
        /// Receives a value indicating whether a global halt is pending.
        /// </param>
        /// <param name="anyHalt">
        /// Receives a value indicating whether any halt is pending.
        /// </param>
        private void GetHaltFlags(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
#if THREADING
            out bool localHalt,
#endif
            out bool globalHalt,
            out bool anyHalt
            )
        {
            bool local;
            bool global;

            GetHaltFlags(
#if THREADING
                engineContext,
#endif
                cancelFlags,
                out local,
                out global,
#if THREADING
                out localHalt,
#endif
                out globalHalt,
                out anyHalt
            );
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method computes the effective halt state for this interpreter
        /// from the specified flags, including the local and global scope
        /// indicators.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to consult; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that select which scopes (local and/or global) to consider.
        /// </param>
        /// <param name="local">
        /// Receives a value indicating whether the local scope was considered.
        /// </param>
        /// <param name="global">
        /// Receives a value indicating whether the global scope was considered.
        /// </param>
        /// <param name="localHalt">
        /// Receives a value indicating whether a local halt is pending.
        /// </param>
        /// <param name="globalHalt">
        /// Receives a value indicating whether a global halt is pending.
        /// </param>
        /// <param name="anyHalt">
        /// Receives a value indicating whether any halt is pending.
        /// </param>
        private void GetHaltFlags(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
            out bool local,
            out bool global,
#if THREADING
            out bool localHalt,
#endif
            out bool globalHalt,
            out bool anyHalt
            )
        {
            local = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Local, true);

            global = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Global, true);

#if THREADING
            localHalt = false;

            if (local &&
                HaveAnyEngineContext(engineContext, cancelFlags))
            {
                if (engineContext != null)
                {
                    localHalt = engineContext.Halt; /* PROPERTY */
                }
                else
                {
                    localHalt = this.Halt; /* PROPERTY */
                }
            }
#endif

            globalHalt = false;

            if (global)
            {
                globalHalt = this.halt; /* FIELD */
            }

#if THREADING
            anyHalt = localHalt || globalHalt;
#else
            anyHalt = globalHalt;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method verifies that a script cancellation (or its reset) is
        /// not being performed superfluously, based on whether the interpreter
        /// is currently busy.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="local">
        /// Non-zero to consider the local (per-thread) busy state.
        /// </param>
        /// <param name="global">
        /// Non-zero to consider the global (interpreter-wide) busy state.
        /// </param>
        /// <param name="busy">
        /// The busy state required for the operation; non-zero when setting a
        /// cancellation, zero when resetting one.
        /// </param>
        /// <param name="ignorePending">
        /// Non-zero to skip the busy-state checks entirely.
        /// </param>
        /// <param name="failPending">
        /// Non-zero to fail when the required busy state is not met.
        /// </param>
        /// <param name="localBusy">
        /// Receives a value indicating whether the interpreter is locally busy.
        /// </param>
        /// <param name="globalBusy">
        /// Receives a value indicating whether the interpreter is globally
        /// busy.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// Non-zero if the operation may proceed; otherwise, zero.
        /// </returns>
        private bool MaybeCancelBusyOrNot(
            bool local,
            bool global,
            bool busy,
            bool ignorePending,
            bool failPending,
            out bool localBusy,
            out bool globalBusy,
            ref Result error
            )
        {
            bool result = true;
            ResultList errors = null;

            localBusy = false;
            globalBusy = false;

            if (!ignorePending)
            {
                if (local)
                {
                    //
                    // BUGFIX: This check is intended to make sure that the calling
                    //         operation (i.e. set cancel -OR- reset cancel) is not
                    //         being performed superfluously.
                    //
                    //         busy = false, reset cancel
                    //         busy = true, set cancel
                    //
                    //         InternalIsBusy = false, not busy, cannot set cancel
                    //         InternalIsBusy = true, is busy, cannot reset cancel
                    //
                    localBusy = InternalIsBusy;

                    if ((localBusy != busy) && failPending)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        if (busy)
                            errors.Add("cannot cancel local script evaluation");
                        else
                            errors.Add("cannot reset local script cancellation");

                        result = false;
                    }
                }

                if (global)
                {
                    //
                    // BUGFIX: This check is intended to make sure that the calling
                    //         operation (i.e. set cancel -OR- reset cancel) is not
                    //         being performed superfluously.
                    //
                    //         busy = false, reset cancel
                    //         busy = true, set cancel
                    //
                    //         InternalIsGlobalBusy = false, not busy, cannot set cancel
                    //         InternalIsGlobalBusy = true, is busy, cannot reset cancel
                    //
                    globalBusy = InternalIsGlobalBusy;

                    if ((globalBusy != busy) && failPending)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        if (busy)
                            errors.Add("cannot cancel global script evaluation");
                        else
                            errors.Add("cannot reset global script cancellation");

                        result = false;
                    }
                }
            }

            if (!result && (errors != null))
                error = errors;

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method verifies that a script halt (or its reset) is not being
        /// performed superfluously, based on whether the interpreter is
        /// currently busy.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="local">
        /// Non-zero to consider the local (per-thread) busy state.
        /// </param>
        /// <param name="global">
        /// Non-zero to consider the global (interpreter-wide) busy state.
        /// </param>
        /// <param name="busy">
        /// The busy state required for the operation; non-zero when setting a
        /// halt, zero when resetting one.
        /// </param>
        /// <param name="ignorePending">
        /// Non-zero to skip the busy-state checks entirely.
        /// </param>
        /// <param name="failPending">
        /// Non-zero to fail when the required busy state is not met.
        /// </param>
        /// <param name="localBusy">
        /// Receives a value indicating whether the interpreter is locally busy.
        /// </param>
        /// <param name="globalBusy">
        /// Receives a value indicating whether the interpreter is globally
        /// busy.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// Non-zero if the operation may proceed; otherwise, zero.
        /// </returns>
        private bool MaybeHaltBusyOrNot(
            bool local,
            bool global,
            bool busy,
            bool ignorePending,
            bool failPending,
            out bool localBusy,
            out bool globalBusy,
            ref Result error
            )
        {
            bool result = true;
            ResultList errors = null;

            localBusy = false;
            globalBusy = false;

            if (!ignorePending)
            {
                if (local)
                {
                    localBusy = (ActiveInteractiveLoops > 1) || InternalIsBusy;

                    if ((localBusy == busy) && failPending)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        if (busy)
                            errors.Add("cannot locally set halt");
                        else
                            errors.Add("cannot locally reset halt");

                        result = false;
                    }
                }

                if (global)
                {
                    globalBusy =
#if SHELL
                        (GlobalInteractiveLoops > 1) ||
#endif
                        InternalIsGlobalBusy;

                    if ((globalBusy == busy) && failPending)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        if (busy)
                            errors.Add("cannot globally set halt");
                        else
                            errors.Add("cannot globally reset halt");

                        result = false;
                    }
                }
            }

            if (!result && (errors != null))
                error = errors;

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method determines whether script evaluation has been canceled
        /// (or unwound) for this interpreter, optionally resetting that state
        /// and reporting the kind of interruption that occurred.  It assumes
        /// the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to consult; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellation state is queried (e.g. local
        /// versus global, whether to reset it, and whether a result is needed).
        /// </param>
        /// <param name="interruptType">
        /// Receives flags describing the kind of interruption (canceled and/or
        /// unwound, local and/or global) that was detected.
        /// </param>
        /// <param name="breakpointType">
        /// Receives flags describing the kind of breakpoint corresponding to
        /// the detected interruption.
        /// </param>
        /// <param name="error">
        /// Upon a pending cancellation, receives the associated cancellation
        /// result (or a default canceled/unwound error message).
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Error" /> if a cancellation is pending;
        /// otherwise, <see cref="ReturnCode.Ok" />.
        /// </returns>
        internal ReturnCode InternalIsCanceled(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
            ref InterruptType interruptType,
#if DEBUGGER
            ref BreakpointType breakpointType,
#endif
            ref Result error
            ) /* ENTRY-POINT, THREAD-SAFE */
        {
#if THREADING
            bool localCancel;
            bool localUnwind;
#endif
            bool globalCancel;
            bool globalUnwind;
            bool anyCancel;
            bool anyUnwind;

            GetCancelFlags(
#if THREADING
                engineContext,
#endif
                cancelFlags,
#if THREADING
                out localCancel,
                out localUnwind,
#endif
                out globalCancel,
                out globalUnwind,
                out anyCancel,
                out anyUnwind
            );

            if (anyCancel || anyUnwind)
            {
                bool globalResult = false;
                bool didReset = false;

#if THREADING
                if (localCancel &&
                    HaveAnyEngineContext(engineContext, cancelFlags))
                {
                    if ((!didReset || FlagOps.HasFlags(
                            cancelFlags, CancelFlags.ResetAll, true)) &&
                        FlagOps.HasFlags(
                            cancelFlags, CancelFlags.ResetLocal, true))
                    {
                        if (engineContext != null)
                        {
                            engineContext.Cancel = false; /* PROPERTY */
                        }
                        else
                        {
                            this.Cancel = false; /* PROPERTY */
                        }

                        didReset = true;
                    }

                    interruptType |= InterruptType.Canceled;
                    interruptType |= InterruptType.Local;

#if DEBUGGER
                    breakpointType |= BreakpointType.Cancel;
#endif
                }
#endif

                if (globalCancel)
                {
                    if ((!didReset || FlagOps.HasFlags(
                            cancelFlags, CancelFlags.ResetAll, true)) &&
                        FlagOps.HasFlags(
                            cancelFlags, CancelFlags.ResetGlobal, true))
                    {
                        this.cancel = false; /* FIELD */
                        didReset = true;
                    }

                    interruptType |= InterruptType.Canceled;
                    interruptType |= InterruptType.Global;

#if DEBUGGER
                    breakpointType |= BreakpointType.Cancel;
#endif

#if THREADING
                    if (!localCancel)
#endif
                        globalResult = true;
                }

#if THREADING
                if (localUnwind)
                {
                    interruptType |= InterruptType.Unwound;
                    interruptType |= InterruptType.Local;

#if DEBUGGER
                    breakpointType |= BreakpointType.Unwind;
#endif
                }
#endif

                if (globalUnwind)
                {
                    interruptType |= InterruptType.Unwound;
                    interruptType |= InterruptType.Global;

#if DEBUGGER
                    breakpointType |= BreakpointType.Unwind;
#endif

#if THREADING
                    if (!localUnwind)
#endif
                        globalResult = true;
                }

                bool needResult = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.NeedResult, true);

                if (needResult)
                {
                    Result localError = null;

                    if (globalResult)
                    {
                        localError = this.cancelResult; /* FIELD */
                    }
#if THREADING
                    else
                    {
                        if (engineContext != null)
                        {
                            localError = engineContext.CancelResult; /* PROPERTY */
                        }
                        else
                        {
                            localError = this.CancelResult; /* PROPERTY */
                        }
                    }
#endif

                    if (localError == null)
                    {
#if THREADING
                        if (localUnwind || globalUnwind)
#else
                        if (globalUnwind)
#endif
                        {
                            localError = Result.Copy(
                                Engine.EvalUnwoundError, ResultFlags.CopyValue);
                        }
                        else
                        {
                            localError = Result.Copy(
                                Engine.EvalCanceledError, ResultFlags.CopyValue);
                        }
                    }

                    error = localError;
                }

                return ReturnCode.Error;
            }
            else
            {
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method records a pending script cancellation for this
        /// interpreter, setting the appropriate local and/or global
        /// cancellation state.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to cancel; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="result">
        /// The result to associate with the cancellation; when null, a default
        /// canceled (or unwound) error message is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellation is performed (e.g. local
        /// versus global, whether to unwind, and whether a result is needed).
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing why the
        /// cancellation could not be performed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalCancelEvaluate(
#if THREADING
            IEngineContext engineContext,
#endif
            Result result,
            CancelFlags cancelFlags,
            ref Result error
            )
        {
            bool local = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Local, true);

            bool global = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Global, true);

            if (local || global)
            {
                bool ignorePending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.IgnorePending, true);

                bool failPending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.FailPending, true);

                bool localBusy;
                bool globalBusy;

                if (!MaybeCancelBusyOrNot(
                        local, global, true, ignorePending, failPending,
                        out localBusy, out globalBusy, ref error))
                {
                    return ReturnCode.Error;
                }

                bool unwind = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.Unwind, true);

                bool needResult = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.NeedResult, true);

                Result localResult = null;

                if (needResult)
                {
                    localResult = (result != null) ? result : (unwind ?
                        Result.Copy(Engine.EvalUnwoundError, ResultFlags.CopyValue) :
                        Result.Copy(Engine.EvalCanceledError, ResultFlags.CopyValue));
                }

#if THREADING
                if (local && (ignorePending || localBusy) &&
                    HaveAnyEngineContext(engineContext, cancelFlags))
                {
                    if (engineContext != null)
                    {
                        engineContext.CancelEvaluate(
                            localResult, unwind, needResult);
                    }
                    else
                    {
                        CancelEvaluate(
                            localResult, unwind, needResult);
                    }
                }
#endif

                if (global && (ignorePending || globalBusy))
                {
                    this.cancel = true; /* FIELD */

                    if (unwind)
                        this.unwind = true; /* FIELD */

                    if (needResult)
                        this.cancelResult = localResult; /* FIELD */
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method records a pending script halt for this interpreter,
        /// setting the appropriate local and/or global halt state.  It assumes
        /// the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to halt; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="result">
        /// The result to associate with the halt; when null, a default halted
        /// error message is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the halt is performed (e.g. local versus
        /// global and whether a result is needed).
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing why the halt
        /// could not be performed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalHaltEvaluate(
#if THREADING
            IEngineContext engineContext,
#endif
            Result result,
            CancelFlags cancelFlags,
            ref Result error
            )
        {
            bool local = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Local, true);

            bool global = FlagOps.HasFlags(
                cancelFlags, CancelFlags.Global, true);

            if (local || global)
            {
                bool ignorePending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.IgnorePending, true);

                bool failPending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.FailPending, true);

                bool localBusy;
                bool globalBusy;

                if (!MaybeHaltBusyOrNot(
                        local, global, true, ignorePending, failPending,
                        out localBusy, out globalBusy, ref error))
                {
                    return ReturnCode.Error;
                }

                bool needResult = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.NeedResult, true);

                Result localResult = null;

                if (needResult)
                {
                    localResult = (result != null) ? result :
                        Result.Copy(Engine.HaltedError, ResultFlags.CopyValue);
                }

#if THREADING
                if (local && (ignorePending || localBusy) &&
                    HaveAnyEngineContext(engineContext, cancelFlags))
                {
                    if (engineContext != null)
                    {
                        engineContext.Halt = true; /* PROPERTY */

                        if (needResult)
                            engineContext.HaltResult = localResult; /* PROPERTY */
                    }
                    else
                    {
                        this.Halt = true; /* PROPERTY */

                        if (needResult)
                            this.HaltResult = localResult; /* PROPERTY */
                    }
                }
#endif

                if (global && (ignorePending || globalBusy))
                {
                    this.halt = true; /* FIELD */

                    if (needResult)
                        this.haltResult = localResult; /* FIELD */
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the Ready() method only.
        //
        /// <summary>
        /// This method resets any pending script cancellation state for this
        /// interpreter, optionally leaving the global cancellation state
        /// untouched and optionally firing a notification.  It is intended for
        /// use by the <c>Ready</c> method only.
        /// </summary>
        /// <param name="noGlobalCancel">
        /// Non-zero to leave the global cancellation state unchanged.
        /// </param>
        /// <param name="notify">
        /// Non-zero to fire a notification when a cancellation state was reset.
        /// </param>
        private void ResetCancel(
            bool noGlobalCancel,
            bool notify
            ) /* NO-LOCK */
        {
#if NOTIFY
            bool anyCancel = false;
#endif

            /////////////////////////////////////////////////////////

#if THREADING
            if (HaveEngineContext() && this.Cancel) /* PROPERTY */
            {
                this.Cancel = false; /* PROPERTY */

#if NOTIFY
                anyCancel = true;
#endif
            }
#endif

            /////////////////////////////////////////////////////////

            if (!noGlobalCancel && this.cancel) /* FIELD */
            {
                this.cancel = false; /* FIELD */

#if NOTIFY
                anyCancel = true;
#endif
            }

            /////////////////////////////////////////////////////////

#if NOTIFY
            if (notify && anyCancel)
            {
                /* IGNORED */
                CheckNotification(
                    NotifyType.Interpreter,
                    NotifyFlags.Reset | NotifyFlags.Canceled,
                    anyCancel, this, null, null, null);
            }
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets any pending script cancellation (or unwind) state
        /// for this interpreter, discarding the detailed results of the reset.
        /// </summary>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellation state is reset (e.g. local
        /// versus global).
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateResetCancel(
            CancelFlags cancelFlags
            )
        {
            Result canceledResults = null;
            bool canceled = false;
            bool unwound = false;
            bool reset = false;
            Result error = null;

            return InternalResetCancel(
#if THREADING
                null,
#endif
                cancelFlags, ref canceledResults,
                ref canceled, ref unwound, ref reset,
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method resets any pending script cancellation (or unwind) state
        /// for this interpreter, reporting which states were reset and any
        /// results that were cleared.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to reset; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellation state is reset (e.g. local
        /// versus global and whether results are needed).
        /// </param>
        /// <param name="canceledResults">
        /// Upon success, receives the list of cancellation results that were
        /// cleared, if any.
        /// </param>
        /// <param name="canceled">
        /// Upon success, receives a value indicating whether a cancellation was
        /// pending.
        /// </param>
        /// <param name="unwound">
        /// Upon success, receives a value indicating whether an unwind was
        /// pending.
        /// </param>
        /// <param name="reset">
        /// Upon success, receives a value indicating whether any state was
        /// actually reset.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalResetCancel(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
            ref Result canceledResults,
            ref bool canceled,
            ref bool unwound,
            ref bool reset,
            ref Result error
            ) /* ENTRY-POINT, THREAD-SAFE */
        {
            bool local;
            bool global;
#if THREADING
            bool localCancel;
            bool localUnwind;
#endif
            bool globalCancel;
            bool globalUnwind;
            bool anyCancel;
            bool anyUnwind;

            GetCancelFlags(
#if THREADING
                engineContext,
#endif
                cancelFlags,
                out local,
                out global,
#if THREADING
                out localCancel,
                out localUnwind,
#endif
                out globalCancel,
                out globalUnwind,
                out anyCancel,
                out anyUnwind
            );

            if (anyCancel || anyUnwind)
            {
                bool ignorePending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.IgnorePending, true);

                bool failPending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.FailPending, true);

                bool localBusy;
                bool globalBusy;

                if (!MaybeCancelBusyOrNot(
                        local, global, false, ignorePending, failPending,
                        out localBusy, out globalBusy, ref error))
                {
                    return ReturnCode.Error;
                }

#if THREADING
                bool localResult = false;

                if ((ignorePending || !localBusy) &&
                    HaveAnyEngineContext(engineContext, cancelFlags))
                {
                    if (engineContext != null)
                    {
                        if (localCancel)
                        {
                            engineContext.Cancel = false; /* PROPERTY */
                            localResult = true;
                        }

                        if (localUnwind)
                        {
                            engineContext.Unwind = false; /* PROPERTY */
                            localResult = true;
                        }
                    }
                    else
                    {
                        if (localCancel)
                        {
                            this.Cancel = false; /* PROPERTY */
                            localResult = true;
                        }

                        if (localUnwind)
                        {
                            this.Unwind = false; /* PROPERTY */
                            localResult = true;
                        }
                    }
                }
#endif

                bool globalResult = false;

                if (ignorePending || !globalBusy)
                {
                    if (globalCancel)
                    {
                        this.cancel = false; /* FIELD */
                        globalResult = true;
                    }

                    if (globalUnwind)
                    {
                        this.unwind = false; /* FIELD */
                        globalResult = true;
                    }
                }

                bool needResult = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.NeedResult, true);

                if (needResult)
                {
                    Result result; /* REUSED */
                    ResultList results = null;

#if THREADING
                    if (localResult &&
                        HaveAnyEngineContext(engineContext, cancelFlags))
                    {
                        if (engineContext != null)
                        {
                            result = engineContext.CancelResult; /* PROPERTY */
                        }
                        else
                        {
                            result = this.CancelResult; /* PROPERTY */
                        }

                        if (result != null)
                        {
                            if (results == null)
                                results = new ResultList();

                            results.Add(result);
                            this.CancelResult = null; /* PROPERTY */
                        }
                    }
#endif

                    if (globalResult)
                    {
                        result = this.cancelResult; /* FIELD */

                        if (result != null)
                        {
                            if (results == null)
                                results = new ResultList();

                            results.Add(result);
                            this.cancelResult = null; /* FIELD */
                        }
                    }

                    canceledResults = results;
                }

                canceled = anyCancel;
                unwound = anyUnwind;

#if THREADING
                reset = localResult || globalResult;
#else
                reset = globalResult;
#endif
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method determines whether script evaluation has been halted for
        /// this interpreter, optionally resetting that state.  It assumes the
        /// interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to consult; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the halt state is queried (e.g. local versus
        /// global, whether to reset it, and whether a result is needed).
        /// </param>
        /// <param name="error">
        /// Upon a pending halt, receives the associated halt result (or a
        /// default halted error message).
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Error" /> if a halt is pending; otherwise,
        /// <see cref="ReturnCode.Ok" />.
        /// </returns>
        internal ReturnCode InternalIsHalted(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
            ref Result error
            ) /* ENTRY-POINT, THREAD-SAFE */
        {
#if THREADING
            bool localHalt;
#endif
            bool globalHalt;
            bool anyHalt;

            GetHaltFlags(
#if THREADING
                engineContext,
#endif
                cancelFlags,
#if THREADING
                out localHalt,
#endif
                out globalHalt,
                out anyHalt
            );

            if (anyHalt)
            {
                bool globalResult = false;

#if THREADING
                if (localHalt &&
                    HaveAnyEngineContext(engineContext, cancelFlags))
                {
                    if (FlagOps.HasFlags(
                            cancelFlags, CancelFlags.ResetLocal, true))
                    {
                        if (engineContext != null)
                        {
                            engineContext.Halt = false; /* PROPERTY */
                        }
                        else
                        {
                            this.Halt = false; /* PROPERTY */
                        }
                    }
                }
#endif

                if (globalHalt)
                {
                    if (FlagOps.HasFlags(
                            cancelFlags, CancelFlags.ResetGlobal, true))
                    {
                        this.halt = false; /* FIELD */
                    }

#if THREADING
                    if (!localHalt)
#endif
                        globalResult = true;
                }

                bool needResult = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.NeedResult, true);

                if (needResult)
                {
                    Result localError = null;

                    if (globalResult)
                    {
                        localError = this.haltResult; /* FIELD */
                    }
#if THREADING
                    else
                    {
                        if (engineContext != null)
                        {
                            localError = engineContext.HaltResult; /* PROPERTY */
                        }
                        else
                        {
                            localError = this.HaltResult; /* PROPERTY */
                        }
                    }
#endif

                    if (localError == null)
                    {
                        localError = Result.Copy(
                            Engine.HaltedError, ResultFlags.CopyValue);
                    }

                    error = localError;
                }

                return ReturnCode.Error;
            }
            else
            {
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method resets any pending script halt state for this
        /// interpreter, reporting which states were reset and any results that
        /// were cleared.  It assumes the interpreter lock is held.
        /// </summary>
        /// <param name="engineContext">
        /// The engine context to reset; when null, the engine context for the
        /// current thread is used.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the halt state is reset (e.g. local versus
        /// global and whether results are needed).
        /// </param>
        /// <param name="haltedResults">
        /// Upon success, receives the list of halt results that were cleared,
        /// if any.
        /// </param>
        /// <param name="halted">
        /// Upon success, receives a value indicating whether a halt was
        /// pending.
        /// </param>
        /// <param name="reset">
        /// Upon success, receives a value indicating whether any state was
        /// actually reset.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalResetHalt(
#if THREADING
            IEngineContext engineContext,
#endif
            CancelFlags cancelFlags,
            ref Result haltedResults,
            ref bool halted,
            ref bool reset,
            ref Result error
            ) /* ENTRY-POINT, THREAD-SAFE */
        {
            bool local;
            bool global;
#if THREADING
            bool localHalt;
#endif
            bool globalHalt;
            bool anyHalt;

            GetHaltFlags(
#if THREADING
                engineContext,
#endif
                cancelFlags,
                out local,
                out global,
#if THREADING
                out localHalt,
#endif
                out globalHalt,
                out anyHalt
            );

            if (anyHalt)
            {
                bool ignorePending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.IgnorePending, true);

                bool failPending = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.FailPending, true);

                bool localBusy;
                bool globalBusy;

                if (!MaybeHaltBusyOrNot(
                        local, global, false, ignorePending, failPending,
                        out localBusy, out globalBusy, ref error))
                {
                    return ReturnCode.Error;
                }

#if THREADING
                bool localResult = false;

                if ((ignorePending || !localBusy) &&
                    HaveAnyEngineContext(engineContext, cancelFlags))
                {
                    if (engineContext != null)
                    {
                        if (localHalt)
                        {
                            engineContext.Halt = false; /* PROPERTY */
                            localResult = true;
                        }
                    }
                    else
                    {
                        if (localHalt)
                        {
                            this.Halt = false; /* PROPERTY */
                            localResult = true;
                        }
                    }
                }
#endif

                bool globalResult = false;

                if (ignorePending || !globalBusy)
                {
                    if (globalHalt)
                    {
                        this.halt = false; /* FIELD */
                        globalResult = true;
                    }
                }

                bool needResult = FlagOps.HasFlags(
                    cancelFlags, CancelFlags.NeedResult, true);

                if (needResult)
                {
                    Result result; /* REUSED */
                    ResultList results = null;

#if THREADING
                    if (localResult &&
                        HaveAnyEngineContext(engineContext, cancelFlags))
                    {
                        if (engineContext != null)
                        {
                            result = engineContext.HaltResult; /* PROPERTY */
                        }
                        else
                        {
                            result = this.HaltResult; /* PROPERTY */
                        }

                        if (result != null)
                        {
                            if (results == null)
                                results = new ResultList();

                            results.Add(result);
                            this.HaltResult = null; /* PROPERTY */
                        }
                    }
#endif

                    if (globalResult)
                    {
                        result = this.haltResult; /* FIELD */

                        if (result != null)
                        {
                            if (results == null)
                                results = new ResultList();

                            results.Add(result);
                            this.haltResult = null; /* FIELD */
                        }
                    }

                    haltedResults = results;
                }

                halted = anyHalt;

#if THREADING
                reset = localResult || globalResult;
#else
                reset = globalResult;
#endif
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the per-evaluation state of this interpreter in
        /// preparation for the engine, clearing any pending cancellation and,
        /// depending on the flags, resetting the result and error state.
        /// </summary>
        /// <param name="engineFlags">
        /// Flags that control which aspects of the state are reset (e.g. the
        /// result, return code, and error information).
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how any pending cancellation state is reset.
        /// </param>
        /// <param name="result">
        /// Upon return, may be cleared or have its return code reset, according
        /// to the specified engine flags.
        /// </param>
        internal void ResetForEngine(
            EngineFlags engineFlags,
            CancelFlags cancelFlags,
            ref Result result
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (!locked)
                {
                    TraceOps.LockTrace(
                        "ResetForEngine",
                        typeof(Engine).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    result = null;
                    return;
                }

                if (disposed)
                {
                    result = null;
                    return;
                }

                /* IGNORED */
                PrivateResetCancel(cancelFlags);

                engineFlags |= EngineFlagsNoLock;

                if (EngineFlagOps.HasNoResetResult(engineFlags))
                {
                    if ((result != null) && ((InternalLevels == 0) ||
                        EngineFlagOps.HasResetReturnCode(engineFlags)))
                    {
                        result.ReturnCode = ReturnCode.Ok;
                    }
                }
                else
                {
                    result = null;

                    if (!EngineFlagOps.HasNoResetError(engineFlags))
                        ResetContextErrorFlags();
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interrupt Callback Handling
        //
        // WARNING: These property accessor methods assume the interpreter
        //          lock is already held.
        //
        /// <summary>
        /// Gets or sets the callback that is invoked when script evaluation is
        /// interrupted (e.g. canceled, unwound, or halted) for this
        /// interpreter.  The accessors assume the interpreter lock is held.
        /// </summary>
        internal InterruptCallback InterruptCallback
        {
            get
            {
                // CheckDisposed();

                //lock (syncRoot)
                //{
                    return interruptCallback;
                //}
            }
            set
            {
                // CheckDisposed();

                //lock (syncRoot)
                //{
                    interruptCallback = value;
                //}
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method invokes the currently registered interrupt callback (if
        /// any) for this interpreter, temporarily clearing it to avoid
        /// re-entrancy and restoring it afterward.
        /// </summary>
        /// <param name="interruptType">
        /// The kind of interruption that occurred.
        /// </param>
        /// <param name="clientData">
        /// Optional caller-supplied data passed through to the callback.
        /// </param>
        /// <param name="waitForLock">
        /// Non-zero to wait for the interpreter lock; otherwise, a single
        /// attempt to acquire it is made.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem (e.g.
        /// the lock could not be acquired or the callback raised an exception).
        /// </param>
        /// <returns>
        /// The return code produced by the callback, or
        /// <see cref="ReturnCode.Ok" /> if no callback is registered;
        /// <see cref="ReturnCode.Error" /> if the lock could not be acquired.
        /// </returns>
        internal ReturnCode FireInterruptCallback(
            InterruptType interruptType,
            IClientData clientData,
            bool waitForLock,
            ref Result error
            )
        {
            // CheckDisposed();

            ReturnCode code = ReturnCode.Ok;
            InterruptCallback localInterruptCallback = null;
            bool locked; /* REUSED */

            try
            {
                locked = false;

                try
                {
                    //
                    // TODO: This was a "soft" lock; however, since this
                    //       is called to notify external components of
                    //       potentially important events, try harder.
                    //
                    if (waitForLock)
                        InternalHardTryLock(ref locked); /* TRANSACTIONAL */
                    else
                        InternalSoftTryLock(ref locked); /* TRANSACTIONAL */

                    if (locked)
                    {
                        localInterruptCallback = interruptCallback;
                        interruptCallback = null; /* NOTE: Prevent recursion? */
                    }
                    else
                    {
                        error = "unable to acquire lock";
                        code = ReturnCode.Error;
                    }
                }
                finally
                {
                    InternalExitLock(ref locked); /* TRANSACTIONAL */
                }

                if (code == ReturnCode.Ok)
                {
                    if (localInterruptCallback != null)
                    {
                        try
                        {
                            code = localInterruptCallback(
                                this, interruptType, clientData,
                                ref error);
                        }
                        catch (Exception e)
                        {
                            error = e;
                            code = ReturnCode.Error;
                        }
                    }
                }
            }
            finally
            {
                if (localInterruptCallback != null)
                {
                    locked = false;

                    try
                    {
                        if (waitForLock)
                            InternalHardTryLock(ref locked); /* TRANSACTIONAL */
                        else
                            InternalSoftTryLock(ref locked); /* TRANSACTIONAL */

                        if (locked)
                        {
                            //
                            // BUGFIX: Only restore the interrupt callback
                            //         if it was not changed while being
                            //         fired.
                            //
                            if (interruptCallback == null)
                            {
                                interruptCallback = localInterruptCallback;
                            }
                            else
                            {
                                DebugOps.Complain(this, ReturnCode.Error,
                                    "interrupt callback was not restored: " +
                                    "changed while being fired");
                            }
                        }
                        else
                        {
                            TraceOps.LockTrace(
                                "FireInterruptCallback",
                                typeof(Interpreter).Name, false,
                                TracePriority.LockError,
                                MaybeWhoHasLock());
                        }
                    }
                    finally
                    {
                        InternalExitLock(ref locked); /* TRANSACTIONAL */
                    }

                    localInterruptCallback = null;
                }
            }

            return code;
        }
        #endregion
        #endregion
        #endregion

