        #region Script Evaluation
        /// <summary>
        /// This method evaluates the specified script text in this interpreter,
        /// using its current engine, substitution, event, and expression flags,
        /// by delegating to the static <see cref="Engine" />.
        /// </summary>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateScript(
            string text,
            ref Result result
            )
        {
            CheckDisposed();

            return Engine.EvaluateScript(
                this, text, engineFlags, substitutionFlags,
                engineEventFlags, expressionFlags, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the specified script text in this interpreter,
        /// using its current engine, substitution, event, and expression flags,
        /// by delegating to the static <see cref="Engine" />.
        /// </summary>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateScript(
            string text,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            return Engine.EvaluateScript(
                this, text, engineFlags, substitutionFlags,
                engineEventFlags, expressionFlags, ref result,
                ref errorLine);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the specified script text in this interpreter,
        /// combining the specified engine flags with the interpreter's current
        /// flags, by delegating to the static <see cref="Engine" />.
        /// </summary>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="engineFlags">
        /// Additional engine flags to combine with this interpreter's current
        /// engine flags for this evaluation.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateScript(
            string text,
            EngineFlags engineFlags,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            return Engine.EvaluateScript(this, text,
                engineFlags | this.engineFlags, substitutionFlags,
                engineEventFlags, expressionFlags, ref result,
                ref errorLine);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the specified script text in this interpreter
        /// while the specified file name is pushed as the current script
        /// location, by delegating to the static <see cref="Engine" />.
        /// </summary>
        /// <param name="fileName">
        /// The file name to associate with the script as its location.
        /// </param>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateScript(
            string fileName,
            string text,
            ref Result result
            )
        {
            CheckDisposed();

            bool pushed = false;

            PushScriptLocation(fileName, true, ref pushed);

            try
            {
                return Engine.EvaluateScript(
                    this, text, engineFlags, substitutionFlags,
                    engineEventFlags, expressionFlags, ref result);
            }
            finally
            {
                PopScriptLocation(true, ref pushed);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the specified script text in this interpreter
        /// while the specified file name is pushed as the current script
        /// location, by delegating to the static <see cref="Engine" />.
        /// </summary>
        /// <param name="fileName">
        /// The file name to associate with the script as its location.
        /// </param>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateScript(
            string fileName,
            string text,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            bool pushed = false;

            PushScriptLocation(fileName, true, ref pushed);

            try
            {
                return Engine.EvaluateScript(
                    this, text, engineFlags, substitutionFlags,
                    engineEventFlags, expressionFlags, ref result,
                    ref errorLine);
            }
            finally
            {
                PopScriptLocation(true, ref pushed);
            }
        }

