                SetErrorLine(this, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads, verifies, and evaluates the bundled scripts
        /// contained in the specified bundle file in this interpreter.
        /// </summary>
        /// <param name="fileName">
        /// The name of the bundle file to evaluate.
        /// </param>
        /// <param name="password">
        /// Optional password used to decrypt and/or verify the bundle file;
        /// may be null.
        /// </param>
        /// <param name="bundleFlags">
        /// Flags that control how the bundle is processed (e.g. key ring
        /// requirements and error handling).
        /// </param>
        /// <param name="clientData">
        /// On input, optional caller-supplied data; on output, may receive data
        /// produced while processing the bundle.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the combined result of the bundle scripts;
        /// upon failure, receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the offending script
        /// where the error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode EvaluateBundleFile(
            string fileName,
            byte[] password,
            BundleFlags bundleFlags,
            ref IClientData clientData,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            IHaveScriptFlags haveScriptFlags = new HaveScriptFlags(false);

            lock (syncRoot) /* TRANSACTIONAL */
            {
                haveScriptFlags.ScriptFlags = ScriptFlagsNoLock;
                haveScriptFlags.EngineFlags = EngineFlagsNoLock;
                haveScriptFlags.SubstitutionFlags = SubstitutionFlagsNoLock;
                haveScriptFlags.EventFlags = EngineEventFlagsNoLock;
                haveScriptFlags.ExpressionFlags = ExpressionFlagsNoLock;
            }

            haveScriptFlags.BundleFlags = bundleFlags;

            return EvaluateBundleFile(
                fileName, password, haveScriptFlags,
                ref clientData, ref result, ref errorLine);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads, verifies, and evaluates the bundled scripts
        /// contained in the specified bundle file in this interpreter, using
        /// the script flags supplied by the caller.
        /// </summary>
        /// <param name="fileName">
        /// The name of the bundle file to evaluate.
        /// </param>
        /// <param name="password">
        /// Optional password used to decrypt and/or verify the bundle file;
        /// may be null.
        /// </param>
        /// <param name="haveScriptFlags">
        /// Optional object supplying the script, engine, substitution, event,
        /// expression, and bundle flags to use; may be null.
        /// </param>
        /// <param name="clientData">
        /// On input, optional caller-supplied data; on output, may receive data
        /// produced while processing the bundle.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the combined result of the bundle scripts;
        /// upon failure, receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the offending script
        /// where the error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode EvaluateBundleFile(
            string fileName,                  /* in */
            byte[] password,                  /* in: OPTIONAL */
            IHaveScriptFlags haveScriptFlags, /* in: OPTIONAL */
            ref IClientData clientData,       /* in, out: OPTIONAL */
            ref Result result,                /* out */
            ref int errorLine                 /* out */
            )
        {
            CheckDisposed();

            Encoding encoding = StringOps.GetEncoding(
                EncodingType.Script);

            if (encoding == null)
            {
                result = "invalid script encoding";
                return ReturnCode.Error;
            }

            if (ScriptOps.EnableOrDisableSecurity(
                    this, true, true, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            BundleFlags bundleFlags = (haveScriptFlags != null) ?
                haveScriptFlags.BundleFlags : BundleFlags.Default;

            Result localResult; /* REUSED */

            string keyRingFileName = ScriptOps.FindSecurityPackageFile(
                this, mergeBundleKeyRingFileName);

            if (!String.IsNullOrEmpty(keyRingFileName)) /* OPTIONAL(?) */
            {
                StringList mergeCommand = new StringList();

                mergeCommand.Add(NamespaceOps.MakeAbsoluteName(
                    mergeBundleCommandName));

                mergeCommand.Add(mergeBundleSubCommandName);
                mergeCommand.Add(keyRingFileName);

                localResult = null;

                if (EvaluateTrustedScript(
                        mergeCommand.ToString(),
                        TrustFlags.MaybeMarkTrusted,
                        ref localResult) != ReturnCode.Ok)
                {
                    result = localResult;
                    return ReturnCode.Error;
                }
            }
            else if (FlagOps.HasFlags(
                    bundleFlags, BundleFlags.RequireKeyRing, true))
            {
                result = String.Format(
                    "missing the required bundle key ring file {0}",
                    FormatOps.WrapOrNull(mergeBundleKeyRingFileName));

                return ReturnCode.Error;
            }

            StringList verifyCommand = new StringList();

            verifyCommand.Add(NamespaceOps.MakeAbsoluteName(
                verifyBundleCommandName));

            verifyCommand.Add(verifyBundleSubCommandName);
            verifyCommand.Add(fileName);

            localResult = null;

            if (EvaluateTrustedScript(
                    verifyCommand.ToString(),
                    TrustFlags.MaybeMarkTrusted,
                    ref localResult) != ReturnCode.Ok)
            {
                result = localResult;
                return ReturnCode.Error;
            }

            CultureInfo cultureInfo = InternalCultureInfo;
            List<Script> scripts = null;

            if (DataOps.GatherBundleScripts(
                    this, cultureInfo, haveScriptFlags, clientData,
                    encoding, fileName, password, null, false,
                    false, ref scripts, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (scripts == null)
            {
                result = "invalid bundle scripts";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(
                    bundleFlags, BundleFlags.ErrorOnEmpty, true) &&
                (scripts.Count == 0))
            {
                result = "bundle file has no scripts";
                return ReturnCode.Error;
            }

            IBundleManager bundleManager;

            lock (syncRoot)
            {
                bundleManager = this.bundleManager;
            }

            if (bundleManager == null)
            {
                result = "invalid bundle manager";
                return ReturnCode.Error;
            }

            if (bundleManager.Mount(
                    this, fileName, password, false,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            string savedFileName;

            bundleManager.BeginEvaluation(
                this, fileName, out savedFileName);

            try
            {
                bool pushed = false;

                PushScriptLocation(fileName, true, ref pushed);

                try
                {
                    ResultList results = null;
                    ResultList errors = null;
                    int localErrorLine = 0;

                    foreach (Script script in scripts)
                    {
                        if (script == null)
                            continue;

                        IBundleData bundleData = script.BundleData;

                        if (bundleData == null)
                            continue;

                        localResult = null;

                        if (Engine.EvaluateScript(this,
                                script, bundleData, ref localResult,
                                ref localErrorLine) == ReturnCode.Ok)
                        {
                            if (results == null)
                                results = new ResultList();

                            results.Add(localResult);
                        }
                        else
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(localResult);

                            if (FlagOps.HasFlags(bundleFlags,
                                    BundleFlags.StopOnError, true))
                            {
                                break;
                            }
                        }
                    }

                    if (errors != null)
                    {
                        result = ResultList.Combine(
                            errors, results);

                        if (localErrorLine != 0)
                            errorLine = localErrorLine;

                        return ReturnCode.Error;
                    }
                    else
                    {
                        result = results;
                        return ReturnCode.Ok;
                    }
                }
                finally
                {
                    PopScriptLocation(true, ref pushed);
                }
            }
            finally
            {
                bundleManager.EndEvaluation(
                    this, ref savedFileName);
            }
        }
#endif

