        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads and evaluates the script contained in the
        /// specified file in this interpreter with elevated trust (temporarily
        /// marking a safe interpreter as trusted), according to the specified
        /// trust flags, by delegating to the static <see cref="Engine" /> once
        /// trust has been applied.
        /// </summary>
        /// <param name="encoding">
        /// The character encoding to use when reading the file; when null, a
        /// default encoding is used.
        /// </param>
        /// <param name="fileName">
        /// The name of the file containing the script to evaluate.
        /// </param>
        /// <param name="trustFlags">
        /// Flags that control how trust is applied (e.g. exclusivity, event
        /// handling, ignoring hidden commands, security levels, and scope frame
        /// use).
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateTrustedFile(
            Encoding encoding,
            string fileName,
            TrustFlags trustFlags,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            bool exclusive;
            bool withEvents;
            bool markTrusted;
            bool allowUnsafe;
            bool ignoreHidden;
            bool useSecurityLevels;
            bool pushScriptLocation;

#if ISOLATED_PLUGINS
            bool noIsolatedPlugins;
#endif

            bool withScopeFrame;

            ScriptOps.ExtractTrustFlags(
                trustFlags, out exclusive, out withEvents, out markTrusted,
                out allowUnsafe, out ignoreHidden, out useSecurityLevels,
                out pushScriptLocation
#if ISOLATED_PLUGINS
                , out noIsolatedPlugins
#endif
                , out withScopeFrame
            );

            bool locked = false;

            try
            {
                if (exclusive)
                    InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (!exclusive || locked)
                {
                    int savedEnabled = 0;

                    if (!withEvents)
                    {
                        if (!EventOps.SaveEnabledAndForceDisabled(
                                this, true, ref savedEnabled))
                        {
                            result = "failed to forcibly disable events";
                            return ReturnCode.Error;
                        }
                    }

                    try
                    {
                        if (markTrusted)
                        {
                            //
                            // NOTE: Use of this flag is currently limited to
                            //       "safe" child interpreters only.  Just
                            //       ignore the flag if called for an "unsafe"
                            //       interpreter.
                            //
                            if (InternalIsSafe())
                                InternalMarkTrusted();
                            else
                                markTrusted = false;
                        }

                        //
                        // NOTE: Use of this method is currently limited to
                        //       "safe" child interpreters only.  Issue an
                        //       error message if called for an "unsafe"
                        //       interpreter.
                        //
                        if (!markTrusted && !allowUnsafe && !InternalIsSafe())
                        {
                            result = "interpreter is already trusted";
                            return ReturnCode.Error;
                        }

                        try
                        {
                            //
                            // HACK: If necessary, add the "IgnoreHidden" engine
                            //       flag to the per-thread engine flags for this
                            //       interpreter so that the script specified by
                            //       the caller can run with full trust.  The
                            //       per-thread engine flags must be used in this
                            //       case; otherwise, other scripts being evaluated
                            //       on other threads in this interpreter would
                            //       also gain full trust.
                            //
                            bool ignoredHidden = false;

                            if (ignoreHidden &&
                                !EngineFlagOps.HasIgnoreHidden(this.ContextEngineFlags))
                            {
                                ignoredHidden = true;
                                this.ContextEngineFlags |= EngineFlags.IgnoreHidden;
                            }

                            try
                            {
                                EnterTrustedLevel();

                                try
                                {
                                    if (useSecurityLevels)
                                        EnterSecurityLevel();

                                    try
                                    {
#if ISOLATED_PLUGINS
                                        PluginFlags savedPluginFlags = PluginFlags.None;

                                        if (noIsolatedPlugins)
                                            BeginNoIsolatedPlugins(ref savedPluginFlags);

                                        try
                                        {
#endif
                                            if (withScopeFrame)
                                            {
                                                return Engine.EvaluateFileWithScopeFrame(
                                                    this, encoding, fileName, engineFlags,
                                                    substitutionFlags, engineEventFlags,
                                                    expressionFlags, ref result, ref errorLine);
                                            }
                                            else
                                            {
                                                return Engine.EvaluateFile(
                                                    this, encoding, fileName, engineFlags,
                                                    substitutionFlags, engineEventFlags,
                                                    expressionFlags, ref result, ref errorLine);
                                            }
#if ISOLATED_PLUGINS
                                        }
                                        finally
                                        {
                                            if (noIsolatedPlugins)
                                                EndNoIsolatedPlugins(ref savedPluginFlags);
                                        }
#endif
                                    }
                                    finally
                                    {
                                        if (useSecurityLevels)
                                            ExitSecurityLevel();
                                    }
                                }
                                finally
                                {
                                    ExitTrustedLevel();
                                }
                            }
                            finally
                            {
                                if (ignoredHidden)
                                {
                                    this.ContextEngineFlags &= ~EngineFlags.IgnoreHidden;
                                    ignoredHidden = false;
                                }
                            }
                        }
                        finally
                        {
                            if (markTrusted)
                            {
                                InternalMarkSafe();
                                markTrusted = false;
                            }
                        }
                    }
                    finally
                    {
                        if (!withEvents)
                        {
                            /* IGNORED */
                            EventOps.RestoreEnabled(this, savedEnabled);

                            savedEnabled = 0;
                        }
                    }
                }
                else
                {
                    TraceOps.LockTrace(
                        "EvaluateTrustedFile",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    result = "could not lock interpreter";
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads and evaluates the script contained in the
        /// specified text reader in this interpreter with elevated trust
        /// (temporarily marking a safe interpreter as trusted), according to
        /// the specified trust flags; on failure, the error line is also
        /// recorded on the interpreter.
        /// </summary>
        /// <param name="name">
        /// A name to associate with the stream as its script location.
        /// </param>
        /// <param name="textReader">
        /// The text reader from which the script is read.
        /// </param>
        /// <param name="trustFlags">
        /// Flags that control how trust is applied (e.g. exclusivity, event
        /// handling, ignoring hidden commands, security levels, and scope frame
        /// use).
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateTrustedStream(
            string name,
            TextReader textReader,
            TrustFlags trustFlags,
            ref Result result
            )
        {
            CheckDisposed();

            int errorLine = 0;

            ReturnCode code = EvaluateTrustedStream(
                name, textReader, 0, Count.Invalid,
                trustFlags, ref result, ref errorLine);

            if (errorLine != 0)
                SetErrorLine(this, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads and evaluates the script contained in the
        /// specified text reader in this interpreter with elevated trust
        /// (temporarily marking a safe interpreter as trusted), according to
        /// the specified trust flags.
        /// </summary>
        /// <param name="name">
        /// A name to associate with the stream as its script location.
        /// </param>
        /// <param name="textReader">
        /// The text reader from which the script is read.
        /// </param>
        /// <param name="trustFlags">
        /// Flags that control how trust is applied (e.g. exclusivity, event
        /// handling, ignoring hidden commands, security levels, and scope frame
        /// use).
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateTrustedStream(
            string name,
            TextReader textReader,
            TrustFlags trustFlags,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            return EvaluateTrustedStream(
                name, textReader, 0, Count.Invalid,
                trustFlags, ref result, ref errorLine);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads and evaluates a portion of the script contained in
        /// the specified text reader in this interpreter with elevated trust
        /// (temporarily marking a safe interpreter as trusted), according to
        /// the specified trust flags; on failure, the error line is also
        /// recorded on the interpreter.
        /// </summary>
        /// <param name="name">
        /// A name to associate with the stream as its script location.
        /// </param>
        /// <param name="textReader">
        /// The text reader from which the script is read.
        /// </param>
        /// <param name="startIndex">
        /// The character index within the stream at which to begin reading.
        /// </param>
        /// <param name="characters">
        /// The number of characters to read, or an invalid count to read to the
        /// end of the stream.
        /// </param>
        /// <param name="trustFlags">
        /// Flags that control how trust is applied (e.g. exclusivity, event
        /// handling, ignoring hidden commands, security levels, and scope frame
        /// use).
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateTrustedStream(
            string name,
            TextReader textReader,
            int startIndex,
            int characters,
            TrustFlags trustFlags,
            ref Result result
            )
        {
            CheckDisposed();

            int errorLine = 0;

            ReturnCode code = EvaluateTrustedStream(
                name, textReader, startIndex, characters,
                trustFlags, ref result, ref errorLine);

            if (errorLine != 0)
                SetErrorLine(this, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads and evaluates a portion of the script contained in
        /// the specified text reader in this interpreter with elevated trust
        /// (temporarily marking a safe interpreter as trusted), according to
        /// the specified trust flags, by delegating to the static
        /// <see cref="Engine" /> once trust has been applied.
        /// </summary>
        /// <param name="name">
        /// A name to associate with the stream as its script location.
        /// </param>
        /// <param name="textReader">
        /// The text reader from which the script is read.
        /// </param>
        /// <param name="startIndex">
        /// The character index within the stream at which to begin reading.
        /// </param>
        /// <param name="characters">
        /// The number of characters to read, or an invalid count to read to the
        /// end of the stream.
        /// </param>
        /// <param name="trustFlags">
        /// Flags that control how trust is applied (e.g. exclusivity, event
        /// handling, ignoring hidden commands, security levels, and scope frame
        /// use).
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode EvaluateTrustedStream(
            string name,
            TextReader textReader,
            int startIndex,
            int characters,
            TrustFlags trustFlags,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            bool exclusive;
            bool withEvents;
            bool markTrusted;
            bool allowUnsafe;
            bool ignoreHidden;
            bool useSecurityLevels;
            bool pushScriptLocation;

#if ISOLATED_PLUGINS
            bool noIsolatedPlugins;
#endif

            bool withScopeFrame;

            ScriptOps.ExtractTrustFlags(
                trustFlags, out exclusive, out withEvents, out markTrusted,
                out allowUnsafe, out ignoreHidden, out useSecurityLevels,
                out pushScriptLocation
#if ISOLATED_PLUGINS
                , out noIsolatedPlugins
#endif
                , out withScopeFrame
            );

            bool locked = false;

            try
            {
                if (exclusive)
                    InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (!exclusive || locked)
                {
                    int savedEnabled = 0;

                    if (!withEvents)
                    {
                        if (!EventOps.SaveEnabledAndForceDisabled(
                                this, true, ref savedEnabled))
                        {
                            result = "failed to forcibly disable events";
                            return ReturnCode.Error;
                        }
                    }

                    try
                    {
                        if (markTrusted)
                        {
                            //
                            // NOTE: Use of this flag is currently limited to
                            //       "safe" child interpreters only.  Just
                            //       ignore the flag if called for an "unsafe"
                            //       interpreter.
                            //
                            if (InternalIsSafe())
                                InternalMarkTrusted();
                            else
                                markTrusted = false;
                        }

                        //
                        // NOTE: Use of this method is currently limited to
                        //       "safe" child interpreters only.  Issue an
                        //       error message if called for an "unsafe"
                        //       interpreter.
                        //
                        if (!markTrusted && !allowUnsafe && !InternalIsSafe())
                        {
                            result = "interpreter is already trusted";
                            return ReturnCode.Error;
                        }

                        try
                        {
                            //
                            // HACK: If necessary, add the "IgnoreHidden" engine
                            //       flag to the per-thread engine flags for this
                            //       interpreter so that the script specified by
                            //       the caller can run with full trust.  The
                            //       per-thread engine flags must be used in this
                            //       case; otherwise, other scripts being evaluated
                            //       on other threads in this interpreter would
                            //       also gain full trust.
                            //
                            bool ignoredHidden = false;

                            if (ignoreHidden &&
                                !EngineFlagOps.HasIgnoreHidden(this.ContextEngineFlags))
                            {
                                ignoredHidden = true;
                                this.ContextEngineFlags |= EngineFlags.IgnoreHidden;
                            }

                            try
                            {
                                EnterTrustedLevel();

                                try
                                {
                                    if (useSecurityLevels)
                                        EnterSecurityLevel();

                                    try
                                    {
#if ISOLATED_PLUGINS
                                        PluginFlags savedPluginFlags = PluginFlags.None;

                                        if (noIsolatedPlugins)
                                            BeginNoIsolatedPlugins(ref savedPluginFlags);

                                        try
                                        {
#endif
                                            if (withScopeFrame)
                                            {
                                                return Engine.EvaluateStreamWithScopeFrame(
                                                    this, name, textReader, startIndex,
                                                    characters, engineFlags, substitutionFlags,
                                                    engineEventFlags, expressionFlags,
                                                    ref result, ref errorLine);
                                            }
                                            else
                                            {
                                                return Engine.EvaluateStream(
                                                    this, name, textReader, startIndex,
                                                    characters, engineFlags, substitutionFlags,
                                                    engineEventFlags, expressionFlags,
                                                    ref result, ref errorLine);
                                            }
#if ISOLATED_PLUGINS
                                        }
                                        finally
                                        {
                                            if (noIsolatedPlugins)
                                                EndNoIsolatedPlugins(ref savedPluginFlags);
                                        }
#endif
                                    }
                                    finally
                                    {
                                        if (useSecurityLevels)
                                            ExitSecurityLevel();
                                    }
                                }
                                finally
                                {
                                    ExitTrustedLevel();
                                }
                            }
                            finally
                            {
                                if (ignoredHidden)
                                {
                                    this.ContextEngineFlags &= ~EngineFlags.IgnoreHidden;
                                    ignoredHidden = false;
                                }
                            }
                        }
                        finally
                        {
                            if (markTrusted)
                            {
                                InternalMarkSafe();
                                markTrusted = false;
                            }
                        }
                    }
                    finally
                    {
                        if (!withEvents)
                        {
                            /* IGNORED */
                            EventOps.RestoreEnabled(this, savedEnabled);

                            savedEnabled = 0;
                        }
                    }
                }
                else
                {
                    TraceOps.LockTrace(
                        "EvaluateTrustedStream",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    result = "could not lock interpreter";
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }

            return ReturnCode.Error;
        }

