        #region Private
        /// <summary>
        /// This method evaluates the specified script object in this
        /// interpreter, pushing it as the current script location, by
        /// delegating to the static <see cref="Engine" />.
        /// </summary>
        /// <param name="script">
        /// The script object to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        private ReturnCode PrivateEvaluateScript(
            IScript script,
            ref Result result,
            ref int errorLine
            )
        {
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            bool pushed = false;

            PushScriptLocation(script, ref pushed);

            try
            {
#endif
                return Engine.EvaluateScript(
                    this, script, ref result, ref errorLine);
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            }
            finally
            {
                PopScriptLocation(script, ref pushed);
            }
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the specified script text in this interpreter
        /// while the given script location is pushed as the current location.
        /// </summary>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="location">
        /// The script location to push while the script runs.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        internal ReturnCode EvaluateScript(
            string text,
            IScriptLocation location,
            ref Result result
            )
        {
            // CheckDisposed(); /* NON-PUBLIC, SANITY */

#if DEBUGGER && DEBUGGER_BREAKPOINTS
            bool pushed = false;

            PushScriptLocation(location, ref pushed);

            try
            {
#endif
                return EvaluateScript(text, ref result);
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            }
            finally
            {
                PopScriptLocation(location, ref pushed);
            }
#endif
        }

