        /// <summary>
        /// This method evaluates the script formed by concatenating the
        /// arguments starting at the specified index in this interpreter; on
        /// failure, the error line is also recorded on the interpreter.
        /// </summary>
        /// <param name="arguments">
        /// The list of arguments to concatenate into a script.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to include.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        internal ReturnCode EvaluateScript(
            ArgumentList arguments,
            int startIndex,
            ref Result result
            )
        {
            // CheckDisposed(); /* NON-PUBLIC, SANITY */

            int errorLine = 0;

            ReturnCode code = EvaluateScript(
                arguments, startIndex, ref result, ref errorLine);

            if (errorLine != 0)
                SetErrorLine(this, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the script formed by concatenating the
        /// arguments starting at the specified index in this interpreter.
        /// </summary>
        /// <param name="arguments">
        /// The list of arguments to concatenate into a script.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to include.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        internal ReturnCode EvaluateScript(
            ArgumentList arguments,
            int startIndex,
            ref Result result,
            ref int errorLine
            )
        {
            // CheckDisposed(); /* NON-PUBLIC, SANITY */

#if DEBUGGER && DEBUGGER_BREAKPOINTS
            IScriptLocation location = null;

            if (ScriptOps.GetLocation(
                    this, arguments, startIndex, ref location,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            bool pushed = false;

            PushScriptLocation(location, ref pushed);

            try
            {
#endif
                return EvaluateScript(
                    ListOps.Concat(arguments, startIndex), ref result,
                    ref errorLine);
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            }
            finally
            {
                PopScriptLocation(location, ref pushed);
            }
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the specified script text in this interpreter;
        /// on success, the script result replaces the text, and on failure the
        /// error is reported as a background error (unless background errors are
        /// suppressed).
        /// </summary>
        /// <param name="text">
        /// On input, the script text to evaluate; on output, upon success,
        /// receives the result of the script.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, the return code
        /// produced by the failing script.
        /// </returns>
        internal ReturnCode EvaluateScriptOrBackgroundError(
            ref string text /* in, out */
            )
        {
            // CheckDisposed();

            ReturnCode code;
            Result result = null;
            int errorLine = 0; /* NOT USED */

            code = Engine.EvaluateScript(
                this, text, engineFlags, substitutionFlags,
                engineEventFlags, expressionFlags, ref result,
                ref errorLine);

            if (code == ReturnCode.Ok)
            {
                text = result;
            }
            else if (!FlagOps.HasFlags(
                    engineEventFlags, EventFlags.NoBgError, true))
            {
                if (EventOps.HandleBackgroundError(
                        this, code, result) != ReturnCode.Ok)
                {
                    DebugOps.Complain(this, code, result);
                }
            }
            else
            {
                TraceOps.DebugTrace(String.Format(
                    "EvaluateScriptOrBackgroundError: interpreter = {0}, " +
                    "code = {1}, result = {2}, errorLine = {3}",
                    FormatOps.InterpreterNoThrow(this), code,
                    FormatOps.WrapOrNull(true, true, result),
                    errorLine), typeof(Interpreter).Name,
                    TracePriority.ScriptError2);
            }

            return code;
        }

