        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        internal ReturnCode EvaluatePackageScript(
            string text,
            ref Result result
            )
        {
            EnterPackageLevel();

            try
            {
                return Engine.EvaluateScript(
                    this, text, engineFlags | EngineFlags.EvaluateGlobal,
                    substitutionFlags, engineEventFlags, expressionFlags,
                    ref result);
            }
            finally
            {
                ExitPackageLevel();
            }
        }

