        /// <summary>
        /// This method evaluates the specified script text in this interpreter
        /// with reduced trust (temporarily marking an unsafe interpreter as
        /// safe); on failure, the error line is also recorded on the
        /// interpreter.
        /// </summary>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        internal ReturnCode EvaluateSafeScript(
            string text,
            ref Result result
            )
        {
            int errorLine = 0;

            ReturnCode code = EvaluateSafeScript(
                text, ref result, ref errorLine);

            if (errorLine != 0)
                SetErrorLine(this, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates the specified script text in this interpreter
        /// with reduced trust (temporarily marking an unsafe interpreter as
        /// safe), by delegating to the static <see cref="Engine" /> once the
        /// interpreter has been made safe.
        /// </summary>
        /// <param name="text">
        /// The script text to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        private ReturnCode EvaluateSafeScript(
            string text,
            ref Result result,
            ref int errorLine
            )
        {
            // CheckDisposed();

            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (InternalIsSafe())
                    {
                        result = "interpreter is already safe";
                        return ReturnCode.Error;
                    }

                    if (InternalMakeSafe(
                            MakeFlags.SafeEvaluate, true,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    try
                    {
                        return Engine.EvaluateScript(
                            this, text, engineFlags, substitutionFlags,
                            engineEventFlags, expressionFlags, ref result,
                            ref errorLine);
                    }
                    finally
                    {
                        ReturnCode safeCode;
                        Result safeError = null;

                        safeCode = InternalMakeSafe(
                            MakeFlags.SafeEvaluate, false,
                            ref safeError);

                        if (safeCode != ReturnCode.Ok)
                            DebugOps.Complain(this, safeCode, safeError);
                    }
                }
                else
                {
                    TraceOps.LockTrace(
                        "EvaluateSafeScript",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    result = "could not lock interpreter";
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads and evaluates the script contained in the
        /// specified file in this interpreter with reduced trust (temporarily
        /// marking an unsafe interpreter as safe); on failure, the error line
        /// is also recorded on the interpreter.
        /// </summary>
        /// <param name="encoding">
        /// The character encoding to use when reading the file; when null, a
        /// default encoding is used.
        /// </param>
        /// <param name="fileName">
        /// The name of the file containing the script to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        internal ReturnCode EvaluateSafeFile(
            Encoding encoding,
            string fileName,
            ref Result result
            )
        {
            int errorLine = 0;

            ReturnCode code = EvaluateSafeFile(
                encoding, fileName, ref result, ref errorLine);

            if (errorLine != 0)
                SetErrorLine(this, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method reads and evaluates the script contained in the
        /// specified file in this interpreter with reduced trust (temporarily
        /// marking an unsafe interpreter as safe), by delegating to the static
        /// <see cref="Engine" /> once the interpreter has been made safe.
        /// </summary>
        /// <param name="encoding">
        /// The character encoding to use when reading the file; when null, a
        /// default encoding is used.
        /// </param>
        /// <param name="fileName">
        /// The name of the file containing the script to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, receives the line number within the script where the
        /// error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        internal ReturnCode EvaluateSafeFile(
            Encoding encoding,
            string fileName,
            ref Result result,
            ref int errorLine
            )
        {
            // CheckDisposed();

            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    EngineFlags localEngineFlags;
                    SubstitutionFlags localSubstitutionFlags;
                    EventFlags localEventFlags;
                    ExpressionFlags localExpressionFlags;

                    localEngineFlags = engineFlags;
                    localSubstitutionFlags = substitutionFlags;
                    localEventFlags = engineEventFlags;
                    localExpressionFlags = expressionFlags;

                    string text = null;

                    if (Engine.ReadOrGetScriptFile(
                            this, encoding, ref fileName,
                            ref localEngineFlags, ref localSubstitutionFlags,
                            ref localEventFlags, ref localExpressionFlags,
                            ref text, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    bool pushed = false;

                    PushScriptLocation(fileName, true, ref pushed);

                    try
                    {
                        if (InternalIsSafe())
                        {
                            result = "interpreter is already safe";
                            return ReturnCode.Error;
                        }

                        if (InternalMakeSafe(
                                MakeFlags.SafeEvaluate, true,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        try
                        {
                            return Engine.EvaluateScript(
                                this, text, localEngineFlags,
                                localSubstitutionFlags, localEventFlags,
                                localExpressionFlags, ref result,
                                ref errorLine);
                        }
                        finally
                        {
                            ReturnCode safeCode;
                            Result safeError = null;

                            safeCode = InternalMakeSafe(
                                MakeFlags.SafeEvaluate, false,
                                ref safeError);

                            if (safeCode != ReturnCode.Ok)
                                DebugOps.Complain(this, safeCode, safeError);
                        }
                    }
                    finally
                    {
                        PopScriptLocation(true, ref pushed);
                    }
                }
                else
                {
                    TraceOps.LockTrace(
                        "EvaluateSafeFile",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    result = "could not lock interpreter";
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This internal script evaluation helper method was
        //          designed for use by the [test1] / [test2] commands
        //          in order to evaluate the list of matching per-test
        //          hooks.
        //
        /// <summary>
        /// This method evaluates each script in the specified list (each
        /// optionally suffixed with the given arguments) in this interpreter.
        /// It is intended for use by the test commands to run the matching
        /// per-test hooks.
        /// </summary>
        /// <param name="texts">
        /// The list of scripts to evaluate.
        /// </param>
        /// <param name="arguments">
        /// Optional arguments appended to each script; may be null.
        /// </param>
        /// <param name="keepResults">
        /// Non-zero to collect the result of each evaluated script.
        /// </param>
        /// <param name="stopOnError">
        /// Non-zero to stop at the first script that fails.
        /// </param>
        /// <param name="results">
        /// On input, an optional existing result list; on output, receives the
        /// collected results and/or error messages.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if all scripts succeeded; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode EvaluateScripts(
            StringList texts,       /* in */
            ArgumentList arguments, /* in */
            bool keepResults,       /* in */
            bool stopOnError,       /* in */
            ref ResultList results  /* in, out */
            ) /* THREAD-SAFE */
        {
            if (texts == null)
            {
                if (results == null)
                    results = new ResultList();

                results.Add("invalid script list");
                return ReturnCode.Error;
            }

            int errorCount = 0;
            string argumentsString = null;

            if (arguments != null)
                argumentsString = arguments.ToString();

            foreach (string text in texts)
            {
                if (text == null)
                    continue;

                string localText;

                if (argumentsString != null)
                {
                    StringBuilder builder = SBF.Create();

                    builder.Append(text);
                    builder.Append(Characters.Space);
                    builder.Append(argumentsString);

                    localText = SBC.GetStringAndRelease(ref builder);
                }
                else
                {
                    localText = text;
                }

                ReturnCode localCode;
                Result localResult = null;

                localCode = EvaluateScript(localText, ref localResult);

                if (keepResults && (localResult != null))
                {
                    localResult.ReturnCode = localCode;

                    if (results == null)
                        results = new ResultList();

                    results.Add(localResult);
                }

                if (localCode != ReturnCode.Ok)
                {
                    errorCount++;

                    if (stopOnError)
                        return localCode;
                }
            }

            return (errorCount == 0) ? ReturnCode.Ok : ReturnCode.Error;
        }
        #endregion
