        /// <summary>
        /// This method evaluates the expression contained in the specified
        /// argument, using this interpreter's current expression flags.
        /// </summary>
        /// <param name="argument">
        /// The argument containing the expression text to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the value of the evaluated expression; upon
        /// failure, receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode EvaluateExpression(
            Argument argument,
            ref Result result
            )
        {
            // CheckDisposed(); /* NON-PUBLIC, SANITY */

#if DEBUGGER && DEBUGGER_BREAKPOINTS
            bool pushed = false;

            PushScriptLocation(argument, ref pushed);

            try
            {
#endif
                return EvaluateExpression((string)argument, ref result);
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            }
            finally
            {
                PopScriptLocation(argument, ref pushed);
            }
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method concatenates the arguments beginning at the specified
        /// start index into a single expression and evaluates it, using this
        /// interpreter's current expression flags.
        /// </summary>
        /// <param name="arguments">
        /// The list of arguments to concatenate into the expression to
        /// evaluate.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to include in the expression.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the value of the evaluated expression; upon
        /// failure, receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode EvaluateExpression(
            ArgumentList arguments,
            int startIndex,
            ref Result result
            )
        {
            // CheckDisposed(); /* NON-PUBLIC, SANITY */

#if DEBUGGER && DEBUGGER_BREAKPOINTS
            IScriptLocation location = null;

            if (ScriptOps.GetLocation(
                    this, arguments, startIndex, ref location,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            bool pushed = false;

            PushScriptLocation(location, ref pushed);

            try
            {
#endif
                return EvaluateExpression(
                    ListOps.Concat(arguments, startIndex), ref result);
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            }
            finally
            {
                PopScriptLocation(location, ref pushed);
            }
#endif
        }

