        #region Command Execution
        /// <summary>
        /// This method resolves the command or other executable entity with
        /// the specified name and executes it with the specified arguments,
        /// delegating execution to the static <see cref="Engine" />.
        /// </summary>
        /// <param name="name">
        /// The name of the command to resolve and execute.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the command.  This parameter may be
        /// null.
        /// </param>
        /// <param name="arguments">
        /// The list of arguments to pass to the command.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the result of the script; upon failure,
        /// receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, another
        /// <see cref="ReturnCode" /> such as <see cref="ReturnCode.Error" />,
        /// <see cref="ReturnCode.Return" />, <see cref="ReturnCode.Break" />,
        /// or <see cref="ReturnCode.Continue" />.
        /// </returns>
        public ReturnCode Invoke(
            string name,
            IClientData clientData,
            ArgumentList arguments,
            ref Result result
            )
        {
            CheckDisposed();

            IExecute execute = null;

            if (InternalGetIExecuteViaResolvers(GetResolveEngineFlagsNoLock(true),
                    name, arguments, LookupFlags.Default, ref execute,
                    ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            //
            // WARNING: This now (indirectly) uses ContextEngineFlags.
            //
            return Engine.Execute(
                name, execute, this, clientData, arguments,
                EngineFlags, substitutionFlags, engineEventFlags,
                expressionFlags,
#if RESULT_LIMITS
                executeResultLimit,
#endif
                ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// Gets or sets the running count of operations performed by this
        /// interpreter.  This property uses interlocked access and does not
        /// acquire the interpreter lock.
        /// </summary>
        internal long OperationCountNoLock
        {
            get { return Interlocked.CompareExchange(ref operationCount, 0, 0); }
            set { Interlocked.Exchange(ref operationCount, value); }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the running count of commands executed by this
        /// interpreter.  This property uses interlocked access and does not
        /// acquire the interpreter lock.
        /// </summary>
        internal long CommandCountNoLock
        {
            get { return Interlocked.CompareExchange(ref commandCount, 0, 0); }
            set { Interlocked.Exchange(ref commandCount, value); }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the running count of unknown-command dispatches
        /// performed by this interpreter.  This property uses interlocked
        /// access and does not acquire the interpreter lock.
        /// </summary>
        private long UnknownCountNoLock
        {
            get { return Interlocked.CompareExchange(ref unknownCount, 0, 0); }
            set { Interlocked.Exchange(ref unknownCount, value); }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method increments the operation count, and optionally the
        /// command count, enforcing the configured operation and command
        /// limits.  If a limit would be exceeded, the affected count is rolled
        /// back and an error is reported.
        /// </summary>
        /// <param name="isCommand">
        /// Non-zero if the operation being counted is also a command, in which
        /// case the command count is incremented as well.
        /// </param>
        /// <param name="code">
        /// Upon a limit being exceeded, receives <see cref="ReturnCode.Error" />;
        /// otherwise, it is left unchanged.
        /// </param>
        /// <param name="error">
        /// Upon a limit being exceeded, receives an error message describing
        /// which limit was exceeded; otherwise, it is left unchanged.
        /// </param>
        internal void IncrementOperationAndCommandCount(
            bool isCommand,      /* in */
            ref ReturnCode code, /* in, out */
            ref Result error     /* in, out */
            )
        {
            long localOperationCount = Interlocked.Increment(
                ref operationCount);

            if ((operationLimit != Limits.Unlimited) &&
                (localOperationCount > operationLimit))
            {
                /* IGNORED */
                Interlocked.Decrement(ref operationCount);

                error = String.Format(
                    "operation limit exceeded: {0}", operationLimit);

                code = ReturnCode.Error;
                return;
            }

            if (isCommand)
            {
                long localCommandCount = Interlocked.Increment(
                    ref commandCount);

                if ((commandLimit != Limits.Unlimited) &&
                    (localCommandCount > commandLimit))
                {
                    /* IGNORED */
                    Interlocked.Decrement(ref commandCount);

                    error = String.Format(
                        "command limit exceeded: {0}", commandLimit);

                    code = ReturnCode.Error;
                    return;
                }
            }
        }

