        #region ICallbackQueueManager Members
#if CALLBACK_QUEUE
        /// <summary>
        /// This method determines whether the callback queue is available
        /// for use by this interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callback queue is not available.
        /// </param>
        /// <returns>
        /// True if the callback queue is available; otherwise, false.
        /// </returns>
        public bool HasCallbackQueue(
            ref Result error /* out */
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                return PrivateHasCallbackQueue(ref error);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes all pending callbacks from the callback
        /// queue.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callback queue could not be cleared.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback queue was
        /// cleared; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode ClearCallbackQueue(
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasCallbackQueue(ref error))
                {
                    callbackQueue.Clear();

                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified callback to the end of the
        /// callback queue, subject to the configured callback limit.
        /// </summary>
        /// <param name="callback">
        /// The callback to enqueue.  This must be a <see cref="CommandCallback" />
        /// instance.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callback could not be enqueued.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was
        /// enqueued; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode EnqueueCallback(
            ICallback callback,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                int queueCount = 0;

                if (PrivateHasCallbackQueue(ref queueCount, ref error))
                {
                    if ((callbackLimit <= 0) || (queueCount < callbackLimit))
                    {
                        CommandCallback commandCallback =
                            callback as CommandCallback;

                        if (commandCallback != null)
                        {
                            callbackQueue.Enqueue(commandCallback);

                            code = ReturnCode.Ok;
                        }
                        else
                        {
                            error = "invalid command callback";
                        }
                    }
                    else
                    {
                        error = "callback queue limit would be exceeded";
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes and returns the callback at the front of the
        /// callback queue.
        /// </summary>
        /// <param name="callback">
        /// Upon success, this is set to the callback removed from the front
        /// of the callback queue.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why a
        /// callback could not be dequeued.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if a callback was dequeued;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode DequeueCallback(
            ref ICallback callback,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                int queueCount = 0;

                if (PrivateHasCallbackQueue(ref queueCount, ref error))
                {
                    if (queueCount > 0)
                    {
                        callback = callbackQueue.Dequeue();

                        code = ReturnCode.Ok;
                    }
                    else
                    {
                        error = "callback queue is empty";
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method counts the callbacks currently pending in the
        /// callback queue.
        /// </summary>
        /// <param name="count">
        /// Upon success, this is set to the number of callbacks currently in
        /// the callback queue.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callbacks could not be counted.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the count was obtained;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode CountCallbacks(
            ref int count,
            ref Result error
            )
        {
            // CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                int queueCount = 0;

                if (PrivateHasCallbackQueue(ref queueCount, ref error))
                {
                    count = queueCount;
                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the callbacks currently pending in
        /// the callback queue, optionally filtered by a match pattern.
        /// </summary>
        /// <param name="pattern">
        /// The optional pattern used to filter the callbacks.  When null, all
        /// callbacks are included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="list">
        /// Upon success, this is set to the list of matching callbacks.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callbacks could not be listed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListCallbacks(
            string pattern,
            bool noCase,
            ref StringList list,
            ref Result error
            )
        {
            // CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasCallbackQueue(ref error))
                {
                    StringList inputList = new StringList(
                        callbackQueue.ToArray());

                    StringList outputList = new StringList();

                    code = GenericOps<string>.FilterList(
                        inputList, outputList, Index.Invalid, Index.Invalid,
                        ToStringFlags.None, pattern, noCase, ref error);

                    if (code == ReturnCode.Ok)
                        list = outputList;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the callback at the front of the callback
        /// queue and returns it as a <see cref="CommandCallback" />.
        /// </summary>
        /// <param name="callback">
        /// Upon success, this is set to the command callback removed from the
        /// front of the callback queue.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if a command callback was
        /// dequeued; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode DequeueCallback(
            ref CommandCallback callback
            )
        {
            ICallback localCallback = null;
            Result error = null;

            if (DequeueCallback(ref localCallback, ref error) == ReturnCode.Ok)
            {
                if (localCallback is CommandCallback)
                {
                    callback = (CommandCallback)localCallback;

                    return ReturnCode.Ok;
                }
                else
                {
                    error = "invalid command callback";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the callback queue is available,
        /// assuming the interpreter lock is already held.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callback queue is not available.
        /// </param>
        /// <returns>
        /// True if the callback queue is available; otherwise, false.
        /// </returns>
        private bool PrivateHasCallbackQueue(
            ref Result error
            )
        {
            int queueCount = 0; /* NOT USED */

            return PrivateHasCallbackQueue(ref queueCount, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the callback queue is available
        /// and, if so, reports its current size, assuming the interpreter
        /// lock is already held.
        /// </summary>
        /// <param name="queueCount">
        /// Upon success, this is set to the number of callbacks currently in
        /// the callback queue.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callback queue is not available.
        /// </param>
        /// <returns>
        /// True if the callback queue is available; otherwise, false.
        /// </returns>
        private bool PrivateHasCallbackQueue(
            ref int queueCount, /* out */
            ref Result error    /* out */
            )
        {
            if (callbackQueue != null)
            {
                queueCount = callbackQueue.Count;
                return true;
            }
            else
            {
                error = "callback queue not available";
                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes every callback from the callback queue and
        /// returns them as an array.  It is intended for use by the engine
        /// only.
        /// </summary>
        /// <param name="callbacks">
        /// On input, this must be null.  Upon success, this is set to an array
        /// containing all callbacks that were removed from the queue, or is
        /// left unchanged when the queue is empty.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callbacks could not be dequeued.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callbacks were
        /// dequeued; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode DequeueAllCallbacks( /* For Engine use only. */
            ref CommandCallback[] callbacks, /* in, out */
            ref Result error                 /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int queueCount = 0;

                if (!PrivateHasCallbackQueue(ref queueCount, ref error))
                    return ReturnCode.Error;

                if (callbacks != null)
                {
                    error = "cannot overwrite valid callback array";
                    return ReturnCode.Error;
                }

                if (queueCount > 0)
                {
                    callbacks = new CommandCallback[queueCount];
                    callbackQueue.CopyTo(callbacks, 0);
                    callbackQueue.Clear();
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enqueues the callbacks from the specified array,
        /// starting at the specified index, subject to the configured
        /// callback limit.  It is intended for use by the engine only.
        /// </summary>
        /// <param name="nextIndex">
        /// The index of the first callback within the array to enqueue.
        /// </param>
        /// <param name="callbacks">
        /// On input, the array of callbacks to enqueue.  Upon success, the
        /// enqueued elements are cleared and this is set to null.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// callbacks could not be enqueued.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callbacks were
        /// enqueued; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode EnqueueSomeCallbacks( /* For Engine use only. */
            int nextIndex,                   /* in */
            ref CommandCallback[] callbacks, /* in, out */
            ref Result error                 /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int queueCount = 0;

                if (!PrivateHasCallbackQueue(ref queueCount, ref error))
                    return ReturnCode.Error;

                if (callbacks == null)
                {
                    error = "invalid callback array";
                    return ReturnCode.Error;
                }

                int length = callbacks.Length;

                if ((nextIndex < 0) || (nextIndex >= length))
                {
                    error = "next callback index is out-of-bounds";
                    return ReturnCode.Error;
                }

                if ((callbackLimit > 0) &&
                    ((queueCount + (length - nextIndex)) > callbackLimit))
                {
                    error = "callback limit would be exceeded";
                    return ReturnCode.Error;
                }

                for (int index = nextIndex; index < length; index++)
                {
                    callbackQueue.Enqueue(callbacks[index]);
                    callbacks[index] = null;
                }

                Array.Resize(ref callbacks, 0);
                callbacks = null;

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For use by the [callback] command only.
        //
        /// <summary>
        /// This method executes all pending callbacks in the callback queue.
        /// It is intended for use by the [callback] command only.
        /// </summary>
        /// <param name="result">
        /// Upon success, this is set to the result of executing the callback
        /// queue; upon failure, this is set to an error message.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback queue was
        /// executed successfully; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ExecuteCallbackQueue(
            ref Result result
            )
        {
            //
            // WARNING: This now (indirectly) uses ContextEngineFlags.
            //
            return Engine.ExecuteCallbackQueue(
                this, EngineFlags, substitutionFlags, engineEventFlags,
                expressionFlags,
#if RESULT_LIMITS
                executeResultLimit,
#endif
                ref result);
        }
        #endregion
#endif
        #endregion

