        /// <summary>
        /// This method determines whether an IExecute (executable) entity
        /// with the specified name exists, as seen through the registered
        /// resolvers, and reports the kind of identifier that was resolved.
        /// </summary>
        /// <param name="name">
        /// The name of the IExecute (executable) entity to check for.
        /// </param>
        /// <param name="kind">
        /// Upon success, this is set to the kind of identifier that was
        /// resolved for the specified name.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// lookup could not be performed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if an IExecute (executable)
        /// entity with the specified name exists; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateDoesIExecuteExistViaResolvers(
            string name,             /* in */
            ref IdentifierKind kind, /* out */
            ref Result error         /* out */
            )
        {
            IExecute execute = null;

            if (InternalGetIExecuteViaResolvers(
                    GetResolveEngineFlagsNoLock(true), name,
                    null, LookupFlags.Exists, ref execute,
                    ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            IIdentifierBase identifierBase = execute as IIdentifierBase;

            if (identifierBase != null)
                kind = identifierBase.Kind;

            return ReturnCode.Ok;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether an object with the specified name
        /// exists and, if so, returns its wrapped value, optionally adjusting
        /// its reference count.
        /// </summary>
        /// <param name="name">
        /// The name of the object to look up.
        /// </param>
        /// <param name="addReference">
        /// Non-zero to add a reference to the object when it is found and not
        /// locked.
        /// </param>
        /// <param name="removeReference">
        /// Non-zero to remove a reference from the object when it is found and
        /// not locked.
        /// </param>
        /// <param name="value">
        /// Upon success, this is set to the value wrapped by the object.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if an object with the
        /// specified name exists; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalDoesObjectExist(
            string name,
            bool addReference,
            bool removeReference,
            ref object value
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                long token = 0; /* NOT USED */
                IObject @object = null;
                Result error = null;

                if (PrivateGetObject(
                        name, LookupFlags.Default, ref token,
                        ref @object, ref error) == ReturnCode.Ok)
                {
                    //
                    // BUGFIX: Do not adjust reference counts for locked objects.
                    //
                    if (!FlagOps.HasFlags(
                            @object.ObjectFlags, ObjectFlags.Locked, true))
                    {
                        if (addReference)
                            @object.AddReference();

                        if (removeReference)
                            @object.RemoveReference();
                    }

                    value = @object.Value;
                    return ReturnCode.Ok;
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether an object with the specified name
        /// exists in this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the object to check for.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// object could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if an object with the
        /// specified name exists; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalDoesObjectExist(
            string name,     /* in */
            ref Result error /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return PrivateDoesObjectExist(name, ref error);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether any object with one of the
        /// specified names exists in this interpreter.
        /// </summary>
        /// <param name="names">
        /// The names of the objects to check for.  This parameter may be
        /// null.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if any object with one of
        /// the specified names exists; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateDoesAnyObjectExist(
            params string[] names
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (names != null)
                {
                    foreach (string name in names)
                    {
                        if (PrivateDoesObjectExist(
                                name) == ReturnCode.Ok)
                        {
                            return ReturnCode.Ok;
                        }
                    }
                }

                return ReturnCode.Error;
            }
        }
