        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Entity Management
        #region Any IExecute
        /// <summary>
        /// This method determines whether the specified name is available for use as
        /// the new name of any executable entity, i.e. that no executable, procedure,
        /// or command currently uses it and, when namespaces are enabled, that its
        /// parent namespace can be resolved.
        /// </summary>
        /// <param name="newName">
        /// The candidate name to validate.
        /// </param>
        /// <param name="noNamespaces">
        /// When true, namespace resolution of the candidate name is skipped.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the name is
        /// not available.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the name is available; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode IsValidAnyIExecuteName(
            string newName,
            bool noNamespaces,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                IExecute execute = null;

                if (GetIExecute(
                        newName, LookupFlags.Exists, ref execute) == ReturnCode.Ok)
                {
                    error = String.Format(
                        "can't rename to {0}: execute already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                IProcedure procedure = null;

                if (GetProcedure(
                        newName, LookupFlags.Exists, ref procedure) == ReturnCode.Ok)
                {
                    error = String.Format(
                        "can't rename to {0}: procedure already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                ICommand command = null;

                if (GetCommand(
                        newName, LookupFlags.Exists, ref command) == ReturnCode.Ok)
                {
                    error = String.Format(
                        "can't rename to {0}: command already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();
                Result localError = null;

                if (useNamespaces && (NamespaceOps.LookupParent(
                        this, newName, false, true, false, ref localError) == null))
                {
                    error = String.Format(
                        "can't rename to {0}: {1}",
                        FormatOps.WrapOrNull(newName),
                        localError);

                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified name is available for use as
        /// the new name of any hidden executable entity, i.e. that no hidden
        /// executable, procedure, or command currently uses it and, when namespaces
        /// are enabled, that its parent namespace can be resolved.
        /// </summary>
        /// <param name="newName">
        /// The candidate name to validate.
        /// </param>
        /// <param name="noNamespaces">
        /// When true, namespace resolution of the candidate name is skipped.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the name is
        /// not available.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the name is available; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode IsValidAnyHiddenIExecuteName(
            string newName,
            bool noNamespaces,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                IExecute execute = null;

                if (GetHiddenIExecute(
                        newName, LookupFlags.Exists, ref execute) == ReturnCode.Ok)
                {
                    error = String.Format(
                        "can't rename to {0}: hidden execute already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                IProcedure procedure = null;

                if (GetHiddenProcedure(
                        newName, LookupFlags.Exists, ref procedure) == ReturnCode.Ok)
                {
                    error = String.Format(
                        "can't rename to {0}: hidden procedure already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                ICommand command = null;

                if (GetHiddenCommand(
                        newName, LookupFlags.Exists, ref command) == ReturnCode.Ok)
                {
                    error = String.Format(
                        "can't rename to {0}: hidden command already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();
                Result localError = null;

                if (useNamespaces && (NamespaceOps.LookupParent(
                        this, newName, false, true, false, ref localError) == null))
                {
                    error = String.Format(
                        "can't rename to {0}: {1}",
                        FormatOps.WrapOrNull(newName),
                        localError);

                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames (or deletes) an executable entity, normalizing the old
        /// and new names with respect to namespaces before performing the operation.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the entity to rename.
        /// </param>
        /// <param name="newName">
        /// The new name to assign to the entity.
        /// </param>
        /// <param name="varName">
        /// The name of a variable to receive the new name, or null if none.
        /// </param>
        /// <param name="kind">
        /// The kind of identifier being renamed, used to select which entity type(s)
        /// to consider.
        /// </param>
        /// <param name="noNamespaces">
        /// When true, namespace processing of the names is skipped.
        /// </param>
        /// <param name="delete">
        /// When true, the operation represents a deletion rather than a true rename.
        /// </param>
        /// <param name="all">
        /// When true, every matching entity kind is processed; otherwise, only the
        /// first match is processed.
        /// </param>
        /// <param name="hidden">
        /// When true, hidden entities are also considered.
        /// </param>
        /// <param name="hiddenOnly">
        /// When true, only hidden entities are considered.
        /// </param>
        /// <param name="result">
        /// Upon success, this may be set to a result value; upon failure, this is set
        /// to an error message.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the operation succeeds; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RenameAnyIExecute(
            string oldName,
            string newName,
            string varName,
            IdentifierKind kind,
            bool noNamespaces,
            bool delete,
            bool all,
            bool hidden,
            bool hiddenOnly,
            ref Result result
            )
        {
            // CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();

                ///////////////////////////////////////////////////////////////////////////////////////

                if (!useNamespaces || (NamespaceOps.GetIExecuteName(
                        this, hidden, hiddenOnly, ref oldName,
                        ref result) == ReturnCode.Ok))
                {
                    oldName = ScriptOps.MakeCommandName(oldName);
                }
                else
                {
                    return ReturnCode.Error;
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (!useNamespaces || (NamespaceOps.NormalizeName(
                        this, ref newName, ref result) == ReturnCode.Ok))
                {
                    newName = ScriptOps.MakeCommandName(newName);
                }
                else
                {
                    return ReturnCode.Error;
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                return PrivateRenameAnyIExecute(
                    oldName, newName, varName, kind, noNamespaces, delete,
                    all, hidden, hiddenOnly, ref result);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to rename (or delete) every executable entity kind --
        /// executable, procedure, and command, optionally including their hidden
        /// counterparts -- that currently bears the old name.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the entities to rename.
        /// </param>
        /// <param name="newName">
        /// The new name to assign to the entities.
        /// </param>
        /// <param name="kind">
        /// The kind of identifier being renamed.
        /// </param>
        /// <param name="noNamespaces">
        /// When true, namespace processing of the names is skipped.
        /// </param>
        /// <param name="delete">
        /// When true, the operation represents a deletion rather than a true rename.
        /// </param>
        /// <param name="all">
        /// When true, every matching entity kind is processed; otherwise, processing
        /// stops after the first match.
        /// </param>
        /// <param name="hidden">
        /// When true, hidden entities are also considered.
        /// </param>
        /// <param name="hiddenOnly">
        /// When true, only hidden entities are considered.
        /// </param>
        /// <param name="result">
        /// Upon success, this may be set to a result value; upon failure, this is set
        /// to an error message.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if at least one matching entity was
        /// renamed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameAllIExecute(
            string oldName,
            string newName,
            IdentifierKind kind,
            bool noNamespaces,
            bool delete,
            bool all,
            bool hidden,
            bool hiddenOnly,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int renameCount = 0;

                if (hidden)
                {
                    if (PrivateDoesHiddenIExecuteExist(oldName) == ReturnCode.Ok)
                    {
                        if (PrivateRenameHiddenIExecute(
                                oldName, newName, noNamespaces,
                                delete, ref result) == ReturnCode.Ok)
                        {
                            renameCount++;

                            if (!all)
                                return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }

                    if (PrivateDoesHiddenProcedureExist(oldName) == ReturnCode.Ok)
                    {
                        if (PrivateRenameHiddenProcedure(
                                oldName, newName, noNamespaces,
                                delete, ref result) == ReturnCode.Ok)
                        {
                            renameCount++;

                            if (!all)
                                return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }

                    if (PrivateDoesHiddenCommandExist(oldName) == ReturnCode.Ok)
                    {
                        if (PrivateRenameHiddenCommand(
                                oldName, newName, noNamespaces,
                                delete, ref result) == ReturnCode.Ok)
                        {
                            renameCount++;

                            if (!all)
                                return ReturnCode.Ok;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }

                    if (hiddenOnly)
                    {
                        if (renameCount > 0)
                        {
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            result = String.Format(
                                "can't rename {0}: it is not hidden",
                                FormatOps.WrapOrNull(oldName));

                            return ReturnCode.Error;
                        }
                    }
                }

                if (PrivateDoesIExecuteExist(oldName) == ReturnCode.Ok)
                {
                    if (PrivateRenameIExecute(
                            oldName, newName, noNamespaces,
                            delete, ref result) == ReturnCode.Ok)
                    {
                        renameCount++;

                        if (!all)
                            return ReturnCode.Ok;
                    }
                    else
                    {
                        return ReturnCode.Error;
                    }
                }

                if (PrivateDoesProcedureExist(oldName) == ReturnCode.Ok)
                {
                    if (PrivateRenameProcedure(
                            oldName, newName, noNamespaces,
                            delete, ref result) == ReturnCode.Ok)
                    {
                        renameCount++;

                        if (!all)
                            return ReturnCode.Ok;
                    }
                    else
                    {
                        return ReturnCode.Error;
                    }
                }

                if (PrivateDoesCommandExist(oldName) == ReturnCode.Ok)
                {
                    if (PrivateRenameCommand(
                            oldName, newName, noNamespaces,
                            delete, ref result) == ReturnCode.Ok)
                    {
                        renameCount++;

                        if (!all)
                            return ReturnCode.Ok;
                    }
                    else
                    {
                        return ReturnCode.Error;
                    }
                }

                if (renameCount > 0)
                {
                    return ReturnCode.Ok;
                }
                else
                {
                    result = String.Format(
                        "can't rename {0}: unknown identifier kind",
                        FormatOps.WrapOrNull(oldName));

                    return ReturnCode.Error;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames (or deletes) the executable entity of the specified
        /// kind and, optionally, stores the new name into a variable.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the entity to rename.
        /// </param>
        /// <param name="newName">
        /// The new name to assign to the entity.
        /// </param>
        /// <param name="varName">
        /// The name of a variable to receive the new name, or null if none.
        /// </param>
        /// <param name="kind">
        /// The kind of identifier being renamed, used to select which entity type to
        /// process.
        /// </param>
        /// <param name="noNamespaces">
        /// When true, namespace processing of the names is skipped.
        /// </param>
        /// <param name="delete">
        /// When true, the operation represents a deletion rather than a true rename.
        /// </param>
        /// <param name="all">
        /// When true, every matching entity kind is processed; otherwise, processing
        /// stops after the first match.
        /// </param>
        /// <param name="hidden">
        /// When true, hidden entities are also considered.
        /// </param>
        /// <param name="hiddenOnly">
        /// When true, only hidden entities are considered.
        /// </param>
        /// <param name="result">
        /// Upon success, this may be set to a result value; upon failure, this is set
        /// to an error message.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the operation succeeds; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameAnyIExecute(
            string oldName,
            string newName,
            string varName,
            IdentifierKind kind,
            bool noNamespaces,
            bool delete,
            bool all,
            bool hidden,
            bool hiddenOnly,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                switch (kind)
                {
                    case IdentifierKind.None:
                        {
                            if (PrivateRenameAllIExecute(
                                    oldName, newName, kind, noNamespaces,
                                    delete, all, hidden, hiddenOnly,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                            break;
                        }
                    case IdentifierKind.Command:
                        {
                            if (PrivateRenameCommand(
                                    oldName, newName, noNamespaces,
                                    delete, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                            break;
                        }
                    case IdentifierKind.HiddenCommand:
                        {
                            if (PrivateRenameHiddenCommand(
                                    oldName, newName, noNamespaces,
                                    delete, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                            break;
                        }
                    case IdentifierKind.Procedure:
                        {
                            if (PrivateRenameProcedure(
                                    oldName, newName, noNamespaces,
                                    delete, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                            break;
                        }
                    case IdentifierKind.HiddenProcedure:
                        {
                            if (PrivateRenameHiddenProcedure(
                                    oldName, newName, noNamespaces,
                                    delete, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                            break;
                        }
                    case IdentifierKind.IExecute:
                        {
                            if (PrivateRenameIExecute(
                                    oldName, newName, noNamespaces,
                                    delete, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                            break;
                        }
                    case IdentifierKind.HiddenIExecute:
                        {
                            if (PrivateRenameHiddenIExecute(
                                    oldName, newName, noNamespaces,
                                    delete, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                            break;
                        }
                    default:
                        {
                            result = "identifier kind not supported";
                            return ReturnCode.Error;
                        }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (varName != null)
                {
                    if (SetVariableValue(
                            VariableFlags.None, varName, newName,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                return ReturnCode.Ok;
            }
        }

