                            else
                            {
                                return ReturnCode.Error;
                            }
                        }
                    case IdentifierKind.IExecute:
                        {
                            if (InternalRemoveIExecute(
                                    name, clientData, ref token,
                                    ref result) == ReturnCode.Ok)
                            {
                                return ReturnCode.Ok;
                            }
                            else
                            {
                                return ReturnCode.Error;
                            }
                        }
                    case IdentifierKind.HiddenIExecute:
                        {
                            if (InternalRemoveHiddenIExecute(
                                    name, clientData, ref token,
                                    ref result) == ReturnCode.Ok)
                            {
                                return ReturnCode.Ok;
                            }
                            else
                            {
                                return ReturnCode.Error;
                            }
                        }
                    default:
                        {
                            result = "identifier kind not supported";
                            return ReturnCode.Error;
                        }
                }
            }
        }
#endif
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IIdentifier
        /// <summary>
        /// This method looks up an identifier of the specified kind by name,
        /// dispatching to the appropriate entity-specific lookup routine.
        /// </summary>
        /// <param name="kind">
        /// The kind of identifier to look up.
        /// </param>
        /// <param name="name">
        /// The name of the identifier to look up.
        /// </param>
        /// <param name="arguments">
        /// The arguments to use when resolving an executable identifier, if
        /// applicable.  This parameter may be null.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="identifier">
        /// Upon success, this is set to the identifier that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// identifier could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the identifier was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetIdentifier(
            IdentifierKind kind,
            string name,
            ArgumentList arguments,
            LookupFlags lookupFlags,
            ref IIdentifier identifier,
            ref Result error
            )
        {
            CheckDisposed();

            switch (kind)
            {
                case IdentifierKind.Interpreter:
                    {
                        Interpreter interpreter = null;

                        if (GetChildInterpreter(
                                name, lookupFlags, ref interpreter,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = interpreter;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Policy:
                    {
                        IPolicy policy = null;

                        if (GetPolicy(
                                name, lookupFlags, ref policy,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = policy;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Trace:
                    {
                        ITrace trace = null;

                        if (GetTrace(
                                name, lookupFlags, ref trace,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = trace;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.AnyIExecute: /* NOTE: IExecute may or may not derive from IIdentifier. */
                    {
                        IExecute execute = null;

                        if (InternalGetIExecuteViaResolvers(
                                GetResolveEngineFlagsNoLock(true), name,
                                arguments, lookupFlags, ref execute,
                                ref error) == ReturnCode.Ok)
                        {
                            if (execute is IIdentifier)
                            {
                                identifier = (IIdentifier)execute;
                                return ReturnCode.Ok;
                            }
                            else
                            {
                                error = "invalid identifier";
                            }
                        }
                        break;
                    }
                case IdentifierKind.Command:
                    {
                        ICommand command = null;

                        if (GetCommand(
                                name, lookupFlags, ref command,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = command;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.HiddenCommand:
                    {
                        ICommand command = null;

                        if (GetHiddenCommand(
                                name, lookupFlags, ref command,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = command;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Ensemble: /* NOTE: ICommand may or may not derive from _Commands.Ensemble. */
                    {
                        ICommand command = null;

                        if (GetEnsemble(
                                name, lookupFlags, ref command,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = command;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Procedure:
                    {
                        IProcedure procedure = null;

                        if (GetProcedure(
                                name, lookupFlags, ref procedure,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = procedure;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.HiddenProcedure:
                    {
                        IProcedure procedure = null;

                        if (GetHiddenProcedure(
                                name, lookupFlags, ref procedure,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = procedure;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.IExecute: /* NOTE: IExecute may or may not derive from IIdentifier. */
                    {
                        IExecute execute = null;

                        if (GetIExecute(
                                name, lookupFlags, ref execute,
                                ref error) == ReturnCode.Ok)
                        {
                            if (execute is IIdentifier)
                            {
                                identifier = (IIdentifier)execute;
                                return ReturnCode.Ok;
                            }
                            else
                            {
                                error = "invalid identifier";
                            }
                        }
                        break;
                    }
                case IdentifierKind.HiddenIExecute:
                    {
                        IExecute execute = null;

                        if (GetHiddenIExecute(
                                name, lookupFlags, ref execute,
                                ref error) == ReturnCode.Ok)
                        {
                            if (execute is IIdentifier)
                            {
                                identifier = (IIdentifier)execute;
                                return ReturnCode.Ok;
                            }
                            else
                            {
                                error = "invalid identifier";
                            }
                        }
                        break;
                    }
                case IdentifierKind.Lambda:
                    {
                        #region Dead Code
#if DEAD_CODE
                        ILambda lambda = null;

                        if (GetLambda(
                                name, lookupFlags, ref lambda,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = lambda;
                            return ReturnCode.Ok;
                        }
#else
                        error = "not implemented";
#endif
                        #endregion
                        break;
                    }
                case IdentifierKind.Operator:
                    {
                        IOperator @operator = null;

                        if (GetOperator(
                                name, lookupFlags, ref @operator,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = @operator;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Function:
                    {
                        IFunction function = null;

                        if (GetFunction(
                                name, lookupFlags, ref function,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = function;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Variable:
                    {
                        VariableFlags flags = VariableFlags.NoElement;

                        if (FlagOps.HasFlags(
                                lookupFlags, LookupFlags.CreateMissing,
                                true))
                        {
                            flags |= VariableFlags.CreateMissing;
                        }

                        IVariable variable = null;

                        if (GetVariableViaResolversWithSplit(
                                name, ref flags, ref variable,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = variable;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.CallFrame:
                    {
                        FrameResult frameResult;
                        ICallFrame frame = null;

                        frameResult = GetCallFrame(
                            name, ref frame, ref error);

                        if (frameResult != FrameResult.Invalid)
                        {
                            identifier = frame;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Scope:
                    {
                        ICallFrame frame = null;

                        if (GetScope(
                                name, lookupFlags, ref frame,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = frame;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.DbConnection:
                    {
#if DATA
                        IDbConnection connection = null;

                        if (GetDbConnection(
                                name, lookupFlags, ref connection,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = new FakeIdentifier(
                                kind, name, new ClientData(
                                connection, true));

                            return ReturnCode.Ok;
                        }
#else
                        error = "not implemented";
#endif
                        break;
                    }
                case IdentifierKind.DbTransaction:
                    {
#if DATA
                        IDbTransaction transaction = null;

                        if (GetDbTransaction(
                                name, lookupFlags, ref transaction,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = new FakeIdentifier(
                                kind, name, new ClientData(
                                transaction, true));

                            return ReturnCode.Ok;
                        }
#else
                        error = "not implemented";
#endif
                        break;
                    }
                case IdentifierKind.Package:
                    {
                        IPackage package = null;

                        if (GetPackage(
                                name, lookupFlags, ref package,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = package;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Plugin:
                    {
                        IPlugin plugin = null;

                        if (GetPlugin(
                                name, lookupFlags, ref plugin,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = plugin;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Object:
                    {
                        IObject @object = null;

                        if (GetObject(
                                name, lookupFlags, ref @object,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = @object;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.NativeModule:
                    {
#if EMIT && NATIVE && LIBRARY
                        IModule module = null;

                        if (GetModule(
                                name, lookupFlags, ref module,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = module;
                            return ReturnCode.Ok;
                        }
#else
                        error = "not implemented";
#endif
                        break;
                    }
                case IdentifierKind.NativeDelegate:
                    {
#if EMIT && NATIVE && LIBRARY
                        IDelegate @delegate = null;

                        if (GetDelegate(
                                name, lookupFlags, ref @delegate,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = @delegate;
                            return ReturnCode.Ok;
                        }
#else
                        error = "not implemented";
#endif
                        break;
                    }
                case IdentifierKind.Host:
                    {
                        if (String.IsNullOrEmpty(name))
                        {
                            identifier = this.InternalHost;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = "unsupported host type";
                        }
                        break;
                    }
                case IdentifierKind.Alias:
                    {
                        IAlias alias = null;

                        if (GetAlias(
                                name, lookupFlags, ref alias,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = alias;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Callback:
                    {
                        ICallback callback = null;

                        if (GetCallback(
                                name, lookupFlags, ref callback,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = callback;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.Resolve:
                    {
                        object enumValue = EnumOps.TryParse(
                            typeof(Priority), name, true, true,
                            ref error);

                        if (enumValue is Priority)
                        {
                            IResolve resolve = null;

                            if (GetResolver(
                                    (Priority)enumValue, ref resolve,
                                    ref error) == ReturnCode.Ok)
                            {
                                identifier = resolve;
                                return ReturnCode.Ok;
                            }
                        }
                        break;
                    }
                case IdentifierKind.Namespace:
                    {
                        INamespace @namespace = NamespaceOps.Lookup(
                            this, name, false, false, ref error);

                        if (@namespace != null)
                        {
                            identifier = @namespace;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.SubCommand:
                    {
                        StringList list = null;

                        if (ParserOps<string>.SplitList(
                                this, name, 0, Length.Invalid, true,
                                ref list, ref error) == ReturnCode.Ok)
                        {
                            if (list.Count >= 2)
                            {
                                string commandName = list[0];
                                ICommand command = null;

                                if (GetEnsemble(
                                        commandName, lookupFlags, ref command,
                                        ref error) == ReturnCode.Ok)
                                {
                                    string subCommandName = list[1];
                                    ISubCommand subCommand = null;

                                    if (ScriptOps.SubCommandFromEnsemble(this,
                                            command, null, null, true, false,
                                            ref subCommandName, ref subCommand,
                                            ref error) == ReturnCode.Ok)
                                    {
                                        identifier = subCommand;
                                        return ReturnCode.Ok;
                                    }
                                }
                            }
                            else
                            {
                                error = "need name of command and sub-command";
                            }
                        }
                        break;
                    }
                case IdentifierKind.InteractiveLoopData:
                    {
#if SHELL
                        if (String.IsNullOrEmpty(name))
                        {
                            identifier = this.InteractiveLoopData;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = "unsupported interactive loop data type";
                        }
#else
                        error = "not implemented";
#endif
                        break;
                    }
                case IdentifierKind.ShellCallbackData:
                    {
#if SHELL
                        if (String.IsNullOrEmpty(name))
                        {
                            identifier = this.ShellCallbackData;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = "unsupported shell callback data type";
                        }
#else
                        error = "not implemented";
#endif
                        break;
                    }
                case IdentifierKind.UpdateData:
                    {
#if SHELL
                        if (String.IsNullOrEmpty(name))
                        {
                            identifier = this.UpdateData;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = "unsupported update data type";
                        }
#else
                        error = "not implemented";
#endif
                        break;
                    }
                case IdentifierKind.Certificate:
                    {
                        IPlugin plugin = null;

                        if (GetPlugin(
                                name, lookupFlags, ref plugin,
                                ref error) == ReturnCode.Ok)
                        {
                            if (plugin != null)
                            {
                                IIdentifier localIdentifier =
                                    plugin.GetCertificate(
                                        this, null, ref error);

                                if (localIdentifier != null)
                                {
                                    identifier = localIdentifier;
                                    return ReturnCode.Ok;
                                }
                            }
                            else
                            {
                                error = "invalid plugin";
                            }
                        }
                        break;
                    }
                case IdentifierKind.KeyPair:
                    {
                        IPlugin plugin = null;

                        if (GetPlugin(
                                name, lookupFlags, ref plugin,
                                ref error) == ReturnCode.Ok)
                        {
                            if (plugin != null)
                            {
                                IIdentifier localIdentifier =
                                    plugin.GetKeyPair(
                                        this, null, ref error);

                                if (localIdentifier != null)
                                {
                                    identifier = localIdentifier;
                                    return ReturnCode.Ok;
                                }
                            }
                            else
                            {
                                error = "invalid plugin";
                            }
                        }
                        break;
                    }
                case IdentifierKind.KeyRing:
                    {
                        IPlugin plugin = null;

                        if (GetPlugin(
                                name, lookupFlags, ref plugin,
                                ref error) == ReturnCode.Ok)
                        {
                            if (plugin != null)
                            {
                                IIdentifier localIdentifier =
                                    plugin.GetKeyRing(
                                        this, null, ref error);

                                if (localIdentifier != null)
                                {
                                    identifier = localIdentifier;
                                    return ReturnCode.Ok;
                                }
                            }
                            else
                            {
                                error = "invalid plugin";
                            }
                        }
                        break;
                    }
                case IdentifierKind.Channel:
                    {
                        IChannel channel = InternalGetChannel(
                            name, ref error);

                        if (channel != null)
                        {
                            identifier = channel;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                case IdentifierKind.None:
                case IdentifierKind.PolicyData:
                case IdentifierKind.TraceData:
                case IdentifierKind.CommandData:
                case IdentifierKind.SubCommandData:
                case IdentifierKind.ProcedureData:
                case IdentifierKind.LambdaData:
                case IdentifierKind.OperatorData:
                case IdentifierKind.FunctionData:
                case IdentifierKind.EnsembleData:
                case IdentifierKind.PackageData:
                case IdentifierKind.PluginData:
                case IdentifierKind.ObjectData:
                case IdentifierKind.ObjectTypeData:
                case IdentifierKind.ObjectType:
                case IdentifierKind.Option:
                case IdentifierKind.Module:
                case IdentifierKind.HostData:
                case IdentifierKind.AliasData:
                case IdentifierKind.DelegateData:
                case IdentifierKind.Delegate:
                case IdentifierKind.SubDelegate:
                case IdentifierKind.Automatic:
                case IdentifierKind.ResolveData:
                case IdentifierKind.ClockData:
                case IdentifierKind.Clock:
                case IdentifierKind.Script:
                case IdentifierKind.ScriptBuilder:
                case IdentifierKind.NamespaceData:
                case IdentifierKind.InteractiveLoop:
                case IdentifierKind.ShellCallback:
                case IdentifierKind.Update:
                case IdentifierKind.Context:
                case IdentifierKind.ContextData:
                case IdentifierKind.Snippet:
                case IdentifierKind.SnippetData:
                case IdentifierKind.Uri:
                case IdentifierKind.Type:
                case IdentifierKind.Hash:
                case IdentifierKind.TrustedPath:
                case IdentifierKind.TrustedUri:
                case IdentifierKind.TrustedType:
                case IdentifierKind.TrustedHash:
                    {
                        error = "identifier kind not supported";
                        break;
                    }
                case IdentifierKind.Path:
                    {
                        PathClientData path = null;

                        if (GetPath(
                                name, lookupFlags, ref path,
                                ref error) == ReturnCode.Ok)
                        {
                            identifier = path;
                            return ReturnCode.Ok;
                        }
                        break;
                    }
                default:
                    {
                        error = "unknown identifier kind";
                        break;
                    }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a rule for every identifier of the specified kind and
        /// adds those rules to a rule set.
        /// </summary>
        /// <param name="kind">
        /// The kind of identifiers to gather.
        /// </param>
        /// <param name="ruleType">
        /// The type of rule to create for each identifier.
        /// </param>
        /// <param name="mode">
        /// The matching mode to associate with each created rule.
        /// </param>
        /// <param name="stopOnError">
        /// When true, adding rules to an existing rule set stops at the first error.
        /// </param>
        /// <param name="ruleSet">
        /// If non-null on input, the created rules are added to this rule set;
        /// otherwise, this is set to a newly created rule set.
        /// </param>
        /// <param name="errors">
        /// If any errors occur, they are added to this list, which is created if
        /// necessary.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the identifiers were gathered
        /// successfully; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GatherIdentifiers(
            IdentifierKind kind,  /* in */
            RuleType ruleType,    /* in */
            MatchMode mode,       /* in */
            bool stopOnError,     /* in */
            ref IRuleSet ruleSet, /* in, out */
            ref ResultList errors /* in, out */
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool success = false;
                IRuleSet localRuleSet = null;

                try
                {
                    Result error = null; /* REUSED */

                    localRuleSet = RuleSet.Create(ref error);

                    if (localRuleSet == null)
                    {
                        if (error != null)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(error);
                        }

                        return ReturnCode.Error;
                    }

                    IEnumerable<string> names = null;

                    error = null;

                    if (GetIdentifierNames(
                            kind, ref names,
                            ref error) != ReturnCode.Ok)
                    {
                        if (error != null)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(error);
                        }

                        return ReturnCode.Error;
                    }

                    foreach (string name in names)
                    {
                        if (name == null)
                            continue;

                        error = null;

                        IRule rule = localRuleSet.BuildAndAddRule(
                            ruleType, kind, mode, name, ref error);

                        if (rule == null)
                        {
                            if (error != null)
                            {
                                if (errors == null)
                                    errors = new ResultList();

                                errors.Add(error);
                            }

                            return ReturnCode.Error;
                        }
                    }

                    if (ruleSet != null)
                    {
                        IEnumerable<IRule> rules = localRuleSet.CopyRules(
                            ref error);

                        if (rules == null)
                            return ReturnCode.Error;

                        localRuleSet.ClearRules();

                        int count = 0; /* NOT USED */

                        if (!ruleSet.AddRules(
                                rules, stopOnError, ref count, ref error))
                        {
                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        ruleSet = localRuleSet;
                        success = true;
                    }

                    return ReturnCode.Ok;
                }
                finally
                {
                    //
                    // HACK: The local variable name "success"
                    //       here is a bit of a misnomer.  It
                    //       should be named something that
                    //       indicates the local rule set has
                    //       been transferred to the caller.
                    //
                    if (!success && (localRuleSet != null))
                    {
                        /* IGNORED */
                        ObjectOps.TryDisposeOrTrace<IRuleSet>(
                            ref localRuleSet);

                        localRuleSet = null;
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method applies a rule set to every identifier of the specified kind,
        /// counting those that fail verification.
        /// </summary>
        /// <param name="kind">
        /// The kind of identifiers to verify.
        /// </param>
        /// <param name="mode">
        /// The matching mode to use when applying the rules.
        /// </param>
        /// <param name="ruleSet">
        /// The rule set to apply to each identifier.
        /// </param>
        /// <param name="unverified">
        /// This is incremented by the number of identifiers that failed verification.
        /// </param>
        /// <param name="errors">
        /// If any identifiers fail verification, descriptive messages are added to
        /// this list, which is created if necessary.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if every identifier was verified;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode VerifyIdentifiers(
            IdentifierKind kind,  /* in */
            MatchMode mode,       /* in */
            IRuleSet ruleSet,     /* in */
            ref int unverified,   /* in, out */
            ref ResultList errors /* in, out */
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (ruleSet == null)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add("invalid ruleset");
                    return ReturnCode.Error;
                }

                IEnumerable<string> names = null;
                Result error = null;

                if (GetIdentifierNames(
                        kind, ref names, ref error) != ReturnCode.Ok)
                {
                    if (error != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(error);
                    }

                    return ReturnCode.Error;
                }

                int localUnverified = 0;

                foreach (string name in names)
                {
                    if (name == null)
                        continue;

                    if (!ruleSet.ApplyRules(this, kind, mode, name))
                    {
                        localUnverified++;

                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(String.Format(
                            "identifier named {0} of kind {1} unverified",
                            FormatOps.WrapOrNull(name),
                            FormatOps.WrapOrNull(kind)));
                    }
                }

                unverified += localUnverified;

                return (localUnverified == 0) ?
                    ReturnCode.Ok : ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        #region Fake Identifier Helper Class
        /// <summary>
        /// This class provides a lightweight, read-only <see cref="IIdentifier" />
        /// implementation used to represent an identifier that does not have its own
        /// dedicated entity type, wrapping a kind, name, and optional client data.
        /// </summary>
#if SERIALIZATION
        [Serializable()]
#endif
        [ObjectId("de4ea52c-324f-4c5f-9c3a-1cb8de2fd23d")]
        private sealed class FakeIdentifier : IIdentifier
        {
            #region Public Constructors
            /// <summary>
            /// Constructs an instance of this class in a default, empty state.
            /// </summary>
            public FakeIdentifier()
                : this(IdentifierKind.None, null, null)
            {
                // do nothing.
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// Constructs an instance of this class using the specified kind, name, and
            /// client data.
            /// </summary>
            /// <param name="kind">
            /// The kind of identifier represented by this instance.
            /// </param>
            /// <param name="name">
            /// The name of the identifier.  This parameter may be null.
            /// </param>
            /// <param name="clientData">
