        //
        // NOTE: This method is designed to lookup and return a named
        //       ICommand that derives from the "_Commands.Ensemble"
        //       base class.  If the command does not exist -OR- does
        //       not derive from the appropriate base class, an error
        //       is returned instead.
        //
        /// <summary>
        /// This method looks up a named command that derives from the ensemble base
        /// class, considering both normal and hidden commands.
        /// </summary>
        /// <param name="name">
        /// The name of the ensemble command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the ensemble command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the ensemble
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the ensemble was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetEnsemble(
            string name,
            LookupFlags lookupFlags,
            ref ICommand command,
            ref Result error
            )
        {
            ICommand localCommand = null; /* REUSED */
            Result localError = null; /* REUSED */

            if (GetCommand(
                    name, lookupFlags, ref localCommand,
                    ref localError) == ReturnCode.Ok)
            {
                if ((localCommand is _Commands.Ensemble) ||
#if EMIT
                    (localCommand is _Commands.Automatic) ||
#endif
                    (localCommand is _Commands.Stub))
                {
                    command = localCommand;
                    return ReturnCode.Ok;
                }

                error = "invalid ensemble";
            }
            else
            {
                ResultList errors = null;

                if (localError != null)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(localError);
                }

                localCommand = null;
                localError = null;

                if (GetHiddenCommand(
                        name, lookupFlags, ref localCommand,
                        ref localError) == ReturnCode.Ok)
                {
                    if ((localCommand is _Commands.Ensemble) ||
#if EMIT
                        (localCommand is _Commands.Automatic) ||
#endif
                        (localCommand is _Commands.Stub))
                    {
                        command = localCommand;
                        return ReturnCode.Ok;
                    }

                    if (errors == null)
                        errors = new ResultList();

                    errors.Add("invalid ensemble");
                }
                else if (localError != null)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(localError);
                }

                error = errors;
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a path by name, producing a normalized error message
        /// when the path cannot be found.
        /// </summary>
        /// <param name="name">
        /// The name of the path to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="path">
        /// Upon success, this is set to the path that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the path
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the path was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetPath(
            string name,
            LookupFlags lookupFlags,
            ref PathClientData path,
            ref Result error
            )
        {
            if (PrivateGetPath(
                    name, lookupFlags, ref path,
                    ref error) != ReturnCode.Ok)
            {
                error = FlagOps.HasFlags(
                    lookupFlags, LookupFlags.Verbose, true) ?
                    String.Format(
                        "invalid path name {0}",
                        FormatOps.DisplayName(name)) :
                    "invalid path name";

                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // HACK: This method does not directly access any fields
        //       of the interpreter; therefore, no locking should
        //       be needed here.
        //
        /// <summary>
        /// This method looks up a path by its value, name, or description among the
        /// paths populated for this interpreter.
        /// </summary>
        /// <param name="name">
        /// The value, name, or description identifying the path to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="path">
        /// Upon success, this is set to the path that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the path
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the path was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetPath(
            string name,
            LookupFlags lookupFlags,
            ref PathClientData path,
            ref Result error
            )
        {
            int sequence = 0;
            PathClientDataDictionary paths = null;

            GlobalState.PopulatePaths(
                this, false, false, FlagOps.HasFlags(
                lookupFlags, LookupFlags.AllPaths, true),
                ref sequence, ref paths);

            if (paths == null)
            {
                error = "paths unavailable";
                return ReturnCode.Error;
            }

            if (name == null)
            {
                error = "invalid path name";
                return ReturnCode.Error;
            }

            //
            // NOTE: Search by the value of the path
            //       itself.
            //
            if (paths.TryGetValue(name, out path))
                goto found;

            IEnumerable<PathClientDataPair> pairs =
                paths.GetPairsInOrder(false);

            if (pairs == null)
            {
                error = "paths unavailable in order";
                return ReturnCode.Error;
            }

            foreach (PathClientDataPair pair in pairs)
            {
                PathClientData clientData = pair.Value;

                if (clientData == null)
                    continue;

                //
                // NOTE: Search by name.
                //
                if (SharedStringOps.SystemEquals(
                        clientData.Name, name))
                {
                    path = clientData;
                    goto found;
                }

                //
                // NOTE: Search by description.
                //
                if (SharedStringOps.SystemEquals(
                        clientData.Description, name))
                {
                    path = clientData;
                    goto found;
                }
            }

            error = "invalid path name";
            return ReturnCode.Error;

        found:

            if ((path == null) && FlagOps.HasFlags(
                    lookupFlags, LookupFlags.Validate, true))
            {
                error = "invalid path";
                return ReturnCode.Error;
            }
            else
            {
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gathers the names of all entities of the specified identifier
        /// kind.
        /// </summary>
        /// <param name="kind">
        /// The kind of identifiers whose names are to be gathered.
        /// </param>
        /// <param name="names">
        /// Upon success, this is set to the collection of identifier names.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the names
        /// could not be gathered.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the names were gathered;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetIdentifierNames(
            IdentifierKind kind,
            ref IEnumerable<string> names,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                IEnumerable<string> localNames;

                switch (kind)
                {
                    case IdentifierKind.Command:
                        {
                            if (commands == null)
                            {
                                error = "commands unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(commands.Values);

                            if (localNames == null)
                            {
                                error = "command names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.SavedCommand:
                        {
                            if (savedCommands == null)
                            {
                                error = "saved commands unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(savedCommands.Values);

                            if (localNames == null)
                            {
                                error = "saved command names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.HiddenCommand:
                        {
                            if (hiddenCommands == null)
                            {
                                error = "hidden commands unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(hiddenCommands.Values);

                            if (localNames == null)
                            {
                                error = "hidden command names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.SavedHiddenCommand:
                        {
                            if (savedHiddenCommands == null)
                            {
                                error = "saved hidden commands unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(savedHiddenCommands.Values);

                            if (localNames == null)
                            {
                                error = "saved hidden command names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.Procedure:
                        {
                            if (procedures == null)
                            {
                                error = "procedures unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(procedures.Values);

                            if (localNames == null)
                            {
                                error = "procedure names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.HiddenProcedure:
                        {
                            if (hiddenProcedures == null)
                            {
                                error = "hidden procedures unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(hiddenProcedures.Values);

                            if (localNames == null)
                            {
                                error = "hidden procedure names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.IExecute:
                        {
                            if (executes == null)
                            {
                                error = "executes unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(executes);

                            if (localNames == null)
                            {
                                error = "execute names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.SavedIExecute:
                        {
                            if (savedExecutes == null)
                            {
                                error = "saved executes unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(savedExecutes);

                            if (localNames == null)
                            {
                                error = "saved execute names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.HiddenIExecute:
                        {
                            if (hiddenExecutes == null)
                            {
                                error = "hidden executes unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(hiddenExecutes);

                            if (localNames == null)
                            {
                                error = "hidden execute names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.SavedHiddenIExecute:
                        {
                            if (savedHiddenExecutes == null)
                            {
                                error = "saved hidden executes unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(savedHiddenExecutes);

                            if (localNames == null)
                            {
                                error = "saved hidden execute names unavailable";
                                return ReturnCode.Error;
                            }

                            names = localNames;
                            return ReturnCode.Ok;
                        }
                    case IdentifierKind.Function:
                        {
                            if (functions == null)
                            {
                                error = "functions unavailable";
                                return ReturnCode.Error;
                            }

                            localNames = EntityOps.GetNamesNoThrow(functions.Values);

                            if (localNames == null)
