        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region INamespace
        /// <summary>
        /// This method determines whether namespace support is currently enabled for
        /// this interpreter.
        /// </summary>
        /// <returns>
        /// True if namespaces are enabled; otherwise, false.
        /// </returns>
        public bool AreNamespacesEnabled()
        {
            CheckDisposed();

            return InternalAreNamespacesEnabled();
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a namespace by name.
        /// </summary>
        /// <param name="name">
        /// The name of the namespace to look up.
        /// </param>
        /// <param name="absolute">
        /// When true, the name is treated as an absolute (fully qualified) namespace
        /// name.
        /// </param>
        /// <param name="namespace">
        /// Upon success, this is set to the namespace that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the namespace
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the namespace was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode LookupNamespace(
            string name,
            bool absolute,
            ref INamespace @namespace,
            ref Result error
            )
        {
            CheckDisposed();

            if (!InternalAreNamespacesEnabled())
            {
                error = "namespaces not available";
                return ReturnCode.Error;
            }

            INamespace localNamespace = NamespaceOps.Lookup(
                this, name, absolute, false, ref error);

            if (localNamespace == null)
                return ReturnCode.Error;

            @namespace = localNamespace;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new namespace and adds it as a child of its parent
        /// namespace.
        /// </summary>
        /// <param name="namespaceData">
        /// The data describing the namespace to create.
        /// </param>
        /// <param name="arguments">
        /// The arguments to associate with the new namespace.  This parameter may be
        /// null.
        /// </param>
        /// <param name="newFrame">
        /// When true, a new call frame is created for the namespace.
        /// </param>
        /// <param name="namespace">
        /// Upon success, this is set to the namespace that was created.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the namespace
        /// could not be created.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the namespace was created;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode CreateNamespace(
            INamespaceData namespaceData,
            ArgumentList arguments,
            bool newFrame,
            ref INamespace @namespace,
            ref Result error
            )
        {
            CheckDisposed();

            if (!InternalAreNamespacesEnabled())
            {
                error = "namespaces not available";
                return ReturnCode.Error;
            }

            if (!CanAddNamespace(ref error))
                return ReturnCode.Error;

            bool success = false;
            INamespace childNamespace = null;

            try
            {
                childNamespace = NamespaceOps.Create(
                    namespaceData, arguments, newFrame, ref error);

                if (childNamespace != null)
                {
                    INamespace parentNamespace = childNamespace.Parent;

                    if (parentNamespace != null)
                    {
                        if (parentNamespace.AddChild(
                                childNamespace, ref error) == ReturnCode.Ok)
                        {
                            /* IGNORED */
                            TrackNamespaceAdded();

                            @namespace = childNamespace;
                            success = true;

                            return ReturnCode.Ok;
                        }
                    }
                    else
                    {
                        error = "invalid parent namespace";
                    }
                }
            }
            finally
            {
                if (!success && (childNamespace != null))
                    NamespaceOps.Dispose(this, ref childNamespace);
            }

            return ReturnCode.Error;
        }
        #endregion

