        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetCallback(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref ICallback callback,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetCallback(
                        name, lookupFlags, ref token, ref callback,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid callback name {0}",
                            FormatOps.DisplayName(name)) :
                        "invalid callback name";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified callback to this interpreter.
        /// </summary>
        /// <param name="callback">
        /// The callback to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the add operation.  This parameter may
        /// be null.
        /// </param>
        /// <param name="token">
        /// This parameter is ignored.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the callback
        /// could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddCallback(
            ICallback callback,
            IClientData clientData,
            ref long token, /* IGNORED */
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (callback == null)
                {
                    result = "invalid callback";
                    return ReturnCode.Error;
                }

                string name = callback.Name;

                if (name == null)
                {
                    result = "invalid callback name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasCallbacks(ref result))
                    return ReturnCode.Error;

                if (DoesCallbackExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: callback already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                callbacks.Add(name, callback);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Callback, NotifyFlags.Added,
                    callback, this,
                    clientData, null, null, ref result);
#endif
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named callback from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the callback to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This parameter
        /// may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the callback
        /// could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RemoveCallback(
            string name,
            IClientData clientData,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasCallbacks(ref result))
                {
                    long token = 0;
                    ICallback callback = null;

                    if (GetCallback(name, LookupFlags.Remove, ref token,
                            ref callback, ref result) == ReturnCode.Ok)
                    {
                        if (!EntityOps.IsReadOnly(callback))
                        {
                            callbacks.Remove(name);

#if NOTIFY
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Callback, NotifyFlags.Removed,
                                new ObjectPair(callback, token), this,
                                clientData, null, null, ref result);
#endif

                            return ReturnCode.Ok;
                        }
                        else
                        {
                            result = "callback is read-only";
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether the specified callback object is present in
        /// this interpreter.
        /// </summary>
        /// <param name="value">
        /// The callback object to look for.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode HaveCallback(
            object value,           /* in */
            LookupFlags lookupFlags /* in */
            )
        {
            string name = null; /* NOT USED */
            Result error = null; /* NOT USED */

            return PrivateGetCallback(value, lookupFlags, ref name, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method produces a string representation of the callbacks in this
        /// interpreter, optionally filtered by a pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to filter which callbacks are included, or null to
        /// include all of them.
        /// </param>
        /// <param name="noCase">
        /// When true, pattern matching is performed in a case-insensitive manner.
        /// </param>
        /// <returns>
        /// The string representation of the matching callbacks, or null if the
        /// callbacks are not available.
        /// </returns>
        internal string CallbacksToString(
            string pattern,
            bool noCase
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (callbacks != null)
                    return callbacks.ToString(pattern, noCase);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a callback by name without applying any error message
        /// normalization.
        /// </summary>
        /// <param name="name">
        /// The name of the callback to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// This parameter is ignored.
        /// </param>
        /// <param name="callback">
        /// Upon success, this is set to the callback that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the callback
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetCallback(
            string name,
            LookupFlags lookupFlags,
            ref long token, /* IGNORED */
            ref ICallback callback,
            ref Result error
            )
        {
            if (!PrivateHasCallbacks(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid callback name";
                return ReturnCode.Error;
            }

            if (!callbacks.TryGetValue(name, out callback))
            {
                error = "callback not found";
                return ReturnCode.Error;
            }

            if ((callback == null) &&
                FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
            {
                error = "invalid callback";
                return ReturnCode.Error;
            }
            else
            {
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // TODO: Make sure this method needs to be public.
        //       This is marked as internal for now.
        //
        /// <summary>
        /// This method looks up a callback by name, discarding any error message
        /// produced on failure.
        /// </summary>
        /// <param name="name">
        /// The name of the callback to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="callback">
        /// Upon success, this is set to the callback that was found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetCallback(
            string name,
            LookupFlags lookupFlags,
            ref ICallback callback
            )
        {
            // CheckDisposed();

            Result error = null;

            return GetCallback(name, lookupFlags, ref callback, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a callback by name.
        /// </summary>
        /// <param name="name">
        /// The name of the callback to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="callback">
        /// Upon success, this is set to the callback that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the callback
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetCallback(
            string name,
            LookupFlags lookupFlags,
            ref ICallback callback,
            ref Result error
            )
        {
            long token = 0;

            return GetCallback(name, lookupFlags, ref token, ref callback, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method searches for the name of the callback whose value matches the
        /// specified object reference.
        /// </summary>
        /// <param name="value">
        /// The callback object to search for.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the matching callback.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the callback
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if a matching callback was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetCallback(
            object value,            /* in */
            LookupFlags lookupFlags, /* in */
            ref string name,         /* out */
            ref Result error         /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasCallbacks(ref error))
                    return ReturnCode.Error;

                if (callbacks.Count > 0)
                {
                    foreach (CallbackPair pair in callbacks)
                    {
                        ICallback localCallback = pair.Value;

                        if (Object.ReferenceEquals(localCallback, value))
                        {
                            if ((localCallback == null) && FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Validate, true))
                            {
                                break;
                            }
                            else
                            {
                                name = pair.Key;
                                return ReturnCode.Ok;
                            }
                        }
                    }
                }

                //
                // HACK: Prevent ToString method from throwing any
                //       exceptions here (e.g. proxy).
                //
                try
                {
                    if (!AppDomainOps.IsTransparentProxy(value))
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "invalid callback {0}",
                                FormatOps.WrapOrNull(value)) :
                            "invalid callback";
                    }
                    else
                    {
                        error = "invalid callback";
                    }
                }
                catch (Exception e)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid callback: {0}",
                            e) :
                        "invalid callback";
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a callback by its underlying delegate, discarding any
        /// name and error message produced on failure.
        /// </summary>
        /// <param name="delegate">
        /// The delegate whose associated callback is to be found.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="callback">
        /// Upon success, this is set to the callback that was found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetCallback(
            Delegate @delegate,
            LookupFlags lookupFlags,
            ref ICallback callback
            )
        {
            string name = null;
            Result error = null;

            return GetCallback(
                @delegate, lookupFlags, CallbackFlags.None,
                CallbackFlags.None, false, false, ref name,
                ref callback, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a callback by its underlying delegate, filtering the
        /// candidates by their callback flags.
        /// </summary>
        /// <param name="delegate">
        /// The delegate whose associated callback is to be found.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="hasFlags">
        /// The callback flags that a candidate callback must have, or
        /// <see cref="CallbackFlags.None" /> to impose no such requirement.
        /// </param>
        /// <param name="notHasFlags">
        /// The callback flags that a candidate callback must not have, or
        /// <see cref="CallbackFlags.None" /> to impose no such requirement.
        /// </param>
        /// <param name="hasAll">
        /// When true, a candidate must have all of the required flags; otherwise,
        /// having any of them is sufficient.
        /// </param>
        /// <param name="notHasAll">
        /// When true, a candidate is rejected only if it has all of the excluded
        /// flags; otherwise, having any of them is sufficient to reject it.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the matching callback.
        /// </param>
        /// <param name="callback">
        /// Upon success, this is set to the callback that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the callback
        /// could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if a matching callback was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetCallback(
            Delegate @delegate,
            LookupFlags lookupFlags,
            CallbackFlags hasFlags,
            CallbackFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            ref string name,
            ref ICallback callback,
            ref Result error
            )
        {
            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasCallbacks(ref error))
                {
                    if (callbacks.Count > 0)
                    {
                        foreach (CallbackPair pair in callbacks)
                        {
                            ICallback localCallback = pair.Value;

                            if (localCallback == null)
                                continue;

                            Delegate localDelegate = localCallback.Delegate;

                            if (Object.ReferenceEquals(localDelegate, @delegate))
                            {
                                CallbackFlags localFlags = localCallback.CallbackFlags;

                                if (((hasFlags == CallbackFlags.None) ||
                                        FlagOps.HasFlags(localFlags, hasFlags, hasAll)) &&
                                    ((notHasFlags == CallbackFlags.None) ||
                                        !FlagOps.HasFlags(localFlags, notHasFlags, notHasAll)))
                                {
                                    name = pair.Key;
                                    callback = localCallback;

                                    code = ReturnCode.Ok;
                                    break;
                                }
                            }
                        }
                    }

                    if (code != ReturnCode.Ok)
                    {
                        //
                        // HACK: Prevent ToString method from throwing any
                        //       exceptions here (e.g. proxy).
                        //
                        try
                        {
                            if (!AppDomainOps.IsTransparentProxy(@delegate))
                            {
                                error = FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Verbose, true) ?
                                    String.Format(
                                        "invalid callback delegate {0}",
                                        FormatOps.WrapOrNull(@delegate)) :
                                    "invalid callback delegate";
                            }
                            else
                            {
                                error = "invalid callback delegate";
                            }
                        }
                        catch (Exception e)
                        {
                            error = FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Verbose, true) ?
                                String.Format(
                                    "invalid callback delegate: {0}",
                                    e) :
                                "invalid callback delegate";
                        }
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified callback to this interpreter.
        /// </summary>
        /// <param name="callback">
        /// The callback to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the add operation.  This parameter may
        /// be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the callback
        /// could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callback was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddCallback(
            ICallback callback,
            IClientData clientData,
            ref Result result
            )
        {
            long token = 0;

            return AddCallback(callback, clientData, ref token, ref result);
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IExecute
        /// <summary>
        /// This method looks up an executable entity (e.g. a command, procedure, or
        /// alias) by its token.
        /// </summary>
        /// <param name="token">
        /// The token associated with the executable entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the executable entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, this is set to the executable entity that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// executable entity could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the executable entity was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetIExecute(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IExecute execute,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetIExecute(
                        token, lookupFlags, ref name, ref execute,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid execute token {0}",
                            FormatOps.WrapOrNull(token)) :
                        "invalid execute token";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up an executable entity (e.g. a command, procedure, or
        /// alias) by its name.
        /// </summary>
        /// <param name="name">
        /// The name of the executable entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// executable entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, this is set to the executable entity that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// executable entity could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the executable entity was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetIExecute(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IExecute execute,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetIExecute(
                        name, lookupFlags, ref token, ref execute,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid execute name {0}",
                            FormatOps.DisplayName(name)) :
                        "invalid execute name";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the names of the executable entities matching
        /// the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against executable entity names, or null to
        /// match all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if pattern matching should be case-insensitive.
        /// </param>
        /// <param name="strict">
        /// Non-zero if the absence of any executable entities should be
        /// treated as an error.
        /// </param>
        /// <param name="list">
        /// Upon success, the matching executable entity names are added to this
        /// list, which is created first if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// list could not be built.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode ListIExecutes(
            string pattern,
            bool noCase,
            bool strict,
            ref StringList list,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasIExecutes(ref localError))
                {
                    if (InternalAreNamespacesEnabled())
                    {
                        INamespace currentNamespace = null;

                        code = GetCurrentNamespaceViaResolvers(
                            null, LookupFlags.Default, ref currentNamespace,
                            ref error);

                        if (code == ReturnCode.Ok)
                        {
                            StringList[] localLists = { null, null };

                            code = executes.ToList(
                                null, false, ref localLists[0], ref error);

                            if (code == ReturnCode.Ok)
                            {
                                code = MatchItems(
                                    currentNamespace, pattern, noCase,
                                    ref localLists, ref error);

                                if (list == null)
                                    list = localLists[1];
                                else
                                    list.AddRange(localLists[1]);
                            }
                        }
                    }
                    else
                    {
                        pattern = ScriptOps.MakeCommandName(pattern);

                        code = executes.ToList(
                            pattern, noCase, ref list, ref error);
                    }
                }
                else if (strict)
                {
                    error = localError;
                }
                else
                {
                    if (list == null)
                        list = new StringList();

                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified executable entity to this interpreter,
        /// using the specified name.
        /// </summary>
        /// <param name="name">
        /// The name to use for the executable entity.
        /// </param>
        /// <param name="execute">
        /// The executable entity to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the add operation.  This
        /// parameter is not used.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added executable entity.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// executable entity could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the executable entity was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddIExecute(
            string name,
            IExecute execute,
            IClientData clientData, /* NOT USED */
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (execute == null)
                {
                    result = "invalid execute";
                    return ReturnCode.Error;
                }

                if (name == null)
                {
                    result = "invalid execute name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasIExecutes(ref result))
                    return ReturnCode.Error;

                //
                // WARNING: Currently, if somebody adds an IExecute that shadows a
                //          command or procedure (by name), it will take priority.
                //          This behavior could be prevented here by changing this
                //          check to be DoesAnyIExecuteExist instead of DoesIExecuteExist;
                //          however, I am not convinced that task should be the
                //          responsibility of this method (i.e. why should a method
                //          that deals with IExecute objects need to know about command
                //          or procedure objects?).  The spirit of this check is basically
                //          "can we physically add the object in question?".
                //
                /* EXEMPT */
                if (FlagOps.HasFlags(interpreterFlags,
                        InterpreterFlags.DoesAnythingExist, true))
                {
                    if (InternalDoesIExecuteExistViaResolvers(name) == ReturnCode.Ok)
                    {
                        result = String.Format(
                            "can't add {0}: something already exists",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                }
                else
                {
                    if (DoesIExecuteExist(name) == ReturnCode.Ok)
                    {
                        result = String.Format(
                            "can't add {0}: execute already exists",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                }

                Result localError = null;

                if (InternalAreNamespacesEnabled() && (NamespaceOps.LookupParent(
                        this, name, false, true, true, ref localError) == null))
                {
                    result = String.Format(
                        "can't add execute {0}: {1}",
                        FormatOps.WrapOrNull(name),
                        localError);

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(
                            execute as IWrapperData);

                        wrapper = EntityOps.MaybeNewWrapperWith<ExecuteWrapper>(
                            id, execute as IWrapperData);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        executes.Add(name, wrapper as ExecuteWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);

#if EXECUTE_CACHE
                        AddOrUpdateIExecuteToCache(name, execute, false, false);
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(name);
#endif

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.IExecute, NotifyFlags.Added,
                            new ObjectPair(execute, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

