        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method finds the executable entity whose name exactly or unambiguously
        /// matches the specified name, honoring the hidden-entity engine flag.
        /// </summary>
        /// <param name="engineFlags">
        /// The flags that control engine behavior, including whether
        /// hidden executable entities should be searched.
        /// </param>
        /// <param name="name">
        /// The name to match against executable entity names.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="ambiguous">
        /// Upon failure, this is set to non-zero if the name matched more
        /// than one executable entity.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the matched
        /// executable entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, this is set to the matched executable entity.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why a
        /// unique match could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if exactly one executable entity matched; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode MatchIExecute(
            EngineFlags engineFlags,
            string name,
            LookupFlags lookupFlags,
            ref bool ambiguous,
            ref long token,
            ref IExecute execute,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool useHidden = EngineFlagOps.HasUseHidden(engineFlags);

                ExecuteWrapperDictionary localExecutes =
                    useHidden ? hiddenExecutes : executes;

                if (localExecutes != null)
                {
                    //
                    // NOTE: *WARNING* Empty command/procedure names are allowed,
                    //       please do not change this to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        if (localExecutes.Count > 0)
                        {
                            ExecuteWrapper localExecute;
                            string exactName = null;
                            StringList list = new StringList();

                            if (localExecutes.TryGetValue(name, out localExecute))
                            {
                                //
                                // NOTE: Exact execute match.
                                //
                                exactName = name;

                                //
                                // NOTE: Store the exact execute match in the result
                                //       list.
                                //
                                list.Add(name);
                            }
                            else
                            {
                                foreach (ExecutePair pair in localExecutes)
                                {
                                    if (SharedStringOps.SystemEquals(pair.Key, 0, name, 0, name.Length))
                                    {
                                        //
                                        // NOTE: Was the key valid (this should always succeed).
                                        //
                                        if (pair.Key != null)
                                        {
                                            //
                                            // NOTE: It was a match; however, was it an exact match?
                                            //
                                            if (pair.Key.Length == name.Length)
                                                //
                                                // NOTE: Preserve match, it may differ in case.
                                                //
                                                exactName = pair.Key;

                                            //
                                            // NOTE: Was it an exact match or did we match at least one
                                            //       character in a partial match?
                                            //
                                            if ((pair.Key.Length == name.Length) || (name.Length > 0))
                                                //
                                                // NOTE: Store the exact or partial match in the results
                                                //       dictionary.
                                                //
                                                list.Add(pair.Key);
                                        }
                                    }
                                }
                            }

                            //
                            // NOTE: If there was an exact match, just use it.
                            //
                            if (exactName != null)
                            {
                                //
                                // NOTE: No need to change the caller's variable,
                                //       it already contains the correct value.
                                //
                                if (PrivateGetIExecute(
                                        exactName, lookupFlags, ref token,
                                        ref execute, ref error) == ReturnCode.Ok)
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        useHidden ? NotifyType.HiddenIExecute : NotifyType.IExecute,
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, exactName, execute, token), this, null, null,
                                        null, ref error);
#endif

                                    return ReturnCode.Ok;
                                }
                            }
                            else if (list.Count == 1)
                            {
                                //
                                // NOTE: Normal case, exactly one command matched.
                                //
                                if (PrivateGetIExecute(
                                        list[0], lookupFlags, ref token,
                                        ref execute, ref error) == ReturnCode.Ok)
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        useHidden ? NotifyType.HiddenIExecute : NotifyType.IExecute,
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, list[0], execute, token), this, null, null,
                                        null, ref error);
#endif

                                    return ReturnCode.Ok;
                                }
                            }
                            else if (list.Count > 1)
                            {
                                error = FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Verbose, true) ?
                                    ScriptOps.BadValue(
                                        "ambiguous", "execute", name, list,
                                        null, null) :
                                    (Result)"ambiguous execute";

                                ambiguous = true;
                            }
                            else
                            {
                                error = FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Verbose, true) ?
                                    ScriptOps.BadValue(
                                        null, "execute", name, localExecutes.Keys,
                                        null, null) :
                                    (Result)"bad execute";
                            }
                        }
                        else
                        {
                            error = "no executes defined";
                        }
                    }
                    else
                    {
                        error = "invalid execute name";
                    }
                }
                else
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "{0}executes not available",
                            useHidden ? "hidden " : String.Empty) :
                        "executes not available";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method looks up an executable entity by its token.  This is the
        /// private implementation that performs the actual lookup.
        /// </summary>
        /// <param name="token">
        /// The token associated with the executable entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the executable entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, this is set to the executable entity that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// executable entity could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the executable entity was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetIExecute(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IExecute execute,
            ref Result error
            )
        {
            if (!PrivateHasIExecutes(ref error))
                return ReturnCode.Error;

            ExecuteWrapper wrapper;

            if (!executes.TryGetValue(token, out wrapper))
            {
                error = "execute not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                execute = wrapper;
                name = EntityOps.GetName(execute as IIdentifierName);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid execute wrapper";
                    return ReturnCode.Error;
                }

                execute = wrapper.execute;
                name = EntityOps.GetName(execute as IIdentifierName);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up an executable entity by its name.  This is the
        /// private implementation that performs the actual lookup.
        /// </summary>
        /// <param name="name">
        /// The name of the executable entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// executable entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, this is set to the executable entity that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// executable entity could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the executable entity was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetIExecute(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IExecute execute,
            ref Result error
            )
        {
            if (!PrivateHasIExecutes(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid execute name";
                return ReturnCode.Error;
            }

            ExecuteWrapper wrapper;

            if (!executes.TryGetValue(name, out wrapper))
            {
                error = "execute not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                execute = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid execute wrapper";
                    return ReturnCode.Error;
                }

                execute = wrapper.execute;

                //
                // WARNING: Cannot grab the token from the IExecute here
                //          because that interface does not inherit from
                //          IWrapperData.
                //
                token = EntityOps.GetToken(wrapper);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

