        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the names of the hidden executable entities
        /// matching the specified pattern, discarding any error message.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against hidden executable entity names, or
        /// null to match all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if pattern matching should be case-insensitive.
        /// </param>
        /// <param name="strict">
        /// Non-zero if the absence of any hidden executable entities should
        /// be treated as an error.
        /// </param>
        /// <param name="list">
        /// Upon success, the matching hidden executable entity names are added
        /// to this list, which is created first if necessary.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListHiddenIExecutes(
            string pattern,
            bool noCase,
            bool strict,
            ref StringList list
            )
        {
            Result error = null;

            return ListHiddenIExecutes(
                pattern, noCase, strict, ref list, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the names of the hidden executable entities
        /// matching the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against hidden executable entity names, or
        /// null to match all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if pattern matching should be case-insensitive.
        /// </param>
        /// <param name="strict">
        /// Non-zero if the absence of any hidden executable entities should
        /// be treated as an error.
        /// </param>
        /// <param name="list">
        /// Upon success, the matching hidden executable entity names are added
        /// to this list, which is created first if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// list could not be built.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListHiddenIExecutes(
            string pattern,
            bool noCase,
            bool strict,
            ref StringList list,
            ref Result error
            )
        {
            // CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasHiddenIExecutes(ref localError))
                {
                    if (InternalAreNamespacesEnabled())
                    {
                        INamespace currentNamespace = null;

                        code = GetCurrentNamespaceViaResolvers(
                            null, LookupFlags.Default, ref currentNamespace,
                            ref error);

                        if (code == ReturnCode.Ok)
                        {
                            StringList[] localLists = { null, null };

                            code = hiddenExecutes.ToList(
                                null, false, ref localLists[0], ref error);

                            if (code == ReturnCode.Ok)
                            {
                                code = MatchItems(
                                    currentNamespace, pattern, noCase,
                                    ref localLists, ref error);

                                if (code == ReturnCode.Ok)
                                    list = localLists[1];
                            }
                        }
                    }
                    else
                    {
                        pattern = ScriptOps.MakeCommandName(pattern);

                        code = hiddenExecutes.ToList(
                            pattern, noCase, ref list, ref error);
                    }
                }
                else if (strict)
                {
                    error = localError;
                }
                else
                {
                    if (list == null)
                        list = new StringList();

                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames an executable entity, optionally bypassing namespace
        /// processing.  This is the private implementation behind the public renaming
        /// methods.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the executable entity to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the executable entity.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to skip namespace processing while renaming.
        /// </param>
        /// <param name="delete">
        /// Non-zero to remove the executable entity instead of renaming it
        /// when the new name is null or empty.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// executable entity could not be renamed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the executable entity was renamed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameIExecute(
            string oldName,
            string newName,
            bool noNamespaces,
            bool delete,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasIExecutes(ref result))
                {
                    if (!delete || !String.IsNullOrEmpty(newName))
                    {
                        IExecute oldExecute = null;

                        if (GetIExecute(oldName, LookupFlags.Default, ref oldExecute, ref result) == ReturnCode.Ok)
                        {
                            ExecuteWrapper oldWrapper = oldExecute as ExecuteWrapper;

                            if (oldWrapper != null)
                            {
                                IAlias oldAlias = oldWrapper.execute as IAlias;

                                if (PreventAliasLoop(oldAlias, newName, ref result) == ReturnCode.Ok)
                                {
                                    if (IsValidAnyIExecuteName(newName, noNamespaces, ref result) == ReturnCode.Ok)
                                    {
                                        bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();

                                        if (!useNamespaces ||
                                            RenameImportInNamespaces(oldName, newName, ref result) == ReturnCode.Ok)
                                        {
                                            /* IGNORED */
                                            executes.Rename(oldName, newName);

#if EXECUTE_CACHE
                                            RenameIExecuteInCache(oldName, newName, oldWrapper, false, false);
#endif

#if ARGUMENT_CACHE
                                            /* IGNORED */
                                            MaybeClearArgumentCache(oldName);

                                            /* IGNORED */
                                            MaybeClearArgumentCache(newName);
#endif

#if NOTIFY
                                            /* IGNORED */
                                            CheckNotification(
                                                NotifyType.IExecute, NotifyFlags.Renamed,
                                                new ObjectTriplet(oldExecute, oldName, newName), this,
                                                null, null, null, ref result);
#endif

                                            result = String.Empty;
                                            return ReturnCode.Ok;
                                        }
                                    }
                                }
                            }
                            else
                            {
                                result = String.Format(
                                    "can't rename {0}: invalid execute wrapper",
                                    FormatOps.WrapOrNull(oldName));
                            }
                        }
                        else
                        {
                            result = String.Format(
                                "can't rename {0}: execute doesn't exist",
                                FormatOps.WrapOrNull(oldName));
                        }
                    }
                    else
                    {
                        return RemoveIExecute(oldName, null, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the specified executable entity, visible or hidden,
        /// from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the executable entity to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the executable entity to remove.
        /// </param>
        /// <param name="execute">
        /// The executable entity to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="hidden">
        /// Non-zero if the executable entity to remove is a hidden one.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// executable entity could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the executable entity was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveIExecute(
            string name,
            long token,
            IExecute execute,
            IClientData clientData,
            bool hidden,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid execute name";
                return ReturnCode.Error;
            }

            GlobalState.PushActiveInterpreter(this);

            try
            {
                if (InternalAreNamespacesEnabled() &&
                    RemoveImportFromNamespaces(name, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

#if NATIVE && TCL
                if ((execute == null) ||
                    (DisposeTclBridges(IntPtr.Zero, execute, null, false, ref result) == ReturnCode.Ok))
#endif
                {
                    if (hidden)
                        /* IGNORED */
                        hiddenExecutes.Remove(name, token);
                    else
                        /* IGNORED */
                        executes.Remove(name, token);

#if EXECUTE_CACHE
                    RemoveIExecuteFromCache(name, hidden, false);
#endif

#if ARGUMENT_CACHE
                    /* IGNORED */
                    MaybeClearArgumentCache(name);
#endif

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(hidden ?
                        NotifyType.HiddenIExecute : NotifyType.IExecute,
                        NotifyFlags.Removed, new ObjectTriplet(execute,
                            name, token), this, clientData, null, null,
                        ref result);
#endif

                    return ReturnCode.Ok;
                }

#if NATIVE && TCL
                return ReturnCode.Error;
#endif
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while removing {0}execute: {1}",
                    hidden ? "hidden " : String.Empty, e);

                return ReturnCode.Error;
            }
            finally
            {
                /* IGNORED */
                GlobalState.PopActiveInterpreter();
            }
        }

