        /// <summary>
        /// This method wraps the specified managed value in a new opaque object and
        /// adds it to this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name to use for the opaque object.
        /// </param>
        /// <param name="type">
        /// The declared type of the wrapped value.
        /// </param>
        /// <param name="objectFlags">
        /// The flags to associate with the opaque object.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the opaque object.  This
        /// parameter may be null.
        /// </param>
        /// <param name="referenceCount">
        /// The initial reference count for the opaque object.
        /// </param>
        /// <param name="interpName">
        /// The name of the native Tcl interpreter associated with the
        /// opaque object, if any.
        /// </param>
        /// <param name="executeArguments">
        /// The arguments used when the opaque object is executed, if
        /// any.
        /// </param>
        /// <param name="value">
        /// The managed value to wrap.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added opaque object.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// opaque object could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the opaque object was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddObject(
            string name,
            Type type,
            ObjectFlags objectFlags,
            IClientData clientData,
            int referenceCount,
#if NATIVE && TCL
            string interpName,
#endif
#if DEBUGGER && DEBUGGER_ARGUMENTS
            ArgumentList executeArguments,
#endif
            object value,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            return AddObject(new _Objects.Default(new ObjectData(
                name, null, null, clientData, false, false, type,
                null, objectFlags, referenceCount, 0,
#if NATIVE && TCL
                interpName,
#endif
#if DEBUGGER && DEBUGGER_ARGUMENTS
                executeArguments,
#endif
                0), value, null), null, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified opaque object to this interpreter.
        /// </summary>
        /// <param name="object">
        /// The opaque object to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the add operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added opaque object.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// opaque object could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the opaque object was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddObject(
            IObject @object,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (@object == null)
                {
                    result = "invalid object";
                    return ReturnCode.Error;
                }

                string name = @object.Name;

                if (name == null)
                {
                    result = "invalid object name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasObjects(ref result))
                    return ReturnCode.Error;

                if (DoesObjectExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: object already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(@object);

                        wrapper = EntityOps.MaybeNewWrapperWith<ObjectWrapper>(
                            id, @object);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        objects.Add(name, wrapper as ObjectWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(@object, newToken);

#if DEBUG && VERBOSE
                        TraceOps.DebugTrace(String.Format(
                            "AddObject: token = {0}, name = {1}, hashCode = {2}",
                            newToken, FormatOps.WrapOrNull(name),
                            FormatOps.WrapHashCode(@object)),
                            typeof(Interpreter).Name, TracePriority.AddDebug);
#endif

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Object, NotifyFlags.Added,
                            new ObjectPair(@object, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Object Renaming Support (WARNING: EXPERIMENTAL)
        /// <summary>
        /// This method renames an opaque object from its old name to a new name,
        /// optionally renaming the associated command alias as well.  Object renaming
        /// support is experimental.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the opaque object to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the opaque object.
        /// </param>
        /// <param name="ignoreAlias">
        /// Non-zero to leave any associated command alias untouched.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to skip namespace processing while renaming.
        /// </param>
        /// <param name="strict">
        /// Non-zero if a failure to rename the associated alias or command
        /// should be treated as an error.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// opaque object could not be renamed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the opaque object was renamed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RenameObject(
            string oldName,
            string newName,
            bool ignoreAlias,
            bool noNamespaces,
            bool strict,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (oldName == null)
                {
                    result = "invalid old object name";
                    return ReturnCode.Error;
                }

                if (newName == null)
                {
                    result = "invalid new object name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasObjects(ref result))
                    return ReturnCode.Error;

                if (DoesObjectExist(newName) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't rename {0}: object already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                ObjectWrapper @object;

                if (!objects.TryGetValue(oldName, out @object))
                {
                    result = String.Format(
                        "can't rename {0}: object does not exist",
                        FormatOps.WrapOrNull(oldName));

                    return ReturnCode.Error;
                }

                IAlias alias = null;

                if (@object != null)
                {
                    if (FlagOps.HasFlags(
                            @object.ObjectFlags, ObjectFlags.Locked, true))
                    {
                        result = String.Format(
                            "can't rename {0}: object is locked",
                            FormatOps.WrapOrNull(oldName));

                        return ReturnCode.Error;
                    }

                    if (!ignoreAlias && FlagOps.HasFlags(
                            @object.ObjectFlags, ObjectFlags.Alias, true))
                    {
                        alias = @object.Alias;

                        string oldCommandName = oldName;
                        string newCommandName = newName;

                        GetCommandNamesForRename(alias,
                            noNamespaces, ref oldCommandName, ref newCommandName);

                        Result localResult = null; /* REUSED */

                        if ((alias != null) && RenameAlias(
                                alias, newName, ref localResult) != ReturnCode.Ok)
                        {
                            if (strict)
                            {
                                result = localResult;
                                return ReturnCode.Error;
                            }
                        }

                        localResult = null;

                        if (PrivateRenameAnyIExecute(
                                oldCommandName, newCommandName, null,
                                IdentifierKind.None, noNamespaces,
                                false, false, false, false,
                                ref localResult) != ReturnCode.Ok)
                        {
                            if (strict)
                            {
                                result = localResult;
                                return ReturnCode.Error;
                            }
                        }
                    }

                    //
                    // NOTE: New name, same token.
                    //
                    @object.Name = newName;
                }

                /* IGNORED */
                objects.Rename(oldName, newName);

                //
                // NOTE: At this point, make sure the alias arguments, if any,
                //       are updated to reflect the new object name.  This is
                //       only applicable if the associated compile-time option
                //       is enabled.
                //
#if CACHE_ARGUMENTLIST_TOSTRING
                if (alias != null)
                {
                    ArgumentList arguments = alias.Arguments;

                    if (arguments != null)
                        arguments.InvalidateCachedString(true);
                }
#endif

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Object, NotifyFlags.Renamed,
                    new ObjectTriplet(@object, oldName, newName),
                    this, null, null, null, ref result);
#endif
            }

            return ReturnCode.Ok;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the opaque object with the specified token from this
        /// interpreter, optionally disposing of its wrapped value.
        /// </summary>
        /// <param name="token">
