        /// <summary>
        /// This method returns a string representation of the opaque objects matching
        /// the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against opaque object names, or null to
        /// match all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if pattern matching should be case-insensitive.
        /// </param>
        /// <returns>
        /// The string representation of the matching opaque objects, or null if there
        /// are no opaque objects.
        /// </returns>
        internal string ObjectsToString(
            string pattern,
            bool noCase
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (objects != null)
                    return objects.ToString(pattern, noCase);
                else
                    return null;
            }
        }

