        /// <summary>
        /// This method looks up an opaque object by its token.  This is the private
        /// implementation that performs the actual lookup.
        /// </summary>
        /// <param name="token">
        /// The token associated with the opaque object to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the opaque object.
        /// </param>
        /// <param name="object">
        /// Upon success, this is set to the opaque object that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// opaque object could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the opaque object was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetObject(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IObject @object,
            ref Result error
            )
        {
            if (!PrivateHasObjects(ref error))
                return ReturnCode.Error;

            ObjectWrapper wrapper;

            if (!objects.TryGetValue(token, out wrapper))
            {
                error = "object not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                @object = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((@object == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid object";
                    return ReturnCode.Error;
                }

                if ((@object != null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.NoDisposed, true))
                {
                    if (@object.Disposed)
                    {
                        error = "disposed object";
                        return ReturnCode.Error;
                    }

                    bool? disposed = ObjectOps.IsDisposed(
                        this, @object.Value, true, false, false);

                    if ((disposed != null) && (bool)disposed)
                    {
                        error = "disposed object value";
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid object wrapper";
                    return ReturnCode.Error;
                }

                @object = wrapper.@object;
                name = EntityOps.GetName(@object);

                if ((@object == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid object";
                    return ReturnCode.Error;
                }

                if ((@object != null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.NoDisposed, true))
                {
                    if (@object.Disposed)
                    {
                        error = "disposed object";
                        return ReturnCode.Error;
                    }

                    bool? disposed = ObjectOps.IsDisposed(
                        this, @object.Value, true, false, false);

                    if ((disposed != null) && (bool)disposed)
                    {
                        error = "disposed object value";
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
        }

