        /// opaque object could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the opaque object was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetObject(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IObject @object,
            ref Result error
            )
        {
            if (!PrivateHasObjects(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid object name";
                return ReturnCode.Error;
            }

            ObjectWrapper wrapper;

            if (!objects.TryGetValue(name, out wrapper))
            {
                error = "object not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                @object = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((@object == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid object";
                    return ReturnCode.Error;
                }

                if ((@object != null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.NoDisposed, true))
                {
                    if (@object.Disposed)
                    {
                        error = "disposed object";
                        return ReturnCode.Error;
                    }

                    bool? disposed = ObjectOps.IsDisposed(
                        this, @object.Value, true, false, false);

                    if ((disposed != null) && (bool)disposed)
                    {
                        error = "disposed object value";
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid object wrapper";
                    return ReturnCode.Error;
                }

                @object = wrapper.@object;
                token = EntityOps.GetToken(@object);

                if ((@object == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid object";
                    return ReturnCode.Error;
                }

                if ((@object != null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.NoDisposed, true))
                {
                    if (@object.Disposed)
                    {
                        error = "disposed object";
                        return ReturnCode.Error;
                    }

                    bool? disposed = ObjectOps.IsDisposed(
                        this, @object.Value, true, false, false);

                    if ((disposed != null) && (bool)disposed)
                    {
                        error = "disposed object value";
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up an opaque object by its name and converts its wrapped
        /// value to an array of bytes.
        /// </summary>
        /// <param name="encoding">
        /// The encoding to use when the wrapped value is a string.
        /// </param>
        /// <param name="name">
        /// The name of the opaque object to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="bytes">
        /// Upon success, this is set to the byte representation of the wrapped
        /// value.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// wrapped value could not be converted.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the wrapped value was converted; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetObjectAsBytes(
            Encoding encoding,
            string name,
            LookupFlags lookupFlags,
            ref byte[] bytes,
            ref Result error
            )
        {
            IObject @object = null;

            if (GetObject(
                    name, lookupFlags, ref @object,
                    ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            object value = @object.Value;

            if (value is string)
            {
                if (StringOps.GetBytes(
                        encoding, (string)value, EncodingType.Binary,
                        true, ref bytes, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }
            else if (value is char)
            {
                bytes = new byte[] {
                    ConversionOps.ToLowByte((char)value),
                    ConversionOps.ToHighByte((char)value)
                };
            }
            else if (value is byte[])
            {
                bytes = (byte[])value;
            }
            else if (value is ByteList)
            {
                bytes = ArrayOps.GetArray<byte>(
                    (ByteList)value, true);
            }
            else
            {
                error = "unsupported object value for bytes";
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up an opaque object by its name and appends its wrapped
        /// value to the virtual output of the specified channel.
        /// </summary>
        /// <param name="name">
        /// The name of the opaque object to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="channel">
        /// The channel whose virtual output the wrapped value is appended
        /// to.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// wrapped value could not be appended.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the wrapped value was appended; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AppendObjectAsVirtualOutput(
            string name,
            LookupFlags lookupFlags,
            IChannel channel,
            ref Result error
            )
        {
            if (channel == null)
            {
                error = "invalid channel";
                return ReturnCode.Error;
            }

            IObject @object = null;

            if (GetObject(
                    name, lookupFlags, ref @object,
                    ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            object value = @object.Value;

            if (value is string)
            {
                channel.AppendVirtualOutput((string)value);
            }
            else if (value is char)
            {
                channel.AppendVirtualOutput((char)value);
            }
            else if (value is byte[])
            {
                channel.AppendVirtualOutput((byte[])value);
            }
            else if (value is ByteList)
            {
                channel.AppendVirtualOutput(
                    ArrayOps.GetArray<byte>((ByteList)value, true));
            }
            else
            {
                error = "unsupported object value for bytes";
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

