        /// </returns>
        private ReturnCode GetObject(
            object value,
            LookupFlags lookupFlags,
            ObjectFlags hasFlags,
            ObjectFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            ref string name,
            ref long token,
            ref IObject @object,
            ref Result error
            )
        {
            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasObjects(ref error))
                {
                    Result localError = null;

                    if (objects.Count > 0)
                    {
                        foreach (__ObjectPair pair in objects)
                        {
                            ObjectWrapper wrapper = pair.Value;

                            if (wrapper == null)
                                continue;

                            if (Object.ReferenceEquals(wrapper.Value, value))
                            {
                                if (((hasFlags == ObjectFlags.None) ||
                                        FlagOps.HasFlags(wrapper.ObjectFlags, hasFlags, hasAll)) &&
                                    ((notHasFlags == ObjectFlags.None) ||
                                        !FlagOps.HasFlags(wrapper.ObjectFlags, notHasFlags, notHasAll)))
                                {
                                    name = pair.Key;

                                    if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
                                        @object = wrapper;
                                    else
                                        @object = wrapper.@object;

                                    token = EntityOps.GetToken(wrapper);

                                    if ((@object == null) &&
                                        FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                                    {
                                        localError = "invalid object";
                                        code = ReturnCode.Error;

                                        break;
                                    }

                                    if ((@object != null) &&
                                        FlagOps.HasFlags(lookupFlags, LookupFlags.NoDisposed, true))
                                    {
                                        if (@object.Disposed)
                                        {
                                            localError = "disposed object";
                                            code = ReturnCode.Error;

                                            break;
                                        }

                                        bool? disposed = ObjectOps.IsDisposed(
                                            this, @object.Value, true, false, false);

                                        if ((disposed != null) && (bool)disposed)
                                        {
                                            localError = "disposed object value";
                                            code = ReturnCode.Error;

                                            break;
                                        }
                                    }

                                    code = ReturnCode.Ok;
                                    break;
                                }
                            }
                        }
                    }

                    if (code != ReturnCode.Ok)
                    {
                        //
                        // HACK: Prevent ToString method from throwing any
                        //       exceptions here (e.g. proxy).
                        //
                        ResultList errors = new ResultList();

                        if (localError != null)
                            errors.Add(localError);

                        try
                        {
                            if (!AppDomainOps.IsTransparentProxy(value))
                            {
                                errors.Add(FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Verbose, true) ?
                                    String.Format(
                                        "invalid object value {0}",
                                        FormatOps.WrapOrNull(value)) :
                                    "invalid object value");
                            }
                            else
                            {
                                errors.Add("invalid object value");
                            }
                        }
                        catch (Exception e)
                        {
                            errors.Add(FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Verbose, true) ?
                                String.Format(
                                    "invalid object value: {0}",
                                    e) :
                                "invalid object value");
                        }

                        error = errors;
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the ObjectTraceCallback method only.
        //
        /// <summary>
        /// This method collects the opaque object wrappers for the specified object
        /// names, for use by the object trace callback.
        /// </summary>
        /// <param name="names">
        /// The names of the opaque objects to collect.
        /// </param>
        /// <param name="objects">
        /// Upon return, the collected opaque object wrappers are added to
        /// this list, which is created first if necessary.
        /// </param>
        private void GetObjectsForTrace(
            StringList names,                /* in */
            ref IList<ObjectWrapper> objects /* in, out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (names == null)
                    return;

                ObjectWrapperDictionary localObjects = this.objects;

                if ((localObjects == null) || (localObjects.Count == 0))
                    return;

                foreach (string name in names)
                {
                    if (name == null)
                        continue;

                    ObjectWrapper wrapper;

                    if (localObjects.TryGetValue(name, out wrapper))
                    {
                        if (objects == null)
                            objects = new List<ObjectWrapper>(names.Count);

                        objects.Add(wrapper);
                    }
                }
            }
        }

