        /// <summary>
        /// This method adds the special opaque object that represents a null value to
        /// this interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// null opaque object could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the null opaque object was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddNullObject(
            ref Result error
            )
        {
            Result result = null;

            if (AddObject(
                    _Object.Null, null,
                    ObjectFlags.ForNullObject,
                    _ClientData.Empty, 0,
#if NATIVE && TCL
                    null,
#endif
#if DEBUGGER && DEBUGGER_ARGUMENTS
                    null,
#endif
                    null, ref result) != ReturnCode.Ok)
            {
                error = result;
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

