        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the opaque object with the specified token from this
        /// interpreter.  This is the private implementation that looks up and removes
        /// the opaque object.
        /// </summary>
        /// <param name="token">
        /// The token associated with the opaque object to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to force a synchronous garbage collection after
        /// disposing the wrapped value.
        /// </param>
        /// <param name="alias">
        /// Non-zero to also remove the command alias associated with the
        /// opaque object.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the removed opaque
        /// object.
        /// </param>
        /// <param name="dispose">
        /// On input, non-zero to request disposal of the wrapped value;
        /// upon return, non-zero if it was actually disposed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// opaque object could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the opaque object was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveObject(
            long token,
            IClientData clientData,
            bool synchronous,
            bool alias,
            ref string name,
            ref bool dispose,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasObjects(ref result))
                {
                    IObject @object = null;

                    if (PrivateGetObject(
                            token, LookupFlags.Remove, ref name,
                            ref @object, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemoveObject(
                            name, token, @object, clientData, synchronous,
                            alias, ref dispose, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

