        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named opaque object from this interpreter.  This is
        /// the private implementation that looks up and removes the opaque object.
        /// </summary>
        /// <param name="name">
        /// The name of the opaque object to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to force a synchronous garbage collection after
        /// disposing the wrapped value.
        /// </param>
        /// <param name="alias">
        /// Non-zero to also remove the command alias associated with the
        /// opaque object.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token of the removed opaque
        /// object.
        /// </param>
        /// <param name="dispose">
        /// On input, non-zero to request disposal of the wrapped value;
        /// upon return, non-zero if it was actually disposed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// opaque object could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the opaque object was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveObject(
            string name,
            IClientData clientData,
            bool synchronous,
            bool alias,
            ref long token,
            ref bool dispose,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasObjects(ref result))
                {
                    IObject @object = null;

                    if (PrivateGetObject(
                            name, LookupFlags.Remove, ref token,
                            ref @object, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemoveObject(
                            name, token, @object, clientData, synchronous,
                            alias, ref dispose, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes, and optionally disposes of, all unlocked opaque
        /// objects matching the specified pattern and reference-count constraint.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against opaque object names, or null to
        /// match all of them.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with each remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="referenceCount">
        /// The maximum reference count an opaque object may have to be
        /// eligible for removal, or a negative value to remove all
        /// matching unlocked opaque objects.
        /// </param>
        /// <param name="stopOnError">
        /// Non-zero to stop and return failure as soon as any opaque
        /// object cannot be removed.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to force a synchronous garbage collection after
        /// disposing each wrapped value.
        /// </param>
        /// <param name="dispose">
        /// On input, non-zero to request disposal of the wrapped values;
        /// upon return, non-zero if at least one was actually disposed.
        /// </param>
        /// <param name="result">
        /// Upon success, this is set to a list describing how many opaque
        /// objects were disposed and removed; upon failure, this is set to an
        /// error message.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the matching opaque objects were removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveObjects(
            string pattern,
            IClientData clientData,
            int referenceCount,
            bool stopOnError,
            bool synchronous,
            ref bool dispose,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasObjects(ref result))
                {
                    StringList keys = new StringList();

                    //
                    // NOTE: Cleanup, PASS #1, collect the list of keys we need to remove
                    //       from the objects collection in the containing interpreter.
                    //
                    foreach (__ObjectPair pair in objects)
                    {
                        string name = pair.Key;

                        if (name == null)
                            continue;

                        IObject @object = pair.Value;

                        if (@object == null)
                            continue;

                        //
                        // HACK: If the pattern specified by the caller is not null,
                        //       only those matching opaque object handles (by name)
                        //       will be removed and/or disposed.
                        //
                        if ((pattern != null) && !StringOps.Match(
                                this, StringOps.DefaultMatchMode, name,
                                pattern, false))
                        {
                            continue;
                        }

                        //
                        // HACK: Using a negative reference count here means that -ALL-
                        //       unlocked opaque object handles will be removed and/or
                        //       disposed.
                        //
                        if ((referenceCount >= 0) &&
                            (@object.ReferenceCount > referenceCount))
                        {
                            continue;
                        }

                        if (!FlagOps.HasFlags(
                                @object.ObjectFlags, ObjectFlags.Locked, true))
                        {
                            keys.Add(name);
                        }
                    }

                    int disposed = 0;

                    //
                    // NOTE: Cleanup, PASS #2, dispose and remove all the objects we found
                    //       from PASS #1 (above).
                    //
                    foreach (string key in keys)
                    {
                        bool localDispose = dispose;
                        Result localResult = null;

                        if ((RemoveObject(
                                key, clientData, synchronous, ref localDispose,
                                ref localResult) != ReturnCode.Ok) && stopOnError)
                        {
                            result = localResult;
                            return ReturnCode.Error;
                        }

                        //
                        // NOTE: At least one object has been disposed.
                        //
                        if (localDispose)
                            disposed++;
                    }

                    //
                    // NOTE: Inform the caller if any of the objects were disposed.
                    //
                    dispose = (disposed > 0);

                    //
                    // NOTE: Return the number of objects we disposed and removed.
                    //
                    result = StringList.MakeList(
                        "disposed", disposed, "removed", keys.Count);

                    return ReturnCode.Ok;
                }
            }

            return ReturnCode.Error;
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IPackage
        /// <summary>
        /// This method looks up a package by its token.
        /// </summary>
        /// <param name="token">
        /// The token associated with the package to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the package.
        /// </param>
        /// <param name="package">
        /// Upon success, this is set to the package that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// package could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the package was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetPackage(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IPackage package,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetPackage(
                        token, lookupFlags, ref name, ref package,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid package token {0}",
                            FormatOps.WrapOrNull(token)) :
                        "invalid package token";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

