                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes and adds the specified package to this interpreter.
        /// </summary>
        /// <param name="package">
        /// The package to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the package during initialization.
        /// This parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added package.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// package could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the package was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddPackage(
            IPackage package,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (package == null)
                {
                    result = "invalid package";
                    return ReturnCode.Error;
                }

                string name = package.Name;

                if (name == null)
                {
                    result = "invalid package name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasPackages(ref result))
                    return ReturnCode.Error;

                if (DoesPackageExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: package already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                ReturnCode code = ReturnCode.Ok;

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    try
                    {
                        try
                        {
                            code = package.Initialize(this,
                                (clientData != null) ? clientData : package.ClientData,
                                ref result);
                        }
                        catch (Exception e)
                        {
                            result = String.Format(
                                "caught exception while initializing package: {0}",
                                e);

                            code = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        ReturnCode terminateCode;
                        Result terminateResult = null;

                        terminateCode = TerminatePackage(
                            package, clientData, ref terminateResult);

                        if (terminateCode != ReturnCode.Ok)
                        {
                            DebugOps.Complain(
                                this, terminateCode, terminateResult);
                        }
                    }

                    if (code != ReturnCode.Ok)
                        return code;

                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(package);

                        wrapper = EntityOps.MaybeNewWrapperWith<PackageWrapper>(
                            id, package);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        packages.Add(name, wrapper as PackageWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(package, newToken);

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Package, NotifyFlags.Added,
                            new ObjectPair(package, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }

                return code;
            }
        }

