        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates and removes the specified package from this
        /// interpreter.  This is the private implementation behind the package removal
        /// methods.
        /// </summary>
        /// <param name="name">
        /// The name of the package to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the package to remove.
        /// </param>
        /// <param name="package">
        /// The package to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the package during termination.
        /// This parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// package could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the package was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemovePackage(
            string name,
            long token,
            IPackage package,
            IClientData clientData,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid package name";
                return ReturnCode.Error;
            }

            GlobalState.PushActiveInterpreter(this);

            try
            {
                if ((package == null) || (TerminatePackage(
                        package, clientData, ref result) == ReturnCode.Ok))
                {
                    packages.Remove(name, token);

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(
                        NotifyType.Package, NotifyFlags.Removed,
                        new ObjectTriplet(package, name, token), this,
                        clientData, null, null, ref result);
#endif

                    return ReturnCode.Ok;
                }

                return ReturnCode.Error;
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while removing package: {0}",
                    e);

                return ReturnCode.Error;
            }
            finally
            {
                /* IGNORED */
                GlobalState.PopActiveInterpreter();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the package with the specified token from this
        /// interpreter.
        /// </summary>
        /// <param name="token">
        /// The token associated with the package to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the package during termination.
        /// This parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the removed package.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// package could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the package was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemovePackage(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasPackages(ref result))
                {
                    IPackage package = null;

                    if (PrivateGetPackage(
                            token, LookupFlags.Remove, ref name,
                            ref package, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemovePackage(
                            name, token, package, clientData, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

