            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasPackages(ref result))
                {
                    IPackage package = null;

                    if (PrivateGetPackage(
                            name, LookupFlags.Remove, ref token,
                            ref package, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemovePackage(
                            name, token, package, clientData, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates the specified package, giving it a chance to release
        /// its resources.
        /// </summary>
        /// <param name="package">
        /// The package to terminate.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the package during termination.
        /// This parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// package could not be terminated.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the package was terminated; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode TerminatePackage(
            IPackage package,
            IClientData clientData,
            ref Result result
            )
        {
            if (package == null)
            {
                result = "invalid package";
                return ReturnCode.Error;
            }

            bool savedImmutable = BeginMutableExecution();

            ReturnCode code;

            try
            {
                code = package.Terminate(this,
                    (clientData != null) ? clientData : package.ClientData,
                    ref result);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Package, NotifyFlags.Terminated,
                    new ObjectTriplet(package, code), this,
                    clientData, null, null, ref result);
#endif
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while terminating package: {0}",
                    e);

                code = ReturnCode.Error;
            }
            finally
            {
                EndMutableExecution(savedImmutable);
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes all packages flagged as temporary that have not been
        /// loaded from this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The client data to pass to each package during termination.
        /// This parameter may be null.
        /// </param>
        /// <param name="tokens">
        /// Upon return, the tokens of the removed temporary packages are
        /// added to this list, which is created first if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why one or
        /// more temporary packages could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if all eligible temporary packages were removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveTemporaryPackages(
            IClientData clientData, /* in */
            ref LongList tokens,    /* in, out */
            ref Result error        /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                StringList list = null;

                foreach (PackagePair pair in packages)
                {
                    IPackage package = pair.Value;

                    if (package == null)
                        continue;

                    if (!FlagOps.HasFlags(package.Flags,
                            PackageFlags.Temporary, true))
                    {
                        continue;
                    }

                    Version loaded = package.Loaded;

                    if (loaded != null)
                    {
                        //
                        // HACK: It was temporary before; however,
                        //       now it has been loaded (somehow?)
                        //       and being promoted to persistent.
                        //
                        package.Flags &= ~PackageFlags.Temporary;
                        continue;
                    }

                    if (list == null)
                        list = new StringList();

                    list.Add(pair.Key);
                }

                ResultList errors = null;

                if (list != null)
                {
                    foreach (string element in list)
                    {
                        long token = 0;
                        Result localError = null;

                        if (InternalRemovePackage(
                                element, clientData, ref token,
                                ref localError) == ReturnCode.Ok)
                        {
                            if (tokens == null)
                                tokens = new LongList();

                            tokens.Add(token);
                        }
                        else
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(localError);
                        }
                    }
                }

                if (errors != null)
                {
                    error = errors;
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }
        #endregion
        #endregion

