        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a plugin by the name of the assembly that
        /// contains it.
        /// </summary>
        /// <param name="assemblyName">
        /// The name of the assembly that contains the plugin to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the plugin.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the plugin.
        /// </param>
        /// <param name="plugin">
        /// Upon success, this is set to the plugin that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetPlugin(
            AssemblyName assemblyName,
            LookupFlags lookupFlags,
            ref string name,
            ref long token,
            ref IPlugin plugin,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPlugins(ref error))
                    return ReturnCode.Error;

                if (plugins.Count == 0)
                {
                    error = "no plugins are loaded";
                    return ReturnCode.Error;
                }

                foreach (PluginPair pair in plugins)
                {
                    PluginWrapper wrapper = pair.Value;

                    if (wrapper == null)
                        continue;

                    if (!AssemblyOps.IsSameAssemblyName(
                            wrapper.AssemblyName, assemblyName))
                    {
                        continue;
                    }

                    if (!RuntimeOps.CheckPluginVersusLookupFlags(
                            wrapper, lookupFlags))
                    {
                        continue;
                    }

                    string localName = pair.Key;
                    long localToken = EntityOps.GetToken(wrapper);
                    IPlugin localPlugin;

                    if (FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Wrapper, true))
                    {
                        localPlugin = wrapper;
                    }
                    else
                    {
                        localPlugin = wrapper.plugin;
                    }

                    if ((localPlugin == null) && FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Validate, true))
                    {
                        error = "invalid plugin";
                        return ReturnCode.Error;
                    }

                    name = localName;
                    token = localToken;
                    plugin = localPlugin;

                    return ReturnCode.Ok;
                }

                error = FlagOps.HasFlags(
                    lookupFlags, LookupFlags.Verbose, true) ?
                    String.Format(
                        "invalid plugin assembly name {0}",
                        FormatOps.AssemblyName(
                            assemblyName, 0, false, true)) :
                    "invalid plugin assembly name";

                return ReturnCode.Error;
            }
        }

