        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetPlugin(
            Assembly assembly,
            LookupFlags lookupFlags,
            ref string name,
            ref long token,
            ref IPlugin plugin,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPlugins(ref error))
                    return ReturnCode.Error;

                if (plugins.Count == 0)
                {
                    error = "no plugins are loaded";
                    return ReturnCode.Error;
                }

                foreach (PluginPair pair in plugins)
                {
                    PluginWrapper wrapper = pair.Value;

                    if (wrapper == null)
                        continue;

                    if (!Object.ReferenceEquals(
                            wrapper.Assembly, assembly))
                    {
                        continue;
                    }

                    if (!RuntimeOps.CheckPluginVersusLookupFlags(
                            wrapper, lookupFlags))
                    {
                        continue;
                    }

                    string localName = pair.Key;
                    long localToken = EntityOps.GetToken(wrapper);
                    IPlugin localPlugin;

                    if (FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Wrapper, true))
                    {
                        localPlugin = wrapper;
                    }
                    else
                    {
                        localPlugin = wrapper.plugin;
                    }

                    if ((localPlugin == null) && FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Validate, true))
                    {
                        error = "invalid plugin";
                        return ReturnCode.Error;
                    }

                    name = localName;
                    token = localToken;
                    plugin = localPlugin;

                    return ReturnCode.Ok;
                }

                error = FlagOps.HasFlags(
                    lookupFlags, LookupFlags.Verbose, true) ?
                    String.Format(
                        "invalid plugin assembly {0}",
                        FormatOps.AssemblyName(
                            assembly, 0, false, true)) :
                    "invalid plugin assembly";

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a plugin whose name matches the specified
        /// pattern.
        /// </summary>
        /// <param name="name">
        /// The pattern to match against the names of the available plugins.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="plugin">
        /// Upon success, this is set to the first plugin whose name matched.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why no
        /// matching plugin could be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if a matching plugin was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode MatchPlugin(
            string name,
            LookupFlags lookupFlags,
            ref IPlugin plugin,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPlugins(ref error))
                    return ReturnCode.Error;

                if (plugins.Count == 0)
                {
                    error = "no plugins are loaded";
                    return ReturnCode.Error;
                }

                foreach (PluginPair pair in plugins)
                {
                    PluginWrapper wrapper = pair.Value;

                    if (wrapper == null)
                        continue;

                    if (!StringOps.Match(
                            this, MatchMode.Glob, pair.Key, name, false))
                    {
                        continue;
                    }

                    if (!RuntimeOps.CheckPluginVersusLookupFlags(
                            wrapper, lookupFlags))
                    {
                        continue;
                    }

                    IPlugin localPlugin;

                    if (FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Wrapper, true))
                    {
                        localPlugin = wrapper;
                    }
                    else
                    {
                        localPlugin = wrapper.plugin;
                    }

                    if ((localPlugin == null) && FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Validate, true))
                    {
                        error = "invalid plugin";
                        return ReturnCode.Error;
                    }

                    plugin = localPlugin;
                    return ReturnCode.Ok;
                }

                error = FlagOps.HasFlags(
                    lookupFlags, LookupFlags.Verbose, true) ?
                    String.Format(
                        "invalid plugin name {0}",
                        FormatOps.DisplayName(name)) :
                    "invalid plugin name";

                return ReturnCode.Error;
            }
        }

