        /// <summary>
        /// This method builds a list of the plugins matching the specified
        /// criteria.
        /// </summary>
        /// <param name="hasFlags">
        /// The plugin flags that must be present.
        /// </param>
        /// <param name="notHasFlags">
        /// The plugin flags that must not be present.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero if all the flags in hasFlags must be present; otherwise,
        /// any one of them is sufficient.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero if all the flags in notHasFlags must be present to exclude
        /// a plugin; otherwise, any one of them is sufficient.
        /// </param>
        /// <param name="pattern">
        /// The pattern to match against the plugin names, or null for all.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extra detail for each plugin in the resulting
        /// list.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat the absence of any plugins as an error.
        /// </param>
        /// <param name="list">
        /// Upon success, the matching plugins are added to this list, which is
        /// created first if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// operation could not be completed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built successfully; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode ListPlugins(
            PluginFlags hasFlags,
            PluginFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            bool strict,
            ref StringList list,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasPlugins(ref localError))
                {
                    code = plugins.ToList(
                        hasFlags, notHasFlags, hasAll, notHasAll,
                        pattern, noCase, full, ref list, ref error);
                }
                else if (strict)
                {
                    error = localError;
                }
                else
                {
                    if (list == null)
                        list = new StringList();

                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

