        /// <summary>
        /// This method creates a copy of the names of all the plugins currently
        /// present in this interpreter.
        /// </summary>
        /// <returns>
        /// Returns a new list containing the names of the plugins, or null if
        /// no plugins are available.
        /// </returns>
        internal StringList CopyPluginKeys()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (plugins != null)
                    return new StringList(plugins.Keys);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a copy of the collection of plugins currently
        /// present in this interpreter.
        /// </summary>
        /// <returns>
        /// Returns a copy of the plugin collection, or null if it is not
        /// available.
        /// </returns>
        internal PluginWrapperDictionary CopyPlugins()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (plugins != null)
                    return new PluginWrapperDictionary(plugins);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if NOTIFY || NOTIFY_OBJECT
#if ISOLATED_PLUGINS
        /// <summary>
        /// This method removes all the isolated (cross-AppDomain) plugins from
        /// the collection of plugins eligible for notifications.
        /// </summary>
        private void RemoveIsolatedNotifyPlugins()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int count = 0;

                if (notifyPlugins == null)
                    return;

                StringList keys = new StringList(notifyPlugins.Keys);

                foreach (string key in keys)
                {
                    if (key == null)
                        continue;

                    PluginWrapper pluginWrapper;

                    if (!notifyPlugins.TryGetValue(key, out pluginWrapper))
                        continue;

                    if (pluginWrapper == null)
                        continue;

                    if (!AppDomainOps.IsTransparentProxy(pluginWrapper))
                        continue;

                    if (notifyPlugins.Remove(key))
                        count++;
                }

                if ((plugins != null) && (count > 0))
                    notifyPlugins.TryCopyVersion(plugins);
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the collection of plugins eligible to receive
        /// notifications, rebuilding the cached copy when necessary.
        /// </summary>
        /// <returns>
        /// Returns the collection of plugins eligible for notifications, or
        /// null if no plugins are available.
        /// </returns>
        private PluginWrapperDictionary GetNotifyPlugins()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (plugins == null)
                {
                    if (notifyPlugins != null)
                    {
                        notifyPlugins.Clear();
                        notifyPlugins = null;
                    }

                    return null;
                }

                if ((notifyPlugins == null) ||
                    !notifyPlugins.TryMatchVersion(plugins))
                {
                    notifyPlugins = new PluginWrapperDictionary(plugins);

#if ISOLATED_PLUGINS
                    if (IsNoIsolatedNotify())
                        RemoveIsolatedNotifyPlugins();
#endif
                }

                return notifyPlugins;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a plugin by its token.  This is the private
        /// implementation that performs the actual lookup.
        /// </summary>
        /// <param name="token">
        /// The token associated with the plugin to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the plugin.
        /// </param>
        /// <param name="plugin">
        /// Upon success, this is set to the plugin that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetPlugin(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IPlugin plugin,
            ref Result error
            )
        {
            if (!PrivateHasPlugins(ref error))
                return ReturnCode.Error;

            PluginWrapper wrapper;

            if (!plugins.TryGetValue(token, out wrapper))
            {
                error = "plugin not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                plugin = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((plugin == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid plugin";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid plugin wrapper";
                    return ReturnCode.Error;
                }

                plugin = wrapper.plugin;
                name = EntityOps.GetName(plugin);

                if ((plugin == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid plugin";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a plugin by its name.  This is the private
        /// implementation that performs the actual lookup.
        /// </summary>
        /// <param name="name">
        /// The name of the plugin to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the plugin.
        /// </param>
        /// <param name="plugin">
        /// Upon success, this is set to the plugin that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetPlugin(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IPlugin plugin,
            ref Result error
            )
        {
            if (!PrivateHasPlugins(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid plugin name";
                return ReturnCode.Error;
            }

            PluginWrapper wrapper;

            if (!plugins.TryGetValue(name, out wrapper))
            {
                error = "plugin not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                plugin = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((plugin == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid plugin";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid plugin wrapper";
                    return ReturnCode.Error;
                }

                plugin = wrapper.plugin;
                token = EntityOps.GetToken(plugin);

                if ((plugin == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid plugin";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

