        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates and removes the specified plugin from this
        /// interpreter.  This is the private implementation behind the plugin
        /// removal methods.
        /// </summary>
        /// <param name="name">
        /// The name of the plugin to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the plugin to remove.
        /// </param>
        /// <param name="plugin">
        /// The plugin to remove.  This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the plugin during termination.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemovePlugin(
            string name,
            long token,
            IPlugin plugin,
            IClientData clientData,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid plugin name";
                return ReturnCode.Error;
            }

            GlobalState.PushActiveInterpreter(this);

            try
            {
                if ((plugin == null) || (TerminatePlugin(
                        plugin, clientData, ref result) == ReturnCode.Ok))
                {
                    plugins.Remove(name, token);

#if NOTIFY || NOTIFY_OBJECT
                    if (notifyPlugins != null)
                        notifyPlugins.Remove(name, token);
#endif

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(
                        NotifyType.Plugin, NotifyFlags.Removed,
                        new ObjectTriplet(plugin, name, token), this,
                        clientData, null, null, ref result);
#endif

                    return ReturnCode.Ok;
                }

                return ReturnCode.Error;
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while removing plugin: {0}",
                    e);

                return ReturnCode.Error;
            }
            finally
            {
                /* IGNORED */
                GlobalState.PopActiveInterpreter();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the plugin with the specified token from this
        /// interpreter.
        /// </summary>
        /// <param name="token">
        /// The token associated with the plugin to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the plugin during termination.  This
        /// parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the removed plugin.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemovePlugin(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasPlugins(ref result))
                {
                    IPlugin plugin = null;

                    if (PrivateGetPlugin(
                            token, LookupFlags.Remove, ref name,
                            ref plugin, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemovePlugin(
                            name, token, plugin, clientData, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named plugin from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the plugin to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the plugin during termination.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token of the removed plugin.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemovePlugin(
            string name,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasPlugins(ref result))
                {
                    IPlugin plugin = null;

                    if (PrivateGetPlugin(
                            name, LookupFlags.Remove, ref token,
                            ref plugin, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemovePlugin(
                            name, token, plugin, clientData, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates the specified plugin, giving it a chance to
        /// release its resources.
        /// </summary>
        /// <param name="plugin">
        /// The plugin to terminate.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the plugin during termination.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be terminated.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was terminated; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode TerminatePlugin(
            IPlugin plugin,
            IClientData clientData,
            ref Result result
            )
        {
            if (plugin == null)
            {
                result = "invalid plugin";
                return ReturnCode.Error;
            }

            bool savedImmutable = BeginMutableExecution();

            ReturnCode code;

            try
            {
                code = plugin.Terminate(this,
                    (clientData != null) ? clientData : plugin.ClientData,
                    ref result);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Plugin, NotifyFlags.Terminated,
                    new ObjectTriplet(plugin, code), this,
                    clientData, null, null, ref result);
#endif
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while terminating plugin: {0}",
                    e);

                code = ReturnCode.Error;
            }
            finally
            {
                EndMutableExecution(savedImmutable);
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the specified plugin, terminating it again
        /// if initialization fails.
        /// </summary>
        /// <param name="plugin">
        /// The plugin to initialize.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the plugin during initialization.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be initialized.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was initialized; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode InitializePlugin(
            IPlugin plugin,
            IClientData clientData,
            ref Result result
            )
        {
            if (plugin == null)
            {
                result = "invalid plugin";
                return ReturnCode.Error;
            }

            ReturnCode code = ReturnCode.Ok;

            try
            {
                GlobalState.PushActiveInterpreter(this);

                try
                {
                    IClientData addClientData;

                    GetClientDataForAddPlugin(
                        plugin, clientData, out addClientData);

                    code = plugin.Initialize(
                        this, addClientData, ref result);

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(
                        NotifyType.Plugin, NotifyFlags.Initialized,
                        new ObjectTriplet(plugin, code), this,
                        clientData, null, null, ref result);
#endif
                }
                catch (Exception e)
                {
                    result = String.Format(
                        "caught exception while initializing plugin: {0}",
                        e);

                    code = ReturnCode.Error;
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }
            finally
            {
                if (code != ReturnCode.Ok)
                {
                    ReturnCode terminateCode;
                    Result terminateResult = null;

                    terminateCode = TerminatePlugin(
                        plugin, clientData, ref terminateResult);

                    if (terminateCode != ReturnCode.Ok)
                    {
                        DebugOps.Complain(this,
                            terminateCode, terminateResult);
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes and adds the specified plugin to this
        /// interpreter.  This is the private implementation behind the plugin
        /// add methods.
        /// </summary>
        /// <param name="plugin">
        /// The plugin to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the plugin during initialization.  This
        /// parameter may be null.
        /// </param>
        /// <param name="noInitialize">
        /// Non-zero to skip initializing the plugin before it is added.
        /// </param>
        /// <param name="noNotify">
        /// Non-zero to skip sending the added notification for the plugin.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added plugin.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// plugin could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugin was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateAddPlugin(
            IPlugin plugin,
            IClientData clientData,
            bool noInitialize,
            bool noNotify,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (plugin == null)
                {
                    result = "invalid plugin";
                    return ReturnCode.Error;
                }

                string name = plugin.Name;

                if (name == null)
                {
                    result = "invalid plugin name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasPlugins(ref result))
                    return ReturnCode.Error;

                if (PrivateDoesPluginExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: plugin already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                ReturnCode code;

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    if (noInitialize)
                    {
                        code = ReturnCode.Ok;
                    }
                    else
                    {
                        code = InitializePlugin(
                            plugin, clientData, ref result);
                    }

                    if (code != ReturnCode.Ok)
                        return code;

                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(plugin);

                        wrapper = EntityOps.MaybeNewWrapperWith<PluginWrapper>(
                            id, plugin);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        plugins.Add(name, wrapper as PluginWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(plugin, newToken);

#if NOTIFY
                        if (!noNotify)
                        {
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Plugin, NotifyFlags.Added,
                                new ObjectPair(plugin, newToken), this,
                                clientData, null, null, ref result);
                        }
#endif

                        if (!noInitialize)
                        {
                            /* NO RESULT */
                            plugin.PostInitialize(
                                this, clientData); /* throw */
                        }

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                catch (Exception e)
                {
                    result = e;
                    code = ReturnCode.Error;
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes and adds each plugin in the specified list
        /// to this interpreter.
        /// </summary>
        /// <param name="plugins">
        /// The list of plugins to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to each plugin during initialization.  This
        /// parameter may be null.
        /// </param>
        /// <param name="noInitialize">
        /// Non-zero to skip initializing each plugin before it is added.
        /// </param>
        /// <param name="noNotify">
        /// Non-zero to skip sending the added notification for each plugin.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why a
        /// plugin could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if all the plugins were added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddPlugins(
            PluginList plugins,     /* in */
            IClientData clientData, /* in */
            bool noInitialize,      /* in */
            bool noNotify,          /* in */
            ref Result error        /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (plugins == null)
                {
                    error = "invalid plugin list";
                    return ReturnCode.Error;
                }

                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (!PrivateHasPlugins(ref error))
                    return ReturnCode.Error;

                foreach (IPlugin plugin in plugins)
                {
                    long token = 0; /* NOT USED */
                    Result result = null;

                    if (PrivateAddPlugin(plugin,
                            clientData, noInitialize,
                            noNotify, ref token,
                            ref result) != ReturnCode.Ok)
                    {
                        error = result;
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes and adds the plugins, if any, carried by the
        /// specified client data to this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The client data that may carry the list of plugins to add.
        /// </param>
        /// <param name="noInitialize">
        /// Non-zero to skip initializing each plugin before it is added.
        /// </param>
        /// <param name="noNotify">
        /// Non-zero to skip sending the added notification for each plugin.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why a
        /// plugin could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the plugins were added or there were none to add; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode MaybeAddPlugins(
            IClientData clientData, /* in */
            bool noInitialize,      /* in */
            bool noNotify,          /* in */
            ref Result error        /* out */
            )
        {
            if (clientData == null)
            {
                error = "invalid clientData";
                return ReturnCode.Error;
            }

            PluginList plugins = clientData.Data as PluginList;

            if (plugins == null)
                return ReturnCode.Ok;

            return AddPlugins(
                plugins, clientData, noInitialize, noNotify,
                ref error);
        }
        #endregion
        #endregion

