        /// <param name="name">
        /// The name of the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the command.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetCommand(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref ICommand command,
            ref Result error
            )
        {
            CheckDisposed();

            return InternalGetCommand(
                name, lookupFlags, ref token, ref command, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its name, verifying that it
        /// belongs to the specified plugin.
        /// </summary>
        /// <param name="plugin">
        /// The plugin that the command is required to belong to.  This
        /// parameter may be null, in which case the ownership check is skipped.
        /// </param>
        /// <param name="name">
        /// The name of the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the command.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found and belongs to the plugin; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetCommandForPlugin(
            IPlugin plugin,
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref ICommand command,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot)
            {
                long localToken = 0;
                ICommand localCommand = null;

                if (InternalGetCommand(name, lookupFlags,
                        ref localToken, ref localCommand,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (localToken == 0)
                {
                    error = "command has invalid token";
                    return ReturnCode.Error;
                }

                if (plugin != null)
                {
                    LongList tokens = plugin.CommandTokens;

                    if (tokens == null)
                    {
                        error = "plugin is missing command tokens";
                        return ReturnCode.Error;
                    }

                    if (!tokens.Contains(localToken))
                    {
                        error = "command token is not for plugin";
                        return ReturnCode.Error;
                    }
                }

                token = localToken;
                command = localCommand;

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the commands matching the specified
        /// criteria.
        /// </summary>
        /// <param name="hasFlags">
        /// The command flags that must be present.
        /// </param>
        /// <param name="notHasFlags">
        /// The command flags that must not be present.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero if all the flags in hasFlags must be present; otherwise,
        /// any one of them is sufficient.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero if all the flags in notHasFlags must be present to exclude
        /// a command; otherwise, any one of them is sufficient.
        /// </param>
        /// <param name="pattern">
        /// The pattern to match against the command names, or null for all.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extra detail for each command in the resulting
        /// list.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat the absence of any commands as an error.
        /// </param>
        /// <param name="list">
        /// Upon success, the matching commands are added to this list, which is
        /// created first if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// operation could not be completed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built successfully; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode ListCommands(
            CommandFlags hasFlags,
            CommandFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            bool strict,
            ref StringList list,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasCommands(ref localError))
                {
                    if (InternalAreNamespacesEnabled())
                    {
                        INamespace currentNamespace = null;

                        code = GetCurrentNamespaceViaResolvers(
                            null, LookupFlags.Default, ref currentNamespace,
                            ref error);

                        if (code == ReturnCode.Ok)
                        {
                            StringList[] localLists = { null, null };

                            code = commands.ToList(
                                hasFlags, notHasFlags, hasAll, notHasAll,
                                null, false, full, ref localLists[0],
                                ref error);

                            if (code == ReturnCode.Ok)
                            {
                                code = MatchItems(
                                    currentNamespace, pattern, noCase,
                                    ref localLists, ref error);

                                if (list == null)
                                    list = localLists[1];
                                else
                                    list.AddRange(localLists[1]);
                            }
                        }
                    }
                    else
                    {
                        pattern = ScriptOps.MakeCommandName(pattern);

                        code = commands.ToList(
                            hasFlags, notHasFlags, hasAll, notHasAll,
                            pattern, noCase, full, ref list, ref error);
                    }
                }
                else if (strict)
                {
                    error = localError;
                }
                else
                {
                    if (list == null)
                        list = new StringList();

                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

