            return AddExecuteCallback(
                name, callback, clientData, null, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a sub-command backed by the specified execute
        /// callback and adds it to the specified command.
        /// </summary>
        /// <param name="name">
        /// The name to use for the new sub-command.
        /// </param>
        /// <param name="command">
        /// The command to which the new sub-command will be added.
        /// </param>
        /// <param name="callback">
        /// The execute callback that will implement the sub-command.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new sub-command.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// This parameter receives the token associated with the new
        /// sub-command, if available.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// sub-command could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the sub-command was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddExecuteCallback(
            string name,
            ICommand command,
            ExecuteCallback callback,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            //
            // NOTE: In order to add/replace the sub-command, both the name
            //       and command itself must be valid.
            //
            if (name == null)
            {
                result = "invalid sub-command name";
                return ReturnCode.Error;
            }

            if (command == null)
            {
                result = "invalid command";
                return ReturnCode.Error;
            }

            EnsembleDictionary subCommands = command.SubCommands;

            if (subCommands == null)
            {
                result = "sub-commands not available";
                return ReturnCode.Error;
            }

            //
            // NOTE: Synthesize a sub-command out of the clear blue sky and
            //       populate it with the callback supplied by the user.  We
            //       do not bother checking if the supplied callback is valid
            //       because we do not actually care.  The worst case is that
            //       the engine will call the Execute method of the default
            //       sub-command created here, which does nothing.
            //
            ISubCommand subCommand = ScriptOps.NewDefaultSubCommand(
                name, clientData, command, SubCommandFlags.None, null,
                DelegateFlags.None);

            subCommand.Callback = callback;
            subCommands[name] = subCommand;

#if ARGUMENT_CACHE
            /* IGNORED */
            MaybeClearArgumentCache(name);
#endif

            return ReturnCode.Ok;
        }

