        /// <summary>
        /// This method creates a command backed by the specified execute
        /// callback, using the specified plugin, sub-commands, and command
        /// flags, and adds it to this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name to use for the new command.
        /// </param>
        /// <param name="callback">
        /// The execute callback that will implement the command.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new command.  This parameter
        /// may be null.
        /// </param>
        /// <param name="plugin">
        /// The plugin to associate with the new command.  This parameter may be
        /// null.
        /// </param>
        /// <param name="subCommands">
        /// The sub-commands to associate with the new command.  This parameter
        /// may be null.
        /// </param>
        /// <param name="commandFlags">
        /// The command flags to use for the new command.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added command.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddExecuteCallback(
            string name,
            ExecuteCallback callback,
            IClientData clientData,
            IPlugin plugin,
            EnsembleDictionary subCommands,
            CommandFlags commandFlags,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            //
            // NOTE: Synthesize a command out of the clear blue sky and
            //       populate it with the callback supplied by the user.
            //       We do not bother checking if the supplied callback
            //       is valid because we do not actually care.  In the
            //       worst case, the engine will call the Execute method
            //       of the default command created here, which does not
            //       do anything.
            //
            ICommand command = new _Commands.Default(new CommandData(
                ScriptOps.MakeCommandName(name), null, null, clientData,
                typeof(_Commands.Default).FullName, commandFlags, plugin,
                0));

            command.Callback = callback;

            if (subCommands != null)
            {
                IEnsemble ensemble = command as IEnsemble;

                if (ensemble != null)
                    ensemble.SubCommands = subCommands;
            }

            return AddCommand(command, clientData, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds a command for each execute callback in the
        /// specified collection to this interpreter.
        /// </summary>
        /// <param name="collection">
        /// The collection of execute callback data used to create the commands.
        /// </param>
        /// <param name="plugin">
        /// The plugin to associate with each new command.  This parameter may
        /// be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with each new command.  This parameter
        /// may be null.
        /// </param>
        /// <param name="ignoreNull">
        /// Non-zero to silently skip null elements in the collection.
        /// </param>
        /// <param name="stopOnError">
        /// Non-zero to stop processing as soon as an error is encountered.
        /// </param>
        /// <param name="errorCount">
        /// This is incremented by the number of errors that were encountered.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message, or list of error
        /// messages, describing the errors that were encountered.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the callbacks were processed without a fatal error; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddExecuteCallbacks(
            IEnumerable<IExecuteCallbackData> collection, /* in */
            IPlugin plugin,                               /* in */
            IClientData clientData,                       /* in */
            bool ignoreNull,                              /* in */
            bool stopOnError,                             /* in */
            ref int errorCount,                           /* in, out */
            ref Result result                             /* out */
            )
        {
            CheckDisposed();

            if (collection == null)
            {
                result = "invalid enumerable";
                return ReturnCode.Error;
            }

            ReturnCode code = ReturnCode.Ok;
            ResultList results = null;

            foreach (IExecuteCallbackData executeData in collection)
            {
                if (executeData == null)
                {
                    if (!ignoreNull)
                    {
                        errorCount++;

                        if (results == null)
                            results = new ResultList();

                        results.Add("invalid execute callback data");

                        if (stopOnError)
                        {
                            code = ReturnCode.Error;
                            break;
                        }
                    }

                    continue;
                }

                long token = executeData.Token;

                if (token != 0) /* NOTE: Refuse to overwrite. */
                {
                    errorCount++;

                    if (results == null)
                        results = new ResultList();

                    results.Add("invalid execute callback token");

                    if (stopOnError)
                    {
                        code = ReturnCode.Error;
                        break;
                    }

                    continue;
                }

                Result localResult = null;

                code = AddExecuteCallback(
                    executeData.Name, executeData.Callback,
                    executeData.ClientData, plugin, ref token,
                    ref localResult);

                if (localResult != null)
                {
                    localResult.ReturnCode = code;

                    if (results == null)
                        results = new ResultList();

                    results.Add(localResult);
                }

                if (code == ReturnCode.Ok)
                {
                    executeData.Token = token;
                }
                else
                {
                    errorCount++;

                    if (stopOnError)
                        break;
                    else
                        code = ReturnCode.Ok;
                }
            }

            if (results != null)
                result = results;

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if EMIT
        /// <summary>
        /// This method creates and adds an automatically generated command for
        /// each of the specified typed instances to this interpreter.
        /// </summary>
        /// <param name="plugin">
        /// The plugin to associate with each new command.  This parameter may
        /// be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with each new command.  This parameter
        /// may be null.
        /// </param>
        /// <param name="typedInstances">
        /// The typed instances to create commands for.
        /// </param>
        /// <param name="mapper">
        /// The delegate mapper to use; when null, a temporary one is created.
        /// </param>
        /// <param name="bindingFlags">
        /// The binding flags to use when reflecting over the instance types.
        /// This parameter may be null.
        /// </param>
        /// <param name="marshalFlags">
        /// The marshalling flags to use.  This parameter may be null.
        /// </param>
        /// <param name="delegateFlags">
        /// The delegate flags to use.  This parameter may be null.
        /// </param>
        /// <param name="safe">
        /// Non-zero if the created commands should be safe for use in a safe
        /// interpreter; this parameter may be null.
        /// </param>
        /// <param name="count">
        /// This is increased by the number of delegate methods that were
        /// loaded.
        /// </param>
        /// <param name="tokens">
        /// Upon success, the tokens of the newly added commands are added to
        /// this list, which is created first if necessary.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// commands could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the commands were added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddAutomaticCommands(
            IPlugin plugin,                            /* in */
            IClientData clientData,                    /* in */
            IEnumerable<TypedInstance> typedInstances, /* in */
            IDelegateMapper mapper,                    /* in */
            BindingFlags? bindingFlags,                /* in */
            MarshalFlags? marshalFlags,                /* in */
            DelegateFlags? delegateFlags,              /* in */
            bool? safe,                                /* in */
            ref long count,                            /* in, out */
            ref LongList tokens,                       /* in, out */
            ref Result result                          /* out */
            )
        {
            CheckDisposed();

            if (typedInstances == null)
            {
                result = "invalid typed instances";
                return ReturnCode.Error;
            }

            typedInstances = ScriptOps.GetUnique(typedInstances);

            if (typedInstances == null)
            {
                result = "invalid unique typed instances";
                return ReturnCode.Error;
            }

            bool success = false;
            bool created = false;
            IDelegateMapper localMapper = null;

            try
            {
                if (mapper != null)
                {
                    localMapper = mapper;
                }
                else
                {
                    created = true;
                    localMapper = new DelegateMapper();
                }

                int localCount = 0;

                foreach (TypedInstance typedInstance in typedInstances)
                {
                    string name = typedInstance.ObjectName;

                    if (name == null)
                        name = typedInstance.FullObjectName;

                    if (name == null)
                        continue;

                    if (localMapper.Load(
                            MarshalOps.GetType(typedInstance), bindingFlags,
                            marshalFlags, delegateFlags, false, ref localCount,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    ICommand command = ScriptOps.NewAutomaticCommand(
                        name, clientData, plugin, typedInstance, localMapper,
                        safe);

                    long token = 0;

                    if (AddCommand(command,
                            clientData, ref token, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    if (tokens == null)
                        tokens = new LongList();

                    tokens.Add(token);
                }

                count += localCount;
                success = (localCount > 0);

                return ReturnCode.Ok;
            }
            finally
            {
                if (!success && created && (localMapper != null))
                {
                    localMapper.Dispose();
                    localMapper = null;
                }
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a sub-command backed by the specified script
        /// command and adds it to the specified command.
        /// </summary>
        /// <param name="name">
        /// The name to use for the new sub-command.
        /// </param>
        /// <param name="command">
        /// The command to which the new sub-command will be added.
        /// </param>
        /// <param name="scriptCommand">
        /// The script command to invoke for the sub-command.  This parameter
        /// may be null.
        /// </param>
        /// <param name="nameIndex">
        /// The argument index of the sub-command name; null to use the default.
        /// This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new sub-command.  This
        /// parameter may be null.
        /// </param>
        /// <param name="subCommandFlags">
        /// The sub-command flags to use for the new sub-command.
        /// </param>
        /// <param name="token">
        /// This parameter receives the token associated with the new
        /// sub-command, if available.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// sub-command could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the sub-command was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddSubCommand(
            string name,
            ICommand command,
            StringList scriptCommand,
            int? nameIndex,
            IClientData clientData,
            SubCommandFlags subCommandFlags,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            //
            // NOTE: In order to add/replace the sub-command, both the name
            //       and command itself must be valid.
            //
            if (name == null)
            {
                result = "invalid sub-command name";
                return ReturnCode.Error;
            }

            if (command == null)
            {
                result = "invalid command";
                return ReturnCode.Error;
            }

            EnsembleDictionary subCommands = command.SubCommands;

            if (subCommands == null)
            {
                result = "sub-commands not available";
                return ReturnCode.Error;
            }

            int localNameIndex;

            if (nameIndex != null)
                localNameIndex = (int)nameIndex;
            else
                localNameIndex = ScriptOps.GetSubCommandNameIndex();

            ISubCommand subCommand = ScriptOps.NewCommandSubCommand(
                name, clientData, command, scriptCommand, localNameIndex,
                subCommandFlags);

            subCommands[name] = subCommand;

#if ARGUMENT_CACHE
            /* IGNORED */
            MaybeClearArgumentCache(name);
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes and adds the specified command to this
        /// interpreter.
        /// </summary>
        /// <param name="command">
        /// The command to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the command during initialization.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added command.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddCommand(
            ICommand command,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (command == null)
                {
                    result = "invalid command";
                    return ReturnCode.Error;
                }

                string name = command.Name;

                if (name == null)
                {
                    result = "invalid command name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasCommands(ref result))
                    return ReturnCode.Error;

                //
                // WARNING: Currently, if somebody adds an ICommand that shadows an
                //          IExecute or procedure (by name), it will basically be
                //          ignored in favor of the IExecute or procedure, which
                //          have higher priority.  This behavior could be prevented
                //          here by changing this check to be DoesAnyExecuteExist
                //          instead of DoesCommandExist; however, I am not convinced
                //          that task should be the responsibility of this method
                //          (i.e. why should a method that deals with commands need
                //          to know about IExecute or procedure objects?).  The spirit
                //          of this check is basically "can we physically add the
                //          object in question?".
                //
                /* EXEMPT */
                if (FlagOps.HasFlags(interpreterFlags,
                        InterpreterFlags.DoesAnythingExist, true))
                {
                    if (InternalDoesIExecuteExistViaResolvers(name) == ReturnCode.Ok)
                    {
                        result = String.Format(
                            "can't add {0}: something already exists",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                }
                else
                {
                    if (DoesCommandExist(name) == ReturnCode.Ok)
                    {
                        result = String.Format(
                            "can't add {0}: command already exists",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                }

                Result localError = null;

                if (InternalAreNamespacesEnabled() && (NamespaceOps.LookupParent(
                        this, name, false, true, true, ref localError) == null))
                {
                    result = String.Format(
                        "can't add command {0}: {1}",
                        FormatOps.WrapOrNull(name),
                        localError);

                    return ReturnCode.Error;
                }

                ReturnCode code = ReturnCode.Ok;

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    try
                    {
                        try
                        {
                            code = command.Initialize(this,
                                (clientData != null) ? clientData : command.ClientData,
                                ref result);
                        }
                        catch (Exception e)
                        {
                            result = String.Format(
                                "caught exception while initializing command: {0}",
                                e);

                            code = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        if (code != ReturnCode.Ok)
                        {
                            ReturnCode terminateCode;
                            Result terminateResult = null;

                            terminateCode = TerminateCommand(
                                command, clientData, ref terminateResult);

                            if (terminateCode != ReturnCode.Ok)
                            {
                                DebugOps.Complain(
                                    this, terminateCode, terminateResult);
                            }
                        }
                    }

                    if (code != ReturnCode.Ok)
                        return code;

                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(command);

                        wrapper = EntityOps.MaybeNewWrapperWith<CommandWrapper>(
                            id, command);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        //
                        // NOTE: Are we allowed to assist in managing the command
                        //       token via the associated plugin?
                        //
                        long newToken = EntityOps.GetToken(wrapper); /* throw */

                        if (!EntityOps.IsNoToken(command))
                        {
                            //
                            // NOTE: Store the command token so that we can remove
                            //       them later without using their names (which
                            //       can change).
                            //
                            IPluginData pluginData = command.Plugin;

                            if (pluginData != null)
                            {
                                LongList tokens = pluginData.CommandTokens;

                                if ((tokens != null) && !tokens.Contains(newToken))
                                {
                                    tokens.Add(newToken);

#if ISOLATED_PLUGINS
                                    //
                                    // HACK: Force the command tokens for the
                                    //       isolated plugin to be updated.
                                    //
                                    if (AppDomainOps.IsIsolated(pluginData))
                                        pluginData.CommandTokens = tokens;
#endif
                                }
                            }
                        }

                        EntityOps.SetToken(command, newToken);

                        commands.Add(name, wrapper as CommandWrapper);
                        success = true;

#if EXECUTE_CACHE
                        AddOrUpdateIExecuteToCache(name, command, false, false);
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(name);
#endif

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Command, NotifyFlags.Added,
                            new ObjectPair(command, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }

                return code;
            }
        }

