        /// <summary>
        /// This method removes the commands with the specified tokens from this
        /// interpreter.
        /// </summary>
        /// <param name="tokens">
        /// The tokens identifying the commands to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to each command during removal.  This
        /// parameter may be null.
        /// </param>
        /// <param name="stopOnError">
        /// Non-zero to stop processing as soon as an error is encountered.
        /// </param>
        /// <param name="failOnError">
        /// Non-zero to return an error result when any command could not be
        /// removed.
        /// </param>
        /// <param name="names">
        /// Upon return, the names of the removed commands are added to this
        /// list, which is created first if necessary.
        /// </param>
        /// <param name="errors">
        /// Upon failure, the encountered errors are added to this list, which
        /// is created first if necessary.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if all the commands were removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RemoveCommands(
            IEnumerable<long> tokens, /* in */
            IClientData clientData,   /* in: OPTIONAL */
            bool stopOnError,         /* in */
            bool failOnError,         /* in */
            ref StringList names,     /* in, out */
            ref ResultList errors     /* in, out */
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (tokens == null)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add("invalid command tokens");
                    return ReturnCode.Error;
                }

                int errorCount = 0;

                foreach (long token in tokens)
                {
                    if (token == 0) // BUGBUG: Should be impossible.
                        continue;

                    string name = null;
                    Result result = null;

                    if (PrivateRemoveAllIExecute(
                            token, clientData, true, true, false,
                            ref name, ref result) == ReturnCode.Ok)
                    {
                        if (names == null)
                            names = new StringList();

                        names.Add(name);
                    }
                    else
                    {
                        errorCount++;

                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(result);

                        if (stopOnError)
                            return ReturnCode.Error;
                    }
                }

                return !failOnError || (errorCount == 0) ?
                    ReturnCode.Ok : ReturnCode.Error;
            }
        }

