        /// </param>
        /// <param name="failOnError">
        /// Non-zero to return an error result when any command could not be
        /// removed.
        /// </param>
        /// <param name="tokens">
        /// Upon return, the tokens of the removed commands are added to this
        /// list, which is created first if necessary.
        /// </param>
        /// <param name="errors">
        /// Upon failure, the encountered errors are added to this list, which
        /// is created first if necessary.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if all the commands were removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RemoveCommands(
            IEnumerable<string> names, /* in */
            IClientData clientData,    /* in: OPTIONAL */
            bool stopOnError,          /* in */
            bool failOnError,          /* in */
            ref LongList tokens,       /* in, out */
            ref ResultList errors      /* in, out */
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (names == null)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add("invalid command names");
                    return ReturnCode.Error;
                }

                int errorCount = 0;

                foreach (string name in names)
                {
                    if (name == null)
                        continue;

                    long token = 0;
                    Result result = null;

                    if (PrivateRemoveAllIExecute(
                            name, clientData, true, true, false,
                            ref token, ref result) == ReturnCode.Ok)
                    {
                        if (tokens == null)
                            tokens = new LongList();

                        tokens.Add(token);
                    }
                    else
                    {
                        errorCount++;

                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(result);

                        if (stopOnError)
                            return ReturnCode.Error;
                    }
                }

                return !failOnError || (errorCount == 0) ?
                    ReturnCode.Ok : ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command whose name exactly or uniquely
        /// matches the specified name.
        /// </summary>
        /// <param name="engineFlags">
        /// The engine flags that control the matching, including whether hidden
        /// commands are considered.
        /// </param>
        /// <param name="name">
        /// The command name to match.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="ambiguous">
        /// Upon return, this is set to non-zero if the name matched more than
        /// one command.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the matched
        /// command.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was matched.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why no
        /// single command could be matched.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if exactly one command matched; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode MatchCommand(
            EngineFlags engineFlags,
            string name,
            LookupFlags lookupFlags,
            ref bool ambiguous,
            ref long token,
            ref ICommand command,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool useHidden = EngineFlagOps.HasUseHidden(engineFlags);
                bool matchHidden = EngineFlagOps.HasMatchHidden(engineFlags);

                CommandWrapperDictionary localCommands =
                    useHidden ? hiddenCommands : commands;

                if (localCommands != null)
                {
                    //
                    // NOTE: *WARNING* Empty command/procedure names are allowed,
                    //       please do not change this to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        if (localCommands.Count > 0)
                        {
                            CommandWrapper localCommand;
                            string exactName = null;
                            StringList list = new StringList();

                            if (localCommands.TryGetValue(name, out localCommand) &&
                                (matchHidden || !EntityOps.IsHidden(localCommand)))
                            {
                                //
                                // NOTE: Exact command match.
                                //
                                exactName = name;

                                //
                                // NOTE: Store the exact command match in the result
                                //       list.
                                //
                                list.Add(name);
                            }
                            else
                            {
                                foreach (CommandPair pair in localCommands)
                                {
                                    if (SharedStringOps.SystemEquals(pair.Key, 0, name, 0, name.Length))
                                    {
                                        //
                                        // NOTE: Is the command visible or are we allowed to
                                        //       find hidden command?
                                        //
                                        if (matchHidden || !EntityOps.IsHidden(pair.Value))
                                        {
                                            //
                                            // NOTE: Was the key valid (this should always succeed).
                                            //
                                            if (pair.Key != null)
                                            {
                                                //
                                                // NOTE: It was a match; however, was it an exact match?
                                                //
                                                if (pair.Key.Length == name.Length)
                                                    //
                                                    // NOTE: Preserve match, it may differ in case.
                                                    //
                                                    exactName = pair.Key;

                                                //
                                                // NOTE: Was it an exact match or did we match at least one
                                                //       character in a partial match?
                                                //
                                                if ((pair.Key.Length == name.Length) || (name.Length > 0))
                                                    //
                                                    // NOTE: Store the exact or partial match in the results
                                                    //       dictionary.
                                                    //
                                                    list.Add(pair.Key);
                                            }
                                        }
                                    }
                                }
                            }

                            //
                            // NOTE: If there was an exact match, just use it.
                            //
                            if (exactName != null)
                            {
                                //
                                // NOTE: No need to change the caller's variable,
                                //       it already contains the correct value.
                                //
                                if ((useHidden && PrivateGetHiddenCommand(
                                        exactName, lookupFlags, ref token,
                                        ref command, ref error) == ReturnCode.Ok) ||
                                    (!useHidden && PrivateGetCommand(
                                        exactName, lookupFlags, ref token,
                                        ref command, ref error) == ReturnCode.Ok))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        useHidden ? NotifyType.HiddenCommand : NotifyType.Command,
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, exactName, command, token), this, null, null,
                                        null, ref error);
#endif

                                    return ReturnCode.Ok;
                                }
                            }
                            else if (list.Count == 1)
                            {
                                //
                                // NOTE: Normal case, exactly one command matched.
                                //
                                if ((useHidden && PrivateGetHiddenCommand(
                                        list[0], lookupFlags, ref token,
                                        ref command, ref error) == ReturnCode.Ok) ||
                                    (!useHidden && PrivateGetCommand(
                                        list[0], lookupFlags, ref token,
                                        ref command, ref error) == ReturnCode.Ok))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        useHidden ? NotifyType.HiddenCommand : NotifyType.Command,
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, list[0], command, token), this, null, null,
                                        null, ref error);
#endif

                                    return ReturnCode.Ok;
                                }
                            }
                            else if (list.Count > 1)
                            {
                                error = FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Verbose, true) ?
                                    ScriptOps.BadValue(
                                        "ambiguous", "command", name, list,
                                        null, null) :
                                    (Result)"ambiguous command";

                                ambiguous = true;
                            }
                            else
                            {
                                error = FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Verbose, true) ?
                                    ScriptOps.BadValue(
                                        null, "command", name, localCommands.Keys,
                                        null, null) :
                                    (Result)"bad command";
                            }
                        }
                        else
                        {
                            error = "no commands defined";
                        }
                    }
                    else
                    {
                        error = "invalid command name";
                    }
                }
                else
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "{0}commands not available",
                            useHidden ? "hidden " : String.Empty) :
                        "commands not available";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method exchanges the active and saved command collections
        /// selected by the specified flags.
        /// </summary>
        /// <param name="swapFlags">
        /// The flags selecting which command collections to swap.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command collections could not be swapped.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command collections were swapped; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode SwapCommands(
            SwapFlags swapFlags,
            ref Result error
            )
        {
            CheckDisposed();

            StringList list = null;

            return SwapCommands(swapFlags, ref list, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method exchanges the active and saved command collections
        /// selected by the specified flags.
        /// </summary>
        /// <param name="swapFlags">
        /// The flags selecting which command collections to swap.
        /// </param>
        /// <param name="list">
        /// Upon return, the names of the swapped collections and their commands
        /// are added to this list.  This parameter may be null.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command collections could not be swapped.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command collections were swapped; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode SwapCommands(
            SwapFlags swapFlags,
            ref StringList list,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (FlagOps.HasFlags(swapFlags, SwapFlags.Command, true))
                {
                    CommandWrapperDictionary swapCommands;

                    swapCommands = commands;
                    commands = savedCommands;
                    savedCommands = swapCommands;

                    if ((list != null) && (commands != null))
                    {
                        list.Add("commands");
                        list.Add(new StringList(commands.Keys).ToString());
                    }
                }

                if (FlagOps.HasFlags(swapFlags, SwapFlags.HiddenCommand, true))
                {
                    CommandWrapperDictionary swapHiddenCommands;

                    swapHiddenCommands = hiddenCommands;
                    hiddenCommands = savedHiddenCommands;
                    savedHiddenCommands = swapHiddenCommands;

                    if ((list != null) && (hiddenCommands != null))
                    {
                        list.Add("hiddenCommands");
                        list.Add(new StringList(hiddenCommands.Keys).ToString());
                    }
                }

                if (FlagOps.HasFlags(swapFlags, SwapFlags.IExecute, true))
                {
                    ExecuteWrapperDictionary swapExecutes;

                    swapExecutes = executes;
                    executes = savedExecutes;
                    savedExecutes = swapExecutes;

                    if ((list != null) && (executes != null))
                    {
                        list.Add("executes");
                        list.Add(new StringList(executes.Keys).ToString());
                    }
                }

                if (FlagOps.HasFlags(swapFlags, SwapFlags.HiddenIExecute, true))
                {
                    ExecuteWrapperDictionary swapHiddenExecutes;

                    swapHiddenExecutes = hiddenExecutes;
                    hiddenExecutes = savedHiddenExecutes;
                    savedHiddenExecutes = swapHiddenExecutes;

                    if ((list != null) && (hiddenExecutes != null))
                    {
                        list.Add("hiddenExecutes");
                        list.Add(new StringList(hiddenExecutes.Keys).ToString());
                    }
                }

#if EXECUTE_CACHE
                /* IGNORED */
                ClearExecuteCache();
#endif

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes a previously saved (swapped) command, identified
        /// by its token, from this interpreter.
        /// </summary>
        /// <param name="token">
        /// The token identifying the saved command to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the command during termination.  This
        /// parameter may be null.
        /// </param>
        /// <param name="swapFlags">
        /// The flags that control how the saved command is removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// saved command could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the saved command was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RemoveSwapCommand(
            long token,             /* in */
            IClientData clientData, /* in */
            SwapFlags swapFlags,    /* in */
            ref Result result       /* out */
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (token == 0)
                {
                    result = "invalid token";
                    return ReturnCode.Error;
                }

                if (savedCommands == null)
                {
                    result = "saved commands unavailable";
                    return ReturnCode.Error;
                }

                CommandWrapper command;

                if (!savedCommands.TryGetValue(token, out command))
                {
                    result = String.Format(
                        "saved command {0} not found", token);

                    return ReturnCode.Error;
                }

                string name = EntityOps.GetName(command);

                if (name == null)
                {
                    result = String.Format(
                        "invalid saved command {0} name", token);

                    return ReturnCode.Error;
                }

                if (!FlagOps.HasFlags(
                        swapFlags, SwapFlags.NoTerminate, true) &&
                    TerminateCommand(command,
                        clientData, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                /* IGNORED */
                savedCommands.Remove(name, token);

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method builds a list of the commands matching the specified
        /// criteria, without regard to namespaces.
        /// </summary>
        /// <param name="hasFlags">
        /// The command flags that must be present.
        /// </param>
        /// <param name="notHasFlags">
        /// The command flags that must not be present.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero if all the flags in hasFlags must be present; otherwise,
        /// any one of them is sufficient.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero if all the flags in notHasFlags must be present to exclude
        /// a command; otherwise, any one of them is sufficient.
        /// </param>
        /// <param name="pattern">
        /// The pattern to match against the command names, or null for all.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extra detail for each command in the resulting
        /// list.
        /// </param>
        /// <param name="list">
        /// Upon success, the matching commands are added to this list, which is
        /// created first if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// operation could not be completed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built successfully; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode CommandsToList(
            CommandFlags hasFlags,
            CommandFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (commands != null)
                {
                    return commands.ToList(
                        hasFlags, notHasFlags, hasAll, notHasAll,
                        pattern, noCase, full, ref list, ref error);
                }
            }

            error = "commands not available";
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the commands that expose sub-commands
        /// (i.e. ensembles) and match the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against the command names, or null for all.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="list">
        /// Upon success, the matching command names are added to this list,
        /// which is created first if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// operation could not be completed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was built successfully; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListEnsembleCommands(
            string pattern,
            bool noCase,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (commands != null)
                {
                    StringList localList = new StringList();

                    foreach (CommandPair pair in commands)
                    {
                        ICommand command = pair.Value;

                        if (command == null)
                            continue;

                        //
                        // BUGFIX: Do not include aliases, e.g. to [object invoke].
                        //
                        if (FlagOps.HasFlags(command.Flags, CommandFlags.Alias, true))
                            continue;

                        EnsembleDictionary subCommands = PolicyOps.GetSubCommandsUnsafe(
                            command); /* COUNT ONLY */

                        if ((subCommands != null) && (subCommands.Count > 0))
                            localList.Add(pair.Key);
                    }

                    bool absolute = false;

                    pattern = NamespaceOps.TrimLeading(pattern, ref absolute);

                    if (absolute || !InternalAreNamespacesEnabled())
                    {
                        if (pattern == null)
                        {
                            list = localList;
                        }
                        else
                        {
                            if (list == null)
                                list = new StringList();

                            foreach (string element in localList)
                            {
                                if (StringOps.Match(
                                        this, MatchMode.Glob, element,
                                        pattern, noCase))
                                {
                                    list.Add(element);
                                }
                            }
                        }

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        bool qualified = NamespaceOps.IsQualifiedName(pattern);

                        return NamespaceOps.MatchItems(
                            this, null, localList, pattern, noCase,
                            false, !qualified, qualified, false,
                            ref list, ref error);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the command names whose read-only state
        /// matches the specified value.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against the command names.  This parameter may
        /// be null.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="readOnly">
        /// The read-only state that a command must have to be included.
        /// </param>
        /// <returns>
        /// Returns a list of the matching command names.
        /// </returns>
        internal StringList GetCommandsReadOnly(
            string pattern,
            bool noCase,
            bool readOnly
            )
        {
            StringList result = new StringList();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (commands != null)
                {
                    foreach (CommandPair pair in commands)
                    {
                        ICommand command = pair.Value;

                        if (command == null)
                            continue;

                        if ((pattern != null) && !StringOps.Match(
                                this, StringOps.DefaultMatchMode, pair.Key,
                                pattern, noCase))
                        {
                            continue;
                        }

                        if (EntityOps.IsReadOnly(command) == readOnly)
                            result.Add(pair.Key);
                    }
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the read-only state of all the commands matching
        /// the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match against the command names.  This parameter may
        /// be null.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="readOnly">
        /// The read-only state to set on the matching commands.
        /// </param>
        /// <returns>
        /// Returns the number of commands whose read-only state was changed.
        /// </returns>
        internal int SetCommandsReadOnly(
            string pattern,
            bool noCase,
            bool readOnly
            )
        {
            int result = 0;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (commands != null)
                {
                    foreach (CommandPair pair in commands)
                    {
                        ICommand command = pair.Value;

                        if (command == null)
                            continue;

                        if ((pattern != null) && !StringOps.Match(
                                this, StringOps.DefaultMatchMode, pair.Key,
                                pattern, noCase))
                        {
                            continue;
                        }

                        if (EntityOps.IsReadOnly(command) == readOnly)
                            continue;

                        if (EntityOps.SetReadOnly(command, readOnly))
                            result++;
                    }
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its token.  This is the private
        /// implementation that performs the actual lookup.
        /// </summary>
        /// <param name="token">
        /// The token associated with the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the command.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetCommand(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref ICommand command,
            ref Result error
            )
        {
            if (!PrivateHasCommands(ref error))
                return ReturnCode.Error;

            CommandWrapper wrapper;

            if (!commands.TryGetValue(token, out wrapper))
            {
                error = "command not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                command = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid command wrapper";
                    return ReturnCode.Error;
                }

                command = wrapper.command;
                name = EntityOps.GetName(command);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its name.  This is the private
        /// implementation that performs the actual lookup.
        /// </summary>
        /// <param name="name">
        /// The name of the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the command.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetCommand(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref ICommand command,
            ref Result error
            )
        {
            if (!PrivateHasCommands(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid command name";
                return ReturnCode.Error;
            }

            CommandWrapper wrapper;

            if (!commands.TryGetValue(name, out wrapper))
            {
                error = "command not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                command = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid command wrapper";
                    return ReturnCode.Error;
                }

                command = wrapper.command;
                token = EntityOps.GetToken(command);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its name, formatting an
        /// appropriate error message on failure.
        /// </summary>
        /// <param name="name">
        /// The name of the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the command.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalGetCommand(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref ICommand command,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetCommand(
                        name, lookupFlags, ref token, ref command,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid command name {0}",
                            FormatOps.DisplayName(name)) :
                        "invalid command name";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its token, discarding the name and
        /// any error message.
        /// </summary>
        /// <param name="token">
        /// The token associated with the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetCommand(
            long token,
            LookupFlags lookupFlags,
            ref ICommand command
            )
        {
            Result error = null;

            return GetCommand(token, lookupFlags, ref command, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its token, discarding the name.
        /// </summary>
        /// <param name="token">
        /// The token associated with the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetCommand(
            long token,
            LookupFlags lookupFlags,
            ref ICommand command,
            ref Result error
            )
        {
            string name = null;

            return GetCommand(token, lookupFlags, ref name, ref command, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its name, discarding the token and
        /// any error message.
        /// </summary>
        /// <param name="name">
