        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a command by its type, searching both the
        /// visible and hidden commands.
        /// </summary>
        /// <param name="type">
        /// The type of the command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the command.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the command.
        /// </param>
        /// <param name="command">
        /// Upon success, this is set to the command that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetCommand(
            Type type,
            LookupFlags lookupFlags,
            ref string name,
            ref long token,
            ref ICommand command,
            ref Result error
            )
        {
            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if ((code != ReturnCode.Ok) && PrivateHasCommands() &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Visible, true))
                {
                    if ((type != null) && (commands.Count > 0))
                    {
                        foreach (CommandPair pair in commands)
                        {
                            CommandWrapper wrapper = pair.Value;

                            if (wrapper == null)
                                continue;

                            if (type.IsInstanceOfType(wrapper.command))
                            {
                                name = pair.Key;

                                if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
                                    command = wrapper;
                                else
                                    command = wrapper.command;

                                token = EntityOps.GetToken(wrapper);

                                if ((command != null) ||
                                    !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                                {
                                    code = ReturnCode.Ok;
                                }

                                break;
                            }
                        }
                    }
                }

                if ((code != ReturnCode.Ok) && PrivateHasHiddenCommands() &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Invisible, true))
                {
                    if ((type != null) && (hiddenCommands.Count > 0))
                    {
                        foreach (CommandPair pair in hiddenCommands)
                        {
                            CommandWrapper wrapper = pair.Value;

                            if (wrapper == null)
                                continue;

                            if (type.IsInstanceOfType(wrapper.command))
                            {
                                name = pair.Key;

                                if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
                                    command = wrapper;
                                else
                                    command = wrapper.command;

                                token = EntityOps.GetToken(wrapper);

                                if ((command != null) ||
                                    !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                                {
                                    code = ReturnCode.Ok;
                                }

                                break;
                            }
                        }
                    }
                }

                if (code != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid command type {0}",
                            FormatOps.TypeName(type)) :
                        "invalid command type";
                }
            }

            return code;
        }

