        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames a command.  This is the private implementation
        /// behind the command rename methods.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the command.
        /// </param>
        /// <param name="newName">
        /// The new name for the command.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to skip namespace-aware processing during the rename.
        /// </param>
        /// <param name="delete">
        /// Non-zero to permit deleting the command when the new name is null or
        /// empty.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be renamed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was renamed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameCommand(
            string oldName,
            string newName,
            bool noNamespaces,
            bool delete,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasCommands(ref result))
                {
                    if (!delete || !String.IsNullOrEmpty(newName))
                    {
                        ICommand oldCommand = null;

                        if (GetCommand(oldName, LookupFlags.Default, ref oldCommand, ref result) == ReturnCode.Ok)
                        {
                            if (!EntityOps.IsReadOnly(oldCommand))
                            {
                                if (EntityOps.IsNoRename(oldCommand))
                                    return ReturnCode.Ok;

                                CommandWrapper oldWrapper = oldCommand as CommandWrapper;

                                if (oldWrapper != null)
                                {
                                    IAlias oldAlias = oldWrapper.command as IAlias;

                                    if (PreventAliasLoop(oldAlias, newName, ref result) == ReturnCode.Ok)
                                    {
                                        if (IsValidAnyIExecuteName(newName, noNamespaces, ref result) == ReturnCode.Ok)
                                        {
                                            bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();

                                            if (!useNamespaces ||
                                                RenameImportInNamespaces(oldName, newName, ref result) == ReturnCode.Ok)
                                            {
                                                //
                                                // NOTE: New name, same token.
                                                //
                                                oldWrapper.Name = newName;

                                                /* IGNORED */
                                                commands.Rename(oldName, newName);

#if EXECUTE_CACHE
                                                RenameIExecuteInCache(oldName, newName, oldWrapper, false, false);
#endif

#if ARGUMENT_CACHE
                                                /* IGNORED */
                                                MaybeClearArgumentCache(oldName);

                                                /* IGNORED */
                                                MaybeClearArgumentCache(newName);
#endif

#if NOTIFY
                                                /* IGNORED */
                                                CheckNotification(
                                                    NotifyType.Command, NotifyFlags.Renamed,
                                                    new ObjectTriplet(oldCommand, oldName, newName), this,
                                                    null, null, null, ref result);
#endif

                                                result = String.Empty;
                                                return ReturnCode.Ok;
                                            }
                                        }
                                    }
                                }
                                else
                                {
                                    result = String.Format(
                                        "can't rename {0}: invalid command wrapper",
                                        FormatOps.WrapOrNull(oldName));
                                }
                            }
                            else
                            {
                                result = String.Format(
                                    "can't rename {0}: command is read-only",
                                    FormatOps.WrapOrNull(oldName));
                            }
                        }
                        else
                        {
                            result = String.Format(
                                "can't rename {0}: command doesn't exist",
                                FormatOps.WrapOrNull(oldName));
                        }
                    }
                    else
                    {
                        return RemoveCommand(oldName, null, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates and removes the specified command from this
        /// interpreter.  This is the private implementation behind the command
        /// removal methods.
        /// </summary>
        /// <param name="name">
        /// The name of the command to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the command to remove.
        /// </param>
        /// <param name="command">
        /// The command to remove.  This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the command during termination.  This
        /// parameter may be null.
        /// </param>
        /// <param name="hidden">
        /// Non-zero if the command being removed is a hidden command.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveCommand(
            string name,
            long token,
            ICommand command,
            IClientData clientData,
            bool hidden,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid command name";
                return ReturnCode.Error;
            }

            GlobalState.PushActiveInterpreter(this);

            try
            {
                if (InternalAreNamespacesEnabled() &&
                    RemoveImportFromNamespaces(name, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (
#if NATIVE && TCL
                    ((command == null) ||
                    (DisposeTclBridges(IntPtr.Zero, command, null, false, ref result) == ReturnCode.Ok)) &&
#endif
                    ((command == null) ||
                    (TerminateCommand(command, clientData, ref result) == ReturnCode.Ok)))
                {
                    if (hidden)
                        /* IGNORED */
                        hiddenCommands.Remove(name, token);
                    else
                        /* IGNORED */
                        commands.Remove(name, token);

#if EXECUTE_CACHE
                    RemoveIExecuteFromCache(name, hidden, false);
#endif

#if ARGUMENT_CACHE
                    /* IGNORED */
                    MaybeClearArgumentCache(name);
#endif

                    if (command != null)
                    {
                        //
                        // NOTE: Are we allowed to assist in managing the command
                        //       token via the associated plugin?
                        //
                        bool noToken = EntityOps.IsNoToken(command);

                        if (!noToken)
                        {
                            //
                            // NOTE: If this command is being managed by a plugin,
                            //       remove the associated token from said plugin.
                            //
                            IPluginData pluginData = command.Plugin;

                            if (pluginData != null)
                            {
                                LongList tokens = pluginData.CommandTokens;

                                if ((tokens != null) && tokens.Contains(token))
                                {
                                    tokens.Remove(token);

#if ISOLATED_PLUGINS
                                    //
                                    // HACK: Force the command tokens for the
                                    //       isolated plugin to be updated.
                                    //
                                    if (AppDomainOps.IsIsolated(pluginData))
                                        pluginData.CommandTokens = tokens;
#endif
                                }
                            }
                        }
                    }

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(hidden ?
                        NotifyType.HiddenCommand : NotifyType.Command,
                        NotifyFlags.Removed, new ObjectTriplet(command,
                            name, token), this, clientData, null, null,
                        ref result);
#endif

                    return ReturnCode.Ok;
                }

                return ReturnCode.Error;
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while removing {0}command: {1}",
                    hidden ? "hidden " : String.Empty, e);

                return ReturnCode.Error;
            }
            finally
            {
                /* IGNORED */
                GlobalState.PopActiveInterpreter();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the command with the specified token from this
        /// interpreter.
        /// </summary>
        /// <param name="token">
        /// The token associated with the command to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the command during removal.  This
        /// parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the removed command.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveCommand(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasCommands(ref result))
                {
                    ICommand command = null;

                    if (PrivateGetCommand(
                            token, LookupFlags.Remove, ref name,
                            ref command, ref result) == ReturnCode.Ok)
                    {
                        if (!EntityOps.IsReadOnly(command))
                        {
                            if (EntityOps.IsNoRemove(command))
                                return ReturnCode.Ok;

                            return PrivateRemoveCommand(
                                name, token, command, clientData,
                                false, ref result);
                        }
                        else
                        {
                            result = "command is read-only";
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named command from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the command to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the command during removal.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token of the removed command.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveCommand(
            string name,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasCommands(ref result))
                {
                    ICommand command = null;

                    if (InternalGetCommand(
                            name, LookupFlags.Remove, ref token,
                            ref command, ref result) == ReturnCode.Ok)
                    {
                        if (!EntityOps.IsReadOnly(command))
                        {
                            if (EntityOps.IsNoRemove(command))
                                return ReturnCode.Ok;

                            return PrivateRemoveCommand(
                                name, token, command, clientData,
                                false, ref result);
                        }
                        else
                        {
                            result = "command is read-only";
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the commands matching the specified flags from
        /// this interpreter, discarding the removed command count.
        /// </summary>
        /// <param name="clientData">
        /// The client data to pass to each command during removal.  This
        /// parameter may be null.
        /// </param>
        /// <param name="hasFlags">
        /// The command flags that must be present; this parameter may be null.
        /// </param>
        /// <param name="notHasFlags">
        /// The command flags that must not be present; this parameter may be
        /// null.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero if all the flags in hasFlags must be present; otherwise,
        /// any one of them is sufficient.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero if all the flags in notHasFlags must be present to exclude
        /// a command; otherwise, any one of them is sufficient.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why a
        /// command could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if all the matching commands were removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RemoveCommands(
            IClientData clientData,
            CommandFlags? hasFlags,
            CommandFlags? notHasFlags,
            bool hasAll,
            bool notHasAll,
            ref Result error
            )
        {
            int count = 0; /* NOT USED */

            return RemoveCommands(
                clientData, hasFlags, notHasFlags, hasAll, notHasAll,
                ref count, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the commands matching the specified flags from
        /// this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The client data to pass to each command during removal.  This
        /// parameter may be null.
        /// </param>
        /// <param name="hasFlags">
        /// The command flags that must be present; this parameter may be null.
        /// </param>
        /// <param name="notHasFlags">
        /// The command flags that must not be present; this parameter may be
        /// null.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero if all the flags in hasFlags must be present; otherwise,
        /// any one of them is sufficient.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero if all the flags in notHasFlags must be present to exclude
        /// a command; otherwise, any one of them is sufficient.
        /// </param>
        /// <param name="count">
        /// This is increased by the number of commands that were removed.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why a
        /// command could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if all the matching commands were removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveCommands(
            IClientData clientData,
            CommandFlags? hasFlags,
            CommandFlags? notHasFlags,
            bool hasAll,
            bool notHasAll,
            ref int count,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                // if (!IsModifiable(false, ref error))
                //     return ReturnCode.Error;

                if (!PrivateHasCommands(ref error))
                    return ReturnCode.Error;

                LongList tokens = null;

                foreach (CommandPair pair in commands)
                {
                    ICommand command = pair.Value;

                    if (command == null)
                        continue;

                    CommandFlags commandFlags = command.Flags;

                    if ((hasFlags != null) && !FlagOps.HasFlags(
                            commandFlags, (CommandFlags)hasFlags,
                            hasAll))
                    {
                        continue;
                    }

                    if ((notHasFlags != null) && FlagOps.HasFlags(
                            commandFlags, (CommandFlags)notHasFlags,
                            notHasAll))
                    {
                        continue;
                    }

                    if (tokens == null)
                        tokens = new LongList();

                    tokens.Add(command.Token);
                }

                if (tokens != null)
                {
                    ResultList errors = null;

                    foreach (long token in tokens)
                    {
                        string name = null; /* NOT USED */
                        Result result = null;

                        if (InternalRemoveCommand(
                                token, clientData, ref name,
                                ref result) == ReturnCode.Ok)
                        {
                            count++;
                        }
                        else
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(result);
                        }
                    }

                    if (errors != null)
                    {
                        error = errors;
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates the specified command, giving it a chance to
        /// release its resources.
        /// </summary>
        /// <param name="command">
        /// The command to terminate.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the command during termination.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be terminated.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was terminated; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode TerminateCommand(
            ICommand command,
            IClientData clientData,
            ref Result result
            )
        {
            if (command == null)
            {
                result = "invalid command";
                return ReturnCode.Error;
            }

            bool savedImmutable = BeginMutableExecution();

            ReturnCode code;

            try
            {
                code = command.Terminate(this,
                    (clientData != null) ? clientData : command.ClientData,
                    ref result);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Command, NotifyFlags.Terminated,
                    new ObjectTriplet(command, code), this,
                    clientData, null, null, ref result);
#endif
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while terminating command: {0}",
                    e);

                code = ReturnCode.Error;
            }
            finally
            {
                EndMutableExecution(savedImmutable);
            }

            return code;
        }
        #endregion
        #endregion

