        #region ISubCommand
#if EMIT
        /// <summary>
        /// This method creates a sub-command for each suitable delegate method
        /// of the specified type (or object) and adds them, as a single
        /// command, to this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name to use for the new command.
        /// </param>
        /// <param name="type">
        /// The type to reflect over for delegate methods.  This parameter is
        /// optional when an object is supplied.
        /// </param>
        /// <param name="object">
        /// The object to reflect over for delegate methods.  This parameter is
        /// optional when a type is supplied.
        /// </param>
        /// <param name="plugin">
        /// The plugin to associate with the new command.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new command and its
        /// sub-commands.  This parameter may be null.
        /// </param>
        /// <param name="nameCallback">
        /// The callback used to generate the name for each sub-command.  This
        /// parameter may be null.
        /// </param>
        /// <param name="delegateFlags">
        /// The delegate flags that control how the delegate methods are
        /// discovered and created.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added command.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddSubCommands(
            string name,                          /* in */
            Type type,                            /* in: OPTIONAL with "object" */
            object @object,                       /* in: OPTIONAL with "type" */
            IPlugin plugin,                       /* in: OPTIONAL */
            IClientData clientData,               /* in: OPTIONAL */
            NewDelegateNameCallback nameCallback, /* in: OPTIONAL */
            DelegateFlags delegateFlags,          /* in */
            ref long token,                       /* out */
            ref Result result                     /* out */
            )
        {
            CheckDisposed();

            if (name == null)
            {
                result = "invalid command name";
                return ReturnCode.Error;
            }

            if (@object != null)
            {
                Type objectType = AppDomainOps.MaybeGetType(@object);

                if (type != null)
                {
                    if ((objectType != null) &&
                        !MarshalOps.IsSameTypeName(objectType, type))
                    {
                        result = String.Format(
                            "object type {0} does not match type {1}",
                            FormatOps.TypeName(objectType),
                            FormatOps.TypeName(type));

                        return ReturnCode.Error;
                    }
                }
                else
                {
                    type = objectType;
                }
            }

            if (type == null)
            {
                result = "invalid type";
                return ReturnCode.Error;
            }

            ResultList errors; /* REUSED */
            MethodInfoList methodInfoList = null;

            errors = null;

            if (RuntimeOps.GetDelegateMethods(
                    type, delegateFlags, ref methodInfoList,
                    ref errors) != ReturnCode.Ok)
            {
                result = errors;
                return ReturnCode.Error;
            }

            DelegateDictionary delegates = null;

            errors = null;

            if (RuntimeOps.CreateDelegates(
                    this, type, @object, methodInfoList,
                    nameCallback, clientData, delegateFlags,
                    ref delegates, ref errors) != ReturnCode.Ok)
            {
                result = errors;
                return ReturnCode.Error;
            }

            return AddSubCommands(
                name, delegates, plugin, clientData, delegateFlags,
                ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a sub-command for each delegate in the specified
        /// dictionary and adds them, as a single command, to this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name to use for the new command.
        /// </param>
        /// <param name="delegates">
        /// The dictionary of named delegates used to create the sub-commands.
        /// </param>
        /// <param name="plugin">
        /// The plugin to associate with the new command.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new command and its
        /// sub-commands.  This parameter may be null.
        /// </param>
        /// <param name="delegateFlags">
        /// The delegate flags that control how the sub-commands are created.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added command.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// command could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the command was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddSubCommands(
            string name,                  /* in */
            DelegateDictionary delegates, /* in */
            IPlugin plugin,               /* in: OPTIONAL */
            IClientData clientData,       /* in: OPTIONAL */
            DelegateFlags delegateFlags,  /* in */
            ref long token,               /* out */
            ref Result result             /* out */
            )
        {
            CheckDisposed();

            if (name == null)
            {
                result = "invalid command name";
                return ReturnCode.Error;
            }

            if (delegates == null)
            {
                result = "invalid delegates";
                return ReturnCode.Error;
            }

            ICommand command = ScriptOps.NewSubDelegateCommand(
                name, clientData, plugin);

            EnsembleDictionary subCommands = new EnsembleDictionary();

            foreach (DelegatePair pair in delegates)
            {
                ISubCommand subCommand = ScriptOps.NewDefaultSubCommand(
                    pair.Key, clientData, command, SubCommandFlags.None,
                    pair.Value, delegateFlags);

                subCommands[pair.Key] = subCommand;
            }

            command.SubCommands = subCommands;

            return AddCommand(command, clientData, ref token, ref result);
        }
#endif
        #endregion

