        /// <summary>
        /// This method creates a policy backed by the specified execute
        /// callback and adds it to this interpreter.
        /// </summary>
        /// <param name="callback">
        /// The execute callback that will implement the policy.
        /// </param>
        /// <param name="plugin">
        /// The plugin to associate with the new policy.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new policy.  This parameter
        /// may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added policy.
        /// </param>
        /// <param name="result">
        /// Upon success, this is set to the name of the newly added policy;
        /// upon failure, this is set to an error message describing why the
        /// policy could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the policy was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddPolicy(
            ExecuteCallback callback,
            IPlugin plugin,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            IPolicy policy = PolicyOps.NewCore(
                callback, clientData, PolicyFlags.None, plugin,
                ref result);

            if (policy != null)
            {
                if (AddPolicy(
                        policy, clientData, ref token,
                        ref result) == ReturnCode.Ok)
                {
                    result = policy.Name;
                    return ReturnCode.Ok;
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified policy to this interpreter.
        /// </summary>
        /// <param name="policy">
        /// The policy to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new policy.  This parameter
        /// may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added policy.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// policy could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the policy was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddPolicy(
            IPolicy policy,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (policy == null)
                {
                    result = "invalid policy";
                    return ReturnCode.Error;
                }

                string name = policy.Name;

                if (name == null)
                {
                    result = "invalid policy name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasPolicies(ref result))
                    return ReturnCode.Error;

                if (DoesPolicyExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: policy already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(policy);

                        wrapper = EntityOps.MaybeNewWrapperWith<PolicyWrapper>(
                            id, policy);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        //
                        // NOTE: Are we allowed to assist in managing the policy
                        //       token via the associated plugin?
                        //
                        long newToken = EntityOps.GetToken(wrapper);

                        if (!EntityOps.IsNoToken(policy))
                        {
                            //
                            // NOTE: Store the policy token so that we can remove
                            //       them later without using their names (which
                            //       can change).
                            //
                            IPluginData pluginData = policy.Plugin;

                            if (pluginData != null)
                            {
                                LongList tokens = pluginData.PolicyTokens;

                                if ((tokens != null) && !tokens.Contains(newToken))
                                {
                                    tokens.Add(newToken);

#if ISOLATED_PLUGINS
                                    //
                                    // HACK: Force the policy tokens for the
                                    //       isolated plugin to be updated.
                                    //
                                    if (AppDomainOps.IsIsolated(pluginData))
                                        pluginData.PolicyTokens = tokens;
#endif
                                }
                            }
                        }

                        EntityOps.SetToken(policy, newToken);

                        policies.Add(name, wrapper as PolicyWrapper);
                        success = true;

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Policy, NotifyFlags.Added,
                            new ObjectPair(policy, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

