        /// <summary>
        /// This method looks up a policy by its token.  This is the private
        /// implementation that performs the actual lookup.
        /// </summary>
        /// <param name="token">
        /// The token associated with the policy to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the policy.
        /// </param>
        /// <param name="policy">
        /// Upon success, this is set to the policy that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// policy could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the policy was found; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetPolicy(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IPolicy policy,
            ref Result error
            )
        {
            if (!PrivateHasPolicies(ref error))
                return ReturnCode.Error;

            PolicyWrapper wrapper;

            if (!policies.TryGetValue(token, out wrapper))
            {
                error = "policy not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                policy = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((policy == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid policy";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid policy wrapper";
                    return ReturnCode.Error;
                }

                policy = wrapper.policy;
                name = EntityOps.GetName(policy);

                if ((policy == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid policy";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

