        /// The name of the file the policy script was read from.  This
        /// parameter may be null.
        /// </param>
        /// <param name="plugin">
        /// The plugin to associate with the new policy.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new policy.  This parameter
        /// may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// policy could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the policy was added; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddScriptPolicy(
            PolicyFlags flags,
            Type commandType,
            long commandToken,
            Interpreter policyInterpreter,
            string text,
            string fileName,
            IPlugin plugin,
            IClientData clientData,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                IScriptPolicy scriptPolicy = ScriptPolicy.Create(
                    flags, commandType, commandToken, policyInterpreter,
                    cultureInfo, text, fileName, ref result);

                if (scriptPolicy == null)
                    return ReturnCode.Error;

                long token = 0;

                return AddScriptPolicy(
                    scriptPolicy, plugin, clientData, ref token,
                    ref result);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the specified policy from this interpreter.
        /// This is the private implementation behind the policy removal
        /// methods.
        /// </summary>
        /// <param name="name">
        /// The name of the policy to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the policy to remove.
        /// </param>
        /// <param name="policy">
        /// The policy to remove.  This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the policy during removal.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// policy could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the policy was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemovePolicy(
            string name,
            long token,
            IPolicy policy,
            IClientData clientData,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid policy name";
                return ReturnCode.Error;
            }

            policies.Remove(name, token);

            if (policy != null)
            {
                //
                // NOTE: Are we allowed to assist in managing the policy
                //       token via the associated plugin?
                //
                bool noToken = EntityOps.IsNoToken(policy);

                if (!noToken)
                {
                    //
                    // NOTE: If this policy is being managed by a plugin,
                    //       remove the associated token from said plugin.
                    //
                    IPluginData pluginData = policy.Plugin;

                    if (pluginData != null)
                    {
                        LongList tokens = pluginData.PolicyTokens;

                        if ((tokens != null) && tokens.Contains(token))
                        {
                            tokens.Remove(token);

#if ISOLATED_PLUGINS
                            //
                            // HACK: Force the policy tokens for the
                            //       isolated plugin to be updated.
                            //
                            if (AppDomainOps.IsIsolated(pluginData))
                                pluginData.PolicyTokens = tokens;
#endif
                        }
                    }
                }
            }

#if NOTIFY
            /* IGNORED */
            CheckNotification(
                NotifyType.Policy, NotifyFlags.Removed,
                new ObjectTriplet(policy, name, token), this,
                clientData, null, null, ref result);
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the policy with the specified token from this
        /// interpreter.
        /// </summary>
        /// <param name="token">
        /// The token associated with the policy to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to pass to the policy during removal.  This
        /// parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the removed policy.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// policy could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the policy was removed; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemovePolicy(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasPolicies(ref result))
                {
                    IPolicy policy = null;

                    if (PrivateGetPolicy(
                            token, LookupFlags.Remove, ref name,
                            ref policy, ref result) == ReturnCode.Ok)
                    {
                        if (!EntityOps.IsReadOnly(policy))
                        {
                            return PrivateRemovePolicy(
                                name, token, policy, clientData, ref result);
                        }
                        else
                        {
                            result = "policy is read-only";
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }

