        #region ITrace
        /// <summary>
        /// This method looks up a trace by its token.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the trace to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the trace that was
        /// found.
        /// </param>
        /// <param name="trace">
        /// Upon success, this is set to the trace that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// trace could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the trace was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetTrace(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref ITrace trace,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetTrace(
                        token, lookupFlags, ref name, ref trace,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid trace token {0}",
                            FormatOps.WrapOrNull(token)) :
                        "invalid trace token";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

