        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: All traces added via this method overload are global (i.e.
        //       interpreter-wide).
        //
        /// <summary>
        /// This method creates a new global (interpreter-wide) trace from
        /// the specified callback and adds it to this interpreter.
        /// </summary>
        /// <param name="callback">
        /// The trace callback delegate to be invoked.
        /// </param>
        /// <param name="plugin">
        /// The plugin associated with the new trace.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the new trace.  This parameter
        /// may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added trace.
        /// </param>
        /// <param name="result">
        /// Upon success, this is set to the name of the newly added trace;
        /// upon failure, this is set to an error message describing why the
        /// trace could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the trace was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddTrace(
            TraceCallback callback,
            IPlugin plugin,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                ITrace trace = ScriptOps.NewCoreTrace(
                    callback, clientData, TraceFlags.Global, plugin,
                    ref result);

                if (traces != null)
                {
                    if (AddTrace(
                            trace, clientData, ref token,
                            ref result) == ReturnCode.Ok)
                    {
                        result = trace.Name;
                        return ReturnCode.Ok;
                    }
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified trace to this interpreter.
        /// </summary>
        /// <param name="trace">
        /// The trace to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the add operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added trace.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// trace could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the trace was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddTrace(
            ITrace trace,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (trace == null)
                {
                    result = "invalid trace";
                    return ReturnCode.Error;
                }

                string name = trace.Name;

                if (name == null)
                {
                    result = "invalid trace name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasTraces(ref result))
                    return ReturnCode.Error;

                if (DoesTraceExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: trace already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(trace);

                        wrapper = EntityOps.MaybeNewWrapperWith<TraceWrapper>(
                            id, trace);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        //
                        // NOTE: Are we allowed to assist in managing the trace
                        //       token via the associated plugin?
                        //
                        long newToken = EntityOps.GetToken(wrapper);

                        if (!EntityOps.IsNoToken(trace))
                        {
                            //
                            // NOTE: Store the trace token so that we can remove
                            //       them later without using their names (which
                            //       can change).
                            //
                            IPluginData pluginData = trace.Plugin;

                            if (pluginData != null)
                            {
                                LongList tokens = pluginData.TraceTokens;

                                if ((tokens != null) && !tokens.Contains(newToken))
                                {
                                    tokens.Add(newToken);

#if ISOLATED_PLUGINS
                                    //
                                    // HACK: Force the trace tokens for the
                                    //       isolated plugin to be updated.
                                    //
                                    if (AppDomainOps.IsIsolated(pluginData))
                                        pluginData.TraceTokens = tokens;
#endif
                                }
                            }
                        }

                        EntityOps.SetToken(trace, newToken);

                        traces.Add(name, wrapper as TraceWrapper);
                        success = true;

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Trace, NotifyFlags.Added,
                            new ObjectPair(trace, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

