        #region Private
        /// <summary>
        /// This method looks up a trace by its token.  It assumes the
        /// interpreter lock is already held by the caller.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the trace to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the trace that was
        /// found.
        /// </param>
        /// <param name="trace">
        /// Upon success, this is set to the trace that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// trace could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the trace was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetTrace(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref ITrace trace,
            ref Result error
            )
        {
            if (!PrivateHasTraces(ref error))
                return ReturnCode.Error;

            TraceWrapper wrapper;

            if (!traces.TryGetValue(token, out wrapper))
            {
                error = "trace not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                trace = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((trace == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid trace";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid trace wrapper";
                    return ReturnCode.Error;
                }

                trace = wrapper.trace;
                name = EntityOps.GetName(trace);

                if ((trace == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid trace";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

