        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetTrace(
            string name,
            LookupFlags lookupFlags,
            ref ITrace trace,
            ref Result error
            )
        {
            long token = 0;

            return GetTrace(name, lookupFlags, ref token, ref trace, ref error);
        }

