        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level removal of a trace from this
        /// interpreter, updating any associated plugin token tracking.
        /// </summary>
        /// <param name="name">
        /// The name of the trace to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the trace to remove.
        /// </param>
        /// <param name="trace">
        /// The trace being removed.  This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// trace could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the trace was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveTrace(
            string name,
            long token,
            ITrace trace,
            IClientData clientData,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid trace name";
                return ReturnCode.Error;
            }

            traces.Remove(name, token);

            if (trace != null)
            {
                //
                // NOTE: Are we allowed to assist in managing the trace
                //       token via the associated plugin?
                //
                bool noToken = EntityOps.IsNoToken(trace);

                if (!noToken)
                {
                    //
                    // NOTE: If this trace is being managed by a plugin,
                    //       remove the associated token from said plugin.
                    //
                    IPluginData pluginData = trace.Plugin;

                    if (pluginData != null)
                    {
                        LongList tokens = pluginData.TraceTokens;

                        if ((tokens != null) && tokens.Contains(token))
                        {
                            tokens.Remove(token);

#if ISOLATED_PLUGINS
                            //
                            // HACK: Force the trace tokens for the
                            //       isolated plugin to be updated.
                            //
                            if (AppDomainOps.IsIsolated(pluginData))
                                pluginData.TraceTokens = tokens;
#endif
                        }
                    }
                }
            }

#if NOTIFY
            /* IGNORED */
            CheckNotification(
                NotifyType.Trace, NotifyFlags.Removed,
                new ObjectTriplet(trace, name, token), this,
                clientData, null, null, ref result);
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the trace identified by the specified token
        /// from this interpreter.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the trace to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the trace that was
        /// removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// trace could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the trace was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveTrace(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasTraces(ref result))
                {
                    ITrace trace = null;

                    if (PrivateGetTrace(
                            token, LookupFlags.Remove, ref name,
                            ref trace, ref result) == ReturnCode.Ok)
                    {
                        if (!EntityOps.IsReadOnly(trace))
                        {
                            return PrivateRemoveTrace(
                                name, token, trace, clientData, ref result);
                        }
                        else
                        {
                            result = "trace is read-only";
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named trace from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the trace to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the trace
        /// that was removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// trace could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the trace was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveTrace(
            string name,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasTraces(ref result))
                {
                    ITrace trace = null;

                    if (PrivateGetTrace(
                            name, LookupFlags.Remove, ref token,
                            ref trace, ref result) == ReturnCode.Ok)
                    {
                        if (!EntityOps.IsReadOnly(trace))
                        {
                            return PrivateRemoveTrace(
                                name, token, trace, clientData, ref result);
                        }
                        else
                        {
                            result = "trace is read-only";
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }
        #endregion
