        #region IAlias
        /// <summary>
        /// This method looks up an alias by its token.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the alias to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the alias that was
        /// found.
        /// </param>
        /// <param name="alias">
        /// Upon success, this is set to the alias that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetAlias(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IAlias alias,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetAlias(
                        token, lookupFlags, ref name, ref alias,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid alias token {0}",
                            FormatOps.WrapOrNull(token)) :
                        "invalid alias token";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

