        /// <summary>
        /// This method creates a new alias with the specified name and
        /// configuration and adds it to this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the alias to create.
        /// </param>
        /// <param name="commandFlags">
        /// The command flags to associate with the alias.
        /// </param>
        /// <param name="aliasFlags">
        /// The alias flags to associate with the alias.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the alias.  This parameter may
        /// be null.
        /// </param>
        /// <param name="targetInterpreter">
        /// The interpreter that contains the target command to be invoked
        /// by the alias.
        /// </param>
        /// <param name="target">
        /// The command to be invoked by the alias.
        /// </param>
        /// <param name="arguments">
        /// The list of leading arguments to prepend when the alias is
        /// invoked.  This parameter may be null.
        /// </param>
        /// <param name="options">
        /// The options associated with the alias.  This parameter may be
        /// null.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to be passed through to the
        /// target command.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added alias.
        /// </param>
        /// <param name="alias">
        /// Upon success, this is set to the newly added alias.
        /// </param>
        /// <param name="result">
        /// Upon success, this is set to the name token of the newly added
        /// alias; upon failure, this is set to an error message describing
        /// why the alias could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddAlias(
            string name,
            CommandFlags commandFlags,
            AliasFlags aliasFlags,
            IClientData clientData,
            Interpreter targetInterpreter,
            IExecute target,
            ArgumentList arguments,
            OptionDictionary options,
            int startIndex,
            ref long token,
            ref IAlias alias,
            ref Result result
            )
        {
            CheckDisposed();

            return PrivateAddAlias(
                name, commandFlags, aliasFlags, clientData, targetInterpreter,
                target, arguments, options, startIndex, ref token, ref alias,
                ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified alias to this interpreter.
        /// </summary>
        /// <param name="alias">
        /// The alias to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the add operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added alias.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddAlias(
            IAlias alias,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (alias == null)
                {
                    result = "invalid alias";
                    return ReturnCode.Error;
                }

                string name = alias.NameToken;

                if (name == null)
                {
                    result = "invalid alias name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasAliases(ref result))
                    return ReturnCode.Error;

                if (DoesAliasExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: alias already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(alias);

                        wrapper = EntityOps.MaybeNewWrapperWith<AliasWrapper>(
                            id, alias);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        aliases.Add(name, wrapper as AliasWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(alias, newToken);

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Alias, NotifyFlags.Added,
                            new ObjectPair(alias, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method builds a list of the alias names defined in this
        /// interpreter, optionally filtered by a pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to match alias names.  This parameter may be
        /// null, in which case all alias names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="all">
        /// Non-zero to include namespace aliases in the list.
        /// </param>
        /// <param name="list">
        /// Upon success, this is set to (or appended with) the list of
        /// matching alias names.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// list could not be produced.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was produced;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListAliases(
            string pattern,
            bool noCase,
            bool all,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasAliases(ref error))
                {
                    AliasFlags notHasFlags = all ?
                        AliasFlags.None : AliasFlags.Namespace;

                    return aliases.ToList(
                        AliasFlags.None, notHasFlags, false, false, pattern,
                        noCase, ref list, ref error);
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up an alias by its token.  It assumes the
        /// interpreter lock is already held by the caller.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the alias to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the alias that was
        /// found.
        /// </param>
        /// <param name="alias">
        /// Upon success, this is set to the alias that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetAlias(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IAlias alias,
            ref Result error
            )
        {
            if (!PrivateHasAliases(ref error))
                return ReturnCode.Error;

            AliasWrapper wrapper;

            if (!aliases.TryGetValue(token, out wrapper))
            {
                error = "alias not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                alias = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((alias == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid alias";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid alias wrapper";
                    return ReturnCode.Error;
                }

                alias = wrapper.alias;
                name = EntityOps.GetName(alias);

                if ((alias == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid alias";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

