            return PrivateAddAlias(
                name, commandFlags, aliasFlags, clientData, targetInterpreter, target,
                arguments, options, startIndex, ref token, ref alias, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level creation of a new alias,
        /// resolving the current namespace and registering the alias as a
        /// command.
        /// </summary>
        /// <param name="name">
        /// The name of the alias to create.
        /// </param>
        /// <param name="commandFlags">
        /// The command flags to associate with the alias.
        /// </param>
        /// <param name="aliasFlags">
        /// The alias flags to associate with the alias.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the alias.  This parameter may
        /// be null.
        /// </param>
        /// <param name="targetInterpreter">
        /// The interpreter that contains the target command to be invoked
        /// by the alias.
        /// </param>
        /// <param name="target">
        /// The command to be invoked by the alias.
        /// </param>
        /// <param name="arguments">
        /// The list of leading arguments to prepend when the alias is
        /// invoked.  This parameter may be null.
        /// </param>
        /// <param name="options">
        /// The options associated with the alias.  This parameter may be
        /// null.
        /// </param>
        /// <param name="startIndex">
        /// The index of the first argument to be passed through to the
        /// target command.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added alias.
        /// </param>
        /// <param name="alias">
        /// Upon success, this is set to the newly added alias.
        /// </param>
        /// <param name="result">
        /// Upon success, this is set to the name token of the newly added
        /// alias; upon failure, this is set to an error message describing
        /// why the alias could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateAddAlias(
            string name,
            CommandFlags commandFlags,
            AliasFlags aliasFlags,
            IClientData clientData,
            Interpreter targetInterpreter,
            IExecute target,
            ArgumentList arguments,
            OptionDictionary options,
            int startIndex,
            ref long token,
            ref IAlias alias,
            ref Result result
            )
        {
            INamespace currentNamespace = null;
            AliasFlags newAliasFlags;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (InternalAreNamespacesEnabled())
                {
                    if (GetCurrentNamespaceViaResolvers(
                            null, LookupFlags.Default,
                            ref currentNamespace,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }

                newAliasFlags = this.newAliasFlags;
            }

            //
            // NOTE: Create the new alias with a unique name token
            //       (which may be the same as the name).
            //
            IAlias newAlias = RuntimeOps.NewAlias(
                ScriptOps.MakeCommandName(name), commandFlags,
                aliasFlags | newAliasFlags, clientData,
                GetAliasNameToken(name), this, targetInterpreter,
                currentNamespace, currentNamespace, target,
                arguments, options, startIndex);

            //
            // NOTE: For now, rely upon the logic in AddCommand.
            //       Eventually, this may perform some specialized
            //       argument validation here.
            //
            ReturnCode code = AddAliasAndCommand(
                newAlias, null, ref token, ref result);

            if (code == ReturnCode.Ok)
            {
                alias = newAlias;
                result = newAlias.NameToken;
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames the specified alias, preserving its token.
        /// </summary>
        /// <param name="alias">
        /// The alias to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the alias.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be renamed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was renamed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RenameAlias(
            IAlias alias,
            string newName,
            ref Result result
            )
        {
            // CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (alias == null)
                {
                    result = "invalid alias";
                    return ReturnCode.Error;
                }

                string oldName = alias.NameToken; /* HACK: Confusing. */

                if (oldName == null)
                {
                    result = "invalid old alias name";
                    return ReturnCode.Error;
                }

                if (newName == null)
                {
                    result = "invalid new object name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasAliases(ref result))
                    return ReturnCode.Error;

                if (DoesAliasExist(newName) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't rename {0}: alias already exists",
                        FormatOps.WrapOrNull(newName));

                    return ReturnCode.Error;
                }

                string oldNameToken = oldName;
                AliasWrapper wrapper;

                if (!aliases.TryGetValue(oldNameToken, out wrapper))
                {
                    result = String.Format(
                        "can't rename {0}: alias does not exist",
                        FormatOps.WrapOrNull(oldNameToken));

                    return ReturnCode.Error;
                }

                IAlias localAlias = wrapper.alias;

                if (!Object.ReferenceEquals(alias, localAlias))
                {
                    result = String.Format(
                        "can't rename {0}: alias mismatch",
                        FormatOps.WrapOrNull(oldNameToken));

                    return ReturnCode.Error;
                }

                string newNameToken = GetAliasNameToken(newName);

                alias.Name = newName;
                alias.NameToken = newNameToken;

                /* IGNORED */
                aliases.Rename(oldNameToken, newNameToken);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Alias, NotifyFlags.Renamed,
                    new ObjectTriplet(alias, oldNameToken, newNameToken),
                    this, clientData, null, null, ref result);
#endif
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level removal of an alias from this
        /// interpreter, also removing any associated object reference and
        /// target disposal callback.
        /// </summary>
        /// <param name="name">
        /// The name of the alias to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the alias to remove.
        /// </param>
        /// <param name="alias">
        /// The alias being removed.  This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveAlias(
            string name,
            long token,
            IAlias alias,
            IClientData clientData,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid alias name";
                return ReturnCode.Error;
            }

            if ((alias != null) &&
                FlagOps.HasFlags(alias.AliasFlags, AliasFlags.Reference, true))
            {
                if (RemoveObjectReference(
                        ReturnCode.Ok, name, ObjectReferenceType.Command,
                        false, ref result) == ReturnCode.Ok)
                {
                    alias.AliasFlags &= ~AliasFlags.Reference;
                }
                else
                {
                    return ReturnCode.Error;
                }
            }

            //
            // BUGFIX: Remove the interpreter disposal callback delegate for this
            //         alias from the list of interpreter disposal callbacks in
            //         the target interpreter since the alias is being removed.
            //
            RemoveTargetDisposeCallback(alias);
            aliases.Remove(name, token);

            if (alias != null)
            {
                //
                // NOTE: Prevent the command from trying to cleanup
                //       the alias since it has now been deleted.
                //
                alias.NameToken = null;
            }

#if NOTIFY
            /* IGNORED */
            CheckNotification(
                NotifyType.Alias, NotifyFlags.Removed,
                new ObjectTriplet(alias, name, token), this,
                clientData, null, null, ref result);
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the alias identified by the specified token
        /// from this interpreter.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the alias to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the alias that was
        /// removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveAlias(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            ) /* NOT USED */
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasAliases(ref result))
                {
                    IAlias alias = null;

                    if (PrivateGetAlias(
                            token, LookupFlags.Remove, ref name,
                            ref alias, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemoveAlias(
                            name, token, alias, clientData, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named alias from this interpreter,
        /// discarding the resulting token.
        /// </summary>
        /// <param name="name">
        /// The name of the alias to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveAlias(
            string name,
            IClientData clientData,
            ref Result result
            )
        {
            long token = 0; /* NOT USED */

            return InternalRemoveAlias(name, clientData, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named alias from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the alias to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the alias
        /// that was removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// alias could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the alias was removed;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveAlias(
            string name,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasAliases(ref result))
                {
                    IAlias alias = null;

                    if (PrivateGetAlias(
                            name, LookupFlags.Remove, ref token,
                            ref alias, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemoveAlias(
                            name, token, alias, clientData, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IFunction
        /// <summary>
        /// This method looks up a function by its token.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the function to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the function that was
        /// found.
        /// </param>
        /// <param name="function">
        /// Upon success, this is set to the function that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetFunction(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IFunction function,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetFunction(
                        token, lookupFlags, ref name, ref function,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid function token {0}",
                            FormatOps.WrapOrNull(token)) :
                        "invalid function token";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a function by its name.
        /// </summary>
        /// <param name="name">
        /// The name of the function to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// function that was found.
        /// </param>
        /// <param name="function">
        /// Upon success, this is set to the function that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetFunction(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IFunction function,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetFunction(
                        name, lookupFlags, ref token, ref function,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid function name {0}",
                            FormatOps.DisplayName(name)) :
                        "invalid function name";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the functions defined in this
        /// interpreter, filtered by flags and an optional pattern.
        /// </summary>
        /// <param name="hasFlags">
        /// The function flags that a function must have to be included.
        /// </param>
        /// <param name="notHasFlags">
        /// The function flags that a function must not have to be included.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="hasFlags" /> be present.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="notHasFlags" /> be present before a function is excluded.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match function names.  This parameter may be
        /// null, in which case all function names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extended information for each function in
        /// the list.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if no functions are available.
        /// </param>
        /// <param name="list">
        /// Upon success, this is set to (or appended with) the list of
        /// matching function names.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// list could not be produced.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was produced;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode ListFunctions(
            FunctionFlags hasFlags,
            FunctionFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            bool strict,
            ref StringList list,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasFunctions(ref localError))
                {
                    code = functions.ToList(
                        hasFlags, notHasFlags, hasAll, notHasAll,
                        pattern, noCase, full, ref list, ref error);
                }
                else if (strict)
                {
                    error = localError;
                }
                else
                {
                    if (list == null)
                        list = new StringList();

                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new function of the specified type and
        /// adds it to this interpreter.
        /// </summary>
        /// <param name="type">
        /// The type that implements the function.  This parameter may be
        /// null, in which case the type is resolved from the function name.
        /// </param>
        /// <param name="name">
        /// The name of the function to add.
        /// </param>
        /// <param name="arguments">
        /// The number of arguments accepted by the function, or the
        /// automatic arity sentinel to use the value declared by the type.
        /// </param>
        /// <param name="types">
        /// The list of argument types accepted by the function.  This
        /// parameter may be null.
        /// </param>
        /// <param name="flags">
        /// The additional function flags to associate with the function.
        /// </param>
        /// <param name="plugin">
        /// The plugin associated with the function.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the function.  This parameter
        /// may be null.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error when the function cannot be added
        /// due to the safety or standard policies of the interpreter.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added function.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddFunction(
            Type type,
            string name,
            int arguments,
            TypeList types,
            FunctionFlags flags,
            IPlugin plugin,
            IClientData clientData,
            bool strict,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            if (type == null)
            {
                type = Type.GetType(
                    FormatOps.FunctionTypeName(name, false), false,
                    true);
            }

            if (type == null)
            {
                type = Type.GetType(FormatOps.FunctionTypeName(
                    Characters.Underscore + name, false), false,
                    true);
            }

            if (type != null)
            {
                FunctionFlags functionFlags =
                    AttributeOps.GetFunctionFlags(type) | flags;

                AddEntityClientData addEntityClientData =
                    new AddEntityClientData(null, this);

                bool createSafe = addEntityClientData.CreateSafe;
                bool createStandard = addEntityClientData.CreateStandard;

                //
                // NOTE: Check if this function has been marked as "safe" or
                //       "unsafe" by its author.
                //
                bool safe = FlagOps.HasFlags(functionFlags,
                        FunctionFlags.Safe, true) &&
                    !FlagOps.HasFlags(functionFlags,
                        FunctionFlags.Unsafe, true);

                //
                // NOTE: If the interpreter is "safe", make sure we only add
                //       functions that are marked as "safe" and NOT marked
                //       as "unsafe" unless we are merely hiding functions
                //       not considered to be "safe".  In that case, we add
                //       all functions, hidden them as necessary.
                //
                if (safe || !createSafe)
                {
                    //
                    // NOTE: Check if this function is part of the "Tcl Standard"
                    //       (i.e. it is largely (or completely) compatible with
                    //       an identically named function from Tcl/Tk 8.4, 8.5,
                    //       and/or 8.6).
                    //
                    bool standard = FlagOps.HasFlags(
                        functionFlags, FunctionFlags.Standard, true);

                    //
                    // NOTE: If the interpreter is "standard", make sure we only
                    //       add functions that are marked as "standard" and NOT
                    //       marked as "non-standard" unless we are merely hiding
                    //       functions not considered to be "standard".  In that
                    //       case, we add all functions, hidden them as necessary.
                    //
                    if (standard || !createStandard)
                    {
                        try
                        {
                            if (arguments == (int)Arity.Automatic)
                                arguments = AttributeOps.GetArguments(type);

                            object[] args = {
                                new FunctionData(
                                    name, null, null, clientData, type.FullName,
                                    type, arguments, types, flags, plugin, 0)
                            };

                            IFunction function =
                                (IFunction)Activator.CreateInstance(type, args);

                            return AddFunction(
                                function, null, ref token, ref result);
                        }
                        catch (Exception e)
                        {
                            result = e;
                        }
                    }
                    else if (strict)
                    {
                        result = "cannot add non-standard function to standard interpreter";
                    }
                    else
                    {
                        return ReturnCode.Ok;
                    }
                }
                else if (strict)
                {
                    result = "cannot add unsafe function to safe interpreter";
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                result = String.Format(
                    "function {0} not found",
                    FormatOps.FunctionTypeName(name, true));
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified function to this interpreter,
        /// initializing it and, when applicable, registering it as a Tcl
        /// math function.
        /// </summary>
        /// <param name="function">
        /// The function to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the add operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added function.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddFunction(
            IFunction function,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (function == null)
                {
                    result = "invalid function";
                    return ReturnCode.Error;
                }

                string name = function.Name;

                if (name == null)
                {
                    result = "invalid function name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasFunctions(ref result))
                    return ReturnCode.Error;

                if (DoesFunctionExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: function already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                //
                // HACK: Due to how the expression parser works, we cannot allow a
                //       function to be added that has the name of an existing
                //       operator.
                //
                if (DoesOperatorExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: operator already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                if (!FlagOps.HasFlags(
                        function.Flags, FunctionFlags.NoTclMathFunction, true) &&
                    /* EXEMPT */
                    FlagOps.HasFlags(
                        interpreterFlags, InterpreterFlags.TclMathFunctions, true))
                {
                    //
                    // HACK: This is part of an ugly hack to add "tcl::mathfunc::*" and
                    //       "tcl::mathop::*" support for [expr] functions and operators
                    //       to Eagle, respectively.  This can only be done for function
                    //       instances that also implement the IExecute interface.
                    //
                    IExecute execute = function as IExecute;
                    long token2; /* REUSED */

                    if (execute != null)
                    {
                        if (InternalAreNamespacesEnabled())
                        {
                            INamespace @namespace = NamespaceOps.Lookup(
                                this, TclVars.Namespace.MathFunctionName, true, true,
                                ref result);

                            if (@namespace == null)
                                return ReturnCode.Error;

                            string qualifiedName = NamespaceOps.MakeQualifiedName(
                                this, @namespace, name);

                            if (ApplyRuleSet(
                                    IdentifierKind.Command, MatchMode.IncludeRuleSetMask,
                                    ScriptOps.MakeCommandName(qualifiedName)))
                            {
                                token2 = 0; /* NOT USED */

                                if (AddIExecute(
                                        qualifiedName, execute, clientData,
                                        ref token2, ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }
                            }
                        }
                        else
                        {
                            string unqualifiedName = NamespaceOps.MakeName(
                                TclVars.Namespace.MathFunctionName, name, true,
                                false);

                            if (ApplyRuleSet(
                                    IdentifierKind.Command, MatchMode.IncludeRuleSetMask,
                                    ScriptOps.MakeCommandName(unqualifiedName)))
                            {
                                token2 = 0; /* NOT USED */

                                if (AddIExecute(
                                        unqualifiedName, execute, clientData,
                                        ref token2, ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }
                            }
                        }
                    }
                }

                ReturnCode code = ReturnCode.Ok;

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    try
                    {
                        try
                        {
                            code = function.Initialize(this,
                                (clientData != null) ? clientData : function.ClientData,
                                ref result);
                        }
                        catch (Exception e)
                        {
                            result = String.Format(
                                "caught exception while initializing function: {0}",
                                e);

                            code = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        if (code != ReturnCode.Ok)
                        {
                            ReturnCode terminateCode;
                            Result terminateResult = null;

                            terminateCode = TerminateFunction(
                                function, clientData, ref terminateResult);

                            if (terminateCode != ReturnCode.Ok)
                            {
                                DebugOps.Complain(
                                    this, terminateCode, terminateResult);
                            }
                        }
                    }

                    if (code != ReturnCode.Ok)
                        return code;

                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(function);

                        wrapper = EntityOps.MaybeNewWrapperWith<FunctionWrapper>(
                            id, function);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        //
                        // NOTE: Are we allowed to assist in managing the function
                        //       token via the associated plugin?
                        //
                        long newToken = EntityOps.GetToken(wrapper);

                        if (!EntityOps.IsNoToken(function))
                        {
                            //
                            // NOTE: Store the function token so that we can remove
                            //       them later without using their names (which
                            //       can change).
                            //
                            IPluginData pluginData = function.Plugin;

                            if (pluginData != null)
                            {
                                LongList tokens = pluginData.FunctionTokens;

                                if ((tokens != null) && !tokens.Contains(newToken))
                                {
                                    tokens.Add(newToken);

#if ISOLATED_PLUGINS
                                    //
                                    // HACK: Force the function tokens for the
                                    //       isolated plugin to be updated.
                                    //
                                    if (AppDomainOps.IsIsolated(pluginData))
                                        pluginData.FunctionTokens = tokens;
#endif
                                }
                            }
                        }

                        EntityOps.SetToken(function, newToken);

                        functions.Add(name, wrapper as FunctionWrapper);
                        success = true;

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Function, NotifyFlags.Added,
                            new ObjectPair(function, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames a function, optionally deleting it instead
        /// when no new name is supplied.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the function to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the function.
        /// </param>
        /// <param name="delete">
        /// Non-zero to remove the function when the new name is null or
        /// empty.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be renamed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was renamed
        /// or removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RenameFunction(
            string oldName,
            string newName,
            bool delete,
            ref Result result
            )
        {
            CheckDisposed();

            return PrivateRenameFunction(
                oldName, newName, delete, ref result);
        }

