        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method looks up a function by its token.  It assumes the
        /// interpreter lock is already held by the caller.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the function to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the function that was
        /// found.
        /// </param>
        /// <param name="function">
        /// Upon success, this is set to the function that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetFunction(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IFunction function,
            ref Result error
            )
        {
            if (!PrivateHasFunctions(ref error))
                return ReturnCode.Error;

            FunctionWrapper wrapper;

            if (!functions.TryGetValue(token, out wrapper))
            {
                error = "function not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                function = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((function == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid function wrapper";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid function wrapper";
                    return ReturnCode.Error;
                }

                function = wrapper.function;
                name = EntityOps.GetName(function);

                if ((function == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a function by its name.  It assumes the
        /// interpreter lock is already held by the caller.
        /// </summary>
        /// <param name="name">
        /// The name of the function to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// function that was found.
        /// </param>
        /// <param name="function">
        /// Upon success, this is set to the function that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetFunction(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IFunction function,
            ref Result error
            )
        {
            if (!HasFunctions(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid function name";
                return ReturnCode.Error;
            }

            FunctionWrapper wrapper;

            if (!functions.TryGetValue(name, out wrapper))
            {
                error = "function not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                function = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((function == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid function";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid function wrapper";
                    return ReturnCode.Error;
                }

                function = wrapper.function;
                token = EntityOps.GetToken(function);

                if ((function == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid function";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a function by its name, discarding the
        /// resulting token.
        /// </summary>
        /// <param name="name">
        /// The name of the function to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="function">
        /// Upon success, this is set to the function that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetFunction(
            string name,
            LookupFlags lookupFlags,
            ref IFunction function,
            ref Result error
            )
        {
            long token = 0;

            return GetFunction(name, lookupFlags, ref token, ref function, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a function by its name for use during
        /// expression evaluation.
        /// </summary>
        /// <param name="name">
        /// The name of the function to look up.
        /// </param>
        /// <param name="function">
        /// Upon success, this is set to the function that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetExpressionFunction(
            string name,
            ref IFunction function,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (functions == null)
                {
                    error = "functions not available";
                    return ReturnCode.Error;
                }

                if (name == null)
                {
                    error = "invalid function name";
                    return ReturnCode.Error;
                }

                FunctionWrapper wrapper;

                if (!functions.TryGetValue(name, out wrapper))
                {
                    error = String.Format(
                        "invalid function name {0}",
                        FormatOps.DisplayName(name));

                    return ReturnCode.Error;
                }

                if (wrapper == null)
                {
                    error = "invalid function wrapper";
                    return ReturnCode.Error;
                }

                function = wrapper.function;

                if (function == null)
                {
                    error = "invalid function";
                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified function to this interpreter,
