        /// Returns <see cref="ReturnCode.Ok" /> if the function was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddFunction(
            Type type,
            string name,
            TypeList types,
            FunctionFlags flags,
            IPlugin plugin,
            IClientData clientData,
            bool strict,
            ref Result result
            )
        {
            long token = 0;

            return AddFunction(
                type, name, types, flags, plugin, clientData,
                strict, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new function of the specified type and
        /// adds it to this interpreter, using automatic arity.
        /// </summary>
        /// <param name="type">
        /// The type that implements the function.  This parameter may be
        /// null, in which case the type is resolved from the function name.
        /// </param>
        /// <param name="name">
        /// The name of the function to add.
        /// </param>
        /// <param name="types">
        /// The list of argument types accepted by the function.  This
        /// parameter may be null.
        /// </param>
        /// <param name="flags">
        /// The additional function flags to associate with the function.
        /// </param>
        /// <param name="plugin">
        /// The plugin associated with the function.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the function.  This parameter
        /// may be null.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error when the function cannot be added
        /// due to the safety or standard policies of the interpreter.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added function.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddFunction(
            Type type,
            string name,
            TypeList types,
            FunctionFlags flags,
            IPlugin plugin,
            IClientData clientData,
            bool strict,
            ref long token,
            ref Result result
            )
        {
            return AddFunction(
                type, name, (int)Arity.Automatic, types, flags,
                plugin, clientData, strict, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level rename of a function,
        /// preserving its token, or removes it when deletion is requested.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the function to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the function.
        /// </param>
        /// <param name="delete">
        /// Non-zero to remove the function when the new name is null or
        /// empty.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be renamed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was renamed
        /// or removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameFunction(
            string oldName,
            string newName,
            bool delete,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasFunctions(ref result))
                {
                    if (!delete || !String.IsNullOrEmpty(newName))
                    {
                        IFunction oldFunction = null;

                        if (GetFunction(oldName, LookupFlags.Default, ref oldFunction, ref result) == ReturnCode.Ok)
                        {
                            if (!EntityOps.IsReadOnly(oldFunction))
                            {
                                if (EntityOps.IsNoRename(oldFunction))
                                    return ReturnCode.Ok;

                                FunctionWrapper oldWrapper = oldFunction as FunctionWrapper;

                                if (oldWrapper != null)
                                {
                                    if (PrivateDoesFunctionExist(newName) != ReturnCode.Ok)
                                    {
                                        //
                                        // NOTE: New name, same token.
                                        //
                                        oldWrapper.Name = newName;

                                        /* IGNORED */
                                        functions.Rename(oldName, newName);

#if NOTIFY
                                        /* IGNORED */
                                        CheckNotification(
                                            NotifyType.Function, NotifyFlags.Renamed,
                                            new ObjectTriplet(oldFunction, oldName, newName), this,
                                            null, null, null, ref result);
#endif

                                        result = String.Empty;
                                        return ReturnCode.Ok;
                                    }
                                    else
                                    {
                                        result = String.Format(
                                            "can't rename {0}: function already exists",
                                            FormatOps.WrapOrNull(oldName));
                                    }
                                }
                                else
                                {
                                    result = String.Format(
                                        "can't rename {0}: invalid function wrapper",
                                        FormatOps.WrapOrNull(oldName));
                                }
                            }
                            else
                            {
                                result = "function is read-only";
                            }
                        }
                        else
                        {
                            result = String.Format(
                                "can't rename {0}: function doesn't exist",
                                FormatOps.WrapOrNull(oldName));
                        }
                    }
                    else
                    {
                        return PrivateRemoveFunction(oldName, null, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level removal of a function from
        /// this interpreter, also removing any associated Tcl math function
        /// command and updating plugin token tracking.
        /// </summary>
        /// <param name="name">
        /// The name of the function to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the function to remove.
        /// </param>
        /// <param name="function">
        /// The function being removed.  This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was
        /// removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveFunction(
            string name,
            long token,
            IFunction function,
            IClientData clientData,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid function name";
                return ReturnCode.Error;
            }

            if (((function == null) || !FlagOps.HasFlags(
                    function.Flags, FunctionFlags.NoTclMathFunction, true)) &&
                /* EXEMPT */
                FlagOps.HasFlags(
                    interpreterFlags, InterpreterFlags.TclMathFunctions, true))
            {
                //
                // HACK: This is part of an ugly hack to add "tcl::mathfunc::*" and
                //       "tcl::mathop::*" support for [expr] functions and operators
                //       to Eagle, respectively.  This can only be done for function
                //       instances that also implement the IExecute interface.
                //
                if (InternalAreNamespacesEnabled())
                {
                    //
                    // BUGBUG: If any of the parent namespaces are already deleted,
                    //         we should skip doing removal of associated commands.
                    //         That checking should not be necessary; however, it
                    //         could be if any of those deleted namespaces are also
                    //         disposed.
                    //
                    INamespace @namespace = NamespaceOps.Lookup(
                        this, TclVars.Namespace.MathFunctionName, true, false);

                    if (@namespace != null)
                    {
                        string qualifiedName = NamespaceOps.MakeQualifiedName(
                            this, @namespace, name);

                        if ((DoesIExecuteExist(
                                qualifiedName) == ReturnCode.Ok) &&
                            (RemoveIExecute(
                                qualifiedName, clientData,
                                ref result) != ReturnCode.Ok))
                        {
                            return ReturnCode.Error;
                        }
                    }
                }
                else
                {
                    string unqualifiedName = NamespaceOps.MakeName(
                        TclVars.Namespace.MathFunctionName, name, true,
                        false);

                    if ((DoesIExecuteExist(
                            unqualifiedName) == ReturnCode.Ok) &&
                        (RemoveIExecute(
                            unqualifiedName, clientData,
                            ref result) != ReturnCode.Ok))
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            GlobalState.PushActiveInterpreter(this);

            try
            {
                if ((function == null) || (TerminateFunction(
                        function, clientData, ref result) == ReturnCode.Ok))
                {
                    functions.Remove(name, token);

                    if (function != null)
                    {
                        //
                        // NOTE: Are we allowed to assist in managing the function
                        //       token via the associated plugin?
                        //
                        bool noToken = EntityOps.IsNoToken(function);

                        if (!noToken)
                        {
                            //
                            // NOTE: If this function is being managed by a plugin,
                            //       remove the associated token from said plugin.
                            //
                            IPluginData pluginData = function.Plugin;

                            if (pluginData != null)
                            {
                                LongList tokens = pluginData.FunctionTokens;

                                if ((tokens != null) && tokens.Contains(token))
                                {
                                    tokens.Remove(token);

#if ISOLATED_PLUGINS
                                    //
                                    // HACK: Force the function tokens for the
                                    //       isolated plugin to be updated.
                                    //
                                    if (AppDomainOps.IsIsolated(pluginData))
                                        pluginData.FunctionTokens = tokens;
#endif
                                }
                            }
                        }
                    }

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(
                        NotifyType.Function, NotifyFlags.Removed,
                        new ObjectTriplet(function, name, token), this,
                        clientData, null, null, ref result);
#endif

                    return ReturnCode.Ok;
                }

                return ReturnCode.Error;
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while removing function: {0}",
                    e);

                return ReturnCode.Error;
            }
            finally
            {
                /* IGNORED */
                GlobalState.PopActiveInterpreter();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the function identified by the specified
        /// token from this interpreter.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the function to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the function that was
        /// removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was
        /// removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveFunction(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasFunctions(ref result))
                {
                    IFunction function = null;

                    if (PrivateGetFunction(
                            token, LookupFlags.Remove, ref name,
                            ref function, ref result) == ReturnCode.Ok)
                    {
                        if (!EntityOps.IsReadOnly(function))
                        {
                            return PrivateRemoveFunction(
                                name, token, function, clientData, ref result);
                        }
                        else
                        {
                            result = "function is read-only";
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }

