        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates the specified function, giving it the
        /// opportunity to release any resources it holds.
        /// </summary>
        /// <param name="function">
        /// The function to terminate.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the terminate operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// function could not be terminated.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the function was
        /// terminated; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode TerminateFunction(
            IFunction function,
            IClientData clientData,
            ref Result result
            )
        {
            if (function == null)
            {
                result = "invalid function";
                return ReturnCode.Error;
            }

            bool savedImmutable = BeginMutableExecution();

            ReturnCode code;

            try
            {
                code = function.Terminate(this,
                    (clientData != null) ? clientData : function.ClientData,
                    ref result);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Function, NotifyFlags.Terminated,
                    new ObjectTriplet(function, code), this,
                    clientData, null, null, ref result);
#endif
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while terminating function: {0}",
                    e);

                code = ReturnCode.Error;
            }
            finally
            {
                EndMutableExecution(savedImmutable);
            }

            return code;
        }
