        /// <summary>
        /// This method creates a new procedure with the specified
        /// definition and adds it to, or updates it within, this
        /// interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the procedure.
        /// </param>
        /// <param name="procedureFlags">
        /// The procedure flags to associate with the procedure.
        /// </param>
        /// <param name="arguments">
        /// The formal argument list of the procedure.  This parameter may
        /// be null.
        /// </param>
        /// <param name="namedArguments">
        /// The named arguments of the procedure.  This parameter may be
        /// null.
        /// </param>
        /// <param name="overwriteArguments">
        /// The arguments used to overwrite variable values when the
        /// procedure is invoked.  This parameter may be null.
        /// </param>
        /// <param name="cleanArguments">
        /// The arguments used to reset variable values after the procedure
        /// is invoked.  This parameter may be null.
        /// </param>
        /// <param name="body">
        /// The body script of the procedure.
        /// </param>
        /// <param name="location">
        /// The script location associated with the procedure body.  This
        /// parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the procedure.  This parameter
        /// may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// procedure.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was added
        /// or updated; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddOrUpdateProcedure(
            string name,
            ProcedureFlags procedureFlags,
            ArgumentList arguments,
            ArgumentDictionary namedArguments,
            ArgumentList overwriteArguments,
            ArgumentList cleanArguments,
            string body,
            IScriptLocation location,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            CheckDisposed();

            IProcedure procedure;
            Result error = null;

            procedure = RuntimeOps.NewProcedure(
                this, ScriptOps.MakeCommandName(name), null, null, procedureFlags,
                arguments, namedArguments, overwriteArguments, cleanArguments,
                body, location, clientData, ref error);

            if (procedure == null)
            {
                result = error;
                return ReturnCode.Error;
            }

            return AddOrUpdateProcedure(procedure, ref token, ref result);
        }

