        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method builds a list of the procedures defined in this
        /// interpreter, filtered by flags and an optional pattern.
        /// </summary>
        /// <param name="hasFlags">
        /// The procedure flags that a procedure must have to be included.
        /// </param>
        /// <param name="notHasFlags">
        /// The procedure flags that a procedure must not have to be
        /// included.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="hasFlags" /> be present.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="notHasFlags" /> be present before a procedure is excluded.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match procedure names.  This parameter may
        /// be null, in which case all procedure names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extended information for each procedure in
        /// the list.
        /// </param>
        /// <param name="list">
        /// Upon success, this is set to (or appended with) the list of
        /// matching procedure names.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// list could not be produced.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was produced;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ProceduresToList(
            ProcedureFlags hasFlags,
            ProcedureFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (procedures != null)
                {
                    return procedures.ToList(
                        hasFlags, notHasFlags, hasAll, notHasAll,
                        pattern, noCase, full, ref list, ref error);
                }
            }

            error = "procedures not available";
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the names of the procedures whose
        /// read-only state matches the requested state, optionally filtered
        /// by a pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to match procedure names.  This parameter may
        /// be null, in which case all procedure names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="readOnly">
        /// Non-zero to include read-only procedures; zero to include
        /// writable procedures.
        /// </param>
        /// <returns>
        /// Returns the list of matching procedure names.
        /// </returns>
        internal StringList GetProceduresReadOnly(
            string pattern,
            bool noCase,
            bool readOnly
            )
        {
            StringList result = new StringList();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (procedures != null)
                {
                    foreach (ProcedurePair pair in procedures)
                    {
                        IProcedure procedure = pair.Value;

                        if (procedure == null)
                            continue;

                        if ((pattern != null) && !StringOps.Match(this,
                                StringOps.DefaultMatchMode, pair.Key,
                                pattern, noCase))
                        {
                            continue;
                        }

                        if (EntityOps.IsReadOnly(procedure) == readOnly)
                            result.Add(pair.Key);
                    }
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the read-only state of the procedures whose
        /// names match the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to match procedure names.  This parameter may
        /// be null, in which case all procedure names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="readOnly">
        /// Non-zero to mark the matching procedures as read-only; zero to
        /// mark them as writable.
        /// </param>
        /// <returns>
        /// Returns the number of procedures whose read-only state was
        /// changed.
        /// </returns>
        internal int SetProceduresReadOnly(
            string pattern,
            bool noCase,
            bool readOnly
            )
        {
            int result = 0;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (procedures != null)
                {
                    foreach (ProcedurePair pair in procedures)
                    {
                        IProcedure procedure = pair.Value;

                        if (procedure == null)
                            continue;

                        if ((pattern != null) && !StringOps.Match(this,
                                StringOps.DefaultMatchMode, pair.Key,
                                pattern, noCase))
                        {
                            continue;
                        }

                        if (EntityOps.IsReadOnly(procedure) == readOnly)
                            continue;

                        if (EntityOps.SetReadOnly(procedure, readOnly))
                            result++;
                    }
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a procedure by its token.  It assumes the
        /// interpreter lock is already held by the caller.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the procedure to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the procedure that was
        /// found.
        /// </param>
        /// <param name="procedure">
        /// Upon success, this is set to the procedure that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetProcedure(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IProcedure procedure,
            ref Result error
            )
        {
            if (!PrivateHasProcedures(ref error))
                return ReturnCode.Error;

            ProcedureWrapper wrapper;

            if (!procedures.TryGetValue(token, out wrapper))
            {
                error = "procedure not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                procedure = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((procedure == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid procedure";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid procedure wrapper";
                    return ReturnCode.Error;
                }

                procedure = wrapper.procedure;
                name = EntityOps.GetName(procedure);

                if ((procedure == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid procedure";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a procedure by its name.  It assumes the
        /// interpreter lock is already held by the caller.
        /// </summary>
        /// <param name="name">
        /// The name of the procedure to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// procedure that was found.
        /// </param>
        /// <param name="procedure">
        /// Upon success, this is set to the procedure that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetProcedure(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IProcedure procedure,
            ref Result error
            )
        {
            if (!PrivateHasProcedures(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid procedure name";
                return ReturnCode.Error;
            }

            ProcedureWrapper wrapper;

            if (!procedures.TryGetValue(name, out wrapper))
            {
                error = "procedure not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                procedure = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((procedure == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid procedure";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid procedure wrapper";
                    return ReturnCode.Error;
                }

                procedure = wrapper.procedure;
                token = EntityOps.GetToken(procedure);

                if ((procedure == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid procedure";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a procedure by its name, discarding any
        /// error message.
        /// </summary>
        /// <param name="name">
        /// The name of the procedure to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
