        /// <param name="procedure">
        /// Upon success, this is set to the procedure that was found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetProcedure(
            string name,
            LookupFlags lookupFlags,
            ref IProcedure procedure
            )
        {
            Result error = null;

            return GetProcedure(name, lookupFlags, ref procedure, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a procedure by its name, discarding the
        /// resulting token.
        /// </summary>
        /// <param name="name">
        /// The name of the procedure to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the lookup is performed.
        /// </param>
        /// <param name="procedure">
        /// Upon success, this is set to the procedure that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be found.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was found;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetProcedure(
            string name,
            LookupFlags lookupFlags,
            ref IProcedure procedure,
            ref Result error
            )
        {
            long token = 0;

            return GetProcedure(name, lookupFlags, ref token, ref procedure, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the procedures defined in this
        /// interpreter, filtered by flags and an optional pattern,
        /// discarding any error message.
        /// </summary>
        /// <param name="hasFlags">
        /// The procedure flags that a procedure must have to be included.
        /// </param>
        /// <param name="notHasFlags">
        /// The procedure flags that a procedure must not have to be
        /// included.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="hasFlags" /> be present.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="notHasFlags" /> be present before a procedure is excluded.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match procedure names.  This parameter may
        /// be null, in which case all procedure names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extended information for each procedure in
        /// the list.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if no procedures are available.
        /// </param>
        /// <param name="list">
        /// Upon success, this is set to (or appended with) the list of
        /// matching procedure names.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was produced;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListProcedures(
            ProcedureFlags hasFlags,
            ProcedureFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            bool strict,
            ref StringList list
            )
        {
            Result error = null;

            return ListProcedures(
                hasFlags, notHasFlags, hasAll, notHasAll, pattern, noCase,
                full, strict, ref list, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the hidden procedures defined in
        /// this interpreter, filtered by flags and an optional pattern,
        /// discarding any error message.
        /// </summary>
        /// <param name="hasFlags">
        /// The procedure flags that a procedure must have to be included.
        /// </param>
        /// <param name="notHasFlags">
        /// The procedure flags that a procedure must not have to be
        /// included.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="hasFlags" /> be present.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="notHasFlags" /> be present before a procedure is excluded.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match procedure names.  This parameter may
        /// be null, in which case all procedure names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extended information for each procedure in
        /// the list.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if no hidden procedures are
        /// available.
        /// </param>
        /// <param name="list">
        /// Upon success, this is set to (or appended with) the list of
        /// matching procedure names.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was produced;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListHiddenProcedures(
            ProcedureFlags hasFlags,
            ProcedureFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            bool strict,
            ref StringList list
            )
        {
            Result error = null;

            return ListHiddenProcedures(
                hasFlags, notHasFlags, hasAll, notHasAll, pattern, noCase,
                full, strict, ref list, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the hidden procedures defined in
        /// this interpreter, filtered by flags and an optional pattern,
        /// honoring the current namespace when namespaces are enabled.
        /// </summary>
        /// <param name="hasFlags">
        /// The procedure flags that a procedure must have to be included.
        /// </param>
        /// <param name="notHasFlags">
        /// The procedure flags that a procedure must not have to be
        /// included.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="hasFlags" /> be present.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="notHasFlags" /> be present before a procedure is excluded.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match procedure names.  This parameter may
        /// be null, in which case all procedure names are matched.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="full">
        /// Non-zero to include extended information for each procedure in
        /// the list.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if no hidden procedures are
        /// available.
        /// </param>
        /// <param name="list">
        /// Upon success, this is set to (or appended with) the list of
        /// matching procedure names.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why the
        /// list could not be produced.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the list was produced;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListHiddenProcedures(
            ProcedureFlags hasFlags,
            ProcedureFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            bool strict,
            ref StringList list,
            ref Result error
            )
        {
            // CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasHiddenProcedures(ref localError))
                {
                    if (InternalAreNamespacesEnabled())
                    {
                        INamespace currentNamespace = null;

                        code = GetCurrentNamespaceViaResolvers(
                            null, LookupFlags.Default, ref currentNamespace,
                            ref error);

                        if (code == ReturnCode.Ok)
                        {
                            StringList[] localLists = { null, null };

                            code = hiddenProcedures.ToList(
                                hasFlags, notHasFlags, hasAll, notHasAll,
                                null, false, full, ref localLists[0],
                                ref error);

                            if (code == ReturnCode.Ok)
                            {
                                code = MatchItems(
                                    currentNamespace, pattern, noCase,
                                    ref localLists, ref error);

                                if (list == null)
                                    list = localLists[1];
                                else
                                    list.AddRange(localLists[1]);
                            }
                        }
                    }
                    else
                    {
                        pattern = ScriptOps.MakeCommandName(pattern);

                        code = hiddenProcedures.ToList(
                            hasFlags, notHasFlags, hasAll, notHasAll,
                            pattern, noCase, full, ref list, ref error);
                    }
                }
                else if (strict)
                {
                    error = localError;
                }
                else
                {
                    if (list == null)
                        list = new StringList();

                    code = ReturnCode.Ok;
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified procedure to, or updates it
        /// within, this interpreter, replacing any conflicting command or
        /// executable entity, discarding the resulting token.
        /// </summary>
        /// <param name="procedure">
        /// The procedure to add or update.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the operation.  This parameter
        /// may be null.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was added
        /// or updated; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddOrUpdateProcedureWithReplace(
            IProcedure procedure,
            IClientData clientData,
            ref Result result
            )
        {
            long token = 0;

            return AddOrUpdateProcedureWithReplace(
                procedure, clientData, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified procedure to, or updates it
        /// within, this interpreter and then removes any executable entity
        /// or command that shares its name.
        /// </summary>
        /// <param name="procedure">
        /// The procedure to add or update.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the operation.  This parameter
        /// may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// procedure.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was added
        /// or updated; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddOrUpdateProcedureWithReplace(
            IProcedure procedure,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            if (procedure != null)
            {
                ReturnCode code = AddOrUpdateProcedure(procedure, ref token, ref result);

                if (code == ReturnCode.Ok)
                {
                    try
                    {
                        string name = procedure.Name;

                        if ((code == ReturnCode.Ok) &&
                            (DoesIExecuteExist(name) == ReturnCode.Ok))
                        {
                            code = RemoveIExecute(name, clientData, ref result);
                        }

                        if ((code == ReturnCode.Ok) &&
                            (DoesCommandExist(name) == ReturnCode.Ok))
                        {
                            code = RemoveCommand(name, clientData, ref result);
                        }
                    }
                    finally
                    {
                        //
                        // BUGFIX: If we fail to remove an ICommand or IExecute,
                        //         we must still remove the procedure we just
                        //         added.
                        //
                        if (code != ReturnCode.Ok)
                        {
                            ReturnCode removeCode;
                            Result removeResult = null;

                            removeCode = RemoveProcedure(token, clientData, ref removeResult);

                            if (removeCode != ReturnCode.Ok)
                                DebugOps.Complain(this, removeCode, removeResult);
                        }
                    }
                }

                return code;
            }
            else
            {
                result = "invalid procedure";
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level add or update of a procedure
        /// within this interpreter.
        /// </summary>
        /// <param name="procedure">
        /// The procedure to add or update.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// procedure.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was added
        /// or updated; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddOrUpdateProcedure(
            IProcedure procedure,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (procedure == null)
                {
                    result = "invalid procedure";
                    return ReturnCode.Error;
                }

                string name = procedure.Name;

                if (name == null)
                {
                    result = "invalid procedure name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasProcedures(ref result))
                    return ReturnCode.Error;

                /* EXEMPT */
                if (FlagOps.HasFlags(interpreterFlags,
                        InterpreterFlags.DoesNonProcedureExist, true))
                {
                    IdentifierKind kind = IdentifierKind.None;

                    if ((PrivateDoesIExecuteExistViaResolvers(
                            name, ref kind) == ReturnCode.Ok) &&
                        !EntityOps.IsProcedure(kind))
                    {
                        result = String.Format(
                            "can't add {0}: non-procedure already exists",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                }

                Result localError = null;

                if (InternalAreNamespacesEnabled() && (NamespaceOps.LookupParent(
                        this, name, false, true, false, ref localError) == null))
                {
                    result = String.Format(
                        "can't add procedure {0}: {1}",
                        FormatOps.WrapOrNull(name),
                        localError);

                    return ReturnCode.Error;
                }

                ProcedureWrapper oldProcedureWrapper = null;
                bool exists = procedures.TryGetValue(name, out oldProcedureWrapper);

                if (exists)
                {
                    if (immutable)
                    {
                        result = "interpreter is immutable";
                        return ReturnCode.Error;
                    }

                    if (EntityOps.IsReadOnly(oldProcedureWrapper))
                    {
                        result = "procedure is read-only";
                        return ReturnCode.Error;
                    }

                    if (EntityOps.IsNoReplace(oldProcedureWrapper))
                        return ReturnCode.Ok;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(procedure);

                        wrapper = EntityOps.MaybeNewWrapperWith<ProcedureWrapper>(
                            id, procedure);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(procedure, newToken);

                        if (exists)
                        {
                            procedures[name] = wrapper as ProcedureWrapper;
                            success = true;

#if EXECUTE_CACHE
                            AddOrUpdateIExecuteToCache(name, procedure, false, false);
#endif

#if ARGUMENT_CACHE
                            /* IGNORED */
                            MaybeClearArgumentCache(name);
#endif

#if NOTIFY
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Procedure, NotifyFlags.Updated,
                                new ObjectPair(oldProcedureWrapper, procedure), this,
                                null, null, null, ref result);
#endif
                        }
                        else if ((procedureLimit == Limits.Unlimited) || (procedures.Count < procedureLimit))
                        {
                            procedures.Add(name, wrapper as ProcedureWrapper);
                            success = true;

#if EXECUTE_CACHE
                            AddOrUpdateIExecuteToCache(name, procedure, false, false);
#endif

#if ARGUMENT_CACHE
                            /* IGNORED */
                            MaybeClearArgumentCache(name);
#endif

#if NOTIFY
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Procedure, NotifyFlags.Added,
                                new ObjectPair(procedure, newToken), this,
                                null, null, null, ref result);
#endif
                        }
                        else
                        {
                            result = String.Format(
                                "can't add procedure {0}: limit exceeded",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level rename of a procedure,
        /// preserving its token, or removes it when deletion is requested.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the procedure to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the procedure.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to skip namespace-aware import renaming and validation.
        /// </param>
        /// <param name="delete">
        /// Non-zero to remove the procedure when the new name is null or
        /// empty.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be renamed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was
        /// renamed or removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameProcedure(
            string oldName,
            string newName,
            bool noNamespaces,
            bool delete,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasProcedures(ref result))
                {
                    if (!delete || !String.IsNullOrEmpty(newName))
                    {
                        IProcedure oldProcedure = null;

                        if (GetProcedure(oldName, LookupFlags.Default, ref oldProcedure, ref result) == ReturnCode.Ok)
                        {
                            if (!EntityOps.IsReadOnly(oldProcedure))
                            {
                                if (EntityOps.IsNoRename(oldProcedure))
                                    return ReturnCode.Ok;

                                ProcedureWrapper oldWrapper = oldProcedure as ProcedureWrapper;

                                if (oldWrapper != null)
                                {
                                    IAlias oldAlias = oldWrapper.procedure as IAlias;

                                    if (PreventAliasLoop(oldAlias, newName, ref result) == ReturnCode.Ok)
                                    {
                                        if (IsValidAnyIExecuteName(newName, noNamespaces, ref result) == ReturnCode.Ok)
                                        {
                                            bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();

                                            if (!useNamespaces ||
                                                RenameImportInNamespaces(oldName, newName, ref result) == ReturnCode.Ok)
                                            {
                                                //
                                                // NOTE: New name, same token.
                                                //
                                                oldWrapper.Name = newName;

                                                /* IGNORED */
                                                procedures.Rename(oldName, newName);

#if EXECUTE_CACHE
                                                RenameIExecuteInCache(oldName, newName, oldWrapper, false, false);
#endif

#if ARGUMENT_CACHE
                                                /* IGNORED */
                                                MaybeClearArgumentCache(oldName);

                                                /* IGNORED */
                                                MaybeClearArgumentCache(newName);
#endif

#if NOTIFY
                                                /* IGNORED */
                                                CheckNotification(
                                                    NotifyType.Procedure, NotifyFlags.Renamed,
                                                    new ObjectTriplet(oldProcedure, oldName, newName), this,
                                                    null, null, null, ref result);
#endif

                                                result = String.Empty;
                                                return ReturnCode.Ok;
                                            }
                                        }
                                    }
                                }
                                else
                                {
                                    result = String.Format(
                                        "can't rename {0}: invalid procedure wrapper",
                                        FormatOps.WrapOrNull(oldName));
                                }
                            }
                            else
                            {
                                result = "procedure is read-only";
                            }
                        }
                        else
                        {
                            result = String.Format(
                                "can't rename {0}: procedure doesn't exist",
                                FormatOps.WrapOrNull(oldName));
                        }
                    }
                    else
                    {
                        return RemoveProcedure(oldName, null, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the low-level removal of a procedure, or
        /// hidden procedure, from this interpreter, also removing any
        /// associated namespace imports.
        /// </summary>
        /// <param name="name">
        /// The name of the procedure to remove.
        /// </param>
        /// <param name="token">
        /// The token associated with the procedure to remove.
        /// </param>
        /// <param name="procedure">
        /// The procedure being removed.  This parameter may be null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="hidden">
        /// Non-zero if the procedure being removed is a hidden procedure.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was
        /// removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveProcedure(
            string name,
            long token,
            IProcedure procedure,
            IClientData clientData,
            bool hidden,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid procedure name";
                return ReturnCode.Error;
            }

            GlobalState.PushActiveInterpreter(this);

            try
            {
                if (InternalAreNamespacesEnabled() &&
                    RemoveImportFromNamespaces(name, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

#if NATIVE && TCL
                if ((procedure == null) ||
                    (DisposeTclBridges(IntPtr.Zero, procedure, null, false, ref result) == ReturnCode.Ok))
#endif
                {
                    if (hidden)
                        /* IGNORED */
                        hiddenProcedures.Remove(name, token);
                    else
                        /* IGNORED */
                        procedures.Remove(name, token);

#if EXECUTE_CACHE
                    RemoveIExecuteFromCache(name, hidden, false);
#endif

#if ARGUMENT_CACHE
                    /* IGNORED */
                    MaybeClearArgumentCache(name);
#endif

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(hidden ?
                        NotifyType.HiddenProcedure : NotifyType.Procedure,
                        NotifyFlags.Removed, new ObjectTriplet(procedure,
                            name, token), this, clientData, null, null,
                        ref result);
#endif

                    return ReturnCode.Ok;
                }

#if NATIVE && TCL
                return ReturnCode.Error;
#endif
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while removing {0}procedure: {1}",
                    hidden ? "hidden " : String.Empty, e);

                return ReturnCode.Error;
            }
            finally
            {
                /* IGNORED */
                GlobalState.PopActiveInterpreter();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the procedure identified by the specified
        /// token from this interpreter.
        /// </summary>
        /// <param name="token">
        /// The token that identifies the procedure to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="name">
        /// Upon success, this is set to the name of the procedure that was
        /// removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was
        /// removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveProcedure(
            long token,
            IClientData clientData,
            ref string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                IProcedure procedure = null;

                if (PrivateGetProcedure(
                        token, LookupFlags.Default, ref name,
                        ref procedure, ref result) == ReturnCode.Ok)
                {
                    if (!EntityOps.IsReadOnly(procedure))
                    {
                        if (EntityOps.IsNoRemove(procedure))
                            return ReturnCode.Ok;

                        return PrivateRemoveProcedure(
                            name, token, procedure, clientData,
                            false, ref result);
                    }
                    else
                    {
                        result = "procedure is read-only";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named procedure from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the procedure to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the remove operation.  This
        /// parameter may be null.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the
        /// procedure that was removed.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// procedure could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the procedure was
        /// removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalRemoveProcedure(
            string name,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                IProcedure procedure = null;

                if (PrivateGetProcedure(
                        name, LookupFlags.Default, ref token,
                        ref procedure, ref result) == ReturnCode.Ok)
                {
                    if (!EntityOps.IsReadOnly(procedure))
                    {
                        if (EntityOps.IsNoRemove(procedure))
                            return ReturnCode.Ok;

                        return PrivateRemoveProcedure(
                            name, token, procedure, clientData,
                            false, ref result);
                    }
                    else
                    {
                        result = "procedure is read-only";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if TEST
        /// <summary>
        /// This method removes all of the procedures whose flags match the
        /// specified criteria from this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The client data to associate with the remove operations.  This
        /// parameter may be null.
        /// </param>
        /// <param name="hasFlags">
        /// The procedure flags that a procedure must have to be removed.
        /// This parameter may be null.
        /// </param>
        /// <param name="notHasFlags">
        /// The procedure flags that a procedure must not have to be
        /// removed.  This parameter may be null.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="hasFlags" /> be present.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the flags in <paramref
        /// name="notHasFlags" /> be present before a procedure is excluded.
        /// </param>
        /// <param name="count">
        /// Upon return, this is incremented by the number of procedures
        /// that were successfully removed.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing why one
        /// or more procedures could not be removed.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if all matching procedures
        /// were removed; otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveProcedures(
            IClientData clientData,
            ProcedureFlags? hasFlags,
            ProcedureFlags? notHasFlags,
            bool hasAll,
            bool notHasAll,
            ref int count,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                // if (!IsModifiable(false, ref error))
                //     return ReturnCode.Error;

                if (!PrivateHasProcedures(ref error))
                    return ReturnCode.Error;

                LongList tokens = null;

                foreach (ProcedurePair pair in procedures)
                {
                    IProcedure procedure = pair.Value;

                    if (procedure == null)
                        continue;

                    ProcedureFlags procedureFlags = procedure.Flags;

                    if ((hasFlags != null) && !FlagOps.HasFlags(
                            procedureFlags, (ProcedureFlags)hasFlags,
                            hasAll))
                    {
                        continue;
                    }

                    if ((notHasFlags != null) && FlagOps.HasFlags(
                            procedureFlags, (ProcedureFlags)notHasFlags,
                            notHasAll))
                    {
                        continue;
                    }

                    if (tokens == null)
                        tokens = new LongList();

                    tokens.Add(procedure.Token);
                }

                if (tokens != null)
                {
                    ResultList errors = null;

                    foreach (long token in tokens)
                    {
                        string name = null; /* NOT USED */
                        Result result = null;

                        if (InternalRemoveProcedure(
                                token, clientData, ref name,
                                ref result) == ReturnCode.Ok)
                        {
                            count++;
                        }
                        else
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(result);
                        }
                    }

                    if (errors != null)
                    {
                        error = errors;
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
        }
#endif

