        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode ListOperators(
            OperatorFlags hasFlags,
            OperatorFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            bool strict,
            ref StringList list,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasOperators(ref localError))
                {
                    code = operators.ToList(
                        hasFlags, notHasFlags, hasAll, notHasAll,
                        pattern, noCase, full, ref list, ref error);
                }
                else if (strict)
                {
                    error = localError;
                }
                else
                {
                    if (list == null)
                        list = new StringList();

                    code = ReturnCode.Ok;
                }
            }

            return code;
