        #region Channel
        /// <summary>
        /// This method determines whether the specified stream is the
        /// underlying stream of the named channel.
        /// </summary>
        /// <param name="name">
        /// The name of the channel to check.
        /// </param>
        /// <param name="channelType">
        /// The type of channel, used together with the name to compute the
        /// channel identifier.
        /// </param>
        /// <param name="stream">
        /// The stream to compare against the underlying stream of the channel.
        /// </param>
        /// <returns>
        /// True if the named channel exists and its underlying stream is the
        /// same instance as <paramref name="stream" />; otherwise, false.
        /// </returns>
        public bool IsStreamForChannel(
            string name,
            ChannelType channelType,
            Stream stream
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                string channelId = RuntimeOps.ChannelTypeToName(
                    name, channelType);

                if ((channelId == null) || (stream == null))
                    return false;

                if (!InternalHasChannels())
                    return false;

                IChannel channel;

                if (!channels.TryGetValue(channelId, out channel))
                    return false;

                if (channel == null)
                    return false;

                ChannelStream channelStream = channel.GetStream();

                if (channelStream == null)
                    return false;

                Stream innerStream = channelStream.GetStream();

                return Object.ReferenceEquals(stream, innerStream);
            }
        }

