        /// <summary>
        /// This method removes the named channel from this interpreter,
        /// optionally flushing and closing it first.
        /// </summary>
        /// <param name="name">
        /// The name of the channel to remove.
        /// </param>
        /// <param name="channelType">
        /// The type of channel, used together with the name to compute the
        /// channel identifier.
        /// </param>
        /// <param name="flush">
        /// Non-zero to flush the channel before removing it.
        /// </param>
        /// <param name="close">
        /// Non-zero to close the channel before removing it.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error when the channel cannot be found or
        /// when flushing or closing it fails.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RemoveChannel(
            string name,
            ChannelType channelType,
            bool flush,
            bool close,
            bool strict,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                string channelId = RuntimeOps.ChannelTypeToName(
                    name, channelType);

                if (channelId == null)
                {
                    error = "invalid channel name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasChannels(ref error))
                    return ReturnCode.Error;

                IChannel channel;

                if (channels.TryGetValue(channelId, out channel))
                {
                    if (flush && (channel != null))
                    {
                        try
                        {
                            //
                            // NOTE: Attempt to flush the channel.
                            //
                            channel.Flush(); /* throw */
                        }
                        catch (Exception e)
                        {
                            if (strict)
                            {
                                error = e;
                                return ReturnCode.Error;
                            }
                        }
                    }

                    if (close && (channel != null))
                    {
                        try
                        {
                            //
                            // NOTE: Attempt to close the channel.
                            //
                            channel.Close(); /* throw */
                        }
                        catch (Exception e)
                        {
                            if (strict)
                            {
                                error = e;
                                return ReturnCode.Error;
                            }
                        }
                    }

                    channels.Remove(channelId);

                    return ReturnCode.Ok;
                }
                else if (strict)
                {
                    error = String.Format(
                        "can not find channel named {0}",
                        FormatOps.WrapOrNull(channelId));

                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

