        #region Private
        /// <summary>
        /// This method adds a new channel, wrapping the specified stream, to
        /// this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new channel.
        /// </param>
        /// <param name="channelType">
        /// The type of channel, used together with the name to compute the
        /// channel identifier.
        /// </param>
        /// <param name="stream">
        /// The stream to be wrapped by the new channel.
        /// </param>
        /// <param name="options">
        /// The options to associate with the new channel.
        /// </param>
        /// <param name="streamFlags">
        /// The flags that control the behavior of the underlying channel
        /// stream.
        /// </param>
        /// <param name="inTranslation">
        /// The end-of-line translation to use when reading from the channel.
        /// </param>
        /// <param name="outTranslation">
        /// The end-of-line translation to use when writing to the channel.
        /// </param>
        /// <param name="encoding">
        /// The encoding to use for the channel, or null for the default.
        /// </param>
        /// <param name="availableTimeout">
        /// The timeout, in milliseconds, used when checking for available
        /// input on the channel, or null for none.
        /// </param>
        /// <param name="nullEncoding">
        /// Non-zero if a null encoding should be permitted for the channel.
        /// </param>
        /// <param name="appendMode">
        /// Non-zero if the channel should operate in append mode.
        /// </param>
        /// <param name="autoFlush">
        /// Non-zero if the channel should be flushed automatically after each
        /// write.
        /// </param>
        /// <param name="rawEndOfStream">
        /// Non-zero to use raw end-of-stream handling for the channel.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the new channel, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddChannel(
            string name,
            ChannelType channelType,
            Stream stream,
            OptionDictionary options,
            StreamFlags streamFlags,
            StreamTranslation inTranslation,
            StreamTranslation outTranslation,
            Encoding encoding,
            int? availableTimeout,
            bool nullEncoding,
            bool appendMode,
            bool autoFlush,
            bool rawEndOfStream,
            IClientData clientData,
            ref Result error
            )
        {
            // CheckDisposed();

            ReturnCode code = ReturnCode.Ok;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                string channelId = RuntimeOps.ChannelTypeToName(
                    name, channelType);

                if (channelId == null)
                {
                    error = "invalid channel name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasChannels(ref error))
                    return ReturnCode.Error;

                if (channels.ContainsKey(channelId)) /* EXEMPT */
                {
                    error = String.Format(
                        "can't add {0}: channel already exists",
                        FormatOps.WrapOrNull(channelId));

                    return ReturnCode.Error;
                }

                ChannelStream channelStream = null;
                IChannel channel = null;

                try
                {
                    channelStream = new ChannelStream(
                        stream, channelType, options, streamFlags,
                        inTranslation, outTranslation);

                    channel = Channel.Create(
                        channelStream, encoding, nullEncoding,
                        appendMode, autoFlush, rawEndOfStream,
                        clientData);

                    if (channelStream != null)
                    {
#if NETWORK
                        channelStream.AvailableTimeout = availableTimeout;
#endif

                        if (channelStream.NeedBuffer && (channel != null))
                            channel.NewBuffered();
                    }

                    channels.Add(name, channel);

                    code = ReturnCode.Ok;
                }
                catch (Exception e)
                {
                    error = e;
                    code = ReturnCode.Error;
                }
                finally
                {
                    if (code != ReturnCode.Ok)
                    {
                        if (channelStream != null)
                        {
                            channelStream.PreventClose = false;
                            channelStream.Close();
                            channelStream = null;
                        }

                        if (channel != null)
                        {
                            channel.Close();
                            channel = null;
                        }
                    }
                }
            }

            return code;
        }
        #endregion
        #endregion

