        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method locks the named scope so that it cannot be modified or
        /// removed until it is unlocked.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to lock.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode LockScope(
            string name,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasScopes(ref error))
                    return ReturnCode.Error;

                ICallFrame frame = null;

                if (GetScope(name,
                        LookupFlags.Default | LookupFlags.NoUsable,
                        ref frame, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (frame == null)
                {
                    error = "invalid call frame";
                    return ReturnCode.Error;
                }

                if (!frame.Lock(ref error))
                    return ReturnCode.Error;

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method unlocks the named scope so that it can be modified or
        /// removed again.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to unlock.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode UnlockScope(
            string name,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasScopes(ref error))
                    return ReturnCode.Error;

                ICallFrame frame = null;

                if (GetScope(name,
                        LookupFlags.Default | LookupFlags.NoUsable,
                        ref frame, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (frame == null)
                {
                    error = "invalid call frame";
                    return ReturnCode.Error;
                }

                if (!frame.Unlock(ref error))
                    return ReturnCode.Error;

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method looks up the scope call frame with the specified name,
        /// discarding any error message.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the scope is looked up.
        /// </param>
        /// <param name="frame">
        /// Upon success, receives the matching scope call frame.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalGetScope(
            string name,
            LookupFlags lookupFlags,
            ref ICallFrame frame
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result error = null;

                return PrivateGetScope(
                    name, lookupFlags, ref frame, ref error);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the scope call frame with
        /// the specified name.  An empty scope name is technically allowed.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the scope is looked up.
        /// </param>
        /// <param name="frame">
        /// Upon success, receives the matching scope call frame.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetScope(
            string name,
            LookupFlags lookupFlags,
            ref ICallFrame frame,
            ref Result error
            )
        {
            if (PrivateHasScopes(ref error))
            {
                //
                // NOTE: *WARNING* Empty scope names are technically allowed,
                //       please do not change this to "!String.IsNullOrEmpty".
                //
                //       That being said, we actually block them for practical
                //       reasons in the [scope] command itself.
                //
                if (name != null)
                {
                    ICallFrame localFrame;

                    if (scopes.TryGetValue(name, out localFrame))
                    {
                        bool noUsable = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.NoUsable, true);

                        if (noUsable || (localFrame == null) ||
                            localFrame.IsUsable(ref error))
                        {
                            frame = localFrame;
                            return ReturnCode.Ok;
                        }
                    }
                    else
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "scope {0} not found",
                                FormatOps.WrapOrNull(name)) :
                            "scope not found";
                    }
                }
                else
                {
                    error = "invalid scope name";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method produces the string form of the scopes defined in this
        /// interpreter, optionally filtered by a name pattern.
        /// </summary>
        /// <param name="pattern">
        /// An optional pattern used to match scope names, or null to match all
        /// of them.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the string form of the matching scopes.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ScopesToString(
            string pattern,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasScopes())
                    result = scopes.ToString(pattern, false); /* EXEMPT */
                else
                    result = String.Empty;
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified scope call frame to this
        /// interpreter, subject to the configured scope limit.
        /// </summary>
        /// <param name="frame">
        /// The scope call frame to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddScope(
            ICallFrame frame,
            IClientData clientData,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (frame == null)
                {
                    result = "invalid scope";
                    return ReturnCode.Error;
                }

                if (!frame.IsUsable(ref result))
                    return ReturnCode.Error;

                string name = frame.Name;

                if (name == null)
                {
                    result = "invalid scope name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasScopes(ref result))
                    return ReturnCode.Error;

                if (DoesScopeExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: scope already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                if ((scopeLimit != Limits.Unlimited) &&
                    (scopes.Count >= scopeLimit))
                {
                    result = String.Format(
                        "can't add {0}: scope limit exceeded",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                scopes.Add(name, frame);
                result = String.Empty;
            }

#if NOTIFY
            //
            // NOTE: This must be done outside of the lock statement (above),
            //       because the code called may have arbitrary side-effects.
            //
            /* IGNORED */
            CheckNotification(
                NotifyType.CallFrame, NotifyFlags.Added,
                frame, this, clientData, null, null,
                ref result);
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named scope from this interpreter,
        /// detaching its namespace and unsetting it as the global scope when
        /// applicable.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="list">
        /// Upon success, receives the list of variables affected by removing
        /// the scope.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveScope(
            string name,
            IClientData clientData,
            ref StringList list,
            ref Result result
            )
        {
            ICallFrame frame; /* REUSED */

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (String.IsNullOrEmpty(name))
                {
                    result = "invalid scope name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasScopes(ref result))
                    return ReturnCode.Error;

                //
                // NOTE: If the specified scope call frame was used with
                //       the [scope global] sub-command, unset it now.
                //
                frame = GlobalScopeFrame;

                if ((frame != null) &&
                    SharedStringOps.SystemEquals(frame.Name, name))
                {
                    if (!frame.IsUsable(ref result))
                        return ReturnCode.Error;

                    if (UnsetGlobalScopeCallFrame(
                            true, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }

                frame = null;

                if (GetScopeCallFrame(
                        name, LookupFlags.RemoveNoVerbose, true, true,
                        ref frame, ref list) == ReturnCode.Ok)
                {
                    //
                    // NOTE: We destroyed the current scope call frame
                    //       (after popping it).
                    //
                    // BUGFIX: Cannot return here, need to cleanup references
                    //         via the notification at the end of the method.
                    //
                    result = String.Empty;
                }
                else
                {
                    //
                    // NOTE: Make sure the scope exists and return an error
                    //       if it does not.
                    //
                    frame = null;

                    if (GetScope(
                            name, LookupFlags.Remove, ref frame,
                            ref result) == ReturnCode.Ok)
                    {
                        if (NamespaceOps.DetachScope(
                                this, null, frame, ref list,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        /* IGNORED */
                        scopes.Remove(name);
                        result = String.Empty;
                    }
                    else
                    {
                        return ReturnCode.Error;
                    }
                }
            }

#if NOTIFY || NOTIFY_OBJECT
            //
            // NOTE: This must be done outside of the lock statement (above),
            //       because the code called may have arbitrary side-effects.
            //
            /* IGNORED */
            CheckNotification(
                NotifyType.CallFrame, NotifyFlags.Deleted,
                frame, this, clientData, null, null,
                ref result);
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method invokes the specified callback once for each usable
        /// scope call frame in this interpreter.
        /// </summary>
        /// <param name="callback">
        /// The callback to invoke for each scope call frame.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass to the callback, if any.
        /// </param>
        /// <param name="errorOnLocked">
        /// Non-zero to return an error when a scope is locked; zero to skip
        /// locked scopes.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InvokeInEachScope(
            CallFrameCallback callback,
            IClientData clientData,
            bool errorOnLocked,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (callback == null)
                {
                    error = "invalid callback";
                    return ReturnCode.Error;
                }

                if (!PrivateHasScopes(ref error))
                    return ReturnCode.Error;

                ReturnCode code = ReturnCode.Ok;
                Result localError; /* REUSED */

                foreach (CallFramePair pair in scopes)
                {
                    ICallFrame frame = pair.Value;

                    if (frame == null)
                        continue;

                    localError = null;

                    if (!frame.IsUsable(ref localError))
                    {
                        if (errorOnLocked)
                        {
                            error = localError;
                            code = ReturnCode.Error;

                            break;
                        }
                        else
                        {
                            continue;
                        }
                    }

                    localError = null;

                    code = callback(frame, clientData, ref localError);

                    if (code != ReturnCode.Ok)
                    {
                        error = localError;
                        break;
                    }
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by [scope eval] sub-command implementation only.
        //
        /// <summary>
        /// This method attempts to lock the named scope, waiting up to the
        /// specified number of microseconds for it to become available.
        /// </summary>
        /// <param name="eventWaitFlags">
        /// The flags that control how the method waits for the scope to become
        /// available.
        /// </param>
        /// <param name="name">
        /// The name of the scope to lock.
        /// </param>
        /// <param name="microseconds">
        /// The maximum number of microseconds to wait for the scope, or zero
        /// to wait indefinitely.  This value cannot be negative.
        /// </param>
        /// <param name="event">
        /// An optional event used to interrupt the wait, or null for none.
        /// </param>
        /// <param name="frame">
        /// Upon success, receives the locked scope call frame.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalLockScope(
            EventWaitFlags eventWaitFlags, /* in */
            string name,                   /* in */
            long microseconds,             /* in */
            EventWaitHandle @event,        /* in, optional */
            ref ICallFrame frame,          /* out */
            ref Result error               /* out */
            ) /* THREAD-SAFE */
        {
            if (microseconds < 0)
            {
                error = "number of microseconds cannot be negative";
                return ReturnCode.Error;
            }

            //
            // TODO: Maybe make this more adjustable?
            //
            int readyMilliseconds = GetEffectiveReadyTimeout(
                this, (microseconds != 0) ? null : (int?)0);

            bool noTimeout = (readyMilliseconds <= 0) || FlagOps.HasFlags(
                eventWaitFlags, EventWaitFlags.NoTimeout, true);

            bool noCancel = FlagOps.HasFlags(
                eventWaitFlags, EventWaitFlags.NoCancel, true);

            bool noGlobalCancel = FlagOps.HasFlags(
                eventWaitFlags, EventWaitFlags.NoGlobalCancel, true);

            bool noWindows = FlagOps.HasFlags(
                eventWaitFlags, EventWaitFlags.NoWindows, true);

            bool noWait = FlagOps.HasFlags(
                eventWaitFlags, EventWaitFlags.NoWait, true);

            bool noSleep = FlagOps.HasFlags(
                eventWaitFlags, EventWaitFlags.NoSleep, true);

            bool trace = FlagOps.HasFlags(
                eventWaitFlags, EventWaitFlags.Trace, true);

            long startCount = PerformanceOps.GetCount();
            long stopCount = 0;

            long slopMicroseconds = EventOps.GetSlopMicroseconds(
                microseconds);

            int sleepMilliseconds = GetMinimumSleepTime(
                SleepType.Variable, EventOps.GetMilliseconds(
                microseconds));

            Result localError = null; /* REUSED */

            while ((microseconds == 0) || !PerformanceOps.HasElapsed(
                    startCount, ref stopCount, microseconds, slopMicroseconds))
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    ICallFrame localFrame = null;

                    localError = null;

                    if (GetScope(
                            name, LookupFlags.Default | LookupFlags.NoUsable,
                            ref localFrame, ref localError) != ReturnCode.Ok)
                    {
                        error = localError;
                        break;
                    }

                    localError = null;

                    if (localFrame.IsLocked() ||
                        localFrame.Lock(ref localError))
                    {
                        frame = localFrame;
                        return ReturnCode.Ok;
                    }

                    if (noWait)
                    {
                        error = localError;
                        return ReturnCode.Error;
                    }
                }

                if (!noSleep) // NOTE: Somewhat dangerous for CPU usage.
                {
                    localError = null;

                    if (EventOps.Wait(this, @event,
                            PerformanceOps.GetMicrosecondsFromMilliseconds(
                                sleepMilliseconds),
                            PerformanceOps.GetMicrosecondsFromMilliseconds(
                                readyMilliseconds),
                            !noTimeout, noWindows, noCancel, noGlobalCancel,
                            trace, ref localError) != ReturnCode.Ok)
                    {
                        error = localError;
                        break;
                    }
                }
            }

            if (localError != null)
            {
                error = localError;
            }
            else
            {
                error = String.Format(
                    "timed out attempting to lock scope {0}",
                    FormatOps.DisplayName(name));
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by [scope eval] sub-command implementation only.
        //
        /// <summary>
        /// This method unlocks the specified scope call frame previously
        /// locked via <c>InternalLockScope</c>.
        /// </summary>
        /// <param name="frame">
        /// The scope call frame to unlock.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalUnlockScope(
            ICallFrame frame,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (frame == null)
                {
                    error = "invalid call frame";
                    return ReturnCode.Error;
                }

                if (!frame.MaybeUnlock(ref error))
                    return ReturnCode.Error;

                return ReturnCode.Ok;
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IDbConnection / IDbTransaction
#if DATA
        #region Database Trace Callback
        #region Support Methods
        /// <summary>
        /// This method determines whether the specified trace callback is the
        /// built-in database trace callback.
        /// </summary>
        /// <param name="callback">
        /// The trace callback to check.
        /// </param>
        /// <returns>
        /// True if the callback is the database trace callback; otherwise,
        /// false.
        /// </returns>
        internal static bool IsDbTraceCallback(
            TraceCallback callback /* in */
            )
        {
            return callback == DbTraceCallback;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the DbTraceCallback method only.
        //
        /// <summary>
        /// This method collects the database connections whose names appear in
        /// the specified list, adding them to the supplied dictionary.
        /// </summary>
        /// <param name="names">
        /// The names of the database connections to collect.
        /// </param>
        /// <param name="connections">
        /// Upon return, receives the matching database connections; existing
        /// entries are preserved.
        /// </param>
        private void GetDbConnectionsForTrace(
            StringList names,                      /* in */
            ref DbConnectionDictionary connections /* in, out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (names == null)
                    return;

                DbConnectionDictionary localConnections = this.connections;

                if ((localConnections == null) || (localConnections.Count == 0))
                    return;

                foreach (string name in names)
                {
                    if (name == null)
                        continue;

                    if ((connections != null) && connections.ContainsKey(name))
                        continue;

                    IDbConnection connection;

                    if (localConnections.TryGetValue(name, out connection))
                    {
                        if (connections == null)
                            connections = new DbConnectionDictionary();

                        connections.Add(name, connection);
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the DbTraceCallback method only.
        //
        /// <summary>
        /// This method collects the database transactions whose names appear in
        /// the specified list, adding them to the supplied dictionary.
        /// </summary>
        /// <param name="names">
        /// The names of the database transactions to collect.
        /// </param>
        /// <param name="transactions">
        /// Upon return, receives the matching database transactions; existing
        /// entries are preserved.
        /// </param>
        private void GetDbTransactionsForTrace(
            StringList names,                        /* in */
            ref DbTransactionDictionary transactions /* in, out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (names == null)
                    return;

                DbTransactionDictionary localTransactions = this.transactions;

                if ((localTransactions == null) || (localTransactions.Count == 0))
                    return;

                foreach (string name in names)
                {
                    if (name == null)
                        continue;

                    if ((transactions != null) && transactions.ContainsKey(name))
                        continue;

                    IDbTransaction transaction;

                    if (localTransactions.TryGetValue(name, out transaction))
                    {
                        if (transactions == null)
                            transactions = new DbTransactionDictionary();

                        transactions.Add(name, transaction);
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to commit or roll back the specified database
        /// transaction, accumulating any errors that occur.
        /// </summary>
        /// <param name="transaction">
        /// The database transaction to commit or roll back.
        /// </param>
        /// <param name="commit">
        /// Upon entry, non-zero to attempt a commit or zero to attempt a
        /// rollback; if a commit fails, it is set to false to force a
        /// subsequent rollback.
        /// </param>
        /// <param name="errors">
        /// Upon failure, receives any errors that occurred; existing entries
        /// are preserved.
        /// </param>
        /// <returns>
        /// True if the commit or rollback succeeded; otherwise, false.
        /// </returns>
        private static bool CommitOrRollback(
            IDbTransaction transaction, /* in */
            ref bool commit,            /* in, out */
            ref ResultList errors       /* in, out */
            )
        {
            try
            {
                if (commit)
                    transaction.Commit(); /* throw */
                else
                    transaction.Rollback(); /* throw */

                return true;
            }
            catch (Exception e)
            {
                if (commit)
                    commit = false; // NOTE: Force rollback?

                if (errors == null)
                    errors = new ResultList();

                errors.Add(e);
                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the value of the named variable, attaching the
        /// database trace used to clean up connections and transactions.
        /// </summary>
        /// <param name="name">
        /// The name of the variable to set.
        /// </param>
        /// <param name="value">
        /// The value to assign to the variable.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode SetDbVariableValue(
            string name,     /* in */
            string value,    /* in */
            ref Result error /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return SetVariableValue(
                    VariableFlags.None, name, value, dbTraceList,
                    ref error);
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method is the variable trace callback that automatically
        /// commits or rolls back database transactions and closes database
        /// connections when the variables referencing them are unset.
        /// </summary>
        /// <param name="breakpointType">
        /// The type of trace operation being performed; only the unset
        /// operation is handled.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter associated with the variable being traced.
        /// </param>
        /// <param name="traceInfo">
        /// The information about the variable trace being performed.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        [MethodFlags(
            MethodFlags.VariableTrace | MethodFlags.System |
            MethodFlags.NoAdd)]
        private static ReturnCode DbTraceCallback(
            BreakpointType breakpointType, /* in */
            Interpreter interpreter,       /* in */
            ITraceInfo traceInfo,          /* in */
            ref Result result              /* out */
            )
        {
            if (breakpointType != BreakpointType.BeforeVariableUnset)
                return ReturnCode.Ok;

            if (traceInfo == null)
            {
                result = "invalid trace";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(
                    traceInfo.Flags, VariableFlags.NoObject, true))
            {
                return ReturnCode.Ok;
            }

            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            IVariable variable = traceInfo.Variable;

            if (variable == null)
            {
                result = "invalid variable";
                return ReturnCode.Error;
            }

            StringList oldValues = null;

            if (!EntityOps.IsUndefined(variable))
            {
                ElementDictionary arrayValue = null;

                if ((traceInfo.Index == null) &&
                    EntityOps.IsArray(variable, ref arrayValue))
                {
                    ScriptOps.GatherTraceValues(
                        null, null, null, arrayValue,
                        ref oldValues);
                }
                else if (traceInfo.OldValue != null)
                {
                    ScriptOps.GatherTraceValues(
                        null, null, traceInfo.OldValue,
                        null, ref oldValues);
                }
            }

            ScriptOps.GatherTraceValues(
                traceInfo.Name, traceInfo.Index, null,
                traceInfo.OldValues, ref oldValues);

            if (oldValues == null)
                return ReturnCode.Ok;

            DbConnectionDictionary oldConnections = null;

            interpreter.GetDbConnectionsForTrace(
                oldValues, ref oldConnections);

            DbTransactionDictionary oldTransactions = null;

            interpreter.GetDbTransactionsForTrace(
                oldValues, ref oldTransactions);

            string oldName; /* REUSED */
            ResultList errors = null;

            if (oldTransactions != null)
            {
                bool wasSuccess = FlagOps.HasFlags(
                    traceInfo.Flags, VariableFlags.Success, true);

                foreach (DbTransactionPair pair in oldTransactions)
                {
                    IDbTransaction oldTransaction = pair.Value;

                    if (oldTransaction == null)
                        continue;

                    oldName = pair.Key;

                    bool isSuccess = wasSuccess;

                    if (CommitOrRollback(
                            oldTransaction, ref isSuccess, ref errors))
                    {
                        if (!interpreter.RemoveDbTransaction(oldName))
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(String.Format(
                                "cannot remove database transaction {0} after {1}",
                                FormatOps.WrapOrNull(oldName), isSuccess ?
                                "initial commit" : "initial rollback"));
                        }
                    }
                    else if (wasSuccess && !isSuccess && CommitOrRollback(
                            oldTransaction, ref isSuccess, ref errors))
                    {
                        if (!interpreter.RemoveDbTransaction(oldName))
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(String.Format(
                                "cannot remove database transaction {0} after {1}",
                                FormatOps.WrapOrNull(oldName), isSuccess ?
                                "fail-safe commit" : "fail-safe rollback"));
                        }
                    }
                }
            }

            if (oldConnections != null)
            {
                foreach (DbConnectionPair pair in oldConnections)
                {
                    IDbConnection oldConnection = pair.Value;

                    if (oldConnection == null)
                        continue;

                    oldName = pair.Key;

                    try
                    {
                        oldConnection.Close(); /* throw */

                        if (!interpreter.RemoveDbConnection(oldName))
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(String.Format(
                                "cannot remove database connection {0}",
                                FormatOps.WrapOrNull(oldName)));
                        }
                    }
                    catch (Exception e)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(e);
                    }
                }
            }

            if (errors != null)
                DebugOps.Complain(interpreter, ReturnCode.Error, errors);

            return ReturnCode.Ok;
        }
        #endregion

