        /// <summary>
        /// This method looks up the database connection with the specified
        /// name, falling back to a matching object whose value is a database
        /// connection.
        /// </summary>
        /// <param name="name">
        /// The name of the database connection or object to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the database connection or object is
        /// looked up.
        /// </param>
        /// <param name="connection">
        /// Upon success, receives the matching database connection.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetAnyDbConnection(
            string name,
            LookupFlags lookupFlags,
            ref IDbConnection connection,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                ResultList errors = null;
                IDbConnection localConnection = null; /* REUSED */
                Result localError = null; /* REUSED */

                if (PrivateGetDbConnection(
                        name, lookupFlags, ref localConnection,
                        ref localError) == ReturnCode.Ok)
                {
                    connection = localConnection;
                    return ReturnCode.Ok;
                }

                if (localError != null)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(localError);
                }

                if (!FlagOps.HasFlags(
                        lookupFlags, LookupFlags.NoObject, true))
                {
                    IObject @object = null;

                    localError = null;

                    if (PrivateGetObject(
                            name, lookupFlags, ref @object,
                            ref localError) == ReturnCode.Ok)
                    {
                        if (@object != null)
                        {
                            localConnection =
                                @object.Value as IDbConnection;

                            if (!FlagOps.HasFlags(lookupFlags,
                                    LookupFlags.Validate, true) ||
                                (localConnection != null))
                            {
                                connection = localConnection;
                                return ReturnCode.Ok;
                            }
                            else
                            {
                                localError = String.Format(
                                    "object {0} is not {1}",
                                    FormatOps.DisplayName(name),
                                    MarshalOps.GetErrorTypeName(
                                        typeof(IDbConnection)));
                            }
                        }
                        else
                        {
                            localError = String.Format(
                                "object {0} is invalid",
                                FormatOps.DisplayName(name));
                        }
                    }

                    if (localError != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }
                }

                if (errors != null)
                    error = errors;

                return ReturnCode.Error;
            }
        }

