        //
        // NOTE: This method assumes the lock is already held.
        //
        /// <summary>
        /// This method performs the actual lookup of the database connection
        /// with the specified name.  This method assumes the lock is already
        /// held.  An empty connection name is technically allowed.
        /// </summary>
        /// <param name="name">
        /// The name of the database connection to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the database connection is looked up.
        /// </param>
        /// <param name="connection">
        /// Upon success, receives the matching database connection.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetDbConnection(
            string name,
            LookupFlags lookupFlags,
            ref IDbConnection connection,
            ref Result error
            )
        {
            if (PrivateHasDbConnections(ref error))
            {
                //
                // NOTE: *WARNING* Empty database connection names are allowed,
                //       please do not change this to "!String.IsNullOrEmpty".
                //
                if (name != null)
                {
                    if (connections.TryGetValue(name, out connection))
                    {
                        if ((connection == null) && FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Validate, true))
                        {
                            error = "invalid connection";
                            return ReturnCode.Error;
                        }
                        else
                        {
                            return ReturnCode.Ok;
                        }
                    }
                    else
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "database connection {0} not found",
                                FormatOps.WrapOrNull(name)) :
                            "database connection not found";
                    }
                }
                else
                {
                    error = "invalid database connection name";
                }
            }

            return ReturnCode.Error;
        }

