        #region Encoding
        /// <summary>
        /// This method looks up the encoding with the specified name, falling
        /// back to a matching framework encoding when permitted.
        /// </summary>
        /// <param name="name">
        /// The name of the encoding to look up, or null to request a null
        /// encoding.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the encoding is looked up.
        /// </param>
        /// <param name="encoding">
        /// Upon success, receives the matching encoding.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetEncoding(
            string name,             /* in */
            LookupFlags lookupFlags, /* in */
            ref Encoding encoding,   /* out */
            ref Result error         /* out */
            )
        {
            CheckDisposed();

            if (name == null)
            {
                if (!FlagOps.HasFlags(
                        lookupFlags, LookupFlags.AllowNull, true))
                {
                    error = "invalid encoding";
                    return ReturnCode.Error;
                }

                encoding = null;
                return ReturnCode.Ok;
            }

            lock (syncRoot) /* TRANSACTIONAL */
            {
                try
                {
                    Encoding localEncoding = null;

                    if (encodings != null)
                    {
                        //
                        // NOTE: We failed to find the one they specified
                        //       in our collection.  Maybe try to fallback
                        //       to the .NET Framework encoding matching
                        //       their specified name?
                        //
                        if (!encodings.TryGetValue(name, out localEncoding))
                        {
                            if (FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Strict, true))
                            {
                                error = String.Format(
                                    "encoding {0} was not found",
                                    FormatOps.WrapOrNull(name));

                                return ReturnCode.Error;
                            }
                            else
                            {
                                localEncoding = StringOps.GetEncoding(name);
                            }
                        }
                    }
                    else
                    {
                        //
                        // HACK: The strict flag does not matter because
                        //       there is no internal list of encodings.
                        //       In this case, only the Validate flag is
                        //       used.
                        //
                        localEncoding = StringOps.GetEncoding(name);
                    }

                    if ((localEncoding == null) && FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Validate, true))
                    {
                        error = "invalid encoding";
                        return ReturnCode.Error;
                    }

                    encoding = localEncoding;
                    return ReturnCode.Ok;
                }
                catch (Exception e)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        e : (Result)"invalid encoding";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up the encoding with the specified name, using
        /// the default encoding when the name refers to the default.
        /// </summary>
        /// <param name="name">
        /// The name of the encoding to look up, or the default encoding name.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the encoding is looked up.
        /// </param>
        /// <param name="encoding">
        /// Upon success, receives the matching encoding.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetEncodingOrDefault(
            string name,             /* in */
            LookupFlags lookupFlags, /* in */
            ref Encoding encoding,   /* out */
            ref Result error         /* out */
            )
        {
            CheckDisposed();

            if (StringOps.IsDefaultEncodingName(name))
            {
                encoding = DefaultEncoding;
                return ReturnCode.Ok;
            }

            ReturnCode code;
            Encoding localEncoding = null;

            code = GetEncoding(
                name, lookupFlags, ref localEncoding, ref error);

            if (code != ReturnCode.Ok)
                return code;

            encoding = localEncoding;
            return ReturnCode.Ok;
        }

