        /// Upon success, receives the matching encoding.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetEncoding(
            string name,             /* in */
            LookupFlags lookupFlags, /* in */
            ref Encoding encoding    /* out */
            )
        {
            Result error = null;

            return GetEncoding(name, lookupFlags, ref encoding, ref error);
