        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method copies the encodings defined in this interpreter into
        /// the supplied dictionary.
        /// </summary>
        /// <param name="encodings">
        /// Upon return, receives the encodings defined in this interpreter; an
        /// empty dictionary is created when none is supplied.
        /// </param>
        internal void GetEncodings(
            ref EncodingDictionary encodings /* in, out */
            )
        {
            if (encodings == null)
                encodings = new EncodingDictionary();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                EncodingDictionary localEncodings = this.encodings;

                if (localEncodings != null)
                    foreach (EncodingPair pair in localEncodings)
                        encodings[pair.Key] = pair.Value;
            }
        }
