        #region Private
        #region IRuleSet
        /// <summary>
        /// This method applies the rule set, if any, associated with this
        /// interpreter to the specified identifier text.
        /// </summary>
        /// <param name="kind">
        /// The kind of identifier being matched.
        /// </param>
        /// <param name="mode">
        /// The matching mode to use when applying the rules.
        /// </param>
        /// <param name="text">
        /// The identifier text to match against the rule set.
        /// </param>
        /// <returns>
        /// True if there is no rule set or the rules permit the identifier;
        /// otherwise, false.
        /// </returns>
        internal bool ApplyRuleSet(
            IdentifierKind kind,
            MatchMode mode,
            string text
            )
        {
            IRuleSet localRuleSet;

            lock (syncRoot)
            {
                localRuleSet = ruleSet;
            }

            if (localRuleSet == null)
                return true;

            return localRuleSet.ApplyRules(this, kind, mode, text);
        }
        #endregion

