        #region Hidden ICommand
        /// <summary>
        /// This method builds a list of the hidden commands defined in this
        /// interpreter, optionally filtered by their flags and by a name
        /// pattern.
        /// </summary>
        /// <param name="hasFlags">
        /// The command flags that must be present for a command to be
        /// included.
        /// </param>
        /// <param name="notHasFlags">
        /// The command flags that must be absent for a command to be included.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the <paramref name="hasFlags" />
        /// flags be present; zero to require only some of them.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the <paramref name="notHasFlags" />
        /// flags be absent; zero to require only some of them.
        /// </param>
        /// <param name="pattern">
        /// An optional pattern used to match command names, or null to match
        /// all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="full">
        /// Non-zero to include full information about each command instead of
        /// just its name.
        /// </param>
        /// <param name="list">
        /// Upon success, receives the list of matching hidden commands.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode HiddenCommandsToList(
            CommandFlags hasFlags,
            CommandFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (hiddenCommands != null)
                {
                    return hiddenCommands.ToList(
                        hasFlags, notHasFlags, hasAll, notHasAll,
                        pattern, noCase, full, ref list, ref error);
                }
            }

            error = "hidden commands not available";
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the hidden command with
        /// the specified token.
        /// </summary>
        /// <param name="token">
        /// The token of the hidden command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the hidden command is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the hidden command.
        /// </param>
        /// <param name="command">
        /// Upon success, receives the matching hidden command, or its wrapper
        /// when requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetHiddenCommand(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref ICommand command,
            ref Result error
            )
        {
            if (!PrivateHasHiddenCommands(ref error))
                return ReturnCode.Error;

            CommandWrapper wrapper;

            if (!hiddenCommands.TryGetValue(token, out wrapper))
            {
                error = "hidden command not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                command = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid hidden command wrapper";
                    return ReturnCode.Error;
                }

                command = wrapper.command;
                name = EntityOps.GetName(command);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the hidden command with
        /// the specified name.
        /// </summary>
        /// <param name="name">
        /// The name of the hidden command to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the hidden command is looked up.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token of the hidden command.
        /// </param>
        /// <param name="command">
        /// Upon success, receives the matching hidden command, or its wrapper
        /// when requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetHiddenCommand(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref ICommand command,
            ref Result error
            )
        {
            if (!PrivateHasHiddenCommands(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid hidden command name";
                return ReturnCode.Error;
            }

            CommandWrapper wrapper;

            if (!hiddenCommands.TryGetValue(name, out wrapper))
            {
                error = "hidden command not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                command = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid command wrapper";
                    return ReturnCode.Error;
                }

                command = wrapper.command;
                token = EntityOps.GetToken(command);

                if ((command == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden command";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

