        #region Hidden IProcedure
        /// <summary>
        /// This method builds a list of the hidden procedures defined in this
        /// interpreter, optionally filtered by their flags and by a name
        /// pattern.
        /// </summary>
        /// <param name="hasFlags">
        /// The procedure flags that must be present for a procedure to be
        /// included.
        /// </param>
        /// <param name="notHasFlags">
        /// The procedure flags that must be absent for a procedure to be
        /// included.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the <paramref name="hasFlags" />
        /// flags be present; zero to require only some of them.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the <paramref name="notHasFlags" />
        /// flags be absent; zero to require only some of them.
        /// </param>
        /// <param name="pattern">
        /// An optional pattern used to match procedure names, or null to match
        /// all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="full">
        /// Non-zero to include full information about each procedure instead of
        /// just its name.
        /// </param>
        /// <param name="list">
        /// Upon success, receives the list of matching hidden procedures.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode HiddenProceduresToList(
            ProcedureFlags hasFlags,
            ProcedureFlags notHasFlags,
            bool hasAll,
            bool notHasAll,
            string pattern,
            bool noCase,
            bool full,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (hiddenProcedures != null)
                {
                    return hiddenProcedures.ToList(
                        hasFlags, notHasFlags, hasAll, notHasAll,
                        pattern, noCase, full, ref list, ref error);
                }
            }

            error = "hidden procedures not available";
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the hidden procedure with
        /// the specified token.
        /// </summary>
        /// <param name="token">
        /// The token of the hidden procedure to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the hidden procedure is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the hidden procedure.
        /// </param>
        /// <param name="procedure">
        /// Upon success, receives the matching hidden procedure, or its wrapper
        /// when requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetHiddenProcedure(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IProcedure procedure,
            ref Result error
            )
        {
            if (!PrivateHasHiddenProcedures(ref error))
                return ReturnCode.Error;

            ProcedureWrapper wrapper;

            if (!hiddenProcedures.TryGetValue(token, out wrapper))
            {
                error = "hidden procedure not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                procedure = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((procedure == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden procedure";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid hidden procedure wrapper";
                    return ReturnCode.Error;
                }

                procedure = wrapper.procedure;
                name = EntityOps.GetName(procedure);

                if ((procedure == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden procedure";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the hidden procedure with
        /// the specified name.
        /// </summary>
        /// <param name="name">
        /// The name of the hidden procedure to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the hidden procedure is looked up.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token of the hidden procedure.
        /// </param>
        /// <param name="procedure">
        /// Upon success, receives the matching hidden procedure, or its wrapper
        /// when requested.
