        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames the named hidden procedure, or removes it when a
        /// rename is requested with an empty new name and deletion is allowed.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the hidden procedure.
        /// </param>
        /// <param name="newName">
        /// The new name for the hidden procedure.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to disable namespace-aware processing of the names.
        /// </param>
        /// <param name="delete">
        /// Non-zero to permit removing the hidden procedure when the new name
        /// is empty.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameHiddenProcedure(
            string oldName,
            string newName,
            bool noNamespaces,
            bool delete,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasHiddenProcedures(ref result))
                {
                    if (!delete || !String.IsNullOrEmpty(newName))
                    {
                        IProcedure oldProcedure = null;

                        if (GetHiddenProcedure(oldName, LookupFlags.Default, ref oldProcedure, ref result) == ReturnCode.Ok)
                        {
                            if (!EntityOps.IsReadOnly(oldProcedure))
                            {
                                if (EntityOps.IsNoRename(oldProcedure))
                                    return ReturnCode.Ok;

                                ProcedureWrapper oldWrapper = oldProcedure as ProcedureWrapper;

                                if (oldWrapper != null)
                                {
                                    IAlias oldAlias = oldWrapper.procedure as IAlias;

                                    if (PreventAliasLoop(oldAlias, newName, ref result) == ReturnCode.Ok)
                                    {
                                        if (IsValidAnyHiddenIExecuteName(newName, noNamespaces, ref result) == ReturnCode.Ok)
                                        {
                                            bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();

                                            if (!useNamespaces ||
                                                RenameImportInNamespaces(oldName, newName, ref result) == ReturnCode.Ok)
                                            {
                                                //
                                                // NOTE: New name, same token.
                                                //
                                                oldWrapper.Name = newName;

                                                /* IGNORED */
                                                hiddenProcedures.Rename(oldName, newName);

#if EXECUTE_CACHE
                                                RenameIExecuteInCache(oldName, newName, oldWrapper, true, false);
#endif

#if ARGUMENT_CACHE
                                                /* IGNORED */
                                                MaybeClearArgumentCache(oldName);

                                                /* IGNORED */
                                                MaybeClearArgumentCache(newName);
#endif

#if NOTIFY
                                                /* IGNORED */
                                                CheckNotification(
                                                    NotifyType.HiddenProcedure, NotifyFlags.Renamed,
                                                    new ObjectTriplet(oldProcedure, oldName, newName), this,
                                                    null, null, null, ref result);
#endif

                                                result = String.Empty;
                                                return ReturnCode.Ok;
                                            }
                                        }
                                    }
                                }
                                else
                                {
                                    result = String.Format(
                                        "can't rename {0}: invalid hidden procedure wrapper",
                                        FormatOps.WrapOrNull(oldName));
                                }
                            }
                            else
                            {
                                result = "hidden procedure is read-only";
                            }
                        }
                        else
                        {
                            result = String.Format(
                                "can't rename {0}: hidden procedure doesn't exist",
                                FormatOps.WrapOrNull(oldName));
                        }
                    }
                    else
                    {
                        return PrivateRemoveHiddenProcedure(oldName, null, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

