        /// <param name="name">
        /// Upon success, receives the name of the hidden execute entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the matching hidden execute entity, or its
        /// wrapper when requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetHiddenIExecute(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IExecute execute,
            ref Result error
            )
        {
            if (!PrivateHasHiddenIExecutes(ref error))
                return ReturnCode.Error;

            ExecuteWrapper wrapper;

            if (!hiddenExecutes.TryGetValue(token, out wrapper))
            {
                error = "hidden execute not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                execute = wrapper;
                name = EntityOps.GetName(execute as IIdentifierName);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid hidden execute wrapper";
                    return ReturnCode.Error;
                }

                execute = wrapper.execute;
                name = EntityOps.GetName(execute as IIdentifierName);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the hidden execute entity
        /// with the specified name.
        /// </summary>
        /// <param name="name">
        /// The name of the hidden execute entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the hidden execute entity is looked up.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token of the hidden execute entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the matching hidden execute entity, or its
        /// wrapper when requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetHiddenIExecute(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IExecute execute,
            ref Result error
            )
        {
            if (!PrivateHasHiddenIExecutes(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid hidden execute name";
                return ReturnCode.Error;
            }

            ExecuteWrapper wrapper;

            if (!hiddenExecutes.TryGetValue(name, out wrapper))
            {
                error = "hidden execute not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                execute = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid hidden execute wrapper";
                    return ReturnCode.Error;
                }

                execute = wrapper.execute;

                //
                // WARNING: Cannot grab the token from the IExecute here
                //          because that interface does not inherit from
                //          IWrapperData.
                //
                token = EntityOps.GetToken(wrapper);

                if ((execute == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid hidden execute";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

