        /// <summary>
        /// This method renames the named hidden execute entity, or removes it
        /// when a rename is requested with an empty new name and deletion is
        /// allowed.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the hidden execute entity.
        /// </param>
        /// <param name="newName">
        /// The new name for the hidden execute entity.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to disable namespace-aware processing of the names.
        /// </param>
        /// <param name="delete">
        /// Non-zero to permit removing the hidden execute entity when the new
        /// name is empty.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRenameHiddenIExecute(
            string oldName,
            string newName,
            bool noNamespaces,
            bool delete,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasHiddenIExecutes(ref result))
                {
                    if (!delete || !String.IsNullOrEmpty(newName))
                    {
                        IExecute oldExecute = null;

                        if (GetHiddenIExecute(oldName, LookupFlags.Default, ref oldExecute, ref result) == ReturnCode.Ok)
                        {
                            ExecuteWrapper oldWrapper = oldExecute as ExecuteWrapper;

                            if (oldWrapper != null)
                            {
                                IAlias oldAlias = oldWrapper.execute as IAlias;

                                if (PreventAliasLoop(oldAlias, newName, ref result) == ReturnCode.Ok)
                                {
                                    if (IsValidAnyHiddenIExecuteName(newName, noNamespaces, ref result) == ReturnCode.Ok)
                                    {
                                        bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();

                                        if (!useNamespaces ||
                                            RenameImportInNamespaces(oldName, newName, ref result) == ReturnCode.Ok)
                                        {
                                            /* IGNORED */
                                            hiddenExecutes.Rename(oldName, newName);

#if EXECUTE_CACHE
                                            RenameIExecuteInCache(oldName, newName, oldWrapper, true, false);
#endif

#if ARGUMENT_CACHE
                                            /* IGNORED */
                                            MaybeClearArgumentCache(oldName);

                                            /* IGNORED */
                                            MaybeClearArgumentCache(newName);
#endif

#if NOTIFY
                                            /* IGNORED */
                                            CheckNotification(
                                                NotifyType.HiddenIExecute, NotifyFlags.Renamed,
                                                new ObjectTriplet(oldExecute, oldName, newName), this,
                                                null, null, null, ref result);
#endif

                                            result = String.Empty;
                                            return ReturnCode.Ok;
                                        }
                                    }
                                }
                            }
                            else
                            {
                                result = String.Format(
                                    "can't rename {0}: invalid hidden execute wrapper",
                                    FormatOps.WrapOrNull(oldName));
                            }
                        }
                        else
                        {
                            result = String.Format(
                                "can't rename {0}: hidden execute doesn't exist",
                                FormatOps.WrapOrNull(oldName));
                        }
                    }
                    else
                    {
                        return PrivateRemoveHiddenIExecute(oldName, null, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

