        /// </param>
        /// <param name="token">
        /// Upon success, receives the token of the operator.
        /// </param>
        /// <param name="operator">
        /// Upon success, receives the matching operator, or its wrapper when
        /// requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetOperator(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IOperator @operator,
            ref Result error
            )
        {
            if (!PrivateHasOperators(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid operator name";
                return ReturnCode.Error;
            }

            OperatorWrapper wrapper;

            if (!operators.TryGetValue(name, out wrapper))
            {
                error = "operator not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                @operator = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((@operator == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid operator";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid operator wrapper";
                    return ReturnCode.Error;
                }

                @operator = wrapper.@operator;
                token = EntityOps.GetToken(@operator);

                if ((@operator == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid operator";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the operator with the
        /// specified token.
        /// </summary>
        /// <param name="token">
        /// The token of the operator to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the operator is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the operator.
        /// </param>
        /// <param name="operator">
        /// Upon success, receives the matching operator, or its wrapper when
        /// requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetOperator(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IOperator @operator,
            ref Result error
            )
        {
            if (!PrivateHasOperators(ref error))
                return ReturnCode.Error;

            OperatorWrapper wrapper;

            if (!operators.TryGetValue(token, out wrapper))
            {
                error = "operator not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                @operator = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((@operator == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid operator";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid operator wrapper";
                    return ReturnCode.Error;
                }

                @operator = wrapper.@operator;
                name = EntityOps.GetName(@operator);

                if ((@operator == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid operator";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

