        /// <summary>
        /// This method looks up the operator with the specified token, also
        /// returning its name.
        /// </summary>
        /// <param name="token">
        /// The token of the operator to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the operator is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the operator.
        /// </param>
        /// <param name="operator">
        /// Upon success, receives the matching operator.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetOperator(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IOperator @operator,
            ref Result error
            )
        {
            // CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetOperator(
                        token, lookupFlags, ref name, ref @operator,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid operator token {0}",
                            FormatOps.WrapOrNull(token)) :
                        "invalid operator token";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the cached operator entries, optionally releasing
        /// the cache itself.
        /// </summary>
        /// <param name="reset">
        /// Non-zero to release the operator cache entirely after clearing its
        /// entries.
        /// </param>
        /// <returns>
        /// The number of cached operator entries that were cleared.
        /// </returns>
        private int ClearOperatorCache(
            bool reset
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int count = 0;

                if (operatorCache != null)
                {
                    int length = operatorCache.Length;

                    for (int index = 0; index < length; index++)
                    {
                        if (operatorCache[index] == null)
                            continue;

                        operatorCache[index] = null;
                        count++;
                    }

                    if (reset)
                        operatorCache = null;
                }

                return count;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the cached operator entry associated with the
        /// specified lexeme.
        /// </summary>
        /// <param name="lexeme">
        /// The lexeme whose cached operator entry is to be cleared.
        /// </param>
        /// <returns>
        /// True if a cached operator entry was cleared; otherwise, false.
        /// </returns>
        private bool ClearOperatorCacheEntry(
            Lexeme lexeme
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (operatorCache == null)
                    return false;

                int length = operatorCache.Length;

                if ((lexeme < 0) || ((int)lexeme >= length))
                    return false;

                if (operatorCache[(int)lexeme] == null)
                    return false;

                operatorCache[(int)lexeme] = null;
                return true;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up the operator used to evaluate the specified
        /// expression lexeme, using and populating the operator cache.
        /// </summary>
        /// <param name="lexeme">
        /// The expression lexeme whose operator is to be looked up.
        /// </param>
        /// <param name="name">
        /// The name of the operator associated with the lexeme.
        /// </param>
        /// <param name="operator">
        /// Upon success, receives the matching operator.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetExpressionOperator(
            Lexeme lexeme,
            string name,
            ref IOperator @operator
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (operatorCache != null)
                {
                    @operator = operatorCache[(int)lexeme]; /* throw */

                    if (@operator != null)
                        return ReturnCode.Ok;
                }

                if (operators == null)
                    return ReturnCode.Error;

                if (name == null)
                    return ReturnCode.Error;

                OperatorWrapper wrapper;

                if (!operators.TryGetValue(name, out wrapper))
                    return ReturnCode.Error;

                if (wrapper == null)
                    return ReturnCode.Error;

                @operator = wrapper.@operator;

                if (@operator == null)
                    return ReturnCode.Error;

                if (operatorCache != null)
                    operatorCache[(int)lexeme] = @operator; /* throw */

                return ReturnCode.Ok;
            }
        }

