        /// </returns>
        internal ReturnCode GetOperator(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IOperator @operator,
            ref Result error
            )
        {
            // CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateGetOperator(
                        name, lookupFlags, ref token, ref @operator,
                        ref error) != ReturnCode.Ok)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "invalid operator name {0}",
                            FormatOps.DisplayName(name)) :
                        "invalid operator name";

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Dead Code
#if DEAD_CODE
        /// <summary>
        /// This method creates a new operator of the specified type and adds it
        /// to this interpreter.
        /// </summary>
        /// <param name="type">
        /// The type that implements the operator.  This parameter may be null,
        /// in which case the type is resolved from the operator name.
        /// </param>
        /// <param name="name">
        /// The name of the operator to add.
        /// </param>
        /// <param name="lexeme">
        /// The lexeme associated with the operator.
        /// </param>
        /// <param name="operands">
        /// The number of operands accepted by the operator, or
        /// <see cref="Arity.Automatic" /> to use the value declared by the
        /// operator type.
        /// </param>
        /// <param name="types">
        /// The list of operand types accepted by the operator.  This parameter
        /// may be null.
        /// </param>
        /// <param name="flags">
        /// The additional operator flags to associate with the operator.
        /// </param>
        /// <param name="plugin">
        /// The plugin associated with the operator.  This parameter may be
        /// null.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the operator.  This parameter may
        /// be null.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error when the operator cannot be added due to
        /// the standard policy of the interpreter.
        /// </param>
        /// <param name="token">
        /// Upon success, this is set to the token associated with the newly
        /// added operator.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing why the
        /// operator could not be added.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the operator was added;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddOperator(
            Type type,
            string name,
            Lexeme lexeme,
            int operands,
            TypeList types,
            OperatorFlags flags,
            IPlugin plugin,
            IClientData clientData,
            bool strict,
            ref long token,
            ref Result result
            )
        {
            // CheckDisposed(); /* NOTE: This API may be public someday. */

            if (type == null)
            {
                type = Type.GetType(
                    FormatOps.OperatorTypeName(name, false), false,
                    true);
            }

            if (type == null)
            {
                type = Type.GetType(FormatOps.OperatorTypeName(
                    Characters.Underscore + name, false), false,
                    true);
            }

            if (type != null)
            {
                OperatorFlags operatorFlags =
                    AttributeOps.GetOperatorFlags(type) | flags;

                AddEntityClientData addEntityClientData =
                    new AddEntityClientData(null, this);

                bool createStandard = addEntityClientData.CreateStandard;

                StringComparison comparisonType =
                    addEntityClientData.OperatorComparisonType;

                //
                // NOTE: Check if this operator is part of the "Tcl Standard"
                //       (i.e. it is largely (or completely) compatible with
                //       an identically named operator from Tcl/Tk 8.4, 8.5,
                //       and/or 8.6).
                //
                bool standard = FlagOps.HasFlags(
                    operatorFlags, OperatorFlags.Standard, true);

                //
                // NOTE: If the interpreter is "standard", make sure we only
                //       add operators that are marked as "standard" and NOT
                //       marked as "non-standard" unless we are merely hiding
                //       operators not considered to be "standard".  In that
                //       case, we add all operators, hidden them as necessary.
                //
                if (standard || !createStandard)
                {
                    try
                    {
                        if (operands == (int)Arity.Automatic)
                            operands = AttributeOps.GetOperands(type);

                        object[] args = {
                            new OperatorData(
                                name, null, null, clientData, type.FullName,
                                type, lexeme, operands, types, flags,
                                comparisonType, plugin, 0)
                        };

                        IOperator @operator =
                            (IOperator)Activator.CreateInstance(type, args);

                        return AddOperator(
                            @operator, null, ref token, ref result);
                    }
                    catch (Exception e)
                    {
                        result = e;
                    }
                }
                else if (strict)
                {
                    result = "cannot add non-standard operator to standard interpreter";
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                result = String.Format(
                    "operator {0} not found",
                    FormatOps.OperatorTypeName(name, true));
            }

            return ReturnCode.Error;
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified operator to this interpreter,
        /// discarding the resulting token.
        /// </summary>
        /// <param name="operator">
        /// The operator to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the operator, if any.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddOperator(
            IOperator @operator,
            IClientData clientData,
            ref Result result
            )
        {
            long token = 0;

            return AddOperator(@operator, clientData, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified operator to this interpreter,
        /// initializing it and optionally registering it as a Tcl math
        /// operator.
        /// </summary>
        /// <param name="operator">
        /// The operator to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the operator, if any.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token assigned to the operator.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddOperator(
            IOperator @operator,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (@operator == null)
                {
                    result = "invalid operator";
                    return ReturnCode.Error;
                }

                string name = @operator.Name;

                if (name == null)
                {
                    result = "invalid operator name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasOperators(ref result))
                    return ReturnCode.Error;

                if (DoesOperatorExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: operator already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                //
                // HACK: Due to how the expression parser works, we cannot allow an
                //       operator to be added that has the name of an existing
                //       function.
                //
                if (DoesFunctionExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: function already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                if (!FlagOps.HasFlags(
                        @operator.Flags, OperatorFlags.NoTclMathOperator, true) &&
                    /* EXEMPT */
                    FlagOps.HasFlags(
                        interpreterFlags, InterpreterFlags.TclMathOperators, true))
                {
                    //
                    // HACK: This is part of an ugly hack to add "tcl::mathfunc::*" and
                    //       "tcl::mathop::*" support for [expr] functions and operators
                    //       to Eagle, respectively.  This can only be done for operator
                    //       instances that also implement the IExecute interface.
                    //
                    IExecute execute = @operator as IExecute;
                    long token2; /* REUSED */

                    if (execute != null)
                    {
                        if (InternalAreNamespacesEnabled())
                        {
                            INamespace @namespace = NamespaceOps.Lookup(
                                this, TclVars.Namespace.MathOperatorName, true, true,
                                ref result);

                            if (@namespace == null)
                                return ReturnCode.Error;

                            string qualifiedName = NamespaceOps.MakeQualifiedName(
                                this, @namespace, name);

                            if (ApplyRuleSet(
                                    IdentifierKind.Command, MatchMode.IncludeRuleSetMask,
                                    ScriptOps.MakeCommandName(qualifiedName)))
                            {
                                token2 = 0; /* NOT USED */

                                if (AddIExecute(
                                        qualifiedName, execute, clientData,
                                        ref token2, ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }
                            }
                        }
                        else
                        {
                            string unqualifiedName = NamespaceOps.MakeName(
                                TclVars.Namespace.MathOperatorName, name, true,
                                false);

                            if (ApplyRuleSet(
                                    IdentifierKind.Command, MatchMode.IncludeRuleSetMask,
                                    ScriptOps.MakeCommandName(unqualifiedName)))
                            {
                                token2 = 0; /* NOT USED */

                                if (AddIExecute(
                                        unqualifiedName, execute, clientData,
                                        ref token2, ref result) != ReturnCode.Ok)
                                {
                                    return ReturnCode.Error;
                                }
                            }
                        }
                    }
                }

                ReturnCode code = ReturnCode.Ok;

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    try
                    {
                        try
                        {
                            code = @operator.Initialize(this,
                                (clientData != null) ? clientData : @operator.ClientData,
                                ref result);
                        }
                        catch (Exception e)
                        {
                            result = String.Format(
                                "caught exception while initializing operator: {0}",
                                e);

                            code = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        if (code != ReturnCode.Ok)
                        {
                            ReturnCode terminateCode;
                            Result terminateResult = null;

                            terminateCode = TerminateOperator(
                                @operator, clientData, ref terminateResult);

                            if (terminateCode != ReturnCode.Ok)
                            {
                                DebugOps.Complain(
                                    this, terminateCode, terminateResult);
                            }
                        }
                    }

                    if (code != ReturnCode.Ok)
                        return code;

                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(@operator);

                        wrapper = EntityOps.MaybeNewWrapperWith<OperatorWrapper>(
                            id, @operator);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        operators.Add(name, wrapper as OperatorWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(@operator, newToken);

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Operator, NotifyFlags.Added,
                            new ObjectPair(@operator, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method terminates the specified operator, allowing it to
        /// release any resources it holds.
        /// </summary>
        /// <param name="operator">
        /// The operator to terminate.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass to the operator and any notification
        /// handlers, if any.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode TerminateOperator(
            IOperator @operator,
            IClientData clientData,
            ref Result result
            )
        {
            if (@operator == null)
            {
                result = "invalid operator";
                return ReturnCode.Error;
            }

            bool savedImmutable = BeginMutableExecution();

            ReturnCode code;

            try
            {
                code = @operator.Terminate(this,
                    (clientData != null) ? clientData : @operator.ClientData,
                    ref result);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Operator, NotifyFlags.Terminated,
                    new ObjectTriplet(@operator, code), this,
                    clientData, null, null, ref result);
#endif
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while terminating operator: {0}",
                    e);

                code = ReturnCode.Error;
            }
            finally
            {
                EndMutableExecution(savedImmutable);
            }

            return code;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IModule
#if EMIT && NATIVE && LIBRARY
        /// <summary>
        /// This method produces the string form of the native modules defined
        /// in this interpreter, optionally filtered by a name pattern.
        /// </summary>
        /// <param name="pattern">
        /// An optional pattern used to match module names, or null to match all
        /// of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <returns>
        /// The string form of the matching native modules, or null if there
        /// are none.
        /// </returns>
        internal string ModulesToString(
            string pattern,
            bool noCase
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (modules != null)
                    return modules.ToString(pattern, noCase);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the native module with the
        /// specified token.
        /// </summary>
        /// <param name="token">
        /// The token of the module to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the module is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the module.
        /// </param>
        /// <param name="module">
        /// Upon success, receives the matching module, or its wrapper when
        /// requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetModule(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IModule module,
            ref Result error
            )
        {
            if (!PrivateHasModules(ref error))
                return ReturnCode.Error;

            ModuleWrapper wrapper;

            if (!modules.TryGetValue(token, out wrapper))
            {
                error = "module not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                module = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((module == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid module";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid module wrapper";
                    return ReturnCode.Error;
                }

                module = wrapper.module;
                name = EntityOps.GetName(module);

                if ((module == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid module";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the native module with the
        /// specified name.
        /// </summary>
        /// <param name="name">
        /// The name of the module to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the module is looked up.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token of the module.
        /// </param>
        /// <param name="module">
        /// Upon success, receives the matching module, or its wrapper when
        /// requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetModule(
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IModule module,
            ref Result error
            )
        {
            if (!PrivateHasModules(ref error))
                return ReturnCode.Error;

            if (name == null)
            {
                error = "invalid module name";
                return ReturnCode.Error;
            }

            ModuleWrapper wrapper;

            if (!modules.TryGetValue(name, out wrapper))
            {
                error = "module not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                module = wrapper;
                token = EntityOps.GetToken(wrapper);

                if ((module == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid module";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid module wrapper";
                    return ReturnCode.Error;
                }

                module = wrapper.module;
                token = EntityOps.GetToken(module);

                if ((module == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid module";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

