        /// <summary>
        /// This method looks up the native module loaded from the specified
        /// file.
        /// </summary>
        /// <param name="fileName">
        /// The file name of the module to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the module is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the matching module.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetModuleByFileName(
            string fileName,
            LookupFlags lookupFlags,
            ref string name,
            ref Result error
            )
        {
            long token = 0;
            IModule module = null;

            return GetModuleByFileName(
                fileName, lookupFlags, ref name, ref token, ref module,
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of the native module loaded
        /// from the specified file.
        /// </summary>
        /// <param name="fileName">
        /// The file name of the module to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the module is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the matching module.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token of the matching module.
        /// </param>
        /// <param name="module">
        /// Upon success, receives the matching module, or its wrapper when
        /// requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetModuleByFileName(
            string fileName,
            LookupFlags lookupFlags,
            ref string name,
            ref long token,
            ref IModule module,
            ref Result error
            )
        {
            ReturnCode code = ReturnCode.Error;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasModules(ref error))
                {
                    if (modules.Count > 0)
                    {
                        foreach (ModulePair pair in modules)
                        {
                            ModuleWrapper wrapper = pair.Value;

                            if (wrapper == null)
                                continue;

                            if (PathOps.IsSameFile(this, fileName, wrapper.FileName))
                            {
                                name = pair.Key;

                                if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
                                    module = wrapper;
                                else
                                    module = wrapper.module;

                                token = EntityOps.GetToken(wrapper);

                                if ((module != null) ||
                                    !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                                {
                                    code = ReturnCode.Ok;
                                }
                                break;
                            }
                        }
                    }

                    if (code != ReturnCode.Ok)
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "invalid module file name {0}",
                                FormatOps.DisplayName(fileName)) :
                            "invalid module file name";
                    }
                }
            }

            return code;
        }

