        /// <summary>
        /// This method adds the specified native module to this interpreter,
        /// discarding the resulting token.
        /// </summary>
        /// <param name="module">
        /// The module to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the module, if any.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddModule(
            IModule module,
            IClientData clientData,
            ref Result result
            )
        {
            long token = 0;

            return AddModule(module, clientData, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified native module to this interpreter.
        /// </summary>
        /// <param name="module">
        /// The module to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the module, if any.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token assigned to the module.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddModule(
            IModule module,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (module == null)
                {
                    result = "invalid module";
                    return ReturnCode.Error;
                }

                string name = module.Name;

                if (name == null)
                {
                    result = "invalid module name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasModules(ref result))
                    return ReturnCode.Error;

                if (DoesModuleExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: module already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(module);

                        wrapper = EntityOps.MaybeNewWrapperWith<ModuleWrapper>(
                            id, module);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        modules.Add(name, wrapper as ModuleWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(module, newToken);

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Module, NotifyFlags.Added,
                            new ObjectPair(module, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the specified native module from this
        /// interpreter, optionally disposing it.
        /// </summary>
        /// <param name="name">
        /// The name of the module to remove.
        /// </param>
        /// <param name="token">
        /// The token of the module to remove.
        /// </param>
        /// <param name="module">
        /// The module to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to collect garbage synchronously after disposing the
        /// module.
        /// </param>
        /// <param name="dispose">
        /// Upon entry, non-zero to dispose the module; upon return, indicates
        /// whether the module still needs to be disposed.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveModule(
            string name,
            long token,
            IModule module,
            IClientData clientData,
            bool synchronous,
            ref bool dispose,
            ref Result result
            )
        {
            if (dispose)
            {
                if (module != null)
                {
                    if (!FlagOps.HasFlags(module.Flags, ModuleFlags.NoRemove, true))
                    {
                        GlobalState.PushActiveInterpreter(this);

                        try
                        {
                            if (ObjectOps.TryDispose<IModule>(ref module,
                                    ref dispose, ref result) == ReturnCode.Ok)
                            {
                                module = null;

                                if (synchronous)
                                    ObjectOps.CollectGarbage(); /* throw */
                            }
                            else
                            {
                                return ReturnCode.Error;
                            }
                        }
                        catch (Exception e)
                        {
                            result = String.Format(
                                "caught exception while disposing module: {0}",
                                e);

                            return ReturnCode.Error;
                        }
                        finally
                        {
                            /* IGNORED */
                            GlobalState.PopActiveInterpreter();
                        }
                    }
                    else
                    {
                        result = "cannot dispose or remove module";

                        return ReturnCode.Error;
                    }
                }
            }

            modules.Remove(name, token);

#if NOTIFY
            /* IGNORED */
            CheckNotification(
                NotifyType.Module, NotifyFlags.Removed,
                new ObjectTriplet(module, name, token), this,
                clientData, null, null, ref result);
#endif

            return ReturnCode.Ok;
        }

