        /// <summary>
        /// This method looks up the named native module and removes it from
        /// this interpreter, also returning its token.
        /// </summary>
        /// <param name="name">
        /// The name of the module to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to collect garbage synchronously after disposing the
        /// module.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token of the removed module.
        /// </param>
        /// <param name="dispose">
        /// Upon entry, non-zero to dispose the module; upon return, indicates
        /// whether the module still needs to be disposed.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveModule(
            string name,
            IClientData clientData,
            bool synchronous,
            ref long token,
            ref bool dispose,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (PrivateHasModules(ref result))
                {
                    IModule module = null;

                    if (PrivateGetModule(
                            name, LookupFlags.Remove, ref token,
                            ref module, ref result) == ReturnCode.Ok)
                    {
                        return PrivateRemoveModule(
                            name, token, module, clientData, synchronous,
                            ref dispose, ref result);
                    }
                }
            }

            return ReturnCode.Error;
        }

