        /// <summary>
        /// This method performs the actual lookup of the managed delegate with
        /// the specified token.
        /// </summary>
        /// <param name="token">
        /// The token of the delegate to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the delegate is looked up.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the delegate.
        /// </param>
        /// <param name="delegate">
        /// Upon success, receives the matching delegate, or its wrapper when
        /// requested.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateGetDelegate(
            long token,
            LookupFlags lookupFlags,
            ref string name,
            ref IDelegate @delegate,
            ref Result error
            )
        {
            if (!PrivateHasDelegates(ref error))
                return ReturnCode.Error;

            DelegateWrapper wrapper;

            if (!delegates.TryGetValue(token, out wrapper))
            {
                error = "delegate not found";
                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                @delegate = wrapper;
                name = EntityOps.GetName(wrapper);

                if ((@delegate == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid delegate";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
            else
            {
                if (wrapper == null)
                {
                    error = "invalid delegate wrapper";
                    return ReturnCode.Error;
                }

                @delegate = wrapper.@delegate;
                name = EntityOps.GetName(@delegate);

                if ((@delegate == null) &&
                    FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                {
                    error = "invalid delegate";
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }

