        /// <summary>
        /// This method adds the specified managed delegate to this interpreter,
        /// discarding the resulting token.
        /// </summary>
        /// <param name="delegate">
        /// The delegate to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the delegate, if any.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddDelegate(
            IDelegate @delegate,
            IClientData clientData,
            ref Result result
            )
        {
            long token = 0;

            return AddDelegate(@delegate, clientData, ref token, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified managed delegate to this interpreter.
        /// </summary>
        /// <param name="delegate">
        /// The delegate to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the delegate, if any.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token assigned to the delegate.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddDelegate(
            IDelegate @delegate,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (@delegate == null)
                {
                    result = "invalid delegate";
                    return ReturnCode.Error;
                }

                string name = @delegate.Name;

                if (name == null)
                {
                    result = "invalid delegate name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasDelegates(ref result))
                    return ReturnCode.Error;

                if (DoesDelegateExist(name) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: delegate already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool success = false;
                    IWrapper wrapper = null;

                    try
                    {
                        long id = EntityOps.NextTokenIdNoThrow(@delegate);

                        wrapper = EntityOps.MaybeNewWrapperWith<DelegateWrapper>(
                            id, @delegate);

                        if (wrapper == null)
                        {
                            result = String.Format(
                                "can't add {0}: no wrapper",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        delegates.Add(name, wrapper as DelegateWrapper);
                        success = true;

                        long newToken = EntityOps.GetToken(wrapper);
                        EntityOps.SetToken(@delegate, newToken);

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Delegate, NotifyFlags.Added,
                            new ObjectPair(@delegate, newToken), this,
                            clientData, null, null, ref result);
#endif

                        token = newToken;
                    }
                    finally
                    {
                        if (!success && (wrapper != null))
                        {
                            wrapper.Dispose();
                            wrapper = null;
                        }
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the specified managed delegate from this
        /// interpreter, optionally disposing it.
        /// </summary>
        /// <param name="name">
        /// The name of the delegate to remove.
        /// </param>
        /// <param name="token">
        /// The token of the delegate to remove.
        /// </param>
        /// <param name="delegate">
        /// The delegate to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to collect garbage synchronously after disposing the
        /// delegate.
        /// </param>
        /// <param name="dispose">
        /// Upon entry, non-zero to dispose the delegate; upon return, indicates
        /// whether the delegate still needs to be disposed.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateRemoveDelegate(
            string name,
            long token,
            IDelegate @delegate,
            IClientData clientData,
            bool synchronous,
            ref bool dispose,
            ref Result result
            )
        {
            if (name == null)
            {
                result = "invalid delegate name";
                return ReturnCode.Error;
            }

            if (dispose)
            {
                if (@delegate != null)
                {
                    GlobalState.PushActiveInterpreter(this);

                    try
                    {
                        if (ObjectOps.TryDispose<IDelegate>(ref @delegate,
                                ref dispose, ref result) == ReturnCode.Ok)
                        {
                            @delegate = null;

                            if (synchronous)
                                ObjectOps.CollectGarbage(); /* throw */
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                    catch (Exception e)
                    {
                        result = String.Format(
                            "caught exception while disposing delegate: {0}",
                            e);

                        return ReturnCode.Error;
                    }
                    finally
                    {
                        /* IGNORED */
                        GlobalState.PopActiveInterpreter();
                    }
                }
            }

            delegates.Remove(name, token);

#if NOTIFY
            /* IGNORED */
            CheckNotification(
                NotifyType.Delegate, NotifyFlags.Removed,
                new ObjectTriplet(@delegate, name, token), this,
                clientData, null, null, ref result);
#endif

            return ReturnCode.Ok;
        }

