        #region Cleanup Paths
        /// <summary>
        /// This method queries the set of paths scheduled to be cleaned up when
        /// this interpreter is disposed, optionally filtered by a name pattern.
        /// </summary>
        /// <param name="pattern">
        /// An optional pattern used to match cleanup paths, or null to match
        /// all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="list">
        /// Upon success, receives a list containing each matching path followed
        /// by the string form of its associated cleanup data.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ListCleanupPaths(
            string pattern,
            bool noCase,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (cleanupPaths == null)
                {
                    error = "cleanup paths not available";
                    return ReturnCode.Error;
                }

                IEnumerable<CleanupPathPair> pairs =
                    cleanupPaths.GetPairsInOrder(true);

                if (pairs == null)
                {
                    error = "cannot get cleanup paths in order";
                    return ReturnCode.Error;
                }

                StringList localList = null;

                foreach (CleanupPathPair pair in pairs)
                {
                    string path = pair.Key;

                    if (String.IsNullOrEmpty(path))
                        continue;

                    if ((pattern != null) && !StringOps.Match(
                            this, MatchMode.Glob, path, pattern,
                            noCase))
                    {
                        continue;
                    }

                    CleanupPathClientData clientData = pair.Value;

                    if ((clientData == null) ||
                        !clientData.MatchPathType(path))
                    {
                        continue;
                    }

                    if (localList == null)
                        localList = new StringList();

                    localList.Add(path);
                    localList.Add(clientData.ToString());
                }

                list = localList;
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method schedules a path to be cleaned up when this interpreter
        /// is disposed, creating or updating its associated cleanup data.
        /// </summary>
        /// <param name="path">
        /// The path to clean up.
        /// </param>
        /// <param name="pathType">
        /// The type of the path (e.g. file or directory).
        /// </param>
        /// <param name="recursive">
        /// Non-zero to remove the path recursively.
        /// </param>
        /// <param name="force">
        /// Non-zero to forcibly remove the path, even when read-only.
        /// </param>
        /// <param name="noComplain">
        /// Non-zero to ignore any errors encountered while removing the path.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddCleanupPath(
            string path,
            PathType pathType,
            bool recursive,
            bool force,
            bool noComplain,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (path == null)
                {
                    error = "invalid path";
                    return ReturnCode.Error;
                }

                if (cleanupPaths == null)
                {
                    error = "cleanup paths not available";
                    return ReturnCode.Error;
                }

                CleanupPathClientData clientData;

                /* IGNORED */
                cleanupPaths.TryGetValue(path, out clientData);

                if (clientData == null)
                    clientData = new CleanupPathClientData();

                clientData.PathType = pathType;
                clientData.Recursive = recursive;
                clientData.Force = force;
                clientData.NoComplain = noComplain;

                cleanupPaths[path] = clientData;
                return ReturnCode.Ok;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Channel
        /// <summary>
        /// This method looks up the channel with the specified name in this
        /// interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the channel to look up.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// The matching channel, or null if there is no channel with the
        /// specified name.
        /// </returns>
        internal IChannel InternalGetChannel(
            string name,
            ref Result error
            )
        {
            if (name == null)
            {
                error = "invalid channel name";
                return null;
            }

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasChannels(ref error))
                    return null;

                IChannel channel;

                if (channels.TryGetValue(name, out channel))
                {
                    if (channel == null)
                    {
                        error = String.Format(
                            "invalid channel {0}",
                            FormatOps.WrapOrNull(name));
                    }
                }
                else
                {
                    error = String.Format(
                        "can not find channel named {0}",
                        FormatOps.WrapOrNull(name));
                }

                return channel;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Virtual Output
        /// <summary>
        /// This method returns the virtual output buffer associated with the
        /// named channel, if any.
        /// </summary>
        /// <param name="name">
        /// The name of the channel whose virtual output buffer is needed.
        /// </param>
        /// <returns>
        /// The virtual output buffer for the channel, or null if the channel
        /// does not exist or does not have virtual output enabled.
        /// </returns>
        internal StringBuilder GetChannelVirtualOutput(
            string name
            )
        {
            StringBuilder builder = null;
            Result error = null;

            if (InternalGetChannelVirtualOutput(
                    name, false, ref builder,
                    ref error) == ReturnCode.Ok)
            {
                return builder;
            }

            return null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method retrieves the virtual output buffer associated with the
        /// named channel, optionally returning a copy of it.
        /// </summary>
        /// <param name="name">
        /// The name of the channel whose virtual output buffer is needed.
        /// </param>
        /// <param name="copy">
        /// Non-zero to return a copy of the virtual output buffer instead of
        /// the buffer itself.
        /// </param>
        /// <param name="builder">
        /// Upon success, receives the virtual output buffer, or a copy of it.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalGetChannelVirtualOutput(
            string name,
            bool copy,
            ref StringBuilder builder,
            ref Result error
            )
        {
            IChannel channel = InternalGetChannel(name, ref error);

            if (channel != null)
            {
                StringBuilder localBuilder = channel.VirtualOutput;

                if (localBuilder != null)
                {
                    builder = copy ?
                        StringOps.CopyStringBuilder(localBuilder) :
                        localBuilder;

                    return ReturnCode.Ok;
                }

                error = String.Format(
                    "virtual output is not enabled for channel named {0}",
                    FormatOps.WrapOrNull(name));
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables or disables virtual output buffering for the
        /// named channel.
        /// </summary>
        /// <param name="name">
        /// The name of the channel to modify.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable virtual output buffering; zero to disable it and
        /// release any existing buffer.
        /// </param>
        /// <param name="result">
        /// Upon success, receives a message describing the change; upon
        /// failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalSetChannelVirtualOutput(
            string name,
            bool enable,
            ref Result result
            )
        {
            IChannel channel = InternalGetChannel(name, ref result);

            if (channel != null)
            {
                StringBuilder localBuilder; /* REUSED */

                if (!enable)
                {
                    localBuilder = channel.VirtualOutput;
                    SBC.Release(ref localBuilder);
                }

                localBuilder = enable ?
                    SBF.CreateNoCache() : null; /* EXEMPT */

                channel.VirtualOutput = localBuilder;

                result = String.Format(
                    "virtual output {0} for channel {1}",
                    ConversionOps.ToEnabled(enable),
                    FormatOps.WrapOrNull(name));

                return ReturnCode.Ok;
            }

            return ReturnCode.Error;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Adding Channels
        /// <summary>
        /// This method adds a channel backed by a file or socket stream to this
        /// interpreter, using the default translation and channel encoding.
        /// </summary>
        /// <param name="name">
        /// The name of the channel to add.
        /// </param>
        /// <param name="stream">
        /// The underlying stream for the channel.
        /// </param>
        /// <param name="options">
        /// The options associated with the channel, if any.
        /// </param>
        /// <param name="flags">
        /// The flags that describe the stream and control channel behavior.
        /// </param>
        /// <param name="availableTimeout">
        /// The timeout, in milliseconds, to use when checking for available
        /// data, or null to use the default.
        /// </param>
        /// <param name="nullEncoding">
        /// Non-zero if the channel should use a null (binary) encoding.
        /// </param>
        /// <param name="appendMode">
        /// Non-zero if data written to the channel should be appended.
        /// </param>
        /// <param name="autoFlush">
        /// Non-zero if the channel should be flushed automatically after each
        /// write.
        /// </param>
        /// <param name="rawEndOfStream">
        /// Non-zero to use raw end-of-stream handling for the channel.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the channel, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddFileOrSocketChannel(
            string name,
            Stream stream,
            OptionDictionary options,
            StreamFlags flags,
            int? availableTimeout,
            bool nullEncoding,
            bool appendMode,
            bool autoFlush,
            bool rawEndOfStream,
            IClientData clientData,
            ref Result error
            )
        {
            return AddChannel(
                name, ChannelType.None, stream, options, flags,
                StreamTranslation.auto, StreamTranslation.auto,
                StringOps.GetEncoding(EncodingType.Channel),
                availableTimeout, nullEncoding, appendMode,
                autoFlush, rawEndOfStream, clientData, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if NETWORK
        /// <summary>
        /// This method adds a channel backed by a TCP listener socket to this
        /// interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the channel to add.
        /// </param>
        /// <param name="channelType">
        /// The type of the channel being added.
        /// </param>
        /// <param name="listener">
        /// The TCP listener that backs the channel.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the channel, including its options,
        /// if any.
        /// </param>
        /// <param name="added">
        /// Upon success, set to non-zero if the channel was actually added.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddTcpListenerChannel(
            string name,
            ChannelType channelType,
            TcpListener listener,
            SocketClientData clientData,
            ref bool added,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                string channelId = RuntimeOps.ChannelTypeToName(
                    name, channelType);

                if (channelId == null)
                {
                    error = "invalid channel name";
                    return ReturnCode.Error;
                }

                if (!PrivateHasChannels(ref error))
                    return ReturnCode.Error;

                if (channels.ContainsKey(channelId)) /* EXEMPT */
                {
                    error = String.Format(
                        "can't add {0}: channel already exists",
                        FormatOps.WrapOrNull(channelId));

                    return ReturnCode.Error;
                }

                OptionDictionary options = (clientData != null) ?
                    clientData.Options : null;

                channels.Add(channelId, Channel.CreateListener(
                    listener, channelType, options,
                    StreamFlags.ListenSocket, clientData));

                added = true;
            }

            return ReturnCode.Ok;
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Standard Channels
        /// <summary>
        /// This method adds, updates, or otherwise modifies the standard input,
        /// output, and/or error channels of this interpreter, using the streams
        /// provided by the specified host.
        /// </summary>
        /// <param name="streamHost">
        /// The host that supplies the underlying streams, or null to use the
        /// interpreter host when the channel type requests it.
        /// </param>
        /// <param name="name">
        /// The name of the channel to modify, or null to use the standard
        /// channel names.  This cannot be non-null when modifying multiple
        /// channels at once.
        /// </param>
        /// <param name="channelType">
        /// The flags that select which standard channels to modify and control
        /// how they are created or updated.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode ModifyStandardChannels(
            IStreamHost streamHost,
            string name, /* NOTE: Cannot be non-null when adding multiple channels. */
            ChannelType channelType,
            ref Result error
            )
        {
            bool locked; /* REUSED */

            if ((streamHost == null) && FlagOps.HasFlags(
                    channelType, ChannelType.UseHost, true))
            {
                locked = false;

                try
                {
                    InternalHardTryLock(ref locked);

                    if (locked)
                    {
                        streamHost = host; /* FIELD */
                    }
                    else
                    {
                        error = "unable to acquire lock";
                        return ReturnCode.Error;
                    }
                }
                finally
                {
                    InternalExitLock(ref locked);
                }
            }

            if (streamHost == null)
            {
                error = "interpreter host not available";
                return ReturnCode.Error;
            }

            locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (!PrivateHasChannels(ref error))
                        return ReturnCode.Error;

                    //
                    // HACK: For the built-in console host only,
                    //       temporarily disable the throwing of
                    //       exceptions due to the console being
                    //       closed.  This is necessary because
                    //       we need to access several properties
                    //       of the host while [re-]adding the
                    //       standard channels (e.g. from the
                    //       [host reset -channels] sub-command).
                    //       See the test "host-1.1" for details.
                    //
#if CONSOLE
                    bool? savedThrowOnMustBeOpen = null;

                    //
                    // NOTE: Is the host providing the underlying
                    //       streams actually the console host?
                    //
                    if (streamHost is _Hosts.Console)
                    {
                        //
                        // NOTE: Mark added channels as belonging
                        //       to the System.Console.
                        //
                        channelType |= ChannelType.Console;

                        //
                        // NOTE: Make sure that exceptions are
                        //       not thrown when the console is
                        //       not open during an attempt to
                        //       make use of it.
                        //
                        _Hosts.Console.BeginThrowOnMustBeOpen(
                            false, out savedThrowOnMustBeOpen);
                    }
                    else
                    {
                        //
                        // NOTE: Make sure that added channels,
                        //       if any, are -NOT- marked as
                        //       belonging to the System.Console.
                        //
                        channelType &= ~ChannelType.Console;
                    }

                    try
                    {
#endif
                        bool allowExist = FlagOps.HasFlags(
                            channelType, ChannelType.AllowExist, true);

                        bool allowProxy = FlagOps.HasFlags(
                            channelType, ChannelType.AllowProxy, true);

                        bool beginContext = FlagOps.HasFlags(
                            channelType, ChannelType.BeginContext, true);

                        bool endContext = FlagOps.HasFlags(
                            channelType, ChannelType.EndContext, true);

                        bool errorOnExist = FlagOps.HasFlags(
                            channelType, ChannelType.ErrorOnExist, true);

                        bool errorOnNotExist = FlagOps.HasFlags(
                            channelType, ChannelType.ErrorOnNotExist, true);

                        bool errorOnNull = FlagOps.HasFlags(
                            channelType, ChannelType.ErrorOnNull, true);

                        bool errorOnProxy = FlagOps.HasFlags(
                            channelType, ChannelType.ErrorOnProxy, true);

                        bool useCurrent = FlagOps.HasFlags(
                            channelType, ChannelType.UseCurrent, true);

                        bool skipGetStream = FlagOps.HasFlags(
                            channelType, ChannelType.SkipGetStream, true);

                        bool closeOnEndContext = FlagOps.HasFlags(
                            channelType, ChannelType.CloseOnEndContext, true);

                        try
                        {
                            //
                            // NOTE: When doing BeginContext and/or EndContext, we
                            //       (may) need the current interpreter host, which
                            //       may be different than the one specified by our
                            //       caller.
                            //
                            IStreamHost currentStreamHost = null;

                            if (beginContext || endContext)
                                currentStreamHost = host; /* FIELD */

                            ChannelType currentChannelType = channelType;

#if CONSOLE
                            bool? savedThrowOnMustBeOpen2 = null;

                            //
                            // NOTE: Is the current host providing the underlying
                            //       streams actually the console host?
                            //
                            if (currentStreamHost is _Hosts.Console)
                            {
                                //
                                // NOTE: Mark added channels as belonging
                                //       to the System.Console.
                                //
                                currentChannelType |= ChannelType.Console;

                                //
                                // NOTE: Make sure that exceptions are
                                //       thrown when the console is not
                                //       open during an attempt to make
                                //       use of it.
                                //
                                _Hosts.Console.BeginThrowOnMustBeOpen(
                                    false, out savedThrowOnMustBeOpen2);
                            }
                            else
                            {
                                //
                                // NOTE: Make sure that added channels,
                                //       if any, are -NOT- marked as
                                //       belonging to the System.Console.
                                //
                                currentChannelType &= ~ChannelType.Console;
                            }

                            try
                            {
#endif
                                HostFlags hostFlags = streamHost.GetHostFlags();

                                ///////////////////////////////////////////////////////////////////////

                                bool modifiedIn = false;

                                if (FlagOps.HasFlags(channelType, ChannelType.Input, true))
                                {
                                    string channelId = (name != null) ?
                                        name : StandardChannel.Input;

                                    IChannel oldChannel;

                                    bool contains = channels.TryGetValue(
                                        channelId, out oldChannel);

                                    if (allowExist || !contains)
                                    {
                                        Stream stream;
                                        Result streamError = null;

                                        stream = skipGetStream ? null :
                                            ChannelOps.GetStream(streamHost,
                                                (channelType & ~ChannelType.StandardChannels) |
                                                ChannelType.Input, useCurrent, ref streamError);

                                        if (skipGetStream || (stream != null))
                                        {
                                            if (allowProxy || (stream == null) ||
                                                !AppDomainOps.IsTransparentProxy(stream))
                                            {
                                                if (beginContext || endContext)
                                                {
                                                    IChannel contextChannel;
                                                    Result contextError; /* REUSED */
                                                    bool contextDispose;

                                                    if (contains)
                                                    {
                                                        contextError = null;
                                                        contextChannel = oldChannel;
                                                        contextDispose = false;
                                                    }
                                                    else
                                                    {
                                                        contextError = null;

                                                        contextChannel = ChannelOps.CreateInput(
                                                            currentStreamHost, currentChannelType,
                                                            ChannelOps.GetStreamFlags(),
                                                            useCurrent, ref contextError);

                                                        contextDispose = true;
                                                    }

                                                    if (contextChannel != null)
                                                    {
                                                        if (endContext)
                                                        {
                                                            contextError = null;

                                                            if (!contextChannel.EndContext(
                                                                    closeOnEndContext,
                                                                    ref contextError))
                                                            {
                                                                if (contextDispose)
                                                                {
                                                                    ObjectOps.TryDisposeOrComplain<IChannel>(
                                                                        this, ref contextChannel);
                                                                }

                                                                contextChannel = null;

                                                                error = contextError;
                                                                return ReturnCode.Error;
                                                            }
                                                        }

                                                        if (beginContext)
                                                        {
                                                            contextError = null;

                                                            if (!contextChannel.BeginContext(
                                                                    stream, ref contextError))
                                                            {
                                                                if (contextDispose)
                                                                {
                                                                    ObjectOps.TryDisposeOrComplain<IChannel>(
                                                                        this, ref contextChannel);
                                                                }

                                                                contextChannel = null;

                                                                error = contextError;
                                                                return ReturnCode.Error;
                                                            }
                                                        }

                                                        if (!contains)
                                                            channels.Add(channelId, contextChannel);
                                                    }
                                                    else if (errorOnNull)
                                                    {
                                                        if (contextError != null)
                                                        {
                                                            error = contextError;
                                                        }
                                                        else
                                                        {
                                                            error = String.Format(
                                                                "can't begin/end context for " +
                                                                "{0}: channel not available",
                                                                FormatOps.WrapOrNull(channelId));
                                                        }

                                                        return ReturnCode.Error;
                                                    }
                                                }
                                                else
                                                {
                                                    IChannel newChannel = Channel.CreateInput(
                                                        stream, channelType,
                                                        ChannelOps.GetStreamFlags(),
                                                        streamHost.InputEncoding);

                                                    if (contains)
                                                    {
                                                        ObjectOps.TryDisposeOrComplain<IChannel>(
                                                            this, ref oldChannel);

                                                        oldChannel = null;

                                                        channels[channelId] = newChannel;
                                                    }
                                                    else if (errorOnNotExist)
                                                    {
                                                        ObjectOps.TryDisposeOrComplain<IChannel>(
                                                            this, ref newChannel);

                                                        newChannel = null;

                                                        error = String.Format(
                                                            "can't update {0}: channel does not exist",
                                                            FormatOps.WrapOrNull(channelId));

                                                        return ReturnCode.Error;
                                                    }
                                                    else
                                                    {
                                                        channels.Add(channelId, newChannel);
                                                    }
                                                }

                                                modifiedIn = true;
                                            }
                                            else if (errorOnProxy)
                                            {
                                                error = String.Format(
                                                    "can't {0} {1}: stream is a proxy",
                                                    contains ? "update" : "add",
                                                    FormatOps.WrapOrNull(channelId));

                                                return ReturnCode.Error;
                                            }
                                        }
                                        else if (errorOnNull)
                                        {
                                            if (streamError != null)
                                            {
                                                error = streamError;
                                            }
                                            else
                                            {
                                                error = String.Format(
                                                    "can't {0} {1}: stream not available",
                                                    contains ? "update" : "add",
                                                    FormatOps.WrapOrNull(channelId));
                                            }

                                            return ReturnCode.Error;
                                        }
                                    }
                                    else if (errorOnExist)
                                    {
                                        error = String.Format(
                                            "can't {0} {1}: channel already exists",
                                            contains ? "update" : "add",
                                            FormatOps.WrapOrNull(channelId));

                                        return ReturnCode.Error;
                                    }
                                }

                                ///////////////////////////////////////////////////////////////////////

                                bool modifiedOut = false;

                                if (FlagOps.HasFlags(channelType, ChannelType.Output, true))
                                {
                                    string channelId = (name != null) ?
                                        name : StandardChannel.Output;

                                    IChannel oldChannel;

                                    bool contains = channels.TryGetValue(
                                        channelId, out oldChannel);

                                    if (allowExist || !contains)
                                    {
                                        Stream stream;
                                        Result streamError = null;

                                        stream = skipGetStream ? null :
                                            ChannelOps.GetStream(streamHost,
                                                (channelType & ~ChannelType.StandardChannels) |
                                                ChannelType.Output, useCurrent, ref streamError);

                                        if (skipGetStream || (stream != null))
                                        {
                                            if (allowProxy || (stream == null) ||
                                                !AppDomainOps.IsTransparentProxy(stream))
                                            {
                                                if (beginContext || endContext)
                                                {
                                                    IChannel contextChannel;
                                                    Result contextError; /* REUSED */
                                                    bool contextDispose;

                                                    if (contains)
                                                    {
                                                        contextError = null;
                                                        contextChannel = oldChannel;
                                                        contextDispose = false;
                                                    }
                                                    else
                                                    {
                                                        contextError = null;

                                                        contextChannel = ChannelOps.CreateOutput(
                                                            currentStreamHost, currentChannelType,
                                                            StreamFlags.None, useCurrent,
                                                            FlagOps.HasFlags(hostFlags,
                                                            HostFlags.AutoFlushOutput, true),
                                                            ref contextError);

                                                        contextDispose = true;
                                                    }

                                                    if (contextChannel != null)
                                                    {
                                                        if (endContext)
                                                        {
                                                            contextError = null;

                                                            if (!contextChannel.EndContext(
                                                                    closeOnEndContext,
                                                                    ref contextError))
                                                            {
                                                                if (contextDispose)
                                                                {
                                                                    ObjectOps.TryDisposeOrComplain<IChannel>(
                                                                        this, ref contextChannel);
                                                                }

                                                                contextChannel = null;

                                                                error = contextError;
                                                                return ReturnCode.Error;
                                                            }
                                                        }

                                                        if (beginContext)
                                                        {
                                                            contextError = null;

                                                            if (!contextChannel.BeginContext(
                                                                    stream, ref contextError))
                                                            {
                                                                if (contextDispose)
                                                                {
                                                                    ObjectOps.TryDisposeOrComplain<IChannel>(
                                                                        this, ref contextChannel);
                                                                }

                                                                contextChannel = null;

                                                                error = contextError;
                                                                return ReturnCode.Error;
                                                            }
                                                        }

                                                        if (!contains)
                                                            channels.Add(channelId, contextChannel);
                                                    }
                                                    else if (errorOnNull)
                                                    {
                                                        if (contextError != null)
                                                        {
                                                            error = contextError;
                                                        }
                                                        else
                                                        {
                                                            error = String.Format(
                                                                "can't begin/end context for " +
                                                                "{0}: channel not available",
                                                                FormatOps.WrapOrNull(channelId));
                                                        }

                                                        return ReturnCode.Error;
                                                    }
                                                }
                                                else
                                                {
                                                    IChannel newChannel = Channel.CreateOutput(
                                                        stream, channelType, StreamFlags.None,
                                                        streamHost.OutputEncoding, FlagOps.HasFlags(
                                                        hostFlags, HostFlags.AutoFlushOutput, true));

                                                    if (contains)
                                                    {
                                                        ObjectOps.TryDisposeOrComplain<IChannel>(
                                                            this, ref oldChannel);

                                                        oldChannel = null;

                                                        channels[channelId] = newChannel;
                                                    }
                                                    else if (errorOnNotExist)
                                                    {
                                                        ObjectOps.TryDisposeOrComplain<IChannel>(
                                                            this, ref newChannel);

                                                        newChannel = null;

                                                        error = String.Format(
                                                            "can't update {0}: channel does not exist",
                                                            FormatOps.WrapOrNull(channelId));

                                                        return ReturnCode.Error;
                                                    }
                                                    else
                                                    {
                                                        channels.Add(channelId, newChannel);
                                                    }
                                                }

                                                modifiedOut = true;
                                            }
                                            else if (errorOnProxy)
                                            {
                                                error = String.Format(
                                                    "can't {0} {1}: stream is a proxy",
                                                    contains ? "update" : "add",
                                                    FormatOps.WrapOrNull(channelId));

                                                return ReturnCode.Error;
                                            }
                                        }
                                        else if (errorOnNull)
                                        {
                                            if (streamError != null)
                                            {
                                                error = streamError;
                                            }
                                            else
                                            {
                                                error = String.Format(
                                                    "can't {0} {1}: stream not available",
                                                    contains ? "update" : "add",
                                                    FormatOps.WrapOrNull(channelId));
                                            }

                                            return ReturnCode.Error;
                                        }
                                    }
                                    else if (errorOnExist)
                                    {
                                        error = String.Format(
                                            "can't {0} {1}: channel already exists",
                                            contains ? "update" : "add",
                                            FormatOps.WrapOrNull(channelId));

                                        return ReturnCode.Error;
                                    }
                                }

                                ///////////////////////////////////////////////////////////////////////

                                bool modifiedError = false;

                                if (FlagOps.HasFlags(channelType, ChannelType.Error, true))
                                {
                                    string channelId = (name != null) ?
                                        name : StandardChannel.Error;

                                    IChannel oldChannel;

                                    bool contains = channels.TryGetValue(
                                        channelId, out oldChannel);

                                    if (allowExist || !contains)
                                    {
                                        Stream stream;
                                        Result streamError = null;

                                        stream = skipGetStream ? null :
                                            ChannelOps.GetStream(streamHost,
                                                (channelType & ~ChannelType.StandardChannels) |
                                                ChannelType.Error, useCurrent, ref streamError);

                                        if (skipGetStream || (stream != null))
                                        {
                                            if (allowProxy || (stream == null) ||
                                                !AppDomainOps.IsTransparentProxy(stream))
                                            {
                                                if (beginContext || endContext)
                                                {
                                                    IChannel contextChannel;
                                                    Result contextError; /* REUSED */
                                                    bool contextDispose;

                                                    if (contains)
                                                    {
                                                        contextError = null;
                                                        contextChannel = oldChannel;
                                                        contextDispose = false;
                                                    }
                                                    else
                                                    {
                                                        contextError = null;

                                                        contextChannel = ChannelOps.CreateError(
                                                            currentStreamHost, currentChannelType,
                                                            StreamFlags.None, useCurrent,
                                                            FlagOps.HasFlags(hostFlags,
                                                            HostFlags.AutoFlushOutput, true),
                                                            ref contextError);

                                                        contextDispose = true;
                                                    }

                                                    if (contextChannel != null)
                                                    {
                                                        if (endContext)
                                                        {
                                                            contextError = null;

                                                            if (!contextChannel.EndContext(
                                                                    closeOnEndContext,
                                                                    ref contextError))
                                                            {
                                                                if (contextDispose)
                                                                {
                                                                    ObjectOps.TryDisposeOrComplain<IChannel>(
                                                                        this, ref contextChannel);
                                                                }

                                                                contextChannel = null;

                                                                error = contextError;
                                                                return ReturnCode.Error;
                                                            }
                                                        }

                                                        if (beginContext)
                                                        {
                                                            contextError = null;

                                                            if (!contextChannel.BeginContext(
                                                                    stream, ref contextError))
                                                            {
                                                                if (contextDispose)
                                                                {
                                                                    ObjectOps.TryDisposeOrComplain<IChannel>(
                                                                        this, ref contextChannel);
                                                                }

                                                                contextChannel = null;

                                                                error = contextError;
                                                                return ReturnCode.Error;
                                                            }
                                                        }

                                                        if (!contains)
                                                            channels.Add(channelId, contextChannel);
                                                    }
                                                    else if (errorOnNull)
                                                    {
                                                        if (contextError != null)
                                                        {
                                                            error = contextError;
                                                        }
                                                        else
                                                        {
                                                            error = String.Format(
                                                                "can't begin/end context for " +
                                                                "{0}: channel not available",
                                                                FormatOps.WrapOrNull(channelId));
                                                        }

                                                        return ReturnCode.Error;
                                                    }
                                                }
                                                else
                                                {
                                                    IChannel newChannel = Channel.CreateError(
                                                        stream, channelType, StreamFlags.None,
                                                        streamHost.ErrorEncoding, FlagOps.HasFlags(
                                                        hostFlags, HostFlags.AutoFlushError, true));

                                                    if (contains)
                                                    {
                                                        ObjectOps.TryDisposeOrComplain<IChannel>(
                                                            this, ref oldChannel);

                                                        oldChannel = null;

                                                        channels[channelId] = newChannel;
                                                    }
                                                    else if (errorOnNotExist)
                                                    {
                                                        ObjectOps.TryDisposeOrComplain<IChannel>(
                                                            this, ref newChannel);

                                                        error = String.Format(
                                                            "can't update {0}: channel does not exist",
                                                            FormatOps.WrapOrNull(channelId));

                                                        return ReturnCode.Error;
                                                    }
                                                    else
                                                    {
                                                        channels.Add(channelId, newChannel);
                                                    }
                                                }

                                                modifiedError = true;
                                            }
                                            else if (errorOnProxy)
                                            {
                                                error = String.Format(
                                                    "can't {0} {1}: stream is a proxy",
                                                    contains ? "update" : "add",
                                                    FormatOps.WrapOrNull(channelId));

                                                return ReturnCode.Error;
                                            }
                                        }
                                        else if (errorOnNull)
                                        {
                                            if (streamError != null)
                                            {
                                                error = streamError;
                                            }
                                            else
                                            {
                                                error = String.Format(
                                                    "can't {0} {1}: stream not available",
                                                    contains ? "update" : "add",
                                                    FormatOps.WrapOrNull(channelId));
                                            }

                                            return ReturnCode.Error;
                                        }
                                    }
                                    else if (errorOnExist)
                                    {
                                        error = String.Format(
                                            "can't {0} {1}: channel already exists",
                                            contains ? "update" : "add",
                                            FormatOps.WrapOrNull(channelId));

                                        return ReturnCode.Error;
                                    }
                                }

                                ///////////////////////////////////////////////////////////////////////////

                                if (modifiedIn || modifiedOut || modifiedError)
                                {
                                    /* IGNORED */
                                    streamHost.SetupChannels();
                                }

                                ///////////////////////////////////////////////////////////////////////////

                                return ReturnCode.Ok;
#if CONSOLE
                            }
                            finally
                            {
                                _Hosts.Console.EndThrowOnMustBeOpen(
                                    ref savedThrowOnMustBeOpen2);
                            }
#endif
                        }
                        catch (Exception e)
                        {
                            error = e;
                            return ReturnCode.Error;
                        }
#if CONSOLE
                    }
                    finally
                    {
                        _Hosts.Console.EndThrowOnMustBeOpen(
                            ref savedThrowOnMustBeOpen);
                    }
#endif
                }
                else
                {
                    error = "unable to acquire lock";
                    return ReturnCode.Error;
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

