        internal ReturnCode ResetStandardChannels(
            IStreamHost streamHost,
            ref Result error
            )
        {
            return ModifyStandardChannels(
                streamHost, null, ChannelType.StandardChannels |
                ChannelType.AllowExist, ref error);
