        #region AppDomain
#if APPDOMAINS
        /// <summary>
        /// This method creates a new application domain and associates it with
        /// this interpreter, tracking it by its friendly name.
        /// </summary>
        /// <param name="friendlyName">
        /// The friendly name to assign to the new application domain.  An empty
        /// name is allowed.
        /// </param>
        /// <param name="baseDirectory">
        /// The base directory to use for the new application domain, if any.
        /// </param>
        /// <param name="packagePath">
        /// The package path to use for the new application domain, if any.
        /// </param>
        /// <param name="evidence">
        /// The security evidence to associate with the new application domain,
        /// if any.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the application domain, if any.
        /// </param>
        /// <param name="useBasePath">
        /// Non-zero to use the base path when configuring the application
        /// domain.
        /// </param>
        /// <param name="verifyCoreAssembly">
        /// Non-zero to verify the core assembly within the new application
        /// domain.
        /// </param>
        /// <param name="useEntryAssembly">
        /// Non-zero to use the entry assembly when configuring the application
        /// domain.
        /// </param>
        /// <param name="optionalEntryAssembly">
        /// Non-zero if the entry assembly is optional.
        /// </param>
        /// <param name="copyConfiguration">
        /// Non-zero to copy the current configuration into the new application
        /// domain.
        /// </param>
        /// <param name="appDomain">
        /// Upon success, receives the newly created application domain.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddAppDomain(
            string friendlyName,
            string baseDirectory,
            string packagePath,
#if CAS_POLICY
            Evidence evidence,
#endif
            IClientData clientData,
            bool useBasePath,
            bool verifyCoreAssembly,
            bool useEntryAssembly,
            bool optionalEntryAssembly,
            bool copyConfiguration,
            ref AppDomain appDomain,
            ref Result error
            )
        {
            //
            // NOTE: *WARNING* Empty application domain names are allowed,
            //       please do not change this to "!String.IsNullOrEmpty".
            //
            if (friendlyName != null)
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (appDomains != null)
                    {
                        if (AppDomainOps.Create(
                                this, friendlyName, baseDirectory, packagePath,
#if CAS_POLICY
                                evidence,
#endif
                                clientData, useBasePath, verifyCoreAssembly,
                                useEntryAssembly, optionalEntryAssembly,
                                copyConfiguration, ref appDomain,
                                ref error) == ReturnCode.Ok)
                        {
                            appDomains.Add(friendlyName, appDomain);

#if NOTIFY
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.AppDomain, NotifyFlags.Added,
                                new ObjectPair(friendlyName, appDomain), this,
                                clientData, null, null, ref error);
#endif

                            return ReturnCode.Ok;
                        }
                    }
                    else
                    {
                        error = "application domains not available";
                    }
                }
            }
            else
            {
                error = "invalid friendly name";
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method unloads the application domain with the specified
        /// friendly name and removes it from this interpreter.
        /// </summary>
        /// <param name="friendlyName">
        /// The friendly name of the application domain to remove.  An empty
        /// name is allowed.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RemoveAppDomain(
            string friendlyName,
            IClientData clientData,
            ref Result error
            )
        {
            //
            // NOTE: *WARNING* Empty application domain names are allowed,
            //       please do not change this to "!String.IsNullOrEmpty".
            //
            if (friendlyName != null)
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (appDomains != null)
                    {
                        AppDomain appDomain;

                        if (appDomains.TryGetValue(friendlyName, out appDomain))
                        {
                            if (AppDomainOps.Unload(
                                    friendlyName, appDomain, clientData,
                                    ref error) == ReturnCode.Ok)
                            {
                                appDomains.Remove(friendlyName);

#if NOTIFY
                                /* IGNORED */
                                CheckNotification(
                                    NotifyType.AppDomain, NotifyFlags.Removed,
                                    new ObjectPair(friendlyName, appDomain), this,
                                    clientData, null, null, ref error);
#endif

                                return ReturnCode.Ok;
                            }
                        }
                        else
                        {
                            error = String.Format(
                                "invalid application domain name {0}",
                                FormatOps.DisplayName(friendlyName));
                        }
                    }
                    else
                    {
                        error = "application domains not available";
                    }
                }
            }
            else
            {
                error = "invalid friendly name";
            }

            return ReturnCode.Error;
        }
#endif
        #endregion

