        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds (or updates) entries in the object types dictionary
        /// of this interpreter from a list of name and value pairs, optionally
        /// filtered by a pattern.
        /// </summary>
        /// <param name="list">
        /// A flat list of type name and value pairs to add; it must contain an
        /// even number of elements.
        /// </param>
        /// <param name="mode">
        /// The matching mode used when filtering type names, or
        /// <see cref="MatchMode.None" /> to add every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match type names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddObjectTypes(
            StringList list,
            MatchMode mode,
            string pattern,
            bool noCase,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // HACK: Potentially modifies object types instead of purely
                //       adding.
                //
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (HasObjectTypes(ref error))
                {
                    if (list != null)
                    {
                        if ((list.Count % 2) == 0)
                        {
                            for (int index = 0; index < list.Count; index += 2)
                            {
                                string key = list[index];

                                if (key != null) // empty string allowed.
                                {
                                    string value = list[index + 1];

                                    if ((mode == MatchMode.None) ||
                                        StringOps.Match(this, mode, key, pattern, noCase))
                                    {
                                        objectTypes[key] = value;
                                    }
                                }
                            }

                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = "type list must have an even number of elements";
                        }
                    }
                    else
                    {
                        error = "invalid type list";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes entries from the object types dictionary of this
        /// interpreter, optionally filtered by a pattern.
        /// </summary>
        /// <param name="mode">
        /// The matching mode used when filtering type names, or
        /// <see cref="MatchMode.None" /> to remove every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match type names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveObjectTypes(
            MatchMode mode,
            string pattern,
            bool noCase,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (HasObjectTypes(ref error))
                {
                    StringList keys = new StringList();

                    //
                    // NOTE: Cleanup, PASS #1, collect the list of keys we need to remove
                    //       from the types dictionary in the containing interpreter.
                    //
                    foreach (_StringPair pair in objectTypes)
                    {
                        string type = pair.Key;

                        if ((mode == MatchMode.None) ||
                            StringOps.Match(this, mode, type, pattern, noCase))
                        {
                            keys.Add(type);
                        }
                    }

                    //
                    // NOTE: Cleanup, PASS #2, and remove all the types we found from
                    //       PASS #1 (above).
                    //
                    foreach (string key in keys)
                        objectTypes.Remove(key);

                    //
                    // NOTE: Ok, we were successful.
                    //
                    return ReturnCode.Ok;
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method counts the entries in the object namespaces dictionary
        /// of this interpreter that match the specified pattern.
        /// </summary>
        /// <param name="mode">
        /// The matching mode used when filtering, or
        /// <see cref="MatchMode.None" /> to match every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="values">
        /// Non-zero to match against the associated assembly names (the values);
        /// zero to match against the namespace names (the keys).
        /// </param>
        /// <param name="matched">
        /// Incremented by the number of matching entries that are found.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode MatchObjectNamespace(
            MatchMode mode,  /* in */
            string pattern,  /* in */
            bool noCase,     /* in */
            bool values,     /* in */
            ref int matched, /* in, out */
            ref Result error /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!HasObjectNamespaces(ref error))
                    return ReturnCode.Error;

                foreach (ObjectNamespacePair pair in objectNamespaces)
                {
                    if (values)
                    {
                        string value = pair.Value;

                        if (value == null)
                            continue;

                        if ((mode == MatchMode.None) ||
                            StringOps.Match(this, mode, value, pattern, noCase))
                        {
                            matched++;
                        }
                    }
                    else
                    {
                        StringLongPair anyPair = pair.Key;

                        if (anyPair == null)
                            continue;

                        string key = anyPair.X;

                        if (key == null)
                            continue;

                        if ((mode == MatchMode.None) ||
                            StringOps.Match(this, mode, key, pattern, noCase))
                        {
                            matched++;
                        }
                    }
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds entries to the object namespaces dictionary of this
        /// interpreter from another dictionary, optionally filtered by a
        /// pattern, discarding the count of added entries.
        /// </summary>
        /// <param name="dictionary">
        /// The dictionary of namespace entries to add.
        /// </param>
        /// <param name="mode">
        /// The matching mode used when filtering namespace names, or
        /// <see cref="MatchMode.None" /> to add every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match namespace names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddObjectNamespaces(
            StringLongPairStringDictionary dictionary, /* in */
            MatchMode mode,                            /* in */
            string pattern,                            /* in */
            bool noCase,                               /* in */
            ref Result error                           /* out */
            )
        {
            int added = 0;

            return AddObjectNamespaces(
                dictionary, mode, pattern, noCase, ref added,
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds entries to the object namespaces dictionary of this
        /// interpreter from another dictionary, optionally filtered by a
        /// pattern, also reporting the number of entries added.
        /// </summary>
        /// <param name="dictionary">
        /// The dictionary of namespace entries to add.
        /// </param>
        /// <param name="mode">
        /// The matching mode used when filtering namespace names, or
        /// <see cref="MatchMode.None" /> to add every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match namespace names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="added">
        /// Incremented by the number of entries that are actually added.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddObjectNamespaces(
            StringLongPairStringDictionary dictionary, /* in */
            MatchMode mode,                            /* in */
            string pattern,                            /* in */
            bool noCase,                               /* in */
            ref int added,                             /* in, out */
            ref Result error                           /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (HasObjectNamespaces(ref error))
                {
                    if (dictionary != null)
                    {
                        foreach (ObjectNamespacePair pair in dictionary)
                        {
                            StringLongPair anyPair = pair.Key;

                            if (anyPair == null)
                                continue;

                            string key = anyPair.X;

                            if (key == null)
                                continue;

                            if ((mode == MatchMode.None) ||
                                StringOps.Match(this, mode, key, pattern, noCase))
                            {
                                if (!objectNamespaces.ContainsKey(key)) /* EXEMPT */
                                {
                                    string value = pair.Value;

                                    objectNamespaces.Add(key, value);
                                    added++;
                                }
                            }
                        }

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = "invalid namespace list";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds entries to the object namespaces dictionary of this
        /// interpreter derived from the namespaces of a sequence of managed
        /// types, optionally filtered by a pattern.
        /// </summary>
        /// <param name="types">
        /// The sequence of types whose namespaces are to be added.
        /// </param>
        /// <param name="nonPublic">
        /// Non-zero to include non-public types; zero to include only public
        /// types.
        /// </param>
        /// <param name="mode">
        /// The matching mode used when filtering namespace names, or
        /// <see cref="MatchMode.None" /> to add every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match namespace names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode AddObjectNamespaces(
            IEnumerable<Type> types,
            bool nonPublic,
            MatchMode mode,
            string pattern,
            bool noCase,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (!HasObjectNamespaces(ref error))
                    return ReturnCode.Error;

                if (types == null)
                {
                    error = "invalid type list";
                    return ReturnCode.Error;
                }

                foreach (Type type in types)
                {
                    if (type == null)
                        continue;

                    if (!nonPublic && !type.IsPublic)
                        continue;

                    string typeNamespace = type.Namespace;

                    if (String.IsNullOrEmpty(typeNamespace))
                        continue;

                    if ((mode == MatchMode.None) || StringOps.Match(
                            this, mode, typeNamespace, pattern, noCase))
                    {
                        if (!objectNamespaces.ContainsKey(
                                typeNamespace)) /* EXEMPT */
                        {
                            objectNamespaces.Add(typeNamespace,
                                AssemblyOps.GetFullName(type));
                        }
                    }
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds entries to the object namespaces dictionary of this
        /// interpreter derived from the namespaces of every type in an
        /// assembly, optionally filtered by a pattern.
        /// </summary>
        /// <param name="assembly">
        /// The assembly whose type namespaces are to be added.
        /// </param>
        /// <param name="nonPublic">
        /// Non-zero to include non-public types; zero to include only public
        /// types.
        /// </param>
        /// <param name="mode">
        /// The matching mode used when filtering namespace names, or
        /// <see cref="MatchMode.None" /> to add every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match namespace names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddObjectNamespaces(
            Assembly assembly,
            bool nonPublic,
            MatchMode mode,
            string pattern,
            bool noCase,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (!HasObjectNamespaces(ref error))
                    return ReturnCode.Error;

                if (assembly == null)
                {
                    error = "invalid assembly";
                    return ReturnCode.Error;
                }

                try
                {
                    Type[] types = assembly.GetTypes(); /* throw */

                    return AddObjectNamespaces(
                        types, nonPublic, mode, pattern, noCase, ref error);
                }
                catch (Exception e)
                {
                    error = e;
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes entries from the object namespaces dictionary of
        /// this interpreter, optionally filtered by a pattern, discarding the
        /// count of removed entries.
        /// </summary>
        /// <param name="mode">
        /// The matching mode used when filtering, or
        /// <see cref="MatchMode.None" /> to remove every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="values">
        /// Non-zero to match against the associated assembly names (the values);
        /// zero to match against the namespace names (the keys).
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveObjectNamespaces(
            MatchMode mode,
            string pattern,
            bool noCase,
            bool values,
            ref Result error
            )
        {
            int removed = 0;

            return RemoveObjectNamespaces(
                mode, pattern, noCase, values, ref removed, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes entries from the object namespaces dictionary of
        /// this interpreter, optionally filtered by a pattern, also reporting
        /// the number of entries removed.
        /// </summary>
        /// <param name="mode">
        /// The matching mode used when filtering, or
        /// <see cref="MatchMode.None" /> to remove every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="values">
        /// Non-zero to match against the associated assembly names (the values);
        /// zero to match against the namespace names (the keys).
        /// </param>
        /// <param name="removed">
        /// Incremented by the number of entries that are actually removed.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveObjectNamespaces(
            MatchMode mode,
            string pattern,
            bool noCase,
            bool values,
            ref int removed,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (!HasObjectNamespaces(ref error))
                    return ReturnCode.Error;

                StringList keys = new StringList();

                //
                // NOTE: Cleanup, PASS #1, collect the list of keys we need to remove
                //       from the namespaces collection in the containing interpreter.
                //
                foreach (ObjectNamespacePair pair in objectNamespaces)
                {
                    StringLongPair anyPair = pair.Key;

                    if (anyPair == null)
                        continue;

                    string namespaceName = anyPair.X;

                    if (namespaceName == null)
                        continue;

                    if (values)
                    {
                        string assemblyName = pair.Value;

                        if ((mode == MatchMode.None) ||
                            StringOps.Match(this, mode, assemblyName, pattern, noCase))
                        {
                            keys.Add(namespaceName);
                        }
                    }
                    else
                    {
                        if ((mode == MatchMode.None) ||
                            StringOps.Match(this, mode, namespaceName, pattern, noCase))
                        {
                            keys.Add(namespaceName);
                        }
                    }
                }

                //
                // NOTE: Cleanup, PASS #2, and remove all the namespaces we found from
                //       PASS #1 (above).
                //
                foreach (string key in keys)
                    if (objectNamespaces.Remove(key))
                        removed++;

                //
                // NOTE: Ok, we were successful.
                //
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds entries to the object interfaces dictionary of this
        /// interpreter from a sequence of managed types, considering only the
        /// interface types, optionally filtered by a pattern.
        /// </summary>
        /// <param name="types">
        /// The sequence of types to examine; only interface types are added.
        /// </param>
        /// <param name="nonPublic">
        /// Non-zero to include non-public interfaces; zero to include only
        /// public interfaces.
        /// </param>
        /// <param name="mode">
        /// The matching mode used when filtering interface names, or
        /// <see cref="MatchMode.None" /> to add every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match interface names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddObjectInterfaces(
            IEnumerable<Type> types,
            bool nonPublic,
            MatchMode mode,
            string pattern,
            bool noCase,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (HasObjectInterfaces(ref error))
                {
                    if (types != null)
                    {
                        foreach (Type type in types)
                        {
                            if ((type != null) &&
                                type.IsInterface &&
                                (nonPublic || type.IsPublic))
                            {
                                if ((mode == MatchMode.None) ||
                                    StringOps.Match(this, mode, type.FullName, pattern, noCase))
                                {
                                    if (!objectInterfaces.ContainsKey(type)) /* EXEMPT */
                                    {
                                        objectInterfaces.Add(type,
                                            new AnyPair<string, long>(
                                                AssemblyOps.GetFullName(type),
                                                NextId()));
                                    }
                                }
                            }
                        }

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = "invalid interface list";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds entries to the object interfaces dictionary of this
        /// interpreter from every interface type in an assembly, optionally
        /// filtered by a pattern.
        /// </summary>
        /// <param name="assembly">
        /// The assembly whose interface types are to be added.
        /// </param>
        /// <param name="nonPublic">
        /// Non-zero to include non-public interfaces; zero to include only
        /// public interfaces.
        /// </param>
        /// <param name="mode">
        /// The matching mode used when filtering interface names, or
        /// <see cref="MatchMode.None" /> to add every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match interface names when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddObjectInterfaces(
            Assembly assembly,
            bool nonPublic,
            MatchMode mode,
            string pattern,
            bool noCase,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (HasObjectInterfaces(ref error))
                {
                    if (assembly != null)
                    {
                        try
                        {
                            Type[] types = assembly.GetTypes();

                            return AddObjectInterfaces(
                                types, nonPublic, mode, pattern, noCase,
                                ref error);
                        }
                        catch (Exception e)
                        {
                            error = e;
                        }
                    }
                    else
                    {
                        error = "invalid assembly";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes entries from the object interfaces dictionary of
        /// this interpreter, optionally filtered by a pattern.
        /// </summary>
        /// <param name="mode">
        /// The matching mode used when filtering, or
        /// <see cref="MatchMode.None" /> to remove every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="values">
        /// Non-zero to match against the associated assembly names (the values);
        /// zero to match against the interface full names (the keys).
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveObjectInterfaces(
            MatchMode mode,
            string pattern,
            bool noCase,
            bool values,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (HasObjectInterfaces(ref error))
                {
                    TypeList keys = new TypeList();

                    //
                    // NOTE: Cleanup, PASS #1, collect the list of keys we need to remove
                    //       from the interfaces collection in the containing interpreter.
                    //
                    foreach (ObjectInterfacePair pair in objectInterfaces)
                    {
                        Type @interface = pair.Key;

                        if (@interface != null)
                        {
                            if (values)
                            {
                                IAnyPair<string, long> anyPair = pair.Value;

                                if (anyPair != null)
                                {
                                    string assemblyName = anyPair.X;

                                    if ((mode == MatchMode.None) ||
                                        StringOps.Match(this, mode, assemblyName, pattern, noCase))
                                    {
                                        keys.Add(@interface);
                                    }
                                }
                            }
                            else
                            {
                                if ((mode == MatchMode.None) ||
                                    StringOps.Match(this, mode, @interface.FullName, pattern, noCase))
                                {
                                    keys.Add(@interface);
                                }
                            }
                        }
                    }

                    //
                    // NOTE: Cleanup, PASS #2, and remove all the interfaces we found from
                    //       PASS #1 (above).
                    //
                    foreach (Type key in keys)
                        objectInterfaces.Remove(key);

                    //
                    // NOTE: Ok, we were successful.
                    //
                    return ReturnCode.Ok;
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method selects the effective alias name for an object command,
        /// preferring the explicit alias name when one is provided.
        /// </summary>
        /// <param name="objectName">
        /// The default object name to use when no alias name is provided.
        /// </param>
        /// <param name="aliasName">
        /// The explicit alias name, or null to use the object name.
        /// </param>
        /// <returns>
        /// The alias name when it is not null; otherwise, the object name.
        /// </returns>
        internal static string GetObjectAliasName(
            string objectName,
            string aliasName
            )
        {
            return (aliasName != null) ? aliasName : objectName;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the namespace-qualified alias name for an object
        /// command based on the runtime type of the wrapped object value.
        /// </summary>
        /// <param name="object">
        /// The wrapped object whose value type determines the namespace, or
        /// null to use the supplied name unchanged.
        /// </param>
        /// <param name="name">
        /// The base name to qualify, also used as the default result.
        /// </param>
        /// <returns>
        /// The namespace-qualified alias name, or the supplied name when no
        /// namespace mapping applies.
        /// </returns>
        private string GetObjectAliasName(
            IObject @object,
            string name
            )
        {
            if (@object == null)
                return name;

            object objectValue = @object.Value;

            if (objectValue == null)
                return name;

            Type type = AppDomainOps.MaybeGetTypeOrNull(objectValue);

            return GetObjectAliasName(type, name, name);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the namespace-qualified alias name for an object
        /// command based on the assembly of the specified managed type and the
        /// alias namespace mappings of this interpreter.
        /// </summary>
        /// <param name="type">
        /// The managed type whose declaring assembly determines the namespace.
        /// </param>
        /// <param name="name">
        /// The base name to qualify.
        /// </param>
        /// <param name="default">
        /// The value to return when no namespace mapping applies, or when
        /// namespaces are not enabled.
        /// </param>
        /// <returns>
        /// The namespace-qualified alias name, or the default value when no
        /// namespace mapping applies.
        /// </returns>
        internal string GetObjectAliasName(
            Type type,
            string name,
            string @default
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if ((type == null) || String.IsNullOrEmpty(name))
                    return @default;

                if (!InternalAreNamespacesEnabled())
                    return @default;

                Assembly assembly = type.Assembly;

                if (assembly == null)
                    return @default;

                string assemblyName = assembly.FullName;

                if (assemblyName == null)
                    return @default;

                string namespaceName;

                if (!objectAliasNamespaces.TryGetValue(
                        assemblyName, out namespaceName))
                {
                    return @default;
                }

                return NamespaceOps.MakeName(namespaceName, name, true, true);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method maps an assembly to the namespace that should be used for
        /// aliased object commands referencing its types.  Re-adding the same
        /// mapping is allowed, but mapping the assembly to a different namespace
        /// is an error.
        /// </summary>
        /// <param name="assembly">
        /// The assembly to map.
        /// </param>
        /// <param name="namespace">
        /// The namespace to associate with the assembly.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode AddObjectAliasNamespace(
            Assembly assembly,
            INamespace @namespace,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (!HasObjectAliasNamespaces(ref error))
                    return ReturnCode.Error;

                if (!InternalAreNamespacesEnabled())
                {
                    error = "namespaces not available";
                    return ReturnCode.Error;
                }

                if (assembly == null)
                {
                    error = "invalid assembly";
                    return ReturnCode.Error;
                }

                if (@namespace == null)
                {
                    error = "invalid namespace";
                    return ReturnCode.Error;
                }

                string assemblyName = assembly.FullName;

                if (assemblyName == null)
                {
                    error = "invalid assembly name";
                    return ReturnCode.Error;
                }

                string namespaceName;

                if (!objectAliasNamespaces.TryGetValue(
                        assemblyName, out namespaceName))
                {
                    objectAliasNamespaces.Add(
                        assemblyName, @namespace.QualifiedName);

                    return ReturnCode.Ok;
                }
                else if (SharedStringOps.SystemEquals(
                        namespaceName, @namespace.QualifiedName))
                {
                    //
                    // NOTE: Already added, same namespace name.  This
                    //       is allowed.
                    //
                    return ReturnCode.Ok;
                }
                else
                {
                    //
                    // NOTE: Already added, different namespace name.
                    //       This is an error.
                    //
                    error = String.Format(
                        "assembly {0} already mapped to namespace {1}",
                        FormatOps.DisplayName(assemblyName),
                        FormatOps.DisplayName(namespaceName));
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes entries from the object alias namespaces
        /// dictionary of this interpreter, optionally filtered by a pattern.
        /// </summary>
        /// <param name="mode">
        /// The matching mode used when filtering, or
        /// <see cref="MatchMode.None" /> to remove every entry.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match when filtering.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="values">
        /// Non-zero to match against the associated namespace names (the
        /// values); zero to match against the assembly names (the keys).
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RemoveObjectAliasNamespaces(
            MatchMode mode,
            string pattern,
            bool noCase,
            bool values,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (HasObjectAliasNamespaces(ref error))
                {
                    StringList keys = new StringList();

                    //
                    // NOTE: Cleanup, PASS #1, collect the list of keys we need to remove
                    //       from the namespaces collection in the containing interpreter.
                    //
                    foreach (_StringPair pair in objectAliasNamespaces)
                    {
                        string assemblyName = pair.Key;

                        if (values)
                        {
                            string namespaceName = pair.Value;

                            if ((mode == MatchMode.None) ||
                                StringOps.Match(this, mode, namespaceName, pattern, noCase))
                            {
                                keys.Add(assemblyName);
                            }
                        }
                        else
                        {
                            if ((mode == MatchMode.None) ||
                                StringOps.Match(this, mode, assemblyName, pattern, noCase))
                            {
                                keys.Add(assemblyName);
                            }
                        }
                    }

                    //
                    // NOTE: Cleanup, PASS #2, and remove all the namespaces we found from
                    //       PASS #1 (above).
                    //
                    foreach (string key in keys)
                        objectAliasNamespaces.Remove(key);

                    //
                    // NOTE: Ok, we were successful.
                    //
                    return ReturnCode.Ok;
                }
            }

            return ReturnCode.Error;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region INamespace
        /// <summary>
        /// Gets the global namespace associated with this interpreter.
        /// </summary>
        internal INamespace GlobalNamespace
        {
            get { /* NO-LOCK */ return globalNamespace; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the dictionary that maps namespace names for this interpreter.
        /// </summary>
        internal StringDictionary NamespaceMappings
        {
            get { /* NO-LOCK */ return namespaceMappings; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Namespace Command Support
        /// <summary>
        /// This method matches command and procedure names against a pattern,
        /// taking namespace qualification and the current namespace into
        /// account, and accumulates the results.
        /// </summary>
        /// <param name="currentNamespace">
        /// The namespace that provides the context for unqualified matching.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match item names, or null to match all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="localLists">
        /// An array of string lists used as input and output; the first element
        /// provides the candidate items and the second element receives the
        /// matching items.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode MatchItems(
            INamespace currentNamespace,
            string pattern,
            bool noCase,
            ref StringList[] localLists,
            ref Result error
            )
        {
            bool simple = NamespaceOps.ShouldUseSimpleMatching(this,
                currentNamespace, pattern, false);

            bool qualified = NamespaceOps.IsQualifiedName(pattern);

            if (simple)
            {
                if (NamespaceOps.MatchItems(
                        this, null, localLists[0],
                        pattern, noCase, false, !qualified,
                        qualified, false, ref localLists[1],
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }
            else
            {
                if ((pattern != null) && !qualified &&
                    !IsGlobalNamespace(currentNamespace))
                {
                    if (NamespaceOps.MatchItems(
                            this, currentNamespace, localLists[0],
                            pattern, noCase, true, !qualified,
                            qualified, false, ref localLists[1],
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }

                if (NamespaceOps.MatchItems(
                        this, currentNamespace, localLists[0],
                        pattern, noCase, false, !qualified,
                        qualified, false, ref localLists[1],
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Namespace Variable Support
        /// <summary>
        /// This method assigns the namespace-qualified name to a variable when
        /// namespaces are enabled and one has not already been set, based on the
        /// namespace of the variable's call frame.
        /// </summary>
        /// <param name="variable">
        /// The variable whose qualified name may be set.
        /// </param>
        /// <returns>
        /// True if the qualified name was set; otherwise, false.
        /// </returns>
        internal bool MaybeSetQualifiedName(
            IVariable variable /* in, out */
            )
        {
            //
            // NOTE: If the variable is invalid -OR- namespaces are not
            //       enabled, do nothing and return false.
            //
            if ((variable == null) || !InternalAreNamespacesEnabled())
                return false;

            //
            // HACK: Do not overwrite any existing [manually specified?]
            //       qualified name that may be stored for the variable.
            //
            string oldQualifiedName = variable.QualifiedName;

            if (oldQualifiedName != null)
                return false;

            //
            // NOTE: Grab the call frame for the variable.  If this is a scope
            //       call frame, do nothing and return false (i.e. there is no
            //       way to form a qualified name for such a variable).  This
            //       is subject to change in the future.  If this is null, the
            //       current namespace will be used; otherwise, the namespace
            //       associated with the call frame will be used.
            //
            // BUGFIX: If this is a local call frame then there should not be
            //         a qualified name set on it.
            //
            ICallFrame frame = variable.Frame;

            if (CallFrameOps.IsLocal(frame))
                return false;

            //
            // NOTE: Update the qualified name for the variable, based on the
            //       namespace for the associated call frame -OR- the current
            //       namespace (extremely rarely, if ever).
            //
            if (frame != null)
            {
                variable.QualifiedName = NamespaceOps.MakeAbsoluteName(
                    NamespaceOps.MakeQualifiedName(this,
                        NamespaceOps.GetCurrent(this, frame), variable.Name));
            }
            else
            {
                variable.QualifiedName = NamespaceOps.MakeQualifiedName(
                    this, variable.Name, true);
            }

            return true;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Namespace Status Support
        /// <summary>
        /// This method determines whether namespace support is enabled for this
        /// interpreter, based on its creation flags.
        /// </summary>
        /// <returns>
        /// True if namespaces are enabled; otherwise, false.
        /// </returns>
        internal bool InternalAreNamespacesEnabled()
        {
            return RuntimeOps.AreNamespacesEnabled(createFlags);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified namespace is currently
        /// in use, based on its outstanding references and, for the global
        /// namespace, whether the interpreter call stack is unwound.
        /// </summary>
        /// <param name="namespace">
        /// The namespace to check.
        /// </param>
        /// <returns>
        /// True if the namespace is in use; otherwise, false.
        /// </returns>
        private bool IsNamespaceInUse(
            INamespace @namespace
            )
        {
            if (@namespace != null)
            {
                //
                // NOTE: Namespaces are considered to be "in-use"
                //       until they no longer have any outstanding
                //       references.
                //
                if (@namespace.ReferenceCount > 0)
                    return true;

                //
                // NOTE: Non-global namespaces are not considered to
                //       be "in-use" just because the call stack for
                //       the interpreter is not completely unwound.
                //
                if (!IsGlobalNamespace(@namespace))
                    return false;
            }

            //
            // NOTE: The global namespace is "in-use" until the call
            //       stack for the interpreter is completely unwound.
            //
            return InternalIsBusy;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified namespace can be
        /// renamed.  A namespace can be renamed only when it is not in use.
        /// </summary>
        /// <param name="namespace">
        /// The namespace to check.
        /// </param>
        /// <returns>
        /// True if the namespace can be renamed; otherwise, false.
        /// </returns>
        private bool CanRenameNamespace( /* EXPERIMENTAL */
            INamespace @namespace
            )
        {
            return !IsNamespaceInUse(@namespace);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified namespace can be
        /// deleted.  A namespace can be deleted only when it is not in use.
        /// </summary>
        /// <param name="namespace">
        /// The namespace to check.
        /// </param>
        /// <returns>
        /// True if the namespace can be deleted; otherwise, false.
        /// </returns>
        private bool CanDeleteNamespace(
            INamespace @namespace
            )
        {
            return !IsNamespaceInUse(@namespace);
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Namespace Traversal Support
        #region For Namespace Diagnostic Use Only
#if SHELL
        /// <summary>
        /// This method writes a diagnostic listing of every namespace in this
        /// interpreter, optionally including their imports and exports, to the
        /// interactive host.
        /// </summary>
        /// <param name="imports">
        /// Non-zero to include the import names of each namespace.
        /// </param>
        /// <param name="exports">
        /// Non-zero to include the export names of each namespace.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode ShowNamespaces(
            bool imports,
            bool exports,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (globalNamespace == null)
                {
                    error = "invalid global namespace";
                    return ReturnCode.Error;
                }

                try
                {
                    return globalNamespace.Traverse(
                        ShowNamespace, new ClientData(new Pair<bool>(
                        imports, exports)), ref error);
                }
                catch (Exception e)
                {
                    error = e;
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method writes the diagnostic listing for a single namespace,
        /// optionally including its imports and exports, to the interactive
        /// host.  It is intended for use as a namespace traversal callback.
        /// </summary>
        /// <param name="namespace">
        /// The namespace to describe.
        /// </param>
        /// <param name="clientData">
        /// The extra data carrying a boolean pair that indicates whether to
        /// include imports and exports.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode ShowNamespace(
            INamespace @namespace,
            IClientData clientData,
            ref Result error
            ) /* NamespaceCallback */
        {
            if (@namespace == null)
            {
                error = "invalid namespace";
                return ReturnCode.Error;
            }

            if (clientData == null)
            {
                error = "invalid clientData";
                return ReturnCode.Error;
            }

            IPair<bool> pair = clientData.Data as IPair<bool>;

            if (pair == null)
            {
                error = "invalid boolean pair";
                return ReturnCode.Error;
            }

            bool imports = pair.X;
            bool exports = pair.Y;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                IInteractiveHost interactiveHost = GetInteractiveHost();

                if (interactiveHost == null)
                {
                    error = "interpreter host not available";
                    return ReturnCode.Error;
                }

                if (!interactiveHost.WriteLine(String.Format(
                        "NAMESPACE {0}",
                        FormatOps.DisplayValue(@namespace.QualifiedName))))
                {
                    error = "write to host failed";
                    return ReturnCode.Error;
                }

                if (imports)
                {
                    foreach (string importName in
                            @namespace.GetImportNames(null, true, false))
                    {
                        if (!interactiveHost.WriteLine(String.Format(
                                "IMPORT-SOURCE {0}",
                                FormatOps.DisplayValue(importName))))
                        {
                            error = "write to host failed";
                            return ReturnCode.Error;
                        }
                    }

                    foreach (string importName in
                            @namespace.GetImportNames(null, false, false))
                    {
                        if (!interactiveHost.WriteLine(String.Format(
                                "IMPORT-TARGET {0}",
                                FormatOps.DisplayValue(importName))))
                        {
                            error = "write to host failed";
                            return ReturnCode.Error;
                        }
                    }
                }

                if (exports)
                {
                    StringList exportNames = @namespace.GetExportNames(null);

                    if (exportNames == null)
                    {
                        error = "invalid namespace export names list";
                        return ReturnCode.Error;
                    }

                    foreach (string exportName in exportNames)
                    {
                        if (!interactiveHost.WriteLine(String.Format(
                                "EXPORT {0}",
                                FormatOps.DisplayValue(exportName))))
                        {
                            error = "write to host failed";
                            return ReturnCode.Error;
                        }
                    }
                }

                return ReturnCode.Ok;
            }
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region For Namespace Import Renaming
        /// <summary>
        /// This method renames an imported command in every namespace of this
        /// interpreter by traversing the namespace tree from the global
        /// namespace.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the imported command.
        /// </param>
        /// <param name="newName">
        /// The new name for the imported command.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RenameImportInNamespaces(
            string oldName,
            string newName,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (globalNamespace == null)
                {
                    error = "invalid global namespace";
                    return ReturnCode.Error;
                }

                try
                {
                    return globalNamespace.Traverse(
                        RenameImportInNamespace, new ClientData(
                        new StringPair(oldName, newName)), ref error);
                }
                catch (Exception e)
                {
                    error = e;
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames an imported command in a single namespace.  It is
        /// intended for use as a namespace traversal callback.
        /// </summary>
        /// <param name="namespace">
        /// The namespace in which to rename the imported command.
        /// </param>
        /// <param name="clientData">
        /// The extra data carrying a string pair with the old and new command
        /// names.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RenameImportInNamespace(
            INamespace @namespace,
            IClientData clientData,
            ref Result error
            ) /* NamespaceCallback */
        {
            if (@namespace == null)
            {
                error = "invalid namespace";
                return ReturnCode.Error;
            }

            if (clientData == null)
            {
                error = "invalid clientData";
                return ReturnCode.Error;
            }

            IPair<string> pair = clientData.Data as IPair<string>;

            if (pair == null)
            {
                error = "invalid string pair";
                return ReturnCode.Error;
            }

            string oldName = pair.X;

            if (oldName == null)
            {
                error = "invalid old command name";
                return ReturnCode.Error;
            }

            string newName = pair.Y;

            if (newName == null)
            {
                error = "invalid new command name";
                return ReturnCode.Error;
            }

            if (@namespace.RenameImport(
                    oldName, newName, false, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region For Namespace Import Removal
        /// <summary>
        /// This method removes an imported command from every namespace of this
        /// interpreter by traversing the namespace tree from the global
        /// namespace.
        /// </summary>
        /// <param name="name">
        /// The name of the imported command to remove.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RemoveImportFromNamespaces(
            string name,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (globalNamespace == null)
                {
                    error = "invalid global namespace";
                    return ReturnCode.Error;
                }

                try
                {
                    return globalNamespace.Traverse(
                        RemoveImportFromNamespace, new ClientData(name),
                        ref error);
                }
                catch (InterpreterDisposedException)
                {
                    //
                    // NOTE: This method is called (indirectly) via the
                    //       disposal pipeline (i.e. also possibly on a
                    //       GC thread); therefore, just ignore this
                    //       exception.
                    //
                    return ReturnCode.Ok;
                }
                catch (Exception e)
                {
                    error = e;
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes an imported command from a single namespace.  It
        /// is intended for use as a namespace traversal callback.
        /// </summary>
        /// <param name="namespace">
        /// The namespace from which to remove the imported command.
        /// </param>
        /// <param name="clientData">
        /// The extra data carrying the name of the imported command to remove.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RemoveImportFromNamespace(
            INamespace @namespace,
            IClientData clientData,
            ref Result error
            ) /* NamespaceCallback */
        {
            if (@namespace == null)
            {
                error = "invalid namespace";
                return ReturnCode.Error;
            }

            if (clientData == null)
            {
                error = "invalid clientData";
                return ReturnCode.Error;
            }

            string name = clientData.Data as string;

            if (name == null)
            {
                error = "invalid command name";
                return ReturnCode.Error;
            }

            if (@namespace.RemoveImports(
                    name, false, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region For Generic Namespace Traversal
        /// <summary>
        /// This method invokes the specified callback for every namespace in
        /// this interpreter by traversing the namespace tree from the global
        /// namespace.
        /// </summary>
        /// <param name="callback">
        /// The callback to invoke for each namespace.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to the callback, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InvokeInEachNamespace(
            NamespaceCallback callback,
            IClientData clientData,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (globalNamespace == null)
                {
                    error = "invalid global namespace";
                    return ReturnCode.Error;
                }

                try
                {
                    return globalNamespace.Traverse(
                        callback, clientData, ref error);
                }
                catch (Exception e)
                {
                    error = e;
                }

                return ReturnCode.Error;
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Namespace Deletion Support
        /// <summary>
        /// This method deletes any namespaces that are pending cleanup for this
        /// interpreter, or deletes the global namespace when namespace support
        /// is disabled, clearing the pending cleanup flag on success.
        /// </summary>
        /// <param name="flags">
        /// The variable flags to use while deleting namespace variables.
        /// </param>
        /// <param name="force">
        /// Non-zero to forcibly delete the namespaces.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode CleanupNamespaces(
            VariableFlags flags,
            bool force,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool pendingCleanup = IsPendingCleanup();

                if (pendingCleanup && InternalAreNamespacesEnabled())
                {
                    if (pendingNamespaces == null)
                    {
                        result = "namespaces pending cleanup not available";
                        return ReturnCode.Error;
                    }

                    //
                    // NOTE: This foreach cannot simply iterate over the pending
                    //       namespace dictionary itself because it is modified
                    //       by the contained DeleteNamespace method.
                    //
                    Result localResult = null;
                    StringList keys = new StringList(pendingNamespaces.Keys);

                    foreach (string key in keys)
                    {
                        INamespace @namespace;

                        if (!pendingNamespaces.TryGetValue(key, out @namespace))
                            continue;

                        if (@namespace == null)
                            continue;

                        //
                        // HACK: If the namespace was somehow "undeleted" prior
                        //       to this cleanup method running, then do *NOT*
                        //       delete it; however, we still want to remove it
                        //       from the pending cleanup list.
                        //
                        if (@namespace.Deleted && DeleteNamespace(
                                flags, @namespace, force,
                                ref localResult) != ReturnCode.Ok)
                        {
                            break;
                        }
                    }

                    //
                    // NOTE: In this context, "success" means that there should
                    //       be no more namespaces pending deletion af this
                    //       point.
                    //
                    if (pendingNamespaces.Count == 0)
                    {
                        UnsetPendingCleanup();
                        return ReturnCode.Ok;
                    }

                    //
                    // NOTE: If there is a local result, use it; otherwise,
                    //       return a generic error message.
                    //
                    if (localResult != null)
                        result = localResult;
                    else
                        result = "some namespaces pending cleanup not deleted";

                    return ReturnCode.Error;
                }
                else if (pendingCleanup)
                {
                    //
                    // NOTE: Namespace support is disabled; therefore, just
                    //       delete the global namespace now.
                    //
                    if (DeleteNamespace(
                            flags, (INamespace)null, false,
                            ref result) == ReturnCode.Ok)
                    {
                        UnsetPendingCleanup();
                        return ReturnCode.Ok;
                    }

                    return ReturnCode.Error;
                }
                else
                {
                    //
                    // NOTE: Namespace support is disabled and the pending
                    //       cleanup flag for the interpreter is not set,
                    //       do nothing.
                    //
                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames the namespace with the specified name, looking up
        /// both the source and destination by name first and verifying that the
        /// destination does not already exist.
        /// </summary>
        /// <param name="oldName">
        /// The name of the namespace to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the namespace.
        /// </param>
        /// <param name="globalOk">
        /// Non-zero to permit renaming the global namespace.
        /// </param>
        /// <param name="inUseOk">
        /// Non-zero to permit renaming a namespace that is currently in use.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode RenameNamespace( /* EXPERIMENTAL */
            string oldName,
            string newName,
            bool globalOk,
            bool inUseOk,
            ref Result result
            )
        {
            // CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (InternalAreNamespacesEnabled())
                {
                    INamespace @namespace = NamespaceOps.Lookup(
                        this, oldName, false, false);

                    if (@namespace == null)
                    {
                        result = String.Format(
                            "unknown namespace {0} in namespace rename command",
                            FormatOps.DisplayName(oldName));

                        return ReturnCode.Error;
                    }

                    if (NamespaceOps.Lookup(
                            this, newName, false, false) != null)
                    {
                        result = String.Format(
                            "can't rename to {0}: namespace already exists",
                            FormatOps.DisplayName(newName));

                        return ReturnCode.Error;
                    }

                    return RenameNamespace(
                        @namespace, newName, globalOk, inUseOk, ref result);
                }
                else
                {
                    result = "namespaces not available";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual renaming of a namespace, including
        /// creating the destination namespace, moving its commands, procedures,
        /// and child namespaces, and deleting the original namespace.
        /// </summary>
        /// <param name="oldNamespace">
        /// The namespace to rename.
        /// </param>
        /// <param name="newName">
        /// The new name for the namespace.
        /// </param>
        /// <param name="globalOk">
        /// Non-zero to permit renaming the global namespace.
        /// </param>
        /// <param name="inUseOk">
        /// Non-zero to permit renaming a namespace that is currently in use.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RenameNamespace( /* EXPERIMENTAL */
            INamespace oldNamespace,
            string newName,
            bool globalOk,
            bool inUseOk,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // NOTE: Phase 0: Verify all parameters and initial state.
                //
                if (!InternalAreNamespacesEnabled())
                {
                    result = "namespaces not available";
                    return ReturnCode.Error;
                }

                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                if (oldNamespace == null)
                {
                    result = "invalid namespace";
                    return ReturnCode.Error;
                }

                //
                // NOTE: Renaming the global namespace is generally not a very
                //       good idea; however, it is technically possible with
                //       one major limiation:
                //
                //       Any global variables that exist before the rename will
                //       continue to exist after the rename [and they will also
                //       continue to be global variables].  Furthermore, the
                //       global call frame itself will be completely unchanged.
                //
                if (!globalOk && IsGlobalNamespace(oldNamespace))
                {
                    result = String.Format(
                        "can't rename {0}: namespace is global",
                        FormatOps.DisplayName(oldNamespace.QualifiedName));

                    return ReturnCode.Error;
                }

                //
                // NOTE: Renaming any namespace that is in use is a very bad
                //       idea; however, it is technically possible; however,
                //       it is highly likely that the script in progress may
                //       return an error, due to moved commands or variables
                //       being seen as "missing".
                //
                if (!inUseOk && !CanRenameNamespace(oldNamespace))
                {
                    result = String.Format(
                        "can't rename {0}: namespace in use",
                        FormatOps.DisplayName(oldNamespace.QualifiedName));

                    return ReturnCode.Error;
                }

                //
                // NOTE: Phase 1: Lookup (or create) the parent of the target
                //       namespace.
                //
                INamespace newParentNamespace = NamespaceOps.LookupParent(
                    this, newName, false, false, true, ref result);

                if (newParentNamespace == null)
                    return ReturnCode.Error;

                //
                // TODO: For now, raise a script error when trying to rename a
                //       namespace to a position that would be beneath itself
                //       in the tree.  In the future, this restriction may be
                //       relaxed.
                //
                if (NamespaceOps.IsDescendant(
                        newParentNamespace, oldNamespace))
                {
                    result = String.Format(
                        "can't rename {0}: new parent is descendant",
                        FormatOps.DisplayName(oldNamespace.QualifiedName));

                    return ReturnCode.Error;
                }

                //
                // HACK: Refuse to start the namespace renaming process if we
                //       cannot create one more namespace, which is required
                //       by the renaming process.
                //
                if (!CanAddNamespace(ref result))
                    return ReturnCode.Error;

                //
                // NOTE: Phase 2: Create the target namespace and link it with
                //       its parent.
                //
                bool success = false;
                INamespace newNamespace = null;
                string newLocalName = NamespaceOps.TailOnly(newName);

                try
                {
                    newNamespace = NamespaceOps.CreateFrom(
                        newLocalName, null, this, newParentNamespace, null,
                        oldNamespace, oldNamespace.Unknown, null, false);

                    if (newNamespace == null)
                    {
                        result = String.Format(
                            "creation of namespace {0} in " +
                            "{1} failed", FormatOps.WrapOrNull(
                            newLocalName), FormatOps.WrapOrNull(
                            newParentNamespace.QualifiedName));

                        return ReturnCode.Error;
                    }

                    if (newParentNamespace.AddChild(
                            newNamespace, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    /* IGNORED */
                    TrackNamespaceAdded();

                    success = true;
                }
                finally
                {
                    if (!success && (newNamespace != null))
                        NamespaceOps.Dispose(this, ref newNamespace);
                }

                //
                // NOTE: Phase 3: Find all matching IExecute-derived entities
                //       from the source namespace (and its children) and then
                //       move (rename) them into the target namespace tree.
                //
                IList<IPair<string>> oldAndNewNames = null;

                if (RenameNamespaceIExecutes(
                        oldNamespace, newNamespace, true, false,
                        ref oldAndNewNames, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                //
                // NOTE: The following handling applies only to those source
                //       namespaces that are not global.
                //
                if (!IsGlobalNamespace(oldNamespace))
                {
                    //
                    // NOTE: Phase 4: Move all child namespaces from the source
                    //       namespace to the target namespace.  This makes no
                    //       sense if the source namespace is global.
                    //
                    if (newNamespace.MoveAllChildren(
                            oldNamespace, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    //
                    // NOTE: Phase 5: Delete the source namespace unless it is
                    //       the global namespace -OR- an ancestor of the target
                    //       one.
                    //
                    if (!NamespaceOps.IsDescendant(newNamespace, oldNamespace))
                    {
                        Result localResult = null;

                        if (DeleteNamespace(
                                VariableFlags.None, oldNamespace, inUseOk,
                                ref localResult) != ReturnCode.Ok)
                        {
                            result = localResult;
                            return ReturnCode.Error;
                        }
                    }
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method moves the commands and procedures from one namespace into
        /// another as part of a namespace rename, recording the old and new
        /// names of each moved entity.
        /// </summary>
        /// <param name="oldNamespace">
        /// The namespace whose commands and procedures are to be moved.
        /// </param>
        /// <param name="newNamespace">
        /// The destination namespace for the moved commands and procedures.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to suppress namespace processing while renaming each entity.
        /// </param>
        /// <param name="delete">
        /// Non-zero to delete the original entities after moving them.
        /// </param>
        /// <param name="oldAndNewNames">
        /// Receives the list of old and new name pairs for the moved entities,
        /// for use when fixing up imports and exports.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode RenameNamespaceIExecutes(
            INamespace oldNamespace,
            INamespace newNamespace,
            bool noNamespaces,
            bool delete,
            ref IList<IPair<string>> oldAndNewNames,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (oldNamespace == null)
                {
                    error = "invalid old namespace";
                    return ReturnCode.Error;
                }

                if (newNamespace == null)
                {
                    error = "invalid new namespace";
                    return ReturnCode.Error;
                }

                string pattern = NamespaceOps.MakeQualifiedPattern(
                    this, oldNamespace, null, false);

                ObjectDictionary dictionary = null;

                if (ListAnyIExecute(pattern, false, true, false,
                        ref dictionary, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                StringList list = new StringList(dictionary.Keys);

                foreach (string oldItemName in list)
                {
                    if (oldItemName == null)
                        continue;

                    string oldQualifiedName = ScriptOps.MakeCommandPrefix(
                        oldNamespace.QualifiedName);

                    if (oldQualifiedName == null)
                        continue;

                    if (!oldItemName.StartsWith(oldQualifiedName,
                            SharedStringOps.SystemComparisonType))
                    {
                        continue;
                    }

                    string newQualifiedName = ScriptOps.MakeCommandPrefix(
                        newNamespace.QualifiedName);

                    if (newQualifiedName == null)
                        continue;

                    string newItemName = NamespaceOps.MakeQualifiedName(
                        newQualifiedName, oldItemName.Substring(
                        oldQualifiedName.Length), true);

                    Result localResult = null;

                    if (RenameAnyIExecute(
                            oldItemName, newItemName, null,
                            IdentifierKind.None, noNamespaces,
                            delete, false, true, false,
                            ref localResult) != ReturnCode.Ok)
                    {
                        error = localResult;
                        return ReturnCode.Error;
                    }

                    //
                    // NOTE: Record the name change for later use when
                    //       dealing with imports/exports.
                    //
                    if (oldAndNewNames == null)
                        oldAndNewNames = new List<IPair<string>>();

                    oldAndNewNames.Add(new Pair<string>(
                        oldItemName, newItemName));
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method deletes the namespace with the specified name, looking it
        /// up by name first when namespace support is enabled.
        /// </summary>
        /// <param name="flags">
        /// The variable flags to use while deleting namespace variables.
        /// </param>
        /// <param name="name">
        /// The name of the namespace to delete.
        /// </param>
        /// <param name="force">
        /// Non-zero to forcibly delete the namespace.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode DeleteNamespace(
            VariableFlags flags,
            string name,
            bool force,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                INamespace @namespace = null;

                if (InternalAreNamespacesEnabled())
                {
                    @namespace = NamespaceOps.Lookup(this, name, false, false);

                    if (@namespace == null)
                    {
                        result = String.Format(
                            "unknown namespace {0} in namespace delete command",
                            FormatOps.DisplayName(name)); /* COMPAT: Tcl. */

                        return ReturnCode.Error;
                    }
                }

                return DeleteNamespace(flags, @namespace, force, ref result);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual deletion of a namespace, including
        /// removing its variables, commands, procedures, and child namespaces,
        /// and handling the global namespace specially.
        /// </summary>
        /// <param name="flags">
        /// The variable flags to use while deleting namespace variables.
        /// </param>
        /// <param name="namespace">
        /// The namespace to delete.
        /// </param>
        /// <param name="force">
        /// Non-zero to forcibly delete the namespace.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode DeleteNamespace(
            VariableFlags flags,
            INamespace @namespace,
            bool force,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref result))
                    return ReturnCode.Error;

                bool useNamespaces = InternalAreNamespacesEnabled();

                if (useNamespaces && (@namespace == null))
                {
                    result = "invalid namespace";
                    return ReturnCode.Error;
                }

                //
                // NOTE: Grab the fully qualified name for the namespace now
                //       as it is needed in several places in this method.
                //
                string qualifiedName = (@namespace != null) ?
                    @namespace.QualifiedName : null;

                //
                // NOTE: See if we can delete the namespace immediately -OR-
                //       if we have to wait until the evluation stack for the
                //       namespace is completely unwound.
                //
                if (force || CanDeleteNamespace(@namespace))
                {
                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Delete all children of the namespace first.
                    //
                    if (@namespace != null)
                    {
                        foreach (INamespace childNamespace in
                                /* ALL */ @namespace.GetChildren(null, true))
                        {
                            if (childNamespace == null)
                                continue;

                            if (DeleteNamespace(
                                    flags, childNamespace, force,
                                    ref result) != ReturnCode.Ok) /* RECURSIVE */
                            {
                                return ReturnCode.Error;
                            }
                        }
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Remove all commands that were imported into the
                    //       namespace now.  Each imported command actually
                    //       corresponds to an alias name token in the target
                    //       interpreter.
                    //
                    if (@namespace != null)
                    {
                        if (@namespace.RemoveAllImports(
                                false, ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Remove all exported commands belonging to this
                    //       namespace from all other namespaces now.
                    //
                    if (@namespace != null)
                    {
                        if (RemoveImportFromNamespaces(
                                NamespaceOps.MakeQualifiedPattern(
                                this, @namespace, null, false),
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Apparently, hidden commands should only be deleted
                    //       from non-global namespaces (COMPAT: Tcl).
                    //
                    bool deleteHidden = !useNamespaces || !IsGlobalNamespace(
                        @namespace);

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Remove all hidden IExecute objects in the
                    //       namespace now.
                    //
                    if (deleteHidden && (hiddenExecutes != null))
                    {
                        StringList keys = null;

                        if (useNamespaces)
                        {
                            if (NamespaceOps.MatchItems(
                                    this, @namespace, hiddenExecutes.Keys,
                                    null, false, false, false, false, false,
                                    ref keys, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }
                        else
                        {
                            keys = new StringList(hiddenExecutes.Keys);
                        }

                        foreach (string key in keys)
                        {
                            /* IGNORED */
                            hiddenExecutes.Remove(key);
                        }

#if EXECUTE_CACHE
                        //
                        // BUGFIX: Everything may have just gone away,
                        //         clear the caches now.
                        //
                        /* IGNORED */
                        ClearExecuteCache();
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(null);
#endif
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Remove all non-hidden IExecute objects in the
                    //       namespace now.
                    //
                    if (executes != null)
                    {
                        StringList keys = null;

                        if (useNamespaces)
                        {
                            if (NamespaceOps.MatchItems(
                                    this, @namespace, executes.Keys,
                                    null, false, false, false, false, false,
                                    ref keys, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }
                        else
                        {
                            keys = new StringList(executes.Keys);
                        }

                        foreach (string key in keys)
                        {
                            /* IGNORED */
                            executes.Remove(key);
                        }

#if EXECUTE_CACHE
                        //
                        // BUGFIX: Everything may have just gone away,
                        //         clear the caches now.
                        //
                        /* IGNORED */
                        ClearExecuteCache();
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(null);
#endif
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Remove hidden all procedures in the namespace
                    //       now.
                    //
                    if (deleteHidden && (hiddenProcedures != null))
                    {
                        StringList keys = null;

                        if (useNamespaces)
                        {
                            if (NamespaceOps.MatchItems(
                                    this, @namespace, hiddenProcedures.Keys,
                                    null, false, false, false, false, false,
                                    ref keys, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }
                        else
                        {
                            keys = new StringList(hiddenProcedures.Keys);
                        }

                        foreach (string key in keys)
                        {
                            IProcedure procedure = hiddenProcedures[key];

                            if (procedure == null)
                            {
                                /* IGNORED */
                                hiddenProcedures.Remove(key);

                                continue;
                            }

                            //
                            // BUGFIX: Skip deleting read-only procedures.
                            //
                            if (EntityOps.IsReadOnly(procedure) ||
                                EntityOps.IsNoRemove(procedure))
                            {
                                continue;
                            }

                            /* IGNORED */
                            hiddenProcedures.Remove(key);
                        }

#if EXECUTE_CACHE
                        //
                        // BUGFIX: Everything may have just gone away,
                        //         clear the caches now.
                        //
                        /* IGNORED */
                        ClearExecuteCache();
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(null);
#endif
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Remove non-hidden all procedures in the namespace
                    //       now.
                    //
                    if (procedures != null)
                    {
                        StringList keys = null;

                        if (useNamespaces)
                        {
                            if (NamespaceOps.MatchItems(
                                    this, @namespace, procedures.Keys,
                                    null, false, false, false, false, false,
                                    ref keys, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }
                        else
                        {
                            keys = new StringList(procedures.Keys);
                        }

                        foreach (string key in keys)
                        {
                            IProcedure procedure = procedures[key];

                            if (procedure == null)
                            {
                                /* IGNORED */
                                procedures.Remove(key);

                                continue;
                            }

                            //
                            // BUGFIX: Skip deleting read-only procedures.
                            //
                            if (EntityOps.IsReadOnly(procedure) ||
                                EntityOps.IsNoRemove(procedure))
                            {
                                continue;
                            }

                            /* IGNORED */
                            procedures.Remove(key);
                        }

#if EXECUTE_CACHE
                        //
                        // BUGFIX: Everything may have just gone away,
                        //         clear the caches now.
                        //
                        /* IGNORED */
                        ClearExecuteCache();
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(null);
#endif
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Attempt to terminate and remove all hidden
                    //       commands for the namespace now.
                    //
                    if (deleteHidden && (hiddenCommands != null))
                    {
                        StringList keys = null;

                        if (useNamespaces)
                        {
                            if (NamespaceOps.MatchItems(
                                    this, @namespace, hiddenCommands.Keys,
                                    null, false, false, false, false, false,
                                    ref keys, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }
                        else
                        {
                            keys = new StringList(hiddenCommands.Keys);
                        }

                        foreach (string key in keys)
                        {
                            ICommand command = hiddenCommands[key];

                            if (command == null)
                            {
                                /* IGNORED */
                                hiddenCommands.Remove(key);

                                continue;
                            }

                            //
                            // BUGFIX: Skip deleting read-only commands.
                            //
                            if (EntityOps.IsReadOnly(command))
                                continue;

                            string commandName = null;

                            ReturnCode code;

                            /* NO RESULT */
                            GlobalState.PushActiveInterpreter(this);

                            try
                            {
                                commandName = EntityOps.GetNameNoThrow(command);

                                code = TerminateCommand(command, null, ref result);
                            }
                            catch (Exception e)
                            {
                                result = String.Format(
                                    "caught exception while deleting hidden command {0}: {1}",
                                     FormatOps.WrapOrNull(commandName), e);

                                code = ReturnCode.Error;
                            }
                            finally
                            {
                                /* IGNORED */
                                GlobalState.PopActiveInterpreter();
                            }

                            if (code == ReturnCode.Ok)
                            {
                                //
                                // NOTE: Command terminated, remove it.
                                //
                                /* IGNORED */
                                hiddenCommands.Remove(key);

                                TraceOps.DebugTrace(String.Format(
                                    "DeleteNamespace: deleted hidden command {0}",
                                    FormatOps.WrapOrNull(commandName)),
                                    typeof(Interpreter).Name,
                                    TracePriority.CleanupDebug);
                            }
                            else
                            {
                                //
                                // NOTE: Failure, halt deletion.
                                //
                                return code;
                            }
                        }

#if EXECUTE_CACHE
                        //
                        // BUGFIX: Everything may have just gone away,
                        //         clear the caches now.
                        //
                        /* IGNORED */
                        ClearExecuteCache();
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(null);
#endif
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Attempt to terminate and remove all non-hidden
                    //       commands for the namespace now.
                    //
                    if (commands != null)
                    {
                        StringList keys = null;

                        if (useNamespaces)
                        {
                            if (NamespaceOps.MatchItems(
                                    this, @namespace, commands.Keys,
                                    null, false, false, false, false, false,
                                    ref keys, ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }
                        }
                        else
                        {
                            keys = new StringList(commands.Keys);
                        }

                        foreach (string key in keys)
                        {
                            ICommand command = commands[key];

                            if (command == null)
                            {
                                /* IGNORED */
                                commands.Remove(key);

                                continue;
                            }

                            //
                            // BUGFIX: Skip deleting read-only commands.
                            //
                            if (EntityOps.IsReadOnly(command))
                                continue;

                            string commandName = null;

                            ReturnCode code;

                            GlobalState.PushActiveInterpreter(this);

                            try
                            {
                                commandName = EntityOps.GetNameNoThrow(command);

                                code = TerminateCommand(command, null, ref result);
                            }
                            catch (Exception e)
                            {
                                result = String.Format(
                                    "caught exception while deleting command {0}: {1}",
                                    FormatOps.WrapOrNull(commandName), e);

                                code = ReturnCode.Error;
                            }
                            finally
                            {
                                /* IGNORED */
                                GlobalState.PopActiveInterpreter();
                            }

                            if (code == ReturnCode.Ok)
                            {
                                //
                                // NOTE: Command terminated, remove it.
                                //
                                /* IGNORED */
                                commands.Remove(key);

                                TraceOps.DebugTrace(String.Format(
                                    "DeleteNamespace: deleted command {0}",
                                    FormatOps.WrapOrNull(commandName)),
                                    typeof(Interpreter).Name,
                                    TracePriority.CleanupDebug);
                            }
                            else
                            {
                                //
                                // NOTE: Failure, halt deletion.
                                //
                                return code;
                            }
                        }

#if EXECUTE_CACHE
                        //
                        // BUGFIX: Everything may have just gone away,
                        //         clear the caches now.
                        //
                        /* IGNORED */
                        ClearExecuteCache();
#endif

#if ARGUMENT_CACHE
                        /* IGNORED */
                        MaybeClearArgumentCache(null);
#endif
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Next, remove all variables in the namespace now.
                    //       This step may remove all global variables (i.e.
                    //       if the global namespace is being deleted).
                    //
                    ICallFrame frame;

                    if (!useNamespaces || IsGlobalNamespace(@namespace))
                        frame = CurrentGlobalFrame;
                    else
                        frame = @namespace.VariableFrame;

                    if (frame != null)
                    {
                        VariableDictionary variables = frame.Variables;

                        if (variables != null)
                        {
#if NOTIFY || NOTIFY_OBJECT
                            //
                            // NOTE: *SPECIAL* This notification must be
                            //       done before the variables are marked
                            //       as "Undefined" because that is what
                            //       the ObjectTraceCallback method
                            //       expects for the BeforeVariableUnset
                            //       breakpoint type.
                            //
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.CallFrame, NotifyFlags.Deleted |
                                    NotifyFlags.Force, frame, this, null,
                                null, null, ref result);
#endif

                            bool reset = FlagOps.HasFlags(
                                flags, VariableFlags.ResetValue, true);

                            bool zero = HasZeroString() && HasZeroString(flags);

                            foreach (VariablePair pair in variables)
                            {
                                IVariable variable = pair.Value;

                                if (variable == null)
                                    continue;

                                ICallFrame scopeFrame = variable.GetFrameMark();

                                /* IGNORED */
                                variable.UnsetFrameMark();

                                /* IGNORED */
                                variable.UnsetNamespaceMark();

                                if (scopeFrame != null)
                                {
                                    /* NO RESULT */
                                    variable.ResetFrame(scopeFrame, this);

                                    //
                                    // HACK: This variable has now been
                                    //       re-parented to its original
                                    //       [scope] call frame; so, do
                                    //       not further mess with it.
                                    //
                                    continue;
                                }

                                //
                                // BUGFIX: Skip deleting any undefined,
                                //         read-only, or "invariant"
                                //         variables.
                                //
                                if (EntityOps.IsUndefined(variable) ||
                                    EntityOps.IsReadOnlyOrInvariant(variable))
                                {
                                    continue;
                                }

                                //
                                // NOTE: The variable is now dead.
                                //
                                if (reset && (variable is Variable))
                                {
                                    /* NO RESULT */
                                    ((Variable)variable).ResetValue(
                                        this, zero);
                                }

                                /* IGNORED */
                                EntityOps.SetUndefined(variable, true);

                                //
                                // NOTE: Remove any pending array searches
                                //       that may exist for this variable.
                                //
                                /* IGNORED */
                                CleanupArraySearches(variable);

                                //
                                // BUGFIX: Mark the variable as "dirty"
                                //         AFTER the actual modifications
                                //         have been completed.
                                //
                                /* IGNORED */
                                EntityOps.SignalDirty(this, variable, null);
                            }
                        }

                        //
                        // BUGFIX: The call frame is no longer usable.  Clean
                        //         it up now and mark it as undefined *unless*
                        //         it is the global call frame.  It should be
                        //         noted that native Tcl appears to use some
                        //         fundamentally different semantics here.
                        //         They leave the global frame in a state that
                        //         is completely unusable.  Since there is no
                        //         point in doing that, we do not.
                        //
                        /* IGNORED */
                        CallFrameOps.Cleanup(
                            CurrentFrame, frame, !IsGlobalCallFrame(frame));
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Remove namespace being deleted from its parent
                    //       unless its parent namespace is already deleted.
                    //
                    if (@namespace != null)
                    {
                        INamespace parentNamespace = @namespace.Parent;

                        if (parentNamespace != null)
                        {
                            ReturnCode removeCode;
                            Result removeError = null;

                            removeCode = parentNamespace.RemoveChild(
                                @namespace.Name, ref removeError);

                            if (removeCode != ReturnCode.Ok)
                                DebugOps.Complain(this, removeCode, removeError);
                        }
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Next, make sure the namespace is removed from the
                    //       pending deletion list, if applicable.  This needs
                    //       to be done prior to actually disposing the object
                    //       itself because the object disposal can fail and
                    //       even if it does, we never want to try and delete
                    //       this namespace again.
                    //
                    if ((pendingNamespaces != null) &&
                        (qualifiedName != null))
                    {
                        /* IGNORED */
                        pendingNamespaces.Remove(qualifiedName);
                    }

                    ///////////////////////////////////////////////////////////
                    //
                    // NOTE: Finally, dispose of the namespace itself.  For
                    //       the global namespace, this is not done unless
                    //       the interpreter is being disposed.
                    //
                    if ((@namespace != null) && !IsGlobalNamespace(@namespace))
                    {
                        //
                        // BUGFIX: When deleting any namespace, make sure to
                        //         remove the references to it from the call
                        //         frames.
                        //
                        ReturnCode clearCode;
                        Result clearError = null;

                        clearCode = NamespaceOps.ClearCurrentForAll(
                            this, CallStack, @namespace, ref clearError);

                        if (clearCode != ReturnCode.Ok)
                        {
                            result = String.Format(
                                "failed while clearing namespace {0}: {1}",
                                FormatOps.WrapOrNull(qualifiedName),
                                clearError);

                            return clearCode;
                        }

                        ReturnCode disposeCode;
                        Result disposeError = null;

                        disposeCode = NamespaceOps.Dispose(
                            this, ref @namespace, ref disposeError);

                        if (disposeCode != ReturnCode.Ok)
                        {
                            result = String.Format(
                                "caught exception while disposing namespace {0}: {1}",
                                FormatOps.WrapOrNull(qualifiedName), disposeError);

                            return disposeCode;
                        }
                    }
                }
                else
                {
                    //
                    // NOTE: Mark the namespace as requiring cleanup after the
                    //       current evaluation stack unwinds.
                    //
                    if (@namespace != null)
                    {
                        if ((pendingNamespaces != null) && (qualifiedName != null) &&
                            !pendingNamespaces.ContainsKey(qualifiedName)) /* EXEMPT */
                        {
                            pendingNamespaces.Add(qualifiedName, @namespace);
                        }

                        /* NO RESULT */
                        @namespace.MarkDeleted();
                    }

                    /* NO RESULT */
                    SetPendingCleanup();
                }

                /* IGNORED */
                TrackNamespaceRemoved();

                return ReturnCode.Ok;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region PendingCleanup Flag
        /// <summary>
        /// This method determines whether the specified interpreter has the
        /// pending cleanup state flag set.  It is intended for external use
        /// only.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to check, or null.
        /// </param>
        /// <returns>
        /// True if the interpreter is not null and has the pending cleanup flag
        /// set; otherwise, false.
        /// </returns>
        public static bool IsPendingCleanup( /* EXTERNAL USE ONLY. */
            Interpreter interpreter
            )
        {
            if (interpreter == null)
                return false;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                return interpreter.IsPendingCleanup();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the pending cleanup state flag is set
        /// for this interpreter.
        /// </summary>
        /// <returns>
        /// True if the pending cleanup flag is set; otherwise, false.
        /// </returns>
        private bool IsPendingCleanup()
        {
            return SetStateFlags(InterpreterStateFlags.PendingCleanup, null);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the pending cleanup state flag for this interpreter.
        /// </summary>
        private void SetPendingCleanup()
        {
            /* IGNORED */
            SetStateFlags(InterpreterStateFlags.PendingCleanup, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the pending cleanup state flag for this
        /// interpreter.
        /// </summary>
        private void UnsetPendingCleanup()
        {
            /* IGNORED */
            SetStateFlags(InterpreterStateFlags.PendingCleanup, false);
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region TraceTextWriterOwned Flag
        /// <summary>
        /// This method determines whether this interpreter owns its trace text
        /// writer and is therefore responsible for disposing it.
        /// </summary>
        /// <returns>
        /// True if the trace text writer is owned; otherwise, false.
        /// </returns>
        private bool IsTraceTextWriterOwned()
        {
            return SetStateFlags(InterpreterStateFlags.TraceTextWriterOwned, null);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the trace text writer as owned by this interpreter.
        /// </summary>
        private void SetTraceTextWriterOwned()
        {
            /* IGNORED */
            SetStateFlags(InterpreterStateFlags.TraceTextWriterOwned, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the trace text writer as not owned by this
        /// interpreter.
        /// </summary>
        private void UnsetTraceTextWriterOwned()
        {
            /* IGNORED */
            SetStateFlags(InterpreterStateFlags.TraceTextWriterOwned, false);
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region DebugTextWriterOwned Flag
        /// <summary>
        /// This method determines whether this interpreter owns its debug text
        /// writer and is therefore responsible for disposing it.
        /// </summary>
        /// <returns>
        /// True if the debug text writer is owned; otherwise, false.
        /// </returns>
        private bool IsDebugTextWriterOwned()
        {
            return SetStateFlags(InterpreterStateFlags.DebugTextWriterOwned, null);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the debug text writer as owned by this interpreter.
        /// </summary>
        private void SetDebugTextWriterOwned()
        {
            /* IGNORED */
            SetStateFlags(InterpreterStateFlags.DebugTextWriterOwned, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the debug text writer as not owned by this
        /// interpreter.
        /// </summary>
        private void UnsetDebugTextWriterOwned()
        {
            /* IGNORED */
            SetStateFlags(InterpreterStateFlags.DebugTextWriterOwned, false);
        }
        #endregion
        #endregion
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Entity Metrics
        /// <summary>
        /// This method collects usage metrics for the commands, functions,
        /// procedures, and/or operators of this interpreter, adding them to a
        /// dictionary keyed by entity kind, usage type, and name.
        /// </summary>
        /// <param name="kind">
        /// The kinds of entities to include in the usage data.
        /// </param>
        /// <param name="type">
        /// The type of usage metric to collect for each entity.
        /// </param>
        /// <param name="dictionary">
        /// The dictionary that receives the usage data; it is created when null.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetUsageData(
            IdentifierKind kind,
            UsageType type,
            ref StringDictionary dictionary,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (dictionary == null)
                    dictionary = new StringDictionary();

                ///////////////////////////////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(kind, IdentifierKind.Command, true) &&
                    (commands != null))
                {
                    foreach (CommandPair pair in commands)
                    {
                        ICommand command = pair.Value;

                        if (command == null)
                            continue;

                        long value = 0;

                        if (!command.GetUsage(type, ref value))
                            continue;

                        string key = String.Format(
                            "{0}{1}{2}{1}{3}", IdentifierKind.Command,
                            Characters.HorizontalTab, type, pair.Key);

                        dictionary[key] = value.ToString();
                    }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(kind, IdentifierKind.Function, true) &&
                    (functions != null))
                {
                    foreach (FunctionPair pair in functions)
                    {
                        IFunction function = pair.Value;

                        if (function == null)
                            continue;

                        long value = 0;

                        if (!function.GetUsage(type, ref value))
                            continue;

                        string key = String.Format(
                            "{0}{1}{2}{1}{3}", IdentifierKind.Function,
                            Characters.HorizontalTab, type, pair.Key);

                        dictionary[key] = value.ToString();
                    }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(kind, IdentifierKind.Procedure, true) &&
                    (procedures != null))
                {
                    foreach (ProcedurePair pair in procedures)
                    {
                        IProcedure procedure = pair.Value;

                        if (procedure == null)
                            continue;

                        long value = 0;

                        if (!procedure.GetUsage(type, ref value))
                            continue;

                        string key = String.Format(
                            "{0}{1}{2}{1}{3}", IdentifierKind.Procedure,
                            Characters.HorizontalTab, type, pair.Key);

                        dictionary[key] = value.ToString();
                    }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(kind, IdentifierKind.Operator, true) &&
                    (operators != null))
                {
                    foreach (OperatorPair pair in operators)
                    {
                        IOperator @operator = pair.Value;

                        if (@operator == null)
                            continue;

                        long value = 0;

                        if (!@operator.GetUsage(type, ref value))
                            continue;

                        string key = String.Format(
                            "{0}{1}{2}{1}{3}", IdentifierKind.Operator,
                            Characters.HorizontalTab, type, pair.Key);

                        dictionary[key] = value.ToString();
                    }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                return ReturnCode.Ok;
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IInterpreterManager Members
        /// <summary>
        /// This method pushes this interpreter onto the per-thread stack of
        /// active interpreters.
        /// </summary>
        /// <param name="clientData">
        /// The extra data to associate with the active interpreter entry, if
        /// any.
        /// </param>
        /// <returns>
        /// Always returns true.
        /// </returns>
        public bool PushActive(
            IClientData clientData
            )
        {
            CheckDisposed();

            /* NO RESULT */
            GlobalState.PushActiveInterpreter(this, clientData);

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks whether this interpreter is at the top of the
        /// per-thread stack of active interpreters.
        /// </summary>
        /// <returns>
        /// True if this interpreter is the active interpreter; otherwise,
        /// false.
        /// </returns>
        public bool PeekActive()
        {
            CheckDisposed();

            return GlobalState.MaybePeekActiveInterpreter(this) != null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops this interpreter off the per-thread stack of active
        /// interpreters, when it is at the top.
        /// </summary>
        /// <returns>
        /// True if this interpreter was popped; otherwise, false.
        /// </returns>
        public bool PopActive()
        {
            CheckDisposed();

            return GlobalState.MaybePopActiveInterpreter(this) != null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables or disables disposal of this interpreter, or
        /// queries the current setting.
        /// </summary>
        /// <param name="noComplain">
        /// Non-zero to skip the disposed-state check that would otherwise throw
        /// if the interpreter is already disposed.
        /// </param>
        /// <param name="enabled">
        /// Non-zero to enable disposal, zero to disable it, or null to query the
        /// current setting without changing it.
        /// </param>
        /// <returns>
        /// The resulting disposal-disabled state, or null when the interpreter
        /// is already disposed.
        /// </returns>
        public bool? SetDisposalEnabled(
            bool noComplain,
            bool? enabled
            )
        {
            if (!noComplain)
                CheckDisposed(); /* EXEMPT */

            lock (syncRoot) /* TRANSACTIONAL */
            {
                return SetDisposalEnabled(enabled);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter is an orphan (i.e. it
        /// has no parent interpreter).
        /// </summary>
        /// <returns>
        /// True if this interpreter is an orphan; otherwise, false.
        /// </returns>
        public bool IsOrphanInterpreter()
        {
            CheckDisposed();

            return InternalIsOrphanInterpreter();
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks whether the child interpreters collection is
        /// available for this interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// True if the child interpreters collection is available; otherwise,
        /// false.
        /// </returns>
        public bool HasChildInterpreters(ref Result error)
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool result = (childInterpreters != null);

                if (!result)
                    error = "child interpreters not available";

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a child interpreter with the specified
        /// path exists.
        /// </summary>
        /// <param name="path">
        /// The path identifying the child interpreter to check for.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the child interpreter exists;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode DoesChildInterpreterExist(string path)
        {
            CheckDisposed();

            return PrivateDoesChildInterpreterExist(path, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up the child interpreter identified by the
        /// specified path, optionally resolving nested paths and creating
        /// intermediate interpreters as needed.
        /// </summary>
        /// <param name="path">
        /// The path identifying the child interpreter to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the child interpreter is looked up.
        /// </param>
        /// <param name="nested">
        /// Non-zero to interpret the path as a nested path that may traverse
        /// multiple levels of child interpreters.
        /// </param>
        /// <param name="create">
        /// Non-zero to create intermediate interpreters as needed when resolving
        /// a nested path.
        /// </param>
        /// <param name="interpreter">
        /// Upon success, receives the matching child interpreter.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the matching child interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode GetChildInterpreter(
            string path,
            LookupFlags lookupFlags,
            bool nested,
            bool create,
            ref Interpreter interpreter,
            ref string name,
            ref Result error
            )
        {
            CheckDisposed();

            if (nested)
                return GetNestedChildInterpreter(path, lookupFlags, create,
                    ref interpreter, ref name, ref error);
            else
                return GetChildInterpreter(path, lookupFlags, ref interpreter,
                    ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new child interpreter at the specified path,
        /// using the supplied settings to control its creation.
        /// </summary>
        /// <param name="path">
        /// The path at which to create the child interpreter.
        /// </param>
        /// <param name="clientData">
        /// The extra data to associate with the child interpreter, if any.
        /// </param>
        /// <param name="interpreterSettings">
        /// The settings used to configure the new child interpreter.
        /// </param>
        /// <param name="isolated">
        /// Non-zero to create the child interpreter in an isolated application
        /// domain.
        /// </param>
        /// <param name="security">
        /// Non-zero to enable security (safe mode) for the new child
        /// interpreter.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the name of the new child interpreter; upon
        /// failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode CreateChildInterpreter(
            string path,
            IClientData clientData,
            IInterpreterSettings interpreterSettings,
            bool isolated,
            bool security,
            ref Result result
            )
        {
            CheckDisposed();

            if (interpreterSettings == null)
            {
                result = "invalid interpreter settings";
                return ReturnCode.Error;
            }

            return CreateChildInterpreter(
                path, clientData,
                interpreterSettings.RuleSet,
                interpreterSettings.CreateFlags,
                interpreterSettings.HostCreateFlags,
                interpreterSettings.InitializeFlags,
                interpreterSettings.ScriptFlags,
                interpreterSettings.InterpreterFlags,
                interpreterSettings.InterpreterTestFlags,
                interpreterSettings.PluginFlags,
#if NATIVE && TCL
                interpreterSettings.FindFlags,
                interpreterSettings.LoadFlags,
#endif
                isolated, security, false, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds an existing interpreter to this interpreter as a
        /// child under the specified name.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the child interpreter.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter to add as a child.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode AddChildInterpreter(
            string name,
            Interpreter interpreter,
            IClientData clientData,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (interpreter == null)
                {
                    error = "invalid interpreter";
                    return ReturnCode.Error;
                }

                if (name == null)
                {
                    error = "invalid interpreter name";
                    return ReturnCode.Error;
                }

                if (!HasChildInterpreters(ref error))
                    return ReturnCode.Error;

                if (Object.ReferenceEquals(interpreter, this))
                {
                    error = String.Format(
                        "can't add {0}: same as current interpreter",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                if (PrivateDoesChildInterpreterExist(name, false) == ReturnCode.Ok)
                {
                    error = String.Format(
                        "can't add {0}: child interpreter already exists",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                if (!CanAddChild(ref error))
                    return ReturnCode.Error;

                childInterpreters.Add(name, interpreter);

#if NOTIFY && NOTIFY_GLOBAL
                if (this.PrivateGlobalNotify)
                {
                    /* IGNORED */
                    CheckNotifications(
                        null, false,
                        NotifyType.Interpreter, NotifyFlags.Added,
                        //
                        // BUGBUG: In order to use this class for notification
                        //         parameters, it really should probably be
                        //         made public.
                        //
                        new ObjectList(name), interpreter,
                        clientData, null, null, ref error);
                }
#endif
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named child interpreter from this
        /// interpreter, using the default synchronous disposal behavior.
        /// </summary>
        /// <param name="name">
        /// The name of the child interpreter to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RemoveChildInterpreter(
            string name,
            IClientData clientData,
            ref Result error
            )
        {
            CheckDisposed();

            return RemoveChildInterpreter(
                name, clientData, ObjectOps.GetDefaultSynchronous(),
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named child interpreter from this
        /// interpreter, disposing it and any associated alias command, and
        /// optionally collecting garbage synchronously.
        /// </summary>
        /// <param name="name">
        /// The name of the child interpreter to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to collect garbage synchronously after disposing the child
        /// interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        public ReturnCode RemoveChildInterpreter(
            string name,
            IClientData clientData,
            bool synchronous,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (HasChildInterpreters(ref error))
                {
                    Interpreter interpreter = null;

                    if (GetChildInterpreter(
                            name, LookupFlags.Interpreter, ref interpreter,
                            ref error) == ReturnCode.Ok)
                    {
                        if ((interpreter != null) &&
                            !Object.ReferenceEquals(interpreter, this) &&
                            !interpreter.IsShared())
                        {
                            GlobalState.PushActiveInterpreter(this);

                            try
                            {
#if APPDOMAINS && ISOLATED_INTERPRETERS
                                string appDomainName = interpreter.ChildAppDomainName;
#endif

                                ///////////////////////////////////////////////////////////////////

                                Interpreter parentInterpreter = interpreter.ParentInterpreter;

                                if ((parentInterpreter != null) &&
                                    parentInterpreter.HasInterpreterAlias(name) == ReturnCode.Ok)
                                {
                                    Result localResult = null;

                                    if (parentInterpreter.RemoveAliasAndCommand(
                                            name, clientData, false,
                                            ref localResult) != ReturnCode.Ok)
                                    {
                                        error = localResult;
                                        return ReturnCode.Error;
                                    }
                                }

                                ///////////////////////////////////////////////////////////////////

                                if (ObjectOps.TryDispose<Interpreter>(
                                        ref interpreter, ref error) == ReturnCode.Ok)
                                {
                                    interpreter = null;

                                    if (synchronous)
                                        ObjectOps.CollectGarbage(); /* throw */
                                }
                                else
                                {
                                    return ReturnCode.Error;
                                }

                                ///////////////////////////////////////////////////////////////////

#if APPDOMAINS && ISOLATED_INTERPRETERS
                                if (appDomainName != null)
                                {
                                    ReturnCode removeCode;
                                    Result removeError = null;

                                    removeCode = RemoveAppDomain(
                                        appDomainName, clientData, ref removeError);

                                    if (removeCode == ReturnCode.Ok)
                                    {
                                        if (synchronous)
                                            ObjectOps.CollectGarbage(); /* throw */
                                    }
                                    else
                                    {
                                        //
                                        // NOTE: Not much we can do at this point.  The child
                                        //       interpreter itself was successfully disposed
                                        //       and must be removed from the collection.  The
                                        //       application domain can still be disposed during
                                        //       the disposal of this interpreter.
                                        //
                                        DebugOps.Complain(this, removeCode, removeError);
                                    }
                                }
#endif
                            }
                            catch (Exception e)
                            {
                                error = String.Format(
                                    "caught exception while disposing child interpreter: {0}",
                                    e);

                                return ReturnCode.Error;
                            }
                            finally
                            {
                                /* IGNORED */
                                GlobalState.PopActiveInterpreter();
                            }
                        }

                        childInterpreters.Remove(name);

#if NOTIFY && NOTIFY_GLOBAL
                        if (this.PrivateGlobalNotify)
                        {
                            /* IGNORED */
                            CheckNotifications(
                                null, false,
                                NotifyType.Interpreter, NotifyFlags.Removed,
                                //
                                // BUGBUG: In order to use this class for notification
                                //         parameters, it really should probably be
                                //         made public.
                                //
                                new ObjectList(name), interpreter,
                                clientData, null, null, ref error);
                        }
#endif

                        return ReturnCode.Ok;
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        //
        // WARNING: This method assumes the interpreter lock is
        //          being held -OR- that holding the interpreter
        //          lock is unnecessary (i.e. because it may be
        //          pending creation and nobody else can access
        //          it yet).
        //
        /// <summary>
        /// This method enables or disables disposal of this interpreter using a
        /// reference count, or queries the current setting.  The interpreter
        /// lock is assumed to be held, or unnecessary.
        /// </summary>
        /// <param name="enabled">
        /// Non-zero to enable disposal, zero to disable it, or null to query the
        /// current setting without changing it.
        /// </param>
        /// <returns>
        /// The resulting disposal-disabled state, or null when the interpreter
        /// is already disposed.
        /// </returns>
        private bool? SetDisposalEnabled(
            bool? enabled
            )
        {
            //
            // NOTE: If the interpreter is already disposed, there
            //       is nothing more we can do.  Return a special
            //       value to the caller to indicate this problem.
            //
            if (PrivateDisposed)
                return null;

            bool result = SetStateFlags(
                InterpreterStateFlags.NoDispose, null);

            if (enabled != null)
            {
                string wasEnabled = String.Format(
                    "still {0}", result ? "DISABLED" : "ENABLED");

                int referenceCount;
                bool wasChanged = false;

                if ((bool)enabled)
                {
                    referenceCount = Interlocked.Decrement(
                        ref disposalDisableCount);

                    if (referenceCount <= 0)
                    {
                        Interlocked.CompareExchange(
                            ref disposalDisableCount, 0,
                            referenceCount);

                        /* IGNORED */
                        SetStateFlags(
                            InterpreterStateFlags.NoDispose,
                            false);

                        wasChanged = true;
                    }

                    TraceOps.DebugTrace(String.Format(
                        "SetDisposalEnabled: ENABLE interpreter " +
                        "{0}, disposal {1} (-{2})", PrivateId,
                        wasChanged ? "now ENABLED" : wasEnabled,
                        referenceCount), typeof(Interpreter).Name,
                        TracePriority.CleanupDebug2);
                }
                else
                {
                    referenceCount = Interlocked.Increment(
                        ref disposalDisableCount);

                    if (referenceCount == 1)
                    {
                        /* IGNORED */
                        SetStateFlags(
                            InterpreterStateFlags.NoDispose,
                            true);

                        wasChanged = true;
                    }

                    TraceOps.DebugTrace(String.Format(
                        "SetDisposalEnabled: DISABLE interpreter " +
                        "{0}, disposal {1} (+{2})", PrivateId,
                        wasChanged ? "now DISABLED" : wasEnabled,
                        referenceCount), typeof(Interpreter).Name,
                        TracePriority.CleanupDebug2);
                }

                result = wasChanged ?
                    (result == (bool)enabled) : false;
            }
            else
            {
                result = !result;
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method forcibly re-enables disposal of this interpreter and
        /// clears the no-dispose flag from both the interpreter and the supplied
        /// creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The creation flags to update; the no-dispose flag is removed from
        /// them on success.
        /// </param>
        /// <returns>
        /// True if disposal was successfully re-enabled; otherwise, false.
        /// </returns>
        private bool MakeSureToDispose(
            ref CreateFlags createFlags /* in, out */
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked);

                if (locked)
                {
                    bool? result = SetDisposalEnabled(true);

                    if ((result != null) && (bool)result)
                    {
                        this.createFlags &= ~CreateFlags.NoDispose;
                        createFlags &= ~CreateFlags.NoDispose;

                        return true;
                    }
                    else
                    {
                        return false;
                    }
                }
                else
                {
                    TraceOps.LockTrace(
                        "MakeSureToDispose",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    return false;
                }
            }
            finally
            {
                InternalExitLock(ref locked);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter is an orphan (i.e. it
        /// has no parent interpreter).
        /// </summary>
        /// <returns>
        /// True if this interpreter has no parent interpreter; otherwise,
        /// false.
        /// </returns>
        internal bool InternalIsOrphanInterpreter()
        {
            return (parentInterpreter == null);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the parent interpreter of this interpreter, or null when
        /// this interpreter is an orphan.
        /// </summary>
        internal Interpreter ParentInterpreter
        {
            get { return parentInterpreter; }
            set { parentInterpreter = value; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the name by which this interpreter is known to its
        /// parent interpreter.
        /// </summary>
        internal string ChildName
        {
            get { return childName; }
            set { childName = value; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if APPDOMAINS && ISOLATED_INTERPRETERS
        /// <summary>
        /// Gets or sets the name of the application domain created to host this
        /// interpreter when it is an isolated child interpreter.
        /// </summary>
        internal string ChildAppDomainName
        {
            get { return childAppDomainName; }
            set { childAppDomainName = value; }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a snapshot copy of the child interpreters of this
        /// interpreter, acquiring the interpreter lock to do so.
        /// </summary>
        /// <returns>
        /// A new list containing the child interpreters, or null if the child
        /// interpreters collection is not available or the lock cannot be
        /// acquired.
        /// </returns>
        private IList<Interpreter> TryCopyChildInterpreters()
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (childInterpreters != null)
                    {
                        return new List<Interpreter>(
                            childInterpreters.Values);
                    }
                }

                return null;
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method produces the string form of the child interpreters of
        /// this interpreter, optionally filtered by a name pattern.
        /// </summary>
        /// <param name="pattern">
        /// An optional pattern used to match child interpreter names, or null to
        /// match all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <returns>
        /// The string form of the matching child interpreters, or null if there
        /// are none.
        /// </returns>
        internal string ChildInterpretersToString(
            string pattern,
            bool noCase
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (childInterpreters != null)
                    return childInterpreters.ToString(pattern, noCase);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified interpreter is the
        /// parent of this interpreter.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to check.
        /// </param>
        /// <returns>
        /// True if the specified interpreter is the parent of this interpreter;
        /// otherwise, false.
        /// </returns>
        private bool IsParentInterpreter(
            Interpreter interpreter
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return (interpreter != null) &&
                    Object.ReferenceEquals(interpreter, parentInterpreter);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified interpreter is a child
        /// of this interpreter.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to check.
        /// </param>
        /// <returns>
        /// True if the specified interpreter is a child of this interpreter;
        /// otherwise, false.
        /// </returns>
        private bool IsChildInterpreter(
            Interpreter interpreter
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return (interpreter != null) && (childInterpreters != null) &&
                    childInterpreters.ContainsValue(interpreter);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified value is the parent of,
        /// or a child of, this interpreter, taking care not to load assemblies
        /// for transparent proxy values.
        /// </summary>
        /// <param name="value">
        /// The value to check, which may be an interpreter or a transparent
        /// proxy.
        /// </param>
        /// <returns>
        /// True if the value is the parent of, or a child of, this interpreter;
        /// otherwise, false.
        /// </returns>
        private bool IsParentOrChildInterpreter(
            object value
            )
        {
            if (value == null)
                return false;

            //
            // BUGFIX: If this object happens to be a transparent proxy,
            //         do not try to cast it to an interpreter as that
            //         could cause an attempt to load its assembly into
            //         this AppDomain.
            //
            // BUGBUG: Perhaps this should use AppDomainOps.MaybeGetType
            //         instead here (i.e. to check if the type is really
            //         an Interpreter)?
            //
            if (AppDomainOps.IsTransparentProxy(value))
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (Object.ReferenceEquals(value, parentInterpreter))
                        return true;

                    if (childInterpreters != null)
                    {
                        foreach (InterpreterPair pair in childInterpreters)
                        {
                            Interpreter childInterpreter = pair.Value;

                            if (childInterpreter == null)
                                continue;

                            if (Object.ReferenceEquals(
                                    value, childInterpreter))
                            {
                                return true;
                            }
                        }
                    }
                }
            }
            else
            {
                Interpreter interpreter = value as Interpreter;

                if (interpreter != null)
                {
                    lock (syncRoot) /* TRANSACTIONAL */
                    {
                        if (IsParentInterpreter(interpreter))
                            return true;

                        if (IsChildInterpreter(interpreter))
                            return true;
                    }
                }
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a child interpreter identified by the
        /// specified path exists, discarding its name.
        /// </summary>
        /// <param name="path">
        /// The path identifying the child interpreter to check for.
        /// </param>
        /// <param name="nested">
        /// Non-zero to interpret the path as a nested path that may traverse
        /// multiple levels of child interpreters.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the child interpreter exists;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateDoesChildInterpreterExist(
            string path,
            bool nested
            )
        {
            string name = null;

            return InternalDoesChildInterpreterExist(path, nested, ref name);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a child interpreter identified by the
        /// specified path exists, also returning its name.
        /// </summary>
        /// <param name="path">
        /// The path identifying the child interpreter to check for.
        /// </param>
        /// <param name="nested">
        /// Non-zero to interpret the path as a nested path that may traverse
        /// multiple levels of child interpreters.
        /// </param>
        /// <param name="name">
        /// Upon success, receives the name of the matching child interpreter.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the child interpreter exists;
        /// otherwise, <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalDoesChildInterpreterExist(
            string path,
            bool nested,
            ref string name
            )
        {
            Interpreter interpreter = null;
            Result error = null;

            return GetChildInterpreter(path, LookupFlags.Exists,
                nested, false, ref interpreter, ref name, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up the child interpreter identified by the
        /// specified path, optionally resolving nested paths and creating
        /// intermediate interpreters as needed, discarding its name.
        /// </summary>
        /// <param name="path">
        /// The path identifying the child interpreter to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the child interpreter is looked up.
        /// </param>
        /// <param name="nested">
        /// Non-zero to interpret the path as a nested path that may traverse
        /// multiple levels of child interpreters.
        /// </param>
        /// <param name="create">
        /// Non-zero to create intermediate interpreters as needed when resolving
        /// a nested path.
        /// </param>
        /// <param name="interpreter">
        /// Upon success, receives the matching child interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode GetChildInterpreter(
            string path,
            LookupFlags lookupFlags,
            bool nested,
            bool create,
            ref Interpreter interpreter,
            ref Result error
            )
        {
            string name = null;

            return GetChildInterpreter(path, lookupFlags, nested, create,
                ref interpreter, ref name, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual lookup of an immediate child
        /// interpreter by name.  The empty string always refers to the current
        /// interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the child interpreter to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the child interpreter is looked up.
        /// </param>
        /// <param name="interpreter">
        /// Upon success, receives the matching child interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetChildInterpreter(
            string name,
            LookupFlags lookupFlags,
            ref Interpreter interpreter,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (HasChildInterpreters(ref error))
                {
                    //
                    // NOTE: *WARNING* Empty interpreter names are technically allowed,
                    //       please do not change this to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        if (name.Length > 0)
                        {
                            if (childInterpreters.TryGetValue(name, out interpreter))
                            {
                                if ((interpreter != null) ||
                                    !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
                                {
                                    return ReturnCode.Ok;
                                }
                                else
                                {
                                    error = FlagOps.HasFlags(
                                        lookupFlags, LookupFlags.Verbose, true) ?
                                        String.Format(
                                            "invalid interpreter name {0}",
                                            FormatOps.DisplayName(name)) :
                                        "invalid interpreter name";
                                }
                            }
                            else
                            {
                                error = FlagOps.HasFlags(
                                    lookupFlags, LookupFlags.Verbose, true) ?
                                    String.Format(
                                        "could not find interpreter {0}",
                                        FormatOps.DisplayName(name)) :
                                    "could not find interpreter";
                            }
                        }
                        else
                        {
                            //
                            // NOTE: The empty string always represents the current
                            //       interpreter.
                            //
                            interpreter = this;

                            return ReturnCode.Ok;
                        }
                    }
                    else
                    {
                        error = "invalid interpreter name";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named child interpreter from this
        /// interpreter, complaining about any error instead of returning it.
        /// </summary>
        /// <param name="name">
        /// The name of the child interpreter to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data to pass along to any notification handlers, if any.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to collect garbage synchronously after disposing the child
        /// interpreter.
        /// </param>
        private void RemoveChildInterpreterOrComplain(
            string name,
            IClientData clientData,
            bool synchronous
            )
        {
            ReturnCode code;
            Result error = null;

            code = RemoveChildInterpreter(
                name, clientData, synchronous, ref error);

            if (code != ReturnCode.Ok)
                DebugOps.Complain(this, code, error);
        }

