        #region ArgumentLocation Interpreter State Flag
#if DEBUGGER && DEBUGGER_BREAKPOINTS
        /// <summary>
        /// This method enables or disables argument location tracking for this
        /// interpreter, and optionally locks or unlocks that setting.
        /// </summary>
        /// <param name="enable">
        /// Non-zero to enable argument location tracking, zero to disable it, or
        /// null to leave the setting unchanged.
        /// </param>
        /// <param name="lock">
        /// Non-zero to lock the argument location setting, zero to unlock it, or
        /// null to leave the lock state unchanged.
        /// </param>
        internal void EnableArgumentLocation(
            bool? enable,
            bool? @lock
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (enable != null)
                {
                    /* IGNORED */
                    SetStateFlags(
                        InterpreterStateFlags.ArgumentLocation,
                        (bool)enable);
                }

                if (@lock != null)
                {
                    /* IGNORED */
                    SetStateFlags(
                        InterpreterStateFlags.ArgumentLocationLock,
                        (bool)@lock);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether argument location tracking is enabled
        /// for this interpreter.
        /// </summary>
        /// <returns>
        /// True if argument location tracking is enabled; otherwise, false.
        /// </returns>
        internal bool HasArgumentLocation()
        {
            return FlagOps.HasFlags(InterpreterStateFlagsNoLock,
                InterpreterStateFlags.ArgumentLocation, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For the core [source] command implementation and
        //       the core script library ("init.eagle") use only.
        //
        /// <summary>
        /// This method begins argument location tracking for this interpreter,
        /// enabling it (unless the setting is locked) and saving the prior state
        /// flags so they can be restored later.  It is for use by the core
        /// [source] command and the core script library only.
        /// </summary>
        /// <param name="addFlags">
        /// Additional interpreter state flags to enable, or null for none.
        /// </param>
        /// <param name="savedInterpreterStateFlags">
        /// Receives the interpreter state flags prior to this call, for later
        /// restoration.
        /// </param>
        internal void BeginArgumentLocation(
            InterpreterStateFlags? addFlags,
            out InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            InterpreterStateFlags localAddFlags = InterpreterStateFlags.None;

            if (addFlags != null)
                localAddFlags |= (InterpreterStateFlags)addFlags;

            if (!FlagOps.HasFlags(InterpreterStateFlagsNoLock,
                    InterpreterStateFlags.ArgumentLocationLock, true))
            {
                localAddFlags |= InterpreterStateFlags.ArgumentLocation;
                savedInterpreterStateFlags = ContextInterpreterStateFlags;
                ContextInterpreterStateFlags |= localAddFlags;
            }
            else
            {
                savedInterpreterStateFlags = InterpreterStateFlags.None;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For the core [source] command implementation and
        //       the core script library ("init.eagle") use only.
        //
        /// <summary>
        /// This method ends argument location tracking for this interpreter,
        /// restoring the previously saved state flags (unless the setting is
        /// locked).  It is for use by the core [source] command and the core
        /// script library only.
        /// </summary>
        /// <param name="savedInterpreterStateFlags">
        /// The interpreter state flags to restore; reset to
        /// <see cref="InterpreterStateFlags.None" /> on return.
        /// </param>
        internal void EndArgumentLocation(
            ref InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            if (!FlagOps.HasFlags(InterpreterStateFlagsNoLock,
                    InterpreterStateFlags.ArgumentLocationLock, true))
            {
                ContextInterpreterStateFlags = savedInterpreterStateFlags;
                savedInterpreterStateFlags = InterpreterStateFlags.None;
            }
        }

