        /// state flag to match the specified value, reinitializing the caches
        /// if a change was made.
        /// </summary>
        /// <param name="highPriority">
        /// Non-zero to enable high-priority mode; otherwise, zero to disable
        /// it.
        /// </param>
        /// <returns>
        /// The new high-priority value if it was changed; otherwise, null.
        /// </returns>
        private bool? MaybeMakeHighPriority(
            bool highPriority
            )
        {
            if (highPriority != HasHighPriority())
            {
                if (highPriority)
                    SetHighPriority();
                else
                    UnsetHighPriority();

                InitializeCaches(true);

                return highPriority;
            }

            return null;
        }
