        #region Private
        /// <summary>
        /// This method gets the error line number for the current thread of
        /// execution in the specified interpreter, in a thread-safe manner.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to query, which may be null.
        /// </param>
        /// <returns>
        /// The error line number, or zero if the interpreter is null or
        /// disposed.
        /// </returns>
        internal static int GetErrorLine(
            Interpreter interpreter
            )
        {
            if (interpreter == null)
                return 0;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return 0;

                return interpreter.ErrorLine; /* PER-THREAD */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the error line number for the current thread of
        /// execution in the specified interpreter, in a thread-safe manner.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to modify, which may be null.
        /// </param>
        /// <param name="errorLine">
        /// The error line number to set.
        /// </param>
        internal static void SetErrorLine(
            Interpreter interpreter,
            int errorLine
            )
        {
            if (interpreter == null)
                return;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return;

                interpreter.ErrorLine = errorLine; /* PER-THREAD */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the error-related variables (the error code and
        /// error information) for the current thread of execution, without
        /// checking for disposal.
        /// </summary>
        /// <param name="flags">
        /// The variable flags to use when resetting the error-related
        /// variables.
        /// </param>
        /// <param name="all">
        /// Non-zero to reset the error-related variables completely; otherwise,
        /// zero to simply unset them.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if any of the error-related variables
        /// could not be reset; otherwise, zero.
        /// </param>
        /// <param name="errors">
        /// Upon failure, receives any error messages encountered while
        /// resetting the error-related variables.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        private ReturnCode PrivateResetErrorInformation(
            VariableFlags flags,
            bool all,
            bool strict,
            ref ResultList errors
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (disposed)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add("interpreter is disposed");
                    return ReturnCode.Error;
                }

                //
                // NOTE: For now, only allow flags related to disabling
                //       watches, and notifications, etc.  Since these
                //       variables are now (transparently) per-thread,
                //       their traces can no longer be disabled.
                //
                flags &= VariableFlags.FastNonInstanceTraceMask;

                //
                // NOTE: Keep track of any errors encountered while
                //       unsetting the error related variables and
                //       report them to the caller, even when in
                //       non-strict mode (i.e. when we would like
                //       to return Ok).
                //
                int errorCount = 0;
                Result error; /* REUSED */

                if (all)
                {
                    error = null;

                    if (ResetThreadVariable(
                            Engine.ErrorCodeVariableFlags | flags,
                            TclVars.Core.ErrorCode,
                            ref error) != ReturnCode.Ok)
                    {
                        if (error != null)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(error);
                        }

                        errorCount++;
                    }

                    error = null;

                    if (ResetThreadVariable(
                            Engine.ErrorInfoVariableFlags | flags,
                            TclVars.Core.ErrorInfo,
                            ref error) != ReturnCode.Ok)
                    {
                        if (error != null)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(error);
                        }

                        errorCount++;
                    }
                }
                else
                {
                    error = null;

                    if (UnsetVariable2(
                            Engine.ErrorCodeVariableFlags | flags,
                            TclVars.Core.ErrorCode, null,
                            ref error) != ReturnCode.Ok)
                    {
                        if (error != null)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(error);
                        }

                        errorCount++;
                    }

                    error = null;

                    if (UnsetVariable2(
                            Engine.ErrorInfoVariableFlags | flags,
                            TclVars.Core.ErrorInfo, null,
                            ref error) != ReturnCode.Ok)
                    {
                        if (error != null)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(error);
                        }

                        errorCount++;
                    }
                }

                //
                // NOTE: In strict mode, return Error if there were any
                //       errors querying the variables; otherwise, return
                //       Ok.
                //
                return strict ?
                    (errorCount > 0 ? ReturnCode.Error : ReturnCode.Ok) :
                    ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method copies the error-related information (the error code and
        /// error information) for the current thread of execution into the
        /// specified result, without checking for disposal.
        /// </summary>
        /// <param name="flags">
        /// The variable flags to use when querying the error-related variables.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if any of the error-related variables
        /// could not be queried; otherwise, zero.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the copied error-related information; upon
        /// failure, receives an error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        internal ReturnCode InternalCopyErrorInformation(
            VariableFlags flags,
            bool strict,
            ref Result result
            )
        {
            ReturnCode code;
            Result errorCode = null;
            Result errorInfo = null;
            ResultList errors = null;

            code = InternalCopyErrorInformation(
                flags, strict, ref errorCode, ref errorInfo,
                ref errors);

            if (code == ReturnCode.Ok)
            {
                if (result == null)
                    result = String.Empty;

                result.ErrorCode = errorCode;
                result.ErrorInfo = errorInfo;
            }
            else
            {
                if (errors != null)
                    result = errors;
                else
                    result = "could not copy error information";
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method copies the error code and error information for the
        /// current thread of execution into separate results, without checking
        /// for disposal, optionally treating query failures as errors and
        /// collecting any error messages encountered.
        /// </summary>
        /// <param name="flags">
        /// The variable flags to use when querying the error-related variables.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if any of the error-related variables
        /// could not be queried; otherwise, zero.
        /// </param>
        /// <param name="errorCode">
        /// Upon success, receives the copied error code value.
        /// </param>
        /// <param name="errorInfo">
        /// Upon success, receives the copied error information value.
        /// </param>
        /// <param name="errors">
        /// Upon failure, receives any error messages encountered while querying
        /// the error-related variables.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        internal ReturnCode InternalCopyErrorInformation(
            VariableFlags flags,  /* in */
            bool strict,          /* in */
            ref Result errorCode, /* out */
            ref Result errorInfo, /* out */
            ref ResultList errors /* in, out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (disposed)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add("interpreter is disposed");
                    return ReturnCode.Error;
                }

                //
                // NOTE: For now, only allow flags related to disabling
                //       watches, and notifications, etc.  Since these
                //       variables are now (transparently) per-thread,
                //       their traces can no longer be disabled without
                //       impacting the correctness of the values.
                //
                flags &= VariableFlags.FastNonInstanceTraceMask;

                //
                // NOTE: Keep track of any errors encountered while
                //       querying the error related variables and
                //       report them to the caller, even when in
                //       non-strict mode (i.e. when we would like
                //       to return Ok).
                //
                int errorCount = 0;
                Result error; /* REUSED */

                error = null;

                if (GetVariableValue(
                        Engine.ErrorCodeVariableFlags | flags,
                        TclVars.Core.ErrorCode, ref errorCode,
                        ref error) != ReturnCode.Ok)
                {
                    if (error != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(error);
                    }

                    errorCount++;
                }

                error = null;

                if (GetVariableValue(
                        Engine.ErrorInfoVariableFlags | flags,
                        TclVars.Core.ErrorInfo, ref errorInfo,
                        ref error) != ReturnCode.Ok)
                {
                    if (error != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(error);
                    }

                    errorCount++;
                }

                //
                // NOTE: In strict mode, return Error if there were any
                //       errors querying the variables; otherwise, return
                //       Ok.
                //
                return strict ?
                    (errorCount > 0 ? ReturnCode.Error : ReturnCode.Ok) :
                    ReturnCode.Ok;
            }
        }
        #endregion
        #endregion

