        /// </summary>
        /// <param name="arguments">
        /// The argument list representing the command to add to the history.
        /// </param>
        /// <param name="historyData">
        /// The history data, supplying the level and flags for the new history
        /// item, which may be null.
        /// </param>
        /// <param name="historyFilter">
        /// The history filter, which is not currently used.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        public ReturnCode AddHistory(
            ArgumentList arguments,
            IHistoryData historyData,
            IHistoryFilter historyFilter, /* NOT USED */
            ref Result error
            )
        {
            CheckDisposed();

            int levels;
            HistoryFlags flags;

            if (historyData != null)
            {
                levels = historyData.Levels;
                flags = historyData.Flags;
            }
            else
            {
                levels = Level.Invalid;
                flags = HistoryFlags.None;
            }

            return AddHistory(arguments, levels, flags, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method loads command history for this interpreter from the
        /// specified file.
        /// </summary>
        /// <param name="encoding">
        /// The encoding to use when reading the file, or null to use the
        /// default history encoding.
        /// </param>
        /// <param name="fileName">
        /// The name of the file to read the command history from.
        /// </param>
        /// <param name="historyData">
        /// The history data, supplying the level and flags for the loaded
        /// history items, which may be null.
        /// </param>
        /// <param name="historyFilter">
        /// The history filter, which is not currently used.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if any line in the file cannot be
        /// parsed; otherwise, zero to skip unparsable lines.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        public ReturnCode LoadHistory(
            Encoding encoding,
            string fileName,
            IHistoryData historyData,
            IHistoryFilter historyFilter, /* NOT USED */
            bool strict,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (String.IsNullOrEmpty(fileName))
                {
                    error = "invalid file name";
                    return ReturnCode.Error;
                }

                if (!File.Exists(fileName))
                {
                    error = String.Format(
                        "couldn't read file {0}: no such file or directory",
                        FormatOps.WrapOrNull(fileName));

                    return ReturnCode.Error;
                }

                if (!HasHistory(ref error))
                    return ReturnCode.Error;

                try
                {
                    if (encoding == null)
                        encoding = StringOps.GetEncoding(EncodingType.History);

                    using (StreamReader streamReader = new StreamReader(
                            new FileStream(fileName, FileMode.Open,
                                FileAccess.Read), encoding)) /* EXEMPT */
                    {
                        int levels;
                        HistoryFlags flags;

                        if (historyData != null)
                        {
                            levels = historyData.Levels;
                            flags = historyData.Flags;
                        }
                        else
                        {
                            levels = Level.Invalid;
                            flags = HistoryFlags.None;
                        }

                        while (!streamReader.EndOfStream)
                        {
                            StringList list = null;
                            Result localError = null;

                            if (ParserOps<string>.SplitList(
                                    this, streamReader.ReadLine(), 0,
                                    Length.Invalid, true, ref list,
                                    ref localError) == ReturnCode.Ok)
                            {
                                IClientData clientData = new HistoryClientData(
                                    null, new ArgumentList(list, ArgumentFlags.None),
                                    levels, flags & HistoryFlags.InstanceMask);

                                _History.AddLast(clientData);
                            }
                            else if (strict)
                            {
                                error = localError;
                                return ReturnCode.Error;
                            }
                        }
                    }

                    return ReturnCode.Ok;
                }
                catch (Exception e)
                {
                    error = e;
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method saves the command history for this interpreter to the
        /// specified file.
        /// </summary>
        /// <param name="encoding">
        /// The encoding to use when writing the file, or null to use the
        /// default history encoding.
        /// </param>
        /// <param name="fileName">
        /// The name of the file to write the command history to.
        /// </param>
        /// <param name="historyData">
        /// The history data, which is not currently used.
        /// </param>
        /// <param name="historyFilter">
        /// The history filter used to select which history items are saved.
        /// </param>
        /// <param name="strict">
        /// Non-zero to return an error if any history item contains invalid
        /// data; otherwise, zero to skip invalid items.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        public ReturnCode SaveHistory(
            Encoding encoding,
            string fileName,
            IHistoryData historyData, /* NOT USED */
            IHistoryFilter historyFilter,
            bool strict,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (String.IsNullOrEmpty(fileName))
                {
                    error = "invalid file name";
                    return ReturnCode.Error;
                }

                if (!HasHistory(ref error))
                    return ReturnCode.Error;

                try
                {
                    if (encoding == null)
                        encoding = StringOps.GetEncoding(EncodingType.History);

                    using (StreamWriter streamWriter = new StreamWriter(
                            new FileStream(fileName, FileMode.Create,
                                FileAccess.Write), encoding)) /* EXEMPT */
                    {
                        foreach (IClientData clientData in _History)
                        {
                            HistoryClientData historyClientData =
                                clientData as HistoryClientData;

                            if (historyClientData != null)
                            {
                                if (HistoryOps.MatchData(
                                        historyClientData, historyFilter))
                                {
                                    ArgumentList arguments =
                                        historyClientData.Arguments;

                                    if (arguments != null)
                                        streamWriter.WriteLine(
                                            arguments.ToString());
                                }
                            }
                            else if (strict)
                            {
                                error = "invalid history data";
                                return ReturnCode.Error;
                            }
                        }
                    }

                    return ReturnCode.Ok;
                }
                catch (Exception e)
                {
                    error = e;
                }
            }

            return ReturnCode.Error;
        }

