        /// <summary>
        /// This method sets or clears the lock that prevents command history
        /// modification for this interpreter.
        /// </summary>
        /// <param name="historyLocked">
        /// Non-zero to lock command history modification; otherwise, zero to
        /// unlock it.
        /// </param>
        private void SetHistoryLocked(
            bool historyLocked
            )
        {
            if (historyLocked)
                interpreterFlags |= InterpreterFlags.LockHistory;
            else
                interpreterFlags &= ~InterpreterFlags.LockHistory;
        }

