        /// <summary>
        /// This method adds the specified command (argument list) to the
        /// command history maintained by this interpreter.
        /// </summary>
        /// <param name="arguments">
        /// The argument list representing the command to add to the history.
        /// </param>
        /// <param name="levels">
        /// The evaluation level associated with the new history item.
        /// </param>
        /// <param name="flags">
        /// The history flags associated with the new history item.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        internal ReturnCode AddHistory(
            ArgumentList arguments,
            int levels,
            HistoryFlags flags
            )
        {
            Result error = null;

            return AddHistory(arguments, levels, flags, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified command (argument list) to the
        /// command history maintained by this interpreter, enforcing the
        /// configured history limit.
        /// </summary>
        /// <param name="arguments">
        /// The argument list representing the command to add to the history.
        /// </param>
        /// <param name="levels">
        /// The evaluation level associated with the new history item.
        /// </param>
        /// <param name="flags">
        /// The history flags associated with the new history item.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        internal ReturnCode AddHistory(
            ArgumentList arguments,
            int levels,
            HistoryFlags flags,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref error))
                    return ReturnCode.Error;

                if (arguments == null)
                {
                    error = "invalid argument list";
                    return ReturnCode.Error;
                }

                if (!HasHistory(ref error))
                    return ReturnCode.Error;

                //
                // NOTE: Add the arguments to the history of executed commands.
                //
                IClientData clientData =
                    new HistoryClientData(null, arguments, levels, flags);

                _History.AddFirst(clientData);

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.History, NotifyFlags.Added,
                    clientData, this,
                    null, null, null, ref error);
#endif

                //
                // NOTE: Prevent the number of history items from exceeding the
                //       limit (unless the limit is -1).
                //
                int limit = historyLimit;

                if (limit >= 0)
                {
                    //
                    // NOTE: If the limit is zero, use the default limit.
                    //
                    if (limit == Limits.Unlimited)
                        limit = DefaultHistoryLimit;

                    while (_History.Count > limit)
                    {
                        //
                        // NOTE: Remove old argument lists in FIFO style.
                        //
                        LinkedListNode<IClientData> last = _History.Last;

                        if (last == null)
                            break;

                        clientData = last.Value;
                        _History.RemoveLast();

#if NOTIFY
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.History, NotifyFlags.Removed,
                            clientData, this,
                            null, null, null, ref error);
#endif
                    }
                }
            }

            return ReturnCode.Ok;
        }
        #endregion
#endif
        #endregion

