        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the interactive host for this interpreter and
        /// verifies that it is currently open.
        /// </summary>
        /// <param name="interactiveHost">
        /// Upon return, receives the interactive host, or null if none is
        /// available.
        /// </param>
        /// <returns>
        /// True if an open interactive host was obtained; otherwise, false.
        /// </returns>
        private bool GetAndCheckInteractiveHost(
            ref IInteractiveHost interactiveHost /* in, out */
            )
        {
            interactiveHost = GetInteractiveHost();

            if (interactiveHost == null)
                return false;

            HostFlags hostFlags = HostOps.GetHostFlags(
                interactiveHost); /* OUTPUT NOT USED */

            return HostOps.IsOpen(this, null,
                ref hostFlags, ref interactiveHost);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the interactive host associated with this
        /// interpreter.
        /// </summary>
        /// <returns>
        /// The interactive host, or null if none is available.
        /// </returns>
        internal IInteractiveHost GetInteractiveHost()
        {
            return GetInteractiveHost(null) as IInteractiveHost;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: First, check the PrivateInteractiveHost property, in case
        //       there is a special host setup for use by the interactive
        //       loop.  Then, if necessary, fallback to the InternalHost
        //       property.  This method should only be called by the code
        //       within the interactive loop subsystem -OR- code that is
        //       intended to interact directly with the user.  The lock is
        //       used to prevent internal race conditions; however, since
        //       this method is used from within the tracing subsystem, it
        //       must make use of the TryLock pattern to avoid deadlocks.
        //
        /// <summary>
        /// This method gets the interactive host associated with this
        /// interpreter, optionally restricting it to a particular type.  It
        /// prefers any special interactive host before falling back to the
        /// primary host, and uses a non-blocking lock to avoid deadlocks.
        /// </summary>
        /// <param name="type">
        /// The required host type (an interface or class), or null to accept
        /// any host type.
        /// </param>
        /// <returns>
        /// The interactive host matching the requested type, or null if none is
        /// available.
        /// </returns>
        internal object GetInteractiveHost(
            Type type /* IHost, one of its derived types, or null. */
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (disposed)
                        return null;

                    IInteractiveHost interactiveHost = PrivateInteractiveHost; /* PROPERTY */

                    if (interactiveHost != null)
                    {
                        //
                        // NOTE: If the caller does not care about the type -OR-
                        //       it is a proxy, just return it.
                        //
                        if (type == null)
                        {
                            TraceOps.DebugTrace(
                                "GetInteractiveHost: interactive host, no type",
                                typeof(Interpreter).Name, TracePriority.HostDebug);

                            return interactiveHost;
                        }

                        //
                        // NOTE: Grab the type of the interactive host and check
                        //       it against the requested interface type.
                        //
                        Type localType = AppDomainOps.MaybeGetTypeOrNull(
                            interactiveHost);

                        if (type.IsInterface)
                        {
                            if (RuntimeOps.DoesClassTypeSupportInterface(
                                    localType, type))
                            {
                                TraceOps.DebugTrace(String.Format(
                                    "GetInteractiveHost: interactive host, interface {0}",
                                    FormatOps.TypeName(type)), typeof(Interpreter).Name,
                                    TracePriority.HostDebug);

                                return interactiveHost;
                            }
                        }
                        else
                        {
                            if (RuntimeOps.IsClassTypeEqualOrSubClass(
                                    localType, type, true))
                            {
                                TraceOps.DebugTrace(String.Format(
                                    "GetInteractiveHost: interactive host, class {0}",
                                    FormatOps.TypeName(type)), typeof(Interpreter).Name,
                                    TracePriority.HostDebug);

                                return interactiveHost;
                            }
                        }
                    }

#if DEBUG && VERBOSE
                    //
                    // NOTE: IHost inherits from all interface types supported
                    //       by this method, so just return it.
                    //
                    TraceOps.DebugTrace(String.Format(
                        "GetInteractiveHost: fallback to normal host, type {0}",
                        FormatOps.TypeName(type)), typeof(Interpreter).Name,
                        TracePriority.HostDebug);
#endif

                    return InternalHost; /* PROPERTY */
                }
                else
                {
                    TraceOps.LockTrace(
                        "GetInteractiveHost",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    return null;
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally updates the script-level "tcl_interactive"
        /// library variable to reflect the specified interactive state, when
        /// called on the primary system thread.
        /// </summary>
        /// <param name="value">
        /// The interactive state to store in the script-level variable.
        /// </param>
        private void MaybeSetInteractiveVariableValue(
            bool value /* in */
            )
        {
            if (IsPrimarySystemThread())
            {
                VariableFlags flags = VariableFlags.ViaProperty;

                //
                // NOTE: Do not create the variable if we have been
                //       prohibited from doing so.  This variable *IS*
                //       allowed in "safe" interpreters, based on what
                //       native Tcl allows.
                //
                if (PrivateIsNoVariables())
                    flags |= VariableFlags.NoCreate;

                //
                // NOTE: Update script-level informational variable.
                //
                SetLibraryVariableValue(
                    flags, TclVars.Core.Interactive, value.ToString());
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // HACK: *SPECIAL* This property merits special attention,
        //       at least for those interested in the interactive
        //       loop code.  This property will only be non-zero
        //       if the interactive user has actually entered the
        //       interactive loop on a given thread.  Also, this
        //       is a logically distinct concern from whether or
        //       not standard input has been redirected.  This is
        //       tied into the "tcl_interactive" script library.
        //
        /// <summary>
        /// Gets or sets a value indicating whether the current thread of
        /// execution is running inside the interactive loop.  Setting this
        /// property also updates the script-level "tcl_interactive" library
        /// variable.
        /// </summary>
        internal bool InternalInteractive
        {
            get
            {
#if THREADING
                IInteractiveContext context = GetInteractiveContext();

                if (context != null)
                    return context.Interactive;
                else
                    return false;
#else
                lock (syncRoot)
                {
                    return interactive;
                }
#endif
            }
            set
            {
#if THREADING
                IInteractiveContext context = GetInteractiveContext();

                if (context != null)
                    context.Interactive = value;
#else
                lock (syncRoot)
                {
                    interactive = value;
                }
#endif

                MaybeSetInteractiveVariableValue(value);
            }
        }

