        /// <summary>
        /// Gets or sets the script evaluation level recorded when the
        /// interactive loop was entered on the current thread of execution.
        /// </summary>
        internal int InteractiveScriptLevels
        {
            get
            {
#if THREADING
                IInteractiveContext context = GetInteractiveContext();

                if (context != null)
                    return context.InteractiveScriptLevels;
                else
                    return 0;
#else
                lock (syncRoot)
                {
                    return interactiveScriptLevels;
                }
#endif
            }
            set
            {
#if THREADING
                IInteractiveContext context = GetInteractiveContext();

                if (context != null)
                    context.InteractiveScriptLevels = value;
#else
                lock (syncRoot)
                {
                    interactiveScriptLevels = value;
                }
#endif
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records the current script evaluation level as the
        /// interactive script level, saving the previous value for later
        /// restoration.
        /// </summary>
        /// <param name="savedInteractiveScriptLevels">
        /// Receives the prior interactive script level, for later restoration.
        /// </param>
        private void BeginInteractiveScriptLevels(
            out int? savedInteractiveScriptLevels /* out */
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                savedInteractiveScriptLevels = InteractiveScriptLevels;
                InteractiveScriptLevels = ScriptLevels;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the interactive script level from a previously
        /// saved value.
        /// </summary>
        /// <param name="savedInteractiveScriptLevels">
        /// The interactive script level to restore; reset to null on return.
        /// </param>
        private void EndInteractiveScriptLevels(
            ref int? savedInteractiveScriptLevels /* in, out */
            )
        {
            if (savedInteractiveScriptLevels != null)
            {
#if !THREADING
                lock (syncRoot) /* TRANSACTIONAL */
#endif
                {
                    InteractiveScriptLevels = (int)savedInteractiveScriptLevels;
                    savedInteractiveScriptLevels = null;
                }
            }
        }

