        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether interactive input is currently
        /// enabled, resolving the automatic setting based on the contents of
        /// the interactive input buffer.
        /// </summary>
        /// <returns>
        /// True if interactive input is enabled; otherwise, false.
        /// </returns>
        internal bool IsInteractiveInputEnabled()
        {
            int retries = 0;

        retry:

            MaybeEnableType enabled = InteractiveInputEnabled;

            switch (enabled)
            {
                case MaybeEnableType.False:
                    {
                        return false;
                    }
                case MaybeEnableType.True:
                    {
                        return true;
                    }
                case MaybeEnableType.Automatic:
                    {
                        StringBuilder builder = InteractiveInputBuffer;

                        if (builder != null)
                        {
                            if (SharedStringOps.SystemEquals(
                                    builder.ToString(), BufferDone))
                            {
                                if (retries == 0)
                                {
                                    EnableInteractiveInput();

                                    retries++;
                                    goto retry;
                                }
                                else
                                {
                                    return true;
                                }
                            }
                            else
                            {
                                return false;
                            }
                        }
                        else
                        {
                            return true;
                        }
                    }
                default:
                    {
                        //
                        // HACK: This is a fail-safe just in case the
                        //       value ends up being something that is
                        //       unrecognized by this method.
                        //
                        return true;
                    }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables interactive input for the current thread of
        /// execution.
        /// </summary>
        private void EnableInteractiveInput()
        {
            InteractiveInputEnabled = MaybeEnableType.True;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if SHELL
        /// <summary>
        /// This method increments the process-wide count of active interactive
        /// loops.
        /// </summary>
        /// <returns>
        /// The new global interactive loop level.
        /// </returns>
        private int PushGlobalInteractiveLoopLevel()
        {
            return Interlocked.Increment(ref globalInteractiveLoops);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method decrements the process-wide count of active interactive
        /// loops.
        /// </summary>
        /// <returns>
        /// The new global interactive loop level.
        /// </returns>
        private int PopGlobalInteractiveLoopLevel()
        {
            return Interlocked.Decrement(ref globalInteractiveLoops);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enters a new (nested) instance of the interactive loop
        /// on the current thread, marking the interpreter as interactive,
        /// enabling interactive input, updating the loop tracking counts, and
        /// saving the prior state for later restoration.
        /// </summary>
        /// <param name="loopData">
        /// The interactive loop data for the loop being entered.
        /// </param>
        /// <param name="saveThread">
        /// Non-zero to save and replace the interactive thread with the current
        /// thread; otherwise, zero.
        /// </param>
        /// <param name="savedInteractiveThread">
        /// Receives the prior interactive thread, for later restoration.
        /// </param>
        /// <param name="savedInteractive">
        /// Receives the prior interactive flag, for later restoration.
        /// </param>
        /// <param name="savedLoopData">
        /// Receives the prior interactive loop data, for later restoration.
        /// </param>
        private void PushLocalInteractiveLoopLevel(
            IInteractiveLoopData loopData,         /* in */
            bool saveThread,                       /* in */
            out Thread savedInteractiveThread,     /* out */
            out bool savedInteractive,             /* out */
            out IInteractiveLoopData savedLoopData /* out */
            )
        {
            //
            // NOTE: The thread for the interactive user is this one.  This
            //       can only be done in the primary application domain for
            //       the interpreter.
            //
            savedInteractiveThread = null;

            if (saveThread)
            {
                savedInteractiveThread = InteractiveThread;
                PrivateInteractiveThread = Thread.CurrentThread;
            }

            //
            // NOTE: Save the interactive "active" flag for this thread and
            //       then force it enabled because this is an interactive
            //       loop and absolutely requires user input; therefore, we
            //       are in interactive mode.
            //
            savedInteractive = InternalInteractive;
            InternalInteractive = true;

            //
            // NOTE: Start out with the interactive loop enabled; this means
            //       that interactive input will be evaluated, not buffered.
            //
            EnableInteractiveInput();

            //
            // NOTE: We are entering an[other] instance of the interactive
            //       loop; therefore, increase our tracking counts.
            //
            ActiveInteractiveLoops++; /* THREAD-SAFE */
            TotalInteractiveLoops++; /* THREAD-SAFE */

            //
            // NOTE: Save previous interactive loop data instance and then
            //       reset it to the (new?) one specified by the caller.
            //
            savedLoopData = InteractiveLoopData; /* THREAD-SAFE */
            InteractiveLoopData = loopData; /* THREAD-SAFE */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method exits the current (nested) instance of the interactive
        /// loop on the current thread, restoring the previously saved
        /// interactive state and updating the loop tracking counts.
        /// </summary>
        /// <param name="restoreThread">
        /// Non-zero to restore the previously saved interactive thread;
        /// otherwise, zero.
        /// </param>
        /// <param name="savedInteractiveThread">
        /// The interactive thread to restore; reset to null on return.
        /// </param>
        /// <param name="savedInteractive">
        /// The interactive flag to restore; reset to false on return.
        /// </param>
        /// <param name="savedLoopData">
        /// The interactive loop data to restore; reset to null on return.
        /// </param>
        private void PopLocalInteractiveLoopLevel(
            bool restoreThread,                    /* in */
            ref Thread savedInteractiveThread,     /* in, out */
            ref bool savedInteractive,             /* in, out */
            ref IInteractiveLoopData savedLoopData /* in, out */
            )
        {
            //
            // BUGFIX: There is no need to restore the interactive loop
            //         level if the interpreter has been disposed.
            //
            if (!disposed)
            {
                //
                // NOTE: Restore interactive loop data property to its
                //       previous value here.  This property is not used
                //       by the core library itself; however, others may
                //       rely on its correctly restored value.
                //
                InteractiveLoopData = savedLoopData;

                //
                // NOTE: We are exiting this instance of the interactive
                //       loop; therefore, decrease our tracking count.
                //
                ActiveInteractiveLoops--; /* THREAD-SAFE */

                //
                // BUGFIX: Restore interactive flag property to previous
                //         value here, do not simply set it to false.
                //
                InternalInteractive = savedInteractive;

                //
                // BUGFIX: Restore interactive thread property to its
                //         previous value here, do not simply set it to
                //         null.  This can only be done in the primary
                //         application domain for the interpreter.
                //
                if (restoreThread)
                    PrivateInteractiveThread = savedInteractiveThread;
            }

            savedLoopData = null;
            savedInteractive = false;
            savedInteractiveThread = null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether interactive read-line support has
        /// been disabled in the specified interpreter, in a thread-safe manner.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to query, which may be null.
        /// </param>
        /// <param name="default">
        /// The value to return if the interpreter is null or disposed.
        /// </param>
        /// <returns>
        /// True if read-line support is disabled; otherwise, false.  The
        /// specified default value is returned when the interpreter is null or
        /// disposed.
        /// </returns>
        private static bool IsReadLineDisabled(
            Interpreter interpreter,
            bool @default
            )
        {
            if (interpreter == null)
                return @default;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return @default;

                return FlagOps.HasFlags(
                    interpreter.InterpreterStateFlagsNoLock,
                    InterpreterStateFlags.ReadLineDisabled,
                    true);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the current interactive input text in the specified
        /// interpreter, in a thread-safe manner.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to modify, which may be null.
        /// </param>
        /// <param name="interactiveInput">
        /// The interactive input text to set.
        /// </param>
        private static void SetInteractiveInput(
            Interpreter interpreter,
            string interactiveInput
            )
        {
            if (interpreter == null)
                return;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return;

                interpreter.InteractiveInput = interactiveInput;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the interactive command callback
        /// should be invoked for the specified text, stripping any verbatim
        /// command prefix from the text when the callback should be bypassed.
        /// </summary>
        /// <param name="text">
        /// The interactive command text; upon return, any verbatim command
        /// prefix has been removed.
        /// </param>
        /// <returns>
        /// True if the interactive command callback should be invoked;
        /// otherwise, false.
        /// </returns>
        private static bool ShouldInteractiveCommandCallback(
            ref string text /* in, out */
            )
        {
            if (String.IsNullOrEmpty(text))
                return true;

            string newPrefix = null;
            int nextIndex = Index.Invalid;

            if (!ShellOps.LooksLikeInteractiveVerbatimCommand(
                    text, ref newPrefix, ref nextIndex))
            {
                return true;
            }

            if (nextIndex != Index.Invalid)
            {
                if (newPrefix != null)
                    text = newPrefix + text.Substring(nextIndex);
                else
                    text = text.Substring(nextIndex);
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes (unhooks) the interactive command callback from
        /// the specified interpreter, typically in response to an exception
        /// raised by the callback, and attempts to notify the host.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose interactive command callback should be
        /// removed, which may be null.
        /// </param>
        private static void RemoveInteractiveCommandCallback(
            Interpreter interpreter /* in */
            )
        {
            //
            // NOTE: If there is no interpreter context, do nothing.
            //
            if (interpreter == null)
                return;

            //
            // HACK: If the callback raises an exception, maybe it is
            //       no longer usable?  For now, we always treat this
            //       as an opportunity to unhook it.
            //
            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (!interpreter.PrivateDisposed)
                    interpreter.InteractiveCommandCallback = null;
            }

            //
            // NOTE: If possible, attempt to emit a message to the
            //       interpreter host showing that the interactive
            //       command callback is now dead.
            //
            try
            {
                IDebugHost debugHost = interpreter.InternalHost;

                if (debugHost != null)
                {
                    debugHost.WriteResult(
                        ReturnCode.Exception, "Interactive command " +
                        "callback removed due to exception.", true);
                }
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.HostError);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the interactive command callback from the specified
        /// interpreter, in a thread-safe manner, removing it if querying it
        /// raises an exception.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to query, which may be null.
        /// </param>
        /// <param name="callback">
        /// Upon return, receives the interactive command callback, or null if
        /// none is set.
        /// </param>
        private static void GetInteractiveCommandCallback(
            Interpreter interpreter,             /* in */
            ref StringTransformCallback callback /* out */
            )
        {
            if (interpreter != null)
            {
                lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
                {
                    if (interpreter.PrivateDisposed)
                        return;

                    try
                    {
                        callback = interpreter.InteractiveCommandCallback; /* throw */
                    }
                    catch (Exception e)
                    {
                        TraceOps.DebugTrace(
                            e, typeof(Interpreter).Name,
                            TracePriority.CallbackError);

                        RemoveInteractiveCommandCallback(interpreter);
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally invokes the interactive command callback
        /// for the specified interpreter to transform the interactive command
        /// text, disabling the debugger and argument caching for the duration
        /// of the callback and removing the callback if it raises an unexpected
        /// exception.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose interactive command callback should be
        /// invoked, which may be null.
        /// </param>
        /// <param name="debug">
        /// Non-zero if the interactive loop is operating in debug mode, in
        /// which case the callback is skipped.
        /// </param>
        /// <param name="text">
        /// The interactive command text; upon return, contains the transformed
        /// text produced by the callback.
        /// </param>
        private static void MaybeInteractiveCommandCallback(
            Interpreter interpreter, /* in */
            bool debug,              /* in */
            ref string text          /* in, out */
            )
        {
            if (interpreter == null)
                return;

            StringTransformCallback callback = null;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return;

                if (!ScriptOps.HasFlags(interpreter,
                        InterpreterFlags.AllowProxyCallback, true) &&
                    AppDomainOps.IsTransparentProxy(interpreter))
                {
                    return;
                }

#if DEBUGGER
                if (debug || interpreter.PrivateHaveDebuggerLoops())
                    return;
#endif

                GetInteractiveCommandCallback(interpreter, ref callback);
            }

            if (callback == null)
                return;

#if DEBUGGER
            //
            // BUGFIX: The interactive command callback may decide to evaluate
            //         a script (or it may be a dynamic delegate); therefore,
            //         disable breakpoints for the duration of its execution.
            //         This avoids some undesirable interactions between the
            //         interactive command callback, the script debugger, and
            //         the interactive loop.
            //
            EngineFlags savedEngineFlags;

            interpreter.BeginNoDebugger(out savedEngineFlags);

            try
            {
#endif
#if ARGUMENT_CACHE
                CacheFlags savedCacheFlags;
                interpreter.BeginNoArgumentCache(out savedCacheFlags);

                try
                {
#endif
                    try
                    {
                        text = callback(text); /* throw */
                    }
                    catch (ScriptException e)
                    {
                        //
                        // HACK: If the thrown "exception" was caused by the
                        //       interactive user simply hitting the Ctrl-C,
                        //       etc, e.g. in order to perform interactive
                        //       script cancellation, then the interactive
                        //       command callback should not be removed.
                        //
                        TraceOps.DebugTrace(
                            e, typeof(Interpreter).Name,
                            TracePriority.CallbackError);

                        if ((e == null) ||
                            (e.ReturnCode != ReturnCode.Error) ||
                            !SharedStringOps.SystemEquals(
                                e.Message, demandCancelResultFormat))
                        {
                            RemoveInteractiveCommandCallback(interpreter);
                        }
                    }
                    catch (Exception e)
                    {
                        TraceOps.DebugTrace(
                            e, typeof(Interpreter).Name,
                            TracePriority.CallbackError);

                        RemoveInteractiveCommandCallback(interpreter);
                    }
#if ARGUMENT_CACHE
                }
                finally
                {
                    interpreter.EndNoArgumentCache(ref savedCacheFlags);
                }
#endif
#if DEBUGGER
            }
            finally
            {
                interpreter.EndNoDebugger(ref savedEngineFlags);
            }
#endif
        }
#endif
        #endregion
        #endregion

