        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks for a commercial license associated with this
        /// interpreter, validating the security certificate and extracting its
        /// unique identifier.
        /// </summary>
        /// <param name="name">
        /// The name of the commercial license to look for.
        /// </param>
        /// <param name="id">
        /// Upon success, receives the unique identifier from the commercial
        /// license; otherwise, null.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message.
        /// </param>
        /// <returns>
        /// True if a valid commercial license was found; otherwise, false.
        /// </returns>
        public bool LookForCommercialLicense(
            string name,
            out Guid? id,
            ref Result error
            )
        {
            CheckDisposed();

            id = null;

            Result result = null;

            if (ScriptOps.CheckSecurityCertificate(
                    this, true, ref result) != ReturnCode.Ok)
            {
                error = result;
                return false;
            }

            StringDictionary dictionary = StringDictionary.FromString(
                result, true, false, ref error);

            if (dictionary == null)
                return false;

            string value;

            if (!dictionary.TryGetValue(DataNames.Id, out value))
            {
                error = String.Format(
                    "missing {0} data value from license",
                    FormatOps.WrapOrNull(DataNames.Id));

                return false;
            }

            Guid localId = Guid.Empty;

            if (Value.GetGuid(
                    value, InternalCultureInfo, ref localId,
                    ref error) != ReturnCode.Ok)
            {
                return false;
            }

            id = localId;
            return true;
        }

