        /// <summary>
        /// This method determines whether the specified token matches the token
        /// assigned to this interpreter.
        /// </summary>
        /// <param name="token">
        /// The token to compare against the interpreter token, which may be
        /// null.
        /// </param>
        /// <returns>
        /// True if the tokens match, including when both are null; otherwise,
        /// false.
        /// </returns>
        public bool MatchToken(
            ulong? token
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if ((token == null) || (this.token == null))
                    return (token == null) && (this.token == null);

                return (ulong)token == (ulong)this.token;
            }
        }

