        /// <summary>
        /// Gets the UTC time at which this interpreter was last accessed, or
        /// null if it has never been accessed, without throwing an exception if
        /// it has been disposed.
        /// </summary>
        public DateTime? LastAccessedNoThrow
        {
            get
            {
                //
                // NOTE: This method may NOT throw exceptions.
                //
                /* CheckDisposed(); */

                long ticks = Interlocked.CompareExchange(
                    ref accessedTicks, 0, 0);

                if (ticks != _Ticks.Invalid)
                {
                    DateTime? then = FormatOps.UtcOrNull(ticks);

                    if (then != null)
                        return (DateTime)then;
                }

                return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter was last accessed
        /// within the specified number of seconds.
        /// </summary>
        /// <param name="maximumSeconds">
        /// The maximum number of seconds since the last access.
        /// </param>
        /// <returns>
        /// True if the interpreter was accessed within the specified number of
        /// seconds; otherwise, false.
        /// </returns>
        public bool CheckLastAccessed(
            long maximumSeconds /* in */
            )
        {
            CheckDisposed();

            long ticks = Interlocked.CompareExchange(
                ref accessedTicks, 0, 0);

            if (ticks == _Ticks.Invalid) // NOTE: Never?
                return false;

            DateTime? then = FormatOps.UtcOrNull(ticks);

            if (then == null)
                return false;

            DateTime now = TimeOps.GetUtcNow();

            if (now < (DateTime)then) // NOTE: Time travel?
                return false;

            //
            // NOTE: Truncates towards zero, which is fine for
            //       the purposes of this method.
            //
            return Convert.ToInt64(now.Subtract(
                (DateTime)then).TotalSeconds) <= maximumSeconds;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method updates the last-accessed time of this interpreter to
        /// the current time.
        /// </summary>
        public void UpdateLastAccessed()
        {
            CheckDisposed();

            Interlocked.Exchange(
                ref accessedTicks, TimeOps.GetUtcNowTicks());
        }

