        /// <summary>
        /// This method formats the identifier of the application domain
        /// associated with this interpreter, for display or diagnostic
        /// purposes.
        /// </summary>
        /// <param name="display">
        /// Non-zero to format the identifier for display to the user;
        /// otherwise, zero.
        /// </param>
        /// <returns>
        /// The formatted application domain identifier, or null if it is not
        /// available.
        /// </returns>
        public string FormatAppDomainId(
            bool display
            )
        {
            // CheckDisposed(); /* EXEMPT */

            bool locked = false;

            try
            {
                InternalSoftTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    return AppDomainOps.FormatIdString(
                        appDomain, disposed, display);
                }
                else
                {
                    TraceOps.LockTrace(
                        "FormatAppDomainId",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockWarning2,
                        MaybeWhoHasLock());
                }

                return display ? AppDomainOps.FormatAppDomain(
                    FormatOps.DisplayBusy) : null;
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

