        ///////////////////////////////////////////////////////////////////////////////////////////////

#if NETWORK && OFFICIAL_BINARY && !ENTERPRISE_LOCKDOWN
        /// <summary>
        /// This method determines whether this interpreter should be
        /// initialized using content obtained from a trusted remote URI.
        /// </summary>
        /// <param name="initializeFlags">
        /// The flags that control how the interpreter is being initialized.
        /// </param>
        /// <returns>
        /// True if initialization via a trusted remote URI should be
        /// performed; otherwise, false.
        /// </returns>
        private bool ShouldInitializeViaTrustedRemoteUri(
            InitializeFlags initializeFlags /* in */
            )
        {
#if MAYBE_ENTERPRISE_LOCKDOWN
            //
            // NOTE: *SECURITY* Since trusted remote URI
            //       content is not under the control of
            //       the enterprise customer, it must be
            //       disallowed when lockdown is enabled.
            //
            if (IsEnterpriseLockdownEnabled())
                return false;
#endif

            if (FlagOps.HasFlags(initializeFlags,
                    InitializeFlags.NoTrustedRemote, true))
            {
                return false;
            }

            if (GlobalConfiguration.DoesValueExist(
                    EnvVars.NoTrustedRemote,
                    ConfigurationFlags.Interpreter))
            {
                return false;
            }

            if (PrivateIsRestricted()) /* Harpy SDK? */
                return false;

            if (HasToken()) /* Harpy Configuration? */
                return false;

            if (GlobalConfiguration.DoesValueExist(
                    EnvVars.ForceTrustedRemote,
                    ConfigurationFlags.Interpreter))
            {
                return true;
            }

            if (FlagOps.HasFlags(initializeFlags,
                    InitializeFlags.TrustedRemote, true))
            {
                return true;
            }

            return false;
        }
#endif

