        /// interpreter by copying the group identifier.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to place into a group.
        /// </param>
        /// <param name="groupInterpreter">
        /// The interpreter whose group identifier will be used.
        /// </param>
        internal static void PutInGroup(
            Interpreter interpreter,
            Interpreter groupInterpreter
            )
        {
            if ((interpreter == null) || (groupInterpreter == null))
                return;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                interpreter.PrivateGroupId = groupInterpreter.PrivateId;
            }
        }

