        internal long NativeThreadId
        {
            get
            {
                // CheckDisposed();

                /* NO-LOCK */
                return Interlocked.CompareExchange(ref nativeThreadId, 0, 0);
            }
            private set
            {
                // CheckDisposed();

                //
                // NOTE: This property "setter" is only supposed to be used during
                //       interpreter initialization.
                //
                /* NO-LOCK */
                Interlocked.Exchange(ref nativeThreadId, value);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the calling thread is the primary
        /// system thread that owns this interpreter.
        /// </summary>
        /// <returns>
        /// True if the current system thread is the primary system thread;
        /// otherwise, false.
        /// </returns>
        internal bool IsPrimarySystemThread()
        {
            return IsPrimarySystemThread(GlobalState.GetCurrentSystemThreadId());
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified thread identifier
        /// refers to the primary system thread that owns this interpreter.
        /// </summary>
        /// <param name="threadId">
        /// The system thread identifier to check.
        /// </param>
        /// <returns>
        /// True if the specified thread identifier is the primary system
        /// thread; otherwise, false.
        /// </returns>
        private bool IsPrimarySystemThread(long threadId)
        {
            return (threadId == Interlocked.CompareExchange(
                ref this.threadId, 0, 0));
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a plugin may be loaded on the
        /// calling thread, taking into account the plugin flags, environment
        /// configuration, and whether the calling thread is the primary system
        /// thread.
        /// </summary>
        /// <param name="pluginFlags">
        /// The flags associated with the plugin being loaded.
        /// </param>
        /// <returns>
        /// True if the plugin may be loaded on the calling thread; otherwise,
        /// false.
        /// </returns>
        private bool CanPluginBeLoaded(
            PluginFlags pluginFlags /* in */
            )
        {
            if (FlagOps.HasFlags(pluginFlags, PluginFlags.LoadOnAnyThread, true))
                return true;

            if (CommonOps.Environment.DoesVariableExist(EnvVars.AllowAnyThread))
                return true;

            if (IsPrimarySystemThread())
                return true;

            return false;
        }

