        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // TODO: When calling this method, be extremely careful when
        //       passing "false" as the "waitForLock" parameter; it
        //       should not be used when the caller cannot handle a
        //       null return value gracefully (e.g. from the method
        //       ShouldWaitVariable).  In this context, "gracefully"
        //       means that the caller would end up providing mostly
        //       the same functionality to its caller regardless of
        //       the return value of this method.
        //
        /// <summary>
        /// This method attempts to obtain the variable event handle using the
        /// specified timeout and locking behavior, discarding any error
        /// message.
        /// </summary>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait for the interpreter
        /// lock, or zero to wait indefinitely using a hard lock.
        /// </param>
        /// <param name="waitForLock">
        /// Non-zero to wait for the interpreter lock; zero to attempt a soft
        /// lock that may fail immediately.
        /// </param>
        /// <returns>
        /// The variable event handle, or null if it could not be obtained.
        /// </returns>
        private EventWaitHandle TryGetVariableEvent(
            int timeout,
            bool waitForLock
            )
        {
            Result error = null;

            return TryGetVariableEvent(timeout, waitForLock, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // TODO: When calling this method, be extremely careful when
        //       passing "false" as the "waitForLock" parameter; it
        //       should not be used when the caller cannot handle a
        //       null return value gracefully (e.g. from the method
        //       ShouldWaitVariable).  In this context, "gracefully"
        //       means that the caller would end up providing mostly
        //       the same functionality to its caller regardless of
        //       the return value of this method.
        //
        /// <summary>
        /// This method attempts to obtain the variable event handle using the
        /// specified timeout and locking behavior.
        /// </summary>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait for the interpreter
        /// lock, or zero to wait indefinitely using a hard lock.
        /// </param>
        /// <param name="waitForLock">
        /// Non-zero to wait for the interpreter lock; zero to attempt a soft
        /// lock that may fail immediately.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing why the variable
        /// event could not be obtained.
        /// </param>
        /// <returns>
        /// The variable event handle, or null if the interpreter lock could
        /// not be acquired.
        /// </returns>
        private EventWaitHandle TryGetVariableEvent(
            int timeout,
            bool waitForLock,
            ref Result error
            )
        {
            bool locked = false;

            try
            {
                if (waitForLock)
                {
                    if (timeout != 0)
                    {
                        InternalTryLock(timeout, ref locked);
                    }
                    else
                    {
                        InternalHardTryLock(ref locked);
                    }
                }
                else
                {
                    InternalSoftTryLock(ref locked);
                }

                if (locked)
                {
                    return variableEvent;
                }
                else
                {
                    error = "unable to acquire lock";

                    TraceOps.LockTrace(
                        "TryGetVariableEvent",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError2,
                        MaybeWhoHasLock());

                    return null;
                }
            }
            finally
            {
                InternalExitLock(ref locked);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method signals the variable event, tracing any failure that
        /// occurs.
        /// </summary>
        private void SignalVariableEvent()
        {
            ReturnCode code;
            Result error = null;

            code = SignalVariableEvent(ref error);

            if (code != ReturnCode.Ok)
            {
                TraceOps.DebugTrace(String.Format(
                    "SignalVariableEvent: {0}",
                    ResultOps.Format(code, error)),
                    typeof(Interpreter).Name,
                    TracePriority.SetupError);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method signals the variable event so that any threads waiting
        /// on variable changes are released.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives an error message describing why the variable
        /// event could not be signaled.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, ReturnCode.Error.
        /// </returns>
        private ReturnCode SignalVariableEvent(
            ref Result error
            )
        {
            EventWaitHandle variableEvent;
            Result localError = null;

            variableEvent = TryGetVariableEvent(ref localError);

            if (variableEvent != null)
            {
                if (ThreadOps.SetEvent(variableEvent))
                    return ReturnCode.Ok;
                else
                    error = "failed to signal variable event";
            }
            else if (localError != null)
            {
                error = localError;
            }
            else
            {
                error = "cannot signal variable event";
            }

            return ReturnCode.Error;
        }

