        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Global Lock
        /// <summary>
        /// This method returns the identifier of the thread that currently
        /// holds the static lock, if any.
        /// </summary>
        /// <returns>
        /// The identifier of the thread holding the static lock, or zero if it
        /// is not held.
        /// </returns>
        private static long MaybeWhoHasStaticLock()
        {
            return Interlocked.CompareExchange(
                ref staticLockThreadId, 0, 0);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records the calling thread as the holder of the static
        /// lock when the lock was successfully acquired.
        /// </summary>
        /// <param name="locked">
        /// Non-zero if the static lock was successfully acquired by the calling
        /// thread.
        /// </param>
        private static void MaybeSomebodyHasStaticLock(
            bool locked /* in */
            )
        {
            if (locked)
            {
                /* IGNORED */
                Interlocked.CompareExchange(ref staticLockThreadId,
                    GlobalState.GetCurrentLockThreadId(), 0);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the record of the static lock holder when the
        /// calling thread is releasing the lock.
        /// </summary>
        /// <param name="locked">
        /// Non-zero if the static lock is currently held by the calling thread
        /// and is being released.
        /// </param>
        private static void MaybeNobodyHasStaticLock(
            bool locked /* in */
            )
        {
            if (locked)
            {
                /* IGNORED */
                Interlocked.CompareExchange(ref staticLockThreadId,
                    0, GlobalState.GetCurrentLockThreadId());
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the static lock without waiting,
        /// recording the calling thread as the holder upon success.
        /// </summary>
        /// <param name="locked">
        /// Upon return, set to non-zero if the static lock was successfully
        /// acquired; otherwise, set to zero.
        /// </param>
        internal static void InternalTryStaticLock( /* NOTE: For DebugOps USE ONLY. */
            ref bool locked /* in, out */
            )
        {
            if (staticSyncRoot == null)
                return;

            locked = Monitor.TryEnter(staticSyncRoot);
            MaybeSomebodyHasStaticLock(locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the static lock, waiting up to the
        /// specified timeout, and records the calling thread as the holder upon
        /// success.
        /// </summary>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait for the static lock.
        /// </param>
        /// <param name="locked">
        /// Upon return, set to non-zero if the static lock was successfully
        /// acquired; otherwise, set to zero.
        /// </param>
        private static void PrivateTryStaticLock(
            int timeout,
            ref bool locked /* in, out */
            )
        {
            if (staticSyncRoot == null)
                return;

            locked = Monitor.TryEnter(staticSyncRoot, timeout);
            MaybeSomebodyHasStaticLock(locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the static lock, waiting up to the
        /// configured wait-lock timeout.
        /// </summary>
        /// <param name="locked">
        /// Upon return, set to non-zero if the static lock was successfully
        /// acquired; otherwise, set to zero.
        /// </param>
        private static void PrivateTryStaticLockWithWait(
            ref bool locked /* in, out */
            )
        {
            PrivateTryStaticLock(ThreadOps.GetTimeout(
                null, null, TimeoutType.WaitLock), ref locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method releases the static lock if it is currently held by the
        /// calling thread.
        /// </summary>
        /// <param name="locked">
        /// Non-zero on input if the static lock is held; set to zero upon
        /// return after the lock has been released.
        /// </param>
        internal static void InternalExitStaticLock( /* NOTE: For DebugOps USE ONLY. */
            ref bool locked /* in, out */
            )
        {
            if (staticSyncRoot == null)
                return;

            if (locked)
            {
                MaybeNobodyHasStaticLock(locked);
                Monitor.Exit(staticSyncRoot);
                locked = false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the static lock without waiting, for
        /// use by external callers.
        /// </summary>
        /// <param name="locked">
        /// Upon return, set to non-zero if the static lock was successfully
        /// acquired; otherwise, set to zero.
        /// </param>
