        /// <summary>
        /// Gets or sets the host associated with this interpreter.  Assigning a
        /// previously unseen host causes its colors, channels, and (when
        /// applicable) debugger support to be configured.
        /// </summary>
        public IHost Host
        {
            get
            {
                CheckDisposed();

                lock (syncRoot)
                {
                    return host;
                }
            }
            set
            {
                CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    IHost oldHost = host;
                    IHost newHost = value;

                    //
                    // BUGFIX: We may have just been handed a host that we have
                    //         never seen before.  Make sure it is setup properly.
                    //
                    ReturnCode code;
                    Result error = null;

                    if ((newHost != null) &&
                        !Object.ReferenceEquals(newHost, oldHost))
                    {
                        code = PreSetupHostColors(newHost, false, ref error);

                        if (code != ReturnCode.Ok)
                            DebugOps.Complain(this, code, error);

                        code = SetupHostChannels(newHost, interpreterFlags, ref error);

                        if (code != ReturnCode.Ok)
                            DebugOps.Complain(this, code, error);

#if DEBUGGER
                        code = SetupDebuggerHost(newHost, ref error);

                        if (code != ReturnCode.Ok)
                            DebugOps.Complain(this, code, error);
#endif
                    }

                    host = newHost;
                }
            }
        }

