        #region Private
        /// <summary>
        /// Gets or sets the ready timeout, in milliseconds, for this
        /// interpreter.  When threading support is enabled, the value is stored
        /// on the engine context; otherwise, it is stored directly on the
        /// interpreter.
        /// </summary>
        private int? PrivateReadyTimeout
        {
            get
            {
#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    return context.ReadyTimeout;
                else
                    return null;
#else
                // lock (syncRoot)
                {
                    return readyTimeout;
                }
#endif
            }
            set
            {
#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    context.ReadyTimeout = value;
#else
                // lock (syncRoot)
                {
                    readyTimeout = value;
                }
#endif
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines the effective ready timeout to use,
        /// preferring an explicit timeout, then the global ready timeout, then
        /// the timeout configured on the interpreter, and finally a computed
        /// default.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose configured ready timeout and creation state
        /// should be consulted, or null to force fallback logic.
        /// </param>
        /// <param name="timeout">
        /// An explicit timeout, in milliseconds, or null to use the fallback
        /// logic.
        /// </param>
        /// <returns>
        /// The effective ready timeout, in milliseconds.
        /// </returns>
        private static int GetEffectiveReadyTimeout(
            Interpreter interpreter,
            int? timeout
            )
        {
            if (timeout != null)
                return (int)timeout;

            int? globalReadyTimeout = GlobalReadyTimeout;

            if (globalReadyTimeout != null)
                return (int)globalReadyTimeout;

            if (interpreter != null)
            {
                int? readyTimeout = interpreter.PrivateReadyTimeout;

                if (readyTimeout != null)
                    return (int)readyTimeout;

                //
                // HACK: If creation (of the interpreter) is pending,
                //       wait forever for it to be ready -UNLESS- the
                //       ready timeout has been explicitly overridden
                //       (per the above check).  In practice, that is
                //       highly unlikely.
                //
                if (interpreter.IsCreationPending())
                    return _Timeout.Infinite;
            }

            //
            // WARNING: *PERF* This is a hot-path; therefore, avoid
            //          passing the interpreter parameter here; use
            //          null instead to force fallback logic.
            //
            return ThreadOps.GetTimeout(null, timeout, TimeoutType.Ready);
        }

