        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the name of the command used to handle unknown
        /// commands, preferring the current namespace, then the global
        /// namespace, and finally the interpreter-wide value.  The caller is
        /// assumed to hold the interpreter lock.
        /// </summary>
        private string PrivateUnknown /* WARNING: Assumes lock is held. */
        {
            get
            {
                if (!disposed && InternalAreNamespacesEnabled())
                {
                    string result;
                    INamespace currentNamespace = null;

                    if ((GetCurrentNamespaceViaResolvers(
                            null, LookupFlags.NoVerbose,
                            ref currentNamespace) == ReturnCode.Ok) &&
                        (currentNamespace != null))
                    {
                        result = currentNamespace.Unknown;

                        if (result != null)
                            return result;
                    }

                    if (globalNamespace != null)
                    {
                        result = globalNamespace.Unknown;

                        if (result != null)
                            return result;
                    }
                }

                return unknown; /* NOTE: *COMPAT* Eagle beta. */
            }
            set
            {
                if (!disposed && InternalAreNamespacesEnabled())
                {
                    INamespace currentNamespace = null;

                    if ((GetCurrentNamespaceViaResolvers(
                            null, LookupFlags.NoVerbose,
                            ref currentNamespace) == ReturnCode.Ok) &&
                        (currentNamespace != null))
                    {
                        currentNamespace.Unknown = value;
                        return;
                    }

                    if (globalNamespace != null)
                    {
                        globalNamespace.Unknown = value;
                        return;
                    }
                }

                unknown = value; /* NOTE: *COMPAT* Eagle beta. */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the name of the command used to handle unknown
        /// commands, honoring the global-only engine flag.
        /// </summary>
        /// <param name="engineFlags">
        /// The engine flags that control whether only the global unknown
        /// handler is considered.
        /// </param>
        /// <returns>
        /// The name of the unknown command handler.
        /// </returns>
        private string GetUnknown(
            EngineFlags engineFlags
            )
        {
            if (EngineFlagOps.HasGlobalOnly(engineFlags))
                return unknown; /* FIELD */

            return PrivateUnknown; /* PROPERTY */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // BUGFIX: The arguments parameter must be "ref" here due to
        //         cross-domain marshalling requirements, i.e. from
        //         the Engine class.
        //
        /// <summary>
        /// This method attempts to locate the unknown command handler and, if
        /// found, prepends it to the supplied argument list so the caller can
        /// dispatch to it, while enforcing the configured unknown invocation
        /// limit.
        /// </summary>
        /// <param name="returnCode">
        /// The return code from the original command lookup that triggered the
        /// unknown handling attempt.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags that control command resolution and which unknown
        /// handler is selected.
        /// </param>
        /// <param name="lookupFlags">
        /// The lookup flags used when resolving the unknown command handler.
        /// </param>
        /// <param name="arguments">
        /// On input, the original argument list; upon success, prefixed with
        /// the resolved unknown command handler.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the resolved executable for the unknown
        /// command handler.
        /// </param>
        /// <param name="useUnknown">
        /// Upon success, set to non-zero to indicate that the unknown handler
        /// should be used.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok if the unknown handler was resolved and should be
        /// used; otherwise, an error or the original return code.
        /// </returns>
        internal ReturnCode AttemptToUseUnknown(
            ReturnCode returnCode,      /* in */
            EngineFlags engineFlags,    /* in */
            LookupFlags lookupFlags,    /* in */
            ref ArgumentList arguments, /* in, out */
            ref IExecute execute,       /* out */
            ref bool useUnknown         /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                long localUnknownCount = Interlocked.Increment(
                    ref unknownCount);

                if ((unknownLimit == Limits.Unlimited) ||
                    (localUnknownCount <= unknownLimit))
                {
                    if (arguments != null)
                    {
                        string unknownText = GetUnknown(engineFlags);

                        if ((unknownText != null) && (UnknownLevels == 0))
                        {
                            StringList unknownList = null;

                            if ((ParserOps<string>.SplitList(
                                    this, unknownText, 0, Length.Invalid, true,
                                    ref unknownList) == ReturnCode.Ok) &&
                                (unknownList.Count > 0))
                            {
                                if (InternalGetIExecuteViaResolvers(
                                        engineFlags | EngineFlags.ToExecute,
                                        unknownList[0], arguments, lookupFlags,
                                        ref execute) == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: Prefix the argument list provided by the
                                    //       caller with the unknown handler for this
                                    //       namespace or interpreter.
                                    //
                                    arguments.InsertRange(0, unknownList);

                                    //
                                    // NOTE: Set the unknown flag so that the we can
                                    //       properly modify the unknown nesting level
                                    //       (below) prior to actually executing
                                    //       [unknown]; otherwise, infinite recursion
                                    //       may result.
                                    //
                                    useUnknown = true;

                                    //
                                    // NOTE: The unknown handler is available.  Have
                                    //       the caller try to use it by indicating
                                    //       success here.
                                    //
                                    return ReturnCode.Ok;
                                }
                            }
                        }
                    }
                }
                else
                {
                    /* IGNORED */
                    Interlocked.Decrement(ref unknownCount);

                    TraceOps.DebugTrace(String.Format(
                        "AttemptToUseUnknown: limit exceeded: {0}",
                        unknownLimit), typeof(Interpreter).Name,
                        TracePriority.ScriptError);
                }

                return returnCode;
            }
        }

