        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method uses more-or-less the same general idea as the
        //       SafeGetQuiet method of the DebugOps class; however, this one
        //       avoids causing an exception to be thrown (and caught) by
        //       accessing the quiet field directly instead of via the property.
        //
        /// <summary>
        /// This method determines whether this interpreter should suppress
        /// extraneous output, consulting the quiet field and the environment
        /// before falling back to the supplied default.
        /// </summary>
        /// <param name="default">
        /// The value to return when neither the quiet field nor the environment
        /// forces quiet behavior.
        /// </param>
        /// <returns>
        /// True if extraneous output should be suppressed; otherwise, the value
        /// of <paramref name="default" />.
        /// </returns>
        internal bool ShouldBeQuiet(
            bool @default
            )
        {
            // CheckDisposed();

            lock (syncRoot)
            {
                if (quiet) /* FIELD */
                    return true;
            }

            //
            // HOOK: Allow the test suite (and others components) to override
            //       the quietness setting via the environment.
            //
            if (CommonOps.Environment.DoesVariableExist(EnvVars.Quiet))
                return true;

            return @default;
        }

