        #region Host Output Size Handling
        /// <summary>
        /// This method attempts to query the output content margin from the
        /// interpreter host.
        /// </summary>
        /// <param name="margin">
        /// Upon success, receives the content margin reported by the host.
        /// </param>
        /// <returns>
        /// True if the margin was obtained from the host; otherwise, false.
        /// </returns>
        private bool GetMarginFromHost(
            ref int margin /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                _Hosts.Default defaultHost =
                    this.host as _Hosts.Default;

                if (defaultHost != null)
                {
                    try
                    {
                        margin = defaultHost.ContentMargin;
                        return true;
                    }
                    catch (Exception e)
                    {
                        TraceOps.DebugTrace(
                            e, typeof(Interpreter).Name,
                            TracePriority.HostError);
                    }
                }

                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to query the current buffer size from the
        /// interpreter host.
        /// </summary>
        /// <param name="width">
        /// Upon success, receives the buffer width reported by the host.
        /// </param>
        /// <param name="height">
        /// Upon success, receives the buffer height reported by the host.
        /// </param>
        /// <returns>
        /// True if the size was obtained from the host; otherwise, false.
        /// </returns>
        private bool GetSizeFromHost(
            ref int width, /* out */
            ref int height /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                IHost host = this.host;

                if (host != null)
                {
                    try
                    {
                        int localWidth = 0;
                        int localHeight = 0;

                        if (host.GetSize( /* throw */
                                HostSizeType.BufferCurrent,
                                ref localWidth, ref localHeight))
                        {
                            width = localWidth;
                            height = localHeight;

                            return true;
                        }
                    }
                    catch (Exception e)
                    {
                        TraceOps.DebugTrace(
                            e, typeof(Interpreter).Name,
                            TracePriority.HostError);
                    }
                }

                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the output content margin, querying the interpreter host when
        /// possible and falling back to the default output margin otherwise.
        /// </summary>
        private int PrivateOutputMargin
        {
            get
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    int margin = 0;

                    if (GetMarginFromHost(ref margin) &&
                        (margin >= Margin.Minimum))
                    {
                        return margin;
                    }

                    return DefaultOutputMargin;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the output width, querying the interpreter host when possible
        /// and falling back to the default output width otherwise.
        /// </summary>
        private int PrivateOutputWidth
        {
            get
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    int width = 0;
                    int height = 0; /* NOT USED */

                    if (GetSizeFromHost(
                            ref width, ref height) &&
                        (width >= Width.Minimum))
                    {
                        return width;
                    }

                    return DefaultOutputWidth;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the output height, querying the interpreter host when possible
        /// and falling back to the default output height otherwise.
        /// </summary>
        private int PrivateOutputHeight
        {
            get
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    int width = 0; /* NOT USED */
                    int height = 0;

                    if (GetSizeFromHost(
                            ref width, ref height) &&
                        (height >= Height.Minimum))
                    {
                        return height;
                    }

                    return DefaultOutputHeight;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the default output content margin, clamped to the minimum
        /// allowed margin.
        /// </summary>
        private /* static */ int DefaultOutputMargin
        {
            get
            {
                int result = Margin.Default;

                if (result < Margin.Minimum)
                    result = Margin.Minimum;

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the default output width, reduced by the output margin when
        /// doing so keeps the result above the minimum allowed width.
        /// </summary>
        private int DefaultOutputWidth
        {
            get
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    int result = Width.Default;

                    if (result < 0)
                        result = 0;

                    int margin = PrivateOutputMargin;

                    if ((margin > 0) &&
                        ((result - margin) > Width.Minimum))
                    {
                        result -= margin;
                    }

                    return result;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the default output height, reduced by the output margin when
        /// doing so keeps the result above the minimum allowed height.
        /// </summary>
        private int DefaultOutputHeight
        {
            get
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    int result = Height.Default;

                    if (result < 0)
                        result = 0;

                    int margin = PrivateOutputMargin;

                    if ((margin > 0) &&
                        ((result - margin) > Height.Minimum))
                    {
                        result -= margin;
                    }

                    return result;
                }
            }
        }
        #endregion
        #endregion
        #endregion

