        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Watchdog Support
        /// <summary>
        /// This method attempts to acquire the interpreter lock and then
        /// immediately release it.  It can be used to test whether the lock is
        /// currently available.
        /// </summary>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait for the lock, or null to
        /// attempt a single non-blocking (soft) lock.
        /// </param>
        /// <returns>
        /// True if the lock was acquired; otherwise, false.
        /// </returns>
        public bool TryLockAndExit(
            int? timeout
            )
        {
            CheckDisposed();

            bool locked = false;

            try
            {
                if (timeout != null)
                    InternalTryLock((int)timeout, ref locked);
                else
                    InternalSoftTryLock(ref locked);

                return locked;
            }
            finally
            {
                InternalExitLock(ref locked);
            }
        }

