        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs a control operation against the interpreter
        /// health (watchdog) thread.
        /// </summary>
        /// <param name="watchdogOperation">
        /// The control operation to perform.
        /// </param>
        /// <param name="clientData">
        /// Optional caller-specific data used by some operations.
        /// </param>
        /// <param name="timeout">
        /// The timeout, in milliseconds, used by some operations, or null to
        /// use the default.
        /// </param>
        /// <param name="mustBeAlive">
        /// Non-zero if the operation should require the health thread to be
        /// alive.
        /// </param>
        /// <param name="forceStart">
        /// Non-zero to force the thread to be started even if one already
        /// appears to be running.
        /// </param>
        /// <param name="strictStart">
        /// Non-zero to treat any failure to start the thread as an error.
        /// </param>
        /// <param name="noAbort">
        /// Non-zero to avoid forcibly aborting the thread when stopping it.
        /// </param>
        /// <param name="strictStop">
        /// Non-zero to treat any failure to stop the thread as an error.
        /// </param>
        /// <param name="noName">
        /// Non-zero to skip verifying the thread name when attaching it.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to include descriptive messages in the result.
        /// </param>
        /// <param name="result">
        /// Upon success, receives any output produced by the operation; upon
        /// failure, receives an error message.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> if the operation was performed
        /// successfully; otherwise, an error code.
        /// </returns>
        private ReturnCode WatchdogHealthControl(
            WatchdogOperation watchdogOperation,
            IClientData clientData,
            int? timeout,
            bool mustBeAlive,
            bool forceStart,
            bool strictStart,
            bool noAbort,
            bool strictStop,
            bool noName,
            bool verbose,
            ref Result result
            )
        {
            IBaseClientData baseClientData = clientData as IBaseClientData;

            switch (watchdogOperation)
            {
                case WatchdogOperation.Check:
                    {
                        result = HasHealthThread(mustBeAlive);
                        return ReturnCode.Ok;
                    }
                case WatchdogOperation.Fetch:
                    {
                        if (baseClientData == null)
                        {
                            result = "invalid core clientData";
                            return ReturnCode.Error;
                        }

                        if (baseClientData.DataNoThrow != null)
                        {
                            result = "core clientData in use";
                            return ReturnCode.Error;
                        }

                        lock (syncRoot) /* TRANSACTIONAL */
                        {
                            baseClientData.DataNoThrow = healthThread;

                            if (verbose)
                                result = "health thread fetched";
                            else
                                result = String.Empty;

                            return ReturnCode.Ok;
                        }
                    }
                case WatchdogOperation.Start:
                    {
                        Result localResult = null;

                        if (StartHealthThread(timeout,
                                forceStart, mustBeAlive, strictStart,
                                ref localResult) != ReturnCode.Ok)
                        {
                            if (localResult != null)
                                result = localResult;
                            else
                                result = "failed to start health thread";

                            return ReturnCode.Error;
                        }
                        else if (verbose)
                        {
                            result = localResult;
                        }
                        else
                        {
                            result = String.Empty;
                        }

                        return ReturnCode.Ok;
                    }
                case WatchdogOperation.Stop:
                    {
                        Result localResult = null;

                        if (InterruptHealthThread(
                                timeout, noAbort, strictStop,
                                ref localResult) != ReturnCode.Ok)
                        {
                            if (localResult != null)
                                result = localResult;
                            else
                                result = "failed to interrupt health thread";

                            return ReturnCode.Error;
                        }
                        else if (verbose)
                        {
                            result = localResult;
                        }
                        else
                        {
                            result = String.Empty;
                        }

                        return ReturnCode.Ok;
                    }
                case WatchdogOperation.Restart:
                    {
                        bool sawError = false;
                        ResultList results = null;
                        Result localResult; /* REUSED */

                        localResult = null;

                        if (InterruptHealthThread(
                                timeout, noAbort, strictStop,
                                ref localResult) != ReturnCode.Ok)
                        {
                            sawError = true;

                            if (results == null)
                                results = new ResultList();

                            if (localResult != null)
                            {
                                results.Add(localResult);
                            }
                            else
                            {
                                results.Add(
                                    "failed to interrupt health thread");
                            }
                        }
                        else if (verbose)
                        {
                            if (results == null)
                                results = new ResultList();

                            if (localResult != null)
                            {
                                results.Add(localResult);
                            }
                            else
                            {
                                results.Add(
                                    "interrupted health thread");
                            }
                        }

                        localResult = null;

                        if (StartHealthThread(timeout,
                                forceStart, mustBeAlive, strictStart,
                                ref localResult) != ReturnCode.Ok)
                        {
                            sawError = true;

                            if (results == null)
                                results = new ResultList();

                            if (localResult != null)
                            {
                                results.Add(localResult);
                            }
                            else
                            {
                                results.Add(
                                    "failed to start health thread");
                            }
                        }
                        else if (verbose)
                        {
                            if (results == null)
                                results = new ResultList();

                            if (localResult != null)
                            {
                                results.Add(localResult);
                            }
                            else
                            {
                                results.Add(
                                    "started health thread");
                            }
                        }

                        result = (results != null) ?
                            results : (Result)String.Empty;

                        return sawError ?
                            ReturnCode.Error : ReturnCode.Ok;
                    }
                case WatchdogOperation.Attach:
                    {
                        if (baseClientData == null)
                        {
                            result = "invalid core clientData";
                            return ReturnCode.Error;
                        }

                        Thread localThread = baseClientData.DataNoThrow as Thread;

                        if (localThread == null)
                        {
                            result = "core clientData is not a thread";
                            return ReturnCode.Error;
                        }

                        if (!noName && !StringOps.Match(
                                this, MatchMode.Glob, localThread.Name,
                                "healthThread: *", false))
                        {
                            result = "thread is not for health";
                            return ReturnCode.Error;
                        }

                        lock (syncRoot) /* TRANSACTIONAL */
                        {
                            if (healthThread == null)
                            {
                                healthThread = localThread;
                                baseClientData.DataNoThrow = null;

                                if (verbose)
                                    result = "health thread attached";
                                else
                                    result = String.Empty;

                                return ReturnCode.Ok;
                            }
                            else
                            {
                                result = "health thread already attached";
                                return ReturnCode.Error;
                            }
                        }
                    }
                case WatchdogOperation.Detach:
                    {
                        if (baseClientData == null)
                        {
                            result = "invalid core clientData";
                            return ReturnCode.Error;
                        }

                        if (baseClientData.DataNoThrow != null)
                        {
                            result = "core clientData in use";
                            return ReturnCode.Error;
                        }

                        lock (syncRoot) /* TRANSACTIONAL */
                        {
                            if (healthThread != null)
                            {
                                baseClientData.DataNoThrow = healthThread;
                                healthThread = null;

                                if (verbose)
                                    result = "health thread detached";
                                else
                                    result = String.Empty;

                                return ReturnCode.Ok;
                            }
                            else
                            {
                                result = "health thread already detached";
                                return ReturnCode.Error;
                            }
                        }
                    }
                default:
                    {
                        result = String.Format(
                            "unsupported watchdog operation: {0}",
                            watchdogOperation);

                        return ReturnCode.Error;
                    }
            }
        }
#endif

