        /// <summary>
        /// This method creates a script object suitable for queuing as an
        /// "after" event, combining the interpreter engine and event flags
        /// with those supplied by the caller.
        /// </summary>
        /// <param name="name">
        /// The name to associate with the script.
        /// </param>
        /// <param name="group">
        /// The group to associate with the script.
        /// </param>
        /// <param name="description">
        /// The description to associate with the script.
        /// </param>
        /// <param name="type">
        /// The type name to associate with the script.
        /// </param>
        /// <param name="text">
        /// The script text.
        /// </param>
        /// <param name="timeStamp">
        /// The time stamp to associate with the script.
        /// </param>
        /// <param name="engineMode">
        /// The engine mode to use when the script is evaluated.
        /// </param>
        /// <param name="scriptFlags">
        /// The script flags to associate with the script.
        /// </param>
        /// <param name="eventFlags">
        /// The event flags to associate with the script.
        /// </param>
        /// <param name="clientData">
        /// Optional caller-specific data to associate with the script.
        /// </param>
        /// <param name="idle">
        /// Non-zero if the script should be treated as an idle event.
        /// </param>
        /// <returns>
        /// Returns the newly created script object.
        /// </returns>
        internal IScript CreateAfterScript(
            string name,
            string group,
            string description,
            string type,
            string text,
            DateTime timeStamp,
            EngineMode engineMode,
            ScriptFlags scriptFlags,
            EventFlags eventFlags,
            IClientData clientData,
            bool idle
            )
        {
            //
            // NOTE: *SECURITY* Do not use the EngineFlags, EngineFlagsNoLock,
            //       or ContextEngineFlags properties here because that could
            //       cause the queued script to be evaluated with elevated
            //       permissions.
            //
            EventFlags localEventFlags;

            lock (syncRoot)
            {
                localEventFlags = afterEventFlags;
            }

            return Script.Create(
                name, group, description, type, text,
                timeStamp, engineMode, scriptFlags,
                engineFlags | EngineFlags.EvaluateGlobal,
                substitutionFlags, eventFlags | localEventFlags |
                    (idle ? EventFlags.Idle : EventFlags.None) |
                    EventFlags.Interpreter, expressionFlags,
                clientData);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method combines the supplied event flags with the interpreter
        /// engine event flags when the supplied flags indicate an
        /// interpreter-level event.
        /// </summary>
        /// <param name="eventFlags">
        /// The event flags to combine with the engine event flags.
        /// </param>
        /// <returns>
        /// Returns the combined event flags.
        /// </returns>
        internal EventFlags CombineEngineEventFlags(
            EventFlags eventFlags
            )
        {
            return FlagOps.HasFlags(eventFlags, EventFlags.Interpreter, true) ?
                engineEventFlags | (eventFlags & ~EventFlags.DequeueMask) :
                eventFlags;
        }

