        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // TODO: When calling this method, be extremely careful when
        //       passing "false" as the "waitForLock" parameter; it
        //       should not be used when the caller cannot handle a
        //       null return value gracefully (e.g. from the method
        //       ShouldWaitVariable).  In this context, "gracefully"
        //       means that the caller would end up providing mostly
        //       the same functionality to its caller regardless of
        //       the return value of this method.
        //
        /// <summary>
        /// This method attempts to obtain the event manager for this
        /// interpreter, using the specified locking behavior and discarding
        /// any error information.
        /// </summary>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait for the lock, or zero to
        /// attempt a single hard lock.
        /// </param>
        /// <param name="waitForLock">
        /// Non-zero to wait for the lock; zero to attempt only a non-blocking
        /// (soft) lock.
        /// </param>
        /// <returns>
        /// The event manager, or null if it could not be obtained.
        /// </returns>
        private IEventManager TryGetEventManager(
            int timeout,
            bool waitForLock
            )
        {
            int limit = 0;
            Result error = null;

            return TryGetEventManager(
                timeout, waitForLock, ref limit, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // TODO: When calling this method, be extremely careful when
        //       passing "false" as the "waitForLock" parameter; it
        //       should not be used when the caller cannot handle a
        //       null return value gracefully (e.g. from the method
        //       ShouldWaitVariable).  In this context, "gracefully"
        //       means that the caller would end up providing mostly
        //       the same functionality to its caller regardless of
        //       the return value of this method.
        //
        /// <summary>
        /// This method attempts to obtain the event manager for this
        /// interpreter, using the specified locking behavior and returning the
        /// configured event limit along with any error information.
        /// </summary>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait for the lock, or zero to
        /// attempt a single hard lock.
        /// </param>
        /// <param name="waitForLock">
        /// Non-zero to wait for the lock; zero to attempt only a non-blocking
        /// (soft) lock.
        /// </param>
        /// <param name="limit">
        /// Upon success, receives the configured event limit for this
        /// interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// The event manager, or null if the lock could not be acquired.
        /// </returns>
        private IEventManager TryGetEventManager(
            int timeout,
            bool waitForLock,
            ref int limit,
            ref Result error
            )
        {
            bool locked = false;

            try
            {
                if (waitForLock)
                {
                    if (timeout != 0)
                    {
                        InternalTryLock(timeout, ref locked);
                    }
                    else
                    {
                        InternalHardTryLock(ref locked);
                    }
                }
                else
                {
                    InternalSoftTryLock(ref locked);
                }

                if (locked)
                {
                    limit = eventLimit;
                    return eventManager;
                }
                else
                {
                    error = "unable to acquire lock";

                    TraceOps.LockTrace(
                        "TryGetEventManager",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError2,
                        MaybeWhoHasLock());

                    return null;
                }
            }
            finally
            {
                InternalExitLock(ref locked);
            }
        }
        #endregion

