            IEventManager eventManager;
            int limit = 0;
            Result localError = null; /* REUSED */

            eventManager = TryGetEventManager(ref limit, ref localError);

            if (EventOps.ManagerIsOk(eventManager))
            {
                ReturnCode code;

                localError = null;

                code = eventManager.QueueEvent(
