            {
                CheckDisposed();

                PrivatePrecision = value;

                MaybeSetPrecisionVariableValue(value);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method rounds the supplied decimal value according to the
        /// configured floating-point precision.
        /// </summary>
        /// <param name="value">
        /// The decimal value to be rounded.
        /// </param>
        /// <returns>
        /// The value rounded according to the configured precision.
        /// </returns>
        internal decimal FixFinalPrecision(
            decimal value
            ) /* throw */
        {
            int localPrecision = PrivatePrecision;

            if (localPrecision > 0)
                return Math.Round(value, localPrecision);
            else if (localPrecision < 0)
                return Math.Round(value, 0);
            else
                return value;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method rounds the supplied double value according to the
        /// configured floating-point precision.
        /// </summary>
        /// <param name="value">
        /// The double value to be rounded.
        /// </param>
        /// <returns>
        /// The value rounded according to the configured precision.
        /// </returns>
        internal double FixFinalPrecision(
            double value
            ) /* throw */
        {
            int localPrecision = PrivatePrecision;

            if (localPrecision > 0)
                return Math.Round(value, localPrecision);
            else if (localPrecision < 0)
                return Math.Round(value, 0);
            else
                return value;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method updates the script-level precision variable to reflect
        /// the specified precision, unless variable creation is prohibited for
        /// this interpreter.
        /// </summary>
        /// <param name="value">
        /// The precision value to store in the script-level variable.
        /// </param>
        private void MaybeSetPrecisionVariableValue(
            int value /* in */
            )
        {
            VariableFlags flags = VariableFlags.ViaProperty;

            //
            // NOTE: Do not create the variable if we have been
            //       prohibited from doing so.  This variable *IS*
            //       NOT allowed in "safe" interpreters, based on
            //       what native Tcl allows.
            //
            if (InternalIsSafe() || PrivateIsNoVariables())
                flags |= VariableFlags.NoCreate;

            //
            // NOTE: Update script-level informational variable.
            //
            SetLibraryVariableValue(
                flags, TclVars.Core.PrecisionName, value.ToString(),
                precisionTraceList);
        }
        #endregion
        #endregion

