        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter is currently
        /// modifiable, discarding any error information.
        /// </summary>
        /// <param name="ignoreImmutable">
        /// Non-zero to ignore the immutable state when making the
        /// determination.
        /// </param>
        /// <returns>
        /// True if the interpreter is modifiable; otherwise, false.
        /// </returns>
        private bool IsModifiable(
            bool ignoreImmutable
            )
        {
            Result error = null;

            return IsModifiable(ignoreImmutable, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter is currently
        /// modifiable.
        /// </summary>
        /// <param name="ignoreImmutable">
        /// Non-zero to ignore the immutable state when making the
        /// determination.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing why the
        /// interpreter is not modifiable.
        /// </param>
        /// <returns>
        /// True if the interpreter is modifiable; otherwise, false.
        /// </returns>
        internal bool IsModifiable(
            bool ignoreImmutable,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (disposed)
                {
                    error = "interpreter is disposed";
                    return false;
                }

                if (readOnly)
                {
                    error = "interpreter is read-only";
                    return false;
                }

                if (!ignoreImmutable && immutable)
                {
                    error = "interpreter is immutable";
                    return false;
                }

                return true;
            }
        }

