        /// <summary>
        /// This method temporarily clears the immutable state of this
        /// interpreter, returning its previous value so it can be restored
        /// later.
        /// </summary>
        /// <returns>
        /// The previous value of the immutable state.
        /// </returns>
        private bool BeginMutableExecution()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool savedImmutable = immutable;

                immutable = false;

                return savedImmutable;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the immutable state of this interpreter to a
        /// previously saved value.
        /// </summary>
        /// <param name="savedImmutable">
        /// The immutable state value to restore.
        /// </param>
        private void EndMutableExecution(
            bool savedImmutable
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                immutable = savedImmutable;
            }
        }

