        /// <summary>
        /// This method increments the readiness count for this interpreter,
        /// returning the resulting nesting depth.
        /// </summary>
        /// <returns>
        /// The updated readiness count, adjusted so that the outermost check
        /// reports zero.
        /// </returns>
        private int BumpReadyCount()
        {
            int localReadyCount = Interlocked.Increment(ref readyCount);

            if (localReadyCount > 0)
                localReadyCount--;

            return localReadyCount;
        }

