        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method assumes the interpreter lock is already held.
        //
        /// <summary>
        /// This method determines whether a child interpreter limit is in
        /// effect for this interpreter.
        /// </summary>
        /// <returns>
        /// True if a child limit is in effect; otherwise, false.
        /// </returns>
        private bool HasChildLimit()
        {
            return (childLimit != Limits.Unlimited);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method assumes the interpreter lock is already held.
        //
        /// <summary>
        /// This method determines whether another child interpreter may be
        /// added without exceeding the configured child limit.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// True if another child interpreter may be added; otherwise, false.
        /// </returns>
        private bool CanAddChild(
            ref Result error
            )
        {
            if (childLimit == Limits.Unlimited)
                return true; /* NO-LIMIT */

            if ((childInterpreters != null) &&
                (childInterpreters.Count >= childLimit))
            {
                error = "cannot add child, limit exceeded";
                return false; /* LIMIT-HIT */
            }

            return true; /* LIMIT-OK */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether another namespace may be added
        /// without exceeding the configured namespace limit.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// True if another namespace may be added; otherwise, false.
        /// </returns>
        internal bool CanAddNamespace(
            ref Result error
            )
        {
            if (namespaceLimit == Limits.Unlimited)
                return true; /* NO-LIMIT */

            if (Interlocked.CompareExchange(
                    ref namespaceCount, 0, 0) >= namespaceLimit)
            {
                error = "cannot add namespace, limit exceeded";
                return false; /* LIMIT-HIT */
            }

            return true; /* LIMIT-OK */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records that a namespace has been added by incrementing
        /// the namespace count for this interpreter.
        /// </summary>
        /// <returns>
        /// The updated namespace count.
        /// </returns>
        internal int TrackNamespaceAdded()
        {
            return Interlocked.Increment(ref namespaceCount);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records that a namespace has been removed by
        /// decrementing the namespace count for this interpreter.
        /// </summary>
        /// <returns>
        /// The updated namespace count.
        /// </returns>
        private int TrackNamespaceRemoved()
        {
            return Interlocked.Decrement(ref namespaceCount);
        }

