#if RESULT_LIMITS
        /// <summary>
        /// This method determines the default result limits appropriate for
        /// the specified interpreter, based on whether it is a "safe"
        /// interpreter.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to inspect, which may be null.
        /// </param>
        /// <param name="executeResultLimit">
        /// Upon return, receives the default execution result limit.
        /// </param>
        /// <param name="nestedResultLimit">
        /// Upon return, receives the default nested result limit.
        /// </param>
        internal static void GetDefaultResultLimits(
            Interpreter interpreter,
            out int executeResultLimit,
            out int nestedResultLimit
            )
        {
            if ((interpreter != null) && interpreter.InternalIsSafe())
            {
                executeResultLimit = DefaultSafeExecuteResultLimit;
                nestedResultLimit = DefaultSafeNestedResultLimit;
            }
            else
            {
                executeResultLimit = DefaultUnsafeExecuteResultLimit;
                nestedResultLimit = DefaultUnsafeNestedResultLimit;
            }
        }

