            set { /* NO-LOCK */ nestedResultLimit = value; }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the fallback timeout, in milliseconds, used when a
        /// specific timeout is not configured, or null if none.
        /// </summary>
        internal int? InternalFallbackTimeout
        {
            get { /* NO-LOCK */ return fallbackTimeout; }
            set { /* NO-LOCK */ fallbackTimeout = value; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method assumes the interpreter lock is already
        //          held.
        //
        /// <summary>
        /// This method translates the specified timeout type into the concrete
        /// timeout type appropriate for this interpreter.
        /// </summary>
        /// <param name="timeoutType">
        /// The timeout type to translate.
        /// </param>
        /// <returns>
        /// The translated timeout type.
        /// </returns>
        internal TimeoutType TranslateTimeoutType(
            TimeoutType timeoutType
            )
        {
            //
            // TODO: If more timeout types depend on whether this is
            //       a "safe" or "unsafe" interpreter, etc, add them
            //       here.
            //
            switch (timeoutType)
            {
                case TimeoutType.Finally:
                    {
                        return InternalIsSafe() ?
                            TimeoutType.SafeFinally :
                            TimeoutType.UnsafeFinally;
                    }
                default:
                    {
                        return timeoutType; /* VERBATIM */
                    }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the timeout collection for this interpreter
        /// if it has not yet been created or if a reset is requested.
        /// </summary>
        /// <param name="reset">
        /// Non-zero to force the timeout collection to be recreated.
        /// </param>
        private void MaybeInitializeTimeouts(
            bool reset
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (reset || (timeouts == null))
                    timeouts = new IntDictionary();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the fallback timeout should be used
        /// for the specified timeout type and value.
        /// </summary>
        /// <param name="timeoutType">
        /// The timeout type being evaluated.
        /// </param>
        /// <param name="timeout">
        /// The fallback timeout value being considered, which may be null.
        /// </param>
        /// <returns>
        /// True if the fallback timeout should be used; otherwise, false.
        /// </returns>
        private static bool ShouldUseFallbackTimeout(
            TimeoutType timeoutType,
            int? timeout
            )
        {
            if (FlagOps.HasFlags(
                    timeoutType, TimeoutType.ForceFallback, true))
            {
                return true;
            }
            else if (FlagOps.HasFlags(
                    timeoutType, TimeoutType.MaybeFallback, true) &&
                (timeout != null) && ((int)timeout >= 0))
            {
                return true;
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the timeout, in milliseconds, configured for the
        /// specified timeout type, discarding any error information.
        /// </summary>
        /// <param name="timeoutType">
        /// The type of timeout to retrieve.
        /// </param>
        /// <returns>
        /// The configured timeout, in milliseconds, or null if none is
        /// configured.
        /// </returns>
        internal int? InternalGetTimeout(
            TimeoutType timeoutType
            )
        {
            Result error = null;

            return InternalGetTimeout(
                timeoutType | TimeoutType.NoError, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the timeout, in milliseconds, configured for the
        /// specified timeout type.
        /// </summary>
        /// <param name="timeoutType">
        /// The type of timeout to retrieve.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// The configured timeout, in milliseconds, or null if none is
        /// configured or an error occurs.
        /// </returns>
        internal int? InternalGetTimeout(
            TimeoutType timeoutType,
            ref Result error
            )
        {
            bool locked = false;

            try
            {
                InternalSoftTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (timeouts == null)
                    {
                        error = "timeouts unavailable";
                        return null;
                    }

                    TimeoutType baseTimeoutType = TranslateTimeoutType(
                        ThreadOps.BaseTimeoutType(timeoutType));

                    string key = baseTimeoutType.ToString();
                    int value;

                    if (timeouts.TryGetValue(key, out value))
                    {
                        return value;
                    }
                    else
                    {
                        int? timeout = fallbackTimeout;

                        if (baseTimeoutType == TimeoutType.Interpreter)
                            return timeout;

                        if (ShouldUseFallbackTimeout(timeoutType, timeout))
                            return timeout;

                        if (!FlagOps.HasFlags(
                                timeoutType, TimeoutType.NoError, true))
                        {
                            error = String.Format(
                                "timeout type {0} not found",
                                FormatOps.WrapOrNull(timeoutType));
                        }
                    }
                }
                else
                {
                    TraceOps.LockTrace(
                        "InternalGetTimeout",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockError,
                        MaybeWhoHasLock());

                    if (!FlagOps.HasFlags(
                            timeoutType, TimeoutType.NoFailSafe, true))
                    {
                        return fallbackTimeout;
                    }
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }

            return null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets or unsets the timeout configured for the specified
        /// timeout type.
        /// </summary>
        /// <param name="timeoutType">
        /// The type of timeout to set or unset.
        /// </param>
        /// <param name="timeout">
        /// The timeout, in milliseconds, to set, or null to unset the timeout.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message describing the problem.
        /// </param>
        /// <returns>
        /// True if the timeout was set or unset successfully; otherwise, false.
        /// </returns>
        internal bool InternalSetOrUnsetTimeout(
            TimeoutType timeoutType,
            int? timeout,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (timeouts == null)
                {
                    error = "timeouts unavailable";
                    return false;
                }

                TimeoutType baseTimeoutType = TranslateTimeoutType(
                    ThreadOps.BaseTimeoutType(timeoutType));

                string key = baseTimeoutType.ToString();

                if (timeout != null)
                {
                    timeouts[key] = (int)timeout;
                    return true;
                }
                else if (timeouts.Remove(key))
                {
                    return true;
                }
                else
                {
                    error = String.Format(
                        "could not remove timeout type {0}",
                        FormatOps.WrapOrNull(timeoutType));

                    return false;
                }
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Notifications
#if NOTIFY || NOTIFY_OBJECT
        /// <summary>
        /// This method fires an event notification to all eligible plugins
        /// loaded into this interpreter, allowing them to observe and possibly
        /// react to the event described by the supplied event arguments.
        /// </summary>
        /// <param name="eventArgs">
        /// The event arguments describing the notification being fired,
        /// including its types and sub-types.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to be supplied to the plugins receiving
        /// this notification.
        /// </param>
        /// <param name="arguments">
        /// The arguments, if any, associated with this notification.
        /// </param>
        /// <param name="result">
        /// Upon success, this may contain results produced while processing
        /// the notification.  Upon failure, this will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        public ReturnCode FireNotification(
            IScriptEventArgs eventArgs,
            IClientData clientData,
            ArgumentList arguments,
            ref Result result
            )
        {
            CheckDisposed();

            return FireNotification(this, eventArgs, clientData, arguments, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether event notifications may currently be
        /// fired on this thread, taking into account both the recursion guard
        /// and the notification suppression flag.
        /// </summary>
        /// <returns>
        /// True if event notifications may be fired; otherwise, false.
        /// </returns>
        private bool CanFireNotifications()
        {
            if (NotifyLevels != 0)
                return false;

            if (FlagOps.HasFlags(PrivateNotifyFlags,
                    NotifyFlags.NoNotify, true))
            {
                return false;
            }

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method temporarily disables event notifications on this
        /// thread, saving the previous notification flags so they can later be
        /// restored.
        /// </summary>
        /// <param name="savedNotifyFlags">
        /// Upon return, this will contain the notification flags that were in
        /// effect prior to disabling notifications.
        /// </param>
        private void BeginNoNotifications(
            out NotifyFlags savedNotifyFlags /* out */
            )
        {
            savedNotifyFlags = PrivateNotifyFlags;
            PrivateNotifyFlags |= NotifyFlags.NoNotify;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the event notification flags previously saved
        /// by <c>BeginNoNotifications</c>, re-enabling notifications on this
        /// thread.
        /// </summary>
        /// <param name="savedNotifyFlags">
        /// On input, the notification flags to restore.  Upon return, this
        /// will be reset to <see cref="NotifyFlags.None" />.
        /// </param>
        private void EndNoNotifications(
            ref NotifyFlags savedNotifyFlags /* in, out */
            )
        {
            PrivateNotifyFlags = savedNotifyFlags;
            savedNotifyFlags = NotifyFlags.None;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified notification types and
        /// sub-type flags are both currently enabled for this interpreter,
        /// taking the per-thread types and flags into account.
        /// </summary>
        /// <param name="type">
        /// The notification types to check.
        /// </param>
        /// <param name="flags">
        /// The notification sub-type flags to check.
        /// </param>
        /// <returns>
        /// True if the specified types and flags are both enabled; otherwise,
        /// false.
        /// </returns>
        private bool CheckNotifyTypesAndFlags(
            NotifyType type,         /* in */
            NotifyFlags flags        /* in */
            )
        {
            //
            // NOTE: Using the properties instead of the fields here
            //       takes into account the per-thread types / flags
            //       as well because the properties return a bitwise
            //       -OR- of global types and flags along with their
            //       associated per-thread values.
            //
            if (FlagOps.HasFlags(PrivateNotifyTypes,
                    type & NotifyType.CheckMask, true) &&
                FlagOps.HasFlags(PrivateNotifyFlags,
                    flags & NotifyFlags.CheckMask, true))
            {
                return true;
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method fires an event notification to all eligible plugins
        /// loaded into the specified interpreter, processing each plugin in
        /// turn for as long as they continue to succeed.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose plugins are to receive the notification.
        /// </param>
        /// <param name="eventArgs">
        /// The event arguments describing the notification being fired,
        /// including its types and sub-types.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to be supplied to the plugins receiving
        /// this notification.
        /// </param>
        /// <param name="arguments">
        /// The arguments, if any, associated with this notification.
        /// </param>
        /// <param name="result">
        /// Upon success, this may contain results produced while processing
        /// the notification.  Upon failure, this will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private static ReturnCode FireNotification(
            Interpreter interpreter,
            IScriptEventArgs eventArgs,
            IClientData clientData,
            ArgumentList arguments,
            ref Result result
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (!interpreter.CanFireNotifications())
            {
                //
                // NOTE: Either event notifications are disabled -OR-
                //       we are already processing one on this thread.
                //       Just return success.
                //
                return ReturnCode.Ok;
            }

            PluginWrapperDictionary plugins = interpreter.GetNotifyPlugins();

            if (plugins == null)
            {
                result = "plugins not available";
                return ReturnCode.Error;
            }

#if ISOLATED_PLUGINS
            //
            // NOTE: Check if we are forbidden from notifying any
            //       plugins that happen to be loaded into isolated
            //       application domains.
            //
            bool noIsolated = interpreter.IsNoIsolatedNotify();
#endif

            //
            // NOTE: Query the event arguments to figure out which
            //       notification types are currently being sent.
            //
            NotifyType hasNotifyTypes = (eventArgs != null) ?
                eventArgs.NotifyTypes : NotifyType.None;

            //
            // NOTE: Query the event arguments to figure out which
            //       notification sub-types are currently being sent.
            //
            NotifyFlags hasNotifyFlags = (eventArgs != null) ?
                eventArgs.NotifyFlags : NotifyFlags.None;

            //
            // NOTE: Prevent endless event notification recursion.
            //
            NotifyFlags savedNotifyFlags;

            interpreter.BeginNoNotifications(out savedNotifyFlags);

            try
            {
                //
                // NOTE: Process each notification (as long as they
                //       all continue to succeed).
                //
                ReturnCode code = ReturnCode.Ok;

                foreach (PluginPair pair in plugins)
                {
                    PluginWrapper pluginWrapper = pair.Value;

                    if (pluginWrapper == null)
                        continue;

#if ISOLATED_PLUGINS
                    //
                    // HACK: *PERF* Possibly forbid any isolated plugins
                    //       from getting this notification.
                    //
                    if (noIsolated && AppDomainOps.IsTransparentProxy(
                            pluginWrapper))
                    {
                        continue;
                    }
#endif

                    try
                    {
                        //
                        // NOTE: Query the plugin to find out which
                        //       notification types it has elected to
                        //       receive.
                        //
                        NotifyType notifyTypes = pluginWrapper.GetTypes(
                            interpreter);

                        //
                        // NOTE: Does this plugin want to receive the
                        //       notifications being sent?
                        //
                        if (!FlagOps.HasFlags(notifyTypes,
                                hasNotifyTypes & NotifyType.CheckMask, true))
                        {
                            continue;
                        }

                        //
                        // NOTE: Query the plugin to find out which
                        //       notification sub-types it has elected
                        //       to receive.
                        //
                        NotifyFlags notifyFlags = pluginWrapper.GetFlags(
                            interpreter);

                        //
                        // NOTE: Does this plugin want to receive the
                        //       notifications being sent?
                        //
                        if (!FlagOps.HasFlags(notifyFlags,
                                hasNotifyFlags & NotifyFlags.CheckMask, true))
                        {
                            continue;
                        }

                        //
                        // NOTE: Since events can basically do anything
                        //       they want, we wrap them in a try block
                        //       to prevent exceptions from escaping.
                        //
                        interpreter.EnterNotifyLevel();

                        try
                        {
                            //
                            // NOTE: Call their notification method.  It
                            //       could do practially anything; however,
                            //       in practice it should not be modifying
                            //       the state of the passed in objects, if
                            //       any.  No guarantee is made about the
                            //       ability of plugins to affect changes
                            //       in the state of the passed in objects
                            //       -OR- to alter the course of action to
                            //       be taken after the notification has
                            //       been processed.
                            //
                            code = pluginWrapper.Notify(
                                interpreter, eventArgs, clientData, arguments,
                                ref result);
                        }
                        finally
                        {
                            interpreter.ExitNotifyLevel();
                        }
                    }
                    catch (Exception e)
                    {
                        //
                        // NOTE: Translate exceptions to a failure return.
                        //
                        result = String.Format(
                            "caught exception while firing notification: {0}",
                            e);

                        code = ReturnCode.Error;
                    }

                    //
                    // NOTE: Check for exception results specially because
                    //       we treat "Break" different from other return
                    //       codes.
                    //
                    if (code == ReturnCode.Break)
                    {
                        //
                        // NOTE: Success; however, skip processing further
                        //       events.
                        //
                        code = ReturnCode.Ok;
                        break;
                    }
                    else if (code != ReturnCode.Ok)
                    {
                        //
                        // NOTE: Some type of failure (or exception), stop
                        //       processing events.
                        //
                        break;
                    }
                }

                return code;
            }
            finally
            {
                interpreter.EndNoNotifications(ref savedNotifyFlags);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally fires an event notification to the
        /// plugins loaded into this interpreter, using a temporary result.
        /// This overload is a convenience wrapper that discards any result
        /// produced while processing the notification.
        /// </summary>
        /// <param name="type">
        /// The notification types being sent.
        /// </param>
        /// <param name="flags">
        /// The notification sub-type flags being sent.
        /// </param>
        /// <param name="data">
        /// The extra data, if any, associated with the event being sent.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter associated with the event being sent.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to be supplied to the plugins receiving
        /// this notification.
        /// </param>
        /// <param name="arguments">
        /// The arguments, if any, associated with this notification.
        /// </param>
        /// <param name="exception">
        /// The exception, if any, associated with the event being sent.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode CheckNotification(
            NotifyType type,         /* in */
            NotifyFlags flags,       /* in */
            object data,             /* in */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            Exception exception      /* in */
            )
        {
            Result result = null;

            return CheckNotification(
                type, flags, data, interpreter, clientData, arguments,
                exception, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally fires an event notification to the
        /// plugins loaded into this interpreter, provided the interpreter is
        /// not disposed, notifications are not disabled, and the specified
        /// types and flags are currently enabled.
        /// </summary>
        /// <param name="type">
        /// The notification types being sent.
        /// </param>
        /// <param name="flags">
        /// The notification sub-type flags being sent.
        /// </param>
        /// <param name="data">
        /// The extra data, if any, associated with the event being sent.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter associated with the event being sent.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to be supplied to the plugins receiving
        /// this notification.
        /// </param>
        /// <param name="arguments">
        /// The arguments, if any, associated with this notification.
        /// </param>
        /// <param name="exception">
        /// The exception, if any, associated with the event being sent.
        /// </param>
        /// <param name="result">
        /// On input, the result associated with the event being sent.  Upon
        /// return, this may contain a result produced while processing the
        /// notification.
        /// </param>
        /// <returns>
        /// Always returns <see cref="ReturnCode.Ok" />; any failure that
        /// occurs while firing the notification is handled internally.
        /// </returns>
        internal ReturnCode CheckNotification(
            NotifyType type,         /* in */
            NotifyFlags flags,       /* in */
            object data,             /* in */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            Exception exception,     /* in */
            ref Result result        /* in, out */
            )
        {
            if (!IsDisposedOrPending(true) &&
                !EngineFlagOps.HasNoNotify(engineFlags) &&
                CanFireNotifications())
            {
                if (CheckNotifyTypesAndFlags(type, flags))
                {
                    bool wrapException = WrapExceptionForNotification;
                    bool useDeepCopy = UseDeepCopyForNotification;

#if MONO_BUILD && (!DEBUG || !VERBOSE)
#pragma warning disable 219
#endif
                    ReturnCode eventCode; // NOTE: Flagged by the Mono C# compiler.
#if MONO_BUILD && (!DEBUG || !VERBOSE)
#pragma warning restore 219
#endif

                    Result eventResult;

                    try
                    {
                        ScriptException scriptException;

                        if (exception is ScriptException)
                            scriptException = (ScriptException)exception;
                        else if (wrapException && (exception != null))
                            scriptException = new ScriptException(null, exception);
                        else
                            scriptException = null;

                        IScriptEventArgs eventArgs = RuntimeOps.GetEventArgs(
                            type, flags, interpreter, new ClientData(data) /* WRAP */,
                            arguments, result, scriptException, InterruptType.None);

                        IClientData eventClientData = clientData; /* REF */
                        ArgumentList eventArguments;

                        if (useDeepCopy)
                        {
                            eventArguments = (arguments != null) ?
                                new ArgumentList(arguments) : null; /* COPY */

                            eventResult = Result.Copy(
                                result, ResultFlags.CopyObject); /* COPY */
                        }
                        else
                        {
                            eventArguments = arguments; /* REF */
                            eventResult = result; /* REF */
                        }

                        eventCode = FireNotification(
                            eventArgs, eventClientData, eventArguments,
                            ref eventResult);
                    }
                    catch (Exception e)
                    {
                        eventResult = String.Format(
                            "caught exception while firing notifications: {0}",
                            e);

                        eventCode = ReturnCode.Error;
                    }
#if DEBUG && VERBOSE
                    finally
                    {
                        if (eventCode != ReturnCode.Ok)
                            DebugOps.Complain(interpreter, eventCode, eventResult);
                    }
#endif
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if NOTIFY_GLOBAL
        /// <summary>
        /// This method conditionally fires an event notification to the
        /// plugins loaded into every interpreter whose name matches the
        /// specified pattern, using a temporary result.  This overload is a
        /// convenience wrapper that discards any result produced while
        /// processing the notifications.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to select which interpreters should receive the
        /// notification, or null to select all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="type">
        /// The notification types being sent.
        /// </param>
        /// <param name="flags">
        /// The notification sub-type flags being sent.
        /// </param>
        /// <param name="data">
        /// The extra data, if any, associated with the event being sent.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter associated with the event being sent.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to be supplied to the plugins receiving
        /// this notification.
        /// </param>
        /// <param name="arguments">
        /// The arguments, if any, associated with this notification.
        /// </param>
        /// <param name="exception">
        /// The exception, if any, associated with the event being sent.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal static ReturnCode CheckNotifications(
            string pattern,          /* in */
            bool noCase,             /* in */
            NotifyType type,         /* in */
            NotifyFlags flags,       /* in */
            object data,             /* in */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            Exception exception      /* in */
            )
        {
            Result result = null;

            return CheckNotifications(
                pattern, noCase, type, flags, data, interpreter,
                clientData, arguments, exception, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally fires an event notification to the
        /// plugins loaded into every interpreter whose name matches the
        /// specified pattern, iterating over all available interpreters and
        /// stopping at the first one that fails.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to select which interpreters should receive the
        /// notification, or null to select all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="type">
        /// The notification types being sent.
        /// </param>
        /// <param name="flags">
        /// The notification sub-type flags being sent.
        /// </param>
        /// <param name="data">
        /// The extra data, if any, associated with the event being sent.
        /// </param>
        /// <param name="interpreter">
        /// The interpreter associated with the event being sent.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to be supplied to the plugins receiving
        /// this notification.
        /// </param>
        /// <param name="arguments">
        /// The arguments, if any, associated with this notification.
        /// </param>
        /// <param name="exception">
        /// The exception, if any, associated with the event being sent.
        /// </param>
        /// <param name="result">
        /// On input, the result associated with the event being sent.  Upon
        /// return, this may contain a result produced while processing the
        /// notifications, or an appropriate error message upon failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private static ReturnCode CheckNotifications(
            string pattern,          /* in */
            bool noCase,             /* in */
            NotifyType type,         /* in */
            NotifyFlags flags,       /* in */
            object data,             /* in */
            Interpreter interpreter, /* in */
            IClientData clientData,  /* in */
            ArgumentList arguments,  /* in */
            Exception exception,     /* in */
            ref Result result        /* in, out */
            )
        {
            InterpreterDictionary interpreters = GlobalState.GetInterpreterPairs();

            if (interpreters == null)
            {
                result = "no interpreters available";
                return ReturnCode.Error;
            }

            ReturnCode code = ReturnCode.Ok;

            bool broadcast = FlagOps.HasFlags(
                flags, NotifyFlags.Broadcast, true);

            bool safe = FlagOps.HasFlags(
                flags, NotifyFlags.Safe, true);

            foreach (InterpreterPair pair in interpreters)
            {
                //
                // NOTE: Do pattern matching first to avoid attempting to
                //       acquire interpreter locks without a valid reason.
                //
                if ((pattern != null) && !StringOps.Match(
                        null, StringOps.DefaultMatchMode, pair.Key,
                        pattern, noCase))
                {
                    continue;
                }

                Interpreter otherInterpreter = pair.Value;

                if (otherInterpreter == null)
                    continue;

                bool locked = false;
                object syncRoot = otherInterpreter.InternalSyncRoot;

                if (syncRoot == null)
                    continue;

                try
                {
                    locked = Monitor.TryEnter(syncRoot);
                    otherInterpreter.MaybeSomebodyHasLock(locked);

                    if (!locked)
                        continue;

                    //
                    // BUGFIX: Always skip the interpreter if it has
                    //         been disposed.
                    //
                    if (otherInterpreter.Disposed)
                        continue;

                    //
                    // BUGFIX: By default, skip this interpreter if it
                    //         belongs to another thread because we do
                    //         not want to create [thread] contexts on
                    //         this thread for it that we have no easy
                    //         way to know when to cleanup.  This limit
                    //         does not apply to broadcast notifications.
                    //
                    if (!broadcast &&
                        !otherInterpreter.IsPrimarySystemThread())
                    {
                        continue;
                    }

                    //
                    // BUGFIX: Do not send any "global" notifications
                    //         to safe interpreters.  Also, do not
                    //         notify an interpreter if we cannot
                    //         obtain the lock for the interpreter OR
                    //         the "global" notification flag is
                    //         disabled for it.  This limit does not
                    //         apply to "safe" notifications.
                    //
                    if (!safe && otherInterpreter.InternalIsSafe())
                        continue;

                    code = otherInterpreter.CheckNotification(
                        type, flags, data, interpreter, clientData,
                        arguments, exception, ref result);

                    if (code != ReturnCode.Ok)
                        break;
                }
                finally
                {
                    if (locked)
                    {
                        otherInterpreter.MaybeNobodyHasLock(locked);
                        Monitor.Exit(syncRoot);
                    }
                }
            }

            return code;
        }
#endif
        #endregion
#endif
        #endregion

