        #region Private
        #region Random Number Generation
        /// <summary>
        /// Gets or sets the entropy provider, if any, used by this interpreter
        /// when generating random data.
        /// </summary>
        internal IProvideEntropy InternalProvideEntropy
        {
            get { /* NO-LOCK */ return provideEntropy; }
            set { /* NO-LOCK */ provideEntropy = value; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the cryptographic random number generator, if any, used by
        /// this interpreter when generating random data.
        /// </summary>
        internal RandomNumberGenerator RandomNumberGenerator
        {
            get { /* NO-LOCK */ return randomNumberGenerator; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the pseudo-random number generator, if any, used by
        /// this interpreter when generating random data.
        /// </summary>
        internal Random Random
        {
            get { /* NO-LOCK */ return random; }
            set { /* NO-LOCK */ random = value; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method appends the configured entropy bytes for this
        /// interpreter to the specified list of bytes.
        /// </summary>
        /// <param name="bytes">
        /// On input, the list of bytes to append to, which may be null.  Upon
        /// return, this will have the entropy bytes appended to it, creating a
        /// new list if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// True if the entropy bytes were appended; otherwise, false.
        /// </returns>
        internal bool AddEntropyToBytes(
            ref ByteList bytes,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool isSafe = InternalIsSafe();
                byte[] entropyBytes = isSafe ? safeEntropy : entropy;

                if (entropyBytes != null)
                {
                    if (bytes == null)
                        bytes = new ByteList();

                    bytes.AddRange(entropyBytes);
                    return true;
                }

                error = String.Format(
                    "{0}entropy not available",
                    isSafe ? "safe " : String.Empty);

                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method appends bytes derived from the current execution
        /// context (e.g. the process, application domain, and thread
        /// identifiers) to the specified list of bytes.
        /// </summary>
        /// <param name="bytes">
        /// On input, the list of bytes to append to, which may be null.  Upon
        /// return, this will have the context bytes appended to it, creating a
        /// new list if necessary.
        /// </param>
        internal void AddContextToBytes(
            ref ByteList bytes
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool isSafe = InternalIsSafe();

                if (bytes == null)
                    bytes = new ByteList();

                if (!isSafe)
                {
                    bytes.Add(BitConverter.GetBytes(
                        ProcessOps.GetParentId()), 0);

                    bytes.Add(BitConverter.GetBytes(
                        ProcessOps.GetId()), 0);
                }

                bytes.Add(BitConverter.GetBytes(
                    AppDomainOps.GetCurrentId()), 0);

                if (isSafe)
                {
                    bytes.Add(BitConverter.GetBytes(
                        GlobalState.GetCurrentManagedThreadId()), 0);
                }
                else
                {
                    bytes.Add(BitConverter.GetBytes(
                        GlobalState.GetCurrentSystemThreadId()), 0);

                    bytes.Add(BitConverter.GetBytes(PrivateId), 0);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method atomically retrieves the random data providers
        /// currently associated with this interpreter.
        /// </summary>
        /// <param name="provideEntropy">
        /// Upon return, this will contain the entropy provider, if any.
        /// </param>
        /// <param name="randomNumberGenerator">
        /// Upon return, this will contain the cryptographic random number
        /// generator, if any.
        /// </param>
        /// <param name="random">
        /// Upon return, this will contain the pseudo-random number generator,
        /// if any.
        /// </param>
        private void GetRandomInstances(
            out IProvideEntropy provideEntropy,              /* out */
            out RandomNumberGenerator randomNumberGenerator, /* out */
            out Random random                                /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                provideEntropy = this.provideEntropy;
                randomNumberGenerator = this.randomNumberGenerator;
                random = this.random;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // BUGFIX: The "bytes" parameter must be "ref"; otherwise,
        //         cross-domain marshalling does not work right.
        //
        /// <summary>
        /// This method fills the specified array with random bytes obtained
        /// from the random data providers associated with this interpreter.
        /// </summary>
        /// <param name="bytes">
        /// On input, the array to be filled with random bytes.  Upon return,
        /// this will contain the generated random bytes.
        /// </param>
        internal void GetRandomBytes(
            ref byte[] bytes
            )
        {
            IProvideEntropy provideEntropy;
            RandomNumberGenerator randomNumberGenerator;
            Random random;

            /* NO RESULT */
            GetRandomInstances(
                out provideEntropy, out randomNumberGenerator, out random);

            /* NO RESULT */
            RuntimeOps.GetRandomBytes(
                provideEntropy, randomNumberGenerator, random, ref bytes);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method generates a signed random number using the random data
        /// providers associated with this interpreter.
        /// </summary>
        /// <returns>
        /// The generated signed random number.
        /// </returns>
        internal long GetSignedRandomNumber()
        {
            return ConversionOps.ToLong(GetRandomNumber());
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method generates an unsigned random number using the random
        /// data providers associated with this interpreter.
        /// </summary>
        /// <returns>
        /// The generated unsigned random number.
        /// </returns>
        internal ulong GetRandomNumber()
        {
            IProvideEntropy provideEntropy;
            RandomNumberGenerator randomNumberGenerator;
            Random random;

            /* NO RESULT */
            GetRandomInstances(
                out provideEntropy, out randomNumberGenerator, out random);

            return RuntimeOps.GetRandomNumber(
                provideEntropy, randomNumberGenerator, random);
        }
        #endregion
        #endregion
        #endregion

