#if WINFORMS
        /// <summary>
        /// This method invokes the chain of key event handlers registered for
        /// the specified event type, for both this interpreter and the status
        /// form.
        /// </summary>
        /// <param name="eventType">
        /// The type of key event being handled.
        /// </param>
        /// <param name="sender">
        /// The object that raised the key event.
        /// </param>
        /// <param name="e">
        /// The event arguments associated with the key event.
        /// </param>
        /// <param name="count">
        /// On input, the initial count of handlers invoked.  Upon return, this
        /// will be increased by the number of handlers invoked.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        public ReturnCode FireKeyEventHandlers(
            EventType eventType,
            object sender,
            EventArgs e,
            ref int count,
            ref Result error
            )
        {
            CheckDisposed();

            ReturnCode code = ReturnCode.Ok;

            KeyOps.ChainEventHandlers(eventType,
                sender, e, null, null, ref count,
                ref code, ref error, GetKeyEventMap(),
                StatusFormOps.GetKeyEventMap());

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a key event mapping exists for the
        /// specified event type, modifier keys, and keys.
        /// </summary>
        /// <param name="eventType">
        /// The type of key event to query.
        /// </param>
        /// <param name="modifiers">
        /// The modifier keys to query.
        /// </param>
        /// <param name="keys">
        /// The keys to query.
        /// </param>
        /// <param name="useOverrides">
        /// True to query the interpreter-specific key event mappings, false to
        /// query the status form key event mappings, or null to query the
        /// interpreter-specific mappings first and then fall back to the status
        /// form mappings.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the mapping exists;
        /// <see cref="ReturnCode.Error" /> otherwise.
        /// </returns>
        public ReturnCode HasKeyEventMapping(
            EventType eventType,
            Keys modifiers,
            Keys keys,
            bool? useOverrides,
            ref Result error
            )
        {
            CheckDisposed();

            KeyOps.KeyEventMap keyEventMap = GetKeyEventMap(useOverrides);

            if (keyEventMap == null)
            {
                error = "key event data unavailable";
                return ReturnCode.Error;
            }

            return keyEventMap.Has(eventType, modifiers, keys, ref error) ?
                ReturnCode.Ok : ReturnCode.Error;
        }

