        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the key event mappings selected according to the
        /// specified override preference.
        /// </summary>
        /// <param name="useOverrides">
        /// True to return the interpreter-specific key event mappings, false to
        /// return the status form key event mappings, or null to return the
        /// interpreter-specific mappings if available and otherwise the status
        /// form mappings.
        /// </param>
        /// <returns>
        /// The selected key event mappings, or null if there are none.
        /// </returns>
        internal KeyOps.KeyEventMap GetKeyEventMap(
            bool? useOverrides
            )
        {
            KeyOps.KeyEventMap keyEventMap;

            if (useOverrides != null)
            {
                keyEventMap = (bool)useOverrides ?
                    GetKeyEventMap() : StatusFormOps.GetKeyEventMap();
            }
            else
            {
                keyEventMap = GetKeyEventMap();

                if (keyEventMap == null)
                    keyEventMap = StatusFormOps.GetKeyEventMap();
            }

            return keyEventMap;
        }
