                    notifyFlags = value;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets a value indicating whether global event notifications
        /// are enabled for this interpreter.
        /// </summary>
        public bool GlobalNotify
        {
            get
            {
                CheckDisposed();

                return PrivateGlobalNotify;
            }
            set
            {
                CheckDisposed();

                Interlocked.Exchange(ref notify, value ? 1 : 0);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the notification types enabled for this interpreter,
