                CheckDisposed();

                PrivateNotifyTypes = value;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the notification sub-type flags enabled for this
        /// interpreter, including any per-thread flags.
        /// </summary>
        public NotifyFlags NotifyFlags
        {
