        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// Gets a value indicating whether global event notifications should
        /// currently be fired for this interpreter; this returns false if the
        /// interpreter has been disposed.
        /// </summary>
        internal bool ShouldGlobalNotify
        {
            get
            {
                if (disposed)
                    return false;

                return PrivateGlobalNotify;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets a value indicating whether global event notifications are
        /// enabled for this interpreter.
        /// </summary>
        private bool PrivateGlobalNotify
        {
            get
            {
                // lock (syncRoot) /* NO-LOCK */
                {
                    return Interlocked.CompareExchange(ref notify, 0, 0) != 0;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the notification types enabled for this interpreter,
        /// combining the global types with any per-thread types.
        /// </summary>
        private NotifyType PrivateNotifyTypes
        {
            get
            {
                // lock (syncRoot) /* NO-LOCK */
                {
#if THREADING
                    IEngineContext context = GetEngineContext();

                    if (context != null)
                        return notifyTypes | context.NotifyTypes;
                    else
                        return notifyTypes;
#else
                    return notifyTypes;
#endif
                }
            }
            set
            {
#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    context.NotifyTypes = value;
#else
                // lock (syncRoot) /* NO-LOCK */
                {
                    notifyTypes = value;
                }
#endif
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the notification sub-type flags enabled for this
        /// interpreter, combining the global flags with any per-thread flags.
        /// </summary>
        private NotifyFlags PrivateNotifyFlags
        {
            get
            {
                // lock (syncRoot) /* NO-LOCK */
                {
#if THREADING
                    IEngineContext context = GetEngineContext();

                    if (context != null)
                        return notifyFlags | context.NotifyFlags;
                    else
                        return notifyFlags;
#else
                    return notifyFlags;
#endif
                }
            }
            set
            {
#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    context.NotifyFlags = value;
#else
                // lock (syncRoot)
                {
                    notifyFlags = value;
                }
#endif
            }
        }
        #endregion
#endif
