        #region IPackageManager Members
        /// <summary>
        /// This method scans the specified paths (or the auto-path) for package
        /// index files, adding any packages found to this interpreter.
        /// </summary>
        /// <param name="paths">
        /// The list of paths to scan, or null to scan the auto-path.
        /// </param>
        /// <param name="autoPath">
        /// Non-zero to include the auto-path when scanning for package index
        /// files.
        /// </param>
        /// <param name="indexes">
        /// Upon return, this will have the file names of the package index
        /// files that were found appended to it.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        public ReturnCode ScanPackages(
            StringList paths,
            bool autoPath,
            ref StringList indexes,
            ref Result error
            )
        {
            CheckDisposed();

            return PkgScan(
                this, paths, autoPath, ref indexes, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method verifies that the specified package is not currently
        /// present (i.e. loaded) in this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The version of the package to check for, or null to check for any
        /// version.
        /// </param>
        /// <param name="exact">
        /// Non-zero if the version must match exactly.
        /// </param>
        /// <param name="result">
        /// Upon failure, this will contain an appropriate error message,
        /// including the case where the package is present.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the package is absent;
        /// <see cref="ReturnCode.Error" /> otherwise.
        /// </returns>
        public ReturnCode AbsentPackage(
            string name,
            Version version,
            bool exact,
            ref Result result
            )
        {
            CheckDisposed();

            return PkgAbsent(
                name, version, _ClientData.Empty, PackageFlags.None,
                exact, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method verifies that the specified package is currently present
        /// (i.e. loaded) in this interpreter, returning its loaded version.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The version of the package to check for, or null to check for any
        /// version.
        /// </param>
        /// <param name="exact">
        /// Non-zero if the version must match exactly.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the loaded version of the package.
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the package is present;
        /// <see cref="ReturnCode.Error" /> otherwise.
        /// </returns>
        public ReturnCode PresentPackage(
            string name,
            Version version,
            bool exact,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result))
                    return ReturnCode.Error;

                IPackage package = null;

                if (GetPackage(
                        name, LookupFlags.NoVerbose,
                        ref package) != ReturnCode.Ok)
                {
                    result = String.Format(
                        "package {0} is not present",
                        FormatOps.PackageName(name, version));

                    return ReturnCode.Error;
                }

                if (package == null) /* IMPOSSIBLE? */
                {
                    result = String.Format(
                        "package {0} is invalid",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                Version loaded = package.Loaded;

                if (loaded == null)
                {
                    result = String.Format(
                        "package {0} is not present",
                        FormatOps.PackageName(name, version));

                    return ReturnCode.Error;
                }

                if (!PackageOps.VersionSatisfies(
                        loaded, version, exact))
                {
                    result = String.Format(
                        "package {0} is not present",
                        FormatOps.PackageName(name, version));

                    return ReturnCode.Error;
                }

                result = loaded;
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method declares that the specified version of a package is now
        /// provided (i.e. loaded) by this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The version of the package being provided.
        /// </param>
        /// <param name="result">
        /// Upon success, this may contain the version of the package that was
        /// already provided.  Upon failure, this will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        public ReturnCode ProvidePackage(
            string name,
            Version version,
            ref Result result
            )
        {
            CheckDisposed();

            return PkgProvide(
                name, version, _ClientData.Empty, PackageFlags.None,
                ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method ensures that the specified package is present in this
        /// interpreter, loading it if necessary, and returns its loaded
        /// version.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The minimum version of the package required, or null for any
        /// version.
        /// </param>
        /// <param name="exact">
        /// Non-zero if the version must match exactly.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the loaded version of the package.
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        public ReturnCode RequirePackage(
            string name,
            Version version,
            bool exact,
            ref Result result
            )
        {
            CheckDisposed();

            return PkgRequire(
                name, version, _ClientData.Empty, PackageFlags.None,
                exact, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method withdraws (i.e. unprovides) the specified version of a
        /// package that was previously provided by this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The version of the package to withdraw, or null to query the
        /// provided version without withdrawing it.
        /// </param>
        /// <param name="result">
        /// Upon success, this may contain the provided version of the package.
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        public ReturnCode WithdrawPackage(
            string name,
            Version version,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result))
                    return ReturnCode.Error;

                IPackage package = null;

                if (GetPackage(
                        name, LookupFlags.NoVerbose,
                        ref package) != ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't find package {0}",
                        FormatOps.PackageName(name, version));

                    return ReturnCode.Error;
                }

                if (package == null) /* IMPOSSIBLE? */
                {
                    result = String.Format(
                        "package {0} is invalid",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                Version loaded = package.Loaded;

                if (version != null)
                {
                    if (loaded != null)
                    {
                        if (PackageOps.VersionCompare(
                                loaded, version) == 0)
                        {
                            //
                            // NOTE: This version of the package is
                            //       now "withdrawn".
                            //
                            package.Loaded = null;

                            result = String.Empty;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            //
                            // NOTE: This is an error, a different
                            //       version of this package has
                            //       been provided.
                            //
                            result = String.Format(
                                "conflicting versions withdrawn for package {0}: " +
                                "{1} then {2} ", FormatOps.DisplayName(name),
                                loaded, version);

                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        //
                        // NOTE: Do nothing, the package has
                        //       already been unprovided.
                        //
                        result = String.Empty;
                        return ReturnCode.Ok;
                    }
                }
                else
                {
                    //
                    // NOTE: Do nothing, just return the version of
                    //       the package that has been provided.
                    //
                    if (loaded != null)
                        result = loaded;
                    else
                        result = String.Empty;

                    return ReturnCode.Ok;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method returns the package context client data currently
        /// associated with this interpreter, if any.
        /// </summary>
        /// <returns>
        /// The package context client data, or null if there is none.
        /// </returns>
        private PackageContextClientData GetPackageContext()
        {
            return ContextClientData as PackageContextClientData;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether packages are available via the
        /// current package context, falling back to the interpreter package
        /// collection if there is no active context.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// True if packages are available; otherwise, false.
        /// </returns>
        private bool HasPackagesViaContext(
            ref Result error
            )
        {
            PackageContextClientData packageContext = GetPackageContext();

            if (packageContext != null)
                return packageContext.HasPackages(ref error);

            return PrivateHasPackages(ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a package by name via the current package
        /// context, falling back to the interpreter package collection if there
        /// is no active context.
        /// </summary>
        /// <param name="name">
        /// The name of the package to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the package is looked up.
        /// </param>
        /// <param name="package">
        /// Upon success, this will contain the package that was found.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private ReturnCode GetPackageViaContext(
            string name,
            LookupFlags lookupFlags,
            ref IPackage package
            )
        {
            PackageContextClientData packageContext = GetPackageContext();

            if (packageContext != null)
            {
                Result error = null; /* IGNORED */

                return packageContext.GetPackage(
                    name, lookupFlags, ref package, ref error);
            }

            return GetPackage(name, lookupFlags, ref package);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds a package via the current package context, falling
        /// back to the interpreter package collection if there is no active
        /// context.
        /// </summary>
        /// <param name="package">
        /// The package to add.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to associate with the package.
        /// </param>
        /// <param name="result">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private ReturnCode AddPackageViaContext(
            IPackage package,
            IClientData clientData,
            ref Result result
            )
        {
            PackageContextClientData packageContext = GetPackageContext();

            if (packageContext != null)
            {
                return packageContext.AddPackage(
                    package, clientData, ref result);
            }

            return AddPackage(package, clientData, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if APPDOMAINS || ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
        /// <summary>
        /// This method determines whether this interpreter is configured to
        /// probe for plugins.
        /// </summary>
        /// <returns>
        /// True if plugin probing is enabled; otherwise, false.
        /// </returns>
        internal bool HasProbePlugins()
        {
            return FlagOps.HasFlags(createFlags, CreateFlags.ProbePlugins, true);
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter currently has
        /// pending package indexes.
        /// </summary>
        /// <returns>
        /// True if there are pending package indexes; otherwise, false.
        /// </returns>
        internal bool HasPendingPackageIndexes()
        {
            return FlagOps.HasFlags(InterpreterStateFlagsNoLock,
                InterpreterStateFlags.PendingPackageIndexes, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks this interpreter as having pending package
        /// indexes, saving the previous interpreter state flags so they can
        /// later be restored.
        /// </summary>
        /// <param name="savedInterpreterStateFlags">
        /// Upon return, this will contain the interpreter state flags that were
        /// in effect prior to this call.
        /// </param>
        internal void BeginPendingPackageIndexes(
            out InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            savedInterpreterStateFlags = ContextInterpreterStateFlags;
            ContextInterpreterStateFlags |= InterpreterStateFlags.PendingPackageIndexes;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the interpreter state flags previously saved by
        /// <c>BeginPendingPackageIndexes</c>, clearing the pending package
        /// indexes mark.
        /// </summary>
        /// <param name="savedInterpreterStateFlags">
        /// On input, the interpreter state flags to restore.  Upon return, this
        /// will be reset to <see cref="InterpreterStateFlags.None" />.
        /// </param>
        internal void EndPendingPackageIndexes(
            ref InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            ContextInterpreterStateFlags = savedInterpreterStateFlags;
            savedInterpreterStateFlags = InterpreterStateFlags.None;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a copy of the package indexes currently
        /// associated with this interpreter.
        /// </summary>
        /// <returns>
        /// A copy of the package indexes, or null if there are none.
        /// </returns>
        internal PackageIndexDictionary CopyPackageIndexes()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (packageIndexes != null)
                    return new PackageIndexDictionary(packageIndexes);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For AutoPathTraceCallback / [package] use only.
        //
        /// <summary>
        /// Sets the package indexes associated with this interpreter.  This
        /// property is intended for use by the auto-path trace callback and the
        /// <c>[package]</c> command only.
        /// </summary>
        internal PackageIndexDictionary PackageIndexes
        {
            set { lock (syncRoot) { packageIndexes = value; } }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: See the SetTemporaryPackages / UnsetTemporaryPackages
        //       methods, which are called from the package subsystem,
        //       namely the PackageOps.InvokeCallback method.  This is
        //       used to (possibly) include the temporary package flag
        //       for all newly created packages found while evaluating
        //       a script file, via its containing directory.
        //
        /// <summary>
        /// This method computes the flags to use for a newly created package,
        /// adding the temporary flag when temporary packages are currently in
        /// effect.
        /// </summary>
        /// <param name="flags">
        /// The base package flags supplied by the caller.
        /// </param>
        /// <returns>
        /// The package flags to use for the new package.
        /// </returns>
        private PackageFlags GetNewPackageFlags(
            PackageFlags flags
            )
        {
            PackageFlags result = (flags & PackageFlags.InstanceMask);

            if (IsTemporaryPackages())
                result |= PackageFlags.Temporary;

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the package indexes associated with this
        /// interpreter.
        /// </summary>
        /// <param name="strict">
        /// Non-zero to treat the absence of package indexes as an error.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode ResetPkgIndexes(
            bool strict,     /* in */
            ref Result error /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (PrivateHasPackageIndexes(ref localError))
                {
                    packageIndexes.Clear();
                }
                else if (strict)
                {
                    error = localError;
                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines the source file name of the package index or
        /// script currently being evaluated, in Unix path format.
        /// </summary>
        /// <param name="fileName">
        /// Upon success, this will contain the source file name.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private ReturnCode PkgSourceFileName(
            ref string fileName, /* out */
            ref Result error     /* out */
            )
        {
            string localFileName = null;

            if (ScriptOps.GetLocation(
                    this, true, false, ref localFileName,
                    ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            fileName = PathOps.GetUnixPath(localFileName);
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the package aliases defined in this interpreter
        /// that match the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to select which package aliases are returned, or
        /// null to select all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the matching package aliases.  Upon
        /// failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
