        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the names of the packages known to this
        /// interpreter that match the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to select which package names are returned, or null
        /// to select all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the matching package names.  Upon
        /// failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgNames(
            string pattern,
            bool noCase,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result))
                    return ReturnCode.Error;

                result = packages.ToString(pattern, noCase);
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the names of the packages currently loaded in
        /// this interpreter that match the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern used to select which loaded packages are returned, or
        /// null to select all of them.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to include detailed information about each loaded package.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the matching loaded packages.  Upon
        /// failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgLoaded(
            string pattern,
            bool noCase,
            bool verbose,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result))
                    return ReturnCode.Error;

                StringList list = new StringList();

                foreach (PackagePair pair in packages)
                {
                    IPackage package = pair.Value;

                    if (package == null)
                        continue;

                    Version loaded = package.Loaded;

                    if (loaded == null)
                        continue;

                    if (verbose)
                    {
                        VersionStringDictionary ifNeeded = package.IfNeeded;

                        list.Add(StringList.MakeList(
                            "name", pair.Key, "loaded", loaded, "flags",
                            package.Flags, "ifNeeded", (ifNeeded != null) ?
                                ifNeeded.Count : Count.Invalid));
                    }
                    else
                    {
                        list.Add(pair.Key);
                    }
                }

                result = list.ToString(pattern, noCase);
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the specified package from this interpreter,
        /// using a temporary result.  This overload is a convenience wrapper
        /// that discards any result produced.
        /// </summary>
        /// <param name="name">
        /// The name of the package to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, associated with the removal.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private ReturnCode PkgForget(
            string name,
            IClientData clientData
            )
        {
            Result result = null;

            return PkgForget(name, clientData, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the specified package from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the package to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, associated with the removal.
        /// </param>
        /// <param name="result">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgForget(
            string name,
            IClientData clientData,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result)) /* CONSISTENCY */
                    return ReturnCode.Error;

                if (DoesPackageExist(name) != ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't find package {0}",
                        FormatOps.PackageName(name, null));
                }

                if (RemovePackage(
                        name, clientData, ref result) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes each of the specified packages from this
        /// interpreter.
        /// </summary>
        /// <param name="names">
        /// The names of the packages to remove.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, associated with the removal.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain an empty string.  Upon failure, this
        /// will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgForget(
            StringList names,
            IClientData clientData,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result)) /* CONSISTENCY */
                    return ReturnCode.Error;

                if (names == null)
                {
                    result = "invalid package list";
                    return ReturnCode.Error;
                }

                foreach (string name in names)
                {
                    /* IGNORED */
                    PkgForget(name, clientData);
                }

                result = String.Empty;
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method queries or sets the "ifneeded" script associated with a
        /// specific version of a package; when a script is supplied it is
        /// stored, otherwise the stored script is returned.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The version of the package.
        /// </param>
        /// <param name="text">
        /// The "ifneeded" script to store for the package version, or null to
        /// query the currently stored script.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to associate with the package.
        /// </param>
        /// <param name="flags">
        /// The package flags that control how an existing package is handled.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the stored "ifneeded" script when
        /// querying, or an empty string when storing.  Upon failure, this will
        /// contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgIfNeeded(
            string name,
            Version version,
            string text,
            IClientData clientData,
            PackageFlags flags,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!HasPackagesViaContext(ref result)) /* CONSISTENCY */
                    return ReturnCode.Error;

                if (version == null)
                {
                    result = "invalid package version";
                    return ReturnCode.Error;
                }

                IPackage package; /* REUSED */
                string indexFileName; /* REUSED */

                if (text != null)
                {
                    ReturnCode code;

                    package = null;

                    if (GetPackageViaContext(
                            name, LookupFlags.NoVerbose,
                            ref package) != ReturnCode.Ok)
                    {
                        indexFileName = null;

                        if (PkgSourceFileName(
                                ref indexFileName,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        package = PackageOps.NewCore(
                            name, null, null, clientData,
                            indexFileName, null,
                            GetNewPackageFlags(flags),
                            null, null);

                        code = AddPackageViaContext(
                            package, clientData, ref result);
                    }
                    else if ((package != null) && FlagOps.HasFlags(
                            package.Flags, PackageFlags.Locked, true))
                    {
                        if (FlagOps.HasFlags(
                                package.Flags, PackageFlags.Rejected, true))
                        {
                            result = String.Format(
                                "rejected: package {0} is locked",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }
                        else
                        {
                            result = String.Empty;
                            return ReturnCode.Ok;
                        }
                    }
                    else if (FlagOps.HasFlags(
                            flags, PackageFlags.FailExisting, true))
                    {
                        result = String.Format(
                            "package {0} is already known",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                    else if (FlagOps.HasFlags(
                            flags, PackageFlags.KeepExisting, true))
                    {
                        result = String.Empty;
                        return ReturnCode.Ok;
                    }
                    else if (package == null) /* IMPOSSIBLE? */
                    {
                        result = String.Format(
                            "package {0} is invalid",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                    else
                    {
                        //
                        // HACK: Package is already present in the
                        //       collection.  Update the package
                        //       index file name to reflect the
                        //       current file being evaluated.
                        //
                        indexFileName = null;

                        if (PkgSourceFileName(
                                ref indexFileName,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        package.IndexFileName = indexFileName;
                        code = ReturnCode.Ok;
                    }

                    //
                    // NOTE: Make sure the package was -OR- that it
                    //       did not need to be.
                    //
                    if (code != ReturnCode.Ok)
                        return ReturnCode.Error;

                    if (package == null) /* IMPOSSIBLE? */
                    {
                        result = String.Format(
                            "package {0} is invalid",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }

                    VersionStringDictionary ifNeeded = package.IfNeeded;

                    if (ifNeeded != null)
                    {
                        ifNeeded[version] = text;
                        result = String.Empty;

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        result = String.Format(
                            "package {0} ifneeded scripts not available",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }
                }
                else
                {
                    package = null;

                    if (GetPackageViaContext(
                            name, LookupFlags.NoVerbose,
                            ref package) == ReturnCode.Ok)
                    {
                        if (package == null) /* IMPOSSIBLE? */
                        {
                            result = String.Format(
                                "package {0} is invalid",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }

                        VersionStringDictionary ifNeeded = package.IfNeeded;

                        if (ifNeeded != null)
                        {
                            string localText;

                            if (ifNeeded.TryGetValue(
                                    version, out localText))
                            {
                                result = localText;
                            }
                            else
                            {
                                result = String.Empty;
                            }

                            return ReturnCode.Ok;
                        }
                        else
                        {
                            result = String.Format(
                                "package {0} ifneeded scripts not available",
                                FormatOps.WrapOrNull(name));

                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        //
                        // NOTE: There is no package.  This is not an error,
                        //       per se, according to native Tcl.
                        //
                        result = String.Empty;
                        return ReturnCode.Ok;
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the versions of the specified package for which
        /// "ifneeded" scripts are available in this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the available versions of the
        /// package.  Upon failure, this will contain an appropriate error
        /// message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgVersions(
            string name,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result)) /* CONSISTENCY */
                    return ReturnCode.Error;

                IPackage package = null;

                if (GetPackage(
                        name, LookupFlags.NoVerbose,
                        ref package) != ReturnCode.Ok)
                {
                    //
                    // NOTE: There is no package.  This is not an error,
                    //       per se, according to native Tcl.
                    //
                    result = String.Empty;
                    return ReturnCode.Ok;
                }

                if (package == null) /* IMPOSSIBLE? */
                {
                    result = String.Format(
                        "package {0} is invalid",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                VersionStringDictionary ifNeeded = package.IfNeeded;

                if (ifNeeded != null)
                    result = ifNeeded.ToString();
                else
                    result = String.Empty;

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method queries, adds, or removes a package alias.  When the
        /// name is null the alias is queried, when it is empty the alias is
        /// removed, and otherwise the alias is added or overwritten.
        /// </summary>
        /// <param name="alias">
        /// The name of the package alias.
        /// </param>
        /// <param name="name">
        /// The name of the package the alias refers to.  When null, the alias
        /// is queried; when empty, the alias is removed.
        /// </param>
        /// <param name="version">
        /// The version of the package the alias refers to, if any.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, associated with the alias.  This parameter
        /// is not currently used.
        /// </param>
        /// <param name="flags">
        /// The package flags, if any, to associate with the alias.
        /// </param>
        /// <param name="result">
        /// Upon success, this may contain the queried package alias.  Upon
        /// failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgAlias(
            string alias,           /* in */
            string name,            /* in: OPTIONAL */
            Version version,        /* in: OPTIONAL */
            IClientData clientData, /* in: NOT USED */
            PackageFlags? flags,    /* in */
            ref Result result       /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackageAliases(ref result)) /* CONSISTENCY */
                    return ReturnCode.Error;

                if (String.IsNullOrEmpty(alias))
                {
                    result = "invalid package alias name";
                    return ReturnCode.Error;
                }

                if (name == null)
                {
                    PackageAliasTriplet anyTriplet;

                    if (!packageAliases.TryGetValue(
                            alias, out anyTriplet))
                    {
                        result = String.Format(
                            "package alias {0} does not exist",
                            FormatOps.DisplayName(alias));

                        return ReturnCode.Error;
                    }

                    result = (anyTriplet != null) ?
                        anyTriplet.ToString() : null;
                }
                else if (name.Length != 0)
                {
                    if (!FlagOps.HasFlags(
                            flags, PackageFlags.Overwrite, true) &&
                        packageAliases.ContainsKey(alias))
                    {
                        result = String.Format(
                            "package alias {0} already exists",
                            FormatOps.DisplayName(alias));

                        return ReturnCode.Error;
                    }

                    if (flags != null)
                    {
                        PackageFlags localFlags = (PackageFlags)flags;

                        localFlags &= PackageFlags.AliasMask;

                        if (localFlags != PackageFlags.None)
                            flags = localFlags;
                        else
                            flags = null;
                    }

                    packageAliases[alias] = new PackageAliasTriplet(
                        name, version, flags);
                }
                else
                {
                    if (!packageAliases.Remove(alias))
                    {
                        result = String.Format(
                            "failed to remove package alias {0}",
                            FormatOps.DisplayName(alias));

                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method declares that the specified version of a package is
        /// provided (i.e. loaded) by this interpreter, creating the package if
        /// necessary.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The version of the package being provided.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, to associate with the package.
        /// </param>
        /// <param name="flags">
        /// The package flags that control how the package is provided.
        /// </param>
        /// <param name="result">
        /// Upon success, this may contain the version of the package that was
        /// already provided.  Upon failure, this will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgProvide(
            string name,
            Version version,
            IClientData clientData,
            PackageFlags flags,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result)) /* CONSISTENCY */
                    return ReturnCode.Error;

                string provideFileName; /* REUSED */
                IPackage package = null;

                if (GetPackage(
                        name, LookupFlags.NoVerbose,
                        ref package) == ReturnCode.Ok)
                {
                    if (package == null) /* IMPOSSIBLE? */
                    {
                        result = String.Format(
                            "package {0} is invalid",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }

                    Version loaded = package.Loaded;

                    if (version != null)
                    {
                        if (loaded == null)
                        {
                            provideFileName = null;

                            if (PkgSourceFileName(
                                    ref provideFileName,
                                    ref result) != ReturnCode.Ok)
                            {
                                return ReturnCode.Error;
                            }

                            //
                            // NOTE: This version of the package is
                            //       now "provided".
                            //
                            package.ProvideFileName = provideFileName;
                            package.Loaded = version;

                            //
                            // NOTE: Update the package flags with the
                            //       ones provided by the caller, if
                            //       any, unless we are forbidden from
                            //       doing so.
                            //
                            if (!FlagOps.HasFlags(
                                    flags, PackageFlags.NoUpdate, true))
                            {
                                package.Flags |=
                                    (flags & PackageFlags.InstanceMask);
                            }

                            result = String.Empty;
                            return ReturnCode.Ok;
                        }
                        else if (PackageOps.VersionCompare(
                                loaded, version) != 0)
                        {
                            //
                            // NOTE: This is an error, a different
                            //       version of this package has
                            //       already been provided.
                            //
                            result = String.Format(
                                "conflicting versions provided for package {0}: " +
                                "{1} then {2} ", FormatOps.WrapOrNull(name),
                                FormatOps.WrapOrNull(loaded),
                                FormatOps.WrapOrNull(version));
                        }
                        else
                        {
                            //
                            // NOTE: Do nothing, the identical
                            //       version has already been
                            //       provided.
                            //
                            result = String.Empty;
                            return ReturnCode.Ok;
                        }
                    }
                    else
                    {
                        //
                        // NOTE: Do nothing, just return the
                        //       version of the package that
                        //       has been provided.
                        //
                        if (loaded != null)
                            result = loaded;
                        else
                            result = String.Empty;

                        return ReturnCode.Ok;
                    }
                }
                else if (version != null)
                {
                    provideFileName = null;

                    if (PkgSourceFileName(
                            ref provideFileName,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    //
                    // NOTE: We have never seen this package
                    //       before.  Create a new package
                    //       and mark it as loaded.
                    //
                    if (AddPackage(PackageOps.NewCore(
                            name, null, null, clientData,
                            null, provideFileName,
                            GetNewPackageFlags(flags),
                            version, null), clientData,
                            ref result) == ReturnCode.Ok)
                    {
                        result = String.Empty;
                        return ReturnCode.Ok;
                    }
                }
                else
                {
                    result = "invalid package version";
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method verifies that the specified package is not currently
        /// provided (i.e. loaded) in this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The version of the package to check for, or null to check for any
        /// version.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, associated with the check.
        /// </param>
        /// <param name="flags">
        /// The package flags, if any, associated with the check.
        /// </param>
        /// <param name="exact">
        /// Non-zero if the version must match exactly.
        /// </param>
        /// <param name="result">
        /// Upon failure, this will contain an appropriate error message,
        /// including the case where the package is provided.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the package is absent;
        /// <see cref="ReturnCode.Error" /> otherwise.
        /// </returns>
        internal ReturnCode PkgAbsent(
            string name,
            Version version,
            IClientData clientData,
            PackageFlags flags,
            bool exact,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result))
                    return ReturnCode.Error;

                IPackage package = null;

                if (GetPackage(
                        name, LookupFlags.NoVerbose,
                        ref package) == ReturnCode.Ok)
                {
                    if (package == null) /* IMPOSSIBLE? */
                    {
                        result = String.Format(
                            "package {0} is invalid",
                            FormatOps.WrapOrNull(name));

                        return ReturnCode.Error;
                    }

                    Version loaded = package.Loaded;

                    if ((version == null) ||
                        PackageOps.VersionSatisfies(loaded, version, exact))
                    {
                        result = String.Format(
                            "package {0} is not absent: " +
                            "package {1} provided",
                            FormatOps.PackageName(name, version),
                            FormatOps.PackageName(name, loaded));

                        return ReturnCode.Error;
                    }
                }

                result = string.Empty;
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves the specified package name through the package
        /// alias chain, if any, updating the name, version, and exact-match
        /// preference accordingly while guarding against alias loops.
        /// </summary>
        /// <param name="name">
        /// On input, the package name to resolve.  Upon return, this may
        /// contain the resolved package name.
        /// </param>
        /// <param name="version">
        /// On input, the requested package version, if any.  Upon return, this
        /// may contain the version supplied by the resolved alias.
        /// </param>
        /// <param name="exact">
        /// On input, the exact-match preference.  Upon return, this may be
        /// updated according to the resolved alias.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// True on success; otherwise, false.
        /// </returns>
        private bool MaybeUsePackageAliases(
            ref string name,     /* in, out */
            ref Version version, /* in, out */
            ref bool exact,      /* in, out */
            ref Result error     /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if ((name != null) && PrivateHasPackageAliases())
                {
                    PackageAliasDictionary found =
                        new PackageAliasDictionary();

                    string localName = name;
                    Version localVersion = null;
                    PackageFlags? localFlags = null;

                    while (true)
                    {
                        PackageAliasTriplet anyTriplet;

                        if ((localName == null) ||
                            !packageAliases.TryGetValue(
                                localName, out anyTriplet))
                        {
                            break;
                        }

                        if (anyTriplet == null)
                        {
                            error = String.Format(
                                "package alias {0} (via {1}) is unavailable",
                                FormatOps.DisplayName(name),
                                FormatOps.DisplayName(localName));

                            return false;
                        }

                        if (FlagOps.HasFlags(
                                anyTriplet.Z, PackageFlags.Disabled, true))
                        {
                            error = String.Format(
                                "package alias {0} (via {1}) is disabled",
                                FormatOps.DisplayName(name),
                                FormatOps.DisplayName(localName));

                            return false;
                        }

                        string temporaryName = anyTriplet.X;

                        if (temporaryName == null)
                        {
                            error = String.Format(
                                "package alias {0} (via {1}) has invalid name",
                                FormatOps.DisplayName(name),
                                FormatOps.DisplayName(localName));

                            return false;
                        }

                        if (found.ContainsKey(temporaryName))
                        {
                            error = String.Format(
                                "package alias {0} (via {1}) loop detected",
                                FormatOps.DisplayName(name),
                                FormatOps.DisplayName(localName));

                            return false;
                        }

                        found[localName] = anyTriplet;

                        localName = temporaryName;
                        localVersion = anyTriplet.Y;
                        localFlags = anyTriplet.Z;
                    }

                    if (found.Count > 0)
                    {
                        name = localName;

                        if ((version == null) && (localVersion != null))
                            version = localVersion;

                        if (localFlags != null)
                        {
                            exact = FlagOps.HasFlags(
                                localFlags, PackageFlags.Exact, true);
                        }
                    }
                }

                return true;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method ensures that the specified package is present in this
        /// interpreter, resolving any package aliases and loading the package
        /// if necessary, and returns its loaded version.
        /// </summary>
        /// <param name="name">
        /// The name of the package.
        /// </param>
        /// <param name="version">
        /// The minimum version of the package required, or null for any
        /// version.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, associated with the request.
        /// </param>
        /// <param name="flags">
        /// The package flags, if any, associated with the request.
        /// </param>
        /// <param name="exact">
        /// Non-zero if the version must match exactly.
        /// </param>
        /// <param name="result">
        /// Upon success, this will contain the loaded version of the package.
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal ReturnCode PkgRequire(
            string name,
            Version version,
            IClientData clientData,
            PackageFlags flags,
            bool exact,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPackages(ref result))
                    return ReturnCode.Error;

                if (!FlagOps.HasFlags(
                        packageFlags, PackageFlags.NoAlias, true) &&
                    !MaybeUsePackageAliases(
                        ref name, ref version, ref exact, ref result))
                {
                    return ReturnCode.Error;
                }

                IPackage package = null;

                if (GetPackage(
                        name, LookupFlags.NoVerbose,
                        ref package) != ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't find package {0}",
                        FormatOps.PackageName(name, version));

                    return ReturnCode.Error;
                }

                if (package == null) /* IMPOSSIBLE? */
                {
                    result = String.Format(
                        "package {0} is invalid",
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

                Version loaded = package.Loaded;

                if (loaded != null)
                    goto loaded;

                //
                // NOTE: Attempt to load the package using the provided
                //       script.
                //
                try
                {
                    Version best = null;

                    if (package.Select(
                            PackagePreference.Default, ref best,
                            ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    if (package.Load(
                            this, best, ref result) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
                catch (Exception e)
                {
                    result = String.Format(
                        "caught exception while loading package: {0}",
                        e);

                    return ReturnCode.Error;
                }

                loaded = package.Loaded; /* REFRESH */

                if (loaded == null)
                {
                    result = String.Format(
                        "attempt to provide package {0} failed: " +
                        "no version of package {1} provided",
                        FormatOps.PackageName(name, version),
                        FormatOps.WrapOrNull(name));

                    return ReturnCode.Error;
                }

            loaded:

                if ((version != null) &&
                    !PackageOps.VersionSatisfies(loaded, version, exact))
                {
                    result = String.Format(
                        "attempt to provide package {0} failed: " +
                        "package {1} provided instead",
                        FormatOps.PackageName(name, version),
                        FormatOps.PackageName(name, loaded));

                    return ReturnCode.Error;
                }

                result = loaded;
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method automatically scans for packages in the specified
        /// interpreter by evaluating the generated package scan script.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to perform the scan.
        /// </param>
        /// <param name="paths">
        /// The list of paths to scan, or null to scan the default paths.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        internal static ReturnCode PkgAutoScan(
            Interpreter interpreter, /* in */
            PathList paths,          /* in: OPTIONAL */
            ref Result error         /* out */
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            string text = PackageOps.GetScanCommand(
                interpreter, null, paths, ref error);

            if (text == null)
                return ReturnCode.Error;

            ReturnCode code;
            Result result = null;

            code = interpreter.EvaluateScript(
                text, ref result);

            if (code != ReturnCode.Ok)
                error = result;

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method scans the specified paths (or the auto-path) for package
        /// index files in the specified interpreter, using a temporary list of
        /// indexes.  This overload is a convenience wrapper that discards the
        /// list of index file names found.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to perform the scan.
        /// </param>
        /// <param name="paths">
        /// The list of paths to scan, or null to scan the auto-path.
        /// </param>
        /// <param name="autoPath">
        /// Non-zero to include the auto-path when scanning for package index
        /// files.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private static ReturnCode PkgScan(
            Interpreter interpreter,
            StringList paths,
            bool autoPath,
            ref Result error
            )
        {
            StringList indexes = null; /* NOT USED */

            return PkgScan(
                interpreter, paths, autoPath, ref indexes, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method scans the specified paths (or the auto-path) for package
        /// index files in the specified interpreter, recording the index file
        /// names that are found.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to perform the scan.
        /// </param>
        /// <param name="paths">
        /// The list of paths to scan, or null to scan the auto-path.
        /// </param>
        /// <param name="autoPath">
        /// Non-zero to include the auto-path when scanning for package index
        /// files.
        /// </param>
        /// <param name="indexes">
        /// Upon return, this will have the file names of the package index
        /// files that were found appended to it.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private static ReturnCode PkgScan(
            Interpreter interpreter,
            StringList paths,
            bool autoPath,
            ref StringList indexes,
            ref Result error
            )
        {
            if (interpreter == null)
            {
                error = "invalid interpreter";
                return ReturnCode.Error;
            }

            PathComparisonType type;
            PackageIndexFlags flags;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                type = interpreter.PrivatePathComparisonType;
                flags = interpreter.PrivatePackageIndexFlags;
            }

            StringList localPaths = (paths != null) ? paths :
                GlobalState.GetAutoPathList(interpreter, autoPath);

            PackageIndexDictionary packageIndexes =
                interpreter.CopyPackageIndexes();

            if (PackageOps.FindAll(
                    interpreter, localPaths, flags, type,
                    ref packageIndexes, ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (packageIndexes != null)
            {
                StringList fileNames =
                    packageIndexes.GetKeysInOrder(false);

                if (indexes != null)
                    indexes.AddRange(fileNames);
                else
                    indexes = new StringList(fileNames);
            }

            interpreter.PackageIndexes = packageIndexes;
            return ReturnCode.Ok;
        }
