        /// <summary>
        /// This method adds a named plugin argument to this interpreter, unless
        /// an argument with the same name already exists.
        /// </summary>
        /// <param name="name">
        /// The name of the plugin argument to add.
        /// </param>
        /// <param name="value">
        /// The value of the plugin argument to add.
        /// </param>
        /// <returns>
        /// The number of plugin arguments that were added.
        /// </returns>
        public int AddPluginArguments(
            string name,
            string value
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                int count = 0;

                if (!IsModifiable(true))
                    return count;

                if (String.IsNullOrEmpty(name))
                    return count;

                if ((pluginArguments != null) &&
                    !pluginArguments.ContainsKey(name)) /* EXEMPT */
                {
                    pluginArguments.Add(name, value);
                    count++;
                }

                return count;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the plugin arguments whose names match the
        /// specified pattern from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The pattern used to match the names of the plugin arguments to
        /// remove.
        /// </param>
        /// <returns>
        /// The number of plugin arguments that were removed.
        /// </returns>
        public int RemovePluginArguments(
            string name
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                int count = 0;

                if (!IsModifiable(false))
                    return count;

                if (String.IsNullOrEmpty(name))
                    return count;

                if (pluginArguments != null)
                {
                    StringList keys = new StringList(pluginArguments.Keys);

                    foreach (string key in keys)
                    {
                        if (StringOps.Match(
                                this, MatchMode.Glob, name, key, false) &&
                            pluginArguments.Remove(key))
                        {
                            count++;
                        }
                    }
                }

                return count;
            }
        }

