        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes all of the commands (and hidden commands)
        /// provided by the specified plugin from this interpreter.
        /// </summary>
        /// <param name="plugin">
        /// The plugin whose commands are to be removed.
        /// </param>
        /// <param name="clientData">
        /// The extra data, if any, associated with the removal.
        /// </param>
        /// <param name="flags">
        /// The flags associated with the removal.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        public ReturnCode RemoveCommands(
            IPlugin plugin,
            IClientData clientData,
            CommandFlags flags,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (plugin != null)
                {
                    LongList localTokens = plugin.CommandTokens;

                    if (localTokens != null)
                        localTokens = (LongList)localTokens.Clone();

                    if (localTokens != null)
                    {
                        ReturnCode code;
                        Result localResult; /* REUSED */

                        foreach (long token in localTokens)
                        {
                            if (PrivateDoesCommandExist(token) == ReturnCode.Ok)
                            {
                                localResult = null;

                                code = RemoveCommand(
                                    token, clientData, ref localResult);

                                if (code != ReturnCode.Ok)
                                {
                                    error = localResult;
                                    return code;
                                }
                            }
                            else if (PrivateDoesHiddenCommandExist(token) == ReturnCode.Ok)
                            {
                                localResult = null;

                                code = InternalRemoveHiddenCommand(
                                    token, clientData, ref localResult);

                                if (code != ReturnCode.Ok)
                                {
                                    error = localResult;
                                    return code;
                                }
                            }
                            else
                            {
                                //
                                // NOTE: We must actually ignore "failures" here because,
                                //       in theory, the command could have been removed
                                //       using the [rename] script command or some other
                                //       mechanism.
                                //
                            }
                        }
                    }

                    return ReturnCode.Ok;
                }
                else
                {
                    error = "invalid plugin";
                }

                return ReturnCode.Error;
            }
        }

