        /// <summary>
        /// This method finds a loaded plugin matching the specified criteria,
        /// using a temporary result.  This overload is a convenience wrapper
        /// that discards any error message produced.
        /// </summary>
        /// <param name="appDomain">
        /// The application domain to which the plugin must belong, or null to
        /// match plugins in any application domain.
        /// </param>
        /// <param name="mode">
        /// The matching mode used to compare the pattern against plugin names.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match plugin names.
        /// </param>
        /// <param name="version">
        /// The version the plugin must have, or null to match any version.
        /// </param>
        /// <param name="publicKeyToken">
        /// The public key token the plugin assembly must have, or null to match
        /// any public key token.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the plugin is looked up.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <returns>
        /// The matching plugin, or null if no matching plugin was found.
        /// </returns>
        internal IPlugin InternalFindPlugin(
            AppDomain appDomain,
            MatchMode mode,
            string pattern,
            Version version,
            byte[] publicKeyToken,
            LookupFlags lookupFlags,
            bool noCase
            )
        {
            Result error = null;

            return InternalFindPlugin(
                appDomain, mode, pattern, version, publicKeyToken,
                lookupFlags, noCase, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method finds a loaded plugin matching the specified criteria.
        /// </summary>
        /// <param name="appDomain">
        /// The application domain to which the plugin must belong, or null to
        /// match plugins in any application domain.
        /// </param>
        /// <param name="mode">
        /// The matching mode used to compare the pattern against plugin names.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match plugin names.
        /// </param>
        /// <param name="version">
        /// The version the plugin must have, or null to match any version.
        /// </param>
        /// <param name="publicKeyToken">
        /// The public key token the plugin assembly must have, or null to match
        /// any public key token.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the plugin is looked up.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// The matching plugin, or null if no matching plugin was found.
        /// </returns>
        internal IPlugin InternalFindPlugin(
            AppDomain appDomain,
            MatchMode mode,
            string pattern,
            Version version,
            byte[] publicKeyToken,
            LookupFlags lookupFlags,
            bool noCase,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasPlugins(ref error))
                    return null;

                foreach (PluginPair pair in plugins)
                {
                    IPlugin plugin = pair.Value;

                    if (plugin == null)
                        continue;

                    if (appDomain != null)
                    {
                        AppDomain pluginAppDomain = plugin.AppDomain;

                        if ((pluginAppDomain != null) &&
                            !AppDomainOps.IsSame(pluginAppDomain, appDomain))
                        {
                            continue;
                        }
                    }

                    AssemblyName assemblyName;

#if ISOLATED_PLUGINS
                    if (AppDomainOps.IsIsolated(plugin))
                    {
                        assemblyName = plugin.AssemblyName;
                    }
                    else
#endif
                    {
                        Assembly assembly = plugin.Assembly;

                        if (assembly == null)
                            continue;

                        assemblyName = assembly.GetName();
                    }

                    if (assemblyName == null)
                        continue;

                    if ((pattern != null) && !StringOps.Match(
                            this, mode, assemblyName.Name, pattern, noCase))
                    {
                        continue;
                    }

                    if ((version != null) &&
                        (PackageOps.VersionCompare(assemblyName.Version,
                            version) != 0))
                    {
                        continue;
                    }

                    if ((publicKeyToken != null) &&
                        !ArrayOps.Equals(
                            assemblyName.GetPublicKeyToken(), publicKeyToken))
                    {
                        continue;
                    }

                    if (!RuntimeOps.CheckPluginVersusLookupFlags(
                            plugin, lookupFlags))
                    {
                        continue;
                    }

                    return plugin;
                }
            }

            error = String.Format(
                "cannot find plugin matching {0} {1} - {2} version {3} " +
                "with public key token {4} in application domain {5} " +
                "and lookup flags {6}", noCase ? "case-insensitive" :
                "case-sensitive", FormatOps.WrapOrNull(mode),
                FormatOps.WrapOrNull(pattern), FormatOps.WrapOrNull(
                version), ArrayOps.ToHexadecimalString(publicKeyToken),
                FormatOps.DisplayAppDomain(appDomain), FormatOps.WrapOrNull(
                lookupFlags));

            return null;
        }

