        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method creates and adds a static plugin to this interpreter
        /// using the specified callback, populating its commands and policies.
        /// </summary>
        /// <param name="callback">
        /// The callback used to create the new static plugin.
        /// </param>
        /// <param name="types">
        /// The list of types used when populating the plugin entities.
        /// </param>
        /// <param name="ruleSet">
        /// The rule set, if any, used to constrain which entities are added.
        /// </param>
        /// <param name="commandFlags">
        /// The command flags, if any, required for a command to be added.
        /// </param>
        /// <param name="notCommandFlags">
        /// The command flags, if any, that prevent a command from being added.
        /// </param>
        /// <param name="useBuiltIn">
        /// Non-zero to use the built-in entity definitions instead of reading
        /// the managed type attributes.
        /// </param>
        /// <param name="noCommands">
        /// Non-zero to skip adding the commands provided by the plugin.
        /// </param>
        /// <param name="noPolicies">
        /// Non-zero to skip adding the policies provided by the plugin.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to produce verbose diagnostic output while setting up the
        /// plugin.
        /// </param>
        /// <param name="token">
        /// Upon success, this will contain the token identifying the added
        /// plugin.
        /// </param>
        /// <param name="name">
        /// Upon success, this will contain the name of the added plugin.
        /// </param>
        /// <param name="flags">
        /// Upon success, this will contain the flags of the added plugin.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private ReturnCode SetupPlugin(
            NewStaticPluginCallback callback, /* in */
            TypeList types,                   /* in */
            IRuleSet ruleSet,                 /* in */
            CommandFlags? commandFlags,       /* in */
            CommandFlags? notCommandFlags,    /* in */
            bool useBuiltIn,                  /* in */
            bool noCommands,                  /* in */
            bool noPolicies,                  /* in */
            bool verbose,                     /* in */
            ref long token,                   /* out */
            ref string name,                  /* out */
            ref PluginFlags flags,            /* out */
            ref Result error                  /* out */
            )
        {
            ReturnCode code;

            if (callback != null)
            {
                IPlugin plugin = callback();

                if (plugin != null)
                {
                    Result localResult = null;

                    code = RuntimeOps.PopulatePluginEntities(
                        this, plugin, types, ruleSet, commandFlags,
                        notCommandFlags, useBuiltIn, noCommands,
                        noPolicies, verbose, ref localResult);

                    if (code == ReturnCode.Ok)
                    {
                        long localToken = 0;

                        code = PrivateAddPlugin(
                            plugin, new PluginClientData(true,
                            useBuiltIn, null), false, false,
                            ref localToken, ref localResult);

                        if (code == ReturnCode.Ok)
                        {
                            token = localToken;
                            name = plugin.Name;
                            flags = plugin.Flags;
                        }
                        else
                        {
                            error = localResult;
                        }
                    }
                    else
                    {
                        error = localResult;
                    }
                }
                else
                {
                    error = String.Format(
                        "new plugin callback {0} failed",
                        FormatOps.WrapOrNull(
                            FormatOps.DelegateName(callback)));

                    code = ReturnCode.Error;
                }
            }
            else
            {
                error = "invalid new plugin callback";
                code = ReturnCode.Error;
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the built-in entity definitions
        /// should be used for the specified kind of identifier.
        /// </summary>
        /// <param name="kind">
        /// The kind of identifier to query.
        /// </param>
        /// <returns>
        /// True if the built-in definitions should be used for the specified
        /// kind of identifier; otherwise, false.
        /// </returns>
        internal static bool ShouldUseBuiltIns(
            IdentifierKind kind
            )
        {
            switch (kind)
            {
                case IdentifierKind.Command:
                    {
                        return useBuiltInCommands;
                    }
                case IdentifierKind.Function:
                    {
                        return useBuiltInFunctions;
                    }
                case IdentifierKind.Operator:
                    {
                        return useBuiltInOperators;
                    }
                default:
                    {
                        return false;
                    }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the required and forbidden command flags
        /// implied by the specified creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The creation flags used to determine the command flags.
        /// </param>
        /// <param name="commandFlags">
        /// Upon return, this will contain the command flags required for a
        /// command to be added, or null if there are none.
        /// </param>
        /// <param name="notCommandFlags">
        /// Upon return, this will contain the command flags that prevent a
        /// command from being added, or null if there are none.
        /// </param>
        private static void SetupCommandFlags(
            CreateFlags createFlags,
            out CommandFlags? commandFlags,
            out CommandFlags? notCommandFlags
            )
        {
            commandFlags = null;
            notCommandFlags = null;

            if (FlagOps.HasFlags(
                    createFlags, CreateFlags.SdkMask, false))
            {
                CommandFlags localCommandFlags = CommandFlags.None;

                if (FlagOps.HasFlags(
                        createFlags, CreateFlags.Initialize, true) &&
                    !FlagOps.HasFlags(
                        createFlags, CreateFlags.NoLibrary, true))
                {
                    localCommandFlags |= CommandFlags.Initialize;
                }

                if (FlagOps.HasFlags(
                        createFlags, CreateFlags.LicenseSdk, true))
                {
                    localCommandFlags |= CommandFlags.LicenseSdk;
                }

                if (FlagOps.HasFlags(
                        createFlags, CreateFlags.SecuritySdk, true))
                {
                    localCommandFlags |= CommandFlags.SecuritySdk;
                }

                commandFlags = localCommandFlags;
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (FlagOps.HasFlags(
                    createFlags, CreateFlags.NoCritical, true))
            {
                notCommandFlags = CommandFlags.Critical;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method creates and adds the built-in plugins (e.g. the core,
        /// object, monitor, and test plugins) to this interpreter, as permitted
        /// by the specified creation flags.  This method assumes the interpreter
        /// lock is held.
        /// </summary>
        /// <param name="ruleSet">
        /// The rule set, if any, used to constrain which entities are added.
        /// </param>
        /// <param name="types">
        /// The list of types used when populating the plugin entities.
        /// </param>
        /// <param name="createFlags">
        /// The creation flags that control which plugins are added.
        /// </param>
        /// <param name="commandFlags">
        /// The command flags, if any, required for a command to be added.
        /// </param>
        /// <param name="notCommandFlags">
        /// The command flags, if any, that prevent a command from being added.
        /// </param>
        /// <param name="force">
        /// Non-zero to add the plugins even if they have already been added.
        /// </param>
        /// <param name="useBuiltIn">
        /// Non-zero to use the built-in entity definitions instead of reading
        /// the managed type attributes.
        /// </param>
        /// <param name="noCommands">
        /// Non-zero to skip adding the commands provided by the plugins.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to produce verbose diagnostic output while setting up the
        /// plugins.
        /// </param>
        /// <param name="error">
        /// Upon failure, this will contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private ReturnCode SetupPlugins(
            IRuleSet ruleSet,              /* in */
            TypeList types,                /* in */
            CreateFlags createFlags,       /* in */
            CommandFlags? commandFlags,    /* in */
            CommandFlags? notCommandFlags, /* in */
            bool force,                    /* in */
            bool useBuiltIn,               /* in */
            bool noCommands,               /* in */
            bool verbose,                  /* in */
            ref Result error               /* out */
            )
        {
            if (!FlagOps.HasFlags(createFlags, CreateFlags.NoPlugins, true))
            {
                string pluginName; /* REUSED */
                PluginFlags pluginFlags; /* REUSED */
                bool nativeCode; /* REUSED */
                bool system; /* REUSED */

                if (!FlagOps.HasFlags(
                        createFlags, CreateFlags.NoCorePlugin, true))
                {
                    if (force || (corePluginToken == 0))
                    {
                        //
                        // HACK: The core plugin has no dynamically added policies.
                        //
                        pluginName = null;
                        pluginFlags = PluginFlags.None;

                        if (SetupPlugin(
                                NewCorePlugin, types, ruleSet,
                                commandFlags, notCommandFlags,
                                useBuiltIn, noCommands,
                                true, verbose, ref corePluginToken,
                                ref pluginName, ref pluginFlags,
                                ref error) == ReturnCode.Ok)
                        {
                            nativeCode = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.NativeCode, true);

                            system = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.System, true);

                            TraceOps.DebugTrace(String.Format(
                                "SetupPlugins: prepared/added {0} {1} core plugin {2}",
                                nativeCode ? "native" : "managed", system ? "system" : "user",
                                FormatOps.WrapOrNull(pluginName)), typeof(Interpreter).Name,
                                TracePriority.StartupDebug);
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

#if NOTIFY || NOTIFY_OBJECT
                if (!FlagOps.HasFlags(
                        createFlags, CreateFlags.NoObjectPlugin, true))
                {
                    if (force || (objectPluginToken == 0))
                    {
                        //
                        // HACK: The object plugin has no dynamically added policies.
                        //
                        pluginName = null;
                        pluginFlags = PluginFlags.None;

                        if (SetupPlugin(
                                NewObjectPlugin, types, ruleSet,
                                commandFlags, notCommandFlags,
                                false, true, true,
                                verbose, ref objectPluginToken,
                                ref pluginName, ref pluginFlags,
                                ref error) == ReturnCode.Ok)
                        {
                            nativeCode = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.NativeCode, true);

                            system = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.System, true);

                            TraceOps.DebugTrace(String.Format(
                                "SetupPlugins: prepared/added {0} {1} object plugin {2}",
                                nativeCode ? "native" : "managed", system ? "system" : "user",
                                FormatOps.WrapOrNull(pluginName)), typeof(Interpreter).Name,
                                TracePriority.StartupDebug);
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                }
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

#if NOTIFY && NOTIFY_ARGUMENTS
                if (!FlagOps.HasFlags(
                        createFlags, CreateFlags.NoMonitorPlugin, true))
                {
                    if (force || (monitorPluginToken == 0))
                    {
                        //
                        // HACK: The monitor plugin has no dynamically added policies.
                        //
                        pluginName = null;
                        pluginFlags = PluginFlags.None;

                        if (SetupPlugin(
                                NewMonitorPlugin, types, ruleSet,
                                commandFlags, notCommandFlags,
                                false, true, true,
                                verbose, ref monitorPluginToken,
                                ref pluginName, ref pluginFlags,
                                ref error) == ReturnCode.Ok)
                        {
                            nativeCode = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.NativeCode, true);

                            system = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.System, true);

                            TraceOps.DebugTrace(String.Format(
                                "SetupPlugins: prepared/added {0} {1} trace plugin {2}",
                                nativeCode ? "native" : "managed", system ? "system" : "user",
                                FormatOps.WrapOrNull(pluginName)), typeof(Interpreter).Name,
                                TracePriority.StartupDebug);
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                }
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

#if TEST_PLUGIN || DEBUG
                if (!FlagOps.HasFlags(
                        createFlags, CreateFlags.NoTestPlugin, true))
                {
                    if (force || (testPluginToken == 0))
                    {
                        //
                        // HACK: The test plugin has no dynamically added policies.
                        //
                        pluginName = null;
                        pluginFlags = PluginFlags.None;

                        if (SetupPlugin(
                                NewTestPlugin, types, ruleSet,
                                commandFlags, notCommandFlags,
                                false, true, true,
                                verbose, ref testPluginToken,
                                ref pluginName, ref pluginFlags,
                                ref error) == ReturnCode.Ok)
                        {
                            nativeCode = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.NativeCode, true);

                            system = FlagOps.HasFlags(
                                pluginFlags, PluginFlags.System, true);

                            TraceOps.DebugTrace(String.Format(
                                "SetupPlugins: prepared/added {0} {1} test plugin {2}",
                                nativeCode ? "native" : "managed", system ? "system" : "user",
                                FormatOps.WrapOrNull(pluginName)), typeof(Interpreter).Name,
                                TracePriority.StartupDebug);
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                }
#endif
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method restores a previously added static plugin in this
        /// interpreter, recreating it via the specified callback if it can no
        /// longer be found.
        /// </summary>
        /// <param name="callback">
        /// The callback used to recreate the static plugin if necessary.
        /// </param>
        /// <param name="useBuiltIn">
        /// Non-zero to use the built-in entity definitions instead of reading
        /// the managed type attributes.
        /// </param>
        /// <param name="noCommands">
        /// Non-zero to skip restoring the commands provided by the plugin.
        /// </param>
        /// <param name="noPolicies">
        /// Non-zero to skip restoring the policies provided by the plugin.
        /// </param>
        /// <param name="standardOnly">
        /// Non-zero to restore only the standard entities provided by the
        /// plugin.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat the inability to restore the plugin as an error.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to produce verbose diagnostic output while restoring the
        /// plugin.
        /// </param>
        /// <param name="token">
        /// On input, the token identifying the plugin to restore.  Upon return,
        /// this may contain the token of the recreated plugin.
        /// </param>
        /// <param name="result">
        /// Upon success, this may contain additional information about the
        /// restored plugin.  Upon failure, this will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success;
        /// <see cref="ReturnCode.Error" /> on failure.
        /// </returns>
        private ReturnCode RestorePlugin(
            NewStaticPluginCallback callback, /* in */
            bool useBuiltIn,                  /* in */
            bool noCommands,                  /* in */
            bool noPolicies,                  /* in */
            bool standardOnly,                /* in */
            bool strict,                      /* in */
            bool verbose,                     /* in */
            ref long token,                   /* in, out */
            ref Result result                 /* out */
            )
        {
            long localToken = token;

            if (localToken != 0)
            {
                CommandFlags commandFlags = CommandFlags.Restore;

                if (useBuiltIn)
                    commandFlags |= CommandFlags.NoAttributes;

                IPlugin plugin = null;
                Result localError = null;

                if ((GetPlugin(localToken,
                        LookupFlags.Default, ref plugin,
                        ref localError) == ReturnCode.Ok) &&
                    (AddCommands(
                        plugin, null, commandFlags,
                        ref localError) == ReturnCode.Ok) &&
                    (MoveExposedAndHiddenCommands(
                        EntityOps.GetFlagsNoThrow(plugin),
                        ref localError) == ReturnCode.Ok) &&
                    (!strict || (SetupFunctions(createFlags,
                        useBuiltIn, standardOnly, verbose,
                        ref localError) == ReturnCode.Ok)))
                {
                    result = String.Empty;
                    return ReturnCode.Ok;
                }
                else
                {
                    result = localError;
                }
            }
            else if (callback != null)
            {
                IPlugin plugin = callback();

                if (plugin != null)
                {
                    Result localResult = null;

                    if ((RuntimeOps.PopulatePluginEntities(
                            this, plugin, null, ruleSet, null,
                            null, useBuiltIn, noCommands, noPolicies,
                            verbose, ref localResult) == ReturnCode.Ok) &&
                        (PrivateAddPlugin(
                            plugin, new PluginClientData(
                                true, useBuiltIn, null),
                            false, false, ref localToken,
                            ref localResult) == ReturnCode.Ok) &&
                        (!strict || (SetupFunctions(createFlags,
                            useBuiltIn, standardOnly, verbose,
                            ref localResult) == ReturnCode.Ok)))
                    {
                        token = localToken;
                        result = String.Empty;

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        result = localResult;
                    }
                }
                else
                {
                    result = String.Format(
                        "new plugin callback {0} failed",
                        FormatOps.WrapOrNull(
                            FormatOps.DelegateName(callback)));
                }
            }
            else
            {
                result = "invalid new plugin callback";
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Isolated Plugin Support
#if ISOLATED_PLUGINS
        /// <summary>
        /// This method unloads the isolated application domain that was
        /// created to host the specified plugin, complaining if the unload
        /// operation fails.
        /// </summary>
        /// <param name="pluginData">
        /// The plugin data associated with the application domain to be
        /// unloaded.
        /// </param>
        /// <param name="clientData">
        /// The optional client data associated with the plugin.
        /// </param>
        /// <param name="friendlyName">
        /// The friendly name of the application domain to be unloaded.
        /// </param>
        /// <param name="appDomain">
        /// The application domain to be unloaded.
        /// </param>
        private void UnloadAppDomainForPlugin(
            IPluginData pluginData,
            IClientData clientData,
            string friendlyName,
            AppDomain appDomain
            )
        {
            string pluginName = EntityOps.GetNameNoThrow(pluginData);
            string appDomainName = FormatOps.DisplayAppDomain(appDomain);

            TraceOps.DebugTrace(String.Format(
                "UnloadAppDomainForPlugin: interpreter = {0}, " +
                "pluginData = {1}, clientData = {2}, appDomainName = {3}",
                FormatOps.InterpreterNoThrow(this),
                FormatOps.WrapOrNull(pluginName),
                FormatOps.WrapOrNull(clientData), appDomainName),
                typeof(Interpreter).Name, TracePriority.CleanupDebug);

            AppDomainOps.UnloadOrComplain(
                this, friendlyName, appDomain, clientData);
        }
#endif
        #endregion

