        #region PluginCreateHelper Class (Serializable)
        /// <summary>
        /// This class is a helper used to finish creating a plugin from inside
        /// the application domain that hosts it, performing the setup steps
        /// (e.g. associating the application domain and assembly, and
        /// populating the plugin entities) that cannot be performed from the
        /// primary application domain.
        /// </summary>
#if SERIALIZATION
        [Serializable()]
#endif
        [ObjectId("44989f7c-828c-4170-8655-404ee607460e")]
        private sealed class PluginCreateHelper
        {
            #region Private Constants
            /// <summary>
            /// The error message used when the plugin is not available.
            /// </summary>
            private const string InvalidPluginError = "invalid plugin";
            /// <summary>
            /// The error message used when the assembly name is not available.
            /// </summary>
            private const string InvalidAssemblyNameError = "invalid assembly name";
            /// <summary>
            /// The error message used when the application domain for the
            /// plugin has already been set.
            /// </summary>
            private const string PluginAppDomainAlreadySetError = "plugin application domain already set";
            /// <summary>
            /// The error message used when the assembly for the plugin has
            /// already been set.
            /// </summary>
            private const string PluginAssemblyAlreadySetError = "plugin assembly name already set";
            /// <summary>
            /// The error message used when the plugin entities cannot be
            /// populated.
            /// </summary>
            private const string CouldNotPopulatePluginEntitiesError = "could not populate plugin entities";
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Private Data
            /// <summary>
            /// The rule set used when populating the plugin entities, if any.
            /// </summary>
            private IRuleSet ruleSet; /* in */
            /// <summary>
            /// The plugin to be set up.
            /// </summary>
            private IPlugin plugin; /* in */
            /// <summary>
            /// The name of the assembly that contains the plugin.
            /// </summary>
            private AssemblyName assemblyName; /* in */
            /// <summary>
            /// Non-zero to produce more diagnostic output while populating the
            /// plugin entities.
            /// </summary>
            private bool verbose; /* in */
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Private Constructors
            /// <summary>
            /// Constructs a new instance of this class.
            /// </summary>
            /// <param name="ruleSet">
            /// The rule set used when populating the plugin entities, if any.
            /// </param>
            /// <param name="plugin">
            /// The plugin to be set up.
            /// </param>
            /// <param name="assemblyName">
            /// The name of the assembly that contains the plugin.
            /// </param>
            /// <param name="verbose">
            /// Non-zero to produce more diagnostic output while populating the
            /// plugin entities.
            /// </param>
            private PluginCreateHelper(
                IRuleSet ruleSet,
                IPlugin plugin,
                AssemblyName assemblyName,
                bool verbose
                )
            {
                this.ruleSet = ruleSet;
                this.plugin = plugin;
                this.assemblyName = assemblyName;
                this.verbose = verbose;
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Static "Factory" Methods
            /// <summary>
            /// This method creates a new instance of this class.
            /// </summary>
            /// <param name="ruleSet">
            /// The rule set used when populating the plugin entities, if any.
            /// </param>
            /// <param name="plugin">
            /// The plugin to be set up.
            /// </param>
            /// <param name="assemblyName">
            /// The name of the assembly that contains the plugin.
            /// </param>
            /// <param name="verbose">
            /// Non-zero to produce more diagnostic output while populating the
            /// plugin entities.
            /// </param>
            /// <returns>
            /// The newly created instance of this class.
            /// </returns>
            public static PluginCreateHelper Create(
                IRuleSet ruleSet,
                IPlugin plugin,
                AssemblyName assemblyName,
                bool verbose
                )
            {
                return new PluginCreateHelper(ruleSet, plugin, assemblyName, verbose);
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Private Methods
            /// <summary>
            /// This method associates the current application domain and its
            /// matching loaded assembly with the plugin.  This cannot be done
            /// from the primary application domain.
            /// </summary>
            private void SetupAppDomainAndAssembly()
            {
                if (plugin == null)
                    throw new InvalidOperationException(InvalidPluginError);

                if (assemblyName == null)
                    throw new InvalidOperationException(InvalidAssemblyNameError);

                AppDomain appDomain = plugin.AppDomain;

                if (appDomain != null)
                    throw new InvalidOperationException(PluginAppDomainAlreadySetError);

                Assembly assembly = plugin.Assembly;

                if (assembly != null)
                    throw new InvalidOperationException(PluginAssemblyAlreadySetError);

                appDomain = AppDomainOps.GetCurrent();

                plugin.AppDomain = appDomain;

                assembly = AssemblyOps.FindInAppDomain(appDomain, assemblyName);

                plugin.Assembly = assembly;
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method populates the command and policy type metadata for
            /// the plugin.  This cannot be done from the primary application
            /// domain.
            /// </summary>
            private void SetupEntities()
            {
                ReturnCode code;
                Result error = null;

                code = RuntimeOps.PopulatePluginEntities(
                    null, plugin, null, ruleSet, null, null,
                    false, false, false, verbose, ref error);

                if (code != ReturnCode.Ok)
                {
                    throw new TypeLoadException(
                        CouldNotPopulatePluginEntitiesError,
                        new ScriptException(code, error));
                }
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Public Methods
            /// <summary>
            /// This method performs all of the plugin setup steps that must be
            /// carried out from inside the application domain that hosts the
            /// plugin.
            /// </summary>
            public void Setup()
            {
                //
                // NOTE: Set the application domain and assembly for this
                //       plugin now because this could not be done from
                //       the primary application domain.
                //
                SetupAppDomainAndAssembly();

                //
                // NOTE: Get the command and policy type metadata for this
                //       plugin now because this cannot be done from the
                //       primary application domain.
                //
                SetupEntities();
            }
            #endregion
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region PluginLoadHelper Class (Serializable)
        /// <summary>
        /// This class is a helper used to load a plugin assembly into an
        /// application domain and to extract the metadata that describes the
        /// plugin (e.g. its assembly name, type, flags, URIs, and resources).
        /// It supports both file-based and byte-array-based loading, including
        /// reflection-only loading.
        /// </summary>
#if SERIALIZATION
        [Serializable()]
#endif
        [ObjectId("532f533d-6b21-45d8-8139-54c7a4be4dbd")]
        private sealed class PluginLoadHelper
        {
            #region Private Constants
            /// <summary>
            /// The error message used when the application domain is not
            /// available.
            /// </summary>
            private const string AppDomainNotAvailableError = "application domain not available";
            /// <summary>
            /// The error message used when the assembly has not been loaded.
            /// </summary>
            private const string AssemblyNotLoadedError = "assembly not loaded";
            /// <summary>
            /// The error message used when the assembly has already been
            /// loaded.
            /// </summary>
            private const string AssemblyAlreadyLoadedError = "assembly already loaded";
            /// <summary>
            /// The error message used when the assembly name has already been
            /// set.
            /// </summary>
            private const string AssemblyNameAlreadySetError = "assembly name already set";
            /// <summary>
            /// The error message used when the plugin type has not been set.
            /// </summary>
            private const string TypeNotSetError = "type not set";
            /// <summary>
            /// The error message used when the plugin type has already been
            /// set.
            /// </summary>
            private const string TypeAlreadySetError = "type already set";
            /// <summary>
            /// The error message used when the primary plugin type cannot be
            /// found.
            /// </summary>
            private const string PrimaryPluginTypeNotFoundError = "primary plugin type not found";
            /// <summary>
            /// The error message used when the URI has already been set.
            /// </summary>
            private const string UriAlreadySetError = "uri already set";
            /// <summary>
            /// The error message used when the update URI has already been set.
            /// </summary>
            private const string UpdateUriAlreadySetError = "update uri already set";
            /// <summary>
            /// The error message used when a resource stream is not available.
            /// </summary>
            private const string ResourceStreamNotAvailable = "resource stream not available";
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Private Data
            /// <summary>
            /// The application domain into which the plugin assembly is loaded.
            /// </summary>
#if SERIALIZATION
            [NonSerialized()]
#endif
            private AppDomain appDomain;

            /// <summary>
            /// The list of trusted assembly hashes used when computing the
            /// assembly plugin flags, if any.
            /// </summary>
            private StringList trustedHashes; /* in */

            /// <summary>
            /// Non-zero if the assembly was loaded from an array of bytes
            /// rather than from a file.
            /// </summary>
            private bool viaBytes;

            /// <summary>
            /// The raw bytes of the plugin assembly, if it is loaded from a
            /// byte array.
            /// </summary>
            private byte[] assemblyBytes; /* in */
            /// <summary>
            /// The raw bytes of the plugin assembly debugging symbols, if any.
            /// </summary>
            private byte[] symbolBytes; /* in */

            /// <summary>
            /// The file name of the plugin assembly, if it is loaded from a
            /// file.
            /// </summary>
            private string fileName; /* in */
            /// <summary>
            /// The fully qualified type name of the plugin type to load.  Upon
            /// success, this may be updated to reflect the resolved type name.
            /// </summary>
            private string typeName; /* in, out */

#if CAS_POLICY
            /// <summary>
            /// The evidence used when loading the plugin assembly, if any.
            /// </summary>
#if SERIALIZATION
            [NonSerialized()]
#endif
            private Evidence evidence; /* in */

#if !MONO && !MONO_HACKS
            /// <summary>
            /// The hash value used when loading the plugin assembly, if any.
            /// </summary>
            private byte[] hashValue; /* in */
            /// <summary>
            /// The hash algorithm used when loading the plugin assembly, if
            /// any.
            /// </summary>
            private AssemblyHashAlgorithm hashAlgorithm; /* in */
#endif
#endif

            /// <summary>
            /// The property helper used to transport the resulting plugin
            /// metadata back to the calling application domain, if any.
            /// </summary>
            private PluginPropertyHelper propertyHelper; /* in, out */
            /// <summary>
            /// The flags that control how the plugin assembly is loaded and
            /// which setup steps are performed.
            /// </summary>
            private PluginLoaderFlags pluginLoaderFlags; /* in */

            /// <summary>
            /// The patterns used to select which assembly resources are
            /// extracted, if any.
            /// </summary>
            private StringList resourcePatterns; /* in */

            /// <summary>
            /// The loaded plugin assembly.
            /// </summary>
#if SERIALIZATION
            [NonSerialized()]
#endif
            private Assembly assembly; /* out */

            /// <summary>
            /// The resolved primary plugin type.
            /// </summary>
#if SERIALIZATION
            [NonSerialized()]
#endif
            private Type type; /* out */

            /// <summary>
            /// The name of the loaded plugin assembly.
            /// </summary>
            private AssemblyName assemblyName; /* out */
            /// <summary>
            /// The date and time associated with the loaded plugin assembly.
            /// </summary>
            private DateTime? dateTime; /* out */
            /// <summary>
            /// The URI associated with the loaded plugin assembly.
            /// </summary>
            private Uri uri; /* out */
            /// <summary>
            /// The update base URI associated with the loaded plugin assembly.
            /// </summary>
            private Uri updateUri; /* out */
            /// <summary>
            /// The plugin flags associated with the loaded plugin assembly.
            /// </summary>
            private PluginFlags assemblyPluginFlags; /* out */
            /// <summary>
            /// The plugin flags associated with the resolved plugin type.
            /// </summary>
            private PluginFlags typePluginFlags; /* out */

#if APPDOMAINS || ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
            /// <summary>
            /// The resources extracted from the loaded plugin assembly, if
            /// any.
            /// </summary>
            private PluginResourceDictionary resources; /* out */
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Private Constructors
            /// <summary>
            /// Constructs a new instance of this class.
            /// </summary>
            /// <param name="trustedHashes">
            /// The list of trusted assembly hashes used when computing the
            /// assembly plugin flags, if any.
            /// </param>
            /// <param name="assemblyBytes">
            /// The raw bytes of the plugin assembly, if it is loaded from a
            /// byte array.
            /// </param>
            /// <param name="symbolBytes">
            /// The raw bytes of the plugin assembly debugging symbols, if any.
            /// </param>
            /// <param name="fileName">
            /// The file name of the plugin assembly, if it is loaded from a
            /// file.
            /// </param>
            /// <param name="typeName">
            /// The fully qualified type name of the plugin type to load.
            /// </param>
            /// <param name="resourcePatterns">
            /// The patterns used to select which assembly resources are
            /// extracted, if any.
            /// </param>
            /// <param name="evidence">
            /// The evidence used when loading the plugin assembly, if any.
            /// </param>
            /// <param name="hashValue">
            /// The hash value used when loading the plugin assembly, if any.
            /// </param>
            /// <param name="hashAlgorithm">
            /// The hash algorithm used when loading the plugin assembly, if
            /// any.
            /// </param>
            /// <param name="propertyHelper">
            /// The property helper used to transport the resulting plugin
            /// metadata back to the calling application domain, if any.
            /// </param>
            /// <param name="pluginLoaderFlags">
            /// The flags that control how the plugin assembly is loaded and
            /// which setup steps are performed.
            /// </param>
            private PluginLoadHelper(
                StringList trustedHashes,            /* in */
                byte[] assemblyBytes,                /* in */
                byte[] symbolBytes,                  /* in */
                string fileName,                     /* in */
                string typeName,                     /* in */
                StringList resourcePatterns,         /* in */
#if CAS_POLICY
                Evidence evidence,                   /* in */
#if !MONO && !MONO_HACKS
                byte[] hashValue,                    /* in */
                AssemblyHashAlgorithm hashAlgorithm, /* in */
#endif
#endif
                PluginPropertyHelper propertyHelper, /* in */
                PluginLoaderFlags pluginLoaderFlags  /* in */
                )
            {
                this.trustedHashes = trustedHashes;
                this.assemblyBytes = assemblyBytes;
                this.symbolBytes = symbolBytes;

                this.fileName = fileName;
                this.typeName = typeName;
                this.resourcePatterns = resourcePatterns;

#if CAS_POLICY
                this.evidence = evidence;

#if !MONO && !MONO_HACKS
                this.hashValue = hashValue;
                this.hashAlgorithm = hashAlgorithm;
#endif
#endif

                this.propertyHelper = propertyHelper;
                this.pluginLoaderFlags = pluginLoaderFlags;
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Static "Factory" Methods
            /// <summary>
            /// This method creates a new instance of this class for loading a
            /// plugin assembly from an array of bytes.
            /// </summary>
            /// <param name="trustedHashes">
            /// The list of trusted assembly hashes used when computing the
            /// assembly plugin flags, if any.
            /// </param>
            /// <param name="assemblyBytes">
            /// The raw bytes of the plugin assembly to load.
            /// </param>
            /// <param name="symbolBytes">
            /// The raw bytes of the plugin assembly debugging symbols, if any.
            /// </param>
            /// <param name="typeName">
            /// The fully qualified type name of the plugin type to load.
            /// </param>
            /// <param name="resourcePatterns">
            /// The patterns used to select which assembly resources are
            /// extracted, if any.
            /// </param>
            /// <param name="evidence">
            /// The evidence used when loading the plugin assembly, if any.
            /// </param>
            /// <param name="pluginLoaderFlags">
            /// The flags that control how the plugin assembly is loaded and
            /// which setup steps are performed.
            /// </param>
            /// <returns>
            /// The newly created instance of this class.
            /// </returns>
            public static PluginLoadHelper Create(
                StringList trustedHashes,           /* in */
                byte[] assemblyBytes,               /* in */
                byte[] symbolBytes,                 /* in */
                string typeName,                    /* in */
                StringList resourcePatterns,        /* in */
#if CAS_POLICY
                Evidence evidence,                  /* in */
#endif
                PluginLoaderFlags pluginLoaderFlags /* in */
                )
            {
                return new PluginLoadHelper(
                    trustedHashes, assemblyBytes, symbolBytes,
                    null, typeName, resourcePatterns,
#if CAS_POLICY
                    evidence,
#if !MONO && !MONO_HACKS
                    null, AssemblyHashAlgorithm.None,
#endif
#endif
                    PluginPropertyHelper.Create(), pluginLoaderFlags);
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method creates a new instance of this class for loading a
            /// plugin assembly from a file.
            /// </summary>
            /// <param name="trustedHashes">
            /// The list of trusted assembly hashes used when computing the
            /// assembly plugin flags, if any.
            /// </param>
            /// <param name="fileName">
            /// The file name of the plugin assembly to load.
            /// </param>
            /// <param name="typeName">
            /// The fully qualified type name of the plugin type to load.
            /// </param>
            /// <param name="resourcePatterns">
            /// The patterns used to select which assembly resources are
            /// extracted, if any.
            /// </param>
            /// <param name="evidence">
            /// The evidence used when loading the plugin assembly, if any.
            /// </param>
            /// <param name="hashValue">
            /// The hash value used when loading the plugin assembly, if any.
            /// </param>
            /// <param name="hashAlgorithm">
            /// The hash algorithm used when loading the plugin assembly, if
            /// any.
            /// </param>
            /// <param name="pluginLoaderFlags">
            /// The flags that control how the plugin assembly is loaded and
            /// which setup steps are performed.
            /// </param>
            /// <returns>
            /// The newly created instance of this class.
            /// </returns>
            public static PluginLoadHelper Create(
                StringList trustedHashes,            /* in */
                string fileName,                     /* in */
                string typeName,                     /* in */
                StringList resourcePatterns,         /* in */

#if CAS_POLICY
                Evidence evidence,                   /* in */
#if !MONO && !MONO_HACKS
                byte[] hashValue,                    /* in */
                AssemblyHashAlgorithm hashAlgorithm, /* in */
#endif
#endif
                PluginLoaderFlags pluginLoaderFlags  /* in */
                )
            {
                return new PluginLoadHelper(
                    trustedHashes, null, null, fileName,
                    typeName, resourcePatterns,
#if CAS_POLICY
                    evidence,
#if !MONO && !MONO_HACKS
                    hashValue, hashAlgorithm,
#endif
#endif
                    PluginPropertyHelper.Create(), pluginLoaderFlags);
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Private Event Handlers
#if ISOLATED_PLUGINS
            /// <summary>
            /// This method handles the application domain assembly resolution
            /// event, returning the plugin assembly when it is requested and
            /// it was loaded via an array of bytes (i.e. has no load context).
            /// </summary>
            /// <param name="sender">
            /// The object where the event handler is attached.
            /// </param>
            /// <param name="args">
            /// The event data that contains the name of the assembly being
            /// resolved.
            /// </param>
            /// <returns>
            /// The resolved assembly, or null if it could not be resolved.
            /// </returns>
            private Assembly AssemblyResolve(
                object sender,        /* in */
                ResolveEventArgs args /* in */
                )
            {
                if (args == null)
                    return null;

                //
                // NOTE: This event handler does not attempt to resolve an
                //       assembly that already has a context (i.e. the Load
                //       or LoadFrom contexts that are used when loading via
                //       an AssemblyName or file name, respectively).
                //
                if ((assemblyBytes == null) || (fileName != null))
                    return null;

                //
                // TODO: Are these the right string comparisons to use here?
                //
                if ((assemblyName != null) && SharedStringOps.SystemEquals(
                        args.Name, assemblyName.FullName))
                {
                    return assembly;
                }

                return null;
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method handles the application domain reflection-only
            /// assembly resolution event, returning the Eagle core library
            /// assembly, the plugin assembly, or a freshly loaded assembly for
            /// any other request.
            /// </summary>
            /// <param name="sender">
            /// The object where the event handler is attached.
            /// </param>
            /// <param name="args">
            /// The event data that contains the name of the assembly being
            /// resolved.
            /// </param>
            /// <returns>
            /// The resolved assembly, or null if it could not be resolved.
            /// </returns>
            private Assembly ReflectionOnlyAssemblyResolve(
                object sender,        /* in */
                ResolveEventArgs args /* in */
                )
            {
                if (args == null)
                    return null;

                //
                // TODO: Are these the right string comparisons to use here?
                //
                if (SharedStringOps.SystemEquals(
                        args.Name, GlobalState.GetAssemblyFullName()))
                {
                    return Assembly.ReflectionOnlyLoadFrom(
                        GlobalState.GetAssemblyLocation());
                }

                if ((assemblyName != null) && SharedStringOps.SystemEquals(
                        args.Name, assemblyName.FullName))
                {
                    return assembly;
                }

                //
                // NOTE: Fallback to simply (re-)loading any assembly that is
                //       requested into the reflection-only context, including
                //       things like "System", et al.
                //
                return Assembly.ReflectionOnlyLoad(args.Name);
            }
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Private Methods
            /// <summary>
            /// This method reads all of the bytes of the named manifest
            /// resource from the loaded plugin assembly.
            /// </summary>
            /// <param name="resourceName">
            /// The name of the manifest resource to read.
            /// </param>
            /// <returns>
            /// The bytes of the named manifest resource.
            /// </returns>
            private byte[] GetResourceBytes(
                string resourceName /* in */
                )
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                using (Stream stream = assembly.GetManifestResourceStream(resourceName)) /* throw */
                {
                    if (stream == null)
                        throw new InvalidOperationException(ResourceStreamNotAvailable);

                    using (BinaryReader binaryReader = new BinaryReader(stream))
                    {
                        return binaryReader.ReadBytes((int)stream.Length); /* throw */
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method ensures that the application domain is set to the
            /// current application domain and, when isolated plugins are
            /// enabled, hooks up the assembly resolution event handlers.
            /// </summary>
            private void SetupAppDomain()
            {
                if (appDomain == null)
                {
                    //
                    // NOTE: Use the current application domain.  This is correct
                    //       because this method should only ever called when the
                    //       correct application domain is on the call stack.
                    //
                    appDomain = AppDomainOps.GetCurrent();

                    ///////////////////////////////////////////////////////////////////////////////////

#if ISOLATED_PLUGINS
                    if (appDomain != null)
                    {
                        //
                        // NOTE: Setup our assembly resolution event handler so that
                        //       it can deal with resolving an assemblies loaded via
                        //       a byte array (i.e. which has no context).
                        //
                        appDomain.AssemblyResolve += new ResolveEventHandler(
                            AssemblyResolve);

                        appDomain.ReflectionOnlyAssemblyResolve += new ResolveEventHandler(
                            ReflectionOnlyAssemblyResolve);
                    }
#endif
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method performs all of the post-load setup steps, querying
            /// the metadata from the loaded plugin assembly (e.g. its name,
            /// date and time, type, URIs, flags, and resources) and, when a
            /// property helper is present, copying that metadata into it for
            /// transport back to the calling application domain.
            /// </summary>
            private void Setup() /* throw */
            {
                SetupAppDomain();

                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Verbose, true))
                {
                    DebugOps.DumpAppDomain(appDomain);
                }

                SetupAssemblyName(); /* throw */
                SetupDateTime(); /* throw */

                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Type, true))
                {
                    SetupTypeName(); /* throw */
                }

                SetupUri(); /* throw */
                SetupUpdateUri(); /* throw */
                SetupAssemblyPluginFlags(); /* throw */

                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Type, true))
                {
                    SetupTypePluginFlags(); /* throw */
                }

#if APPDOMAINS || ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Resources, true))
                {
                    SetupResources(); /* throw */
                }
#endif

                //
                // NOTE: If the property helper was provided, use it to send our
                //       output data back to the other application domain.
                //
                if (propertyHelper != null)
                {
                    propertyHelper.AssemblyName = assemblyName;
                    propertyHelper.DateTime = dateTime;
                    propertyHelper.FileName = fileName;
                    propertyHelper.TypeName = typeName;
                    propertyHelper.Uri = uri;
                    propertyHelper.UpdateUri = updateUri;
                    propertyHelper.AssemblyPluginFlags = assemblyPluginFlags;
                    propertyHelper.TypePluginFlags = typePluginFlags;

#if APPDOMAINS || ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
                    propertyHelper.Resources = resources;
#endif
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method queries the full name of the loaded plugin assembly
            /// and stores it for later use by the plugin loader.
            /// </summary>
            private void SetupAssemblyName()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                if (assemblyName != null)
                    throw new InvalidOperationException(AssemblyNameAlreadySetError);

                //
                // NOTE: Get the full name of the assembly and store it for
                //       later use by the plugin loader.
                //
                assemblyName = assembly.GetName();
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method determines the date and time associated with the
            /// loaded plugin assembly and stores it for later use by the plugin
            /// loader.
            /// </summary>
            private void SetupDateTime()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                //
                // NOTE: Get the DateTime of the assembly and store it for later
                //       use by the plugin loader.
                //
                if (assembly.ReflectionOnly)
                {
                    if (fileName != null)
                    {
                        DateTime localDateTime = DateTime.MinValue;

                        if (FileOps.GetPeFileDateTime(
                                fileName, ref localDateTime))
                        {
                            dateTime = localDateTime;
                        }
                        else
                        {
                            dateTime = DateTime.MinValue;
                        }
                    }
                    else
                    {
                        dateTime = DateTime.MinValue;
                    }
                }
                else
                {
                    dateTime = _Shared.AttributeOps.GetAssemblyDateTime(
                        assembly);
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method determines the plugin flags associated with the
            /// loaded plugin assembly and combines them into the assembly
            /// plugin flags.
            /// </summary>
            private void SetupAssemblyPluginFlags()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                if (viaBytes)
                {
                    assemblyPluginFlags |= RuntimeOps.GetAssemblyPluginFlags(
                        null, trustedHashes, assembly, assemblyBytes);
                }
                else
                {
                    assemblyPluginFlags |= RuntimeOps.GetAssemblyPluginFlags(
                        null, trustedHashes, assembly);
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method determines the plugin flags associated with the
            /// resolved plugin type and stores them for later use by the plugin
            /// loader.
            /// </summary>
            private void SetupTypePluginFlags()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                if (type == null)
                    throw new InvalidOperationException(TypeNotSetError);

                if (assembly.ReflectionOnly)
                    typePluginFlags = AttributeOps.GetReflectionOnlyPluginFlags(type);
                else
                    typePluginFlags = AttributeOps.GetPluginFlags(type);
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method resolves the plugin type, using the specified type
            /// name when present or otherwise locating the primary plugin type
            /// in the loaded assembly, and stores the resulting type and type
            /// name for later use by the plugin loader.
            /// </summary>
            private void SetupTypeName()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                if (type != null)
                    throw new InvalidOperationException(TypeAlreadySetError);

                //
                // NOTE: Do they want a specific plugin type or simply the
                //       default one?
                //
                if (!String.IsNullOrEmpty(typeName))
                {
                    type = assembly.GetType(typeName, true, false); /* throw */

                    //
                    // NOTE: Did we find the type?  For now, this should already be
                    //       true because the above code should throw an exception
                    //       if the type is not found.
                    //
                    if (type != null)
                        typeName = type.FullName;
                }
                else
                {
                    ReturnCode code;
                    Result error = null;

                    code = RuntimeOps.FindPrimaryPlugin(
                        assembly, FlagOps.HasFlags(pluginLoaderFlags,
                        PluginLoaderFlags.Verbose, true), ref typeName,
                        ref error);

                    if (code == ReturnCode.Ok)
                    {
                        //
                        // NOTE: Attempt to get the type from the assembly now.
                        //
                        type = assembly.GetType(typeName, true, false); /* throw */
                    }
                    else
                    {
                        throw new TypeLoadException(
                            PrimaryPluginTypeNotFoundError,
                            new ScriptException(code, error));
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method determines the URI associated with the loaded
            /// plugin assembly, falling back to the assembly location when no
            /// URI attribute is present, and stores it for later use by the
            /// plugin loader.
            /// </summary>
            private void SetupUri()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                if (uri != null)
                    throw new InvalidOperationException(UriAlreadySetError);

                //
                // NOTE: Check if the plugin assembly contains a an AssemblyUri
                //       attribute.
                //
                if (assembly.ReflectionOnly)
                    uri = AttributeOps.GetReflectionOnlyAssemblyUri(assembly);
                else
                    uri = _Shared.AttributeOps.GetAssemblyUri(assembly);

                //
                // NOTE: If the plugin assembly does NOT contain an AssemblyUri
                //       attribute, use its location.
                //
                if (uri == null)
                {
                    string location = assembly.Location;

                    if (!String.IsNullOrEmpty(location))
                        uri = new Uri(location); /* throw */
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method determines the update base URI associated with the
            /// loaded plugin assembly and stores it for later use by the plugin
            /// loader.
            /// </summary>
            private void SetupUpdateUri()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                if (updateUri != null)
                    throw new InvalidOperationException(UpdateUriAlreadySetError);

                //
                // NOTE: Check if the plugin assembly contains a an AssemblyUri
                //       attribute.
                //
                if (assembly.ReflectionOnly)
                {
                    updateUri = AttributeOps.GetReflectionOnlyAssemblyUpdateBaseUri(
                        assembly);
                }
                else
                {
                    updateUri = _Shared.AttributeOps.GetAssemblyUpdateBaseUri(
                        assembly);
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

#if APPDOMAINS || ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
            /// <summary>
            /// This method extracts the manifest resources from the loaded
            /// plugin assembly, filtered by the configured resource patterns,
            /// and stores them for later use by the plugin loader.
            /// </summary>
            private void SetupResources()
            {
                if (assembly == null)
                    throw new InvalidOperationException(AssemblyNotLoadedError);

                string[] resourceNames = assembly.GetManifestResourceNames(); /* throw */

                if (resourceNames != null)
                {
                    bool ignoreEmpty = FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.IgnoreEmpty,
                        true);

                    foreach (string resourceName in resourceNames)
                    {
                        if ((resourcePatterns != null) &&
                            !StringOps.MatchAnyOrAll(
                                null, MatchMode.Glob, resourceName,
                                resourcePatterns, false, false))
                        {
                            continue;
                        }

                        byte[] bytes = GetResourceBytes(resourceName);

                        if (ignoreEmpty &&
                            ((bytes == null) || (bytes.Length == 0)))
                        {
                            continue;
                        }

                        if (resources == null)
                            resources = new PluginResourceDictionary();

                        resources[resourceName] = bytes;
                    }
                }
            }
#endif
            #endregion

