            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Public Methods
#if !CAS_POLICY
            /// <summary>
            /// This method loads the plugin assembly from its file into the
            /// application domain, then performs the post-load setup steps when
            /// requested.  This overload is used when Code Access Security
            /// policy is not in effect.
            /// </summary>
            public void NoCasLoad1()
            {
                if (assembly != null)
                    throw new InvalidOperationException(AssemblyAlreadyLoadedError);

                //
                // NOTE: Load the assembly into this AppDomain now.
                //
                assembly = Assembly.LoadFrom(fileName); /* throw */

                //
                // NOTE: This assembly was NOT loaded via an array of bytes.
                //
                viaBytes = false;

                //
                // NOTE: Perform the post-load setup steps?
                //
                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Setup, true))
                {
                    Setup(); /* throw */
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method loads the plugin assembly from its raw bytes into
            /// the application domain, then performs the post-load setup steps
            /// when requested.  This overload is used when Code Access Security
            /// policy is not in effect.
            /// </summary>
            public void NoCasLoad2()
            {
                if (assembly != null)
                    throw new InvalidOperationException(AssemblyAlreadyLoadedError);

                SetupAppDomain();

                if (appDomain == null)
                    throw new InvalidOperationException(AppDomainNotAvailableError);

                //
                // NOTE: Load the raw assembly into this AppDomain now.
                //
                assembly = appDomain.Load(assemblyBytes, symbolBytes);

                //
                // NOTE: This assembly was loaded via an array of bytes.
                //
                viaBytes = true;

                //
                // NOTE: Perform the post-load setup steps?
                //
                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Setup, true))
                {
                    Setup(); /* throw */
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if CAS_POLICY
            /// <summary>
            /// This method loads the plugin assembly from its file into the
            /// application domain using the provided evidence, then performs the
            /// post-load setup steps when requested.  This overload is used when
            /// Code Access Security policy is in effect.
            /// </summary>
            public void CasLoad2()
            {
                if (assembly != null)
                    throw new InvalidOperationException(AssemblyAlreadyLoadedError);

                //
                // NOTE: Load the assembly into this AppDomain using the
                //       provided evidence now.
                //
                assembly = Assembly.LoadFrom(fileName, evidence); /* throw */

                //
                // NOTE: This assembly was NOT loaded via an array of bytes.
                //
                viaBytes = false;

                //
                // NOTE: Perform the post-load setup steps?
                //
                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Setup, true))
                {
                    Setup(); /* throw */
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            /// <summary>
            /// This method loads the plugin assembly from its raw bytes into
            /// the application domain using the provided evidence, then performs
            /// the post-load setup steps when requested.  This overload is used
            /// when Code Access Security policy is in effect.
            /// </summary>
            public void CasLoad3()
            {
                if (assembly != null)
                    throw new InvalidOperationException(AssemblyAlreadyLoadedError);

                SetupAppDomain();

                if (appDomain == null)
                    throw new InvalidOperationException(AppDomainNotAvailableError);

                //
                // NOTE: Load the raw assembly into this AppDomain using the
                //       provided evidence now.
                //
                assembly = appDomain.Load(
                    assemblyBytes, symbolBytes, evidence); /* throw */

                //
                // NOTE: This assembly was loaded via an array of bytes.
                //
                viaBytes = true;

                //
                // NOTE: Perform the post-load setup steps?
                //
                if (FlagOps.HasFlags(
                        pluginLoaderFlags, PluginLoaderFlags.Setup, true))
                {
                    Setup(); /* throw */
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

#if !MONO && !MONO_HACKS
            /// <summary>
            /// This method loads the plugin assembly from its file into the
            /// application domain using the provided evidence and hash
            /// parameters, then performs the post-load setup steps when
            /// requested.  This overload is used when Code Access Security
