        #region Private
        /// <summary>
        /// Gets or sets a value indicating whether an exception should be
        /// thrown when an unsupported feature is requested.
        /// </summary>
        internal bool ThrowOnFeatureNotSupported
        {
            get
            {
                lock (syncRoot)
                {
                    return throwOnFeatureNotSupported;
                }
            }
            set
            {
                lock (syncRoot)
                {
                    throwOnFeatureNotSupported = value;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the client data value associated with the named
        /// runtime option.
        /// </summary>
        /// <param name="name">
        /// The name of the runtime option to query.
        /// </param>
        /// <param name="value">
        /// Upon success, receives the client data value associated with the
        /// named runtime option.
        /// </param>
        /// <returns>
        /// True if the named runtime option was found; otherwise, false.
        /// </returns>
        internal bool InternalGetRuntimeOption(
            string name,
            ref IClientData value
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (String.IsNullOrEmpty(name))
                    return false;

                return (runtimeOptions != null) &&
                    runtimeOptions.TryGetValue(name, out value);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the named runtime option is present.
        /// </summary>
        /// <param name="name">
        /// The name of the runtime option to check.
        /// </param>
        /// <returns>
        /// True if the named runtime option is present; otherwise, false.
        /// </returns>
        private bool PrivateHasRuntimeOption(
            string name /* in */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (String.IsNullOrEmpty(name))
                    return false;

                return (runtimeOptions != null) &&
                    runtimeOptions.ContainsKey(name); /* EXEMPT */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes all of the runtime options, optionally updating
        /// the associated script-level variable and issuing a notification.
        /// </summary>
        /// <param name="setVariable">
        /// Non-zero to update the associated script-level variable.
        /// </param>
        /// <param name="notify">
        /// Non-zero to issue a notification about the change.
        /// </param>
        /// <returns>
        /// True if the runtime options were cleared; otherwise, false.
        /// </returns>
        private bool PrivateClearRuntimeOptions(
            bool setVariable, /* in */
            bool notify       /* in */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false))
                    return false;

                if (runtimeOptions != null)
                {
                    VariableFlags flags;

                    if (setVariable)
                    {
                        //
                        // NOTE: Do not create the variable if we have
                        //       been prohibited from doing so.
                        //
                        flags = VariableFlags.ViaProperty;

                        if (InternalIsSafe() || PrivateIsNoVariables())
                            flags |= VariableFlags.NoCreate;
                    }
                    else
                    {
                        flags = VariableFlags.None;
                    }

                    //
                    // NOTE: Update script-level informational variable.
                    //       This variable is NOT allowed in "safe"
                    //       interpreters.
                    //
                    ClientDataDictionary oldRuntimeOptions;

                    SaveRuntimeOptions(out oldRuntimeOptions);
                    runtimeOptions.Clear();

                    if (setVariable)
                    {
                        /* IGNORED */
                        SetLibraryVariableValue2(
                            flags, Vars.Platform.Name,
                            Vars.Platform.RuntimeOptions,
                            runtimeOptions.ToString());
                    }

#if NOTIFY
                    if (notify)
                    {
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.RuntimeOption, NotifyFlags.Cleared,
                            new ObjectPair(oldRuntimeOptions, runtimeOptions),
                            this, null, null, null);
                    }
#endif

                    return true;
                }
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the named runtime option, optionally updating the
        /// associated script-level variable and issuing a notification.
        /// </summary>
        /// <param name="name">
        /// The name of the runtime option to add.
        /// </param>
        /// <param name="setVariable">
        /// Non-zero to update the associated script-level variable.
        /// </param>
        /// <param name="notify">
        /// Non-zero to issue a notification about the change.
        /// </param>
        /// <returns>
        /// True if the runtime option was added; otherwise, false.
        /// </returns>
        private bool PrivateAddRuntimeOption(
            string name,      /* in */
            bool setVariable, /* in */
            bool notify       /* in */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true))
                    return false;

                if (String.IsNullOrEmpty(name))
                    return false;

                if ((runtimeOptions != null) &&
                    !runtimeOptions.ContainsKey(name)) /* EXEMPT */
                {
                    VariableFlags flags;

                    if (setVariable)
                    {
                        //
                        // NOTE: Do not create the variable if we have
                        //       been prohibited from doing so.
                        //
                        flags = VariableFlags.ViaProperty;

                        if (InternalIsSafe() || PrivateIsNoVariables())
                            flags |= VariableFlags.NoCreate;
                    }
                    else
                    {
                        flags = VariableFlags.None;
                    }

                    //
                    // NOTE: Update script-level informational variable.
                    //       This variable is NOT allowed in "safe"
                    //       interpreters.
                    //
                    runtimeOptions.Add(name, null);

                    if (setVariable)
                    {
                        /* IGNORED */
                        SetLibraryVariableValue2(
                            flags, Vars.Platform.Name,
                            Vars.Platform.RuntimeOptions,
                            runtimeOptions.ToString());
                    }

#if NOTIFY
                    if (notify)
                    {
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.RuntimeOption, NotifyFlags.Added,
                            new ObjectPair(runtimeOptions, name), this,
                            null, null, null);
                    }
#endif

                    return true;
                }
                else
                {
                    return false;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the named runtime option, optionally updating
        /// the associated script-level variable and issuing a notification.
        /// </summary>
        /// <param name="name">
        /// The name of the runtime option to remove.
        /// </param>
        /// <param name="setVariable">
        /// Non-zero to update the associated script-level variable.
        /// </param>
        /// <param name="notify">
        /// Non-zero to issue a notification about the change.
        /// </param>
        /// <returns>
        /// True if the runtime option was removed; otherwise, false.
        /// </returns>
        private bool PrivateRemoveRuntimeOption(
            string name,      /* in */
            bool setVariable, /* in */
            bool notify       /* in */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false))
                    return false;

                if (String.IsNullOrEmpty(name))
                    return false;

                if ((runtimeOptions != null) &&
                    runtimeOptions.ContainsKey(name)) /* EXEMPT */
                {
                    VariableFlags flags;

                    if (setVariable)
                    {
                        //
                        // NOTE: Do not create the variable if we have
                        //       been prohibited from doing so.
                        //
                        flags = VariableFlags.ViaProperty;

                        if (InternalIsSafe() || PrivateIsNoVariables())
                            flags |= VariableFlags.NoCreate;
                    }
                    else
                    {
                        flags = VariableFlags.None;
                    }

                    //
                    // NOTE: Update script-level informational variable.
                    //       This variable is NOT allowed in "safe"
                    //       interpreters.
                    //
                    bool result = runtimeOptions.Remove(name);

                    if (setVariable)
                    {
                        /* IGNORED */
                        SetLibraryVariableValue2(
                            flags, Vars.Platform.Name,
                            Vars.Platform.RuntimeOptions,
                            runtimeOptions.ToString());
                    }

#if NOTIFY
                    if (notify)
                    {
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.RuntimeOption, NotifyFlags.Removed,
                            new ObjectPair(runtimeOptions, name), this,
                            null, null, null);
                    }
#endif

                    return result; /* NOTE: Must be true. */
                }
                else
                {
                    return false;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method changes a runtime option based on a leading operator
        /// character in its name: a plus sign adds the option, a minus sign
        /// removes it, an equal sign clears all options before adding it, and
        /// an identifier character adds it.
        /// </summary>
        /// <param name="name">
        /// The name of the runtime option to change, optionally prefixed with
        /// an operator character.
        /// </param>
        /// <param name="setVariable">
        /// Non-zero to update the associated script-level variable.
        /// </param>
        /// <param name="notify">
        /// Non-zero to issue a notification about the change.
        /// </param>
        /// <returns>
        /// True if the runtime option was changed; otherwise, false.
        /// </returns>
        private bool PrivateChangeRuntimeOption(
            string name,      /* in */
            bool setVariable, /* in */
            bool notify       /* in */
            )
        {
            if (String.IsNullOrEmpty(name))
                return false;

            char @operator = name[0];

            switch (@operator)
            {
                case Characters.PlusSign:
                    {
                        if (name.Length > 1)
                        {
                            return PrivateAddRuntimeOption(
                                name.Substring(1), setVariable, notify);
                        }

                        break;
                    }
                case Characters.MinusSign:
                    {
                        if (name.Length > 1)
                        {
                            return PrivateRemoveRuntimeOption(
                                name.Substring(1), setVariable, notify);
                        }

                        break;
                    }
                case Characters.EqualSign:
                    {
                        if (name.Length > 1)
                        {
                            return PrivateClearRuntimeOptions(
                                setVariable, notify) &&
                            PrivateAddRuntimeOption(
                                name.Substring(1), setVariable, notify);
                        }

                        break;
                    }
                default:
                    {
                        if (Parser.IsIdentifier(@operator))
                        {
                            return PrivateAddRuntimeOption(
                                name, setVariable, notify);
                        }

                        break;
                    }
            }

            return false;
        }

