        #region IResolveManager Members
        #region Variable Frame Resolution (WARNING: EXPERIMENTAL)
        /// <summary>
        /// This method attempts to resolve the call frame and variable name
        /// for a variable using the resolvers configured for this interpreter.
        /// </summary>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed, including whether
        /// verbose error information is gathered.
        /// </param>
        /// <param name="frame">
        /// On input, the call frame to use as the starting point; upon success,
        /// receives the resolved call frame.
        /// </param>
        /// <param name="varName">
        /// On input, the name of the variable to resolve; upon success, may
        /// receive the resolved variable name.
        /// </param>
        /// <param name="variableFlags">
        /// On input, the variable flags to use; upon success, may receive the
        /// updated variable flags.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        public ReturnCode GetVariableFrameViaResolvers(
            LookupFlags lookupFlags,         /* in */
            ref ICallFrame frame,            /* in, out */
            ref string varName,              /* in, out */
            ref VariableFlags variableFlags, /* in, out */
            ref Result error                 /* out */
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (HasResolvers(ref  error))
                {
                    ResultList errors = null;

                    foreach (IResolve resolve in resolvers)
                    {
                        if (resolve != null)
                        {
                            Result localError = null;

                            try
                            {
                                ReturnCode code = resolve.GetVariableFrame(
                                    ref frame, ref varName, ref variableFlags,
                                    ref localError);

                                if (code == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: Success, return the entity that this
                                    //       resolver found.
                                    //
                                    return ReturnCode.Ok;
                                }
                                else if (code == ReturnCode.Return)
                                {
                                    //
                                    // NOTE: Failure, return the error that this
                                    //       resolver returned verbatim.
                                    //
                                    error = localError;

                                    return ReturnCode.Error;
                                }
                                else if (code == ReturnCode.Break)
                                {
                                    //
                                    // NOTE: Failure, skip all other resolvers
                                    //       for this entity and return all the
                                    //       previously collected errors.
                                    //
                                    break;
                                }
                                else if (code == ReturnCode.Continue)
                                {
                                    //
                                    // NOTE: Failure, keep trying; however, do
                                    //       not add the error message from this
                                    //       resolver.
                                    //
                                    continue;
                                }
                            }
                            catch (Exception e)
                            {
                                if (FlagOps.HasFlags(
                                        lookupFlags, LookupFlags.Verbose, true))
                                {
                                    localError = e;
                                }
                            }

                            if (localError != null)
                            {
                                if (errors == null)
                                    errors = new ResultList();

                                errors.Add(localError);
                            }
                        }
                    }

                    if (errors != null)
                        error = errors;
                    else
                        error = "no resolvers defined";
                }
            }

            return ReturnCode.Error;
        }

