        /// <param name="hasFlags">
        /// The flags to check for on the call frame.
        /// </param>
        /// <param name="all">
        /// Non-zero if all of the specified flags must be set; otherwise, any
        /// one of them being set is sufficient.
        /// </param>
        /// <returns>
        /// True if the call frame has the specified flags set; false if it does
        /// not; or null if there is no applicable call frame.
        /// </returns>
        public bool? HasCallFrameFlags( /* EXPERIMENTAL */
            ICallFrame frame,        /* in */
            CallFrameFlags hasFlags, /* in */
            bool all                 /* in */
            )
        {
            CheckDisposed();

#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                frame = MaybeGetCurrentCallFrame(frame);

                if (frame == null)
                    return null;

                return FlagOps.HasFlags(frame.Flags, hasFlags, all);
            }
        }

