        //
        // WARNING: *EXPERIMENTAL* This API may change until the
        //          resolver subsystem is completed.
        //
        /// <summary>
        /// This method attempts to find a call frame matching the specified
        /// criteria, starting from a given call frame or the current one.
        /// </summary>
        /// <param name="absolute">
        /// Non-zero if the level is an absolute frame level; otherwise, it is
        /// relative to the starting call frame.
        /// </param>
        /// <param name="level">
        /// The call frame level to find.
        /// </param>
        /// <param name="hasFlags">
        /// The flags that a matching call frame must have set.
        /// </param>
        /// <param name="notHasFlags">
        /// The flags that a matching call frame must not have set.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero if all of the flags in <paramref name="hasFlags" /> must be
        /// set; otherwise, any one of them being set is sufficient.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero if all of the flags in <paramref name="notHasFlags" /> must
        /// be unset; otherwise, any one of them being unset is sufficient.
        /// </param>
        /// <param name="frame">
        /// On input, the call frame to use as the starting point, or null to
        /// use the current call frame; upon success, receives the matching call
        /// frame.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        public ReturnCode GetCallFrame( /* EXPERIMENTAL */
            bool absolute,              /* in */
            int level,                  /* in */
            CallFrameFlags hasFlags,    /* in */
            CallFrameFlags notHasFlags, /* in */
            bool hasAll,                /* in */
            bool notHasAll,             /* in */
            ref ICallFrame frame,       /* in, out */
            ref Result error            /* out */
            )
        {
            CheckDisposed();

#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                ICallFrame currentFrame =
                    (frame != null) ? frame : CurrentFrame;

                return CallFrameOps.GetOrFind(
                    CallStack, GlobalFrame /* EXEMPT */, CurrentGlobalFrame,
                    currentFrame, absolute, false, level, hasFlags,
                    notHasFlags, hasAll, notHasAll, ref frame, ref error);
            }
        }

