        #region Private
        /// <summary>
        /// This method returns the specified call frame, or the current call
        /// frame when none is specified.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use, or null to use the current call frame.
        /// </param>
        /// <returns>
        /// The specified call frame, or the current call frame when none is
        /// specified.
        /// </returns>
        private ICallFrame MaybeGetCurrentCallFrame(
            ICallFrame frame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                if (frame != null)
                    return frame;

                return CallFrameOps.FollowNext(CurrentFrame);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method parses the specified level specification text and
        /// attempts to locate the corresponding call frame.
        /// </summary>
        /// <param name="text">
        /// The level specification text identifying the call frame to locate.
        /// </param>
        /// <param name="otherFrame">
        /// Upon success, receives the located call frame.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// A value indicating how the level specification was processed and
        /// whether the call frame was located.
        /// </returns>
        internal FrameResult GetCallFrame(
            string text,
            ref ICallFrame otherFrame,
            ref Result error
            )
        {
            //
            // BUGBUG: Why not use the NoVariables (Tracking) flag here?
            //
            return Value.GetCallFrame(
                text, LevelFlags.All, CallStack, GlobalFrame /* EXEMPT */,
                CurrentGlobalFrame, CurrentFrame, CallFrameFlags.Variables,
                CallFrameFlags.Invisible | CallFrameFlags.NoVariables,
                false, false, Value.GetCallFrameValueFlags(false),
                InternalCultureInfo, ref otherFrame, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method parses the specified level specification text and
        /// attempts to locate the corresponding call frame, returning detailed
        /// information about how the level was interpreted.
        /// </summary>
        /// <param name="text">
        /// The level specification text identifying the call frame to locate.
        /// </param>
        /// <param name="mark">
        /// Upon return, receives a value indicating whether the located call
        /// frame should be marked.
        /// </param>
        /// <param name="absolute">
        /// Upon return, receives a value indicating whether the level was
        /// interpreted as absolute.
        /// </param>
        /// <param name="super">
        /// Upon return, receives a value indicating whether a super-global
        /// level was requested.
        /// </param>
        /// <param name="level">
        /// Upon return, receives the resolved call frame level.
        /// </param>
        /// <param name="currentFrame">
        /// Upon return, receives the current call frame used as the starting
        /// point for resolution.
        /// </param>
        /// <param name="otherFrame">
        /// Upon success, receives the located call frame.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// A value indicating how the level specification was processed and
        /// whether the call frame was located.
        /// </returns>
        internal FrameResult GetCallFrame(
            string text,
            ref bool mark,
            ref bool absolute,
            ref bool super,
            ref int level,
            ref ICallFrame currentFrame,
            ref ICallFrame otherFrame,
            ref Result error
            )
        {
            //
            // BUGBUG: Why not use the NoVariables (Tracking) flag here?
            //
            currentFrame = CurrentFrame;

            return Value.GetCallFrame(
                text, LevelFlags.All, CallStack, GlobalFrame /* EXEMPT */,
                CurrentGlobalFrame, currentFrame, CallFrameFlags.Variables,
                CallFrameFlags.Invisible | CallFrameFlags.NoVariables,
                false, false, Value.GetCallFrameValueFlags(false),
                InternalCultureInfo, ref mark, ref absolute, ref super,
                ref level, ref otherFrame, ref error);
        }
        #endregion
        #endregion

