        /// The engine flags to be used during resolution.
        /// </returns>
        internal static EngineFlags GetResolveEngineFlags(
            EngineFlags engineFlags,
            bool exact
            )
        {
            return Engine.GetResolveFlags(engineFlags, exact);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adjusts the supplied engine flags so that hidden entities
        /// are matched consistently regardless of whether exact name matching is
        /// being performed.
        /// </summary>
        /// <param name="engineFlags">
        /// The base engine flags to adjust.
        /// </param>
        /// <param name="exact">
        /// Non-zero if exact name matching is being performed.
        /// </param>
        /// <returns>
        /// The adjusted engine flags.
        /// </returns>
        private static EngineFlags GetMatchAnyEngineFlags(
            EngineFlags engineFlags,
            bool exact
            )
        {
            EngineFlags result = engineFlags;

            if (exact)
            {
                if (EngineFlagOps.HasMatchHidden(result))
                    result |= EngineFlags.GetHidden;
            }
            else
            {
                if (EngineFlagOps.HasGetHidden(result))
                    result |= EngineFlags.MatchHidden;
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method optionally unwraps an executable entity from its wrapper,
        /// discarding any error information.
        /// </summary>
        /// <param name="lookupFlags">
        /// Flags that control how the unwrapping is performed.
        /// </param>
        /// <param name="executeWrapper">
        /// The wrapper containing the executable entity to unwrap.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the unwrapped executable entity.
        /// </param>
        /// <returns>
        /// True if the executable entity was unwrapped (or unwrapping was not
        /// required); otherwise, false.
        /// </returns>
        private static bool MaybeUnwrapIExecute(
            LookupFlags lookupFlags, /* in */
            IExecute executeWrapper, /* in */
            ref IExecute execute     /* out */
            )
        {
            Result error = null;

            return MaybeUnwrapIExecute(
                lookupFlags | LookupFlags.NoVerbose, executeWrapper,
                ref execute, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method optionally unwraps an executable entity from its
        /// wrapper.
        /// </summary>
        /// <param name="lookupFlags">
        /// Flags that control how the unwrapping is performed, including whether
        /// the wrapper itself is used and whether the result is validated.
        /// </param>
        /// <param name="executeWrapper">
        /// The wrapper containing the executable entity to unwrap.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the unwrapped executable entity.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// True if the executable entity was unwrapped (or unwrapping was not
        /// required); otherwise, false.
        /// </returns>
        private static bool MaybeUnwrapIExecute(
            LookupFlags lookupFlags, /* in */
            IExecute executeWrapper, /* in */
            ref IExecute execute,    /* out */
            ref Result error         /* out */
            )
        {
            if (FlagOps.HasFlags(lookupFlags, LookupFlags.Wrapper, true))
            {
                //
                // NOTE: The caller, PrivateMatchAnyIExecute, must make sure
                //       the "executeWrapper" parameter is in fact a wrapper.
                //
                execute = executeWrapper;
            }
            else
            {
                IWrapper wrapper = executeWrapper as IWrapper;

                if (wrapper != null)
                    execute = wrapper.Object as IExecute;
                else
                    execute = null;
            }

            //
            // NOTE: At this point, either the IExecute must be valid -OR-
            //       the Validate lookup flag must be unset; otherwise, this
            //       method has failed (i.e. thus emulating the behavior of
            //       the associated PrivateGet* methods).
            //
            if ((execute == null) &&
                FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true))
            {
                if (!FlagOps.HasFlags(lookupFlags, LookupFlags.NoVerbose, true))
                    error = "invalid execute";

                return false;
            }

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if EXECUTE_CACHE
        /// <summary>
        /// This method attempts to retrieve a previously cached executable
        /// entity by name from the appropriate execute cache.
        /// </summary>
        /// <param name="name">
        /// The name of the cached executable entity to retrieve.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed.
        /// </param>
        /// <param name="useHidden">
        /// Non-zero to retrieve from the hidden execute cache; otherwise, the
        /// normal execute cache is used.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the cached executable entity.
        /// </param>
        /// <returns>
        /// True if the executable entity was found in the cache; otherwise,
        /// false.
        /// </returns>
        private bool TryGetIExecuteFromCache(
            string name,
            LookupFlags lookupFlags,
            bool useHidden,
            ref IExecute execute
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                IExecute localExecute = null;

                if (useHidden)
                {
                    if (hiddenExecuteCache != null)
                    {
                        if (hiddenExecuteCache.TryGet(name,
                                FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true),
                                ref localExecute))
                        {
                            if (MaybeUnwrapIExecute(
                                    lookupFlags, localExecute, ref localExecute))
                            {
#if CACHE_STATISTICS
                                /* IGNORED */
                                hiddenExecuteCache.IncrementCacheCount(CacheCountType.Hit);
#endif

                                execute = localExecute;
                                return true;
                            }
#if CACHE_STATISTICS
                            else
                            {
                                /* IGNORED */
                                hiddenExecuteCache.IncrementCacheCount(CacheCountType.Miss);
                            }
#endif
                        }
#if CACHE_STATISTICS
                        else
                        {
                            /* IGNORED */
                            hiddenExecuteCache.IncrementCacheCount(CacheCountType.Miss);
                        }
#endif
                    }
                }
                else
                {
                    if (executeCache != null)
                    {
                        if (executeCache.TryGet(name,
                                FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true),
                                ref localExecute))
                        {
                            if (MaybeUnwrapIExecute(
                                    lookupFlags, localExecute, ref localExecute))
                            {
#if CACHE_STATISTICS
                                /* IGNORED */
                                executeCache.IncrementCacheCount(CacheCountType.Hit);
#endif

                                execute = localExecute;
                                return true;
                            }
#if CACHE_STATISTICS
                            else
                            {
                                /* IGNORED */
                                executeCache.IncrementCacheCount(CacheCountType.Miss);
                            }
#endif
                        }
#if CACHE_STATISTICS
                        else
                        {
                            /* IGNORED */
                            executeCache.IncrementCacheCount(CacheCountType.Miss);
                        }
#endif
                    }
                }
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method optionally unwraps the specified executable entity and
        /// then adds it to, or updates it in, the appropriate execute cache.
        /// </summary>
        /// <param name="lookupFlags">
        /// Flags that control how the unwrapping is performed.
        /// </param>
        /// <param name="name">
        /// The name under which the executable entity is cached.
        /// </param>
        /// <param name="execute">
        /// The executable entity to cache.
        /// </param>
        /// <param name="useHidden">
        /// Non-zero to use the hidden execute cache; otherwise, the normal
        /// execute cache is used.
        /// </param>
        /// <param name="invalidate">
        /// Non-zero to invalidate any existing cached entry for the specified
        /// name.
        /// </param>
        /// <returns>
        /// True if the cache was successfully updated; otherwise, false.
        /// </returns>
        private bool MaybeUnwrapIExecuteAndAddOrUpdateToCache(
            LookupFlags lookupFlags,
            string name,
            IExecute execute,
            bool useHidden,
            bool invalidate
            )
        {
            IExecute localExecute = null;

            if (!MaybeUnwrapIExecute(
                    lookupFlags & ~LookupFlags.Wrapper,
                    execute, ref localExecute))
            {
                localExecute = execute;
            }

            return AddOrUpdateIExecuteToCache(
                name, localExecute, useHidden, invalidate);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified executable entity to, or updates it
        /// in, the appropriate execute cache.
        /// </summary>
        /// <param name="name">
        /// The name under which the executable entity is cached.
        /// </param>
        /// <param name="execute">
        /// The executable entity to cache.
        /// </param>
        /// <param name="useHidden">
        /// Non-zero to use the hidden execute cache; otherwise, the normal
        /// execute cache is used.
        /// </param>
        /// <param name="invalidate">
        /// Non-zero to invalidate any existing cached entry for the specified
        /// name.
        /// </param>
        /// <returns>
        /// True if the cache was successfully updated; otherwise, false.
        /// </returns>
        private bool AddOrUpdateIExecuteToCache(
            string name,
            IExecute execute,
            bool useHidden,
            bool invalidate
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (useHidden)
                {
                    if (hiddenExecuteCache != null)
                    {
                        Interlocked.Increment(ref cacheGeneration);

                        return hiddenExecuteCache.AddOrUpdate(
                            name, execute, invalidate);
                    }
                }
                else
                {
                    if (executeCache != null)
                    {
                        Interlocked.Increment(ref cacheGeneration);

                        return executeCache.AddOrUpdate(
                            name, execute, invalidate);
                    }
                }

                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method renames a cached executable entity in the appropriate
        /// execute cache.
        /// </summary>
        /// <param name="oldName">
        /// The current name of the cached executable entity.
        /// </param>
        /// <param name="newName">
        /// The new name to assign to the cached executable entity.
        /// </param>
        /// <param name="execute">
        /// The executable entity associated with the cache entry.
        /// </param>
        /// <param name="useHidden">
        /// Non-zero to use the hidden execute cache; otherwise, the normal
        /// execute cache is used.
        /// </param>
        /// <param name="invalidate">
        /// Non-zero to invalidate any existing cached entry involved in the
        /// rename.
        /// </param>
        /// <returns>
        /// True if the cache entry was successfully renamed; otherwise, false.
        /// </returns>
        private bool RenameIExecuteInCache(
            string oldName,
            string newName,
            IExecute execute,
            bool useHidden,
            bool invalidate
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (useHidden)
                {
                    if (hiddenExecuteCache != null)
                    {
                        Interlocked.Increment(ref cacheGeneration);

                        return hiddenExecuteCache.Rename(
                            oldName, newName, execute, invalidate);
                    }
                }
                else
                {
                    if (executeCache != null)
                    {
                        Interlocked.Increment(ref cacheGeneration);

                        return executeCache.Rename(
                            oldName, newName, execute, invalidate);
                    }
                }

                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes a cached executable entity from the appropriate
        /// execute cache.
        /// </summary>
        /// <param name="name">
        /// The name of the cached executable entity to remove.
        /// </param>
        /// <param name="useHidden">
        /// Non-zero to use the hidden execute cache; otherwise, the normal
        /// execute cache is used.
        /// </param>
        /// <param name="invalidate">
        /// Non-zero to invalidate the cached entry being removed.
        /// </param>
        /// <returns>
        /// True if the cache entry was successfully removed; otherwise, false.
        /// </returns>
        private bool RemoveIExecuteFromCache(
            string name,
            bool useHidden,
            bool invalidate
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (useHidden)
                {
                    if (hiddenExecuteCache != null)
                    {
                        Interlocked.Increment(ref cacheGeneration);

                        return hiddenExecuteCache.Remove(
                            name, invalidate);
                    }
                }
                else
                {
                    if (executeCache != null)
                    {
                        Interlocked.Increment(ref cacheGeneration);

                        return executeCache.Remove(
                            name, invalidate);
                    }
                }

                return false;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to look up any executable entity (an IExecute,
        /// procedure, or command) by name, consulting the execute cache when it
        /// is enabled.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use as the context for the lookup.  This parameter
        /// is not used.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags that control which kinds of entities are considered
        /// and whether hidden entities are used.
        /// </param>
        /// <param name="name">
        /// The name of the entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token associated with the resolved
        /// entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the resolved executable entity.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateGetAnyIExecute(
            ICallFrame frame, /* NOT USED */
            EngineFlags engineFlags,
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IExecute execute,
            ref Result error
            )
        {
            string newName = ScriptOps.MakeCommandName(name);

#if EXECUTE_CACHE
            bool noCache = FlagOps.HasFlags(lookupFlags, LookupFlags.NoCache, true) ||
                EngineFlagOps.HasNoCache(engineFlags);
#endif

            bool useHidden = EngineFlagOps.HasUseHidden(engineFlags);
            IExecute localExecute; /* REUSED */

#if EXECUTE_CACHE
            localExecute = null;

            if (!noCache &&
                TryGetIExecuteFromCache(newName, lookupFlags, useHidden, ref localExecute))
            {
                execute = localExecute;
                return ReturnCode.Ok;
            }
#endif

            localExecute = null;

            if (EngineFlagOps.HasUseIExecutes(engineFlags) &&
                 ((useHidden && (GetHiddenIExecute(
                    newName, lookupFlags, ref localExecute) == ReturnCode.Ok)) ||
                 (!useHidden && (GetIExecute(
                    newName, lookupFlags, ref localExecute) == ReturnCode.Ok))))
            {
#if EXECUTE_CACHE
                if (!noCache)
                {
                    MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                        lookupFlags, newName, localExecute, useHidden, false);
                }
#endif

                execute = localExecute;
                return ReturnCode.Ok;
            }
            else
            {
                IProcedure localProcedure = null;

                if (EngineFlagOps.HasUseProcedures(engineFlags) &&
                    ((useHidden && (GetHiddenProcedure(
                        newName, lookupFlags, ref localProcedure) == ReturnCode.Ok)) ||
                    (!useHidden && (GetProcedure(
                        newName, lookupFlags, ref localProcedure) == ReturnCode.Ok))))
                {
#if EXECUTE_CACHE
                    if (!noCache)
                    {
                        MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                            lookupFlags, newName, localProcedure, useHidden, false);
                    }
#endif

                    execute = localProcedure;
                    return ReturnCode.Ok;
                }
                else
                {
                    ICommand localCommand = null;

                    if (EngineFlagOps.HasUseCommands(engineFlags) &&
                        ((useHidden && (GetHiddenCommand(
                            newName, lookupFlags, ref localCommand) == ReturnCode.Ok)) ||
                        (!useHidden && (GetCommand(
                            newName, lookupFlags, ref localCommand) == ReturnCode.Ok))))
                    {
#if EXECUTE_CACHE
                        if (!noCache)
                        {
                            MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                                lookupFlags, newName, localCommand, useHidden, false);
                        }
#endif

                        execute = localCommand;
                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "invalid {0}command name {1}",
                                useHidden ? "hidden " : String.Empty,
                                FormatOps.DisplayName(name)) :
                            "invalid command name";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to match any executable entity (an IExecute,
        /// procedure, or command) using the specified name as a pattern,
        /// reporting whether the match was ambiguous.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use as the context for the lookup.  This parameter
        /// is not used.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags that control which kinds of entities are considered
        /// and whether hidden entities are used.
        /// </param>
        /// <param name="name">
        /// The name or pattern of the entity to match.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed.
        /// </param>
        /// <param name="ambiguous">
        /// Upon return, receives a value indicating whether the specified name
        /// matched more than one entity.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token associated with the matched entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the matched executable entity.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateMatchAnyIExecute(
            ICallFrame frame, /* NOT USED */
            EngineFlags engineFlags,
            string name,
            LookupFlags lookupFlags,
            ref bool ambiguous,
            ref long token,
            ref IExecute execute,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // NOTE: *WARNING* Empty command/procedure names are allowed,
                //       please do not change this to "!String.IsNullOrEmpty".
                //
                if (name != null)
                {
                    string newName = ScriptOps.MakeCommandPattern(name);

#if EXECUTE_CACHE
                    bool noCache = FlagOps.HasFlags(lookupFlags, LookupFlags.NoCache, true) ||
                        EngineFlagOps.HasNoCache(engineFlags);
#endif

                    bool useHidden = EngineFlagOps.HasUseHidden(engineFlags);

#if EXECUTE_CACHE
                    if (!noCache &&
                        TryGetIExecuteFromCache(newName, lookupFlags, useHidden, ref execute))
                    {
                        return ReturnCode.Ok;
                    }
#endif

                    string exactName = null;
                    ExecuteDictionary matches = new ExecuteDictionary();

                    if (exactName == null)
                    {
                        if (EngineFlagOps.HasUseIExecutes(engineFlags))
                        {
                            ExecuteWrapperDictionary localExecutes = useHidden ?
                                hiddenExecutes : executes;

                            if ((localExecutes != null) && (localExecutes.Count > 0))
                            {
                                ExecuteWrapper localExecute;

                                if (localExecutes.TryGetValue(newName, out localExecute))
                                {
                                    //
                                    // NOTE: Exact execute match.
                                    //
                                    exactName = newName;

                                    //
                                    // NOTE: Store the exact execute match in the results
                                    //       dictionary.
                                    //
                                    matches.Add(newName, localExecute);
                                }
                                else
                                {
                                    foreach (ExecutePair pair in localExecutes)
                                    {
                                        if (SharedStringOps.SystemEquals(pair.Key, 0, newName, 0, newName.Length))
                                        {
                                            //
                                            // NOTE: Was the key valid (this should always succeed).
                                            //
                                            if (pair.Key != null)
                                            {
                                                //
                                                // NOTE: It was a match; however, was it an exact match?
                                                //
                                                if (pair.Key.Length == newName.Length)
                                                    //
                                                    // NOTE: Preserve match, it may differ in case.
                                                    //
                                                    exactName = pair.Key;

                                                //
                                                // NOTE: Was it an exact match or did we match at least one
                                                //       character in a partial match?
                                                //
                                                if ((pair.Key.Length == newName.Length) || (newName.Length > 0))
                                                    //
                                                    // NOTE: Store the exact or partial match in the results
                                                    //       dictionary.
                                                    //
                                                    matches.Add(pair.Key, pair.Value);
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    bool matchHidden = EngineFlagOps.HasMatchHidden(engineFlags);

                    if (exactName == null)
                    {
                        if (EngineFlagOps.HasUseProcedures(engineFlags))
                        {
                            ProcedureWrapperDictionary localProcedures = useHidden ?
                                hiddenProcedures : procedures;

                            if ((localProcedures != null) && (localProcedures.Count > 0))
                            {
                                ProcedureWrapper localProcedure;

                                if (localProcedures.TryGetValue(newName, out localProcedure) &&
                                    (matchHidden || !EntityOps.IsHidden(localProcedure)))
                                {
                                    //
                                    // NOTE: Exact procedure match.
                                    //
                                    exactName = newName;

                                    //
                                    // NOTE: Store the exact procedure match in the results
                                    //       dictionary.
                                    //
                                    matches.Add(newName, localProcedure);
                                }
                                else
                                {
                                    foreach (ProcedurePair pair in localProcedures)
                                    {
                                        if (SharedStringOps.SystemEquals(pair.Key, 0, newName, 0, newName.Length))
                                        {
                                            //
                                            // NOTE: Is the procedure visible or are we allowed to
                                            //       find hidden procedures?
                                            //
                                            if (matchHidden || !EntityOps.IsHidden(pair.Value))
                                            {
                                                //
                                                // NOTE: Was the key valid (this should always succeed).
                                                //
                                                if (pair.Key != null)
                                                {
                                                    //
                                                    // NOTE: It was a match; however, was it an exact match?
                                                    //
                                                    if (pair.Key.Length == newName.Length)
                                                        //
                                                        // NOTE: Preserve match, it may differ in case.
                                                        //
                                                        exactName = pair.Key;

                                                    //
                                                    // NOTE: Was it an exact match or did we match at least one
                                                    //       character in a partial match?
                                                    //
                                                    if ((pair.Key.Length == newName.Length) || (newName.Length > 0))
                                                        //
                                                        // NOTE: Store the exact or partial match in the results
                                                        //       dictionary.
                                                        //
                                                        matches.Add(pair.Key, pair.Value);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    if (exactName == null)
                    {
                        if (EngineFlagOps.HasUseCommands(engineFlags))
                        {
                            CommandWrapperDictionary localCommands = useHidden ?
                                hiddenCommands : commands;

                            if ((localCommands != null) && (localCommands.Count > 0))
                            {
                                CommandWrapper localCommand;

                                if (localCommands.TryGetValue(newName, out localCommand) &&
                                    (matchHidden || !EntityOps.IsHidden(localCommand)))
                                {
                                    //
                                    // NOTE: Exact command match.
                                    //
                                    exactName = newName;

                                    //
                                    // NOTE: Store the exact command match in the results
                                    //       dictionary.
                                    //
                                    matches.Add(newName, localCommand);
                                }
                                else
                                {
                                    foreach (CommandPair pair in localCommands)
                                    {
                                        if (SharedStringOps.SystemEquals(pair.Key, 0, newName, 0, newName.Length))
                                        {
                                            //
                                            // NOTE: Is the command visible or are we allowed to
                                            //       find hidden command?
                                            //
                                            if (matchHidden || !EntityOps.IsHidden(pair.Value))
                                            {
                                                //
                                                // NOTE: Was the key valid (this should always succeed).
                                                //
                                                if (pair.Key != null)
                                                {
                                                    //
                                                    // NOTE: It was a match; however, was it an exact match?
                                                    //
                                                    if (pair.Key.Length == newName.Length)
                                                        //
                                                        // NOTE: Preserve match, it may differ in case.
                                                        //
                                                        exactName = pair.Key;

                                                    //
                                                    // NOTE: Was it an exact match or did we match at least one
                                                    //       character in a partial match?
                                                    //
                                                    if ((pair.Key.Length == newName.Length) || (newName.Length > 0))
                                                        //
                                                        // NOTE: Store the exact or partial match in the results
                                                        //       dictionary.
                                                        //
                                                        matches.Add(pair.Key, pair.Value);
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }

                    //
                    // NOTE: If there was an exact match, just use it.
                    //
                    // BUGFIX: We need to make 100% sure that we get the wrapper here
                    //         because that is what we want to store in the execute
                    //         cache.  Otherwise, the cache cannot satisfy requests
                    //         for the wrapper later (i.e. based on the lookup flags
                    //         for each call).
                    //
                    LookupFlags localLookupFlags = lookupFlags | LookupFlags.Wrapper;

                    if (exactName != null)
                    {
                        //
                        // NOTE: Exact match, return the matching command or
                        //       procedure.
                        //
                        IExecute match = matches[exactName];

                        if (match is ExecuteWrapper)
                        {
                            long localToken = 0;
                            IExecute localExecute = null;

                            if ((useHidden && PrivateGetHiddenIExecute(
                                    exactName, localLookupFlags, ref localToken,
                                    ref localExecute, ref error) == ReturnCode.Ok) ||
                                (!useHidden && PrivateGetIExecute(
                                    exactName, localLookupFlags, ref localToken,
                                    ref localExecute, ref error) == ReturnCode.Ok))
                            {
#if EXECUTE_CACHE
                                if (!noCache)
                                {
                                    MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                                        lookupFlags, exactName, localExecute, useHidden, false);
                                }
#endif

                                if (MaybeUnwrapIExecute(
                                        lookupFlags, localExecute, ref localExecute, ref error))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        NotifyType.Resolver | (useHidden ? NotifyType.HiddenIExecute : NotifyType.IExecute),
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, exactName, localExecute, localToken), this, null, null, null,
                                        ref error);
#endif

                                    token = localToken;
                                    execute = localExecute;

                                    return ReturnCode.Ok;
                                }
                            }
                        }
                        else if (match is ProcedureWrapper)
                        {
                            long localToken = 0;
                            IProcedure localProcedure = null;
                            IExecute localExecute = null;

                            if ((useHidden && PrivateGetHiddenProcedure(
                                    exactName, localLookupFlags, ref localToken,
                                    ref localProcedure, ref error) == ReturnCode.Ok) ||
                                (!useHidden && PrivateGetProcedure(
                                    exactName, localLookupFlags, ref localToken,
                                    ref localProcedure, ref error) == ReturnCode.Ok))
                            {
#if EXECUTE_CACHE
                                if (!noCache)
                                {
                                    MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                                        lookupFlags, exactName, localProcedure, useHidden, false);
                                }
#endif

                                if (MaybeUnwrapIExecute(
                                        lookupFlags, localProcedure, ref localExecute, ref error))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        NotifyType.Resolver | (useHidden ? NotifyType.HiddenProcedure : NotifyType.Procedure),
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, exactName, localProcedure, localToken), this, null, null, null,
                                        ref error);
#endif

                                    token = localToken;
                                    execute = localExecute;

                                    return ReturnCode.Ok;
                                }
                            }
                        }
                        else if (match is CommandWrapper)
                        {
                            long localToken = 0;
                            ICommand localCommand = null;
                            IExecute localExecute = null;

                            if ((useHidden && PrivateGetHiddenCommand(
                                    exactName, localLookupFlags, ref localToken,
                                    ref localCommand, ref error) == ReturnCode.Ok) ||
                                (!useHidden && PrivateGetCommand(
                                    exactName, localLookupFlags, ref localToken,
                                    ref localCommand, ref error) == ReturnCode.Ok))
                            {
#if EXECUTE_CACHE
                                if (!noCache)
                                {
                                    MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                                        lookupFlags, exactName, localCommand, useHidden, false);
                                }
#endif

                                if (MaybeUnwrapIExecute(
                                        lookupFlags, localCommand, ref localExecute, ref error))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        NotifyType.Resolver | (useHidden ? NotifyType.HiddenCommand : NotifyType.Command),
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, exactName, localCommand, localToken), this, null, null, null,
                                        ref error);
#endif

                                    token = localToken;
                                    execute = localExecute;

                                    return ReturnCode.Ok;
                                }
                            }
                        }
                        else
                        {
                            error = FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Verbose, true) ?
                                String.Format(
                                    "object {0} is not an execute, procedure, or command wrapper",
                                    FormatOps.WrapOrNull(exactName)) :
                                "object is not an execute, procedure, or command wrapper";
                        }
                    }
                    else if (matches.Count == 1)
                    {
                        string key = new StringList(matches.Keys)[0];

                        //
                        // NOTE: Normal case, exactly one command matched.
                        //
                        if (matches[key] is ExecuteWrapper)
                        {
                            long localToken = 0;
                            IExecute localExecute = null;

                            if ((useHidden && (PrivateGetHiddenIExecute(
                                    key, localLookupFlags, ref localToken,
                                    ref localExecute, ref error) == ReturnCode.Ok)) ||
                                (!useHidden && (PrivateGetIExecute(
                                    key, localLookupFlags, ref localToken,
                                    ref localExecute, ref error) == ReturnCode.Ok)))
                            {
#if EXECUTE_CACHE
                                if (!noCache)
                                {
                                    MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                                        lookupFlags, key, localExecute, useHidden, false);
                                }
#endif

                                if (MaybeUnwrapIExecute(
                                        lookupFlags, localExecute, ref localExecute, ref error))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        NotifyType.Resolver | (useHidden ? NotifyType.HiddenIExecute : NotifyType.IExecute),
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, key, localExecute, localToken), this, null, null, null,
                                        ref error);
#endif

                                    token = localToken;
                                    execute = localExecute;

                                    return ReturnCode.Ok;
                                }
                            }
                        }
                        else if (matches[key] is ProcedureWrapper)
                        {
                            long localToken = 0;
                            IProcedure localProcedure = null;
                            IExecute localExecute = null;

                            if ((useHidden && (PrivateGetHiddenProcedure(
                                    key, localLookupFlags, ref localToken,
                                    ref localProcedure, ref error) == ReturnCode.Ok)) ||
                                (!useHidden && (PrivateGetProcedure(
                                    key, localLookupFlags, ref localToken,
                                    ref localProcedure, ref error) == ReturnCode.Ok)))
                            {
#if EXECUTE_CACHE
                                if (!noCache)
                                {
                                    MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                                        lookupFlags, key, localProcedure, useHidden, false);
                                }
#endif

                                if (MaybeUnwrapIExecute(
                                        lookupFlags, localProcedure, ref localExecute, ref error))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        NotifyType.Resolver | (useHidden ? NotifyType.HiddenProcedure : NotifyType.Procedure),
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, key, localProcedure, localToken), this, null, null, null,
                                        ref error);
#endif

                                    token = localToken;
                                    execute = localExecute;

                                    return ReturnCode.Ok;
                                }
                            }
                        }
                        else if (matches[key] is CommandWrapper)
                        {
                            long localToken = 0;
                            ICommand localCommand = null;
                            IExecute localExecute = null;

                            if ((useHidden && (PrivateGetHiddenCommand(
                                    key, localLookupFlags, ref localToken,
                                    ref localCommand, ref error) == ReturnCode.Ok)) ||
                                (!useHidden && (PrivateGetCommand(
                                    key, localLookupFlags, ref localToken,
                                    ref localCommand, ref error) == ReturnCode.Ok)))
                            {
#if EXECUTE_CACHE
                                if (!noCache)
                                {
                                    MaybeUnwrapIExecuteAndAddOrUpdateToCache(
                                        lookupFlags, key, localCommand, useHidden, false);
                                }
#endif

                                if (MaybeUnwrapIExecute(
                                        lookupFlags, localCommand, ref localExecute, ref error))
                                {
#if NOTIFY
                                    /* IGNORED */
                                    CheckNotification(
                                        NotifyType.Resolver | (useHidden ? NotifyType.HiddenCommand : NotifyType.Command),
                                        NotifyFlags.Matched | (useHidden ? NotifyFlags.Hidden : NotifyFlags.None),
                                        new ObjectList(engineFlags, name, key, localCommand, localToken), this, null, null, null,
                                        ref error);
#endif

                                    token = localToken;
                                    execute = localExecute;

                                    return ReturnCode.Ok;
                                }
                            }
                        }
                        else
                        {
                            error = FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Verbose, true) ?
                                String.Format(
                                    "object {0} is not an execute, procedure, or command wrapper",
                                    FormatOps.WrapOrNull(key)) :
                                "object is not an execute, procedure, or command wrapper";
                        }
                    }
                    else if (matches.Count > 1)
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            ScriptOps.BadValue(
                                "ambiguous", useHidden ?
                                "hidden command" : "command", name, matches.Keys,
                                null, null) :
                            (Result)"ambiguous command";

                        ambiguous = true;
                    }
                    else
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "invalid {0}command name {1}",
                                useHidden ? "hidden " : String.Empty,
                                FormatOps.WrapOrNull(name)) :
                            "invalid command name";
                    }
                }
                else
                {
                    error = "invalid command name";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up any executable entity (an IExecute, procedure,
        /// or command) by exact name, falling back to hidden entities when
        /// appropriate.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use as the context for the lookup.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags that control which kinds of entities are considered
        /// and whether hidden entities are used.
        /// </param>
        /// <param name="name">
        /// The name of the entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token associated with the resolved
        /// entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the resolved executable entity.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        internal ReturnCode GetAnyIExecute(
            ICallFrame frame,
            EngineFlags engineFlags,
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IExecute execute,
            ref Result error
            ) /* USED BY CORE RESOLVER */
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return PrivateGetAnyIExecute2(
                    frame, engineFlags, name, lookupFlags, ref token,
                    ref execute, ref error);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up any executable entity (an IExecute, procedure,
        /// or command) by exact name, optionally falling back to a search of the
        /// hidden entities so that policies may govern their execution.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use as the context for the lookup.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags that control which kinds of entities are considered
        /// and whether hidden entities are used.
        /// </param>
        /// <param name="name">
        /// The name of the entity to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token associated with the resolved
        /// entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the resolved executable entity.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateGetAnyIExecute2(
            ICallFrame frame,
            EngineFlags engineFlags,
            string name,
            LookupFlags lookupFlags,
            ref long token,
            ref IExecute execute,
            ref Result error
            ) /* USED BY CORE RESOLVER */
        {
            //
            // NOTE: When searching for [non-hidden] commands, fallback to
            //       searching the hidden commands also to give the policies,
            //       if any, a chance to allow or deny their execution;
            //       however, only do this if the appropriate flag (i.e. the
            //       MatchHidden flag) is set.
            //
            Result localError = null;

            if (PrivateGetAnyIExecute(
                    frame, engineFlags, name, lookupFlags, ref token,
                    ref execute, ref localError) == ReturnCode.Ok)
            {
                return ReturnCode.Ok;
            }
            else if (RuntimeOps.ShouldResolveHidden(engineFlags, false))
            {
                Result localError2 = null; /* VALUE NOT USED */

                if (PrivateGetAnyIExecute(
                        frame, engineFlags | EngineFlags.UseHidden,
                        name, lookupFlags, ref token, ref execute,
                        ref localError2) == ReturnCode.Ok)
                {
                    return ReturnCode.Ok;
                }
            }

            error = localError;
            return ReturnCode.Error;
        }

