        /// <summary>
        /// This method builds a dictionary of executable entities (commands and
        /// procedures) whose names match the specified pattern.
        /// </summary>
        /// <param name="pattern">
        /// The pattern to match entity names against, or null to match all
        /// entities.
        /// </param>
        /// <param name="noCase">
        /// Non-zero to perform case-insensitive pattern matching.
        /// </param>
        /// <param name="hidden">
        /// Non-zero to include hidden entities in the results.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat the absence of a given category of entities as an
        /// error.
        /// </param>
        /// <param name="dictionary">
        /// Upon success, receives the dictionary of matching entities.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        internal ReturnCode ListAnyIExecute(
            string pattern,
            bool noCase,
            bool hidden,
            bool strict,
            ref ObjectDictionary dictionary,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                ResultList errors = null;
                ObjectDictionary localDictionary = null;
                Result localError = null;

                ///////////////////////////////////////////////////////////////////////////////////////

                if (PrivateHasCommands(ref localError))
                {
                    if (commands.ToDictionary(
                            pattern, noCase, ref localDictionary,
                            ref localError) != ReturnCode.Ok)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }
                }
                else if (strict)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(localError);
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (PrivateHasProcedures(ref localError))
                {
                    if (procedures.ToDictionary(
                            pattern, noCase, ref localDictionary,
                            ref localError) != ReturnCode.Ok)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }
                }
                else if (strict)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(localError);
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (PrivateHasIExecutes(ref localError))
                {
                    if (executes.ToDictionary(
                            pattern, noCase, ref localDictionary,
                            ref localError) != ReturnCode.Ok)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }
                }
                else if (strict)
                {
                    if (errors == null)
                        errors = new ResultList();

                    errors.Add(localError);
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (hidden)
                {
                    if (PrivateHasHiddenCommands(ref localError))
                    {
                        if (hiddenCommands.ToDictionary(
                                pattern, noCase, ref localDictionary,
                                ref localError) != ReturnCode.Ok)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(localError);
                        }
                    }
                    else if (strict)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }

                    ///////////////////////////////////////////////////////////////////////////////////

                    if (PrivateHasHiddenProcedures(ref localError))
                    {
                        if (hiddenProcedures.ToDictionary(
                                pattern, noCase, ref localDictionary,
                                ref localError) != ReturnCode.Ok)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(localError);
                        }
                    }
                    else if (strict)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }

                    ///////////////////////////////////////////////////////////////////////////////////

                    if (PrivateHasHiddenIExecutes(ref localError))
                    {
                        if (hiddenExecutes.ToDictionary(
                                pattern, noCase, ref localDictionary,
                                ref localError) != ReturnCode.Ok)
                        {
                            if (errors == null)
                                errors = new ResultList();

                            errors.Add(localError);
                        }
                    }
                    else if (strict)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(localError);
                    }
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (errors != null)
                {
                    error = errors;
                    return ReturnCode.Error;
                }

                dictionary = localDictionary;
                return ReturnCode.Ok;
            }
        }

