        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to resolve a command (or other executable
        /// entity) by name by consulting each resolver configured for this
        /// interpreter in turn, also reporting whether the name was ambiguous
        /// and the associated token.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use as the context for resolution.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags to use during resolution.
        /// </param>
        /// <param name="name">
        /// The name of the command (or other executable entity) to resolve.
        /// </param>
        /// <param name="arguments">
        /// The arguments associated with the command being resolved, if any.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed.
        /// </param>
        /// <param name="ambiguous">
        /// Upon return, receives a value indicating whether the specified name
        /// matched more than one entity.
        /// </param>
        /// <param name="token">
        /// Upon success, receives the token associated with the resolved
        /// entity.
        /// </param>
        /// <param name="execute">
        /// Upon success, receives the resolved executable entity.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateGetIExecuteViaResolvers( /* EXPERIMENTAL */
            ICallFrame frame,
            EngineFlags engineFlags,
            string name,
            ArgumentList arguments,
            LookupFlags lookupFlags,
            ref bool ambiguous,
            ref long token,
            ref IExecute execute,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (HasResolvers(ref error))
                {
                    ResultList errors = null;

                    foreach (IResolve resolve in resolvers)
                    {
                        if (resolve != null)
                        {
                            Result localError = null;

                            try
                            {
                                ReturnCode code = resolve.GetIExecute(frame,
                                    engineFlags, name, arguments, lookupFlags,
                                    ref ambiguous, ref token, ref execute,
                                    ref localError);

                                if (code == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: Success, return the entity that this
                                    //       resolver found.
                                    //
                                    return ReturnCode.Ok;
                                }
                                else if (code == ReturnCode.Return)
                                {
                                    //
                                    // NOTE: Failure, return the error that this
                                    //       resolver returned verbatim.
                                    //
                                    error = localError;

                                    return ReturnCode.Error;
                                }
                                else if (code == ReturnCode.Break)
                                {
                                    //
                                    // NOTE: Failure, skip all other resolvers
                                    //       for this entity and return all the
                                    //       previously collected errors.
                                    //
                                    break;
                                }
                                else if (code == ReturnCode.Continue)
                                {
                                    //
                                    // NOTE: Failure, keep trying; however, do
                                    //       not add the error message from this
                                    //       resolver.
                                    //
                                    continue;
                                }
                            }
                            catch (Exception e)
                            {
                                if (FlagOps.HasFlags(
                                        lookupFlags, LookupFlags.Verbose, true))
                                {
                                    localError = e;
                                }
                            }

                            if (localError != null)
                            {
                                if (errors == null)
                                    errors = new ResultList();

                                errors.Add(localError);
                            }
                        }
                    }

                    if (errors != null)
                        error = errors;
                    else
                        error = "no resolvers defined";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to resolve a procedure by name using the
        /// resolvers configured for this interpreter, following any wrappers or
        /// aliases to the underlying procedure.
        /// </summary>
        /// <param name="name">
        /// The name of the procedure to resolve.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the lookup is performed.
        /// </param>
        /// <param name="procedure">
        /// Upon success, receives the resolved procedure.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        internal ReturnCode GetProcedureViaResolvers(
            string name,
            LookupFlags lookupFlags,
            ref IProcedure procedure,
            ref Result error
            )
        {
            IExecute execute = null;

            if (InternalGetIExecuteViaResolvers(
                    GetResolveEngineFlagsNoLock(true),
                    name, null, lookupFlags,
                    ref execute, ref error) == ReturnCode.Ok)
            {

            retry:

                if (execute is IProcedure)
                {
                    procedure = (IProcedure)execute;
                    return ReturnCode.Ok;
                }
                else if (execute is IWrapper)
                {
                    IWrapper wrapper = (IWrapper)execute;
                    execute = wrapper.Object as IExecute;
                    goto retry;
                }
                else if (execute is IAlias)
                {
                    IAlias alias = (IAlias)execute;
                    string targetName = null;

                    if (GetAliasArguments(
                            alias, null, ref targetName,
                            ref error) == ReturnCode.Ok)
                    {
                        IExecute aliasTarget = null;

                        if (GetAliasTarget(alias,
                                targetName, null, lookupFlags,
                                true, ref aliasTarget,
                                ref error) == ReturnCode.Ok)
                        {
                            execute = aliasTarget;
                            goto retry;
                        }
                        else
                        {
                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        return ReturnCode.Error;
                    }
                }
            }
            else
            {
                return ReturnCode.Error;
            }

            error = FlagOps.HasFlags(
                lookupFlags, LookupFlags.Verbose, true) ?
                String.Format(
                    "invalid procedure name {0}",
                    FormatOps.DisplayName(name)) :
                "invalid procedure name";

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to resolve a variable by name and index by
        /// consulting each resolver configured for this interpreter in turn,
        /// optionally enforcing that the resolved variable is non-null and
        /// usable.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use as the context for resolution.
        /// </param>
        /// <param name="varName">
        /// The name of the variable to resolve.
        /// </param>
        /// <param name="varIndex">
        /// The array element index of the variable to resolve, if any.
        /// </param>
        /// <param name="flags">
        /// On input, the variable flags to use; upon return, may receive the
        /// updated variable flags.
        /// </param>
        /// <param name="variable">
        /// Upon success, receives the resolved variable.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateGetVariableViaResolvers( /* EXPERIMENTAL */
            ICallFrame frame,
            string varName,
            string varIndex,
            ref VariableFlags flags,
            ref IVariable variable,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (HasResolvers(ref error))
                {
                    bool resolveNull = FlagOps.HasFlags(
                        flags, VariableFlags.ResolveNull, true);

                    bool noUsable = FlagOps.HasFlags(
                        flags, VariableFlags.NoUsable, true);

                    ResultList errors = null;

                    foreach (IResolve resolve in resolvers)
                    {
                        if (resolve != null)
                        {
                            Result localError; /* REUSED */

                            try
                            {
                                ReturnCode code;
                                IVariable localVariable = null;

                                localError = null;

                                code = resolve.GetVariable(
                                    frame, varName, varIndex, ref flags,
                                    ref localVariable, ref localError);

                                if (code == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: Success, return the entity that this
                                    //       resolver found.  If that entity is
                                    //       now null and that is disallowed via
                                    //       the flags, fail.
                                    //
                                    if (!resolveNull && (localVariable == null))
                                    {
                                        error = String.Format(
                                            "can't resolve {0}: variable is invalid",
                                            FormatOps.ErrorVariableName(varName, varIndex));

                                        return ReturnCode.Error;
                                    }

                                    if (!noUsable && (localVariable != null))
                                    {
                                        localError = null;

                                        if (!localVariable.IsUsable(ref localError))
                                        {
                                            error = String.Format(
                                                "can't resolve {0}: {1}",
                                                FormatOps.ErrorVariableName(varName, varIndex),
                                                FormatOps.DisplayString(localError));

                                            return ReturnCode.Error;
                                        }
                                    }

                                    variable = localVariable;
                                    return ReturnCode.Ok;
                                }
                                else if (code == ReturnCode.Return)
                                {
                                    //
                                    // NOTE: Failure, return the error that this
                                    //       resolver returned verbatim.
                                    //
                                    error = localError;

                                    return ReturnCode.Error;
                                }
                                else if (code == ReturnCode.Break)
                                {
                                    //
                                    // NOTE: Failure, skip all other resolvers
                                    //       for this entity and return all the
                                    //       previously collected errors.
                                    //
                                    break;
                                }
                                else if (code == ReturnCode.Continue)
                                {
                                    //
                                    // NOTE: Failure, keep trying; however, do
                                    //       not add the error message from this
                                    //       resolver.
                                    //
                                    continue;
                                }
                            }
                            catch (Exception e)
                            {
                                localError = e;
                            }

                            if (localError != null)
                            {
                                if (errors == null)
                                    errors = new ResultList();

                                errors.Add(localError);
                            }
                        }
                    }

                    if (errors != null)
                        error = errors;
                    else
                        error = "no resolvers defined";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves a variable using the resolvers configured for
        /// this interpreter and returns its value as an object dictionary,
        /// splitting the supplied name into its name and index components.
        /// </summary>
        /// <param name="name">
        /// The name of the variable to resolve, possibly including an array
        /// element index.
        /// </param>
        /// <param name="variableFlags">
        /// On input, the variable flags to use; upon return, may receive the
        /// updated variable flags.
        /// </param>
        /// <param name="variable">
        /// Upon success, receives the resolved variable.
        /// </param>
        /// <param name="dictionary">
        /// Upon success, receives the value of the resolved variable as an
        /// object dictionary.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        internal ReturnCode GetDictionaryVariableViaResolversWithSplit(
            string name,                     /* in */
            ref VariableFlags variableFlags, /* in, out */
            ref IVariable variable,          /* out */
            ref ObjectDictionary dictionary, /* out */
            ref Result error                 /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (GetVariableViaResolversWithSplit(
                        name, ref variableFlags, ref variable,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                object value = null;

                if (ScriptOps.ResolveVariableValue(
                        null, ref variableFlags, ref variable,
                        ref value, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (value is ObjectDictionary)
                {
                    dictionary = (ObjectDictionary)value;
                }
                else
                {
                    dictionary = ObjectDictionary.FromString(
                        this, StringOps.GetStringFromObject(
                        value), true, false, ref error);

                    if (dictionary == null)
                        return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }

