        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method splits the supplied variable name and index into their
        /// name and index components and then resolves the variable using the
        /// resolvers configured for this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to use as the context for resolution.
        /// </param>
        /// <param name="name">
        /// The name of the variable to resolve, possibly including an array
        /// element index.
        /// </param>
        /// <param name="index">
        /// The array element index of the variable to resolve, if any.
        /// </param>
        /// <param name="varName">
        /// Upon success, receives the resolved base variable name.
        /// </param>
        /// <param name="varIndex">
        /// Upon success, receives the resolved array element index, if any.
        /// </param>
        /// <param name="variableFlags">
        /// On input, the variable flags to use; upon return, may receive the
        /// updated variable flags.
        /// </param>
        /// <param name="variable">
        /// Upon success, receives the resolved variable.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateGetVariableViaResolversWithSplit(
            ICallFrame frame,
            string name,
            string index,
            ref string varName,
            ref string varIndex,
            ref VariableFlags variableFlags,
            ref IVariable variable,
            ref Result error
            )
        {
            //
            // NOTE: Reset the error related flags because we have not
            //       actually searched for the variable yet.
            //
            variableFlags &= ~VariableFlags.ErrorMask;

            //
            // BUGFIX: Prevent any custom resolvers from returning a null
            //         variable along with a successful return code.
            //
            variableFlags &= ~VariableFlags.ResolveNull;

            //
            // BUGFIX: Block all attempts to use an array element reference
            //         in the variable name if an explicit array element
            //         index has been explicitly specified by the caller.
            //
            if (index != null)
                variableFlags |= VariableFlags.NoElement;

            //
            // NOTE: Perform a split of the name (which may refer to an array
            //       element) into the base variable name and the array index,
            //       if any.
            //
            if (ScriptOps.SplitVariableName(
                    this, variableFlags, name, ref varName,
                    ref varIndex, ref error) == ReturnCode.Ok)
            {
                //
                // NOTE: The caller may need to know if the variable name
                //       refers to an array element.
                //
                if (varIndex != null)
                    variableFlags |= VariableFlags.WasElement;

                return PrivateGetVariableViaResolvers(
                    frame, varName, varIndex, ref variableFlags,
                    ref variable, ref error);
            }

            return ReturnCode.Error;
        }
        #endregion
