        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Resolver Management (WARNING: EXPERIMENTAL)
        /// <summary>
        /// This method determines whether this interpreter has a collection of
        /// resolvers available.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// True if a collection of resolvers is available; otherwise, false.
        /// </returns>
        public bool HasResolvers(ref Result error)
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                bool result = (resolvers != null);

                if (!result)
                    error = "resolvers not available";

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the resolvers for this interpreter back to a
        /// single, freshly created core resolver.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        public ReturnCode ResetResolvers(
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(false, ref error))
                    return ReturnCode.Error;

                if (!HasResolvers(ref error))
                    return ReturnCode.Error;

                InternalResetResolvers(ref error);
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the resolver at the specified priority from the
        /// resolvers configured for this interpreter.
        /// </summary>
        /// <param name="priority">
        /// The priority of the resolver to retrieve.
        /// </param>
        /// <param name="resolve">
        /// Upon success, receives the resolver at the specified priority.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        public ReturnCode GetResolver(
            Priority priority,
            ref IResolve resolve,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!HasResolvers(ref error))
                    return ReturnCode.Error;

                if (priority == Priority.Lowest)
                    priority = (Priority)resolvers.Count - 1;
                else if (priority == Priority.None)
                    priority = Priority.Highest;

                if (((int)priority < 0) ||
                    ((int)priority > resolvers.Count))
                {
                    error = "invalid priority";
                    return ReturnCode.Error;
                }

                resolve = resolvers[(int)priority];
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds a resolver to this interpreter at the specified
        /// priority.
        /// </summary>
        /// <param name="resolve">
        /// The resolver to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the resolver, if any.
        /// </param>
        /// <param name="priority">
        /// The priority at which to add the resolver.
        /// </param>
        /// <param name="result">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        public ReturnCode AddResolver(
            IResolve resolve,
            IClientData clientData,
            Priority priority,
            ref Result result
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!IsModifiable(true, ref result))
                    return ReturnCode.Error;

                if (resolve == null)
                {
                    result = "invalid resolve";
                    return ReturnCode.Error;
                }

                if (!HasResolvers(ref result))
                    return ReturnCode.Error;

                long token;

                if (priority == Priority.Lowest)
                {
                    resolvers.Add(resolve);
                    token = resolvers.Count - 1;
                }
                else
                {
                    if (priority == Priority.None)
                        priority = Priority.Highest;

                    if (((int)priority < 0) ||
                        ((int)priority > resolvers.Count))
                    {
                        result = "invalid priority";
                        return ReturnCode.Error;
                    }

                    resolvers.Insert((int)priority, resolve);
                    token = (long)priority;
                }

                token = EntityOps.NextTokenIdNoThrow(resolve, token);
                EntityOps.SetToken(resolve, token);

#if ARGUMENT_CACHE
                /* IGNORED */
                MaybeClearArgumentCache(null);
#endif

#if NOTIFY
                /* IGNORED */
                CheckNotification(
                    NotifyType.Resolve, NotifyFlags.Added,
                    new ObjectPair(resolve, priority), this,
                    clientData, null, null, ref result);
#endif

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether this interpreter has a collection of
        /// resolvers available, discarding any error information.
        /// </summary>
        /// <returns>
        /// True if a collection of resolvers is available; otherwise, false.
        /// </returns>
        private bool HasResolvers()
        {
            Result error = null;

            return HasResolvers(ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the resolvers for this interpreter back to a
        /// single, freshly created core resolver, without checking whether the
        /// interpreter is modifiable.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        internal void InternalResetResolvers(
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (HasResolvers())
                {
                    DisposeResolvers();

                    IResolve resolve = RuntimeOps.NewResolver(
                        this, CurrentGlobalFrame, globalNamespace,
                        createFlags);

                    resolvers.Clear();
                    resolvers.Add(resolve);

                    EntityOps.SetToken(
                        resolve, (long)Priority.Highest); /* EXEMPT */

#if ARGUMENT_CACHE
                    /* IGNORED */
                    MaybeClearArgumentCache(null);
#endif

#if NOTIFY
                    /* IGNORED */
                    CheckNotification(
                        NotifyType.Resolve, NotifyFlags.Reset,
                        null, this, null, null, null, ref error);
#endif
                }
            }
        }
        #endregion
        #endregion
        #endregion

