        /// <summary>
        /// Gets the current script location for this interpreter.  This is the
        /// manually set script location when one is present; otherwise, it is
        /// the most recently pushed script location, if any.
        /// </summary>
        public IScriptLocation ScriptLocation
        {
            get
            {
                CheckDisposed();

#if !THREADING
                lock (syncRoot) /* TRANSACTIONAL */
#endif
                {
                    IScriptLocation scriptLocation = ManualScriptLocation;

                    if (scriptLocation != null)
                        return scriptLocation;

                    ScriptLocationList scriptLocations = ScriptLocations;

                    if ((scriptLocations == null) || (scriptLocations.Count == 0))
                        return null;

                    return scriptLocations.Peek();
                }
            }
        }

