        /// <summary>
        /// This method retrieves the script (or library script) with the
        /// specified name, without separate client data input.
        /// </summary>
        /// <param name="name">
        /// The name of the script to retrieve.
        /// </param>
        /// <param name="scriptFlags">
        /// On input, flags that control how the script is located and loaded;
        /// upon return, may receive updated flags describing the retrieved
        /// script.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the script text; upon failure, receives
        /// information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        internal ReturnCode GetScript(
            string name,
            ref ScriptFlags scriptFlags,
            ref Result result
            )
        {
            IClientData clientData = null;

            return PrivateGetScript(
                name, ref scriptFlags, ref clientData, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method performs the actual work of retrieving the script (or
        /// library script) with the specified name from the host or other
        /// configured script sources.
        /// </summary>
        /// <param name="name">
        /// The name of the script to retrieve.
        /// </param>
        /// <param name="scriptFlags">
        /// On input, flags that control how the script is located and loaded;
        /// upon return, may receive updated flags describing the retrieved
        /// script.
        /// </param>
        /// <param name="clientData">
        /// On input, the client data to use during retrieval; upon success, may
        /// receive client data associated with the retrieved script.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the script text; upon failure, receives
        /// information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        private ReturnCode PrivateGetScript(
            string name,
            ref ScriptFlags scriptFlags,
            ref IClientData clientData,
            ref Result result
            )
        {
            IFileSystemHost fileSystemHost = InternalHost;
            bool direct = IsInitializeDirect();

            if (FlagOps.HasFlags(
                    scriptFlags, ScriptFlags.Library, true))
            {
                return ScriptOps.GetLibrary(
                    this, fileSystemHost, name, direct,
                    ref scriptFlags, ref clientData,
                    ref result);
            }
            else
            {
                ScriptOps.MaybeExactNameOnly(
                    this, name, true, ref scriptFlags);

                return HostOps.GetScript(
                    this, fileSystemHost, name, direct,
                    ref scriptFlags, ref clientData,
                    ref result);
            }
        }
        #endregion
        #endregion

