        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method acquires the interpreter lock and marks this interpreter
        /// as trusted, leaving the lock held upon success so that the caller may
        /// perform additional trusted operations.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        public ReturnCode LockAndMarkTrusted(ref Result error)
        {
            CheckDisposed();

            if (syncRoot == null)
            {
                error = "invalid interpreter synchronization object";
                return ReturnCode.Error;
            }

            bool locked = Monitor.TryEnter(syncRoot);
            MaybeSomebodyHasLock(locked);

            if (!locked) /* EXEMPT */
            {
                error = "could not obtain interpreter lock";
                return ReturnCode.Error;
            }

            if (!InternalIsSafe())
            {
                error = "interpreter is already marked as trusted";
                MaybeNobodyHasLock(locked);
                Monitor.Exit(syncRoot); /* EXEMPT */
                return ReturnCode.Error;
            }

            /* LOCK HELD */
            InternalMarkTrusted();

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks this interpreter as safe and then releases the
        /// interpreter lock, complementing <c>LockAndMarkTrusted</c>.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives information about the error.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success; otherwise, an error code.
        /// </returns>
        public ReturnCode MarkSafeAndUnlock(ref Result error)
        {
            CheckDisposed();

            if (syncRoot == null)
            {
                error = "invalid interpreter synchronization object";
                return ReturnCode.Error;
            }

            bool locked = Monitor.TryEnter(syncRoot);
            MaybeSomebodyHasLock(locked);

            if (!locked) /* EXEMPT */
            {
                error = "could not obtain interpreter lock";
                return ReturnCode.Error;
            }

            if (InternalIsSafe())
            {
                error = "interpreter is already marked as safe";
                MaybeNobodyHasLock(locked);
                Monitor.Exit(syncRoot); /* EXEMPT */
                return ReturnCode.Error;
            }

            /* LOCK HELD */
            InternalMarkSafe();
            MaybeNobodyHasLock(locked);
            Monitor.Exit(syncRoot); /* EXEMPT */
            Monitor.Exit(syncRoot); /* EXEMPT */
            /* LOCK NOT HELD */

            return ReturnCode.Ok;
        }

