        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the list of trusted file system paths for this
        /// interpreter, creating it first if necessary.
        /// </summary>
        /// <returns>
        /// The list of trusted file system paths, which is never null.
        /// </returns>
        private StringList InitializeAndGetTrustedPaths() /* CANNOT RETURN NULL */
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (trustedPaths == null)
                    trustedPaths = new StringList();

                return trustedPaths;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method merges the specified trusted file system paths into the
        /// list of trusted paths for this interpreter, skipping any that are
        /// empty or already present.
        /// </summary>
        /// <param name="trustedPaths">
        /// The trusted file system paths to merge.
        /// </param>
        /// <returns>
        /// The list of paths that were actually added, or null if the supplied
        /// list was null.
        /// </returns>
        private StringList PrivateMergeTrustedPaths(
            StringList trustedPaths /* in */
            )
        {
            if (trustedPaths == null)
                return null;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                StringList result = new StringList();

                StringList liveTrustedPaths =
                    InitializeAndGetTrustedPaths();

                foreach (string trustedPath in trustedPaths)
                {
                    if (String.IsNullOrEmpty(trustedPath))
                        continue;

                    if (liveTrustedPaths.Contains(trustedPath))
                        continue;

                    liveTrustedPaths.Add(trustedPath);
                    result.Add(trustedPath);
                }

                return result;
            }
        }

