        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the dictionary of trusted URIs for this
        /// interpreter, creating it first if necessary.
        /// </summary>
        /// <returns>
        /// The dictionary of trusted URIs, which is never null.
        /// </returns>
        private UriDictionary<object> InitializeAndGetTrustedUris() /* CANNOT RETURN NULL */
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (trustedUris == null)
                    trustedUris = new UriDictionary<object>();

                return trustedUris;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method merges the specified trusted URIs into the dictionary of
        /// trusted URIs for this interpreter, skipping any that are null or
        /// already present.
        /// </summary>
        /// <param name="trustedUris">
        /// The trusted URIs to merge.
        /// </param>
        /// <returns>
        /// The collection of URI strings that were actually added, or null if
        /// the supplied dictionary was null.
        /// </returns>
        private IEnumerable<string> PrivateMergeTrustedUris(
            UriDictionary<object> trustedUris /* in */
            )
        {
            if (trustedUris == null)
                return null;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                StringList result = new StringList();

                UriDictionary<object> liveTrustedUris =
                    InitializeAndGetTrustedUris();

                foreach (UriPair pair in trustedUris)
                {
                    Uri trustedUri = pair.Key;

                    if (trustedUri == null)
                        continue;

                    if (liveTrustedUris.ContainsKey(trustedUri))
                        continue;

                    liveTrustedUris[trustedUri] = pair.Value;
                    result.Add(trustedUri.ToString());
                }

                return result;
            }
        }

