        private int PrivateClearTrustedHashes()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                int count = 0;

                if (trustedHashes != null)
                {
                    count += trustedHashes.Count;
                    trustedHashes.Clear();
                }

                return count;
