        internal bool InternalIsSafeWithFlags(
            InterpreterFlags hasFlags,
            bool all
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return InternalIsSafe() &&
                    /* EXEMPT */
                    FlagOps.HasFlags(interpreterFlags, hasFlags, all);
