        /// <summary>
        /// This method determines whether this interpreter satisfies the
        /// specified security level requirements.
        /// </summary>
        /// <param name="securityLevel">
        /// The security level requirements to check against.
        /// </param>
        /// <returns>
        /// True if this interpreter satisfies the specified security level
        /// requirements; otherwise, false.
        /// </returns>
        internal bool MatchSecurityLevel(
            SecurityLevel securityLevel
            )
        {
            if (FlagOps.HasFlags(securityLevel, SecurityLevel.Safe, true) &&
                !InternalIsSafe())
            {
                return false;
            }

            if (FlagOps.HasFlags(securityLevel, SecurityLevel.Sdk, true) &&
                !InternalIsAnySdk())
            {
                return false;
            }

            return true;
        }

