        /// This method determines whether the specified create flags describe an
        /// interpreter configured for use with the specified SDK type or types.
        /// </summary>
        /// <param name="sdkType">
        /// The SDK type or types to check for.
        /// </param>
        /// <param name="createFlags">
        /// The create flags to check.
        /// </param>
        /// <param name="all">
        /// Non-zero if all of the specified SDK types must be present; otherwise,
        /// any one of them being present is sufficient.
        /// </param>
        /// <returns>
        /// True if the create flags describe an interpreter for the specified SDK
        /// type or types; otherwise, false.
        /// </returns>
        private static bool PrivateIsSdk(
            SdkType sdkType,
            CreateFlags createFlags,
            bool all
            )
        {
            CreateFlags hasCreateFlags = CreateFlags.None;

            if (FlagOps.HasFlags(sdkType, SdkType.Security, true))
                hasCreateFlags |= CreateFlags.SecuritySdk;

            if (FlagOps.HasFlags(sdkType, SdkType.License, true))
                hasCreateFlags |= CreateFlags.LicenseSdk;

            if (FlagOps.HasFlags(sdkType, SdkType.NonCritical, true))
                hasCreateFlags |= CreateFlags.NoCritical;

            return FlagOps.HasFlags(createFlags, hasCreateFlags, all);
        }

