        /// </param>
        /// <param name="names">
        /// Upon success, this parameter will be modified to contain the names
        /// of the snippets that were removed.
        /// </param>
        /// <param name="errors">
        /// Upon failure, this parameter will be modified to contain any error
        /// messages that were generated.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode RemoveSnippets( /* EXPERIMENTAL */
            SnippetFlags snippetFlags,     /* in: NOT USED */
            LookupFlags lookupFlags,       /* in */
            ref IEnumerable<string> names, /* in, out */
            ref ResultList errors          /* out */
            )
        {
            CheckDisposed();

            if (HaveBadSnippetFlags(snippetFlags))
            {
                if (errors == null)
                    errors = new ResultList();

                errors.Add("permission denied: safe interpreter cannot remove snippets");
                return ReturnCode.Error;
            }

            return PrivateRemoveSnippets(
                snippetFlags, lookupFlags, true, ref names, ref errors);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether the specified snippet flags represent
        /// an operation that is not permitted within a safe interpreter.
        /// </summary>
        /// <param name="snippetFlags">
        /// The snippet flags to be checked.
        /// </param>
        /// <returns>
        /// True if the operation is not permitted for the current interpreter;
        /// otherwise, false.
        /// </returns>
        private bool HaveBadSnippetFlags(
            SnippetFlags snippetFlags /* in */
            )
        {
            if (FlagOps.HasFlags(
                    snippetFlags, SnippetFlags.IgnoreSafe, true) ||
                !InternalIsSafe())
            {
                return false;
            }

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes and/or validates the canonical (hash-based)
        /// name for the specified snippet.
        /// </summary>
        /// <param name="snippet">
        /// The snippet whose name is to be computed or validated.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control how the snippet name is computed and
        /// validated.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippet is looked up.  This
        /// parameter is not currently used.
        /// </param>
        /// <param name="name">
        /// Upon entry, the requested name of the snippet, if any; upon success,
        /// this parameter will be modified to contain the canonical name.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode InternalSnippetName(
            ISnippet snippet,          /* in */
            SnippetFlags snippetFlags, /* in */
            LookupFlags lookupFlags,   /* in: NOT USED */
            ref string name,           /* in, out */
            ref Result error           /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (snippet == null)
                {
                    error = "invalid snippet";
                    return ReturnCode.Error;
                }

                if ((name != null) &&
                    !StringOps.IsSha1HashValue(name) &&
                    !StringOps.IsSha512HashValue(name))
                {
                    error = String.Format(
                        "malformed snippet name: must match " +
                        "regular expression {0} or {1}",
                        FormatOps.DisplayString(
                            StringOps.sha1HashValueRegEx),
                        FormatOps.DisplayString(
                            StringOps.sha512HashValueRegEx));

                    return ReturnCode.Error;
                }

                byte[] hashValue;

                if (FlagOps.HasFlags(snippetFlags,
                        SnippetFlags.HashOtherPath, true) ||
                    FlagOps.HasFlags(snippet.SnippetFlags,
                        SnippetFlags.HashOtherPath, true))
                {
                    string path = snippet.Path;

                    if (String.IsNullOrEmpty(path))
                    {
                        error = String.Format(
                            "invalid snippet path for {0}",
                            FormatOps.DisplayString(name));

                        return ReturnCode.Error;
                    }

                    string otherPath = PathOps.RemoveExtension(
                        path);

                    if (String.IsNullOrEmpty(otherPath))
                    {
                        error = String.Format(
                            "invalid other path {0} for {1}",
                            FormatOps.DisplayString(otherPath),
                            FormatOps.DisplayString(path));

                        return ReturnCode.Error;
                    }

                    if (!File.Exists(otherPath))
                    {
                        error = String.Format(
                            "other path {0} for {1} does not exist",
                            FormatOps.DisplayString(otherPath),
                            FormatOps.DisplayString(path));

                        return ReturnCode.Error;
                    }

                    hashValue = RuntimeOps.HashFile(
                        null, otherPath, null, ref error);
                }
                else
                {
                    byte[] bytes = snippet.Bytes; /* OVERRIDE? */

                    if (bytes != null)
                    {
                        hashValue = HashOps.HashBytes(
                            null, bytes, EncodingType.Snippet,
                            ref error);
                    }
                    else
                    {
                        hashValue = HashOps.HashString(
                            null, StringOps.GetEncoding(
                            EncodingType.Snippet), snippet.Text,
                            EncodingType.Snippet, ref error);
                    }
                }

                if (hashValue == null)
                    return ReturnCode.Error;

                string localName = FormatOps.HashValue(hashValue);

                if (localName == null)
                {
                    error = "invalid hashed name";
                    return ReturnCode.Error;
                }

                if (name != null)
                {
                    if (!FlagOps.HasFlags(snippetFlags,
                            SnippetFlags.AllowAnyHash, true) &&
                        !SharedStringOps.SystemEquals(name, localName))
                    {
                        error = String.Format(
                            "snippet name mismatch: have {0}, want {1}",
                            FormatOps.DisplayString(name),
                            FormatOps.DisplayString(localName));

                        return ReturnCode.Error;
                    }

                    if (FlagOps.HasFlags(snippetFlags,
                            SnippetFlags.UseAnyHash, true))
                    {
                        localName = name;
                    }
                }
                else
                {
                    name = localName;
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a snippet with the specified name is
        /// present in this interpreter, optionally honoring access restrictions
        /// for public callers.
        /// </summary>
        /// <param name="name">
        /// The name of the snippet to query for.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing.  This parameter is not
        /// currently used.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippet is looked up.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case hidden snippets are not visible.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the snippet is present; otherwise,
        /// an error return code.
        /// </returns>
        private ReturnCode PrivateHaveSnippet(
            string name,               /* in */
            SnippetFlags snippetFlags, /* in: NOT USED */
            LookupFlags lookupFlags,   /* in */
            bool viaPublic,            /* in */
            ref Result error           /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasSnippets(ref error))
                    return ReturnCode.Error;

                if (String.IsNullOrEmpty(name))
                {
                    error = "invalid snippet name";
                    return ReturnCode.Error;
                }

                ISnippet oldSnippet;

                if (!snippets.TryGetValue(name, out oldSnippet))
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} not found",
                            FormatOps.DisplayName(name)) :
                        "snippet not found";

                    return ReturnCode.Error;
                }

                if ((oldSnippet == null) && FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Validate, true))
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} is invalid",
                            FormatOps.DisplayName(name)) :
                        "snippet is invalid";

                    return ReturnCode.Error;
                }

                if (viaPublic &&
                    (oldSnippet != null) && oldSnippet.IsHidden())
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} is hidden",
                            FormatOps.DisplayName(name)) :
                        "snippet is hidden";

                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a snippet by name on behalf of internal
        /// callers, bypassing the access restrictions applied to public
        /// callers.
        /// </summary>
        /// <param name="name">
        /// The name of the snippet to look up.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippet is looked up.
        /// </param>
        /// <param name="snippet">
        /// Upon success, this parameter will be modified to contain the snippet
        /// that was found.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode InternalGetSnippet(
            string name,               /* in */
            SnippetFlags snippetFlags, /* in */
            LookupFlags lookupFlags,   /* in */
            ref ISnippet snippet       /* out */
            )
        {
            Result error = null;

            return PrivateGetSnippet(
                name, snippetFlags, lookupFlags,
                false, ref snippet, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a snippet by name, optionally honoring access
        /// restrictions for public callers, and returns it.
        /// </summary>
        /// <param name="name">
        /// The name of the snippet to look up.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing.  This parameter is not
        /// currently used.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippet is looked up.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case hidden snippets are not visible.
        /// </param>
        /// <param name="snippet">
        /// Upon success, this parameter will be modified to contain the snippet
        /// that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateGetSnippet(
            string name,               /* in */
            SnippetFlags snippetFlags, /* in: NOT USED */
            LookupFlags lookupFlags,   /* in */
            bool viaPublic,            /* in */
            ref ISnippet snippet,      /* out */
            ref Result error           /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasSnippets(ref error))
                    return ReturnCode.Error;

                if (String.IsNullOrEmpty(name))
                {
                    error = "invalid snippet name";
                    return ReturnCode.Error;
                }

                ISnippet localSnippet; /* REUSED */

                if (snippets.TryGetValue(name, out localSnippet))
                    goto maybeOk;

                string rawNameOnly;

                try
                {
                    rawNameOnly = Path.GetFileNameWithoutExtension(
                        name); /* throw */
                }
                catch (Exception e)
                {
                    TraceOps.DebugTrace(
                        e, typeof(Interpreter).Name,
                        TracePriority.FileSystemError);

                    rawNameOnly = null;
                }

                if ((rawNameOnly != null) &&
                    snippets.TryGetValue(rawNameOnly, out localSnippet))
                {
                    goto maybeOk;
                }

                error = FlagOps.HasFlags(
                    lookupFlags, LookupFlags.Verbose, true) ?
                    String.Format(
                        "snippet {0} not found",
                        FormatOps.DisplayName(name)) :
                    "snippet not found";

                return ReturnCode.Error;

            maybeOk:

                if (localSnippet == null)
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} is invalid",
                            FormatOps.DisplayName(name)) :
                        "snippet is invalid";

                    return ReturnCode.Error;
                }

                if (viaPublic && localSnippet.IsHidden())
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} is hidden",
                            FormatOps.DisplayName(name)) :
                        "snippet is hidden";

                    return ReturnCode.Error;
                }

                if (localSnippet.IsDisabled())
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} is disabled",
                            FormatOps.DisplayName(name)) :
                        "snippet is disabled";

                    return ReturnCode.Error;
                }

                snippet = localSnippet;
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the names of the snippets that match the
        /// specified criteria, optionally honoring access restrictions for
        /// public callers.
        /// </summary>
        /// <param name="pattern">
        /// The optional pattern used to match snippet names.  If this value is
        /// null, all snippet names are eligible to be returned.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control which snippets are eligible to be
        /// returned.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippets are looked up.  This
        /// parameter is not currently used.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case hidden snippets are not visible.
        /// </param>
        /// <param name="names">
        /// Upon success, this parameter will be modified to contain the names
        /// of the matching snippets.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateListSnippets(
            string pattern,                /* in: OPTIONAL */
            bool noCase,                   /* in */
            SnippetFlags snippetFlags,     /* in */
            LookupFlags lookupFlags,       /* in: NOT USED */
            bool viaPublic,                /* in */
            ref IEnumerable<string> names, /* in, out */
            ref Result error               /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasSnippets(ref error))
                    return ReturnCode.Error;

                if (HaveBadSnippetFlags(snippetFlags))
                {
                    error = "permission denied: safe interpreter cannot list snippets";
                    return ReturnCode.Error;
                }

                SnippetFlags hasFlags = Snippet.MaskFlags(
                    snippetFlags, null, null, null, null);

                bool hasAll = FlagOps.HasFlags(
                    snippetFlags, SnippetFlags.HasAllFlags, true);

                if (names == null)
                    names = new StringList();

                foreach (SnippetPair pair in snippets)
                {
                    ISnippet snippet = pair.Value;

                    if (snippet == null)
                        continue;

                    if (viaPublic && snippet.IsHidden())
                        continue;

                    if ((hasFlags != SnippetFlags.None) && !FlagOps.HasFlags(
                            snippet.SnippetFlags, hasFlags, hasAll))
                    {
                        continue;
                    }

                    if ((pattern != null) && !StringOps.Match(
                            this, MatchMode.Glob, pair.Key, pattern, noCase))
                    {
                        continue;
                    }

                    /* IGNORED */
                    ListOps.IEnumerableAddToList<string>(names, pair.Key);
                }

                /* IGNORED */
                ListOps.IEnumerableSortList<string>(names);

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a snippet by name and evaluates it as a script,
        /// optionally honoring access restrictions for public callers and
        /// removing the snippet after use when so configured.
        /// </summary>
        /// <param name="name">
        /// The name of the snippet to evaluate.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippet is looked up.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case hidden snippets are not visible.
        /// </param>
        /// <param name="result">
        /// Upon return, this parameter will be modified to contain the result
        /// of evaluating the snippet.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this parameter will be modified to contain the line
        /// number where the error occurred.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateEvaluateSnippet(
            string name,               /* in */
            SnippetFlags snippetFlags, /* in */
            LookupFlags lookupFlags,   /* in */
            bool viaPublic,            /* in */
            ref Result result,         /* out */
            ref int errorLine          /* out */
            )
        {
            ISnippet snippet = null;

            if (PrivateGetSnippet(
                    name, snippetFlags, lookupFlags, viaPublic,
                    ref snippet, ref result) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (snippet == null)
            {
                result = "invalid snippet";
                return ReturnCode.Error;
            }

            bool remove = false;

            if (FlagOps.HasFlags(snippetFlags,
                    SnippetFlags.RemoveOnUse, true) ||
                FlagOps.HasFlags(snippet.SnippetFlags,
                    SnippetFlags.RemoveOnUse, true))
            {
                remove = true;
            }

            try
            {
                IScript script = Script.Create(
                    snippet, ref result);

                if (script == null)
                    return ReturnCode.Error;

                return PrivateEvaluateScript(
                    script, ref result, ref errorLine);
            }
            finally
            {
                if (remove)
                {
                    ReturnCode removeCode;
                    Result removeError = null;

                    removeCode = PrivateRemoveSnippet(
                        name, snippetFlags, lookupFlags,
                        false, ref removeError);

                    if (removeCode != ReturnCode.Ok)
                    {
                        DebugOps.Complain(
                            this, removeCode, removeError);
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes snippets from this interpreter, optionally
        /// honoring access restrictions for public callers (such as not
        /// removing locked snippets).
        /// </summary>
        /// <param name="snippetFlags">
        /// The flags used to control which snippets are removed.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippets are looked up.  This
        /// parameter is not currently used.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case locked snippets are preserved.
        /// </param>
        /// <param name="count">
        /// Upon return, this parameter will be incremented by the number of
        /// snippets that were removed.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateClearSnippets(
            SnippetFlags snippetFlags, /* in */
            LookupFlags lookupFlags,   /* in: NOT USED */
            bool viaPublic,            /* in */
            ref int count,             /* in, out */
            ref Result error           /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasSnippets(ref error))
                    return ReturnCode.Error;

                if (HaveBadSnippetFlags(snippetFlags))
                {
                    error = "permission denied: safe interpreter cannot clear snippets";
                    return ReturnCode.Error;
                }

                if (viaPublic)
                {
                    StringList keys = new StringList(snippets.Keys);

                    foreach (string key in keys)
                    {
                        if (key == null)
                            continue;

                        ISnippet snippet;

                        if (!snippets.TryGetValue(key, out snippet))
                            continue;

                        if (snippet == null)
                            continue;

                        if (snippet.IsLocked())
                            continue;

                        if (snippets.Remove(key))
                            count++;
                    }

                    if (snippets.Count == 0)
                        snippets.Clear();
                }
                else
                {
                    count += snippets.Count;
                    snippets.Clear();
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified snippet to this interpreter,
        /// optionally honoring access restrictions for public callers and
        /// handling duplicate snippets according to the specified flags.
        /// </summary>
        /// <param name="snippet">
        /// The snippet to be added.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing, including how
        /// duplicates are handled.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippet is looked up.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case hidden snippets are not visible.
        /// </param>
        /// <param name="name">
        /// Upon entry, the requested name of the snippet, if any; upon success,
        /// this parameter will be modified to contain the actual name assigned
        /// to the snippet.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateAddSnippet(
            ISnippet snippet,          /* in */
            SnippetFlags snippetFlags, /* in */
            LookupFlags lookupFlags,   /* in */
            bool viaPublic,            /* in */
            ref string name,           /* in, out */
            ref Result error           /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasSnippets(ref error))
                    return ReturnCode.Error;

                string localName = name;

                if (InternalSnippetName(
                        snippet, snippetFlags,
                        lookupFlags, ref localName,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                snippet.MaybeSetName(localName); /* throw */

                ISnippet oldSnippet;

                if (snippets.TryGetValue(localName, out oldSnippet))
                {
                    if (viaPublic &&
                        (oldSnippet != null) && oldSnippet.IsHidden())
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "snippet {0} already hidden",
                                FormatOps.DisplayName(localName)) :
                            "snippet already hidden";

                        return ReturnCode.Error;
                    }
                    else if (FlagOps.HasFlags(snippetFlags,
                            SnippetFlags.IgnoreDuplicate, true))
                    {
                        return ReturnCode.Ok;
                    }
                    else if (!FlagOps.HasFlags(snippetFlags,
                            SnippetFlags.AllowDuplicate, true))
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "snippet {0} already present",
                                FormatOps.DisplayName(localName)) :
                            "snippet already present";

                        return ReturnCode.Error;
                    }
                }

                snippets[localName] = snippet;
                name = localName;

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the snippet with the specified name from this
        /// interpreter, optionally honoring access restrictions for public
        /// callers (such as not removing locked snippets).
        /// </summary>
        /// <param name="name">
        /// The name of the snippet to remove.
        /// </param>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing.  This parameter is not
        /// currently used.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippet is looked up.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case locked snippets cannot be removed.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateRemoveSnippet(
            string name,               /* in */
            SnippetFlags snippetFlags, /* in: NOT USED */
            LookupFlags lookupFlags,   /* in */
            bool viaPublic,            /* in */
            ref Result error           /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasSnippets(ref error))
                    return ReturnCode.Error;

                if (String.IsNullOrEmpty(name))
                {
                    error = "invalid snippet name";
                    return ReturnCode.Error;
                }

                ISnippet oldSnippet;

                if (!snippets.TryGetValue(name, out oldSnippet))
                {
                    if (FlagOps.HasFlags(
                            lookupFlags, LookupFlags.NoComplain, true))
                    {
                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = FlagOps.HasFlags(
                            lookupFlags, LookupFlags.Verbose, true) ?
                            String.Format(
                                "snippet {0} not found",
                                FormatOps.DisplayName(name)) :
                            "snippet not found";

                        return ReturnCode.Error;
                    }
                }

                if (viaPublic &&
                    (oldSnippet != null) && oldSnippet.IsLocked())
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} is locked",
                            FormatOps.DisplayName(name)) :
                        "snippet is locked";

                    return ReturnCode.Error;
                }

                if (!snippets.Remove(name))
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "snippet {0} not removed",
                            FormatOps.DisplayName(name)) :
                        "snippet not removed";

                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds each snippet in the specified list to this
        /// interpreter, optionally honoring access restrictions for public
        /// callers.
        /// </summary>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippets are looked up.
        /// </param>
        /// <param name="snippets">
        /// The list of snippets to be added.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case hidden snippets are not visible.
        /// </param>
        /// <param name="names">
        /// Upon success, this parameter will be modified to contain the names
        /// of the snippets that were added.
        /// </param>
        /// <param name="errors">
        /// Upon failure, this parameter will be modified to contain any error
        /// messages that were generated.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateAddSnippets(
            SnippetFlags snippetFlags,     /* in */
            LookupFlags lookupFlags,       /* in */
            SnippetList snippets,          /* in */
            bool viaPublic,                /* in */
            ref IEnumerable<string> names, /* in, out */
            ref ResultList errors          /* in, out */
            )
        {
            if (snippets == null)
            {
                if (errors == null)
                    errors = new ResultList();

                errors.Add("invalid snippet list");
                return ReturnCode.Error;
            }

            int errorCount = 0;

            foreach (ISnippet snippet in snippets)
            {
                if (snippet == null)
                    continue;

                string name = snippet.Name;
                Result error = null;

                if (PrivateAddSnippet(snippet,
                        snippetFlags, lookupFlags, viaPublic,
                        ref name, ref error) == ReturnCode.Ok)
                {
                    if (name != null)
                    {
                        if (names == null)
                            names = new StringList();

                        /* IGNORED */
                        ListOps.IEnumerableAddToList<string>(
                            names, name);
                    }
                }
                else
                {
                    if (error != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(error);
                    }

                    errorCount++;
                }
            }

            /* IGNORED */
            ListOps.IEnumerableSortList<string>(names);

            return (errorCount > 0) ? ReturnCode.Error : ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes each named snippet in the specified list from
        /// this interpreter, optionally honoring access restrictions for public
        /// callers.
        /// </summary>
        /// <param name="snippetFlags">
        /// The flags used to control snippet processing.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the snippets are looked up.
        /// </param>
        /// <param name="viaPublic">
        /// Non-zero if this method is being called on behalf of a public
        /// caller, in which case locked snippets cannot be removed.
        /// </param>
        /// <param name="names">
        /// Upon entry, the names of the snippets to remove; upon success, this
        /// parameter will be modified to contain null.
        /// </param>
        /// <param name="errors">
        /// Upon failure, this parameter will be modified to contain any error
        /// messages that were generated.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode PrivateRemoveSnippets(
            SnippetFlags snippetFlags,     /* in */
            LookupFlags lookupFlags,       /* in */
            bool viaPublic,                /* in */
            ref IEnumerable<string> names, /* in, out */
            ref ResultList errors          /* in, out */
            )
        {
            if (names == null)
            {
                if (errors == null)
                    errors = new ResultList();

                errors.Add("invalid snippet name list");
                return ReturnCode.Error;
            }

            //
            // BUGBUG: On Mono v6.12.0.200, GetEnumerator
            //         method will crash here for reasons
            //         that are not immediately obvious.
            //
            int errorCount = 0;

            foreach (string name in names)
            {
                Result error = null;

                if (PrivateRemoveSnippet(
                        name, snippetFlags, lookupFlags,
                        viaPublic, ref error) != ReturnCode.Ok)
                {
                    if (error != null)
                    {
                        if (errors == null)
                            errors = new ResultList();

                        errors.Add(error);
                    }

                    errorCount++;
                }
            }

            if (errorCount == 0)
            {
                /* IGNORED */
                ListOps.IEnumerableClearList<string>(names);

                names = null;

                return ReturnCode.Ok;
            }

            return ReturnCode.Error;
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region IStatusManager Members
#if WINFORMS
        /// <summary>
        /// This method verifies that the status form thread for this
        /// interpreter is responsive.
        /// </summary>
        /// <param name="clientData">
        /// The optional client data associated with the request.  This
        /// parameter is not currently used.
        /// </param>
        /// <param name="timeout">
        /// The optional timeout, in milliseconds, to wait for the status form
        /// thread to respond.  If this value is null, a default timeout is
        /// used.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode CheckStatus(
            IClientData clientData, /* in: NOT USED */
            int? timeout,           /* in */
            ref Result error        /* out */
            )
        {
            CheckDisposed();

            int localTimeout;

            if (timeout != null)
                localTimeout = (int)timeout;
            else
                localTimeout = GetMinimumSleepTime(SleepType.Heartbeat) * 2;

            return StatusFormOps.CheckThread(this, localTimeout, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method starts the status form thread for this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The optional client data used to control how the status form is
        /// started.
        /// </param>
        /// <param name="timeout">
        /// The optional timeout, in milliseconds, to wait for the status form
        /// thread to start.  If this value is null, a default timeout is used.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode StartStatus(
            IClientData clientData, /* in: OPTIONAL */
            int? timeout,           /* in */
            ref Result error        /* out */
            )
        {
            CheckDisposed();

            bool? canClose;
            bool? topMost;
            bool? allowHotKeys;

            StatusFormOps.GetStartFlags(
                clientData, out canClose, out topMost, out allowHotKeys);

            int localTimeout;

            if (timeout != null)
            {
                localTimeout = (int)timeout;
            }
            else
            {
                localTimeout = GetMinimumSleepTime(SleepType.Heartbeat) * 10;

                if (CommonOps.Runtime.IsMono())
                    localTimeout *= 2;
            }

            return StatusFormOps.StartThread(
                this, localTimeout, canClose, topMost, allowHotKeys, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method stops the status form thread for this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The optional client data associated with the request.  This
        /// parameter is not currently used.
        /// </param>
        /// <param name="timeout">
        /// The optional timeout, in milliseconds, to wait for the status form
        /// thread to stop.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode StopStatus(
            IClientData clientData, /* in: NOT USED */
            int? timeout,           /* in */
            ref Result error        /* out */
            )
        {
            CheckDisposed();

            return StatusFormOps.StopThread(
                this, GetStatusSynchronous(false, true), ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the text currently displayed by the status form
        /// for this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The optional client data associated with the request.
        /// </param>
        /// <param name="timeout">
        /// The optional timeout, in milliseconds, to wait for the operation to
        /// complete.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode ClearStatus(
            IClientData clientData, /* in: OPTIONAL */
            int? timeout,           /* in */
            ref Result error        /* out */
            )
        {
            CheckDisposed();

            if (MaybeInvokeStatusCallback(
                    clientData, null, true, ref error))
            {
                return ReturnCode.Ok;
            }

            return StatusFormOps.Clear(
                this, GetStatusSynchronous(false, false), ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method displays the specified text using the status form for
        /// this interpreter.
        /// </summary>
        /// <param name="clientData">
        /// The optional client data associated with the request.
        /// </param>
        /// <param name="text">
        /// The status text to be displayed.
        /// </param>
        /// <param name="timeout">
        /// The optional timeout, in milliseconds, to wait for the operation to
        /// complete.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode ReportStatus(
            IClientData clientData, /* in: OPTIONAL */
            string text,            /* in */
            int? timeout,           /* in */
            ref Result error        /* out */
            )
        {
            CheckDisposed();

            if (MaybeInvokeStatusCallback(
                    clientData, text, false, ref error))
            {
                return ReturnCode.Ok;
            }

            return StatusFormOps.Report(
                this, text, GetStatusSynchronous(false, false), ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether status form operations should be
        /// performed synchronously, taking into account the current platform
        /// and calling context.
        /// </summary>
        /// <param name="dispose">
        /// Non-zero if this method is being called as part of disposing the
        /// interpreter.
        /// </param>
        /// <param name="stop">
        /// Non-zero if this method is being called in order to stop the status
        /// form thread.
        /// </param>
        /// <returns>
        /// Non-zero if status form operations should be synchronous, zero if
        /// they should be asynchronous, or null to use the configured default.
        /// </returns>
        private bool? GetStatusSynchronous(
            bool dispose, /* in: Being called via Dispose(), et al? */
            bool stop     /* in: Being called to stop status thread? */
            )
        {
            if (!dispose && stop &&
                !PlatformOps.IsWindowsOperatingSystem())
            {
                return true; /* HACK: Wait for stop on Mono with X11. */
            }

            return statusSynchronous;
        }
        #endregion
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ISynchronizeBase Members
        //
        // WARNING: FOR EXTERNAL USE ONLY.
        //
        /// <summary>
        /// Gets the object used to synchronize access to this interpreter.
        /// This member is intended for external use only.
        /// </summary>
        public object SyncRoot
        {
            //
            // TODO: Rethink this strategy.  Should calls for the interpreter
            //       lock from inside the interpreter methods be able to throw
            //       an exception?  If so, why?  If not, why not?
            //
            get { CheckDisposed(); return syncRoot; }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ISynchronize Members
        //
        // WARNING: FOR EXTERNAL USE ONLY.
        //
        /// <summary>
        /// This method attempts to acquire the lock for this interpreter
        /// without blocking.  This member is intended for external use only.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// successfully acquired by the calling thread.
        /// </param>
        public void TryLock(
            ref bool locked
            )
        {
            CheckDisposed();

            InternalSoftTryLock(ref locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: FOR EXTERNAL USE ONLY.
        //
        /// <summary>
        /// This method attempts to acquire the lock for this interpreter,
        /// waiting up to the configured wait-lock timeout.  This member is
        /// intended for external use only.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// successfully acquired by the calling thread.
        /// </param>
        public void TryLockWithWait(
            ref bool locked
            )
        {
            CheckDisposed();

            //
            // NOTE: Since this method is NEVER called from within
            //       the core library itself, especially not from
            //       within any hot paths, it is permitted to call
            //       back into this interpreter in order to obtain
            //       an overridden timeout.
            //
            /* EXEMPT */
            InternalTryLock(ThreadOps.GetTimeout(
                this, null, TimeoutType.WaitLock),
                ref locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: FOR EXTERNAL USE ONLY.
        //
        /// <summary>
        /// This method attempts to acquire the lock for this interpreter
        /// without blocking and without throwing an exception if the
        /// interpreter has been disposed.  This member is intended for external
        /// use only.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// successfully acquired by the calling thread.
        /// </param>
        public void TryLockNoThrow(
            ref bool locked
            )
        {
            // CheckDisposed(); /* EXEMPT */

            InternalSoftTryLock(ref locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: FOR EXTERNAL USE ONLY.
        //
        /// <summary>
        /// This method attempts to acquire the lock for this interpreter,
        /// waiting up to the specified timeout.  This member is intended for
        /// external use only.
        /// </summary>
        /// <param name="timeout">
        /// The maximum amount of time, in milliseconds, to wait for the lock to
        /// be acquired.
        /// </param>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// successfully acquired by the calling thread.
        /// </param>
        public void TryLock(
            int timeout,
            ref bool locked
            )
        {
            CheckDisposed();

            InternalTryLock(timeout, ref locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: FOR EXTERNAL USE ONLY.
        //
        /// <summary>
        /// This method releases the lock for this interpreter, if it is
        /// currently held by the calling thread.  This member is intended for
        /// external use only.
        /// </summary>
        /// <param name="locked">
        /// Upon entry, non-zero if the lock is held by the calling thread; upon
        /// return, this parameter will be zero once the lock has been released.
        /// </param>
        public void ExitLock(
            ref bool locked
            )
        {
            if (RuntimeOps.ShouldCheckDisposedOnExitLock(locked)) /* EXEMPT */
                CheckDisposed();

            InternalExitLock(ref locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method returns the identifier of the thread that most recently
        /// recorded ownership of the interpreter lock, if any.
        /// </summary>
        /// <returns>
        /// The thread identifier of the lock owner, or zero if no owner has
        /// been recorded.
        /// </returns>
        internal long MaybeWhoHasLock()
        {
            return Interlocked.CompareExchange(
                ref lockThreadId, 0, 0);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records that the current thread now owns the interpreter
        /// lock, but only if the lock was actually acquired.
        /// </summary>
        /// <param name="locked">
        /// Non-zero if the interpreter lock was just acquired by the current
        /// thread.
        /// </param>
        private void MaybeSomebodyHasLock(
            bool locked /* in */
            )
        {
            if (locked)
            {
                /* IGNORED */
                Interlocked.CompareExchange(ref lockThreadId,
                    GlobalState.GetCurrentLockThreadId(), 0);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the recorded ownership of the interpreter lock by
        /// the current thread, but only if the lock is being released.
        /// </summary>
        /// <param name="locked">
        /// Non-zero if the interpreter lock is being released by the current
        /// thread.
        /// </param>
        private void MaybeNobodyHasLock(
            bool locked /* in */
            )
        {
            if (locked)
            {
                /* IGNORED */
                Interlocked.CompareExchange(ref lockThreadId,
                    0, GlobalState.GetCurrentLockThreadId());
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the object used to synchronize access to this interpreter, for
        /// use within the core library.
        /// </summary>
        internal object InternalSyncRoot
        {
            get { return syncRoot; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method unconditionally acquires the lock for this interpreter,
        /// blocking until it becomes available.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// acquired by the calling thread.
        /// </param>
        internal void InternalLock(
            ref bool locked
            )
        {
            if (syncRoot == null)
                return;

            Monitor.Enter(syncRoot);
            locked = true;
            MaybeSomebodyHasLock(locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the lock for this interpreter
        /// without blocking, for use within the core library.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// acquired by the calling thread.
        /// </param>
        internal void InternalSoftTryLock(
            ref bool locked
            )
        {
            if (syncRoot == null)
                return;

            locked = Monitor.TryEnter(syncRoot);
            MaybeSomebodyHasLock(locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the lock for this interpreter using
        /// the default lock level, for use within the core library.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// acquired by the calling thread.
        /// </param>
        internal void InternalHardTryLock(
            ref bool locked
            )
        {
            //
            // TODO: Consider not hard-coding the level to zero here.
            //
            InternalHardTryLock(
                DefaultLockLevel, ref locked); /* COMPAT: Eagle beta. */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the lock for this interpreter using
        /// the specified lock level, which controls the timeout and retry
        /// behavior.
        /// </summary>
        /// <param name="level">
        /// The lock level used to control how aggressively the lock is
        /// acquired.
        /// </param>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// acquired by the calling thread.
        /// </param>
        private void InternalHardTryLock(
            int level,
            ref bool locked
            )
        {
            //
            // WARNING: This is an extremely hot path.  Please do not
            //          change this code without carefully measuring
            //          the performance impact.
            //
            // HACK: *PERF* Avoid calling back into this interpreter
            //       to query a timeout value that should generally
            //       be a logical constant anyhow, i.e. prevent the
            //       called ThreadOps.GetTimeout method from calling
            //       into our InternalGetTimeout method, et al.
            //
            switch (level)
            {
                case -1:
                    {
                        /* SEE: InternalSoftTryLock */
                        InternalTryLock(0, ref locked);

                        break;
                    }
                case 0: /* COMPAT: Eagle beta. */
                    {
                        //
                        // NOTE: This was the (legacy) behavior
                        //       prior to beta 55.
                        //
                        /* SEE: InternalHardTryLock */
                        InternalTryLock(ThreadOps.GetTimeout(
                            null, null, TimeoutType.HardLock),
                            ref locked);

                        break;
                    }
                case 1:
                    {
                        //
                        // NOTE: This is the currently the most
                        //       serious level.  The implication
                        //       is that a failure to acquire the
                        //       lock may (partially) corrupt the
                        //       interpreter state, e.g. when the
                        //       Engine class is coming back from
                        //       evaluation and has to pop call
                        //       frames.  Yes, the call stack is
                        //       per-thread; however, there is a
                        //       bit of non-threaded state used
                        //       as well.
                        //
                        /* a.k.a. PrivateVeryHardTryLock */
                        PrivateTryLockWithRetries(TimeoutType.HardLock,
                            TimeoutType.EngineLock, ref locked);

                        break;
                    }
                default:
                    {
                        goto case -1; /* NOTE: Default non-blocking. */
                    }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the lock for this interpreter using
        /// the engine lock level, which is the most aggressive level used when
        /// the engine must reliably acquire the lock.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// acquired by the calling thread.
        /// </param>
        internal void InternalEngineTryLock( /* a.k.a. InternalVeryHardTryLock */
            ref bool locked
            )
        {
            InternalHardTryLock(
                PrivateLockLevel /* NO-LOCK */, ref locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method calculates the per-retry timeout to use when acquiring
        /// the interpreter lock, resolving the specified timeout types to their
        /// configured values.
        /// </summary>
        /// <param name="shortTimeoutType">
        /// The timeout type that provides the minimum amount of time to wait
        /// for a single lock attempt.
        /// </param>
        /// <param name="longTimeoutType">
        /// The timeout type that provides the overall amount of time to wait
        /// across all lock attempts.
        /// </param>
        /// <param name="maximumRetries">
        /// The maximum number of times the lock acquisition will be retried.
        /// </param>
        /// <returns>
        /// The amount of time, in milliseconds, to wait for each individual
        /// lock attempt.
        /// </returns>
        private static int CalculateOneTimeout(
            TimeoutType shortTimeoutType, /* in: ~1 second to ~4 seconds? */
            TimeoutType longTimeoutType,  /* in: ~2 seconds to infinite? */
            int maximumRetries            /* in: e.g. 1 to 10, etc. */
            )
        {
            return CalculateOneTimeout(ThreadOps.GetTimeout(
                null, null, shortTimeoutType), ThreadOps.GetTimeout(
                null, null, longTimeoutType), maximumRetries);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method calculates the per-retry timeout to use when acquiring
        /// the interpreter lock, given explicit short and long timeout values.
        /// </summary>
        /// <param name="shortTimeout">
        /// The minimum amount of time, in milliseconds, to wait for a single
        /// lock attempt.
        /// </param>
        /// <param name="longTimeout">
        /// The overall amount of time, in milliseconds, to wait across all lock
        /// attempts.
        /// </param>
        /// <param name="maximumRetries">
        /// The maximum number of times the lock acquisition will be retried.
        /// </param>
        /// <returns>
        /// The amount of time, in milliseconds, to wait for each individual
        /// lock attempt.
        /// </returns>
        private static int CalculateOneTimeout(
            int shortTimeout,  /* in: ~1 second to ~4 seconds? */
            int longTimeout,   /* in: ~2 seconds to infinite? */
            int maximumRetries /* in: e.g. 1 to 10, etc. */
            )
        {
            int oneTimeout;

            if (longTimeout != _Timeout.Infinite)
            {
                //
                // HACK: Assume lock callback does not want to be
                //       called too frequently.  Also assume that
                //       we do not want to wait too long between
                //       iterations to the lock callback.
                //
                if (maximumRetries > 0)
                {
                    oneTimeout = longTimeout / maximumRetries;

                    if (oneTimeout < shortTimeout)
                        oneTimeout = shortTimeout;
                }
                else
                {
                    oneTimeout = shortTimeout;
                }
            }
            else if (shortTimeout != _Timeout.Infinite)
            {
                //
                // NOTE: If the engine timeout value is infinite,
                //       that means wait forever unless canceled
                //       by the lock callback; however, only wait
                //       a "little bit" at a time.  The hard lock
                //       timeout cannot be infinite, so use that.
                //
                oneTimeout = shortTimeout;
            }
            else
            {
                //
                // HACK: Infinite timeouts are not allowed here;
                //       instead give a timeout that will return
                //       instantly we cannot acquire the lock.
                //
                oneTimeout = 0;
            }

            return oneTimeout;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method repeatedly attempts to acquire the lock for this
        /// interpreter, invoking the configured lock callback between attempts,
        /// until the lock is acquired, the maximum number of retries is
        /// reached, or the callback requests that the attempts be abandoned.
        /// </summary>
        /// <param name="shortTimeoutType">
        /// The timeout type that provides the minimum amount of time to wait
        /// for a single lock attempt.
        /// </param>
        /// <param name="longTimeoutType">
        /// The timeout type that provides the overall amount of time to wait
        /// across all lock attempts.
        /// </param>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// acquired by the calling thread.
        /// </param>
        private void PrivateTryLockWithRetries(
            TimeoutType shortTimeoutType,
            TimeoutType longTimeoutType,
            ref bool locked
            )
        {
            //
            // NOTE: Calculate the per-retry timeout value to pass
            //       to the InternalTryLock method.  The resulting
            //       value CANNOT be infinite and __should__ be a
            //       relatively low number, e.g. 1000 milliseconds.
            //
            int maximumRetries = PrivateLockRetries;

            int oneTimeout = CalculateOneTimeout(
                shortTimeoutType, longTimeoutType, maximumRetries);

            LockCallback callback;
            int retry = 0;
            bool no = false;

            while (true)
            {
                /* NO RESULT */
                InternalTryLock(oneTimeout, ref locked);

                if (locked)
                    break;

                if ((maximumRetries >= 0) &&
                    (retry >= maximumRetries))
                {
                    break;
                }

                //
                // NOTE: One thing to keep in mind about the
                //       locking callback is that it may not
                //       be called very often, if ever.  If
                //       there are no other threads needing
                //       the interpreter lock -OR- if there
                //       are no retries necessary to acquire
                //       it, the locking callback may simply
                //       never be called.
                //
                // WARNING: Nothing too expensive should be
                //          done in the locking callback as
                //          that could seriously slow down
                //          the library.  It is recommended
                //          to use it for only for things
                //          like tracing and user interface
                //          updates, e.g. via servicing an
                //          external event loop.
                //
                callback = PrivateLockCallback; /* NO-LOCK */
                retry++;

                if ((callback != null) &&
                    callback(this, retry, oneTimeout, ref no))
                {
                    break;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the lock for this interpreter,
        /// waiting up to the specified timeout, for use within the core
        /// library.
        /// </summary>
        /// <param name="timeout">
        /// The maximum amount of time, in milliseconds, to wait for the lock to
        /// be acquired.
        /// </param>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the lock was
        /// acquired by the calling thread.
        /// </param>
        internal void InternalTryLock(
            int timeout,
            ref bool locked
            )
        {
            if (syncRoot == null)
                return;

            locked = Monitor.TryEnter(syncRoot, timeout);
            MaybeSomebodyHasLock(locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method releases the lock for this interpreter, if it is
        /// currently held by the calling thread, for use within the core
        /// library.
        /// </summary>
        /// <param name="locked">
        /// Upon entry, non-zero if the lock is held by the calling thread; upon
        /// return, this parameter will be zero once the lock has been released.
        /// </param>
        internal void InternalExitLock(
            ref bool locked
            )
        {
            if (syncRoot == null)
                return;

            if (locked)
            {
                MaybeNobodyHasLock(locked);
                Monitor.Exit(syncRoot);
                locked = false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if SHELL
        /// <summary>
        /// This method implements the lock callback used by the interactive
        /// shell, optionally prompting the interactive user to decide whether
        /// to continue waiting for the interpreter lock.
        /// </summary>
        /// <param name="synchronizeAll">
        /// The object on whose behalf the lock is being acquired.
        /// </param>
        /// <param name="retry">
        /// The number of the current lock acquisition retry.
        /// </param>
        /// <param name="timeout">
        /// The per-retry timeout, in milliseconds, used for each lock attempt.
        /// </param>
        /// <param name="no">
        /// A sticky flag that, upon entry, indicates whether the user has
        /// already chosen to keep waiting without being prompted again; upon
        /// return, this parameter may be modified to reflect that choice.
        /// </param>
        /// <returns>
        /// True if the lock acquisition should be abandoned; otherwise, false
        /// to continue retrying.
        /// </returns>
        private bool ShellLockCallback(
            ISynchronizeAll synchronizeAll, /* in */
            int retry,                      /* in */
            int timeout,                    /* in */
            ref bool no                     /* in, out */
            )
        {
#if WINFORMS
            bool setNo = false;
            DialogResult dialogResult;

            if (no) /* STICKY */
            {
                //
                // HACK: We know this means the interactive
                //       user (if any?) explicitly selected
                //       the "No" option; therefore, stick
                //       to it.
                //
                dialogResult = DialogResult.No;
            }
            else if (!InternalInteractive)
            {
                //
                // NOTE: Use the default non-interactive
                //       result for this method, which
                //       should be "Yes", to retain the
                //       legacy behavior of failing after
                //       one try.
                //
                dialogResult = DefaultLock1DialogResult;
            }
            else
            {
                //
                // NOTE: Show a dialog to the user with
                //       the following choices:
                //
                //       1. Yes: Fail immediately.
                //       2. No: Retry, do not ask again.
                //       3. Cancel: Retry, ask again.
                //
                dialogResult = FormOps.YesOrNoOrCancel(
                    String.Format(
                        lockCallbackPromptFormat,
                        retry * timeout),
                    GlobalState.GetPackageName(),
                    DefaultLock2DialogResult);

                setNo = true;
            }

            if (dialogResult == DialogResult.No)
            {
                //
                // HACK: This means, it is NOT deadlocked,
                //       continue waiting (forever?), and
                //       do not ask again.
                //
                if (setNo && !no)
                    no = true;

                return false;
            }

            return (dialogResult == DialogResult.Yes);
#else
            bool setNo = false;
            bool? dialogResult;

            if (no) /* STICKY */
            {
                //
                // HACK: We know this means the interactive
                //       user (if any?) explicitly selected
                //       the "No" option; therefore, stick
                //       to it.
                //
                dialogResult = false; /* No */
            }
            else if (!InternalInteractive)
            {
                //
                // NOTE: Use the default non-interactive
                //       result for this method, which
                //       should be "Yes", to retain the
                //       legacy behavior of failing after
                //       one try.
                //
                dialogResult = DefaultLock1DialogResult;
            }
            else
            {
                //
                // NOTE: Show a dialog to the user with
                //       the following choices:
                //
                //       1. Yes: Fail immediately.
                //       2. No: Retry, do not ask again.
                //       3. Cancel: Retry, ask again.
                //
                dialogResult = WindowOps.YesOrNoOrCancel(
                    String.Format(
                        lockCallbackPromptFormat,
                        retry * timeout),
                    GlobalState.GetPackageName(),
                    DefaultLock2DialogResult);

                setNo = true;
            }

            if (dialogResult == null) /* Cancel */
                return false;

            if (!(bool)dialogResult) /* No */
            {
                //
                // HACK: This means, it is NOT deadlocked,
                //       continue waiting (forever?), and
                //       do not ask again.
                //
                if (setNo && !no)
                    no = true;

                return false; /* No */
            }

            return true; /* Yes */
#endif
        }
#endif
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ISynchronizeStatic Members
        /// <summary>
