        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ITclEntityManager Members
#if NATIVE && TCL
        #region Tcl Interpreter Support
        /// <summary>
        /// This method determines whether native Tcl interpreter support is
        /// available within this interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// True if native Tcl interpreter support is available; otherwise,
        /// false.
        /// </returns>
        public bool HasTclInterpreters(ref Result error)
        {
            CheckDisposed();

            return InternalHasTclInterpreters(ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a native Tcl interpreter with the
        /// specified name exists within this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to query for.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the native Tcl interpreter exists;
        /// otherwise, an error return code.
        /// </returns>
        public ReturnCode DoesTclInterpreterExist(string name)
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;
            Result error = null;

            return GetTclInterpreter(name, LookupFlags.Exists, ref interp, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a native Tcl interpreter by name and returns a
        /// handle to it.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl interpreter is looked
        /// up.
        /// </param>
        /// <param name="interp">
        /// Upon success, this parameter will be modified to contain the handle
        /// to the native Tcl interpreter that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode GetTclInterpreter(
            string name,
            LookupFlags lookupFlags,
            ref IntPtr interp,
            ref Result error
            )
        {
            CheckDisposed();

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclInterpreters(ref error))
                {
                    //
                    // NOTE: *WARNING* Empty Tcl interpreter names are allowed,
                    //       please do not change this to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        if (tclInterps.TryGetValue(name, out interp) &&
                            ((interp != IntPtr.Zero) ||
                            !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true)))
                        {
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Verbose, true) ?
                                String.Format(
                                    "invalid Tcl interpreter {0}",
                                    FormatOps.WrapOrNull(name)) :
                                "invalid Tcl interpreter";
                        }
                    }
                    else
                    {
                        error = "invalid Tcl interpreter name";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new native Tcl interpreter and adds it to this
        /// interpreter.
        /// </summary>
        /// <param name="createFlags">
        /// The flags used to control how the native Tcl interpreter is created.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the name of
        /// the newly created native Tcl interpreter; upon failure, it will be
        /// modified to contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode CreateTclInterpreter(
            TclCreateFlags createFlags,
            ref Result result
            )
        {
            CheckDisposed();

            if (!IsModifiable(true, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclInterpreters(ref result))
                {
                    GlobalState.PushActiveInterpreter(this);

                    try
                    {
                        bool initialize = FlagOps.HasFlags(
                            createFlags, TclCreateFlags.Initialize, true);

                        bool memory = FlagOps.HasFlags(
                            createFlags, TclCreateFlags.Memory, true);

                        bool safe = FlagOps.HasFlags(
                            createFlags, TclCreateFlags.Safe, true);

                        IntPtr interp = IntPtr.Zero;

                        if (TclWrapper.CreateInterpreter(
                                tclApi, initialize, memory, safe, ref interp,
                                ref result) == ReturnCode.Ok)
                        {
                            string name = FormatOps.Id(
                                safe ? tclSafeInterpPrefix : tclInterpPrefix, null, NextId());

                            tclInterps.Add(name, interp);
                            result = name;

#if NOTIFY && NOTIFY_TCL
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Tcl | NotifyType.Interpreter, NotifyFlags.Added,
                                //
                                // BUGBUG: In order to use this class for notification
                                //         parameters, it really should probably be
                                //         made public.
                                //
                                new ObjectList(initialize, safe, name, interp), this,
                                null, null, null, ref result);
#endif

                            return ReturnCode.Ok;
                        }
                    }
                    finally
                    {
                        /* IGNORED */
                        GlobalState.PopActiveInterpreter();
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method deletes the native Tcl interpreter with the specified
        /// name from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to delete.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain an empty
        /// string; upon failure, it will be modified to contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode DeleteTclInterpreter(
            string name,
            ref Result result
            )
        {
            CheckDisposed();

            if (!IsModifiable(false, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclInterpreters(ref result))
                {
                    GlobalState.PushActiveInterpreter(this);

                    try
                    {
                        IntPtr interp = IntPtr.Zero;

                        if (GetTclInterpreter(
                                name, LookupFlags.Default, ref interp, ref result) == ReturnCode.Ok)
                        {
                            if (
#if NATIVE_PACKAGE
                                !NativePackage.ShouldDeleteTclInterpreter(name, interp) ||
#endif
                                TclWrapper.DeleteInterpreter(
                                    tclApi, false, ref interp, ref result) == ReturnCode.Ok)
                            {
                                tclInterps.Remove(name);
                                result = String.Empty;

#if NOTIFY && NOTIFY_TCL
                                /* IGNORED */
                                CheckNotification(
                                    NotifyType.Tcl | NotifyType.Interpreter, NotifyFlags.Removed,
                                    new ObjectPair(name, interp), this,
                                    null, null, null, ref result);
#endif

                                return ReturnCode.Ok;
                            }
                        }
                    }
                    finally
                    {
                        /* IGNORED */
                        GlobalState.PopActiveInterpreter();
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether native Tcl interpreter support is
        /// available within this interpreter, for use within the core library.
        /// </summary>
        /// <returns>
        /// True if native Tcl interpreter support is available; otherwise,
        /// false.
        /// </returns>
        internal bool InternalHasTclInterpreters()
        {
            Result error = null;

            return InternalHasTclInterpreters(ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether native Tcl interpreter support is
        /// available within this interpreter, for use within the core library.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// True if native Tcl interpreter support is available; otherwise,
        /// false.
        /// </returns>
        internal bool InternalHasTclInterpreters(
            ref Result error
            )
        {
            lock (tclSyncRoot)
            {
                bool result = (tclInterps != null);

                if (!result)
                    error = "no Tcl interpreters available";

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a native Tcl interpreter by name and returns a
        /// handle to it, for use within the core library.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl interpreter is looked
        /// up.
        /// </param>
        /// <param name="interp">
        /// Upon success, this parameter will be modified to contain the handle
        /// to the native Tcl interpreter that was found.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode GetTclInterpreter(
            string name,
            LookupFlags lookupFlags,
            ref IntPtr interp
            )
        {
            Result error = null;

            return GetTclInterpreter(name, lookupFlags, ref interp, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method locates the parent native Tcl interpreter associated
        /// with this interpreter, which is identified by a specially formatted
        /// name.
        /// </summary>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl interpreter is looked
        /// up.
        /// </param>
        /// <param name="name">
        /// Upon success, this parameter will be modified to contain the name of
        /// the parent native Tcl interpreter.
        /// </param>
        /// <param name="interp">
        /// Upon success, this parameter will be modified to contain the handle
        /// to the parent native Tcl interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode GetTclParentInterpreter(
            LookupFlags lookupFlags,
            ref string name,
            ref IntPtr interp,
            ref Result error
            )
        {
            /* CheckDisposed(); */

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclInterpreters(ref error))
                {
                    //
                    // HACK: Use the convention that we always prefix the
                    //       parent Tcl interpreter with a specially formatted
                    //       name in order to find it (we cannot simply use the
                    //       Tcl interpreter at index zero because the Tcl
                    //       interpreters are maintained in a dictionary).
                    //
                    string pattern = FormatOps.Id(tclParentInterpPrefix, null,
                        Characters.Asterisk.ToString());

                    //
                    // NOTE: Search all the Tcl interpreters in this interpreter
                    //       for the parent Tcl interp stopping as soon as we
                    //       find a valid one (there should only be one valid
                    //       parent Tcl interpreter per interpreter at any given
                    //       time).
                    //
                    string key = null;
                    IntPtr value = IntPtr.Zero;

                    foreach (InterpPair pair in tclInterps)
                    {
                        //
                        // NOTE: Hard-coded match mode is OK here.
                        //
                        if (StringOps.Match(
                                this, MatchMode.Glob, pair.Key, pattern, false) &&
                            (pair.Value != IntPtr.Zero))
                        {
                            key = pair.Key;
                            value = pair.Value;
                            break;
                        }
                    }

                    //
                    // NOTE: Did we find the handle for the parent Tcl
                    //       interpreter?
                    //
                    if (key != null)
                    {
                        name = key;
                        interp = value;

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = "Tcl parent interpreter is not available";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Used by the Execute method of the _Commands.Tcl class to help
        //       implement the [tcl primary] sub-command.
        //
        /// <summary>
        /// This method locates the parent native Tcl interpreter associated
        /// with this interpreter, first checking the interpreters managed
        /// directly and then any provided by the native package, if available.
        /// </summary>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl interpreter is looked
        /// up.
        /// </param>
        /// <param name="name">
        /// Upon success, this parameter will be modified to contain the name of
        /// the parent native Tcl interpreter.
        /// </param>
        /// <param name="interp">
        /// Upon success, this parameter will be modified to contain the handle
        /// to the parent native Tcl interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain any error
        /// messages that were generated.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode GetAnyTclParentInterpreter(
            LookupFlags lookupFlags,
            ref string name,
            ref IntPtr interp,
            ref Result error
            )
        {
            ResultList errors = null;
            Result localError = null;

            if (GetTclParentInterpreter(
                    lookupFlags, ref name, ref interp,
                    ref localError) == ReturnCode.Ok)
            {
                return ReturnCode.Ok;
            }
            else
            {
                if (errors == null)
                    errors = new ResultList();

                errors.Add(localError);
            }

#if NATIVE_PACKAGE
            localError = null;

            if (NativePackage.GetParentTclInterpreter(
                    this, ref name, ref interp,
                    ref localError) == ReturnCode.Ok)
            {
                return ReturnCode.Ok;
            }
            else
            {
                if (errors == null)
                    errors = new ResultList();

                errors.Add(localError);
            }
#endif

            error = errors;
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For use by the TclApi class only.
        //
        /// <summary>
        /// This method determines whether the specified native Tcl interpreter
        /// handle, optionally matching the specified name pattern, is known to
        /// this interpreter.
        /// </summary>
        /// <param name="pattern">
        /// The optional pattern used to match native Tcl interpreter names.  If
        /// this value is null, all interpreters are eligible to match.
        /// </param>
        /// <param name="interp">
        /// The handle to the native Tcl interpreter to search for.
        /// </param>
        /// <returns>
        /// True if a matching native Tcl interpreter was found; otherwise,
        /// false.
        /// </returns>
        internal bool HasTclInterpreter(
            string pattern,
            IntPtr interp
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (tclInterps == null)
                    return false;

                foreach (InterpPair pair in tclInterps) /* O(N) */
                {
                    //
                    // NOTE: Hard-coded match mode is OK here.
                    //
                    if ((pattern != null) && !StringOps.Match(
                            this, MatchMode.Glob, pair.Key, pattern, false))
                    {
                        continue;
                    }

                    //
                    // NOTE: Does this Tcl interpreter match the one specified
                    //       by the caller?  If so, stop now.
                    //
                    if (pair.Value == interp)
                        return true;
                }

                //
                // NOTE: No matching Tcl interpreter was found.
                //
                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For use by the TclApi class only.
        //
        /// <summary>
        /// This method adds the specified native Tcl interpreter handle to the
        /// collection of interpreters managed by this interpreter.
        /// </summary>
        /// <param name="interpName">
        /// The name to associate with the native Tcl interpreter.
        /// </param>
        /// <param name="interp">
        /// The handle to the native Tcl interpreter to add.
        /// </param>
        internal void AddTclInterpreter(
            string interpName,
            IntPtr interp
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (tclInterps == null)
                    return;

                tclInterps.Add(interpName, interp); /* O(1) */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For use by the TclApi class only.
        //
        /// <summary>
        /// This method removes all occurrences of the specified native Tcl
        /// interpreter handle from the collection of interpreters managed by
        /// this interpreter.
        /// </summary>
        /// <param name="interp">
        /// The handle to the native Tcl interpreter to remove.
        /// </param>
        /// <returns>
        /// The number of native Tcl interpreters that were removed.
        /// </returns>
        internal int RemoveTclInterpreter(
            IntPtr interp
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (tclInterps == null)
                    return 0;

                return tclInterps.RemoveAll(interp, 0); /* O(N) */
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Tcl Thread Support
#if TCL_THREADS
        /// <summary>
        /// This method determines whether native Tcl thread support is
        /// available within this interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// True if native Tcl thread support is available; otherwise, false.
        /// </returns>
        public bool HasTclThreads(ref Result error)
        {
            CheckDisposed();

            lock (tclSyncRoot)
            {
                bool result = (tclThreads != null);

                if (!result)
                    error = "no Tcl threads available";

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a native Tcl thread with the
        /// specified name exists within this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl thread to query for.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the native Tcl thread exists;
        /// otherwise, an error return code.
        /// </returns>
        public ReturnCode DoesTclThreadExist(string name)
        {
            CheckDisposed();

            TclThread thread = null;
            Result error = null;

            return GetTclThread(name, LookupFlags.Exists, ref thread, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a native Tcl thread by name and returns it.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl thread to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl thread is looked up.
        /// </param>
        /// <param name="thread">
        /// Upon success, this parameter will be modified to contain the native
        /// Tcl thread that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
#if TCL_WRAPPER
        public
#else
        internal
#endif
        ReturnCode GetTclThread(
            string name,
            LookupFlags lookupFlags,
            ref TclThread thread,
            ref Result error
            )
        {
#if TCL_WRAPPER
            CheckDisposed();
#endif

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (HasTclThreads(ref error))
                {
                    //
                    // NOTE: *WARNING* Empty Tcl thread names are allowed,
                    //       please do not change this to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        if (tclThreads.TryGetValue(name, out thread) &&
                            ((thread != null) ||
                            !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true)))
                        {
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Verbose, true) ?
                                String.Format(
                                    "invalid Tcl thread {0}",
                                    FormatOps.WrapOrNull(name)) :
                                "invalid Tcl thread";
                        }
                    }
                    else
                    {
                        error = "invalid Tcl thread name";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new native Tcl thread, along with its own
        /// native Tcl interpreter, and adds it to this interpreter.
        /// </summary>
        /// <param name="callback">
        /// The callback to be invoked when the native Tcl thread completes.
        /// </param>
        /// <param name="clientData">
        /// The client data to be passed to the native Tcl thread.
        /// </param>
        /// <param name="timeout">
        /// The timeout, in milliseconds, used for operations on the native Tcl
        /// thread.
        /// </param>
        /// <param name="threadFlags">
        /// The flags used to control how the native Tcl thread is created.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the name of
        /// the newly created native Tcl thread; upon failure, it will be
        /// modified to contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode CreateTclThread(
            ResultCallback callback,
            IClientData clientData,
            int timeout,
            TclThreadFlags threadFlags,
            ref Result result
            )
        {
            CheckDisposed();

            if (!IsModifiable(true, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (HasTclThreads(ref result))
                {
                    GlobalState.PushActiveInterpreter(this);

                    try
                    {
                        string name = FormatOps.Id(tclThreadPrefix, null,
                            GlobalState.NextThreadId(this, true));

                        if (InternalNoThreadAbort)
                            threadFlags |= TclThreadFlags.NoAbort;

                        TclThread thread = TclThread.Create(
                            this, callback, clientData, timeout, name, threadFlags,
                            ref result);

                        if (thread != null)
                        {
                            tclThreads.Add(name, thread);
                            result = name;

#if NOTIFY && NOTIFY_TCL
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Tcl | NotifyType.Thread, NotifyFlags.Added,
                                new ObjectPair(name, thread), this,
                                null, null, null, ref result);
#endif

                            //
                            // HACK: Always wait for the thread to fully start by
                            //       using the default join timeout instead of the
                            //       timeout value specified by the caller.
                            //
                            bool waitForStart = FlagOps.HasFlags(
                                threadFlags, TclThreadFlags.WaitForStart, true);

                            if (waitForStart)
                                thread.WaitForStart(ThreadOps.DefaultJoinTimeout);

                            return ReturnCode.Ok;
                        }
                    }
                    finally
                    {
                        /* IGNORED */
                        GlobalState.PopActiveInterpreter();
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method shuts down and deletes the native Tcl thread with the
        /// specified name from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl thread to delete.
        /// </param>
        /// <param name="threadFlags">
        /// The flags used to control how the native Tcl thread is shut down.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain an empty
        /// string; upon failure, it will be modified to contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode DeleteTclThread(
            string name,
            TclThreadFlags threadFlags,
            ref Result result
            )
        {
            CheckDisposed();

            TclThread thread = null;

            if (!IsModifiable(false, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (HasTclThreads(ref result))
                {
                    if ((GetTclThread(
                            name, LookupFlags.Default, ref thread,
                            ref result) == ReturnCode.Ok) &&
                        (thread == null))
                    {
                        result = "invalid Tcl thread";
                    }
                }
            }

            //
            // NOTE: If we managed to find the thread above then attempt
            //       to shut it down now.  We do this without holding a
            //       lock on the interpreter to avoid a deadlock with the
            //       other thread when it attempts to use the Tcl API
            //       object associated with this interpreter.
            //
            if (thread != null)
            {
                GlobalState.PushActiveInterpreter(this);

                try
                {
                    ITclApi tclApi;

                    lock (tclSyncRoot)
                    {
                        tclApi = this.tclApi;
                    }

                    if (InternalNoThreadAbort)
                        threadFlags |= TclThreadFlags.NoAbort;

                    if (thread.Shutdown(
                            tclApi, GetTclBridges(thread.Interp, null, null),
                            threadFlags, ref result) == ReturnCode.Ok)
                    {
                        thread.Dispose(); /* throw */

                        lock (tclSyncRoot)
                        {
                            tclThreads.Remove(name);
                        }

                        result = String.Empty;

#if NOTIFY && NOTIFY_TCL
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Tcl | NotifyType.Thread, NotifyFlags.Removed,
                            new ObjectPair(name, thread), this,
                            null, null, null, ref result);
#endif

                        return ReturnCode.Ok;
                    }
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method returns a string representation of the native Tcl
        /// threads managed by this interpreter that match the specified
        /// pattern.
        /// </summary>
        /// <param name="pattern">
        /// The optional pattern used to match native Tcl thread names.  If this
        /// value is null, all threads are eligible to be included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <returns>
        /// The string representation of the matching native Tcl threads, or
        /// null if native Tcl thread support is not available.
        /// </returns>
        internal string TclThreadsToString(
            string pattern,
            bool noCase
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (tclThreads != null)
                    return tclThreads.ToString(pattern, noCase);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether native Tcl thread support is
        /// available within this interpreter, for use within the core library.
        /// </summary>
        /// <returns>
        /// True if native Tcl thread support is available; otherwise, false.
        /// </returns>
        internal bool HasTclThreads()
        {
            Result error = null;
            return HasTclThreads(ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a native Tcl thread by name and returns it, for
        /// use within the core library.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl thread to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl thread is looked up.
        /// </param>
        /// <param name="thread">
        /// Upon success, this parameter will be modified to contain the native
        /// Tcl thread that was found.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode GetTclThread(
            string name,
            LookupFlags lookupFlags,
            ref TclThread thread
            )
        {
            Result error = null;

            return GetTclThread(name, lookupFlags, ref thread, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: The returned Tcl interpreter may only be used in conjunction with the Tcl
        //          C API on the thread that it was created on.  This restriction is NOT
        //          enforced by this function as we are merely returning the pointer to it.
        //
        /// <summary>
        /// This method looks up a native Tcl interpreter or thread by name and
        /// returns a handle to its native Tcl interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter or thread to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl interpreter or thread
        /// is looked up.
        /// </param>
        /// <param name="interp">
        /// Upon success, this parameter will be modified to contain the handle
        /// to the native Tcl interpreter that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode GetTclInterpreterOrThread(
            string name,
            LookupFlags lookupFlags,
            ref IntPtr interp,
            ref Result error
            )
        {
            bool fromThread = false;

            return GetTclInterpreterOrThread(
                name, lookupFlags, ref interp, ref fromThread, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a native Tcl interpreter or thread by name and
        /// returns a handle to its native Tcl interpreter, also indicating
        /// whether the handle came from a native Tcl thread.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter or thread to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl interpreter or thread
        /// is looked up.
        /// </param>
        /// <param name="interp">
        /// Upon success, this parameter will be modified to contain the handle
        /// to the native Tcl interpreter that was found.
        /// </param>
        /// <param name="fromThread">
        /// Upon success, this parameter will be modified to be non-zero if the
        /// returned handle came from a native Tcl thread.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        private ReturnCode GetTclInterpreterOrThread(
            string name,
            LookupFlags lookupFlags,
            ref IntPtr interp,
            ref bool fromThread,
            ref Result error
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclInterpreters(ref error))
                {
                    //
                    // NOTE: *WARNING* Empty Tcl interpreter and thread names are allowed,
                    //       please do not change this to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        if (tclInterps.TryGetValue(name, out interp) &&
                            ((interp != IntPtr.Zero) ||
                            !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true)))
                        {
                            fromThread = false;
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            if (HasTclThreads(ref error))
                            {
                                TclThread thread;

                                if (tclThreads.TryGetValue(name, out thread) &&
                                    ((thread != null) ||
                                    !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true)))
                                {
                                    interp = (thread != null) ?
                                        thread.Interp : IntPtr.Zero;

                                    fromThread = true;
                                    return ReturnCode.Ok;
                                }
                                else
                                {
                                    error = FlagOps.HasFlags(
                                        lookupFlags, LookupFlags.Verbose, true) ?
                                        String.Format(
                                            "invalid Tcl interpreter or thread {0}",
                                            FormatOps.WrapOrNull(name)) :
                                        "invalid Tcl interpreter or thread";
                                }
                            }
                        }
                    }
                    else
                    {
                        error = "invalid Tcl interpreter or thread name";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method collects the handles of the native Tcl interpreters that
        /// match the specified name pattern.
        /// </summary>
        /// <param name="pattern">
        /// The optional pattern used to match native Tcl interpreter names.  If
        /// this value is null, all interpreters are eligible to be included.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl interpreters are looked
        /// up.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="strict">
        /// Non-zero if the absence of native Tcl interpreter support should be
        /// treated as an error.
        /// </param>
        /// <param name="interps">
        /// Upon success, this parameter will be modified to contain the handles
        /// of the matching native Tcl interpreters, keyed by name.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode GetTclInterpreters(
            string pattern,
            LookupFlags lookupFlags,
            bool noCase,
            bool strict,
            ref IntPtrDictionary interps,
            ref Result error
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                Result localError = null;

                if (InternalHasTclInterpreters(ref localError))
                {
                    if (interps == null)
                        interps = new IntPtrDictionary();

                    foreach (InterpPair pair in tclInterps)
                    {
                        if ((pattern == null) ||
                            StringOps.Match(
                                this, MatchMode.Glob, pair.Key, pattern, noCase))
                        {
                            interps.Add(pair.Key, pair.Value);
                        }
                    }

                    return ReturnCode.Ok;
                }
                else if (strict)
                {
                    error = localError;
                    return ReturnCode.Error;
                }
                else
                {
                    return ReturnCode.Ok;
                }
            }
        }
        #endregion
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Tcl Command Support
        /// <summary>
        /// This method determines whether native Tcl command bridge support is
        /// available within this interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// True if native Tcl command bridge support is available; otherwise,
        /// false.
        /// </returns>
        public bool HasTclBridges(ref Result error)
        {
            CheckDisposed();

            return InternalHasTclBridges(ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a native Tcl command bridge with the
        /// specified name exists within this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl command bridge to query for.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the native Tcl command bridge
        /// exists; otherwise, an error return code.
        /// </returns>
        public ReturnCode DoesTclBridgeExist(string name)
        {
            CheckDisposed();

            TclBridge tclBridge = null;
            Result error = null;

            return GetTclBridge(name, LookupFlags.Exists, ref tclBridge, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a bridge that exposes the specified Eagle
        /// command as a command within a native Tcl interpreter.
        /// </summary>
        /// <param name="execute">
        /// The Eagle command to be invoked when the native Tcl command is
        /// executed.
        /// </param>
        /// <param name="interpName">
        /// The name of the native Tcl interpreter or thread in which to create
        /// the command.
        /// </param>
        /// <param name="commandName">
        /// The name of the command to create within the native Tcl interpreter.
        /// </param>
        /// <param name="clientData">
        /// The client data to be associated with the bridged command.
        /// </param>
        /// <param name="commandFlags">
        /// The flags used to control how the native Tcl command bridge is
        /// created.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the name of
        /// the newly created native Tcl command bridge; upon failure, it will
        /// be modified to contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode AddTclBridge(
            IExecute execute,
            string interpName,
            string commandName,
            IClientData clientData,
            TclCommandFlags commandFlags,
            ref Result result
            )
        {
            CheckDisposed();

            if (!IsModifiable(true, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (execute == null)
                {
                    result = "invalid execute";
                    return ReturnCode.Error;
                }

                if (!InternalHasTclInterpreters(ref result))
                    return ReturnCode.Error;

                if (!InternalHasTclBridges(ref result))
                    return ReturnCode.Error;

                IntPtr interp = IntPtr.Zero;

                //
                // NOTE: *THREADING* Get the Tcl interpreter even if it is in an isolated thread.
                //       If the Tcl interpreter is from an isolated thread then this method may
                //       only be called from that thread.
                //
                bool fromThread = false;

#if TCL_THREADS
                if (GetTclInterpreterOrThread(
                        interpName, LookupFlags.Default, ref interp,
                        ref fromThread, ref result) != ReturnCode.Ok)
#else
                if (GetTclInterpreter(
                        interpName, LookupFlags.Default, ref interp,
                        ref result) != ReturnCode.Ok)
#endif
                {
                    return ReturnCode.Error;
                }

                string bridgeName =
                    FormatOps.TclBridgeName(interpName, commandName);

                if (bridgeName == null)
                {
                    result = "invalid bridge name";
                    return ReturnCode.Error;
                }

                if (DoesTclBridgeExist(bridgeName) == ReturnCode.Ok)
                {
                    result = String.Format(
                        "can't add {0}: command already exists in Tcl interpreter {1}",
                        FormatOps.WrapOrNull(commandName),
                        FormatOps.WrapOrNull(interpName));

                    return ReturnCode.Error;
                }

                GlobalState.PushActiveInterpreter(this);

                try
                {
                    bool forceDelete = FlagOps.HasFlags(
                        commandFlags, TclCommandFlags.ForceDelete, true);

                    bool noComplain = FlagOps.HasFlags(
                        commandFlags, TclCommandFlags.NoComplain, true);

                    TclBridge tclBridge = TclBridge.Create(this, execute,
                        (clientData != null) ? clientData : ObjectOps.GetClientData(execute),
                        interp, commandName, fromThread, forceDelete, noComplain, ref result);

                    if (tclBridge == null)
                        return ReturnCode.Error;

                    tclBridges.Add(bridgeName, tclBridge);

#if NOTIFY && NOTIFY_TCL
                    /* IGNORED */
                    CheckNotification(
                        NotifyType.Tcl | NotifyType.Command, NotifyFlags.Added,
                        //
                        // BUGBUG: In order to use this class for notification
                        //         parameters, it really should probably be
                        //         made public.
                        //
                        new ObjectList(execute, interpName, commandName, bridgeName,
                            commandFlags, tclBridge), this,
                        clientData, null, null, ref result);
#endif

                    result = bridgeName;
                }
                finally
                {
                    /* IGNORED */
                    GlobalState.PopActiveInterpreter();
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a standard native Tcl command bridge that
        /// exposes the Eagle <c>eval</c> command within a native Tcl
        /// interpreter, allowing native Tcl scripts to execute Eagle commands.
        /// </summary>
        /// <param name="interpName">
        /// The name of the native Tcl interpreter or thread in which to create
        /// the command.
        /// </param>
        /// <param name="commandName">
        /// The name of the command to create within the native Tcl interpreter.
        /// If this value is null, a default command name is used.
        /// </param>
        /// <param name="clientData">
        /// The client data to be associated with the bridged command.
        /// </param>
        /// <param name="commandFlags">
        /// The flags used to control how the native Tcl command bridge is
        /// created.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the name of
        /// the newly created native Tcl command bridge; upon failure, it will
        /// be modified to contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode AddStandardTclBridge(
            string interpName,
            string commandName,
            IClientData clientData,
            TclCommandFlags commandFlags,
            ref Result result
            )
        {
            CheckDisposed();

            if (!IsModifiable(true, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            //
            // NOTE: Lookup and fetch a reference to the Eagle [eval]
            //       command, if available.
            //
            ICommand command = null;

            if (GetCommand(
                    typeof(_Commands.Eval), LookupFlags.Default,
                    ref command, ref result) == ReturnCode.Ok)
            {
                //
                // NOTE: Create a "bridge" between the Eagle [eval] command
                //       and the native Tcl [eagle] command.  This allows a
                //       native Tcl script to execute Eagle commands.
                //
                if (commandName == null)
                    commandName = GlobalState.GetPackageNameNoCase();

                if (!String.IsNullOrEmpty(commandName))
                {
                    return AddTclBridge(
                        command, interpName, commandName, null,
                        commandFlags, ref result);
                }

                result = "invalid command name";
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the native Tcl command bridge for the specified
        /// command from a native Tcl interpreter.
        /// </summary>
        /// <param name="interpName">
        /// The name of the native Tcl interpreter from which to remove the
        /// command.
        /// </param>
        /// <param name="commandName">
        /// The name of the command to remove from the native Tcl interpreter.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the request.
        /// </param>
        /// <param name="commandFlags">
        /// The flags used to control how the native Tcl command bridge is
        /// removed.  This parameter is not currently used.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain an empty
        /// string; upon failure, it will be modified to contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode RemoveTclBridge(
            string interpName,
            string commandName,
            IClientData clientData,
            TclCommandFlags commandFlags, /* NOT USED */
            ref Result result
            )
        {
            CheckDisposed();

            if (!IsModifiable(false, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclBridges(ref result))
                {
                    string bridgeName =
                        FormatOps.TclBridgeName(interpName, commandName);

                    TclBridge tclBridge = null;

                    if (GetTclBridge(
                            bridgeName, LookupFlags.Remove, ref tclBridge,
                            ref result) == ReturnCode.Ok)
                    {
                        GlobalState.PushActiveInterpreter(this);

                        try
                        {
                            if (tclBridge != null)
                            {
                                tclBridge.Dispose(); /* throw */
                                tclBridge = null;
                            }

                            tclBridges.Remove(bridgeName);

#if NOTIFY && NOTIFY_TCL
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Tcl | NotifyType.Command, NotifyFlags.Removed,
                                //
                                // BUGBUG: In order to use this class for notification
                                //         parameters, it really should probably be
                                //         made public.
                                //
                                new ObjectList(interpName, commandName, bridgeName, commandFlags, tclBridge), this,
                                clientData, null, null, ref result);
#endif

                            result = String.Empty;
                            return ReturnCode.Ok;
                        }
                        catch (Exception e)
                        {
                            result = String.Format(
                                "caught exception while disposing Tcl bridge: {0}",
                                e);

                            return ReturnCode.Error;
                        }
                        finally
                        {
                            /* IGNORED */
                            GlobalState.PopActiveInterpreter();
                        }
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether native Tcl command bridge support is
        /// available within this interpreter, for use within the core library.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// True if native Tcl command bridge support is available; otherwise,
        /// false.
        /// </returns>
        internal bool InternalHasTclBridges(
            ref Result error
            )
        {
            lock (tclSyncRoot)
            {
                bool result = (tclBridges != null);

                if (!result)
                    error = "no Tcl bridges available";

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a string representation of the native Tcl
        /// command bridges managed by this interpreter that match the specified
        /// pattern.
        /// </summary>
        /// <param name="pattern">
        /// The optional pattern used to match native Tcl command bridge names.
        /// If this value is null, all bridges are eligible to be included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <returns>
        /// The string representation of the matching native Tcl command
        /// bridges, or null if native Tcl command bridge support is not
        /// available.
        /// </returns>
        internal string TclBridgesToString(
            string pattern,
            bool noCase
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (tclBridges != null)
                    return tclBridges.ToString(pattern, noCase);
                else
                    return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a shallow copy of the collection of native Tcl
        /// command bridges managed by this interpreter.
        /// </summary>
        /// <returns>
        /// A new dictionary containing the native Tcl command bridges currently
        /// managed by this interpreter.
        /// </returns>
        internal TclBridgeDictionary CopyTclBridges()
        {
            lock (tclSyncRoot)
            {
                return new TclBridgeDictionary(tclBridges);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified native Tcl command bridge to the
        /// collection of bridges managed by this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name to associate with the native Tcl command bridge.
        /// </param>
        /// <param name="tclBridge">
        /// The native Tcl command bridge to add.
        /// </param>
        internal void AddTclBridge(
            string name,
            TclBridge tclBridge
            )
        {
            if (name != null)
            {
                lock (tclSyncRoot) /* TRANSACTIONAL */
                {
                    if (tclBridges != null)
                        tclBridges.Add(name, tclBridge);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes all native Tcl command bridges that refer to the
        /// specified bridge object from the collection of bridges managed by
        /// this interpreter.
        /// </summary>
        /// <param name="tclBridge">
        /// The native Tcl command bridge to remove.
        /// </param>
        /// <returns>
        /// The number of native Tcl command bridges that were removed.
        /// </returns>
        internal int RemoveTclBridges(
            TclBridge tclBridge
            )
        {
            int result = 0;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (tclBridges != null)
                {
                    StringList keys = new StringList();

                    //
                    // NOTE: Cleanup, PASS #1, collect the list of keys we need to remove
                    //       from the TclBridges collection in the containing interpreter.
                    //
                    foreach (TclBridgePair pair in tclBridges)
                        if (Object.ReferenceEquals(pair.Value, tclBridge))
                            keys.Add(pair.Key);

                    //
                    // NOTE: Cleanup, PASS #2, remove all the TclBridge objects we found
                    //       from PASS #1 (above).  Please note that since all of these
                    //       are assumed to refer to the same TclBridge object, dispose is
                    //       called [exactly once] after the TclBridge collection cleanup
                    //       has been completed.
                    //
                    foreach (string key in keys)
                        if (tclBridges.Remove(key))
                            result++;
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a native Tcl command bridge by name and returns
        /// it, for use within the core library.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl command bridge to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl command bridge is
        /// looked up.
        /// </param>
        /// <param name="tclBridge">
        /// Upon success, this parameter will be modified to contain the native
        /// Tcl command bridge that was found.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode GetTclBridge(
            string name,
            LookupFlags lookupFlags,
            ref TclBridge tclBridge
            )
        {
            Result error = null;

            return GetTclBridge(name, lookupFlags, ref tclBridge, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a native Tcl command bridge by name and returns
        /// it.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl command bridge to look up.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags used to control how the native Tcl command bridge is
        /// looked up.
        /// </param>
        /// <param name="tclBridge">
        /// Upon success, this parameter will be modified to contain the native
        /// Tcl command bridge that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        internal ReturnCode GetTclBridge(
            string name,
            LookupFlags lookupFlags,
            ref TclBridge tclBridge,
            ref Result error
            )
        {
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclBridges(ref error))
                {
                    //
                    // NOTE: *WARNING* Empty Tcl command names are allowed,
                    //       please do not change this to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        if (tclBridges.TryGetValue(name, out tclBridge) &&
                            ((tclBridge != null) ||
                            !FlagOps.HasFlags(lookupFlags, LookupFlags.Validate, true)))
                        {
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = FlagOps.HasFlags(
                                lookupFlags, LookupFlags.Verbose, true) ?
                                String.Format(
                                    "invalid Tcl command {0}",
                                    FormatOps.WrapOrNull(name)) :
                                "invalid Tcl command";
                        }
                    }
                    else
                    {
                        error = "invalid Tcl command name";
                    }
                }
            }

            return ReturnCode.Error;
        }
        #endregion
        #endregion
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ITclManager Members
#if NATIVE && TCL
        #region Tcl Synchronization Support
        /// <summary>
        /// Gets the object used to synchronize access to the native Tcl
        /// subsystem for this interpreter.
        /// </summary>
        public object TclSyncRoot
        {
            //
            // TODO: Rethink this strategy.  Should calls for the interpreter
            //       lock from inside the interpreter methods be able to throw
            //       an exception?  If so, why?  If not, why not?
            //
            get { CheckDisposed(); return tclSyncRoot; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method returns the identifier of the thread that most recently
        /// recorded ownership of the native Tcl lock, if any.
        /// </summary>
        /// <returns>
        /// The thread identifier of the lock owner, or zero if no owner has
        /// been recorded.
        /// </returns>
        private long MaybeWhoHasTclLock()
        {
            return Interlocked.CompareExchange(
                ref tclLockThreadId, 0, 0);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records that the current thread now owns the native Tcl
        /// lock, but only if the lock was actually acquired.
        /// </summary>
        /// <param name="locked">
        /// Non-zero if the native Tcl lock was just acquired by the current
        /// thread.
        /// </param>
        private void MaybeSomebodyHasTclLock(
            bool locked /* in */
            )
        {
            if (locked)
            {
                /* IGNORED */
                Interlocked.CompareExchange(ref tclLockThreadId,
                    GlobalState.GetCurrentLockThreadId(), 0);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the recorded ownership of the native Tcl lock by
        /// the current thread, but only if the lock is being released.
        /// </summary>
        /// <param name="locked">
        /// Non-zero if the native Tcl lock is being released by the current
        /// thread.
        /// </param>
        private void MaybeNobodyHasTclLock(
            bool locked /* in */
            )
        {
            if (locked)
            {
                /* IGNORED */
                Interlocked.CompareExchange(ref tclLockThreadId,
                    0, GlobalState.GetCurrentLockThreadId());
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets the object used to synchronize access to the native Tcl
        /// subsystem for this interpreter, for use within the core library.
        /// </summary>
        internal object InternalTclSyncRoot
        {
            get { return tclSyncRoot; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to acquire the native Tcl lock without
        /// blocking.
        /// </summary>
        /// <param name="locked">
        /// Upon return, this parameter will be non-zero if the native Tcl lock
        /// was acquired by the calling thread.
        /// </param>
        private void PrivateSoftTclTryLock(
             ref bool locked
             )
        {
            if (tclSyncRoot == null)
                return;

            locked = Monitor.TryEnter(tclSyncRoot);
            MaybeSomebodyHasTclLock(locked);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method releases the native Tcl lock, if it is currently held by
        /// the calling thread.
        /// </summary>
        /// <param name="locked">
        /// Upon entry, non-zero if the native Tcl lock is held by the calling
        /// thread; upon return, this parameter will be zero once the lock has
        /// been released.
        /// </param>
        private void PrivateTclExitLock(
            ref bool locked
            )
        {
            if (tclSyncRoot == null)
                return;

            if (locked)
            {
                MaybeNobodyHasTclLock(locked);
                Monitor.Exit(tclSyncRoot);
                locked = false;
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Tcl Read-Only Support
        /// <summary>
        /// Gets or sets a value indicating whether the native Tcl subsystem for
        /// this interpreter is read-only.  When read-only, operations that would
        /// modify the native Tcl state are not permitted.
        /// </summary>
        public bool TclReadOnly
        {
            get
            {
                CheckDisposed();

                lock (tclSyncRoot)
                {
                    return PrivateTclReadOnly;
                }
            }
            set
            {
                CheckDisposed();

                lock (tclSyncRoot)
                {
                    PrivateTclReadOnly = value;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// Gets or sets a value indicating whether the native Tcl subsystem for
        /// this interpreter is read-only, without acquiring any lock.
        /// </summary>
        private bool PrivateTclReadOnly
        {
            get { /* NO-LOCK */ return tclReadOnly; }
            set { /* NO-LOCK */ tclReadOnly = value; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the native Tcl subsystem for this
        /// interpreter is currently read-only.
        /// </summary>
        /// <param name="error">
        /// If the native Tcl subsystem is read-only, this parameter will be
        /// modified to contain an appropriate error message.
        /// </param>
        /// <returns>
        /// True if the native Tcl subsystem is read-only; otherwise, false.
        /// </returns>
        private bool IsTclReadOnly(
            ref Result error
            )
        {
            lock (tclSyncRoot)
            {
                if (tclReadOnly)
                {
                    error = "Tcl subsystem is read-only";
                    return true;
                }

                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets whether the native Tcl subsystem for this
        /// interpreter is read-only, updating both the read-only flag and the
        /// associated load flags.
        /// </summary>
        /// <param name="readOnly">
        /// Non-zero to make the native Tcl subsystem read-only; zero to make it
        /// modifiable.
        /// </param>
        internal void MakeTclReadOnly(
            bool readOnly
            )
        {
            // CheckDisposed();

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (readOnly)
                    tclLoadFlags |= LoadFlags.ReadOnly;
                else
                    tclLoadFlags &= ~LoadFlags.ReadOnly;

                tclReadOnly = readOnly;
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Tcl Loader Support
        /// <summary>
        /// This method determines whether the native Tcl library has been
        /// loaded and is available for use by this interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// True if the native Tcl library is available; otherwise, false.
        /// </returns>
        public bool HasTcl(ref Result error)
        {
            CheckDisposed();

            lock (tclSyncRoot)
            {
                bool result = (tclApi != null);

                if (!result)
                    error = "no Tcl available";

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the current thread is the native Tcl
        /// thread associated with this interpreter.
        /// </summary>
        /// <returns>
        /// True if the current thread is the native Tcl thread; otherwise,
        /// false.
        /// </returns>
        public bool IsTclThread()
        {
            CheckDisposed();

            return IsTclThread(GlobalState.GetCurrentNativeThreadId());
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the patch level (version) of the native Tcl
        /// library currently loaded by this interpreter.
        /// </summary>
        /// <param name="patchLevel">
        /// Upon success, this parameter will be modified to contain the patch
        /// level of the native Tcl library.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode GetTclPatchLevel(
            ref Version patchLevel,
            ref Result error
            )
        {
            CheckDisposed();

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (tclApi != null)
                {
                    TclBuild build = tclApi.Build;

                    if (build != null)
                    {
                        patchLevel = build.PatchLevel;
                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = "invalid Tcl build object";
                    }
                }
                else
                {
                    error = "invalid Tcl API object";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method locates and loads the native Tcl library, creating the
        /// parent native Tcl interpreter for this interpreter.
        /// </summary>
        /// <param name="findFlags">
        /// The flags used to control how the native Tcl library is located.
        /// </param>
        /// <param name="loadFlags">
        /// The flags used to control how the native Tcl library is loaded.
        /// </param>
        /// <param name="paths">
        /// The optional collection of paths to search for the native Tcl
        /// library.
        /// </param>
        /// <param name="text">
        /// The optional text used to help locate the native Tcl library.
        /// </param>
        /// <param name="minimumRequired">
        /// The minimum acceptable version of the native Tcl library.
        /// </param>
        /// <param name="maximumRequired">
        /// The maximum acceptable version of the native Tcl library.
        /// </param>
        /// <param name="unknown">
        /// The version to assume when the native Tcl library version cannot be
        /// determined.
        /// </param>
        /// <param name="clientData">
        /// The client data to be associated with the loaded native Tcl library.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the name of
        /// the parent native Tcl interpreter; upon failure, it will be modified
        /// to contain an appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode LoadTcl(
            FindFlags findFlags,
            LoadFlags loadFlags,
            IEnumerable<string> paths,
            string text,
            Version minimumRequired,
            Version maximumRequired,
            Version unknown,
            IClientData clientData,
            ref Result result
            )
        {
            CheckDisposed();

            if (!IsModifiable(true, ref result))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref result))
                return ReturnCode.Error;

            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (InternalHasTclInterpreters(ref result))
                {
                    if (IsTclThread())
                    {
                        GlobalState.PushActiveInterpreter(this);

                        try
                        {
#if NOTIFY && NOTIFY_TCL
                            /* IGNORED */
                            CheckNotification(
                                NotifyType.Tcl, NotifyFlags.PreLoad,
                                //
                                // BUGBUG: In order to use this class for notification
                                //         parameters, it really should probably be
                                //         made public.
                                //
                                new ObjectList(findFlags, loadFlags, paths, minimumRequired,
                                    maximumRequired, unknown), this, null, null, null,
                                    ref result);
#endif

                            IntPtr interp = IntPtr.Zero;

                            if (TclWrapper.Load(
                                    this, findFlags, loadFlags, null, paths,
                                    text, minimumRequired, maximumRequired,
                                    unknown, clientData, ref tclApi,
                                    ref interp, ref result) == ReturnCode.Ok)
                            {
                                string name = FormatOps.Id(
                                    tclParentInterpPrefix, null, NextId());

                                //
                                // NOTE: Even though the parent Tcl interpreter is not really intended
                                //       for general purpose scripting use, add it anyhow so that we
                                //       can keep track of it and delete it later.  This Tcl interpreter
                                //       is always considered to be "fully trusted" and has the full set
                                //       of Tcl commands available to it.
                                //
                                tclInterps.Add(name, interp);
                                result = name;

#if NOTIFY && NOTIFY_TCL
                                /* IGNORED */
                                CheckNotification(
                                    NotifyType.Tcl, NotifyFlags.Load,
                                    //
                                    // BUGBUG: In order to use this class for notification
                                    //         parameters, it really should probably be
                                    //         made public.
                                    //
                                    new ObjectList(findFlags, loadFlags, paths, minimumRequired,
                                        maximumRequired, unknown), this, null, null, null,
                                        ref result);
#endif

                                return ReturnCode.Ok;
                            }
                        }
                        finally
                        {
                            /* IGNORED */
                            GlobalState.PopActiveInterpreter();
                        }
                    }
                    else
                    {
                        result = "cannot load Tcl, wrong thread";
                    }
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method disposes of any native Tcl objects and unloads the
        /// native Tcl library previously loaded by this interpreter.
        /// </summary>
        /// <param name="unloadFlags">
        /// The flags used to control how the native Tcl library is unloaded.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error return
        /// code.
        /// </returns>
        public ReturnCode UnloadTcl(
            UnloadFlags unloadFlags, /* in */
            ref Result error         /* out */
            )
        {
            CheckDisposed();

            if (!IsModifiable(false, ref error))
                return ReturnCode.Error;

            if (IsTclReadOnly(ref error))
                return ReturnCode.Error;

            //
            // BUGFIX: Holding this lock while disposing of isolated Tcl
            //         threads can very easily result in a deadlock.
            //
            // lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                if (IsTclThread())
                {
                    GlobalState.PushActiveInterpreter(this);

                    try
                    {
#if NOTIFY && NOTIFY_TCL
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Tcl, NotifyFlags.PreUnload,
                            unloadFlags, this,
                            null, null, null, ref error);
#endif

                        //
                        // NOTE: First, attempt to cleanup and/or dispose
                        //       any Tcl related objects.
                        //
                        if (DisposeTcl(false, false, false, ref error) == ReturnCode.Ok)
                        {
                            //
                            // NOTE: Since the Tcl parent interpreter should
                            //       already be deleted now, just [implicitly]
                            //       pass an invalid Tcl interpreter handle to
                            //       Unload here, which will cause it to skip
                            //       attempting to delete the Tcl parent
                            //       interpreter.  After this call it may no
                            //       longer be safe to use the Tcl API because
                            //       we may be holding the last reference to it
                            //       and this call will then cause it to be
                            //       completely unloaded from memory.
                            //
                            if (TclWrapper.Unload(this, unloadFlags, ref tclApi,
                                    ref error) == ReturnCode.Ok)
                            {
#if NOTIFY && NOTIFY_TCL
                                /* IGNORED */
                                CheckNotification(
                                    NotifyType.Tcl, NotifyFlags.Unload,
                                    unloadFlags, this,
                                    null, null, null, ref error);
#endif

                                return ReturnCode.Ok;
                            }
                        }
                    }
                    finally
                    {
                        /* IGNORED */
                        GlobalState.PopActiveInterpreter();
                    }
                }
                else
                {
                    error = "cannot unload Tcl, wrong thread";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if TCL_WRAPPER
        /// <summary>
        /// Gets or sets the native Tcl API object used by this interpreter to
        /// interact with the loaded native Tcl library.
        /// </summary>
        public ITclApi TclApi
        {
            get
            {
                CheckDisposed();

                lock (tclSyncRoot)
                {
                    return tclApi;
                }
            }
            set
            {
                CheckDisposed();

                lock (tclSyncRoot)
                {
                    tclApi = value;
                }
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method returns the identifier of the native thread associated
        /// with the native Tcl library for this interpreter.
        /// </summary>
        /// <returns>
        /// The native Tcl thread identifier, or zero if none has been recorded.
        /// </returns>
        internal long GetTclThreadId()
        {
            //
            // HACK: In order to avoid any potential deadlocks
            //       here, avoid grabbing the interpreter lock.
            //
            return Interlocked.CompareExchange(ref nativeThreadId, 0, 0);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified thread identifier
        /// matches the native Tcl thread associated with this interpreter.
        /// </summary>
        /// <param name="threadId">
        /// The thread identifier to compare against the native Tcl thread
        /// identifier.
        /// </param>
        /// <returns>
        /// True if the specified thread identifier is that of the native Tcl
        /// thread; otherwise, false.
        /// </returns>
        internal bool IsTclThread(long threadId)
        {
            return (threadId == GetTclThreadId());
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets or sets the native Tcl API object used by this interpreter to
        /// interact with the loaded native Tcl library, for use within the core
        /// library.
        /// </summary>
        internal ITclApi InternalTclApi
        {
            get { return tclApi; }
            set { tclApi = value; }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Tcl Interpreter Support
        /// <summary>
        /// This method determines whether script evaluation has been canceled
        /// for the specified native Tcl interpreter, using the default set of
        /// canceled flags.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to query.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// The cancellation status of the specified native Tcl interpreter, as
        /// a <see cref="ReturnCode" /> value.
        /// </returns>
        public ReturnCode IsTclInterpreterCanceled(
            string name,
            ref Result error
            )
        {
            CheckDisposed();

            return IsTclInterpreterCanceled(
                name, TclWrapper.GetCanceledFlags(false, true),
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether script evaluation has been canceled
        /// for the specified native Tcl interpreter, using the specified
        /// canceled flags.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to query.
        /// </param>
        /// <param name="flags">
        /// The flags used to control how the cancellation status is queried.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// The cancellation status of the specified native Tcl interpreter, as
        /// a <see cref="ReturnCode" /> value.
        /// </returns>
        public ReturnCode IsTclInterpreterCanceled(
            string name,
            Tcl_CanceledFlags flags,
            ref Result error
            )
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;

            if (GetTclInterpreter(
                    name, LookupFlags.Default, ref interp,
                    ref error) == ReturnCode.Ok)
            {
                return TclWrapper.Canceled(
                    tclApi, interp, flags, ref error);
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified native Tcl interpreter
        /// is ready to evaluate a script.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to query.
        /// </param>
        /// <param name="deleted">
        /// Non-zero if a deleted native Tcl interpreter should be considered as
        /// not ready.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// True if the specified native Tcl interpreter is ready; otherwise,
        /// false.
        /// </returns>
        public bool IsTclInterpreterReady(
            string name,
            bool deleted,
            ref Result error
            )
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;

            if (GetTclInterpreter(
                    name, LookupFlags.Default, ref interp,
                    ref error) == ReturnCode.Ok)
            {
                return TclWrapper.IsReady(
                    tclApi, interp, deleted, ref error);
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified native Tcl interpreter
        /// is currently active (i.e. evaluating a script).
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to query.
        /// </param>
        /// <returns>
        /// True if the specified native Tcl interpreter is active; otherwise,
        /// false.
        /// </returns>
        public bool IsTclInterpreterActive(
            string name
            )
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;

            if (GetTclInterpreter(
                    name, LookupFlags.NoVerbose,
                    ref interp) == ReturnCode.Ok)
            {
                return TclWrapper.GetInterpActive(tclApi, interp);
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the line number associated with the most recent
        /// error that occurred in the specified native Tcl interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to query.
        /// </param>
        /// <returns>
        /// The error line number, or zero if it cannot be determined.
        /// </returns>
        public int GetTclInterpreterErrorLine(
            string name
            )
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;

            if (GetTclInterpreter(
                    name, LookupFlags.NoVerbose,
                    ref interp) == ReturnCode.Ok)
            {
                return TclWrapper.GetErrorLine(tclApi, interp);
