        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method determines whether the specified native Tcl interpreter
        /// is ready to evaluate a script, treating a deleted interpreter as not
        /// ready and discarding any error message.
        /// </summary>
        /// <param name="name">
        /// The name of the native Tcl interpreter to query.
        /// </param>
        /// <returns>
        /// True if the specified native Tcl interpreter is ready; otherwise,
        /// false.
        /// </returns>
        internal bool IsTclInterpreterReady(
            string name
            )
        {
            Result error = null;

            return IsTclInterpreterReady(name, true, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method locates the native thread identifier associated with the
        /// specified native Tcl interpreter, searching both the interpreters
        /// belonging to the primary thread and any isolated Tcl threads owned by
        /// this interpreter.
        /// </summary>
        /// <param name="interp">
        /// The native Tcl interpreter to locate.
        /// </param>
        /// <param name="threadId">
        /// Upon success, this parameter will be modified to contain the native
        /// thread identifier that owns the specified native Tcl interpreter.
        /// </param>
        /// <returns>
        /// True if the specified native Tcl interpreter was found; otherwise,
        /// false.
        /// </returns>
        internal bool FindTclInterpreterThreadId(
            IntPtr interp,
            ref long threadId
            )
        {
            IntPtrList interps = null;
#if TCL_THREADS
            TclThreadList threads = null;
#endif

            //
            // BUGBUG: This is likely to be a serious performance bottleneck
            //         since this method must be called for every Tcl API
            //         function call that involves a Tcl interpreter or a Tcl
            //         object.
            //
            lock (tclSyncRoot) /* TRANSACTIONAL */
            {
                //
                // NOTE: Get the list of Tcl interps from the
                //       interpreter.
                //
                if (InternalHasTclInterpreters())
                    interps = new IntPtrList(tclInterps.Values);

#if TCL_THREADS
                //
                // NOTE: Get the list of Tcl threads from the
                //       interpreter.
                //
                if (HasTclThreads())
                    threads = new TclThreadList(tclThreads.Values);
#endif
            }

            //
            // NOTE: First, check the Tcl interps that belong to the
            //       primary thread for this interpreter.
            //
            if (interps != null)
            {
                foreach (IntPtr localInterp in interps)
                {
                    if (localInterp == interp)
                    {
                        //
                        // NOTE: Return the primary native thread Id.
                        //
                        threadId = GetTclThreadId();

                        //
                        // NOTE: Success, we found the Tcl interpreter.
                        //
                        return true;
                    }
                }
            }

#if TCL_THREADS
            //
            // NOTE: Next, check the Tcl threads that belong to this
            //       interpreter.  Each one of these threads has an
            //       isolated Tcl interpreter.
            //
            if (threads != null)
            {
                foreach (TclThread thread in threads)
                {
                    if ((thread != null) && (thread.Interp == interp))
                    {
                        //
                        // NOTE: Return the specified thread Id for this Tcl
                        //       interpreter.
                        //
                        threadId = thread.ThreadId;

                        //
                        // NOTE: Success, we found the Tcl interpreter.
                        //
                        return true;
                    }
                }
            }
#endif

#if TCL_WRAPPER
            // lock (tclSyncRoot) /* TRANSACTIONAL */ /* TODO: Lock? */
            {
                //
                // NOTE: In "Tcl wrapper" mode, we assume that any
                //       Tcl interpreter we cannot otherwise locate
                //       was created on the main thread of the Eagle
                //       interpreter.
                //
                if (FlagOps.HasFlags(
                        tclFindFlags, FindFlags.TclWrapper, true))
                {
                    //
                    // NOTE: Return the primary thread Id.
                    //
                    threadId = this.threadId;

                    return true;
                }
            }
#endif

            //
            // NOTE: Failure, we did not find the Tcl interpreter.
            //
            return false;
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Tcl Thread Event Support
#if TCL_THREADS
        /// <summary>
        /// This method queues an event for asynchronous or synchronous handling
        /// on the specified isolated Tcl thread.
        /// </summary>
        /// <param name="threadName">
        /// The name of the Tcl thread to which the event should be queued.
        /// </param>
        /// <param name="type">
        /// The type of event to queue.
        /// </param>
        /// <param name="flags">
        /// The flags used to control how the event is queued and handled.
        /// </param>
        /// <param name="data">
        /// The optional data to associate with the queued event.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero if this method should block until the event has been
        /// handled.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the result
        /// of handling the event; upon failure, it will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode QueueTclThreadEvent(
            string threadName,
            EventType type,
            EventFlags flags,
            object data,
            bool synchronous,
            ref Result result
            )
        {
            CheckDisposed();

            int errorLine = 0;

            return QueueTclThreadEvent(
                threadName, type, flags, data, synchronous, ref result, ref errorLine);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method queues an event for asynchronous or synchronous handling
        /// on the specified isolated Tcl thread, also reporting the error line
        /// number associated with any failure.
        /// </summary>
        /// <param name="threadName">
        /// The name of the Tcl thread to which the event should be queued.
        /// </param>
        /// <param name="type">
        /// The type of event to queue.
        /// </param>
        /// <param name="flags">
        /// The flags used to control how the event is queued and handled.
        /// </param>
        /// <param name="data">
        /// The optional data to associate with the queued event.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero if this method should block until the event has been
        /// handled.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the result
        /// of handling the event; upon failure, it will contain an appropriate
        /// error message.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this parameter will be modified to contain the line
        /// number where the error occurred.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode QueueTclThreadEvent(
            string threadName,
            EventType type,
            EventFlags flags,
            object data,
            bool synchronous,
            ref Result result,
            ref int errorLine
            )
        {
            CheckDisposed();

            TclThread thread = null;

            if (GetTclThread(threadName, LookupFlags.Default, ref thread, ref result) == ReturnCode.Ok)
            {
                if (thread != null)
                {
                    if (thread.QueueEvent(type, flags, data, synchronous,
                            ref result, ref errorLine) == ReturnCode.Ok)
                    {
#if NOTIFY && NOTIFY_TCL
                        /* IGNORED */
                        CheckNotification(
                            NotifyType.Tcl | NotifyType.Thread | NotifyType.Event, NotifyFlags.Queued,
                            new ObjectList(threadName, thread, type, flags, data, synchronous),
                            this, null, null, null, ref result);
#endif

                        return ReturnCode.Ok;
                    }
                }
                else
                {
                    result = "invalid Tcl thread";
                }
            }

            return ReturnCode.Error;
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Tcl Thread Miscellaneous Support
#if !TCL_THREADS
        /// <summary>
        /// This method determines whether the specified thread identifier is
        /// that of the primary thread for this interpreter.  When native Tcl
        /// threading is not available, this is used in place of the per-thread
        /// tracking facilities.
        /// </summary>
        /// <param name="threadId">
        /// On input, the thread identifier to compare against the primary thread
        /// for this interpreter.  On output, when it did not already match, this
        /// parameter will be modified to contain the primary thread identifier
        /// for this interpreter.
        /// </param>
        /// <returns>
        /// True if the specified thread identifier is that of the primary thread
        /// for this interpreter; otherwise, false.
        /// </returns>
        internal bool IsPrimaryTclThread(
            ref long threadId /* in, out */
            )
        {
            //
            // NOTE: Is the thread Id provided by the caller the same as the
            //       primary one for this interpreter?
            //
            bool result = (threadId == this.threadId);

            //
            // NOTE: Now that we know the result, overwrite the thread Id
            //       provided by the caller with the primary one for this
            //       interpreter, if necessary (for their use).
            //
            if (!result) /* NOTE: Skip if already the same. */
                threadId = this.threadId;

            //
            // NOTE: Done, return the result.
            //
            return result;
        }
#endif
        #endregion

