        /// <summary>
        /// This method cancels the script currently being evaluated in the
        /// specified native Tcl interpreter, using the specified evaluate flags
        /// and returning the client data associated with the cancellation.
        /// </summary>
        /// <param name="interpName">
        /// The name of the native Tcl interpreter to use.
        /// </param>
        /// <param name="result">
        /// The optional result to associate with the cancellation.
        /// </param>
        /// <param name="flags">
        /// The flags used to control how the cancellation is performed.
        /// </param>
        /// <param name="clientData">
        /// Upon success, this parameter will be modified to contain the client
        /// data associated with the cancellation.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode CancelTclEvaluate(
            string interpName,
            Result result,
            Tcl_EvalFlags flags,
            ref IClientData clientData,
            ref Result error
            )
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;

            ReturnCode code = GetTclInterpreter(
                interpName, LookupFlags.Default, ref interp, ref result);

            if (code == ReturnCode.Ok)
            {
                code = TclWrapper.CancelEvaluate(
                    tclApi, interp, result, flags, ref clientData, ref error);
            }

#if NOTIFY && NOTIFY_TCL
            /* IGNORED */
            CheckNotification(
                NotifyType.Tcl | NotifyType.Script, NotifyFlags.Canceled,
                new ObjectTriplet(flags, result, code), this,
                null, null, null, ref error);
#endif

            return code;
        }

