        /// <summary>
        /// Gets or sets a value indicating whether exceptions raised by the
        /// loaded native Tcl library should be caught and converted into errors.
        /// </summary>
        public bool TclExceptions
        {
            get
            {
                CheckDisposed();

                lock (tclSyncRoot) /* TRANSACTIONAL */
                {
                    return (tclApi != null) ? tclApi.Exceptions : false;
                }
            }
            set
            {
                CheckDisposed();

                lock (tclSyncRoot) /* TRANSACTIONAL */
                {
                    if (tclApi != null) tclApi.Exceptions = value;
                }
            }
        }

