        /// <summary>
        /// This method evaluates the Tcl script contained in the specified file
        /// using the specified native Tcl interpreter, using the specified
        /// exception handling behavior and returning the associated client
        /// data.
        /// </summary>
        /// <param name="interpName">
        /// The name of the native Tcl interpreter to use.
        /// </param>
        /// <param name="fileName">
        /// The name of the file containing the Tcl script to evaluate.
        /// </param>
        /// <param name="exceptions">
        /// Non-zero if exceptions raised by the native Tcl library should be
        /// caught and converted into errors.
        /// </param>
        /// <param name="clientData">
        /// Upon success, this parameter will be modified to contain the client
        /// data associated with the evaluation.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the result
        /// of evaluating the file; upon failure, it will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode EvaluateTclFile(
            string interpName,
            string fileName,
            bool exceptions,
            ref IClientData clientData,
            ref Result result
            )
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;

            ReturnCode code = GetTclInterpreter(
                interpName, LookupFlags.Default, ref interp, ref result);

            if (code == ReturnCode.Ok)
            {
                string name = StringList.MakeList("tcl source", interpName, fileName);

                ICallFrame frame = NewTrackingCallFrame(name,
                    CallFrameFlags.Source | CallFrameFlags.Tcl);

                PushAutomaticCallFrame(frame);

                code = TclWrapper.EvaluateFile(
                    tclApi, interp, fileName, exceptions, ref clientData, ref result);

#if NOTIFY && NOTIFY_TCL
                /* IGNORED */
                CheckNotification(
                    NotifyType.Tcl | NotifyType.File, NotifyFlags.Evaluated,
                    new ObjectPair(interpName, fileName), this,
                    null, null, null, ref result);
#endif

                //
                // NOTE: Pop the original call frame that we pushed above and
                //       any intervening scope call frames that may be leftover
                //       (i.e. they were not explicitly closed).
                //
                /* IGNORED */
                PopScopeCallFramesAndOneMore();
            }

            return code;
        }

