        /// </param>
        /// <param name="name">
        /// The name of the Tcl variable to query.
        /// </param>
        /// <param name="value">
        /// Upon success, this parameter will be modified to contain the value of
        /// the variable.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode GetTclVariableValue(
            string interpName,
            Tcl_VarFlags flags,
            string name,
            ref Result value,
            ref Result error
            )
        {
            CheckDisposed();

            IntPtr interp = IntPtr.Zero;

            ReturnCode code = GetTclInterpreter(
                interpName, LookupFlags.Default, ref interp, ref error);

            if (code == ReturnCode.Ok)
            {
                code = TclWrapper.GetVariable(
                    tclApi, interp, flags, name, ref value, ref error);

#if NOTIFY && NOTIFY_TCL
                /* IGNORED */
                CheckNotification(
                    NotifyType.Tcl | NotifyType.Variable, NotifyFlags.GetVariable,
                    new ObjectList(interpName, flags, name, value), this,
                    null, null, null, ref error);
#endif
            }

            return code;
        }

