        #region Variable Performance
        /// <summary>
        /// This method enables or disables the "fast" mode for the specified
        /// variable, which controls whether trace and notification processing is
        /// bypassed for that variable.
        /// </summary>
        /// <param name="name">
        /// The name of the variable to modify.
        /// </param>
        /// <param name="fast">
        /// Non-zero to enable "fast" mode for the variable; zero to disable it.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode MakeVariableFast(
            string name,
            bool fast,
            ref Result error
            )
        {
            CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                VariableFlags flags = VariableFlags.NoElement;
                IVariable variable = null;

                if (GetVariableViaResolversWithSplit(
                        name, ref flags, ref variable,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (EntityOps.IsLink(variable))
                {
                    variable = EntityOps.FollowLinks(
                        variable, flags, ref error);

                    if (variable == null)
                        return ReturnCode.Error;
                }

                variable.SetFlags(VariableFlags.FastMask, fast);
                return ReturnCode.Ok;
            }
        }
        #endregion

