        /// </param>
        /// <param name="limit">
        /// The maximum number of events to process while waiting.
        /// </param>
        /// <param name="event">
        /// The optional additional event handle that, when signaled, should also
        /// satisfy the wait.
        /// </param>
        /// <param name="notReady">
        /// Upon return, this parameter will be modified to indicate whether the
        /// interpreter was not ready to wait.
        /// </param>
        /// <param name="timedOut">
        /// Upon return, this parameter will be modified to indicate whether the
        /// wait timed out before the variable changed.
        /// </param>
        /// <param name="changed">
        /// Upon return, this parameter will be modified to indicate whether the
        /// variable changed while waiting.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode WaitVariable(
            EventWaitFlags eventWaitFlags, /* in */
            VariableFlags variableFlags,   /* in */
            string name,                   /* in */
            long microseconds,             /* in */
            long? threadId,                /* in, optional */
            int limit,                     /* in */
            EventWaitHandle @event,        /* in, optional */
            ref bool notReady,             /* out */
            ref bool timedOut,             /* out */
            ref bool changed,              /* out */
            ref Result error               /* out */
            ) /* THREAD-SAFE */
        {
            CheckDisposed();

            IAnyClientData clientData = null;

            try
            {
                ReturnCode code = ReturnCode.Ok;

                ///////////////////////////////////////////////////////////////

                EventCallback preCallback;
                EventCallback postCallback;

                EventOps.QueryWaitCallbacks(
                    this, out preCallback, out postCallback);

                if ((preCallback != null) || (postCallback != null))
                {
                    clientData = new AnyClientData();

                    clientData.TrySetAny("eventWaitFlags", eventWaitFlags);
                    clientData.TrySetAny("variableFlags", variableFlags);
                    clientData.TrySetAny("name", name);
                    clientData.TrySetAny("microseconds", microseconds);
                    clientData.TrySetAny("threadId", threadId);
                    clientData.TrySetAny("limit", limit);
                    clientData.TrySetAny("event", @event);
                }

                ///////////////////////////////////////////////////////////////

                if (preCallback != null)
                {
                    clientData.TrySetAny("callback", "preWaitVariable");
                    clientData.TrySetAny("code", code);
                    clientData.TrySetAny("error", error);

                    try
                    {
                        ReturnCode callbackCode;
                        Result callbackError = null;

                        callbackCode = preCallback(
                            this, clientData,
                            ref callbackError); /* throw */

                        if (callbackCode != ReturnCode.Ok)
                        {
                            error = callbackError;
                            return callbackCode;
                        }
                    }
                    catch (Exception e)
                    {
                        error = e;
                        return ReturnCode.Error;
                    }
                }

                ///////////////////////////////////////////////////////////////

                if (microseconds < 0)
                {
                    error = "number of microseconds cannot be negative";
                    return ReturnCode.Error;
                }

                ///////////////////////////////////////////////////////////////

                if (EnterWait() > 0)
                {
                    //
                    // NOTE: *WARNING* Empty variable names are allowed, please
                    //       do not change these to "!String.IsNullOrEmpty".
                    //
                    if (name != null)
                    {
                        bool noBgError = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoBgError, true);

                        bool noManagerEvents = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoManagerEvents, true);

                        bool noCancel = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoCancel, true);

                        bool noGlobalCancel = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoGlobalCancel, true);

                        bool stopOnError = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.StopOnError, true);

                        bool errorOnEmpty = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.ErrorOnEmpty, true);

                        bool userInterface = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.UserInterface, true);

                        bool noUserInterface = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoUserInterface, true);

                        bool noEvents = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoEvents, true);

#if NATIVE && WINDOWS
                        bool noWindows = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoWindows, true);
#endif

                        bool noSleep = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoSleep, true);

                        bool noComplain = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.NoComplain, true);

                        bool stopOnComplain = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.StopOnComplain, true);

                        bool stopOnGlobalComplain = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.StopOnGlobalComplain, true);

                        bool onlyWaiting = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.OnlyWaiting, true);

                        bool onlyExists = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.OnlyExists, true);

                        bool doOneEvent = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.DoOneEvent, true);

#if NATIVE && TCL
                        bool tclDoOneEvent = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.TclDoOneEvent, true);

                        //
                        // NOTE: The "TclWaitEvent" flag should rarely, if ever,
                        //       be used.
                        //
                        bool tclWaitEvent = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.TclWaitEvent, true);

                        bool tclAllEvents = FlagOps.HasFlags(
                            eventWaitFlags, EventWaitFlags.TclAllEvents, true);
#endif

                        //
                        // NOTE: *WARNING* Sanity check the user-interface
                        //       flag here.  We MUST pump messages if this
                        //       is an STA thread.
                        //
                        if (!userInterface && ThreadOps.IsStaThread())
                        {
                            userInterface = true;

                            if (FlagOps.HasFlags(
                                    eventWaitFlags, EventWaitFlags.Trace, true))
                            {
                                //
                                // HACK: Uses the "id" field directly, to
                                //       avoid disposal exception issues.
                                //
                                TraceOps.DebugTrace(String.Format(
                                    "WaitVariable: detected STA thread, user-interface " +
                                    "flag forcibly enabled, interpreter = {0}, " +
                                    "eventWaitFlags = {1}, variableFlags = {2}, name = {3}, " +
                                    "microseconds = {4}, limit = {5}, event = {6}, " +
                                    "notReady = {7}, changed = {8}, error = {9}",
                                    FormatOps.WrapOrNull(id),
                                    FormatOps.WrapOrNull(eventWaitFlags),
                                    FormatOps.WrapOrNull(variableFlags),
                                    FormatOps.WrapOrNull(name), microseconds,
                                    limit, FormatOps.WrapOrNull(@event), notReady,
                                    changed, FormatOps.WrapOrNull(true, true, error)),
                                    typeof(Interpreter).Name, TracePriority.EventDebug);
                            }
                        }

                        //
                        // NOTE: Setup the extra event flags for this
                        //       method.  These will be based primarily on
                        //       the event wait flags passed by the caller
                        //       and will typically be "None".
                        //
                        EventFlags extraEventFlags = EventFlags.None;

                        if (noBgError)
                            extraEventFlags |= EventFlags.NoBgError;

                        //
                        // NOTE: Is the variable undefined before waiting
                        //       for changes?
                        //
                        bool wasUndefined = false;

                        //
                        // NOTE: Has the existence of the variable been
                        //       checked?
                        //
                        bool once = false;

                        //
                        // NOTE: NOTE: Does the variable currently exist?
                        //
                        bool exists = false;

                        //
                        // NOTE: Has the variable been added, modified, or
                        //       unset since we started waiting?
                        //
                        bool dirty = false;

                        //
                        // NOTE: What is the timeout used when waiting for
                        //       an internal lock request (e.g. to fetch
                        //       the IEventManager, etc)?
                        //
                        int timeout = EventOps.GetMilliseconds(microseconds);

                        //
                        // NOTE: Create the array of event handles to wait
                        //       on.  The first event is signaled when any
                        //       variable is set or unset in the interpreter.
                        //       The second event is signaled when the queue
                        //       managed by the event manager is empty.  The
                        //       third [and final] event is signaled when an
                        //       event is queued to the queue managed by the
                        //       event manager.
                        //
                        EventWaitHandle[] events = GetEventWaitHandles(
                            @event, timeout, true, noManagerEvents, true);

                        //
                        // NOTE: Keep track of the total number of events
                        //       processed.
                        //
                        int localEventCount = 0;

#if NATIVE && TCL
                        //
                        // NOTE: Keep track of the total number of native Tcl
                        //       events processed.
                        //
                        int localTclEventCount = 0;
                        int localTclSleepCount = 0;
#endif

                        //
                        // NOTE: Keep track of the iterations of main loop of
                        //       this method (for diagnostic purposes only).
                        //
                        int localWaitSpinCount = 0;

                        //
                        // NOTE: For precise timing, use the high-resolution
                        //       CPU performance counter.
                        //
                        long startCount = PerformanceOps.GetCount();
                        long stopCount = 0;

                        //
                        // BUGFIX: Make sure the slop time does not exceed
                        //         the actual wait.
                        //
                        long slopMicroseconds = EventOps.GetSlopMicroseconds(
                            microseconds);

                        //
                        // NOTE: Keep waiting for the variable until one of
                        //       the following conditions is true:
                        //
                        //       1. The interpreter is no longer ready (i.e.
                        //          canceled, deleted, halted, exited, etc).
                        //
                        //       2. The variable is created, deleted, or
                        //          changed.
                        //
                        //       3. Any error is raised while processing
                        //          events, fully taking into account the
                        //          "stopOnError" flag, which is handled by
                        //          the EventManager itself.
                        //
                        CheckVariableNameUndefined(
                            this, name, eventWaitFlags, variableFlags,
                            ref wasUndefined);

                        while (((code = EventReady(
                                     this, null, noCancel, noGlobalCancel,
                                     out notReady, out timedOut,
                                     ref error)) == ReturnCode.Ok) &&
                               ((microseconds == 0) || !PerformanceOps.HasElapsed(
                                     startCount, ref stopCount, microseconds,
                                     slopMicroseconds)) &&
                               ((code = IsVariableNameSignaled(
                                     this, name, eventWaitFlags, variableFlags,
                                     onlyWaiting, onlyExists, ref wasUndefined,
                                     ref once, ref exists, ref dirty,
                                     ref error)) == ReturnCode.Ok) && !dirty)
                        {
                            //
                            // NOTE: Grab the (current) number of complaints that
                            //       have been registered for thread and/or
                            //       AppDomain.
                            //
                            long beforeComplainCount = 0;
                            long beforeGlobalComplainCount = 0;
                            long beforeComplainQuietCount = 0; /* NOT USED */
                            long beforeGlobalComplainQuietCount = 0; /* NOT USED */

                            if (stopOnComplain || stopOnGlobalComplain)
                            {
                                DebugOps.GetComplainCounts(
                                    stopOnComplain, stopOnGlobalComplain,
                                    ref beforeComplainCount,
                                    ref beforeGlobalComplainCount,
                                    ref beforeComplainQuietCount,
                                    ref beforeGlobalComplainQuietCount);
                            }

                            //
                            // NOTE: We need a local result because we do
                            //       not want to change the caller's result
                            //       based on random async events that get
                            //       processed while waiting for their
                            //       variable to become "signaled".  However,
                            //       we will change the caller's result if
                            //       an error is encountered.
                            //
                            Result localResult; /* REUSED */

#if NATIVE && TCL
                            //
                            // NOTE: Does the caller also want to process
                            //       native Tcl events during this wait
                            //       operation?
                            //
                            if (tclDoOneEvent)
                            {
                                //
                                // NOTE: If Tcl has been loaded into this
                                //       interpreter, attempt to process
                                //       events for it now.
                                //
                                ITclApi tclApi = _Private.Tcl.TclApi.GetTclApi(this);

                                if (_Private.Tcl.TclApi.CheckModule(tclApi))
                                {
                                    //
                                    // NOTE: Process one (or all) Tcl events
                                    //       from its queue, without waiting.
                                    //
                                    localResult = null;

                                    code = TclWrapper.DoOneEvent(
                                        this, 0, tclWaitEvent, tclAllEvents,
                                        noComplain, ref localTclEventCount,
                                        ref localTclSleepCount, ref tclApi,
                                        ref localResult);

                                    _Private.Tcl.TclApi.SetTclApi(
                                        this, tclApi);

                                    //
                                    // NOTE: If we encountered an error
                                    //       processing Tcl events, break
                                    //       out of the loop and return
                                    //       the error code and result to
                                    //       the caller.
                                    //
                                    if (code != ReturnCode.Ok)
                                    {
                                        error = localResult;
                                        break;
                                    }
                                }
                            }
#endif

                            //
                            // NOTE: Does the caller also want to process
                            //       events during this wait operation?
                            //
                            if (doOneEvent)
                            {
                                //
                                // NOTE: Attempt to process all pending
                                //       events stopping if an error is
                                //       encountered.  This grabs and uses
                                //       the current wait event flags
                                //       without locking.
                                //
                                EventFlags? localWaitEventFlags = TryGetWaitEventFlags();

                                if (localWaitEventFlags != null)
                                {
                                    localResult = null;

                                    code = EventOps.DoOneEvent(
                                        this, (EventFlags)localWaitEventFlags |
                                        extraEventFlags, EventPriority.WaitVariable,
                                        threadId, limit, stopOnError, errorOnEmpty,
                                        !noUserInterface && userInterface,
                                        ref localEventCount, ref localResult);

                                    //
                                    // NOTE: If we encountered an error
                                    //       processing events, break out
                                    //       of the loop and return the
                                    //       error code and result to the
                                    //       caller.
                                    //
                                    if (code != ReturnCode.Ok)
                                    {
                                        error = localResult;
                                        break;
                                    }
                                }
                            }

                            //
                            // NOTE: Is the caller permitting us to sleep?
                            //       If not, do nothing; otherwise, figure
                            //       out the correct method and timeout for
                            //       sleeping.
                            //
                            if (!noSleep)
                            {
                                //
                                // NOTE: Get configured sleep time for this
                                //       interpreter [or the minimum possible
                                //       sleep time].
                                //
                                int sleepMilliseconds = GetMinimumSleepTime(
                                    SleepType.Variable, timeout);

                                //
                                // NOTE: Here, we yield to other running
                                //       threads.  This also gives them an
                                //       opportunity to cancel any script
                                //       being evaluated on this thread
                                //       and/or update the variable we are
                                //       waiting for.
                                //
                                SleepWaitCallback localSleepWaitCallback =
                                    TryGetSleepWaitCallback();

                                if (localSleepWaitCallback != null)
                                {
                                    localResult = null;

                                    code = localSleepWaitCallback(
                                        this, events, sleepMilliseconds,
                                        eventWaitFlags, ref localResult);

                                    if (code != ReturnCode.Ok)
                                    {
                                        error = localResult;
                                        break;
                                    }
                                }
                                else if (!noEvents && (events != null))
                                {
#if NATIVE && WINDOWS
                                    if (!noWindows &&
                                        PlatformOps.IsWindowsOperatingSystem())
                                    {
                                        localResult = null;

                                        code = WindowOps.WaitForMultipleHandles(
                                            events, sleepMilliseconds,
                                            userInterface, ref localResult);

                                        if (code != ReturnCode.Ok)
                                        {
                                            error = localResult;
                                            break;
                                        }
                                    }
                                    else
#endif
                                    {
                                        /* IGNORED */
                                        ThreadOps.WaitAnyEvent(
                                            events, sleepMilliseconds);
                                    }
                                }
                                else
                                {
                                    localResult = null;

                                    code = HostOps.Sleep(
                                        this, sleepMilliseconds,
                                        ref localResult);

                                    if (code != ReturnCode.Ok)
                                    {
                                        error = localResult;
                                        break;
                                    }
                                }
                            }

                            //
                            // NOTE: Grab the (new) number of complaints that
                            //       have been registered for thread and/or
                            //       AppDomain.
                            //
                            long afterComplainCount = 0;
                            long afterGlobalComplainCount = 0;
                            long afterComplainQuietCount = 0; /* NOT USED */
                            long afterGlobalComplainQuietCount = 0; /* NOT USED */

                            if (stopOnComplain || stopOnGlobalComplain)
                            {
                                DebugOps.GetComplainCounts(
                                    stopOnComplain, stopOnGlobalComplain,
                                    ref afterComplainCount,
                                    ref afterGlobalComplainCount,
                                    ref afterComplainQuietCount,
                                    ref afterGlobalComplainQuietCount);
                            }

                            //
                            // NOTE: If the stop-on-complain flags have been
                            //       set, make sure there have been no
                            //       complaints for this iteration -OR- stop
                            //       processing events now.
                            //
                            if (stopOnComplain &&
                                    (afterComplainCount > beforeComplainCount))
                            {
                                string complaint = this.Complaint; /* THREAD-SAFE */

                                error = StringList.MakeList(String.Format(
                                    "count of complaints increased from {0} to {1}",
                                    beforeComplainCount, afterComplainCount), complaint);

                                code = ReturnCode.Error;
                                break;
                            }

                            if (stopOnGlobalComplain &&
                                    (afterGlobalComplainCount > beforeGlobalComplainCount))
                            {
                                string complaint = DebugOps.SafeGetGlobalComplaint(); /* THREAD-SAFE */

                                error = StringList.MakeList(String.Format(
                                    "count of global complaints increased from {0} to {1}",
                                    beforeGlobalComplainCount, afterGlobalComplainCount),
                                    complaint);

                                code = ReturnCode.Error;
                                break;
                            }

                            //
                            // NOTE: Keep track of how many times we actually
                            //       waited for an event.  This does not
                            //       currently distinguish between a timeout
                            //       and an event handle being signaled.
                            //
                            localWaitSpinCount++; /* THREAD-SAFE */
                            Interlocked.Increment(ref waitSpinCount);
                        }

#if NATIVE && TCL
                        //
                        // BUGFIX: Update the total processed Tcl event count
                        //         for this interpreter.  We do not care about
                        //         the return code here because this field is
                        //         totally exempt from the "transactional
                        //         semantics" of this method.  This was being
                        //         done from within the loop above; however,
                        //         it was wrong to do it that way (i.e. because
                        //         an event could be double counted).
                        //
                        /* IGNORED */
                        Interlocked.Add(ref tclEventCount, localTclEventCount);
                        Interlocked.Add(ref tclSleepCount, localTclSleepCount);
#endif

                        //
                        // BUGFIX: Update the total processed event count for
                        //         this interpreter.  We do not care about the
                        //         return code here because this field is
                        //         totally exempt from the "transactional
                        //         semantics" of this method.  This was being
                        //         done from within the loop above; however,
                        //         it was wrong to do it that way (i.e. because
                        //         an event could be double counted).
                        //
                        /* IGNORED */
                        Interlocked.Add(ref eventCount, localEventCount);

                        //
                        // NOTE: Clear the wait status bit(s) for the scalar
                        //       variable and/or array element being waited.
                        //
                        ClearVariableNameWait(
                            this, name, eventWaitFlags, variableFlags);

                        //
                        // NOTE: Show diagnostics about this wait operation?
                        //
                        if (FlagOps.HasFlags(
                                eventWaitFlags, EventWaitFlags.Trace, true))
                        {
                            //
                            // HACK: Uses the interpreter "id" field directly,
                            //       to avoid disposal exception issues.
                            //
                            TraceOps.DebugTrace(String.Format(
                                "WaitVariable: interpreter = {0}, code = {1}, " +
                                "eventWaitFlags = {2}, variableFlags = {3}, " +
                                "name = {4}, microseconds = {5}, threadId = {6}, " +
                                "limit = {7}, wasUndefined = {8}, once = {9}, " +
                                "exists = {10}, dirty = {11}, localEventCount = {12}, " +
                                "eventCount = {13}, localTclEventCount = {14}, " +
                                "localTclSleepCount = {15}, tclEventCount = {16}, " +
                                "tclSleepCount = {17}, waitCount = {18}, " +
                                "localWaitSpinCount = {19}, waitSpinCount = {20}, " +
                                "event = {21}, changed = {22}, error = {23}",
                                FormatOps.WrapOrNull(id), code,
                                FormatOps.WrapOrNull(eventWaitFlags),
                                FormatOps.WrapOrNull(variableFlags),
                                FormatOps.WrapOrNull(name),
                                microseconds,
                                FormatOps.WrapOrNull(threadId),
                                limit, wasUndefined, once, exists,
                                dirty, localEventCount, eventCount,
#if NATIVE && TCL
                                localTclEventCount,
                                localTclSleepCount,
                                tclEventCount,
                                tclSleepCount,
#else
                                0,
                                0,
                                0,
                                0,
#endif
                                waitCount, localWaitSpinCount, waitSpinCount,
                                FormatOps.WrapOrNull(@event), changed,
                                FormatOps.WrapOrNull(true, true, error)),
                                typeof(Interpreter).Name,
                                TracePriority.EventDebug);
                        }

                        //
                        // NOTE: Upon success, let the caller know if the
                        //       variable was actually changed (i.e. set
                        //       to dirty).
                        //
                        if (code == ReturnCode.Ok)
                            changed = dirty;
                    }
                    else
                    {
                        error = "invalid variable name";
                        code = ReturnCode.Error;
                    }

                    /* IGNORED */
                    ExitWait();
                }
                else
                {
                    error = "wait subsystem locked";
                    code = ReturnCode.Error;
                }

                ///////////////////////////////////////////////////////////////

                if (postCallback != null)
                {
                    clientData.TrySetAny("callback", "postWaitVariable");
                    clientData.TrySetAny("code", code);
                    clientData.TrySetAny("error", error);

                    try
                    {
                        ReturnCode callbackCode;
                        Result callbackError = null;

                        callbackCode = postCallback(
                            this, clientData,
                            ref callbackError); /* throw */

                        if (callbackCode != ReturnCode.Ok)
                        {
                            error = callbackError;
                            return callbackCode;
                        }
                    }
                    catch (Exception e)
                    {
                        error = e;
                        return ReturnCode.Error;
                    }
                }

                ///////////////////////////////////////////////////////////////

                return code;
            }
            finally
            {
                ObjectOps.DisposeOrTrace<IAnyClientData>(
                    this, ref clientData);

                clientData = null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method acquires an exclusive lock on the specified variable,
        /// waiting up to the specified amount of time and processing events
        /// while it waits.
        /// </summary>
        /// <param name="eventWaitFlags">
        /// The flags used to control how events are processed while waiting.
        /// </param>
        /// <param name="variableFlags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="name">
        /// The name of the variable to lock.
        /// </param>
        /// <param name="microseconds">
        /// The maximum number of microseconds to wait for the lock, or zero to
        /// wait indefinitely.
        /// </param>
        /// <param name="event">
        /// The optional additional event handle that, when signaled, should
        /// abort the wait.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode LockVariable(
            EventWaitFlags eventWaitFlags, /* in */
            VariableFlags variableFlags,   /* in */
            string name,                   /* in */
            long microseconds,             /* in */
            EventWaitHandle @event,        /* in, optional */
            ref Result error               /* out */
            ) /* THREAD-SAFE */
        {
            CheckDisposed();

            return PrivateLockVariable(
                eventWaitFlags, variableFlags, name, microseconds,
                @event, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method releases an exclusive lock previously acquired on the
        /// specified variable.
        /// </summary>
        /// <param name="variableFlags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="name">
        /// The name of the variable to unlock.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        public ReturnCode UnlockVariable(
            VariableFlags variableFlags, /* in */
            string name,                 /* in */
            ref Result error             /* out */
            )
        {
            CheckDisposed();

            return PrivateUnlockVariable(variableFlags, name, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method attempts to return the event flags used while waiting,
        /// acquiring the interpreter lock only if it can be done without
        /// blocking.
        /// </summary>
        /// <returns>
        /// The configured wait event flags, or null if the interpreter lock
        /// could not be acquired.
        /// </returns>
        private EventFlags? TryGetWaitEventFlags()
        {
            bool locked = false;

            try
            {
                InternalSoftTryLock(ref locked);

                if (locked)
                    return waitEventFlags;
            }
            finally
            {
                InternalExitLock(ref locked);
            }

            return null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to return the callback invoked while sleeping
        /// during a wait, acquiring the interpreter lock only if it can be done
        /// without blocking.
        /// </summary>
        /// <returns>
        /// The configured sleep-wait callback, or null if the interpreter lock
        /// could not be acquired.
        /// </returns>
        private SleepWaitCallback TryGetSleepWaitCallback()
        {
            bool locked = false;

            try
            {
                InternalSoftTryLock(ref locked);

                if (locked)
                    return sleepWaitCallback;
            }
            finally
            {
                InternalExitLock(ref locked);
            }

            return null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a list of the names of the variables that match
        /// the specified pattern.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control which variables are included.
        /// </param>
        /// <param name="pattern">
        /// The optional pattern that variable names must match in order to be
        /// included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <returns>
        /// The list of matching variable names, or null on failure.
        /// </returns>
        internal StringList VariablesToList(
            VariableFlags flags, /* in */
            string pattern,      /* in */
            bool noCase          /* in */
            )
        {
            ICallFrame frame;

            return VariablesToList(flags, pattern, noCase, out frame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a list of the names of the variables that match
        /// the specified pattern, also returning the call frame that was
        /// searched.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control which variables are included.
        /// </param>
        /// <param name="pattern">
        /// The optional pattern that variable names must match in order to be
        /// included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="frame">
        /// Upon return, this parameter will be modified to contain the call
        /// frame that was searched for variables.
        /// </param>
        /// <returns>
        /// The list of matching variable names, or null on failure.
        /// </returns>
        internal StringList VariablesToList(
            VariableFlags flags, /* in */
            string pattern,      /* in */
            bool noCase,         /* in */
            out ICallFrame frame /* out */
            )
        {
            Result error = null;

            StringList list = VariablesToList(
                flags, pattern, noCase, out frame, ref error);

            if ((list == null) && (error != null))
                DebugOps.Complain(this, ReturnCode.Error, error);

            return list;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a list of the names of the variables that match
        /// the specified pattern, reporting any error message.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control which variables are included.
        /// </param>
        /// <param name="pattern">
        /// The optional pattern that variable names must match in order to be
        /// included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// The list of matching variable names, or null on failure.
        /// </returns>
        private StringList VariablesToList(
            VariableFlags flags, /* in */
            string pattern,      /* in */
            bool noCase,         /* in */
            ref Result error     /* out */
            )
        {
            ICallFrame frame;

            return VariablesToList(
                flags, pattern, noCase, out frame, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a list of the names of the variables that match
        /// the specified pattern, also returning the call frame that was
        /// searched and reporting any error message.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control which variables are included.
        /// </param>
        /// <param name="pattern">
        /// The optional pattern that variable names must match in order to be
        /// included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="frame">
        /// Upon return, this parameter will be modified to contain the call
        /// frame that was searched for variables.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// The list of matching variable names, or null on failure.
        /// </returns>
        private StringList VariablesToList(
            VariableFlags flags,  /* in */
            string pattern,       /* in */
            bool noCase,          /* in */
            out ICallFrame frame, /* out */
            ref Result error      /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                frame = null;

                bool globalOnly = FlagOps.HasFlags(
                    flags, VariableFlags.GlobalOnly, true);

                ICallFrame variableFrame = null;
                VariableFlags frameFlags = VariableFlags.None;
                INamespace @namespace = null;
                string qualifiers = null;
                bool qualified = false;
                bool absolute = false;

                if (globalOnly)
                {
                    if (pattern != null)
                        pattern = ScriptOps.MakeVariableName(pattern);

                    variableFrame = CurrentGlobalFrame;
                }
                else
                {
                    bool useNamespaces = InternalAreNamespacesEnabled();

                    if (useNamespaces && (pattern != null))
                    {
                        string tail = null;
                        NamespaceFlags namespaceFlags = NamespaceFlags.None;

                        if (NamespaceOps.SplitName(
                                pattern, ref qualifiers, ref tail,
                                ref namespaceFlags, ref error) != ReturnCode.Ok)
                        {
                            return null;
                        }

                        qualified = FlagOps.HasFlags(
                            namespaceFlags, NamespaceFlags.Qualified, true);

                        absolute = FlagOps.HasFlags(
                            namespaceFlags, NamespaceFlags.Absolute, true);

                        @namespace = NamespaceOps.Lookup(
                            this, qualifiers, false, false, ref error);

                        if (@namespace == null)
                            return null;

                        if (qualified || absolute)
                        {
                            if (IsGlobalNamespace(@namespace))
                            {
                                variableFrame = CurrentGlobalFrame;
                                frameFlags |= VariableFlags.GlobalOnly;
                            }
                            else
                            {
                                variableFrame = @namespace.VariableFrame;
                            }
                        }
                        else
                        {
                            variableFrame = GetVariableFrame(null, frameFlags);

                            if (GetVariableFrameViaResolvers(
                                    LookupFlags.NoVerbose, ref variableFrame,
                                    ref frameFlags, ref error) != ReturnCode.Ok)
                            {
                                return null;
                            }
                        }

                        pattern = tail;
                    }
                    else
                    {
                        if (useNamespaces &&
                            GetCurrentNamespaceViaResolvers(
                                null, LookupFlags.NoVerbose,
                                ref @namespace, ref error) != ReturnCode.Ok)
                        {
                            return null;
                        }

                        variableFrame = GetVariableFrame(null,
                            ref pattern, ref frameFlags);

                        if (GetVariableFrameViaResolvers(
                                LookupFlags.NoVerbose, ref variableFrame,
                                ref frameFlags, ref error) != ReturnCode.Ok)
                        {
                            return null;
                        }
                    }
                }

                if (variableFrame == null)
                {
                    error = "invalid call frame from resolver";
                    return null;
                }

                VariableDictionary variables = variableFrame.Variables;

                if (variables == null)
                {
                    error = "call frame does not support variables";
                    return null;
                }

                StringList list = new StringList();

                bool linksOnly = FlagOps.HasFlags(flags,
                    VariableFlags.Link, true);

                bool systemOnly = FlagOps.HasFlags(flags,
                    VariableFlags.System, true);

                bool undefinedOnly = FlagOps.HasFlags(flags,
                    VariableFlags.Undefined, true);

                bool frameGlobalOnly = FlagOps.HasFlags(frameFlags,
                    VariableFlags.GlobalOnly, true);

                foreach (VariablePair pair in variables)
                {
                    IVariable variable = pair.Value;

                    if (!undefinedOnly && EntityOps.IsUndefined(variable))
                        continue;

                    string varName = pair.Key;

                    if ((pattern != null) && !StringOps.Match(
                            this, StringOps.DefaultMatchMode, varName,
                            pattern, false))
                    {
                        continue;
                    }

                    ///////////////////////////////////////////////////////////

                    if (globalOnly)
                    {
                        //
                        // BUGFIX: *COMPAT* Tcl. Apparently, links to undefined
                        //         variables do show up in the list of returned
                        //         globals (upvar-8.10).
                        //
                        // BUGFIX: Actually, that is a Tcl bug, not a feature;
                        //         therefore, we will mask undefined variables
                        //         from being returned by this command.
                        //
                        if (IsGlobalCallFrame(CallFrameOps.FollowNext(
                                variable.Frame)))
                        {
                            list.Add(varName);
                        }
                    }
                    else if ((!linksOnly || EntityOps.IsLink(variable)) &&
                        (!systemOnly || EntityOps.IsSystem(variable)) &&
                        (!undefinedOnly || EntityOps.IsUndefined(variable)))
                    {
                        //
                        // NOTE: Add the local variable or variable link name
                        //       to the resulting list.
                        //
                        if ((@namespace != null) &&
                            !IsGlobalNamespace(@namespace))
                        {
                            list.Add(NamespaceOps.MakeName(qualifiers,
                                varName, qualified, qualified || absolute));
                        }
                        else
                        {
                            list.Add(frameGlobalOnly ?
                                NamespaceOps.MakeAbsoluteName(varName) :
                                varName);
                        }
                    }
                }

                frame = variableFrame;
                return list;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method appends the names of the matching global variables to the
        /// specified list when the specified call frame is a namespace call
        /// frame.
        /// </summary>
        /// <param name="frame">
        /// The call frame being enumerated.
        /// </param>
        /// <param name="flags">
        /// The flags used to control which variables are included.
        /// </param>
        /// <param name="pattern">
        /// The optional pattern that variable names must match in order to be
        /// included.
        /// </param>
        /// <param name="noCase">
        /// Non-zero if the pattern matching should be case-insensitive.
        /// </param>
        /// <param name="list">
        /// On input, the list of variable names to which any matching global
        /// variable names should be appended.  This parameter will be created if
        /// it is null and there are matching global variables.
        /// </param>
        internal void MaybeAddGlobals(
            ICallFrame frame,    /* in */
            VariableFlags flags, /* in */
            string pattern,      /* in */
            bool noCase,         /* in */
            ref StringList list  /* in, out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (IsNamespaceCallFrame(frame))
                {
                    StringList localList = VariablesToList(
                        flags | VariableFlags.GlobalOnly, pattern,
                        noCase);

                    if (localList != null)
                    {
                        if (list == null)
                            list = new StringList();

                        list.AddRange(localList);
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new, transient variable instance to stand in
        /// for a variable that does not actually exist in the specified call
        /// frame.  The created variable is not added to the call frame.
        /// </summary>
        /// <param name="variableFrame">
        /// The call frame that would have owned the variable.
        /// </param>
        /// <param name="varName">
        /// The name of the variable to create.
        /// </param>
        /// <param name="varValue">
        /// The optional value for the new variable.  An element dictionary
        /// causes the variable to become an array; any other value makes it a
        /// scalar.
        /// </param>
        /// <param name="traces">
        /// The optional list of traces to associate with the new variable.
        /// </param>
        /// <param name="dirty">
        /// Non-zero if the new variable should be marked as dirty.
        /// </param>
        /// <param name="variableFlags">
        /// On input, the flags used to create the variable.  On output, this
        /// parameter will be modified to reflect the flags applied to the new
        /// variable, including the "WasMissing" flag.
        /// </param>
        /// <param name="localVariable">
        /// Upon return, this parameter will be modified to contain the newly
        /// created variable.
        /// </param>
        internal void CreateMissingVariable(
            ICallFrame variableFrame,
            string varName,
            object varValue,
            TraceList traces,
            bool dirty,
            ref VariableFlags variableFlags,
            out IVariable localVariable
            )
        {
            //
            // NOTE: The variable does not exist in the call frame,
            //       set the "WasMissing" flag.
            //
            variableFlags |= VariableFlags.WasMissing;

            //
            // NOTE: Is the target call frame the global one?  If so,
            //       make sure the correct flag is set.
            //
            bool isGlobalCallFrame = IsGlobalCallFrame(variableFrame);

            //
            // NOTE: Create the new variable instance now.  This is
            //       very similar to how variables are created via
            //       the AddVariable2 method.
            //
            localVariable = new Variable(variableFrame, varName,
                (variableFlags & ~VariableFlags.NonAddMask) |
                CallFrameOps.GetNewVariableFlags(variableFrame) |
                GetNewVariableFlags(isGlobalCallFrame), null,
                GetTraces(traces, varName, null, varValue, null),
                variableEvent);

            //
            // NOTE: Does the newly created (dummy) variable need a
            //       value?
            //
            if (varValue != null)
            {
                //
                // HACK: If the value happens to refer to an array
                //       of elements, this new variable will become
                //       an array; otherwise, it will be a scalar.
                //
                ElementDictionary arrayValue =
                    varValue as ElementDictionary;

                if (arrayValue != null)
                {
                    localVariable.Value = null;
                    localVariable.ArrayValue = arrayValue;

                    EntityOps.SetArray(localVariable, true);
                }
                else
                {
                    localVariable.Value = varValue;
                    localVariable.ArrayValue = null;

                    EntityOps.SetArray(localVariable, false);
                }
            }

            //
            // NOTE: Does the newly created (dummy) variable need to
            //       be signaled (as dirty)?
            //
            if (dirty)
                EntityOps.SetDirty(localVariable, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up a variable in the specified call frame, for use
        /// by the core variable resolver.  Optionally, when the appropriate flag
        /// is set, a transient variable is created to stand in for a missing
        /// variable.
        /// </summary>
        /// <param name="frame">
        /// The call frame in which to begin looking up the variable.
        /// </param>
        /// <param name="varName">
        /// The name of the variable to look up.
        /// </param>
        /// <param name="varIndex">
        /// The array element index, if any.  This parameter is not used.
        /// </param>
        /// <param name="traces">
        /// The optional list of traces to associate with a transient variable
        /// that is created for a missing variable.
        /// </param>
        /// <param name="variableFlags">
        /// On input, the flags used to control how the variable is looked up.
        /// On output, this parameter will be modified to reflect the status of
        /// the lookup.
        /// </param>
        /// <param name="variable">
        /// Upon success, this parameter will be modified to contain the variable
        /// that was found.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode GetVariable(
            ICallFrame frame,
            string varName,
            string varIndex, /* NOT USED */
            TraceList traces,
            ref VariableFlags variableFlags,
            ref IVariable variable,
            ref Result error
            ) /* USED BY CORE RESOLVER ONLY */
        {
            /* CheckDisposed(); */

            //
            // NOTE: Reset all status flags because we haven't checked
            //       anything yet.
            //
            variableFlags &= ~VariableFlags.ErrorMask;

            //
            // NOTE: Make sure the supplied variable name is valid.
            //
            if (varName == null)
            {
                error = "invalid variable name";
                return ReturnCode.Error;
            }

            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // NOTE: Get applicable call frame based on provided
                //       variable name and flags.
                //
                ICallFrame variableFrame = frame;

                if (GetVariableFrameViaResolvers(
                        LookupFlags.Default, ref variableFrame,
                        ref varName, ref variableFlags,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }

                if (variableFrame == null)
                {
                    error = "invalid call frame from resolver";
                    return ReturnCode.Error;
                }

                VariableDictionary variables = variableFrame.Variables;

                if (variables == null)
                {
                    error = "call frame does not support variables";
                    return ReturnCode.Error;
                }

                if (variables.Count == 0)
                {
                    //
                    // NOTE: The variable cannot exist in the call frame
                    //       (i.e. because there are no variables in the
                    //       call frame), set the "NotFound" flag.
                    //
                    variableFlags |= VariableFlags.NotFound;

                    error = "no variables in call frame";
                    return ReturnCode.Error;
                }

                //
                // NOTE: Try to get the variable in the desired call frame.
                //
                IVariable localVariable;

                if (variables.TryGetValue(varName, out localVariable))
                {
                    //
                    // NOTE: Ok, there was physically a variable within the
                    //       call frame.  Now, make sure it is defined -AND-
                    //       matches the other variable flags specified by
                    //       the caller, if any.
                    //
                    if (ScriptOps.CheckVariableStatus(
                            varName, localVariable, ref variableFlags,
                            ref error) == ReturnCode.Ok)
                    {
                        variable = localVariable;
                        return ReturnCode.Ok;
                    }
                }
                else if (FlagOps.HasFlags(
                        variableFlags, VariableFlags.CreateMissing, true))
                {
                    //
                    // HACK: The variable does not exist in the call frame;
                    //       however, since the "CreateMissing" flag is set,
                    //       pretend like it does.  It should be noted that
                    //       the variable is not actually added to the call
                    //       frame here.  Since this flag introduces a new,
                    //       unusual, and potentially disruptive behavior,
                    //       it should generally only be used for diagnostic
                    //       and testing purposes.
                    //
                    CreateMissingVariable(
                        variableFrame, varName, missingVariableValue,
                        traces, missingVariableDirty, ref variableFlags,
                        out localVariable);

                    variable = localVariable;
                    return ReturnCode.Ok;
                }
                else
                {
                    //
                    // NOTE: The variable does not exist in the call frame,
                    //       set the "NotFound" flag.
                    //
                    variableFlags |= VariableFlags.NotFound;

                    //
                    // HACK: This is on the "hot path" for WaitVariable on
                    //       variables that do not yet exist; therefore, do
                    //       not use String.Format here.
                    //
                    // BUGBUG: Just how slow is String.Format and why?
                    //
                    // error = String.Format(
                    //     "variable {0} not found in call frame {1}",
                    //     FormatOps.ErrorVariableName(varName),
                    //     FormatOps.WrapOrNull(variableFrame));
                    //
                    error = "variable not found in call frame";
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a variable with the specified name
        /// exists, for use within the core library, returning the variable that
        /// was found.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="name">
        /// The name of the variable to check for.
        /// </param>
        /// <param name="variable">
        /// Upon success, this parameter will be modified to contain the variable
        /// that was found.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok if the variable exists; otherwise, ReturnCode.Error.
        /// </returns>
        internal ReturnCode InternalDoesVariableExist(
            VariableFlags flags,
            string name,
            ref IVariable variable
            )
        {
            bool badRequest = false;
            Result error = null;

            return PrivateDoesVariableExist(
                flags, null, name, ref variable, ref badRequest, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a variable with the specified name
        /// exists in the specified call frame, also reporting whether the
        /// request itself was malformed.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="frame">
        /// The call frame in which to look up the variable.
        /// </param>
        /// <param name="name">
        /// The name of the variable to check for.
        /// </param>
        /// <param name="badRequest">
        /// Upon return, this parameter will be modified to indicate whether the
        /// request itself was malformed (as opposed to the variable simply not
        /// existing).
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok if the variable exists; otherwise, ReturnCode.Error.
        /// </returns>
        private ReturnCode PrivateDoesVariableExist(
            VariableFlags flags,
            ICallFrame frame,
            string name,
            ref bool badRequest,
            ref Result error
            )
        {
            IVariable variable = null;

            return PrivateDoesVariableExist(
                flags, frame, name, ref variable, ref badRequest, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a variable with the specified name
        /// exists in the specified call frame, returning the variable that was
        /// found and reporting whether the request itself was malformed.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="frame">
        /// The call frame in which to look up the variable.
        /// </param>
        /// <param name="name">
        /// The name of the variable to check for.
        /// </param>
        /// <param name="variable">
        /// Upon success, this parameter will be modified to contain the variable
        /// that was found.
        /// </param>
        /// <param name="badRequest">
        /// Upon return, this parameter will be modified to indicate whether the
        /// request itself was malformed (as opposed to the variable simply not
        /// existing).
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok if the variable exists; otherwise, ReturnCode.Error.
        /// </returns>
        private ReturnCode PrivateDoesVariableExist( /* SECONDARY */
            VariableFlags flags,
            ICallFrame frame,
            string name,
            ref IVariable variable,
            ref bool badRequest,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                flags |= existVariableFlags;

                string varName = null;
                string varIndex = null;

                if (ScriptOps.SplitVariableName(
                        this, flags, name, ref varName,
                        ref varIndex, ref error) == ReturnCode.Ok)
                {
                    IVariable localVariable = null;

                    flags |= VariableFlags.NoUsable;

                    if (GetVariableViaResolversWithSplit(
                            frame, varName, ref flags, ref localVariable,
                            ref error) == ReturnCode.Ok)
                    {
                        //
                        // BUGFIX: Null and undefined variables do not "exist".
                        //
                        if (localVariable == null)
                        {
                            error = String.Format(
                                "can't verify {0}: no such variable",
                                FormatOps.ErrorVariableName(
                                    localVariable, null, varName, varIndex));

                            return ReturnCode.Error;
                        }

                        //
                        // NOTE: If the variable physically exists but is not usable
                        //       from this thread, just return failure now, with the
                        //       bad request flag set.
                        //
                        if (!localVariable.IsUsable(ref error))
                        {
                            badRequest = true;
                            return ReturnCode.Error;
                        }

                        //
                        // NOTE: For linked variables, we may be linking to an array
                        //       element.
                        //
                        string linkIndex = null;

                        if (EntityOps.IsLink(localVariable))
                        {
                            //
                            // NOTE: Get the array element index of the link, if any.
                            //
                            linkIndex = localVariable.LinkIndex;

                            //
                            // NOTE: Follow the linked variable.
                            //
                            localVariable = EntityOps.FollowLinks(
                                localVariable, flags, ref error);

                            if (localVariable == null)
                                return ReturnCode.Error;

                            //
                            // NOTE: If the variable physically exists but is not usable
                            //       from this thread, just return failure now, with the
                            //       bad request flag set.
                            //
                            if (!localVariable.IsUsable(ref error))
                            {
                                badRequest = true;
                                return ReturnCode.Error;
                            }
                        }

                        //
                        // NOTE: If they specified the NoElement flag, then make sure
                        //       the linked variable does not refer to an array element.
                        //
                        if ((linkIndex == null) ||
                            !FlagOps.HasFlags(flags, VariableFlags.NoElement, true))
                        {
                            badRequest = false; // var name searched OK and found OK.

                            //
                            // BUGFIX: Null and undefined variables do not "exist".
                            //
                            if (!EntityOps.IsUndefined(localVariable))
                            {
                                //
                                // NOTE: Are they requesting an array, directly or
                                //       indirectly (i.e. indirectly if the specified
                                //       variable name or variable link contains an
                                //       element index and they did not specify the
                                //       NoElement flag)?
                                //
                                if (FlagOps.HasFlags(flags, VariableFlags.Array, true) ||
                                    (varIndex != null) || (linkIndex != null))
                                {
                                    //
                                    // NOTE: Is the variable an array?
                                    //
                                    if (EntityOps.IsArray2(localVariable) &&
                                        ((varIndex == null) || (linkIndex == null)))
                                    {
                                        if ((varIndex != null) || (linkIndex != null))
                                        {
                                            //
                                            // NOTE: If there was no element index specified,
                                            //       use the one from the variable link.
                                            //
                                            if (varIndex == null)
                                                varIndex = linkIndex;

                                            //
                                            // HACK: Handle the global "env" array specially.
                                            //       We must do this because our global "env"
                                            //       array has no backing storage (unlike Tcl's)
                                            //       and we do not have a trace operation for
                                            //       "exists".
                                            //
                                            ElementDictionary arrayValue = localVariable.ArrayValue;

                                            if ((IsEnvironmentVariable(localVariable) &&
                                                    CommonOps.Environment.DoesVariableExist(varIndex)) ||
                                                ((arrayValue != null) && arrayValue.ContainsKey(varIndex)))
                                            {
                                                variable = localVariable;
                                                return ReturnCode.Ok;
                                            }
                                            else if ((IsTestsVariable(localVariable) &&
                                                    PrivateDoesTestsVariableExist(varIndex)) ||
                                                ((arrayValue != null) && arrayValue.ContainsKey(varIndex)))
                                            {
                                                variable = localVariable;
                                                return ReturnCode.Ok;
                                            }
                                            else if ((IsSystemArrayVariable(localVariable) &&
                                                    MarshalOps.DoesArrayElementExist(
                                                        binder, InternalCultureInfo, localVariable,
                                                        varIndex)) ||
                                                ((arrayValue != null) && arrayValue.ContainsKey(varIndex)))
                                            {
                                                variable = localVariable;
                                                return ReturnCode.Ok;
                                            }
                                            else
                                            {
                                                ThreadVariable threadVariable = null;

                                                if ((IsThreadVariable(localVariable, ref threadVariable) &&
                                                        threadVariable.DoesExist(this, varIndex)) ||
                                                    ((arrayValue != null) && arrayValue.ContainsKey(varIndex)))
                                                {
                                                    variable = localVariable;
                                                    return ReturnCode.Ok;
                                                }
                                                else
                                                {
#if DATA
                                                    DatabaseVariable databaseVariable = null;

                                                    if ((IsDatabaseVariable(localVariable, ref databaseVariable) &&
                                                            databaseVariable.DoesExist(this, varIndex)) ||
                                                        ((arrayValue != null) && arrayValue.ContainsKey(varIndex)))
                                                    {
                                                        variable = localVariable;
                                                        return ReturnCode.Ok;
                                                    }
                                                    else
#endif
                                                    {
#if NETWORK && WEB
                                                        NetworkVariable networkVariable = null;

                                                        if ((IsNetworkVariable(localVariable, ref networkVariable) &&
                                                                networkVariable.DoesExist(this, varIndex)) ||
                                                            ((arrayValue != null) && arrayValue.ContainsKey(varIndex)))
                                                        {
                                                            variable = localVariable;
                                                            return ReturnCode.Ok;
                                                        }
                                                        else
#endif
                                                        {
#if !NET_STANDARD_20 && WINDOWS
                                                            RegistryVariable registryVariable = null;

                                                            if ((IsRegistryVariable(localVariable, ref registryVariable) &&
                                                                    registryVariable.DoesExist(this, varIndex)) ||
                                                                ((arrayValue != null) && arrayValue.ContainsKey(varIndex)))
                                                            {
                                                                variable = localVariable;
                                                                return ReturnCode.Ok;
                                                            }
                                                            else
#endif
                                                            {
                                                                error = String.Format(
                                                                    "can't verify {0}: no such element in array",
                                                                    FormatOps.ErrorVariableName(
                                                                        localVariable, linkIndex, varName, varIndex));
                                                            }
                                                        }
                                                    }
                                                }
                                            }
                                        }
                                        else
                                        {
                                            //
                                            // NOTE: The variable is an array and we did not want to
                                            //       validate any actual element.
                                            //
                                            variable = localVariable;
                                            return ReturnCode.Ok;
                                        }
                                    }
                                    else
                                    {
                                        error = String.Format(
                                            "can't verify {0}: variable isn't array",
                                            FormatOps.ErrorVariableName(
                                                localVariable, linkIndex, varName, varIndex));
                                    }
                                }
                                else if (FlagOps.HasFlags(flags, VariableFlags.NoArray, true))
                                {
                                    if (EntityOps.IsArray2(localVariable))
                                    {
                                        //
                                        // NOTE: They requested verification of a scalar variable
                                        //       and the variable is actually an array, this is
                                        //       an error.
                                        //
                                        error = String.Format(
                                            "can't verify {0}: variable is array",
                                            FormatOps.ErrorVariableName(
                                                localVariable, linkIndex, varName, varIndex));
                                    }
                                    else
                                    {
                                        //
                                        // HACK: *SPECIAL* Transparently per-thread scalar
                                        //       variables need special checking.
                                        //
                                        ThreadVariable threadVariable = null;

                                        if (IsThreadVariable(localVariable, ref threadVariable))
                                        {
                                            if (threadVariable.DoesExist(this))
                                            {
                                                variable = localVariable;
                                                return ReturnCode.Ok;
                                            }
                                            else
                                            {
                                                error = String.Format(
                                                    "can't verify {0}: no such variable",
                                                    FormatOps.ErrorVariableName(
                                                        localVariable, linkIndex, varName, varIndex));
                                            }
                                        }
                                        else
                                        {
                                            //
                                            // NOTE: They requested verification of a scalar variable
                                            //       and [correctly] did not supply an element index,
                                            //       everything is ok.
                                            //
                                            variable = localVariable;
                                            return ReturnCode.Ok;
                                        }
                                    }
                                }
                                else
                                {
                                    //
                                    // HACK: *SPECIAL* Transparently per-thread scalar
                                    //       variables need special checking.
                                    //
                                    ThreadVariable threadVariable = null;

                                    if (IsThreadVariable(localVariable, ref threadVariable))
                                    {
                                        if (threadVariable.DoesExist(this))
                                        {
                                            variable = localVariable;
                                            return ReturnCode.Ok;
                                        }
                                        else
                                        {
                                            error = String.Format(
                                                "can't verify {0}: no such variable",
                                                FormatOps.ErrorVariableName(
                                                    localVariable, linkIndex, varName, varIndex));
                                        }
                                    }
                                    else
                                    {
                                        //
                                        // NOTE: No special flags were set and they did not specify an
                                        //       element index.
                                        //
                                        variable = localVariable;
                                        return ReturnCode.Ok;
                                    }
                                }
                            }
                            else
                            {
                                error = String.Format(
                                    "can't verify {0}: no such variable",
                                    FormatOps.ErrorVariableName(
                                        localVariable, linkIndex, varName, varIndex));
                            }
                        }
                        else
                        {
                            //
                            // NOTE: Bad request, they wanted to validate that the
                            //       variable does not refer to an array element
                            //       and the linked variable does.  Indicate this
                            //       special condition to the caller.
                            //
                            badRequest = true; // var name NOT searched OK.

                            //
                            // NOTE: Provide an informative error message.
                            //
                            error = "name refers to an element in an array";
                        }
                    }
                    else
                    {
                        //
                        // NOTE: If we did not actually search for the variable
                        //       (due to the internal calls to parse the variable
                        //       name failing, etc), we do not want to pretend that
                        //       the variable was simply not found.
                        //
                        if (FlagOps.HasFlags(flags, VariableFlags.NotFound, true))
                            badRequest = false; // var name searched OK and NOT found.
                        else
                            badRequest = true; // var name NOT searched OK.
                    }
                }
                else
                {
                    //
                    // NOTE: Bad variable name could not be parsed.
                    //       Indicate this special condition to the
                    //       caller.
                    //
                    badRequest = true; // var name NOT searched OK.
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether post-processing of variable values is
        /// currently disabled for this interpreter.
        /// </summary>
        /// <returns>
        /// True if post-processing of variable values is disabled; otherwise,
        /// false.
        /// </returns>
        private bool HasNoPostProcess()
        {
            /* EXEMPT */
            return FlagOps.HasFlags(interpreterFlags,
                InterpreterFlags.NoPostProcess, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method post-processes the value of a variable prior to returning
        /// it, optionally performing substitution and/or script evaluation on the
        /// value as directed by the variable.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the value is converted prior to being
        /// returned.
        /// </param>
        /// <param name="name">
        /// The name of the variable being post-processed.
        /// </param>
        /// <param name="index">
        /// The array element index, if any.
        /// </param>
        /// <param name="variable">
        /// The variable whose value is being post-processed.
        /// </param>
        /// <param name="oldValue">
        /// The raw value of the variable to be post-processed.
        /// </param>
        /// <param name="value">
        /// Upon success, this parameter will be modified to contain the
        /// post-processed value.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        private ReturnCode PostProcessVariableValue(
            VariableFlags flags,
            string name,
            string index,
            IVariable variable,
            object oldValue,
            ref Result value,
            ref Result error
            )
        {
            //
            // NOTE: Do we need to post-process this variable value at all
            //       prior to returning it?
            //
            if (EntityOps.IsSubstituteOrEvaluate(variable))
            {
                Result result = null;

                //
                // NOTE: Do we need to post-process the variable value by
                //       processing substitutions contained within it?
                //
                if (EntityOps.IsSubstitute(variable))
                {
                    if (SubstituteString(
                            StringOps.GetStringFromObject(oldValue),
                            ref result) != ReturnCode.Ok)
                    {
                        error = result;
                        return ReturnCode.Error;
                    }

                    oldValue = result;
                }

                //
                // NOTE: Do we need to post-process the variable value by
                //       evaluating it as a script?
                //
                if (EntityOps.IsEvaluate(variable))
                {
                    if (EvaluateScript(
                            StringOps.GetStringFromObject(oldValue),
                            ref result) != ReturnCode.Ok) /* EXEMPT */
                    {
                        error = result;
                        return ReturnCode.Error;
                    }

                    oldValue = result;
                }
            }

            //
            // NOTE: If post-processing was skipped or we were
            //       successful, signal success and return.
            //
            if (!FlagOps.HasFlags(flags, VariableFlags.SkipToString, true))
            {
                value = StringOps.GetResultFromObject(oldValue);
            }
            else
            {
                value = Result.FromObject(
                    oldValue, false, false, FlagOps.HasFlags(
                    flags, VariableFlags.FallbackToString, true));
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Currently, for use by the [array] command and the
        //       FireArraySetTraces method only.
        //
        /// <summary>
        /// This method fires the traces associated with the specified variable,
        /// determining the old value automatically.
        /// </summary>
        /// <param name="breakpointType">
        /// The kind of variable operation that triggered the traces.
        /// </param>
        /// <param name="flags">
        /// The flags used to control how the traces are fired.
        /// </param>
        /// <param name="frame">
        /// The call frame that owns the variable.
        /// </param>
        /// <param name="varName">
        /// The name of the variable.
        /// </param>
        /// <param name="varIndex">
        /// The array element index, if any.
        /// </param>
        /// <param name="newValue">
        /// The new value being assigned to the variable, if any.
        /// </param>
        /// <param name="oldValues">
        /// The old array element values, if any.
        /// </param>
        /// <param name="newValues">
        /// The new array element values, if any.
        /// </param>
        /// <param name="variable">
        /// The variable whose traces are being fired.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the result
        /// of firing the traces; upon failure, it will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode FireTraces(
            BreakpointType breakpointType,
            VariableFlags flags,
            ICallFrame frame,
            string varName,
            string varIndex,
            object newValue,
            ElementDictionary oldValues,
            ElementDictionary newValues,
            IVariable variable,
            ref Result result
            )
        {
            if (!FlagOps.HasFlags(flags, VariableFlags.NonTrace, false) &&
                !HasPendingTraces() && EntityOps.HasTraces(variable) &&
                !EntityOps.IsNoTrace(variable))
            {
                object oldValue = EntityOps.GetOldValue(
                    flags, variable, varIndex,
                    ScriptOps.GetDefaultValue(breakpointType));

                ITraceInfo traceInfo = ScriptOps.NewTraceInfo(
                    this, null, breakpointType, frame, variable,
                    varName, varIndex, flags, oldValue, newValue,
                    oldValues, newValues, null, NeedNewTraceInfo(
                    flags), false, !EntityOps.IsNoPostProcess(
                    variable), ReturnCode.Ok);

                return ScriptOps.FireTraces(
                    variable, breakpointType, this, traceInfo,
                    ref result);
            }
            else
            {
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the FireCloneTraces method only.
        //
        /// <summary>
        /// This method fires the traces associated with the specified variable,
        /// using the specified old value.
        /// </summary>
        /// <param name="breakpointType">
        /// The kind of variable operation that triggered the traces.
        /// </param>
        /// <param name="flags">
        /// The flags used to control how the traces are fired.
        /// </param>
        /// <param name="frame">
        /// The call frame that owns the variable.
        /// </param>
        /// <param name="varName">
        /// The name of the variable.
        /// </param>
        /// <param name="varIndex">
        /// The array element index, if any.
        /// </param>
        /// <param name="oldValue">
        /// The old value of the variable, if any.
        /// </param>
        /// <param name="newValue">
        /// The new value being assigned to the variable, if any.
        /// </param>
        /// <param name="oldValues">
        /// The old array element values, if any.
        /// </param>
        /// <param name="newValues">
        /// The new array element values, if any.
        /// </param>
        /// <param name="variable">
        /// The variable whose traces are being fired.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the result
        /// of firing the traces; upon failure, it will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        private ReturnCode FireTraces(
            BreakpointType breakpointType,
            VariableFlags flags,
            ICallFrame frame,
            string varName,
            string varIndex,
            object oldValue,
            object newValue,
            ElementDictionary oldValues,
            ElementDictionary newValues,
            IVariable variable,
            ref Result result
            )
        {
            if (!FlagOps.HasFlags(flags, VariableFlags.NonTrace, false) &&
                !HasPendingTraces() && EntityOps.HasTraces(variable) &&
                !EntityOps.IsNoTrace(variable))
            {
                ITraceInfo traceInfo = ScriptOps.NewTraceInfo(
                    this, null, breakpointType, frame, variable,
                    varName, varIndex, flags, oldValue, newValue,
                    oldValues, newValues, null, NeedNewTraceInfo(
                    flags), false, !EntityOps.IsNoPostProcess(
                    variable), ReturnCode.Ok);

                return ScriptOps.FireTraces(
                    variable, breakpointType, this, traceInfo,
                    ref result);
            }
            else
            {
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the IVariable.CopyValueFrom and
        //          IVariable.Clone methods only.
        //
        /// <summary>
        /// This method fires the traces associated with the specified variable
        /// when its value is being cloned or copied, merging the old and new
        /// array element values before firing.
        /// </summary>
        /// <param name="breakpointType">
        /// The kind of variable operation that triggered the traces.
        /// </param>
        /// <param name="flags">
        /// The flags used to control how the traces are fired.
        /// </param>
        /// <param name="frame">
        /// The call frame that owns the variable.
        /// </param>
        /// <param name="varName">
        /// The name of the variable.
        /// </param>
        /// <param name="varIndex">
        /// The array element index, if any.
        /// </param>
        /// <param name="oldValue">
        /// The old value of the variable, if any.
        /// </param>
        /// <param name="newValue">
        /// The new value being assigned to the variable, if any.
        /// </param>
        /// <param name="oldValues">
        /// The old array element values, if any.
        /// </param>
        /// <param name="newValues">
        /// The new array element values, if any.
        /// </param>
        /// <param name="variable">
        /// The variable whose traces are being fired.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter will be modified to contain the result
        /// of firing the traces; upon failure, it will contain an appropriate
        /// error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode FireCloneTraces(
            BreakpointType breakpointType,
            VariableFlags flags,
            ICallFrame frame,
            string varName,
            string varIndex,
            object oldValue,
            object newValue,
            ElementDictionary oldValues,
            ElementDictionary newValues,
            IVariable variable,
            ref Result result
            )
        {
            EventWaitHandle variableEvent;

            variableEvent = TryGetVariableEvent(ref result);

            if (variableEvent == null)
                return ReturnCode.Error;

            ElementDictionary effectiveNewValues = (oldValues != null) ?
                new ElementDictionary(variableEvent, oldValues) :
                new ElementDictionary(variableEvent);

            if (newValues != null)
            {
                foreach (_ObjectPair pair in newValues)
                    effectiveNewValues[pair.Key] = pair.Value;
            }

            return FireTraces(
                breakpointType, flags, frame, varName, varIndex,
                oldValue, newValue, oldValues, effectiveNewValues,
                variable, ref result);
        }

