        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode FireArraySetTraces( // NOTE: For use by [array] command only.
            BreakpointType breakpointType,
            VariableFlags flags,
            ICallFrame frame,
            string varName,
            string varIndex,
            object newValue,
            ElementDictionary oldValues,
            ElementDictionary newValues,
            IVariable variable,
            ref Result result
            )
        {
            EventWaitHandle variableEvent;

            variableEvent = TryGetVariableEvent(ref result);

            if (variableEvent == null)
                return ReturnCode.Error;

            ElementDictionary effectiveNewValues = (oldValues != null) ?
                new ElementDictionary(variableEvent, oldValues) :
                new ElementDictionary(variableEvent);

            if (newValues != null)
            {
                foreach (_ObjectPair pair in newValues)
                    effectiveNewValues[pair.Key] = pair.Value;
            }

            return FireTraces(
                breakpointType, flags, frame, varName, varIndex, newValue,
                oldValues, effectiveNewValues, variable, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the value of the specified variable as a wide
        /// integer, for use by the <c>incr</c> command.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="name">
        /// The name of the variable to query.
        /// </param>
        /// <param name="value">
        /// Upon success, this parameter will be modified to contain the integer
        /// value of the variable.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode GetIntegerVariableValue( /* NOTE: For [incr] use only. */
            VariableFlags flags,
            string name,
            ref long value,
            ref Result error
            )
        {
            ReturnCode code;
            Result result = null;

            code = GetVariableValue(
                flags | VariableFlags.SkipToString, name, ref result,
                ref error);

            if (code != ReturnCode.Ok)
                return code;

            if (result != null)
            {
                if (result.Value is int)
                {
                    value = (int)result.Value;
                    return ReturnCode.Ok;
                }

                if (result.Value is long)
                {
                    value = (long)result.Value;
                    return ReturnCode.Ok;
                }
            }

            code = Value.GetWideInteger2(
                (IGetValue)result, ValueFlags.AnyWideInteger,
                InternalCultureInfo, ref value, ref error);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the value of the specified variable to a wide
        /// integer, for use by the <c>incr</c> command.  The value is stored as a
        /// 32-bit integer when it fits.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is set.
        /// </param>
        /// <param name="name">
        /// The name of the variable to set.
        /// </param>
        /// <param name="value">
        /// The integer value to assign to the variable.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode SetIntegerVariableValue( /* NOTE: For [incr] use only. */
            VariableFlags flags,
            string name,
            long value,
            ref Result error
            )
        {
            int intValue = ConversionOps.ToInt(value);

            if (value == intValue)
            {
                IVariable variable = null;

                return SetVariableValue2(
                    flags, null, name, null, intValue, null, ref variable,
                    ref error);
            }
            else
            {
                IVariable variable = null;

                return SetVariableValue2(
                    flags, null, name, null, value, null, ref variable,
                    ref error);
            }
        }

