        /// <param name="readOnly">
        /// Non-zero if the returned list should be read-only.
        /// </param>
        /// <param name="value">
        /// Upon success, this parameter will be modified to contain the list
        /// value of the variable.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode GetListVariableValue( /* NOTE: For [lsearch] use only. */
            VariableFlags flags,
            string name,
            bool copy,
            bool errorOnNotFound,
            bool errorOnNotList,
            bool readOnly,
            ref StringList value
            )
        {
            IVariable variable = null;
            bool cached = false;
            Result error = null;

            return GetListVariableValue(
                flags, name, copy, errorOnNotFound, errorOnNotList,
                readOnly, ref variable, ref value, ref cached,
                ref error);
        }

