        internal ReturnCode GetListVariableValue( /* NOTE: For [lappend]/[lget]/[lset] use only. */
            VariableFlags flags,
            string name,
            bool copy,
            bool errorOnNotFound,
            bool errorOnNotList,
            bool readOnly,
            ref StringList value,
