        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the value of the specified variable as a list, also
        /// returning the variable that was found and whether the returned list
        /// is the one cached in the variable.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="name">
        /// The name of the variable to query.
        /// </param>
        /// <param name="copy">
        /// Non-zero if a copy of the list should be returned rather than the
        /// list stored in the variable.
        /// </param>
        /// <param name="errorOnNotFound">
        /// Non-zero if an error should be raised when the variable does not
        /// exist; otherwise, an empty list is returned.
        /// </param>
        /// <param name="errorOnNotList">
        /// Non-zero if an error should be raised when the variable value is not
        /// a valid list; otherwise, it is parsed as one.
        /// </param>
        /// <param name="readOnly">
        /// Non-zero if the returned list should be read-only.
        /// </param>
        /// <param name="variable">
        /// Upon success, this parameter will be modified to contain the variable
        /// that was found.
        /// </param>
        /// <param name="value">
        /// Upon success, this parameter will be modified to contain the list
        /// value of the variable.
        /// </param>
        /// <param name="cached">
        /// Upon return, this parameter will be modified to indicate whether the
        /// returned list is the list cached in the variable (as opposed to a
        /// freshly parsed one).
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        private ReturnCode GetListVariableValue(
            VariableFlags flags,
            string name,
            bool copy,
            bool errorOnNotFound,
            bool errorOnNotList,
            bool readOnly,
            ref IVariable variable,
            ref StringList value,
            ref bool cached,
            ref Result error
            )
        {
            ReturnCode code;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                flags |= VariableFlags.SkipToString;

                string varIndex = null;
                Result localValue = null;
                Result localError = null;

                code = GetVariableValue(
                    flags, name, ref varIndex, ref variable, ref localValue,
                    ref localError);

                if (code == ReturnCode.Ok)
                {
                    object oldValue = !EntityOps.IsVirtualOrSystem(variable) ?
                        EntityOps.GetOldValue(flags, variable, varIndex, null) :
                        StringOps.GetStringFromObject(localValue);

                    if (oldValue is StringList)
                    {
                        if (copy)
                            value = new StringList((StringList)oldValue);
                        else
                            value = (StringList)oldValue;

                        cached = true;
                    }
                    else if (!errorOnNotList)
                    {
                        if (oldValue != null)
                        {
                            code = ParserOps<string>.SplitList(
                                this, StringOps.GetStringFromObject(oldValue),
                                0, Length.Invalid, readOnly, ref value, ref error);

                            if (code == ReturnCode.Ok)
                                cached = false;
                        }
                        else
                        {
                            value = new StringList();
                            cached = false;
                        }
                    }
                    else
                    {
                        error = "variable value is not a list";
                        code = ReturnCode.Error;
                    }
                }
                else if (!errorOnNotFound)
                {
                    //
                    // NOTE: The variable does not exist (or the name is
                    //       invalid, etc).  Return an empty list and let
                    //       the caller deal with it.  For [lappend], if
                    //       the name is invalid, the subsequent call to
                    //       SetVariableValue will fail, that's alright.
                    //
                    value = new StringList();
                    cached = false;

                    code = ReturnCode.Ok;
                }
                else
                {
                    error = localError;
                }
            }

            return code;
        }

