        /// <summary>
        /// This method gets the value of the variable with the specified name,
        /// for use within the core library, discarding any error message.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="name">
        /// The name of the variable to query.
        /// </param>
        /// <param name="value">
        /// Upon success, this parameter will be modified to contain the value of
        /// the variable.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode GetVariableValue(
            VariableFlags flags,
            string name,
            ref Result value
            )
        {
            IVariable variable = null;
            Result error = null;

            return GetVariableValue2(
                flags, name, null, ref variable, ref value, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method splits the specified variable name into its name and
        /// array element index components and then gets the value of the
        /// variable, for use by the GetListVariableValue method.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up.
        /// </param>
        /// <param name="name">
        /// The name of the variable to query, possibly including an array
        /// element index.
        /// </param>
        /// <param name="varIndex">
        /// Upon return, this parameter will be modified to contain the array
        /// element index parsed from the variable name, if any.
        /// </param>
        /// <param name="variable">
        /// Upon success, this parameter will be modified to contain the variable
        /// that was found.
        /// </param>
        /// <param name="value">
        /// Upon success, this parameter will be modified to contain the value of
        /// the variable.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        private ReturnCode GetVariableValue( /* NOTE: For use by GetListVariableValue only. */
            VariableFlags flags,
            string name,
            ref string varIndex,
            ref IVariable variable,
            ref Result value,
            ref Result error
            )
        {
            string varName = null;

            if (ScriptOps.SplitVariableName(
                    this, flags, name, ref varName,
                    ref varIndex, ref error) == ReturnCode.Ok)
            {
                return GetVariableValue2(
                    flags, varName, varIndex, ref variable,
                    ref value, ref error);
            }

            return ReturnCode.Error;
        }

