        /// <summary>
        /// This method resets the variable with the specified name only if it
        /// already exists, treating a non-existent variable as success while
        /// still reporting an invalid name as a failure.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up and reset.
        /// </param>
        /// <param name="name">
        /// The name of the variable to reset.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal ReturnCode ResetExistingVariable(
            VariableFlags flags,
            string name,
            ref Result error
            )
        {
            bool badRequest = false;
            Result localError; /* REUSED */

            //
            // NOTE: Check if the variable exists; if
            //       not, do nothing.  If the name is
            //       invalid, return overall failure;
            //       otherwise, return total success.
            //
            localError = null;

            if (PrivateDoesVariableExist(
                    flags, null, name, ref badRequest,
                    ref localError) != ReturnCode.Ok)
            {
                //
                // NOTE: The variable does not exist;
                //       check if the name itself was
                //       bad.
                //
                if (badRequest)
                {
                    error = localError;
                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }

            //
            // NOTE: The variable already exists; try
            //       to reset its value now.  Failing
            //       that, return an overall failure.
            //
            localError = null;

            if (ResetVariable(flags, name,
                    ref localError) != ReturnCode.Ok)
            {
                error = localError;
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

