        /// <summary>
        /// This method configures the specified variable so that its elements
        /// are backed by the specified system array, looking it up in the
        /// specified call frame.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control how the variable is looked up and
        /// configured.
        /// </param>
        /// <param name="frame">
        /// The call frame in which to look up the variable.
        /// </param>
        /// <param name="name">
        /// The name of the variable to configure.
        /// </param>
        /// <param name="array">
        /// The system array used to back the variable.
        /// </param>
        /// <param name="variable">
        /// Upon success, this parameter will be modified to contain the variable
        /// that was configured.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        private ReturnCode SetVariableSystemArray2(
            VariableFlags flags,
            ICallFrame frame,
            string name,
            Array array,
            ref IVariable variable,
            ref Result error
            )
        {
            // CheckDisposed();

            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // HACK: Make use of the configured "extra" variable flags
                //       for this operation.
                //
                flags |= systemArrayVariableFlags;

                //
                // NOTE: This code assumes the systemArrayTraceList field
                //       cannot be null.
                //
                TraceList traces = systemArrayTraceList;

                if (GetVariableViaResolversWithSplit(
                        frame, name, null, ref flags,
                        ref variable, ref error) == ReturnCode.Ok)
                {
                    if ((traces != null) &&
                        (variable.AddTraces(traces) == traces.Count) &&
                        HasSystemArrayTraceCallback(variable))
                    {
                        variable.SetupValue(array, false, true, true, true);
                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = String.Format(
                            "can't link {0}: could not set variable array",
                            FormatOps.ErrorVariableName(
                                variable, null, name, null));
                    }

                    return ReturnCode.Error;
                }
                else
                {
                    if (SetVariableValue2(
                            flags, frame, name, null, array, traces,
                            ref variable, ref error) == ReturnCode.Ok)
                    {
                        if (HasSystemArrayTraceCallback(variable))
                        {
                            variable.SetupValue(null, false, true, true, true);
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            error = String.Format(
                                "can't link {0}: could not set variable array",
                                FormatOps.ErrorVariableName(
                                    variable, null, name, null));
                        }
                    }

                    return ReturnCode.Error;
                }
            }
        }

