        /// <param name="thread">
        /// The thread to associate with status reporting.
        /// </param>
        /// <returns>
        /// True if the status thread was set; otherwise, false.
        /// </returns>
        internal bool MaybeSetStatusThread(
            Thread thread
            )
        {
            return Object.ReferenceEquals(Interlocked.CompareExchange(
                ref statusThread, thread, null), null);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to clear the thread associated with status
        /// reporting, but only if it is currently the specified thread.
        /// </summary>
        /// <param name="thread">
        /// The thread expected to be currently associated with status
        /// reporting.
        /// </param>
        /// <param name="ignoreNull">
        /// Non-zero to return success when there was no status thread set.
        /// </param>
        /// <returns>
        /// True if the status thread was cleared (or was already unset and
        /// <paramref name="ignoreNull" /> is non-zero); otherwise, false.
        /// </returns>
        internal bool MaybeResetStatusThread(
            Thread thread,
            bool ignoreNull
            )
        {
            Thread oldThread = Interlocked.CompareExchange(
                ref statusThread, null, thread);

            if (oldThread == null)
            {
                TraceOps.DebugTrace(
                    "MaybeResetStatusThread: old thread was already null",
                    typeof(Interpreter).Name, TracePriority.StatusError);

                return ignoreNull;
            }

            return Object.ReferenceEquals(oldThread, thread);
        }

