        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method invokes the configured status callback, if any, to
        /// report a status update.
        /// </summary>
        /// <param name="clientData">
        /// The client data to pass to the status callback.
        /// </param>
        /// <param name="text">
        /// The status text to pass to the status callback.
        /// </param>
        /// <param name="clear">
        /// Non-zero if the status callback should clear any previously
        /// reported status.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message or exception.
        /// </param>
        /// <returns>
        /// True if the callback was invoked and returned ReturnCode.Return;
        /// otherwise, false.
        /// </returns>
        private bool MaybeInvokeStatusCallback(
            IClientData clientData,
            string text,
            bool clear,
            ref Result error
            )
        {
            StatusCallback callback = Interlocked.CompareExchange(
                ref statusCallback, null, null);

            if (callback != null)
            {
                try
                {
                    ReturnCode code = callback(
                        this, clientData, text, clear,
                        ref error); /* throw */

                    if (code == ReturnCode.Return)
                        return true;
                }
                catch (Exception e)
                {
                    error = e;
                }
            }

            return false;
        }

