                                _Constants.Prompt.ViaEnvironment),
                                console, verbose);
#endif

                            loop = false;
                        }
                        #endregion

                        ///////////////////////////////////////////////////////////////////////////////

                        #region Engine Settings
                        //
                        // NOTE: Check for the no-throw-on-disposed environment variable.
                        //       If it is set (to anything) then we will not throw exceptions
                        //       when a disposed object is accessed.
                        //
                        if (GlobalConfiguration.DoesValueExist(
                                EnvVars.NoThrowOnDisposed, GlobalConfiguration.GetFlags(
                                ConfigurationFlags.Interpreter, verbose))) /* GLOBAL */
                        {
#if CONSOLE
                            if (FlagOps.HasFlags(
                                    createFlags, CreateFlags.ThrowOnDisposed, true))
                            {
                                ConsoleOps.MaybeWritePrompt(
                                    _Constants.Prompt.NoThrowOnDisposed,
                                    console, verbose);
                            }
#endif

                            Engine.SetThrowOnDisposed(null, false, false); /* GLOBAL */
                        }
                        #endregion
                    }

                    TraceOps.DebugTrace(String.Format(
                        "ProcessStartupOptions: exited, interpreter = {0}, argv = {1}, " +
                        "createFlags = {2}, originFlags = {3}, console = {4}, " +
                        "verbose = {5}, initialize = {6}, loop = {7}, error = {8}",
                        FormatOps.InterpreterNoThrow(interpreter),
                        FormatOps.WrapOrNull(true, true, argv), FormatOps.WrapOrNull(createFlags),
                        FormatOps.WrapOrNull(originFlags), console, verbose, initialize, loop,
                        FormatOps.WrapOrNull(true, true, error)),
                        typeof(Interpreter).Name, TracePriority.StartupDebug);

                    return ReturnCode.Ok;
                }
                else
                {
                    error = "invalid interpreter";
                }
            }
            catch (Exception e)
            {
                error = e;
            }

#if CONSOLE
            ConsoleOps.MaybeWriteError(
                ResultOps.Format(ReturnCode.Error, error),
                console);
#endif

            TraceOps.DebugTrace(String.Format(
                "ProcessStartupOptions: exited, interpreter = {0}, argv = {1}, " +
                "createFlags = {2}, originFlags = {3}, console = {4}, " +
                "verbose = {5}, initialize = {6}, loop = {7}, error = {8}",
                FormatOps.InterpreterNoThrow(interpreter),
                FormatOps.WrapOrNull(true, true, argv), FormatOps.WrapOrNull(createFlags),
                FormatOps.WrapOrNull(originFlags), console, verbose, initialize, loop,
                FormatOps.WrapOrNull(true, true, error)),
                typeof(Interpreter).Name, TracePriority.StartupError);

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Profiler Support
        /// <summary>
        /// Gets the profiler state associated with this interpreter, or null if
        /// profiling is not enabled or the interpreter could not be locked.
        /// </summary>
        internal IProfilerState Profiler
        {
            get
            {
                bool locked = false;

                try
                {
                    InternalSoftTryLock(ref locked);

                    if (locked)
                        return GetProfiler();
                }
                finally
                {
                    InternalExitLock(ref locked);
                }

                return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter currently has a
        /// profiler.
        /// </summary>
        /// <returns>
        /// True if a profiler is present; otherwise, false.
        /// </returns>
        private bool HaveProfiler()
        {
            return (profiler != null); /* NO-LOCK */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to mark the existing profiler for reuse and
        /// return it.
        /// </summary>
        /// <param name="profiler">
        /// Upon success, this parameter will be modified to contain the
        /// profiler that may be reused; otherwise, it will be set to null.
        /// </param>
        /// <returns>
        /// True if the profiler was marked for reuse and returned; otherwise,
        /// false.
        /// </returns>
        internal bool TryReuseProfiler(
            out IProfilerState profiler
            )
        {
            profiler = null;

            bool locked = false;

            try
            {
                InternalSoftTryLock(ref locked);

                if (locked && SetStateFlags(
                        InterpreterStateFlags.ReUseProfiler, null))
                {
                    profiler = GetProfiler();
                    return true;
                }
            }
            finally
            {
                InternalExitLock(ref locked);
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the profiler state associated with this
        /// interpreter, without acquiring any lock.
        /// </summary>
        /// <returns>
        /// The profiler state, or null if profiling is not enabled.
        /// </returns>
        private IProfilerState GetProfiler()
        {
            return profiler; /* NO-LOCK */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the profiler state associated with this
        /// interpreter, without acquiring any lock.
        /// </summary>
        /// <param name="profiler">
        /// The profiler state to associate with this interpreter, or null to
        /// remove any existing profiler.
        /// </param>
        private void SetProfiler(
            IProfilerState profiler /* in */
            )
        {
            this.profiler = profiler; /* NO-LOCK */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new profiler state for this interpreter,
        /// seeding its totals from the specified profiler, without acquiring
        /// any lock.
        /// </summary>
        /// <param name="profiler">
        /// The profiler state whose totals should be used to seed the new
        /// profiler, or null if there is none.
        /// </param>
        private void CreateProfiler(
            IProfilerState profiler /* in */
            )
        {
            this.profiler = ProfilerState.CreateWithTotalsFrom(
                profiler); /* NO-LOCK */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables or disables profiling for this interpreter.
        /// </summary>
        /// <param name="enable">
        /// Non-zero to enable profiling, or zero to disable it.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message, such as when profiling is already in the
        /// requested state.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        private ReturnCode EnableProfiler(
            bool enable,                 /* in */
            ref Result error             /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (enable)
                {
                    if (!HaveProfiler())
                    {
                        CreateProfiler(null);
                    }
                    else
                    {
                        error = "profiler already enabled";
                        return ReturnCode.Error;
                    }
                }
                else if (HaveProfiler())
                {
                    DisposeProfiler();
                }
                else
                {
                    error = "profiler already disabled";
                    return ReturnCode.Error;
                }

                return ReturnCode.Ok;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Static "Factory" Methods
        #region Private Static "Factory" Helper Methods
        /// <summary>
        /// This method determines whether the creation of this interpreter is
        /// still in progress.
        /// </summary>
        /// <returns>
        /// True if creation is pending; otherwise, false.
        /// </returns>
        private bool IsCreationPending()
        {
            return Interlocked.CompareExchange(
                ref creationPending, 0, 0) > 0;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the creation of this interpreter as being in
        /// progress.
        /// </summary>
        /// <param name="pending">
        /// Upon return, this parameter will be set to non-zero to indicate that
        /// creation is now pending.
        /// </param>
        private void BeginCreationPending(
            out bool pending /* out */
            )
        {
            /* IGNORED */
            Interlocked.Increment(ref creationPending);

            pending = true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the creation of this interpreter as no longer
        /// being in progress, if it was previously marked as pending.
        /// </summary>
        /// <param name="pending">
        /// On input, non-zero if creation is currently pending.  Upon return,
        /// this parameter will be set to zero.
        /// </param>
        private void EndCreationPending(
            ref bool pending /* in, out */
            )
        {
            if (pending)
            {
                /* IGNORED */
                Interlocked.Decrement(ref creationPending);

                pending = false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the current count of pending requests to disable
        /// interpreter creation.
        /// </summary>
        /// <returns>
        /// The number of outstanding requests to disable interpreter creation.
        /// </returns>
        internal static int GetDisableCreationCount()
        {
            return Interlocked.CompareExchange(
                ref globalDisableCreationCount, 0, 0);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether interpreter creation is currently
        /// disabled, consulting global state.
        /// </summary>
        /// <param name="persistentOnly">
        /// Non-zero to consider only persistent (as opposed to transient)
        /// disable requests.
        /// </param>
        /// <param name="hasToken">
        /// Non-zero if the interpreter being created is associated with a
        /// licensing token, which may relax the transient disable check.
        /// </param>
        /// <param name="error">
        /// If creation is disabled, this parameter will be modified to contain
        /// an appropriate error message.
        /// </param>
        /// <returns>
        /// True if interpreter creation is disabled; otherwise, false.
        /// </returns>
        internal static bool IsCreationDisabled(
            bool persistentOnly, /* in */
            bool hasToken,       /* in */
            ref Result error     /* out */
            )
        {
            return IsCreationDisabled(
                true, persistentOnly, hasToken, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the primary Interpreter.Create method only.
        //
        /// <summary>
        /// This method determines whether interpreter creation is currently
        /// disabled, optionally consulting global state.  This overload is
        /// intended for use by the primary interpreter creation method only.
        /// </summary>
        /// <param name="useGlobalState">
        /// Non-zero to consult global state when checking for persistent
        /// disable requests.
        /// </param>
        /// <param name="persistentOnly">
        /// Non-zero to consider only persistent (as opposed to transient)
        /// disable requests.
        /// </param>
        /// <param name="hasToken">
        /// Non-zero if the interpreter being created is associated with a
        /// licensing token, which may relax the transient disable check.
        /// </param>
        /// <param name="error">
        /// If creation is disabled, this parameter will be modified to contain
        /// an appropriate error message.
        /// </param>
        /// <returns>
        /// True if interpreter creation is disabled; otherwise, false.
        /// </returns>
        private static bool IsCreationDisabled(
            bool useGlobalState, /* in */
            bool persistentOnly, /* in */
            bool hasToken,       /* in */
            ref Result error     /* out */
            )
        {
            #region Check Transient Status
            if (!persistentOnly && Interlocked.CompareExchange(
                    ref globalDisableCreationCount, 0, 0) > 0)
            {
                //
                // HACK: When creating token-based interpreters (e.g. via
                //       the Harpy Licensing SDK, allow this check to be
                //       skipped if the associated environment variable
                //       is set.
                //
                if (hasToken && GlobalConfiguration.DoesValueExist(
                        EnvVars.CreateFailSafe, ConfigurationFlags.Interpreter))
                {
                    TraceOps.DebugTrace(String.Format(
                        "IsCreationDisabled: {0}", CreationTemporarilyDisabledError),
                        typeof(Interpreter).Name, TracePriority.SecurityWarning);
                }
                else
                {
                    error = CreationTemporarilyDisabledError;
                    return true;
                }
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Global State Usage
            if (!useGlobalState)
            {
                TraceOps.DebugTrace(
                    "IsCreationDisabled: use of global state is disabled",
                    typeof(Interpreter).Name, TracePriority.SecurityDebug2);

                return false;
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Check Persistent Status
            #region Grab Interpreter Context
            Interpreter interpreter = GlobalState.GetStubInterpreter();

            if (interpreter == null)
            {
                //
                // HACK: If there is no stub interpreter, it most likely
                //       means something is seriously wrong, e.g. if the
                //       stub assembly is loaded, it was probably due to
                //       an implicit reference, which is not supported,
                //       and we should just allow creation.
                //
                TraceOps.DebugTrace(
                    "IsCreationDisabled: stub interpreter unavailable",
                    typeof(Interpreter).Name, TracePriority.SecurityWarning2);

                return false;
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Check AppDomain Status
            ArgumentList arguments = new ArgumentList();

            arguments.Add("stub");     /* NOTE: Stub command name. */
            arguments.Add("creation"); /* NOTE: Stub sub-command name. */

            bool allowCreation;

            if (GlobalState.IsStubAssemblyInAppDomain(
                    interpreter, null, arguments, null, false,
                    out allowCreation) == ReturnCode.Ok)
            {
                error = "interpreter creation is persistently disabled (1)";
                return true;
            }
            else if (allowCreation)
            {
                return false;
            }
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Check Process Status
            if (GlobalState.IsStubAssemblyInProcess(interpreter, null))
            {
                error = "interpreter creation is persistently disabled (2)";
                return true;
            }
            #endregion
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks whether interpreter creation is persistently
        /// disabled and, if so, throws an exception unless suppressed by the
        /// specified flags.
        /// </summary>
        /// <param name="methodName">
        /// The name of the calling method, used for diagnostic purposes.
        /// </param>
        /// <param name="disableFlags">
        /// The flags used to control the behavior of this method, including
        /// whether the check may be skipped and whether failures are reported
        /// quietly.
        /// </param>
        private static void CheckPersistentCreationDisabled(
            string methodName,        /* in */
            DisableFlags disableFlags /* in */
            ) /* throw */
        {
            Result error = null;

            if (!FlagOps.HasFlags(
                    disableFlags, DisableFlags.AllowNop, true) &&
                IsCreationDisabled(true, false, ref error))
            {
                TraceOps.DebugTrace(String.Format(
                    "{0}: appDomain = {1}, error = {2}",
                    methodName, AppDomainOps.GetCurrentId(),
                    FormatOps.WrapOrNull(error)),
                    typeof(Interpreter).Name,
                    TracePriority.SecurityError);

                if (FlagOps.HasFlags(
                        disableFlags, DisableFlags.Quiet, true))
                {
                    return;
                }

                throw new ScriptException(ReturnCode.Error, error);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to load the stub assembly, if it has not
        /// already been loaded anywhere.
        /// </summary>
        /// <param name="clientData">
        /// The optional client data to associate with the load operation, or
        /// null if there is none.
        /// </param>
        /// <param name="disableFlags">
        /// This parameter is not used.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        private static ReturnCode MaybeTryToLoadStubAssembly(
            IClientData clientData,    /* in: OPTIONAL */
            DisableFlags disableFlags, /* in: NOT USED */
            ref Result error           /* out */
            )
        {
            if (GlobalState.IsStubAssemblyAnywhere())
                return ReturnCode.Ok;

            return GlobalState.TryToLoadStubAssembly(
                clientData, true, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to load the stub assembly and, if it cannot be
        /// loaded, throws an exception unless suppressed by the specified
        /// flags.
        /// </summary>
        /// <param name="clientData">
        /// The optional client data to associate with the load operation, or
        /// null if there is none.
        /// </param>
        /// <param name="disableFlags">
        /// The flags used to control the behavior of this method, including
        /// whether failures are reported quietly.
        /// </param>
        private static void MaybeTryToLoadStubAssemblyOrMaybeThrow(
            IClientData clientData,   /* in: OPTIONAL */
            DisableFlags disableFlags /* in */
            ) /* throw */
        {
            ReturnCode code;
            Result error = null;

            code = MaybeTryToLoadStubAssembly(
                clientData, disableFlags, ref error);

            if (code != ReturnCode.Ok)
            {
                TraceOps.DebugTrace(String.Format(
                    "MaybeTryToLoadStubAssemblyOrMaybeThrow: " +
                    "appDomain = {0}, code = {1}, error = {2}",
                    AppDomainOps.GetCurrentId(), code,
                    FormatOps.WrapOrNull(error)),
                    typeof(Interpreter).Name,
                    TracePriority.SecurityError);

                if (FlagOps.HasFlags(
                        disableFlags, DisableFlags.Quiet, true))
                {
                    return;
                }

                throw new ScriptException(code, error);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method re-enables interpreter creation by decrementing the
        /// outstanding disable count, after verifying that creation is not
        /// persistently disabled.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control the behavior of this method.
        /// </param>
        internal static void EnableCreation(
            DisableFlags flags /* in */
            ) /* throw */
        {
            CheckPersistentCreationDisabled("EnableCreation", flags);
            Interlocked.Decrement(ref globalDisableCreationCount);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method disables interpreter creation by incrementing the
        /// outstanding disable count, optionally making the change persistent
        /// via the stub assembly.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control the behavior of this method, including
        /// whether the disable should be persistent, whether the existence
        /// check is overridden, and whether failures are reported quietly.
        /// </param>
        internal static void DisableCreation(
            DisableFlags flags /* in */
            ) /* throw */
        {
            Result error; /* REUSED */

            if (!FlagOps.HasFlags(flags, DisableFlags.Override, true) &&
                (GlobalState.CountInterpreters(true) <= 0))
            {
                error = "cannot disable interpreter creation, " +
                    "none appear to exist";

                TraceOps.DebugTrace(String.Format(
                    "DisableCreation: appDomain = {0}, flags = {1}, " +
                    "error = {2}", AppDomainOps.GetCurrentId(), flags,
                    FormatOps.WrapOrNull(error)),
                    typeof(Interpreter).Name,
                    TracePriority.SecurityError);

                if (FlagOps.HasFlags(flags, DisableFlags.Quiet, true))
                    return;

                throw new ScriptException(ReturnCode.Error, error);
            }

            Interlocked.Increment(ref globalDisableCreationCount);

            if (FlagOps.HasFlags(flags, DisableFlags.Persistent, true))
            {
                if (Interlocked.CompareExchange(
                        ref globalStubAssemblyCount, 0, 0) > 0)
                {
                    MaybeTryToLoadStubAssemblyOrMaybeThrow(null, flags);
                }
                else
                {
                    error = "cannot persistently disable interpreter " +
                        "creation, stub assembly not enabled";

                    TraceOps.DebugTrace(String.Format(
                        "DisableCreation: appDomain = {0}, flags = {1}, " +
                        "error = {2}", AppDomainOps.GetCurrentId(), flags,
                        FormatOps.WrapOrNull(error)),
                        typeof(Interpreter).Name,
                        TracePriority.SecurityError);

                    if (FlagOps.HasFlags(flags, DisableFlags.Quiet, true))
                        return;

                    throw new ScriptException(ReturnCode.Error, error);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if ENTERPRISE_LOCKDOWN || MAYBE_ENTERPRISE_LOCKDOWN
        /// <summary>
        /// This method determines whether enterprise lockdown mode is enabled.
        /// When compiled with ENTERPRISE_LOCKDOWN, this mode is always enabled
        /// and cannot be changed programmatically; otherwise, it reflects
        /// whether the stub assembly is loaded.
        /// </summary>
        /// <returns>
        /// True if enterprise lockdown mode is enabled; otherwise, false.
        /// </returns>
        internal static bool IsEnterpriseLockdownEnabled()
        {
#if ENTERPRISE_LOCKDOWN
            //
            // HACK: When compiled with ENTERPRISE_LOCKDOWN,
            //       this mode is always enabled -AND- cannot
            //       be enabled or disabled programmatically.
            //
            return true;
#else
            return GlobalState.IsStubAssemblyAnywhere();
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables enterprise lockdown mode.  When compiled with
        /// ENTERPRISE_LOCKDOWN, this mode is always enabled and cannot be
        /// changed programmatically; otherwise, this method attempts to load
        /// the stub assembly.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter will be modified to contain an
        /// appropriate error message.
        /// </param>
        /// <returns>
        /// ReturnCode.Ok on success, ReturnCode.Error on failure.
        /// </returns>
        internal static ReturnCode EnableEnterpriseLockdown(
            ref Result error /* out */
            )
        {
#if ENTERPRISE_LOCKDOWN
            //
            // HACK: When compiled with ENTERPRISE_LOCKDOWN,
            //       this mode is always enabled -AND- cannot
            //       be enabled or disabled programmatically.
            //
            return ReturnCode.Ok;
#else
            return MaybeTryToLoadStubAssembly(
                null, DisableFlags.Default, ref error);
#endif
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method increments the count of outstanding requests to enable
        /// the stub assembly, after verifying that creation is not persistently
        /// disabled.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control the behavior of this method.
        /// </param>
        internal static void EnableStubAssembly(
            DisableFlags flags /* in */
            ) /* throw */
        {
            CheckPersistentCreationDisabled("EnableStubAssembly", flags);
            Interlocked.Increment(ref globalStubAssemblyCount);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method decrements the count of outstanding requests to enable
        /// the stub assembly, after verifying that creation is not persistently
        /// disabled.
        /// </summary>
        /// <param name="flags">
        /// The flags used to control the behavior of this method.
        /// </param>
        internal static void DisableStubAssembly(
            DisableFlags flags /* in */
            ) /* throw */
        {
            CheckPersistentCreationDisabled("DisableStubAssembly", flags);
            Interlocked.Decrement(ref globalStubAssemblyCount);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally adjusts the specified creation flags based
        /// on whether a licensing token is present.
        /// </summary>
        /// <param name="token">
        /// The licensing token associated with the interpreter being created,
        /// or null if there is none.
        /// </param>
        /// <param name="createFlags">
        /// The creation flags to adjust.  When a token is present, the flag
        /// indicating that creation should proceed only if necessary is added.
        /// </param>
        private static void MaybeMutateCreateFlags(
            ulong? token,               /* in */
            ref CreateFlags createFlags /* in, out */
            )
        {
            if (token != null)
                createFlags |= CreateFlags.IfNecessary;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method conditionally adjusts the specified initialization flags
        /// based on whether a licensing token is present.
        /// </summary>
        /// <param name="token">
        /// The licensing token associated with the interpreter being created,
        /// or null if there is none.
        /// </param>
        /// <param name="initializeFlags">
        /// The initialization flags to adjust.  When a token is present, the
        /// flag indicating a trusted remote context is removed.
        /// </param>
        private static void MaybeMutateInitializeFlags(
            ulong? token,                       /* in */
            ref InitializeFlags initializeFlags /* in, out */
            )
        {
            if (token != null)
                initializeFlags &= ~InitializeFlags.TrustedRemote;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private Static "Factory" Methods
        /// <summary>
        /// Creates a new interpreter for use by the native package integration
        /// layer.
        /// </summary>
        /// <param name="args">
        /// The startup (command-line style) arguments to make available to the
        /// new interpreter, or null for none.
        /// </param>
        /// <param name="createFlags">
        /// Flags controlling how the interpreter itself is created (for example,
        /// whether it is created "safe").
        /// </param>
        /// <param name="hostCreateFlags">
        /// Flags controlling how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// Flags controlling how the interpreter is initialized.
        /// </param>
        /// <param name="scriptFlags">
        /// The default script flags used by the engine within the new
        /// interpreter.
        /// </param>
        /// <param name="findFlags">
        /// The initial native Tcl find flags.
        /// </param>
        /// <param name="loadFlags">
        /// The initial native Tcl load flags.
        /// </param>
        /// <param name="text">
        /// The "pre-init" (post-setup) script to evaluate, if any.
        /// </param>
        /// <param name="libraryPath">
        /// The location of the script library (the "init" script), or null to use
        /// the default.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
