                hostCreateFlags, initializeFlags, scriptFlags,
                Defaults.InterpreterFlags,
                Defaults.InterpreterTestFlags,
                Defaults.PluginFlags,
#if NATIVE && TCL
                findFlags, loadFlags,
#endif
                null, null, null, null, null, null, null, null,
                null, null, text, libraryPath, null, ref result);
        }

