        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        internal static Interpreter Create( /* For ScriptThread use. */
            IEnumerable<string> args,
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            InitializeFlags initializeFlags,
            ScriptFlags scriptFlags,
            InterpreterFlags interpreterFlags,
            IHost host,
            ref Result result
            )
        {
            return Create(null, null,
                _ClientData.Empty, args, null, createFlags,
                hostCreateFlags, initializeFlags, scriptFlags,
                interpreterFlags, Defaults.InterpreterTestFlags,
                Defaults.PluginFlags,
#if NATIVE && TCL
                Defaults.FindFlags, Defaults.LoadFlags,
#endif
                null, host, null, null, null, null, null, null,
                null, null, null, null, null, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates a new interpreter for use by InterpreterHelper.Create and the
        /// [test2] command.
        /// </summary>
        /// <param name="ruleSet">
        /// The rule set used to determine which commands and other entities
        /// should be added to the new interpreter.
        /// </param>
        /// <param name="args">
        /// The startup (command-line style) arguments to make available to the
        /// new interpreter, or null for none.
        /// </param>
        /// <param name="createFlags">
        /// Flags controlling how the interpreter itself is created (for example,
        /// whether it is created "safe").
        /// </param>
        /// <param name="hostCreateFlags">
        /// Flags controlling how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// Flags controlling how the interpreter is initialized.
        /// </param>
        /// <param name="scriptFlags">
        /// The default script flags used by the engine within the new
        /// interpreter.
        /// </param>
        /// <param name="interpreterFlags">
        /// The initial interpreter configuration flags.
        /// </param>
        /// <param name="interpreterTestFlags">
        /// The initial interpreter test configuration flags.
        /// </param>
        /// <param name="pluginFlags">
        /// The initial plugin flags.
        /// </param>
        /// <param name="findFlags">
        /// The initial native Tcl find flags.
        /// </param>
        /// <param name="loadFlags">
        /// The initial native Tcl load flags.
        /// </param>
        /// <param name="text">
        /// The "pre-init" (post-setup) script to evaluate, if any.
        /// </param>
        /// <param name="libraryPath">
        /// The location of the script library (the "init" script), or null to use
        /// the default.
        /// </param>
        /// <param name="autoPathList">
        /// Extra directories to search for packages, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        internal static Interpreter Create( /* InterpreterHelper.Create and [test2] */
            IRuleSet ruleSet,
            IEnumerable<string> args,
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            InitializeFlags initializeFlags,
            ScriptFlags scriptFlags,
            InterpreterFlags interpreterFlags,
            InterpreterTestFlags interpreterTestFlags,
            PluginFlags pluginFlags,
#if NATIVE && TCL
            FindFlags findFlags,
            LoadFlags loadFlags,
#endif
            string text,
            string libraryPath,
            StringList autoPathList,
            ref Result result
            )
        {
            return Create(null, ruleSet,
                _ClientData.Empty, args, null, createFlags,
                hostCreateFlags, initializeFlags, scriptFlags,
                interpreterFlags, interpreterTestFlags,
                pluginFlags,
#if NATIVE && TCL
                findFlags, loadFlags,
#endif
                null, null, null, null, null, null, null, null,
                null, null, text, libraryPath, autoPathList,
                ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates a new interpreter for internal debugger use only.
        /// </summary>
        /// <param name="culture">
        /// The name of the culture to use when parsing within the new
        /// interpreter, or null to use the default.
        /// </param>
        /// <param name="createFlags">
        /// Flags controlling how the interpreter itself is created (for example,
        /// whether it is created "safe").
        /// </param>
        /// <param name="hostCreateFlags">
        /// Flags controlling how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// Flags controlling how the interpreter is initialized.
        /// </param>
        /// <param name="scriptFlags">
        /// The default script flags used by the engine within the new
        /// interpreter.
        /// </param>
        /// <param name="interpreterFlags">
        /// The initial interpreter configuration flags.
        /// </param>
        /// <param name="pluginFlags">
        /// The initial plugin flags.
        /// </param>
        /// <param name="appDomain">
        /// The application domain in which to create the interpreter, or null to
        /// use the current one.
        /// </param>
        /// <param name="host">
        /// The host to associate with the new interpreter, or null to use the
        /// default host.
        /// </param>
        /// <param name="libraryPath">
        /// The location of the script library (the "init" script), or null to use
        /// the default.
        /// </param>
        /// <param name="autoPathList">
        /// Extra directories to search for packages, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        internal static Interpreter Create( /* NOTE: INTERNAL DEBUGGER USE ONLY. */
            string culture,
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            InitializeFlags initializeFlags,
            ScriptFlags scriptFlags,
            InterpreterFlags interpreterFlags,
            PluginFlags pluginFlags,
            AppDomain appDomain,
            IHost host,
            string libraryPath,
            StringList autoPathList,
            ref Result result
            )
        {
            return Create(null, null,
                _ClientData.Empty, null, culture, createFlags,
                hostCreateFlags, initializeFlags, scriptFlags,
                interpreterFlags, Defaults.InterpreterTestFlags,
                pluginFlags,
#if NATIVE && TCL
                Defaults.FindFlags, Defaults.LoadFlags,
#endif
                appDomain, host, null, null, null, null, null,
                null, null, null, null, libraryPath, autoPathList,
                ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// The core interpreter creation method.  All other Create overloads
        /// ultimately delegate to this method, which performs the actual work of
        /// constructing, configuring, and initializing a new interpreter.  It is
        /// not intended to be called directly.
        /// </summary>
        /// <param name="token">
        /// An optional licensing/certificate token used by the Harpy security
        /// plugin; when non-null, it is also used for secure interpreter lookup.
        /// </param>
        /// <param name="ruleSet">
        /// The rule set used to determine which commands and other entities
        /// should be added to the new interpreter.
        /// </param>
        /// <param name="clientData">
        /// Optional caller-supplied data passed along to the new interpreter and
        /// its creation callbacks.
        /// </param>
        /// <param name="args">
        /// The startup (command-line style) arguments to make available to the
        /// new interpreter, or null for none.
        /// </param>
        /// <param name="culture">
        /// The name of the culture to use when parsing within the new
        /// interpreter, or null to use the default.
        /// </param>
        /// <param name="createFlags">
        /// Flags controlling how the interpreter itself is created (for example,
        /// whether it is created "safe").
        /// </param>
        /// <param name="hostCreateFlags">
        /// Flags controlling how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// Flags controlling how the interpreter is initialized.
        /// </param>
        /// <param name="scriptFlags">
        /// The default script flags used by the engine within the new
        /// interpreter.
        /// </param>
        /// <param name="interpreterFlags">
        /// The initial interpreter configuration flags.
        /// </param>
        /// <param name="interpreterTestFlags">
        /// The initial interpreter test configuration flags.
        /// </param>
        /// <param name="pluginFlags">
        /// The initial plugin flags.
        /// </param>
        /// <param name="findFlags">
        /// The initial native Tcl find flags.
        /// </param>
        /// <param name="loadFlags">
        /// The initial native Tcl load flags.
        /// </param>
        /// <param name="appDomain">
        /// The application domain in which to create the interpreter, or null to
        /// use the current one.
        /// </param>
        /// <param name="host">
        /// The host to associate with the new interpreter, or null to use the
        /// default host.
        /// </param>
        /// <param name="profile">
        /// The name of the host profile to load, or null for none.
        /// </param>
        /// <param name="owner">
        /// The logical owner of the new interpreter, if any.
        /// </param>
        /// <param name="applicationObject">
        /// An object reserved for use by the application, or null if not needed.
        /// </param>
        /// <param name="policyObject">
        /// An object reserved for use by custom policies, or null if not needed.
        /// </param>
        /// <param name="resolverObject">
        /// An object reserved for use by custom resolvers, or null if not needed.
        /// </param>
        /// <param name="userObject">
        /// An object reserved for use by the user, or null if not needed.
        /// </param>
        /// <param name="policies">
        /// The interpreter policies (for example, those used to make it "safe"),
        /// if any.
        /// </param>
        /// <param name="traces">
        /// The interpreter-wide variable traces to add, if any.
        /// </param>
        /// <param name="text">
        /// The "pre-init" (post-setup) script to evaluate, if any.
        /// </param>
        /// <param name="libraryPath">
        /// The location of the script library (the "init" script), or null to use
        /// the default.
        /// </param>
        /// <param name="autoPathList">
        /// Extra directories to search for packages, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        private static Interpreter Create( /* CORE */
            ulong? token,                              // 01: secure lookup token for IfNecessary interpreter lookup.
            IRuleSet ruleSet,                          // 02: the ruleset used to determine which commands should be added.
            IClientData clientData,                    // 03: the client data to pass to the new interpreter callback.
            IEnumerable<string> args,                  // 04: original arguments to the host application, where applicable.
            string culture,                            // 05: currently, used only for parsing (error messages are same).
            CreateFlags createFlags,                   // 06: special creation flags.
            HostCreateFlags hostCreateFlags,           // 07: special host creation flags.
            InitializeFlags initializeFlags,           // 08: special initialization flags.
            ScriptFlags scriptFlags,                   // 09: the default script flags used by the engine.
            InterpreterFlags interpreterFlags,         // 10: the initial interpreter configuration flags.
            InterpreterTestFlags interpreterTestFlags, // 11: the initial interpreter configuration flags.
            PluginFlags pluginFlags,                   // 12: the initial plugin flags.
#if NATIVE && TCL
            FindFlags findFlags,                       // 13: the initial native Tcl find flags.
            LoadFlags loadFlags,                       // 14: the initial native Tcl load flags.
#endif
            AppDomain appDomain,                       // 15: pass null to use the current application domain.
            IHost host,                                // 16: pass null to use the default host.
            string profile,                            // 17: the host profile to load (pass null for none).
            object owner,                              // 18: the logical "owner" of the new interpreter.
            object applicationObject,                  // 19: this is reserved for use by the application (pass null if not needed).
            object policyObject,                       // 20: this is reserved for use by custom policies (pass null if not needed).
            object resolverObject,                     // 21: this is reserved for use by custom resolvers (pass null if not needed).
            object userObject,                         // 22: this is reserved for use by the user (pass null if not needed).
            PolicyList policies,                       // 23: interpreter policies (e.g. "safe", etc), if any.
            TraceList traces,                          // 24: interpreter wide variable traces, if any.
            string text,                               // 25: the "pre-init" (actually "post-setup") script, if any.
            string libraryPath,                        // 26: location of the script library (i.e. "init" script).
            StringList autoPathList,                   // 27: extra dirs to check for packages.
            ref Result result                          // 28: result of script library initialization or error upon failure.
            )
        {
            MaybeStaticInitialize();

#if ENTERPRISE_LOCKDOWN || MAYBE_ENTERPRISE_LOCKDOWN
            if (!IsEnterpriseLockdownEnabled())
            {
#if ENTERPRISE_LOCKDOWN
                if (GlobalState.TryToCacheStubAssembly(
                        ref result) != ReturnCode.Ok)
                {
                    return null;
                }
#else
                GlobalState.TryToCacheStubAssemblyOrTrace();
#endif
            }
#endif

            //
            // NOTE: Set the console and verbose (output control flags) to
            //       their initial values based on the host creation flags
            //       (which may change just below).  These values will be
            //       refreshed again if necessary.
            //
            bool console;
            bool verbose;

            RefreshConsoleAndVerbose(
                hostCreateFlags, out console, out verbose);

            //
            // HACK: *SECURITY* The creation flags are security sensitive;
            //       however, they will only be modified when the caller
            //       opts-in via the "GetFlags" meta-creation flag.
            //
            if (FlagOps.HasFlags(createFlags, CreateFlags.GetFlags, true))
            {
                createFlags = GetStartupCreateFlags(
                    args, createFlags, OptionOriginFlags.Create,
                    console, verbose);

                hostCreateFlags = Interpreter.GetStartupHostCreateFlags(
                    args, hostCreateFlags, OptionOriginFlags.Create,
                    console, verbose);

                RefreshConsoleAndVerbose(
                    hostCreateFlags, out console, out verbose);
            }

            DateTime now = TimeOps.GetUtcNow();
            Interpreter interpreter = null;
            bool locked = false;
            IProfilerState profiler = null;

            try
            {
                if (FlagOps.HasFlags(
                        createFlags, CreateFlags.MeasureTime, true))
                {
                    profiler = ProfilerState.Create();
                }

                if (profiler != null)
                    profiler.Start();

                if (ruleSet != null)
                    ruleSet.MakeReadOnly();

                ReturnCode code;
                StringList argv = (args != null) ? new StringList(args) : null;

                ///////////////////////////////////////////////////////////
                //
                // HACK: Grab either the default data flags or those from
                //       the environment, which can be used to figure out
                //       "missing script file" issues, etc.
                //
                DataFlags dataFlags = HostOps.GetDataFlags(
                    culture, false, createFlags, verbose);

                ///////////////////////////////////////////////////////////

                TraceOps.DebugTrace(String.Format(
                    "Create ({0})", AppDomainOps.GetCurrentId()),
                    null, typeof(Interpreter).Name, TracePriority.StartupDebug,
                    false, "token", FormatOps.WrapOrNull(token != null),
                    "ruleSet", FormatOps.WrapOrNull(ruleSet),
                    "clientData", FormatOps.WrapOrNull(clientData),
                    "argv", FormatOps.WrapOrNull(true, true, argv),
                    "culture", FormatOps.WrapOrNull(culture),
                    "createFlags", FormatOps.WrapOrNull(createFlags),
                    "hostCreateFlags", FormatOps.WrapOrNull(hostCreateFlags),
                    "initializeFlags", FormatOps.WrapOrNull(initializeFlags),
                    "dataFlags", FormatOps.WrapOrNull(dataFlags),
                    "scriptFlags", FormatOps.WrapOrNull(scriptFlags),
                    "interpreterFlags", FormatOps.WrapOrNull(interpreterFlags),
                    "interpreterTestFlags", FormatOps.WrapOrNull(interpreterTestFlags),
                    "pluginFlags", FormatOps.WrapOrNull(pluginFlags),
#if NATIVE && TCL
                    "findFlags", FormatOps.WrapOrNull(findFlags),
                    "loadFlags", FormatOps.WrapOrNull(loadFlags),
#endif
                    "appDomain", FormatOps.DisplayAppDomain(appDomain),
                    "host", FormatOps.WrapOrNull(host),
                    "profile", FormatOps.WrapOrNull(profile),
                    "owner", FormatOps.WrapOrNull(owner),
                    "applicationObject", FormatOps.WrapOrNull(applicationObject),
                    "policyObject", FormatOps.WrapOrNull(policyObject),
                    "resolverObject", FormatOps.WrapOrNull(resolverObject),
                    "userObject", FormatOps.WrapOrNull(userObject),
                    "policies", FormatOps.WrapOrNull(policies),
                    "traces", FormatOps.WrapOrNull(traces),
                    "text", FormatOps.WrapOrNull(text),
                    "libraryPath", FormatOps.WrapOrNull(libraryPath),
                    "autoPathList", FormatOps.WrapOrNull(true, true, autoPathList),
                    "now", FormatOps.WrapOrNull(FormatOps.Iso8601FullDateTime(now)),
                    "console", console, "verbose", verbose,
                    "result", FormatOps.WrapOrNull(true, true, result));

                //
                // NOTE: Pause for them to attach a debugger, if requested.  For
                //       embedders, we really need the ability to break into the
                //       debugger here; otherwise, being able to easily attach a
                //       debugger at a predictable point becomes a problem.
                //
                if (FlagOps.HasFlags(
                        createFlags, CreateFlags.BreakOnCreate, true) ||
                    ((GlobalConfiguration.DoesValueExist(
                        EnvVars.Break, ConfigurationFlags.Interpreter)) &&
                     (Interlocked.Increment(ref globalBreakCount) == 1)))
                {
                    #region Requires Console Support
#if CONSOLE
                    /* NO RESULT */
                    ConsoleOps.DebugBreak();
#endif
                    #endregion

                    ///////////////////////////////////////////////////////////

                    DebugOps.Break(); /* throw */
                }

                ///////////////////////////////////////////////////////////////

                //
                // NOTE: When this is set (to non-zero), a failure to add
                //       an interpreter to the GlobalState state will NOT
                //       be treated as a failure of this method.  This is
                //       only done when the IfCannotLock creation flag is
                //       set -AND- we are unable to check for an existing
                //       interpreter within the GlobalState state.
                //
                bool ifCannotLock = FlagOps.HasFlags(
                    createFlags, CreateFlags.IfCannotLock, true);

                bool couldNotLock = false;

                ///////////////////////////////////////////////////////////////

                EventCallback useInterpreterCallback = UseInterpreterCallback;
                EventCallback newInterpreterCallback = NewInterpreterCallback;

                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        createFlags, CreateFlags.IfNecessary, true))
                {
                    int getRetries = 0;

                getRetry:

                    //
                    // NOTE: Is there already at least one matching
                    //       interpreter created in this AppDomain?
                    //
                    bool getNotLocked = false;
                    bool getNotFound = false;
                    Result getError = null;

                    if (token != null)
                    {
                        interpreter = GlobalState.GetTokenInterpreter(
                            (ulong)token, ref getNotLocked, ref getNotFound,
                            ref getError);
                    }
                    else
                    {
                        interpreter = GlobalState.GetFirstInterpreter(
                            createFlags, ref getNotLocked, ref getNotFound,
                            ref getError);
                    }

                    //
                    // NOTE: Did we find a pre-existing interpreter that
                    //       we can use (and/or that matched the specified
                    //       token)?
                    //
                    if (interpreter != null)
                    {
                        //
                        // NOTE: Bump the "creation" count for interpreter.
                        //       This allows callers to know when one-time
                        //       setup steps should be performed.  This is
                        //       only done *once* per call to this method.
                        //
                        if (getRetries == 0)
                        {
                            /* IGNORED */
                            interpreter.BumpCreateCount();
                        }

                        //
                        // NOTE: Is there a callback for using an existing
                        //       interpreter?
                        //
                        // HACK: Token-based interpreters are exempt from
                        //       this handling, i.e. will not be seen by
                        //       any registered "interpreter callbacks".
                        //       This design decision may be revised in
                        //       the future.
                        //
                        if ((token == null) &&
                            (useInterpreterCallback != null))
                        {
                            //
                            // NOTE: Invoke the callback now, if
                            //       the return code is Ok, just
                            //       use this interpreter as-is.
                            //       If the return code is Error,
                            //       then fail creation now -AND-
                            //       return; otherwise, create an
                            //       interpreter.
                            //
                            code = useInterpreterCallback(
                                interpreter, clientData, ref result);

                            if (code != ReturnCode.Ok)
                            {
                                TraceOps.DebugTrace(String.Format(
                                    "Create ({0}): " +
                                    "use callback failure, " +
                                    "code = {1}, result = {2}",
                                    AppDomainOps.GetCurrentId(),
                                    code, FormatOps.WrapOrNull(
                                        true, true, result)),
                                    typeof(Interpreter).Name,
                                    TracePriority.StartupError);

                                interpreter = null;
                            }

                            if ((code == ReturnCode.Ok) ||
                                (code == ReturnCode.Error))
                            {
                                goto done;
                            }
                        }
                        else
                        {
                            goto done;
                        }
                    }
                    else if (!getNotFound)
                    {
                        //
                        // HACK: If this condition is hit, that means
                        //       we did not simply fail to "find" the
                        //       interpreter, but were actually unable
                        //       to even search for it (e.g. locking
                        //       error, etc).  Therefore, transform it
                        //       into a real creation error.
                        //
                        if (getNotLocked)
                        {
                            if ((MaximumLockRetries > 0) &&
                                (getRetries++ < MaximumLockRetries))
                            {
                                goto getRetry;
                            }

                            couldNotLock = true;

                            if (ifCannotLock)
                            {
                                //
                                // HACK: In this case, we do not know if
                                //       the interpreter already exists;
                                //       therefore, we need to make sure
                                //       a created interpreter does not
                                //       end up with a duplicate token.
                                //
                                // HACK: Also, if this is supposed to be
                                //       a token-identified interpreter,
                                //       reset the token to a value that
                                //       should not conflict, i.e. even
                                //       if global tracking is disabled
                                //       (-AND- it will NOT be tracked)
                                //       because the GlobalTracking flag
                                //       is not present.  Additionally,
                                //       make sure this interpreter does
                                //       eventually get disposed.
                                //
                                createFlags &= ~CreateFlags.NoDispose;

                                if (token != null)
                                    token = RuntimeOps.GetRandomNumber();

                                TraceOps.DebugTrace(String.Format(
                                    "Create ({0}): " +
                                    "{1} reset, getError = {2}",
                                    AppDomainOps.GetCurrentId(),
                                    (token != null) ?
                                        "token" : "first",
                                    FormatOps.WrapOrNull(
                                        true, true, getError)),
                                    typeof(Interpreter).Name,
                                    TracePriority.StartupDebug3);
                            }
                            else
                            {
                                result = getError;

                                TraceOps.DebugTrace(String.Format(
                                    "Create ({0}): " +
                                    "{1} failure, result = {2}",
                                    AppDomainOps.GetCurrentId(),
                                    (token != null) ?
                                        "token" : "first",
                                    FormatOps.WrapOrNull(
                                        true, true, result)),
                                    typeof(Interpreter).Name,
                                    TracePriority.StartupError);

                                goto done;
                            }
                        }
                    }
                    else
                    {
                        TraceOps.DebugTrace(String.Format(
                            "Create ({0}): not found",
                            AppDomainOps.GetCurrentId()),
                            typeof(Interpreter).Name,
                            TracePriority.StartupError2);
                    }
                }

                ///////////////////////////////////////////////////////////////

                bool globalTracking = FlagOps.HasFlags(
                    initializeFlags, InitializeFlags.GlobalTracking, true);

                ///////////////////////////////////////////////////////////////

                if (!couldNotLock && IsCreationDisabled(
                        globalTracking, false, (token != null), ref result))
                {
                    goto done;
                }

                ///////////////////////////////////////////////////////////////

                bool throwOnError = FlagOps.HasFlags(
                    createFlags, CreateFlags.ThrowOnError, true);

                bool pending = false; /* finally */

                try
                {
                    //
                    // NOTE: Create a brand new (empty) interpreter instance.  This
                    //       interpreter instance will not be readily visible outside
                    //       of this method until this method returns it; that being
                    //       said, some care is taken to avoid "deadlocks" with other
                    //       subsystems.
                    //
                    interpreter = new Interpreter(token);

                    /* NO RESULT */
                    interpreter.BeginCreationPending(out pending);

                    /* IGNORED */
                    interpreter.BumpCreateCount();

                    /* IGNORED */
                    Interlocked.Increment(ref globalCreateCount);

                    //
                    // BUGFIX: Build the auto-path without holding the interpreter
                    //         lock; otherwise, a deadlock could result.  This can
                    //         happen because building the global portion of the
                    //         auto-path requires holding the static GlobalState
                    //         lock.
                    //
                    StringList localAutoPathList = FlagOps.HasFlags(
                        initializeFlags, InitializeFlags.GlobalAutoPath, true) ?
                        GlobalState.GetAutoPathList(interpreter, libraryPath,
                        autoPathList, initializeFlags, false) : null;

                    try
                    {
                        //
                        // NOTE: Acquire the lock for the new interpreter instance.
                        //       This is being used instead of a lock statement here
                        //       so that lock can be released and then re-obtained as
                        //       necessary within this block.
                        //
                        interpreter.InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                        if (locked)
                        {
                            //
                            // NOTE: Push the new interpreter instance onto the active
                            //       interpreter stack for this thread.  This does not
                            //       allow any other thread to obtain this interpreter
                            //       instance.
                            //
                            GlobalState.PushActiveInterpreter(interpreter);

                            try
                            {
                                //
                                // NOTE: Perform the preliminary initialization of this
                                //       interpreter instance.  Generally, this cannot
                                //       fail.  Typically, an interpreter host will be
                                //       created (or cloned) from within it.  That new
                                //       interpreter host will be passed a reference
                                //       to this interpreter instance.  In theory, it
                                //       could then "escape" and be visible by other
                                //       threads; however, this is unlikely, e.g. none
                                //       of the built-in interpreter hosts permit this
                                //       to happen.
                                //
                                Result localResult = null; /* REUSED */

                                code = interpreter.PreSetup(
                                    ruleSet, culture, createFlags, hostCreateFlags,
                                    initializeFlags, dataFlags, scriptFlags,
                                    interpreterFlags, interpreterTestFlags,
                                    pluginFlags,
#if NATIVE && TCL
                                    findFlags, loadFlags,
#endif
                                    appDomain, host, profile, owner, applicationObject,
                                    policyObject, resolverObject, userObject,
                                    new ClientDataDictionary(), text, libraryPath,
                                    autoPathList, ref localResult);

                                if ((code != ReturnCode.Ok) &&
                                    (localResult != null))
                                {
                                    result = localResult;
                                }

                                //*****************************************************

                                if (code == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: Perform general setup of this interpreter
                                    //       instance.  At this point, it is still not
                                    //       really capable of evaluating scripts.  It
                                    //       should be noted that this method contains
                                    //       a call to the notification subsystem, and
                                    //       in theory that could permit other threads
                                    //       and/or external components to be able to
                                    //       see this interpreter instance, primarily
                                    //       via other interpreter instances that were
                                    //       already created.
                                    //
                                    localResult = null;

                                    code = interpreter.Setup(
                                        createFlags, hostCreateFlags, initializeFlags,
                                        interpreterFlags, pluginFlags, ruleSet, args,
                                        localAutoPathList, policies, traces,
                                        ref localResult);

                                    if ((code != ReturnCode.Ok) &&
                                        (localResult != null))
                                    {
                                        result = localResult;
                                    }
                                }

                                //*****************************************************
                                // WARNING: No scripts of any kind may be evaluated
                                //          using the interpreter until after this
                                //          point.
                                //*****************************************************

                                if (code == ReturnCode.Ok)
                                {
                                    EventCallback prepareInterpreterCallback =
                                        PrepareInterpreterCallback;

                                    if (prepareInterpreterCallback != null)
                                    {
                                        IClientData prepareClientData =
                                            new ClientData();

                                        localResult = null;

                                        code = prepareInterpreterCallback(
                                            interpreter, prepareClientData,
                                            ref localResult);

                                        if (code == ReturnCode.Ok)
                                        {
                                            localResult = null;

                                            code = interpreter.MaybeAddPlugins(
                                                prepareClientData, true, true,
                                                ref localResult);

                                            if ((code != ReturnCode.Ok) &&
                                                (localResult != null))
                                            {
                                                result = localResult;
                                            }
                                        }
                                        else if (localResult != null)
                                        {
                                            result = localResult;
                                        }
                                    }
                                }

                                //*****************************************************

                                if (code == ReturnCode.Ok)
                                {
                                    bool initialize = true;

                                    if (FlagOps.HasFlags(
                                            createFlags, CreateFlags.Startup, true))
                                    {
                                        //
                                        // NOTE: Perform any operations necessary
                                        //       based on the configured "startup"
                                        //       options.  This method consults the
                                        //       environment and configuration file
                                        //       in order to do its work, which is
                                        //       quite linear and mostly harmless.
                                        //       It does not readily permit other
                                        //       threads of external components to
                                        //       access this interpreter instance.
                                        //
                                        localResult = null;

                                        code = ProcessStartupOptions(
                                            interpreter, args, createFlags,
                                            OptionOriginFlags.Standard,
                                            console, verbose, ref initialize,
                                            ref localResult);

                                        if ((code != ReturnCode.Ok) &&
                                            (localResult != null))
                                        {
                                            result = localResult;
                                        }
                                    }

                                    //*************************************************

#if DEBUGGER
                                    if (code == ReturnCode.Ok)
                                    {
                                        //
                                        // NOTE: This must be prior to the Initialize()
                                        //       call below if we want to be able to
                                        //       debug the startup script.
                                        //
                                        // BUGFIX: Use the same host as we were passed,
                                        //         never create a new one here.
                                        //
                                        if (FlagOps.HasFlags(
                                                createFlags, CreateFlags.Debugger,
                                                true))
                                        {
                                            //
                                            // TODO: Make possible to disable copying
                                            //       the library path and/or auto-path
                                            //       here?
                                            //
                                            // NOTE: Create optional script debugger,
                                            //       if possible.  This *MAY* result in
                                            //       another interpreter instance being
                                            //       created.  If that fails, the
                                            //       script debugger itself is still
                                            //       created.  However, this static
                                            //       method must be re-entrant.  In
                                            //       order to prevent infinite (mutual)
                                            //       recursion at this point, callers
                                            //       of this method (e.g. the Debugger
                                            //       class) *MUST* mask off the
                                            //       "Debugger" interpreter creation
                                            //       flag.
                                            //
                                            IDebugger debugger = DebuggerOps.Create(
                                                FlagOps.HasFlags(createFlags,
                                                    CreateFlags.DebuggerInterpreter,
                                                    true),
                                                culture, createFlags, hostCreateFlags,
                                                initializeFlags, scriptFlags,
                                                interpreterFlags, pluginFlags,
                                                interpreter.GetAppDomain(),
                                                interpreter.InternalHost,
                                                DebuggerOps.GetLibraryPath(interpreter),
                                                DebuggerOps.GetAutoPathList(interpreter));

                                            if (debugger != null)
                                            {
                                                //
                                                // NOTE: Associate new script debugger
                                                //       instance into new interpreter
                                                //       instance.
                                                //
                                                interpreter.Debugger = debugger;
                                            }
                                            else
                                            {
                                                //
                                                // NOTE: Currently, this cannot happen
                                                //       as script debugger creation
                                                //       cannot currently fail.  This
                                                //       may change in the future.
                                                //
                                                result = "unable to create script debugger";
                                                code = ReturnCode.Error;
                                            }
                                        }
                                    }
#endif

                                    if (code == ReturnCode.Ok)
                                    {
                                        //
                                        // NOTE: If script library initialization was
                                        //       requested, do it now.
                                        //
                                        // WARNING: This performs evaluation of a few
                                        //          script library files.  To further
                                        //          complicate matters, any (or all)
                                        //          of these script library files may
                                        //          be user-defined.  Should one of
                                        //          these script library files raise a
                                        //          script error or throw exceptions,
                                        //          the overall creation process for
                                        //          the new interpreter instance may
                                        //          fail.
                                        //
                                        // LOCKING: Exit the interpreter lock prior
                                        //          to script evaluation.  Skip any
                                        //          attempts to reacquire the lock
                                        //          as it should not be needed after
                                        //          this point within this method.
                                        //          It should be noted here that the
                                        //          PrivateInitialize method and all
                                        //          other parts of the script library
                                        //          initialization pipeline perform
                                        //          their own locking.
                                        //
                                        // NOTE: Check the creation flags and the
                                        //       initialization override to determine
                                        //       if script library initialization is
                                        //       desired.
                                        //
                                        bool wantInitialize = initialize &&
                                            FlagOps.HasFlags(createFlags,
                                                CreateFlags.Initialize, true);

                                        if (wantInitialize)
                                        {
                                            interpreter.InternalExitLock(
                                                ref locked); /* TRANSACTIONAL */

                                            Result initializeError = null;

                                            code = interpreter.PrivateInitialize(
                                                localAutoPathList, false, false,
                                                ref initializeError);

                                            interpreter.MaybeIgnoreInitializeError(
                                                ref code, ref initializeError);

                                            if ((code != ReturnCode.Ok) &&
                                                (initializeError != null))
                                            {
                                                result = initializeError;
                                            }
                                        }
                                    }
                                }

                                //*****************************************************

                                if (code == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: Check for the optional new interpreter
                                    //       instance callback (delegate).  When it
                                    //       is set, all new interpreter instances
                                    //       created in this AppDomain will be sent
                                    //       to it for review prior to them being
                                    //       returned from this method.  This could
                                    //       certainly allow other threads and/or
                                    //       external components to obtain this new
                                    //       interpreter instance.
                                    //
                                    // LOCKING: Exit the interpreter lock prior to
                                    //          executing the callback delegate and
                                    //          skip any attempts to reacquire the
                                    //          lock as it should not be needed after
                                    //          this point within this method.
                                    //
                                    // HACK: Token-based interpreters are exempt from
                                    //       this handling, i.e. will not be seen by
                                    //       any registered "interpreter callbacks".
                                    //       This design decision may be revised in
                                    //       the future.
                                    //
                                    if ((token == null) &&
                                        (newInterpreterCallback != null))
                                    {
                                        GlobalState.PopActiveInterpreter();

                                        try
                                        {
                                            interpreter.InternalExitLock(
                                                ref locked); /* TRANSACTIONAL */

                                            code = newInterpreterCallback(
                                                interpreter, clientData, ref result);

                                            if (code != ReturnCode.Ok)
                                            {
                                                TraceOps.DebugTrace(String.Format(
                                                    "Create ({0}): " +
                                                    "new callback failure, " +
                                                    "code = {1}, result = {2}",
                                                    AppDomainOps.GetCurrentId(),
                                                    code, FormatOps.WrapOrNull(
                                                        true, true, result)),
                                                    typeof(Interpreter).Name,
                                                    TracePriority.StartupError);
                                            }
                                        }
                                        finally
                                        {
                                            GlobalState.PushActiveInterpreter(
                                                interpreter);
                                        }
                                    }
                                }

                                //*****************************************************

                                if ((code == ReturnCode.Ok) && globalTracking)
                                {
                                    int addRetries = 0;

                                addRetry:

                                    //
                                    // NOTE: Add this new interpreter instance to the
                                    //       global tracking list.  This must succeed
                                    //       or interpreter creation will fail.
                                    //
                                    bool addNotLocked = false;
                                    Result addError = null;

                                    if (token != null)
                                    {
                                        if (!GlobalState.AddTokenInterpreter(
                                                interpreter, ref addNotLocked,
                                                ref addError))
                                        {
                                            if (addNotLocked)
                                            {
                                                if ((MaximumLockRetries > 0) &&
                                                    (addRetries++ < MaximumLockRetries))
                                                {
                                                    goto addRetry;
                                                }

                                                if (ifCannotLock || couldNotLock)
                                                {
                                                    /* IGNORED */
                                                    interpreter.MakeSureToDispose(
                                                        ref createFlags);

                                                    goto skipAdd;
                                                }
                                            }

                                            result = addError;
                                            code = ReturnCode.Error;
                                        }
                                    }
                                    else
                                    {
                                        if ((GlobalState.AddInterpreter(
                                                interpreter, ref addNotLocked,
                                                ref addError) <= 0))
                                        {
                                            if (addNotLocked)
                                            {
                                                if ((MaximumLockRetries > 0) &&
                                                    (addRetries++ < MaximumLockRetries))
                                                {
                                                    goto addRetry;
                                                }

                                                if (ifCannotLock || couldNotLock)
                                                {
                                                    /* IGNORED */
                                                    interpreter.MakeSureToDispose(
                                                        ref createFlags);

                                                    goto skipAdd;
                                                }
                                            }

                                            result = addError;
                                            code = ReturnCode.Error;
                                        }
                                    }
                                }

                                //*****************************************************

                            skipAdd:

                                if (code == ReturnCode.Ok)
                                {
#if NOTIFY && NOTIFY_GLOBAL
                                    //
                                    // NOTE: When global notifications are enabled
                                    //       (rare), notify other interpreters that
                                    //       a new interpreter has been crated and
                                    //       added to the global list.
                                    //
                                    // LOCKING: Exit the interpreter lock prior to
                                    //          firing the global notification and
                                    //          skip any attempts to reacquire the
                                    //          lock as it should not be needed after
                                    //          this point within this method.
                                    //
                                    if (interpreter.PrivateGlobalNotify)
                                    {
                                        interpreter.InternalExitLock(
                                            ref locked); /* TRANSACTIONAL */

                                        /* IGNORED */
                                        CheckNotifications(
                                            null, false,
                                            NotifyType.Interpreter, NotifyFlags.Added,
                                            new ObjectList(culture,
                                                createFlags, hostCreateFlags, host),
                                            interpreter, null, null, null, ref result);
                                    }
#endif
                                }
                                else
                                {
                                    //
                                    // NOTE: At this point, somehow the interpreter
                                    //       creation process has failed.  The new
                                    //       interpreter instance must be disposed
                                    //       to cleanup any resources it may have
                                    //       allocated prior to this point.
                                    //
                                    // LOCKING: Exit the interpreter lock prior to
                                    //          disposing the interpreter instance
                                    //          and skip any attempts to reacquire
                                    //          the lock as it should not be needed
                                    //          after this point within this method.
                                    //          The process of interpreter disposal
                                    //          process may reacquire the lock, and
                                    //          that should be fine.
                                    //
                                    interpreter.InternalExitLock(
                                        ref locked); /* TRANSACTIONAL */

                                    ObjectOps.TryDisposeOrComplain<Interpreter>(
                                        interpreter, ref interpreter);

                                    interpreter = null;
                                }

                                //*****************************************************

                                if ((interpreter == null) && throwOnError)
                                {
                                    TraceOps.DebugTrace(String.Format(
                                        "Create ({0}): failure (with throw), " +
                                        "code = {1}, result = {2}",
                                        AppDomainOps.GetCurrentId(), code,
                                        FormatOps.WrapOrNull(true, true, result)),
                                        typeof(Interpreter).Name,
                                        TracePriority.StartupError);

                                    //
                                    // NOTE: If we get to this point then we have
                                    //       failed to fully create or initialize
                                    //       the interpreter -AND- they requested
                                    //       that we throw an exception in that
                                    //       case.
                                    //
                                    throw new ScriptException(code, result, null);
                                }
                            }
                            finally
                            {
                                /* IGNORED */
                                GlobalState.PopActiveInterpreter();
                            }
                        }
                        else
                        {
                            TraceOps.LockTrace(String.Format(
                                "Create ({0})", AppDomainOps.GetCurrentId()),
                                typeof(Interpreter).Name, " (1)", false,
                                TracePriority.LockError,
                                interpreter.MaybeWhoHasLock());
                        }
                    }
                    finally
                    {
                        if (interpreter != null)
                        {
                            interpreter.InternalExitLock(
                                ref locked); /* TRANSACTIONAL */
                        }
                    }
                }
                catch (Exception e)
                {
                    TraceOps.DebugTrace(
                        e, typeof(Interpreter).Name,
                        TracePriority.StartupError);

                    if (interpreter != null)
                    {
                        interpreter.InternalExitLock(
                            ref locked); /* TRANSACTIONAL */

                        ObjectOps.TryDisposeOrComplain<Interpreter>(
                            interpreter, ref interpreter);

                        interpreter = null;
                    }

                    if (throwOnError)
                        throw;
                    else
                        result = e;
                }
                finally
                {
                    if (interpreter != null)
                    {
                        interpreter.EndCreationPending(
                            ref pending);
                    }
                }

            done:

                if (interpreter != null)
                {
#if THREADING
                    if (FlagOps.HasFlags(
                            initializeFlags, InitializeFlags.Health, true))
                    {
                        //
                        // HACK: This method ends up calling quite a few
                        //       other methods that may throw exceptions
                        //       if the target interpreter is disposed,
                        //       etc (this was pointed out by Coverity);
                        //       therefore, use a special variant that
                        //       simply catches everything.
                        //
                        if (interpreter.PrivateWatchdogControlNoThrow(
                                WatchdogType.Health,
                                WatchdogOperation.StartAndFlags,
                                TimeoutFlags.Default, clientData,
                                null, ref result) != ReturnCode.Ok)
                        {
                            ObjectOps.TryDisposeOrComplain<Interpreter>(
                                interpreter, ref interpreter);

                            interpreter = null;

                            goto done;
                        }
                    }
#endif

                    TraceOps.DebugTrace(String.Format(
                        "Create ({0}): success, interpreter = {1}, " +
                        "result = {2}",
                        AppDomainOps.GetCurrentId(),
                        FormatOps.InterpreterNoThrow(interpreter),
                        FormatOps.WrapOrNull(true, true, result)),
                        typeof(Interpreter).Name,
                        TracePriority.StartupDebug);
                }
                else
                {
                    TraceOps.DebugTrace(String.Format(
                        "Create ({0}): failure (without throw), " +
                        "interpreter = {1}, result = {2}",
                        AppDomainOps.GetCurrentId(),
                        FormatOps.InterpreterNoThrow(interpreter),
                        FormatOps.WrapOrNull(true, true, result)),
                        typeof(Interpreter).Name,
                        TracePriority.StartupError);
                }
            }
            finally
            {
                if (profiler != null)
                {
                    profiler.Stop();

                    TraceOps.DebugTrace(String.Format(
                        "Create ({0}): return, interpreter = {1}, " +
                        "result = {2}, completed in {3}",
                        AppDomainOps.GetCurrentId(),
                        FormatOps.InterpreterNoThrow(interpreter),
                        FormatOps.WrapOrNull(true, true, result),
                        FormatOps.MaybeNull(profiler)),
                        typeof(Interpreter).Name,
                        TracePriority.StartupDebug3);

                    if (interpreter != null)
                    {
                        try
                        {
                            interpreter.InternalHardTryLock(
                                ref locked); /* TRANSACTIONAL */

                            if (locked)
                            {
                                interpreter.CreateProfiler(
                                    profiler);
                            }
                            else
                            {
                                TraceOps.LockTrace(String.Format(
                                    "Create ({0})", AppDomainOps.GetCurrentId()),
                                    typeof(Interpreter).Name, " (2)", false,
                                    TracePriority.LockError,
                                    interpreter.MaybeWhoHasLock());
                            }
                        }
                        finally
                        {
                            interpreter.InternalExitLock(
                                ref locked); /* TRANSACTIONAL */
                        }
                    }

                    /* IGNORED */
                    ObjectOps.TryDisposeOrTrace<IProfilerState>(
                        ref profiler);

                    profiler = null;
                }
            }

            return interpreter;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Public Static "Factory" Methods
        //
        // NOTE: This is the "simplest" possible method that can
        //       be used to create an interpreter.
        //
        /// <summary>
        /// Creates a new interpreter using all default settings.  This is the
        /// simplest creation overload and the recommended starting point; use
        /// it when you do not need to customize creation flags, startup
        /// arguments, a custom host, or a licensing token.  For configurable
        /// creation, use an overload that accepts <see cref="CreateFlags" /> or
        /// an <c>IInterpreterSettings</c> object.  Always dispose the returned
        /// interpreter when finished.  See <c>embedding_eagle.md</c> and
        /// <c>choosing_create_overload.md</c>.
        /// </summary>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot
        /// be created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        public static Interpreter Create( /* Kapok, null InterpreterSettings, test suite, etc. */
            ref Result result
            )
        {
            return Create(null, null,
                _ClientData.Empty, null, null, Defaults.CreateFlags,
                Defaults.HostCreateFlags, Defaults.InitializeFlags,
                Defaults.ScriptFlags, Defaults.InterpreterFlags,
                Defaults.InterpreterTestFlags, Defaults.PluginFlags,
#if NATIVE && TCL
                Defaults.FindFlags, Defaults.LoadFlags,
#endif
                null, null, null, null, null, null, null, null, null,
                null, null, null, null, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates a new interpreter using default settings together with a
        /// licensing token.  Use this overload when you have a
        /// licensing/certificate token issued for use with the Harpy security
        /// plugin and otherwise need no customization; for the simplest case, use
        /// Create(ref Result) instead.
        /// </summary>
        /// <param name="token">
        /// An optional licensing/certificate token used by the Harpy security
        /// plugin; when non-null, it is also used for secure interpreter lookup.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        public static Interpreter Create( /* Harpy */
            ulong? token,
            ref Result result
            )
        {
            CreateFlags createFlags = Defaults.CreateFlags;

            MaybeMutateCreateFlags(token, ref createFlags);

            InitializeFlags initializeFlags = Defaults.InitializeFlags;

            MaybeMutateInitializeFlags(token, ref initializeFlags);

            return Create(token, null,
                _ClientData.Empty, null, null, createFlags,
                Defaults.HostCreateFlags, initializeFlags,
                Defaults.ScriptFlags, Defaults.InterpreterFlags,
                Defaults.InterpreterTestFlags, Defaults.PluginFlags,
#if NATIVE && TCL
                Defaults.FindFlags, Defaults.LoadFlags,
#endif
                null, null, null, null, null, null, null, null, null,
                null, null, null, null, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates a new interpreter using default settings, supplying the
        /// specified startup arguments.  Use this overload when you only need to
        /// pass startup (command-line style) arguments and require no other
        /// customization.
        /// </summary>
        /// <param name="args">
        /// The startup (command-line style) arguments to make available to the
        /// new interpreter, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        public static Interpreter Create( /* Example.Program, test suite, etc. */
            IEnumerable<string> args,
            ref Result result
            )
        {
            return Create(null, null,
                _ClientData.Empty, args, null, Defaults.CreateFlags,
                Defaults.HostCreateFlags, Defaults.InitializeFlags,
                Defaults.ScriptFlags, Defaults.InterpreterFlags,
                Defaults.InterpreterTestFlags, Defaults.PluginFlags,
#if NATIVE && TCL
                Defaults.FindFlags, Defaults.LoadFlags,
#endif
                null, null, null, null, null, null, null, null, null,
                null, null, null, null, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates a new interpreter using default settings, supplying both a
        /// licensing token and startup arguments.  Use this overload when you
        /// have a Harpy licensing token and also need to pass startup
        /// (command-line style) arguments.
        /// </summary>
        /// <param name="token">
        /// An optional licensing/certificate token used by the Harpy security
        /// plugin; when non-null, it is also used for secure interpreter lookup.
        /// </param>
        /// <param name="args">
        /// The startup (command-line style) arguments to make available to the
        /// new interpreter, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        public static Interpreter Create(
            ulong? token,
            IEnumerable<string> args,
            ref Result result
            )
        {
            CreateFlags createFlags = Defaults.CreateFlags;

            MaybeMutateCreateFlags(token, ref createFlags);

            InitializeFlags initializeFlags = Defaults.InitializeFlags;

            MaybeMutateInitializeFlags(token, ref initializeFlags);

            return Create(token, null,
                _ClientData.Empty, args, null, createFlags,
                Defaults.HostCreateFlags, initializeFlags,
                Defaults.ScriptFlags, Defaults.InterpreterFlags,
                Defaults.InterpreterTestFlags, Defaults.PluginFlags,
#if NATIVE && TCL
                Defaults.FindFlags, Defaults.LoadFlags,
#endif
                null, null, null, null, null, null, null, null, null,
                null, null, null, null, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates a new interpreter with the specified startup arguments and
        /// explicit creation flags.  Use this overload when you need to control
        /// interpreter and host creation behavior (for example, creating a "safe"
        /// interpreter) in addition to passing startup arguments.
        /// </summary>
        /// <param name="args">
        /// The startup (command-line style) arguments to make available to the
        /// new interpreter, or null for none.
        /// </param>
        /// <param name="createFlags">
        /// Flags controlling how the interpreter itself is created (for example,
        /// whether it is created "safe").
        /// </param>
        /// <param name="hostCreateFlags">
        /// Flags controlling how the interpreter host is created.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        public static Interpreter Create( /* Engine.EvaluateOneScript, MSBuild, WiX, etc. */
            IEnumerable<string> args,
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            ref Result result
            )
        {
            return Create(null, null,
                _ClientData.Empty, args, null, createFlags,
                hostCreateFlags, Defaults.InitializeFlags,
                Defaults.ScriptFlags, Defaults.InterpreterFlags,
                Defaults.InterpreterTestFlags, Defaults.PluginFlags,
#if NATIVE && TCL
                Defaults.FindFlags, Defaults.LoadFlags,
#endif
                null, null, null, null, null, null, null, null,
                null, null, null, null, null, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Creates a new interpreter with a licensing token, startup arguments,
        /// an optional post-setup script, and fine-grained control over creation,
        /// initialization, script, interpreter, and plugin behavior.  Use this
        /// overload (intended for the Harpy SDK) when you have a licensing token
        /// and need detailed control over creation without using a full settings
        /// object.
        /// </summary>
        /// <param name="token">
        /// An optional licensing/certificate token used by the Harpy security
        /// plugin; when non-null, it is also used for secure interpreter lookup.
        /// </param>
        /// <param name="args">
        /// The startup (command-line style) arguments to make available to the
        /// new interpreter, or null for none.
        /// </param>
        /// <param name="createFlags">
