        /// <summary>
        /// Creates a new interpreter from a configurable settings object.  Use
        /// this overload when you have a configurable <c>IInterpreterSettings</c>
        /// object; for the simplest case, use Create(ref Result) instead.  When
        /// strict is true and the settings object is null, creation fails;
        /// otherwise default settings are used.
        /// </summary>
        /// <param name="interpreterSettings">
        /// The configurable settings object describing how the interpreter should
        /// be created, or null.
        /// </param>
        /// <param name="strict">
        /// When true, a null interpreterSettings causes creation to fail; when
        /// false, an interpreter is created using default settings instead.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an appropriate error message describing
        /// why the interpreter could not be created.
        /// </param>
        /// <returns>
        /// The newly created <see cref="Interpreter" /> -OR- null if it cannot be
        /// created, in which case <paramref name="result" /> describes the
        /// failure.
        /// </returns>
        public static Interpreter Create( /* InterpreterHelper, etc. */
            IInterpreterSettings interpreterSettings,
            bool strict,
            ref Result result
            )
        {
            if (interpreterSettings != null)
            {
                return Create(null,
                    interpreterSettings.RuleSet, _ClientData.Empty,
                    interpreterSettings.Args, interpreterSettings.Culture,
                    interpreterSettings.CreateFlags, interpreterSettings.HostCreateFlags,
                    interpreterSettings.InitializeFlags, interpreterSettings.ScriptFlags,
                    interpreterSettings.InterpreterFlags,
                    interpreterSettings.InterpreterTestFlags,
                    interpreterSettings.PluginFlags,
#if NATIVE && TCL
                    interpreterSettings.FindFlags, interpreterSettings.LoadFlags,
#endif
                    interpreterSettings.AppDomain, interpreterSettings.Host,
                    interpreterSettings.Profile, interpreterSettings.Owner,
                    interpreterSettings.ApplicationObject, interpreterSettings.PolicyObject,
                    interpreterSettings.ResolverObject, interpreterSettings.UserObject,
                    interpreterSettings.Policies, interpreterSettings.Traces,
                    interpreterSettings.Text, interpreterSettings.LibraryPath,
                    interpreterSettings.AutoPathList, ref result);
            }

            if (strict)
            {
                result = "invalid interpreter settings";
                return null;
            }

            return Create(ref result);
        }

