        #region Pre-Setup
        /// <summary>
        /// This method resolves and records the culture used by the interpreter
        /// during the pre-setup phase of creation.
        /// </summary>
        /// <param name="culture">
        /// The name of the culture to use, or null to use the default culture.
        /// </param>
        /// <param name="specific">
        /// Non-zero to require a specific (non-neutral) culture.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PreSetupCulture( /* COMPAT: Eagle beta. */
            string culture,  /* in */
            bool specific,   /* in */
            ref Result error /* out */
            )
        {
            CultureInfo localCultureInfo = RuntimeOps.GetCultureInfo(
                culture, specific, ref error);

            if (localCultureInfo == null)
                return ReturnCode.Error;

            cultureInfo = localCultureInfo;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For use by the _Hosts.Core class only.
        //
        /// <summary>
        /// Gets the resource manager used to look up the localized strings for
        /// this interpreter.  This property is for use by the core host only.
        /// </summary>
        internal ResourceManager ResourceManager
        {
            get { return resourceManager; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates and records the resource manager for the
        /// interpreter during the pre-setup phase of creation.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PreSetupResourceManager( /* COMPAT: Eagle beta. */
            ref Result error /* out */
            )
        {
            ResourceManager localResourceManager =
                RuntimeOps.GetResourceManager(
                    InternalCultureInfo, ref error);

            if (localResourceManager == null)
                return ReturnCode.Error;

            resourceManager = localResourceManager;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the default foreground and background console
        /// colors for the interpreter, querying them from the specified host
        /// during the pre-setup phase of creation.
        /// </summary>
        /// <param name="host">
        /// The interpreter host from which to query the default colors.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat a failure to obtain the colors as an error.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PreSetupHostColors(
            IHost host,
            bool strict,
            ref Result error
            )
        {
            //
            // NOTE: Set the system default values for the "default" foreground
            //       and background colors now.  That way, even if there is no
            //       interpreter host or it decides not to do anything, these
            //       values will still be explicitly initialized.
            //
            defaultForegroundColor = _ConsoleColor.Default;
            defaultBackgroundColor = _ConsoleColor.Default;

            //
            // NOTE: If this IHost call fails, the caller will fail to setup
            //       the interpreter.  This is considered to be legitimate,
            //       even in non-strict mode, because IHost implementations are
            //       free to simply return "Ok" without having to do anything
            //       else (i.e. the default colors have already been set to the
            //       system defaults before this call).  Therefore, an IHost
            //       implementation that returns "Error" here is explicitly
            //       saying "the interpreter setup should fail".  Furthermore,
            //       we attempt to further minimize the risk of failure here
            //       by explicitly requesting the default hard-coded colors
            //       from the host (i.e. both the "foreground" and "background"
            //       boolean arguments are set to "false") because that should
            //       be even less likely to fail (and it _is_ less likely to
            //       fail with the "stock" implementation of this method, as
            //       provided by the _Hosts.Core host).
            //
            return HostOps.GetColors(
                host, ColorName.Default, false, false, strict,
                ref defaultForegroundColor, ref defaultBackgroundColor,
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method enables or disables namespace support for the interpreter,
        /// optionally disposing any existing namespace state and adjusting the
        /// associated creation flags.
        /// </summary>
        /// <param name="enable">
        /// Non-zero to enable namespace support; zero to disable it.
        /// </param>
        /// <param name="dispose">
        /// Non-zero to dispose any existing namespace objects before making
        /// changes.
        /// </param>
        /// <param name="flags">
        /// Non-zero to also update the interpreter creation flags to reflect the
        /// new namespace state.
        /// </param>
        internal void PreSetupNamespaces(
            bool enable,
            bool dispose,
            bool flags
            )
        {
            TraceOps.DebugTrace(String.Format(
                "PreSetupNamespaces: interpreter = {0}, " +
                "enable = {1}, dispose = {2}, flags = {3}",
                FormatOps.InterpreterNoThrow(this), enable, dispose, flags),
                typeof(Interpreter).Name, TracePriority.StartupDebug);

            ///////////////////////////////////////////////////////////////////////////////////////////

            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // HACK: Make 100% sure that we are not about to overwrite valid
                //       disposable object instances when enabling or disabling
                //       namespace support.
                //
                if (dispose)
                {
                    ClearAndMaybeResetNamespacePodObjects(true);
                    DisposeNamespaces();
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (enable)
                {
                    if (globalNamespace == null)
                        globalNamespace = NamespaceOps.CreateGlobal(this);

                    if (pendingNamespaces == null)
                        pendingNamespaces = new Dictionary<string, INamespace>();

                    if (namespaceMappings == null)
                        namespaceMappings = NamespaceOps.CreateMappings(this);

                    if (flags)
                        createFlags |= CreateFlags.UseNamespaces;

                    Interlocked.Exchange(ref namespaceCount, 1); /* GLOBAL */
                }
                else if (flags)
                {
                    createFlags &= ~CreateFlags.UseNamespaces;

                    Interlocked.Exchange(ref namespaceCount, 0); /* NONE */
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
#if CACHE_DICTIONARY
        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method applies the configured cache settings to all of the caches
        /// currently associated with the interpreter.  This method assumes the
        /// interpreter lock is held.
        /// </summary>
        /// <returns>
        /// The flags identifying the caches whose properties were updated.
        /// </returns>
        private CacheFlags SetPropertiesOnCaches()
        {
            return SetPropertiesOnCaches(cacheFlags, true); /* EXEMPT */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method applies cache settings to the selected caches associated
        /// with the interpreter.  This method assumes the interpreter lock is
        /// held.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches should be configured.
        /// </param>
        /// <param name="enable">
        /// Non-zero to enable the configured cache properties; zero to disable
        /// them.
        /// </param>
        /// <returns>
        /// The flags identifying the caches whose properties were updated.
        /// </returns>
        private CacheFlags SetPropertiesOnCaches(
            CacheFlags flags,
            bool enable
            )
        {
            CacheFlags newFlags = CacheFlags.None;

            ///////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE
            if ((argumentCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.Argument, true))
            {
                CacheConfiguration.SetProperties<Argument, Argument>(
                    argumentCache, enable);

                newFlags |= CacheFlags.Argument;
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if LIST_CACHE
            if ((stringListCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.StringList, true))
            {
                CacheConfiguration.SetProperties<string, StringList>(
                    stringListCache, enable);

                newFlags |= CacheFlags.StringList;
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if PARSE_CACHE
            if ((parseStateCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.IParseState, true))
            {
                CacheConfiguration.SetProperties<string, IParseState>(
                    parseStateCache, enable);

                newFlags |= CacheFlags.IParseState;
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if TYPE_CACHE
            if ((typeCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.Type, true))
            {
                CacheConfiguration.SetProperties<string, Type>(
                    typeCache, enable);

                newFlags |= CacheFlags.Type;
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if COM_TYPE_CACHE
            if ((comTypeListCache != null) &&
                FlagOps.HasFlags(flags, CacheFlags.ComTypeList, true))
            {
                CacheConfiguration.SetProperties<IntPtr, TypeList>(
                    comTypeListCache, enable);

                newFlags |= CacheFlags.ComTypeList;
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (FlagOps.HasFlags(flags, CacheFlags.StringBuilder, true))
            {
                //
                // HACK: This is faked because this cache does
                //       not support setting initial properties.
                //
                newFlags |= CacheFlags.StringBuilder;
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (FlagOps.HasFlags(newFlags, flags & CacheFlags.TypicalMask, true))
                return CacheFlags.SetProperties;
            else
                return CacheFlags.None;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method creates and configures the interpreter caches during the
        /// pre-setup phase of creation.  This method assumes the interpreter lock
        /// is held.
        /// </summary>
        /// <returns>
        /// The flags identifying the caches that were created.
        /// </returns>
        internal CacheFlags PreSetupCaches()
        {
            return PreSetupCaches(cacheFlags, null); /* EXEMPT */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method creates the selected interpreter caches during the
        /// pre-setup phase of creation, optionally restoring previously saved
        /// cache counts.  This method assumes the interpreter lock is held.
        /// </summary>
        /// <param name="flags">
        /// The flags identifying which caches should be created.
        /// </param>
        /// <param name="savedCacheCounts">
        /// The previously saved per-cache counts to restore, or null if none.
        /// </param>
        /// <returns>
        /// The flags identifying the caches that were created.
        /// </returns>
        private CacheFlags PreSetupCaches(
            CacheFlags flags,
            Dictionary<CacheFlags, long[]> savedCacheCounts
            )
        {
            CacheFlags newFlags = CacheFlags.None;

            ///////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE || LIST_CACHE
            int capacity = CacheConfiguration.GetCapacity();
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE
            if (FlagOps.HasFlags(flags, CacheFlags.Argument, true))
            {
                if (argumentCache == null)
                {
                    argumentCache = new ArgumentCacheDictionary(
                        capacity >= 0 ? capacity : 0);

#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        RuntimeOps.MaybeRestoreCacheCounts(
                            CacheFlags.Argument, argumentCache, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    newFlags |= CacheFlags.Argument;
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if LIST_CACHE
            if (FlagOps.HasFlags(flags, CacheFlags.StringList, true))
            {
                if (stringListCache == null)
                {
                    stringListCache = new StringListDictionary(
                        capacity >= 0 ? capacity : 0, true);

#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        RuntimeOps.MaybeRestoreCacheCounts(
                            CacheFlags.StringList, stringListCache, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    newFlags |= CacheFlags.StringList;
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if PARSE_CACHE
            if (FlagOps.HasFlags(flags, CacheFlags.IParseState, true))
            {
                if (parseStateCache == null)
                {
                    parseStateCache = new ParseStateDictionary();

#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        RuntimeOps.MaybeRestoreCacheCounts(
                            CacheFlags.IParseState, parseStateCache, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    newFlags |= CacheFlags.IParseState;
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if EXECUTE_CACHE
            if (FlagOps.HasFlags(flags, CacheFlags.IExecute, true))
            {
                if (executeCache == null)
                {
                    executeCache = new ExecuteCache();

#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        RuntimeOps.MaybeRestoreCacheCounts(
                            CacheFlags.IExecute, executeCache, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    /* INTENTIONAL: see "if" */
                    newFlags |= CacheFlags.IExecute; /* NOTE: Not a typo. */
                }

                if (hiddenExecuteCache == null)
                {
                    hiddenExecuteCache = new ExecuteCache();

#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        RuntimeOps.MaybeRestoreCacheCounts(
                            CacheFlags.HiddenIExecute, hiddenExecuteCache, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    /* INTENTIONAL: see "if" */
                    newFlags |= CacheFlags.IExecute; /* NOTE: Not a typo. */
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if TYPE_CACHE
            if (FlagOps.HasFlags(flags, CacheFlags.Type, true))
            {
                if (typeCache == null)
                {
                    typeCache = new TypeDictionary();

#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        RuntimeOps.MaybeRestoreCacheCounts(
                            CacheFlags.Type, typeCache, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    newFlags |= CacheFlags.Type;
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if COM_TYPE_CACHE
            if (FlagOps.HasFlags(flags, CacheFlags.ComTypeList, true))
            {
                if (comTypeListCache == null)
                {
                    comTypeListCache = new IntPtrTypeListDictionary();

#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        RuntimeOps.MaybeRestoreCacheCounts(
                            CacheFlags.ComTypeList, comTypeListCache, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    newFlags |= CacheFlags.ComTypeList;
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (FlagOps.HasFlags(flags, CacheFlags.StringBuilder, true))
            {
                //
                // NOTE: *SPECIAL* This is a static cache for the
                //       entire AppDomain.  In this method, check
                //       to see if it needs to be enabled; if so,
                //       enable it now.
                //
                if (!SBC.MaybeEnable(null) && SBC.MaybeEnable(true))
                {
#if CACHE_STATISTICS
                    if (FlagOps.HasFlags(
                            flags, CacheFlags.KeepCounts, true))
                    {
                        /* IGNORED */
                        SBC.MaybeRestoreCounts(
                            CacheFlags.StringBuilderCache, false,
                            false, ref savedCacheCounts);

                        /* IGNORED */
                        SBF.MaybeRestoreCounts(
                            CacheFlags.StringBuilderFactory, false,
                            false, ref savedCacheCounts);
                    }
#endif

                    newFlags |= CacheFlags.StringBuilder;
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (FlagOps.HasFlags(newFlags, flags & CacheFlags.TypicalMask, true))
                return CacheFlags.Reset;
            else
                return CacheFlags.None;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if !THREADING
        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method performs the first phase of call frame pre-setup, creating
        /// the call stack and the global call frame.  This method assumes the
        /// interpreter lock is held.
        /// </summary>
        private void PreSetupCallFramesPhase1()
        {
            CallStack = new CallStack(this.PrivateRecursionLimit, false);
            GlobalFrame = NewGlobalCallFrame(CallStack); /* EXEMPT */
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method performs the second phase of call frame pre-setup, pushing
        /// the global call frame and resetting the other well-known call frame
        /// references.  This method assumes the interpreter lock is held.
        /// </summary>
        private void PreSetupCallFramesPhase2()
        {
            PushGlobalCallFrame(false); // NOTE: This call frame is never popped.

            GlobalScopeFrame = null;
            // CurrentFrame = null; // HACK: *SPECIAL* Via Push*CallFrame() only.
            ProcedureFrame = null;
            UplevelFrame = null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates and/or configures the interpreter host during the
        /// pre-setup phase of creation.  The host is established first so that it
        /// can be used to communicate any subsequent initialization failures.
        /// </summary>
        /// <param name="host">
        /// The host to use or clone, or null to create a new default host.
        /// </param>
        /// <param name="hostCreateFlags">
        /// The flags controlling how the host is created or cloned.
        /// </param>
        /// <param name="profile">
        /// The name of the host profile to use, or null for none.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PreSetupHost(
            IHost host,
            HostCreateFlags hostCreateFlags,
            string profile,
            ref Result error
            )
        {
            //
            // NOTE: Create and/or setup our host environment first because this
            //       will be used to communicate all other initialization failures.
            //
            IHost localHost = null;
            bool localHostOwned = false;
            Result createError = null;

            if (host != null)
            {
                if (FlagOps.HasFlags(hostCreateFlags, HostCreateFlags.Clone, true))
                {
                    //
                    // NOTE: Use a clone of the specified hosting environment.
                    //
                    try
                    {
                        localHost = host.Clone(this); /* throw */

                        if (localHost != null)
                            localHostOwned = true;
                    }
                    catch (Exception e)
                    {
                        createError = e;
                    }
                }
                else
                {
                    //
                    // NOTE: Use the specified hosting environment.
                    //
                    localHost = host;
                }
            }
            else if (!FlagOps.HasFlags(hostCreateFlags, HostCreateFlags.Disable, true))
            {
                if ((profile == null) &&
                    !FlagOps.HasFlags(hostCreateFlags, HostCreateFlags.NoProfile, true))
                {
                    profile = GlobalConfiguration.GetValue(
                        EnvVars.Profile, ConfigurationFlags.Interpreter);
                }

                ///////////////////////////////////////////////////////////////////////////////////////

#if CONSOLE
                if (!String.IsNullOrEmpty(profile))
                {
                    ConsoleOps.MaybeWritePrompt(String.Format(
                        _Constants.Prompt.Profile, profile));
                }

                ///////////////////////////////////////////////////////////////////////////////////////

                if (!FlagOps.HasFlags(
                        hostCreateFlags, HostCreateFlags.NoNativeConsole, true))
                {
                    HostOps.SetupNativeConsole(this, hostCreateFlags);
                }
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

                //
                // NOTE: *HOOK* Allow the default host to be overridden by
                //       an external application or third-party plugin.
                //
                NewHostCallback callback = NewHostCallback; /* STATIC */

            retry:

                if (callback != null)
                {
                    //
                    // HACK: The lock is held while the custom host is
                    //       being created.  In theory, this could cause
                    //       a deadlock if the callback is not careful.
                    //
                    localHost = HostOps.NewCustom(
                        callback, this, null, profile, hostCreateFlags,
                        ref createError);

                    if (localHost != null)
                        localHostOwned = true;

                    if ((localHost == null) && FlagOps.HasFlags(
                            hostCreateFlags, HostCreateFlags.MustCreate,
                            true))
                    {
                        //
                        // NOTE: We failed to create a new host using the
                        //       configured creation callback -AND- we are
                        //       not permitted to fail; therefore, disable
                        //       the creation callback (for this call only)
                        //       and then fallback to default semantics.
                        //
                        callback = null;
                        goto retry;
                    }
                }
                else
                {
#if CONSOLE
                    //
                    // NOTE: Default hosting environment (i.e. optimized
                    //       for console apps, like the interactive shell).
                    //
                    if (!FlagOps.HasFlags(
                            hostCreateFlags, HostCreateFlags.NoConsole,
                            true))
                    {
                        localHost = HostOps.NewConsole(
                            this, null, profile, hostCreateFlags);

                        if (localHost != null)
                        {
                            localHostOwned = true;

#if NATIVE && WINDOWS
                            //
                            // HACK: Unfortunately, this cannot be done in
                            //       the HostOps.WriteNativeConsole method
                            //       because this console host has not yet
                            //       been created at that point.
                            //
                            if (FlagOps.HasFlags(hostCreateFlags,
                                    HostCreateFlags.WriteConsole, true))
                            {
                                _Hosts.Console consoleHost =
                                    localHost as _Hosts.Console;

                                if (consoleHost != null)
                                    consoleHost.SetWriteNative(true);
                            }
#endif
                        }
                    }
                    else
#endif
                    if (!FlagOps.HasFlags(
                            hostCreateFlags, HostCreateFlags.NoDiagnostic,
                            true))
                    {
                        //
                        // NOTE: Debugging hosting environment, for builds
                        //       that do not have System.Console support.
                        //
                        localHost = HostOps.NewDiagnostic(
                            this, null, profile, hostCreateFlags);

                        if (localHost != null)
                            localHostOwned = true;
                    }
                    else if (!FlagOps.HasFlags(
                            hostCreateFlags, HostCreateFlags.NoNull,
                            true))
                    {
                        localHost = HostOps.NewNull(
                            this, null, profile, hostCreateFlags);

                        if (localHost != null)
                            localHostOwned = true;
                    }
                    else if (!FlagOps.HasFlags(
                            hostCreateFlags, HostCreateFlags.NoFake,
                            true))
                    {
                        localHost = HostOps.NewFake(
                            this, null, profile, hostCreateFlags);

                        if (localHost != null)
                            localHostOwned = true;
                    }
                }
            }
            else
            {
                //
                // NOTE: No interpreter host.  This probably won't work
                //       very well in most circumstances.
                //
                localHost = null;
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            //
            // TODO: Force use of the host wrapper?  How is this actually useful?
            //       At the moment, this is primarily useful when testing.
            //
            Result wrapError = null;

#if ISOLATED_PLUGINS
            bool overwriteIsolatedHost = false;
#endif

            if ((localHost != null) && FlagOps.HasFlags(
                    hostCreateFlags, HostCreateFlags.UseWrapper, true))
            {
                if (!localHostOwned && FlagOps.HasFlags(
                        hostCreateFlags, HostCreateFlags.OwnWrapper, true))
                {
                    localHostOwned = true;
                }

                HostOps.WrapOrDispose(
                    this, null, profile, localHost.HostCreateFlags,
                    ref localHost, ref localHostOwned, ref wrapError);

#if ISOLATED_PLUGINS
                overwriteIsolatedHost = true;
#endif
            }
#if ISOLATED_PLUGINS
            else if (FlagOps.HasFlags(
                    hostCreateFlags, HostCreateFlags.ResetIsolated, true))
            {
                overwriteIsolatedHost = true;
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

            if ((localHost == null) && !FlagOps.HasFlags(
                    hostCreateFlags, HostCreateFlags.Disable, true) &&
                FlagOps.HasFlags(
                    hostCreateFlags, HostCreateFlags.MustCreate, true))
            {
                ResultList errors = new ResultList();

                if (createError != null)
                    errors.Add(createError);

                if (wrapError != null)
                    errors.Add(wrapError);

                errors.Add("failed to create interpreter host");

                error = errors;
                return ReturnCode.Error;
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            //
            // NOTE: Either we successfully created a new host -OR- failures
            //       to create the host can be safely ignored.
            //
            this.host = localHost;

            //
            // NOTE: If the isolated host (may) need to be updated, attempt to
            //       do that now.
            //
#if ISOLATED_PLUGINS
            /* IGNORED */
            AppDomainOps.MaybeSetIsolatedHost(
                this, localHost, overwriteIsolatedHost);
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

            //
            // HACK: To make troubleshooting interpreter host integration issues
            //       (somewhat) easier, emit a diagnostic message when the first
            //       interpreter is (being) created to show which host is being
            //       used, its creation flags, and its resulting flags.
            //
            if (GlobalState.CountInterpreters(true) == 0)
            {
                TraceOps.DebugTrace(String.Format(
                        "PreSetupHost (P:{0} A:{1} T:{2})",
                        ProcessOps.GetId(), /* NOTE: Not typo. */
                        AppDomainOps.GetCurrentId(),
                        GlobalState.GetCurrentSystemThreadId()), null,
                    typeof(Interpreter).Name, TracePriority.StartupInform2,
                    false, "hostCreateFlags", hostCreateFlags, "hostType",
                    AppDomainOps.MaybeGetTypeOrComplain(localHost),
                    "hostFlags", HostOps.GetHostFlags(localHost),
                    "hostOwned", localHostOwned, "hostCreateError",
                    createError);
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method performs the pre-setup phase of interpreter creation,
        /// establishing thread affinity, the host, culture, caches, call frames,
        /// and the other core state required before the main setup phase can run.
        /// </summary>
        /// <param name="ruleSet">
        /// The rule set to associate with the interpreter, or null for none.
        /// </param>
        /// <param name="culture">
        /// The name of the culture to use, or null to use the default culture.
        /// </param>
        /// <param name="createFlags">
        /// The flags controlling how the interpreter is created.
        /// </param>
        /// <param name="hostCreateFlags">
        /// The flags controlling how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// The flags controlling how the interpreter is initialized.
        /// </param>
        /// <param name="dataFlags">
        /// The flags controlling how interpreter data is handled.
        /// </param>
        /// <param name="scriptFlags">
        /// The default script flags used by the engine within the interpreter.
        /// </param>
        /// <param name="interpreterFlags">
        /// The initial interpreter configuration flags.
        /// </param>
        /// <param name="interpreterTestFlags">
        /// The initial interpreter test configuration flags.
        /// </param>
        /// <param name="pluginFlags">
        /// The flags controlling how plugins are loaded.
        /// </param>
        /// <param name="findFlags">
        /// The flags controlling how a native Tcl library is located.
        /// </param>
        /// <param name="loadFlags">
        /// The flags controlling how a native Tcl library is loaded.
        /// </param>
        /// <param name="appDomain">
        /// The application domain in which the interpreter is being created, or
        /// null to use the current one.
        /// </param>
        /// <param name="host">
        /// The host to use or clone, or null to create a new default host.
        /// </param>
        /// <param name="profile">
        /// The name of the host profile to use, or null for none.
        /// </param>
        /// <param name="owner">
        /// An object reserved for use as the owner of the interpreter, or null if
        /// not needed.
        /// </param>
        /// <param name="applicationObject">
        /// An object reserved for use by the application, or null if not needed.
        /// </param>
        /// <param name="policyObject">
        /// An object reserved for use by custom policies, or null if not needed.
        /// </param>
        /// <param name="resolverObject">
        /// An object reserved for use by custom resolvers, or null if not needed.
        /// </param>
        /// <param name="userObject">
        /// An object reserved for use by the user, or null if not needed.
        /// </param>
        /// <param name="runtimeOptions">
        /// The collection of runtime options for the interpreter, or null for
        /// none.
        /// </param>
        /// <param name="text">
        /// The "pre-init" (post-setup) script to evaluate, if any.
        /// </param>
        /// <param name="libraryPath">
        /// The location of the script library, or null to use the default.
        /// </param>
        /// <param name="autoPathList">
        /// Extra directories to search for packages, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing the problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PreSetup(
            IRuleSet ruleSet,
            string culture,
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            InitializeFlags initializeFlags,
            DataFlags dataFlags,
            ScriptFlags scriptFlags,
            InterpreterFlags interpreterFlags,
            InterpreterTestFlags interpreterTestFlags,
            PluginFlags pluginFlags,
#if NATIVE && TCL
            FindFlags findFlags,
            LoadFlags loadFlags,
#endif
            AppDomain appDomain,
            IHost host,
            string profile,
            object owner,
            object applicationObject,
            object policyObject,
            object resolverObject,
            object userObject,
            ClientDataDictionary runtimeOptions,
            string text,
            string libraryPath,
            StringList autoPathList,
            ref Result result
            )
        {
            #region Thread Affinity / AppDomain Identity
            //
            // NOTE: Keep track of the thread that this interpreter was created on.
            //
            this.PrivateThread = Thread.CurrentThread;
            this.PrivateThreadId = GlobalState.GetCurrentSystemThreadId();
            this.ManagedThreadId = GlobalState.GetCurrentManagedThreadId();
            this.NativeThreadId = GlobalState.GetCurrentNativeThreadId();
            this.PrivateVariableEvent = ThreadOps.CreateEvent(false);
            this.PrivateSetupEvent = ThreadOps.CreateEvent(false);

#if NATIVE
            //
            // HACK: On platforms where the native printf-based double formatting
            //       would not work by default (e.g. macOS on arm64, without the
            //       optional Bolt helper library), unset UsePrintfForDouble flag
            //       so the managed fallback is always used.
            //
            if (FlagOps.HasFlags(interpreterFlags,
                    InterpreterFlags.UsePrintfForDouble, true) &&
                !NativeOps.ShouldUsePrintfForDouble())
            {
                interpreterFlags &= ~InterpreterFlags.UsePrintfForDouble;
            }
#endif

            //
            // HACK: Disable any "implicit" use of the Thread.Abort() method, i.e.
            //       when there are no "noAbort" arguments or other flags in use?
            //
            this.InternalNoThreadAbort = FlagOps.HasFlags(
                interpreterFlags, InterpreterFlags.NoThreadAbort, true);

            //
            // NOTE: What is the rule set used to create / populate this interpreter?
            //
            this.ruleSet = ruleSet;

            //
            // NOTE: What is the application domain for this interpreter?
            //
            this.appDomain = (appDomain != null) ? appDomain : AppDomainOps.GetCurrent();
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Owning Object
            //
            // NOTE: What object is logically the "owner" of this interpreter?
            //
            this.owner = owner;
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Application Integration
            //
            // NOTE: Set the application and user objects now, in case they are necessary
            //       during the later phases of interpreter initialization (e.g. for use
            //       with a custom security policy callback).
            //
            this.applicationObject = applicationObject;
            this.policyObject = policyObject;
            this.resolverObject = resolverObject;
            this.userObject = userObject;
            this.runtimeOptions = runtimeOptions;

            ///////////////////////////////////////////////////////////////////////////////////////////

            //
            // BUGBUG: There is no (longer an) easy way to disable this feature; however,
            //         it can only be used via a Utility method call and is currently not
            //         used.
            //
            this.throwOnFeatureNotSupported = true;
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            #region Status Data
#if WINFORMS
            this.statusThread = null;
            this.statusStartEventName = null;
            this.statusDoneEventName = null;
            this.statusObject = null;
            this.statusCallback = null;
            this.statusLevels = 0;
            this.statusDisposed = 0;
            this.statusIterations = 0;
            this.statusSynchronous = null;
            this.keyEventMap = null;
#endif
            #endregion

            ///////////////////////////////////////////////////////////////////////////////////////////

            //
            // NOTE: We must have a culture and resource manager setup before we do anything
            //       further because they are required to get access to our string resources
            //       (error messages, etc).
            //
            if ((PreSetupCulture(culture, false, ref result) == ReturnCode.Ok) &&
                (PreSetupResourceManager(ref result) == ReturnCode.Ok) &&
                (PreSetupHost(host, hostCreateFlags, profile, ref result) == ReturnCode.Ok) &&
                (PreSetupHostColors(this.host, false, ref result) == ReturnCode.Ok))
            {
                #region Private Properties (Part 1)
                this.PrivateReadOnly = false;
                this.PrivateImmutable = false;
                this.PrivateReadyLimit = DefaultReadyLimit;
                this.PrivateRecursionLimit = DefaultRecursionLimit;
                this.InternalFallbackTimeout = DefaultFallbackTimeout;
                this.PrivateSleepTime = _Public.EventManager.DefaultSleepTime;
                this.PrivateExitCode = ResultOps.SuccessExitCode();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Public Properties
                Interlocked.Exchange(ref this.lockCallback, null);
                Interlocked.Exchange(ref this.lockRetries, 0);
                Interlocked.Exchange(ref this.lockLevel, 1);

                ///////////////////////////////////////////////////////////////////////////////////////

                this.DateTimeFormat = ObjectOps.GetDefaultDateTimeFormat();
                this.DateTimeKind = ObjectOps.GetDefaultDateTimeKind();
                this.DateTimeStyles = ObjectOps.GetDefaultDateTimeStyles();
                this.TimeServers = ObjectOps.GetDefaultTimeServers();

                ///////////////////////////////////////////////////////////////////////////////////////

                this.Quiet = DebugOps.GetDefaultQuiet(DefaultQuiet);
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Private Properties (Part 2)
                if (FlagOps.HasFlags(createFlags, CreateFlags.Safe, true))
                {
                    this.InternalChildLimit = DefaultSafeChildLimit;

#if CALLBACK_QUEUE
                    this.InternalCallbackLimit = DefaultSafeCallbackLimit;
#endif

                    this.InternalIterationLimit = DefaultSafeIterationLimit;
                    this.InternalNamespaceLimit = DefaultSafeNamespaceLimit;
                    this.InternalScopeLimit = DefaultSafeScopeLimit;
                    this.InternalEventLimit = DefaultSafeEventLimit;
                    this.InternalProcedureLimit = DefaultSafeProcedureLimit;
                    this.InternalVariableLimit = DefaultSafeVariableLimit;
                    this.InternalArrayElementLimit = DefaultSafeArrayElementLimit;
                    this.InternalOperationLimit = DefaultSafeOperationLimit;
                    this.InternalCommandLimit = DefaultSafeCommandLimit;
                    this.InternalUnknownLimit = DefaultSafeUnknownLimit;
                    this.InternalDictionaryPairLimit = DefaultSafeDictionaryPairLimit;
                    this.InternalDictionaryNestLimit = DefaultSafeDictionaryNestLimit;
                }
                else
                {
                    this.InternalChildLimit = DefaultUnsafeChildLimit;

#if CALLBACK_QUEUE
                    this.InternalCallbackLimit = DefaultUnsafeCallbackLimit;
#endif

                    this.InternalIterationLimit = DefaultUnsafeIterationLimit;
                    this.InternalNamespaceLimit = DefaultUnsafeNamespaceLimit;
                    this.InternalScopeLimit = DefaultUnsafeScopeLimit;
                    this.InternalEventLimit = DefaultUnsafeEventLimit;
                    this.InternalProcedureLimit = DefaultUnsafeProcedureLimit;
                    this.InternalVariableLimit = DefaultUnsafeVariableLimit;
                    this.InternalArrayElementLimit = DefaultUnsafeArrayElementLimit;
                    this.InternalOperationLimit = DefaultUnsafeOperationLimit;
                    this.InternalCommandLimit = DefaultUnsafeCommandLimit;
                    this.InternalUnknownLimit = DefaultUnsafeUnknownLimit;
                    this.InternalDictionaryPairLimit = DefaultUnsafeDictionaryPairLimit;
                    this.InternalDictionaryNestLimit = DefaultUnsafeDictionaryNestLimit;
                }

                ///////////////////////////////////////////////////////////////////////////////////////

#if RESULT_LIMITS
                if (FlagOps.HasFlags(createFlags, CreateFlags.Safe, true))
                {
                    this.InternalExecuteResultLimit = DefaultSafeExecuteResultLimit;
                    this.InternalNestedResultLimit = DefaultSafeNestedResultLimit;
                }
                else
                {
                    this.InternalExecuteResultLimit = DefaultUnsafeExecuteResultLimit;
                    this.InternalNestedResultLimit = DefaultUnsafeNestedResultLimit;
                }
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Timeouts
                MaybeInitializeTimeouts(false);
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Script Bundles
#if DATA
                bundleManager = new BundleManager();
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Script Library Pre-Initialization
                preInitializeText = text;
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Script Library Paths
                this.libraryPath = libraryPath;
                this.autoPathList = autoPathList;
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Script Library Miscellaneous
                preSetup = false;
                setup = false;
                initialized = false;
                initializedPath = null;

#if SHELL
                initializedShell = false;
                initializedShellPath = null;
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

                InitializeAndGetTrustedPaths();
                InitializeAndGetTrustedUris();
                InitializeAndGetTrustedTypes();
                InitializeAndGetTrustedHashes();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Flags
                this.createFlags = createFlags;
                this.defaultCreateFlags = CreateFlags.NestedUse; /* [interp create] */
                this.hostCreateFlags = hostCreateFlags;
                this.defaultHostCreateFlags = HostCreateFlags.NestedUse; /* [interp create] */
                this.initializeFlags = initializeFlags;
                this.defaultInitializeFlags = Defaults.InitializeFlags;
                this.dataFlags = dataFlags;
                this.scriptFlags = scriptFlags;
                this.defaultScriptFlags = Defaults.ScriptFlags;
                this.interpreterFlags = interpreterFlags;
                this.defaultInterpreterFlags = Defaults.InterpreterFlags;
                this.interpreterTestFlags = interpreterTestFlags;
                this.defaultInterpreterTestFlags = Defaults.InterpreterTestFlags;
                this.interpreterStateFlags = Defaults.InterpreterStateFlags;
                this.optionBehaviorFlags = Defaults.OptionBehaviorFlags;

                ///////////////////////////////////////////////////////////////////////////////////////

#if SHELL
                this.interactiveLoopFlags = Defaults.InteractiveLoopFlags;
                this.promptFlags = Defaults.PromptFlags;
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

                this.pluginFlags = pluginFlags;

                ///////////////////////////////////////////////////////////////////////////////////////

#if ENTERPRISE_LOCKDOWN || MAYBE_ENTERPRISE_LOCKDOWN
                if (IsEnterpriseLockdownEnabled())
                    EnforceLockdownForPlugins();
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

#if ISOLATED_PLUGINS
                if (FlagOps.HasFlags(createFlags, CreateFlags.IsolatePlugins, true))
                    EnablePluginIsolation();

                if (FlagOps.HasFlags(createFlags, CreateFlags.NoPluginPreview, true))
                    DisablePluginPreview();
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

                this.defaultPluginFlags = Defaults.PluginFlags;

                ///////////////////////////////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(createFlags, CreateFlags.NoDispose, true))
                {
                    /* IGNORED */
                    SetDisposalEnabled(false);
                }

                ///////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
                string value = GlobalConfiguration.GetValue(
                    EnvVars.CacheFlags, ConfigurationFlags.Interpreter);

                if (!String.IsNullOrEmpty(value))
                {
                    cacheFlags = CacheFlags.Default;

                    object enumValue;
                    Result localError = null;

                    enumValue = EnumOps.TryParseFlags(
                        this, typeof(CacheFlags),
                        cacheFlags.ToString(), value,
                        InternalCultureInfo, true, true,
                        true, ref localError);

                    if (enumValue is CacheFlags)
                    {
                        cacheFlags = (CacheFlags)enumValue;
                    }
                    else
                    {
                        DebugOps.Complain(
                            this, ReturnCode.Error, localError);
                    }
                }
                else
                {
                    cacheFlags = CacheFlags.Default;
                }
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

                existVariableFlags = VariableFlags.None;
                getVariableFlags = VariableFlags.None;
                setVariableFlags = VariableFlags.None;
                resetVariableFlags = VariableFlags.None;
                unsetVariableFlags = VariableFlags.None;
                addVariableFlags = VariableFlags.None;
                systemArrayVariableFlags = VariableFlags.None;

                ///////////////////////////////////////////////////////////////////////////////////////

                pathComparisonType = PathComparisonType.Default;
                packageIndexFlags = PackageIndexFlags.AutoPath; /* TODO: Good default? */

#if APPDOMAINS || ISOLATED_INTERPRETERS || ISOLATED_PLUGINS
                if (FlagOps.HasFlags(createFlags, CreateFlags.ProbePlugins, true))
                    packageIndexFlags |= PackageIndexFlags.Plugin;
#endif

                packageIfNeededFlags = PackageIfNeededFlags.Default;

                ///////////////////////////////////////////////////////////////////////////////////////

                eventVariableFlags = VariableFlags.None;
                eventWaitFlags = EventWaitFlags.Default;
                readyFlags = ReadyFlags.None;
                engineFlags = EngineFlags.None;
                substitutionFlags = SubstitutionFlags.Default;
                expressionFlags = ExpressionFlags.Default;

                ///////////////////////////////////////////////////////////////////////////////////////

                afterEventFlags = EventFlags.After;
                engineEventFlags = EventFlags.Engine;
                queueEventFlags = EventFlags.Queue;
                serviceEventFlags = EventFlags.Service;
                updateEventFlags = EventFlags.Wait;
                waitEventFlags = EventFlags.Wait;

                ///////////////////////////////////////////////////////////////////////////////////////

                updateFlags = UpdateFlags.Default;

                ///////////////////////////////////////////////////////////////////////////////////////

#if DEBUGGER || SHELL
                headerFlags = HeaderFlags.Invalid;
                detailFlags = DetailFlags.Invalid;
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

#if SHELL && INTERACTIVE_COMMANDS
                interactiveCommandsEnabled = true; // COMPAT: Eagle beta.
                interactiveEngineFlags = EngineFlags.None;
                interactiveSubstitutionFlags = SubstitutionFlags.None;
                interactiveEventFlags = EventFlags.None;
                interactiveExpressionFlags = ExpressionFlags.None;
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

                newGlobalVariableFlags = VariableFlags.None;
                newLocalVariableFlags = VariableFlags.None;

                ///////////////////////////////////////////////////////////////////////////////////////

                packageFlags = PackageFlags.None;
                procedureFlags = ProcedureFlags.None;

                ///////////////////////////////////////////////////////////////////////////////////////

#if NOTIFY || NOTIFY_OBJECT
                notifyTypes = NotifyType.None;
                notifyFlags = NotifyFlags.None;

                //
                // NOTE: For now, default the "global" notification setting to
                //       enabled.  This can be overridden prior to any "global"
                //       notifications being fired by changing this setting
                //       from the "init" script or by using the NoGlobalNotify
                //       flag.
                //
                notify = !FlagOps.HasFlags(
                    createFlags, CreateFlags.NoGlobalNotify, true) ? 1 : 0;
#endif

                ///////////////////////////////////////////////////////////////////////////////////////

#if NATIVE && TCL
                this.tclFindFlags = findFlags;
                this.defaultTclFindFlags = Defaults.FindFlags;

                ///////////////////////////////////////////////////////////////////////////////////////

                this.tclLoadFlags = loadFlags;
                this.defaultTclLoadFlags = Defaults.LoadFlags;

                ///////////////////////////////////////////////////////////////////////////////////////

                tclCommandUnloadFlags = UnloadFlags.Default;
                tclExitUnloadFlags = UnloadFlags.None;

                ///////////////////////////////////////////////////////////////////////////////////////

                this.PrivateTclReadOnly = FlagOps.HasFlags(loadFlags, LoadFlags.ReadOnly, true);
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Plugin Tokens
                corePluginToken = 0;

#if NOTIFY || NOTIFY_OBJECT
                objectPluginToken = 0;

#if TEST
                scriptNotifyPluginToken = 0;
#endif
#endif

#if NOTIFY && NOTIFY_ARGUMENTS
                monitorPluginToken = 0;
#endif

#if TEST_PLUGIN || DEBUG
                testPluginToken = 0;
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Core Entities
                //
                // NOTE: How many discrete operations have been executed?
                //
                Interlocked.Exchange(ref operationCount, 0);

                //
                // NOTE: How many commands have been executed?
                //
                Interlocked.Exchange(ref commandCount, 0);

                //
                // NOTE: How many times has the [unknown] script been executed?
                //
                Interlocked.Exchange(ref unknownCount, 0);

                //
                // NOTE: How many readiness checks have been executed?
                //
                Interlocked.Exchange(ref readyCount, 0);

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Packages
                packageAliases = new PackageAliasDictionary();
                packageIndexes = new PackageIndexDictionary();
                packages = new PackageWrapperDictionary();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Error Handling
                backgroundError = TclVars.Command.BackgroundError;
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Unknown Handling
                unknownCallback = null;
                unknown = TclVars.Command.Unknown; /* BUGFIX: Must be before PreSetupNamespaces. */
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Package Handling
                packageFallback = null;
                packageUnknown = TclVars.Command.PackageUnknown;
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Namespaces
                PreSetupNamespaces(InternalAreNamespacesEnabled(), true, false);
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Core Extensibility
                pluginArguments = new StringDictionary();
                plugins = new PluginWrapperDictionary();
                commands = new CommandWrapperDictionary();
                savedCommands = new CommandWrapperDictionary();
                hiddenCommands = new CommandWrapperDictionary();
                savedHiddenCommands = new CommandWrapperDictionary();
                policies = new PolicyWrapperDictionary();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Executable Objects
                procedures = new ProcedureWrapperDictionary();
                hiddenProcedures = new ProcedureWrapperDictionary();

                #region Dead Code
#if DEAD_CODE
                lambdas = new LambdaWrapperDictionary();
#endif
                #endregion

                executes = new ExecuteWrapperDictionary();
                savedExecutes = new ExecuteWrapperDictionary();
                hiddenExecutes = new ExecuteWrapperDictionary();
                savedHiddenExecutes = new ExecuteWrapperDictionary();
                operators = new OperatorWrapperDictionary();
                operatorCache = new IOperator[(int)Lexeme.Maximum + 1];
                functions = new FunctionWrapperDictionary();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Event Manager
                //
                // NOTE: Create the event manager now.
                //
                eventManager = new EventManager(this);

                //
                // NOTE: How many events have been processed?
                //
                eventCount = 0;

#if NATIVE && TCL
                //
                // NOTE: How many native Tcl events have been processed?
                //
                tclEventCount = 0;
                tclSleepCount = 0;
#endif

                //
                // NOTE: Initialize the count of pending wait calls to zero.
                //
                waitCount = 0;

                //
                // NOTE: How many times have we waited for an event (in WaitVariable)?
                //
                waitSpinCount = 0;
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Variables
                missingVariableValue = null;
                missingVariableDirty = true;
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Variable Traces
                traces = new TraceWrapperDictionary();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Variable Scopes
                scopes = new CallFrameDictionary();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Snippets
                snippets = new SnippetDictionary();
                #endregion
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region CLR Integration
                binder = new ScriptBinder(
                    this, null, FlagOps.HasFlags(createFlags,
                    CreateFlags.NoDefaultBinder, true), this.Debug);

                createInstanceBindingFlags =
                    ObjectOps.GetBindingFlags(
                        MetaBindingFlags.PublicCreateInstance, true);

                objects = new ObjectWrapperDictionary();
                aliases = new AliasWrapperDictionary();
                newAliasFlags = AliasFlags.None;
                callbacks = new CallbackDictionary();

                ///////////////////////////////////////////////////////////////////////////////////////

                objectTypes = new StringDictionary();

                ///////////////////////////////////////////////////////////////////////////////////////

                ObjectOps.GetNamespaces(this, out objectNamespaces);

                ///////////////////////////////////////////////////////////////////////////////////////

                objectInterfaces = new TypePairDictionary<string, long>();
                objectAliasNamespaces = new StringDictionary();

                ///////////////////////////////////////////////////////////////////////////////////////

                pluginBaseDirectory = null;

                ///////////////////////////////////////////////////////////////////////////////////////

                #region XML Integration
#if XML
                if (FlagOps.HasFlags(createFlags, CreateFlags.Safe, true))
                    retryXml = XmlErrorTypes.SafeInterpreter;
                else
                    retryXml = XmlErrorTypes.UnsafeInterpreter;

                validateXml = false;
                relaxedXml = false;
                allXml = false;
#endif
                #endregion
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Interpreters
                parentInterpreter = null;
                childName = null;

#if APPDOMAINS && ISOLATED_INTERPRETERS
                childAppDomainName = null;
#endif

                childInterpreters = new InterpreterDictionary();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Other Entities
#if DATA
                connections = new DbConnectionDictionary();
                transactions = new DbTransactionDictionary();
#endif

#if CALLBACK_QUEUE
                callbackQueue = new CallbackQueue();
#endif

#if APPDOMAINS
                appDomains = new AppDomainDictionary();
#endif

#if NATIVE && TCL
                lock (tclSyncRoot) // NOTE: Pedantic.
                {
                    tclInterps = new IntPtrDictionary();

#if TCL_THREADS
                    tclThreads = new TclThreadDictionary();
#endif

                    tclBridges = new TclBridgeDictionary();
                }
#endif

#if EMIT && NATIVE && LIBRARY
                modules = new ModuleWrapperDictionary();
                delegates = new DelegateWrapperDictionary();
#endif

                cleanupPaths = new PathDictionary<CleanupPathClientData>();
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Random Number Generators
                if (!FlagOps.HasFlags(createFlags, CreateFlags.NoRandom, true))
                {
                    provideEntropy = null;
                    randomNumberGenerator = RNGCryptoServiceProvider.Create();
                    random = new Random(); /* EXEMPT */

                    ///////////////////////////////////////////////////////////////////////////////////
                    //
                    // NOTE: Prepare entropy buffers for use by various script commands,
                    //       e.g. the [info context] sub-command.  Different buffers are
                    //       used for "safe" and "unsafe" modes.  In spite of that fact,
                    //       these buffers are NOT considered to be a security feature.
                    //
                    entropy = new byte[DefaultEntropySize];

                    /* NO RESULT */
                    GetRandomBytes(ref entropy);

                    ///////////////////////////////////////////////////////////////////////////////////

                    safeEntropy = new byte[DefaultEntropySize];

                    /* NO RESULT */
                    GetRandomBytes(ref safeEntropy);
                }
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Object Identifiers
#if RANDOMIZE_ID
                //
                // NOTE: If possible, randomize the starting Id for objects.
                //
                nextId = (random != null) ? Math.Abs(random.Next()) : 0;
#else
                nextId = 0;
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Channels & Encodings
                channels = new ChannelDictionary();

                //
                // NOTE: Initialize the "well-known" encodings.
                //
                encodings = new EncodingDictionary(new _Comparers.StringCustom(
                    SharedStringOps.GetSystemComparisonType(true)));

                encodings.Add(StringOps.NullEncodingName, null);

                encodings.Add(StringOps.BinaryEncodingName,
                    StringOps.GetEncoding(EncodingType.Binary));

                encodings.Add(StringOps.ChannelEncodingName,
                    StringOps.GetEncoding(EncodingType.Channel));

                encodings.Add(StringOps.DefaultEncodingName,
                    StringOps.GetEncoding(EncodingType.Default));

                encodings.Add(StringOps.SystemEncodingName,
                    StringOps.GetEncoding(EncodingType.System));

                encodings.Add(StringOps.TclEncodingName,
                    StringOps.GetEncoding(EncodingType.Tcl));

                encodings.Add(StringOps.TextEncodingName,
                    StringOps.GetEncoding(EncodingType.Text));

                encodings.Add(StringOps.ScriptEncodingName,
                    StringOps.GetEncoding(EncodingType.Script));

                encodings.Add(StringOps.XmlEncodingName,
                    StringOps.GetEncoding(EncodingType.Xml));

                encodings.Add(StringOps.SnippetEncodingName,
                    StringOps.GetEncoding(EncodingType.Snippet));

                encodings.Add(IdentityEncoding.webName, IdentityEncoding.Identity);
                encodings.Add(OneByteEncoding.webName, OneByteEncoding.OneByte);
                encodings.Add(TwoByteEncoding.webName, TwoByteEncoding.TwoByte);
                encodings.Add(TclEncoding.webName, TclEncoding.Tcl);
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Static Lock Held
                lock (staticSyncRoot)
                {
#if NATIVE
                    #region Native Stack Checking
                    RuntimeOps.MaybeInitializeStackChecking();
                    #endregion
#endif

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Cache Settings
#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
                    InitializeCaches(false);
#endif
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Context Manager (Threaded Only)
#if THREADING
                    ContextManager.Initialize();
#endif
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Native Tcl/Tk Integration Data
#if NATIVE && TCL
                    #region Transfer Global Tcl/Tk Integration Data
                    MaybeTransferFromTclPurgatory();
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Re-Initialize Global Tcl/Tk Integration Data
                    MaybeInitializeTclPurgatory();
                    #endregion
#endif
                    #endregion
                }
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Cached Entities
#if ARGUMENT_CACHE || LIST_CACHE || PARSE_CACHE || EXECUTE_CACHE || TYPE_CACHE || COM_TYPE_CACHE
                //
                // HACK: When an interpreter is being created for use by an
                //       SDK subsystem, skip initializing the caches.
                //
                if (!PrivateIsSdk(SdkType.AnySdkMask, createFlags, false))
                {
                    /* IGNORED */
                    Interlocked.Increment(ref cacheGeneration);

                    /* IGNORED */
                    PreSetupCaches();
                }

                ///////////////////////////////////////////////////////////////////////////////////////

#if CACHE_DICTIONARY
                /* IGNORED */
                SetPropertiesOnCaches();
#endif
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Context Manager (Threaded Only)
#if THREADING
                //
                // NOTE: This must be done AFTER the static Initialize method
                //       of the ContextManager class has been called (above).
                //
                contextManager = new ContextManager(this);

                ResetDisposeContextCounts();
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Variable Context Members (Non-Threaded Only)
#if !THREADING
                PreSetupCallFramesPhase1();

                ///////////////////////////////////////////////////////////////////////////////////////

                PreSetupCallFramesPhase2();
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Command & Variable Resolvers
                //
                // NOTE: For now, just add the core resolver.  This must refer
                //       to the "CurrentGlobalFrame" property so that it gets
                //       created now, if necessary.
                //
                resolvers = new List<IResolve>(new IResolve[] {
                    RuntimeOps.NewResolver(this, CurrentGlobalFrame, globalNamespace, createFlags)
                });
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Engine Context Members
                GlobalCancel = false;
                GlobalUnwind = false;
                GlobalHalt = false;

                GlobalCancelResult = null;
                GlobalHaltResult = null;
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Engine Context Members (Non-Threaded Only)
#if !THREADING
                ContextClientData = null;

                InternalLevels = 0;
                MaximumLevels = 0;

                ParserLevels = 0;
                MaximumParserLevels = 0;

                ExpressionLevels = 0;
                EntryExpressionLevels = 0;
                MaximumExpressionLevels = 0;

                PreviousLevels = 0;
                CatchLevels = 0;
                UnknownLevels = 0;
                TraceLevels = 0;
                SubCommandLevels = 0;
                SettingLevels = 0;
                PackageLevels = 0;
                PackageIndexLevels = 0;

#if ARGUMENT_CACHE
                CacheArgument = Argument.InternalCreate();
#endif

#if DEBUGGER
                WatchpointLevels = 0;
#endif

#if NOTIFY || NOTIFY_OBJECT
                NotifyLevels = 0;
                NotifyTypes = NotifyType.None;
                NotifyFlags = NotifyFlags.None;
#endif

                SecurityLevels = 0;
                PolicyLevels = 0;
                TestLevels = 0;

                CommandInitialDecision = PolicyDecision.None;
                ScriptInitialDecision = PolicyDecision.None;
                FileInitialDecision = PolicyDecision.None;
                StreamInitialDecision = PolicyDecision.None;

                CommandFinalDecision = PolicyDecision.None;
                ScriptFinalDecision = PolicyDecision.None;
                FileFinalDecision = PolicyDecision.None;
                StreamFinalDecision = PolicyDecision.None;

                ReadyTimeout = null;

#if DEBUGGER
                IsDebuggerExiting = false;
#endif

                StackOverflow = false;

#if DEBUGGER
                Debugger = null;
                InteractiveLoopCallback = null;
#endif

#if SHELL
                PreviewArgumentCallback = null;
                UnknownArgumentCallback = null;
                EvaluateScriptCallback = null;
                EvaluateFileCallback = null;
                EvaluateEncodedFileCallback = null;
#endif

#if PREVIOUS_RESULT
                PreviousResult = null;
#endif

                LastError = null;
                SharedEngineFlags = EngineFlags.None;

                ParseState = null;

                ReturnCode = ReturnCode.Ok;

                ErrorLine = 0;
                ErrorCode = null;
                ErrorInfo = null;
                ErrorFrames = 0;
                Exception = null;

                ManualScriptLocation = null;
                ScriptLocations = new ScriptLocationList();

                PreviousProcessId = 0;

                ArraySearches = new ArraySearchDictionary();

#if HISTORY
                HistoryEngineFilter = null;
                _History = new ClientDataList();
#endif

                Complaint = null;
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Interactive Non-Context Members
#if SHELL
                pausedInteractiveLoops = new LongLongDictionary();
                globalInteractiveLoops = 0;
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Interactive Context Members (Non-Threaded Only)
#if !THREADING
                // Interactive = false; // HACK: *SPECIAL* Setup() only.
                InteractiveScriptLevels = 0;
                InteractiveInputEnabled = MaybeEnableType.False;
                InteractiveInputBuffer = null;
                InteractiveInput = null;
                PreviousInteractiveInput = null;
                InteractiveMode = null;

                ///////////////////////////////////////////////////////////////////////////////////////

                // ActiveInteractiveLoops = 0; // HACK: *SPECIAL* Setup() only.
                TotalInteractiveLoops = 0;
                TotalInteractiveInputs = 0;

                ///////////////////////////////////////////////////////////////////////////////////////

#if SHELL
                SavedShellArguments = null;
                ShellArguments = null;
                ShellCallbackData = null;
                InteractiveLoopData = null;
                UpdateData = null;
#endif

                InteractiveCommandCallback = null;

                ///////////////////////////////////////////////////////////////////////////////////////

#if HISTORY
                HistoryLoadData = null;
                HistorySaveData = null;

                HistoryInfoFilter = null;
                HistoryLoadFilter = null;
                HistorySaveFilter = null;

                HistoryFileName = null;
#endif
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Test Context Members (Non-Threaded Only)
#if !THREADING
                //
                // NOTE: Initialize the test related data.
                //
                TestTargetInterpreter = null;
                TestStatistics = new long[(int)TestInformationType.SizeOf];
                TestConstraints = new StringList();
                TestKnownBugs = new IntDictionary();
                TestSkipped = new StringListDictionary();
                TestFailures = new StringList();
                TestCounts = new IntDictionary();
                TestMatch = new StringList(); /* TODO: Should this default to all (*)? */
                TestSkip = new StringList();
                TestReturnCodeMessages = TestOps.GetReturnCodeMessages();

#if DEBUGGER
                TestBreakpoints = new StringDictionary();
#endif

                TestHooks = new StringDictionary();
                TestComparer = null;
                TestPath = null;
                TestVerbose = TestOutputType.Default;
                TestRepeatCount = Count.Invalid;
                TestPrevious = null;
                TestCurrent = null;
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                #region Interactive Loop Members
#if SHELL
                interactiveLoopSemaphore = ThreadOps.CreateSemaphore(1, 1);
                interactiveLoopDoneEvent = ThreadOps.CreateEvent(false);
#endif
                #endregion

                ///////////////////////////////////////////////////////////////////////////////////////

                preSetup = true;
                return ReturnCode.Ok;
            }

            return ReturnCode.Error;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Setup
#if SHELL
        /// <summary>
        /// This method determines whether the specified interpreter flags
        /// indicate that the interpreter is intended for use by the shell.
        /// </summary>
        /// <param name="interpreterFlags">
        /// The interpreter flags to examine.
        /// </param>
        /// <returns>
        /// True if the interpreter is intended for shell use; otherwise,
        /// false.
        /// </returns>
        private static bool IsForShellUse(
            InterpreterFlags interpreterFlags
            )
        {
            /* EXEMPT */
            return FlagOps.HasFlags(interpreterFlags,
                InterpreterFlags.ForShellUse, true);
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if DEBUGGER
        /// <summary>
        /// This method sets up the host used by the script debugger associated
        /// with the interpreter.
        /// </summary>
        /// <param name="host">
        /// The host to use for the debugger, or null for none.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupDebuggerHost(
            IHost host,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // NOTE: If this interpreter has no debugger then we
                //       can simply do nothing.
                //
                IDebugger debugger = this.Debugger;

                if (debugger != null)
                {
                    //
                    // NOTE: Extract the isolated debugger interpreter
                    //       and check its validity.
                    //
                    Interpreter debugInterpreter = debugger.Interpreter;

                    if (debugInterpreter != null)
                    {
                        try
                        {
                            //
                            // NOTE: If the provided host is valid, clone it
                            //       into the isolated debugger interpreter;
                            //       otherwise, just use the provided null
                            //       value (i.e. if the parent interpreter
                            //       does not have a valid host then the
                            //       isolated debugger interpreter should not
                            //       have one either).
                            //
                            IHost newHost = (host != null) ?
                                host.Clone(debugInterpreter) : null;

                            //
                            // NOTE: Set the host for the isolated debugger
                            //       interpreter (may be null).
                            //
                            debugInterpreter.Host = newHost;

                            //
                            // BUGFIX: There is no need to call SetupHostChannels
                            //         here for the debug interpreter because that
                            //         should have been automatically in response
                            //         to the above host reassignment.
                            //
                            return ReturnCode.Ok;
                        }
                        catch (Exception e)
                        {
                            error = e;
                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        //
                        // NOTE: Ok, the debugger interpreter is not available.
                        //       This is not an error.
                        //
                        return ReturnCode.Ok;
                    }
                }
                else
                {
                    //
                    // NOTE: Ok, the debugger is not available.  This is not
                    //       an error.
                    //
                    return ReturnCode.Ok;
                }
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method sets up the core lists of variable traces used by the
        /// interpreter, optionally forcing them to be recreated.
        /// </summary>
        /// <param name="plugin">
        /// The plugin associated with the traces being added, or null for
        /// none.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the traces, or null for none.
        /// </param>
        /// <param name="force">
        /// Non-zero to force the trace lists to be recreated even if they
        /// already exist.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupTraceLists(
            IPlugin plugin,
            IClientData clientData,
            bool force,
            ref Result error /* NOT USED */
            )
        {
            if (force || (autoPathTraceList == null))
            {
                autoPathTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { AutoPathTraceCallback });
            }

            if (force || (environmentTraceList == null))
            {
                environmentTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { EnvironmentTraceCallback });
            }

            if (force || (enumerableVariableTraceList == null))
            {
                enumerableVariableTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { EnumerableVariableTraceCallback });
            }

            if (force || (linkedVariableTraceList == null))
            {
                linkedVariableTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { LinkedVariableTraceCallback });
            }

            if (force || (systemArrayTraceList == null))
            {
                systemArrayTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { SystemArrayTraceCallback });
            }

            if (force || (objectTraceList == null))
            {
                objectTraceList = new TraceList(
                    clientData, TraceFlags.Global, plugin,
                    new TraceCallback[] { ObjectTraceCallback });
            }

            if (force || (precisionTraceList == null))
            {
                precisionTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { PrecisionTraceCallback });
            }

            if (force || (testsTraceList == null))
            {
                testsTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { TestsTraceCallback });
            }

#if DATA
            if (force || (dbTraceList == null))
            {
                dbTraceList = new TraceList(
                    clientData, TraceFlags.None, plugin,
                    new TraceCallback[] { DbTraceCallback });
            }
#endif

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified variable traces to the interpreter.
        /// </summary>
        /// <param name="traces">
        /// The list of variable traces to add, or null for none.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the traces, or null for none.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupTraces(
            TraceList traces,
            IClientData clientData,
            ref Result error
            )
        {
            if (traces != null)
            {
                foreach (ITrace trace in traces)
                {
                    Result localResult = null;

                    if (AddTrace(trace, clientData,
                            ref localResult) != ReturnCode.Ok)
                    {
                        error = localResult;
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
            else
            {
                error = "invalid traces";
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method adds the core variable traces to the interpreter, subject
        /// to the specified creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling whether the core traces are added.
        /// </param>
        /// <param name="traces">
        /// The additional list of variable traces to add, or null for none.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupTraces(
            CreateFlags createFlags,
            TraceList traces,
            ref Result error
            )
        {
            if (!FlagOps.HasFlags(
                    createFlags, CreateFlags.NoCoreTraces, true))
            {
                IPlugin plugin = GetCorePlugin(ref error);

                if (plugin == null)
                    return ReturnCode.Error;

                if (SetupTraceLists(
                        plugin, _ClientData.Empty, false,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            ///////////////////////////////////////////////////////////////////

            //
            // NOTE: Setup interpreter wide variable traces now.  Traces
            //       provided by the caller are added first followed by
            //       traces needed for proper operation of features like
            //       core opaque object handle reference counting.
            //
            if (traces != null)
            {
                if (SetupTraces(
                        traces, null, ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            ///////////////////////////////////////////////////////////////////

            if (!FlagOps.HasFlags(
                    createFlags, CreateFlags.NoCoreTraces, true) &&
                (objectTraceList != null))
            {
                if (SetupTraces(
                        objectTraceList, null,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified policies to the interpreter.
        /// </summary>
        /// <param name="policies">
        /// The list of policies to add, or null for none.
        /// </param>
        /// <param name="plugin">
        /// The plugin associated with the policies being added, or null for
        /// none.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the policies, or null for
        /// none.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupPolicies(
            PolicyList policies,
            IPlugin plugin,
            IClientData clientData,
            ref Result error
            )
        {
            if (policies != null)
            {
                foreach (IPolicy policy in policies)
                {
                    if (policy == null)
                        continue;

                    Result localResult = null;

                    if (AddPolicy(
                            policy.Callback, plugin, clientData,
                            ref localResult) != ReturnCode.Ok)
                    {
                        error = localResult;
                        return ReturnCode.Error;
                    }
                }

                return ReturnCode.Ok;
            }
            else
            {
                error = "invalid policies";
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method adds the core policies to the interpreter, subject to the
        /// specified creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling whether the core policies are added.
        /// </param>
        /// <param name="policies">
        /// The additional list of policies to add, or null for none.
        /// </param>
        /// <param name="noCommands">
        /// Non-zero to skip adding the policy-related commands.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupPolicies(
            CreateFlags createFlags,
            PolicyList policies,
            bool noCommands,
            ref Result error
            )
        {
            //
            // NOTE: For "safe" interpreters, setup the interpreter policies
            //       now.  Policies provided by the caller are added first
            //       followed by the policies needed for proper operation of
            //       various features (e.g. script library initialization).
            //
            if (policies != null)
            {
                if (SetupPolicies(
                        policies, null, null,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            ///////////////////////////////////////////////////////////////////

            if (!noCommands && !FlagOps.HasFlags(
                    createFlags, CreateFlags.NoCorePolicies, true))
            {
                PolicyList corePolicies = new PolicyList(
                    PolicyOps.CommandCallbacks);

                if (corePolicies != null)
                {
                    IPlugin plugin = GetCorePlugin(ref error);

                    if (plugin == null)
                        return ReturnCode.Error;

                    if (SetupPolicies(
                            corePolicies, plugin, null,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets up the well-known objects exposed within the
        /// interpreter, subject to the specified creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the objects are set up.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupObjects(
            CreateFlags createFlags,
            ref Result error
            )
        {
            if (!FlagOps.HasFlags(
                    createFlags, CreateFlags.NoObjects, true))
            {
                if (AddNullObject(ref error) != ReturnCode.Ok)
                    return ReturnCode.Error;

                if (!FlagOps.HasFlags(
                        createFlags, CreateFlags.NoVariablesMask, false)) /* EXEMPT */
                {
                    Result result = null;

                    if (SetLibraryVariableValue(
                            VariableFlags.NullMask, Vars.Core.Null,
                            _Object.Null, ref result) != ReturnCode.Ok)
                    {
                        error = result;
                        return ReturnCode.Error;
                    }
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the interpreter has been configured to
        /// skip adding the core variables.
        /// </summary>
        /// <returns>
        /// True if the core variables should not be added; otherwise, false.
        /// </returns>
        private bool PrivateIsNoVariables()
        {
            //
            // NOTE: Assumes lock is already held if needed.
            //
            return FlagOps.HasFlags(
                createFlags, CreateFlags.NoVariablesMask, false);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the value to use for the auto-path variable,
        /// based on the specified list of directories and safety setting.
        /// </summary>
        /// <param name="autoPathList">
        /// The list of directories to include in the auto-path, or null for
        /// none.
        /// </param>
        /// <param name="safe">
        /// Non-zero to compute a value suitable for a "safe" interpreter,
        /// zero for an unsafe one, or null to use the current interpreter
        /// setting.
        /// </param>
        /// <returns>
        /// The computed auto-path value, or null if one cannot be computed.
        /// </returns>
        private string GetAutoPathValue(
            StringList autoPathList,
            bool? safe
            )
        {
            bool localSafe = (safe != null) ?
                (bool)safe : InternalIsSafe();

            if (localSafe)
                return null;

            return (autoPathList != null) ?
                autoPathList.ToString() : null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        // WARNING: Please do not change this method unless you know
        //          exactly how it works.
        //
        /// <summary>
        /// This method sets up the minimum set of variables required by the
        /// interpreter.
        /// </summary>
        /// <param name="autoPathList">
        /// Extra directories to search for packages, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode SetupMinimumVariables(
            StringList autoPathList,
            ref Result result
            )
        {
            //
            // HACK: Even when "NoPlatform" flag is set, always set the
            //       "tcl_platform(engine)" (see TIP #440) array element
            //       because it is required by the [isEagle] core script
            //       library procedure, which is absolutely critical to
            //       proper core script library initialization.
            //
            ReturnCode code = ReturnCode.Ok;

            if (!FlagOps.HasFlags(
                    createFlags, CreateFlags.NoVariables, true)) /* EXEMPT */
            {
                if (code == ReturnCode.Ok)
                {
                    code = SetLibraryVariableValue2( /* LOADER: [isEagle] */
                        VariableFlags.None, TclVars.Platform.Name,
                        TclVars.Platform.Engine, Vars.Package.Name,
                        ref result);
                }

                if ((code == ReturnCode.Ok) && initialized)
                {
                    InitializeFlags localInitializeFlags;

                    lock (syncRoot)
                    {
                        localInitializeFlags = initializeFlags;
                    }

                    code = SetAutoPathList( /* PACKAGE: $::auto_path */
                        autoPathList, FlagOps.HasFlags(localInitializeFlags,
                        InitializeFlags.NoTraceAutoPath, true), FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.IgnoreError, true),
                        ref result);
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method sets up the core variables within the interpreter,
        /// subject to the specified creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the variables are set up.
        /// </param>
        /// <param name="args">
        /// The startup (command-line style) arguments to expose, or null for
        /// none.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat any failure to set up a variable as an error.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode SetupVariables(
            CreateFlags createFlags,
            IEnumerable<string> args,
            bool strict,
            ref Result result
            )
        {
            ReturnCode code = ReturnCode.Ok;

            if (!FlagOps.HasFlags(
                    createFlags, CreateFlags.NoVariablesMask, false)) /* EXEMPT */
            {
                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue(
                        VariableFlags.None, TclVars.Package.VersionName,
                        TclVars.Package.VersionValue, ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue(
                        VariableFlags.None, TclVars.Package.PatchLevelName,
                        TclVars.Package.PatchLevelValue, ref result);

                bool success; /* REUSED */
                ThreadVariable threadVariable; /* REUSED */

                if (code == ReturnCode.Ok)
                {
                    success = false;
                    threadVariable = null;

                    try
                    {
                        threadVariable = ThreadVariable.Create();

                        if (threadVariable != null)
                        {
                            code = threadVariable.AddVariable(
                                this, Engine.ErrorCodeVariableFlags,
                                TclVars.Core.ErrorCode, ref result);

                            if (code == ReturnCode.Ok)
                                success = true;
                        }
                        else
                        {
                            result = String.Format(
                                "could not create thread variable {0}",
                                FormatOps.ErrorVariableName(
                                    TclVars.Core.ErrorCode));

                            code = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        if (!success && (threadVariable != null))
                        {
                            threadVariable.Dispose();
                            threadVariable = null;
                        }
                    }
                }

                if (code == ReturnCode.Ok)
                {
                    success = false;
                    threadVariable = null;

                    try
                    {
                        threadVariable = ThreadVariable.Create();

                        if (threadVariable != null)
                        {
                            code = threadVariable.AddVariable(
                                this, Engine.ErrorInfoVariableFlags,
                                TclVars.Core.ErrorInfo, ref result);

                            if (code == ReturnCode.Ok)
                                success = true;
                        }
                        else
                        {
                            result = String.Format(
                                "could not create thread variable {0}",
                                FormatOps.ErrorVariableName(
                                    TclVars.Core.ErrorInfo));

                            code = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        if (!success && (threadVariable != null))
                        {
                            threadVariable.Dispose();
                            threadVariable = null;
                        }
                    }
                }

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue(
                        VariableFlags.None, TclVars.Core.PrecisionName,
                        TclVars.Expression.DefaultPrecision.ToString(),
                        precisionTraceList, ref result);

                if (code == ReturnCode.Ok)
                    code = AddLibraryVariable(VariableFlags.Array,
                        Vars.Core.Tests, testsTraceList, strict, ref result);

                if (code == ReturnCode.Ok)
                {
                    if (!InternalIsSafe())
                    {
                        if (args != null)
                        {
                            StringList arguments = new StringList(args);

                            if (code == ReturnCode.Ok)
                                code = SetLibraryVariableValue(
                                    VariableFlags.None, TclVars.Core.ShellArgumentCount,
                                    arguments.Count.ToString(), ref result);

                            if (code == ReturnCode.Ok)
                                code = SetLibraryVariableValue(
                                    VariableFlags.None, TclVars.Core.ShellArguments,
                                    arguments.ToString(), ref result);
                        }
                        else if (FlagOps.HasFlags(
                                createFlags, CreateFlags.SetArguments, true))
                        {
                            if (code == ReturnCode.Ok)
                                code = SetLibraryVariableValue(
                                    VariableFlags.None, TclVars.Core.ShellArgumentCount,
                                    Value.ZeroString, ref result);

                            if (code == ReturnCode.Ok)
                                code = SetLibraryVariableValue(
                                    VariableFlags.None, TclVars.Core.ShellArguments,
                                    null, ref result);
                        }

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue(
                                VariableFlags.None, TclVars.Core.ShellArgument0,
                                PathOps.GetExecutableName(), ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue(
                                VariableFlags.None, Vars.Core.WhatIfShellArgumentCount,
                                Value.ZeroString, ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue(
                                VariableFlags.None, Vars.Core.WhatIfShellArguments,
                                null, ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue(
                                VariableFlags.None, TclVars.Core.RunCommandsFileName,
                                TclVars.Path.RunCommands, ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue(
                                VariableFlags.None, TclVars.Core.NonWordCharacters,
                                null, ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue(
                                VariableFlags.None, TclVars.Core.WordCharacters,
                                null, ref result);

                        if (code == ReturnCode.Ok)
                            code = AddLibraryVariable(
                                VariableFlags.None, TclVars.Core.AutoSourcePath,
                                null, strict, ref result);

                        if (code == ReturnCode.Ok)
                            code = AddLibraryVariable(VariableFlags.Array,
                                TclVars.Core.Environment, environmentTraceList, strict,
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = AddLibraryVariable(VariableFlags.Array,
                                Vars.Core.Shell, null, strict, ref result);

                        if (code == ReturnCode.Ok)
                            code = AddLibraryVariable(VariableFlags.Array,
                                Vars.Core.Debugger, null, strict, ref result);

                        if (code == ReturnCode.Ok)
                            code = AddLibraryVariable(VariableFlags.Array,
                                Vars.Core.Paths, null, strict, ref result);

                        if (code == ReturnCode.Ok)
                            code = AddLibraryVariable(VariableFlags.Array,
                                TclVars.Core.AutoIndex, null, strict, ref result);
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the list of available types must be
        /// queried in order to complete setup, based on the specified creation
        /// flags.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the interpreter is created.
        /// </param>
        /// <returns>
        /// True if the type list is required for setup; otherwise, false.
        /// </returns>
        private static bool NeedTypesForSetup(
            CreateFlags createFlags
            )
        {
            if (!ShouldUseBuiltIns(IdentifierKind.Command) && !FlagOps.HasFlags(
                    createFlags, CreateFlags.NoCommands, true))
            {
                TraceOps.DebugTrace(
                    "NeedTypesForSetup: not using built-in commands",
                    typeof(Interpreter).Name, TracePriority.StartupDebug);

                return true;
            }

            if (!ShouldUseBuiltIns(IdentifierKind.Function) && !FlagOps.HasFlags(
                    createFlags, CreateFlags.NoFunctions, true))
            {
                TraceOps.DebugTrace(
                    "NeedTypesForSetup: not using built-in functions",
                    typeof(Interpreter).Name, TracePriority.StartupDebug);

                return true;
            }

            if (!ShouldUseBuiltIns(IdentifierKind.Operator))
            {
                TraceOps.DebugTrace(
                    "NeedTypesForSetup: not using built-in operators",
                    typeof(Interpreter).Name, TracePriority.StartupDebug);

                return true;
            }

            TraceOps.DebugTrace(
                "NeedTypesForSetup: assembly types are not needed",
                typeof(Interpreter).Name, TracePriority.StartupDebug);

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method adds the core functions to the interpreter, querying the
        /// available types as needed.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the functions are set up.
        /// </param>
        /// <param name="useBuiltIn">
        /// Non-zero to add the built-in functions.
        /// </param>
        /// <param name="standardOnly">
        /// Non-zero to add only the functions considered part of the
        /// standard.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to emit verbose diagnostics while adding functions.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupFunctions(
            CreateFlags createFlags,
            bool useBuiltIn,
            bool standardOnly,
            bool verbose,
            ref Result error
            )
        {
            TypeList types = null;
            ResultList errors = null;

            if (!RuntimeOps.GetTypes(
                    verbose, ref types, ref errors))
            {
                error = errors;
                return ReturnCode.Error;
            }

            return SetupFunctions(
                types, createFlags, useBuiltIn, standardOnly,
                verbose, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method adds the core functions to the interpreter, using the
        /// specified list of available types.
        /// </summary>
        /// <param name="types">
        /// The list of available types from which functions are added.
        /// </param>
        /// <param name="createFlags">
        /// The flags controlling how the functions are set up.
        /// </param>
        /// <param name="useBuiltIn">
        /// Non-zero to add the built-in functions.
        /// </param>
        /// <param name="standardOnly">
        /// Non-zero to add only the functions considered part of the
        /// standard.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to emit verbose diagnostics while adding functions.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupFunctions(
            TypeList types,
            CreateFlags createFlags,
            bool useBuiltIn,
            bool standardOnly,
            bool verbose,
            ref Result error
            )
        {
            if (FlagOps.HasFlags(
                    createFlags, CreateFlags.NoFunctions, true))
            {
                return ReturnCode.Ok;
            }

            IPlugin plugin = GetCorePlugin(ref error);

            if (plugin == null)
                return ReturnCode.Error;

            List<IFunctionData> functions = null;

            if (useBuiltIn)
            {
                if (RuntimeOps.GetBuiltInFunctions(
                        plugin, standardOnly, ref functions,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }
            else
            {
                if (RuntimeOps.GetPluginFunctions(
                        plugin, types, standardOnly,
                        verbose, ref functions,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            foreach (IFunctionData functionData in functions)
            {
                if (functionData == null)
                    continue;

                if (useBuiltIn)
                    functionData.Flags |= FunctionFlags.NoAttributes;

                IFunction function = null;
                Result localResult; /* REUSED */

                localResult = null;

                if (RuntimeOps.CreateFunction(functionData,
                        ref function, ref localResult) != ReturnCode.Ok)
                {
                    error = localResult;
                    return ReturnCode.Error;
                }

                localResult = null;

                if (AddFunction(
                        function, null, ref localResult) != ReturnCode.Ok)
                {
                    error = localResult;
                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the operator flags to use when adding operators,
        /// based on the specified creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the interpreter is created.
        /// </param>
        /// <param name="operatorFlags">
        /// Upon return, this is set to the computed operator flags, or null if
        /// none are needed.
        /// </param>
        private static void SetupOperatorFlags(
            CreateFlags createFlags,
            out OperatorFlags? operatorFlags
            )
        {
            operatorFlags = null;

            if (FlagOps.HasFlags(
                    createFlags, CreateFlags.SecuritySdk, true))
            {
                operatorFlags = OperatorFlags.SecurityMask;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the core operators to the interpreter, using the
        /// specified list of available types and flags.
        /// </summary>
        /// <param name="types">
        /// The list of available types from which operators are added.
        /// </param>
        /// <param name="createFlags">
        /// The flags controlling how the operators are set up.
        /// </param>
        /// <param name="interpreterFlags">
        /// The interpreter flags in effect while adding operators.
        /// </param>
        /// <param name="pluginFlags">
        /// The flags controlling how plugins are loaded.
        /// </param>
        /// <param name="operatorFlags">
        /// The operator flags controlling which operators are added, or null
        /// for none.
        /// </param>
        /// <param name="useBuiltIn">
        /// Non-zero to add the built-in operators.
        /// </param>
        /// <param name="standardOnly">
        /// Non-zero to add only the operators considered part of the
        /// standard.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to emit verbose diagnostics while adding operators.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupOperators(
            TypeList types,
            CreateFlags createFlags,
            InterpreterFlags interpreterFlags,
            PluginFlags pluginFlags,
            OperatorFlags? operatorFlags,
            bool useBuiltIn,
            bool standardOnly,
            bool verbose,
            ref Result error
            )
        {
            if (FlagOps.HasFlags(
                    createFlags, CreateFlags.NoOperators, true))
            {
                return ReturnCode.Ok;
            }

            IPlugin plugin = GetCorePlugin(ref error);

            if (plugin == null)
                return ReturnCode.Error;

            List<IOperatorData> operators = null;

            if (useBuiltIn)
            {
                if (RuntimeOps.GetBuiltInOperators(
                        plugin, StringOps.GetComparisonType(
                            interpreterFlags, false),
                        standardOnly, ref operators,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }
            else
            {
                if (RuntimeOps.GetPluginOperators(
                        plugin, types, StringOps.GetComparisonType(
                            interpreterFlags, false),
                        standardOnly, verbose, ref operators,
                        ref error) != ReturnCode.Ok)
                {
                    return ReturnCode.Error;
                }
            }

            foreach (IOperatorData operatorData in operators)
            {
                if (operatorData == null)
                    continue;

                if ((operatorFlags != null) && !FlagOps.HasFlags(
                        operatorData.Flags, (OperatorFlags)operatorFlags,
                        false))
                {
                    continue;
                }

                if (useBuiltIn)
                    operatorData.Flags |= OperatorFlags.NoAttributes;

                IOperator @operator = null;
                Result localResult; /* REUSED */

                localResult = null;

                if (RuntimeOps.CreateOperator(operatorData,
                        ref @operator, ref localResult) != ReturnCode.Ok)
                {
                    error = localResult;
                    return ReturnCode.Error;
                }

                localResult = null;

                if (AddOperator(
                        @operator, null, ref localResult) != ReturnCode.Ok)
                {
                    error = localResult;
                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets up the standard input, output, and error channels
        /// using the specified stream host.
        /// </summary>
        /// <param name="streamHost">
        /// The stream host providing the standard channels.
        /// </param>
        /// <param name="interpreterFlags">
        /// The interpreter flags controlling how the channels are set up.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupHostChannels(
            IStreamHost streamHost,
            InterpreterFlags interpreterFlags,
            ref Result error
            )
        {
            ChannelType channelType = ChannelType.StandardChannels |
                ChannelType.AllowExist;

            //
            // NOTE: Allow transparent proxies for the standard channel
            //       streams from the specified host only if it is also
            //       a transparent proxy.
            //
            // TODO: This is really a "policy" decision and may need to
            //       be reevaluated in the future.  There is now a flag
            //       to control this behavior; however, that decision
            //       may need to be reevaluated in the future as well.
            //
            /* EXEMPT */
            if (FlagOps.HasFlags(interpreterFlags,
                    InterpreterFlags.AllowProxyStream, true) ||
                AppDomainOps.IsTransparentProxy(streamHost))
            {
                channelType |= ChannelType.AllowProxy;
            }

            return ModifyStandardChannels(
                streamHost, null, channelType, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method performs the main setup phase of interpreter creation,
        /// adding the core commands, functions, operators, variables, policies,
        /// traces, and other entities after the pre-setup phase has completed.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the interpreter is created.
        /// </param>
        /// <param name="hostCreateFlags">
        /// The flags controlling how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// The flags controlling how the interpreter is initialized.
        /// </param>
        /// <param name="interpreterFlags">
        /// The initial interpreter configuration flags.
        /// </param>
        /// <param name="pluginFlags">
        /// The flags controlling how plugins are loaded.
        /// </param>
        /// <param name="ruleSet">
        /// The rule set to associate with the interpreter, or null for none.
        /// </param>
        /// <param name="args">
        /// The startup (command-line style) arguments to expose, or null for
        /// none.
        /// </param>
        /// <param name="autoPathList">
        /// Extra directories to search for packages, or null for none.
        /// </param>
        /// <param name="policies">
        /// The list of policies to add, or null for none.
        /// </param>
        /// <param name="traces">
        /// The list of variable traces to add, or null for none.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode Setup(
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            InitializeFlags initializeFlags,
            InterpreterFlags interpreterFlags,
            PluginFlags pluginFlags,
            IRuleSet ruleSet,
            IEnumerable<string> args,
            StringList autoPathList,
            PolicyList policies,
            TraceList traces,
            ref Result result
            )
        {
            ReturnCode code = ReturnCode.Ok;

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Standard Channels
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
            {
                //
                // HACK: If all of the following conditions are true,
                //       setup the standard channels now:
                //
                //       1. This is not a "safe" interpreter.
                //
                //       2. It is primarily for shell usage.
                //
                //       3. Host creation was not disabled.
                //
                //       4. Standard channels are not disabled.
                //
                if ((!InternalIsSafe() ||
#if SHELL
                        IsForShellUse(interpreterFlags)
#else
                        false
#endif
                    ) &&
                    !FlagOps.HasFlags(hostCreateFlags, HostCreateFlags.Disable, true) &&
                    !FlagOps.HasFlags(createFlags, CreateFlags.NoChannels, true))
                {
                    code = ModifyStandardChannels(
                        host, null, ChannelType.StandardChannels, ref result);
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Shared Global Flags
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            bool noCommands = FlagOps.HasFlags(createFlags, CreateFlags.NoCommands, true);
            bool verbose = FlagOps.HasFlags(createFlags, CreateFlags.Verbose, true);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Core Library Types
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            TypeList types = null;

            if ((code == ReturnCode.Ok) && NeedTypesForSetup(createFlags))
            {
                ResultList errors = null;

                if (!RuntimeOps.GetTypes(verbose, ref types, ref errors))
                {
                    result = errors;
                    code = ReturnCode.Error;
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Core Library Plugins
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
            {
                CommandFlags? commandFlags;
                CommandFlags? notCommandFlags;

                SetupCommandFlags(
                    createFlags, out commandFlags, out notCommandFlags);

                code = SetupPlugins(
                    ruleSet, types, createFlags, commandFlags, notCommandFlags,
                    true, ShouldUseBuiltIns(IdentifierKind.Command), noCommands,
                    verbose, ref result);
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Namespace Support (optional)
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
            {
                if (!noCommands && RuntimeOps.AreNamespacesEnabled(createFlags))
                {
                    Result localError = null;

                    if (NamespaceOps.HaveRequiredCommands(this, true, ref localError))
                    {
                        code = NamespaceOps.Enable(this, null, true, false, ref result);
                    }
                    else
                    {
                        if (localError != null)
                        {
                            result = new ResultList(
                                "cannot enable namespace support", localError);
                        }
                        else
                        {
                            result = "cannot enable namespace support: no command?";
                        }

                        code = ReturnCode.Error;
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Core command policies (for safe interpreters).
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                code = SetupPolicies(createFlags, policies, noCommands, ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Pre-defined Trace Lists
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                code = SetupTraces(createFlags, traces, ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Pre-defined Global Variables
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                code = SetupMinimumVariables(autoPathList, ref result);

            if (code == ReturnCode.Ok)
                code = SetupVariables(createFlags, args, true, ref result);

            if (code == ReturnCode.Ok)
                code = SetupMinimumPlatform(ref result);

            if (code == ReturnCode.Ok)
                code = SetupPlatform(createFlags, true, ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (GlobalState.CountInterpreters(true) == 0)
            {
                string osNameAndVersion =
                    PlatformOps.GetOperatingSystemNameAndVersion();

                if (osNameAndVersion != null)
                    osNameAndVersion = osNameAndVersion.Trim();

                TraceOps.DebugTrace(String.Format(
                        "SetupPlatform (P:{0} A:{1} T:{2})",
                        ProcessOps.GetId(), /* NOTE: Not typo. */
                        AppDomainOps.GetCurrentId(),
                        GlobalState.GetCurrentSystemThreadId()), null,
                    typeof(Interpreter).Name, TracePriority.StartupInform,
                    false, "platform", osNameAndVersion, "runtime",
                    CommonOps.Runtime.GetRuntimeNameAndVersion(),
                    "library", RuntimeOps.GetVersion(VersionFlags.Setup));
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Pre-defined Environment Variables
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                code = SetupHome(createFlags, ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Update script-level interactive status.
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                code = SetupInteractiveLoop(interpreterFlags, ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Update script-level floating-point precision.
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                code = SetupPrecision(ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Predefined Objects
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                code = SetupObjects(createFlags, ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // More Shared Global Flags
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            bool standardOnly = FlagOps.HasFlags(createFlags, CreateFlags.Standard, true);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Expression Functions
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
            {
                code = SetupFunctions(
                    types, createFlags, ShouldUseBuiltIns(IdentifierKind.Function),
                    standardOnly, verbose, ref result);
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Expression Operators
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
            {
                OperatorFlags? operatorFlags;

                SetupOperatorFlags(createFlags, out operatorFlags);

                code = SetupOperators(
                    types, createFlags, interpreterFlags, pluginFlags, operatorFlags,
                    ShouldUseBuiltIns(IdentifierKind.Operator), standardOnly, verbose,
                    ref result);
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Evaluate the "pre-init" script, if any...
            // Cannot do this without commands (obviously?)...
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if ((code == ReturnCode.Ok) && !noCommands)
                code = PrivatePreInitialize(false, ref result);

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Loader & Library Commands
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

            if ((code == ReturnCode.Ok) && !noCommands)
            {
                if (!FlagOps.HasFlags(createFlags, CreateFlags.NoLoader, true))
                {
                    IPlugin plugin = GetCorePlugin(ref result);

                    if (plugin != null)
                    {
                        code = PackageOps.MaybeAddLoaderCommand(
                            this, plugin, ruleSet, ref result);
                    }
                    else
                    {
                        code = ReturnCode.Error;
                    }
                }
                else
                {
                    //
                    // HACK: After trying to automatically setup for
                    //       the core loader, mask off the creation
                    //       flag that may have been used to prevent
                    //       this behavior.
                    //
                    /* NO RESULT */
                    AllowInitializeLoader();
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

            if ((code == ReturnCode.Ok) && !noCommands)
            {
                if (!InternalIsSafe())
                {
                    IPlugin plugin = GetCorePlugin(ref result);

                    if (plugin != null)
                    {
                        code = PackageOps.MaybeAddSourceWithInfoCommand(
                            this, plugin, ruleSet, ref result);
                    }
                    else
                    {
                        code = ReturnCode.Error;
                    }
                }
            }

            ///////////////////////////////////////////////////////////////////////////////////////////
            //
            // Unsupported & Test Commands (optional)
            //
            ///////////////////////////////////////////////////////////////////////////////////////////

#if TEST
            if ((code == ReturnCode.Ok) && !noCommands &&
                FlagOps.HasFlags(
                    initializeFlags, InitializeFlags.Unsupported, true))
            {
                if (FlagOps.HasFlags(
                        initializeFlags, InitializeFlags.Unsupported, true))
                {
                    code = _Tests.Default.TestAddUnsupportedCommands(
                        this, null, ref result);
                }
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if TEST
            if ((code == ReturnCode.Ok) && !noCommands &&
                GlobalConfiguration.DoesValueExist(
                    EnvVars.TestCommands, ConfigurationFlags.Interpreter))
            {
                LongList tokens = null;
                ResultList errors = null;

                code = _Tests.Default.TestAddAllCommands(
                    this, new _Tests.Default.RuleSetClientData(), null, false,
                    false, ref tokens, ref errors);

                if (code != ReturnCode.Ok)
                    result = errors;
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

#if NOTIFY && NOTIFY_GLOBAL
            if ((code == ReturnCode.Ok) && this.PrivateGlobalNotify)
            {
                /* IGNORED */
                CheckNotifications(
                    null, false,
                    NotifyType.Interpreter, NotifyFlags.Setup,
                    new ObjectPair(createFlags, args), this,
                    null, null, null, ref result);
            }
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

            if (code == ReturnCode.Ok)
                setup = true;

            ///////////////////////////////////////////////////////////////////////////////////////////

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines the home directory to use, based on the
        /// specified flags and lookup priority.
        /// </summary>
        /// <param name="homeFlags">
        /// The flags controlling how the home directory is located.
        /// </param>
        /// <param name="priority">
        /// The priority controlling the order in which candidate locations
        /// are considered.
        /// </param>
        /// <param name="reverse">
        /// Non-zero to reverse the order in which candidate locations are
        /// considered.
        /// </param>
        /// <returns>
        /// The home directory, or null if one cannot be determined.
        /// </returns>
        private static string GetHome(
            HomeFlags homeFlags,
            Priority priority,
            bool reverse
            )
        {
            //
            // NOTE: Initially, search for an appropriate "override" value
            //       for the HOME environment variable.  This will only be
            //       used when the HOME environment variable is not set.
            //
            IAnyPair<HomeFlags, string> homePair =
                PathOps.GetAnyHomeDirectoryPair(homeFlags, priority, reverse);

            if (homePair != null)
            {
                //
                // NOTE: Found an "overridden" home directory value, return
                //       it verbatim.
                //
                return homePair.Y;
            }
            else
            {
                //
                // NOTE: Start with an empty string.  The Win32 drive letter
                //       and path will be added to this string, if available,
                //       before it is returned.
                //
                StringBuilder home = SBF.Create();

                //
                // NOTE: Check for HOMEDRIVE environment variable and append
                //       its value, if any, to the value that we are going to
                //       return.
                //
                string homeDrive = GlobalConfiguration.GetValue(
                    EnvVars.HomeDrive, ConfigurationFlags.Interpreter);

                if (homeDrive != null)
                    home.Append(homeDrive);

                //
                // NOTE: Check for HOMEPATH environment variable and append
                //       its value, if any, to the value that we are going to
                //       return.
                //
                string homePath = GlobalConfiguration.GetValue(
                    EnvVars.HomePath, ConfigurationFlags.Interpreter |
                    ConfigurationFlags.NativePathValue);

                if (homePath != null)
                    home.Append(homePath);

                //
                // BUGFIX: There is (almost?) no point in returning an empty
                //         string here; therefore, transform it into a null
                //         value instead.
                //
                return (home.Length > 0) ? home.ToString() : null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets up the home directory variable for the interpreter,
        /// subject to the specified creation flags.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the home directory is set up.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private static ReturnCode SetupHome(
            CreateFlags createFlags,
            ref Result error /* NOT USED */
            )
        {
            if (!FlagOps.HasFlags(createFlags, CreateFlags.Safe, true) &&
                !FlagOps.HasFlags(createFlags, CreateFlags.NoHome, true))
            {
                if (!PathOps.HaveHomeDirectory(HomeFlags.SetupHomeSetMask))
                {
                    string home = GetHome(
                        HomeFlags.SetupHomeGetMask, Priority.Highest, true);

                    if (!String.IsNullOrEmpty(home) && Directory.Exists(home))
                    {
                        PathOps.SetHomeDirectory(
                            HomeFlags.SetupHomeSetMask, PathOps.GetUnixPath(
                            home));
                    }
                    else
                    {
                        TraceOps.DebugTrace(String.Format(
                            "SetupHome: home directory is unavailable: {0}",
                            FormatOps.WrapOrNull(home)),
                            typeof(Interpreter).Name,
                            TracePriority.FileSystemWarning);
                    }
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets up the state required for the interactive loop,
        /// subject to the specified interpreter flags.
        /// </summary>
        /// <param name="interpreterFlags">
        /// The interpreter flags controlling how the interactive loop is set
        /// up.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupInteractiveLoop(
            InterpreterFlags interpreterFlags,
            ref Result error
            )
        {
            try
            {
                this.InternalInteractive = FlagOps.HasFlags(
                    interpreterFlags, InterpreterFlags.Interactive, true);

                this.ActiveInteractiveLoops = 0;

                return ReturnCode.Ok;
            }
            catch (Exception e)
            {
                error = e;
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets up the floating-point precision used by the
        /// interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode SetupPrecision(
            ref Result error
            )
        {
            try
            {
                this.Precision = TclVars.Expression.DefaultPrecision;
                return ReturnCode.Ok;
            }
            catch (Exception e)
            {
                error = e;
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the platform-related variables have
        /// been set up within the interpreter.
        /// </summary>
        /// <returns>
        /// True if the platform variables are present; otherwise, false.
        /// </returns>
        internal bool HavePlatformVariables()
        {
            if (FlagOps.HasFlags(
                    createFlags, CreateFlags.NoPlatformMask, false))
            {
                return false;
            }

            if (DoesVariableExist(VariableFlags.GlobalOnly,
                    TclVars.Platform.Name) != ReturnCode.Ok)
            {
                return false;
            }

            if (DoesVariableExist(VariableFlags.GlobalOnly,
                    Vars.Platform.Name) != ReturnCode.Ok)
            {
                return false;
            }

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        // WARNING: Please do not change this method unless you know
        //          exactly how it works.
        //
        /// <summary>
        /// This method sets up the minimum set of platform-related variables
        /// required by the interpreter.
        /// </summary>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode SetupMinimumPlatform(
            ref Result result
            )
        {
            //
            // HACK: Even when "NoPlatform" flag is set, always set the
            //       "patchLevel" -AND- "textOrSuffix" elements of the
            //       "eagle_platform" array because they are required
            //       by the core loader package procedures, which are
            //       important to proper core library plugin loading.
            //
            ReturnCode code = ReturnCode.Ok;

            if (!FlagOps.HasFlags(
                    createFlags, CreateFlags.NoVariables, true)) /* EXEMPT */
            {
                if (code == ReturnCode.Ok)
                {
                    Version version = GlobalState.GetAssemblyVersion();

                    code = SetLibraryVariableValue2( /* LOADER: [getPatchLevel] */
                        VariableFlags.None, Vars.Platform.Name,
                        Vars.Platform.PatchLevel, (version != null) ?
                            version.ToString() : null, ref result);
                }

                if (code == ReturnCode.Ok)
                {
                    code = SetLibraryVariableValue2( /* LOADER: [getBuildType] */
                        VariableFlags.None, Vars.Platform.Name,
                        Vars.Platform.TextOrSuffix,
                        RuntimeOps.GetAssemblyTextOrSuffix(
                            GlobalState.GetAssembly()),
                        ref result);
                }

                if (code == ReturnCode.Ok)
                {
                    code = SetLibraryVariableValue2( /* LOADER: [isMono] / [isDotNetCore] */
                        VariableFlags.None, Vars.Platform.Name,
                        Vars.Platform.RuntimeName,
                        CommonOps.Runtime.GetRuntimeName(),
                        ref result);
                }

                if (code == ReturnCode.Ok)
                {
                    code = SetLibraryVariableValue2( /* LOADER: [isWindows] */
                        VariableFlags.None, TclVars.Platform.Name,
                        TclVars.Platform.PlatformName,
                        PlatformOps.GetPlatformName(), ref result);
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: Assumes the interpreter lock is held.
        //
        /// <summary>
        /// This method sets up the platform-related variables within the
        /// interpreter, optionally creating them if they do not already exist.
        /// </summary>
        /// <param name="createFlags">
        /// The flags controlling how the platform variables are set up.
        /// </param>
        /// <param name="create">
        /// Non-zero to create the platform variables if they do not already
        /// exist.
        /// </param>
        /// <param name="result">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode SetupPlatform(
            CreateFlags createFlags,
            bool create,
            ref Result result
            )
        {
            ReturnCode code = ReturnCode.Ok;

            if (!FlagOps.HasFlags(
                    createFlags, CreateFlags.NoPlatformMask, false))
            {
                if (code == ReturnCode.Ok)
                {
                    string byteOrder = BitConverter.IsLittleEndian ?
                        TclVars.Platform.LittleEndianValue :
                        TclVars.Platform.BigEndianValue;

                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.ByteOrder,
                        byteOrder, ref result);
                }

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.CharacterSize,
                        sizeof(char).ToString() + Characters.MinusSign +
                            sizeof(char).ToString(),
                        ref result);

#if DEBUG
                //
                // NOTE: When built with DEBUG, we are always debug-enabled.
                //
                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.Debug,
                        ConversionOps.ToInt(true).ToString(), ref result);
#endif

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.DirectorySeparator,
                        PathOps.NativeDirectorySeparatorChar.ToString(), ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.AlternateDirectorySeparator,
                        PathOps.NonNativeDirectorySeparatorChar.ToString(), ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.PatchLevel,
                        TclVars.Package.PatchLevelValue, ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.PathSeparator,
                        Path.PathSeparator.ToString(), ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.OsProductType,
                        PlatformOps.GetProductTypeName(), ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.PointerSize,
                        IntPtr.Size.ToString(), ref result);

                if (code == ReturnCode.Ok) /* we are always threads-enabled */
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.Threaded,
                        ConversionOps.ToInt(true).ToString(), ref result);

                if (code == ReturnCode.Ok) /* we are always unicode-enabled */
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.Unicode,
                        ConversionOps.ToInt(true).ToString(), ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.Version,
                        TclVars.Package.VersionValue, ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        TclVars.Platform.Name, TclVars.Platform.WordSize,
                        sizeof(int).ToString(), ref result);

                Version version; /* REUSED */
                Uri uri; /* REUSED */

                if (code == ReturnCode.Ok)
                {
                    version = GlobalState.GetAssemblyVersion();

                    code = SetLibraryVariableValue2(VariableFlags.None,
                        Vars.Platform.Name, Vars.Platform.Version,
                        FormatOps.MajorMinor(version), ref result);
                }

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        Vars.Platform.Name, Vars.Platform.Configuration,
                        AttributeOps.GetAssemblyConfiguration(
                            GlobalState.GetAssembly()),
                        ref result);

                if (code == ReturnCode.Ok)
                {
                    DateTime timeStamp = CreatedNoThrow; /* PROPERTY */

                    code = SetLibraryVariableValue2(VariableFlags.None,
                        Vars.Platform.Name, Vars.Platform.InterpreterTimeStamp,
                        FormatOps.Iso8601DateTime(timeStamp, true),
                        ref result);
                }

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        Vars.Platform.Name, Vars.Platform.Vendor,
                        RuntimeOps.GetVendor(this, false), ref result);

                if (code == ReturnCode.Ok)
                    code = SetLibraryVariableValue2(VariableFlags.None,
                        Vars.Platform.Name, Vars.Platform.Suffix,
                        PathOps.GetBaseSuffix(GlobalState.GetAssembly()),
                        ref result);

                if (code == ReturnCode.Ok)
                {
                    if (!InternalIsSafe())
                    {
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Timeout,
                                ThreadOps.GetTimeout(
                                    this, null, TimeoutType.Start |
                                    TimeoutType.MaybeFallback).ToString(),
                                ref result);

#if NETWORK
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.NetworkTimeout,
                                WebOps.GetTimeoutOrDefault(
                                    this, TimeoutType.Network).ToString(),
                                ref result);
#endif

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.Processors,
                                Environment.ProcessorCount.ToString(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.Host,
                                Environment.MachineName, ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.Machine,
                                PlatformOps.GetMachineName(), ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsName,
                                PlatformOps.GetOperatingSystemName(), ref result);

                        if (code == ReturnCode.Ok)
                        {
                            OperatingSystem operatingSystem = PlatformOps.GetOperatingSystem();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsString,
                                (operatingSystem != null) ?
                                    operatingSystem.ToString() : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsVersion,
                                PlatformOps.GetOperatingSystemMajorMinor(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsPatchLevel,
                                PlatformOps.GetOperatingSystemPatchLevel(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsServicePack,
                                PlatformOps.GetOperatingSystemServicePack(),
                                ref result);

#if !NET_STANDARD_20
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsReleaseId,
                                PlatformOps.GetOperatingSystemReleaseId(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsExtra,
                                PlatformOps.GetOperatingSystemExtra(this, false),
                                ref result);

                        if ((code == ReturnCode.Ok) && !FlagOps.HasFlags(
                                createFlags, CreateFlags.NoPopulateOsExtra, true))
                        {
                            /* ASYNCHRONOUS */
                            PlatformOps.PopulateOperatingSystemExtra(
                                this, true, true, true);
                        }
#else
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.OsExtra,
                                null, ref result);
#endif

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.ProcessBits,
                                PlatformOps.GetProcessBits().ToString(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                TclVars.Platform.Name, TclVars.Platform.User,
                                PlatformOps.GetUserName(false), ref result);

#if CAS_POLICY
                        if (code == ReturnCode.Ok)
                        {
                            Result permissionSetResult = null;

                            try
                            {
#if NET_40
                                if (AppDomainOps.IsLegacyCasPolicyEnabled())
#endif
                                {
                                    Evidence evidence = GlobalState.GetAssemblyEvidence();

                                    PermissionSet permissionSet = (evidence != null) ?
                                        SecurityManager.ResolvePolicy(evidence) : null;

                                    permissionSetResult = (permissionSet != null) ?
                                        StringOps.NormalizeWhiteSpace(
                                            permissionSet.ToString(), Characters.Space,
                                            WhiteSpaceFlags.VariableUse) : null;
                                }
                            }
                            catch (Exception e)
                            {
                                permissionSetResult = e;
                            }

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.PermissionSet,
                                permissionSetResult, ref result);
                        }
#endif

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.SourceId,
                                _Shared.AttributeOps.GetAssemblySourceId(
                                    GlobalState.GetAssembly()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.SourceTimeStamp,
                                _Shared.AttributeOps.GetAssemblySourceTimeStamp(
                                    GlobalState.GetAssembly()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Administrator,
                                RuntimeOps.IsAdministrator().ToString(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.ApplicationAddressRange,
                                PlatformOps.GetApplicationAddressRange(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Culture,
                                FormatOps.CultureName(
                                    GlobalState.GetAssemblyCultureInfo(), false),
                                ref result);

                        if (code == ReturnCode.Ok)
                        {
                            version = CommonOps.Runtime.GetFrameworkVersion();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.FrameworkVersion,
                                (version != null) ? version.ToString() : null,
                                ref result);
                        }

#if !NET_STANDARD_20
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.FrameworkExtraVersion,
                                CommonOps.Runtime.GetFrameworkExtraVersion(),
                                ref result);
#else
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.FrameworkExtraVersion,
                                null, ref result);
#endif

#if NATIVE && WINDOWS
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.ProcessorAffinityMasks,
                                NativeOps.GetProcessorAffinityMasks().ToString(),
                                ref result);
#endif

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Wow64,
                                PlatformOps.GetWin32onWin64().ToString(),
                                ref result);

                        if (code == ReturnCode.Ok)
                        {
                            version = CommonOps.Runtime.GetRuntimeVersion();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.RuntimeVersion,
                                (version != null) ? version.ToString() : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.RuntimeBuild,
                                CommonOps.Runtime.GetRuntimeBuild(), ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.RuntimeExtraVersion,
                                CommonOps.Runtime.GetRuntimeExtraVersion(), ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.ImageRuntimeVersion,
                                AssemblyOps.GetImageRuntimeVersion(
                                    GlobalState.GetAssembly()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Epoch,
                                FormatOps.Iso8601DateTime(TimeOps.UnixEpoch, true),
                                ref result);

                        if (code == ReturnCode.Ok)
                        {
                            Assembly assembly = GlobalState.GetAssembly();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.GlobalAssemblyCache,
                                (assembly != null) ?
                                    assembly.GlobalAssemblyCache.ToString() :
                                    false.ToString(),
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                        {
                            StringList options = DefineConstants.OptionList;

                            if (options != null)
                            {
                                options = new StringList(options);
                                options.Sort();
                            }

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.CompileOptions,
                                (options != null) ? options.ToString(false) : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.CSharpOptionsName,
                                Vars.Platform.CSharpOptionsValue, ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.RuntimeOptions,
                                runtimeOptions.ToString(), ref result);

                        if (!FlagOps.HasFlags(createFlags, CreateFlags.NoObjectIds, true))
                        {
                            StringPairList objectIds =
                                AttributeOps.GetObjectIds(GlobalState.GetAssembly(), false);

                            if (code == ReturnCode.Ok)
                                code = SetLibraryVariableValue2(VariableFlags.None,
                                    Vars.Platform.Name, Vars.Platform.ObjectIds,
                                    (objectIds != null) ? objectIds.ToString() : null,
                                    ref result);
                        }

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.MinimumDate,
                                FormatOps.Iso8601DateTime(DateTime.MinValue, true),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.MaximumDate,
                                FormatOps.Iso8601DateTime(DateTime.MaxValue, true),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.TimeStamp,
                                FormatOps.Iso8601DateTime(
                                    _Shared.AttributeOps.GetAssemblyDateTime(
                                        GlobalState.GetAssembly()), true),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Release,
                                _Shared.AttributeOps.GetAssemblyRelease(
                                    GlobalState.GetAssembly()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Tag,
                                _Shared.AttributeOps.GetAssemblyTag(
                                    GlobalState.GetAssembly()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Text,
                                _Shared.AttributeOps.GetAssemblyText(
                                    GlobalState.GetAssembly()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.TargetFramework,
                                AttributeOps.GetAssemblyTargetFramework(
                                    GlobalState.GetAssembly()),
                                ref result);

#if NATIVE && NATIVE_UTILITY
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.NativeUtility,
                                NativeUtility.GetVersion(this), ref result);
#endif

                        if (code == ReturnCode.Ok)
                        {
                            uri = GlobalState.GetAssemblyUri();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Uri,
                                (uri != null) ? uri.ToString() : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                        {
                            uri = GlobalState.GetAssemblyUpdateBaseUri();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.UpdateBaseUri,
                                (uri != null) ? uri.ToString() : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                        {
                            uri = GlobalState.GetAssemblyDownloadBaseUri();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.DownloadBaseUri,
                                (uri != null) ? uri.ToString() : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                        {
                            uri = GlobalState.GetAssemblyScriptBaseUri();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.ScriptBaseUri,
                                (uri != null) ? uri.ToString() : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                        {
                            uri = GlobalState.GetAssemblyAuxiliaryBaseUri();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.AuxiliaryBaseUri,
                                (uri != null) ? uri.ToString() : null,
                                ref result);
                        }

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.PublicKey,
                                AssemblyOps.GetPublicKey(
                                    GlobalState.GetAssemblyName()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.PublicKeyToken,
                                AssemblyOps.GetPublicKeyToken(
                                    GlobalState.GetAssemblyName()),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.ModuleVersionId,
                                AssemblyOps.GetModuleVersionId(
                                    GlobalState.GetAssembly()).ToString(),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Certificate,
                                FormatOps.Certificate(this,
                                    GlobalState.GetAssemblyLocation(), GetCertificate(),
                                    !create || RuntimeOps.ShouldCheckCoreFileTrusted(),
                                    false, false),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.UpdatePathAndQueryName,
                                String.Format(
                                    Vars.Platform.UpdatePathAndQueryValue,
                                    GlobalState.GetAssemblyUpdateVersion(),
                                    null),
                                ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.StrongName,
                                FormatOps.StrongName(
                                    GlobalState.GetAssembly(),
#if CAS_POLICY
                                    GetStrongName(),
#endif
                                    !create || (RuntimeOps.ShouldCheckStrongNameVerified()
#if !NET_STANDARD_20
                                        && SetupOps.ShouldCheckCoreVerified()
#endif
                                )), ref result);

                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.StrongNameTag,
                                _Shared.AttributeOps.GetAssemblyStrongNameTag(
                                    GlobalState.GetAssembly()),
                                ref result);

#if CAS_POLICY
                        //
                        // TODO: Apparently, this can be quite slow.
                        //
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Hash,
                                FormatOps.Hash(GetHash()), ref result);
#else
                        if (code == ReturnCode.Ok)
                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.Hash,
                                null, ref result);
#endif

                        if (code == ReturnCode.Ok)
                        {
                            version = GlobalState.GetEntryAssemblyVersion();

                            code = SetLibraryVariableValue2(VariableFlags.None,
                                Vars.Platform.Name, Vars.Platform.ShellVersion,
                                FormatOps.MajorMinor(version),
                                ref result);

                            if (code == ReturnCode.Ok)
                            {
                                code = SetLibraryVariableValue2(VariableFlags.None,
                                    Vars.Platform.Name, Vars.Platform.ShellPatchLevel,
                                    (version != null) ? version.ToString() : null,
                                    ref result);
                            }
                        }
                    }
                }
            }

            return code;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Initialization
        /// <summary>
        /// This method evaluates a named script, typically part of the script
        /// library, within the specified interpreter.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to evaluate the script.
        /// </param>
        /// <param name="name">
        /// The name of the script to evaluate.
        /// </param>
        /// <param name="core">
        /// Non-zero if the script being evaluated is part of the core script
        /// library.
        /// </param>
        /// <param name="direct">
        /// Non-zero to evaluate the script directly rather than through the
        /// normal script resolution machinery.
        /// </param>
        /// <param name="scriptFlags">
        /// The flags controlling how the script is located and evaluated.
        /// Upon return, this reflects any changes made while resolving the
        /// script.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the script.  Upon return, this
        /// reflects the client data resolved for the script.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of evaluating the script;
        /// upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private static ReturnCode EvaluateScript(
            Interpreter interpreter,
            string name,
            bool core,
            bool direct,
            ref ScriptFlags scriptFlags,
            ref IClientData clientData,
            ref Result result
            )
        {
            string text = null;

            return EvaluateScript(
                interpreter, name, core, direct, ref scriptFlags, ref clientData,
                ref text, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates a named script, typically part of the script
        /// library, within the specified interpreter, also returning the text of
        /// the script that was evaluated.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to evaluate the script.
        /// </param>
        /// <param name="name">
        /// The name of the script to evaluate.
        /// </param>
        /// <param name="core">
        /// Non-zero if the script being evaluated is part of the core script
        /// library.
        /// </param>
        /// <param name="direct">
        /// Non-zero to evaluate the script directly rather than through the
        /// normal script resolution machinery.
        /// </param>
        /// <param name="scriptFlags">
        /// The flags controlling how the script is located and evaluated.
        /// Upon return, this reflects any changes made while resolving the
        /// script.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the script.  Upon return, this
        /// reflects the client data resolved for the script.
        /// </param>
        /// <param name="text">
        /// Upon success, this contains the text of the script that was
        /// evaluated.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of evaluating the script;
        /// upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private static ReturnCode EvaluateScript(
            Interpreter interpreter,
            string name,
            bool core,
            bool direct,
            ref ScriptFlags scriptFlags,
            ref IClientData clientData,
            ref string text,
            ref Result result
            )
        {
            int errorLine = 0;

            ReturnCode code = EvaluateScript(
                interpreter, name, core, direct, ref scriptFlags,
                ref clientData, ref text, ref result,
                ref errorLine);

            if (errorLine != 0)
                SetErrorLine(interpreter, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: *WARNING* This method is for use with named (i.e.
        //       predefined) script library and host scripts only.
        //       This method may be radically modified and/or
        //       removed in the future.
        //
        /// <summary>
        /// This method evaluates a named script, typically part of the script
        /// library, within the specified interpreter, also returning the text of
        /// the script that was evaluated and the line number of any error.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to evaluate the script.
        /// </param>
        /// <param name="name">
        /// The name of the script to evaluate.
        /// </param>
        /// <param name="core">
        /// Non-zero if the script being evaluated is part of the core script
        /// library.
        /// </param>
        /// <param name="direct">
        /// Non-zero to evaluate the script directly rather than through the
        /// normal script resolution machinery.
        /// </param>
        /// <param name="scriptFlags">
        /// The flags controlling how the script is located and evaluated.
        /// Upon return, this reflects any changes made while resolving the
        /// script.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the script.  Upon return, this
        /// reflects the client data resolved for the script.
        /// </param>
        /// <param name="text">
        /// Upon success, this contains the text of the script that was
        /// evaluated.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of evaluating the script;
        /// upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this is set to the line number where the error
        /// occurred.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private static ReturnCode EvaluateScript(
            Interpreter interpreter,
            string name,
            bool core,
            bool direct,
            ref ScriptFlags scriptFlags,
            ref IClientData clientData,
            ref string text,
            ref Result result,
            ref int errorLine
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                errorLine = 0;

                return ReturnCode.Error;
            }

#if DEBUGGER && DEBUGGER_BREAKPOINTS
            InterpreterStateFlags savedInterpreterStateFlags;

            interpreter.BeginLibraryScriptPending(
                out savedInterpreterStateFlags);
#endif

            try
            {
#if ARGUMENT_CACHE
                CacheFlags savedCacheFlags;
                interpreter.BeginNoArgumentCache(out savedCacheFlags);

                try
                {
#endif
                    PackageFlags savedPackageFlags = interpreter.ContextPackageFlags;
                    ProcedureFlags savedProcedureFlags = interpreter.ContextProcedureFlags;

                    try
                    {
                        PackageFlags newPackageFlags = savedPackageFlags;
                        ProcedureFlags newProcedureFlags = savedProcedureFlags;

                        ///////////////////////////////////////////////////////////////////////////////

                        bool library = FlagOps.HasFlags(scriptFlags, ScriptFlags.Library, true);
                        bool interactive = FlagOps.HasFlags(scriptFlags, ScriptFlags.Interactive, true);

                        ///////////////////////////////////////////////////////////////////////////////

                        if (core)
                        {
                            newPackageFlags |= PackageFlags.Core;
                            newProcedureFlags |= ProcedureFlags.Core;
                        }

                        if (library)
                        {
                            newPackageFlags |= PackageFlags.Library;
                            newProcedureFlags |= ProcedureFlags.Library;
                        }

                        if (interactive)
                        {
                            newPackageFlags |= PackageFlags.Interactive;
                            newProcedureFlags |= ProcedureFlags.Interactive;
                        }

                        ///////////////////////////////////////////////////////////////////////////////

                        interpreter.ContextPackageFlags = newPackageFlags;
                        interpreter.ContextProcedureFlags = newProcedureFlags;

                        ///////////////////////////////////////////////////////////////////////////////

                        /* EXEMPT */
                        bool forceGlobal = FlagOps.HasFlags(
                            interpreter.InterpreterFlags, InterpreterFlags.ForceGlobalLibrary,
                            true);

                        ///////////////////////////////////////////////////////////////////////////////

                        ScriptLibraryCallback callback;

                        if (library)
                        {
                            callback = new ScriptLibraryCallback(ScriptOps.GetLibrary);
                        }
                        else
                        {
                            ScriptOps.MaybeExactNameOnly(
                                interpreter, name, null, ref scriptFlags);

                            callback = new ScriptLibraryCallback(HostOps.GetScript);
                        }

                        ///////////////////////////////////////////////////////////////////////////////

                        IFileSystemHost fileSystemHost = interpreter.InternalHost;
                        Result localResult = null;

                        if (callback(
                                interpreter, fileSystemHost, name, direct, ref scriptFlags,
                                ref clientData, ref localResult) == ReturnCode.Ok)
                        {
                            text = localResult;

                            if (!String.IsNullOrEmpty(text))
                            {
                                if (FlagOps.HasFlags(scriptFlags, ScriptFlags.File, true))
                                {
                                    if (PathOps.IsRemoteUri(text) || File.Exists(text))
                                    {
                                        bool needUnset = false;

                                        try
                                        {
                                            if (FlagOps.HasFlags(scriptFlags,
                                                    ScriptFlags.Asynchronous, true) ||
                                                interpreter.InternalIsSafe() ||
                                                ((needUnset = true) &&
                                                (interpreter.SetLibraryVariableValue2(
                                                    VariableFlags.GlobalOnly,
                                                    Vars.Core.Debugger,
                                                    Vars.Debugger.ScriptName, name,
                                                    ref result) == ReturnCode.Ok)))
                                            {
                                                if (forceGlobal)
                                                {
                                                    return interpreter.EvaluateGlobalFile(
                                                        text, ref result, ref errorLine);
                                                }
                                                else
                                                {
                                                    return interpreter.EvaluateFile(
                                                        text, ref result, ref errorLine);
                                                }
                                            }
                                            else
                                            {
                                                return ReturnCode.Error;
                                            }
                                        }
                                        finally
                                        {
                                            if (needUnset)
                                            {
                                                /* IGNORED */
                                                interpreter.UnsetLibraryVariable(
                                                    VariableFlags.GlobalOnly,
                                                    Vars.Core.Debugger,
                                                    Vars.Debugger.ScriptName);

                                                needUnset = false;
                                            }
                                        }
                                    }
                                    else
                                    {
                                        result = String.Format(
                                            "the provided {0}{1} named script file " +
                                            "{2} is not a valid remote uri and does " +
                                            "not exist locally", forceGlobal ? "global " :
                                            String.Empty, FormatOps.WrapOrNull(name),
                                            FormatOps.WrapOrNull(text));
                                    }
                                }
                                else
                                {
                                    //
                                    // BUGFIX: Use the original script [file?] name, exactly
                                    //         as specified, for any contained [info script]
                                    //         calls.
                                    //
                                    bool pushed = false;

                                    interpreter.PushScriptLocation(name, true, ref pushed);

                                    try
                                    {
                                        bool needUnset = false;

                                        try
                                        {
                                            if (FlagOps.HasFlags(scriptFlags,
                                                    ScriptFlags.Asynchronous, true) ||
                                                interpreter.InternalIsSafe() ||
                                                ((needUnset = true) &&
                                                (interpreter.SetLibraryVariableValue2(
                                                    VariableFlags.GlobalOnly,
                                                    Vars.Core.Debugger,
                                                    Vars.Debugger.ScriptName, name,
                                                    ref result) == ReturnCode.Ok)))
                                            {
                                                if (forceGlobal)
                                                {
                                                    return interpreter.EvaluateGlobalScript(
                                                        text, ref result, ref errorLine);
                                                }
                                                else
                                                {
                                                    return interpreter.EvaluateScript(
                                                        text, ref result, ref errorLine);
                                                }
                                            }
                                            else
                                            {
                                                return ReturnCode.Error;
                                            }
                                        }
                                        finally
                                        {
                                            if (needUnset)
                                            {
                                                /* IGNORED */
                                                interpreter.UnsetLibraryVariable(
                                                    VariableFlags.GlobalOnly,
                                                    Vars.Core.Debugger,
                                                    Vars.Debugger.ScriptName);

                                                needUnset = false;
                                            }
                                        }
                                    }
                                    finally
                                    {
                                        interpreter.PopScriptLocation(true, ref pushed);
                                    }
                                }
                            }
                            else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.Required, true))
                            {
                                //
                                // NOTE: The script is required; therefore, this
                                //       is an error.
                                //
                                result = String.Format(
                                    "the provided {0}{1} named script is " +
                                    "invalid (required)", forceGlobal ? "global " :
                                    String.Empty, FormatOps.WrapOrNull(name));
                            }
                            else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.Optional, true))
                            {
                                //
                                // NOTE: Script is explicitly optional, this is OK.
                                //
                                result = String.Empty;
                                return ReturnCode.Ok;
                            }
                            else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.ErrorOnEmpty, true))
                            {
                                //
                                // NOTE: The strict flag is set; therefore, this
                                //       is an error.
                                //
                                result = String.Format(
                                    "the provided {0}{1} named script is " +
                                    "invalid (strict)", forceGlobal ? "global " :
                                    String.Empty, FormatOps.WrapOrNull(name));
                            }
                            else
                            {
                                //
                                // TODO: Script is neither explicitly requierd nor
                                //       optional and the strict flag is not set;
                                //       therefore, just return success.  These
                                //       semantics may need fine-tuning later.
                                //
                                result = String.Empty;
                                return ReturnCode.Ok;
                            }
                        }
                        else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.Required, true) ||
                            FlagOps.HasFlags(scriptFlags, ScriptFlags.ErrorOnEmpty, true))
                        {
                            //
                            // NOTE: No suitable script could be located to
                            //       satisfy the request.  Return the inner
                            //       error message verbatim.
                            //
                            result = localResult;
                        }
                        else
                        {
                            //
                            // TODO: Script is neither explicitly requierd nor
                            //       optional and the strict flag is not set;
                            //       therefore, just return success.  These
                            //       semantics may need fine-tuning later.
                            //
                            result = String.Empty;
                            return ReturnCode.Ok;
                        }
                    }
                    finally
                    {
                        //
                        // NOTE: Restore the saved package and procedure flags.
                        //
                        interpreter.ContextProcedureFlags = savedProcedureFlags;
                        interpreter.ContextPackageFlags = savedPackageFlags;
                    }
#if ARGUMENT_CACHE
                }
                finally
                {
                    interpreter.EndNoArgumentCache(ref savedCacheFlags);
                }
#endif
            }
            catch (Exception e)
            {
                result = e;
            }
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            finally
            {
                interpreter.EndLibraryScriptPending(
                    ref savedInterpreterStateFlags);
            }
#endif

            //
            // NOTE: If we get to this point, we have failed and we do
            //       not have error line information (i.e. we may not
            //       have evaluated anything).
            //
            errorLine = 0;

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates a named startup script within the specified
        /// interpreter.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to evaluate the startup script.
        /// </param>
        /// <param name="name">
        /// The name of the startup script to evaluate.
        /// </param>
        /// <param name="direct">
        /// Non-zero to evaluate the script directly rather than through the
        /// normal script resolution machinery.
        /// </param>
        /// <param name="scriptFlags">
        /// The flags controlling how the script is located and evaluated.
        /// Upon return, this reflects any changes made while resolving the
        /// script.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the script.  Upon return, this
        /// reflects the client data resolved for the script.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of evaluating the script;
        /// upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private static ReturnCode EvaluateStartupScript(
            Interpreter interpreter,
            string name,
            bool direct,
            ref ScriptFlags scriptFlags,
            ref IClientData clientData,
            ref Result result
            )
        {
            int errorLine = 0;

            ReturnCode code = EvaluateStartupScript(
                interpreter, name, direct, ref scriptFlags, ref clientData,
                ref result, ref errorLine);

            if (errorLine != 0)
                SetErrorLine(interpreter, errorLine);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates a named startup script within the specified
        /// interpreter, also returning the line number of any error.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to evaluate the startup script.
        /// </param>
        /// <param name="name">
        /// The name of the startup script to evaluate.
        /// </param>
        /// <param name="direct">
        /// Non-zero to evaluate the script directly rather than through the
        /// normal script resolution machinery.
        /// </param>
        /// <param name="scriptFlags">
        /// The flags controlling how the script is located and evaluated.
        /// Upon return, this reflects any changes made while resolving the
        /// script.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the script.  Upon return, this
        /// reflects the client data resolved for the script.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of evaluating the script;
        /// upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this is set to the line number where the error
        /// occurred.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private static ReturnCode EvaluateStartupScript(
            Interpreter interpreter,
            string name,
            bool direct,
            ref ScriptFlags scriptFlags,
            ref IClientData clientData,
            ref Result result,
            ref int errorLine
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                errorLine = 0;

                return ReturnCode.Error;
            }

#if DEBUGGER && DEBUGGER_BREAKPOINTS
            InterpreterStateFlags savedInterpreterStateFlags;

            interpreter.BeginLibraryScriptPending(
                out savedInterpreterStateFlags);
#endif

            try
            {
#if ARGUMENT_CACHE
                CacheFlags savedCacheFlags;
                interpreter.BeginNoArgumentCache(out savedCacheFlags);

                try
                {
#endif
                    ProcedureFlags savedProcedureFlags = interpreter.ContextProcedureFlags;

                    try
                    {
                        ProcedureFlags newProcedureFlags = savedProcedureFlags;

                        ///////////////////////////////////////////////////////////////////////////////

                        bool library = FlagOps.HasFlags(scriptFlags, ScriptFlags.Library, true);
                        bool interactive = FlagOps.HasFlags(scriptFlags, ScriptFlags.Interactive, true);

                        ///////////////////////////////////////////////////////////////////////////////

                        if (library)
                            newProcedureFlags |= ProcedureFlags.Library;

                        if (interactive)
                            newProcedureFlags |= ProcedureFlags.Interactive;

                        ///////////////////////////////////////////////////////////////////////////////

                        interpreter.ContextProcedureFlags = newProcedureFlags;

                        ///////////////////////////////////////////////////////////////////////////////

                        /* EXEMPT */
                        bool forceGlobal = FlagOps.HasFlags(
                            interpreter.InterpreterFlags, InterpreterFlags.ForceGlobalLibrary,
                            true);

                        ///////////////////////////////////////////////////////////////////////////////

                        IFileSystemHost fileSystemHost = interpreter.InternalHost;
                        Result localResult = null;
                        ResultList errors = null;

                        if (ScriptOps.GetStartup(
                                interpreter, fileSystemHost, name, direct, ref scriptFlags,
                                ref clientData, ref localResult, ref errors) == ReturnCode.Ok)
                        {
                            string text = localResult;

                            if (!String.IsNullOrEmpty(text))
                            {
                                if (FlagOps.HasFlags(scriptFlags, ScriptFlags.File, true))
                                {
                                    if (PathOps.IsRemoteUri(text) || File.Exists(text))
                                    {
                                        bool needUnset = false;

                                        try
                                        {
                                            if (FlagOps.HasFlags(scriptFlags,
                                                    ScriptFlags.Asynchronous, true) ||
                                                interpreter.InternalIsSafe() ||
                                                ((needUnset = true) &&
                                                (interpreter.SetLibraryVariableValue2(
                                                    VariableFlags.GlobalOnly,
                                                    Vars.Core.Debugger,
                                                    Vars.Debugger.ScriptName, name,
                                                    ref result) == ReturnCode.Ok)))
                                            {
                                                if (forceGlobal)
                                                {
                                                    return interpreter.EvaluateGlobalFile(
                                                        text, ref result, ref errorLine);
                                                }
                                                else
                                                {
                                                    return interpreter.EvaluateFile(
                                                        text, ref result, ref errorLine);
                                                }
                                            }
                                            else
                                            {
                                                return ReturnCode.Error;
                                            }
                                        }
                                        finally
                                        {
                                            if (needUnset)
                                            {
                                                /* IGNORED */
                                                interpreter.UnsetLibraryVariable(
                                                    VariableFlags.GlobalOnly,
                                                    Vars.Core.Debugger,
                                                    Vars.Debugger.ScriptName);

                                                needUnset = false;
                                            }
                                        }
                                    }
                                    else
                                    {
                                        result = String.Format(
                                            "the provided {0}{1} startup script file " +
                                            "{2} is not a valid remote uri and does " +
                                            "not exist locally", forceGlobal ? "global " :
                                            String.Empty, FormatOps.WrapOrNull(name),
                                            FormatOps.WrapOrNull(text));
                                    }
                                }
                                else
                                {
                                    bool needUnset = false;

                                    try
                                    {
                                        if (FlagOps.HasFlags(scriptFlags,
                                                ScriptFlags.Asynchronous, true) ||
                                            interpreter.InternalIsSafe() ||
                                            ((needUnset = true) &&
                                            (interpreter.SetLibraryVariableValue2(
                                                VariableFlags.GlobalOnly,
                                                Vars.Core.Debugger,
                                                Vars.Debugger.ScriptName, name,
                                                ref result) == ReturnCode.Ok)))
                                        {
                                            if (forceGlobal)
                                            {
                                                return interpreter.EvaluateGlobalScript(
                                                    text, ref result, ref errorLine);
                                            }
                                            else
                                            {
                                                return interpreter.EvaluateScript(
                                                    text, ref result, ref errorLine);
                                            }
                                        }
                                        else
                                        {
                                            return ReturnCode.Error;
                                        }
                                    }
                                    finally
                                    {
                                        if (needUnset)
                                        {
                                            /* IGNORED */
                                            interpreter.UnsetLibraryVariable(
                                                VariableFlags.GlobalOnly,
                                                Vars.Core.Debugger,
                                                Vars.Debugger.ScriptName);

                                            needUnset = false;
                                        }
                                    }
                                }
                            }
                            else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.Required, true))
                            {
                                //
                                // NOTE: The script is required; therefore, this
                                //       is an error.
                                //
                                result = String.Format(
                                    "the provided {0}{1} startup script is " +
                                    "invalid (required)", forceGlobal ? "global " :
                                    String.Empty, FormatOps.WrapOrNull(name));
                            }
                            else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.Optional, true))
                            {
                                //
                                // NOTE: Script is explicitly optional, this is OK.
                                //
                                result = String.Empty;
                                return ReturnCode.Ok;
                            }
                            else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.ErrorOnEmpty, true))
                            {
                                //
                                // NOTE: The strict flag is set; therefore, this
                                //       is an error.
                                //
                                result = String.Format(
                                    "the provided {0}{1} startup script is " +
                                    "invalid (strict)", forceGlobal ? "global " :
                                    String.Empty, FormatOps.WrapOrNull(name));
                            }
                            else
                            {
                                //
                                // TODO: Script is neither explicitly requierd nor
                                //       optional and the strict flag is not set;
                                //       therefore, just return success.  These
                                //       semantics may need fine-tuning later.
                                //
                                result = String.Empty;
                                return ReturnCode.Ok;
                            }
                        }
                        else if (FlagOps.HasFlags(scriptFlags, ScriptFlags.Required, true) ||
                            FlagOps.HasFlags(scriptFlags, ScriptFlags.ErrorOnEmpty, true))
                        {
                            //
                            // NOTE: No suitable script could be located to
                            //       satisfy the request.  Return the inner
                            //       error message verbatim.
                            //
                            result = errors;
                        }
                        else
                        {
                            //
                            // TODO: Script is neither explicitly requierd nor
                            //       optional and the strict flag is not set;
                            //       therefore, just return success.  These
                            //       semantics may need fine-tuning later.
                            //
                            result = String.Empty;
                            return ReturnCode.Ok;
                        }
                    }
                    finally
                    {
                        //
                        // NOTE: Restore the saved procedure flags.
                        //
                        interpreter.ContextProcedureFlags = savedProcedureFlags;
                    }
#if ARGUMENT_CACHE
                }
                finally
                {
                    interpreter.EndNoArgumentCache(ref savedCacheFlags);
                }
#endif
            }
            catch (Exception e)
            {
                result = e;
            }
#if DEBUGGER && DEBUGGER_BREAKPOINTS
            finally
            {
                interpreter.EndLibraryScriptPending(
                    ref savedInterpreterStateFlags);
            }
#endif

            //
            // NOTE: If we get to this point, we have failed and we do
            //       not have error line information (i.e. we may not
            //       have evaluated anything).
            //
            errorLine = 0;

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method registers (provides) the core packages within the
        /// interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode ProvideCorePackages(
            ref Result error /* out */
            )
        {
            //
            // NOTE: These flags are used when automatically adding the static
            //       packages (i.e. "Tcl" and "Eagle") to the interpreter.
            //
            PackageFlags flags = PackageFlags.Static | PackageFlags.Core |
                PackageFlags.Automatic;

            //
            // NOTE: Provide the static Tcl package in the interpreter for the
            //       purpose of source compatibility with package index files.
            //
            ReturnCode code;
            Result localResult = null;

            code = PkgProvide(TclVars.Package.Name, TclVars.Package.Version,
                _ClientData.Empty, flags, ref localResult);

            if (code != ReturnCode.Ok)
            {
                error = localResult;
                return code;
            }

            //
            // NOTE: Provide the static Eagle package in the interpreter.
            //
            code = PkgProvide(
                GlobalState.GetPackageName(), GlobalState.GetAssemblyVersion(),
                _ClientData.Empty, flags, ref localResult);

            if (code != ReturnCode.Ok)
            {
                error = localResult;
                return code;
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method permits the script library to be initialized by clearing
        /// the creation flag that suppresses library initialization.
        /// </summary>
        private void AllowInitializeLibrary()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                createFlags &= ~CreateFlags.NoLibrary;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method permits the plugin loader to be initialized by clearing
        /// the creation flag that suppresses loader initialization.
        /// </summary>
        private void AllowInitializeLoader()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                createFlags &= ~CreateFlags.NoLoader;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the script library within the interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitializeLibrary(
            ref Result error /* out */
            )
        {
            InitializeFlags localInitializeFlags;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                localInitializeFlags = initializeFlags;
            }

            ReturnCode code = ReturnCode.Ok;

            try
            {
                bool direct = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.Direct, true);

                ///////////////////////////////////////////////////////////////
                //               REQUIRED CORE SCRIPT LIBRARY                //
                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Initialization,
                        true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.CoreLibraryRequiredFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    string text = null;
                    Result localResult = null;

                    code = EvaluateScript(
                        this, FileName.Initialization, true, direct,
                        ref scriptFlags, ref clientData, ref text,
                        ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }

                    //
                    // NOTE: The "init" script is special.  After being
                    //       evaluated successfully, its location must
                    //       be saved -AND- used to populate the script
                    //       variable "tcl_library".
                    //
                    lock (syncRoot) /* TRANSACTIONAL */
                    {
                        if (FlagOps.HasFlags(
                                scriptFlags, ScriptFlags.File, true))
                        {
                            //
                            // BUGFIX: Save the directory where we found
                            //         the "init" script.
                            //
                            initializedPath = PathOps.TranslatePath(
                                PathOps.GetDirectoryName(text),
                                PathTranslationType.Default);
                        }
                        else
                        {
                            //
                            // BUGFIX: No file was used to find the "init"
                            //         script; however, we probably pulled
                            //         it from the assembly resources.
                            //
                            Assembly assembly = GlobalState.GetAssembly();

                            initializedPath = (assembly != null) ?
                                PathOps.TranslatePath(assembly.Location,
                                    PathTranslationType.Default) : null;
                        }
                    }
                }

                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Safe, true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.CoreLibraryRequiredFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    Result localResult = null;

                    code = EvaluateScript(
                        this, FileName.Safe, true, direct,
                        ref scriptFlags, ref clientData,
                        ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }
                }

                ///////////////////////////////////////////////////////////////
                //                REQUIRED CORE PLUGIN LOADER                //
                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Loader,
                        true))
                {
                    code = InternalInitializeLoader(direct, ref error);
                }

                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Test, true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.CoreLibraryRequiredFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    Result localResult = null;

                    code = EvaluateScript(
                        this, FileName.Test, true, direct,
                        ref scriptFlags, ref clientData,
                        ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }
                }

                ///////////////////////////////////////////////////////////////
                //               OPTIONAL CORE SCRIPT LIBRARY                //
                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Embedding, true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.ApplicationLibraryOptionalFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    Result localResult = null;

                    code = EvaluateScript(
                        this, FileName.Embedding, true, direct,
                        ref scriptFlags, ref clientData,
                        ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }
                }

                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Vendor, true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.VendorLibraryOptionalFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    Result localResult = null;

                    code = EvaluateScript(
                        this, FileName.Vendor, true, direct,
                        ref scriptFlags, ref clientData,
                        ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }
                }

                ///////////////////////////////////////////////////////////////

#if (NETWORK && OFFICIAL_BINARY && !ENTERPRISE_LOCKDOWN) || THREADING
                bool asynchronous = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.Asynchronous, true);

                bool waitForStart = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.WaitForStart, true);
#endif

                ///////////////////////////////////////////////////////////////

#if NETWORK && DATA && OFFICIAL_BINARY && !ENTERPRISE_LOCKDOWN
                //
                // NOTE: Currently, the trusted remote script bundle is only
                //       evaluated if the interpreter has a "token" that was
                //       assigned at creation -OR- this is a DEBUG build and
                //       we are not been forbidden from doing so.  This may
                //       be changed in the future.
                //
                if (ShouldInitializeViaTrustedRemoteUri(localInitializeFlags))
                {
                    bool keepSecurity = FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.KeepSecurity,
                        true);

                    WaitCallback trustedRemoteCallback = new WaitCallback(
                            delegate (object state)
                    {
                        //
                        // NOTE: First, check if the Harpy plugin can be
                        //       loaded into the interpreter.  If not, do
                        //       nothing.  If so, attempt to download the
                        //       trusted remote script.  Then, verify its
                        //       signature with the appropriate key pair,
                        //       which will be from "keyRing.one.eagle".
                        //       If that fails, skip it, complain loudly,
                        //       leaving the interpreter unchanged, with
                        //       the exception of the Harpy plugin being
                        //       loaded into its AppDomain.  It could be
                        //       unloaded from the interpreter itself in
                        //       this case.  If the trusted remote script
                        //       is properly signed, it will be evaluated
                        //       as a "script bundle", and possibly with
                        //       interpreter / AppDomain isolation, and
                        //       possibly in a "safe" interpreter with a
                        //       custom IRuleSet to configure its command
                        //       set, which is fundamentally a "sandbox",
                        //       e.g. for partially trusted or marginally
                        //       trusted scripts.  This is intended to be
                        //       used in certain application integration
                        //       scenarios when deploying and/or managing
                        //       client applications (or servers) that do
                        //       require the ability to perform dynamic,
                        //       centralized configuration.  For this use
                        //       case, the customers must have some kind
                        //       of valid license for Harpy and/or Eagle
                        //       Enterprise Edition (EEE) -AND- will need
                        //       to coordinate the exact scripts with the
                        //       company response for the official Eagle
                        //       binary releases ("Mistachkin Systems")
                        //       for two reasons: 1) Defining the exact
                        //       IP address blocks to include for each
                        //       of the desired script variants. 2) In
                        //       order to subject each trusted remote
                        //       script variant for vetting, rule set
                        //       configuration, script bundle creation,
                        //       testing, and final signing.  While the
                        //       open source community may customize any
                        //       of this functionality in their binaries
                        //       and their own copies of the source code,
                        //       the official binaries may not be changed
                        //       (i.e. they are digitally signed) and the
                        //       official servers may not be used without
                        //       explicit permission (i.e. you can simply
                        //       point it at your own servers).
                        //
                        IClientData clientData = _ClientData.Empty;

                        ScriptOps.InitializeViaTrustedRemoteUri(
                            this, clientData, StringOps.GetEncoding(
                                EncodingType.RemoteUri),
                            ScriptFlags.VendorLibraryOptionalFile,
                            ScriptOps.GetPasswordForTrustedRemoteUri(),
                            asynchronous, keepSecurity);
                    });

                    ///////////////////////////////////////////////////////////

                    if (asynchronous)
                    {
                        ThreadOps.QueueUserWorkItem(
                            trustedRemoteCallback, waitForStart);
                    }
                    else
                    {
                        trustedRemoteCallback(null);
                    }
                }
#endif

                ///////////////////////////////////////////////////////////////
                //        OPTIONAL USER SCRIPT LIBRARY (SYNCHRONOUS)         //
                ///////////////////////////////////////////////////////////////

                if (!GlobalConfiguration.DoesValueExist(
                        EnvVars.NoStartups, ConfigurationFlags.Interpreter) &&
                    FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Startup1, true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.ApplicationLibraryOptionalFile |
                        ScriptFlags.UserLibraryOptionalFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    Result localResult = null;

                    code = EvaluateScript(
                        this, FileName.Startup, true, direct,
                        ref scriptFlags, ref clientData,
                        ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }
                }

                ///////////////////////////////////////////////////////////////
                //        OPTIONAL USER SCRIPT LIBRARY (ASYNCHRONOUS)        //
                ///////////////////////////////////////////////////////////////

#if THREADING
                //
                // BUGBUG: This block of code should be relatively fail-safe,
                //         i.e. the worker script should always be evaluated
                //         on the other thread, i.e. even though it may not
                //         complete; however, there appears to be some kind
                //         of thread pool race condition that can cause this
                //         script to not be evaluated at all.
                //
                if (ShouldInitializeViaWorker1(localInitializeFlags))
                {
                    WaitCallback worker1Callback = new WaitCallback(
                            delegate(object state)
                    {
                        ScriptFlags scriptFlags = ScriptOps.GetFlags(this,
                            ScriptFlags.ApplicationLibraryOptionalFile |
                            ScriptFlags.UserLibraryOptionalFile |
                            ScriptFlags.Asynchronous, false, false);

                        ReturnCode localCode;
                        IClientData clientData = _ClientData.Empty;
                        Result localResult = null;

                        localCode = EvaluateScript(
                            this, FileName.Worker, true, direct,
                            ref scriptFlags, ref clientData,
                            ref localResult);

                        if (localCode != ReturnCode.Ok)
                        {
                            TraceOps.DebugTrace(String.Format(
                                "PrivateInitializeLibrary: {0} " +
                                "failure, interpreter = {1}, " +
                                "localCode = {2}, localResult = {3}",
                                InitializeFlags.Worker1,
                                FormatOps.InterpreterNoThrow(this),
                                localCode, FormatOps.WrapOrNull(
                                    true, false, localResult)),
                                typeof(Interpreter).Name,
                                TracePriority.ScriptError2);
                        }
                    });

                    ///////////////////////////////////////////////////////////

                    if (asynchronous)
                    {
                        ThreadOps.QueueUserWorkItem(
                            worker1Callback, waitForStart);
                    }
                    else
                    {
                        worker1Callback(null);
                    }
                }
#endif
            }
            finally
            {
#if ARGUMENT_CACHE
                //
                // HACK: Clear out any cached Argument objects that have
                //       location information to make room in the cache.
                //
                /* IGNORED */
                ClearCaches(CacheFlags.Argument, false);
#endif
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the plugin loader within the interpreter.
        /// </summary>
        /// <param name="direct">
        /// Non-zero to initialize the loader directly rather than through the
        /// normal script resolution machinery.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InternalInitializeLoader(
            bool direct,     /* in */
            ref Result error /* out */
            )
        {
            ProcedureFlags savedProcedureFlags = ContextProcedureFlags;

            try
            {
                //
                // HACK: All script library procedures provided
                //       by the core loader package are "safe"
                //       because they build [package ifneeded]
                //       and [load] commands for evaluation at
                //       a later time -AND- they use commands
                //       and/or sub-commands that are marked as
                //       "safe" -AND- they perform their own
                //       security checks as necessary.  The
                //       reason this is needed is because the
                //       PackageOps class forcibly evaluates
                //       (the security) package index files in
                //       a "safe" evaluation context even when
                //       the interpreter itself is "unsafe".
                //
                ContextProcedureFlags |= ProcedureFlags.Safe;

                ScriptFlags scriptFlags = ScriptOps.GetFlags(
                    this, ScriptFlags.CoreLibraryRequiredFile,
                    false, false);

                IClientData clientData = _ClientData.Empty;
                string text = null;
                Result result = null;

                if (EvaluateScript(
                        this, FileName.Loader, true, direct,
                        ref scriptFlags, ref clientData,
                        ref text, ref result) == ReturnCode.Ok)
                {
                    return ReturnCode.Ok;
                }
                else
                {
                    error = result;
                    return ReturnCode.Error;
                }
            }
            finally
            {
                ContextProcedureFlags = savedProcedureFlags;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the list of directories that make up the
        /// auto-path for the interpreter.
        /// </summary>
        /// <param name="autoPathList">
        /// Upon success, this is set to the computed list of auto-path
        /// directories.
        /// </param>
        /// <param name="skipTrace">
        /// Non-zero to skip emitting trace diagnostics while computing the
        /// list.
        /// </param>
        /// <param name="ignoreError">
        /// Non-zero to ignore any errors encountered while computing the
        /// list.
        /// </param>
        /// <returns>
        /// True if the list was computed successfully; otherwise, false.
        /// </returns>
        private ReturnCode GetAutoPathList(
            ref StringList autoPathList, /* out */
            bool skipTrace,              /* in */
            bool ignoreError             /* in */
            )
        {
            Result error = null;

            return GetAutoPathList(
                ref autoPathList, skipTrace, ignoreError,
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the list of directories that make up the
        /// auto-path for the interpreter, returning an error message on
        /// failure.
        /// </summary>
        /// <param name="autoPathList">
        /// Upon success, this is set to the computed list of auto-path
        /// directories.
        /// </param>
        /// <param name="skipTrace">
        /// Non-zero to skip emitting trace diagnostics while computing the
        /// list.
        /// </param>
        /// <param name="ignoreError">
        /// Non-zero to ignore any errors encountered while computing the
        /// list.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode GetAutoPathList(
            ref StringList autoPathList, /* out */
            bool skipTrace,              /* in */
            bool ignoreError,            /* in */
            ref Result error             /* out */
            )
        {
            VariableFlags variableFlags;

            if (skipTrace)
                variableFlags = VariableFlags.SkipTrace;
            else
                variableFlags = VariableFlags.None;

            ReturnCode code = GetListVariableValue(
                variableFlags, TclVars.Core.AutoPath, false,
                false, false, false, ref autoPathList, ref error);

            TracePriority priority = ResultOps.IsSuccess(code, false) ?
                TracePriority.ScriptDebug : TracePriority.ScriptError;

            TraceOps.DebugTrace(String.Format(
                "GetAutoPathList: autoPathList = {0}, code = {1}, " +
                "error = {2}", FormatOps.WrapOrNull(autoPathList),
                FormatOps.WrapOrNull(code), FormatOps.WrapOrNull(error)),
                typeof(Interpreter).Name, priority);

            if ((code != ReturnCode.Ok) && ignoreError)
                code = ReturnCode.Ok;

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the auto-path variable of the interpreter to the
        /// specified list of directories.
        /// </summary>
        /// <param name="autoPathList">
        /// The list of auto-path directories to set, or null for none.
        /// </param>
        /// <param name="skipTrace">
        /// Non-zero to skip emitting trace diagnostics while setting the
        /// list.
        /// </param>
        /// <param name="ignoreError">
        /// Non-zero to ignore any errors encountered while setting the
        /// list.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode SetAutoPathList(
            StringList autoPathList,
            bool skipTrace,
            bool ignoreError,
            ref Result error
            )
        {
            VariableFlags variableFlags;

            if (skipTrace)
                variableFlags = VariableFlags.SkipTrace;
            else
                variableFlags = VariableFlags.None;

            TraceList traceList;

            lock (syncRoot)
            {
                traceList = autoPathTraceList;
            }

            ReturnCode code = SetLibraryVariableValue(
                variableFlags, TclVars.Core.AutoPath,
                GetAutoPathValue(autoPathList, null),
                traceList, ref error);

            TracePriority priority = ResultOps.IsSuccess(code, false) ?
                TracePriority.ScriptDebug : TracePriority.ScriptError;

            TraceOps.DebugTrace(String.Format(
                "SetAutoPathList: autoPathList = {0}, code = {1}, " +
                "error = {2}", FormatOps.WrapOrNull(autoPathList),
                FormatOps.WrapOrNull(code), FormatOps.WrapOrNull(error)),
                typeof(Interpreter).Name, priority);

            if ((code != ReturnCode.Ok) && ignoreError)
                code = ReturnCode.Ok;

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method merges the specified existing auto-path with the current
        /// auto-path of the interpreter.
        /// </summary>
        /// <param name="oldAutoPathList">
        /// The existing auto-path directories to merge in, or null for none.
        /// </param>
        /// <param name="autoPathList">
        /// Upon success, this is set to the merged list of auto-path
        /// directories.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateMergeAutoPath(
            StringList oldAutoPathList,  /* in: OPTIONAL */
            ref StringList autoPathList, /* out */
            ref Result error             /* out */
            )
        {
            StringList newAutoPathList = null;

            if (GetAutoPathList(
                    ref newAutoPathList, true, false) != ReturnCode.Ok)
            {
                autoPathList = oldAutoPathList;
                return ReturnCode.Ok;
            }

            StringList localAutoPathList = new StringList();

            if (oldAutoPathList != null)
                localAutoPathList.AddRange(oldAutoPathList);

            if (newAutoPathList != null)
                localAutoPathList.AddRange(newAutoPathList);

            autoPathList = localAutoPathList;
            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the auto-path for the interpreter, optionally
        /// merging it with the global auto-path.
        /// </summary>
        /// <param name="autoPathList">
        /// The additional auto-path directories to use, or null for none.
        /// </param>
        /// <param name="noGlobalAutoPath">
        /// Non-zero to exclude the global auto-path directories.
        /// </param>
        /// <param name="noMergeAutoPath">
        /// Non-zero to skip merging with any existing auto-path.
        /// </param>
        /// <param name="noTraceAutoPath">
        /// Non-zero to skip emitting trace diagnostics for the auto-path.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitializeAutoPath(
            StringList autoPathList, /* in: OPTIONAL */
            bool noGlobalAutoPath,   /* in */
            bool noMergeAutoPath,    /* in */
            bool noTraceAutoPath,    /* in */
            ref Result error         /* out */
            )
        {
            //
            // NOTE: Trigger the initialization of the package
            //       "subsystem".  This must be done after the
            //       library has been initialized; otherwise,
            //       the pkgIndex scripts will not be able to
            //       use those facilities.
            //
            InitializeFlags localInitializeFlags;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                localInitializeFlags = initializeFlags;
            }

            if (FlagOps.HasFlags(localInitializeFlags,
                    InitializeFlags.SetAutoPath, true))
            {
                bool mergeAutoPath = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.MergeAutoPath,
                    true);

                bool skipTrace = noTraceAutoPath || FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.NoTraceAutoPath,
                    true);

                bool ignoreError = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.IgnoreError,
                    true);

                //
                // WARNING: Do not "optimize" this code by not
                //          calling GlobalState.GetAutoPathList
                //          when the interpreter is "safe".  The
                //          GlobalState.GetAutoPathList method
                //          has a side-effect of initializing
                //          the global auto-path list as needed,
                //          and other code may rely on us doing
                //          just that.
                //
                StringList localAutoPathList;

                if (autoPathList != null)
                {
                    //
                    // HACK: *SPECIAL* This means the caller is
                    //       giving us the global auto-path and
                    //       it should be used verbatim.
                    //
                    if (!noMergeAutoPath && mergeAutoPath)
                    {
                        localAutoPathList = null;

                        if (PrivateMergeAutoPath(
                                autoPathList, ref localAutoPathList,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        localAutoPathList = autoPathList;
                    }
                }
                else if (!noGlobalAutoPath &&
                    FlagOps.HasFlags(localInitializeFlags,
                        InitializeFlags.GlobalAutoPath, true))
                {
                    localAutoPathList = GlobalState.GetAutoPathList(
                        this, false);

                    if (!noMergeAutoPath && mergeAutoPath &&
                        (PrivateMergeAutoPath(
                            localAutoPathList, ref localAutoPathList,
                            ref error) != ReturnCode.Ok))
                    {
                        return ReturnCode.Error;
                    }
                }
                else if (!noMergeAutoPath && mergeAutoPath)
                {
                    localAutoPathList = null;

                    if (GetAutoPathList(
                            ref localAutoPathList, skipTrace,
                            ignoreError, ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }
                }
                else
                {
                    localAutoPathList = null;
                }

                return SetAutoPathList(
                    localAutoPathList, skipTrace, ignoreError,
                    ref error);
            }
            else
            {
                //
                // NOTE: Ok, skip setting the auto-path and just
                //       return success.
                //
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the script library path for the interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitializeLibraryPath(
            ref Result error /* out */
            )
        {
            InitializeFlags localInitializeFlags;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                localInitializeFlags = initializeFlags;
            }

            if (FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.LibraryPath,
                    true))
            {
                string newPath;

                lock (syncRoot)
                {
                    newPath = initializedPath;
                }

                return SetLibraryVariableValue(
                    VariableFlags.None, TclVars.Core.Library, newPath,
                    ref error);
            }
            else
            {
                return ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if DEBUGGER
        /// <summary>
        /// This method initializes the script debugger for the interpreter,
        /// optionally forcing reinitialization.
        /// </summary>
        /// <param name="force">
        /// Non-zero to force the debugger to be reinitialized even if it has
        /// already been initialized.
        /// </param>
        /// <param name="debug">
        /// Non-zero to enable debugging once the debugger is initialized.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitializeDebugger(
            bool force,      /* in */
            bool debug,      /* in */
            ref Result error /* out */
            )
        {
            //
            // NOTE: Now, see if we need still need to initialize
            //       isolated interpreter for our debugger (if we
            //       have one).
            //
            ReturnCode code = ReturnCode.Ok;
            IDebugger debugger = Debugger; /* PROPERTY */

            if (debugger != null)
            {
                Interpreter debugInterpreter = debugger.Interpreter;

                if ((debugInterpreter != null) &&
                    !debugInterpreter.PrivateInitialized)
                {
                    /* RECURSION */
                    code = debugInterpreter.PrivateInitialize(
                        force, debug, ref error);

                    debugInterpreter.MaybeIgnoreInitializeError(
                        ref code, ref error);
                }
            }

            return code;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records that interpreter initialization has completed and
        /// optionally raises the associated notification.
        /// </summary>
        /// <param name="force">
        /// Non-zero if initialization was forced.
        /// </param>
        /// <param name="debug">
        /// Non-zero if debugging was requested during initialization.
        /// </param>
        /// <param name="notify">
        /// Non-zero to raise the initialization notification.
        /// </param>
        /// <param name="wasInitialized">
        /// Non-zero if the interpreter had already been initialized before
        /// this operation.
        /// </param>
        /// <param name="didInitialize">
        /// Non-zero if this operation actually performed initialization.
        /// </param>
        /// <param name="error">
        /// Upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        private void MarkAsInitialized(
            bool force,          /* in */
            bool debug,          /* in */
            bool notify,         /* in */
            bool wasInitialized, /* in */
            bool didInitialize,  /* in */
            ref Result error     /* in, out */
            )
        {
#if NOTIFY && NOTIFY_GLOBAL
            string newPath;
#endif

            lock (syncRoot) /* TRANSACTIONAL */
            {
#if NOTIFY && NOTIFY_GLOBAL
                newPath = initializedPath;
#endif

                if (!initialized)
                    initialized = true;
            }

#if NOTIFY && NOTIFY_GLOBAL
            if (notify && this.PrivateGlobalNotify)
            {
                /* IGNORED */
                CheckNotifications(
                    null, false, NotifyType.Interpreter |
                    NotifyType.Library, NotifyFlags.Initialized,
                    new ObjectList(force, debug, newPath,
                        wasInitialized, didInitialize),
                    this, null, null, null, ref error);
            }
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the interpreter, optionally forcing
        /// reinitialization.
        /// </summary>
        /// <param name="force">
        /// Non-zero to force the interpreter to be reinitialized even if it
        /// has already been initialized.
        /// </param>
        /// <param name="debug">
        /// Non-zero to enable debugging once initialization completes.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitialize(
            bool force,      /* in */
            bool debug,      /* in */
            ref Result error /* out */
            )
        {
            return PrivateInitialize(null, force, debug, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the interpreter using the specified auto-path,
        /// optionally forcing reinitialization.
        /// </summary>
        /// <param name="autoPathList">
        /// The additional auto-path directories to use, or null for none.
        /// </param>
        /// <param name="force">
        /// Non-zero to force the interpreter to be reinitialized even if it
        /// has already been initialized.
        /// </param>
        /// <param name="debug">
        /// Non-zero to enable debugging once initialization completes.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitialize(
            StringList autoPathList, /* in: OPTIONAL */
            bool force,              /* in */
            bool debug,              /* in */
            ref Result error         /* out */
            )
        {
            ReturnCode code = ReturnCode.Ok;
            bool wasInitialized;
            bool didInitialize = false;

            lock (syncRoot)
            {
                wasInitialized = initialized;
            }

            if (force || !wasInitialized)
            {
                #region Set Debugger Engine Flags (Optional)
#if DEBUGGER
                EngineFlags savedEngineFlags = EngineFlags.None;

                if (debug)
                    BeginNoDebugger(out savedEngineFlags);

                try
#endif
                #endregion
                {
                    #region Phase 0: Copy Creation & Initialization Flags
                    CreateFlags localCreateFlags;
                    InitializeFlags localInitializeFlags;
                    PackageIfNeededFlags localPackageIfNeededFlags;

                    lock (syncRoot)
                    {
                        localCreateFlags = createFlags;
                        localInitializeFlags = initializeFlags;
                        localPackageIfNeededFlags = packageIfNeededFlags;
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 1: Optional Plugin Isolation
#if ISOLATED_PLUGINS
                    if (FlagOps.HasFlags(
                            localInitializeFlags, InitializeFlags.Isolated, true))
                    {
                        //
                        // HACK: If requested via the (script library)
                        //       initialization flags, forcibly enable
                        //       plugin isolation now.  This is before
                        //       any script library scripts could have
                        //       been loaded or evaluated.  This is of
                        //       particular importance if the security
                        //       plugins (e.g. Harpy, Badge, etc) are
                        //       scheduled to be loaded as they may be
                        //       restricted to loading into isolated
                        //       application domains.  In general, the
                        //       only scripts evaluated prior to this
                        //       are the pre-initialization script(s)
                        //       specified via the command line or the
                        //       environment, etc.  Pre-initialization
                        //       scripts, if any, should not load any
                        //       plugins (e.g. via [package require]).
                        //       Since the auto-path is not setup at
                        //       that point, they would have to call
                        //       the [load] command directly, which
                        //       is not recommended.
                        //
                        EnablePluginIsolation();
                    }
#endif
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 2: Auto-Path Diagnostics (Optional)
                    //
                    // NOTE: Debug all the key paths used to initialize the
                    //       interpreter.  This was created initially to
                    //       debug compliance with our path resolution
                    //       expectations (primarily on Mono).
                    //
                    if (FlagOps.HasFlags(
                            localInitializeFlags, InitializeFlags.ShowAutoPath, true))
                    {
                        GlobalState.DisplayPaths(this, DebugPathFlags.Automatic);
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 3: Provide System Packages
                    if (code == ReturnCode.Ok)
                    {
                        code = ProvideCorePackages(ref error);
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 4: Pre-Set Auto-Path Variable
                    if (code == ReturnCode.Ok)
                    {
                        if (!FlagOps.HasFlags( /* EXEMPT */
                                localCreateFlags, CreateFlags.NoVariables, true) &&
                            !FlagOps.HasFlags( /* EXEMPT */
                                localCreateFlags, CreateFlags.NoCritical, true))
                        {
                            code = PrivateInitializeAutoPath(
                                null, true, true, true, ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 5: Initialize Library
                    if (code == ReturnCode.Ok)
                    {
                        if (!FlagOps.HasFlags(
                                localCreateFlags, CreateFlags.NoLibrary, true))
                        {
                            AliasFlags savedNewAliasFlags;

                            lock (syncRoot) /* TRANSACTIONAL */
                            {
                                savedNewAliasFlags = newAliasFlags;
                                newAliasFlags |= AliasFlags.System;
                            }

                            try
                            {
                                code = PrivateInitializeLibrary(ref error);

                                if (code == ReturnCode.Ok)
                                    didInitialize = true;
                            }
                            finally
                            {
                                lock (syncRoot) /* TRANSACTIONAL */
                                {
                                    newAliasFlags = savedNewAliasFlags;
                                    savedNewAliasFlags = AliasFlags.None;
                                }
                            }
                        }
                        else
                        {
                            //
                            // HACK: After trying to automatically initialize
                            //       the core library, mask off the creation
                            //       flag that may have been used to prevent
                            //       the actual script file evaluation.
                            //
                            /* NO RESULT */
                            AllowInitializeLibrary();
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 6: Set Library Initialization Path Variable
                    if (code == ReturnCode.Ok)
                    {
                        if (!FlagOps.HasFlags( /* EXEMPT */
                                localCreateFlags, CreateFlags.NoVariables, true) &&
                            !FlagOps.HasFlags( /* EXEMPT */
                                localCreateFlags, CreateFlags.NoCritical, true))
                        {
                            code = PrivateInitializeAutoPath(
                                autoPathList, false, false, false, ref error);

                            if (code == ReturnCode.Ok)
                                code = PrivateInitializeLibraryPath(ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 7: Initialize Debugger Interpreter
#if DEBUGGER
                    if (code == ReturnCode.Ok)
                    {
                        code = PrivateInitializeDebugger(
                            force, debug, ref error);
                    }
#endif
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 8: Optional (Pre-)Populate Well-Known Packages
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.WellKnown, true))
                        {
#if TEST
                            AssemblyFilePluginNames mappings;

                            mappings = _Tests.Default.TestGetAssemblyFilePluginNames(
                                this, null, localPackageIfNeededFlags, ref error);

                            if (mappings != null)
                            {
                                Result result = null;

                                code = PackageOps.CreateAndEvaluateIfNeededScripts(
                                    this, mappings, null, null, null, InternalCultureInfo,
                                    localPackageIfNeededFlags, ref result);

                                if ((code != ReturnCode.Ok) && (result != null))
                                    error = result;
                            }
                            else
                            {
                                code = ReturnCode.Error;
                            }
#else
                            error = "not implemented";
                            code = ReturnCode.Error;
#endif
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 9: Optional Static Callback
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.Callback, true))
                        {
                            EventCallback callback = InitializeInterpreterCallback;

                            if (callback != null)
                            {
                                Result result = null;

                                code = callback(this, null, ref result);

                                if ((code != ReturnCode.Ok) && (result != null))
                                    error = result;
                            }
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 10: Optional Re-Scan Packages
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.Scan, true))
                        {
                            code = PkgScan(
                                this, null, FlagOps.HasFlags(localInitializeFlags,
                                InitializeFlags.RefreshAutoPath, true), ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 11: Optional Load Security Package
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.Security, true))
                        {
                            code = ScriptOps.EnableOrDisableSecurity(
                                this, true, FlagOps.HasFlags(localCreateFlags,
                                CreateFlags.NoVariablesMask, false), ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 12: Optional Remove "Critical" Commands
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.NoCritical, true))
                        {
                            code = RemoveCommands(
                                _ClientData.Empty, CommandFlags.Critical, null, true,
                                false, ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 13: Optional Remove "Unsafe" Commands
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.NoUnsafe, true))
                        {
                            code = RemoveCommands(
                                _ClientData.Empty, CommandFlags.Unsafe, null, true,
                                false, ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 14: Set Library Initialized Flag
                    //
                    // NOTE: Has everything succeeded?
                    //
                    if (code == ReturnCode.Ok)
                    {
                        MarkAsInitialized(
                            force, debug, true, wasInitialized, didInitialize, ref error);
                    }
                    #endregion
                }
                #region Restore Saved Engine Flags
#if DEBUGGER
                finally
                {
                    if (debug)
                        EndNoDebugger(ref savedEngineFlags);
                }
#endif
                #endregion
            }

            TraceOps.DebugTrace(String.Format(
                "PrivateInitialize: interpreter = {0}, force = {1}, " +
                "debug = {2}, wasInitialized = {3}, didInitialize = {4}, " +
                "code = {5}, error = {6}",
                FormatOps.InterpreterNoThrow(this),
                force, debug, wasInitialized, didInitialize, code,
                FormatOps.WrapOrNull(true, true, error)),
                typeof(Interpreter).Name, TracePriority.StartupDebug);

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether global tracking is enabled for the
        /// interpreter.
        /// </summary>
        /// <returns>
        /// True if global tracking is enabled; otherwise, false.
        /// </returns>
        private bool IsGlobalTrackingEnabled()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return FlagOps.HasFlags(
                    initializeFlags, InitializeFlags.GlobalTracking, true);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether initialization errors should be
        /// ignored for the interpreter.
        /// </summary>
        /// <returns>
        /// True if initialization errors should be ignored; otherwise, false.
        /// </returns>
        private bool PrivateIsIgnoreOnError()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return FlagOps.HasFlags(
                    createFlags, CreateFlags.IgnoreOnError, true);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method optionally clears an initialization error, converting it
        /// to success when the interpreter is configured to ignore such errors.
        /// </summary>
        /// <param name="code">
        /// The return code to examine and possibly reset to success.
        /// </param>
        /// <param name="error">
        /// The error message to examine and possibly clear.
        /// </param>
        private void MaybeIgnoreInitializeError(
            ref ReturnCode code,
            ref Result error
            )
        {
            if ((code != ReturnCode.Ok) && PrivateIsIgnoreOnError())
            {
                TraceOps.DebugTrace(String.Format(
                    "MaybeIgnoreInitializeError: error is being " +
                    "ignored, interpreter = {0}, code = {1}, error = {2}",
                    FormatOps.InterpreterNoThrow(this), code,
                    FormatOps.WrapOrNull(true, true, error)),
                    typeof(Interpreter).Name, TracePriority.StartupError);

                error = null;
                code = ReturnCode.Ok;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if SHELL
        /// <summary>
        /// This method permits the shell script library to be initialized by
        /// clearing the creation flag that suppresses shell library
        /// initialization.
        /// </summary>
        private void AllowInitializeShellLibrary()
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                createFlags &= ~CreateFlags.NoShellLibrary;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the shell script library within the
        /// interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitializeShellLibrary(
            ref Result error /* out */
            )
        {
            InitializeFlags localInitializeFlags;

            lock (syncRoot)
            {
                localInitializeFlags = initializeFlags;
            }

            ReturnCode code = ReturnCode.Ok;

            try
            {
                bool direct = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.Direct, true);

                ///////////////////////////////////////////////////////////////
                //               REQUIRED SHELL SCRIPT LIBRARY               //
                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Shell, true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.Interactive |
                        ScriptFlags.CoreLibraryRequiredFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    string text = null;
                    Result localResult = null;

                    code = EvaluateScript(
                        this, FileName.Shell, true, direct,
                        ref scriptFlags, ref clientData,
                        ref text, ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }

                    //
                    // NOTE: The "shell" script is special.  After being
                    //       evaluated successfully, its location must
                    //       be saved -AND- used to populate the script
                    //       variable "tcl_shellLibrary".
                    //
                    lock (syncRoot) /* TRANSACTIONAL */
                    {
                        if (FlagOps.HasFlags(
                                scriptFlags, ScriptFlags.File, true))
                        {
                            //
                            // NOTE: Save the directory where we found
                            //       the "shell" script.
                            //
                            initializedShellPath = PathOps.TranslatePath(
                                PathOps.GetDirectoryName(text),
                                PathTranslationType.Default);
                        }
                        else
                        {
                            //
                            // NOTE: No file was used to find the "shell"
                            //       script; however, we probably pulled
                            //       it from the assembly resources.
                            //
                            Assembly assembly = GlobalState.GetAssembly();

                            initializedShellPath = (assembly != null) ?
                                PathOps.TranslatePath(assembly.Location,
                                    PathTranslationType.Default) : null;
                        }
                    }
                }

                ///////////////////////////////////////////////////////////////
                //       OPTIONAL SHELL (COMMAND SYNTAX?) HELP FILE(S)       //
                ///////////////////////////////////////////////////////////////

                if (FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.SyntaxHelp, true))
                {
                    ResultList localErrors = null;

                    code = SyntaxOps.LoadAndCacheDataFrom(
                        GlobalState.InitializeOrGetBinaryPath(false),
                        StringOps.GetEncoding(EncodingType.Syntax),
                        SyntaxDataFlags.LoadAndCacheDataFrom,
                        ref localErrors);

                    if (code != ReturnCode.Ok)
                    {
                        error = localErrors;
                        return code;
                    }
                }

                ///////////////////////////////////////////////////////////////

#if THREADING
                bool asynchronous = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.Asynchronous, true);

                bool waitForStart = FlagOps.HasFlags(
                    localInitializeFlags, InitializeFlags.WaitForStart, true);
#endif

                ///////////////////////////////////////////////////////////////
                //       OPTIONAL SHELL SCRIPT LIBRARY (ASYNCHRONOUS)        //
                ///////////////////////////////////////////////////////////////

#if THREADING
                //
                // BUGBUG: This block of code should be relatively fail-safe,
                //         i.e. the worker script should always be evaluated
                //         on the other thread, i.e. even though it may not
                //         complete; however, there appears to be some kind
                //         of thread pool race condition that can cause this
                //         script to not be evaluated at all.
                //
                if (ShouldInitializeViaShellWorker(localInitializeFlags))
                {
                    WaitCallback shellWorkerCallback = new WaitCallback(
                            delegate (object state)
                    {
                        ScriptFlags scriptFlags = ScriptOps.GetFlags(this,
                            ScriptFlags.Interactive |
                            ScriptFlags.ApplicationOptionalFile |
                            ScriptFlags.UserOptionalFile |
                            ScriptFlags.Asynchronous, false, false);

                        ReturnCode localCode;
                        IClientData clientData = _ClientData.Empty;
                        Result localResult = null;

                        localCode = EvaluateStartupScript(
                            this, FileName.ShellWorker, direct,
                            ref scriptFlags, ref clientData,
                            ref localResult);

                        if (localCode != ReturnCode.Ok)
                        {
                            TraceOps.DebugTrace(String.Format(
                                "PrivateInitializeShellLibrary: {0} " +
                                "failure, interpreter = {1}, " +
                                "localCode = {2}, localResult = {3}",
                                InitializeFlags.ShellWorker,
                                FormatOps.InterpreterNoThrow(this),
                                localCode, FormatOps.WrapOrNull(
                                    true, false, localResult)),
                                typeof(Interpreter).Name,
                                TracePriority.ScriptError2);
                        }
                    });

                    ///////////////////////////////////////////////////////////

                    if (asynchronous)
                    {
                        ThreadOps.QueueUserWorkItem(
                            shellWorkerCallback, waitForStart);
                    }
                    else
                    {
                        shellWorkerCallback(null);
                    }
                }
#endif

                ///////////////////////////////////////////////////////////////
                //               OPTIONAL SHELL STARTUP SCRIPT               //
                ///////////////////////////////////////////////////////////////

                if (!GlobalConfiguration.DoesValueExist(
                        EnvVars.NoStartups, ConfigurationFlags.Interpreter) &&
                    FlagOps.HasFlags(
                        localInitializeFlags, InitializeFlags.Startup3, true))
                {
                    ScriptFlags scriptFlags = ScriptOps.GetFlags(
                        this, ScriptFlags.Interactive |
                        ScriptFlags.ApplicationOptionalFile |
                        ScriptFlags.UserOptionalFile,
                        false, false);

                    IClientData clientData = _ClientData.Empty;
                    Result localResult = null;

                    code = EvaluateStartupScript(
                        this, TclVars.Core.RunCommandsFileName,
                        direct, ref scriptFlags, ref clientData,
                        ref localResult);

                    if (code != ReturnCode.Ok)
                    {
                        error = localResult;
                        return code;
                    }
                }
            }
            finally
            {
#if ARGUMENT_CACHE
                //
                // HACK: Clear out any cached Argument objects that have
                //       location information to make room in the cache.
                //
                /* IGNORED */
                ClearCaches(CacheFlags.Argument, false);
#endif
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the shell script library path for the
        /// interpreter.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitializeShellLibraryPath(
            ref Result error /* out */
            )
        {
            string newPath;

            lock (syncRoot)
            {
                newPath = initializedShellPath;
            }

            return SetLibraryVariableValue(
                VariableFlags.None, TclVars.Core.ShellLibrary,
                newPath, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records that shell initialization has completed and
        /// optionally raises the associated notification.
        /// </summary>
        /// <param name="force">
        /// Non-zero if shell initialization was forced.
        /// </param>
        /// <param name="debug">
        /// Non-zero if debugging was requested during shell initialization.
        /// </param>
        /// <param name="notify">
        /// Non-zero to raise the shell initialization notification.
        /// </param>
        /// <param name="wasInitialized">
        /// Non-zero if the shell had already been initialized before this
        /// operation.
        /// </param>
        /// <param name="didInitialize">
        /// Non-zero if this operation actually performed shell
        /// initialization.
        /// </param>
        /// <param name="error">
        /// Upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        private void MarkAsShellInitialized(
            bool force,          /* in */
            bool debug,          /* in */
            bool notify,         /* in */
            bool wasInitialized, /* in */
            bool didInitialize,  /* in */
            ref Result error     /* in, out */
            )
        {
#if NOTIFY && NOTIFY_GLOBAL
            string newPath;
#endif

            lock (syncRoot) /* TRANSACTIONAL */
            {
#if NOTIFY && NOTIFY_GLOBAL
                newPath = initializedShellPath;
#endif

                if (!initializedShell)
                    initializedShell = true;
            }

#if NOTIFY && NOTIFY_GLOBAL
            if (notify && this.PrivateGlobalNotify)
            {
                /* IGNORED */
                CheckNotifications(
                    null, false, NotifyType.Interpreter |
                    NotifyType.Shell, NotifyFlags.Initialized,
                    new ObjectList(force, debug, newPath,
                        wasInitialized, didInitialize),
                    this, null, null, null, ref error);
            }
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method initializes the shell support within the interpreter,
        /// optionally forcing reinitialization.
        /// </summary>
        /// <param name="force">
        /// Non-zero to force the shell to be reinitialized even if it has
        /// already been initialized.
        /// </param>
        /// <param name="debug">
        /// Non-zero to enable debugging once shell initialization completes.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode PrivateInitializeShell(
            bool force,      /* in */
            bool debug,      /* in */
            ref Result error /* out */
            )
        {
            ReturnCode code = ReturnCode.Ok;
            bool wasInitialized;
            bool didInitialize = false;

            lock (syncRoot)
            {
                wasInitialized = initializedShell;
            }

            if (force || !wasInitialized)
            {
                #region Set Debugger Engine Flags (Optional)
#if DEBUGGER
                EngineFlags savedEngineFlags = EngineFlags.None;

                if (debug)
                    BeginNoDebugger(out savedEngineFlags);

                try
#endif
                #endregion
                {
                    #region Phase 0: Copy Creation / Initialization Flags
                    CreateFlags localCreateFlags;
                    InitializeFlags localInitializeFlags;

                    lock (syncRoot)
                    {
                        localCreateFlags = createFlags;
                        localInitializeFlags = initializeFlags;
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 1: Auto-Path Diagnostics (Optional)
                    //
                    // NOTE: Debug all the key paths used to initialize the
                    //       interpreter.  This was created initially to
                    //       debug compliance with our path resolution
                    //       expectations (primarily on Mono).
                    //
                    if (FlagOps.HasFlags(
                            localInitializeFlags, InitializeFlags.ShowAutoPath, true))
                    {
                        GlobalState.DisplayPaths(this, DebugPathFlags.Automatic);
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 2: Initialize Shell Library
                    if (code == ReturnCode.Ok)
                    {
                        if (!FlagOps.HasFlags(
                                localCreateFlags, CreateFlags.NoShellLibrary, true))
                        {
                            code = PrivateInitializeShellLibrary(ref error);

                            if (code == ReturnCode.Ok)
                                didInitialize = true;
                        }
                        else
                        {
                            //
                            // HACK: After trying to automatically initialize
                            //       the shell library, mask off the creation
                            //       flag that may have been used to prevent
                            //       the actual script file evaluation.
                            //
                            /* NO RESULT */
                            AllowInitializeShellLibrary();
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 3: Optional Remove "Critical" Commands
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.ShellNoCritical, true))
                        {
                            code = RemoveCommands(
                                _ClientData.Empty, CommandFlags.Critical, null, true,
                                false, ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 4: Optional Remove "Unsafe" Commands
                    if (code == ReturnCode.Ok)
                    {
                        if (FlagOps.HasFlags(
                                localInitializeFlags, InitializeFlags.ShellNoUnsafe, true))
                        {
                            code = RemoveCommands(
                                _ClientData.Empty, CommandFlags.Unsafe, null, true,
                                false, ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 5: Set Shell Library Variable
                    if (code == ReturnCode.Ok)
                    {
                        if (!FlagOps.HasFlags(
                                localCreateFlags, CreateFlags.NoVariablesMask, false) &&
                            !FlagOps.HasFlags(
                                localCreateFlags, CreateFlags.Safe, true))
                        {
                            code = PrivateInitializeShellLibraryPath(ref error);
                        }
                    }
                    #endregion

                    ///////////////////////////////////////////////////////////////////////////////////

                    #region Phase 6: Set Shell Initialized Flag
                    if (code == ReturnCode.Ok)
                    {
                        MarkAsShellInitialized(
                            force, debug, true, wasInitialized, didInitialize, ref error);
                    }
                    #endregion
                }
                #region Restore Saved Engine Flags
#if DEBUGGER
                finally
                {
                    if (debug)
                        EndNoDebugger(ref savedEngineFlags);
                }
#endif
                #endregion
            }

            TraceOps.DebugTrace(String.Format(
                "PrivateInitializeShell: interpreter = {0}, force = {1}, " +
                "debug = {2}, wasInitialized = {3}, didInitialize = {4}, " +
                "code = {5}, error = {6}",
                FormatOps.InterpreterNoThrow(this),
                force, debug, wasInitialized, didInitialize, code,
                FormatOps.WrapOrNull(true, true, error)),
                typeof(Interpreter).Name, TracePriority.StartupDebug);

            return code;
        }
#endif
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interpreter Settings Support
        /// <summary>
        /// This method gathers the complete list of policies currently
        /// configured for the interpreter, combining the system and user
        /// policies.
        /// </summary>
        /// <param name="full">
        /// Non-zero to always include the global system policies; zero to
        /// include them only when they are incomplete.
        /// </param>
        /// <returns>
        /// The gathered list of policies, or null if there are none.
        /// </returns>
        private PolicyList GatherPolicyList(
            bool full /* in */
            )
        {
            PolicyList policies = null;
            PolicyList systemPolicies = MakePolicyList(true);

            //
            // HACK: Only include the list of global system
            //       policies if it is incomplete unless the
            //       "full" flag is specified.
            //
            if ((systemPolicies != null) && (full ||
                !PolicyOps.HasExecuteCallbacks(systemPolicies)))
            {
                if (policies == null)
                    policies = new PolicyList();

                policies.AddRange(systemPolicies);
            }

            PolicyList userPolicies = MakePolicyList(false);

            if (userPolicies != null)
            {
                if (policies == null)
                    policies = new PolicyList();

                policies.AddRange(userPolicies);
            }

            return policies;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the policies currently configured for
        /// the interpreter, filtered by whether they are system policies.
        /// </summary>
        /// <param name="system">
        /// Non-zero to include only system policies, zero to include only
        /// non-system policies, or null to include all of them.
        /// </param>
        /// <returns>
        /// The list of matching policies, or null if there are none.
        /// </returns>
        private PolicyList MakePolicyList(
            bool? system /* in */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (policies == null)
                    return null;

                PolicyList result = null;

                foreach (PolicyPair pair in policies)
                {
                    PolicyWrapper wrapper = pair.Value;

                    if (wrapper == null)
                        continue;

                    if (AppDomainOps.IsTransparentProxy(wrapper)) /* REDUNDANT */
                        continue;

                    IPolicy policy = wrapper.Object as IPolicy;

                    if (policy == null)
                        continue;

                    if (AppDomainOps.IsTransparentProxy(policy))
                        continue;

                    if ((system != null) && FlagOps.HasFlags(
                            policy.MethodFlags, MethodFlags.System,
                            true) != (bool)system)
                    {
                        continue;
                    }

                    if (result == null)
                        result = new PolicyList();

                    result.Add(policy);
                }

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gathers the complete list of variable traces currently
        /// configured for the interpreter, combining the system and user
        /// traces.
        /// </summary>
        /// <param name="full">
        /// Non-zero to always include the global system traces; zero to
        /// include them only when they are incomplete.
        /// </param>
        /// <returns>
        /// The gathered list of traces, or null if there are none.
        /// </returns>
        private TraceList GatherTraceList(
            bool full /* in */
            )
        {
            TraceList traces = null;

            TraceList systemTraces = MakeTraceList(
                null, null, null, null, true);

            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // HACK: Only include the list of global system
                //       traces if it is incomplete unless the
                //       "full" flag is specified.
                //
                if ((systemTraces != null) && (full ||
                    !HasVariableTraces(systemTraces, true)))
                {
                    if (traces == null)
                        traces = new TraceList();

                    traces.AddRange(systemTraces);
                }
            }

            TraceList userTraces = MakeTraceList(
                null, null, null, null, false);

            if (userTraces != null)
            {
                if (traces == null)
                    traces = new TraceList();

                traces.AddRange(userTraces);
            }

            return traces;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list of the variable traces currently configured
        /// for the interpreter, filtered by whether they are system traces and,
        /// for a scalar variable, whether the automatic object trace callback is
        /// needed.
        /// </summary>
        /// <param name="varName">
        /// The name of the variable for which the trace list is being built,
        /// used to decide whether the object trace callback is required.
        /// </param>
        /// <param name="varIndex">
        /// The array element index of the variable, used to decide whether
        /// the object trace callback is required, or null for none.
        /// </param>
        /// <param name="varValue">
        /// The value of the variable, used to decide whether the object trace
        /// callback is required, or null for none.
        /// </param>
        /// <param name="array">
        /// Non-zero if the variable is an array, zero if it is a scalar, or
        /// null if unspecified.
        /// </param>
        /// <param name="system">
        /// Non-zero to include only system traces, zero to include only
        /// non-system traces, or null to include all of them.
        /// </param>
        /// <returns>
        /// The list of matching traces, or null if there are none.
        /// </returns>
        private TraceList MakeTraceList(
            string varName,  /* in */
            string varIndex, /* in */
            object varValue, /* in */
            bool? array,     /* in */
            bool? system     /* in */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (traces == null)
                    return null;

                TraceList result = null;

                foreach (TracePair pair in traces)
                {
                    TraceWrapper wrapper = pair.Value;

                    if (wrapper == null)
                        continue;

                    if (AppDomainOps.IsTransparentProxy(wrapper)) /* REDUNDANT */
                        continue;

                    ITrace trace = wrapper.Object as ITrace;

                    if (trace == null)
                        continue;

                    if (AppDomainOps.IsTransparentProxy(trace))
                        continue;

                    if ((system != null) && FlagOps.HasFlags(
                            trace.MethodFlags, MethodFlags.System,
                            true) != (bool)system)
                    {
                        continue;
                    }

                    //
                    // HACK: *PERF* If the AutoTraceObject flag is set, we may
                    //       skip adding the ObjectTraceCallback, for reasons
                    //       of performance.  In those cases, it will only be
                    //       added "when necessary".  In this context, that is
                    //       taken to mean that the name, [array element] index,
                    //       and/or value of the variable refers to an existing
                    //       opaque object handle.  For reasons of consistency,
                    //       we will NOT skip adding the ObjectTraceCallback if
                    //       the variable is an array (i.e. because traces are
                    //       generally added only at variable creation time, not
                    //       at element creation time, and an array may contain
                    //       both simple values as well as values that refer to
                    //       opaque object handles).  This policy may be removed
                    //       in the future if other enhancements are made to the
                    //       array value handling.
                    //
                    if ((array != null) && !(bool)array && /* SCALAR-ONLY */
                        (varValue is string) && HasAutoTraceObject() &&
                        IsObjectTraceCallback(trace.Callback) &&
                        (PrivateDoesAnyObjectExist(varName,
                            varIndex, (string)varValue) != ReturnCode.Ok))
                    {
                        continue;
                    }

                    if (result == null)
                        result = new TraceList();

                    result.Add(trace);
                }

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method populates an interpreter settings object with the current
        /// configuration of the interpreter.
        /// </summary>
        /// <param name="recreate">
        /// Non-zero to create a new settings object even if one was
        /// supplied.
        /// </param>
        /// <param name="full">
        /// Non-zero to include the full set of settings.
        /// </param>
        /// <param name="interpreterSettings">
        /// The settings object to populate.  Upon success, this contains the
        /// populated settings, creating a new object if necessary.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode PopulateInterpreterSettings(
            bool recreate,                                /* in */
            bool full,                                    /* in */
            ref IInterpreterSettings interpreterSettings, /* in, out */
            ref Result error                              /* out */
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                ReturnCode code;
                StringList list = null;

                code = GetListVariableValue(
                    VariableFlags.GlobalOnly, TclVars.Core.ShellArguments,
                    true, false, false, false, ref list, ref error);

                if (code != ReturnCode.Ok)
                    return code;

                if (interpreterSettings == null)
                    interpreterSettings = InterpreterSettings.Create();

                interpreterSettings.Args = list;

                CultureInfo cultureInfo = InternalCultureInfo;

                interpreterSettings.Culture = (cultureInfo != null) ?
                    cultureInfo.Name : null;

                interpreterSettings.AppDomain = appDomain;

                //
                // BUGFIX: When being called in order to recreate an
                //         interpreter, existing host cannot be used
                //         because it will be disposed.
                //
                IHost localHost = recreate ? null : host;

                interpreterSettings.Host = localHost;

                interpreterSettings.Profile = (localHost != null) ?
                    localHost.Profile : null;

                //
                // BUGBUG: If this interpreter is within an isolated
                //         AppDomain, these could throw an exception;
                //         therefore, they now have their own checks
                //         for transparent proxies.
                //
                // NOTE: System policies and traces should be omitted
                //       if they represent complete sets without any
                //       customizations (i.e. if the user has removed
                //       a system policy and/or trace manually we do
                //       not want to accidentally re-add it) _unless_
                //       the "full" flag is specified.
                //
                interpreterSettings.Policies = GatherPolicyList(full);
                interpreterSettings.Traces = GatherTraceList(full);

                interpreterSettings.Text = preInitializeText;

                interpreterSettings.AutoPathList = (autoPathList != null) ?
                    new StringList(autoPathList) : null;

                return code;
            }
        }
        #endregion

