#if DEBUGGER
        /// <summary>
        /// This method determines whether watchpoints of the specified type can
        /// currently be hit within the interpreter.
        /// </summary>
        /// <param name="breakpointType">
        /// The type of breakpoint to consider.
        /// </param>
        /// <returns>
        /// True if watchpoints can be hit; otherwise, false.
        /// </returns>
        private bool CanHitWatchpoints(
            BreakpointType breakpointType /* NOT USED */
            )
        {
            return !EngineFlagOps.HasNoWatchpoint(engineFlags) &&
                !PrivateIsDebuggerActive();
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether breakpoints of the specified type can
        /// currently be hit within the interpreter.
        /// </summary>
        /// <param name="breakpointType">
        /// The type of breakpoint to consider.
        /// </param>
        /// <returns>
        /// True if breakpoints can be hit; otherwise, false.
        /// </returns>
        internal bool CanHitBreakpoints(
            BreakpointType breakpointType
            )
        {
            bool viaReady = FlagOps.HasFlags(
                breakpointType, BreakpointType.Ready, false);

            return (!viaReady || !IsDebuggerExiting) &&
                !EngineFlagOps.HasNoBreakpoint(engineFlags) &&
                !PrivateIsDebuggerActive();
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method formats the configured test breakpoints into their string
        /// representation.
        /// </summary>
        /// <param name="result">
        /// Upon success, this contains the string form of the test
        /// breakpoints; upon failure, this contains an error message describing
        /// the problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode TestBreakpointsToString(
            ref Result result
            )
        {
            StringDictionary testBreakpoints = TestBreakpoints;

            if (testBreakpoints == null)
            {
                result = "test breakpoints not available";
                return ReturnCode.Error;
            }

            result = testBreakpoints.ToString(null, false);
            return ReturnCode.Ok;
