        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a test breakpoint with the specified
        /// name is set.
        /// </summary>
        /// <param name="name">
        /// The name of the test breakpoint to check for.
        /// </param>
        /// <returns>
        /// True if the named test breakpoint is set; otherwise, false.
        /// </returns>
        internal bool HasTestBreakpoint(
            string name
            )
        {
            if (name != null)
            {
                StringDictionary testBreakpoints = TestBreakpoints;

                if (testBreakpoints != null)
                    return testBreakpoints.ContainsKey(name);
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets or clears the test breakpoint with the specified
        /// name.
        /// </summary>
        /// <param name="name">
        /// The name of the test breakpoint to set or clear.
        /// </param>
        /// <param name="enable">
        /// Non-zero to set the test breakpoint; zero to clear it.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// True if the test breakpoint was successfully set or cleared;
        /// otherwise, false.
        /// </returns>
        internal bool SetTestBreakpoint(
            string name,
            bool enable,
            ref Result error
            )
        {
            if (name == null)
            {
                error = "invalid test name";
                return false;
            }

            StringDictionary testBreakpoints = TestBreakpoints;

            if (testBreakpoints == null)
            {
                error = "test breakpoints not available";
                return false;
            }

            if (enable == testBreakpoints.ContainsKey(name))
            {
                error = String.Format(
                    "test {0} breakpoint is already {1}",
                    FormatOps.WrapOrNull(name),
                    enable ? "set" : "unset");

                return false;
            }

            if (enable)
                testBreakpoints.Add(name, null);
            else
                testBreakpoints.Remove(name);

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks whether a breakpoint of the specified type should
        /// be triggered and, if so, enters the script debugger.
        /// </summary>
        /// <param name="code">
        /// The return code in effect at the point the breakpoint is being
        /// checked.
        /// </param>
        /// <param name="breakpointType">
        /// The type of breakpoint being checked.
        /// </param>
        /// <param name="breakpointName">
        /// The name associated with the breakpoint being checked.
        /// </param>
        /// <param name="token">
        /// The script token associated with the current location, or null for
        /// none.
        /// </param>
        /// <param name="traceInfo">
        /// The variable trace information associated with the breakpoint, or
        /// null for none.
        /// </param>
        /// <param name="execute">
        /// The entity being executed at the current location, or null for
        /// none.
        /// </param>
        /// <param name="executeArgument">
        /// The argument being evaluated at the current location, or null for
        /// none.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the current location, or null for
        /// none.
        /// </param>
        /// <param name="arguments">
        /// The arguments associated with the current location, or null for
        /// none.
        /// </param>
        /// <param name="result">
        /// Upon return, this contains the result produced by the debugger, if
        /// any; upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode CheckBreakpoints(
            ReturnCode code,
            BreakpointType breakpointType,
            string breakpointName,
            IToken token,
            ITraceInfo traceInfo,
            IExecute execute,
            IExecuteArgument executeArgument,
            IClientData clientData,
            ArgumentList arguments,
            ref Result result
            )
        {
            return Engine.CheckBreakpoints(
                code, breakpointType, breakpointName, token, traceInfo, engineFlags,
                substitutionFlags, engineEventFlags, expressionFlags, execute,
                executeArgument, this, clientData, arguments, ref result);
        }

