        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Test Hooks Support
        /// <summary>
        /// This method appends the arguments describing a test hook invocation to
        /// the specified argument list.
        /// </summary>
        /// <param name="hookType">
        /// The type of test hook being prepared.
        /// </param>
        /// <param name="resultType">
        /// The type of test result associated with the hook.
        /// </param>
        /// <param name="name">
        /// The name of the test, or null for none.
        /// </param>
        /// <param name="description">
        /// The description of the test, or null for none.
        /// </param>
        /// <param name="constraints">
        /// The constraints associated with the test, or null for none.
        /// </param>
        /// <param name="skip">
        /// Non-zero if the test is being skipped.
        /// </param>
        /// <param name="fail">
        /// Non-zero if the test is being marked as failed.
        /// </param>
        /// <param name="ignore">
        /// Non-zero if the test is being ignored.
        /// </param>
        /// <param name="whatIf">
        /// Non-zero to operate in "what-if" mode, without making changes.
        /// </param>
        /// <param name="knownBug">
        /// Non-zero if the test is associated with a known bug.
        /// </param>
        /// <param name="returnCode">
        /// The return code associated with the test, or null for none.
        /// </param>
        /// <param name="result">
        /// The result associated with the test, or null for none.
        /// </param>
        /// <param name="arguments">
        /// The argument list to which the prepared arguments are appended.
        /// </param>
        internal void PrepareTestHooksArguments(
            TestHookType hookType,     /* in */
            TestResultType resultType, /* in */
            string name,               /* in: OPTIONAL */
            string description,        /* in: OPTIONAL */
            string constraints,        /* in: OPTIONAL */
            bool skip,                 /* in */
            bool fail,                 /* in */
            bool ignore,               /* in */
            bool whatIf,               /* in */
            bool knownBug,             /* in */
            ReturnCode? returnCode,    /* in: OPTIONAL */
            Result result,             /* in: OPTIONAL */
            ref ArgumentList arguments /* in, out */
            )
        {
            if (arguments == null)
                arguments = new ArgumentList();

            arguments.Add("hookType");
            arguments.Add(hookType);

            arguments.Add("resultType");
            arguments.Add(resultType);

            arguments.Add("name");
            arguments.Add(name);

            arguments.Add("description");
            arguments.Add(description);

            arguments.Add("constraints");
            arguments.Add(constraints);

            arguments.Add("skip");
            arguments.Add(skip);

            arguments.Add("fail");
            arguments.Add(fail);

            arguments.Add("ignore");
            arguments.Add(ignore);

            arguments.Add("whatIf");
            arguments.Add(whatIf);

            arguments.Add("knownBug");
            arguments.Add(knownBug);

            if (returnCode != null)
            {
                arguments.Add("returnCode");
                arguments.Add((ReturnCode)returnCode);
            }

            if (result != null)
            {
                arguments.Add("result");
                arguments.Add(result);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method lists the test hooks currently configured for the
        /// interpreter.
        /// </summary>
        /// <param name="result">
        /// Upon success, this contains the list of test hooks; upon failure,
        /// this contains an error message describing the problem.
