        internal ReturnCode ListTestHooks(
            ref Result result /* out */
            ) /* THREAD-SAFE */
        {
            StringDictionary hooks = TestHooks;

            if (hooks == null)
            {
                result = "test hooks unavailable";
                return ReturnCode.Error;
            }

            result = hooks.KeysToString(null, false);
            return ReturnCode.Ok;
