        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether any test hooks of the specified type
        /// match the specified pattern, optionally gathering the matching names.
        /// </summary>
        /// <param name="type">
        /// The type of test hooks to check for.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match test hook names, or null to match all of
        /// them.
        /// </param>
        /// <param name="gather">
        /// Non-zero to gather the matching test hook names into the supplied
        /// list.
        /// </param>
        /// <param name="list">
        /// Upon return, this contains the gathered list of matching test hook
        /// names, if any.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode HasTestHooks(
            TestHookType type,   /* in */
            string pattern,      /* in */
            bool gather,         /* in */
            ref StringList list, /* in, out */
            ref Result error     /* out */
            ) /* THREAD-SAFE */
        {
            if (pattern == null)
            {
                error = "invalid pattern";
                return ReturnCode.Error;
            }

            StringDictionary hooks = TestHooks;

            if (hooks == null)
            {
                error = "test hooks unavailable";
                return ReturnCode.Error;
            }

            string formatted = FormatOps.TestHookPattern(type, pattern);

            if (formatted == null)
            {
                error = String.Format(
                    "invalid formatted pattern for {0}",
                    FormatOps.DisplayName(pattern));

                return ReturnCode.Error;
            }

            int count = 0;
            string localValue;

            if (hooks.TryGetValue(formatted, out localValue))
            {
                if (gather)
                {
                    if (list == null)
                        list = new StringList();

                    list.Add(localValue);
                }

                count++;
            }

            if (FlagOps.HasFlags(type, TestHookType.ExactMatch, true))
            {
                if (count > 0)
                    return ReturnCode.Ok;

                error = String.Format(
                    "exact test hook {0} not found",
                    FormatOps.DisplayName(formatted));

                return ReturnCode.Error;
            }

            if (FlagOps.HasFlags(type, TestHookType.AnyMatch, true) ||
                StringOps.HasStringMatchChar(formatted))
            {
                bool noCase = FlagOps.HasFlags(type, TestHookType.NoCase, true);

                foreach (KeyValuePair<string, string> pair in hooks)
                {
                    //
                    // HACK: The exact matches are always handled above.
                    //
                    if (SharedStringOps.SystemEquals(formatted, pair.Key))
                        continue;

                    if (StringOps.Match(
                            this, MatchMode.Glob, formatted, pair.Key, noCase))
                    {
                        if (gather)
                        {
                            if (list == null)
                                list = new StringList();

                            list.Add(pair.Value);
                        }

                        count++;
                    }
                }
            }

            if (count > 0)
                return ReturnCode.Ok;

            error = String.Format(
                "no test hook matching {0} found",
                FormatOps.DisplayName(formatted));

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets or unsets the test hooks of the specified type that
        /// match the specified pattern.
        /// </summary>
        /// <param name="type">
        /// The type of test hooks to set or unset.
        /// </param>
        /// <param name="pattern">
        /// The pattern used to match test hook names, or null to match all of
        /// them.
        /// </param>
        /// <param name="value">
        /// The value to assign to the matching test hooks, or null to unset
        /// them.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode SetOrUnsetTestHook(
            TestHookType type, /* in */
            string pattern,    /* in */
            string value,      /* in */
            ref Result error   /* out */
            ) /* THREAD-SAFE */
        {
            if (pattern == null)
            {
                error = "invalid pattern";
                return ReturnCode.Error;
            }

            StringDictionary hooks = TestHooks; /* CONTEXT */

            if (hooks == null)
            {
                error = "test hooks unavailable";
                return ReturnCode.Error;
            }

            string formatted = FormatOps.TestHookPattern(
                type, pattern);

            if (formatted == null)
            {
                error = String.Format(
                    "invalid formatted pattern for {0}",
                    FormatOps.DisplayName(pattern));

                return ReturnCode.Error;
            }

            if (value != null)
            {
                if (FlagOps.HasFlags(type,
                        TestHookType.AllowOverwrite, true))
                {
                    hooks[formatted] = value;
                    return ReturnCode.Ok;
                }
                else if (hooks.ContainsKey(formatted))
                {
                    error = String.Format(
                        "test hook {0} already exists",
                        FormatOps.DisplayName(formatted));

                    return ReturnCode.Error;
                }
                else
                {
                    hooks.Add(formatted, value);
                    return ReturnCode.Ok;
                }
            }
            else if (hooks.ContainsKey(formatted))
            {
                if (hooks.Remove(formatted))
                {
                    return ReturnCode.Ok;
                }
                else
                {
                    error = String.Format(
                        "could not remove test hook {0}",
                        FormatOps.DisplayName(formatted));

                    return ReturnCode.Error;
                }
            }
            else
            {
                error = String.Format(
                    "test hook {0} not found",
                    FormatOps.DisplayName(formatted));

                return ReturnCode.Error;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Shell & Interactive Loop Support
        #region Shell Support
        #region Shell Script Evaluation Support
#if SHELL
        /// <summary>
        /// This method refreshes the cached delegates used to evaluate scripts
        /// and files during shell processing.
        /// </summary>
        internal void RefreshShellCallbacks()
        {
            //
            // HACK: The lock statement here is not needed when compiled
            //       with THREADING enabled because all values referenced
            //       are from per-thread storage in that case.
            //
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                IShellCallbackData callbackData = ShellCallbackData;

                if (callbackData != null)
                {
                    callbackData.SetNewOrResetPreExisting(
                        this.PreviewArgumentCallback,
                        this.UnknownArgumentCallback,
                        this.EvaluateScriptCallback,
                        this.EvaluateFileCallback,
                        this.EvaluateEncodedFileCallback,
#if DEBUGGER
                        this.InteractiveLoopCallback,
#endif
                        false);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates a script during shell processing by invoking
        /// the specified callback.
        /// </summary>
        /// <param name="evaluateScriptCallback">
        /// The callback used to evaluate the script.
        /// </param>
        /// <param name="text">
        /// The text of the script to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of the evaluation; upon
        /// failure, this contains an error message describing the problem.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this is set to the line number where the error
        /// occurred.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode ShellEvaluateScript(
            EvaluateScriptCallback evaluateScriptCallback, /* in */
            string text,                                   /* in */
            ref Result result,                             /* out */
            ref int errorLine                              /* out */
            )
        {
            try
            {
                if (evaluateScriptCallback == null)
                {
                    return EvaluateScript(
                        text, ref result, ref errorLine);
                }

                return evaluateScriptCallback(
                    this, text, ref result, ref errorLine);
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates a script file during shell processing by
        /// invoking the specified callback.
        /// </summary>
        /// <param name="evaluateFileCallback">
        /// The callback used to evaluate the file.
        /// </param>
        /// <param name="fileName">
        /// The name of the file to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of the evaluation; upon
        /// failure, this contains an error message describing the problem.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this is set to the line number where the error
        /// occurred.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode ShellEvaluateFile(
            EvaluateFileCallback evaluateFileCallback, /* in */
            string fileName,                           /* in */
            ref Result result,                         /* out */
            ref int errorLine                          /* out */
            )
        {
            try
            {
                if (evaluateFileCallback == null)
                {
#if DATA
                    //
                    // TODO: Are these the best bundle flags
                    //       to use here?
                    //
                    BundleFlags bundleFlags =
                        BundleFlags.Default |
                        BundleFlags.RequireKeyRing;

                    if (PathOps.MightBeBundleFile(fileName))
                    {
                        IClientData clientData = null;

                        return EvaluateBundleFile(
                            fileName, null, bundleFlags,
                            ref clientData, ref result,
                            ref errorLine);
                    }
                    else
#endif
                    {
                        return EvaluateFile(
                            fileName, ref result, ref errorLine);
                    }
                }

                return evaluateFileCallback(
                    this, fileName, ref result, ref errorLine);
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates a script file using the specified encoding
        /// during shell processing by invoking the specified callback.
        /// </summary>
        /// <param name="evaluateEncodedFileCallback">
        /// The callback used to evaluate the encoded file.
        /// </param>
        /// <param name="encoding">
        /// The encoding to use when reading the file, or null to use the
        /// default.
        /// </param>
        /// <param name="fileName">
        /// The name of the file to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of the evaluation; upon
        /// failure, this contains an error message describing the problem.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this is set to the line number where the error
        /// occurred.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode ShellEvaluateFile(
            EvaluateEncodedFileCallback evaluateEncodedFileCallback, /* in */
            Encoding encoding,                                       /* in */
            string fileName,                                         /* in */
            ref Result result,                                       /* out */
            ref int errorLine                                        /* out */
            )
        {
            try
            {
                if (evaluateEncodedFileCallback == null)
                {
                    return EvaluateFile(
                        encoding, fileName, ref result, ref errorLine);
                }

                return evaluateEncodedFileCallback(
                    this, encoding, fileName, ref result, ref errorLine);
            }
            catch (Exception e)
            {
                result = e;
                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method evaluates a script file using the specified encoding and
        /// shell callback data during shell processing.
        /// </summary>
        /// <param name="callbackData">
        /// The shell callback data identifying how the file should be
        /// evaluated.
        /// </param>
        /// <param name="encoding">
        /// The encoding to use when reading the file, or null to use the
        /// default.
        /// </param>
        /// <param name="fileName">
        /// The name of the file to evaluate.
        /// </param>
        /// <param name="result">
        /// Upon success, this contains the result of the evaluation; upon
        /// failure, this contains an error message describing the problem.
        /// </param>
        /// <param name="errorLine">
        /// Upon failure, this is set to the line number where the error
        /// occurred.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private ReturnCode ShellEvaluateFile(
            IShellCallbackData callbackData, /* in */
            Encoding encoding,               /* in */
            string fileName,                 /* in */
            ref Result result,               /* out */
            ref int errorLine                /* out */
            )
        {
            if (callbackData == null)
            {
                result = "invalid shell callback data";
                return ReturnCode.Error;
            }

            if (encoding != null)
            {
                return ShellEvaluateFile(
                    callbackData.EvaluateEncodedFileCallback,
                    encoding, fileName, ref result, ref errorLine);
            }
            else
            {
                return ShellEvaluateFile(
                    callbackData.EvaluateFileCallback, fileName,
                    ref result, ref errorLine);
            }
        }
#endif
        #endregion

