        #region Shell Core Support
#if SHELL
        /// <summary>
        /// This method determines the error line number to report for the shell,
        /// based on the specified interpreter and candidate line number.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose error line is being reported, or null for
        /// none.
        /// </param>
        /// <param name="errorLine">
        /// The candidate error line number.
        /// </param>
        /// <returns>
        /// The error line number to report for the shell.
        /// </returns>
        private static int GetShellErrorLine(
            Interpreter interpreter,
            int errorLine
            )
        {
            if (errorLine != 0)
                return errorLine;

            return GetErrorLine(interpreter);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the core shell main entry point is
        /// currently active on any thread.
        /// </summary>
        /// <returns>
        /// True if the core shell main entry point is active; otherwise,
        /// false.
        /// </returns>
        private static bool IsShellMainCoreActive()
        {
            return Interlocked.CompareExchange(ref globalShellMainCoreCount, 0, 0) > 0;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method implements the core of the shell main entry point,
        /// processing the supplied arguments and optionally initializing the
        /// interpreter and entering the interactive loop.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to run the shell.
        /// </param>
        /// <param name="callbackData">
        /// The shell callback data controlling how scripts and files are
        /// evaluated, or null for none.
        /// </param>
        /// <param name="clientData">
        /// The client data to make available during shell processing, or
        /// null for none.
        /// </param>
        /// <param name="args">
        /// The shell (command-line style) arguments to process, or null for
        /// none.
        /// </param>
        /// <param name="whatIf">
        /// Non-zero to operate in "what-if" mode, without making changes.
        /// </param>
        /// <param name="initialize">
        /// Non-zero to initialize the interpreter.  Upon return, this
        /// reflects whether initialization is still pending.
        /// </param>
        /// <param name="loop">
        /// Non-zero to enter the interactive loop.  Upon return, this
        /// reflects whether the interactive loop is still pending.
        /// </param>
        /// <param name="interactive">
        /// Non-zero if the shell is running interactively.  Upon return, this
        /// reflects the updated interactive state.
        /// </param>
        /// <param name="result">
        /// The result associated with shell processing.  Upon return, this
        /// contains the final result or an error message describing any
        /// problem.
        /// </param>
        /// <returns>
        /// The exit code produced by the shell.
        /// </returns>
        private static ExitCode PrivateShellMainCore(
            Interpreter interpreter,         /* in */
            IShellCallbackData callbackData, /* in: OPTIONAL */
            IClientData clientData,          /* in: OPTIONAL */
            IEnumerable<string> args,        /* in: OPTIONAL */
            bool whatIf,                     /* in */
            ref bool initialize,             /* in, out */
            ref bool loop,                   /* in, out */
            ref bool interactive,            /* in, out */
            ref Result result                /* in, out */
            )
        {
            //
            // NOTE: This is the core implementation of the Eagle Shell entry
            //       point.  Given a (valid) interpreter and the raw command
            //       line, it drives the whole shell lifecycle and returns the
            //       process exit code.  The high-level flow is:
            //
            //       1. CAPTURE & CALLBACKS.  Record which optional parameters
            //          the caller supplied, save the original command line and
            //          the per-thread shell callback data, and resolve the
            //          process / "arguments" file names and the interpreter
            //          host used for result reporting.
            //
            //       2. PRE-PROCESS ARGUMENTS.  When enabled, read additional
            //          command line arguments from an "arguments" file and/or
            //          the application settings, merge them into the effective
            //          command line, and (in debug mode) trace the result.
            //
            //       3. ARGUMENT / OPTION PROCESSING.  This is the bulk of the
            //          method: a loop (with a "retry" path) that walks the
            //          command line one argument at a time, trims switch
            //          characters, and dispatches each recognized option.
            //          Options can (re)initialize the interpreter, evaluate
            //          files or inline scripts, switch to an on-demand "child"
            //          interpreter (the "-child" option), request the
            //          interactive loop, and set "what-if" mode, among others.
            //          The ref parameters initialize/loop/interactive are
            //          updated here as the relevant options are seen.
            //
            //       4. INTERACTIVE LOOP.  If requested (or forced), enter the
            //          interactive loop (PrivateInteractiveLoop) -- unless
            //          running in "what-if" mode, which only reports what would
            //          happen without actually doing it.
            //
            //       5. CLEANUP.  Optionally dispose the interpreter (in
            //          particular an on-demand "child" interpreter) and return
            //          the accumulated exit code.
            //
            //       The numerous local variables declared up front carry state
            //       across these phases (e.g. the return code and error line,
            //       the file / interactive exit codes, the count of arguments
            //       added from files, the interactive loop count, usage
            //       information, and the script-reading encoding).
            //
            // NOTE: This method is always called with a valid interpreter.
            //       Initially, that interpreter is used to process command
            //       line arguments and evaluate any requested scripts; at
            //       some point, the optional "-child" command line option
            //       may get used, which switches to a "child" interpreter,
            //       created on-demand.  When the "child" interpreter is in
            //       use, command line options and evaluated scripts will
            //       use it instead of the one originally specified by the
            //       caller.  If the optional "-parent" command line option
            //       is hit, the interpreter in use will be switched back
            //       to the original interpreter.
            //
            bool stopOnUnknown = false;

            if (callbackData != null)
            {
                whatIf = whatIf || callbackData.WhatIf;
                stopOnUnknown = callbackData.StopOnUnknown;
            }

            //
            // NOTE: Interpreter ownership model for this method.  Several
            //       references are used to track interpreters here:
            //
            //       activeInterpreter -- the interpreter currently selected for
            //           command line processing and script evaluation.
            //
            //       parentInterpreter -- the original, caller-provided
            //           interpreter (initially the same as activeInterpreter).
            //           It is owned by the CALLER (typically via a "using"
            //           statement); this method does NOT dispose it unless it
            //           actually re-created the parent itself.
            //
            //       childInterpreter -- an interpreter created on-demand by this
            //           method (via the parent's CreateChildInterpreter),
            //           selected with the "-child" option; childName is its name
            //           within the parent's child registry.
            //
            //       The "-recreate" / "-reconfigure" options can replace the
            //       active interpreter: the old one is torn down first (a parent
            //       via Dispose; a child via the parent's RemoveChildInterpreter,
            //       which keeps the parent's child registry consistent), then a
            //       new one is created.  When this method creates an interpreter
            //       that it must dispose, it sets "dispose" and records the exact
            //       instance in "disposeInterpreter" (with "disposeChild" noting
            //       whether that instance is a child).  At exit, ONLY that
            //       recorded interpreter is torn down -- a child through its
            //       parent, a top-level interpreter directly -- so the
            //       caller-owned parent is never disposed unless this method
            //       re-created the parent itself.
            //
            Interpreter activeInterpreter = interpreter;
            Interpreter parentInterpreter = interpreter;
            Interpreter childInterpreter = null;
            string childName = null;
            bool invalidInterpreter = false;

            IList<string> savedArgv = (args != null) ? new StringList(args) : null;
            IList<string> argv = (args != null) ? new StringList(args) : null;

            TraceOps.DebugTrace(String.Format(
                "PrivateShellMainCore: entered, interpreter = {0}, " +
                "callbackData = {1}, clientData = {2}, savedArgv = {3}, " +
                "argv = {4}, whatIf = {5}, initialize = {6}, loop = {7}, " +
                "interactive = {8}, result = {9}",
                FormatOps.InterpreterNoThrow(interpreter),
                FormatOps.ShellCallbackData(callbackData),
                FormatOps.WrapOrNull(clientData),
                FormatOps.WrapOrNull(true, true, savedArgv),
                FormatOps.WrapOrNull(true, true, argv), whatIf,
                initialize, loop, interactive, FormatOps.WrapOrNull(
                true, true, result)), typeof(Interpreter).Name,
                TracePriority.StartupDebug);

            ExitCode exitCode = ExitCode.Unknown;
            bool dispose = false; /* EXEMPT */
            Interpreter disposeInterpreter = null; /* NOTE: Interp created here. */
            bool disposeChild = false; /* NOTE: Created a child interp? */
            bool quiet = false; /* TODO: Good default? */

            interactive = false;

            if (activeInterpreter == null)
            {
                result = "invalid interpreter";

                if (!whatIf)
                {
                    HostOps.WriteConsoleOrComplain(
                        ReturnCode.Error, result);
                }

                exitCode = ShellOps.FailureExitCode(activeInterpreter);

                goto done;
            }

            //
            // NOTE: Keep track of whether our direct caller provided each
            //       of the available shell callbacks.  This creates a deep
            //       copy of the shell callback data provided by the caller
            //       because we do not want to change the callers variable.
            //
            IShellCallbackData localCallbackData = _ShellCallbackData.Create(
                callbackData);

            if (localCallbackData != null)
            {
                /* NO RESULT */
                localCallbackData.CheckForPreExisting();
            }

            if (!whatIf)
            {
                //
                // NOTE: Save the original command line arguments passed by
                //       the caller.  Later, the [info argv] sub-command can
                //       be used to inspect them (from "unsafe" interpreters
                //       only).
                //
                activeInterpreter.SavedShellArguments = savedArgv;

                //
                // NOTE: Initially, start out with no extra shell arguments.
                //       Later on, if a script ends up modifying this list,
                //       those arguments will be prepended to the front of
                //       the list of command line arguments being processed
                //       by this method.
                //
                activeInterpreter.ShellArguments = null;

                //
                // NOTE: Save the shell callback data for this thread using
                //       the interactive context for the interpreter.
                //
                activeInterpreter.ShellCallbackData = localCallbackData;

                //
                // NOTE: Initially, grab each of the shell callbacks from
                //       the interpreter itself if they were not provided
                //       by our direct caller.
                //
                /* NO RESULT */
                activeInterpreter.RefreshShellCallbacks();
            }

            //
            // NOTE: Get the file name(s) that started the current process.
            //
            string executableFileName = PathOps.GetExecutableName();
            string managedExecutableFileName = PathOps.GetManagedExecutableName();

            //
            // NOTE: Get the file name where additional command line
            //       arguments may be found.
            //
            StringList argvFileNames = ShellOps.GetArgumentsFileNames(
                managedExecutableFileName);

            //
            // NOTE: Determine if the arguments file, if any, should really
            //       be used.
            //
            bool useArgvFileNames = ShellOps.ShouldUseArgumentsFileNames(
                argv);

            //
            // NOTE: Determine if the AppSettings, if any, should really be
            //       used.
            //
            bool useAppSettings = ShellOps.ShouldUseArgumentsAppSettings(
                argv);

            //
            // NOTE: Fetch the interpreter host now for result reporting
            //       purposes.
            //
            // NOTE: Also, during shell argument processing, should we
            //       attempt to be as quiet as possible?
            //
            IInteractiveHost interactiveHost = null;

            if (!whatIf)
                interactiveHost = activeInterpreter.GetInteractiveHost();

            //
            // NOTE: If the quiet flag for this method ends up being set
            //       explicitly via the command line, stop automatically
            //       refreshing it.
            //
            bool refreshQuiet = true;

            if (!whatIf && refreshQuiet)
                quiet = activeInterpreter.ShouldBeQuiet();

            //
            // NOTE: This may end up containing the built command line for
            //       use when emitting trace messages.
            //
            string commandLine; /* REUSED */
            bool done; /* REUSED */

            //
            // NOTE: In debug mode, show the command line arguments just
            //       as we received them.
            //
            if (!whatIf && activeInterpreter.Debug)
            {
                HostOps.WriteLineOrConsole(interactiveHost, String.Format(
                    "The executable file name is: {0}", executableFileName));

                HostOps.WriteLineOrConsole(interactiveHost, String.Format(
                    "The managed executable file name is: {0}",
                    managedExecutableFileName));

                done = false;

                commandLine = RuntimeOps.BuildCommandLine(
                    activeInterpreter, argv, null, true, false,
                    false, ref done, ref result);

                if (done)
                    goto done;

                if (commandLine == null)
                {
                    HostOps.WriteConsoleOrComplain(
                        ReturnCode.Error, result);

                    exitCode = ShellOps.FailureExitCode(
                        activeInterpreter);

                    goto done;
                }

                HostOps.WriteLineOrConsole(interactiveHost, String.Format(
                    "The original command line arguments are: {0}",
                    !String.IsNullOrEmpty(commandLine) ? commandLine :
                    FormatOps.DisplayNone));

                HostOps.WriteLineOrConsole(interactiveHost, String.Format(
                    "Use of arguments file name is: {0}", useArgvFileNames ?
                    "enabled" : "disabled"));

                HostOps.WriteLineOrConsole(interactiveHost, String.Format(
                    "Use of application settings is: {0}", useAppSettings ?
                    "enabled" : "disabled"));

                HostOps.WriteLineOrConsole(interactiveHost, String.Format(
                    "The arguments file names are: {0}",
                    FormatOps.DisplayList(argvFileNames)));

#if ENTERPRISE_LOCKDOWN || MAYBE_ENTERPRISE_LOCKDOWN
                if (IsEnterpriseLockdownEnabled())
                {
                    HostOps.WriteLineOrConsole(interactiveHost,
                        "Enterprise script certificate enforcement is locked.");
                }
#endif
            }

            //
            // NOTE: We need the return code and error line all over the
            //       place in this method.
            //
            ReturnCode code;
            int errorLine = 0;

            //
            // NOTE: If this is non-zero, it indicates that a brand new
            //       interpreter must be created an option is processed
            //       that requires mutating the current interpreter is
            //       being handled, e.g. "-safe" and/or "-standard".
            //
            bool[] create = new bool[] {
                false, /* FORCE NEW?      */
                false, /* FORCE CHILD?    */
                false, /* FORCE SAFE?     */
                false  /* FORCE STANDARD? */
            };

            if (!whatIf)
            {
                create[2] = activeInterpreter.InternalIsSafe();
                create[3] = activeInterpreter.InternalIsStandard();
            }

            //
            // NOTE: How many arguments were added to the command line by
            //       the host, argument files, application settings, etc?
            //
            IList<string> readArgv = null;

            //
            // NOTE: If this is non-zero, the command line arguments were
            //       "locked" by the interpreter host and other arguments
            //       are being ignored.  Its value will be checked if the
            //       interpreter is recreated via the "-recreate" command
            //       line option and it causes the startup-phase options
            //       (i.e. the creation flags, the pre-initialize text,
            //       and the library path) to be silently discarded.
            //
            bool lockArgv = false;

            //
            // NOTE: If this is non-zero, the Trim() method will not be
            //       used on command line arguments.  By default, it will
            //       be used because some platforms (e.g. .NET Core) are
            //       broken with respect to preserving arguments that are
            //       empty strings (i.e. they *will* preserve an argument
            //       that consists solely of whitespace).
            //
            bool noTrim = false;

            //
            // NOTE: If this is non-zero, the interpreter initialization
            //       will be forced (i.e. it will be performed even if it
            //       has already been done).
            //
            bool forceInitialize = false;

            //
            // NOTE: If this value is non-zero after a file is evaluated,
            //       we enter the interactive loop instead of exiting the
            //       process.
            //
            bool noExit = false;

            //
            // NOTE: If this value is non-zero after the interactive loop
            //       exits, it will be entered again.
            //
            bool kiosk = false;

            //
            // NOTE: This is the number of times the interactive loop has
            //       been reentered due to the kiosk lock.
            //
            int kioskLoops = 0;

            //
            // NOTE: Command line usage information variables.
            //
            bool showOptions = false;
            bool showEnvironment = false;

            //
            // NOTE: This is the encoding to use for reading a script file.
            //       It can be set using the "-encoding" command-line option.
            //
            Encoding encoding = null;

            //
            // NOTE: Are use of the "arguments" files enabled?  If so, then
            //       attempt to obtain command line arguments from the file
            //       system and/or the interpreter host.
            //
            if (useArgvFileNames)
            {
                //
                // NOTE: First, attempt to read some additional command line
                //       arguments from the interpreter host.  It should be
                //       noted that a lack of command line arguments from
                //       the interpreter host is not a failure.
                //
                string hostArgvFileName = null;
                IList<string> hostArgv = null;
                int hostReadArgv = 0;
                ResultList errors = null;

                code = ShellOps.ReadArgumentsFromHost(
                    activeInterpreter, argvFileNames, encoding,
                    /* POP */ 0, false, false, ref hostArgvFileName,
                    ref hostArgv, ref hostReadArgv, ref errors);

                if (code == ReturnCode.Ok)
                {
                    if (!whatIf && activeInterpreter.Debug &&
                        (hostReadArgv > 0))
                    {
                        HostOps.WriteLineOrConsole(
                            interactiveHost, String.Format(
                            "Read arguments from host file: {0}",
                            FormatOps.WrapOrNull(hostArgvFileName)));
                    }
                }
                else
                {
                    result = errors;

                    exitCode = ShellOps.ReturnCodeToExitCode(
                        activeInterpreter, code, true);

                    goto done;
                }

                //
                // NOTE: Were some command line arguments actually read from
                //       the interpreter host?
                //
                if (hostReadArgv > 0)
                {
                    //
                    // NOTE: If the interpreter host locked the command line
                    //       arguments to the ones it provided, replace all
                    //       of the original command line arguments with those
                    //       -AND- skip checking the file system for any more;
                    //       otherwise, append the command line arguments
                    //       provided by the interpreter host to the original
                    //       command line arguments -AND- continue checking
                    //       on the file system for any more.
                    //
                    if (ShellOps.ShouldLockHostArguments(hostArgv))
                    {
                        //
                        // BUGFIX: The script arguments must be synchronized
                        //         with the actual command line arguments to
                        //         process.
                        //
                        code = activeInterpreter.PrivateSetArguments(
                            hostArgv, whatIf, true, ref result);

                        if (code != ReturnCode.Ok)
                        {
                            exitCode = ShellOps.ReturnCodeToExitCode(
                                activeInterpreter, code, true);

                            goto done;
                        }

                        argv = hostArgv;
                        hostArgv = null;

                        readArgv = null; /* REDUNDANT */
                        lockArgv = true;

                        goto haveArgv;
                    }
                }

                //
                // NOTE: If the optional file containing additional command
                //       line arguments exits, attempt to read and process
                //       it now; otherwise, skip reading additional command
                //       line arguments from the file system.
                //
                string argvFileName = null;

                if (ShellOps.SomeFileExists(
                        argvFileNames, ref argvFileName) &&
                    ((hostReadArgv == 0) || !PathOps.IsEqualFileName(
                        argvFileName, hostArgvFileName)))
                {
                    code = ShellOps.ReadArgumentsFromFile(
                        activeInterpreter, encoding, argvFileName,
                        /* POP */ 0, false, false, ref readArgv,
                        ref result);

                    if (code == ReturnCode.Ok)
                    {
                        if (!whatIf && activeInterpreter.Debug)
                        {
                            HostOps.WriteLineOrConsole(
                                interactiveHost, String.Format(
                                "Read arguments from automatic file: {0}",
                                FormatOps.WrapOrNull(argvFileName)));
                        }
                    }
                    else
                    {
                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);

                        goto done;
                    }
                }

                //
                // NOTE: If allowed (and available), attempt to read some
                //       command line arguments from the AppSettings.
                //
                if (useAppSettings)
                {
                    code = ShellOps.ReadArgumentsFromAppSettings(
                        activeInterpreter, /* POP */ 0, false,
                        ref readArgv, ref result);

                    if (code == ReturnCode.Ok)
                    {
                        if (!whatIf && activeInterpreter.Debug)
                        {
                            HostOps.WriteLineOrConsole(interactiveHost,
                                "Read arguments from application settings.");
                        }
                    }
                    else
                    {
                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);

                        goto done;
                    }
                }

                //
                // NOTE: Were some command line arguments actually read
                //       from the interpreter host, without the locking
                //       option being set?  If so, add them now.
                //
                if (!lockArgv && (hostReadArgv > 0) && (hostArgv != null))
                {
                    ShellOps.CommitToArguments(
                        hostArgv, /* POP */ 0, false, ref readArgv);
                }

            haveArgv:

                //
                // NOTE: In debug mode, always show the modified command
                //       line arguments.
                //
                if (!whatIf && activeInterpreter.Debug)
                {
                    done = false;

                    commandLine = RuntimeOps.BuildCommandLine(
                        activeInterpreter, argv, null, true, false,
                        false, ref done, ref result);

                    if (done)
                        goto done;

                    if (commandLine == null)
                    {
                        HostOps.WriteConsoleOrComplain(
                            ReturnCode.Error, result);

                        exitCode = ShellOps.FailureExitCode(
                            activeInterpreter);

                        goto done;
                    }

                    HostOps.WriteLineOrConsole(
                        interactiveHost, String.Format(
                        "The read command line arguments are: {0}",
                        !String.IsNullOrEmpty(commandLine) ?
                            commandLine : FormatOps.DisplayNone));
                }
            }

#if TEST
            //
            // NOTE: Clear out list of processed command line options
            //       for this thread.
            //
            _Tests.Default.TestShellClearArguments();
#endif

            //
            // NOTE: How many times have we hit the "retry" label when
            //       processing command line arguments?
            //
            int retries = 0;

            //
            // NOTE: How many of the command line arguments have been
            //       need to be removed from their associated script
            //       variable (i.e. "argv") before evaluating the next
            //       user script -OR- entering the interactive loop?
            //
            int removeArgv = 0;

        readArgv:

            //
            // NOTE: If any command line arguments were read from files
            //       and/or application settings, try to add them now.
            //
            if (readArgv != null)
            {
                if (activeInterpreter.MaybeAddArguments(
                        whatIf, ref removeArgv, ref argv, readArgv,
                        ref result) != ReturnCode.Ok)
                {
                    ShellOps.ShellMainCoreError(
                        activeInterpreter, null, null, String.Format(
                        "could not add shell arguments {0} from files " +
                        "and/or settings", FormatOps.WrapOrNull(readArgv)),
                        whatIf, ref argv, ref interactiveHost, ref quiet,
                        ref result);

                    exitCode = ShellOps.FailureExitCode(activeInterpreter);

                    goto done;
                }

                readArgv = null;
            }

        retryArgv: // NOTE: Used to continue processing arguments.

            //
            // NOTE: Initially, this value will be "1"; subsequently,
            //       this will be incremented every time another one
            //       of the command line arguments needs to continue
            //       processing more command line arguments, not for
            //       "terminal" command line arguments like "-file",
            //       et al.
            //
            retries++;

            //
            // HACK: This if statement should not be strictly needed
            //       here because we should never get to this point
            //       with a null active interpreter; however, we may
            //       (?) need to placate static analysis tools.
            //
            if (activeInterpreter == null) /* IMPOSSIBLE (?) */
            {
                result = "invalid active interpreter";

                if (!whatIf)
                {
                    HostOps.WriteConsoleOrComplain(
                        ReturnCode.Error, result);
                }

                exitCode = ShellOps.FailureExitCode(
                    activeInterpreter);

                goto done;
            }

            //
            // NOTE: In debug mode, always show the modified command
            //       line arguments.
            //
            if (!whatIf && activeInterpreter.Debug)
            {
                done = false;

                commandLine = RuntimeOps.BuildCommandLine(
                    activeInterpreter, argv, null, true, false,
                    false, ref done, ref result);

                if (done)
                    goto done;

                if (commandLine == null)
                {
                    HostOps.WriteConsoleOrComplain(
                        ReturnCode.Error, result);

                    exitCode = ShellOps.FailureExitCode(
                        activeInterpreter);

                    goto done;
                }

                HostOps.WriteLineOrConsole(
                    interactiveHost, String.Format(
                    "Retry #{0} entry command line arguments are: {1}",
                    retries, !String.IsNullOrEmpty(commandLine) ?
                        commandLine : FormatOps.DisplayNone));
            }

            //
            // NOTE: Check and see if additional command line arguments
            //       need to be added based on those present within the
            //       interactive context for the active interpreter.
            //       This will be skipped if the command line arguments
            //       are locked.
            //
            if (!lockArgv)
            {
                IList<string> shellArguments =
                    activeInterpreter.ShellArguments;

                if (activeInterpreter.MaybeAddArguments(
                        whatIf, ref removeArgv, ref argv, shellArguments,
                        ref result) != ReturnCode.Ok)
                {
                    ShellOps.ShellMainCoreError(
                        activeInterpreter, null, null, String.Format(
                        "could not add shell arguments {0} from the " +
                        "interactive context", FormatOps.WrapOrNull(
                        shellArguments)), whatIf, ref argv,
                        ref interactiveHost, ref quiet, ref result);

                    exitCode = ShellOps.FailureExitCode(activeInterpreter);

                    goto done;
                }
            }

            //
            // NOTE: Re-fetch the number of command line arguments, as
            //       it has either never been fetched -OR- it has been
            //       changed.
            //
            int argc = (argv != null) ? argv.Count : 0;

            //
            // NOTE: Re-fetch interpreter host in case it has changed
            //       out from under us during argument processing.
            //
            if (!whatIf)
                interactiveHost = activeInterpreter.GetInteractiveHost();

            if (argc > 0)
            {
                //
                // NOTE: This is the starting argument index to use.
                //       Generally, this should always be zero.  The
                //       argument list will be modified as we process
                //       each argument.
                //
                int argIndex = 0;

                //
                // NOTE: Grab the first, second, and third arguments
                //       from the list, possibly invoking an argument
                //       preview callback.  Handle errors by halting
                //       further argument processing.
                //
                string arg0;
                string savedArg0;
                bool gotArg0;

                if (ShellOps.MaybeGetAndPreviewArgument(
                        activeInterpreter, localCallbackData, clientData,
                        ArgumentPhase.Phase0, noTrim, whatIf,
                        ref interactiveHost, ref argIndex, out arg0,
                        out gotArg0, out savedArg0, ref argv, ref result,
                        ref quiet, ref exitCode) != ReturnCode.Ok)
                {
                    goto doneArgs;
                }

                string arg1;
                string savedArg1;
                bool gotArg1;

                if (ShellOps.MaybeGetAndPreviewArgument(
                        activeInterpreter, localCallbackData, clientData,
                        ArgumentPhase.Phase0, noTrim, whatIf,
                        ref interactiveHost, ref argIndex, out arg1,
                        out gotArg1, out savedArg1, ref argv, ref result,
                        ref quiet, ref exitCode) != ReturnCode.Ok)
                {
                    goto doneArgs;
                }

                string arg2;
                string savedArg2;
                bool gotArg2;

                if (ShellOps.MaybeGetAndPreviewArgument(
                        activeInterpreter, localCallbackData, clientData,
                        ArgumentPhase.Phase0, noTrim, whatIf,
                        ref interactiveHost, ref argIndex, out arg2,
                        out gotArg2, out savedArg2, ref argv, ref result,
                        ref quiet, ref exitCode) != ReturnCode.Ok)
                {
                    goto doneArgs;
                }

                //
                // NOTE: By default, the arguments for a command line
                //       option need to be removed (i.e. popped) from
                //       its handler; however, when "goto option" is
                //       used, that must be skipped.
                //
                bool popArgv = true;

            option:

#if TEST
                //
                // NOTE: For testing purposes, attempt to keep track of
                //       all command line options that are processed by
                //       this method on this thread.
                //
                _Tests.Default.TestShellTrackArguments(
                    retries, removeArgv, false, argv);
#endif

                //
                // NOTE: At this point, a first argument is required.
                //       If there is none, we are done with processing
                //       arguments.  Maybe enter the interactive loop?
                //
                if (arg0 == null)
                {
                    argv = null;
                    goto retryArgv;
                }

                //
                // NOTE: This is the number of switch chars in front
                //       of the current argument.
                //
                int switchCount = 0;

                //
                // NOTE: This trims any leading switch chars from the
                //       current argument and sets the count to the
                //       number of switch chars actually removed.
                //
                arg0 = StringOps.TrimSwitchChars(arg0, ref switchCount);

                if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.AnyFile))
                {
                    if (arg1 != null)
                    {
                        removeArgv += 2;

                        code = activeInterpreter.MaybeRemoveArguments(
                            whatIf, ref removeArgv, ref result);

                        if ((code == ReturnCode.Ok) && !whatIf)
                        {
                            errorLine = 0;

                            code = activeInterpreter.ShellEvaluateFile(
                                localCallbackData, encoding, arg1,
                                ref result, ref errorLine);
                        }

                        if (code == ReturnCode.Ok)
                        {
                            //
                            // NOTE: The shell callbacks may have been
                            //       changed via the evaluated script;
                            //       therefore, refresh the ones which
                            //       were not directly supplied by the
                            //       caller.
                            //
                            if (!whatIf)
                            {
                                /* NO RESULT */
                                activeInterpreter.RefreshShellCallbacks();
                            }

                            //
                            // NOTE: Must refresh the quiet flag now as
                            //       it could have been changed by the
                            //       evaluated script.
                            //
                            if (!whatIf && refreshQuiet)
                                quiet = activeInterpreter.ShouldBeQuiet();

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto retryArgv;
                        }
                        else
                        {
                            //
                            // BUGFIX: We may have evaluated some code and
                            //         the host may have been changed; grab
                            //         it again.
                            //
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                GetShellErrorLine(activeInterpreter, errorLine),
                                true, true, whatIf, ref argv,
                                ref interactiveHost, ref quiet, ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <fileName>\"",
                            CommandLineOption.AnyFile), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
#if !ENTERPRISE_LOCKDOWN
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.AnyInitialize))
                {
#if MAYBE_ENTERPRISE_LOCKDOWN
                    if (IsEnterpriseLockdownEnabled())
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "cannot use command line option {0}: lockdown",
                            FormatOps.WrapOrNull(CommandLineOption.AnyInitialize)),
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                    else
#endif
                    {
                        if (arg1 != null)
                        {
                            removeArgv += 2;

                            code = activeInterpreter.MaybeRemoveArguments(
                                whatIf, ref removeArgv, ref result);

                            if ((code == ReturnCode.Ok) && !whatIf)
                            {
                                errorLine = 0;

                                code = activeInterpreter.ShellEvaluateScript(
                                    _ShellCallbackData.GetEvaluateScriptCallback(
                                        localCallbackData), arg1, ref result,
                                    ref errorLine);
                            }

                            if (code == ReturnCode.Ok)
                            {
                                //
                                // NOTE: The shell callbacks may have been
                                //       changed via the evaluated script;
                                //       therefore, refresh the ones which
                                //       were not directly supplied by the
                                //       caller.
                                //
                                if (!whatIf)
                                {
                                    /* NO RESULT */
                                    activeInterpreter.RefreshShellCallbacks();
                                }

                                //
                                // NOTE: Must refresh the quiet flag now as
                                //       it could have been changed by the
                                //       evaluated script.
                                //
                                if (!whatIf && refreshQuiet)
                                    quiet = activeInterpreter.ShouldBeQuiet();

                                if (popArgv)
                                {
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    popArgv = false;
                                }

                                goto retryArgv;
                            }
                            else
                            {
                                //
                                // BUGFIX: We may have evaluated some code and
                                //         the host may have been changed; grab
                                //         it again.
                                //
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0, code, result,
                                    GetShellErrorLine(activeInterpreter, errorLine),
                                    true, true, whatIf, ref argv,
                                    ref interactiveHost, ref quiet, ref result);
                            }

                            exitCode = ShellOps.ReturnCodeToExitCode(
                                activeInterpreter, code, true);
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, String.Format(
                                "wrong # args: should be \"-{0} <script>\"",
                                CommandLineOption.AnyInitialize), whatIf,
                                ref argv, ref interactiveHost, ref quiet,
                                ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                }
#endif
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Arguments))
                {
                    if (arg1 != null)
                    {
                        //
                        // NOTE: This method pops its own arguments from the
                        //       list.  The literal "2" in the parameter list
                        //       for ReadArgumentsFromFile is the number of
                        //       arguments that need to be popped from the
                        //       front of the list prior to appending any of
                        //       the arguments found in the specified file.
                        //
                        code = ShellOps.ReadArgumentsFromFile(
                            activeInterpreter, encoding, arg1,
                            /* POP */ 2, true, false, ref readArgv,
                            ref result);

                        if (code == ReturnCode.Ok)
                        {
                            if (!whatIf && activeInterpreter.Debug)
                            {
                                HostOps.WriteLineOrConsole(
                                    interactiveHost, String.Format(
                                    "Read arguments from specific file: {0}",
                                    FormatOps.WrapOrNull(arg1)));
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto readArgv;
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                whatIf, ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <fileName>\"",
                            CommandLineOption.Arguments), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Break))
                {
                    #region Requires Console Support
#if CONSOLE
                    if (!whatIf)
                    {
                        /* NO RESULT */
                        ConsoleOps.DebugBreak();
                    }
#endif
                    #endregion

                    ///////////////////////////////////////////////////////

                    //
                    // NOTE: Break into the managed debugger, skipping no
                    //       method to obtain the method name, and force
                    //       the issue because this is the result of a
                    //       direct user request.
                    //
                    if (!whatIf)
                    {
                        /* NO RESULT */
                        DebugOps.Break(
                            activeInterpreter, null, true); /* throw */
                    }

                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 1;

                    goto retryArgv;
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.ClearTrace))
                {
                    if (whatIf)
                    {
                        code = ReturnCode.Ok;
                    }
                    else
                    {
                        code = DebugOps.ClearTraceListeners(
                            true, activeInterpreter.Debug, true, true,
                            ref result);
                    }

                    if (code == ReturnCode.Ok)
                    {
                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 1;

                        goto retryArgv;
                    }

                    ShellOps.ShellMainCoreError(
                        activeInterpreter, savedArg0, arg0, code, result,
                        whatIf, ref argv, ref interactiveHost, ref quiet,
                        ref result);

                    exitCode = ShellOps.ReturnCodeToExitCode(
                        activeInterpreter, code, true);
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Child))
                {
                    removeArgv += 1;

                    code = activeInterpreter.MaybeRemoveArguments(
                        whatIf, ref removeArgv, ref result);

                    if (code == ReturnCode.Ok)
                    {
                        if (childInterpreter != null)
                        {
                            if (!whatIf)
                            {
                                create[1] = true;

                                if (!quiet)
                                {
                                    ShellOps.WritePrompt(activeInterpreter,
                                        _Constants.Prompt.Child);
                                }
                            }

                            activeInterpreter = childInterpreter;

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto retryArgv;
                        }
                        else if (create[0])
                        {
                            if (!whatIf)
                            {
                                create[1] = true;

                                if (!quiet)
                                {
                                    ShellOps.WritePrompt(activeInterpreter,
                                        _Constants.Prompt.Child);
                                }
                            }

                            activeInterpreter = null;

                            arg0 = Characters.MinusSign + CommandLineOption.Recreate;

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto option;
                        }
                        else if (!whatIf)
                        {
                            result = "child interpreter unavailable";
                        }
                        else
                        {
                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto retryArgv;
                        }
                    }

                    if (code != ReturnCode.Ok)
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, code, result,
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Debug))
                {
                    if (!whatIf)
