                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 1;

                    goto retryArgv;
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.NoExit))
                {
                    noExit = true;

#if DEBUGGER
                    activeInterpreter.EnableNoExit(true);
                    activeInterpreter.EnableIgnoreEnabled(true);
#endif

                    if (!whatIf && !quiet)
                    {
                        ShellOps.WritePrompt(interactiveHost,
                            _Constants.Prompt.NoExit);
                    }

                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 1;

                    goto retryArgv;
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.NoTrim))
                {
                    noTrim = true;

                    if (!whatIf && !quiet)
                    {
                        ShellOps.WritePrompt(interactiveHost,
                            _Constants.Prompt.NoTrim);
                    }

                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 1;

                    goto retryArgv;
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Parent))
                {
                    removeArgv += 1;

                    code = activeInterpreter.MaybeRemoveArguments(
                        whatIf, ref removeArgv, ref result);

                    if (code == ReturnCode.Ok)
                    {
                        if (parentInterpreter != null)
                        {
                            if (!whatIf)
                            {
                                create[1] = false;

                                if (!quiet)
                                {
                                    ShellOps.WritePrompt(activeInterpreter,
                                        _Constants.Prompt.Parent);
                                }
                            }

                            activeInterpreter = parentInterpreter;

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto retryArgv;
                        }
                        else if (!whatIf)
                        {
                            result = "parent interpreter unavailable";
                        }
                        else
                        {
                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto retryArgv;
                        }
                    }

                    if (code != ReturnCode.Ok)
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, code, result,
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Pause))
                {
                    if (whatIf || (interactiveHost != null)) /* EXEMPT */
                    {
                        if (!whatIf)
                        {
                            ShellOps.WritePrompt(
                                interactiveHost, String.Format(
                                _Constants.Prompt.Debugger,
                                ProcessOps.GetId()));

                            /* IGNORED */
                            interactiveHost.Pause();
                        }

                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 1;

                        goto retryArgv;
                    }
                    else
                    {
                        HostOps.WriteConsoleOrComplain(
                            ReturnCode.Error, "interpreter host not available");

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.PluginArguments))
                {
                    if ((arg1 != null) && (arg2 != null))
                    {
                        if (whatIf ||
                            (activeInterpreter.AddPluginArguments(arg1, arg2) > 0))
                        {
                            if (!whatIf && !quiet)
                            {
                                ShellOps.WritePrompt(
                                    interactiveHost, String.Format(
                                    _Constants.Prompt.PluginArguments,
                                    arg1));
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 3;

                            goto retryArgv;
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0,
                                "failed to add plugin arguments", whatIf,
                                ref argv, ref interactiveHost, ref quiet,
                                ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <pluginName> <arguments>\"",
                            CommandLineOption.PluginArguments), whatIf,
                            ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.PostFile))
                {
                    if (arg1 != null)
                    {
                        if (whatIf || activeInterpreter.PrivateInitialized)
                        {
                            removeArgv += 2;

                            code = activeInterpreter.MaybeRemoveArguments(
                                whatIf, ref removeArgv, ref result);

                            if ((code == ReturnCode.Ok) && !whatIf)
                            {
                                errorLine = 0;

                                code = activeInterpreter.ShellEvaluateFile(
                                    localCallbackData, encoding, arg1,
                                    ref result, ref errorLine);
                            }

                            if (code == ReturnCode.Ok)
                            {
                                //
                                // NOTE: The shell callbacks may have been
                                //       changed via the evaluated script;
                                //       therefore, refresh the ones which
                                //       were not directly supplied by the
                                //       caller.
                                //
                                if (!whatIf)
                                {
                                    /* NO RESULT */
                                    activeInterpreter.RefreshShellCallbacks();
                                }

                                //
                                // NOTE: Must refresh the quiet flag now as
                                //       it could have been changed by the
                                //       evaluated script.
                                //
                                if (!whatIf && refreshQuiet)
                                    quiet = activeInterpreter.ShouldBeQuiet();

                                if (popArgv)
                                {
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    popArgv = false;
                                }

                                goto retryArgv;
                            }
                            else
                            {
                                //
                                // BUGFIX: We may have evaluated some code and
                                //         the host may have been changed; grab
                                //         it again.
                                //
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0, code, result,
                                    GetShellErrorLine(activeInterpreter, errorLine),
                                    true, true, whatIf, ref argv,
                                    ref interactiveHost, ref quiet, ref result);
                            }

                            exitCode = ShellOps.ReturnCodeToExitCode(
                                activeInterpreter, code, true);
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0,
                                "script library is not initialized", whatIf,
                                ref argv, ref interactiveHost, ref quiet,
                                ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <fileName>\"",
                            CommandLineOption.PostFile), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
#if !ENTERPRISE_LOCKDOWN
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.PostInitialize))
                {
#if MAYBE_ENTERPRISE_LOCKDOWN
                    if (IsEnterpriseLockdownEnabled())
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "cannot use command line option {0}: lockdown",
                            FormatOps.WrapOrNull(CommandLineOption.PostInitialize)),
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                    else
#endif
                    {
                        if (arg1 != null)
                        {
                            if (whatIf || activeInterpreter.PrivateInitialized)
                            {
                                removeArgv += 2;

                                code = activeInterpreter.MaybeRemoveArguments(
                                    whatIf, ref removeArgv, ref result);

                                if ((code == ReturnCode.Ok) && !whatIf)
                                {
                                    errorLine = 0;

                                    code = activeInterpreter.ShellEvaluateScript(
                                        _ShellCallbackData.GetEvaluateScriptCallback(
                                            localCallbackData), arg1, ref result,
                                        ref errorLine);
                                }

                                if (code == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: The shell callbacks may have been
                                    //       changed via the evaluated script;
                                    //       therefore, refresh the ones which
                                    //       were not directly supplied by the
                                    //       caller.
                                    //
                                    if (!whatIf)
                                    {
                                        /* NO RESULT */
                                        activeInterpreter.RefreshShellCallbacks();
                                    }

                                    //
                                    // NOTE: Must refresh the quiet flag now as
                                    //       it could have been changed by the
                                    //       evaluated script.
                                    //
                                    if (!whatIf && refreshQuiet)
                                        quiet = activeInterpreter.ShouldBeQuiet();

                                    if (popArgv)
                                    {
                                        GenericOps<string>.PopFirstArgument(ref argv);
                                        GenericOps<string>.PopFirstArgument(ref argv);
                                        popArgv = false;
                                    }

                                    goto retryArgv;
                                }
                                else
                                {
                                    //
                                    // BUGFIX: We may have evaluated some code and
                                    //         the host may have been changed; grab
                                    //         it again.
                                    //
                                    ShellOps.ShellMainCoreError(
                                        activeInterpreter, savedArg0, arg0, code, result,
                                        GetShellErrorLine(activeInterpreter, errorLine),
                                        true, true, whatIf, ref argv,
                                        ref interactiveHost, ref quiet, ref result);
                                }

                                exitCode = ShellOps.ReturnCodeToExitCode(
                                    activeInterpreter, code, true);
                            }
                            else
                            {
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0,
                                    "script library is not initialized", whatIf,
                                    ref argv, ref interactiveHost, ref quiet,
                                    ref result);

                                exitCode = ShellOps.FailureExitCode(activeInterpreter);
                            }
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, String.Format(
                                "wrong # args: should be \"-{0} <script>\"",
                                CommandLineOption.PostInitialize), whatIf,
                                ref argv, ref interactiveHost, ref quiet,
                                ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                }
#endif
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.PreFile))
                {
                    if (arg1 != null)
                    {
                        if (whatIf || !activeInterpreter.PrivateInitialized)
                        {
                            removeArgv += 2;

                            code = activeInterpreter.MaybeRemoveArguments(
                                whatIf, ref removeArgv, ref result);

                            if ((code == ReturnCode.Ok) && !whatIf)
                            {
                                errorLine = 0;

                                code = activeInterpreter.ShellEvaluateFile(
                                    localCallbackData, encoding, arg1,
                                    ref result, ref errorLine);
                            }

                            if (code == ReturnCode.Ok)
                            {
                                //
                                // NOTE: The shell callbacks may have been
                                //       changed via the evaluated script;
                                //       therefore, refresh the ones which
                                //       were not directly supplied by the
                                //       caller.
                                //
                                if (!whatIf)
                                {
                                    /* NO RESULT */
                                    activeInterpreter.RefreshShellCallbacks();
                                }

                                //
                                // NOTE: Must refresh the quiet flag now as
                                //       it could have been changed by the
                                //       evaluated script.
                                //
                                if (!whatIf && refreshQuiet)
                                    quiet = activeInterpreter.ShouldBeQuiet();

                                if (popArgv)
                                {
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    popArgv = false;
                                }

                                goto retryArgv;
                            }
                            else
                            {
                                //
                                // BUGFIX: We may have evaluated some code and
                                //         the host may have been changed; grab
                                //         it again.
                                //
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0, code, result,
                                    GetShellErrorLine(activeInterpreter, errorLine),
                                    true, true, whatIf, ref argv,
                                    ref interactiveHost, ref quiet, ref result);
                            }

                            exitCode = ShellOps.ReturnCodeToExitCode(
                                activeInterpreter, code, true);
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0,
                                "script library is already initialized",
                                whatIf, ref argv, ref interactiveHost,
                                ref quiet, ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <fileName>\"",
                            CommandLineOption.PreFile), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
#if !ENTERPRISE_LOCKDOWN
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.PreInitialize))
                {
#if MAYBE_ENTERPRISE_LOCKDOWN
                    if (IsEnterpriseLockdownEnabled())
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "cannot use command line option {0}: lockdown",
                            FormatOps.WrapOrNull(CommandLineOption.PreInitialize)),
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                    else
#endif
                    {
                        if (arg1 != null)
                        {
                            if (whatIf || !activeInterpreter.PrivateInitialized)
                            {
                                removeArgv += 2;

                                code = activeInterpreter.MaybeRemoveArguments(
                                    whatIf, ref removeArgv, ref result);

                                if ((code == ReturnCode.Ok) && !whatIf)
                                {
                                    errorLine = 0;

                                    code = activeInterpreter.ShellEvaluateScript(
                                        _ShellCallbackData.GetEvaluateScriptCallback(
                                            localCallbackData), arg1, ref result,
                                        ref errorLine);
                                }

                                if (code == ReturnCode.Ok)
                                {
                                    //
                                    // NOTE: The shell callbacks may have been
                                    //       changed via the evaluated script;
                                    //       therefore, refresh the ones which
                                    //       were not directly supplied by the
                                    //       caller.
                                    //
                                    if (!whatIf)
                                    {
                                        /* NO RESULT */
                                        activeInterpreter.RefreshShellCallbacks();
                                    }

                                    //
                                    // NOTE: Must refresh the quiet flag now as
                                    //       it could have been changed by the
                                    //       evaluated script.
                                    //
                                    if (!whatIf && refreshQuiet)
                                        quiet = activeInterpreter.ShouldBeQuiet();

                                    if (popArgv)
                                    {
                                        GenericOps<string>.PopFirstArgument(ref argv);
                                        GenericOps<string>.PopFirstArgument(ref argv);
                                        popArgv = false;
                                    }

                                    goto retryArgv;
                                }
                                else
                                {
                                    //
                                    // BUGFIX: We may have evaluated some code and
                                    //         the host may have been changed; grab
                                    //         it again.
                                    //
                                    ShellOps.ShellMainCoreError(
                                        activeInterpreter, savedArg0, arg0, code, result,
                                        GetShellErrorLine(activeInterpreter, errorLine),
                                        true, true, whatIf, ref argv,
                                        ref interactiveHost, ref quiet, ref result);
                                }

                                exitCode = ShellOps.ReturnCodeToExitCode(
                                    activeInterpreter, code, true);
                            }
                            else
                            {
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0,
                                    "script library is already initialized",
                                    whatIf, ref argv, ref interactiveHost,
                                    ref quiet, ref result);

                                exitCode = ShellOps.FailureExitCode(activeInterpreter);
                            }
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, String.Format(
                                "wrong # args: should be \"-{0} <script>\"",
                                CommandLineOption.PreInitialize), whatIf,
                                ref argv, ref interactiveHost, ref quiet,
                                ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                }
#endif
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Profile))
                {
                    if (arg1 != null)
                    {
                        if (whatIf || (HostOps.LoadProfile(
                                activeInterpreter, interactiveHost, arg1,
                                encoding, ref result) == ReturnCode.Ok))
                        {
                            if (!whatIf && !quiet)
                            {
                                ShellOps.WritePrompt(
                                    interactiveHost, String.Format(
                                    _Constants.Prompt.Profile, arg1));
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }
                        else
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, String.Format(
                                "failed to reload host profile: {0}", result),
                                whatIf, ref argv, ref interactiveHost,
                                ref quiet, ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <profile>\"",
                            CommandLineOption.Profile), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Quiet))
                {
                    if (arg1 != null)
                    {
                        bool enable = false;

                        code = Value.GetBoolean2(
                            arg1, ValueFlags.AnyBoolean,
                            ShellOps.GetCultureInfo(activeInterpreter),
                            ref enable, ref result);

                        if (code == ReturnCode.Ok)
                        {
                            quiet = enable;
                            refreshQuiet = false;

                            if (!whatIf && !quiet)
                            {
                                ShellOps.WritePrompt(
                                    interactiveHost, String.Format(
                                    _Constants.Prompt.Quiet, enable ?
                                        "enabled" : "disabled",
                                    _Constants.Prompt.ViaCommandLine));
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }

                        if (code != ReturnCode.Ok)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                whatIf, ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <enable>\"",
                            CommandLineOption.Quiet), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Reconfigure))
                {
                    if (arg1 != null)
                    {
                        if (activeInterpreter != null)
                        {
                            removeArgv += 2;

                            code = activeInterpreter.MaybeRemoveArguments(
                                whatIf, ref removeArgv, ref result);
                        }
                        else
                        {
                            //
                            // HACK: The script arguments for the active
                            //       interpreter are going away, because
                            //       it will be disposed; therefore, we
                            //       have have nothing to remove later.
                            //
                            removeArgv = 0;

                            code = ReturnCode.Ok;
                        }

                        if (code == ReturnCode.Ok)
                        {
                            bool wasParent = Object.ReferenceEquals(
                                activeInterpreter, parentInterpreter);

                            if (!create[1] || !wasParent)
                            {
                                bool wasIsolated;
                                bool wasSecurity;

                                IInterpreterSettings interpreterSettings = null;

                                if (activeInterpreter != null)
                                {
#if ISOLATED_PLUGINS
                                    wasIsolated = AppDomainOps.IsIsolated(activeInterpreter);
#else
                                    wasIsolated = false;
#endif

                                    wasSecurity = activeInterpreter.HasSecurity();

                                    code = InterpreterSettings.LoadFrom(arg1,
                                        activeInterpreter.InternalCultureInfo, false,
                                        true, ref interpreterSettings, ref result);
                                }
                                else
                                {
#if ISOLATED_PLUGINS
                                    wasIsolated = AppDomainOps.IsIsolated(interpreter);
#else
                                    wasIsolated = false;
#endif

                                    wasSecurity = interpreter.HasSecurity(); /* EXEMPT */

                                    code = InterpreterSettings.LoadFrom(arg1,
                                        interpreter.InternalCultureInfo, false,
                                        true, ref interpreterSettings, ref result);
                                }

                                if (code == ReturnCode.Ok)
                                {
                                    invalidInterpreter = true;

                                    try
                                    {
                                        if (activeInterpreter != null)
                                        {
                                            if (!whatIf)
                                            {
                                                //
                                                // NOTE: We plan on re-creating the active
                                                //       interpreter (below); therefore, we
                                                //       must dispose the current one first.
                                                //
                                                if (wasParent)
                                                {
                                                    activeInterpreter.Dispose(); /* throw */
                                                }
                                                else if (childName != null)
                                                {
                                                    parentInterpreter.RemoveChildInterpreterOrComplain(
                                                        childName, null, true);
                                                }
                                                else
                                                {
                                                    activeInterpreter.Dispose(); /* throw */
                                                }

                                                activeInterpreter = null;

                                                if (wasParent)
                                                {
                                                    parentInterpreter = null;
                                                    childInterpreter = null;
                                                }
                                                else
                                                {
                                                    childInterpreter = null;
                                                }

                                                invalidInterpreter = false;

                                                //
                                                // NOTE: If this command line option has
                                                //       been used before, the disposal
                                                //       flag will be set (i.e. because
                                                //       we created the interpreter that
                                                //       was just disposed).  Therefore,
                                                //       reset it now since the disposal
                                                //       of the interpreter is complete.
                                                //
                                                dispose = false;
                                                disposeInterpreter = null;
                                                disposeChild = false;
                                            }
                                        }
                                    }
                                    catch (Exception e)
                                    {
                                        result = e;
                                        code = ReturnCode.Error;
                                    }
                                }

                                if (code == ReturnCode.Ok)
                                {
                                    if (!whatIf)
                                    {
                                        if (create[2])
                                            interpreterSettings.MakeSafe();

                                        if (create[3])
                                            interpreterSettings.MakeStandard();

                                        if (create[1])
                                        {
                                            if (parentInterpreter.CreateChildInterpreter(
                                                    null, clientData, interpreterSettings,
                                                    wasIsolated, wasSecurity,
                                                    ref result) == ReturnCode.Ok)
                                            {
                                                childName = result;

                                                if (parentInterpreter.GetNestedChildInterpreter(
                                                        childName, LookupFlags.Interpreter,
                                                        false, ref activeInterpreter,
                                                        ref result) != ReturnCode.Ok)
                                                {
                                                    activeInterpreter = null; /* REDUNDANT? */
                                                }
                                            }
                                            else
                                            {
                                                activeInterpreter = null; /* REDUNDANT */
                                            }
                                        }
                                        else
                                        {
                                            activeInterpreter = Create(
                                                interpreterSettings, true, ref result);
                                        }
                                    }

                                    if (activeInterpreter != null)
                                    {
                                        if (!whatIf)
                                        {
                                            //
                                            // NOTE: This method has now re-created the
                                            //       active interpreter; therefore, it
                                            //       must be disposed by this method
                                            //       before exiting.  Record the exact
                                            //       interpreter we created (and whether
                                            //       it is a child) so the disposal at
                                            //       the end targets it -- and never the
                                            //       caller-owned parent unless we
                                            //       actually re-created the parent.
                                            //
                                            dispose = true;
                                            disposeInterpreter = activeInterpreter;
                                            disposeChild = create[1];

                                            if (wasParent)
                                                parentInterpreter = activeInterpreter;
                                            else
                                                childInterpreter = activeInterpreter;
                                        }

                                        if (!whatIf && !quiet)
                                        {
                                            ShellOps.WritePrompt(activeInterpreter,
                                                String.Format(_Constants.Prompt.Reconfigure,
                                                wasParent ? "Parent" : "Child",
                                                FormatOps.InterpreterNoThrow(activeInterpreter),
                                                arg1));
                                        }

                                        if (popArgv)
                                        {
                                            GenericOps<string>.PopFirstArgument(ref argv);
                                            GenericOps<string>.PopFirstArgument(ref argv);
                                            popArgv = false;
                                        }

                                        goto retryArgv;
                                    }
                                    else
                                    {
                                        code = ReturnCode.Error;
                                    }
                                }

                                if (code != ReturnCode.Ok)
                                {
                                    ShellOps.ShellMainCoreError(
                                        activeInterpreter, savedArg0, arg0, code, result,
                                        whatIf, ref argv, ref interactiveHost, ref quiet,
                                        ref result);
                                }

                                exitCode = ShellOps.ReturnCodeToExitCode(
                                    activeInterpreter, code, true);
                            }
                            else if (!whatIf)
                            {
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0,
                                    "cannot reconfigure parent interpreter " +
                                    "with child interpreter", whatIf, ref argv,
                                    ref interactiveHost, ref quiet, ref result);

                                exitCode = ShellOps.FailureExitCode(activeInterpreter);
                            }
                            else
                            {
                                if (popArgv)
                                {
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    GenericOps<string>.PopFirstArgument(ref argv);
                                    popArgv = false;
                                }

                                goto retryArgv;
                            }
                        }
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <settings>\"",
                            CommandLineOption.Reconfigure), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Recreate))
                {
                    if (activeInterpreter != null)
                    {
                        removeArgv += 1;

                        code = activeInterpreter.MaybeRemoveArguments(
                            whatIf, ref removeArgv, ref result);
                    }
                    else
                    {
                        //
                        // HACK: The script arguments for the active
                        //       interpreter are going away, because
                        //       it will be disposed; therefore, we
                        //       have have nothing to remove later.
                        //
                        removeArgv = 0;

                        code = ReturnCode.Ok;
                    }

                    if (code == ReturnCode.Ok)
                    {
                        bool wasParent = Object.ReferenceEquals(
                            activeInterpreter, parentInterpreter);

                        if (!create[1] || !wasParent)
                        {
                            bool wasIsolated;
                            bool wasSecurity;

                            IInterpreterSettings interpreterSettings = null;

                            if (activeInterpreter != null)
                            {
#if ISOLATED_PLUGINS
                                wasIsolated = AppDomainOps.IsIsolated(activeInterpreter);
#else
                                wasIsolated = false;
#endif

                                wasSecurity = activeInterpreter.HasSecurity();

                                code = InterpreterSettings.LoadFrom(
                                    activeInterpreter, true, true, false,
                                    ref interpreterSettings, ref result);
                            }
                            else
                            {
#if ISOLATED_PLUGINS
                                wasIsolated = AppDomainOps.IsIsolated(interpreter); /* EXEMPT */
#else
                                wasIsolated = false;
#endif

                                wasSecurity = interpreter.HasSecurity(); /* EXEMPT */

                                code = InterpreterSettings.LoadFrom(
                                    interpreter, true, true, false, /* EXEMPT */
                                    ref interpreterSettings, ref result);
                            }

                            if (code == ReturnCode.Ok)
                            {
                                if (lockArgv)
                                {
                                    code = InterpreterSettings.UseStartupDefaults(
                                        interpreterSettings, CreateFlags.CoreShellUse,
                                        HostCreateFlags.CoreShellUse, ref result);
                                }
                                else
                                {
                                    /* NO RESULT */
                                    InterpreterSettings.CheckPoliciesAndTraces(
                                        interpreterSettings);
                                }
                            }

                            if (code == ReturnCode.Ok)
                            {
                                invalidInterpreter = true;

                                try
                                {
                                    if (activeInterpreter != null)
                                    {
                                        if (!whatIf)
                                        {
                                            //
                                            // NOTE: We plan on re-creating the active
                                            //       interpreter (below); therefore, we
                                            //       must dispose the current one first.
                                            //
                                            if (wasParent)
                                            {
                                                activeInterpreter.Dispose(); /* throw */
                                            }
                                            else if (childName != null)
                                            {
                                                parentInterpreter.RemoveChildInterpreterOrComplain(
                                                    childName, null, true);
                                            }
                                            else
                                            {
                                                activeInterpreter.Dispose(); /* throw */
                                            }

                                            activeInterpreter = null;

                                            if (wasParent)
                                            {
                                                parentInterpreter = null;
                                                childInterpreter = null;
                                            }
                                            else
                                            {
                                                childInterpreter = null;
                                            }

                                            invalidInterpreter = false;

                                            //
                                            // NOTE: If this command line option has
                                            //       been used before, the disposal
                                            //       flag will be set (i.e. because
                                            //       we created the interpreter that
                                            //       was just disposed).  Therefore,
                                            //       reset it now since the disposal
                                            //       of the interpreter is complete.
                                            //
                                            dispose = false;
                                            disposeInterpreter = null;
                                            disposeChild = false;
                                        }
                                    }
                                }
                                catch (Exception e)
                                {
                                    result = e;
                                    code = ReturnCode.Error;
                                }
                            }

                            if (code == ReturnCode.Ok)
                            {
                                if (!whatIf)
                                {
                                    if (create[2])
                                        interpreterSettings.MakeSafe();

                                    if (create[3])
                                        interpreterSettings.MakeStandard();

                                    if (create[1])
                                    {
                                        if (parentInterpreter.CreateChildInterpreter(
                                                null, clientData, interpreterSettings,
                                                wasIsolated, wasSecurity,
                                                ref result) == ReturnCode.Ok)
                                        {
                                            childName = result;

                                            if (parentInterpreter.GetNestedChildInterpreter(
                                                    childName, LookupFlags.Interpreter,
                                                    false, ref activeInterpreter,
                                                    ref result) != ReturnCode.Ok)
                                            {
                                                activeInterpreter = null; /* REDUNDANT? */
                                            }
                                        }
                                        else
                                        {
                                            activeInterpreter = null; /* REDUNDANT */
                                        }
                                    }
                                    else
                                    {
                                        activeInterpreter = Create(
                                            interpreterSettings, true, ref result);
                                    }
                                }

                                if (activeInterpreter != null)
                                {
                                    if (!whatIf)
                                    {
                                        //
                                        // NOTE: This method has now re-created the
                                        //       active interpreter; therefore, it
                                        //       must be disposed by this method
                                        //       before exiting.  Record the exact
                                        //       interpreter we created (and whether
                                        //       it is a child) so the disposal at
                                        //       the end targets it -- and never the
                                        //       caller-owned parent unless we
                                        //       actually re-created the parent.
                                        //
                                        dispose = true;
                                        disposeInterpreter = activeInterpreter;
                                        disposeChild = create[1];

                                        if (wasParent)
                                            parentInterpreter = activeInterpreter;
                                        else
                                            childInterpreter = activeInterpreter;
                                    }

                                    if (!whatIf && !quiet)
                                    {
                                        ShellOps.WritePrompt(activeInterpreter,
                                            String.Format(_Constants.Prompt.Recreate,
                                            wasParent ? "Parent" : "Child",
                                            FormatOps.InterpreterNoThrow(activeInterpreter)));
                                    }

                                    if (popArgv)
                                    {
                                        GenericOps<string>.PopFirstArgument(ref argv);
                                        popArgv = false;
                                    }

                                    goto retryArgv;
                                }
                                else
                                {
                                    code = ReturnCode.Error;
                                }
                            }

                            if (code != ReturnCode.Ok)
                            {
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0, code, result,
                                    whatIf, ref argv, ref interactiveHost, ref quiet,
                                    ref result);
                            }

                            exitCode = ShellOps.ReturnCodeToExitCode(
                                activeInterpreter, code, true);
                        }
                        else if (!whatIf)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0,
                                "cannot recreate parent interpreter " +
                                "with child interpreter", whatIf, ref argv,
                                ref interactiveHost, ref quiet, ref result);

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                        else
                        {
                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            goto retryArgv;
                        }
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.RuntimeOption))
                {
                    if (arg1 != null)
                    {
                        bool setVariable;
                        bool notify;

                        if (whatIf || activeInterpreter.PrivateInitialized)
                        {
                            setVariable = true;
                            notify = true;
                        }
                        else
                        {
                            setVariable = false;
                            notify = false;
                        }

                        if (whatIf ||
                            activeInterpreter.PrivateChangeRuntimeOption(
                                arg1, setVariable, notify))
                        {
                            if (!whatIf && !quiet)
                            {
                                ShellOps.WritePrompt(
                                    interactiveHost, String.Format(
                                    _Constants.Prompt.RuntimeOption,
                                    arg1));
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }
                        else
                        {
                            //
                            // BUGFIX: We may have evaluated some code and
                            //         the host may have been changed; grab
                            //         it again.
                            //
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0,
                                "failed to change runtime option", whatIf,
                                ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <optionName>\"",
                            CommandLineOption.RuntimeOption), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Safe))
                {
                    if (whatIf)
                    {
                        code = ReturnCode.Ok;
                    }
                    else
                    {
                        create[2] = true;

                        if (!quiet)
                        {
                            ShellOps.WritePrompt(
                                interactiveHost, String.Format(
                                _Constants.Prompt.Safe,
                                _Constants.Prompt.ViaCommandLine));
                        }

                        if (create[0])
                        {
                            arg0 = Characters.MinusSign + CommandLineOption.Recreate;

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 1;

                            goto option;
                        }
                        else
                        {
                            code = activeInterpreter.InternalMakeSafe(
                                MakeFlags.SafeShell, true, ref result);
                        }
                    }

                    if (code == ReturnCode.Ok)
                    {
                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 1;

                        goto retryArgv;
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, code, result,
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);
                    }

                    exitCode = ShellOps.ReturnCodeToExitCode(
                        activeInterpreter, code, true);
                }
#if TEST
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.ScriptTrace))
                {
                    if (arg1 != null)
                    {
                        if (whatIf)
                        {
                            code = ReturnCode.Ok;
                        }
                        else
                        {
                            code = DebugOps.AddScriptTraceListener(
                                activeInterpreter, arg1, activeInterpreter.Debug,
                                false, ref result);
                        }

                        if (code == ReturnCode.Ok)
                        {
                            if (!whatIf && !quiet)
                            {
                                ShellOps.WritePrompt(
                                    interactiveHost, String.Format(
                                    _Constants.Prompt.ScriptTrace,
                                    _Constants.Prompt.ViaCommandLine));
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }

                        if (code != ReturnCode.Ok)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                whatIf, ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <value>\"",
                            CommandLineOption.ScriptTrace), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
#endif
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Security))
                {
                    if (arg1 != null)
                    {
                        bool enable = false;

                        code = Value.GetBoolean2(
                            arg1, ValueFlags.AnyBoolean,
                            ShellOps.GetCultureInfo(activeInterpreter),
                            ref enable, ref result);

                        if ((code == ReturnCode.Ok) && !whatIf)
                        {
                            code = ScriptOps.EnableOrDisableSecurity(
                                activeInterpreter, enable,
                                activeInterpreter.PrivateIsNoVariables(),
                                ref result);

                            if (code == ReturnCode.Ok)
                            {
                                //
                                // NOTE: The shell callbacks may have been
                                //       changed via the evaluated script;
                                //       therefore, refresh the ones which
                                //       were not directly supplied by the
                                //       caller.
                                //
                                /* NO RESULT */
                                activeInterpreter.RefreshShellCallbacks();
                            }
                        }

                        if (code == ReturnCode.Ok)
                        {
                            if (!whatIf && !quiet)
                            {
                                ShellOps.WritePrompt(
                                    interactiveHost, String.Format(
                                    _Constants.Prompt.Security, enable ?
                                        "enabled" : "disabled",
                                        _Constants.Prompt.ViaCommandLine));
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }

                        if (code != ReturnCode.Ok)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                GetShellErrorLine(activeInterpreter, errorLine),
                                true, true, whatIf, ref argv,
                                ref interactiveHost, ref quiet, ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <enable>\"",
                            CommandLineOption.Security), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.SetCreate))
                {
                    if (arg1 != null)
                    {
                        bool localCreate = create[0];

                        code = Value.GetBoolean2(
                            arg1, ValueFlags.AnyBoolean,
                            ShellOps.GetCultureInfo(activeInterpreter),
                            ref localCreate, ref result);

                        if (code == ReturnCode.Ok)
                        {
                            if (!whatIf)
                            {
                                create[0] = localCreate;

                                if (!quiet)
                                {
                                    if (localCreate)
                                    {
                                        ShellOps.WritePrompt(interactiveHost,
                                            _Constants.Prompt.Create);
                                    }
                                    else
                                    {
                                        ShellOps.WritePrompt(interactiveHost,
                                            _Constants.Prompt.NoCreate);
                                    }
                                }
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }

                        if (code != ReturnCode.Ok)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                whatIf, ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <enable>\"",
                            CommandLineOption.SetCreate), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.SetInitialize))
                {
                    if (arg1 != null)
                    {
                        code = Value.GetBoolean2(
                            arg1, ValueFlags.AnyBoolean,
                            ShellOps.GetCultureInfo(activeInterpreter),
                            ref initialize, ref result);

                        if (code == ReturnCode.Ok)
                        {
                            if (!whatIf && !quiet)
                            {
                                if (initialize)
                                {
                                    ShellOps.WritePrompt(interactiveHost,
                                        _Constants.Prompt.Initialize);
                                }
                                else
                                {
                                    ShellOps.WritePrompt(
                                        interactiveHost, String.Format(
                                        _Constants.Prompt.NoInitialize,
                                        _Constants.Prompt.ViaCommandLine));
                                }
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }

                        if (code != ReturnCode.Ok)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                whatIf, ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <enable>\"",
                            CommandLineOption.SetInitialize), whatIf,
                            ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.SetLoop))
                {
                    if (arg1 != null)
                    {
                        code = Value.GetBoolean2(
                            arg1, ValueFlags.AnyBoolean,
                            ShellOps.GetCultureInfo(activeInterpreter),
                            ref loop, ref result);

                        if (code == ReturnCode.Ok)
                        {
                            if (!whatIf && !quiet)
                            {
                                if (loop)
                                {
                                    ShellOps.WritePrompt(interactiveHost,
                                        _Constants.Prompt.Loop);
                                }
                                else
                                {
                                    ShellOps.WritePrompt(
                                        interactiveHost, String.Format(
                                        _Constants.Prompt.NoLoop,
                                        _Constants.Prompt.ViaCommandLine));
                                }
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }

                        if (code != ReturnCode.Ok)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                whatIf, ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <enable>\"",
                            CommandLineOption.SetLoop), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.SetupTrace))
                {
                    if (whatIf)
                    {
                        code = ReturnCode.Ok;
                    }
                    else
                    {
                        code = DebugOps.SetupTraceListeners(
                            DebugOps.GetTraceListenerType(true),
                            clientData, true, activeInterpreter.Debug,
                            true, true, ref result);
                    }

                    if (code == ReturnCode.Ok)
                    {
                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 1;

                        goto retryArgv;
                    }

                    ShellOps.ShellMainCoreError(
                        activeInterpreter, savedArg0, arg0, code, result,
                        whatIf, ref argv, ref interactiveHost, ref quiet,
                        ref result);

                    exitCode = ShellOps.ReturnCodeToExitCode(
                        activeInterpreter, code, true);
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Standard))
                {
                    if (whatIf)
                    {
                        code = ReturnCode.Ok;
                    }
                    else
                    {
                        create[3] = true;

                        if (!quiet)
                        {
                            ShellOps.WritePrompt(
                                interactiveHost, String.Format(
                                _Constants.Prompt.Standard,
                                _Constants.Prompt.ViaCommandLine));
                        }

                        if (create[0])
                        {
                            arg0 = Characters.MinusSign + CommandLineOption.Recreate;

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 1;

                            goto option;
                        }
                        else
                        {
                            code = activeInterpreter.MakeStandard(
                                MakeFlags.StandardShell, true, ref result);
                        }
                    }

                    if (code == ReturnCode.Ok)
                    {
                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 1;

                        goto retryArgv;
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, code, result,
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);
                    }

                    exitCode = ShellOps.ReturnCodeToExitCode(
                        activeInterpreter, code, true);
                }
#if TEST
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.StartupLogFile))
                {
                    //
                    // NOTE: Actually, this argument should have already been
                    //       processed by the GetStartupLogFileName() method;
                    //       therefore, just skip over it.  However, first
                    //       issue a warning to make sure that the user knows
                    //       about this.
                    //
                    if (!whatIf && !quiet)
                    {
                        ShellOps.WritePrompt(interactiveHost,
                            _Constants.Prompt.LogFile);
                    }

                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 2;

                    goto retryArgv;
                }
#endif
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.StartupLibrary))
                {
                    //
                    // NOTE: Actually, this argument should have already been
                    //       processed by the GetStartupLibraryPath() method;
                    //       therefore, just skip over it.  However, first
                    //       issue a warning to make sure that the user knows
                    //       about this.
                    //
                    if (!whatIf && !quiet)
                    {
                        ShellOps.WritePrompt(interactiveHost,
                            _Constants.Prompt.LibraryPath);
                    }

                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 2;

                    goto retryArgv;
                }
#if !ENTERPRISE_LOCKDOWN
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.StartupPreInitialize))
                {
#if MAYBE_ENTERPRISE_LOCKDOWN
                    if (IsEnterpriseLockdownEnabled())
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "cannot use command line option {0}: lockdown",
                            FormatOps.WrapOrNull(CommandLineOption.StartupPreInitialize)),
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                    else
#endif
                    {
                        //
                        // NOTE: Actually, this argument should have already been
                        //       processed by the GetStartupPreInitializeText()
                        //       method; therefore, just skip over it.  However,
                        //       first issue a warning to make sure that the user
                        //       knows about this.
                        //
                        if (!whatIf && !quiet)
                        {
                            ShellOps.WritePrompt(interactiveHost,
                                _Constants.Prompt.PreInitializeText);
                        }

                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 2;

                        goto retryArgv;
                    }
                }
#endif
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Step))
                {
#if DEBUGGER
                    if (!whatIf)
                    {
                        activeInterpreter.SingleStep = true;

                        if (!quiet)
                        {
                            ShellOps.WritePrompt(
                                interactiveHost, String.Format(
                                _Constants.Prompt.SingleStep,
                                _Constants.Prompt.ViaCommandLine));
                        }
                    }
#else
                    if (!whatIf && !quiet)
                    {
                        ShellOps.WritePrompt(
                            interactiveHost, String.Format(
                            _Constants.Prompt.NoDebugger,
                            _Constants.Prompt.ViaCommandLine));
                    }
#endif

                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 1;

                    goto retryArgv;
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.StopOnUnknown))
                {
                    if (arg1 != null)
                    {
                        code = Value.GetBoolean2(
                            arg1, ValueFlags.AnyBoolean,
                            ShellOps.GetCultureInfo(activeInterpreter),
                            ref stopOnUnknown, ref result);

                        if (code == ReturnCode.Ok)
                        {
                            if (!whatIf && !quiet)
                            {
                                if (stopOnUnknown)
                                {
                                    ShellOps.WritePrompt(interactiveHost,
                                        _Constants.Prompt.StopOnUnknown);
                                }
                                else
                                {
                                    ShellOps.WritePrompt(
                                        interactiveHost, String.Format(
                                        _Constants.Prompt.NoStopOnUnknown,
                                        _Constants.Prompt.ViaCommandLine));
                                }
                            }

                            if (popArgv)
                            {
                                GenericOps<string>.PopFirstArgument(ref argv);
                                GenericOps<string>.PopFirstArgument(ref argv);
                                popArgv = false;
                            }

                            removeArgv += 2;

                            goto retryArgv;
                        }

                        if (code != ReturnCode.Ok)
                        {
                            ShellOps.ShellMainCoreError(
                                activeInterpreter, savedArg0, arg0, code, result,
                                whatIf, ref argv, ref interactiveHost, ref quiet,
                                ref result);
                        }

                        exitCode = ShellOps.ReturnCodeToExitCode(
                            activeInterpreter, code, true);
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <enable>\"",
                            CommandLineOption.StopOnUnknown), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    (StringOps.MatchSwitch(arg0, CommandLineOption.Test) ||
                    StringOps.MatchSwitch(arg0, CommandLineOption.PluginTest)))
                {
                    if (gotArg0)
                        removeArgv += 1;

                    if (gotArg1)
                        removeArgv += 1;

                    if (gotArg2)
                        removeArgv += 1;

                    code = activeInterpreter.MaybeRemoveArguments(
                        whatIf, ref removeArgv, ref result);

                    if ((code == ReturnCode.Ok) && !whatIf && initialize)
                    {
                        code = activeInterpreter.PrivateInitialize(
                            forceInitialize, false, ref result);

                        activeInterpreter.MaybeIgnoreInitializeError(
                            ref code, ref result);

                        if (code == ReturnCode.Ok)
                        {
                            //
                            // NOTE: The shell callbacks may have been
                            //       changed via the evaluated script;
                            //       therefore, refresh the ones which
                            //       were not directly supplied by the
                            //       caller.
                            //
                            /* NO RESULT */
                            activeInterpreter.RefreshShellCallbacks();
                        }
                    }

                    bool all = false;

                    if ((code == ReturnCode.Ok) && (arg2 != null))
                    {
                        code = Value.GetBoolean2(
                            arg2, ValueFlags.AnyBoolean,
                            ShellOps.GetCultureInfo(activeInterpreter),
                            ref all, ref result);
                    }

                    if ((code == ReturnCode.Ok) && !whatIf)
                    {
                        errorLine = 0;

                        code = TestOps.ShellMain(
                            activeInterpreter, arg1, null,
                            activeInterpreter.EngineFlags,
                            activeInterpreter.SubstitutionFlags,
                            activeInterpreter.EngineEventFlags,
                            activeInterpreter.ExpressionFlags,
                            StringOps.MatchSwitch(arg0,
                                CommandLineOption.PluginTest) ?
                                TestPathType.Plugins :
                            TestPathType.Default, all,
                            ref result, ref errorLine);
                    }

                    if (code != ReturnCode.Ok)
                    {
                        //
                        // BUGFIX: We may have evaluated some code and
                        //         the host may have been changed; grab
                        //         it again.
                        //
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, code, result,
                            GetShellErrorLine(activeInterpreter, errorLine),
                            true, true, whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);
                    }

                    //
                    // BUGFIX: All remaining command line arguments have (now)
                    //         been consumed, so clear them out.  Technically,
                    //         this is superflous for this particular command
                    //         line option because even if the -noExit option
                    //         is active, these arguments will be cleared out
                    //         first.
                    //
                    argv = null;

                    //
                    // NOTE: If the exit code for the interpreter is successful,
                    //       use the return code to figure out what this method
                    //       should return (i.e. just in case of a failure to
                    //       initialize, evaluate a script, etc).
                    //
                    ShellOps.GetExitCode(activeInterpreter, code, out exitCode);
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.TestDirectory))
                {
                    if (arg1 != null)
                    {
                        if (!whatIf)
                            activeInterpreter.TestPath = arg1;

                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 2;

                        goto retryArgv;
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <directory>\"",
                            CommandLineOption.TestDirectory), whatIf,
                            ref argv, ref interactiveHost, ref quiet,
                            ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.TraceToHost))
                {
                    if (!whatIf)
                    {
                        activeInterpreter.InterpreterFlags |= InterpreterFlags.TraceToHost;

                        if (!quiet)
                        {
                            ShellOps.WritePrompt(
                                interactiveHost, String.Format(
                                _Constants.Prompt.TraceToHost,
                                _Constants.Prompt.ViaCommandLine));
                        }
                    }

                    if (popArgv)
                    {
                        GenericOps<string>.PopFirstArgument(ref argv);
                        popArgv = false;
                    }

                    removeArgv += 1;

                    goto retryArgv;
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.VendorPath))
                {
                    if (arg1 != null)
                    {
                        if (!whatIf)
                            PathOps.SetVendorPath(arg1);

                        if (popArgv)
                        {
                            GenericOps<string>.PopFirstArgument(ref argv);
                            GenericOps<string>.PopFirstArgument(ref argv);
                            popArgv = false;
                        }

                        removeArgv += 2;

                        goto retryArgv;
                    }
                    else
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, String.Format(
                            "wrong # args: should be \"-{0} <directory>\"",
                            CommandLineOption.VendorPath), whatIf, ref argv,
                            ref interactiveHost, ref quiet, ref result);

                        exitCode = ShellOps.FailureExitCode(activeInterpreter);
                    }
                }
                else if ((switchCount > 0) &&
                    StringOps.MatchSwitch(arg0, CommandLineOption.Version))
                {
                    if (whatIf)
                    {
                        code = ReturnCode.Ok;
                    }
                    else
                    {
                        code = HelpOps.WriteVersion(
                            activeInterpreter, true, true, true,
                            true, true, true, true, true,
                            false, ref result);
                    }

                    if (code != ReturnCode.Ok)
                    {
                        ShellOps.ShellMainCoreError(
                            activeInterpreter, savedArg0, arg0, code, result,
                            whatIf, ref argv, ref interactiveHost, ref quiet,
                            ref result);
                    }

                    exitCode = ShellOps.ReturnCodeToExitCode(
                        activeInterpreter, code, true);
                }
                else
                {
                    //
                    // HACK: If the stop-on-unknown flag is set, just stop
                    //       further processing when any unknown argument
                    //       is found.  This is primarily important due to
                    //       skipping of the unknown argument handler, as
                    //       that could have arbitrary side-effects.
                    //
                    if (!stopOnUnknown)
                    {
                        //
                        // NOTE: This callback is (a bit) special as it is
                        //       optional -AND- it can impact the control
                        //       flow within this method (when specified).
                        //       Therefore, the helper method used to query
                        //       it is a bit different and requires an
                        //       output parameter.
                        //
                        bool wasHandled = false;

                        code = ShellOps.UnknownArgument(
                            activeInterpreter, interactiveHost, clientData,
                            localCallbackData, switchCount, arg0, whatIf,
                            ref wasHandled, ref argv, ref result);

                        if (wasHandled)
                        {
                            if (code == ReturnCode.Ok)
                            {
                                goto retryArgv;
                            }
                            else
                            {
                                //
                                // BUGFIX: We may have evaluated some code and
                                //         the host may have been changed; grab
                                //         it again.
                                //
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0, code, result,
                                    whatIf, ref argv, ref interactiveHost, ref quiet,
                                    ref result);

                                exitCode = ShellOps.FailureExitCode(activeInterpreter);
                            }
                        }
                        else
                        {
                            if (whatIf)
                            {
                                code = ReturnCode.Ok;
                            }
                            else
                            {
                                code = HelpOps.WriteUsage(
                                    activeInterpreter, String.Format(
                                    "invalid argument {0}, use \"-{1}\" for help",
                                    FormatOps.WrapOrNull(savedArg0),
                                    CommandLineOption.Help), false, false, false,
                                    false, true, ref result);
                            }

                            if (code != ReturnCode.Ok)
                            {
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, savedArg0, arg0, code, result,
                                    whatIf, ref argv, ref interactiveHost, ref quiet,
                                    ref result);
                            }

                            exitCode = ShellOps.FailureExitCode(activeInterpreter);
                        }
                    }
                }

            doneArgs:

                //
                // NOTE: If requested, force entry into interactive loop,
                //       unless there is no interpreter available.
                //
                if (noExit && (activeInterpreter != null))
                {
                    //
                    // NOTE: It is necessary to invalidate the command line
                    //       arguments here; otherwise, the interactive loop
                    //       will not be entered.
                    //
                    argv = null;
                    goto retryArgv;
                }
            }
            else if (loop)
            {
                code = activeInterpreter.MaybeRemoveArguments(
                    whatIf, ref removeArgv, ref result);

                if ((code == ReturnCode.Ok) && !whatIf && initialize)
                {
                    code = activeInterpreter.PrivateInitialize(
                        forceInitialize, false, ref result);

                    activeInterpreter.MaybeIgnoreInitializeError(
                        ref code, ref result);

                    if (code == ReturnCode.Ok)
                    {
                        //
                        // NOTE: The shell callbacks may have been
                        //       changed via the evaluated script;
                        //       therefore, refresh the ones which
                        //       were not directly supplied by the
                        //       caller.
                        //
                        /* NO RESULT */
                        activeInterpreter.RefreshShellCallbacks();
                    }
                }

                if (code == ReturnCode.Ok)
                {
                    //
                    // HACK: Next, disable any flags that may be unsuitable
                    //       (for use in the interactive loop) -AND- enable
                    //       any flags that might be useful.
                    //
                    int flagCount = whatIf ? 0 :
                        activeInterpreter.MaybeChangeFlagsForInteractiveUse();

                    TraceOps.DebugTrace(String.Format(
                        "PrivateShellMainCore: interactive use detected, " +
                        "changed {0} flag {1}", flagCount, (flagCount != 1) ?
                        "sets" : "set"), typeof(Interpreter).Name,
                        TracePriority.StartupDebug3);

                    //
                    // HACK: Since populating the list of installed updates
                    //       is fairly expensive, only do it automatically
                    //       for an interpreter that is actually going to
                    //       enter the interactive loop.  For this, it does
                    //       not matter if the interactive loop callback is
                    //       being used (i.e. it has been customized).  Do
                    //       not do this for "safe" interpreters (e.g. via
                    //       the -safe command line option, etc).  Also, do
                    //       do not this for non-default AppDomains.  Note
                    //       that we cannot actually check the Interactive
                    //       property of the interpreter at this point, due
                    //       to it (generally) being initialized only from
                    //       within the interactive loop itself.
                    //
#if !NET_STANDARD_20
                    if (!whatIf &&
                        PlatformOps.ShouldPopulateOperatingSystemExtra(
                            activeInterpreter, false, true, false, false,
                            true))
                    {
                        /* ASYNCHRONOUS */
                        PlatformOps.PopulateOperatingSystemExtra(
                            activeInterpreter, false, true, true);
                    }
#endif

                kiosk:

                    //
                    // NOTE: At this point, if we are not in "what-if" mode,
                    //       we will entered the interactive loop below.
                    //
                    interactive = true;

                    if (!whatIf)
                    {
                        //
                        // NOTE: Always use the original command line arguments
                        //       (as passed by the caller) here; otherwise, we
                        //       should always end up with a null argument list
                        //       because we cannot get to this block of code
                        //       unless there are no arguments left to process
                        //       (or there never were any to begin with).
                        //
                        InteractiveLoopData interactiveLoopData =
                            new InteractiveLoopData(args);

#if DEBUGGER
                        //
                        // NOTE: This callback is (a bit) special as it is
                        //       optional -AND- it can impact the control
                        //       flow within this method (when specified).
                        //       Therefore, the helper method used to query
                        //       it is a bit different and requires an
                        //       output parameter.
                        //
                        InteractiveLoopCallback interactiveLoopCallback;

                        if (_ShellCallbackData.GetInteractiveLoopCallback(
                                localCallbackData, out interactiveLoopCallback))
                        {
                            //
                            // NOTE: Use the specified interactive loop callback
                            //       instead of the default interactive loop
                            //       implementation.  All the defaulted parameter
                            //       values here should match those used by the
                            //       InteractiveLoop method overload that accepts
                            //       three parameters (i.e. the one used by this
                            //       method).
                            //
                            try
                            {
                                code = interactiveLoopCallback( /* throw */
                                    activeInterpreter, interactiveLoopData,
                                    ref result);
                            }
                            catch (Exception e)
                            {
                                result = e;
                                code = ReturnCode.Error;

                                //
                                // NOTE: *SPECIAL* The custom interactive loop
                                //       threw an exception and may not have set
                                //       the exit code; therefore, use the error
                                //       return code instead.
                                //
                                exitCode = ShellOps.ReturnCodeToExitCode(
                                    activeInterpreter, code, true);
                            }
                        }
                        else
#endif
                        {
                            //
                            // NOTE: Use the built-in interactive loop.  This
                            //       is the default behavior when there are no
                            //       arguments -OR- the arguments do not specify
                            //       a script or file to evaluate.  Even if/when
                            //       the built-in interactive loop is used, there
                            //       are a variety of mechanisms (e.g. the IHost)
                            //       that can be used to customize its behavior.
                            //
                            code = InteractiveLoop(
                                activeInterpreter, interactiveLoopData,
                                ref result);
                        }

                        //
                        // NOTE: At this point, if the interpreter is still valid
                        //       and kiosk mode is enabled for the interpreter,
                        //       do the following things:
                        //
                        //       1. Emit the current result IF there was an error
                        //          in the interactive loop.  It should be noted
                        //          here that an error condition will NOT prevent
                        //          the interactive loop from being reentered.
                        //
                        //       2. Reset exit flag for the interpreter in use.
                        //
                        //       3. Jump back to the top of the interactive loop
                        //          and run it again.
                        //
                        //       None of the above actions will be performed when
                        //       operating in "what-if" mode.  The net effect of
                        //       these actions is that "typical" ways of exiting
                        //       the interactive loop, e.g. [exit], et al, will
                        //       not work.
                        //
                        if (!whatIf && !activeInterpreter.PrivateDisposed &&
                            activeInterpreter.GetAndCheckInteractiveHost(
                                ref interactiveHost) &&
                            (kiosk || activeInterpreter.IsKioskLock()))
                        {
                            if (code != ReturnCode.Ok)
                            {
                                ShellOps.ShellMainCoreError(
                                    activeInterpreter, null, null, code, result,
                                    whatIf, ref argv, ref interactiveHost, ref quiet,
                                    ref result);
                            }

                            bool exit = activeInterpreter.PrivateExit;

                            if (exit) /* PERF */
                                activeInterpreter.PrivateExit = false;

                            if (!quiet)
                            {
                                ShellOps.WritePrompt(
                                    interactiveHost, String.Format(
                                    _Constants.Prompt.DeniedExit, exit ?
                                        " and reset interpreter flag" :
                                        String.Empty));
                            }

                            kioskLoops++;

                            if (activeInterpreter.IsKioskArgv())
                            {
                                IList<string> arguments = null;

                                if (activeInterpreter.PrivateGetArguments(
                                        ref arguments, whatIf, true,
                                        ref result) == ReturnCode.Ok)
                                {
                                    argv = arguments;
                                    goto retryArgv;
                                }
                            }

                            goto kiosk;
                        }
                    }
                }
                else
                {
                    //
                    // BUGFIX: We may have evaluated some code and
                    //         the host may have been changed; grab
                    //         it again.
                    //
                    ShellOps.ShellMainCoreError(
                        activeInterpreter, null, null, code, result,
                        Interpreter.GetErrorLine(activeInterpreter), true,
                        true, whatIf, ref argv, ref interactiveHost,
                        ref quiet, ref result);
                }

                //
                // NOTE: The return code is not used here to determine
                //       the exit code.  Instead, the exit code for the
                //       interpreter is used directly.
                //
                ShellOps.GetExitCode(activeInterpreter, out exitCode);
            }
            else
            {
                TraceOps.DebugTrace(
                    "PrivateShellMainCore: interactive loop skipped",
                    typeof(Interpreter).Name, TracePriority.StartupDebug);

                //
                // NOTE: The return code is not used here to determine
                //       the exit code.  Instead, the exit code for the
                //       interpreter is used directly.
                //
                ShellOps.GetExitCode(activeInterpreter, out exitCode);
            }

        done:

            //
            // NOTE: Do we need to dispose of an interpreter now?  This only
            //       occurs when the -reconfigure / -recreate command line
            //       options caused an interpreter to be (re-)created locally
            //       within this method; the "disposeInterpreter" variable
            //       tracks that exact instance.  Any interpreter NOT created
            //       here (e.g. the caller-owned parent) is left alone -- the
            //       using statement in use by the caller, if any, takes care
            //       of disposing it.
            //
            if (!whatIf && dispose &&
                !invalidInterpreter && (disposeInterpreter != null))
            {
                ReturnCode disposeCode;
                Result disposeError = null;
                bool localDispose;

                if (disposeChild &&
                    (parentInterpreter != null) && (childName != null))
                {
                    //
                    // NOTE: The interpreter we created is a child; remove it
                    //       THROUGH its parent so the parent's child registry
                    //       stays consistent (this also disposes it).  Do NOT
                    //       dispose the parent, which the caller still owns.
                    //       Any failure is reported by the "OrComplain" helper.
                    //
                    parentInterpreter.RemoveChildInterpreterOrComplain(
                        childName, null, true);

                    disposeCode = ReturnCode.Ok;
                    localDispose = true;
                }
                else
                {
                    //
                    // NOTE: The interpreter we created is a top-level (parent)
                    //       interpreter that we own; dispose it directly.
                    //
                    Interpreter localInterpreter = disposeInterpreter;

                    localDispose = dispose;

                    disposeCode = ObjectOps.TryDispose<Interpreter>(
                        ref localInterpreter, ref localDispose, ref disposeError);
                }

                if (!quiet)
                {
                    if (disposeCode == ReturnCode.Ok)
                    {
                        ShellOps.WritePrompt((Interpreter)null,
                            String.Format(_Constants.Prompt.Disposed,
                            disposeChild ? "Child" : "Parent",
                            FormatOps.InterpreterNoThrow(disposeInterpreter),
                            localDispose ? String.Empty : "not "));
                    }
                    else
                    {
                        ShellOps.WritePrompt((Interpreter)null,
                            String.Format(_Constants.Prompt.DisposedError,
                            disposeChild ? "Child" : "Parent",
                            FormatOps.InterpreterNoThrow(disposeInterpreter),
                            disposeError));
                    }
                }

                TraceOps.DebugTrace(String.Format(
                    "PrivateShellMainCore: dispose, disposeInterpreter = {0}, " +
                    "disposeChild = {1}, disposeCode = {2}, localDispose = " +
                    "{3}, disposeError = {4}",
                    FormatOps.InterpreterNoThrow(disposeInterpreter),
                    disposeChild, FormatOps.WrapOrNull(disposeCode),
                    FormatOps.WrapOrNull(localDispose), FormatOps.WrapOrNull(
                    true, false, disposeError)), typeof(Interpreter).Name,
                    (disposeCode == ReturnCode.Ok) ?
                        TracePriority.ShellDebug3 : TracePriority.ShellError);
            }

            TraceOps.DebugTrace(String.Format(
                "PrivateShellMainCore: exited, interpreter = {0}, " +
                "callbackData = {1}, clientData = {2}, savedArgv = {3}, " +
                "argv = {4}, whatIf = {5}, initialize = {6}, loop = {7}, " +
                "interactive = {8}, dispose = {9}, result = {10}, " +
                "exitCode = {11}",
                FormatOps.InterpreterNoThrow(interpreter),
                FormatOps.ShellCallbackData(callbackData),
                FormatOps.WrapOrNull(clientData),
                FormatOps.WrapOrNull(true, true, savedArgv),
                FormatOps.WrapOrNull(true, true, argv), whatIf,
                initialize, loop, interactive, dispose,
                FormatOps.WrapOrNull(true, true, result), exitCode),
                typeof(Interpreter).Name, TracePriority.StartupDebug);

            return exitCode;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if TEST
        /// <summary>
        /// This method determines whether the interactive loop may be entered,
        /// based on the specified interpreter and arguments.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter for which the interactive loop is being
        /// considered.
        /// </param>
        /// <param name="args">
        /// The shell (command-line style) arguments to consider, or null for
        /// none.
        /// </param>
        /// <param name="result">
        /// Upon success, this is set to non-zero if the interactive loop may
        /// be entered; otherwise, it is set to zero.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal static ReturnCode MayEnterInteractiveLoop(
            Interpreter interpreter,  /* in */
            IEnumerable<string> args, /* in: OPTIONAL */
            ref bool result,          /* out */
            ref Result error          /* out */
            ) /* THREAD-SAFE, RE-ENTRANT */
        {
            Interlocked.Increment(ref globalShellMainCoreCount);

            try
            {
                bool initialize = false;
                bool loop = true;
                bool interactive = false;
                Result localResult = null;

                if (PrivateShellMainCore(interpreter,
                        null, null, args, true /* what-if */,
                        ref initialize, ref loop, ref interactive,
                        ref localResult) == ExitCode.Success)
                {
                    result = interactive;
                    return ReturnCode.Ok;
                }
                else
                {
                    error = localResult;
                    return ReturnCode.Error;
                }
            }
            finally
            {
                Interlocked.Decrement(ref globalShellMainCoreCount);
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method is an entry point that runs the shell within the
        /// specified interpreter, optionally initializing it and entering the
        /// interactive loop.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to run the shell.
        /// </param>
        /// <param name="args">
        /// The shell (command-line style) arguments to process, or null for
        /// none.
        /// </param>
        /// <param name="initialize">
        /// Non-zero to initialize the interpreter before running the shell.
        /// </param>
        /// <param name="loop">
        /// Non-zero to enter the interactive loop.
        /// </param>
        /// <param name="result">
        /// The result associated with shell processing.  Upon return, this
        /// contains the final result or an error message describing any
        /// problem.
        /// </param>
        /// <returns>
        /// The exit code produced by the shell.
        /// </returns>
        public static ExitCode ShellMainCore(
            Interpreter interpreter,  /* in */
            IEnumerable<string> args, /* in: OPTIONAL */
            bool initialize,          /* in */
            bool loop,                /* in */
            ref Result result         /* in, out */
            ) /* ENTRY-POINT, THREAD-SAFE, RE-ENTRANT */
        {
            return ShellMainCore(
                interpreter, null, null, args,
                initialize, loop, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method is [also] specifically for use by alternative shells
        //       (i.e. ones that have no console, etc).  This method assumes that
        //       the interpreter has already been created with the desired options
        //       and that the interpreter host has been set to something with
        //       suitable functionality (i.e. minimally, something that fully
        //       implements the IInteractiveHost interface).
        //
        /// <summary>
        /// This method is an entry point that runs the shell within the
        /// specified interpreter using the supplied callback and client data,
        /// optionally initializing it and entering the interactive loop.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which to run the shell.
        /// </param>
        /// <param name="callbackData">
        /// The shell callback data controlling how scripts and files are
        /// evaluated, or null for none.
        /// </param>
        /// <param name="clientData">
        /// The client data to make available during shell processing, or
        /// null for none.
        /// </param>
        /// <param name="args">
        /// The shell (command-line style) arguments to process, or null for
        /// none.
        /// </param>
        /// <param name="initialize">
        /// Non-zero to initialize the interpreter before running the shell.
        /// </param>
        /// <param name="loop">
        /// Non-zero to enter the interactive loop.
        /// </param>
        /// <param name="result">
        /// The result associated with shell processing.  Upon return, this
        /// contains the final result or an error message describing any
        /// problem.
        /// </param>
        /// <returns>
        /// The exit code produced by the shell.
        /// </returns>
        public static ExitCode ShellMainCore(
            Interpreter interpreter,         /* in */
            IShellCallbackData callbackData, /* in: OPTIONAL */
            IClientData clientData,          /* in: OPTIONAL */
            IEnumerable<string> args,        /* in: OPTIONAL */
            bool initialize,                 /* in */
            bool loop,                       /* in */
            ref Result result                /* in, out */
            ) /* ENTRY-POINT, THREAD-SAFE, RE-ENTRANT */
        {
            Interlocked.Increment(ref globalShellMainCoreCount);

            try
            {
                bool interactive = false;

                return PrivateShellMainCore(
                    interpreter, callbackData, clientData,
                    args, false, ref initialize, ref loop,
                    ref interactive, ref result);
            }
            finally
            {
                Interlocked.Decrement(ref globalShellMainCoreCount);
            }
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Standard Shell Entry Point
#if SHELL
        /// <summary>
        /// This method determines whether the shell is currently running from
        /// within the main assembly entry point.
        /// </summary>
        /// <returns>
        /// True if the shell assembly entry point is active; otherwise,
        /// false.
        /// </returns>
        private static bool IsShellAssemblyActive()
        {
            AssemblyName assemblyName = GlobalState.GetEntryAssemblyName();

            if (assemblyName != null)
            {
                string simpleName = assemblyName.Name;

                if (SharedStringOps.SystemEquals(simpleName, _Assembly.Shell))
                    return true;

                if (SharedStringOps.SystemEquals(simpleName, _Assembly.Kit))
                    return true;
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the shell main entry point is
        /// currently active on any thread.
        /// </summary>
        /// <returns>
        /// True if the shell main entry point is active; otherwise, false.
        /// </returns>
        private static bool IsShellMainActive()
        {
            return Interlocked.CompareExchange(ref globalShellMainCount, 0, 0) > 0;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if TEST
        /// <summary>
        /// This method optionally sets up the trace log file for the shell,
        /// based on the supplied arguments.
        /// </summary>
        /// <param name="args">
        /// The shell (command-line style) arguments to examine, or null for
        /// none.
        /// </param>
        /// <param name="originFlags">
        /// The flags identifying the origin of the options being processed.
        /// </param>
        /// <param name="console">
        /// Non-zero if the shell is attached to a console.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to emit verbose diagnostics while setting up the log
        /// file.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        private static ReturnCode MaybeSetupTraceLogFile(
            IEnumerable<string> args,
            OptionOriginFlags originFlags,
            bool console,
            bool verbose,
            ref Result error
            )
        {
            ReturnCode code;
            string fileName = null;

            code = GetStartupLogFileName(
                args, originFlags, console, verbose, ref fileName,
                ref error);

            if ((code == ReturnCode.Ok) && (fileName != null))
            {
                TraceListener listener = null; /* NOT USED */

                code = DebugOps.SetupTraceLogFile(
                    ShellOps.GetTraceListenerName(null,
                        GlobalState.GetCurrentSystemThreadId()),
                    fileName, null, null, true, false, false,
                    false, false, ref listener, ref error);
            }

            return code;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method implements the standard shell main entry point, creating
        /// an interpreter from the supplied settings and running the shell.
        /// </summary>
        /// <param name="interpreterSettings">
        /// The interpreter settings used to create the interpreter, or null
        /// to use the defaults.
        /// </param>
        /// <param name="args">
        /// The shell (command-line style) arguments to process, or null for
        /// none.
        /// </param>
        /// <param name="originFlags">
        /// The flags identifying the origin of the options being processed.
        /// </param>
        /// <returns>
        /// The exit code produced by the shell.
        /// </returns>
        private static ExitCode PrivateShellMain(
            IInterpreterSettings interpreterSettings,
            IEnumerable<string> args,
            OptionOriginFlags originFlags
            )
        {
            MaybeStaticInitialize();

            ExitCode exitCode;

            try
            {
                //
                // NOTE: Grab the effective console and verbose settings now, as
                //       they are used to determine if any subsequent diagnostic
                //       messages should be emitted.
                //
                bool console;
                bool verbose;

                RefreshConsoleAndVerbose(out console, out verbose);

                //
                // NOTE: We need return code and a result variable very early on
                //       now for startup log file name, pre-initialize text, and
                //       library path processing.  Later, it is used to capture
                //       the result (or error message) of the shell interpreter
                //       creation operation.
                //
                ReturnCode code = ReturnCode.Ok;
                Result result = null;

#if TEST
                if (code == ReturnCode.Ok) /* REDUNDANT */
                {
                    code = MaybeSetupTraceLogFile(
                        args, originFlags, console, verbose, ref result);
                }
#endif

                //
                // NOTE: Create an interpreter settings object based on the
                //       context we already have; then, check for a settings
                //       file and allow the settings to be overridden from
                //       it.
                //
                IInterpreterSettings localInterpreterSettings;
                CreateFlags createFlags = CreateFlags.None;

                if (interpreterSettings != null)
                {
                    createFlags = interpreterSettings.CreateFlags;
                    localInterpreterSettings = interpreterSettings;
                }
                else
                {
                    localInterpreterSettings = InterpreterSettings.CreateShell(
                        null, args, originFlags, console, verbose, ref result);

                    if (localInterpreterSettings != null)
                        createFlags = localInterpreterSettings.CreateFlags;
                    else
                        code = ReturnCode.Error;
                }

                if (code == ReturnCode.Ok)
                {
                    code = InterpreterSettings.UseShellDefaults(
                        localInterpreterSettings, createFlags, ref result);
                }

#if XML && SERIALIZATION
                if (code == ReturnCode.Ok)
                {
                    code = InterpreterSettings.LoadFrom(
                        (CultureInfo)null, FlagOps.HasFlags(
                            originFlags, OptionOriginFlags.Optional, true),
                        FlagOps.HasFlags(
                            originFlags, OptionOriginFlags.Merge, true),
                        FlagOps.HasFlags(
                            originFlags, OptionOriginFlags.Expand, true),
                        ref localInterpreterSettings, ref result);
                }
#endif

                if (code == ReturnCode.Ok)
                {
                    //
                    // NOTE: Create an interpreter now inside of a using block
                    //       so that we can be relatively sure it will be
                    //       finalized on this thread.
                    //
                    using (Interpreter interpreter = Create(
                            localInterpreterSettings, true, ref result))
                    {
                        //
                        // NOTE: Make sure the interpreter was created.  This
                        //       can (in theory) be a problem if/when the
                        //       ThrowOnError flag ends up getting removed
                        //       somehow prior to the call to actually create
                        //       the interpreter.
                        //
                        if (interpreter != null)
                        {
                            //
                            // NOTE: By default, enable locking prompts for
                            //       the shell when used interactively.
                            //
                            interpreter.LockCallback = new LockCallback(
                                interpreter.ShellLockCallback);

                            //
                            // NOTE: By default, set a more aggressive locking
                            //       retry limit for the shell.
                            //
                            interpreter.LockRetries = MaximumLockRetries;

                            //
                            // NOTE: By default, initialize the script library
                            //       and enter the interactive loop.
                            //
                            bool initialize = true;
                            bool loop = true;

                            //
                            // NOTE: Process all the remaining startup options
                            //       (i.e. the ones that do not modify the
                            //       interpreter creation flags or library path)
                            //       now.
                            //
                            code = ProcessStartupOptions(
                                interpreter, args, createFlags, originFlags,
                                console, verbose, ref initialize, ref loop,
                                ref result);

                            if (code == ReturnCode.Ok)
                            {
                                exitCode = ShellMainCore(
                                    interpreter, null, null, args,
                                    initialize, loop, ref result);
                            }
                            else
                            {
                                ShellOps.ShellMainCoreError(
                                    interpreter, null, null, code, result);

                                exitCode = ShellOps.ReturnCodeToExitCode(
                                    interpreter, code, true);
                            }
                        }
                        else
                        {
                            //
                            // NOTE: Creation of the interpreter failed.
                            //
                            HostOps.WriteConsoleOrComplain(
                                ReturnCode.Error, result);

                            exitCode = ShellOps.FailureExitCode(interpreter);
                        }
                    }
                }
                else
                {
                    //
                    // NOTE: Library path processing failed.
                    //
                    HostOps.WriteConsoleOrComplain(ReturnCode.Error, result);

                    exitCode = ShellOps.ReturnCodeToExitCode(null, code, true);
                }
            }
            catch (Exception e)
            {
                //
                // WARNING: Top-level unhandled exception handler.
                //          We should never get here.  If we do then
                //          something has gone really wrong and should
                //          be complained about loudly.
                //
                string message = String.Format("UNHANDLED EXCEPTION: {0}", e);

                //
                // NOTE: We cannot rely on the Interpreter now (nor the
                //       IHost contained within it); therefore, output
                //       directly to the console.
                //
                HostOps.WriteConsoleOrComplain(ReturnCode.Error, message);

                //
                // NOTE: Output to trace listeners.
                //
                try
                {
                    DebugOps.TraceWriteLine(message,
                        typeof(Exception).Name); /* EXEMPT */ /* throw */
                }
                catch
                {
                    // do nothing.
                }

                //
                // NOTE: Break into the debugger, if one is attached.
                //
                DebugOps.MaybeBreak(message);

                //
                // NOTE: Re-throw the exception if we have been requested
                //       to do so.
                //
                if (GlobalConfiguration.DoesValueExist(
                        EnvVars.Throw, ConfigurationFlags.Interpreter))
                {
                    throw;
                }

                //
                // TODO: The ability to diagnostic send memory dumps here.
                //
                exitCode = ResultOps.ExceptionExitCode();
            }

            ///////////////////////////////////////////////////////////////////////////////////////////

#if WINFORMS
            if (GlobalState.IsPrimaryThread())
                StatusFormOps.Exit();
#endif

            ///////////////////////////////////////////////////////////////////////////////////////////

            try
            {
                long[] totalMemory = { 0, 0 };

                ObjectOps.GetTotalMemory(true,
                    ref totalMemory[0], ref totalMemory[1]);

                TraceOps.DebugTrace(String.Format(
                    "PrivateShellMain: exited, exitCode = {0}, " +
                    "totalMemory[0] = {1}, totalMemory[1] = {2}",
                    exitCode, totalMemory[0], totalMemory[1]),
                    typeof(Interpreter).Name, TracePriority.StartupDebug);
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.StartupError);
            }

            return exitCode;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method is the standard shell main entry point, creating a default
        /// interpreter and running the shell with the supplied arguments.
        /// </summary>
        /// <param name="args">
        /// The shell (command-line style) arguments to process, or null for
        /// none.
        /// </param>
        /// <returns>
        /// The exit code produced by the shell.
        /// </returns>
        public static ExitCode ShellMain(
            IEnumerable<string> args
            ) /* ENTRY-POINT, THREAD-SAFE, RE-ENTRANT */
        {
            return ShellMain(null, args);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method is the standard shell main entry point, creating an
        /// interpreter from the supplied settings and running the shell with the
        /// supplied arguments.
        /// </summary>
        /// <param name="interpreterSettings">
        /// The interpreter settings used to create the interpreter, or null
        /// to use the defaults.
        /// </param>
        /// <param name="args">
        /// The shell (command-line style) arguments to process, or null for
        /// none.
        /// </param>
        /// <returns>
        /// The exit code produced by the shell.
        /// </returns>
        public static ExitCode ShellMain(
            IInterpreterSettings interpreterSettings,
            IEnumerable<string> args
            ) /* ENTRY-POINT, THREAD-SAFE, RE-ENTRANT */
        {
            Interlocked.Increment(ref globalShellMainCount);

            try
            {
                return PrivateShellMain(
                    interpreterSettings, args, OptionOriginFlags.Shell);
            }
            finally
            {
                Interlocked.Decrement(ref globalShellMainCount);
            }
        }
#endif
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interactive Loop Support
        #region Interactive Check-For-Update Support
        /// <summary>
        /// This method queries the engine, substitution, event, and expression
        /// flags associated with the specified interpreter, without throwing on
        /// failure.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose flags are being queried, or null for none.
        /// </param>
        /// <param name="debug">
        /// Non-zero to query the flags appropriate for debugging.
        /// </param>
        /// <param name="engineFlags">
        /// Upon return, this is set to the queried engine flags.
        /// </param>
        /// <param name="substitutionFlags">
        /// Upon return, this is set to the queried substitution flags.
        /// </param>
        /// <param name="eventFlags">
        /// Upon return, this is set to the queried event flags.
        /// </param>
        /// <param name="expressionFlags">
        /// Upon return, this is set to the queried expression flags.
        /// </param>
        internal static void QueryFlagsNoThrow(
            Interpreter interpreter,
            bool debug,
            out EngineFlags engineFlags,
            out SubstitutionFlags substitutionFlags,
            out EventFlags eventFlags,
            out ExpressionFlags expressionFlags
            )
        {
            engineFlags = EngineFlags.None;
            substitutionFlags = SubstitutionFlags.Default;
            eventFlags = EventFlags.Default;
            expressionFlags = ExpressionFlags.Default;

            if (interpreter != null)
            {
                try
                {
                    engineFlags = interpreter.EngineFlags |
                        DebuggerOps.GetEngineFlags(debug);

                    substitutionFlags = interpreter.SubstitutionFlags;
                    eventFlags = interpreter.EngineEventFlags;
                    expressionFlags = interpreter.ExpressionFlags;
                }
                catch (Exception e)
                {
                    TraceOps.DebugTrace(
                        e, typeof(Interpreter).Name,
                        TracePriority.ShellError);
                }
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interactive Debugger Support
#if DEBUGGER
        /// <summary>
        /// This method temporarily disables the script debugger, saving the
        /// current engine flags so they can later be restored.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// Upon return, this is set to the engine flags that were in effect
        /// before debugging was disabled.
        /// </param>
        private void BeginNoDebugger(
            out EngineFlags savedEngineFlags
            )
        {
            savedEngineFlags = ContextEngineFlags;
            ContextEngineFlags |= EngineFlags.NoDebuggerMask;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method re-enables the script debugger, restoring the engine
        /// flags previously saved by a matching call.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// The engine flags to restore, as previously saved.
        /// </param>
        private void EndNoDebugger(
            ref EngineFlags savedEngineFlags
            )
        {
            EngineFlags disableEngineFlags = EngineFlags.None;

            if (!EngineFlagOps.HasNoBreakpoint(savedEngineFlags))
                disableEngineFlags |= EngineFlags.NoBreakpoint;

            if (!EngineFlagOps.HasNoWatchpoint(savedEngineFlags))
                disableEngineFlags |= EngineFlags.NoWatchpoint;

            ContextEngineFlags &= ~disableEngineFlags;
            savedEngineFlags = EngineFlags.None;
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interactive Exit Support
#if SHELL
        /// <summary>
        /// This method updates the supplied exit flag based on whether the
        /// specified interpreter has been asked to exit.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose exit state is being checked, or null for
        /// none.
        /// </param>
        /// <param name="exit">
        /// The exit flag to update.  Upon return, this is non-zero if the
        /// interpreter has been asked to exit.
        /// </param>
        private static void CheckExit(
            Interpreter interpreter, /* in */
            ref bool exit            /* in, out */
            )
        {
            if (interpreter != null)
            {
                lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
                {
                    if (!interpreter.PrivateDisposed)
                    {
                        bool newExit = interpreter.PrivateExit;

                        if (newExit && !exit)
                            exit = newExit;
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks whether the specified interpreter has been asked to
        /// exit and, if so, records that within the supplied interactive loop
        /// data.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose exit state is being checked, or null for
        /// none.
        /// </param>
        /// <param name="loopData">
        /// The interactive loop data to update with the exit state.
        /// </param>
        internal static void CheckExit(
            Interpreter interpreter,      /* in */
            IInteractiveLoopData loopData /* in */
            )
        {
            if ((interpreter != null) && (loopData != null))
            {
                lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
                {
                    if (!interpreter.PrivateDisposed)
                    {
                        bool oldExit = loopData.Exit;
                        bool newExit = interpreter.PrivateExit;

                        if (newExit && !oldExit)
                            loopData.SetExit();
                    }
                }
            }
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interactive Prompt Support
#if SHELL
        /// <summary>
        /// This method displays an interactive prompt using the specified host.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter associated with the prompt, or null for none.
        /// </param>
        /// <param name="interactiveHost">
        /// The interactive host used to display the prompt.
        /// </param>
        /// <param name="hostFlags">
        /// The flags describing the capabilities of the host.
        /// </param>
        /// <param name="type">
        /// The type of prompt to display.
        /// </param>
        /// <param name="promptFlags">
        /// The flags controlling how the prompt is displayed.
        /// </param>
        /// <param name="count">
        /// The interactive input count associated with the prompt.
        /// </param>
        /// <param name="trace">
        /// Non-zero to emit trace diagnostics while displaying the prompt.
        /// </param>
        /// <param name="done">
        /// Upon return, this is non-zero if no further prompting is
        /// required.
        /// </param>
        private static void Prompt(
            Interpreter interpreter,
            IInteractiveHost interactiveHost,
            HostFlags hostFlags,
            PromptType type,
            PromptFlags promptFlags,
            int count,
            bool trace,
            ref bool done
            )
        {
            //
            // NOTE: We require an interactive host to display a custom prompt
            //       (or even to display a default prompt).
            //
            if (interactiveHost != null)
            {
                ReturnCode code; /* IGNORED (?) */
                Result error = null;

                //
                // NOTE: Request the host to display some a prompt appropriate
                //       for the specified prompt type and flags.
                //
                try
                {
                    if (FlagOps.HasFlags(hostFlags, HostFlags.Prompt, true))
                    {
                        code = interactiveHost.Prompt(
                            type, ref promptFlags, ref error); /* throw */
                    }
                    else
                    {
                        error = String.Format(
                            HostOps.NoFeatureError, HostFlags.Prompt);

                        code = ReturnCode.Error;
                    }
                }
                catch (Exception e)
                {
                    error = e;
                    code = ReturnCode.Error;
                }

                //
                // NOTE: If tracing is enabled, emit key information about the
                //       success -OR- failure to display the prompt.
                //
                if (trace)
                {
                    TraceOps.DebugTrace(String.Format(
                        "Prompt: code = {0}, flags = {1}, error = {2}",
                        code, FormatOps.WrapOrNull(promptFlags),
                        FormatOps.WrapOrNull(true, true, error)),
                        typeof(Interpreter).Name,
                        TracePriority.HostDebug);
                }

                //
                // NOTE: If the host failed to display some type of prompt,
                //       fallback to an appropriate default prompt now.
                //
                if (!FlagOps.HasFlags(promptFlags, PromptFlags.Done, true))
                {
                    //
                    // NOTE: If available, grab the integer identifier for
                    //       the interpreter as this will help the end users
                    //       to identity which interpreter is emitting the
                    //       prompt.
                    //
                    long id = 0;

                    HostOps.MaybeAdjustPromptFlags(
                        interpreter, ref promptFlags, ref id);

                    //
                    // NOTE: Get the appropriate default prompt for this
                    //       situation.
                    //
                    string prompt = HostOps.GetDefaultPrompt(
                        interpreter, type, promptFlags, id, count);

                    //
                    // NOTE: If there is a prompt configured and we cannot
                    //       write it, this is considered to be an error
                    //       fatal to the interactive loop.
                    //
                    if ((prompt != null) && !interactiveHost.Write(prompt))
                    {
                        //
                        // NOTE: If we cannot display prompts, there is not
                        //       much point in the interactive loop.
                        //
                        done = true;
                    }
                }
            }
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interactive Input Support
#if SHELL
        /// <summary>
        /// This method reads a line of interactive input from the specified
        /// host.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter associated with the input, or null for none.
        /// </param>
        /// <param name="interactiveHost">
        /// The interactive host from which to read the input.
        /// </param>
        /// <param name="trace">
        /// Non-zero to emit trace diagnostics while reading the input.
        /// </param>
        /// <param name="value">
        /// Upon success, this is set to the line of input that was read.
        /// </param>
        /// <param name="done">
        /// Upon return, this is non-zero if no further input is available.
        /// </param>
        /// <returns>
        /// True if a line of input was read; otherwise, false.
        /// </returns>
        private static bool ReadInteractiveInput(
            Interpreter interpreter,
            IInteractiveHost interactiveHost,
            bool trace,
            ref string value,
            ref bool done
            )
        {
            bool result = false;

            if (interactiveHost != null)
            {
                try
                {
                    if (IsReadLineDisabled(interpreter, true))
                    {
                        done = true; /* NOTE: Disabled, we are done. */

                        if (trace)
                        {
                            TraceOps.DebugTrace(
                                "ReadInteractiveInput: disabled",
                                typeof(Interpreter).Name,
                                TracePriority.ThreadError);
                        }
                    }
                    else
                    {
                        lock (staticSyncRoot) /* TRANSACTIONAL */
                        {
                            if ((readValue != null) &&
                                (readValue.Length >= 1))
                            {
                                value = readValue[0]; /* HOOK BEFORE */
                            }
                        }

                        result = interactiveHost.ReadLine(
                            ref value); /* throw */

                        Interlocked.Increment(ref readCount);

                        lock (staticSyncRoot) /* TRANSACTIONAL */
                        {
                            if ((readValue != null) &&
                                (readValue.Length >= 2))
                            {
                                readValue[1] = value; /* SAVE AFTER */
                            }
                        }
                    }
                }
                catch (ThreadAbortException)
                {
                    Thread.ResetAbort();

                    done = true; /* NOTE: Aborted, we are done. */

                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "ReadInteractiveInput: caught thread abort",
                            typeof(Interpreter).Name,
                            TracePriority.ThreadError2);
                    }
                }
                catch (ThreadInterruptedException)
                {
                    done = true; /* NOTE: Interrupted, we are done. */

                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "ReadInteractiveInput: caught thread interrupt",
                            typeof(Interpreter).Name,
                            TracePriority.ThreadError2);
                    }
                }
                catch (ObjectDisposedException)
                {
                    done = true; /* NOTE: Host disposed, we are done. */

                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "ReadInteractiveInput: caught host disposed",
                            typeof(Interpreter).Name,
                            TracePriority.HostError);
                    }
                }
                catch (Exception e)
                {
                    TraceOps.DebugTrace(
                        e, typeof(Interpreter).Name,
                        TracePriority.HostError);
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method is private, very specialized, subject to change
        //          at any time, and is really only designed to be called from
        //          within the InteractiveLoop method.  Therefore, use this
        //          method at your own risk.
        //
        /// <summary>
        /// This method determines whether the specified interactive input
        /// represents a complete command ready to be evaluated.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter in which the input would be evaluated, or null for
        /// none.
        /// </param>
        /// <param name="text">
        /// The interactive input text to examine.
        /// </param>
        /// <param name="startIndex">
        /// The index at which to begin examining the input.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags in effect while examining the input.
        /// </param>
        /// <param name="substitutionFlags">
        /// The substitution flags in effect while examining the input.
        /// </param>
        /// <param name="notReady">
        /// Upon return, this is non-zero if the input is not yet ready to be
        /// evaluated.
        /// </param>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// True if the input represents a complete command; otherwise, false.
        /// </returns>
        private static bool InteractiveIsComplete(
            Interpreter interpreter,             /* in */
            string text,                         /* in */
            int startIndex,                      /* in */
            EngineFlags engineFlags,             /* in */
            SubstitutionFlags substitutionFlags, /* in */
            ref bool notReady,                   /* in, out */
            ref Result error                     /* out */
            )
        {
            //
            // BUGFIX: To avoid recursively entering the interactive loop due
            //         to an active script cancellation flag, make sure that
            //         breakpoints are disabled while the parser is checking
            //         the interactive text.
            //
            EngineFlags localEngineFlags = engineFlags;

#if DEBUGGER
            localEngineFlags |= EngineFlags.NoDebuggerMask;
#endif

            return Parser.IsComplete(
                interpreter, null, Parser.StartLine, text, startIndex,
                Length.Invalid, localEngineFlags, substitutionFlags,
                ref notReady, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records that another line of interactive input has been
        /// received for the specified interpreter and returns the updated total.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose interactive input total is being updated, or
        /// null for none.
        /// </param>
        /// <returns>
        /// The updated total number of interactive inputs, or an invalid count
        /// if the interpreter is null.
        /// </returns>
        internal static int AnotherInteractiveInput(
            Interpreter interpreter
            )
        {
            if (interpreter == null)
                return Count.Invalid;

            return ++interpreter.TotalInteractiveInputs; /* THREAD-SAFE */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method appends the specified text to the interactive input buffer
        /// for the current context, optionally adding a line terminator.
        /// </summary>
        /// <param name="text">
        /// The text to append to the interactive input buffer, or null to
        /// append nothing.
        /// </param>
        /// <param name="newLine">
        /// Non-zero to append a line terminator after the text.
        /// </param>
        internal void BufferInteractiveInput(
            string text, /* in */
            bool newLine /* in */
            ) /* THREAD-SAFE */
        {
            StringBuilder builder = InteractiveInputBuffer; /* NOTE: Context only. */

            if (builder == null)
            {
                builder = SBF.CreateNoCache(); /* EXEMPT */
                InteractiveInputBuffer = builder;
            }

            if (text != null)
            {
                if (newLine)
                    builder.AppendLine(text);
                else
                    builder.Append(text);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if DEBUGGER
        /// <summary>
        /// This method flushes the buffered interactive input to the script
        /// debugger and clears the buffer.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this is set to an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode EnqueueInteractiveInput(
            ref Result error /* out */
            ) /* THREAD-SAFE */
        {
            IDebugger debugger = Debugger; /* NOTE: Context only. */

            if (debugger == null)
            {
                error = "debugger not available";
                return ReturnCode.Error;
            }

            StringBuilder builder = InteractiveInputBuffer; /* NOTE: Context only. */

            if (builder == null)
            {
                error = "interactive input buffer not available";
                return ReturnCode.Error;
            }

            if (debugger.EnqueueBuffer(
                    builder.ToString(), ref error) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            builder.Length = 0;
            return ReturnCode.Ok;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method is private, very specialized, subject to change
        //          at any time, and is really only designed to be called from
        //          within the InteractiveLoop method.  Therefore, use this
        //          method at your own risk.
        //
        /// <summary>
        /// This method reads and processes a unit of interactive input for the
        /// specified interpreter, handling prompting, cancellation, and command
        /// detection as needed.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter for which interactive input is being read.
        /// </param>
        /// <param name="refresh">
        /// Non-zero to refresh the interactive host before reading, zero to
        /// skip refreshing, or null to use the default behavior.
        /// </param>
        /// <param name="noCommand">
        /// Non-zero to skip treating the input as an interactive command.
        /// </param>
        /// <param name="trace">
        /// Non-zero to emit trace diagnostics while reading the input.
        /// </param>
        /// <param name="debug">
        /// Non-zero if the interactive input is being read for debugging.
        /// </param>
        /// <param name="queue">
        /// Non-zero to queue the input rather than evaluate it immediately.
        /// </param>
        /// <param name="engineFlags">
        /// The engine flags in effect while reading the input.
        /// </param>
        /// <param name="substitutionFlags">
        /// The substitution flags in effect while reading the input.
        /// </param>
        /// <param name="clientData">
        /// The client data to make available while reading the input, or null
        /// for none.
        /// </param>
        /// <param name="forceCancel">
        /// Non-zero to force any pending script cancellation to be honored.
        /// </param>
        /// <param name="forceHalt">
        /// Non-zero to force any pending halt to be honored.
        /// </param>
        /// <param name="interactiveHost">
        /// The interactive host used to read the input.  Upon return, this
        /// reflects the host that was actually used.
        /// </param>
        /// <param name="savedText">
        /// The previously saved partial input, if any.  Upon return, this
        /// reflects the updated saved input.
        /// </param>
        /// <param name="exit">
        /// Non-zero if the interpreter has been asked to exit.  Upon return,
        /// this reflects the updated exit state.
        /// </param>
        /// <param name="done">
        /// Non-zero if no further input is required.  Upon return, this
        /// reflects the updated done state.
        /// </param>
        /// <param name="previous">
        /// Upon return, this is non-zero if the previous input was reused.
        /// </param>
        /// <param name="canceled">
        /// Upon return, this is non-zero if reading the input was canceled.
        /// </param>
        /// <param name="text">
        /// Upon return, this is set to the interactive input text that was
        /// read.
        /// </param>
        /// <param name="notReady">
        /// Upon return, this is non-zero if the input is not yet ready to be
        /// evaluated.
        /// </param>
        /// <param name="parseError">
        /// Upon return, this is set to any error encountered while parsing the
        /// input, or null if there was none.
        /// </param>
        internal static void GetInteractiveInput(
            Interpreter interpreter,              /* in */
            bool? refresh,                        /* in */
#if INTERACTIVE_COMMANDS
            bool noCommand,                       /* in */
#endif
            bool trace,                           /* in */
            bool debug,                           /* in */
            bool queue,                           /* in */
            EngineFlags engineFlags,              /* in */
            SubstitutionFlags substitutionFlags,  /* in */
            IClientData clientData,               /* in */
            bool forceCancel,                     /* in */
            bool forceHalt,                       /* in */
            ref IInteractiveHost interactiveHost, /* in, out */
            ref string savedText,                 /* in, out */
            ref bool exit,                        /* in, out */
            ref bool done,                        /* in, out */
            ref bool previous,                    /* out */
            out bool canceled,                    /* out */
            out string text,                      /* out */
            out bool notReady,                    /* out */
            out Result parseError                 /* out */
            )
        {
            //
            // NOTE: Keep track of the number of times, per thread, that an
            //       attempt was made to get some interactive input.
            //
            int count = AnotherInteractiveInput(interpreter);

            //
            // NOTE: Grab the host flags now as we need them to determine if
            //       the prompt can and should [always] be displayed.
            //
            HostFlags hostFlags = HostOps.GetHostFlags(interactiveHost);

            //
            // NOTE: Re-fetch the interpreter host in case it has been
            //       externally modified or closed.  Also, make sure it is
            //       still open.  If either of these checks fail or return
            //       false, bail out now.
            //
            PromptFlags promptFlags = PromptFlags.None;

            bool isOpen = HostOps.IsOpen(
                interpreter, refresh, ref hostFlags, ref promptFlags,
                ref interactiveHost);

            HostOps.MaybeAdjustPromptFlags(debug, queue, ref promptFlags);

            //
            // BUGFIX: Verify that the interactive host is still valid and
            //         open.  If not, the rest of this method is basically
            //         useless and we are done.
            //
            if (!isOpen)
            {
                done = true; /* NOTE: Invalid or closed host, we are done. */

                if (trace)
                {
                    TraceOps.DebugTrace(String.Format(
                        "GetInteractiveInput: leaving, host " +
                        "is already invalid or closed, exit = {0}, " +
                        "interactiveHost = {1}, isOpen = {2}",
                        exit, (interactiveHost != null), isOpen),
                        typeof(Interpreter).Name,
                        TracePriority.HostDebug);
                }

                //
                // NOTE: Reset the variables used by our caller (the main
                //       interactive loop).
                //
                canceled = false;
                text = null;
                notReady = false;
                parseError = null;

                return;
            }

            ReturnCode resetCode;
            Result resetError = null;

            //
            // NOTE: We must reset the script cancellation flags if we can
            //       (i.e. if no evals are pending), because the IsComplete
            //       method now relies upon the Ready method prior to the
            //       Engine.Evaluate* method having been called (which would
            //       normally cooperatively reset the script cancellation
            //       flags prior to checking them), which checks the script
            //       cancellation flags.
            //
            bool resetCancel = false;

            resetCode = Engine.ResetCancel(
                interpreter, ShellOps.GetResetCancelFlags(forceCancel),
                ref resetCancel, ref resetError);

            if (resetCode == ReturnCode.Ok)
            {
                if (trace)
                {
                    TraceOps.DebugTrace(String.Format(
                        "GetInteractiveInput: cancel flags {0}",
                        resetCancel ? "reset" : "not reset"),
                        typeof(Interpreter).Name,
                        TracePriority.HostDebug);
                }
            }
            else
            {
                if (trace)
                {
                    TraceOps.DebugTrace(String.Format(
                        "GetInteractiveInput: failed to {0} cancel flags",
                        resetCancel ? "reset" : "not reset"),
                        typeof(Interpreter).Name,
                        TracePriority.EngineError);
                }
            }

            //
            // NOTE: We must reset the debugger halt flags if we can (i.e.
            //       if no evals are pending and no other interactive loops
            //       are active), because Parser.IsComplete now relies upon
            //       Interpreter.Ready prior to Engine.Evaluate* having been
            //       called (which would normally cooperatively reset the
            //       debugger halt flags prior to checking them), which checks
            //       the debugger halt flags.
            //
            bool resetHalt = false;

            resetCode = Engine.ResetHalt(
                interpreter, ShellOps.GetResetCancelFlags(forceHalt),
                ref resetHalt, ref resetError);

            if (resetCode == ReturnCode.Ok)
            {
                if (trace)
                {
                    TraceOps.DebugTrace(String.Format(
                        "GetInteractiveInput: halt flags {0}.",
                        resetHalt ? "reset" : "not reset"),
                        typeof(Interpreter).Name,
                        TracePriority.HostDebug);
                }
            }
            else
            {
                if (trace)
                {
                    TraceOps.DebugTrace(String.Format(
                        "GetInteractiveInput: failed to {0} halt flags",
                        resetHalt ? "reset" : "not reset"),
                        typeof(Interpreter).Name,
                        TracePriority.EngineError);
                }
            }

            //
            // NOTE: Does the host want to force the prompt to be displayed
            //       even if input has been redirected?  If so, just do it.
            //       Otherwise, check if the host input is NOT currently being
            //       redirected (i.e. we currently have an interactive user)
            //       and then display the prompt prior to requesting any input
            //       from the host.
            //
            if (FlagOps.HasFlags(hostFlags, HostFlags.ForcePrompt, true) ||
                !HostOps.IsInputRedirected(interactiveHost))
            {
                //
                // WARNING: This may end up evaluating a script, if one or
                //          more of the "prompt script" variables are set.
                //          For the duration of the evaluated script, the
                //          script cancellation flags will be ignored.
                //
                Prompt(
                    interpreter, interactiveHost, hostFlags,
                    PromptType.Start, promptFlags, count, trace,
                    ref done);

                if (done)
                {
                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "GetInteractiveInput: leaving, done flag was " +
                            "set by start prompt",
                            typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }

                    //
                    // NOTE: Reset the variables used by our caller (the main
                    //       interactive loop).
                    //
                    canceled = false;
                    text = null;
                    notReady = false;
                    parseError = null;

                    return;
                }
            }

            //
            // NOTE: Check if the debugger is set to enter the interactive loop
            //       upon script cancellation.
            //
            bool breakOnCancel =
                DebuggerOps.GetBreakOnCancel(interpreter, false);

            //
            // NOTE: Reset the variables used by our caller (the main
            //       interactive loop).
            //
            canceled = false;
            text = String.Empty; // NOTE: Cannot be null.
            notReady = breakOnCancel; // NOTE: Bypass readiness?
            parseError = null;

            //
            // NOTE: This is the starting index used for the call to the parser
            //       to check if the input is complete.  This value should be
            //       just past the interactive command indicator, if present;
            //       otherwise, it should be zero.
            //
            int startIndex;

            do
            {
                //
                // NOTE: Re-grab the host flags now as they may have changed
                //       (?) and we need them to determine if the prompt can
                //       and should [always] be displayed.
                //
                hostFlags = HostOps.GetHostFlags(interactiveHost);

                //
                // NOTE: Was there a parser error just now when we checked if
                //       the input text was a complete command?
                //
                if (parseError != null)
                {
                    if (trace)
                    {
                        TraceOps.DebugTrace(String.Format(
                            "GetInteractiveInput: parse error: {0}",
                            FormatOps.WrapOrNull(parseError)),
                            typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }

                    //
                    // NOTE: Does this host support multiple-line input?
                    //
                    if (FlagOps.HasFlags(
                            hostFlags, HostFlags.MultipleLineInput, true))
                    {
                        if (trace)
                        {
                            TraceOps.DebugTrace(
                                "GetInteractiveInput: multiple-line " +
                                "input is supported, setting canceled " +
                                "flag...", typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }

                        //
                        // NOTE: For hosts that support multiple-line input,
                        //       we will not accept any incomplete input.
                        //       Therefore, bail out now with an "error" (i.e.
                        //       or at least our closest approximation of one).
                        //
                        canceled = true;

                        break;
                    }

                    //
                    // NOTE: In the event of a parser error (i.e. if the line
                    //       entered does not represent a complete command)
                    //       display the error in the host title.
                    //
                    /* IGNORED */
                    HostOps.SetTitle(interactiveHost, String.Format(
                        "incomplete: {0}", parseError));

                    /* IGNORED */
                    // HostOps.WriteLine(interactiveHost,
                    //     String.Format("incomplete: {0}", parseError));

                    parseError = null;
                }

                //
                // NOTE: Re-check if the host input is being redirected (i.e.
                //       we do not have an interactive user) then display the
                //       input continuation prompt if necessary prior to
                //       requesting more input from the host.
                //
                bool redirected = HostOps.IsInputRedirected(interactiveHost);

                if (!String.IsNullOrEmpty(text) && (!redirected ||
                    FlagOps.HasFlags(hostFlags, HostFlags.ForcePrompt, true)))
                {
                    //
                    // WARNING: This may end up evaluating a script, if one or
                    //          more of the "prompt script" variables are set.
                    //          For the duration of the evaluated script, the
                    //          script cancellation flags will be ignored.
                    //
                    Prompt(
                        interpreter, interactiveHost, hostFlags,
                        PromptType.Continue, promptFlags, count,
                        trace, ref done);

                    if (done)
                    {
                        if (trace)
                        {
                            TraceOps.DebugTrace(
                                "GetInteractiveInput: leaving, done " +
                                "flag was set by continue prompt",
                                typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }

                        //
                        // NOTE: Reset the variables used by our caller (the
                        //       main interactive loop).
                        //
                        canceled = false;
                        text = null;
                        notReady = false;
                        parseError = null;

                        return;
                    }
                }

                string line = null; // NOTE: Current input line.
                int length; // NOTE: Length of the current input line.

                //
                // NOTE: Check and see if the previous iteration of the primary
                //       loop saved some input for us to use.  If so, use it
                //       and set the saved input to null.
                //
                if (!String.IsNullOrEmpty(savedText))
                {
                    line = savedText;
                    savedText = null;

                    length = line.Length;

                    if (trace)
                    {
                        TraceOps.DebugTrace(String.Format(
                            "GetInteractiveInput: using saved input " +
                            "containing {0} characters...",
                            length), typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }
                }

                //
                // NOTE: Is the current line of input still null (i.e. there
                //       was no saved input to use)?
                //
                if (line == null)
                {
                    //
                    // NOTE: Check and see if the debugger has command input
                    //       injected via the [debug icommand] sub-command for
                    //       us to use.
                    //
                    line = DebuggerOps.GetCommand(interpreter, false);

                    if (line != null)
                    {
                        length = line.Length;

                        if (trace)
                        {
                            TraceOps.DebugTrace(String.Format(
                                "GetInteractiveInput: injecting line " +
                                "of input from debugger containing {0} " +
                                "characters...",
                                length), typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }
                    }
                }

                //
                // NOTE: Are we processing input injected via saved input text
                //       -OR- the debugger?
                //
                if (!String.IsNullOrEmpty(line))
                {
                    //
                    // NOTE: Prevent this command from being used [again?] as
                    //       the previous interactive input and disable the
                    //       ability to use the "again" command.
                    //
                    previous = false;

                    //
                    // NOTE: Simulate the command having been entered via the
                    //       host.
                    //
                    /* IGNORED */
                    HostOps.WriteLine(interactiveHost, line);
                }

                //
                // NOTE: Has the request for input been canceled by the host
                //       (i.e. either a null line was returned and no input
                //       redirection is in use OR the ReadLine method returned
                //       false).
                //
                bool cancel = false;

                //
                // NOTE: Get a line of input from the host, if necessary (i.e.
                //       we do not already have a command injected via the
                //       debugger, etc).
                //
                if (!String.IsNullOrEmpty(line) || ReadInteractiveInput(
                        interpreter, interactiveHost, trace, ref line,
                        ref done))
                {
                    if (line != null) /* more input? */
                    {
                        length = line.Length;

                        if (trace)
                        {
                            TraceOps.DebugTrace(String.Format(
                                "GetInteractiveInput: read line of " +
                                "input containing {0} characters",
                                length), typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }

                        if (length > 0)
                            text += line + Characters.NewLine;
                        else
                            text += Characters.NewLine;

                        SetInteractiveInput(interpreter, text);
                    }
                    else if (redirected)
                    {
                        if (trace)
                        {
                            TraceOps.DebugTrace(
                                "GetInteractiveInput: read null line of " +
                                "redirected input, setting exit flag...",
                                typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }

                        //
                        // NOTE: It looks like console input is being
                        //       redirected and we have run out of it;
                        //       therefore, bail out of the interactive
                        //       loop now.
                        //
                        exit = true;
                    }
                    else
                    {
                        if (FlagOps.HasFlags(
                                hostFlags, HostFlags.TreatMissingLineAsEof, true))
                        {
                            if (trace)
                            {
                                TraceOps.DebugTrace(
                                    "GetInteractiveInput: read null " +
                                    "line of input, setting exit flag...",
                                    typeof(Interpreter).Name,
                                    TracePriority.HostDebug);
                            }

                            exit = true;
                        }
                        else
                        {
                            if (trace)
                            {
                                TraceOps.DebugTrace(
                                    "GetInteractiveInput: read null " +
                                    "line of input, setting cancel flag...",
                                    typeof(Interpreter).Name,
                                    TracePriority.HostDebug);
                            }

                            //
                            // NOTE: The ReadLine method returned true;
                            //       however, the actual input line is
                            //       null and input is (probably?) not
                            //       being redirected.  Therefore, just
                            //       assume the user has canceled the
                            //       input request.
                            //
                            cancel = true;
                        }
                    }
                }
                else if (done)
                {
                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "GetInteractiveInput: leaving, aborted " +
                            "while reading line of input...",
                            typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }

                    //
                    // NOTE: The ReadLine method has returned false
                    //       and the done flag is set; therefore, we
                    //       were aborted by another thread while
                    //       reading input.
                    //
                    break;
                }
                else if (redirected)
                {
                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "GetInteractiveInput: failed to read line " +
                            "of redirected input, setting exit flag...",
                            typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }

                    exit = true;
                }
                else
                {
                    if (FlagOps.HasFlags(
                            hostFlags, HostFlags.TreatMissingLineAsEof, true))
                    {
                        if (trace)
                        {
                            TraceOps.DebugTrace(
                                "GetInteractiveInput: failed to read line " +
                                "of input, setting exit flag...",
                                typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }

                        exit = true;
                    }
                    else
                    {
                        if (trace)
                        {
                            TraceOps.DebugTrace(
                                "GetInteractiveInput: failed to read line " +
                                "of input, setting cancel flag...",
                                typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }

                        //
                        // NOTE: The ReadLine method has returned false;
                        //       therefore, assume the input request was
                        //       canceled by the user.
                        //
                        cancel = true;
                    }
                }

                //
                // NOTE: Re-grab the host flags now as they may have changed
                //       during a host read (?) and we need them to determine
                //       if the host is still open.
                //
                hostFlags = HostOps.GetHostFlags(interactiveHost);

                //
                // NOTE: Re-fetch the interpreter host in case it has been
                //       externally modified or closed.  Also, make sure it is
                //       still open.  If either of these checks fail or return
                //       false, bail out now.
                //
                isOpen = HostOps.IsOpen(
                    interpreter, refresh, ref hostFlags, ref promptFlags,
                    ref interactiveHost);

                HostOps.MaybeAdjustPromptFlags(debug, queue, ref promptFlags);

                //
                // NOTE: Make sure that we exit if the [exit] command was used.
                //       This is needed because another thread may have set the
                //       exit flag for the interpreter while we were waiting
                //       for input.
                //
                CheckExit(interpreter, ref exit);

                //
                // NOTE: Did the interpreter exit while we were reading (or was
                //       the host invalidated, perhaps by Dispose)?
                //
                if (exit || !isOpen)
                {
                    done = true; /* NOTE: Async exit, we are done. */

                    if (trace)
                    {
                        TraceOps.DebugTrace(String.Format(
                            "GetInteractiveInput: leaving, exit = {0}, " +
                            "interactiveHost = {1}, isOpen = {2}",
                            exit, (interactiveHost != null), isOpen),
                            typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }

                    break;
                }
                //
                // NOTE: Was input canceled while we were reading?
                //
                else if (cancel)
                {
                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "GetInteractiveInput: leaving, input was " +
                            "canceled...", typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }

                    /* IGNORED */
                    HostOps.WriteLine(interactiveHost, null);
                    canceled = true; /* skip command processing */

                    break;
                }
                else if (StringOps.IsLogicallyEmpty(text))
                {
                    if (trace)
                    {
                        TraceOps.DebugTrace(
                            "GetInteractiveInput: leaving, null or " +
                            "empty input...", typeof(Interpreter).Name,
                            TracePriority.HostDebug);
                    }

                    break;
                }

                //
                // NOTE: Figure out if this looks like an interactive command;
                //       if so, start checking if the input is complete at the
                //       character just after the interactive command prefix;
                //       otherwise, start at index zero.
                //
                startIndex = 0;

                /* IGNORED */
                ShellOps.LooksLikeAnyInteractiveCommand(text, ref startIndex);

                //
                // NOTE: Finally, see if the input is complete enough to return
                //       to the caller -OR- if we are done processing for some
                //       other reason (i.e. user canceled).
                //
            } while ((StringOps.IsLogicallyEmpty(text) ||
                     !InteractiveIsComplete(interpreter, text, startIndex,
                            engineFlags, substitutionFlags, ref notReady,
                            ref parseError)) &&
                     !notReady);

            //
            // NOTE: Make sure that we have not exited and that the host is
            //       still valid and open.
            //
            if (!done)
            {
                /* IGNORED */
                HostOps.SetTitle(interactiveHost, null);

                if (notReady)
                {
#if INTERACTIVE_COMMANDS
                    //
                    // NOTE: If this is an interactive debugger command, fake
                    //       the interpreter being "ready" (at least as far as
                    //       input validation goes) because we need to give the
                    //       user the opportunity to reset the script
                    //       cancellation flag, etc.
                    //
                    if (!noCommand && InteractiveOps.CheckCommand(
                            interpreter, text, null, clientData, true, false))
                    {
                        if (trace)
                        {
                            TraceOps.DebugTrace(
                                "GetInteractiveInput: input looks like an " +
                                "interactive command, interpreter readiness " +
                                "faked", typeof(Interpreter).Name,
                                TracePriority.HostDebug);
                        }

                        notReady = false;
                    }
                    else // NOTE: Dangling else (see "if" statement below).
#endif
                    if (!breakOnCancel)
                    {
                        //
                        // NOTE: Show the user why the interpreter is not ready.
                        //
                        /* IGNORED */
                        HostOps.WriteResultLine(interactiveHost,
                            ReturnCode.Error, String.Format(
                                "interpreter not ready: {0}", parseError));
                    }
                }
            }
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interactive Command Support
#if SHELL
        /// <summary>
        /// This method queries the engine, substitution, event, and expression
        /// flags used by the interactive loop.
        /// </summary>
        /// <param name="localEngineFlags">
        /// Upon return, this is set to the engine flags used by the
        /// interactive loop.
        /// </param>
        /// <param name="localSubstitutionFlags">
        /// Upon return, this is set to the substitution flags used by the
        /// interactive loop.
        /// </param>
        /// <param name="localEventFlags">
        /// Upon return, this is set to the event flags used by the
        /// interactive loop.
        /// </param>
        /// <param name="localExpressionFlags">
        /// Upon return, this is set to the expression flags used by the
        /// interactive loop.
        /// </param>
        private void QueryInteractiveLoopFlags(
            out EngineFlags localEngineFlags,
            out SubstitutionFlags localSubstitutionFlags,
            out EventFlags localEventFlags,
            out ExpressionFlags localExpressionFlags
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    localEngineFlags = this.EngineFlagsNoLock; /* PROPERTY */

                    localSubstitutionFlags = this.substitutionFlags;
                    localEventFlags = this.engineEventFlags;
                    localExpressionFlags = this.expressionFlags;
                }
                else
                {
                    localEngineFlags = EngineFlags.None;
                    localSubstitutionFlags = SubstitutionFlags.Default;
                    localEventFlags = EventFlags.Default;
                    localExpressionFlags = ExpressionFlags.Default;

                    TraceOps.LockTrace(
                        "QueryInteractiveLoopFlags",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockWarning,
                        MaybeWhoHasLock());
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if SHELL && INTERACTIVE_COMMANDS
        #region GC Test Thread Support
        /// <summary>
        /// This method determines whether the test garbage-collection thread
        /// exists, optionally requiring it to be alive.
        /// </summary>
        /// <param name="mustBeAlive">
        /// Non-zero to require that the thread also be alive.
        /// </param>
        /// <returns>
        /// True if the test garbage-collection thread exists (and is alive when
        /// required); otherwise, false.
        /// </returns>
        private bool HasTestGcThread(
            bool mustBeAlive
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                return !mustBeAlive || ThreadOps.IsAlive(testGcThread);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method is the thread start routine for the test
        /// garbage-collection thread, which periodically forces garbage
        /// collection.
        /// </summary>
        /// <param name="obj">
        /// The state object passed to the thread start routine.
        /// </param>
        private static void TestGcThreadStart( /* THREAD-SAFE */
            object obj /* NOT USED */
            ) /* System.Threading.ParameterizedThreadStart */
        {
            bool verbose = false;

            try
            {
                IAnyPair<Interpreter, bool> anyPair =
                    obj as IAnyPair<Interpreter, bool>;

                if (anyPair != null)
                    verbose = anyPair.Y;

                while (true)
                {
                    //
                    // NOTE: Force a full garbage collection now.
                    //
                    ObjectOps.CollectGarbage(); /* throw */

                    //
                    // NOTE: Wait a while before trying again.
                    //
                    HostOps.ThreadSleep(testGcSleepTime); /* throw */
                }
            }
            catch (ThreadAbortException e)
            {
                Thread.ResetAbort();

                if (verbose)
                {
                    TraceOps.DebugTrace(
                        e, typeof(Interpreter).Name,
                        TracePriority.ThreadError2);
                }
            }
            catch (ThreadInterruptedException e)
            {
                if (verbose)
                {
                    TraceOps.DebugTrace(
                        e, typeof(Interpreter).Name,
                        TracePriority.ThreadError2);
                }
            }
            catch (Exception e)
            {
                if (verbose)
                {
                    TraceOps.DebugTrace(
                        e, typeof(Interpreter).Name,
                        TracePriority.CleanupError);
                }

                throw;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method starts the test garbage-collection thread for the
        /// interpreter.
        /// </summary>
        /// <param name="mustBeAlive">
        /// Non-zero to require that an existing thread be alive when
        /// determining whether one is already running.
        /// </param>
        /// <param name="verbose">
        /// Non-zero to emit verbose diagnostics while starting the thread.
        /// </param>
        /// <param name="strictStart">
        /// Non-zero to treat a failure to start the thread as an error.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode StartTestGcThread(
            bool mustBeAlive,
            bool verbose,
            bool strictStart,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                Thread localThread = testGcThread;

                if ((localThread == null) ||
                    (mustBeAlive && !ThreadOps.IsAlive(localThread)))
                {
                    bool success = false;

                    try
                    {
                        localThread = Engine.CreateThread(
                            this, TestGcThreadStart,
                            0, false, false, true);

                        if (localThread != null)
                        {
                            localThread.Name = String.Format(
                                "testGcThread: {0}",
                                FormatOps.InterpreterNoThrow(
                                    this)); /* throw */

                            localThread.Start(
                                new AnyPair<Interpreter, bool>(
                                    this, verbose)); /* throw */

                            testGcThread = localThread;
                            success = true;

                            result = "created and started garbage collection test thread";
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            result = "could not create garbage collection test thread";
                        }
                    }
                    catch (Exception e)
                    {
                        result = String.Format(
                            "failed to start garbage collection test thread, " +
                            "caught exception {0}", FormatOps.WrapOrNull(e));
                    }
                    finally
                    {
                        if (!success && (localThread != null))
                        {
                            try
                            {
                                localThread.Interrupt(); /* throw */
                                localThread = null;
                            }
                            catch (Exception e)
                            {
                                TraceOps.DebugTrace(
                                    e, typeof(Interpreter).Name,
                                    TracePriority.ThreadError);
                            }
                        }
                    }
                }
                else
                {
                    result = "garbage collection test thread already started";

                    //
                    // NOTE: This is not really always an error due to nested
                    //       interactive loops.
                    //
                    if (!strictStart)
                        return ReturnCode.Ok;
                }

                return ReturnCode.Error;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method interrupts and stops the test garbage-collection thread
        /// for the interpreter.
        /// </summary>
        /// <param name="timeout">
        /// The maximum time, in milliseconds, to wait for the thread to stop,
        /// or null to use the default.
        /// </param>
        /// <param name="noAbort">
        /// Non-zero to avoid aborting the thread if it does not stop in
        /// time.
        /// </param>
        /// <param name="strictStop">
        /// Non-zero to treat a failure to stop the thread as an error.
        /// </param>
        /// <param name="result">
        /// Upon failure, this contains an error message describing the
        /// problem.
        /// </param>
        /// <returns>
        /// Returns <see cref="ReturnCode.Ok" /> on success; otherwise,
        /// <see cref="ReturnCode.Error" />.
        /// </returns>
        internal ReturnCode InterruptTestGcThread(
            int? timeout,
            bool noAbort,
            bool strictStop,
            ref Result result
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                Thread localThread = testGcThread;

                if (localThread != null)
                {
                    try
                    {
                        if (ThreadOps.IsAlive(localThread))
                        {
                            localThread.Interrupt();

                            int localTimeout;

                            if (timeout != null)
                                localTimeout = (int)timeout;
                            else
                                localTimeout = ThreadOps.DefaultJoinTimeout;

                            if (!localThread.Join(localTimeout) &&
                                ThreadOps.IsAlive(localThread))
                            {
                                if (noAbort)
                                {
                                    result = String.Format(
                                        "failed to join garbage collection " +
                                        "test thread after {0} milliseconds",
                                        localTimeout);

                                    return ReturnCode.Error;
                                }
                                else
                                {
                                    /* BUGBUG: Leaks? */
                                    localThread.Abort(); /* throw */

                                    result = "aborted garbage collection test thread";
                                }
                            }
                            else
                            {
                                result = "interrupted garbage collection test thread";
                            }

                            testGcThread = null; /* NOTE: Joined (?) */
                            return ReturnCode.Ok;
                        }
                        else
                        {
                            testGcThread = null; /* NOTE: Dead. */
                            result = "garbage collection test thread is not alive";

                            //
                            // NOTE: This is not really always an error
                            //       due to subtle timing issues.
                            //
                            if (!strictStop)
                                return ReturnCode.Ok;
                        }
                    }
                    catch (Exception e)
                    {
                        result = String.Format(
                            "failed to interrupt garbage collection test thread, " +
                            "caught exception {0}", FormatOps.WrapOrNull(e));
                    }
                }
                else
                {
                    result = "garbage collection test thread already stopped";

                    //
                    // NOTE: This is not really always an error due to nested
                    //       interactive loops.
                    //
                    if (!strictStop)
                        return ReturnCode.Ok;
                }

                return ReturnCode.Error;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method queries the engine, substitution, event, and expression
        /// flags, along with the result limits, used while processing
        /// interactive commands.
        /// </summary>
        /// <param name="engineFlags">
        /// Upon return, this is set to the engine flags in effect.
        /// </param>
        /// <param name="interactiveCommandsEnabled">
        /// Upon return, this is non-zero if interactive commands are
        /// enabled.
        /// </param>
        /// <param name="interactiveEngineFlags">
        /// Upon return, this is set to the engine flags used for interactive
        /// commands.
        /// </param>
        /// <param name="interactiveSubstitutionFlags">
        /// Upon return, this is set to the substitution flags used for
        /// interactive commands.
        /// </param>
        /// <param name="interactiveEventFlags">
        /// Upon return, this is set to the event flags used for interactive
        /// commands.
        /// </param>
        /// <param name="interactiveExpressionFlags">
        /// Upon return, this is set to the expression flags used for
        /// interactive commands.
        /// </param>
        /// <param name="interactiveExecuteResultLimit">
        /// Upon return, this is set to the result length limit applied when
        /// executing interactive commands.
        /// </param>
        /// <param name="interactiveNestedResultLimit">
        /// Upon return, this is set to the result length limit applied to
        /// nested results of interactive commands.
        /// </param>
        internal void QueryInteractiveFlagsAndLimits(
            out EngineFlags engineFlags,
            out bool interactiveCommandsEnabled,
            out EngineFlags interactiveEngineFlags,
            out SubstitutionFlags interactiveSubstitutionFlags,
            out EventFlags interactiveEventFlags,
            out ExpressionFlags interactiveExpressionFlags
#if RESULT_LIMITS
            , out int interactiveExecuteResultLimit
            , out int interactiveNestedResultLimit
#endif
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    engineFlags = this.EngineFlagsNoLock; /* PROPERTY */

                    interactiveCommandsEnabled = this.interactiveCommandsEnabled;

                    interactiveEngineFlags = this.interactiveEngineFlags;
                    interactiveSubstitutionFlags = this.interactiveSubstitutionFlags;
                    interactiveEventFlags = this.interactiveEventFlags;
                    interactiveExpressionFlags = this.interactiveExpressionFlags;

#if RESULT_LIMITS
                    interactiveExecuteResultLimit = this.executeResultLimit;
                    interactiveNestedResultLimit = this.nestedResultLimit;
#endif
                }
                else
                {
                    InteractiveOps.ResetFlagsAndLimits(
                        this, out engineFlags, out interactiveCommandsEnabled,
                        out interactiveEngineFlags, out interactiveSubstitutionFlags,
                        out interactiveEventFlags, out interactiveExpressionFlags
#if RESULT_LIMITS
                        , out interactiveExecuteResultLimit
                        , out interactiveNestedResultLimit
#endif
                    );

                    TraceOps.LockTrace(
                        "QueryInteractiveFlags",
                        typeof(Interpreter).Name, false,
                        TracePriority.LockWarning,
                        MaybeWhoHasLock());
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interactive Script Cancellation Support
#if CONSOLE
        /// <summary>
        /// This method determines whether a console cancel event (e.g. a
        /// Ctrl-C or Ctrl-Break key press) should be handled by this class.
        /// </summary>
        /// <param name="sender">
        /// The object that raised the console cancel event.  This parameter
        /// is not used.
        /// </param>
        /// <param name="e">
        /// The data associated with the console cancel event, or null if it
        /// is not available.
        /// </param>
        /// <returns>
        /// True if the console cancel event should be handled; otherwise,
        /// false.
        /// </returns>
        private static bool ShouldHandleConsoleCancelEvent(
            object sender, /* NOT USED */
            ConsoleCancelEventArgs e
            )
        {
            return (e == null) || !e.Cancel;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the cancel flag on the console cancel event
        /// arguments, when appropriate, in order to prevent the default
        /// handling that would otherwise terminate the current process.
        /// </summary>
        /// <param name="sender">
        /// The object that raised the console cancel event.  This parameter
        /// is not used.
        /// </param>
        /// <param name="e">
        /// The data associated with the console cancel event, or null if it
        /// is not available.
        /// </param>
        private static void MaybeSetConsoleEventArgsCancelFlag(
            object sender, /* NOT USED */
            ConsoleCancelEventArgs e
            )
        {
            //
            // NOTE: Prevent default handling (which would then terminate
            //       the current process); however, we cannot prevent the
            //       key Ctrl-Break from terminating the current process
            //       (only Ctrl-C).
            //
            if ((e != null) && !e.Cancel &&
                (e.SpecialKey == ConsoleSpecialKey.ControlC))
            {
                e.Cancel = true;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method begins a block of code during which console cancel
        /// events are ignored, saving the previous console cancellation
        /// setting so that it can be restored later.
        /// </summary>
        /// <param name="savedCancelViaConsole">
        /// Upon return, this parameter receives the previous console
        /// cancellation setting so it can be passed to the matching
        /// <c>EndNoConsoleCancelEventHandler</c> call.
        /// </param>
        internal static void BeginNoConsoleCancelEventHandler(
            ref int savedCancelViaConsole
            )
        {
            savedCancelViaConsole = Interlocked.Exchange(
                ref cancelViaConsole[0], 1 /* IGNORE */);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method ends a block of code during which console cancel
        /// events were ignored, restoring the previously saved console
        /// cancellation setting.
        /// </summary>
        /// <param name="savedCancelViaConsole">
        /// The previously saved console cancellation setting, as returned by
        /// the matching <c>BeginNoConsoleCancelEventHandler</c> call.  This
        /// parameter is reset to zero before returning.
        /// </param>
        internal static void EndNoConsoleCancelEventHandler(
            ref int savedCancelViaConsole
            )
        {
            /* IGNORED */
            Interlocked.Exchange(
                ref cancelViaConsole[0], savedCancelViaConsole);

            savedCancelViaConsole = 0;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the InteractiveOps and StatusFormOps
        //          classes only.
        //
        /// <summary>
        /// This method optionally prompts the user and then cancels the
        /// scripts currently being evaluated by all known interpreters.  This
        /// overload discards the resulting interpreter count and canceled
        /// status.
        /// </summary>
        /// <param name="sender">
        /// The object that raised the console cancel event.
        /// </param>
        /// <param name="prompt">
        /// Non-zero to prompt the user before canceling any scripts.
        /// </param>
        internal static void MaybeShowPromptAndAllCancel(
            object sender,
            bool prompt
            ) /* THREAD-SAFE */
        {
            int interpreterCount;
            bool canceled;

            MaybeShowPromptAndAllCancel(
                sender, null, prompt, out interpreterCount,
                out canceled);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method optionally prompts the user and then cancels the
        /// scripts currently being evaluated by all known interpreters, or by
        /// all known interactive interpreters, based on the user's response.
        /// </summary>
        /// <param name="sender">
        /// The object that raised the console cancel event.
        /// </param>
        /// <param name="e">
        /// The data associated with the console cancel event, or null if it
        /// is not available.
        /// </param>
        /// <param name="prompt">
        /// Non-zero to prompt the user before canceling any scripts.
        /// </param>
        /// <param name="interpreterCount">
        /// Upon return, this parameter receives the number of interpreters
        /// that had their scripts canceled.
        /// </param>
        /// <param name="canceled">
        /// Upon return, this parameter is set to true if the user canceled
        /// the prompt without selecting a cancellation option; otherwise, it
        /// is set to false.
        /// </param>
        private static void MaybeShowPromptAndAllCancel(
            object sender,
            ConsoleCancelEventArgs e,
            bool prompt,
            out int interpreterCount,
            out bool canceled
            ) /* THREAD-SAFE */
        {
            //
            // NOTE: Set skipped flag to false and set count of canceled
            //       interpreters to something obviously invalid to make
            //       it clear in trace messages what actually happened.
            //
            interpreterCount = Count.Invalid - 1; /* -2 */
            canceled = false;

            //
            // NOTE: Cancel all currently running scripts in all threads.
            //       Only handle the first event generated by the Ctrl-C.
            //
            if (!ShouldHandleConsoleCancelEvent(sender, e))
                return;

            try
            {
#if WINFORMS
                DialogResult dialogResult;

                if (prompt)
                {
                    dialogResult = FormOps.YesOrNoOrCancel(
                        demandCancelPromptFormat,
                        GlobalState.GetPackageName(),
                        DefaultCancelDialogResult);
                }
                else
                {
                    dialogResult = DefaultCancelDialogResult;
                }

                if (dialogResult == DialogResult.Cancel)
                {
                    canceled = true;
                    return;
                }

                if (dialogResult == DialogResult.Yes)
#else
                bool? dialogResult;

                if (prompt)
                {
                    dialogResult = WindowOps.YesOrNoOrCancel(
                        demandCancelPromptFormat,
                        GlobalState.GetPackageName(),
                        DefaultCancelDialogResult);
                }
                else
                {
                    dialogResult = DefaultCancelDialogResult;
                }

                if (dialogResult == null)
                {
                    canceled = true;
                    return;
                }

                if ((bool)dialogResult)
#endif
                {
                    interpreterCount = AllCancelAnyEvaluate(true);
                }
                else
                {
                    interpreterCount = AllCancelInteractiveEvaluate(true);
                }
            }
            finally
            {
                MaybeSetConsoleEventArgsCancelFlag(sender, e);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the _Hosts.Console class only.
        //
        /// <summary>
        /// This method creates a new console cancel event handler delegate
        /// suitable for use with the system console.
        /// </summary>
        /// <returns>
        /// A newly created <see cref="ConsoleCancelEventHandler" /> delegate.
        /// </returns>
        internal static ConsoleCancelEventHandler
                NewConsoleCancelEventHandler() /* THREAD-SAFE */
        {
            return new ConsoleCancelEventHandler(
                ConsoleCancelEventHandler);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method is the console cancel event handler used to respond to
        /// Ctrl-C and Ctrl-Break key presses by canceling running scripts,
        /// subject to the current console cancellation settings.
        /// </summary>
        /// <param name="sender">
        /// The object that raised the console cancel event.
        /// </param>
        /// <param name="e">
        /// The data associated with the console cancel event, or null if it
        /// is not available.
        /// </param>
        private static void ConsoleCancelEventHandler(
            object sender,
            ConsoleCancelEventArgs e
            ) /* THREAD-SAFE */
        {
            /* IGNORED */
            Interlocked.Increment(ref cancelViaConsolePending);

            try
            {
                /* IGNORED */
                ResetCancelViaConsoleEvent();

                try
                {
                    //
                    // NOTE: Record local time event handler was entered.
                    //
                    DateTime now = TimeOps.GetNow();

                    //
                    // NOTE: Is script cancellation via the console Ctrl-C
                    //       handler actually enabled right now?
                    //
                    int localSetting = Interlocked.CompareExchange(
                        ref cancelViaConsole[0], 0, 0);

                    //
                    // NOTE: Increment the number of times this static
                    //       event handler has been triggered.
                    //
                    int localCount = Interlocked.Increment(
                        ref cancelViaConsole[1]);

                    //
                    // NOTE: Is the event handler totally disabled?
                    //
                    if (localSetting <= 0)
                    {
                        TraceOps.DebugTrace(
                            "ConsoleCancelEventHandler",
                            "disabled", typeof(Interpreter).Name,
                            TracePriority.HostDebug, false, "sender",
                            sender, "e", e, "cancelCount", localCount,
                            "cancelSetting", localSetting, "dateTime",
                            FormatOps.Iso8601DateTime(now));

                        //
                        // HACK: *SPECIAL* Just let the process die, in
                        //       order to cooperate better with shells
                        //       and other software that uses the shell
                        //       in batch mode.
                        //
                        // MaybeSetConsoleEventArgsCancelFlag(sender, e);
                        //
                        return;
                    }

                    //
                    // NOTE: Is script cancellation via the console
                    //       disabled?
                    //
                    if (localSetting == 1)
                    {
                        TraceOps.DebugTrace(
                            "ConsoleCancelEventHandler",
                            "ignored", typeof(Interpreter).Name,
                            TracePriority.HostDebug, false, "sender",
                            sender, "e", e, "cancelCount", localCount,
                            "cancelSetting", localSetting, "dateTime",
                            FormatOps.Iso8601DateTime(now));

                        MaybeSetConsoleEventArgsCancelFlag(sender, e);
                        return;
                    }

                    //
                    // NOTE: If we get to this point, that means script
                    //       cancellation via the console is enabled.
                    //
                    TraceOps.DebugTrace(
                        "ConsoleCancelEventHandler",
                        "entered", typeof(Interpreter).Name,
                        TracePriority.HostDebug, false, "sender",
                        sender, "e", e, "cancelCount", localCount,
                        "cancelSetting", localSetting, "dateTime",
                        FormatOps.Iso8601DateTime(now));

                    int interpreterCount;
                    bool canceled;

                    MaybeShowPromptAndAllCancel(sender, e,
                        (localSetting <= 2), out interpreterCount,
                        out canceled);

                    if (canceled)
                        goto canceled;

                    goto done;

                canceled:

                    TraceOps.DebugTrace(
                        "ConsoleCancelEventHandler",
                        "canceled", typeof(Interpreter).Name,
                        TracePriority.HostDebug, false, "sender",
                        sender, "e", e, "cancelCount", localCount,
                        "cancelSetting", localSetting, "dateTime",
                        FormatOps.Iso8601DateTime(now));

                    MaybeSetConsoleEventArgsCancelFlag(sender, e);

                done:

                    TraceOps.DebugTrace(
                        "ConsoleCancelEventHandler",
                        "exited", typeof(Interpreter).Name,
                        TracePriority.HostDebug, false, "sender",
                        sender, "e", e, "cancelCount", localCount,
                        "cancelSetting", localSetting, "dateTime",
                        FormatOps.Iso8601DateTime(now),
                        "interpreterCount", interpreterCount);
                }
                finally
                {
                    /* IGNORED */
                    SetCancelViaConsoleEvent();
                }
            }
            finally
            {
                /* IGNORED */
                Interlocked.Decrement(ref cancelViaConsolePending);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Cancel via Console Event
        /// <summary>
        /// This method resets the event used to signal that console-based
        /// script cancellation is in progress.
        /// </summary>
        /// <returns>
        /// True if the event was successfully reset; otherwise, false.
        /// </returns>
        internal static bool ResetCancelViaConsoleEvent()
        {
            return ThreadOps.ResetEvent(cancelViaConsoleEvent);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method signals the event used to indicate that console-based
        /// script cancellation is in progress.
        /// </summary>
        /// <returns>
        /// True if the event was successfully signaled; otherwise, false.
        /// </returns>
        private static bool SetCancelViaConsoleEvent()
        {
            return ThreadOps.SetEvent(cancelViaConsoleEvent);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method waits for the console-based script cancellation event
        /// to become signaled, which indicates that such a cancellation is no
        /// longer in progress.
        /// </summary>
        /// <param name="timeout">
        /// The maximum amount of time, in milliseconds, to wait.
        /// </param>
        /// <returns>
        /// True if the event became signaled within the specified timeout;
        /// otherwise, false.
        /// </returns>
        internal static bool WaitForNotCancelViaConsoleEvent(
            int timeout /* in */
            )
        {
            return ThreadOps.WaitEvent(cancelViaConsoleEvent, timeout);
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Cancel via Console Pending Levels
        /// <summary>
        /// This method determines whether one or more console-based script
        /// cancellations are currently pending.
        /// </summary>
        /// <returns>
        /// True if at least one console-based script cancellation is pending;
        /// otherwise, false.
        /// </returns>
        internal static bool IsCancelViaConsolePending()
        {
            return Interlocked.CompareExchange(
                ref cancelViaConsolePending, 0, 0) > 0;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method waits for all pending console-based script
        /// cancellations to complete, using a default sleep interval between
        /// checks.
        /// </summary>
        /// <param name="waitSeconds">
        /// The maximum amount of time, in seconds, to wait.
        /// </param>
        /// <returns>
        /// True if all pending cancellations completed within the allotted
        /// time; otherwise, false.
        /// </returns>
        private bool WaitForNotCancelViaConsolePending(
            int waitSeconds /* in */
            )
        {
            return WaitForNotCancelViaConsolePending(
                waitCount, GetMinimumSleepTime(SleepType.Dispose));
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method waits for all pending console-based script
        /// cancellations to complete, sleeping for the specified interval
        /// between checks.
        /// </summary>
        /// <param name="waitSeconds">
        /// The maximum amount of time, in seconds, to wait.
        /// </param>
        /// <param name="sleepMilliseconds">
        /// The amount of time, in milliseconds, to sleep between successive
        /// checks.
        /// </param>
        /// <returns>
        /// True if all pending cancellations completed within the allotted
        /// time; otherwise, false.
        /// </returns>
        private static bool WaitForNotCancelViaConsolePending(
            int waitSeconds,      /* in */
            int sleepMilliseconds /* in */
            )
        {
            DateTime start = TimeOps.GetUtcNow();

            try
            {
                while (true)
                {
                    if (!IsCancelViaConsolePending())
                        return true;

                    double elapsedSeconds = 0.0;

                    if (!TimeOps.ElapsedSeconds(
                            ref elapsedSeconds, start) ||
                        (elapsedSeconds < 0) ||
                        (elapsedSeconds > waitSeconds))
                    {
                        return false;
                    }

                    HostOps.ThreadSleep(
                        EventOps.GetDisposeSleepMilliseconds(
                            sleepMilliseconds)); /* throw */
                }
            }
            catch (ThreadAbortException e)
            {
                Thread.ResetAbort();

                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.ThreadError2);

                return false;
            }
            catch (ThreadInterruptedException e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.ThreadError2);

                return false;
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.HostError);

                return false;
            }
            finally
            {
                TracePriority priority = TracePriority.CleanupDebug;
                double stopSeconds = 0.0;

                if (!TimeOps.ElapsedSeconds(ref stopSeconds, start) ||
                    (stopSeconds < 0) || (stopSeconds >= waitSeconds))
                {
                    priority = TracePriority.CleanupError;
                }

                TraceOps.DebugTrace(String.Format(
                    "WaitForNotCancelViaConsolePending: {0} seconds",
                    stopSeconds), typeof(Interpreter).Name, priority);
            }
        }
        #endregion
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method cancels the script (if any) currently being evaluated
        /// by the specified interpreter.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose active script evaluation should be canceled.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellation is performed.
        /// </param>
        private static void CancelAnyEvaluate(
            Interpreter interpreter,
            CancelFlags cancelFlags
            )
        {
            if (interpreter == null)
                return;

            try
            {
                ReturnCode code;
                Result error = null;

                code = interpreter.InternalCancelAnyEvaluateNoContext(
                    demandCancelResultFormat, cancelFlags, ref error);

                if ((code != ReturnCode.Ok) && !FlagOps.HasFlags(
                        cancelFlags, CancelFlags.NoComplain, true))
                {
                    DebugOps.Complain(interpreter, code, error);
                }
            }
            catch (InterpreterDisposedException)
            {
                //
                // NOTE: The interpreter is disposed, do nothing.
                //
                TraceOps.DebugTrace(String.Format(
                    "CancelAnyEvaluate: interpreter = {0}, caught " +
                    "InterpreterDisposedException",
                    FormatOps.InterpreterNoThrow(interpreter)),
                    typeof(Interpreter).Name,
                    TracePriority.EngineError);
            }
            finally
            {
                //
                // BUGFIX: Cleanup any stray contexts that were created
                //         on this [random thread-pool] thread?
                //
                /* IGNORED */
                interpreter.MaybeDisposeThread();
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method cancels the scripts (if any) currently being evaluated
        /// by each of the specified interpreters.
        /// </summary>
        /// <param name="interpreters">
        /// The interpreters whose active script evaluations should be
        /// canceled.
        /// </param>
        /// <param name="cancelFlags">
        /// Flags that control how the cancellations are performed.
        /// </param>
        private static void CancelAnyEvaluate(
            IEnumerable<Interpreter> interpreters,
            CancelFlags cancelFlags
            )
        {
            if (interpreters == null)
                return;

            foreach (Interpreter interpreter in interpreters)
            {
                if (interpreter == null)
                    continue;

                /* NO RESULT */
                CancelAnyEvaluate(interpreter, cancelFlags);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method cancels the scripts currently being evaluated by all
        /// known interpreters.
        /// </summary>
        /// <param name="global">
        /// Non-zero to also cancel scripts being evaluated at the global
        /// level.
        /// </param>
        /// <returns>
        /// The number of interpreters that had their scripts canceled.
        /// </returns>
        private static int AllCancelAnyEvaluate(
            bool global
            )
        {
            return AllCancelAnyEvaluate(
                GlobalState.GetInterpreters(), global);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method cancels the scripts currently being evaluated by all
        /// known interactive interpreters.
        /// </summary>
        /// <param name="global">
        /// Non-zero to also cancel scripts being evaluated at the global
        /// level.
        /// </param>
        /// <returns>
        /// The number of interpreters that had their scripts canceled.
        /// </returns>
        private static int AllCancelInteractiveEvaluate(
            bool global
            )
        {
            return AllCancelAnyEvaluate(GetAllInteractive(
                GlobalState.GetInterpreters()), global);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method cancels the scripts currently being evaluated by each
        /// of the specified interpreters, including those of their child
        /// interpreters.
        /// </summary>
        /// <param name="interpreters">
        /// The interpreters whose active script evaluations should be
        /// canceled.
        /// </param>
        /// <param name="global">
        /// Non-zero to also cancel scripts being evaluated at the global
        /// level.
        /// </param>
        /// <returns>
        /// The total number of interpreters that had their scripts canceled,
        /// including child interpreters.
        /// </returns>
        private static int AllCancelAnyEvaluate(
            IEnumerable<Interpreter> interpreters,
            bool global
            )
        {
            if (interpreters == null)
                return Count.Invalid;

            CancelFlags cancelFlags = RuntimeOps.GetCancelEvaluateFlags(
                global, true, true, false, true, false);

            cancelFlags |= CancelFlags.InteractiveCancelEvent;

#if CONSOLE
            bool cancelThread = Interlocked.CompareExchange(
                ref cancelThreadViaConsole, 0, 0) > 0;

            if (cancelThread)
                cancelFlags |= CancelFlags.InteractiveCancelThread;
#endif

            int count = 0;

            foreach (Interpreter interpreter in interpreters)
            {
                if (interpreter == null)
                    continue;

                /* NO RESULT */
                CancelAnyEvaluate(interpreter, cancelFlags);

                count++;

                IList<Interpreter> childInterpreters =
                    interpreter.TryCopyChildInterpreters();

                if (childInterpreters == null)
                    continue;

                /* NO RESULT */
                CancelAnyEvaluate(childInterpreters, cancelFlags);

                count += childInterpreters.Count;
            }

            return count;
        }

