        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method calculates the number of seconds that have elapsed
        /// since this interpreter was created.
        /// </summary>
        /// <param name="now">
        /// The current time, expressed as UTC.
        /// </param>
        /// <returns>
        /// The number of seconds elapsed since this interpreter was created,
        /// or null if it cannot be determined.
        /// </returns>
        private double? SecondsSinceCreated(
            DateTime now
            )
        {
            try
            {
                long ticks = Interlocked.CompareExchange(
                    ref createdTicks, 0, 0);

                if (ticks != _Ticks.Invalid)
                {
                    DateTime? then = FormatOps.UtcOrNull(ticks);

                    if (then != null)
                    {
                        return now.Subtract(
                            (DateTime)then).TotalSeconds; /* throw */
                    }
                }
            }
            catch
            {
                // do nothing.
            }

            return null;
        }

