        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether security has ever been enabled for
        /// this interpreter.
        /// </summary>
        /// <returns>
        /// True if security has been enabled for this interpreter; otherwise,
        /// false.
        /// </returns>
        internal bool HasSecurity()
        {
            return FlagOps.HasFlags(interpreterStateFlags, /* NO-LOCK */
                InterpreterStateFlags.SecurityWasEnabled, true); /* EXEMPT */
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether policy checking is currently in
        /// progress for this interpreter.
        /// </summary>
        /// <returns>
        /// True if policy checking is currently pending; otherwise, false.
        /// </returns>
        private bool HasPendingPolicies()
        {
            return FlagOps.HasFlags(InterpreterStateFlagsNoLock,
                InterpreterStateFlags.PendingPolicies, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks policy checking as pending for this interpreter,
        /// saving the previous interpreter state flags so that they can be
        /// restored later.
        /// </summary>
        /// <param name="savedInterpreterStateFlags">
        /// Upon return, this parameter receives the previous interpreter state
        /// flags.
        /// </param>
        private void BeginPendingPolicies(
            out InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            savedInterpreterStateFlags = ContextInterpreterStateFlags;
            ContextInterpreterStateFlags |= InterpreterStateFlags.PendingPolicies;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the pending policy checking state for this
        /// interpreter, restoring the previously saved interpreter state
        /// flags.
        /// </summary>
        /// <param name="savedInterpreterStateFlags">
        /// The previously saved interpreter state flags, as produced by the
        /// matching <c>BeginPendingPolicies</c> call.  This parameter is reset
        /// to <see cref="InterpreterStateFlags.None" /> before returning.
        /// </param>
        private void EndPendingPolicies(
            ref InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            ContextInterpreterStateFlags = savedInterpreterStateFlags;
            savedInterpreterStateFlags = InterpreterStateFlags.None;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the text encoding to use when applying
        /// policies.
        /// </summary>
        /// <param name="rawBytes">
        /// Non-zero to return an encoding suitable for raw bytes; otherwise,
        /// the default text encoding is returned.
        /// </param>
        /// <returns>
        /// The <see cref="Encoding" /> to use for policy processing.
        /// </returns>
        private static Encoding GetPolicyEncoding(
            bool rawBytes
            )
        {
            return rawBytes ? OneByteEncoding.OneByte :
                StringOps.GetEncoding(EncodingType.Default);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method emits, when appropriate, a diagnostic trace describing
        /// the results of checking a set of policies.
        /// </summary>
        /// <param name="allPolicies">
        /// The complete set of policies that were checked.
        /// </param>
        /// <param name="failedPolicies">
        /// The subset of policies that failed, if any.
        /// </param>
        /// <param name="methodFlags">
        /// The method flags associated with the policy check.
        /// </param>
        /// <param name="policyFlags">
        /// The policy flags associated with the policy check.
        /// </param>
        /// <param name="fileName">
        /// The file name associated with the policy check, if any.
        /// </param>
        /// <param name="code">
        /// The overall return code produced by the policy check.
        /// </param>
        /// <param name="decision">
        /// The overall policy decision produced by the policy check.
        /// </param>
        /// <param name="result">
        /// The result or error message produced by the policy check.
        /// </param>
        private void MaybeEmitPolicyResults(
            PolicyWrapperDictionary allPolicies,
            PolicyWrapperDictionary failedPolicies,
            MethodFlags methodFlags,
            PolicyFlags policyFlags,
            string fileName,
            ReturnCode code,
            PolicyDecision decision,
            Result result
            )
        {
            TracePriority priority;

            if (PolicyOps.IsSuccess(code, decision))
            {
#if DEBUG
                priority = TracePriority.PolicyDebug;
#else
                return;
#endif
            }
            else
            {
                priority = TracePriority.PolicyError;
            }

            string formatted = FormatOps.MaybeEmitPolicyResults(
                allPolicies, failedPolicies, methodFlags,
                policyFlags, fileName, code, decision, result);

            TraceOps.DebugTrace(
                formatted, typeof(Interpreter).Name, priority);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks the specified entity against all of the
        /// applicable policies configured for this interpreter, combining their
        /// decisions.
        /// </summary>
        /// <param name="methodFlags">
        /// The method flags used to select which policies apply.
        /// </param>
        /// <param name="policyFlags">
        /// The policy flags that control how the policies are checked.
        /// </param>
        /// <param name="assemblyName">
        /// The assembly name being checked, if applicable.
        /// </param>
        /// <param name="typeName">
        /// The type name being checked, if applicable.
        /// </param>
        /// <param name="execute">
        /// The executable entity being checked, if applicable.
        /// </param>
        /// <param name="arguments">
        /// The arguments being checked, if applicable.
        /// </param>
        /// <param name="script">
        /// The script being checked, if applicable.
        /// </param>
        /// <param name="fileName">
        /// The file name being checked, if applicable.
        /// </param>
        /// <param name="bytes">
        /// The raw bytes being checked, if applicable.
        /// </param>
        /// <param name="text">
        /// The text being checked, if applicable.
        /// </param>
        /// <param name="encoding">
        /// The encoding associated with the entity being checked, if
        /// applicable.
        /// </param>
        /// <param name="timeout">
        /// The timeout, in milliseconds, to make available to the policies, or
        /// null for none.
        /// </param>
        /// <param name="hashValue">
        /// The precomputed hash of the entity being checked, if any.
        /// </param>
        /// <param name="hashAlgorithmName">
        /// The name of the hash algorithm used to compute the hash, or null to
        /// use the default.
        /// </param>
        /// <param name="clientData">
        /// The client data to make available to the policies.
        /// </param>
        /// <param name="decision">
        /// Provides and receives the policy decision; upon return, it reflects
        /// the combined decision of the checked policies.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives an optional informational
        /// message; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode CheckPolicies(
            MethodFlags methodFlags,
            PolicyFlags policyFlags,
            AssemblyName assemblyName,
            string typeName,
            IExecute execute,
            ArgumentList arguments,
            IScript script,
            string fileName,
            byte[] bytes,
            string text,
            Encoding encoding,
            int? timeout,
            byte[] hashValue,
            string hashAlgorithmName,
            IClientData clientData,
            ref PolicyDecision decision,
            ref Result result
            )
        {
            //
            // NOTE: Prevent endless recursion.
            //
            if (HasPendingPolicies() || (PolicyLevels != 0))
                return ReturnCode.Ok;

            //
            // NOTE: Attempt to grab a copy of the policy collection for
            //       the current interpreter and see if this interpreter
            //       support policies?
            //
            PolicyWrapperDictionary allPolicies = CopyPolicies();

            if (allPolicies == null)
                return ReturnCode.Ok;

            InterpreterStateFlags savedInterpreterStateFlags;

            BeginPendingPolicies(out savedInterpreterStateFlags);

            try
            {
                //
                // NOTE: How many policies with good intentions have failed?
                //
                PolicyWrapperDictionary failedPolicies = null;

                //
                // NOTE: Create the policy data object with the current policy
                //       related information (including the original decision,
                //       which is typically "unknown").
                //
                IPolicyContext policyContext = PolicyContext.Create(
                    policyFlags, assemblyName, typeName, execute,
                    arguments, script, fileName, bytes, text, encoding,
                    timeout, hashValue, hashAlgorithmName, clientData,
                    /* interpreter */ null, /* plugin */ null, decision);

                //
                // NOTE: When going through the generic callback delegates, we
                //       need to wrap our object in a clientData.
                //
                IClientData policyClientData = new ClientData(policyContext);

                //
                // NOTE: Process each policy (as long as they all continue
                //       to succeed).
                //
                ReturnCode code = ReturnCode.Ok;

                foreach (PolicyPair pair in allPolicies)
                {
                    IPolicy policy = pair.Value;

                    //
                    // NOTE: Skip invalid policies.
                    //
                    if (policy == null)
                        continue;

                    //
                    // NOTE: Do not invoke the policy if it has been disabled.
                    //
                    if (EntityOps.IsDisabled(policy))
                        continue;

                    //
                    // NOTE: Only execute the policies which match the specified
                    //       flags (i.e. command or file policies).
                    //
                    // FIXME: *PERF* Make sure this does not impact policy
                    //        performance too seriously.
                    //
                    if (!EntityOps.HasFlags(policy, methodFlags, false))
                        continue;

                    //
                    // NOTE: Since policies can basically do anything they want,
                    //       we wrap them in a try block to prevent exceptions
                    //       from escaping.
                    //
                    EnterPolicyLevel();

                    try
                    {
                        //
                        // HACK: Since we need the plugin to vary with each
                        //       policy called, do that now (i.e. to provide
                        //       more context for isolated policy support).
                        //
                        // TODO: Improve the locking semantics here.
                        //
                        PolicyDecision beforeDecision = policyContext.Decision;
                        PolicyDecision afterDecision = beforeDecision;

                        try
                        {
                            policyContext.Interpreter = this;
                            policyContext.Plugin = policy.Plugin;

                            code = policy.Execute(
                                this, policyClientData, arguments, ref result);

                            afterDecision = policyContext.Decision;
                        }
                        finally
                        {
                            if ((code != ReturnCode.Ok) ||
                                (PolicyOps.IsSuccess(beforeDecision) &&
                                !PolicyOps.IsSuccess(afterDecision)))
                            {
                                if (failedPolicies == null)
                                    failedPolicies = new PolicyWrapperDictionary();

                                failedPolicies.Add(pair.Key, pair.Value);
                            }
                        }
                    }
                    catch (Exception e)
                    {
                        //
                        // NOTE: Translate exceptions to a failure return.
                        //
                        result = String.Format(
                            "caught exception while checking policies: {0}",
                            e);

                        code = ReturnCode.Error;
                    }
                    finally
                    {
                        ExitPolicyLevel();
                    }

                    //
                    // NOTE: Check for exception results specially because we
                    //       treat "Break" different from other return codes.
                    //
                    if (code == ReturnCode.Break)
                    {
                        //
                        // NOTE: Success; however, skip processing further
                        //       traces for this policy operation.
                        //
                        code = ReturnCode.Ok;
                        break;
                    }
                    else if (code != ReturnCode.Ok)
                    {
                        //
                        // NOTE: Some type of failure (or exception), stop
                        //       processing for this policy operation.
                        //
                        break;
                    }
                }

                //
                // NOTE: If all the policies succeeded and our local "pass" status
                //       is valid, copy it to the variable provided by the caller.
                //
                if (code == ReturnCode.Ok)
                {
                    //
                    // NOTE: Each policy gets one "vote" about whether or not to
                    //       allow the execution of the command.  One or more of
                    //       the current policies must agree for the execution of
                    //       the command to be allowed.  There must always be at
                    //       least one policy that "votes" to allow execution of
                    //       the command before it will be allowed (i.e. the
                    //       default policy denies everything).
                    //
                    decision = policyContext.Decision;

                    //
                    // NOTE: If there is no result so far, use the reason given
                    //       for the policy decision, if any.  We do not care if
                    //       the reason is null at this point.
                    //
                    if (result == null)
                        result = policyContext.Reason;
                }

#if false // DISABLED: HOT-PATH
                bool maybeEmit = true;

#if POLICY_TRACE
                bool didEmit;

                TraceOps.MaybeWritePolicyTrace(
                    "CheckPolicies", this, !PolicyContext.GetForceTraceFull(),
                    out didEmit, "methodFlags", methodFlags, "policyFlags",
                    policyFlags, "assemblyName", assemblyName, "typeName",
                    typeName, "execute", execute, "arguments", arguments,
                    "script", script, "fileName", fileName, "bytes", bytes,
                    "text", text, "encoding", encoding, "timeout", timeout,
                    "hashValue", hashValue, "hashAlgorithmName",
                    hashAlgorithmName, "clientData", clientData,
                    "decision", decision, "code", code, "result", result);

                if (didEmit && PolicyOps.IsSuccess(code, decision))
                    maybeEmit = false;
#endif

                if (maybeEmit)
                {
                    MaybeEmitPolicyResults(
                        allPolicies, failedPolicies, methodFlags,
                        policyFlags, fileName, code, decision,
                        result);
                }
#endif

                return code;
            }
            finally
            {
                EndPendingPolicies(ref savedInterpreterStateFlags);
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Trace Support
        /// <summary>
        /// This method determines whether trace processing is currently in
        /// progress for this interpreter.
        /// </summary>
        /// <returns>
        /// True if trace processing is currently pending; otherwise, false.
        /// </returns>
        private bool HasPendingTraces()
        {
            return FlagOps.HasFlags(InterpreterStateFlagsNoLock,
                InterpreterStateFlags.PendingTraces, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Dead Code
#if DEAD_CODE
        /// <summary>
        /// This method marks the start of a region in which traces are pending,
        /// saving the previous interpreter state flags.
        /// </summary>
        /// <param name="savedInterpreterStateFlags">
        /// Upon return, receives the interpreter state flags as they were before
        /// the pending traces flag was set, for later restoration.
        /// </param>
        private void BeginPendingTraces(
            out InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            savedInterpreterStateFlags = ContextInterpreterStateFlags;
            ContextInterpreterStateFlags |= InterpreterStateFlags.PendingTraces;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the end of a region in which traces are pending,
        /// restoring the previously saved interpreter state flags.
        /// </summary>
        /// <param name="savedInterpreterStateFlags">
        /// The saved interpreter state flags to restore.  Upon return, this is
        /// reset to <see cref="InterpreterStateFlags.None" />.
        /// </param>
        private void EndPendingTraces(
            ref InterpreterStateFlags savedInterpreterStateFlags
            )
        {
            ContextInterpreterStateFlags = savedInterpreterStateFlags;
            savedInterpreterStateFlags = InterpreterStateFlags.None;
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method combines the specified variable traces with the
        /// applicable global variable traces for this interpreter.
        /// </summary>
        /// <param name="traces">
        /// The variable-specific traces to include, if any.
        /// </param>
        /// <param name="varName">
        /// The name of the variable associated with the traces.
        /// </param>
        /// <param name="varIndex">
        /// The array element index associated with the traces, if any.
        /// </param>
        /// <param name="varValue">
        /// The value of the variable associated with the traces, if any.
        /// </param>
        /// <param name="array">
        /// Non-zero if the variable is an array, false if it is a scalar, or
        /// null if this is unknown.
        /// </param>
        /// <returns>
        /// A new list containing the combined traces, or null if there are
        /// none.
        /// </returns>
        internal TraceList GetTraces(
            TraceList traces,
            string varName,
            string varIndex,
            object varValue,
            bool? array
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                TraceList result = null;

                TraceList globalTraces = MakeTraceList(
                    varName, varIndex, varValue, array, null);

                if ((globalTraces != null) || (traces != null))
                {
                    result = new TraceList();

                    if (traces != null)
                        result.AddRange(traces);

                    if (globalTraces != null)
                        result.AddRange(globalTraces);
                }

                return result;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a new trace information object is
        /// needed for an operation using the specified variable flags.
        /// </summary>
        /// <param name="flags">
        /// The variable flags associated with the operation.
        /// </param>
        /// <returns>
        /// True if a new trace information object is needed; otherwise, false.
        /// </returns>
        internal bool NeedNewTraceInfo(
            VariableFlags flags
            )
        {
            if (FlagOps.HasFlags(flags, VariableFlags.NewTraceInfo, true))
                return true;

            //
            // NOTE: Query the number of trace levels at this point.
            //       Normally, this should be exactly one.
            //
            int levels = TraceLevels;

#if DEBUGGER
            //
            // NOTE: When compiled with integrated debugger support,
            //       also count the number of watchpoint levels.
            //
            levels += WatchpointLevels;
#endif

            return (levels > 0);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the flags, links, and traces of a variable that
        /// was previously undefined or a link, so that it behaves like a newly
        /// defined variable.
        /// </summary>
        /// <param name="frame">
        /// The call frame associated with the variable.
        /// </param>
        /// <param name="savedVariable">
        /// The previously saved variable that may be linked to the variable,
        /// if any.
        /// </param>
        /// <param name="variable">
        /// The variable whose flags or link should be cleared.
        /// </param>
        /// <param name="traceInfo">
        /// The trace information that supplies the variable flags, if any.
        /// </param>
        /// <param name="traces">
        /// The traces to assign to the newly defined variable, if any.
        /// </param>
        /// <param name="wasUndefined">
        /// Upon return, this parameter is set to true if the variable was
        /// previously undefined; otherwise, it is set to false.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode ClearVariableFlagsOrLink(
            ICallFrame frame,
            IVariable savedVariable,
            IVariable variable,
            ITraceInfo traceInfo,
            TraceList traces,
            ref bool wasUndefined,
            ref Result error
            )
        {
            //
            // BUGFIX: The variable may have been undefined or a link to a
            //         variable in an undefined call frame.
            //
            if (variable != null)
            {
                wasUndefined = EntityOps.IsUndefined(variable);
                bool isLink = EntityOps.IsLink(variable);

                if (wasUndefined || isLink)
                {
                    //
                    // NOTE: First, grab the variable flags from the trace, if
                    //       any.
                    //
                    VariableFlags flags = (traceInfo != null) ?
                        traceInfo.Flags : VariableFlags.None;

                    //
                    // NOTE: Next, attempt to obtain the call frame that this
                    //       variable belongs to.
                    //
                    ICallFrame variableFrame = frame;

                    if (GetVariableFrameViaResolvers(
                            LookupFlags.Default, ref variableFrame, ref flags,
                            ref error) != ReturnCode.Ok)
                    {
                        return ReturnCode.Error;
                    }

                    //
                    // NOTE: Next, figure out which variable flags need to be
                    //       masked off.  If the variable is being recycled
                    //       (i.e. because it was previously undefined), there
                    //       are additional flags to mask off.
                    //
                    VariableFlags flagsMask = VariableFlags.NonSetMask;

                    if (wasUndefined)
                        flagsMask = VariableFlags.NonDefinedMask;

                    //
                    // NOTE: Next, reset the flags to the ones provided by the
                    //       caller, masking off any invalid ones.
                    //
                    variable.Flags = (flags & ~flagsMask);

                    //
                    // NOTE: If this variable was pointed to by a link, make
                    //       sure that link is "defined" now as well.
                    //
                    if ((savedVariable != null) &&
                        !Object.ReferenceEquals(savedVariable, variable))
                    {
                        EntityOps.SetUndefined(savedVariable, false);
                    }

                    //
                    // NOTE: Next, make sure the variable is no longer a link
                    //       to another variable, if necessary.
                    //
                    if (isLink)
                    {
                        EntityOps.SetLink(variable, false);

                        variable.Link = null;
                        variable.LinkIndex = null;
                    }

                    //
                    // NOTE: Next, flag the variable as either global or local,
                    //       depending on the call frame it resides in.
                    //
                    if (IsGlobalCallFrame(variableFrame))
                        EntityOps.SetGlobal(variable, true);
                    else
                        EntityOps.SetLocal(variable, true);

                    //
                    // NOTE: Next, reset the traces for this variable to the
                    //       same ones that would be assigned to brand new
                    //       variables.
                    //
                    variable.Traces = GetTraces(
                        traces, null, null, null, null);
                }
            }
            else
            {
                //
                // NOTE: There is no variable; therefore, it cannot be
                //       undefined.
                //
                wasUndefined = false;
            }

            return ReturnCode.Ok;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Alias Support
        /// <summary>
        /// This method builds the target name for invoking the specified
        /// alias, given its arguments.  This overload discards the resulting
        /// target arguments.
        /// </summary>
        /// <param name="alias">
        /// The alias whose target name is being determined.
        /// </param>
