        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode GetAliasArguments(
            IAlias alias,
            ArgumentList arguments,
            ref string targetName
            )
        {
            ArgumentList targetArguments = null;

            return GetAliasArguments(
                alias, arguments, ref targetName, ref targetArguments);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds the target name and target arguments for
        /// invoking the specified alias, given its arguments.
        /// </summary>
        /// <param name="alias">
        /// The alias whose target name and arguments are being determined.
        /// </param>
        /// <param name="arguments">
        /// The arguments supplied to the alias.
        /// </param>
        /// <param name="targetName">
        /// Upon success, this parameter receives the resolved target name.
        /// </param>
        /// <param name="targetArguments">
        /// Upon success, this parameter receives the resolved target
        /// arguments.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode GetAliasArguments(
            IAlias alias,
            ArgumentList arguments,
            ref string targetName,
            ref ArgumentList targetArguments
            )
        {
            Result error = null;

            return GetAliasArguments(
                alias, arguments, ref targetName, ref targetArguments, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds the target name for invoking the specified
        /// alias, given its arguments.  This overload discards the resulting
        /// target arguments.
        /// </summary>
        /// <param name="alias">
        /// The alias whose target name is being determined.
        /// </param>
        /// <param name="arguments">
        /// The arguments supplied to the alias.
        /// </param>
        /// <param name="targetName">
        /// Upon success, this parameter receives the resolved target name.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode GetAliasArguments(
            IAlias alias,
            ArgumentList arguments,
            ref string targetName,
            ref Result error
            )
        {
            ArgumentList targetArguments = null;

            return GetAliasArguments(
                alias, arguments, ref targetName, ref targetArguments, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds the target name and target arguments for
        /// invoking the specified alias, given its arguments.
        /// </summary>
        /// <param name="alias">
        /// The alias whose target name and arguments are being determined.
        /// </param>
        /// <param name="arguments">
        /// The arguments supplied to the alias.
        /// </param>
        /// <param name="targetName">
        /// Upon success, this parameter receives the resolved target name.
        /// </param>
        /// <param name="targetArguments">
        /// Upon success, this parameter receives the resolved target
        /// arguments.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode GetAliasArguments(
            IAlias alias,
            ArgumentList arguments,
            ref string targetName,
            ref ArgumentList targetArguments,
            ref Result error
            )
        {
            ReturnCode code;

            if (alias != null)
            {
                AliasFlags aliasFlags = alias.AliasFlags;

                bool mergeArguments = FlagOps.HasFlags(
                    aliasFlags, AliasFlags.MergeArguments, true);

                bool skipTargetName = FlagOps.HasFlags(
                    aliasFlags, AliasFlags.SkipTargetName, true);

                bool skipSourceName = FlagOps.HasFlags(
                    aliasFlags, AliasFlags.SkipSourceName, true);

                bool useTargetRemaining = FlagOps.HasFlags(
                    aliasFlags, AliasFlags.UseTargetRemaining, true);

                if (mergeArguments)
                {
                    //
                    // NOTE: Merged argument handling, carefully merge the
                    //       option and non-option arguments from the first
                    //       and second lists.  The start index for the second
                    //       list here is hard-coded to one because we know
                    //       that the command name itself is the first argument
                    //       in the second list.
                    //
                    code = PrivateMergeArguments(
                        alias.Options, alias.Arguments, arguments,
                        OptionBehaviorFlags.Default, alias.StartIndex, 1,
                        skipTargetName, skipSourceName, useTargetRemaining,
                        ref targetArguments, ref error);
                }
                else
                {
                    targetArguments = null;

                    //
                    // NOTE: Standard argument handling, simply append the
                    //       arguments from the first and second lists, in that
                    //       order, to the target argument list.
                    //
                    if ((alias.Arguments != null) || (arguments != null))
                        targetArguments = new ArgumentList();

                    if (alias.Arguments != null)
                    {
                        targetArguments.AddRange(ArgumentList.GetRange(
                            alias.Arguments, skipTargetName ? 1 : 0));
                    }

                    if (arguments != null)
                    {
                        targetArguments.AddRange(ArgumentList.GetRange(
                            arguments, skipSourceName ? 1 : 0));
                    }

                    code = ReturnCode.Ok;
                }

                //
                // NOTE: If necessary, modify the first argument to be the
                //       alias name.  Afterwards, always provide the value of
                //       the first argument to the caller.
                //
                targetName = null;

                if ((targetArguments != null) && (targetArguments.Count > 0))
                    targetName = targetArguments[0];
            }
            else
            {
                error = "invalid alias";
                code = ReturnCode.Error;
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves the target executable entity for the specified
        /// alias.  This overload discards the unknown-handler flag and any
        /// error message.
        /// </summary>
        /// <param name="alias">
        /// The alias whose target is being resolved.
        /// </param>
        /// <param name="targetName">
        /// The name of the target to resolve.
        /// </param>
        /// <param name="targetArguments">
        /// The arguments associated with the target, if any.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the target is looked up.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat an unresolved target as an error.
        /// </param>
        /// <param name="target">
        /// Upon success, this parameter receives the resolved target.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode GetAliasTarget(
            IAlias alias,
            string targetName,
            ArgumentList targetArguments,
            LookupFlags lookupFlags,
            bool strict,
            ref IExecute target
            )
        {
            bool useUnknown = false;
            Result error = null;

            return GetAliasTarget(
                alias, targetName, targetArguments, lookupFlags, strict,
                ref target, ref useUnknown, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves the target executable entity for the specified
        /// alias.  This overload discards the unknown-handler flag.
        /// </summary>
        /// <param name="alias">
        /// The alias whose target is being resolved.
        /// </param>
        /// <param name="targetName">
        /// The name of the target to resolve.
        /// </param>
        /// <param name="targetArguments">
        /// The arguments associated with the target, if any.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the target is looked up.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat an unresolved target as an error.
        /// </param>
        /// <param name="target">
        /// Upon success, this parameter receives the resolved target.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode GetAliasTarget(
            IAlias alias,
            string targetName,
            ArgumentList targetArguments,
            LookupFlags lookupFlags,
            bool strict,
            ref IExecute target,
            ref Result error
            )
        {
            bool useUnknown = false;

            return GetAliasTarget(
                alias, targetName, targetArguments, lookupFlags, strict,
                ref target, ref useUnknown, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves the target executable entity for the specified
        /// alias, optionally falling back to the unknown command handler.
        /// </summary>
        /// <param name="alias">
        /// The alias whose target is being resolved.
        /// </param>
        /// <param name="targetName">
        /// The name of the target to resolve.
        /// </param>
        /// <param name="targetArguments">
        /// The arguments associated with the target, if any.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the target is looked up.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat an unresolved target as an error.
        /// </param>
        /// <param name="target">
        /// Upon success, this parameter receives the resolved target.
        /// </param>
        /// <param name="useUnknown">
        /// Upon return, this parameter is set to true if the unknown command
        /// handler was used to resolve the target.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode GetAliasTarget(
            IAlias alias,
            string targetName,
            ArgumentList targetArguments,
            LookupFlags lookupFlags,
            bool strict,
            ref IExecute target,
            ref bool useUnknown,
            ref Result error
            )
        {
            if (alias == null)
            {
                error = "invalid alias";
                return ReturnCode.Error;
            }

            //
            // NOTE: First, try for the pre-resolved target.
            //
            target = alias.Target;

            //
            // NOTE: Otherwise, is this a late-bound alias?
            //
            if (target != null)
            {
                //
                // NOTE: Success, just return it.
                //
                return ReturnCode.Ok;
            }
            else
            {
                //
                // NOTE: Query the necessary engine flags for use with the
                //       resolver subsystem.
                //
                EngineFlags engineFlags = GetResolveEngineFlagsNoLock(true);

                //
                // NOTE: If this alias has the global flag, make sure to use
                //       the global engine flag (to the resolver) as well.
                //
                if (FlagOps.HasFlags(
                        alias.AliasFlags, AliasFlags.GlobalNamespace, true))
                {
                    engineFlags |= EngineFlags.GlobalOnly;
                }

                ReturnCode code;
                Result localError = null;

                //
                // NOTE: Not found; lookup the target by name.
                //
                code = InternalGetIExecuteViaResolvers(
                    engineFlags, targetName, targetArguments, lookupFlags,
                    ref target, ref localError);

                //
                // NOTE: During the alias creation process, the target
                //       does not have to be defined.  However, during
                //       the execution process, it does.  This can only
                //       work if there are target arguments since there
                //       is no other usable basis to use for looking up
                //       an executable entity.
                //
                if (code != ReturnCode.Ok)
                {
                    //
                    // NOTE: Attempt to use the unknown handler for
                    //       the interpreter when the target cannot
                    //       be resolved (COMPAT: Tcl).
                    //
                    code = AttemptToUseUnknown(
                        code, engineFlags | EngineFlags.GlobalOnly,
                        lookupFlags, ref targetArguments, ref target,
                        ref useUnknown);

                    if (code != ReturnCode.Ok)
                    {
                        if (!strict)
                            code = ReturnCode.Ok;
                        else
                            error = localError;
                    }
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns a unique name token for an alias with the
        /// specified name, prepending namespace separators as needed to avoid
        /// collisions.
        /// </summary>
        /// <param name="name">
        /// The candidate alias name.
        /// </param>
        /// <returns>
        /// A unique name token derived from <paramref name="name" />.
        /// </returns>
        internal string GetAliasNameToken(string name)
        {
            //
            // NOTE: Initially, the name token is the same as the name;
            //       however, this may change later if the command is
            //       renamed.
            //
            string result = name;

            if (!String.IsNullOrEmpty(result))
            {
                while (DoesAliasExist(result) == ReturnCode.Ok)
                {
                    /*
                     * NOTE: This comment stolen from "generic/tclInterp.c".
                     *
                     * The alias name cannot be used as unique token, it is already taken.
                     * We can produce a unique token by prepending "::" repeatedly. This
                     * algorithm is a stop-gap to try to maintain the command name as
                     * token for most use cases, fearful of possible backwards compat
                     * problems. A better algorithm would produce unique tokens that need
                     * not be related to the command name.
                     *
                     * ATTENTION: the tests in interp.test and possibly safe.test depend
                     * on the precise definition of these tokens.
                     *
                     */
                    result = TclVars.Namespace.Separator + result;
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines the old and (possibly namespace-qualified)
        /// new command names to use when renaming a command.
        /// </summary>
        /// <param name="identifierName">
        /// The identifier supplying the existing command name.
        /// </param>
        /// <param name="noNamespaces">
        /// Non-zero to disable namespace-qualification of the new command
        /// name.
        /// </param>
        /// <param name="oldCommandName">
        /// Upon return, this parameter receives the existing command name.
        /// </param>
        /// <param name="newCommandName">
        /// Provides the requested new command name and, upon return, receives
        /// the possibly namespace-qualified new command name.
        /// </param>
        private void GetCommandNamesForRename(
            IIdentifierName identifierName, /* in */
            bool noNamespaces,              /* in */
            ref string oldCommandName,      /* out */
            ref string newCommandName       /* in, out */
            )
        {
            if (identifierName == null)
                return;

            oldCommandName = identifierName.Name;

            if (oldCommandName == null)
                return;

            bool useNamespaces = !noNamespaces && InternalAreNamespacesEnabled();

            if (useNamespaces && !NamespaceOps.IsQualifiedName(newCommandName))
            {
                INamespace @namespace = NamespaceOps.LookupParent(
                    this, oldCommandName, false, true, false);

                if (@namespace != null)
                {
                    newCommandName = NamespaceOps.MakeQualifiedName(
                        this, @namespace, newCommandName);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method follows the specified alias to the next alias in its
        /// chain, if any, taking a pending rename into account.
        /// </summary>
        /// <param name="alias">
        /// The original alias at the start of the chain.
        /// </param>
        /// <param name="nextAlias">
        /// The current alias in the chain to follow.
        /// </param>
        /// <param name="newName">
        /// The new name being assigned to the alias, if it is being renamed;
        /// otherwise, null.
        /// </param>
        /// <returns>
        /// The next alias in the chain, or null if there is none.
        /// </returns>
        private IAlias FollowAlias(
            IAlias alias,
            IAlias nextAlias,
            string newName
            )
        {
            IAlias result = null;

            if (nextAlias.Target != null)
            {
                result = nextAlias.Target as IAlias;
            }
            else
            {
                Interpreter targetInterpreter = nextAlias.TargetInterpreter;

                if (targetInterpreter != null)
                {
                    string targetName = null;
                    ArgumentList targetArguments = null;

                    if (targetInterpreter.GetAliasArguments(
                            nextAlias, null, ref targetName,
                            ref targetArguments) == ReturnCode.Ok)
                    {
                        if (targetName != null)
                        {
                            if (targetInterpreter.GetAlias(
                                    targetName, LookupFlags.Default,
                                    ref result) != ReturnCode.Ok)
                            {
                                //
                                // NOTE: If the alias is being renamed, make
                                //       sure we are using the new name (i.e.
                                //       in that case the caller(s) is/are
                                //       responsible for passing it to us).
                                //
                                if (Object.ReferenceEquals(targetInterpreter, this) &&
                                    SharedStringOps.SystemEquals(targetName,
                                        (newName != null) ? newName : alias.Name))
                                {
                                    result = alias;
                                }
                            }
                        }
                    }
                }
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method verifies that defining or renaming the specified alias
        /// would not create a loop in its chain.
        /// </summary>
        /// <param name="alias">
        /// The alias being defined or renamed.
        /// </param>
        /// <param name="newName">
        /// The new name being assigned to the alias, if it is being renamed;
        /// otherwise, null.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if no loop would be created; otherwise,
        /// an appropriate error code.
        /// </returns>
        private ReturnCode PreventAliasLoop(
            IAlias alias,
            string newName,
            ref Result error
            )
        {
            IAlias nextAlias = alias;

            while (nextAlias != null)
            {
                //
                // NOTE: Proceed to the next alias in the chain.
                //
                nextAlias = FollowAlias(alias, nextAlias, newName);

                //
                // NOTE: Check to see if we have found a loop.
                //
                if (Object.ReferenceEquals(nextAlias, alias))
                {
                    error = String.Format(
                        "cannot define or rename alias {0}: would create a loop",
                        FormatOps.WrapOrNull(
                            (newName != null) ? newName : alias.Name));

                    return ReturnCode.Error;
                }
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method adds the specified alias and its associated command to
        /// this interpreter.
        /// </summary>
        /// <param name="alias">
        /// The alias (which may also be a command) to add.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the alias and command.
        /// </param>
        /// <param name="token">
        /// Upon success, this parameter receives the token assigned to the
        /// added alias.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives an optional informational
        /// message; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode AddAliasAndCommand(
            IAlias alias,
            IClientData clientData,
            ref long token,
            ref Result result
            )
        {
            if (PreventAliasLoop(alias, null, ref result) == ReturnCode.Ok)
                //
                // NOTE: If the provided alias is not also a command, this cast will
                //       silently fail; however, that is fine because AddCommand will
                //       return an appropriate error message to the caller.
                //
                if (AddCommand(alias as ICommand, clientData, ref result) == ReturnCode.Ok)
                    if (AddAlias(alias, clientData, ref token, ref result) == ReturnCode.Ok)
                        return ReturnCode.Ok;

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the alias with the specified name, along with
        /// its associated command, from this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the alias to remove.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the removal.
        /// </param>
        /// <param name="strict">
        /// Non-zero to treat a missing alias or command as an error.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives an optional informational
        /// message; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode RemoveAliasAndCommand(
            string name,
            IClientData clientData,
            bool strict,
            ref Result result
            )
        {
            /* CheckDisposed(); */

            Result localResult = null;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (PrivateHasAliases(ref localResult))
                {
                    IAlias alias = null;

                    if (GetAlias(
                            name, LookupFlags.Default, ref alias,
                            ref localResult) == ReturnCode.Ok)
                    {
                        if (InternalRemoveAlias(
                                alias.NameToken, clientData,
                                ref localResult) == ReturnCode.Ok)
                        {
                            if (PrivateHasCommands(ref localResult))
                            {
                                string commandName =
                                    ScriptOps.MakeCommandName(
                                        alias.Name);

                                if ((DoesCommandExist(
                                        commandName) != ReturnCode.Ok) ||
                                    (RemoveCommand(
                                        commandName, clientData,
                                        ref localResult) == ReturnCode.Ok))
                                {
                                    return ReturnCode.Ok;
                                }
                            }
                            else if (!strict)
                            {
                                return ReturnCode.Ok;
                            }
                        }
                    }
                }
                else if (!strict)
                {
                    return ReturnCode.Ok;
                }
            }

            result = localResult;
            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interpreter Alias Support
        /// <summary>
        /// This method determines whether a cross-interpreter alias with the
        /// specified name exists in this interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the alias to check.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if a matching cross-interpreter alias
        /// exists; otherwise, an appropriate error code.
        /// </returns>
        private ReturnCode HasInterpreterAlias(
            string name
            )
        {
            IAlias alias = null;

            if (GetAlias(
                    name, LookupFlags.AliasNoVerbose,
                    ref alias) != ReturnCode.Ok)
            {
                return ReturnCode.Error;
            }

            if (!FlagOps.HasFlags(alias.AliasFlags,
                    AliasFlags.CrossInterpreter, true))
            {
                return ReturnCode.Error;
            }

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves the target command used to implement
        /// cross-interpreter aliases (i.e. the [interp] command).
        /// </summary>
        /// <param name="target">
        /// Upon success, this parameter receives the resolved target command.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode GetInterpreterAliasTarget(
            ref IExecute target,
            ref Result error
            )
        {
            ICommand command = null;

            if (GetCommand(
                    typeof(_Commands.Interp), LookupFlags.AliasDefault,
                    ref command, ref error) == ReturnCode.Ok)
            {
                target = command;

                return ReturnCode.Ok;
            }

            return ReturnCode.Error;
        }

