        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Child Interpreter Support
        /// <summary>
        /// This method determines the path, relative to this interpreter, of
        /// the specified descendant interpreter.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose path is being determined.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives the path, as a list of child
        /// interpreter names; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode GetInterpreterPath(
            Interpreter interpreter,
            ref Result result
            )
        {
            if (interpreter == null)
            {
                result = "invalid interpreter";
                return ReturnCode.Error;
            }

            if (Object.ReferenceEquals(interpreter, this))
            {
                result = String.Empty;
                return ReturnCode.Ok;
            }

            Interpreter otherInterpreter = interpreter;
            StringList list = new StringList();

            while (!Object.ReferenceEquals(otherInterpreter, this))
            {
                string childName = otherInterpreter.ChildName;

                if (childName == null)
                    childName = otherInterpreter.InternalToString();

                //
                // NOTE: Keep track of the names going up the chain.
                //
                list.Add(childName);

                //
                // NOTE: Traverse to our parent interpreter.
                //
                otherInterpreter = otherInterpreter.ParentInterpreter;

                //
                // NOTE: Make sure the interpreter is still valid
                //       because we still haven't found this
                //       interpreter yet.
                //
                if (otherInterpreter == null)
                {
                    //
                    // NOTE: This should not really happen.  If so,
                    //       it is an error.
                    //
                    result = "invalid parent interpreter";
                    return ReturnCode.Error;
                }
            }

            list.Reverse();
            result = list;

            return ReturnCode.Ok;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves the nested child interpreter identified by the
        /// specified path.  This overload discards the resolved leaf name.
        /// </summary>
        /// <param name="path">
        /// The path identifying the nested child interpreter.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the interpreter is looked up.
        /// </param>
        /// <param name="create">
        /// Non-zero to return the parent interpreter into which a new child
        /// should be created, rather than the leaf interpreter itself.
        /// </param>
        /// <param name="interpreter">
        /// Upon success, this parameter receives the resolved interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode GetNestedChildInterpreter(
            string path,
            LookupFlags lookupFlags,
            bool create,
            ref Interpreter interpreter, /* NOTE: Only set upon success. */
            ref Result error             /* NOTE: Only set upon failure. */
            )
        {
            string name = null;

            return GetNestedChildInterpreter(
                path, lookupFlags, create, ref interpreter, ref name,
                ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resolves the nested child interpreter identified by the
        /// specified path, also returning the leaf name.
        /// </summary>
        /// <param name="path">
        /// The path identifying the nested child interpreter.
        /// </param>
        /// <param name="lookupFlags">
        /// Flags that control how the interpreter is looked up.
        /// </param>
        /// <param name="create">
        /// Non-zero to return the parent interpreter into which a new child
        /// should be created, rather than the leaf interpreter itself.
        /// </param>
        /// <param name="interpreter">
        /// Upon success, this parameter receives the resolved interpreter.
        /// </param>
        /// <param name="name">
        /// Upon success, this parameter receives the name of the leaf (or
        /// to-be-created) interpreter.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode GetNestedChildInterpreter(
            string path,                 /* in */
            LookupFlags lookupFlags,     /* in */
            bool create,                 /* in */
            ref Interpreter interpreter, /* out */
            ref string name,             /* out */
            ref Result error             /* out */
            )
        {
            StringList list = null;

            if (ParserOps<string>.SplitList(
                    this, path, 0, Length.Invalid, true,
                    ref list, ref error) == ReturnCode.Ok)
            {
                Interpreter otherInterpreter = this;

                if (list.Count > 0)
                {
                    for (int index = 0; index < list.Count - 1; index++)
                    {
                        //
                        // BUGFIX: This loop should work correctly even when
                        //         the "Validate" lookup flag is disabled.
                        //
                        if (otherInterpreter == null)
                        {
                            error = "invalid interpreter";
                            return ReturnCode.Error;
                        }

                        if (otherInterpreter.GetChildInterpreter(
                                list[index], lookupFlags, ref otherInterpreter,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }
                    }

                    //
                    // NOTE: This will be the name of the new interpreter
                    //       to be created in the target interpreter if the
                    //       "create" flag is true; otherwise, it will simply
                    //       be the name of the innertmost nested interpreter.
                    //
                    name = list[list.Count - 1];

                    if (!create)
                    {
                        //
                        // NOTE: Return the last interpreter in the "chain";
                        //       this one will be validated (i.e. checked for
                        //       null) only if the caller has requested it.
                        //
                        return otherInterpreter.GetChildInterpreter(
                            name, lookupFlags, ref interpreter, ref error);
                    }
                }

                interpreter = otherInterpreter;
                return ReturnCode.Ok;
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new child interpreter at the specified path
        /// beneath this interpreter.
        /// </summary>
        /// <param name="path">
        /// The path at which to create the child interpreter.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the child interpreter.
        /// </param>
        /// <param name="ruleSet">
        /// The rule set to associate with the child interpreter, if any.
        /// </param>
        /// <param name="createFlags">
        /// Flags that control how the interpreter is created.
        /// </param>
        /// <param name="hostCreateFlags">
        /// Flags that control how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// Flags that control how the interpreter is initialized.
        /// </param>
        /// <param name="scriptFlags">
        /// Flags that control how scripts are located during initialization.
        /// </param>
        /// <param name="interpreterFlags">
        /// Flags that control miscellaneous interpreter behavior.
        /// </param>
        /// <param name="interpreterTestFlags">
        /// Flags that control interpreter test behavior.
        /// </param>
        /// <param name="pluginFlags">
        /// Flags that control how plugins are loaded.
        /// </param>
        /// <param name="findFlags">
        /// Flags that control how the native Tcl library is found.
        /// </param>
        /// <param name="loadFlags">
        /// Flags that control how the native Tcl library is loaded.
        /// </param>
        /// <param name="isolated">
        /// Non-zero to create the child interpreter in an isolated application
        /// domain.
        /// </param>
        /// <param name="security">
        /// Non-zero to enable security in the child interpreter.
        /// </param>
        /// <param name="alias">
        /// Non-zero to add an alias in this interpreter that refers to the
        /// child interpreter.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives an optional informational
        /// message; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode CreateChildInterpreter(
            string path,
            IClientData clientData,
            IRuleSet ruleSet,
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            InitializeFlags initializeFlags,
            ScriptFlags scriptFlags,
            InterpreterFlags interpreterFlags,
            InterpreterTestFlags interpreterTestFlags,
            PluginFlags pluginFlags,
#if NATIVE && TCL
            FindFlags findFlags,
            LoadFlags loadFlags,
#endif
            bool isolated,
            bool security,
            bool alias,
            ref Result result
            )
        {
            return CreateInterpreter(
                path, clientData, ruleSet, createFlags, hostCreateFlags,
                initializeFlags, scriptFlags, interpreterFlags,
                interpreterTestFlags, pluginFlags,
#if NATIVE && TCL
                findFlags, loadFlags,
#endif
                PeerType.Default, isolated, security, alias, ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new interpreter at the specified path,
        /// optionally as a peer, beneath this interpreter.
        /// </summary>
        /// <param name="path">
        /// The path at which to create the interpreter.
        /// </param>
        /// <param name="clientData">
        /// The client data to associate with the interpreter.
        /// </param>
        /// <param name="ruleSet">
        /// The rule set to associate with the interpreter, if any.
        /// </param>
        /// <param name="createFlags">
        /// Flags that control how the interpreter is created.
        /// </param>
        /// <param name="hostCreateFlags">
        /// Flags that control how the interpreter host is created.
        /// </param>
        /// <param name="initializeFlags">
        /// Flags that control how the interpreter is initialized.
        /// </param>
        /// <param name="scriptFlags">
        /// Flags that control how scripts are located during initialization.
        /// </param>
        /// <param name="interpreterFlags">
        /// Flags that control miscellaneous interpreter behavior.
        /// </param>
        /// <param name="interpreterTestFlags">
        /// Flags that control interpreter test behavior.
        /// </param>
        /// <param name="pluginFlags">
        /// Flags that control how plugins are loaded.
        /// </param>
        /// <param name="findFlags">
        /// Flags that control how the native Tcl library is found.
        /// </param>
        /// <param name="loadFlags">
        /// Flags that control how the native Tcl library is loaded.
        /// </param>
        /// <param name="peerType">
        /// The type of peer relationship to establish for the new interpreter.
        /// </param>
        /// <param name="isolated">
        /// Non-zero to create the interpreter in an isolated application
        /// domain.
        /// </param>
        /// <param name="security">
        /// Non-zero to enable security in the interpreter.
        /// </param>
        /// <param name="alias">
        /// Non-zero to add an alias in this interpreter that refers to the new
        /// interpreter.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives an optional informational
        /// message; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode CreateInterpreter(
            string path,
            IClientData clientData,
            IRuleSet ruleSet,
            CreateFlags createFlags,
            HostCreateFlags hostCreateFlags,
            InitializeFlags initializeFlags,
            ScriptFlags scriptFlags,
            InterpreterFlags interpreterFlags,
            InterpreterTestFlags interpreterTestFlags,
            PluginFlags pluginFlags,
#if NATIVE && TCL
            FindFlags findFlags,
            LoadFlags loadFlags,
#endif
            PeerType peerType,
            bool isolated,
            bool security,
            bool alias,
            ref Result result
            )
        {
            ReturnCode code = ReturnCode.Ok;
            Interpreter interpreter = null;
            string name = null;
            Result localResult;

            if (path != null)
            {
                localResult = null;

                code = GetNestedChildInterpreter(
                    path, LookupFlags.Interpreter,
                    true, ref interpreter, ref name,
                    ref localResult);

                if (code != ReturnCode.Ok)
                    result = localResult;
            }
            else
            {
                interpreter = this;
            }

            if (code == ReturnCode.Ok)
            {
                bool peer = FlagOps.HasFlags(peerType, PeerType.Normal, true);

#if APPDOMAINS && ISOLATED_INTERPRETERS
                string otherAppDomainName = null;
                AppDomain otherAppDomain = null;
                InterpreterHelper otherInterpreterHelper = null;
#endif
                Interpreter otherInterpreter = null;

                try
                {
                    bool locked = false;

                    try
                    {
                        interpreter.InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                        if (locked)
                        {
                            if (peer || interpreter.CanAddChild(ref result))
                            {
                                IList<string> arguments = null;

                                if (!peer || FlagOps.HasFlags(peerType, PeerType.NoArguments, true) ||
                                    (interpreter.PrivateGetArguments(
                                        ref arguments, false, false, ref result) == ReturnCode.Ok))
                                {
                                    CreateFlags noUseCreateFlags = peer ?
                                        CreateFlags.NoPeerUseMask : CreateFlags.NoChildUseMask;

                                    if (isolated)
                                    {
#if APPDOMAINS && ISOLATED_INTERPRETERS
                                        otherAppDomainName = FormatOps.Id(
                                            peer ? "peerInterpreter" : "childInterpreter",
                                            null, NextId());

                                        localResult = null;

                                        if (peer)
                                        {
                                            code = AppDomainOps.Create(
                                                interpreter, otherAppDomainName, null, null,
#if CAS_POLICY
                                                null,
#endif
                                                clientData, true,
                                                FlagOps.HasFlags(createFlags,
                                                    CreateFlags.VerifyCoreAssembly, true),
                                                !FlagOps.HasFlags(createFlags,
                                                    CreateFlags.NoUseEntryAssembly, true),
                                                FlagOps.HasFlags(createFlags,
                                                    CreateFlags.OptionalEntryAssembly, true),
                                                !FlagOps.HasFlags(createFlags,
                                                    CreateFlags.NoConfiguration, true),
                                                ref otherAppDomain, ref localResult);
                                        }
                                        else
                                        {
                                            code = interpreter.AddAppDomain(
                                                otherAppDomainName, null, null,
#if CAS_POLICY
                                                null,
#endif
                                                clientData, true,
                                                FlagOps.HasFlags(createFlags,
                                                    CreateFlags.VerifyCoreAssembly, true),
                                                !FlagOps.HasFlags(createFlags,
                                                    CreateFlags.NoUseEntryAssembly, true),
                                                FlagOps.HasFlags(createFlags,
                                                    CreateFlags.OptionalEntryAssembly, true),
                                                !FlagOps.HasFlags(createFlags,
                                                    CreateFlags.NoConfiguration, true),
                                                ref otherAppDomain, ref localResult);
                                        }

                                        if (code == ReturnCode.Ok)
                                        {
                                            localResult = null;

                                            otherInterpreterHelper = InterpreterHelper.Create(
                                                otherAppDomain, ruleSet, arguments, createFlags & ~noUseCreateFlags,
                                                hostCreateFlags, initializeFlags, scriptFlags, interpreterFlags,
                                                interpreterTestFlags, pluginFlags,
#if NATIVE && TCL
                                                findFlags, loadFlags,
#endif
                                                null, null, null, ref localResult);

                                            if (otherInterpreterHelper != null)
                                            {
                                                otherInterpreter = otherInterpreterHelper.Interpreter;

                                                if (otherInterpreter == null)
                                                {
                                                    if (localResult != null)
                                                        result = localResult;
                                                    else
                                                        result = "interpreter helper has no interpreter";

                                                    code = ReturnCode.Error;
                                                }
                                                else if (!peer &&
                                                    interpreter.HasChildLimit() &&
                                                    !otherInterpreter.HasChildLimit())
                                                {
                                                    otherInterpreter.InternalChildLimit = Limits.Forbidden;
                                                }
                                            }
                                            else
                                            {
                                                result = localResult;
                                                code = ReturnCode.Error;
                                            }
                                        }
                                        else
                                        {
                                            //
                                            // NOTE: If the AddAppDomain method does not return
                                            //       success, then an AppDomain was not added to
                                            //       the target interpreter and the AppDomain was
                                            //       already cleaned up; therefore, do not try to
                                            //       remove it below (i.e. reset the name of the
                                            //       new AppDomain to null here).
                                            //
                                            otherAppDomainName = null;
                                            result = localResult;
                                        }
#else
                                        result = "not implemented";
                                        code = ReturnCode.Error;
#endif
                                    }
                                    else
                                    {
                                        localResult = null;

                                        otherInterpreter = Create(
                                            ruleSet, arguments,
                                            createFlags & ~noUseCreateFlags,
                                            hostCreateFlags, initializeFlags,
                                            scriptFlags, interpreterFlags,
                                            interpreterTestFlags, pluginFlags,
#if NATIVE && TCL
                                            findFlags, loadFlags,
#endif
                                            ref localResult);

                                        if (otherInterpreter == null)
                                        {
                                            result = localResult;
                                            code = ReturnCode.Error;
                                        }
                                        else if (!peer &&
                                            interpreter.HasChildLimit() &&
                                            !otherInterpreter.HasChildLimit())
                                        {
                                            otherInterpreter.InternalChildLimit = Limits.Forbidden;
                                        }
                                    }
                                }
                                else
                                {
                                    code = ReturnCode.Error;
                                }
                            }
                            else
                            {
                                code = ReturnCode.Error;
                            }
                        }
                        else
                        {
                            result = "unable to acquire lock";
                            code = ReturnCode.Error;
                        }
                    }
                    finally
                    {
                        interpreter.InternalExitLock(ref locked); /* TRANSACTIONAL */
                    }

                    if ((code == ReturnCode.Ok) && security)
                    {
                        localResult = null;

                        code = ScriptOps.EnableOrDisableSecurity(
                            otherInterpreter, true, FlagOps.HasFlags(
                            createFlags, CreateFlags.NoVariablesMask,
                            false), ref localResult);

                        if (code != ReturnCode.Ok)
                            result = localResult;
                    }
                }
                catch (Exception e)
                {
                    result = e;
                    code = ReturnCode.Error;
                }
                finally
                {
                    if (code == ReturnCode.Ok)
                    {
                        string otherId = isolated ?
                            GlobalState.NextInterpreterId().ToString() :
                            otherInterpreter.PrivateId.ToString();

                        if (name == null)
                            name = otherId;

                        if (!peer)
                        {
                            if ((code == ReturnCode.Ok) && alias)
                            {
                                localResult = null;

                                code = AddInterpreterAlias(
                                    name, null, ObjectOptionType.None,
                                    ref localResult);

                                if (code != ReturnCode.Ok)
                                    result = localResult;
                            }

                            if (code == ReturnCode.Ok)
                            {
                                localResult = null;

                                code = interpreter.AddChildInterpreter(
                                    name, otherInterpreter, clientData,
                                    ref localResult);

                                if (code != ReturnCode.Ok)
                                    result = localResult;
                            }
                        }

                        if (code == ReturnCode.Ok)
                        {
                            if (peer)
                            {
                                if (FlagOps.HasFlags(peerType, PeerType.Object, true))
                                {
                                    //
                                    // NOTE: Return the created interpreter as an opaque
                                    //       object handle in the current interpreter.
                                    //
                                    ObjectOptionType objectOptionType =
                                        ObjectOptionType.Default;

                                    code = MarshalOps.FixupReturnValue(
                                        interpreter, null, ObjectFlags.Default,
                                        ObjectOps.GetInvokeOptions(objectOptionType), null,
                                        objectOptionType, null, otherInterpreter, true,
                                        FlagOps.HasFlags(peerType, PeerType.Alias, true),
                                        false, ref result);
                                }
                                else
                                {
                                    //
                                    // NOTE: Return the interpreter path if it is valid;
                                    //       otherwise, return the generated interpreter
                                    //       name.
                                    //
                                    result = (path != null) ? path : name;
                                }
                            }
                            else
                            {
                                //
                                // NOTE: Set the parent interpreter for the newly
                                //       created interpreter.
                                //
                                otherInterpreter.ParentInterpreter = interpreter;

                                //
                                // NOTE: We need a way to find this new interpreter
                                //       by the arbitrary name assigned to it by the
                                //       caller, not just the automatic Id; therefore,
                                //       store that now.
                                //
                                if (!SharedStringOps.SystemEquals(name, otherId))
                                    otherInterpreter.ChildName = name;

#if APPDOMAINS && ISOLATED_INTERPRETERS
                                //
                                // NOTE: Set the application domain name for the newly
                                //       created interpreter (in isolated mode only).
                                //
                                if (otherAppDomainName != null)
                                    otherInterpreter.ChildAppDomainName = otherAppDomainName;
#endif

                                //
                                // NOTE: Return the interpreter path if it is valid;
                                //       otherwise, return the generated interpreter
                                //       name.
                                //
                                result = (path != null) ? path : name;
                            }
                        }
                    }

                    ///////////////////////////////////////////////////////////////////////////////////

                    if (code != ReturnCode.Ok)
                    {
                        if (otherInterpreter != null)
                        {
                            ObjectOps.TryDisposeOrComplain<Interpreter>(
                                interpreter, ref otherInterpreter);

                            otherInterpreter = null;
                        }

                        ///////////////////////////////////////////////////////////////////////////////

#if APPDOMAINS && ISOLATED_INTERPRETERS
                        if (otherInterpreterHelper != null)
                        {
                            ObjectOps.TryDisposeOrComplain<InterpreterHelper>(
                                interpreter, ref otherInterpreterHelper);

                            otherInterpreterHelper = null;
                        }

                        ReturnCode removeCode = ReturnCode.Ok;
                        Result removeError = null;

                        if (peer)
                        {
                            if (otherAppDomain != null)
                            {
                                removeCode = AppDomainOps.Unload(
                                    otherAppDomainName, otherAppDomain,
                                    clientData, ref removeError);
                            }
                        }
                        else
                        {
                            if (otherAppDomainName != null)
                            {
                                removeCode = interpreter.RemoveAppDomain(
                                    otherAppDomainName, clientData,
                                    ref removeError);
                            }
                        }

                        if (removeCode != ReturnCode.Ok)
                        {
                            DebugOps.Complain(
                                interpreter, removeCode, removeError);
                        }
#endif
                    }
                }
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method deletes the child interpreter identified by the
        /// specified path.
        /// </summary>
        /// <param name="path">
        /// The path identifying the child interpreter to delete.
        /// </param>
        /// <param name="clientData">
        /// The client data associated with the deletion.
        /// </param>
        /// <param name="synchronous">
        /// Non-zero to perform the deletion synchronously.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode DeleteChildInterpreter(
            string path,
            IClientData clientData,
            bool synchronous,
            ref Result error
            )
        {
            Interpreter interpreter = null;
            string name = null;

            if (GetNestedChildInterpreter(
                    path, LookupFlags.Interpreter, true,
                    ref interpreter, ref name,
                    ref error) == ReturnCode.Ok)
            {
                return interpreter.RemoveChildInterpreter(
                    name, clientData, synchronous, ref error);
            }

            return ReturnCode.Error;
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Context Manager Support
        /// <summary>
        /// This method counts the interpreters associated with the current
        /// thread (or, when threading support is unavailable, the interpreters
        /// whose primary thread is the current one).
        /// </summary>
        /// <returns>
        /// The number of interpreters associated with the current thread.
        /// </returns>
        private int CountThreadInterpreters()
        {
#if THREADING
            try
            {
                IContextManager contextManager = PrivateContextManager;

                if (contextManager != null)
                    return contextManager.GetInterpreterContextCount();
            }
            catch
            {
                // do nothing.
            }
#else
            IEnumerable<Interpreter> interpreters = GlobalState.GetInterpreters();

            if (interpreters != null)
            {
                int count = 0;

                foreach (Interpreter interpreter in interpreters)
                {
                    if (interpreter == null)
                        continue;

                    if (interpreter.IsPrimarySystemThread())
                        count++;
                }

                return count;
            }
#endif

            return 0;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if THREADING
        //
        // WARNING: For use only by the following methods only:
        //
        //          1. MarshalOps.MaybeModifyReturnValueObjectFlags
        //
        /// <summary>
        /// Gets the context manager for this interpreter.
        /// </summary>
        internal IContextManager InternalContextManager
        {
            get { return PrivateContextManager; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use only by the following classes only:
        //
        //          1. Interpreter (this class)
        //
        //          Yes, this is funny.
        //
        /// <summary>
        /// Gets the context manager for this interpreter, incrementing the
        /// context manager access count.
        /// </summary>
        private IContextManager PrivateContextManager
        {
            get
            {
                /* IGNORED */
                Interlocked.Increment(ref contextManagerCount);

                return contextManager;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the counts of contexts seen before and after
        /// disposal for this interpreter.
        /// </summary>
        private void ResetDisposeContextCounts()
        {
            Interlocked.Exchange(
                ref preDisposeContextCount, 0);

            Interlocked.Exchange(
                ref postDisposeContextCount, 0);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method queries the counts of contexts seen before and after
        /// disposal for this interpreter.
        /// </summary>
        /// <param name="preDisposeContextCount">
        /// Upon return, this parameter receives the number of contexts present
        /// before disposal.
        /// </param>
        /// <param name="postDisposeContextCount">
        /// Upon return, this parameter receives the number of contexts present
        /// after disposal.
        /// </param>
        internal void QueryDisposeContextCounts(
            ref long preDisposeContextCount,
            ref long postDisposeContextCount
            )
        {
            preDisposeContextCount = Interlocked.CompareExchange(
                ref this.preDisposeContextCount, 0, 0);

            postDisposeContextCount = Interlocked.CompareExchange(
                ref this.postDisposeContextCount, 0, 0);
        }
#endif
        #endregion

