        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
#if THREADING
        /// <summary>
        /// This method obtains the engine context associated with the current
        /// thread for this interpreter, creating one if necessary.
        /// </summary>
        /// <param name="error">
        /// Upon failure, receives an error message describing why the engine
        /// context could not be obtained.
        /// </param>
        /// <returns>
        /// The engine context for the current thread, or null if it could not
        /// be obtained.
        /// </returns>
        private IEngineContext GetEngineContext(
            ref Result error /* out */
            )
        {
            IContextManager contextManager = PrivateContextManager;

            if (contextManager == null)
            {
                error = "context manager unavailable";
                return null;
            }

            return contextManager.GetEngineContext(true, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method obtains the engine context associated with the current
        /// thread for this interpreter, creating one if necessary.
        /// </summary>
        /// <returns>
        /// The engine context for the current thread, or null if it could not
        /// be obtained.
        /// </returns>
        private IEngineContext GetEngineContext()
        {
            IContextManager contextManager = PrivateContextManager;

            return (contextManager != null) ?
                contextManager.GetEngineContext(true) : null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method obtains the engine context associated with the current
        /// thread for this interpreter without creating one if it does not
        /// already exist.
        /// </summary>
        /// <returns>
        /// The existing engine context for the current thread, or null if none
        /// exists.
        /// </returns>
        internal IEngineContext GetEngineContextNoCreate()
        {
            IContextManager contextManager = PrivateContextManager;

            return (contextManager != null) ?
                contextManager.GetEngineContext(false) : null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether an engine context already exists for
        /// the current thread for this interpreter.
        /// </summary>
        /// <returns>
        /// True if an engine context already exists for the current thread;
        /// otherwise, false.
        /// </returns>
        private bool HaveEngineContext()
        {
            return GetEngineContextNoCreate() != null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether any engine context is available,
        /// considering the supplied engine context, any existing engine context
        /// for the current thread, and optionally forcing the creation of one.
        /// </summary>
        /// <param name="engineContext">
        /// The candidate engine context to consider first.  This parameter may
        /// be null.
        /// </param>
        /// <param name="cancelFlags">
        /// The flags controlling the behavior of this method, including whether
        /// to force the creation of an engine context.
        /// </param>
        /// <returns>
        /// True if an engine context is available; otherwise, false.
        /// </returns>
        private bool HaveAnyEngineContext(
            IEngineContext engineContext,
            CancelFlags cancelFlags
            )
        {
            if (engineContext != null)
                return true;

            if (HaveEngineContext())
                return true;

            if (FlagOps.HasFlags(
                    cancelFlags, CancelFlags.ForceContext, true) &&
                (GetEngineContext() /* CREATE */ != null))
            {
                return true;
            }

            return false;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a client data object that carries the
        /// information needed to manage a script timeout for this interpreter.
        /// </summary>
        /// <param name="data">
        /// The extra, opaque client data to associate with the timeout.  This
        /// parameter may be null.
        /// </param>
        /// <param name="timeoutFlags">
        /// The flags controlling the behavior of the script timeout.
        /// </param>
        /// <param name="cancelFlags">
        /// The flags controlling how the script is canceled when the timeout
        /// elapses, or null to use the default behavior.
        /// </param>
        /// <param name="timeout">
        /// The timeout, in milliseconds.
        /// </param>
        /// <returns>
        /// The newly created script timeout client data object.
        /// </returns>
        internal ScriptTimeoutClientData CreateScriptTimeoutClientData(
            object data,
            TimeoutFlags timeoutFlags,
            CancelFlags? cancelFlags,
            int timeout
            )
        {
#if THREADING
            IEngineContext engineContext = GetEngineContextNoCreate();
#endif

            return new ScriptTimeoutClientData(
                data, this,
#if THREADING
                engineContext,
#endif
                timeoutFlags, cancelFlags, timeout);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets a value indicating whether this interpreter is currently busy
        /// evaluating a script.
        /// </summary>
        internal bool InternalIsBusy
        {
            get
            {
#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    return context.Levels > 0;
                else
                    return false;
#else
                // lock (syncRoot)
                {
                    return levels > 0;
                }
#endif
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// Gets a value indicating whether this interpreter is currently busy
        /// evaluating a script at the global level.
        /// </summary>
        internal bool InternalIsGlobalBusy
        {
            get
            {
#if THREADING
                if ((Interlocked.CompareExchange(ref globalLevels, 0, 0) > 0) ||
                    (Interlocked.CompareExchange(ref globalScriptLevels, 0, 0) > 0))
                {
                    return true;
                }

                return false;
#else
                return InternalIsBusy;
#endif
            }
        }

