                    return contextClientData;
                }
#endif
            }
            set
            {
#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    context.ClientData = value;
#else
                lock (syncRoot)
                {
                    contextClientData = value;
                }
#endif
            }
        }

