#if THREADING
        /// <summary>
        /// This method temporarily suppresses global script cancellation for
        /// the current thread for this interpreter.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// Upon return, receives the engine flags that were in effect before
        /// global cancellation was suppressed, for later restoration.
        /// </param>
        private void BeginNoGlobalCancel(
            out EngineFlags savedEngineFlags
            )
        {
            savedEngineFlags = ContextEngineFlags;
            ContextEngineFlags |= EngineFlags.NoGlobalCancel;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores global script cancellation behavior for the
        /// current thread for this interpreter, undoing a prior call to
        /// suppress it.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// On input, the engine flags previously saved when global cancellation
        /// was suppressed; upon return, this is reset to no flags.
        /// </param>
        private void EndNoGlobalCancel(
            ref EngineFlags savedEngineFlags
            )
        {
            EngineFlags disableEngineFlags = EngineFlags.None;

            if (!EngineFlagOps.HasNoGlobalCancel(savedEngineFlags))
                disableEngineFlags |= EngineFlags.NoGlobalCancel;

            ContextEngineFlags &= ~disableEngineFlags;
            savedEngineFlags = EngineFlags.None;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the beginning of execution that originates outside
        /// the engine (for example, from native or host code) for this
        /// interpreter.
        /// </summary>
        /// <returns>
        /// The saved engine flags that should later be passed to
        /// <c>EndExternalExecution</c> to restore the prior state.
        /// </returns>
        internal EngineFlags BeginExternalExecution()
        {
#if THREADING
            IEngineContext context = GetEngineContext();

            if (context != null)
                return context.BeginExternalExecution();
            else
                return EngineFlags.None;
#else
            EnterLevel();

            engineFlags |= EngineFlags.ExternalExecution;
            return Engine.AddStackCheckFlags(ref engineFlags);
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the end of execution that originated outside the
        /// engine for this interpreter, restoring the prior engine flags.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// The engine flags previously returned by <c>BeginExternalExecution</c>.
        /// </param>
        /// <returns>
        /// The resulting script evaluation nesting level after exiting the
        /// external execution.
        /// </returns>
        internal int EndExternalExecution(
            EngineFlags savedEngineFlags
            )
        {
#if THREADING
            IEngineContext context = GetEngineContext();

            if (context != null)
                return context.EndExternalExecution(savedEngineFlags);
            else
                return 0;
#else
            Engine.RemoveStackCheckFlags(savedEngineFlags, ref engineFlags);
            engineFlags &= ~EngineFlags.ExternalExecution;

            return ExitLevel();
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the end of execution that originated outside the
        /// engine for this interpreter and, when the outermost level is
        /// reached, performs any necessary namespace cleanup.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// The engine flags previously returned by <c>BeginExternalExecution</c>.
        /// </param>
        /// <returns>
        /// The resulting script evaluation nesting level after exiting the
        /// external execution.
        /// </returns>
        internal int EndAndCleanupExternalExecution( /* EXIT POINT */
            EngineFlags savedEngineFlags
            )
        {
            int levels = EndExternalExecution(savedEngineFlags);

            if (levels == 0)
            {
                /* IGNORED */
                Engine.CleanupNamespacesOrComplain(this);
            }

            return levels;
        }

