        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether a result trace should be written,
        /// based on the supplied interpreter flags and disposed state.
        /// </summary>
        /// <param name="interpreterFlags">
        /// The interpreter flags to consult, or null if none are available.
        /// </param>
        /// <param name="disposed">
        /// Non-zero if the interpreter has been disposed, zero if it has not,
        /// or null if this is unknown.
        /// </param>
        /// <param name="priority">
        /// On input, the proposed trace priority; upon return, this may be
        /// raised when the interpreter has been disposed.
        /// </param>
        /// <returns>
        /// True if a result trace should be written; otherwise, false.
        /// </returns>
        private static bool ShouldTraceResult(
            InterpreterFlags? interpreterFlags, /* in: OPTIONAL */
            bool? disposed,                     /* in: OPTIONAL */
            ref TracePriority priority          /* in, out */
            )
        {
            bool result = false;

            //
            // NOTE: *RULE #1* If the associated trace flag has been
            //       set explicitly, always write the trace.
            //
            if ((interpreterFlags != null) &&
                HasTraceResult((InterpreterFlags)interpreterFlags))
            {
                result = true;
            }

            //
            // NOTE: *RULE #2* If the interpreter has been disposed,
            //       write the trace.
            //
            if ((disposed != null) && (bool)disposed)
            {
                priority = TracePriority.EngineError;
                result = true;
            }

            return result;
        }

