#if PREVIOUS_RESULT
        /// <summary>
        /// This method gets the result of the previous script evaluation for
        /// the specified interpreter in a thread-safe manner.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to query.  This parameter may be null.
        /// </param>
        /// <returns>
        /// The result of the previous script evaluation, or null if it is
        /// unavailable.
        /// </returns>
        internal static Result GetPreviousResult(
            Interpreter interpreter
            )
        {
            if (interpreter == null)
                return null;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return null;

                return interpreter.PreviousResult;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the result of the previous script evaluation for
        /// the specified interpreter in a thread-safe manner.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to modify.  This parameter may be null.
        /// </param>
        /// <param name="previousResult">
        /// The result to record as the previous script evaluation result.  This
        /// parameter may be null.
        /// </param>
        internal static void SetPreviousResult(
            Interpreter interpreter,
            Result previousResult
            )
        {
            if (interpreter == null)
                return;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return;

                interpreter.PreviousResult = previousResult;
            }
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to reuse the most recently recorded error for
        /// this interpreter as the operation result.
        /// </summary>
        /// <param name="result">
        /// Upon success, receives the previously recorded last error; upon
        /// failure, receives an error message indicating that no error was
        /// recorded.
        /// </param>
        /// <returns>
        /// True if a recorded last error was available and used; otherwise,
        /// false.
        /// </returns>
        internal bool TryUseLastError(
            ref Result result /* out */
            ) /* THREAD-SAFE */
        {
            Result lastError = LastError; /* CONTEXT */

            if (lastError != null)
            {
                result = lastError; /* i.e. re-throw */
                return true;
            }
            else
            {
                //
                // TODO: There is no last error available;
                //       therefore, do not permit it to be
                //       used.  Perhaps there should be a
                //       way to allow this?  Currently, a
                //       null -OR- empty error message is
                //       forbidden as it makes things much
                //       harder to diagnose.
                //
                result = "no error was recorded";
                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method is for test-suite use only.
        //          Please do not remove or modify it.
        //
        /// <summary>
        /// This method clears the most recently recorded error for this
        /// interpreter, discarding any prior value.  This method is for
        /// test-suite use only.
        /// </summary>
        /// <returns>
        /// True if a recorded last error was present and has been cleared;
        /// otherwise, false.
        /// </returns>
        private bool MaybeResetLastError()
        {
            Result result = null; /* NOT USED */

            return MaybeResetLastError(ref result);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method is for test-suite use only.
        //          Please do not remove or modify it.
        //
        /// <summary>
        /// This method clears the most recently recorded error for this
        /// interpreter, optionally returning its prior value.  This method is
        /// for test-suite use only.
        /// </summary>
        /// <param name="result">
        /// Upon return, receives the previously recorded last error when one was
        /// present; otherwise, it is left unchanged.
        /// </param>
        /// <returns>
        /// True if a recorded last error was present and has been cleared;
        /// otherwise, false.
        /// </returns>
        private bool MaybeResetLastError(
            ref Result result /* out */
            )
        {
            Result lastError = LastError; /* CONTEXT */

            if (lastError != null)
                result = lastError; /* i.e. get error */

            LastError = null;
            return (lastError != null);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method records the specified result as the most recent error
        /// for this interpreter when it differs from the currently recorded
        /// last error.
        /// </summary>
        /// <param name="result">
        /// The result to record as the last error.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the recorded last error was updated; otherwise, false.
        /// </returns>
        internal bool MaybeSetLastError(
            Result result /* in */
            )
        {
            Result lastError = LastError; /* CONTEXT */

            if (lastError != null)
            {
                if (!Object.ReferenceEquals(result, lastError))
                {
                    LastError = result; /* CONTEXT */
                    return true;
                }
            }
            else if (result != null)
            {
                LastError = result; /* CONTEXT */
                return true;
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method sets the previous process identifier for the specified
        /// interpreter in a thread-safe manner.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to modify.  This parameter may be null.
        /// </param>
        /// <param name="processId">
        /// The process identifier to record as the previous process identifier.
        /// </param>
        internal static void SetPreviousProcessId(
            Interpreter interpreter,
            long processId
            )
        {
            if (interpreter == null)
                return;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return;

                interpreter.PreviousProcessId = processId;
            }
        }
        #endregion

