        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the beginning of a nested sub-expression for this
        /// interpreter by snapshotting and updating the entry expression level.
        /// </summary>
        /// <param name="savedExpressionLevels">
        /// Upon success, receives the entry expression level that was in effect
        /// before this call, for later restoration.
        /// </param>
        /// <returns>
        /// True if the sub-expression was pushed; otherwise, false.
        /// </returns>
        internal bool PushSubExpression(
            ref int savedExpressionLevels /* out */
            )
        {
#if THREADING
            IEngineContext context = GetEngineContext();

            if (context == null)
                return false;

            savedExpressionLevels = context.EntryExpressionLevels;
            context.EntryExpressionLevels = context.ExpressionLevels;
#else
            savedExpressionLevels = entryExpressionLevels;
            entryExpressionLevels = expressionLevels;
#endif

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method marks the end of a nested sub-expression for this
        /// interpreter by restoring the previously saved entry expression level.
        /// </summary>
        /// <param name="savedExpressionLevels">
        /// On input, the entry expression level previously saved by
        /// <c>PushSubExpression</c>; upon return, this is reset to zero.
        /// </param>
        /// <returns>
        /// True if the sub-expression was popped; otherwise, false.
        /// </returns>
        internal bool PopSubExpression(
            ref int savedExpressionLevels /* in, out */
            )
        {
#if THREADING
            IEngineContext context = GetEngineContext();

            if (context == null)
                return false;

            context.EntryExpressionLevels = savedExpressionLevels;
            savedExpressionLevels = 0;
#else
            entryExpressionLevels = savedExpressionLevels;
            savedExpressionLevels = 0;
#endif

            return true;
        }

