        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Enter / Exit Engine Levels
        /// <summary>
        /// This method increments the overall (engine) nesting level for the
        /// current thread for this interpreter, also entering the global
        /// nesting level when threading support is enabled.
        /// </summary>
        /// <returns>
        /// The resulting engine nesting level.
        /// </returns>
        internal int EnterEngineLevel()
        {
#if THREADING
            /* IGNORED */
            EnterGlobalLevel();
#endif

            return EnterLevel();
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method decrements the overall (engine) nesting level for the
        /// current thread for this interpreter, also exiting the global
        /// nesting level when threading support is enabled.
        /// </summary>
        /// <returns>
        /// The resulting engine nesting level.
        /// </returns>
        internal int ExitEngineLevel()
        {
#if THREADING
            /* IGNORED */
            ExitGlobalLevel();
#endif

            return ExitLevel();
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method increments the script nesting level used by the engine
        /// for the current thread for this interpreter, also entering the
        /// global script nesting level when threading support is enabled, and
        /// updates the maximum script nesting level seen so far.
        /// </summary>
        /// <returns>
        /// The resulting script nesting level.
        /// </returns>
        internal int EnterEngineScriptLevel()
        {
#if THREADING
            /* IGNORED */
            EnterGlobalScriptLevel();
#endif

            int levels = EnterScriptLevel();

            if (levels > MaximumScriptLevels)
                MaximumScriptLevels = levels;

            return levels;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method decrements the script nesting level used by the engine
        /// for the current thread for this interpreter, also exiting the
        /// global script nesting level when threading support is enabled.
        /// </summary>
        /// <returns>
        /// The resulting script nesting level.
        /// </returns>
        internal int ExitEngineScriptLevel()
        {
#if THREADING
            /* IGNORED */
            ExitGlobalScriptLevel();
#endif

            return ExitScriptLevel();
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Interpreter Readiness
        /// <summary>
        /// This method determines whether this interpreter currently has any
        /// active evaluation, parser, or expression nesting levels.
        /// </summary>
        /// <returns>
        /// True if any internal, parser, or expression nesting levels are
        /// active; otherwise, false.
        /// </returns>
        internal bool HasReadyLevels()
        {
            if (InternalLevels > 0) /* EXEMPT */
                return true;

            if (ParserLevels > 0)
                return true;

            if (ExpressionLevels > 0)
                return true;

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is already held.
        //
        /// <summary>
        /// This method queries the current evaluation, parser, and expression
        /// nesting levels, along with their maximum observed values, for the
        /// current thread for this interpreter.  This method assumes the
        /// interpreter lock is already held.
        /// </summary>
        /// <param name="levels">
        /// Upon success, this parameter receives the current evaluation
        /// nesting level.
        /// </param>
        /// <param name="maximumLevels">
        /// Upon success, this parameter receives the maximum evaluation
        /// nesting level seen so far.
        /// </param>
        /// <param name="parserLevels">
        /// Upon success, this parameter receives the current parser nesting
        /// level.
        /// </param>
        /// <param name="maximumParserLevels">
        /// Upon success, this parameter receives the maximum parser nesting
        /// level seen so far.
        /// </param>
        /// <param name="expressionLevels">
        /// Upon success, this parameter receives the current expression
        /// nesting level.
        /// </param>
        /// <param name="maximumExpressionLevels">
        /// Upon success, this parameter receives the maximum expression
        /// nesting level seen so far.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message describing
        /// the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error
        /// return code.
        /// </returns>
        private ReturnCode GetReadyLevels(
            ref int levels,
            ref int maximumLevels,
            ref int parserLevels,
            ref int maximumParserLevels,
            ref int expressionLevels,
            ref int maximumExpressionLevels,
            ref Result error
            )
        {
#if THREADING
            IEngineContext context = GetEngineContext(ref error);

            if (context != null)
            {
                levels = context.Levels;
                maximumLevels = context.MaximumLevels;

                if (levels > maximumLevels)
                    context.MaximumLevels = maximumLevels = levels;

                parserLevels = context.ParserLevels;
                maximumParserLevels = context.MaximumParserLevels;

                if (parserLevels > maximumParserLevels)
                    context.MaximumParserLevels = maximumParserLevels = parserLevels;

                expressionLevels = context.ExpressionLevels;
                maximumExpressionLevels = context.MaximumExpressionLevels;

                if (expressionLevels > maximumExpressionLevels)
                    context.MaximumExpressionLevels = maximumExpressionLevels = expressionLevels;

                return ReturnCode.Ok;
            }

            return ReturnCode.Error;
#else
            levels = this.levels;
            maximumLevels = this.maximumLevels;

            if (levels > maximumLevels)
                this.MaximumLevels = maximumLevels = levels;

            parserLevels = this.parserLevels;
            maximumParserLevels = this.maximumParserLevels;

            if (parserLevels > maximumParserLevels)
                this.MaximumParserLevels = maximumParserLevels = parserLevels;

            expressionLevels = this.expressionLevels;
            maximumExpressionLevels = this.maximumExpressionLevels;

            if (expressionLevels > maximumExpressionLevels)
                this.MaximumExpressionLevels = maximumExpressionLevels = expressionLevels;

            return ReturnCode.Ok;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks whether the specified interpreter is ready to
        /// evaluate a script, using the default readiness timeout.  This
        /// overload is intended for external use only.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to check for readiness.  This parameter may be
        /// null.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message describing
        /// why the interpreter is not ready.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the interpreter is ready;
        /// otherwise, an error return code.
        /// </returns>
        public static ReturnCode Ready( /* FOR EXTERNAL USE ONLY. */
            Interpreter interpreter,
            ref Result error
            ) /* THREAD-SAFE */
        {
            return Ready(interpreter, null, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method checks whether the specified interpreter is ready to
        /// evaluate a script, using the specified readiness timeout.  This
        /// overload is intended for external use only.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter to check for readiness.  This parameter may be
        /// null.
        /// </param>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait when acquiring the
        /// interpreter lock, or null to use the default timeout.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message describing
        /// why the interpreter is not ready.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the interpreter is ready;
        /// otherwise, an error return code.
        /// </returns>
        public static ReturnCode Ready( /* FOR EXTERNAL USE ONLY. */
            Interpreter interpreter,
            int? timeout,
            ref Result error
            ) /* THREAD-SAFE */
        {
            int localTimeout = GetEffectiveReadyTimeout(interpreter, timeout);

            ReadyFlags flags = ReadyFlags.ViaPublic;

            if (!FlagOps.HasFlags(flags, ReadyFlags.Disabled, true) &&
                !FlagOps.HasFlags(flags, ReadyFlags.NoFlags, true))
            {
                flags |= TryGetReadyFlags(interpreter, localTimeout, true);
            }

            bool timedOut;

            return Ready(
                interpreter, localTimeout, flags, out timedOut, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if NATIVE && TCL
        /// <summary>
