        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Engine Flags Support
        /// <summary>
        /// This method clears the error-related engine flags from the engine
        /// context for the current thread.  This method is for use by the
        /// <c>ResetForEngine</c> method only.
        /// </summary>
        private void ResetContextErrorFlags()
        {
            //
            // WARNING: For use by the ResetForEngine method only.
            //
            ContextEngineFlags &= ~EngineFlags.ErrorMask;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether an error is currently in progress
        /// based on the engine flags for the current thread.
        /// </summary>
        /// <returns>
        /// True if an error is currently in progress; otherwise, false.
        /// </returns>
        private bool HasErrorInProgress()
        {
            //
            // WARNING: Possibly per-thread engine flags used here,
            //          MUST use property, not field.
            //
            return EngineFlagOps.HasErrorInProgress(EngineFlags);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether argument caching is currently
        /// disabled based on the engine flags for the current thread.
        /// </summary>
        /// <returns>
        /// True if argument caching is disabled; otherwise, false.
        /// </returns>
        internal bool HasNoCacheArgument()
        {
#if ARGUMENT_CACHE
            //
            // WARNING: Possibly per-thread engine flags used here,
            //          MUST use property, not field.
            //
            return EngineFlagOps.HasNoCacheArgument(EngineFlags);
#else
            return false;
#endif
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

#if ARGUMENT_CACHE || PARSE_CACHE
        //
        // NOTE: This method is designed to disable all caching by the engine
        //       (i.e. not the parser) for the current thread only, saving the
        //       preexisting (per-thread) engine flags for later use with the
        //       EndProcedureBodyNoCaching method (below).
        //
        /// <summary>
        /// This method disables all engine-level caching (i.e. not parser
        /// caching) for the current thread only, saving the preexisting
        /// (per-thread) engine flags for later use with the
        /// <c>EndProcedureBodyNoCaching</c> method.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// Upon return, this parameter receives the engine flags that were in
        /// effect prior to disabling caching.
        /// </param>
        internal void BeginProcedureBodyNoCaching(
            ref EngineFlags savedEngineFlags
            )
        {
            EngineFlags enableEngineFlags = EngineFlags.None;

#if PARSE_CACHE
            enableEngineFlags |= EngineFlags.NoCacheParseState;
#endif

#if ARGUMENT_CACHE
            enableEngineFlags |= EngineFlags.NoCacheArgument;
#endif

            savedEngineFlags = ContextEngineFlags;
            ContextEngineFlags |= enableEngineFlags;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method is designed to restore all caching by the engine
        //       (i.e. not the parser) for the current thread only, restoring
        //       the previously saved (per-thread) engine flags.
        //
        /// <summary>
        /// This method restores all engine-level caching (i.e. not parser
        /// caching) for the current thread only, restoring the previously
        /// saved (per-thread) engine flags.
        /// </summary>
        /// <param name="savedEngineFlags">
        /// On input, the previously saved engine flags to restore; upon
        /// return, this parameter is reset to <see cref="EngineFlags.None" />.
        /// </param>
        internal void EndProcedureBodyNoCaching(
            ref EngineFlags savedEngineFlags
            )
        {
            EngineFlags disableEngineFlags = EngineFlags.None;

#if PARSE_CACHE
            if (!EngineFlagOps.HasNoCacheParseState(savedEngineFlags))
                disableEngineFlags |= EngineFlags.NoCacheParseState;
#endif

#if ARGUMENT_CACHE
            if (!EngineFlagOps.HasNoCacheArgument(savedEngineFlags))
                disableEngineFlags |= EngineFlags.NoCacheArgument;
#endif

            ContextEngineFlags &= ~disableEngineFlags;
            savedEngineFlags = EngineFlags.None;
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Array Searches Support
        //
        // NOTE: The actual ArraySearches property is located with
        //       the engine context members, also within this file.
        //
        /// <summary>
        /// This method removes all pending array searches associated with the
        /// specified variable.
        /// </summary>
        /// <param name="variable">
        /// The variable whose associated array searches are to be removed.
        /// This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the array searches collection was present and processed;
        /// otherwise, false.
        /// </returns>
        private bool CleanupArraySearches(IVariable variable)
        {
            int removed = 0;

            return CleanupArraySearches(variable, ref removed);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes all pending array searches associated with the
        /// specified variable, also reporting how many were removed.
        /// </summary>
        /// <param name="variable">
        /// The variable whose associated array searches are to be removed.
        /// This parameter may be null.
        /// </param>
        /// <param name="removed">
        /// This parameter is incremented by the number of array searches that
        /// were removed.
        /// </param>
        /// <returns>
        /// True if the array searches collection was present and processed;
        /// otherwise, false.
        /// </returns>
        private bool CleanupArraySearches(
            IVariable variable,
            ref int removed
            )
        {
            if (variable != null)
            {
                ArraySearchDictionary arraySearches = ArraySearches;

                if (arraySearches != null)
                {
                    //
                    // NOTE: Cleanup, PASS #1, collect the list of keys we need to remove
                    //       from the objects collection in the containing interpreter.
                    //
                    StringList keys = new StringList();

                    foreach (ArraySearchPair pair in arraySearches)
                    {
                        ArraySearch arraySearch = pair.Value;

                        if ((arraySearch != null) &&
                            Object.ReferenceEquals(arraySearch.Variable, variable))
                        {
                            keys.Add(pair.Key);
                        }
                    }

                    //
                    // NOTE: Cleanup, PASS #2, remove all the objects we found from PASS
                    //       #1 (above).
                    //
                    foreach (string key in keys)
                        LogicOps.Y(arraySearches.Remove(key), removed++);

                    return true;
                }
            }

            return false;
        }
        #endregion

