        #region Private
#if SHELL
        /// <summary>
        /// This method determines whether the interactive loop running in the
        /// specified application domain and on the specified thread is
        /// currently paused.
        /// </summary>
        /// <param name="appDomainId">
        /// The identifier of the application domain hosting the interactive
        /// loop.
        /// </param>
        /// <param name="threadId">
        /// The identifier of the thread running the interactive loop.
        /// </param>
        /// <param name="done">
        /// Upon success, this parameter is set to non-zero if the interactive
        /// loop is not paused (i.e. it may proceed).
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message describing
        /// the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error
        /// return code.
        /// </returns>
        internal ReturnCode IsPausedInteractiveLoop(
            int appDomainId,
            long threadId,
            ref bool done,
            ref Result error
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (pausedInteractiveLoops == null)
                    {
                        error = "paused interactive loops unavailable";
                        return ReturnCode.Error;
                    }

                    long localKey = ConversionOps.MakeLong(
                        appDomainId, threadId);

                    long localValue;

                    if (pausedInteractiveLoops.TryGetValue(
                            localKey, out localValue))
                    {
                        done = localValue <= 0;
                    }
                    else
                    {
                        done = true;
                    }

                    return ReturnCode.Ok;
                }
                else
                {
                    error = "unable to acquire lock";
                    return ReturnCode.Error;
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method builds a list describing the paused state of all
        /// tracked interactive loops.
        /// </summary>
        /// <param name="list">
        /// Upon success, this parameter receives the list of paused
        /// interactive loop descriptions.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message describing
        /// the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error
        /// return code.
        /// </returns>
        internal ReturnCode ListPausedInteractiveLoops(
            ref StringList list,
            ref Result error
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (pausedInteractiveLoops == null)
                    {
                        error = "paused interactive loops unavailable";
                        return ReturnCode.Error;
                    }

                    StringList localList = new StringList();

                    foreach (LongPair pair in pausedInteractiveLoops)
                    {
                        long appDomainId; /* int */
                        long threadId;

                        ConversionOps.UnmakeLong(
                            pair.Key, out appDomainId, out threadId);

                        long value = pair.Value;

                        localList.Add(String.Format(
                            "{0}/{1}: {2} {3}", appDomainId, threadId,
                            value, (value > 0) ? "PAUSED" : "UNPAUSED"));
                    }

                    list = localList;
                    return ReturnCode.Ok;
                }
                else
                {
                    error = "unable to acquire lock";
                    return ReturnCode.Error;
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method increments the pause count for the interactive loop
        /// running in the specified application domain and on the specified
        /// thread.
        /// </summary>
        /// <param name="appDomainId">
        /// The identifier of the application domain hosting the interactive
        /// loop.
        /// </param>
        /// <param name="threadId">
        /// The identifier of the thread running the interactive loop.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives a message describing the new
        /// paused state; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error
        /// return code.
        /// </returns>
        internal ReturnCode PauseInteractiveLoop(
            int appDomainId,
            long threadId,
            ref Result result
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (pausedInteractiveLoops == null)
                    {
                        result = "paused interactive loops unavailable";
                        return ReturnCode.Error;
                    }

                    long localKey = ConversionOps.MakeLong(
                        appDomainId, threadId);

                    long localValue;

                    if (!pausedInteractiveLoops.TryGetValue(
                            localKey, out localValue))
                    {
                        localValue = 0;
                    }

                    pausedInteractiveLoops[localKey] = ++localValue;

                    result = String.Format(
                        "interactive loop {0}/{1} paused: {2}",
                        appDomainId, threadId, localValue);

                    return ReturnCode.Ok;
                }
                else
                {
                    result = "unable to acquire lock";
                    return ReturnCode.Error;
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method decrements the pause count for, or removes, the
        /// interactive loop running in the specified application domain and on
        /// the specified thread.
        /// </summary>
        /// <param name="appDomainId">
        /// The identifier of the application domain hosting the interactive
        /// loop.
        /// </param>
        /// <param name="threadId">
        /// The identifier of the thread running the interactive loop.
        /// </param>
        /// <param name="errorOnNotFound">
        /// Non-zero to return an error if no matching paused interactive loop
        /// is found.
        /// </param>
        /// <param name="remove">
        /// Non-zero to remove the tracking entry for the interactive loop
        /// instead of decrementing its pause count.
        /// </param>
        /// <param name="force">
        /// Non-zero to force removal of the tracking entry even when its
        /// pause count is still positive.
        /// </param>
        /// <param name="sleep">
        /// Non-zero to wait briefly before returning.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives a message describing the new
        /// paused state; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error
        /// return code.
        /// </returns>
        internal ReturnCode UnpauseInteractiveLoop(
            int appDomainId,
            long threadId,
            bool errorOnNotFound,
            bool remove,
            bool force,
            bool sleep,
            ref Result result
            )
        {
            bool locked = false;

            try
            {
                InternalHardTryLock(ref locked); /* TRANSACTIONAL */

                if (locked)
                {
                    if (pausedInteractiveLoops == null)
                    {
                        result = "paused interactive loops unavailable";
                        return ReturnCode.Error;
                    }

                    long localKey = ConversionOps.MakeLong(
                        appDomainId, threadId);

                    long localValue;

                    if (!pausedInteractiveLoops.TryGetValue(
                            localKey, out localValue))
                    {
                        if (errorOnNotFound)
                        {
                            result = String.Format(
                                "interactive loop {0}/{1} already unpaused",
                                appDomainId, threadId);

                            return ReturnCode.Error;
                        }
                        else
                        {
                            return ReturnCode.Ok;
                        }
                    }

                    if (remove)
                    {
                        if ((force || (localValue <= 0)) &&
                            !pausedInteractiveLoops.Remove(localKey))
                        {
                            result = String.Format(
                                "interactive loop {0}/{1} not unpaused",
                                appDomainId, threadId);

                            return ReturnCode.Error;
                        }
                    }
                    else
                    {
                        pausedInteractiveLoops[localKey] = --localValue;
                    }

                    if (sleep)
                    {
                        if (EventOps.Wait(
                                this, null, ShellOps.PauseMicroseconds,
                                null, true, false, false, false, false,
                                ref result) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }
                    }

                    result = String.Format(
                        "interactive loop {0}/{1} {2}: {3}",
                        appDomainId, threadId, remove ? "removed" :
                        "unpaused", localValue);

                    return ReturnCode.Ok;
                }
                else
                {
                    result = "unable to acquire lock";
                    return ReturnCode.Error;
                }
            }
            finally
            {
                InternalExitLock(ref locked); /* TRANSACTIONAL */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method installs the specified update data for the current
        /// thread, saving the previous update data for later restoration.
        /// </summary>
        /// <param name="newUpdateData">
        /// The update data to install.  This parameter may be null.
        /// </param>
        /// <param name="savedUpdateData">
        /// Upon return, this parameter receives the previously installed
        /// update data.
        /// </param>
        internal void PushUpdateData(
            IUpdateData newUpdateData,
            ref IUpdateData savedUpdateData
            )
        {
            //
            // NOTE: This lock is not necessary when we are compiled with
            //       the THREADING option enabled because UpdateData is a
            //       per-thread value in that case.
            //
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                savedUpdateData = UpdateData;
                UpdateData = newUpdateData;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the previously saved update data for the
        /// current thread.
        /// </summary>
        /// <param name="savedUpdateData">
        /// On input, the previously saved update data to restore; upon return,
        /// this parameter is reset to null.
        /// </param>
        internal void PopUpdateData(
            ref IUpdateData savedUpdateData
            )
        {
            //
            // NOTE: This lock is not necessary when we are compiled with
            //       the THREADING option enabled because UpdateData is a
            //       per-thread value in that case.
            //
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                UpdateData = savedUpdateData;
                savedUpdateData = null;
            }
        }
#endif
        #endregion
        #endregion

