        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This property is always the global call frame; however,
        //          it is intended for use by the ContextManager class only.
        //          Please use the "GlobalFrame" property instead.  Assumes
        //          interpreter lock is held.
        //
        /// <summary>
        /// Gets the global call frame directly, bypassing the per-thread
        /// variable context.  This property is intended for use by the
        /// <c>ContextManager</c> class only and assumes the interpreter lock
        /// is held.
        /// </summary>
        internal ICallFrame InternalGlobalFrame
        {
            get { return globalFrame; }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: This method is allowed to access the global call frame
        //          variable directly because it is called directly by the
        //          ContextManager class.  Nobody else should access the
        //          global frame variable directly.  Please use the
        //          "CurrentGlobalFrame" property instead.  This assumes
        //          the interpreter lock is held.
        //
        /// <summary>
        /// This method creates the global call frame for this interpreter if
        /// it does not already exist.  This method is intended for use by the
        /// <c>ContextManager</c> class only and assumes the interpreter lock
        /// is held.
        /// </summary>
        /// <param name="callStack">
        /// The call stack to associate with the newly created global call
        /// frame.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the global call frame already existed; otherwise, false.
        /// </returns>
        internal bool CreateGlobalFrame(
            CallStack callStack
            )
        {
            if (globalFrame == null)
            {
                globalFrame = NewGlobalCallFrame(callStack);
                return false; /* NOTE: It was not already there. */
            }

            return true; /* NOTE: It was already there. */
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ICallFrame Management
        /// <summary>
        /// This method determines whether the specified call frame is present
        /// in the call stack for the current thread for this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to locate.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is present in the call stack; otherwise,
        /// false.
        /// </returns>
        internal bool IsCallFrameInCallStack(ICallFrame frame)
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                if (CallStack != null)
                    return CallStack.Contains(frame);
                else
                    return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is the
        /// variable call frame resolved for variable access in the current
        /// context.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is the resolved variable call frame;
        /// otherwise, false.
        /// </returns>
        internal bool IsVariableCallFrame(ICallFrame frame)
        {
            if (!CallFrameOps.IsVariable(frame))
                return false;

            ICallFrame variableFrame = frame;

            if (GetVariableFrameViaResolvers( /* NO-LOCK */
                    LookupFlags.NoVerbose,
                    ref variableFrame) != ReturnCode.Ok)
            {
                return false;
            }

            return CallFrameOps.IsSame(frame, variableFrame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is the
        /// current global call frame for this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is the current global call frame;
        /// otherwise, false.
        /// </returns>
        internal bool IsGlobalCallFrame(ICallFrame frame)
        {
            return CallFrameOps.IsSame(frame, CurrentGlobalFrame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is the
        /// global scope call frame for this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is the global scope call frame; otherwise,
        /// false.
        /// </returns>
        internal bool IsGlobalScopeCallFrame(ICallFrame frame)
        {
            return CallFrameOps.IsSame(frame, GlobalScopeFrame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is the
        /// current call frame for this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is the current call frame; otherwise,
        /// false.
        /// </returns>
        internal bool IsCurrentCallFrame(ICallFrame frame)
        {
            return CallFrameOps.IsSame(frame, CurrentFrame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is the
        /// procedure call frame for this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is the procedure call frame; otherwise,
        /// false.
        /// </returns>
        internal bool IsProcedureCallFrame(ICallFrame frame)
        {
            return CallFrameOps.IsSame(frame, ProcedureFrame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is the
        /// uplevel call frame for this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is the uplevel call frame; otherwise,
        /// false.
        /// </returns>
        internal bool IsUplevelCallFrame(ICallFrame frame)
        {
            return CallFrameOps.IsSame(frame, UplevelFrame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is a
        /// namespace call frame.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <returns>
        /// True if the call frame is a namespace call frame; otherwise,
        /// false.
        /// </returns>
        internal static bool IsNamespaceCallFrame(ICallFrame frame)
        {
            return CallFrameOps.IsNamespace(frame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified call frame is a scope
        /// call frame that is currently tracked by this interpreter.
        /// </summary>
        /// <param name="frame">
        /// The call frame to check.  This parameter may be null.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message describing
        /// why the call frame is not a tracked scope call frame.
        /// </param>
        /// <returns>
        /// True if the call frame is a tracked scope call frame; otherwise,
        /// false.
        /// </returns>
        internal bool IsScopeCallFrame(
            ICallFrame frame,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!CallFrameOps.IsScope(frame))
                {
                    error = "call frame not of the scope type";
                    return false;
                }

                if (!PrivateHasScopes(ref error))
                    return false;

                foreach (CallFramePair pair in scopes)
                {
                    ICallFrame localFrame = pair.Value;

                    if (localFrame == null)
                        continue;

                    if (CallFrameOps.IsSame(frame, localFrame))
                        return true;
                }

                error = "scope call frame not found";
                return false;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the call frame for the procedure currently being
        /// executed, falling back to the current global call frame when no
        /// procedure frame is active.  This method cannot return null.
        /// </summary>
        /// <returns>
        /// The procedure call frame, or the current global call frame if none
        /// is active.
        /// </returns>
        internal ICallFrame GetProcedureFrame() /* CANNOT RETURN NULL */
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                ICallFrame frame = ProcedureFrame;

                return (frame != null) ? frame : CurrentGlobalFrame;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the uplevel call frame, falling back to the
        /// current call frame when no uplevel frame is active.  This method
        /// cannot return null.
        /// </summary>
        /// <returns>
        /// The uplevel call frame, or the current call frame if none is
        /// active.
        /// </returns>
        internal ICallFrame GetUplevelFrame() /* CANNOT RETURN NULL */
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                ICallFrame frame = UplevelFrame;

                return (frame != null) ? frame : CurrentFrame;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines the call frame that should be used for
        /// variable access, after extracting any frame-selection flags
        /// encoded in the specified variable name.  This method cannot return
        /// null.
        /// </summary>
        /// <param name="frame">
        /// The starting call frame, or null to start from the current call
        /// frame.
        /// </param>
        /// <param name="varName">
        /// On input, the variable name possibly containing encoded flags;
        /// upon return, the variable name with any encoded flags removed.
        /// </param>
        /// <param name="flags">
        /// On input, the variable flags to use; upon return, updated with any
        /// flags extracted from the variable name.
        /// </param>
        /// <returns>
        /// The call frame to use for variable access.
        /// </returns>
        internal ICallFrame GetVariableFrame(
            ICallFrame frame,
            ref string varName,
            ref VariableFlags flags
            ) /* CANNOT RETURN NULL */
        {
            EntityOps.GetFlags(ref varName, ref flags);

            return GetVariableFrame(frame, flags);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines the call frame that should be used for
        /// variable access, based on the specified variable flags.  This
        /// method cannot return null.
        /// </summary>
        /// <param name="frame">
        /// The starting call frame, or null to start from the current call
        /// frame.
        /// </param>
        /// <param name="flags">
        /// The variable flags controlling which call frame is selected.
        /// </param>
        /// <returns>
        /// The call frame to use for variable access.
        /// </returns>
        internal ICallFrame GetVariableFrame( // TODO: Replace uses of me.
            ICallFrame frame,
            VariableFlags flags
            ) /* CANNOT RETURN NULL */
        {
            ICallFrame variableFrame;

#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                if (FlagOps.HasFlags(flags, VariableFlags.GlobalOnly, true))
                {
                    variableFrame = CurrentGlobalFrame;
                }
                else
                {
                    if (frame != null)
                        variableFrame = CallFrameOps.FollowNext(frame);
                    else
                        variableFrame = CallFrameOps.FollowNext(CurrentFrame);

                    if (variableFrame == null)
                        variableFrame = CurrentGlobalFrame;
                }
            }

            return variableFrame;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines the call frame flags and starting call
        /// frame to use when servicing an <c>info level</c> style request.
        /// </summary>
        /// <param name="subCommand">
        /// The name of the sub-command being processed, or null.
        /// </param>
        /// <param name="flags">
        /// On input, the call frame flags to adjust; upon return, updated to
        /// reflect whether invisible call frames should be considered.
        /// </param>
        /// <param name="frame">
        /// Upon return, this parameter receives the call frame from which the
        /// request should be serviced.
        /// </param>
        internal void GetInfoLevelFlagsAndFrame(
            string subCommand,
            ref CallFrameFlags flags,
            ref ICallFrame frame
            ) /* HACK */
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                flags |= CallFrameFlags.Invisible;
                frame = CurrentFrame;

                //
                // NOTE: If we are not performing work for the generic
                //       "level" sub-command then always allow invisible
                //       call frames to be seen; otherwise, only allow
                //       invisible call frames to be seen if we are within
                //       a call frame that has the appropriate flag set.
                //
                if ((subCommand != null) && !SharedStringOps.SystemEquals(
                        subCommand, CallFrameOps.InfoLevelSubCommand) ||
                    CallFrameOps.Find(CallStack, frame, false, 0,
                        CallFrameFlags.NoInvisible, CallFrameFlags.None,
                        false, false) == ReturnCode.Ok)
                {
                    flags &= ~CallFrameFlags.Invisible;
                    frame = CallFrameOps.FollowNext(frame);
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method gets the call frame flags used when counting call
        /// frames for an <c>info level</c> request, taking into account
        /// whether namespaces are enabled.
        /// </summary>
        /// <returns>
        /// The call frame flags to use for <c>info level</c> processing.
        /// </returns>
        internal CallFrameFlags GetInfoLevelCallFrameFlags()
        {
            CallFrameFlags result = CallFrameFlags.InfoLevel;

            if (!InternalAreNamespacesEnabled())
                result &= ~CallFrameFlags.Namespace;

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method computes the call frame level reported by the
        /// <c>info level</c> command.
        /// </summary>
        /// <param name="subCommand">
        /// The name of the sub-command being processed, or null.
        /// </param>
        /// <param name="level">
        /// Upon success, this parameter receives the computed call frame
        /// level.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message describing
        /// the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error
        /// return code.
        /// </returns>
        internal ReturnCode GetInfoLevel(
            string subCommand,
            ref int level,
            ref Result error
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // HACK: Allow, through the usage of "##<integer>" notation,
                //       traversal of all call frames, including invisible
                //       ones.  This feature is not supported by Tcl.
                //
                CallFrameFlags notHasFlags = CallFrameFlags.None;
                ICallFrame currentFrame = null;

                GetInfoLevelFlagsAndFrame(
                    subCommand, ref notHasFlags, ref currentFrame);

                if ((currentFrame != null) &&
                    currentFrame.HasFlags(CallFrameFlags.Downlevel, true))
                {
                    level = (int)currentFrame.FrameLevel;
                    return ReturnCode.Ok;
                }

                return CallFrameOps.Count(CallStack, currentFrame,
                    GetInfoLevelCallFrameFlags(), notHasFlags, false,
                    false, ref level, ref error);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method retrieves the command arguments associated with the
        /// call frame at the specified level, as reported by the
        /// <c>info level</c> command.
        /// </summary>
        /// <param name="subCommand">
        /// The name of the sub-command being processed, or null.
        /// </param>
        /// <param name="text">
        /// The original level specification text, used for error reporting.
        /// </param>
        /// <param name="level">
        /// The call frame level whose arguments are to be retrieved.
        /// </param>
        /// <param name="fullName">
        /// Non-zero to use the fully resolved command name as the first
        /// argument.
        /// </param>
        /// <param name="result">
        /// Upon success, this parameter receives the string form of the call
        /// frame arguments; upon failure, it receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error
        /// return code.
        /// </returns>
        internal ReturnCode GetInfoLevelArguments(
            string subCommand,
            string text,
            int level,
            bool fullName,
            ref Result result
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // HACK: Allow, through the usage of "##<integer>" notation,
                //       traversal of all call frames, including invisible
                //       ones.  This feature is not supported by Tcl.
                //
                CallFrameFlags notHasFlags = CallFrameFlags.NoVariables;
                ICallFrame currentFrame = null;

                GetInfoLevelFlagsAndFrame(
                    subCommand, ref notHasFlags, ref currentFrame);

                ArgumentList arguments;
                string executeName = null;

                if ((currentFrame != null) &&
                    currentFrame.HasFlags(CallFrameFlags.Downlevel, true))
                {
                    ICallFrame uplevelFrame = GetUplevelFrame();

                    arguments = (uplevelFrame != null) ?
                        uplevelFrame.Arguments : null;

                    if (arguments != null)
                    {
                        if (fullName && !CallFrameOps.GetIExecuteName(
                                uplevelFrame, ref executeName))
                        {
                            //
                            // TODO: Should this fail?  Caller requested
                            //       the "exact" name and for some reason
                            //       we cannot provide it.  Alternatively,
                            //       we could fallback to the normal case
                            //       and use the first argument.
                            //
                            result = "uplevel frame missing command name";
                            return ReturnCode.Error;
                        }

                        if (executeName != null)
                        {
                            arguments = arguments.CloneWithNewFirstValue(
                                executeName);
                        }

                        result = arguments.ToString();
                        return ReturnCode.Ok;
                    }
                }

                ReturnCode code;
                ICallFrame frame = null;

                code = CallFrameOps.GetOrFind(
                    CallStack, GlobalFrame /* EXEMPT */, CurrentGlobalFrame,
                    currentFrame, (level > 0), false, Math.Abs(level),
                    CallFrameFlags.Variables, notHasFlags, false, false,
                    ref frame, ref result);

                arguments = (frame != null) ? frame.Arguments : null;

                if ((code == ReturnCode.Ok) && (arguments != null))
                {
                    if (fullName && !CallFrameOps.GetIExecuteName(
                            frame, ref executeName))
                    {
                        //
                        // TODO: Should this fail?  Caller requested
                        //       the "exact" name and for some reason
                        //       we cannot provide it.  Alternatively,
                        //       we could fallback to the normal case
                        //       and use the first argument.
                        //
                        result = "specified frame missing command name";
                        return ReturnCode.Error;
                    }

                    if (executeName != null)
                    {
                        arguments = arguments.CloneWithNewFirstValue(
                            executeName);
                    }

                    result = arguments.ToString();
                }
                else
                {
                    result = String.Format(
                        "bad level {0}",
                        FormatOps.WrapOrNull(text));

                    code = ReturnCode.Error;
                }

                return code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Peek / Push / Pop
        #region Shared
#if DEBUG
        /// <summary>
        /// This method determines whether strict call stack handling is
        /// enabled for this interpreter, causing an invalid call stack to be
        /// treated as an error.
        /// </summary>
        /// <returns>
        /// True if strict call stack handling is enabled; otherwise, false.
        /// </returns>
        private bool IsCallStackStrict()
        {
            //
            // HACK: Accessed without locking, critical path.
            //
            // lock (syncRoot) /* TRANSACTIONAL */
            {
                return FlagOps.HasFlags( /* NO-LOCK */
                    interpreterStateFlags, InterpreterStateFlags.StrictCallStack,
                    true); /* EXEMPT */
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method throws a script exception indicating that the call
        /// stack is in an invalid state.
        /// </summary>
        /// <param name="code">
        /// The return code to associate with the thrown exception.
        /// </param>
        /// <param name="error">
        /// The error message providing additional detail, or null.
        /// </param>
        private void ThrowInvalidCallStack(
            ReturnCode code,
            Result error
            )
        {
            Result result = (error != null) ?
                String.Format("{0}: {1}", InvalidCallStackError, error) :
                InvalidCallStackError;

#if DEBUG && VERBOSE
            DebugOps.Complain(this, code, result);
#endif

            throw new ScriptException(code, result);
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Peek
        /// <summary>
        /// This method determines whether a call frame can be peeked at or
        /// popped from the call stack for the current thread for this
        /// interpreter.
        /// </summary>
        /// <returns>
        /// True if a call frame can be peeked at or popped; otherwise, false.
        /// </returns>
        internal bool CanPeekCallFrame()
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                return CallFrameOps.CanPeekOrPop(CallStack);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the call frame at the top of the call stack
        /// for the current thread for this interpreter, without removing it.
        /// </summary>
        /// <returns>
        /// The call frame at the top of the call stack, or null if none is
        /// available.
        /// </returns>
        internal ICallFrame PeekCallFrame()
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                ICallFrame peekFrame = null;
                CallStack callStack = CallStack;

#if DEBUG
                if (CallFrameOps.CanPeekOrPop(callStack))
#endif
                {
                    peekFrame = CallFrameOps.Peek(callStack);
                }
#if DEBUG
                else if (IsCallStackStrict())
                {
                    //
                    // NOTE: If there are no call frames on the stack, this
                    //       is an error.
                    //
                    ThrowInvalidCallStack(ReturnCode.Error,
                        "missing global call frame before peek");
                }
#endif

                return peekFrame;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method searches the call stack for the first call frame whose
        /// flags match the specified criteria.
        /// </summary>
        /// <param name="notFrame">
        /// A call frame to exclude from the search, or null to exclude none.
        /// </param>
        /// <param name="hasFlags">
        /// The call frame flags that a matching call frame must have.
        /// </param>
        /// <param name="notHasFlags">
        /// The call frame flags that a matching call frame must not have.
        /// </param>
        /// <param name="hasAll">
        /// Non-zero to require that all of the <paramref name="hasFlags" />
        /// flags be present; zero to require only any of them.
        /// </param>
        /// <param name="notHasAll">
        /// Non-zero to require that all of the <paramref name="notHasFlags" />
        /// flags be absent; zero to require only any of them.
        /// </param>
        /// <returns>
        /// The first matching call frame, or null if no match is found.
        /// </returns>
        private ICallFrame FindCallFrame(
            ICallFrame notFrame,
            CallFrameFlags hasFlags,
            CallFrameFlags notHasFlags,
            bool hasAll,
            bool notHasAll
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                CallStack callStack = CallStack; /* PROPERTY */

                if (callStack != null)
                {
                    int count = callStack.Count;

                    for (int index = 0; index < count; index++)
                    {
                        ICallFrame frame = null;

                        if (!CallFrameOps.CanPeekOrPop(
                                callStack, index, ref frame))
                        {
                            continue;
                        }

                        if (frame == null)
                            continue;

                        if ((notFrame != null) &&
                            CallFrameOps.IsSame(frame, notFrame))
                        {
                            continue;
                        }

                        CallFrameFlags? flags =
                            CallFrameOps.GetFlagsNoThrow(frame);

                        if (flags == null)
                            break;

                        if (CallFrameOps.MatchFlags(
                                (CallFrameFlags)flags, hasFlags,
                                notHasFlags, hasAll, notHasAll))
                        {
                            return frame;
                        }
                    }
                }

                return null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // WARNING: For use by the CallFrameOps.CloneToExisting
        //          method only.
        //
        /// <summary>
        /// This method finds the first variable call frame on the call stack,
        /// optionally excluding a specific call frame.  This method is for use
        /// by the <c>CallFrameOps.CloneToExisting</c> method only.
        /// </summary>
        /// <param name="notFrame">
        /// A call frame to exclude from the search, or null to exclude none.
        /// </param>
        /// <returns>
        /// The first matching variable call frame, or null if no match is
        /// found.
        /// </returns>
        internal ICallFrame GetVariableCallFrame(
            ICallFrame notFrame
            )
        {
            return FindCallFrame(
                notFrame, CallFrameFlags.Variables,
                CallFrameFlags.None, false, false);
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Push
        /// <summary>
        /// This method pushes the specified call frame onto the call stack
        /// for the current thread for this interpreter and makes it the
        /// current call frame.
        /// </summary>
        /// <param name="newFrame">
        /// The call frame to push.  This parameter may be null.
        /// </param>
        internal void PushCallFrame(
            ICallFrame newFrame
            )
        {
            PushCallFrame(newFrame, false);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pushes the specified call frame onto the call stack
        /// for the current thread for this interpreter, flagging it as
        /// automatic, and makes it the current call frame.
        /// </summary>
        /// <param name="newFrame">
        /// The call frame to push.  This parameter may be null.
        /// </param>
        internal void PushAutomaticCallFrame(
            ICallFrame newFrame
            )
        {
            PushCallFrame(newFrame, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pushes the specified call frame onto the call stack
        /// for the current thread for this interpreter, optionally flagging
        /// it as automatic, and makes it the current call frame.
        /// </summary>
        /// <param name="newFrame">
        /// The call frame to push.  This parameter may be null.
        /// </param>
        /// <param name="automatic">
        /// Non-zero to flag the pushed call frame as automatic.
        /// </param>
        private void PushCallFrame(
            ICallFrame newFrame,
            bool automatic
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                CallStack callStack = CallStack;

#if DEBUG
                if (CallFrameOps.CanPush(callStack))
#endif
                {
                    ICallFrame frame = null;

                    //
                    // NOTE: Push the call frame.
                    //
                    CallFrameOps.Push(callStack, newFrame, ref frame);

                    //
                    // NOTE: Flag the call frame as 'automatic', if necessary.
                    //
                    if (automatic && (frame != null))
                        frame.Flags |= CallFrameFlags.Automatic;

                    //
                    // NOTE: Set the current call frame to the one we just pushed.
                    //
                    CurrentFrame = frame;
                }
#if DEBUG
                else if (IsCallStackStrict())
                {
                    //
                    // NOTE: If the call stack is unusable, this is an error.
                    //
                    ThrowInvalidCallStack(
                        ReturnCode.Error, "missing before push");
                }
#endif
            }

#if NOTIFY
            /* IGNORED */
            CheckNotification(
                NotifyType.CallFrame, NotifyFlags.Pushed,
                newFrame, this,
                null, null, null);
#endif
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Pop
        /// <summary>
        /// This method pops the call frame at the top of the call stack for
        /// the current thread for this interpreter and makes the next call
        /// frame the current one.
        /// </summary>
        /// <returns>
        /// The call frame that was popped, or null if none was available.
        /// </returns>
        private ICallFrame PopCallFrame()
        {
            ICallFrame popFrame = null;
            ICallFrame frame = null;

#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Grab the thread call stack into a local variable.
                //
                CallStack callStack = CallStack;

                //
                // NOTE: Pop the call frame now.  In the debug build, make
                //       sure there are actually some call frames available;
                //       otherwise, complain.
                //
#if DEBUG
                if (CallFrameOps.CanPeekOrPop(callStack))
#endif
                {
                    popFrame = CallFrameOps.Pop(callStack, ref frame);
                }
#if DEBUG
                else if (IsCallStackStrict())
                {
                    //
                    // NOTE: If there are no call frames on the stack, this
                    //       is an error.
                    //
                    ThrowInvalidCallStack(ReturnCode.Error,
                        "missing global call frame before pop");
                }
#endif

                //
                // NOTE: Set the current call frame to the one we just popped.
                //
                CurrentFrame = frame;

#if DEBUG
                //
                // NOTE: If there are no call frames left on the stack, this
                //       is an error.
                //
                if (IsCallStackStrict() &&
                    !CallFrameOps.CanPeekOrPop(callStack))
                {
                    ThrowInvalidCallStack(ReturnCode.Error,
                        "missing global call frame after pop");
                }
#endif
            }

#if NOTIFY || NOTIFY_OBJECT
            /* IGNORED */
            CheckNotification(
                NotifyType.CallFrame, NotifyFlags.Popped,
                popFrame, this,
                null, null, null);
#endif

            return popFrame;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops the call frame at the top of the call stack for
        /// the current thread for this interpreter without throwing on an
        /// invalid call stack, optionally raising a notification.
        /// </summary>
        /// <param name="notify">
        /// Non-zero to raise a call frame popped notification.
        /// </param>
        /// <returns>
        /// The call frame that was popped, or null if none was available.
        /// </returns>
        private ICallFrame PopCallFrameNoThrow(
            bool notify
            )
        {
            ICallFrame popFrame = null;

#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Grab the thread call stack into a local variable.
                //
                CallStack callStack = CallStack;

                //
                // NOTE: Pop the call frame now.  In the debug build, make
                //       sure there are actually some call frames available;
                //       otherwise, complain.
                //
                if (CallFrameOps.CanPeekOrPop(callStack))
                {
                    ICallFrame frame = null;

                    //
                    // NOTE: Attempt to pop one call frame now.  This may be
                    //       the global call frame and that is fine.  It is
                    //       up to the caller to make sure the call stack is
                    //       in a consistent state after this method returns.
                    //
                    popFrame = CallFrameOps.Pop(callStack, ref frame);

                    //
                    // NOTE: Set the current call frame to the one we just
                    //       popped.
                    //
                    CurrentFrame = frame;
                }
            }

#if NOTIFY || NOTIFY_OBJECT
            if (notify)
            {
                /* IGNORED */
                CheckNotification(
                    NotifyType.CallFrame, NotifyFlags.Popped,
                    popFrame, this,
                    null, null, null);
            }
#endif

            return popFrame;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops all consecutive call frames matching the
        /// specified flags from the top of the call stack and then pops one
        /// additional call frame.
        /// </summary>
        /// <param name="hasFlags">
        /// The call frame flags that a call frame must have to be popped.
        /// </param>
        /// <param name="all">
        /// Non-zero to require that all of the specified flags be present;
        /// zero to require only any of them.
        /// </param>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        private ICallFrame PopCallFramesAndOneMore(
            CallFrameFlags hasFlags,
            bool all
            )
        {
            ICallFrame newFrame;

            newFrame = PopCallFrames(hasFlags, 0, all);

            if (newFrame != null)
                newFrame = PopCallFrame();

            return newFrame;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops consecutive call frames matching the specified
        /// flags from the top of the call stack, up to the specified limit.
        /// </summary>
        /// <param name="hasFlags">
        /// The call frame flags that a call frame must have to be popped.
        /// </param>
        /// <param name="limit">
        /// The maximum number of matching call frames to pop, or zero (or
        /// negative) for no limit.
        /// </param>
        /// <param name="all">
        /// Non-zero to require that all of the specified flags be present;
        /// zero to require only any of them.
        /// </param>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        private ICallFrame PopCallFrames(
            CallFrameFlags hasFlags,
            int limit,
            bool all
            )
        {
            ICallFrame frame = null;
            bool usable = true; /* NOT USED */

            return PopCallFrames(hasFlags, limit, all, ref frame, ref usable);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops consecutive call frames matching the specified
        /// flags from the top of the call stack, up to the specified limit,
        /// also reporting whether the call stack remains usable.
        /// </summary>
        /// <param name="hasFlags">
        /// The call frame flags that a call frame must have to be popped.
        /// </param>
        /// <param name="limit">
        /// The maximum number of matching call frames to pop, or zero (or
        /// negative) for no limit.
        /// </param>
        /// <param name="all">
        /// Non-zero to require that all of the specified flags be present;
        /// zero to require only any of them.
        /// </param>
        /// <param name="usable">
        /// Upon return, this parameter is set to zero if a disposed call
        /// frame was encountered, indicating the call stack may be in an
        /// inconsistent state.
        /// </param>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        private ICallFrame PopCallFrames(
            CallFrameFlags hasFlags,
            int limit,
            bool all,
            ref bool usable
            )
        {
            ICallFrame frame = null;

            return PopCallFrames(hasFlags, limit, all, ref frame, ref usable);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops consecutive call frames matching the specified
        /// flags from the top of the call stack, up to the specified limit,
        /// reporting the most recently popped call frame and whether the call
        /// stack remains usable.
        /// </summary>
        /// <param name="hasFlags">
        /// The call frame flags that a call frame must have to be popped.
        /// </param>
        /// <param name="limit">
        /// The maximum number of matching call frames to pop, or zero (or
        /// negative) for no limit.
        /// </param>
        /// <param name="all">
        /// Non-zero to require that all of the specified flags be present;
        /// zero to require only any of them.
        /// </param>
        /// <param name="frame">
        /// Upon return, this parameter receives the most recent call frame
        /// that was popped.
        /// </param>
        /// <param name="usable">
        /// Upon return, this parameter is set to zero if a disposed call
        /// frame was encountered, indicating the call stack may be in an
        /// inconsistent state.
        /// </param>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        private ICallFrame PopCallFrames(
            CallFrameFlags hasFlags,
            int limit,
            bool all,
            ref ICallFrame frame,
            ref bool usable
            )
        {
            ICallFrame newFrame = null;

#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                int count = 0;
                bool done = false;

                do
                {
                    //
                    // NOTE: Examine the current call frame without popping it.
                    //       Upon returning from this method, returning a valid
                    //       call frame will cause that call frame to be popped.
                    //
                    newFrame = PeekCallFrame();

                    //
                    // HACK: Prevent an exception from being thrown here if the
                    //       call frame has been disposed (i.e. via the context
                    //       manager) at a point after the last disposal check.
                    //
                    CallFrameFlags? flags = CallFrameOps.GetFlagsNoThrow(newFrame);

                    //
                    // BUGFIX: Also, if the call frame *is* disposed, make sure
                    //         that we abort early and try to warn our caller.
                    //
                    if (flags == null)
                    {
                        usable = false;
                        return null;
                    }

                    if ((newFrame != null) && FlagOps.HasFlags(
                            (CallFrameFlags)flags, hasFlags, all))
                    {
                        //
                        // NOTE: The current call frame does match the flags
                        //       provided by the caller, attempt to pop it now.
                        //
#if DEBUG
                        ICallFrame popFrame = PopCallFrame();
#else
                        /* IGNORED */
                        PopCallFrame();
#endif

                        //
                        // NOTE: Keep track of how many call frames have been
                        //       popped so far.
                        //
                        count++;

#if DEBUG
                        //
                        // NOTE: Check that the popped call frame matches the one
                        //       that we were expecting to pop.
                        //
                        if (IsCallStackStrict() &&
                            !CallFrameOps.IsSame(popFrame, newFrame))
                        {
                            ThrowInvalidCallStack(ReturnCode.Error,
                                "popped call frame does not match expected");
                        }
#endif

                        //
                        // NOTE: Provide the caller with the most recent frame
                        //       that was popped.
                        //
                        frame = newFrame;

                        //
                        // NOTE: Have we reached the limit for the number of
                        //       matching call frames to pop?  If the limit is
                        //       zero or negative, there is no limit.
                        //
                        if ((limit > 0) && (count >= limit))
                            done = true;
                    }
                    else
                    {
                        done = true;
                    }
                }
                while (!done);
            }

            return newFrame;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Global (Engine)
        /// <summary>
        /// This method pushes a reference to the global call frame onto the
        /// call stack for the current thread, making it the current call
        /// frame.
        /// </summary>
        /// <param name="mark">
        /// Non-zero to mark the existing call frames as invisible so that the
        /// pushed global call frame behaves like <c>[uplevel #0]</c>.
        /// </param>
        internal void PushGlobalCallFrame(
            bool mark
            )
        {
            PushGlobalCallFrame(mark, false);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pushes a reference to the global call frame onto the
        /// call stack for the current thread, making it the current call
        /// frame, optionally treating the pushed call frame as automatic.
        /// </summary>
        /// <param name="mark">
        /// Non-zero to mark the existing call frames as invisible so that the
        /// pushed global call frame behaves like <c>[uplevel #0]</c>.
        /// </param>
        /// <param name="automatic">
        /// Non-zero if the pushed call frame should be considered as having
        /// been pushed automatically by the engine.
        /// </param>
        private void PushGlobalCallFrame(
            bool mark,
            bool automatic
            )
        {
            if (mark)
            {
                //
                // BUGFIX: When pushing the global call frame from the engine we
                //         must make sure this is treated just like [uplevel #0]
                //         (i.e. the other call frames must be marked as invisible
                //         for [info level], etc to work properly).
                //
                ReturnCode code;
                Result error = null;

                code = CallFrameOps.MarkMatching(
                    CallStack, CurrentFrame, true, 0, CallFrameFlags.Variables,
                    CallFrameFlags.Invisible | CallFrameFlags.NoVariables,
                    CallFrameFlags.Invisible, false, false, true, ref error);

                if (code != ReturnCode.Ok)
                    DebugOps.Complain(this, code, error); // BUGBUG: Panic!

                ICallFrame globalFrame = CurrentGlobalFrame;
                string frameName;

                if (CallFrameOps.IsGlobalScope(globalFrame))
                    frameName = "global scope (engine)";
                else
                    frameName = "global (engine)";

                ICallFrame frame = NewLinkedCallFrame(
                    frameName, 0, CallFrameFlags.Uplevel, CurrentResolveData,
                    null, null, globalFrame);

                PushCallFrame(frame, automatic);

                //
                // TODO: Figure out if this will work here when use instead
                //       of the previous two statements.
                //
                // PushCallFrame(CurrentGlobalFrame, automatic);
            }
            else
            {
                PushCallFrame(CurrentGlobalFrame, automatic);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops all consecutive scope call frames from the top of
        /// the call stack and then pops one additional call frame.
        /// </summary>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        internal ICallFrame PopScopeCallFramesAndOneMore() /* EXIT POINT */
        {
            return PopCallFramesAndOneMore(CallFrameFlags.Scope, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops all consecutive scope call frames from the top of
        /// the call stack.
        /// </summary>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        internal ICallFrame PopScopeCallFrames()
        {
            return PopCallFrames(CallFrameFlags.Scope, 0, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops all consecutive scope call frames from the top of
        /// the call stack, also reporting whether the call stack remains
        /// usable.
        /// </summary>
        /// <param name="usable">
        /// Upon return, this parameter is set to zero if a disposed call frame
        /// was encountered, indicating the call stack may be in an inconsistent
        /// state.
        /// </param>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        internal ICallFrame PopScopeCallFrames(
            ref bool usable
            )
        {
            return PopCallFrames(CallFrameFlags.Scope, 0, true, ref usable);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops all consecutive scope call frames from the top of
        /// the call stack, reporting the most recently popped call frame and
        /// whether the call stack remains usable.
        /// </summary>
        /// <param name="frame">
        /// Upon return, this parameter receives the most recent call frame
        /// that was popped.
        /// </param>
        /// <param name="usable">
        /// Upon return, this parameter is set to zero if a disposed call frame
        /// was encountered, indicating the call stack may be in an inconsistent
        /// state.
        /// </param>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        internal ICallFrame PopScopeCallFrames(
            ref ICallFrame frame,
            ref bool usable
            )
        {
            return PopCallFrames(
                CallFrameFlags.Scope, 0, true, ref frame, ref usable);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops the global call frame, along with any open scope
        /// call frames above it, from the call stack for the current thread.
        /// </summary>
        /// <param name="mark">
        /// Non-zero to mark the remaining call frames as visible again,
        /// reversing the effect of a marked global call frame push.
        /// </param>
        internal void PopGlobalCallFrame( /* EXIT POINT */
            bool mark
            )
        {
            /* IGNORED */
            PopScopeCallFramesAndOneMore();

            if (mark)
            {
                ReturnCode code;
                Result error = null;

                code = CallFrameOps.MarkMatching(
                    CallStack, CurrentFrame, true, 0, CallFrameFlags.Variables,
                    CallFrameFlags.NoVariables, CallFrameFlags.Invisible, false,
                    false, false, ref error);

                if (code != ReturnCode.Ok)
                    DebugOps.Complain(this, code, error); // BUGBUG: Panic!
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Namespace (Core)
        #region Dead Code
#if DEAD_CODE
        /// <summary>
        /// This method sets the current namespace for this interpreter, saving
        /// the previous current namespace.
        /// </summary>
        /// <param name="namespace">
        /// The namespace to make the current namespace.
        /// </param>
        /// <param name="savedNamespace">
        /// Upon return, receives the previous current namespace, for later
        /// restoration.
        /// </param>
        internal void PushCurrentNamespace(
            INamespace @namespace,
            ref INamespace savedNamespace
            )
        {
            savedNamespace = NamespaceOps.GetCurrent(this, null);
            NamespaceOps.SetCurrent(this, null, @namespace);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the previously saved current namespace for this
        /// interpreter.
        /// </summary>
        /// <param name="savedNamespace">
        /// The previously saved namespace to restore as the current namespace.
        /// Upon return, this is reset to null.
        /// </param>
        /// <returns>
        /// Returns the current namespace that was in effect prior to the
        /// restoration.
        /// </returns>
        internal INamespace PopCurrentNamespace(
            ref INamespace savedNamespace
            )
        {
            INamespace @namespace = NamespaceOps.GetCurrent(this, null);
            NamespaceOps.SetCurrent(this, null, savedNamespace);
            savedNamespace = null;
            return @namespace;
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method increases the reference count of the namespace that is
        /// associated with the specified call frame, marking it as entered.
        /// </summary>
        /// <param name="newFrame">
        /// The call frame whose associated namespace is being entered.
        /// </param>
        private void EnterNamespaceCallFrame(
            ICallFrame newFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Increase the reference count for the namespace that
                //       is associated with the call frame.
                //
                if (newFrame != null)
                {
                    INamespace @namespace = NamespaceOps.GetCurrent(
                        this, newFrame);

                    if (@namespace != null)
                    {
                        /* IGNORED */
                        @namespace.Enter(true);
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method decreases the reference count of the namespace that is
        /// associated with the specified call frame, marking it as exited, and
        /// deletes the namespace if it has been pending deletion and is now
        /// eligible.
        /// </summary>
        /// <param name="newFrame">
        /// The call frame whose associated namespace is being exited.
        /// </param>
        private void ExitNamespaceCallFrame(
            ICallFrame newFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Decrease the reference count for the namespace that
                //       is associated with the call frame.
                //
                if (newFrame != null)
                {
                    INamespace @namespace = NamespaceOps.GetCurrent(
                        this, newFrame);

                    if (@namespace != null)
                    {
                        /* IGNORED */
                        @namespace.Exit(true);

                        if (@namespace.Deleted &&
                            !IsGlobalNamespace(@namespace) &&
                            CanDeleteNamespace(@namespace))
                        {
                            ReturnCode deleteCode;
                            Result deleteResult = null;

                            deleteCode = DeleteNamespace(
                                VariableFlags.None, @namespace, false,
                                ref deleteResult);

                            if (deleteCode != ReturnCode.Ok)
                                DebugOps.Complain(this, deleteCode, deleteResult);
                        }
                    }
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pushes the specified namespace call frame onto the call
        /// stack as an automatic call frame and increases the reference count
        /// of its associated namespace.
        /// </summary>
        /// <param name="newFrame">
        /// The namespace call frame to push onto the call stack.
        /// </param>
        internal void PushNamespaceCallFrame(
            ICallFrame newFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: For now, just push the call frame as 'automatic'.
                //
                PushAutomaticCallFrame(newFrame);

                //
                // NOTE: Increase the reference count for the namespace that
                //       is associated with the call frame.
                //
                EnterNamespaceCallFrame(newFrame);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method decreases the reference count of the namespace that is
        /// associated with the specified call frame and then pops the call
        /// frame, along with any open scope call frames above it, from the call
        /// stack.
        /// </summary>
        /// <param name="newFrame">
        /// The namespace call frame whose associated namespace is being exited.
        /// </param>
        /// <returns>
        /// The last call frame that was popped, or null if none was popped.
        /// </returns>
        internal ICallFrame PopNamespaceCallFrame(
            ICallFrame newFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Decrease the reference count for the namespace that
                //       is associated with the call frame.
                //
                /* NO RESULT */
                ExitNamespaceCallFrame(newFrame);

                //
                // NOTE: Cleanup any leftover open scopes from the procedure.
                //       We MUST do this here because otherwise the pop below
                //       will fail to pop the procedure call frame from the
                //       stack, thereby permanently unbalancing it.
                //
                return PopScopeCallFramesAndOneMore();
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Procedure (Core)
        /// <summary>
        /// This method records the specified call frame as the current
        /// procedure call frame, saving the previous procedure call frame so
        /// that it can be restored later.
        /// </summary>
        /// <param name="newFrame">
        /// The call frame to make the current procedure call frame.
        /// </param>
        /// <param name="savedFrame">
        /// Upon return, this parameter receives the procedure call frame that
        /// was current prior to this call.
        /// </param>
        internal void EnterProcedureCallFrame(
            ICallFrame newFrame,
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                savedFrame = ProcedureFrame; // save the current procedure call frame.
                ProcedureFrame = newFrame;   // set the new procedure call frame.
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the procedure call frame that was saved by a
        /// prior call to <c>EnterProcedureCallFrame</c>, making it the current
        /// procedure call frame again.
        /// </summary>
        /// <param name="savedFrame">
        /// The previously saved procedure call frame to restore.  Upon return,
        /// this parameter is reset to null.
        /// </param>
        internal void ExitProcedureCallFrame(
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                ProcedureFrame = savedFrame; // restore the saved procedure call frame.
                savedFrame = null;           // reset the saved procedure call frame.
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pushes the specified procedure call frame onto the call
        /// stack, entering its namespace context if necessary, and records it
        /// as the current procedure call frame.
        /// </summary>
        /// <param name="newFrame">
        /// The procedure call frame to push onto the call stack.
        /// </param>
        /// <param name="automatic">
        /// Non-zero if the pushed call frame should be considered as having
        /// been pushed automatically by the engine.
        /// </param>
        /// <param name="savedFrame">
        /// Upon return, this parameter receives the procedure call frame that
        /// was current prior to this call.
        /// </param>
        internal void PushProcedureCallFrame(
            ICallFrame newFrame,
            bool automatic,
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Push the new procedure call frame, thereby making it
                //       the current call frame.
                //
                PushCallFrame(newFrame, automatic);

                //
                // NOTE: If necessary, enter the namespace context.
                //
                if (InternalAreNamespacesEnabled())
                    EnterNamespaceCallFrame(newFrame);

                //
                // NOTE: Save the current procedure call frame and enter the
                //       new procedure call frame.
                //
                EnterProcedureCallFrame(newFrame, ref savedFrame);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method cleans up and pops the specified procedure call frame
        /// from the call stack, exiting its namespace context if necessary and
        /// restoring the previously saved procedure call frame.
        /// </summary>
        /// <param name="newFrame">
        /// The procedure call frame being popped from the call stack.
        /// </param>
        /// <param name="savedFrame">
        /// The previously saved procedure call frame to restore.  Upon return,
        /// this parameter is reset to null.
        /// </param>
        /// <returns>
        /// The call frame that was popped, or null if none was available.
        /// </returns>
        internal ICallFrame PopProcedureCallFrame( /* EXIT POINT */
            ICallFrame newFrame,
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Cleanup any leftover open scopes from the procedure.
                //       We MUST do this here because otherwise the pop below
                //       will fail to pop the procedure call frame from the
                //       stack, thereby permanently unbalancing it.
                //
                /* IGNORED */
                PopScopeCallFrames();

                //
                // NOTE: Exit the current procedure call frame and restore
                //       the procedure call frame saved earlier.
                //
                ExitProcedureCallFrame(ref savedFrame);

                //
                // NOTE: If necessary, exit the namespace context.
                //
                if (InternalAreNamespacesEnabled())
                    ExitNamespaceCallFrame(newFrame);

                //
                // NOTE: Grab the current call frame so that we can clean it
                //       up (i.e. remove undefined variables).
                //
                ICallFrame currentFrame = CurrentFrame;

                //
                // NOTE: Cleanup the current call frame (i.e. the procedure
                //       call frame).
                //
                /* IGNORED */
                CallFrameOps.Cleanup(currentFrame, newFrame, false);

                //
                // NOTE: Now pop the top call frame, which should be the
                //       procedure call frame.
                //
                ICallFrame popFrame = PopCallFrame();

                //
                // NOTE: Cleanup the call frame and mark it as undefined.
                //
                /* IGNORED */
                CallFrameOps.Cleanup(currentFrame, popFrame, true);

                //
                // NOTE: Return the call frame we just popped.
                //
                return popFrame;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Uplevel (Core)
        /// <summary>
        /// This method records the specified call frame as the current uplevel
        /// call frame, saving the previous uplevel call frame so that it can be
        /// restored later.
        /// </summary>
        /// <param name="newFrame">
        /// The call frame to make the current uplevel call frame.
        /// </param>
        /// <param name="savedFrame">
        /// Upon return, this parameter receives the uplevel call frame that was
        /// current prior to this call.
        /// </param>
        internal void EnterUplevelCallFrame(
            ICallFrame newFrame,
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                savedFrame = UplevelFrame; // save the current uplevel call frame.
                UplevelFrame = newFrame;   // set the new uplevel call frame.
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the uplevel call frame that was saved by a
        /// prior call to <c>EnterUplevelCallFrame</c>, making it the current
        /// uplevel call frame again.
        /// </summary>
        /// <param name="savedFrame">
        /// The previously saved uplevel call frame to restore.  Upon return,
        /// this parameter is reset to null.
        /// </param>
        internal void ExitUplevelCallFrame(
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                UplevelFrame = savedFrame; // restore the saved uplevel call frame.
                savedFrame = null;           // reset the saved uplevel call frame.
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pushes the specified uplevel call frame onto the call
        /// stack, links it to the call frame that was current prior to the
        /// push, and records it as the current uplevel call frame.
        /// </summary>
        /// <param name="oldFrame">
        /// The call frame that was current prior to the uplevel call frame
        /// being pushed; it is linked to the new call frame.
        /// </param>
        /// <param name="newFrame">
        /// The uplevel call frame to push onto the call stack.
        /// </param>
        /// <param name="automatic">
        /// Non-zero if the pushed call frame should be considered as having
        /// been pushed automatically by the engine.
        /// </param>
        /// <param name="savedFrame">
        /// Upon return, this parameter receives the uplevel call frame that was
        /// current prior to this call.
        /// </param>
        internal void PushUplevelCallFrame(
            ICallFrame oldFrame,
            ICallFrame newFrame,
            bool automatic,
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Push the new uplevel call frame, thereby making it
                //       the current call frame.
                //
                PushCallFrame(newFrame, automatic);

                //
                // NOTE: Link the newly created [uplevel] call frame to the
                //       current frame provided by the caller.  This will help
                //       later when the [info level] sub-command is used from
                //       a [downlevel] call frame.
                //
                if (oldFrame != null)
                    oldFrame.Other = newFrame;

                //
                // NOTE: Save the current uplevel call frame and enter the
                //       new uplevel call frame.
                //
                EnterUplevelCallFrame(oldFrame, ref savedFrame);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops the specified uplevel call frame from the call
        /// stack, unlinks it from the prior call frame, and restores the
        /// previously saved uplevel call frame.
        /// </summary>
        /// <param name="oldFrame">
        /// The call frame that was current prior to the uplevel call frame
        /// being pushed; it is unlinked from the new call frame.
        /// </param>
        /// <param name="newFrame">
        /// The uplevel call frame being popped from the call stack.
        /// </param>
        /// <param name="savedFrame">
        /// The previously saved uplevel call frame to restore.  Upon return,
        /// this parameter is reset to null.
        /// </param>
        /// <returns>
        /// The call frame that was popped, or null if none was available.
        /// </returns>
        internal ICallFrame PopUplevelCallFrame(
            ICallFrame oldFrame,
            ICallFrame newFrame,
            ref ICallFrame savedFrame
            )
        {
#if !THREADING
            lock (syncRoot) /* TRANSACTIONAL */
#endif
            {
                //
                // NOTE: Cleanup any leftover open scopes from the uplevel.
                //       We MUST do this here because otherwise the pop below
                //       will fail to pop the uplevel call frame from the
                //       stack, thereby permanently unbalancing it.
                //
                /* IGNORED */
                PopScopeCallFrames();

                //
                // NOTE: Exit the current uplevel call frame and restore
                //       the uplevel call frame saved earlier.
                //
                ExitUplevelCallFrame(ref savedFrame);

                //
                // NOTE: Now unlink the [uplevel] call frame from the old call
                //       frame (i.e. the one that was the current call frame
                //       prior to the [uplevel] call frame being pushed).
                //
                if (oldFrame != null)
                    oldFrame.Other = null;

                //
                // NOTE: Now pop the top call frame, which should be the
                //       uplevel call frame.
                //
                ICallFrame popFrame = PopCallFrame();

                //
                // NOTE: Return the call frame we just popped.
                //
                return popFrame;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Automatic (Engine)
        /// <summary>
        /// This method determines whether an automatic call frame should be
        /// popped from the call stack of the specified interpreter, based on
        /// whether the call frame at the top of the call stack differs from the
        /// specified call frame.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose call stack is to be examined.
        /// </param>
        /// <param name="oldFrame">
        /// The call frame that was current prior to any automatic call frame
        /// being pushed.
        /// </param>
        /// <returns>
        /// True if an automatic call frame should be popped; otherwise, false.
        /// </returns>
        internal static bool ShouldPopAutomaticCallFrame( /* EXIT POINT */
            Interpreter interpreter,
            ICallFrame oldFrame
            )
        {
            if (interpreter == null)
                return false;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return false;

                if (oldFrame == null)
                    return false;

                if (!interpreter.CanPeekCallFrame())
                    return false;

                return !CallFrameOps.IsSame(
                    oldFrame, interpreter.PeekCallFrame());
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method pops any leftover open scope call frames and then, if
        /// present, a single automatic call frame from the top of the call
        /// stack of the specified interpreter, resetting the procedure and
        /// uplevel call frames if either was popped.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose call stack is to be modified.
        /// </param>
        /// <param name="usable">
        /// Upon return, this parameter is set to zero if a disposed call frame
        /// was encountered, indicating the call stack may be in an inconsistent
        /// state.
        /// </param>
        /// <returns>
        /// The automatic call frame that was popped, or null if none was
        /// popped.
        /// </returns>
        internal static ICallFrame PopAutomaticCallFrame( /* EXIT POINT */
            Interpreter interpreter,
            ref bool usable
            )
        {
            if (interpreter == null)
                return null;

            lock (interpreter.InternalSyncRoot) /* TRANSACTIONAL */
            {
                if (interpreter.PrivateDisposed)
                    return null;

                //
                // NOTE: Cleanup any leftover open scopes from the procedure.  We
                //       MUST do this here because otherwise the pop below will
                //       fail to pop the procedure call frame from the stack,
                //       thereby permanently unbalancing it.
                //
                /* IGNORED */
                interpreter.PopScopeCallFrames(ref usable);

                if (!usable)
                    return null;

                //
                // NOTE: If the top of the call stack is an automatic call frame,
                //       that means it was not cleaned up by the code associated
                //       with originally pushing it.  In that case, pop it now;
                //       however, make sure that a maximum of one such call frame
                //       is popped.
                //
                ICallFrame popFrame = interpreter.PopCallFrames(
                    CallFrameFlags.Automatic, 1, true, ref usable);

                if (!usable)
                    return null;

                //
                // NOTE: If the current procedure call frame was just popped, then
                //       it must be reset it as well.
                //
                if (CallFrameOps.IsSame(popFrame, interpreter.ProcedureFrame))
                    interpreter.ProcedureFrame = null;

                //
                // NOTE: If the current uplevel call frame was just popped, then
                //       it must be reset it as well.
                //
                if (CallFrameOps.IsSame(popFrame, interpreter.UplevelFrame))
                    interpreter.UplevelFrame = null;

                //
                // NOTE: Always return the call frame that was just popped, if any.
                //
                return popFrame;
            }
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Reset (Emergency Use Only)
        //
        // HACK: *WARNING* This method is a very lightly tested way of forcing
        //       the call stack for the interpreter to be completely reset to
        //       its initial state (i.e. with only the global frame present).
        //       It must not be called while a script is being evaluated using
        //       the interpreter (from any thread); otherwise, the results are
        //       undefined.  Since this method is private, it can only be used
        //       via reflection.  If this method fails, the interpreter may be
        //       in an inconsistent state (e.g. its call stack may be unusable
        //       for script evaluation).
        //
        /// <summary>
        /// This method forcibly resets the call stack for this interpreter back
        /// to its initial state, with only the global call frame present.  It is
        /// intended for emergency use only and must not be called while a script
        /// is being evaluated.
        /// </summary>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message that
        /// describes the reason the call stack could not be reset.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode ResetCallStackAndFrames(
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (disposed)
                {
                    error = "attempt to call eval in disposed interpreter";
                    return ReturnCode.Error;
                }

                CallStack callStack = CallStack;
                ICallFrame peekFrame = null;

                while (true)
                {
                    if (!CallFrameOps.CanPeekOrPop(callStack, ref peekFrame))
                        break;

                    if (IsGlobalCallFrame(peekFrame))
                        break;

                    /* IGNORED */
                    PopCallFrame();
                }

                if (!IsGlobalCallFrame(peekFrame))
                {
                    error = "final peeked call frame is not global";
                    return ReturnCode.Error;
                }

                if (!IsGlobalCallFrame(PopCallFrameNoThrow(false)))
                {
                    error = "final popped call frame is not global";
                    return ReturnCode.Error;
                }

                if (!CallFrameOps.IsEmpty(callStack, true))
                {
                    error = "call stack is not empty";
                    return ReturnCode.Error;
                }

                PreSetupCallFramesPhase2();
                return ReturnCode.Ok;
            }
        }
        #endregion
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ICallFrame (Scope)
        /// <summary>
        /// This method looks up the innermost open scope call frame, optionally
        /// popping it from the call stack and removing it from the interpreter.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to look up, or null to match the innermost
        /// open scope regardless of its name.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the scope is looked up, including whether
        /// a verbose error message is produced.
        /// </param>
        /// <param name="pop">
        /// Non-zero to pop the matching call frame from the call stack.
        /// </param>
        /// <param name="remove">
        /// Non-zero to remove the matching scope from the interpreter.
        /// </param>
        /// <param name="frame">
        /// Upon success, this parameter receives the matching scope call frame.
        /// </param>
        /// <param name="list">
        /// Upon success, this parameter receives the list of names detached
        /// from the scope when it is removed.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode GetScopeCallFrame(
            string name,
            LookupFlags lookupFlags,
            bool pop,
            bool remove,
            ref ICallFrame frame,
            ref StringList list
            )
        {
            Result error = null;

            return GetScopeCallFrame(
                name, lookupFlags, pop, remove, ref frame, ref list, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up the innermost open scope call frame, optionally
        /// popping it from the call stack and removing it from the interpreter,
        /// reporting any error encountered.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to look up, or null to match the innermost
        /// open scope regardless of its name.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the scope is looked up, including whether
        /// a verbose error message is produced.
        /// </param>
        /// <param name="pop">
        /// Non-zero to pop the matching call frame from the call stack.
        /// </param>
        /// <param name="remove">
        /// Non-zero to remove the matching scope from the interpreter.
        /// </param>
        /// <param name="frame">
        /// Upon success, this parameter receives the matching scope call frame.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message that
        /// describes the reason for the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode GetScopeCallFrame(
            string name,
            LookupFlags lookupFlags,
            bool pop,
            bool remove,
            ref ICallFrame frame,
            ref Result error
            )
        {
            StringList list = null;

            return GetScopeCallFrame(
                name, lookupFlags, pop, remove, ref frame, ref list, ref error);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method looks up the innermost open scope call frame, optionally
        /// popping it from the call stack and removing it from the interpreter,
        /// reporting the detached name list and any error encountered.  This is
        /// the core implementation used by the other overloads.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to look up, or null to match the innermost
        /// open scope regardless of its name.
        /// </param>
        /// <param name="lookupFlags">
        /// The flags that control how the scope is looked up, including whether
        /// a verbose error message is produced.
        /// </param>
        /// <param name="pop">
        /// Non-zero to pop the matching call frame from the call stack.
        /// </param>
        /// <param name="remove">
        /// Non-zero to remove the matching scope from the interpreter.
        /// </param>
        /// <param name="frame">
        /// Upon success, this parameter receives the matching scope call frame.
        /// </param>
        /// <param name="list">
        /// Upon success, this parameter receives the list of names detached
        /// from the scope when it is removed.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message that
        /// describes the reason for the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        private ReturnCode GetScopeCallFrame(
            string name,
            LookupFlags lookupFlags,
            bool pop,
            bool remove,
            ref ICallFrame frame,
            ref StringList list,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                if (!PrivateHasScopes(ref error))
                    return ReturnCode.Error;

                //
                // NOTE: Grab the current call frame without popping it.
                //
                ICallFrame newFrame = PeekCallFrame();

                //
                // NOTE: We cannot follow linked call frames if we
                //       intend to pop the innermost scope call frame.
                //
                if (!pop)
                    newFrame = CallFrameOps.FollowNext(newFrame);

                //
                // NOTE: Is the current call frame valid?
                //
                if (newFrame == null)
                {
                    error = "invalid call frame";
                    return ReturnCode.Error;
                }

                if (!newFrame.IsUsable(ref error))
                    return ReturnCode.Error;

                //
                // NOTE: Is this a [scope] created persistent call frame (i.e.
                //       one that was created by [scope], but not by [scope
                //       eval]).
                //
                CallFrameFlags frameFlags = newFrame.Flags;

                if (!FlagOps.HasFlags(frameFlags, CallFrameFlags.Scope, true) ||
                    FlagOps.HasFlags(frameFlags, CallFrameFlags.Evaluate, true))
                {
                    error = "no scopes are open";
                    return ReturnCode.Error;
                }

                //
                // NOTE: Does the provided scope name, if any, match?
                //
                if ((name == null) ||
                    SharedStringOps.SystemEquals(newFrame.Name, name))
                {
                    //
                    // NOTE: Pop the call frame from the call stack?
                    //
                    if (pop)
                    {
                        //
                        // NOTE: We know the call stack has not changed here
                        //       because we are holding the interpreter lock.
                        //
                        frame = PopCallFrame(); // return and remove it.

#if DEBUG
                        //
                        // NOTE: Check that the popped call frame matches the one
                        //       that we were expecting to pop.
                        //
                        if (IsCallStackStrict() &&
                            !CallFrameOps.IsSame(frame, newFrame))
                        {
                            ThrowInvalidCallStack(ReturnCode.Error,
                                "popped call frame does not match expected");
                        }
#endif
                    }
                    else
                    {
                        frame = newFrame; // just return it.
                    }

                    //
                    // NOTE: Remove the call frame from the interpreter?
                    //
                    if (remove)
                    {
                        if (NamespaceOps.DetachScope(
                                this, null, newFrame, ref list,
                                ref error) != ReturnCode.Ok)
                        {
                            return ReturnCode.Error;
                        }

                        /* IGNORED */
                        scopes.Remove(newFrame.Name);
                    }

                    return ReturnCode.Ok;
                }
                else
                {
                    error = FlagOps.HasFlags(
                        lookupFlags, LookupFlags.Verbose, true) ?
                        String.Format(
                            "scope {0} is not innermost",
                            FormatOps.WrapOrNull(name)) :
                        "scope is not innermost";

                    return ReturnCode.Error;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method copies the formal argument variables of the enclosing
        /// procedure into the specified scope call frame so that they are
        /// accessible from within the scope.
        /// </summary>
        /// <param name="frame">
        /// The scope call frame to receive the copied argument variables.
        /// </param>
        /// <param name="merge">
        /// Non-zero to overwrite any existing variables in the call frame; zero
        /// to copy only those that do not already exist.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message that
        /// describes the reason for the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode CopyProcedureArgumentsToFrame(
            ICallFrame frame,
            bool merge,
            ref Result error
            )
        {
            ArgumentList frameArguments = null;
            bool useNamedArguments = false;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                ICallFrame procedureFrame = ProcedureFrame;

                //
                // NOTE: Steal the arguments from the containing procedure;
                //       otherwise, we cannot access them from the [scope].
                //
                if (procedureFrame != null)
                {
                    ArgumentList procedureArguments =
                        procedureFrame.ProcedureArguments;

                    if (procedureArguments != null)
                    {
                        frameArguments = new ArgumentList(
                            procedureArguments);

                        IProcedure procedure =
                            procedureFrame.Execute as IProcedure;

                        if (EntityOps.IsNamedArguments(procedure))
                            useNamedArguments = true;
                    }
                }
            }

            ReturnCode code = ReturnCode.Ok;

            if ((frame != null) && (frameArguments != null))
            {
                //
                // NOTE: Create variables for each of the formal arguments
                //       to the enclosing procedure.  Start the counting at
                //       one to skip the procedure name itself.
                //
                VariableDictionary variables = frame.Variables;

                if (useNamedArguments)
                {
                    for (int argumentIndex = 1;
                            argumentIndex < frameArguments.Count; argumentIndex += 2)
                    {
                        Argument nameArgument = frameArguments[argumentIndex];

                        if (nameArgument == null)
                            continue;

                        string varName = StringOps.GetStringFromObject(nameArgument);

                        if (merge || !variables.ContainsKey(varName))
                        {
                            Argument valueArgument = frameArguments[argumentIndex + 1];
                            object varValue = null;

                            if (valueArgument != null)
                                varValue = valueArgument.Value;

                            IVariable frameVariable = null; /* NOT USED */

                            code = SetVariableValue2(
                                VariableFlags.Argument, frame, varName, null,
                                varValue, null, ref frameVariable, ref error);

                            if (code != ReturnCode.Ok)
                                break;
                        }
                    }
                }
                else
                {
                    for (int argumentIndex = 1;
                            argumentIndex < frameArguments.Count; argumentIndex++)
                    {
                        Argument frameArgument = frameArguments[argumentIndex];

                        if (frameArgument == null)
                            continue;

                        string varName = frameArgument.Name;

                        if (merge || !variables.ContainsKey(varName))
                        {
                            object varValue = frameArgument.Value;
                            IVariable frameVariable = null; /* NOT USED */

                            code = SetVariableValue2(
                                VariableFlags.Argument, frame, varName, null,
                                varValue, null, ref frameVariable, ref error);

                            if (code != ReturnCode.Ok)
                                break;
                        }
                    }
                }

                //
                // NOTE: Finally, update the arguments for the call frame so
                //       that things like [info level] will work properly.
                //
                if (code == ReturnCode.Ok)
                    frame.Arguments = frameArguments;
            }

            return code;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes that the interpreter lock is held.
        //
        /// <summary>
        /// This method promotes the named scope call frame to be the current
        /// global scope call frame, pushing it onto the call stack and marking
        /// the existing global frame as invisible.  This method assumes that
        /// the interpreter lock is held.
        /// </summary>
        /// <param name="name">
        /// The name of the scope to promote to the global scope call frame.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message that
        /// describes the reason for the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode SetGlobalScopeCallFrame(
            string name,
            ref Result error
            )
        {
            ICallFrame frame = null;

            if (GetScope(
                    name, LookupFlags.Default, ref frame,
                    ref error) == ReturnCode.Ok)
            {
                if (CallFrameOps.MarkGlobalScope(frame, ref error))
                {
                    //
                    // NOTE: First, set the global scope call frame
                    //       to the named scope call frame specified
                    //       by the caller.  Then, since it will now
                    //       be considered the current global frame,
                    //       push it onto the call stack, all while
                    //       leaving the existing global frame on
                    //       the call stack as well.
                    //
                    GlobalScopeFrame = frame;
                    PushGlobalCallFrame(false);

                    //
                    // NOTE: Finally, temporarily mark the global
                    //       frame as invisible so it will not work
                    //       for [uplevel 1], etc.
                    //
                    ICallFrame globalFrame = GlobalFrame; /* EXEMPT */

                    if (globalFrame != null)
                        globalFrame.Flags |= CallFrameFlags.Invisible;

                    return ReturnCode.Ok;
                }
            }

            return ReturnCode.Error;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes that the interpreter lock is held.
        //
        /// <summary>
        /// This method demotes the current global scope call frame, popping it
        /// from the call stack and restoring normal use of the regular global
        /// frame, while leaving the scope intact for later use.  This method
        /// assumes that the interpreter lock is held.
        /// </summary>
        /// <param name="strict">
        /// Non-zero to treat the absence of a global scope call frame as an
        /// error; zero to treat it as success.
        /// </param>
        /// <param name="error">
        /// Upon failure, this parameter receives an error message that
        /// describes the reason for the failure.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an appropriate
        /// error code.
        /// </returns>
        internal ReturnCode UnsetGlobalScopeCallFrame(
            bool strict,
            ref Result error
            )
        {
            ICallFrame globalScopeFrame = GlobalScopeFrame;

            if (globalScopeFrame != null)
            {
                CallFrameFlags newFlags = CallFrameFlags.None;

                if (CallFrameOps.GetNonGlobalScopeFlags(
                        globalScopeFrame, ref newFlags, ref error))
                {
                    //
                    // NOTE: First, remove temporary mark of global
                    //       frame as invisible, to restore normal
                    //       functioning of [uplevel], etc.
                    //
                    ICallFrame globalFrame = GlobalFrame; /* EXEMPT */

                    if (globalFrame != null)
                        globalFrame.Flags &= ~CallFrameFlags.Invisible;

                    //
                    // NOTE: Next, pop the global scope call frame
                    //       from the call stack.  If the top call
                    //       frame is not really the global scope
                    //       call frame, the results are undefined.
                    //       Next, reset the global scope frame to
                    //       null, which allows the normal global
                    //       frame to be used again.
                    //
                    PopGlobalCallFrame(false);
                    GlobalScopeFrame = null;

                    //
                    // NOTE: Finally, reset the flags for the scope
                    //       call frame, leaving it intact for later
                    //       use with the [scope] command and then
                    //       return success to the caller.
                    //
                    globalScopeFrame.Flags = newFlags;
                    return ReturnCode.Ok;
                }
            }
            else if (!strict)
            {
                return ReturnCode.Ok;
            }
            else
            {
                error = "global scope call frame not set";
            }

            return ReturnCode.Error;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region ICallFrame (Factory)
        /// <summary>
        /// This method creates a new call frame suitable for executing a
        /// procedure, automatically resolving the parent namespace from the
        /// procedure name when namespaces are enabled.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new call frame.
        /// </param>
        /// <param name="flags">
        /// The flags to assign to the new call frame.
        /// </param>
        /// <param name="auxiliaryData">
        /// The optional auxiliary client data to associate with the new call
        /// frame.
        /// </param>
        /// <param name="execute">
        /// The entity, typically a procedure, being executed within the new
        /// call frame.
        /// </param>
        /// <param name="arguments">
        /// The arguments to associate with the new call frame.
        /// </param>
        /// <returns>
        /// The newly created call frame.  This method never returns null.
        /// </returns>
        internal ICallFrame NewProcedureCallFrame(
            string name,
            CallFrameFlags flags,
            IClientData auxiliaryData,
            IExecute execute,
            ArgumentList arguments
            ) /* CANNOT RETURN NULL */
        {
            INamespace @namespace = null;

            if (InternalAreNamespacesEnabled())
                @namespace = NamespaceOps.LookupParent(this, name, false, true, false);

            return NewProcedureCallFrame(
                name, flags, auxiliaryData, execute, arguments, @namespace);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new call frame suitable for executing a
        /// procedure within the specified namespace, applying any extra call
        /// frame flags implied by the procedure flags.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new call frame.
        /// </param>
        /// <param name="flags">
        /// The flags to assign to the new call frame.
        /// </param>
        /// <param name="auxiliaryData">
        /// The optional auxiliary client data to associate with the new call
        /// frame.
        /// </param>
        /// <param name="execute">
        /// The entity, typically a procedure, being executed within the new
        /// call frame.
        /// </param>
        /// <param name="arguments">
        /// The arguments to associate with the new call frame.
        /// </param>
        /// <param name="namespace">
        /// The namespace to associate with the new call frame, or null to use
        /// the current resolver data.
        /// </param>
        /// <returns>
        /// The newly created call frame.  This method never returns null.
        /// </returns>
        private ICallFrame NewProcedureCallFrame(
            string name,
            CallFrameFlags flags,
            IClientData auxiliaryData,
            IExecute execute,
            ArgumentList arguments,
            INamespace @namespace
            ) /* CANNOT RETURN NULL */
        {
            CallStack callStack = CallStack;
            CallFrameFlags extraFlags = CallFrameFlags.None;
            IProcedure procedure = execute as IProcedure;

            if (procedure != null)
            {
                ProcedureFlags procedureFlags = procedure.Flags;

                if (FlagOps.HasFlags(
                        procedureFlags, ProcedureFlags.Library, true))
                {
                    extraFlags |= CallFrameFlags.Library;
                }

                if (FlagOps.HasFlags(
                        procedureFlags, ProcedureFlags.Fast, true))
                {
                    extraFlags |= CallFrameFlags.Fast;
                }

                if (FlagOps.HasFlags(
                        procedureFlags, ProcedureFlags.MatchTypes, true))
                {
                    extraFlags |= CallFrameFlags.MatchTypes;
                }
            }

            return new CallFrame(
                NextId(), 0, name, null,
                (callStack != null) ? callStack.Count + 1 : 0, InternalLevels,
                flags | extraFlags, auxiliaryData, (@namespace != null) ?
                new ResolverClientData(@namespace) : CurrentResolveData,
                null, execute, arguments, false);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new namespace call frame using the current
        /// resolver data and a fresh set of variables.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new call frame.
        /// </param>
        /// <param name="flags">
        /// The flags to assign to the new call frame.
        /// </param>
        /// <param name="arguments">
        /// The arguments to associate with the new call frame.
        /// </param>
        /// <returns>
        /// The newly created call frame.
        /// </returns>
        internal ICallFrame NewNamespaceCallFrame(
            string name,
            CallFrameFlags flags,
            ArgumentList arguments
            )
        {
            return NewNamespaceCallFrame(name, flags, arguments, null, true);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new namespace call frame associated with the
        /// specified namespace, optionally giving it a fresh set of variables.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new call frame.
        /// </param>
        /// <param name="flags">
        /// The flags to assign to the new call frame.
        /// </param>
        /// <param name="arguments">
        /// The arguments to associate with the new call frame.
        /// </param>
        /// <param name="namespace">
        /// The namespace to associate with the new call frame, or null to use
        /// the current resolver data.
        /// </param>
        /// <param name="newVariables">
        /// Non-zero to give the new call frame its own fresh set of variables.
        /// </param>
        /// <returns>
        /// The newly created call frame.
        /// </returns>
        internal ICallFrame NewNamespaceCallFrame(
            string name,
            CallFrameFlags flags,
            ArgumentList arguments,
            INamespace @namespace,
            bool newVariables
            )
        {
            CallStack callStack = CallStack;

            return new CallFrame(
                NextId(), 0, name, null,
                (callStack != null) ? callStack.Count + 1 : 0, InternalLevels,
                flags | CallFrameFlags.Namespace, null, null, (@namespace != null) ?
                new ResolverClientData(@namespace) : CurrentResolveData,
                null, null, null, arguments, false, newVariables);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new namespace call frame associated with the
        /// global namespace and the specified entity to execute.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new call frame.
        /// </param>
        /// <param name="flags">
        /// The flags to assign to the new call frame.
        /// </param>
        /// <param name="execute">
        /// The entity being executed within the new call frame.
        /// </param>
        /// <param name="arguments">
        /// The arguments to associate with the new call frame.
        /// </param>
        /// <returns>
        /// The newly created call frame.
        /// </returns>
        private ICallFrame NewNamespaceCallFrame( /* NOT USED */
            string name,
            CallFrameFlags flags,
            IExecute execute,
            ArgumentList arguments
            )
        {
            CallStack callStack = CallStack;

            return new CallFrame(
                NextId(), 0, name, null,
                (callStack != null) ? callStack.Count + 1 : 0, InternalLevels,
                flags | CallFrameFlags.Namespace, null, null, (globalNamespace != null) ?
                new ResolverClientData(globalNamespace) : CurrentResolveData,
                null, null, execute, arguments, false, false);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new tracking call frame, linked to the current
        /// call frame, using the current resolver data.
        /// </summary>
        /// <param name="name">
