        /// </returns>
        internal ICallFrame NewTrackingCallFrame(
            string name,
            CallFrameFlags flags
            )
        {
            return NewTrackingCallFrame(name, flags, CurrentResolveData);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new tracking call frame, linked to the current
        /// call frame, using the specified resolver data.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new call frame.
        /// </param>
        /// <param name="flags">
        /// The flags to assign to the new call frame.
        /// </param>
        /// <param name="resolveData">
        /// The resolver client data to associate with the new call frame.
        /// </param>
        /// <returns>
        /// The newly created call frame.
        /// </returns>
        private ICallFrame NewTrackingCallFrame(
            string name,
            CallFrameFlags flags,
            IClientData resolveData
            )
        {
            return NewLinkedCallFrame(
                name, 0, flags | CallFrameFlags.Tracking, resolveData,
                null, null, CurrentFrame);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method creates a new engine call frame, linked to the current
        /// call frame, using the current resolver data.
        /// </summary>
        /// <param name="name">
        /// The name to assign to the new call frame.
        /// </param>
        /// <param name="flags">
