        internal PluginFlags PluginFlags
        {
            get { lock (syncRoot) { return pluginFlags; } }
            set
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    pluginFlags = value;

#if ENTERPRISE_LOCKDOWN || MAYBE_ENTERPRISE_LOCKDOWN
                    if (IsEnterpriseLockdownEnabled())
                        EnforceLockdownForPlugins();
#endif
                }
            }
