        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method temporarily enables loading plugins on any thread,
        /// saving the previous plugin flags so that they can be restored later.
        /// </summary>
        /// <param name="savedPluginFlags">
        /// Upon return, this parameter receives the plugin flags that were in
        /// effect prior to this call.
        /// </param>
        internal void BeginLoadOnAnyThread(
            out PluginFlags savedPluginFlags
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                savedPluginFlags = pluginFlags;
                pluginFlags |= PluginFlags.LoadOnAnyThread;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method restores the plugin flags that were saved by a prior
        /// call to <c>BeginLoadOnAnyThread</c>, ending the temporary ability to
        /// load plugins on any thread.
        /// </summary>
        /// <param name="savedPluginFlags">
        /// The previously saved plugin flags to restore.  Upon return, this
        /// parameter is reset to <see cref="PluginFlags.None" />.
        /// </param>
        internal void EndLoadOnAnyThread(
            ref PluginFlags savedPluginFlags
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                pluginFlags = savedPluginFlags;
                savedPluginFlags = PluginFlags.None;
            }
        }

