#if SHELL
        /// <summary>
        /// This method adjusts certain default flags that are disabled for
        /// non-interactive use, immediately before entering the interactive
        /// loop.
        /// </summary>
        /// <returns>
        /// The number of flag sets that were modified.
        /// </returns>
        private int MaybeChangeFlagsForInteractiveUse()
        {
            //
            // NOTE: This method is only called right before entering
            //       the interactive loop.  Therefore, we know it is
            //       safe to remove the (various?) default flags that
            //       are disabled for non-interactive use.
            //
            int count = 0;

            lock (syncRoot) /* TRANSACTIONAL */
            {
                //
                // NOTE: Since we are about to enter the interactive
                //       loop, enable plugin update checks; however,
                //       only do this if the plugin flags have not
                //       been (somehow?) modified via script library
                //       initialization.
                //
                if (ScriptOps.AreTypicalPluginFlagsInUse(pluginFlags, true))
                {
                    pluginFlags &= ~PluginFlags.NonInteractiveMask;
                    count++;
                }
            }

            return count;
        }
#endif

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Ready Flags
        /// <summary>
        /// This method attempts to retrieve the ready flags for the specified
        /// interpreter, using <see cref="ReadyFlags.Unknown" /> when they
        /// cannot be determined.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose ready flags are to be retrieved.
        /// </param>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait to acquire the
        /// interpreter lock.
        /// </param>
        /// <param name="useEngine">
        /// Non-zero to also include the ready flags derived from the engine
        /// flags of the interpreter.
        /// </param>
        /// <returns>
        /// The ready flags for the interpreter, or the default value when they
        /// cannot be determined.
        /// </returns>
        private static ReadyFlags TryGetReadyFlags(
            Interpreter interpreter,
            int timeout,
            bool useEngine
            )
        {
            return TryGetReadyFlags(
                interpreter, timeout, ReadyFlags.Unknown, useEngine);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method attempts to retrieve the ready flags for the specified
        /// interpreter, returning the supplied default value when they cannot be
        /// determined.  It will not block longer than the specified timeout when
        /// acquiring the interpreter lock.
        /// </summary>
        /// <param name="interpreter">
        /// The interpreter whose ready flags are to be retrieved.
        /// </param>
        /// <param name="timeout">
        /// The maximum number of milliseconds to wait to acquire the
        /// interpreter lock.
        /// </param>
        /// <param name="default">
        /// The value to return when the ready flags cannot be determined.
        /// </param>
        /// <param name="useEngine">
        /// Non-zero to also include the ready flags derived from the engine
        /// flags of the interpreter.
        /// </param>
        /// <returns>
        /// The ready flags for the interpreter, or the default value when they
        /// cannot be determined.
        /// </returns>
        private static ReadyFlags TryGetReadyFlags(
            Interpreter interpreter,
            int timeout,
            ReadyFlags @default,
            bool useEngine
            )
        {
            if (interpreter == null)
                return @default;

            ///////////////////////////////////////////////////////////////////
            //
            // BUGFIX: Do not use the public SyncRoot property here (in case we
            //         have been disposed), use the internal property instead.
            //
            bool locked = false;
            object syncRoot = interpreter.InternalSyncRoot;

            if (syncRoot == null)
                return @default;

            try
            {
                //
                // BUGFIX: *THREADING* Allow the callers to specify a timeout
                //         to avoid potential deadlocks here in some cases.
                //
                locked = Monitor.TryEnter(syncRoot, timeout);
                interpreter.MaybeSomebodyHasLock(locked);

                //
                // NOTE: We cannot check if the interpreter is actually ready;
                //       therefore, return failure.
                //
                if (!locked)
                    return @default;

                //
                // NOTE: We absolutely cannot continue if the interpreter has
                //       been disposed because that means there will be no
                //       engine context, which is required for checking the
                //       native stack space, among other things.  This is
                //       always checked because using a disposed interpreter
                //       is considered to be a serious programming error.
                //
                if (interpreter.PrivateDisposed)
                    return @default;

                //
                // NOTE: Start out with the ready flags for the interpreter.
                //       Then, optionally add the ready flags for the engine
                //       flags for the interpreter.
                //
                ReadyFlags result = interpreter.PrivateReadyFlags;

                if (useEngine)
                    result |= Engine.GetReadyFlags(interpreter.EngineFlags);

                //
                // NOTE: Return the ready flags for the interpreter.
                //
                return result;
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.EngineError);
            }
            finally
            {
                if (locked)
                {
                    interpreter.MaybeNobodyHasLock(locked);
                    Monitor.Exit(syncRoot);
                }
            }

            return @default;
        }
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

