                        if (stringListCache.ContainsKey(text))
                        {
#if CACHE_STATISTICS
                            /* IGNORED */
                            stringListCache.IncrementCacheCount(CacheCountType.Collide);
#endif

                            return false;
                        }

                        stringListCache.Add(text, list);

#if CACHE_STATISTICS
                        /* IGNORED */
                        stringListCache.IncrementCacheCount(CacheCountType.Add);
#endif

                        return true;
                    }
                }
            }

            return false;
        }

