        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Core Trace Callbacks
        #region Support Methods
        /// <summary>
        /// This method configures the specified trace information so that a
        /// variable "get" operation is canceled and completed using the
        /// specified return code and original value.
        /// </summary>
        /// <param name="traceInfo">
        /// The trace information to configure; if it is null, this method does
        /// nothing.
        /// </param>
        /// <param name="code">
        /// The return code to record on the trace information.
        /// </param>
        /// <param name="oldValue">
        /// The original value to record on the trace information.
        /// </param>
        private static void SetTraceInfoForGetResult(
            ITraceInfo traceInfo,
            ReturnCode code,
            object oldValue
            )
        {
            if (traceInfo != null)
            {
                traceInfo.OldValue = oldValue;
                traceInfo.Cancel = true;
                traceInfo.ReturnCode = code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method configures the specified trace information so that a
        /// variable "get" operation is canceled and completed using the
        /// specified return code and result, converting the result to its
        /// string form.
        /// </summary>
        /// <param name="traceInfo">
        /// The trace information to configure; if it is null, this method does
        /// nothing.
        /// </param>
        /// <param name="code">
        /// The return code to record on the trace information.
        /// </param>
        /// <param name="result">
        /// The result whose string form is recorded on the trace information as
        /// the original value.
        /// </param>
        private static void SetTraceInfoForGetResult(
            ITraceInfo traceInfo,
            ReturnCode code,
            Result result
            )
        {
            SetTraceInfoForGetResult(traceInfo, code,
                (object)StringOps.GetStringFromObject(result));
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method configures the specified trace information and overall
        /// result so that a variable "set" operation is canceled and completed
        /// using the specified values and return code, marking the variable as
        /// defined and dirty.
        /// </summary>
        /// <param name="traceInfo">
        /// The trace information to configure; if it is null, this method does
        /// nothing.
        /// </param>
        /// <param name="variable">
        /// The variable being set, which is marked as defined and dirty.
        /// </param>
        /// <param name="oldValue">
        /// The original value to record on the trace information.
        /// </param>
        /// <param name="newValue">
        /// The new value to record on the trace information and to use when
        /// producing the result.
        /// </param>
        /// <param name="code">
        /// The return code to record on the trace information.
        /// </param>
        /// <param name="result">
        /// Upon return, receives the result produced from the new value.
        /// </param>
        private static void SetTraceInfoForSetResult(
            ITraceInfo traceInfo,
            IVariable variable,
            object oldValue,
            object newValue,
            ReturnCode code,
            ref Result result
            )
        {
            //
            // HACK: This result is not 100% correct;
            //       however, we do not really care.
            //       Firstly, setting the overall
            //       result is entirely optional for
            //       trace callbacks that "succeed".
            //       Secondly, using FixupReturnValue
            //       (or similar) method here would
            //       potentially create opaque object
            //       handles which would then just be
            //       leaked because they would never
            //       actually even be seen by the
            //       calling script.  At some point,
            //       it might be worthwhile to use
            //       the FixupReturnValue method here
            //       with the value of the toString
            //       parameter hard-wired to true.
            //
            result = StringOps.GetResultFromObject(newValue);

            EntityOps.SetUndefined(variable, false);
            EntityOps.SetDirty(variable, true);

            if (traceInfo != null)
            {
                traceInfo.OldValue = oldValue;
                traceInfo.NewValue = newValue;
                traceInfo.Cancel = true;
                traceInfo.ReturnCode = code;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified variable is forbidden
        /// from participating in an array copy operation because it is backed
        /// by special, externally managed storage.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <returns>
        /// True if the variable is forbidden from array copy operations;
        /// otherwise, false.
        /// </returns>
        internal bool IsForbiddenVariableForArrayCopy(
            IVariable variable
            )
        {
            // CheckDisposed();

            if (IsEnvironmentVariable(variable))
                return true;

            if (IsTestsVariable(variable))
                return true;

#if DATA
            if (IsDatabaseVariable(variable))
                return true;
#endif

#if NETWORK && WEB
            if (IsNetworkVariable(variable))
                return true;
#endif

#if !NET_STANDARD_20 && WINDOWS
            if (IsRegistryVariable(variable))
                return true;
#endif

            if (IsThreadVariable(variable))
                return true;

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified variable is one of the
        /// special variables managed by built-in trace callbacks.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <returns>
        /// True if the variable is a special variable; otherwise, false.
        /// </returns>
        internal bool IsSpecialVariable(
            IVariable variable
            )
        {
            // CheckDisposed();

            if (IsAutoPathVariable(variable))
                return true;

            if (IsPrecisionVariable(variable))
                return true;

            if (IsEnvironmentVariable(variable))
                return true;

            if (IsTestsVariable(variable))
                return true;

            if (IsSystemArrayVariable(variable))
                return true;

#if DATA
            if (IsDatabaseVariable(variable))
                return true;
#endif

#if NETWORK && WEB
            if (IsNetworkVariable(variable))
                return true;
#endif

#if !NET_STANDARD_20 && WINDOWS
            if (IsRegistryVariable(variable))
                return true;
#endif

            if (IsThreadVariable(variable))
                return true;

            if (IsLinkedVariable(variable))
                return true;

            if (IsEnumerableVariable(variable))
                return true;

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: This method assumes the interpreter lock is already held.
        //
        /// <summary>
        /// This method determines whether the specified list of traces contains
        /// all of the applicable built-in variable trace callbacks.  This
        /// method assumes the interpreter lock is already held.
        /// </summary>
        /// <param name="traces">
        /// The list of traces to examine.
        /// </param>
        /// <param name="globalOnly">
        /// Non-zero to consider only the trace callbacks that apply to global
        /// variables.
        /// </param>
        /// <returns>
        /// True if all of the applicable built-in trace callbacks are present;
        /// otherwise, false.
        /// </returns>
        private bool HasVariableTraces(
            TraceList traces, /* in */
            bool globalOnly   /* in */
            )
        {
            if (traces == null)
                return false;

            if (!globalOnly && (autoPathTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, autoPathTraceList))
            {
                return false;
            }

            if (!globalOnly && (environmentTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, environmentTraceList))
            {
                return false;
            }

            if (!globalOnly && (enumerableVariableTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, enumerableVariableTraceList))
            {
                return false;
            }

            if (!globalOnly && (linkedVariableTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, linkedVariableTraceList))
            {
                return false;
            }

            if (!globalOnly && (systemArrayTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, systemArrayTraceList))
            {
                return false;
            }

            if ((objectTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, objectTraceList))
            {
                return false;
            }

            if (!globalOnly && (precisionTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, precisionTraceList))
            {
                return false;
            }

            if (!globalOnly && (testsTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, testsTraceList))
            {
                return false;
            }

#if DATA
            if (!globalOnly && (dbTraceList != null) &&
                !ScriptOps.HasTraceCallbacks(traces, dbTraceList))
            {
                return false;
            }
#endif

            return true;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified list of traces contains
        /// all of the built-in trace callbacks that would normally be added to
        /// a variable.
        /// </summary>
        /// <param name="traces">
        /// The list of traces to examine.
        /// </param>
        /// <param name="globalOnly">
        /// Non-zero to consider only the trace callbacks that apply to global
        /// variables.
        /// </param>
        /// <returns>
        /// True if all of the expected built-in trace callbacks are present;
        /// otherwise, false.
        /// </returns>
        internal static bool HasTraceCallbacks(
            TraceList traces, /* in */
            bool globalOnly   /* in */
            )
        {
            if (traces == null)
                return false;

            List<TraceCallback> callbacks = new List<TraceCallback>();

            callbacks.Add(ObjectTraceCallback);

            if (!globalOnly)
            {
                callbacks.Add(AutoPathTraceCallback);
                callbacks.Add(EnvironmentTraceCallback);
                callbacks.Add(EnumerableVariableTraceCallback);
                callbacks.Add(LinkedVariableTraceCallback);
                callbacks.Add(SystemArrayTraceCallback);
                callbacks.Add(PrecisionTraceCallback);
                callbacks.Add(TestsTraceCallback);
            }

            foreach (TraceCallback callback in callbacks) /* O(N) */
            {
                if (callback == null)
                    continue;

                bool found = false;

                foreach (ITrace trace in traces) /* O(M) */
                {
                    if (trace == null)
                        continue;

                    if (AppDomainOps.IsTransparentProxy(trace))
                        continue;

                    if (trace.Callback == callback)
                    {
                        found = true;
                        break;
                    }
                }

                if (!found)
                    return false;
            }

            return true;
        }
        #endregion

