        /// This method determines whether the specified variable is the global
        /// "auto_path" variable that has the auto-path trace callback attached.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <returns>
        /// True if the variable is the auto-path variable; otherwise, false.
        /// </returns>
        private bool IsAutoPathVariable(IVariable variable)
        {
            return (variable != null) &&
                IsGlobalCallFrame(variable.Frame) &&
