        /// <summary>
        /// This method determines whether the specified variable has the
        /// precision trace callback attached to it.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <returns>
        /// True if the variable has the precision trace callback; otherwise,
        /// false.
        /// </returns>
        private static bool HasPrecisionTraceCallback(
            IVariable variable
            )
        {
            return (variable != null) &&
                (variable.Traces != null) &&
                variable.Traces.Contains(PrecisionTraceCallback);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified variable is the global
        /// precision-related variable that has the precision trace callback
        /// attached.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <returns>
        /// True if the variable is the precision variable; otherwise, false.
        /// </returns>
        private bool IsPrecisionVariable(IVariable variable)
        {
            return (variable != null) &&
                IsGlobalCallFrame(variable.Frame) &&
                SharedStringOps.SystemEquals(
                    variable.Name, TclVars.Core.PrecisionName) &&
                !HasPendingTraces() &&
                HasPrecisionTraceCallback(variable);
        }

