        /// <summary>
        /// Gets or sets the precision used when formatting floating-point
        /// values, kept in sync with the script-level precision variable.
        /// </summary>
        private int PrivatePrecision
        {
            get { return Interlocked.CompareExchange(ref precision, 0, 0); }
            set { Interlocked.Exchange(ref precision, value); }
        }

