        /// True if the variable is a database variable; otherwise, false.
        /// </returns>
        private bool IsDatabaseVariable(
            IVariable variable
            )
        {
            DatabaseVariable databaseVariable = null;

            return IsDatabaseVariable(variable, ref databaseVariable);
        }

