        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <param name="networkVariable">
        /// Upon success, receives the network variable associated with the
        /// trace callback.
        /// </param>
        /// <returns>
        /// True if the variable is a network variable; otherwise, false.
        /// </returns>
        internal bool IsNetworkVariable(
            IVariable variable,
            ref NetworkVariable networkVariable
            )
        {
            return (variable != null) && !HasPendingTraces() &&
                HasNetworkTraceCallback(variable, ref networkVariable);
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Registry Variable Support
#if !NET_STANDARD_20 && WINDOWS
        /// <summary>
        /// This method determines whether the specified variable has a registry
        /// variable trace callback attached to it, returning the associated
        /// registry variable.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <param name="registryVariable">
        /// Upon success, receives the registry variable associated with the
        /// trace callback.
        /// </param>
        /// <returns>
        /// True if the variable has a registry variable trace callback;
        /// otherwise, false.
        /// </returns>
        private static bool HasRegistryTraceCallback(
            IVariable variable,
            ref RegistryVariable registryVariable
            )
        {
            if (variable == null)
                return false;

            TraceList traces = variable.Traces;

            if (traces == null)
                return false;

            foreach (ITrace trace in traces)
            {
                if (trace == null)
                    continue;

                if (AppDomainOps.IsTransparentProxy(trace))
                    continue;

                TraceCallback callback = trace.Callback;

                if (callback == null)
                    continue;

                MethodInfo methodInfo = callback.Method;

                if (methodInfo == null)
                    continue;

                if (methodInfo.DeclaringType == typeof(RegistryVariable))
                {
                    registryVariable = callback.Target as RegistryVariable;
                    return (registryVariable != null);
                }
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified variable is backed by a
        /// registry variable trace callback.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <returns>
        /// True if the variable is a registry variable; otherwise, false.
        /// </returns>
        private bool IsRegistryVariable(
            IVariable variable
            )
        {
            RegistryVariable registryVariable = null;

            return IsRegistryVariable(variable, ref registryVariable);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified variable is backed by a
        /// registry variable trace callback, returning the associated registry
        /// variable.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <param name="registryVariable">
        /// Upon success, receives the registry variable associated with the
        /// trace callback.
        /// </param>
        /// <returns>
        /// True if the variable is a registry variable; otherwise, false.
        /// </returns>
        internal bool IsRegistryVariable(
            IVariable variable,
            ref RegistryVariable registryVariable
            )
        {
            return (variable != null) && !HasPendingTraces() &&
                HasRegistryTraceCallback(variable, ref registryVariable);
        }
#endif
        #endregion

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Thread Variable Support
        /// <summary>
        /// This method determines whether the specified variable has a thread
        /// variable trace callback attached to it, returning the associated
        /// thread variable.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <param name="threadVariable">
        /// Upon success, receives the thread variable associated with the trace
        /// callback.
        /// </param>
        /// <returns>
        /// True if the variable has a thread variable trace callback;
        /// otherwise, false.
        /// </returns>
        private static bool HasThreadTraceCallback(
            IVariable variable,
            ref ThreadVariable threadVariable
            )
        {
            if (variable == null)
                return false;

            TraceList traces = variable.Traces;

            if (traces == null)
                return false;

            foreach (ITrace trace in traces)
            {
                if (trace == null)
                    continue;

                if (AppDomainOps.IsTransparentProxy(trace))
                    continue;

                TraceCallback callback = trace.Callback;

                if (callback == null)
                    continue;

                MethodInfo methodInfo = callback.Method;

                if (methodInfo == null)
                    continue;

                if (methodInfo.DeclaringType == typeof(ThreadVariable))
                {
                    threadVariable = callback.Target as ThreadVariable;
                    return (threadVariable != null);
                }
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified variable is backed by a
        /// thread variable trace callback.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <returns>
        /// True if the variable is a thread variable; otherwise, false.
        /// </returns>
        private bool IsThreadVariable(
            IVariable variable
            )
        {
