        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether the specified variable is backed by a
        /// thread variable trace callback, returning the associated thread
        /// variable.
        /// </summary>
        /// <param name="variable">
        /// The variable to check.
        /// </param>
        /// <param name="threadVariable">
        /// Upon success, receives the thread variable associated with the trace
        /// callback.
        /// </param>
        /// <returns>
        /// True if the variable is a thread variable; otherwise, false.
        /// </returns>
        internal bool IsThreadVariable(
            IVariable variable,
            ref ThreadVariable threadVariable
            )
        {
            return (variable != null) && !HasPendingTraces() &&
                HasThreadTraceCallback(variable, ref threadVariable);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the per-thread state associated with the
        /// specified thread variable for all threads.
        /// </summary>
        /// <param name="flags">
        /// The variable flags to use when resolving the named variable.
        /// </param>
        /// <param name="name">
        /// The name of the thread variable to reset.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error code.
        /// </returns>
        private ReturnCode ResetThreadVariable(
            VariableFlags flags,
            string name,
            ref Result error
            )
        {
            lock (syncRoot) /* TRANSACTIONAL */
            {
                IVariable variable = null;

                if (GetVariableViaResolversWithSplit(
                        name, ref flags, ref variable,
                        ref error) == ReturnCode.Ok)
                {
                    ThreadVariable threadVariable = null;

                    if (IsThreadVariable(
                            variable, ref threadVariable))
                    {
                        /* IGNORED */
                        threadVariable.CleanupForAll();

                        return ReturnCode.Ok;
                    }
                    else
                    {
                        error = "variable is not per-thread";
                    }
                }

                return ReturnCode.Error;
            }
        }
        #endregion

