        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region "Active" Interpreter Support
        /// <summary>
        /// This method returns the active interpreter for the calling thread,
        /// falling back to any available interpreter in the current process if
        /// there is no active interpreter.
        /// </summary>
        /// <returns>
        /// An interpreter, or null if none could be found.
        /// </returns>
        public static Interpreter GetAny() /* THREAD-SAFE */
        {
            Interpreter interpreter = GetActive();

            if (interpreter == null)
            {
                ReturnCode code;
                Result error = null;

                code = GlobalState.GetInterpreter(
                    LookupFlags.Interpreter, null,
                    ref interpreter, ref error);

                if (code != ReturnCode.Ok)
                {
                    TraceOps.DebugTrace(String.Format(
                        "GetAny: code = {0}, error = {1}",
                        code, FormatOps.WrapOrNull(error)),
                        typeof(Interpreter).Name,
                        TracePriority.InterpreterError);
                }
            }

            return interpreter;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the interpreter that is currently active on the
        /// calling thread, if any.
        /// </summary>
        /// <returns>
        /// The active interpreter, or null if there is none.
        /// </returns>
        public static Interpreter GetActive() /* THREAD-SAFE */
        {
            ActiveInterpreterPair anyPair = GetActivePair();
            return (anyPair != null) ? anyPair.X : null;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the active interpreter pair for the calling
        /// thread, excluding token interpreters.
        /// </summary>
        /// <returns>
        /// The active interpreter pair, or null if there is no eligible active
        /// interpreter.
        /// </returns>
        public static ActiveInterpreterPair GetActivePair()
        {
            ActiveInterpreterPair anyPair = GetActivePair(null);

            if (anyPair == null)
                return null;

            //
            // BUGFIX: The public GetActive*() methods cannot be
            //         allowed to return a "token" interpreter.
            //
            Interpreter interpreter = anyPair.X;

            if ((interpreter == null) || interpreter.HasToken())
                return null;

            return anyPair;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Private
        /// <summary>
        /// This method returns the subset of the specified interpreters that
        /// are associated with the calling thread.
        /// </summary>
        /// <param name="interpreters">
        /// The interpreters to filter.
        /// </param>
        /// <returns>
        /// The interpreters associated with the calling thread, or null if
        /// there are none.
        /// </returns>
        private static IEnumerable<Interpreter> GetAllInteractive(
            IEnumerable<Interpreter> interpreters
            )
        {
            if (interpreters == null)
                return null;

            IList<Interpreter> result = null;

            foreach (Interpreter interpreter in interpreters)
            {
                if (interpreter == null)
                    continue;

                if (!ThreadOps.IsCurrent(
                        interpreter.PrivateThread))
                {
#if SHELL
                    if (!ThreadOps.IsCurrent(
                            interpreter.PrivateInteractiveThread))
#endif
                    {
                        continue;
                    }
                }

                if (result == null)
                    result = new List<Interpreter>();

                result.Add(interpreter);
            }

            return result;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method returns the active interpreter pair for the calling
        /// thread, optionally restricted to interpreters of the specified type.
        /// </summary>
        /// <param name="type">
        /// The type of interpreter to match, or null to match any type.
        /// </param>
        /// <returns>
        /// The active interpreter pair, or null if there is none.
        /// </returns>
        internal static ActiveInterpreterPair GetActivePair(
            Type type
            )
        {
            return GlobalState.GetActiveInterpreter(type);
        }

