        /// <summary>
        /// This method returns the number of times this interpreter is
        /// currently active.
        /// </summary>
        /// <param name="global">
        /// Non-zero to return this interpreter's own active count; zero to
        /// count the number of times this interpreter is active in the global
        /// interpreter state.
        /// </param>
        /// <returns>
        /// The active count.
        /// </returns>
        private int GetActiveCount(
            bool global
            )
        {
            if (global)
            {
                return Interlocked.CompareExchange(ref activeCount, 0, 0);
            }
            else
            {
                return GlobalState.CountActiveInterpreters(this);
            }
        }

