        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method starts a new server socket thread that listens for
        /// incoming connections using the specified parameters.
        /// </summary>
        /// <param name="options">
        /// The options used to configure the server socket.
        /// </param>
        /// <param name="timeout">
        /// The timeout, in milliseconds, to wait for the server socket thread
        /// to start, or null to use the default.
        /// </param>
        /// <param name="address">
        /// The local address on which to listen, or null to listen on any
        /// address.
        /// </param>
        /// <param name="port">
        /// The local port on which to listen.
        /// </param>
        /// <param name="addressFamily">
        /// The address family to use, or null to use the default.
        /// </param>
        /// <param name="streamFlags">
        /// The flags used to configure the underlying stream.
        /// </param>
        /// <param name="availableTimeout">
        /// The timeout, in milliseconds, used when checking for available data,
        /// or null to use the default.
        /// </param>
        /// <param name="readTimeout">
        /// The read timeout, in milliseconds, or null to use the default.
        /// </param>
        /// <param name="writeTimeout">
        /// The write timeout, in milliseconds, or null to use the default.
        /// </param>
        /// <param name="keepAlive">
        /// Non-zero to enable keep-alive on accepted connections, or null to
        /// use the default.
        /// </param>
        /// <param name="exclusive">
        /// Non-zero to bind the socket exclusively.
        /// </param>
        /// <param name="text">
        /// The script command to evaluate for each accepted connection.
        /// </param>
        /// <param name="result">
        /// Upon success, receives the name of the listener channel; upon
        /// failure, receives an error message.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> on success; otherwise, an error code.
        /// </returns>
        internal ReturnCode StartServerSocket(
            OptionDictionary options,
            int? timeout,
            string address,
            string port,
            AddressFamily? addressFamily,
            StreamFlags streamFlags,
            int? availableTimeout,
            int? readTimeout,
            int? writeTimeout,
            bool? keepAlive,
            bool exclusive,
            string text, /* command */
            ref Result result
            )
        {
            bool success = false;
            EventWaitHandle localEvent = null;
            Thread localThread = null;

            try
            {
                //
                // TODO: Maybe make this into a named event and then
                //       have the server socket thread open its own
                //       instance of it?
                //
                localEvent = ThreadOps.CreateEvent(false);

                SocketClientData clientData = new SocketClientData(
                    null, localEvent, this, options, address, port,
                    addressFamily, streamFlags, availableTimeout,
                    readTimeout, writeTimeout, keepAlive, exclusive,
                    text);

                int localTimeout = ThreadOps.GetTimeout(
                    this, timeout, TimeoutType.Start);

                localThread = Engine.CreateThread(
                    this, SocketOps.ServerThreadStart, 0,
                    true, false, true);

                if (localThread != null)
                {
                    localThread.Name = FormatOps.Id(String.Format(
                        "serverSocketThread: {0}",
                            FormatOps.InterpreterNoThrow(
                                this)), port, 0); /* throw */

                    localThread.Start(clientData); /* throw */

                    //
                    // HACK: For now, avoid ever using new overload(s)
                    //       of this method; otherwise, Mono crashes.
                    //
                    if (ThreadOps.WaitEvent(localEvent, localTimeout))
                    {
                        //
                        // NOTE: Upon success from the newly created
                        //       server socket thread return the code
                        //       "Ok" and the name of its associated
                        //       TcpListener channel; otherwise, upon
                        //       failure, return the code "Error" and
                        //       the associated error message.
                        //
                        result = clientData.Result;

                        if (clientData.ReturnCode == ReturnCode.Ok)
                        {
                            //
                            // NOTE: If (and only if) this point is
                            //       reached, we know that the server
                            //       socket thread is fully setup and
                            //       working (i.e. no need to shut it
                            //       down via interrupting it).
                            //
                            success = true;

                            return ReturnCode.Ok;
                        }
                    }
                    else
                    {
                        result = "timed out starting server thread";
                    }
                }
                else
                {
                    result = "could not create server thread";
                }
            }
            catch (Exception e)
            {
                result = e;
            }
            finally
            {
                if (!success && (localThread != null))
                {
                    try
                    {
                        localThread.Interrupt(); /* throw */
                        localThread = null;
                    }
                    catch (Exception e)
                    {
                        TraceOps.DebugTrace(
                            e, typeof(Interpreter).Name,
                            TracePriority.ThreadError);
                    }
                }

                ThreadOps.CloseEvent(ref localEvent);
            }

            return ReturnCode.Error;
        }
#endif
        #endregion

