        internal string Complaint
        {
            get
            {
                // CheckDisposed(); /* EXEMPT */

#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    return context.Complaint;
                else
                    return null;
#else
                lock (syncRoot)
                {
                    return complaint;
                }
