            }
            set
            {
                // CheckDisposed(); /* EXEMPT */

#if THREADING
                IEngineContext context = GetEngineContext();

                if (context != null)
                    context.Complaint = value;
#else
                lock (syncRoot)
                {
                    complaint = value;
                }
#endif
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method determines whether this interpreter is permitted to
        /// exit, consulting the interpreter host when one is available.
        /// </summary>
        /// <param name="exitCode">
        /// The exit code that would be used if the exit were permitted.
        /// </param>
        /// <param name="force">
        /// Non-zero if the exit is being forced.
        /// </param>
        /// <param name="fail">
        /// Non-zero if a failure to exit should be treated as significant.
        /// </param>
        /// <param name="message">
        /// The message associated with the exit request.
        /// </param>
        /// <param name="error">
        /// Upon failure, receives an error message explaining why the exit is
        /// not permitted.
        /// </param>
        /// <returns>
        /// <see cref="ReturnCode.Ok" /> if the exit is permitted; otherwise, an
        /// error code.
        /// </returns>
        internal ReturnCode CanExit(
            ExitCode exitCode,
            bool force,
            bool fail,
            string message,
            ref Result error
            )
        {
            ReturnCode code = ReturnCode.Ok;
            IProcessHost processHost = InternalHost;

            if (processHost != null)
            {
                try
                {
                    if (FlagOps.HasFlags(
                            processHost.GetHostFlags(), HostFlags.Exit, true))
                    {
                        if (processHost.Exiting)
                        {
                            error = "interpreter host is already exiting";
                            code = ReturnCode.Error;
                        }
                        else if (!processHost.CanExit)
                        {
                            error = "exit denied by interpreter host";
                            code = ReturnCode.Error;
                        }
                        else if (force && !processHost.CanForceExit)
                        {
                            error = "force exit denied by interpreter host";
                            code = ReturnCode.Error;
                        }
                    }
                }
                catch (Exception e)
                {
                    //
                    // TODO: Should this simply allow the exit to take place?
                    //
                    error = e;
                    code = ReturnCode.Error;
                }
            }

            TraceOps.DebugTrace(String.Format(
                "CanExit: returning, exitCode = {0}, force = {1}, " +
                "fail = {2}, message = {3}, code = {4}, error = {5}",
                exitCode, force, fail, FormatOps.WrapOrNull(true, true,
                message), code, FormatOps.WrapOrNull(true, true, error)),
                typeof(Interpreter).Name, TracePriority.HostDebug);

            return code;
        }

