        /// <summary>
        /// This method deletes any temporary file system paths associated with
        /// this interpreter and optionally resets the associated tracking state.
        /// </summary>
        /// <param name="force">
        /// Non-zero to reset the tracking state even if path cleanup fails.
        /// </param>
        /// <param name="reset">
        /// Non-zero to reset the tracking state after cleanup.
        /// </param>
        private void CleanupAndMaybeResetPaths(
            bool force,
            bool reset
            )
        {
            StringList list = null;
            ResultList errors = null;

            /* IGNORED */
            CleanupAndMaybeResetPaths(
                force, reset, ref list, ref errors);
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method deletes any temporary file system paths associated with
        /// this interpreter, optionally resetting the tracking state, and
        /// collects the affected paths and any errors.
        /// </summary>
        /// <param name="force">
        /// Non-zero to reset the tracking state even if path cleanup fails.
        /// </param>
        /// <param name="reset">
        /// Non-zero to reset the tracking state after cleanup.
        /// </param>
        /// <param name="list">
        /// Upon return, receives the list of paths that were processed; this list
        /// may be created if necessary.
        /// </param>
        /// <param name="errors">
        /// Upon return, receives any errors that were encountered; this list may
        /// be created if necessary.
        /// </param>
        /// <returns>
        /// <c>ReturnCode.Ok</c> on success; otherwise, an appropriate error code.
        /// </returns>
        internal ReturnCode CleanupAndMaybeResetPaths(
            bool force,
            bool reset,
            ref StringList list,
            ref ResultList errors
            )
        {
            ReturnCode code = FileOps.CleanupPaths(
                this, cleanupPaths, false, false, ref list,
                ref errors);

            if ((force || (code == ReturnCode.Ok)) && reset)
                cleanupPaths = null;

            return code;
        }

