        #region Child Interpreter Disposal
#if DATA
        /// <summary>
        /// This method disposes of the script bundle manager associated with this
        /// interpreter, if any, and then sets it to null.
        /// </summary>
        private void DisposeBundleManager()
        {
            if (bundleManager == null)
                return;

            ReturnCode code;
            Result result = null;

            try
            {
                code = ObjectOps.TryDispose<IBundleManager>(
                    ref bundleManager, ref result);

                bundleManager = null;
            }
            catch (Exception e)
            {
                result = String.Format(
                    "caught exception while disposing bundle manager: {0}", e);

                code = ReturnCode.Error;
