        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method clears the "late" plain-data objects for this interpreter
        /// (snippets, runtime options, plugin arguments, package indexes, and
        /// package aliases) and optionally resets them.
        /// </summary>
        /// <param name="reset">
        /// Non-zero to reset (null out) the collections after clearing them.
        /// </param>
        private void ClearAndMaybeResetLatePodObjects(
            bool reset
            )
        {
            if (snippets != null)
            {
                snippets.Clear();

                if (reset)
                    snippets = null;
            }

            if (runtimeOptions != null)
            {
                runtimeOptions.Clear();

                if (reset)
                    runtimeOptions = null;
            }

            if (pluginArguments != null)
            {
                pluginArguments.Clear();

                if (reset)
                    pluginArguments = null;
            }

            if (packageIndexes != null)
            {
                packageIndexes.Clear();

                if (reset)
                    packageIndexes = null;
            }

            if (packageAliases != null)
            {
                packageAliases.Clear();

                if (reset)
                    packageAliases = null;
            }
        }

