        ///////////////////////////////////////////////////////////////////////////////////////////////

        #region Disposal Helper Methods (Callbacks)
        /// <summary>
        /// This method removes the registered dispose callback for the specified
        /// alias from its target interpreter.
        /// </summary>
        /// <param name="alias">
        /// The alias whose dispose callback should be removed from its target
        /// interpreter.
        /// </param>
        private static void RemoveTargetDisposeCallback(
            IAlias alias
            )
        {
            try
            {
                if (alias != null)
                {
                    Interpreter targetInterpreter = alias.TargetInterpreter;

                    if (targetInterpreter != null)
                        targetInterpreter.RemoveDisposeCallback(alias);
                }
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.CallbackError);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method removes the post-disposal callback supplied by the
        /// specified alias from this interpreter.
        /// </summary>
        /// <param name="alias">
        /// The alias whose post-disposal callback should be removed.
        /// </param>
        private void RemoveDisposeCallback(
            IAlias alias
            )
        {
            try
            {
                lock (syncRoot) /* TRANSACTIONAL */
                {
                    if (postDisposeCallbacks != null)
                    {
                        DisposeCallback callback = alias.PostInterpreterDisposed;

                        if (callback != null)
                            postDisposeCallbacks -= callback;
                    }
                }
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.CallbackError);
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the registered pre-disposal callbacks for this
        /// interpreter.
        /// </summary>
        private void ResetPreDisposeCallbacks()
        {
            lock (syncRoot)
            {
                preDisposeCallbacks = null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method invokes the registered pre-disposal callbacks for this
        /// interpreter, if any.
        /// </summary>
        /// <returns>
        /// True if there were callbacks to invoke; otherwise, false.
        /// </returns>
        private bool FirePreDisposeCallbacks()
        {
            try
            {
                DisposeCallback localPreDisposeCallbacks;

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    localPreDisposeCallbacks = preDisposeCallbacks;
                }

                //
                // BUGFIX: Do not hold the interpreter lock while invoking
                //         the callbacks as that could lead to deadlocks.
                //
                if (localPreDisposeCallbacks != null)
                {
                    localPreDisposeCallbacks(this);
                    return true;
                }
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.CallbackError);
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method resets the registered post-disposal callbacks for this
        /// interpreter.
        /// </summary>
        private void ResetPostDisposeCallbacks()
        {
            lock (syncRoot)
            {
                postDisposeCallbacks = null;
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        /// <summary>
        /// This method invokes the registered post-disposal callbacks for this
        /// interpreter, if any.
        /// </summary>
        /// <returns>
        /// True if there were callbacks to invoke; otherwise, false.
        /// </returns>
        private bool FirePostDisposeCallbacks()
        {
            try
            {
                DisposeCallback localPostDisposeCallbacks;

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    localPostDisposeCallbacks = postDisposeCallbacks;
                }

                //
                // BUGFIX: Do not hold the interpreter lock while invoking
                //         the callbacks as that could lead to deadlocks.
                //
                if (localPostDisposeCallbacks != null)
                {
                    localPostDisposeCallbacks(this);
                    return true;
                }
            }
            catch (Exception e)
            {
                TraceOps.DebugTrace(
                    e, typeof(Interpreter).Name,
                    TracePriority.CallbackError);
            }

            return false;
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For now, this event is internal only; however, it may
        //       eventually be exposed.
        //
        /// <summary>
        /// This event is raised just before this interpreter is disposed.  It is
        /// currently for internal use only.
        /// </summary>
        internal event DisposeCallback PreInterpreterDisposed
        {
            add
            {
                // CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    preDisposeCallbacks -= value;
                    preDisposeCallbacks += value;
                }
            }
            remove
            {
                // CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    preDisposeCallbacks -= value;
                }
            }
        }

        ///////////////////////////////////////////////////////////////////////////////////////////////

        //
        // NOTE: For now, this event is internal only; however, it may
        //       eventually be exposed.
        //
        /// <summary>
        /// This event is raised just after this interpreter is disposed.  It is
        /// currently for internal use only.
        /// </summary>
        internal event DisposeCallback PostInterpreterDisposed
        {
            add
            {
                // CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    postDisposeCallbacks -= value;
                    postDisposeCallbacks += value;
                }
            }
            remove
            {
                // CheckDisposed();

                lock (syncRoot) /* TRANSACTIONAL */
                {
                    postDisposeCallbacks -= value;
                }
            }
        }
